try:
    from dotenv import load_dotenv
    _dotenv_candidates: List[Path] = []
    try:
        ud = str(os.environ.get("ML_USER_DATA_DIR") or os.environ.get("FT_USER_DATA_DIR") or "").strip()
    except Exception:
        ud = ""
    user_dotenv: Optional[Path] = None
    if ud:
        try:
            user_dotenv = Path(ud).expanduser() / ".env"
            _dotenv_candidates.append(user_dotenv)
        except Exception:
            user_dotenv = None
    try:
        allow_project_dotenv = str(os.environ.get("ML_ALLOW_PROJECT_DOTENV", "") or "").strip().lower() in ("1", "true", "yes", "y", "on")
    except Exception:
        allow_project_dotenv = False
    try:
        strict_user_dotenv = str(os.environ.get("ML_STRICT_USER_DOTENV", "") or "").strip().lower() in ("1", "true", "yes", "y", "on")
    except Exception:
        strict_user_dotenv = False

    should_fallback_to_project = bool(allow_project_dotenv)
    if (not should_fallback_to_project) and (not strict_user_dotenv):
        try:
            should_fallback_to_project = bool(user_dotenv is None or (not user_dotenv.exists()))
        except Exception:
            should_fallback_to_project = True

    if should_fallback_to_project:
        try:
            _dotenv_candidates.append(Path(__file__).resolve().parent / ".env")
        except Exception:
            pass
        try:
            _dotenv_candidates.append(Path(os.getcwd()) / ".env")
        except Exception:
            pass
    for p in _dotenv_candidates:
        try:
            if p.exists():
                load_dotenv(dotenv_path=str(p), override=False)
                break
        except Exception:
            continue
except Exception:
    pass

