_CHARACTERIZATION_EXCLUSIVE_LOCK = threading.Lock()
_CHARACTERIZATION_EXCLUSIVE_STATE: Dict[str, Any] = {"running": 0, "since_ms": 0, "last_end_ms": 0}

def _characterization_exclusive_is_running() -> bool:
    try:
        return int(_CHARACTERIZATION_EXCLUSIVE_STATE.get("running") or 0) > 0
    except Exception:
        return False

def _characterization_exclusive_inc() -> None:
    with _CHARACTERIZATION_EXCLUSIVE_LOCK:
        _CHARACTERIZATION_EXCLUSIVE_STATE["running"] = int(_CHARACTERIZATION_EXCLUSIVE_STATE.get("running") or 0) + 1
        if int(_CHARACTERIZATION_EXCLUSIVE_STATE.get("since_ms") or 0) <= 0:
            _CHARACTERIZATION_EXCLUSIVE_STATE["since_ms"] = int(time.time() * 1000)

def _characterization_exclusive_dec() -> None:
    with _CHARACTERIZATION_EXCLUSIVE_LOCK:
        _CHARACTERIZATION_EXCLUSIVE_STATE["running"] = max(0, int(_CHARACTERIZATION_EXCLUSIVE_STATE.get("running") or 0) - 1)
        if int(_CHARACTERIZATION_EXCLUSIVE_STATE.get("running") or 0) <= 0:
            _CHARACTERIZATION_EXCLUSIVE_STATE["last_end_ms"] = int(time.time() * 1000)
            _CHARACTERIZATION_EXCLUSIVE_STATE["since_ms"] = 0


@app.after_request
def _cors_after_request(resp: Response) -> Response:
    try:
        origin = str(request.headers.get("Origin") or "").strip()
    except Exception:
        origin = ""
    allowlist = None
    try:
        raw = str(os.environ.get("CORS_ALLOW_ORIGINS", "") or "").strip()
        if raw:
            allowlist = {x.strip() for x in raw.split(",") if x.strip()}
    except Exception:
        allowlist = None
    allow_any = allowlist is None

    if origin and (allow_any or (origin in (allowlist or set()))):
        resp.headers["Access-Control-Allow-Origin"] = origin
        resp.headers["Vary"] = "Origin"
        resp.headers["Access-Control-Allow-Credentials"] = "true"
    else:
        resp.headers["Access-Control-Allow-Origin"] = "*"

    resp.headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization, X-CSRF-Token, X-Webhook-Token, X-Execute-Token, X-Config-Token, X-Maintenance-Token, X-Config-Signature, X-HMAC-Signature"
    resp.headers["Access-Control-Allow-Methods"] = "GET, POST, PUT, PATCH, DELETE, OPTIONS"
    return resp


@app.before_request
def _cors_preflight() -> Optional[Response]:
    try:
        m = str(request.method or "").strip().upper()
    except Exception:
        m = ""
    if m == "OPTIONS":
        return jsonify({"ok": True}), 200
    return None


@app.before_request
def _characterization_exclusive_guard() -> Optional[Response]:
    try:
        if not _characterization_exclusive_is_running():
            return None
    except Exception:
        return None
    try:
        m = str(request.method or "").strip().upper()
    except Exception:
        m = ""
    if m == "OPTIONS":
        return None
    try:
        p = str(request.path or "")
    except Exception:
        p = ""
    if p.startswith("/governance/characterization/"):
        return None
    if p in ("/health", "/ping"):
        return None
    try:
        st = dict(_CHARACTERIZATION_EXCLUSIVE_STATE)
    except Exception:
        st = {"running": 1}
    return jsonify({"ok": False, "error": "characterization_running", "state": st}), 503

