def _default_book_run_id() -> str:
    try:
        v = str(os.environ.get("BOOK_RUN_ID") or "").strip()
        if v:
            return v
    except Exception:
        pass
    try:
        return f"run_{datetime.now(timezone.utc).strftime('%Y%m%d')}"
    except Exception:
        return uuid.uuid4().hex


