def _universe_default_core_pool(min_n: int = 10) -> List[str]:
    try:
        n = int(min_n)
    except Exception:
        n = 10
    n = int(max(3, min(200, int(n))))
    base = [
        "BTC",
        "ETH",
        "SOL",
        "XRP",
        "BNB",
        "DOGE",
        "ADA",
        "AVAX",
        "LINK",
        "SUI",
        "TON",
        "NEAR",
        "APT",
        "ARB",
        "OP",
        "MATIC",
        "LTC",
        "BCH",
        "TRX",
        "DOT",
        "ATOM",
        "ETC",
        "FIL",
        "INJ",
        "UNI",
        "AAVE",
        "PEPE",
        "SHIB",
    ]
    seed: List[str] = []
    try:
        for k in ("core", "shadow", "watchlist"):
            xs = UNIVERSE_STATE.get(k) if isinstance(UNIVERSE_STATE, dict) else None
            if not isinstance(xs, list):
                continue
            for x in xs:
                s = str(x or "").strip().upper()
                if s:
                    seed.append(s)
    except Exception:
        pass
    local_seed: List[str] = []
    try:
        shim_local = _hl_info_shim_from_local_data(int(_now_ms()), max_coins=400)
        if shim_local is not None:
            uni0 = shim_local.meta().get("universe", [])
            if isinstance(uni0, list):
                for it in uni0:
                    if not isinstance(it, dict):
                        continue
                    s = str(it.get("name") or "").strip().upper()
                    if s:
                        local_seed.append(s)
    except Exception:
        pass
    out: List[str] = []
    seen = set()
    for x in seed + local_seed + base:
        s = str(x or "").strip().upper()
        if not s or s in ("USDT", "USDC") or s in seen:
            continue
        seen.add(s)
        out.append(s)
        if len(out) >= int(n):
            break
    if not out:
        out = ["BTC", "ETH", "SOL"]
    return out


def _run_universe_build_with_timeout(now_ms: int, timeout_sec: Optional[float] = None) -> Dict[str, Any]:
    if timeout_sec is None:
        try:
            timeout_sec = float(CONFIG.get("universe_build_timeout_sec", 45) or 45)
        except Exception:
            timeout_sec = 45.0
    try:
        to_sec = float(timeout_sec)
    except Exception:
        to_sec = 45.0
    to_sec = float(_clip(float(to_sec), 5.0, 300.0))
    box: Dict[str, Any] = {"error": None}

    def _task() -> None:
        try:
            _build_universe_pipeline(int(now_ms))
        except Exception as e:
            box["error"] = str(e)

    t = threading.Thread(target=_task, daemon=True)
    t.start()
    t.join(timeout=float(to_sec))
    if t.is_alive():
        try:
            min_ready = int(CONFIG.get("universe_min_ready_core_size", 10) or 10)
        except Exception:
            min_ready = 10
        min_ready = int(max(3, min(200, int(min_ready))))
        try:
            n_core = int(CONFIG.get("universe_core_size", 30) or 30)
        except Exception:
            n_core = 30
        n_core = int(max(int(min_ready), min(300, int(n_core))))
        try:
            n_shadow = int(CONFIG.get("universe_shadow_size", 30) or 30)
        except Exception:
            n_shadow = 30
        n_shadow = int(max(0, min(500, int(n_shadow))))
        try:
            n_watch_min = int(CONFIG.get("universe_watchlist_min_size", 8) or 8)
        except Exception:
            n_watch_min = 8
        n_watch_min = int(max(0, min(500, int(n_watch_min))))
        cand_list: List[str] = []
        stage_a_issues: Dict[str, Any] = {}
        stage_a_filters: Dict[str, Any] = {}
        try:
            shim_local = _hl_info_shim_from_local_data(int(now_ms), max_coins=int(CONFIG.get("universe_timeout_local_max_coins", 200) or 200))
        except Exception:
            shim_local = None
        if shim_local is not None:
            uni_local = []
            try:
                uni_local = shim_local.meta().get("universe", [])
            except Exception:
                uni_local = []
            if isinstance(uni_local, list):
                for it in uni_local:
                    if not isinstance(it, dict):
                        continue
                    s = str(it.get("name") or "").strip().upper()
                    if s and s not in ("USDT", "USDC") and s not in cand_list:
                        cand_list.append(s)
            try:
                res_local = _build_universe_stage_a(shim_local)
            except Exception:
                res_local = {}
            try:
                xs = res_local.get("candidates") if isinstance(res_local, dict) else None
                if isinstance(xs, list):
                    for x in xs:
                        s = str(x or "").strip().upper()
                        if s and s not in ("USDT", "USDC") and s not in cand_list:
                            cand_list.append(s)
            except Exception:
                pass
            try:
                v = res_local.get("issues") if isinstance(res_local, dict) else None
                stage_a_issues = (dict(v) if isinstance(v, dict) else {})
            except Exception:
                stage_a_issues = {}
            try:
                v = res_local.get("filters") if isinstance(res_local, dict) else None
                stage_a_filters = (dict(v) if isinstance(v, dict) else {})
            except Exception:
                stage_a_filters = {}
        need_total = int(max(int(min_ready), int(n_core) + int(n_shadow) + int(n_watch_min)))
        if len(cand_list) < int(need_total):
            fill = _universe_default_core_pool(min_n=int(need_total))
            for c in fill:
                if c not in cand_list:
                    cand_list.append(c)
                if len(cand_list) >= int(need_total):
                    break
        total_n = int(len(cand_list))
        reserve_shadow = int(min(int(n_shadow), max(5, int(total_n * 0.35)))) if total_n > 0 else 0
        core_target = int(min(int(n_core), max(int(min_ready), int(total_n - reserve_shadow)))) if total_n > 0 else int(min_ready)
        core_target = int(max(int(min_ready), min(int(core_target), int(total_n)))) if total_n > 0 else int(min_ready)
        core = cand_list[: int(core_target)]
        rem = cand_list[int(core_target) :]
        rem_n = int(len(rem))
        try:
            timeout_shadow_min = int(CONFIG.get("universe_timeout_min_shadow", 4) or 4)
        except Exception:
            timeout_shadow_min = 4
        try:
            timeout_watch_min = int(CONFIG.get("universe_timeout_min_watchlist", 4) or 4)
        except Exception:
            timeout_watch_min = 4
        timeout_shadow_min = int(max(0, min(100, int(timeout_shadow_min))))
        timeout_watch_min = int(max(0, min(100, int(timeout_watch_min))))
        shadow_target = int(min(int(n_shadow), max(int(timeout_shadow_min), int(rem_n - timeout_watch_min))))
        shadow_target = int(max(0, min(int(shadow_target), int(max(0, rem_n - 1 if rem_n >= 2 else rem_n)))))
        shadow = rem[: int(shadow_target)]
        watch = rem[int(shadow_target) :]
        if len(core) < int(min_ready):
            fill = _universe_default_core_pool(min_n=int(min_ready))
            for c in fill:
                if c not in core:
                    core.append(c)
                if len(core) >= int(min_ready):
                    break
        pools = {"liq": {"HIGH": core[:], "MED": shadow[:], "LOW": watch[:]}, "beta": {"HIGH": [], "MID": [], "LOW": []}, "quality": {"GOOD": core[:] + shadow[:], "OK": watch[:], "BAD": []}, "cluster": {}}
        selection_hints = {"btc_alt_candidates": [c for c in (core + shadow + watch) if c not in ("BTC", "USDT", "USDC")][:30], "topk_per_cluster": 1, "excluded_clusters": [], "excluded_coins": [], "constraints": {"timeout_fallback": True}}
        candidates_schema: List[Dict[str, Any]] = []
        for i, c in enumerate((core + shadow + watch), start=1):
            candidates_schema.append({"coin": str(c), "rank": int(i), "score": 0.0, "source": "timeout_fallback", "issues": (stage_a_issues.get(str(c), []) if isinstance(stage_a_issues, dict) else []), "liq": {"turnover_7d_median": 0.0, "age_days": 0.0, "gap_rate_7d": 0.0, "jump_rate_7d": 0.0}})
        UNIVERSE_STATE["core"] = core
        UNIVERSE_STATE["shadow"] = shadow
        UNIVERSE_STATE["watchlist"] = watch
        UNIVERSE_STATE["counts"] = {"core": int(len(core)), "shadow": int(len(shadow)), "watchlist": int(len(watch))}
        try:
            meta0 = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
            meta = dict(meta0) if isinstance(meta0, dict) else {}
            meta["last_error"] = {"ts": int(now_ms), "error": "universe_build_timeout"}
            meta["core_placeholder"] = True
            meta["core_placeholder_reason"] = "build_timeout_fallback"
            meta["core_placeholder_since_ms"] = int(now_ms)
            meta["building"] = False
            meta["stage_a_issues"] = stage_a_issues
            meta["stage_a_filters"] = stage_a_filters
            meta["candidates"] = candidates_schema
            meta["candidates_ts"] = int(now_ms)
            meta["pools"] = pools
            meta["clusters"] = {}
            meta["selection_hints"] = selection_hints
            UNIVERSE_STATE["metadata"] = meta
        except Exception:
            pass
        UNIVERSE_STATE["last_update"] = int(now_ms)
        return {"ok": False, "timeout": True, "error": "universe_build_timeout"}
    err = box.get("error")
    if err:
        return {"ok": False, "timeout": False, "error": str(err)}
    return {"ok": True, "timeout": False}


def _ensure_universe_core_ready(now_ms: int) -> None:
    core0 = UNIVERSE_STATE.get("core") if isinstance(UNIVERSE_STATE, dict) else None
    meta0 = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
    meta0 = meta0 if isinstance(meta0, dict) else {}
    try:
        min_ready = int(CONFIG.get("universe_min_ready_core_size", 10) or 10)
    except Exception:
        min_ready = 10
    min_ready = int(max(1, min(2000, int(min_ready))))
    core_placeholder = bool(meta0.get("core_placeholder", False))
    if isinstance(core0, list) and core0 and (len(core0) >= int(min_ready)) and (not bool(core_placeholder)):
        return
    acquired = False
    try:
        acquired = bool(UNIVERSE_BUILD_LOCK.acquire(blocking=False))
    except Exception:
        acquired = False
    if not acquired:
        core1 = UNIVERSE_STATE.get("core") if isinstance(UNIVERSE_STATE, dict) else None
        if not isinstance(core1, list) or not core1:
            boot = _universe_default_core_pool(min_n=20)
            UNIVERSE_STATE["core"] = boot[:10]
            UNIVERSE_STATE["shadow"] = boot[10:20]
            UNIVERSE_STATE["watchlist"] = boot[20:]
            try:
                meta1 = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
                meta2 = dict(meta1) if isinstance(meta1, dict) else {}
                meta2["core_placeholder"] = True
                meta2["core_placeholder_reason"] = "lock_busy"
                meta2["core_placeholder_since_ms"] = int(now_ms)
                UNIVERSE_STATE["metadata"] = meta2
            except Exception:
                pass
            if int(UNIVERSE_STATE.get("last_update") or 0) <= 0:
                UNIVERSE_STATE["last_update"] = int(now_ms)
        return

    try:
        core1 = UNIVERSE_STATE.get("core") if isinstance(UNIVERSE_STATE, dict) else None
        meta0 = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
        meta = dict(meta0) if isinstance(meta0, dict) else {}
        core_placeholder = bool(meta.get("core_placeholder", False))
        if isinstance(core1, list) and core1 and (len(core1) >= int(min_ready)) and (not bool(core_placeholder)):
            return

        last_attempt = 0
        try:
            last_attempt = int(meta.get("last_build_attempt_ms") or 0)
        except Exception:
            last_attempt = 0
        inflight = bool(UNIVERSE_BUILD_INFLIGHT.get("running", False)) if isinstance(UNIVERSE_BUILD_INFLIGHT, dict) else False
        inflight_ts = 0
        try:
            inflight_ts = int(UNIVERSE_BUILD_INFLIGHT.get("ts") or 0) if isinstance(UNIVERSE_BUILD_INFLIGHT, dict) else 0
        except Exception:
            inflight_ts = 0
        try:
            inflight_ttl_sec = int(CONFIG.get("universe_build_inflight_ttl_sec", 180) or 180)
        except Exception:
            inflight_ttl_sec = 180
        inflight_ttl_sec = int(max(30, min(1800, int(inflight_ttl_sec))))
        inflight_fresh = inflight and (inflight_ts > 0) and (int(now_ms) - int(inflight_ts) < int(inflight_ttl_sec) * 1000)
        if inflight and (not inflight_fresh):
            try:
                if isinstance(UNIVERSE_BUILD_INFLIGHT, dict):
                    UNIVERSE_BUILD_INFLIGHT["running"] = False
            except Exception:
                pass

        if (not inflight_fresh) and (last_attempt <= 0 or int(now_ms) - int(last_attempt) >= 60_000):
            meta["last_build_attempt_ms"] = int(now_ms)
            meta["building"] = True
            meta["building_since_ms"] = int(now_ms)
            try:
                UNIVERSE_STATE["metadata"] = meta
            except Exception:
                pass
            try:
                if isinstance(UNIVERSE_BUILD_INFLIGHT, dict):
                    UNIVERSE_BUILD_INFLIGHT["running"] = True
                    UNIVERSE_BUILD_INFLIGHT["ts"] = int(now_ms)
            except Exception:
                pass

            def _bg() -> None:
                try:
                    try:
                        boot_to = float(CONFIG.get("universe_bootstrap_timeout_sec", 15) or 15)
                    except Exception:
                        boot_to = 15.0
                    res = _run_universe_build_with_timeout(int(now_ms), timeout_sec=float(boot_to))
                    if not bool(res.get("ok", False)):
                        e = str(res.get("error") or "universe_build_failed")
                        meta1 = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
                        meta2 = dict(meta1) if isinstance(meta1, dict) else {}
                        meta2["last_error"] = {"ts": int(now_ms), "error": str(e)}
                        meta2["building"] = False
                        UNIVERSE_STATE["metadata"] = meta2
                except Exception as e:
                    try:
                        meta1 = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
                        meta2 = dict(meta1) if isinstance(meta1, dict) else {}
                        meta2["last_error"] = {"ts": int(now_ms), "error": str(e)}
                        meta2["building"] = False
                        UNIVERSE_STATE["metadata"] = meta2
                    except Exception:
                        pass
                finally:
                    try:
                        if isinstance(UNIVERSE_BUILD_INFLIGHT, dict):
                            UNIVERSE_BUILD_INFLIGHT["running"] = False
                    except Exception:
                        pass
                    try:
                        meta1 = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
                        meta2 = dict(meta1) if isinstance(meta1, dict) else {}
                        meta2["building"] = False
                        UNIVERSE_STATE["metadata"] = meta2
                    except Exception:
                        pass

            try:
                t = threading.Thread(target=_bg, daemon=True)
                t.start()
            except Exception:
                pass

        core2 = UNIVERSE_STATE.get("core") if isinstance(UNIVERSE_STATE, dict) else None
        if not isinstance(core2, list) or not core2:
            boot = _universe_default_core_pool(min_n=24)
            UNIVERSE_STATE["core"] = boot[:10]
            UNIVERSE_STATE["shadow"] = boot[10:18]
            UNIVERSE_STATE["watchlist"] = boot[18:24]
            try:
                meta1 = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
                meta2 = dict(meta1) if isinstance(meta1, dict) else {}
                meta2["core_placeholder"] = True
                meta2["core_placeholder_reason"] = "empty_core_fallback"
                meta2["core_placeholder_since_ms"] = int(now_ms)
                UNIVERSE_STATE["metadata"] = meta2
            except Exception:
                pass
            if int(UNIVERSE_STATE.get("last_update") or 0) <= 0:
                UNIVERSE_STATE["last_update"] = int(now_ms)
    finally:
        try:
            UNIVERSE_BUILD_LOCK.release()
        except Exception:
            pass


def _safe_universe_state_snapshot() -> Dict[str, Any]:
    for _ in range(3):
        try:
            return copy.deepcopy(UNIVERSE_STATE)
        except RuntimeError:
            time.sleep(0.002)
        except Exception:
            break
    try:
        return {
            "core": list(UNIVERSE_STATE.get("core") or []),
            "shadow": list(UNIVERSE_STATE.get("shadow") or []),
            "watchlist": list(UNIVERSE_STATE.get("watchlist") or []),
            "counts": dict(UNIVERSE_STATE.get("counts") or {}),
            "metadata": dict(UNIVERSE_STATE.get("metadata") or {}),
            "last_update": int(UNIVERSE_STATE.get("last_update") or 0),
        }
    except Exception:
        return {"core": [], "shadow": [], "watchlist": [], "counts": {}, "metadata": {}, "last_update": 0}


