def _entry_macro_scope_ok(pair: str, strategy_id: Optional[str]) -> bool:
    try:
        if not bool(CONFIG.get("entry_macro_gate_enabled", False)):
            return False
    except Exception:
        return False
    sid = ("" if strategy_id is None else str(strategy_id)).strip()
    if sid:
        bypass = None
        try:
            bypass = CONFIG.get("entry_macro_gate_bypass_strategy_prefixes")
        except Exception:
            bypass = None
        prefixes = bypass if isinstance(bypass, list) and bypass else ["quant", "quant_"]
        s0 = sid.lower()
        for pfx in prefixes:
            p0 = str(pfx or "").strip().lower()
            if not p0:
                continue
            if s0.startswith(p0):
                return False
    p = str(pair or "").strip()
    if not p:
        return False
    scope = str(CONFIG.get("entry_macro_gate_scope", "all") or "all").lower().strip()
    if scope == "auto":
        st0 = TRACKER_STATE.get("entry_macro_gate_scope_suggested")
        if isinstance(st0, dict):
            try:
                sug = str(st0.get("scope") or "").lower().strip()
            except Exception:
                sug = ""
            try:
                ts0 = int(st0.get("ts") or 0)
            except Exception:
                ts0 = 0
            try:
                ttl_sec = int(CONFIG.get("entry_macro_gate_scope_suggested_ttl_sec", 86400) or 86400)
            except Exception:
                ttl_sec = 86400
            ttl_sec = int(max(60, min(14 * 86400, int(ttl_sec))))
            if sug in ("all", "btc_only", "alt_only") and ts0 > 0 and (int(_now_ms()) - int(ts0)) <= int(ttl_sec) * 1000:
                scope = sug
    pu = p.upper()
    coin = pu
    if "/" in pu:
        coin = pu.split("/")[0].split(":")[0]
    elif "-" in pu:
        try:
            coin = str(_hl_coin_from_pair(pu) or "").upper().strip()
        except Exception:
            coin = pu.split("-")[0]
    if scope == "btc_only":
        if coin not in ("BTC", "BTC-PERP"):
            return False
    elif scope == "alt_only":
        if coin in ("BTC", "BTC-PERP"):
            return False
    pairs_cfg = CONFIG.get("entry_macro_gate_pairs")
    if isinstance(pairs_cfg, list) and pairs_cfg:
        allowed = False
        for w in pairs_cfg:
            w0 = str(w or "").strip()
            if not w0:
                continue
            w0u = w0.upper()
            if w0u == pu or w0u == coin:
                allowed = True
                break
            if "/" in w0u and w0u.split("/")[0].split(":")[0] == coin:
                allowed = True
                break
            if "-" in w0u:
                try:
                    if str(_hl_coin_from_pair(w0u) or "").upper() == coin:
                        allowed = True
                        break
                except Exception:
                    pass
        if not allowed:
            return False
    sids_cfg = CONFIG.get("entry_macro_gate_strategy_ids")
    if isinstance(sids_cfg, list) and sids_cfg:
        sid = ("" if strategy_id is None else str(strategy_id)).strip()
        if not sid:
            return False
        ok = False
        for w in sids_cfg:
            w0 = str(w or "").strip()
            if not w0:
                continue
            if w0 == sid:
                ok = True
                break
        if not ok:
            return False
    return True


def _entry_macro_threshold_shift(regime: str, side: str) -> float:
    r = str(regime or "").upper().strip()
    s = str(side or "").lower().strip()
    key = None
    if r == "R1":
        key = "entry_macro_shift_r1_long" if s == "long" else "entry_macro_shift_r1_short"
    elif r == "R3":
        key = "entry_macro_shift_r3"
    elif r == "R4":
        key = "entry_macro_shift_r4_long" if s == "long" else "entry_macro_shift_r4_short"
    if not key:
        return 0.0
    try:
        return float(CONFIG.get(key, 0.0) or 0.0)
    except Exception:
        return 0.0


def _entry_macro_size_multiplier(regime: str, side: str) -> float:
    r = str(regime or "").upper().strip()
    s = str(side or "").lower().strip()
    if r == "R5":
        return 0.0
    base_key = None
    side_key = None
    if r == "R1":
        base_key = "entry_macro_size_mult_r1"
        side_key = "entry_macro_size_mult_r1_short" if s == "short" else None
    elif r == "R3":
        base_key = "entry_macro_size_mult_r3"
    elif r == "R4":
        base_key = "entry_macro_size_mult_r4"
        side_key = "entry_macro_size_mult_r4_long" if s == "long" else None
    try:
        base = float(CONFIG.get(base_key, 1.0) or 1.0) if base_key else 1.0
    except Exception:
        base = 1.0
    try:
        side_mul = float(CONFIG.get(side_key, 1.0) or 1.0) if side_key else 1.0
    except Exception:
        side_mul = 1.0
    return float(base) * float(side_mul)


def _entry_macro_btc_regime_at(ts_ms: int, thresholds: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    t = _macro_trend_at(int(ts_ms), "BTC")
    e = _macro_energy_at(int(ts_ms), "BTC")
    f = _macro_flow_at(int(ts_ms))
    try:
        rb = float(e.get("risk_baseline") or 0.0)
    except Exception:
        rb = 0.0
    try:
        atr = float(e.get("atr_pct") or 0.0)
    except Exception:
        atr = 0.0
    try:
        tw = int(t.get("trend_w_dir") or 0)
    except Exception:
        tw = 0
    try:
        td = int(t.get("trend_d_dir") or 0)
    except Exception:
        td = 0
    try:
        trc = float(t.get("trend_rate_change_dw") or 0.0)
    except Exception:
        trc = 0.0
    try:
        mf_dir = int(f.get("macro_flow_dir") or 0)
    except Exception:
        mf_dir = 0
    try:
        mf_chg_dir = int(f.get("macro_flow_chg_dir") or 0)
    except Exception:
        mf_chg_dir = 0
    try:
        mf_speed = float(f.get("macro_flow_chg_speed") or 0.0)
    except Exception:
        mf_speed = 0.0
    try:
        rs_btc = float(f.get("rs_btc_vs_mkt") or 0.0)
    except Exception:
        rs_btc = 0.0
    if isinstance(thresholds, dict) and thresholds:
        try:
            r_mid = float(thresholds.get("r_mid") or 0.0)
        except Exception:
            r_mid = 0.0
        try:
            r_high = float(thresholds.get("r_high") or 0.0)
        except Exception:
            r_high = 0.0
        try:
            atr_p80 = float(thresholds.get("atr_p80") or 0.0)
        except Exception:
            atr_p80 = 0.0
        try:
            atr_p95 = float(thresholds.get("atr_p95") or 0.0)
        except Exception:
            atr_p95 = 0.0
        try:
            r5_dom = float(thresholds.get("r5_dom") or 0.0)
        except Exception:
            r5_dom = 0.0
    else:
        try:
            r_mid = float(CONFIG.get("entry_macro_risk_mid", 0.0) or 0.0)
        except Exception:
            r_mid = 0.0
        try:
            r_high = float(CONFIG.get("entry_macro_risk_high", 0.0) or 0.0)
        except Exception:
            r_high = 0.0
        try:
            atr_p80 = float(CONFIG.get("entry_macro_atr_p80", 0.0) or 0.0)
        except Exception:
            atr_p80 = 0.0
        try:
            atr_p95 = float(CONFIG.get("entry_macro_atr_p95", 0.0) or 0.0)
        except Exception:
            atr_p95 = 0.0
        try:
            r5_dom = float(CONFIG.get("entry_macro_r5_flow_min_dom", 0.0) or 0.0)
        except Exception:
            r5_dom = 0.0
    valid = any(
        [
            rb > 0.0,
            atr > 0.0,
            tw != 0,
            td != 0,
            mf_dir != 0,
            rs_btc != 0.0,
        ]
    )
    regime = "R3"
    is_r5 = False
    if r_high > 0.0 and rb >= r_high:
        is_r5 = True
    if not is_r5 and atr_p95 > 0.0 and atr >= atr_p95:
        is_r5 = True
    if not is_r5 and r5_dom > 0.0:
        if mf_dir == -1 and mf_chg_dir == -1 and abs(rs_btc) >= r5_dom:
            is_r5 = True
    if is_r5:
        regime = "R5"
    else:
        if tw == 1 and td == 1 and trc > 0.0:
            high_risk = False
            if r_mid > 0.0 and rb > r_mid:
                high_risk = True
            if atr_p80 > 0.0 and atr >= atr_p80:
                high_risk = True
            if high_risk and not (r_high > 0.0 and rb >= r_high) and not (atr_p95 > 0.0 and atr >= atr_p95):
                regime = "R2"
            else:
                if r_mid <= 0.0 or rb <= r_mid:
                    if mf_dir in (0, 1) and rs_btc >= 0.0 and mf_chg_dir in (0, 1):
                        regime = "R1"
        if regime == "R3":
            if td == 0 or (tw * td) == -1 or mf_dir == 0:
                regime = "R3"
            elif tw == -1 and td == -1:
                low_risk_extreme = False
                if r_high > 0.0 and rb >= r_high:
                    low_risk_extreme = True
                if atr_p95 > 0.0 and atr >= atr_p95:
                    low_risk_extreme = True
                if not low_risk_extreme:
                    if mf_dir in (-1, 0) or rs_btc <= 0.0:
                        regime = "R4"
            else:
                regime = "R3"
    return {
        "ts": int(ts_ms),
        "regime": regime,
        "risk_baseline": rb,
        "atr_pct": atr,
        "trend_w_dir": tw,
        "trend_d_dir": td,
        "trend_rate_change_dw": trc,
        "macro_flow_dir": mf_dir,
        "macro_flow_chg_dir": mf_chg_dir,
        "macro_flow_chg_speed": mf_speed,
        "rs_btc_vs_mkt": rs_btc,
        "valid": bool(valid),
    }


def _entry_macro_threshold_overlay(thr_base: float, side: str, pair: str, strategy_id: Optional[str], ts_ms: int) -> Tuple[float, Optional[str], Optional[Dict[str, Any]]]:
    if not _entry_macro_scope_ok(pair=str(pair), strategy_id=strategy_id):
        return float(thr_base), None, None
    snap = _entry_macro_btc_regime_at(int(ts_ms))
    regime = str(snap.get("regime") or "R3")
    if not bool(snap.get("valid", True)):
        return float(thr_base), regime, snap
    shift = _entry_macro_threshold_shift(regime, side)
    thr_adj = float(thr_base) + float(shift)
    return float(thr_adj), regime, snap


