def _aster_trailing_stop_market_order_qty(coin: str, side: str, qty: float, callback_rate: float, activation_price: float = None, reduce_only: bool = True, owner: Any = None, client_order_id: str = None) -> Dict[str, Any]:
    sym = _aster_symbol_from_coin(coin)
    s = str(side or "").lower().strip()
    if s not in ("long", "short", "buy", "sell"):
        raise RuntimeError("invalid_side")
    buy = (s in ("long", "buy"))
    order_side = "BUY" if buy else "SELL"
    q = abs(float(qty))
    q = float(_aster_round_qty(sym, q))
    cb = float(callback_rate)
    if (not math.isfinite(cb)) or cb <= 0.0:
        raise RuntimeError("invalid_callback_rate")
    params: Dict[str, Any] = {
        "symbol": sym,
        "side": order_side,
        "type": "TRAILING_STOP_MARKET",
        "callbackRate": float(cb),
        "quantity": float(q),
        "newOrderRespType": "RESULT",
        "workingType": "CONTRACT_PRICE",
    }
    if activation_price is not None:
        ap = float(activation_price)
        if math.isfinite(ap) and ap > 0.0:
            params["activationPrice"] = float(ap)
    if bool(reduce_only):
        params["reduceOnly"] = "true"
    if client_order_id:
        params["newClientOrderId"] = str(client_order_id)
    ver = "v3" if _aster_auth_mode(owner) == "v3" else "v1"
    resp = _aster_http("POST", f"/fapi/{ver}/order", params=params, signed=True, timeout_sec=15.0, owner=owner)
    return {"symbol": sym, "side": order_side, "quantity": float(q), "callback_rate": float(cb), "activation_price": (None if activation_price is None else float(params.get("activationPrice"))), "reduce_only": bool(reduce_only), "resp": resp}


def _aster_protect_after_open(coin: str, pos_side: str, qty: float, entry_px: float, owner: Any, base_order_id: str, tag: str) -> Dict[str, Any]:
    out: Dict[str, Any] = {"ok": False, "skipped": False, "reason": None, "stop": None, "take_profit": None, "trailing": None, "errors": []}

    try:
        enabled = bool(CONFIG.get("aster_protect_on_open_enabled", False))
    except Exception:
        enabled = False
    if not enabled:
        out["skipped"] = True
        out["reason"] = "disabled"
        return out

    allow = CONFIG.get("aster_protect_owner_allowlist")
    if isinstance(allow, list) and allow:
        if str(owner or "").strip().lower() not in {str(x).strip().lower() for x in list(allow)}:
            out["skipped"] = True
            out["reason"] = "owner_not_allowed"
            return out

    try:
        q = float(qty)
    except Exception:
        q = 0.0
    try:
        px0 = float(entry_px)
    except Exception:
        px0 = 0.0
    if (not math.isfinite(q)) or q <= 0.0:
        out["skipped"] = True
        out["reason"] = "missing_qty"
        return out
    if (not math.isfinite(px0)) or px0 <= 0.0:
        out["skipped"] = True
        out["reason"] = "missing_entry_price"
        return out

    s = str(pos_side or "").lower().strip()
    if s not in ("long", "short"):
        out["skipped"] = True
        out["reason"] = "invalid_pos_side"
        return out
    is_long = (s == "long")
    close_side = "sell" if is_long else "buy"
    sym = _aster_symbol_from_coin(str(coin))

    try:
        sl_pct = float(CONFIG.get("aster_protect_stop_loss_pct") or 0.0)
    except Exception:
        sl_pct = 0.0
    try:
        tp_pct = float(CONFIG.get("aster_protect_take_profit_pct") or 0.0)
    except Exception:
        tp_pct = 0.0
    try:
        cb = float(CONFIG.get("aster_protect_trailing_callback_rate") or 0.0)
    except Exception:
        cb = 0.0
    try:
        min_dist_bps = float(CONFIG.get("aster_protect_min_distance_bps") or 0.0)
    except Exception:
        min_dist_bps = 0.0
    min_dist_bps = float(_clip(float(min_dist_bps), 0.0, 200.0))

    if math.isfinite(sl_pct) and sl_pct > 0.0:
        sl_pct = float(_clip(float(sl_pct), 0.0005, 0.80))
    else:
        sl_pct = 0.0
    if math.isfinite(tp_pct) and tp_pct > 0.0:
        tp_pct = float(_clip(float(tp_pct), 0.0005, 5.0))
    else:
        tp_pct = 0.0
    if math.isfinite(cb) and cb > 0.0:
        cb = float(_clip(float(cb), 0.1, 5.0))
    else:
        cb = 0.0

    def _cid(kind: str) -> str:
        h = hashlib.sha256(f"{str(base_order_id)}|{str(kind)}|{str(owner)}".encode("utf-8")).hexdigest()
        return f"p{h[:30]}"

    ok_any = False

    if sl_pct > 0.0:
        raw = float(px0) * (1.0 - float(sl_pct)) if is_long else float(px0) * (1.0 + float(sl_pct))
        min_raw = float(px0) * (1.0 - float(min_dist_bps) / 10000.0) if is_long else float(px0) * (1.0 + float(min_dist_bps) / 10000.0)
        raw = min(raw, min_raw) if is_long else max(raw, min_raw)
        try:
            sp = _aster_round_price(sym, float(raw), round_up=(not is_long))
            stop = _aster_stop_market_order_qty(coin=str(coin), side=str(close_side), qty=float(q), stop_price=float(sp), reduce_only=True, owner=owner, client_order_id=_cid("sl"))
            out["stop"] = stop
            ok_any = True
        except Exception as e:
            out["errors"].append({"kind": "stop_loss", "error": str(e)})

    if tp_pct > 0.0:
        raw = float(px0) * (1.0 + float(tp_pct)) if is_long else float(px0) * (1.0 - float(tp_pct))
        min_raw = float(px0) * (1.0 + float(min_dist_bps) / 10000.0) if is_long else float(px0) * (1.0 - float(min_dist_bps) / 10000.0)
        raw = max(raw, min_raw) if is_long else min(raw, min_raw)
        try:
            tp = _aster_round_price(sym, float(raw), round_up=bool(is_long))
            take = _aster_take_profit_market_order_qty(coin=str(coin), side=str(close_side), qty=float(q), trigger_price=float(tp), reduce_only=True, owner=owner, client_order_id=_cid("tp"))
            out["take_profit"] = take
            ok_any = True
        except Exception as e:
            out["errors"].append({"kind": "take_profit", "error": str(e)})

    if cb > 0.0:
        try:
            trail = _aster_trailing_stop_market_order_qty(coin=str(coin), side=str(close_side), qty=float(q), callback_rate=float(cb), activation_price=float(px0), reduce_only=True, owner=owner, client_order_id=_cid("tr"))
            out["trailing"] = trail
            ok_any = True
        except Exception as e:
            out["errors"].append({"kind": "trailing", "error": str(e)})

    out["ok"] = bool(ok_any) and (not bool(out["errors"]))
    if ok_any and bool(out["errors"]):
        out["ok"] = False
    if not ok_any:
        out["skipped"] = True
        out["reason"] = "no_protect_configured"
    return out


def _aster_order_query(symbol: str, order_id: Any, owner: Any = None) -> Any:
    sym = str(symbol or "").upper().strip()
    if not sym:
        raise RuntimeError("invalid_symbol")
    try:
        oid = int(order_id)
    except Exception:
        raise RuntimeError("invalid_order_id")
    ver = "v3" if _aster_auth_mode(owner) == "v3" else "v1"
    return _aster_http("GET", f"/fapi/{ver}/order", params={"symbol": sym, "orderId": int(oid)}, signed=True, timeout_sec=10.0, owner=owner)


def _aster_order_cancel(symbol: str, order_id: Any, owner: Any = None) -> Any:
    sym = str(symbol or "").upper().strip()
    if not sym:
        raise RuntimeError("invalid_symbol")
    try:
        oid = int(order_id)
    except Exception:
        raise RuntimeError("invalid_order_id")
    ver = "v3" if _aster_auth_mode(owner) == "v3" else "v1"
    return _aster_http("DELETE", f"/fapi/{ver}/order", params={"symbol": sym, "orderId": int(oid)}, signed=True, timeout_sec=10.0, owner=owner)


def _aster_wait_fill(symbol: str, order_id: Any, timeout_sec: float, poll_ms: int = 250, owner: Any = None) -> Dict[str, Any]:
    t0 = time.time()
    timeout = float(max(0.0, float(timeout_sec)))
    poll = int(max(50, int(poll_ms)))
    last: Any = None
    while True:
        now = time.time()
        if timeout > 0 and (now - t0) >= timeout:
            break
        try:
            last = _aster_order_query(symbol=str(symbol), order_id=order_id, owner=owner)
        except Exception as e:
            last = {"error": str(e)}
        st = None
        try:
            st = str((last or {}).get("status") or "").upper() if isinstance(last, dict) else None
        except Exception:
            st = None
        if st in ("FILLED", "CANCELED", "REJECTED", "EXPIRED"):
            break
        time.sleep(float(poll) / 1000.0)
    out: Dict[str, Any] = {"ok": True, "done": False, "filled": False, "last": last}
    try:
        st2 = str((last or {}).get("status") or "").upper() if isinstance(last, dict) else ""
    except Exception:
        st2 = ""
    out["done"] = bool(st2 in ("FILLED", "CANCELED", "REJECTED", "EXPIRED"))
    out["filled"] = bool(st2 == "FILLED")
    out["status"] = st2
    return out


def _aster_update_leverage(coin: str, leverage: int, owner: Any = None) -> Any:
    sym = _aster_symbol_from_coin(coin)
    ver = "v3" if _aster_auth_mode(owner) == "v3" else "v1"
    lev_target = _entry_hard_clip_leverage(leverage)

    cap_cache = TRACKER_STATE.get("aster_leverage_cap")
    if not isinstance(cap_cache, dict):
        cap_cache = {}
        TRACKER_STATE["aster_leverage_cap"] = cap_cache
    try:
        cap0 = cap_cache.get(str(coin))
        cap_i = int(cap0) if cap0 is not None else None
    except Exception:
        cap_i = None
    if cap_i is not None and int(cap_i) > 0:
        lev_target = int(min(int(lev_target), int(cap_i)))

    lev_cache = TRACKER_STATE.get("aster_leverage")
    if not isinstance(lev_cache, dict):
        lev_cache = {}
        TRACKER_STATE["aster_leverage"] = lev_cache
    try:
        cur0 = lev_cache.get(str(coin))
        cur_i = int(cur0) if cur0 is not None else None
    except Exception:
        cur_i = None
    if cur_i is not None and int(cur_i) == int(lev_target):
        return {"ok": True, "cached": True, "symbol": sym, "coin": str(coin), "leverage": int(cur_i), "leverage_used": int(cur_i)}

    candidates: List[int] = []
    for lv in [int(lev_target), 12, 10, 8, 6, 5, 4, 3, 2, 1]:
        try:
            lv_i = int(lv)
        except Exception:
            continue
        if lv_i <= 0:
            continue
        if lv_i > int(lev_target):
            continue
        if lv_i not in candidates:
            candidates.append(int(lv_i))
    if not candidates:
        candidates = [1]

    last_err: Optional[str] = None
    for lv_i in candidates:
        try:
            resp = _aster_http("POST", f"/fapi/{ver}/leverage", params={"symbol": sym, "leverage": int(lv_i)}, signed=True, timeout_sec=10.0, owner=owner)
            try:
                lev_cache[str(coin)] = int(lv_i)
            except Exception:
                pass
            try:
                cap_prev = cap_cache.get(str(coin))
                cap_prev_i = int(cap_prev) if cap_prev is not None else None
            except Exception:
                cap_prev_i = None
            try:
                if cap_prev_i is None or int(lv_i) < int(cap_prev_i):
                    cap_cache[str(coin)] = int(lv_i)
            except Exception:
                pass
            if isinstance(resp, dict):
                out = dict(resp)
                out["leverage_used"] = int(lv_i)
                return out
            return resp
        except Exception as e:
            last_err = str(e)
            msg = str(last_err or "").lower()
            if ("-4161" in str(last_err)) or ("leverage reduction is not supported" in msg):
                out = {
                    "ok": True,
                    "skipped": True,
                    "symbol": sym,
                    "coin": str(coin),
                    "leverage_requested": int(lev_target),
                    "reason": "leverage_reduction_not_supported_isolated_open_positions",
                    "error": str(last_err),
                }
                if cur_i is not None:
                    out["leverage_used"] = int(cur_i)
                    out["leverage"] = int(cur_i)
                return out
            if (
                ("-2027" in str(last_err))
                or ("-4028" in str(last_err))
                or ("maximum supported leverage" in msg)
                or ("maximum available leverage" in msg)
                or ("exceeds the maximum" in msg)
                or (("leverage" in msg) and ("not valid" in msg))
            ):
                continue
            raise
    raise RuntimeError(last_err or "aster_leverage_update_failed")


def _aster_set_margin_type(coin: str, isolated: bool, owner: Any = None) -> Any:
    sym = _aster_symbol_from_coin(coin)
    desired = "ISOLATED" if bool(isolated) else "CROSSED"
    cache = ASTER_STATE.get("margin_type")
    if not isinstance(cache, dict):
        cache = {}
        ASTER_STATE["margin_type"] = cache
    try:
        cached = cache.get(sym)
    except Exception:
        cached = None
    if cached == desired:
        return {"ok": True, "cached": True, "symbol": sym, "marginType": desired}
    ver = "v3" if _aster_auth_mode(owner) == "v3" else "v1"
    try:
        to0 = float(CONFIG.get("aster_http_timeout_sec", 20.0) or 20.0)
    except Exception:
        to0 = 20.0
    to0 = float(max(1.0, min(60.0, float(to0))))
    resp = _aster_http("POST", f"/fapi/{ver}/marginType", params={"symbol": sym, "marginType": desired}, signed=True, timeout_sec=float(to0), owner=owner)
    try:
        cache[sym] = desired
    except Exception:
        pass
    return resp


def _aster_classify_error(err: Any) -> Dict[str, Any]:
    s = ""
    try:
        s = str(err or "")
    except Exception:
        s = ""
    sl = s.lower()
    code = None
    try:
        m = re.search(r'"code"\s*:\s*(-?\d+)', s)
        if m:
            code = int(m.group(1))
    except Exception:
        code = None

    if (code == -5019) or ("service not available in your region" in sl) or ("-5019" in s):
        return {
            "error_kind": "region_blocked",
            "code": code,
            "hint": "Aster API 返回地域限制（-5019）。需要在允许地区运行，或配置 aster_http_proxy / ASTER_HTTP_PROXY 走代理。",
        }
    if (code == -1021) or ("timestamp for this request" in sl) or ("recvwindow" in sl) or ("-1021" in s):
        return {
            "error_kind": "clock_skew",
            "code": code,
            "hint": "Aster API 时间戳偏差（-1021）。检查本机时间同步（NTP），并可调大 aster_recv_window_ms / aster_timestamp_safety_ms。",
        }
    if "missing_aster_api_key" in sl or "missing_aster_secret_key" in sl or "aster_auth_unavailable" in sl:
        return {
            "error_kind": "auth_missing",
            "code": code,
            "hint": "Aster 鉴权缺失或不可用。优先用 GET /live/preflight 检查 aster.owners.<owner>.blockers 与 auth_mode。",
        }
    return {"error_kind": None, "code": code, "hint": None}


def _aster_record_last_error(owner: Any, err: Any) -> None:
    try:
        o = str(_ab_norm_owner(owner) or owner or "").strip().lower()
    except Exception:
        o = str(owner or "").strip().lower()
    if o not in ("strategy", "quant", "carry", "three_screen"):
        o = "strategy"
    info = _aster_classify_error(err)
    try:
        s = str(err or "")
    except Exception:
        s = ""
    try:
        d = TRACKER_STATE.get("aster_last_error_by_owner")
        if not isinstance(d, dict):
            d = {}
            TRACKER_STATE["aster_last_error_by_owner"] = d
        d[o] = {
            "ts": int(_now_ms()),
            "owner": str(o),
            "error": s[:2000],
            "error_kind": info.get("error_kind"),
            "code": info.get("code"),
        }
    except Exception:
        pass


def _aster_ping_payload(owner: Any = None) -> Dict[str, Any]:
    base_url = _aster_base_url()
    out: Dict[str, Any] = {
        "ok": True,
        "base_url": base_url,
        "trading_enabled": _aster_enabled_for_trading_for_owner(owner),
        "auth_mode": _aster_auth_mode(owner),
        "has_api_key": bool(_aster_api_key(owner)),
        "has_secret": bool(_aster_secret_key(owner)),
        "has_user": bool(_aster_user(owner)),
        "has_signer": bool(_aster_signer(owner)),
        "has_signer_private_key": bool(_aster_signer_private_key(owner)),
        "server_time": None,
        "btc_mid": None,
    }
    try:
        ver = "v3" if _aster_auth_mode(owner) == "v3" else "v1"
        try:
            to0 = float(CONFIG.get("aster_ping_timeout_sec", CONFIG.get("aster_http_timeout_sec", 20.0)) or 20.0)
        except Exception:
            to0 = 20.0
        to0 = float(max(1.0, min(60.0, float(to0))))
        _aster_http("GET", f"/fapi/{ver}/ping", params={}, signed=False, timeout_sec=float(to0), owner=owner)
        t = _aster_http("GET", f"/fapi/{ver}/time", params={}, signed=False, timeout_sec=float(to0), owner=owner)
        if isinstance(t, dict) and t.get("serverTime") is not None:
            out["server_time"] = int(t.get("serverTime"))
        try:
            out["btc_mid"] = float(_aster_mid("BTC", owner=owner))
        except Exception:
            out["btc_mid"] = None
    except Exception as e:
        out["ok"] = False
        err0 = str(e)
        out["error"] = err0
        try:
            out["proxy_configured"] = bool(str(_aster_http_proxy(owner) or "").strip())
        except Exception:
            pass
        try:
            msg = str(out.get("error") or "")
            msg_l = msg.lower()
            if ("unexpected_eof_while_reading" in msg_l) or ("eof occurred in violation of protocol" in msg_l) or ("connection reset" in msg_l) or ("errno=54" in msg_l):
                out["error_kind"] = "network_handshake_reset"
                out["hint"] = "Aster HTTPS 握手被对端重置；检查网络/地域限制/防火墙，或配置 aster_http_proxy / ASTER_HTTP_PROXY 走代理"
            else:
                info = _aster_classify_error(msg)
                if info.get("error_kind"):
                    out["error_kind"] = info.get("error_kind")
                if info.get("hint"):
                    out["hint"] = info.get("hint")
                if info.get("code") is not None:
                    out["code"] = info.get("code")
        except Exception:
            pass
        try:
            _aster_record_last_error(owner, err0)
        except Exception:
            pass
    return out


def _aster_fetch_positions(owner: Any = None) -> Tuple[List[Dict[str, Any]], Optional[str]]:
    mode = _aster_auth_mode(owner)
    preferred = "v3" if mode == "v3" else "v1"
    last_err: Optional[str] = None

    def _try(path: str) -> Any:
        nonlocal last_err
        try:
            try:
                to0 = float(CONFIG.get("aster_http_timeout_sec", 20.0) or 20.0)
            except Exception:
                to0 = 20.0
            to0 = float(max(1.0, min(60.0, float(to0))))
            return _aster_http("GET", path, params={}, signed=True, timeout_sec=float(to0), owner=owner)
        except Exception as e:
            last_err = str(e)
            return None

    def _is_err_payload(v: Any) -> bool:
        if not isinstance(v, dict):
            return False
        if v.get("success") is False:
            return True

    def _unwrap_data(v: Any) -> Any:
        if isinstance(v, dict) and ("data" in v):
            return v.get("data")
        return v
        code = v.get("code")
        if code is None:
            return False
        try:
            ci = int(code)
            return ci != 0
        except Exception:
            return True

    candidates: List[str] = []
    for ver in [preferred, "v2", "v1", "v3"]:
        if ver not in ("v1", "v2", "v3"):
            continue
        candidates.append(f"/fapi/{ver}/positionRisk")
        candidates.append(f"/fapi/{ver}/account")
    candidates.append("/dapi/v1/positionRisk")
    candidates.append("/dapi/v1/account")

    raw = None
    for p in candidates:
        candidate = _try(p)
        if candidate is None:
            continue
        if _is_err_payload(candidate):
            try:
                last_err = str(candidate.get("msg") or candidate.get("message") or candidate)
            except Exception:
                last_err = "aster_error_payload"
            continue
        candidate_u = _unwrap_data(candidate)
        if isinstance(candidate_u, list):
            raw = candidate_u
            break
        if isinstance(candidate_u, dict):
            pr = candidate_u.get("positionRisk")
            ps = candidate_u.get("positions")
            if isinstance(pr, list) or isinstance(ps, list):
                raw = candidate_u
                break
        continue

    raw = _unwrap_data(raw)

    positions_raw: List[Dict[str, Any]] = []
    if isinstance(raw, list):
        positions_raw = [x for x in raw if isinstance(x, dict)]
    elif isinstance(raw, dict):
        pr = raw.get("positionRisk")
        if isinstance(pr, list):
            positions_raw = [x for x in pr if isinstance(x, dict)]
        else:
            ps = raw.get("positions")
            if isinstance(ps, list):
                positions_raw = [x for x in ps if isinstance(x, dict)]

    out: List[Dict[str, Any]] = []
    for p in list(positions_raw):
        try:
            sym = str(p.get("symbol") or "").upper().strip()
            if not sym:
                continue
            amt = _to_float(p.get("positionAmt", p.get("positionAmtQty", p.get("position", p.get("amt", 0.0)))))
            if abs(float(amt)) < 1e-12:
                continue
            side = "long" if float(amt) > 0 else "short"
            coin = sym
            for suf in ("USDT", "USDC", "USD"):
                if coin.endswith(suf):
                    coin = coin[:-len(suf)]
                    break
            for suf in ("-PERP", "_PERP", "PERP"):
                if coin.endswith(suf):
                    coin = coin[:-len(suf)]
                    break
            coin = _hl_coin_from_pair(coin)
            entry_px = _to_float(p.get("entryPrice", p.get("avgEntryPrice", p.get("averagePrice", 0.0))))
            liq_px = _to_float(p.get("liquidationPrice", p.get("liqPrice", p.get("liqPx", 0.0))))
            mark_px = _to_float(p.get("markPrice", p.get("markPx", p.get("price", 0.0))))
            unreal = _to_float(p.get("unRealizedProfit", p.get("unrealizedProfit", p.get("unrealizedPnl", 0.0))))

            lv = p.get("leverage")
            if lv is None:
                lv = p.get("leverageRate")
            try:
                lv_f = float(_to_float(lv))
            except Exception:
                lv_f = 0.0
            leverage_i: Optional[int] = None
            if math.isfinite(float(lv_f)) and float(lv_f) > 0.0:
                try:
                    leverage_i = int(max(1, int(round(float(lv_f)))))
                except Exception:
                    leverage_i = None
            notional = p.get("notional")
            if notional is None:
                notional = p.get("positionNotional")
            if notional is not None:
                notional_u = abs(_to_float(notional))
            else:
                px = float(mark_px) if float(mark_px) > 0 else float(entry_px)
                notional_u = abs(float(amt) * float(px))
            out.append({
                "coin": str(coin),
                "symbol": str(sym),
                "side": str(side),
                "position_amt": float(amt),
                "notional_usdc": float(notional_u),
                "entry_px": float(entry_px),
                "liq_px": float(liq_px),
                "mark_px": float(mark_px),
                "unrealized_pnl_u": float(unreal),
                "leverage": leverage_i,
            })
        except Exception:
            continue

    if raw is None:
        return [], last_err
    return out, None


def _aster_fetch_account_summary(owner: Any = None) -> Dict[str, Any]:
    mode = _aster_auth_mode(owner)
    preferred = "v3" if mode == "v3" else "v1"
    last_err: Optional[str] = None

    def _try(path: str) -> Any:
        nonlocal last_err
        try:
            try:
                to0 = float(CONFIG.get("aster_http_timeout_sec", 20.0) or 20.0)
            except Exception:
                to0 = 20.0
            to0 = float(max(1.0, min(60.0, float(to0))))
            return _aster_http("GET", path, params={}, signed=True, timeout_sec=float(to0), owner=owner)
        except Exception as e:
            last_err = str(e)
            return None

    def _unwrap_data(v: Any) -> Any:
        if isinstance(v, dict) and ("data" in v):
            return v.get("data")
        return v

    def _is_err_payload(v: Any) -> bool:
        if not isinstance(v, dict):
            return False
        if v.get("success") is False:
            return True
        if "code" in v:
            try:
                return int(v.get("code") or 0) != 0
            except Exception:
                return True
        return False

    candidates: List[str] = []
    for ver in [preferred, "v2", "v1", "v3"]:
        if ver not in ("v1", "v2", "v3"):
            continue
        candidates.append(f"/fapi/{ver}/account")
        candidates.append(f"/fapi/{ver}/balance")
    candidates.append("/dapi/v1/account")
    candidates.append("/dapi/v1/balance")

    raw = None
    for p in candidates:
        candidate = _try(p)
        if candidate is None:
            continue
        if _is_err_payload(candidate):
            try:
                last_err = str(candidate.get("msg") or candidate.get("message") or candidate)
            except Exception:
                last_err = "aster_error_payload"
            continue
        candidate_u = _unwrap_data(candidate)
        if isinstance(candidate_u, dict) and candidate_u:
            raw = candidate_u
            break
        if isinstance(candidate_u, list) and candidate_u:
            raw = {"balances": [x for x in candidate_u if isinstance(x, dict)]}
            break

    raw = _unwrap_data(raw)
    if not isinstance(raw, dict) or not raw:
        return {"ok": False, "error": last_err or "aster_account_unavailable"}

    def _pick_balance_asset(assets: Any, symbol: str) -> Optional[Dict[str, Any]]:
        if not isinstance(assets, list):
            return None
        sym_u = str(symbol or "").upper().strip()
        for a in assets:
            if not isinstance(a, dict):
                continue
            asset = str(a.get("asset") or a.get("coin") or "").upper().strip()
            if asset == sym_u:
                return a
        return None

    assets = raw.get("assets")
    balances = raw.get("balances")
    if assets is None and balances is not None:
        assets = balances

    usdt = _pick_balance_asset(assets, "USDT")
    usdc = _pick_balance_asset(assets, "USDC")

    def _asset_summary(a: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
        if not isinstance(a, dict):
            return None
        asset = str(a.get("asset") or a.get("coin") or "").upper().strip()
        if not asset:
            return None
        out: Dict[str, Any] = {"asset": asset}
        for k in [
            "walletBalance",
            "availableBalance",
            "marginBalance",
            "unrealizedProfit",
            "initialMargin",
            "maintMargin",
            "positionInitialMargin",
            "openOrderInitialMargin",
            "crossWalletBalance",
            "crossUnPnl",
            "maxWithdrawAmount",
        ]:
            if k in a:
                out[k] = float(_to_float(a.get(k)))
        return out

    summary: Dict[str, Any] = {}
    for k in [
        "totalWalletBalance",
        "totalMarginBalance",
        "totalUnrealizedProfit",
        "availableBalance",
        "walletBalance",
        "totalInitialMargin",
        "totalMaintMargin",
        "totalPositionInitialMargin",
        "totalOpenOrderInitialMargin",
        "maxWithdrawAmount",
    ]:
        if k in raw:
            summary[k] = float(_to_float(raw.get(k)))

    out = {
        "ok": True,
        "ts": int(_now_ms()),
        "owner": (None if owner is None else str(owner)),
        "summary": summary,
        "assets": {
            "USDT": _asset_summary(usdt),
            "USDC": _asset_summary(usdc),
        },
    }
    return out


def _aster_fetch_open_orders(owner: Any = None) -> Tuple[List[Dict[str, Any]], Optional[str]]:
    mode = _aster_auth_mode(owner)
    preferred = "v3" if mode == "v3" else "v1"
    last_err: Optional[str] = None

    def _try(path: str) -> Any:
        nonlocal last_err
        try:
            return _aster_http("GET", path, params={}, signed=True, timeout_sec=10.0, owner=owner)
        except Exception as e:
            last_err = str(e)
            return None

    def _is_err_payload(v: Any) -> bool:
        if not isinstance(v, dict):
            return False
        if v.get("success") is False:
            return True

    def _unwrap_data(v: Any) -> Any:
        if isinstance(v, dict) and ("data" in v):
            return v.get("data")
        return v
        code = v.get("code")
        if code is None:
            return False
        try:
            ci = int(code)
            return ci != 0
        except Exception:
            return True

    candidates: List[str] = []
    for ver in [preferred, "v2", "v1", "v3"]:
        if ver not in ("v1", "v2", "v3"):
            continue
        candidates.append(f"/fapi/{ver}/openOrders")
    candidates.append("/dapi/v1/openOrders")

    raw = None
    for p in candidates:
        candidate = _try(p)
        if candidate is None:
            continue
        if _is_err_payload(candidate):
            try:
                last_err = str(candidate.get("msg") or candidate.get("message") or candidate)
            except Exception:
                last_err = "aster_error_payload"
            continue
        raw = _unwrap_data(candidate)
        break

    raw = _unwrap_data(raw)

    if isinstance(raw, list):
        return [x for x in raw if isinstance(x, dict)], None

    if raw is None:
        return [], last_err
    return [], None


def _aster_sync(update_orders: bool = True) -> Dict[str, Any]:
    now_ms = _now_ms()

    def _aster_owner_ready_for_positions(owner0: str) -> bool:
        try:
            if not bool(_aster_enabled_for_trading_for_owner(owner0)):
                return False
        except Exception:
            return False
        try:
            omode = str(_aster_auth_mode(owner0) or "none").lower().strip()
        except Exception:
            omode = "none"
        if omode not in ("v1", "v3"):
            return False
        if omode == "v1":
            return bool(_aster_api_key(owner0)) and bool(_aster_secret_key(owner0))
        return bool(_aster_user(owner0)) and bool(_aster_signer(owner0)) and bool(_aster_signer_private_key(owner0))

    owners_to_fetch: List[Any] = []
    for owner0 in ("quant", "strategy", "carry", "three_screen"):
        if _aster_owner_ready_for_positions(owner0):
            owners_to_fetch.append(owner0)
    if not owners_to_fetch:
        owners_to_fetch = [None]

    errs: Dict[str, str] = {}
    positions_by_owner: Dict[str, Dict[str, Dict[str, Any]]] = {}
    for owner0 in owners_to_fetch:
        owner_key = _ab_norm_owner(owner0 or "strategy")
        if owner_key not in ("strategy", "quant", "carry", "three_screen"):
            owner_key = "strategy"
        by_pair = positions_by_owner.get(owner_key)
        if not isinstance(by_pair, dict):
            by_pair = {}
            positions_by_owner[owner_key] = by_pair
        try:
            if owner0 is None:
                pos0, err0 = _aster_fetch_positions()
            else:
                try:
                    pos0, err0 = _aster_fetch_positions(owner=owner0)
                except TypeError:
                    pos0, err0 = _aster_fetch_positions()
        except Exception as e:
            pos0, err0 = [], str(e)
        if err0 is not None:
            errs[str(owner0 or "strategy")] = str(err0)
            continue
        for p in list(pos0 or []):
            if not isinstance(p, dict):
                continue
            coin = str(p.get("coin") or "").upper().strip()
            if not coin:
                continue
            pair = f"{coin}-PERP"
            try:
                amt = float(_to_float(p.get("position_amt", 0.0)))
            except Exception:
                amt = 0.0
            if abs(float(amt)) < 1e-12:
                continue
            cur = by_pair.get(pair)
            if not isinstance(cur, dict):
                by_pair[pair] = dict(p)
                by_pair[pair]["side"] = ("long" if float(amt) > 0 else "short")
                by_pair[pair]["ab_owner"] = owner_key
                continue
            try:
                prev_amt = float(_to_float(cur.get("position_amt", 0.0)))
            except Exception:
                prev_amt = 0.0
            new_amt = float(prev_amt) + float(amt)
            cur["position_amt"] = float(new_amt)
            cur["side"] = ("long" if float(new_amt) > 0 else "short")
            try:
                cur["notional_usdc"] = float(_to_float(cur.get("notional_usdc", 0.0))) + float(_to_float(p.get("notional_usdc", 0.0)))
            except Exception:
                pass
            try:
                cur["unrealized_pnl_u"] = float(_to_float(cur.get("unrealized_pnl_u", 0.0))) + float(_to_float(p.get("unrealized_pnl_u", 0.0)))
            except Exception:
                pass
            w0 = abs(float(prev_amt))
            w1 = abs(float(amt))
            w = float(w0 + w1)
            if w > 0:
                for k in ("entry_px", "liq_px"):
                    try:
                        a = float(_to_float(cur.get(k, 0.0)))
                        b = float(_to_float(p.get(k, 0.0)))
                        if a > 0 and b > 0:
                            cur[k] = (a * w0 + b * w1) / w
                    except Exception:
                        pass
            try:
                mp = float(_to_float(p.get("mark_px", 0.0)))
                if mp > 0:
                    cur["mark_px"] = mp
            except Exception:
                pass

    positions_all: List[Dict[str, Any]] = []
    for by_pair in list(positions_by_owner.values()):
        if not isinstance(by_pair, dict):
            continue
        for p in list(by_pair.values()):
            if isinstance(p, dict):
                positions_all.append(p)

    fetch_err = (";".join([f"{k}:{v}" for k, v in sorted(list(errs.items()))]) if errs else None)

    if fetch_err is not None:
        aster_state = TRACKER_STATE.get("aster")
        if not isinstance(aster_state, dict):
            aster_state = {}
            TRACKER_STATE["aster"] = aster_state
        try:
            prev_cnt = int(aster_state.get("open_position_count") or 0)
        except Exception:
            prev_cnt = 0
        aster_state["ts"] = int(now_ms)
        aster_state["open_position_count"] = int(prev_cnt)
        aster_state["pruned_open_positions"] = 0
        aster_state["positions_fetch_error"] = fetch_err
        return {
            "ok": False,
            "ts": int(now_ms),
            "open_orders": 0,
            "open_positions": int(prev_cnt),
            "pruned_open_positions": 0,
            "orders_updated": 0,
            "open_orders_error": None,
            "error": fetch_err,
        }

    open_orders: List[Dict[str, Any]] = []
    open_orders_err: Optional[str] = None
    if bool(update_orders):
        errs_orders: Dict[str, str] = {}
        all_open_orders: List[Dict[str, Any]] = []
        for owner0 in owners_to_fetch:
            try:
                oo0, err0 = _aster_fetch_open_orders(owner=owner0)
            except Exception as e:
                oo0, err0 = [], str(e)
            if err0 is not None:
                errs_orders[str(owner0 or "strategy")] = str(err0)
                continue
            for o in list(oo0 or []):
                if not isinstance(o, dict):
                    continue
                o2 = dict(o)
                if o2.get("ab_owner") is None:
                    o2["ab_owner"] = str(owner0 or "strategy")
                all_open_orders.append(o2)
        open_orders = all_open_orders
        open_orders_err = (";".join([f"{k}:{v}" for k, v in sorted(list(errs_orders.items()))]) if errs_orders else None)

    open_pairs_by_owner: Dict[str, Dict[str, Dict[str, Any]]] = {"strategy": {}, "quant": {}, "carry": {}, "three_screen": {}}
    for owner_key, by_pair in list(positions_by_owner.items()):
        if owner_key not in ("strategy", "quant", "carry", "three_screen"):
            continue
        if not isinstance(by_pair, dict):
            continue
        for p in list(by_pair.values()):
            if not isinstance(p, dict):
                continue
            try:
                coin = str(p.get("coin") or "").upper().strip()
                if not coin:
                    continue
                pair = f"{coin}-PERP"
                open_pairs_by_owner[owner_key][pair] = {
                    "pair": str(pair),
                    "ts": int(now_ms),
                    "side": str(p.get("side") or "long"),
                    "notional_usdc": float(_to_float(p.get("notional_usdc", 0.0))),
                    "leverage": (None if p.get("leverage") is None else int(p.get("leverage") or 0)),
                    "aster_position_amt": float(_to_float(p.get("position_amt", 0.0))),
                    "aster_unrealized_pnl_u": float(_to_float(p.get("unrealized_pnl_u", 0.0))),
                    "aster_mid_px": float(_to_float(p.get("mark_px", 0.0))),
                    "aster_entry_px": float(_to_float(p.get("entry_px", 0.0))),
                    "aster_liquidation_px": float(_to_float(p.get("liq_px", 0.0))),
                }
            except Exception:
                continue

    open_pairs_all: Dict[str, Dict[str, Any]] = {}
    try:
        for sys_name0, mp0 in list(open_pairs_by_owner.items()):
            if not isinstance(mp0, dict):
                continue
            for pair0, meta0 in list(mp0.items()):
                if isinstance(meta0, dict):
                    open_pairs_all[str(pair0)] = meta0
    except Exception:
        open_pairs_all = {}

    aster_pruned_open_positions = 0
    try:
        op_strategy = _tracker_open_positions_get("strategy")
        op_carry = _tracker_open_positions_get("carry")
        op_quant = _tracker_open_positions_get("quant")
        op_three_screen = _tracker_open_positions_get("three_screen")

        def _aster_sync_infer_system(pair0: Any, cur0: Any) -> Optional[str]:
            if not isinstance(cur0, dict):
                return None
            try:
                v0 = str(cur0.get("venue") or "").lower().strip()
            except Exception:
                v0 = ""
            if v0 and v0 != "aster":
                return None
            try:
                gid = str(cur0.get("group_id") or "").strip().lower()
            except Exception:
                gid = ""
            try:
                ver = str(cur0.get("strategy_version") or "").strip().lower()
            except Exception:
                ver = ""
            try:
                sid = str(cur0.get("strategy_id") or "").strip().lower()
            except Exception:
                sid = ""
            if sid:
                sys0 = _system_from_strategy_id(sid)
                if sys0 in ("quant", "carry", "three_screen"):
                    return str(sys0)
            if gid != "aster_sync" and ver != "aster_sync":
                return None
            try:
                p = str(pair0 or cur0.get("pair") or "").strip().upper()
            except Exception:
                p = ""
            if not p:
                return None
            try:
                overrides = CONFIG.get("aster_sync_pair_system_overrides")
            except Exception:
                overrides = None
            if isinstance(overrides, dict):
                try:
                    ov = overrides.get(p) or overrides.get(p.upper()) or overrides.get(p.lower())
                except Exception:
                    ov = None
                if ov is not None:
                    s = str(ov).strip().lower()
                    if s in ("strategy", "quant", "carry", "three_screen"):
                        return s
            if p == "ZEC-PERP":
                return "quant"
            return None

        for pair, cur in list(op_strategy.items()):
            if not isinstance(cur, dict):
                continue
            sys0 = str(cur.get("system_id") or "").strip().lower()
            eo0 = str(cur.get("exit_owner") or "").strip().lower()
            if sys0 == "carry" or eo0 == "carry_trade":
                try:
                    del op_strategy[pair]
                except Exception:
                    pass
                cur["system_id"] = "carry"
                cur["exit_owner"] = "carry_trade"
                op_carry[str(pair)] = cur
            elif sys0 == "quant":
                try:
                    del op_strategy[pair]
                except Exception:
                    pass
                cur["system_id"] = "quant"
                op_quant[str(pair)] = cur
            elif sys0 == "three_screen":
                try:
                    del op_strategy[pair]
                except Exception:
                    pass
                cur["system_id"] = "three_screen"
                op_three_screen[str(pair)] = cur
            else:
                if str(pair) in open_pairs_by_owner.get("carry", {}):
                    try:
                        del op_strategy[pair]
                    except Exception:
                        pass
                    cur["system_id"] = "carry"
                    cur["exit_owner"] = "carry_trade"
                    op_carry[str(pair)] = cur
                    continue
                if str(pair) in open_pairs_by_owner.get("quant", {}):
                    try:
                        del op_strategy[pair]
                    except Exception:
                        pass
                    cur["system_id"] = "quant"
                    op_quant[str(pair)] = cur
                    continue
                if str(pair) in open_pairs_by_owner.get("three_screen", {}):
                    try:
                        del op_strategy[pair]
                    except Exception:
                        pass
                    cur["system_id"] = "three_screen"
                    op_three_screen[str(pair)] = cur
                    continue
                sys_inf = _aster_sync_infer_system(pair, cur)
                if sys_inf == "carry":
                    try:
                        del op_strategy[pair]
                    except Exception:
                        pass
                    cur["system_id"] = "carry"
                    cur["exit_owner"] = "carry_trade"
                    op_carry[str(pair)] = cur
                elif sys_inf == "quant":
                    try:
                        del op_strategy[pair]
                    except Exception:
                        pass
                    cur["system_id"] = "quant"
                    op_quant[str(pair)] = cur
                elif sys_inf == "three_screen":
                    try:
                        del op_strategy[pair]
                    except Exception:
                        pass
                    cur["system_id"] = "three_screen"
                    op_three_screen[str(pair)] = cur

        aster_pairs = set(open_pairs_all.keys())
        aster_pairs_by_owner: Dict[str, set] = {}
        try:
            for sys_name0, mp0 in list(open_pairs_by_owner.items()):
                if not isinstance(mp0, dict):
                    continue
                aster_pairs_by_owner[str(sys_name0)] = set([str(k) for k in mp0.keys()])
        except Exception:
            aster_pairs_by_owner = {}

        def _infer_system_id_for_pair(pair: str) -> str:
            try:
                p0 = str(pair or "").strip().upper()
            except Exception:
                p0 = ""
            if p0:
                try:
                    overrides = CONFIG.get("aster_sync_pair_system_overrides")
                except Exception:
                    overrides = None
                if isinstance(overrides, dict):
                    try:
                        ov = overrides.get(p0) or overrides.get(p0.upper()) or overrides.get(p0.lower())
                    except Exception:
                        ov = None
                    if ov is not None:
                        s = str(ov).strip().lower()
                        if s in ("strategy", "quant", "carry", "three_screen"):
                            return s
                if p0 == "ZEC-PERP":
                    return "quant"
            best = None
            best_ts = -1
            for o in ORDERS.values():
                if not isinstance(o, dict):
                    continue
                try:
                    if str(o.get("exchange") or "").lower().strip() != "aster":
                        continue
                    if str(o.get("action") or "").lower().strip() != "open":
                        continue
                    if str(o.get("pair") or "").strip().upper() != str(pair or "").strip().upper():
                        continue
                    ts0 = int(o.get("ts") or 0)
                    if ts0 > best_ts:
                        best_ts = ts0
                        best = o
                except Exception:
                    continue
            if isinstance(best, dict):
                return _system_from_strategy_id(best.get("system_id") or best.get("strategy_id"))
            return "strategy"

        stores = [("strategy", op_strategy), ("carry", op_carry), ("quant", op_quant), ("three_screen", op_three_screen)]
        for sys_name, op in stores:
            for pair, cur in list(op.items()):
                if not isinstance(cur, dict):
                    continue
                v0 = str(cur.get("venue") or "").lower().strip()
                managed = (v0 == "aster") or (v0 in ("", "stub") and str(pair) in open_pairs_all)
                if not managed:
                    continue
                meta = open_pairs_by_owner.get(str(sys_name), {}).get(str(pair))
                if not isinstance(meta, dict):
                    continue
                cur["pair"] = str(pair)
                cur["venue"] = "aster"
                if cur.get("system_id") is None:
                    cur["system_id"] = str(sys_name)
                try:
                    cur["last_sync_ts"] = int(meta.get("ts") or now_ms)
                except Exception:
                    pass
                try:
                    mode0 = str(cur.get("mode") or "").lower().strip()
                    sim0 = bool(cur.get("simulated", False)) or (mode0 in ("dry-run", "dryrun", "paper", "sim", "simulated"))
                except Exception:
                    sim0 = False
                try:
                    if not bool(CONFIG.get("dry_run", True)):
                        if bool(cur.get("simulated", False)):
                            cur["simulated"] = False
                        if str(cur.get("mode") or "").lower().strip() in ("dry-run", "dryrun"):
                            cur["mode"] = "real"
                except Exception:
                    pass
                try:
                    if (not bool(CONFIG.get("dry_run", True))) or (not bool(sim0)):
                        cur["side"] = meta.get("side")
                        cur["notional_usdc"] = float(_to_float(meta.get("notional_usdc", 0.0)))
                except Exception:
                    pass

                try:
                    if cur.get("leverage") is None and meta.get("leverage") is not None:
                        lv_i = int(meta.get("leverage") or 0)
                        cur["leverage"] = (None if int(lv_i) <= 0 else int(lv_i))
                except Exception:
                    pass
                try:
                    amt = float(_to_float(meta.get("aster_position_amt", 0.0)))
                    cur["base_qty"] = abs(float(amt))
                except Exception:
                    pass
                for k in ("aster_position_amt", "aster_unrealized_pnl_u", "aster_mid_px", "aster_entry_px", "aster_liquidation_px"):
                    try:
                        cur[k] = float(_to_float(meta.get(k, 0.0)))
                    except Exception:
                        pass

                try:
                    if cur.get("liq_px") is None:
                        cur["liq_px"] = float(_to_float(cur.get("aster_liquidation_px") or 0.0))
                    if cur.get("liquidation_px") is None:
                        cur["liquidation_px"] = float(_to_float(cur.get("aster_liquidation_px") or 0.0))
                    if cur.get("mark_price") is None:
                        cur["mark_price"] = float(_to_float(cur.get("aster_mid_px") or 0.0))
                except Exception:
                    pass
                try:
                    pos_value = float(_to_float(cur.get("notional_usdc", 0.0)))
                    unreal = float(_to_float(cur.get("aster_unrealized_pnl_u", 0.0)))
                    cur["unrealized_pnl_pct"] = float(unreal) / float(pos_value) if pos_value > 0 else 0.0
                except Exception:
                    pass
                try:
                    u = float(cur.get("aster_unrealized_pnl_u") or 0.0)
                    mx = cur.get("mfe_pnl_u")
                    mn = cur.get("mae_pnl_u")
                    cur["mfe_pnl_u"] = float(u) if mx is None else float(max(float(mx), float(u)))
                    cur["mae_pnl_u"] = float(u) if mn is None else float(min(float(mn), float(u)))
                except Exception:
                    pass
                try:
                    if str(sys_name) == "carry":
                        cur["exit_owner"] = "carry_trade"
                    else:
                        eo = cur.get("exit_owner")
                        eo_s = ("" if eo is None else str(eo)).strip()
                        if eo_s not in ("strategy", "exit_feeder"):
                            seed_extra = str(cur.get("order_id") or "")
                            try:
                                entry_ts = int(cur.get("entry_ts") or cur.get("ts") or now_ms)
                            except Exception:
                                entry_ts = int(now_ms)
                            cur["exit_owner"] = _exit_owner_choose(pair=str(pair), side=str(cur.get("side") or "long"), entry_ts=int(entry_ts), seed_extra=seed_extra)
                except Exception:
                    pass
                op[str(pair)] = cur

        def _has_aster_entry(op0: Any, pair0: str) -> bool:
            if not isinstance(op0, dict):
                return False
            cur0 = op0.get(pair0)
            if not isinstance(cur0, dict):
                return False
            v0 = str(cur0.get("venue") or "").lower().strip()
            if v0 == "aster":
                return True
            if v0 in ("", "stub") and str(pair0) in aster_pairs:
                return True
            return False

        op_three = TRACKER_STATE.get("three_screen_open_positions") or {}
        for sys_new, mp in list(open_pairs_by_owner.items()):
            if sys_new not in ("strategy", "quant", "carry", "three_screen"):
                continue
            if not isinstance(mp, dict):
                continue
            for pair, meta in list(mp.items()):
                if _has_aster_entry(op_strategy, pair) or _has_aster_entry(op_carry, pair) or _has_aster_entry(op_quant, pair) or _has_aster_entry(op_three, pair):
                    continue
                op_new = _tracker_open_positions_get(sys_new)
                try:
                    entry_ts = int(meta.get("ts") or now_ms)
                except Exception:
                    entry_ts = int(now_ms)
                side = str(meta.get("side") or "long")
                try:
                    notional_usdc = float(_to_float(meta.get("notional_usdc", 0.0)))
                except Exception:
                    notional_usdc = 0.0
                try:
                    base_qty = abs(float(_to_float(meta.get("aster_position_amt", 0.0))))
                except Exception:
                    base_qty = 0.0
                try:
                    exit_owner = "carry_trade" if str(sys_new) == "carry" else _exit_owner_choose(pair=str(pair), side=str(side), entry_ts=int(entry_ts), seed_extra="aster_sync")
                except Exception:
                    exit_owner = ("carry_trade" if str(sys_new) == "carry" else "strategy")
                op_new[pair] = {
                    "pair": str(pair),
                    "venue": "aster",
                    "ts": int(entry_ts),
                    "entry_ts": int(entry_ts),
                    "last_sync_ts": int(entry_ts),
                    "order_id": None,
                    "event_id": None,
                    "side": str(side),
                    "notional_usdc": float(notional_usdc),
                    "base_qty": float(base_qty),
                    "mode": ("dry-run" if bool(CONFIG.get("dry_run", True)) else "real"),
                    "simulated": bool(CONFIG.get("dry_run", True)),
                    "strategy_id": None,
                    "strategy_version": "aster_sync",
                    "group_id": "aster_sync",
                    "feature_set_id": "",
                    "exit_owner": str(exit_owner),
                    "system_id": str(sys_new),
                    "leverage": (None if meta.get("leverage") is None else int(meta.get("leverage") or 0)),
                    "aster_position_amt": float(_to_float(meta.get("aster_position_amt", 0.0))),
                    "aster_unrealized_pnl_u": float(_to_float(meta.get("aster_unrealized_pnl_u", 0.0))),
                    "aster_mid_px": float(_to_float(meta.get("aster_mid_px", 0.0))),
                    "aster_entry_px": float(_to_float(meta.get("aster_entry_px", 0.0))),
                    "aster_liquidation_px": float(_to_float(meta.get("aster_liquidation_px", 0.0))),
                    "mark_price": float(_to_float(meta.get("aster_mid_px", 0.0))),
                    "liq_px": float(_to_float(meta.get("aster_liquidation_px", 0.0))),
                    "liquidation_px": float(_to_float(meta.get("aster_liquidation_px", 0.0))),
                    "unrealized_pnl_pct": (float(_to_float(meta.get("aster_unrealized_pnl_u", 0.0))) / float(notional_usdc) if float(notional_usdc) > 0 else 0.0),
                }

        for sys_name, op in stores:
            sys_pairs = aster_pairs_by_owner.get(str(sys_name), set())
            for pair in list(op.keys()):
                try:
                    cur = op.get(pair)
                    if not isinstance(cur, dict):
                        continue
                    v0 = str(cur.get("venue") or "").lower().strip()
                    managed = (v0 == "aster") or (v0 in ("", "stub") and str(pair) in aster_pairs)
                    if not managed:
                        continue
                except Exception:
                    continue
                if pair not in sys_pairs:
                    try:
                        mode0 = str((op.get(pair) or {}).get("mode") or "").lower().strip()
                        sim0 = bool((op.get(pair) or {}).get("simulated", False)) or (mode0 in ("dry-run", "dryrun", "paper", "sim", "simulated"))
                        if sim0:
                            continue
                    except Exception:
                        pass
                    try:
                        try:
                            _tracker_set_post_close_cooldown(raw_pair=str(pair), coin=str(_hl_coin_from_pair(str(pair)) or ""), ts=int(now_ms), system_id=str(sys_name))
                        except Exception:
                            pass
                        del op[pair]
                        aster_pruned_open_positions += 1
                    except Exception:
                        pass
    except Exception:
        pass

    aster_state = TRACKER_STATE.get("aster")
    if not isinstance(aster_state, dict):
        aster_state = {}
        TRACKER_STATE["aster"] = aster_state
    aster_state["ts"] = int(now_ms)
    open_positions_total = 0
    try:
        open_positions_total = int(sum([len(mp or {}) for mp in list(open_pairs_by_owner.values()) if isinstance(mp, dict)]))
    except Exception:
        open_positions_total = 0
    aster_state["open_position_count"] = int(open_positions_total)
    aster_state["pruned_open_positions"] = int(aster_pruned_open_positions)
    aster_state["positions_fetch_error"] = fetch_err

    updated_orders = 0
    if update_orders:
        open_oids: set = set()
        try:
            for oo in list(open_orders or []):
                if not isinstance(oo, dict):
                    continue
                oid = oo.get("orderId")
                if oid is None:
                    oid = oo.get("id")
                if oid is None:
                    continue
                open_oids.add(str(oid))
        except Exception:
            open_oids = set()

        pos_by_coin_by_owner: Dict[str, Dict[str, Dict[str, Any]]] = {"strategy": {}, "quant": {}, "carry": {}, "three_screen": {}}
        try:
            for owner_key, by_pair in list(positions_by_owner.items()):
                if owner_key not in ("strategy", "quant", "carry", "three_screen"):
                    continue
                if not isinstance(by_pair, dict):
                    continue
                for p in list(by_pair.values()):
                    if not isinstance(p, dict):
                        continue
                    c = str(p.get("coin") or "").upper().strip()
                    if not c:
                        continue
                    pos_by_coin_by_owner[owner_key][c] = p
        except Exception:
            pos_by_coin_by_owner = {"strategy": {}, "quant": {}, "carry": {}, "three_screen": {}}

        for o in list(ORDERS.values()):
            try:
                if not isinstance(o, dict):
                    continue
                if str(o.get("exchange") or "").lower().strip() != "aster":
                    continue
                if str(o.get("status") or "").lower().strip() != "submitted":
                    continue
                prev_status = str(o.get("status") or "").strip().lower()
                oid = o.get("exchange_oid")
                if oid is None:
                    continue
                if str(oid) in open_oids:
                    continue

                age_ms = int(now_ms) - int(o.get("ts") or 0)
                if age_ms < 30_000:
                    continue

                pair = str(o.get("pair") or "")
                coin = _hl_coin_from_pair(pair)
                tag = str(o.get("tag") or "").lower().strip()
                is_close = ("close" in tag) or ("reduce" in tag)
                owner_key = _ab_norm_owner(o.get("ab_owner") or o.get("system_id") or "strategy")
                if owner_key not in ("strategy", "quant", "carry", "three_screen"):
                    owner_key = "strategy"
                has_pos = bool(coin and str(coin).upper().strip() in pos_by_coin_by_owner.get(owner_key, {}))

                oq_status = None
                oq_short = None
                oq_err = None
                try:
                    sym0 = None
                    try:
                        sym0 = (o.get("exec") or {}).get("resp", {}).get("symbol") if isinstance(o.get("exec"), dict) else None
                    except Exception:
                        sym0 = None
                    if sym0 is None:
                        try:
                            sym0 = _aster_symbol_from_coin(str(coin))
                        except Exception:
                            sym0 = None
                    sym0 = (None if sym0 is None else str(sym0).strip().upper() or None)
                    if sym0 and oid is not None:
                        oq = _aster_order_query(symbol=str(sym0), order_id=oid, owner=owner_key)
                        if isinstance(oq, dict) and oq:
                            try:
                                oq_status = str(oq.get("status") or "").upper().strip() or None
                            except Exception:
                                oq_status = None
                            oq_short = {
                                "status": oq_status,
                                "executedQty": (oq.get("executedQty") if isinstance(oq, dict) else None),
                                "avgPrice": (oq.get("avgPrice") if isinstance(oq, dict) else None),
                                "updateTime": (oq.get("updateTime") if isinstance(oq, dict) else None),
                            }
                except Exception as e:
                    oq_err = str(e)
                    oq_status = None
                    oq_short = None

                if oq_status in ("FILLED", "CANCELED", "CANCELLED", "REJECTED", "EXPIRED"):
                    if oq_status == "FILLED":
                        o["status"] = "filled"
                    elif oq_status in ("CANCELED", "CANCELLED"):
                        o["status"] = "canceled"
                    else:
                        o["status"] = "failed"
                    o["sync"] = {
                        "ts": int(now_ms),
                        "method": "order_query",
                        "open_orders_error": open_orders_err,
                        "order_status": oq_short,
                        "order_query_error": oq_err,
                    }
                    updated_orders += 1
                    try:
                        _archive_order(o)
                    except Exception:
                        pass
                    try:
                        if is_close and str(o.get("status") or "").lower().strip() == "filled":
                            pair0 = str(o.get("pair") or "")
                            if pair0:
                                pos0 = o.get("pos_snapshot")
                                if not isinstance(pos0, dict):
                                    pos0 = {}
                                _tracker_auto_exit_settle(
                                    pair=pair0,
                                    pos=pos0,
                                    order_id=str(o.get("id") or ""),
                                    exit_reason=str(o.get("tag") or "aster_sync_close_filled"),
                                    exit_tag=str(o.get("tag") or "aster_sync_close_filled"),
                                )
                    except Exception:
                        pass
                    continue
                elif oq_status in ("NEW", "PARTIALLY_FILLED"):
                    continue

                if is_close:
                    if has_pos:
                        continue
                    o["status"] = "filled"
                    o["sync"] = {"ts": int(now_ms), "method": "open_orders_absent_close_no_position", "open_orders_error": open_orders_err}
                    updated_orders += 1
                    if prev_status != "filled":
                        try:
                            tid0 = str(o.get("base_event_id") or o.get("event_id") or "").strip()
                        except Exception:
                            tid0 = ""
                        if tid0:
                            try:
                                _emit_order_submit_events(o, str(tid0))
                            except Exception:
                                pass
                    try:
                        _archive_order(o)
                    except Exception:
                        pass
                    try:
                        pair0 = str(o.get("pair") or "")
                        if pair0:
                            pos0 = o.get("pos_snapshot")
                            if not isinstance(pos0, dict):
                                pos0 = {}
                            _tracker_auto_exit_settle(
                                pair=pair0,
                                pos=pos0,
                                order_id=str(o.get("id") or ""),
                                exit_reason=str(o.get("tag") or "aster_sync_close_filled"),
                                exit_tag=str(o.get("tag") or "aster_sync_close_filled"),
                            )
                    except Exception:
                        pass
                    continue

                if has_pos and age_ms >= 120_000:
                    o["status"] = "filled"
                    o["sync"] = {"ts": int(now_ms), "method": "open_orders_absent_open_has_position", "open_orders_error": open_orders_err}
                    updated_orders += 1
                    if prev_status != "filled":
                        try:
                            tid0 = str(o.get("base_event_id") or o.get("event_id") or "").strip()
                        except Exception:
                            tid0 = ""
                        if tid0:
                            try:
                                _emit_order_submit_events(o, str(tid0))
                            except Exception:
                                pass
                    try:
                        _archive_order(o)
                    except Exception:
                        pass
                    continue

                if age_ms >= 10 * 60_000:
                    o["status"] = "failed"
                    o["sync"] = {"ts": int(now_ms), "method": "open_orders_absent_open_no_position", "open_orders_error": open_orders_err}
                    updated_orders += 1
                    try:
                        _archive_order(o)
                    except Exception:
                        pass
            except Exception:
                continue

    return {
        "ok": bool(fetch_err is None),
        "ts": int(now_ms),
        "open_orders": int(len(open_orders or [])),
        "open_positions": int(open_positions_total),
        "pruned_open_positions": int(aster_pruned_open_positions),
        "orders_updated": int(updated_orders),
        "open_orders_error": open_orders_err,
        "error": fetch_err,
    }


def _aster_sync_record(update_orders: bool = True) -> Dict[str, Any]:
    now_ms = _now_ms()
    st = TRACKER_STATE.get("aster")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["aster"] = st
    try:
        out = _aster_sync(update_orders=update_orders)
        st["sync_ok"] = bool(out.get("ok", False))
        st["last_sync_ts"] = int(out.get("ts") or now_ms)
        st["last_sync_error"] = out.get("error")
        try:
            hist = st.get("sync_history")
            if not isinstance(hist, list):
                hist = []
                st["sync_history"] = hist
            hist.append({"ts": int(out.get("ts") or now_ms), "ok": bool(out.get("ok", False)), "error": out.get("error")})
            if len(hist) > 220:
                st["sync_history"] = hist[-200:]
        except Exception:
            pass
        return out
    except Exception as e:
        st["sync_ok"] = False
        st["ts"] = int(now_ms)
        st["last_sync_ts"] = int(now_ms)
        st["last_sync_error"] = str(e)
        try:
            hist = st.get("sync_history")
            if not isinstance(hist, list):
                hist = []
                st["sync_history"] = hist
            hist.append({"ts": int(now_ms), "ok": False, "error": str(e)})
            if len(hist) > 220:
                st["sync_history"] = hist[-200:]
        except Exception:
            pass
        return {"ok": False, "ts": int(now_ms), "error": str(e)}


def _hl_info() -> Any:
    if Info is None:
        raise RuntimeError("hyperliquid_sdk_unavailable")
    base_url = _hl_base_url()
    if HL_STATE.get("info") is None or HL_STATE.get("base_url") != base_url:
        HL_STATE["info"] = Info(base_url, skip_ws=True)
        HL_STATE["exchange"] = None
        HL_STATE["base_url"] = base_url
    return HL_STATE["info"]


def _hl_clients(owner: Any = None) -> Tuple[Any, Any, str]:
    if Info is None or Exchange is None or Account is None:
        raise RuntimeError("hyperliquid_sdk_unavailable")

    base_url = _hl_base_url()
    owner_n = None
    try:
        owner_n = (_ab_norm_owner(owner) if owner is not None else None)
    except Exception:
        owner_n = None

    account_address = _hl_account_address(owner_n)
    if not account_address:
        raise RuntimeError("missing_HYPERLIQUID_ACCOUNT_ADDRESS")

    vault_address = _hl_vault_address(owner_n)
    if vault_address and (not str(vault_address).startswith("0x") or len(str(vault_address)) != 42):
        raise RuntimeError("invalid_HYPERLIQUID_VAULT_ADDRESS")

    pk = _hl_env_get_for_owner("HYPERLIQUID_API_PRIVATE_KEY", owner_n)
    if not pk:
        raise RuntimeError("missing_HYPERLIQUID_API_PRIVATE_KEY")

    try:
        pk_fp = hashlib.sha256(pk.encode("utf-8")).hexdigest()[:16]
    except Exception:
        pk_fp = None

    info = _hl_info()

    clients = HL_STATE.get("clients_by_owner")
    if not isinstance(clients, dict):
        clients = {}
        HL_STATE["clients_by_owner"] = clients
    key = (str(owner_n) if owner_n in ("strategy", "quant", "carry", "three_screen") else "default")
    ent = clients.get(key)
    if not isinstance(ent, dict):
        ent = {"exchange": None, "account": None, "vault": None, "pk_fp": None}
        clients[key] = ent

    try:
        if ent.get("base_url") != base_url:
            ent["exchange"] = None
            ent["base_url"] = str(base_url)
    except Exception:
        pass

    if (pk_fp is not None) and (ent.get("pk_fp") != pk_fp):
        ent["exchange"] = None
        ent["account"] = None
        ent["vault"] = None
        try:
            ent["pk_fp"] = str(pk_fp)
        except Exception:
            pass

    if ent.get("exchange") is None or ent.get("account") != account_address or ent.get("vault") != vault_address:
        wallet = Account.from_key(pk)
        ent["exchange"] = Exchange(wallet, base_url=base_url, vault_address=vault_address, account_address=account_address)
        ent["account"] = account_address
        ent["vault"] = vault_address
        if pk_fp is not None:
            try:
                ent["pk_fp"] = str(pk_fp)
            except Exception:
                pass

    return info, ent["exchange"], account_address


def _get_coin_stats_7d(coin: str) -> Dict[str, float]:
    # Try to calculate 7d turnover/spread/gap/jump from cached 5m data
    try:
        pair = f"{coin}/USDT"
        c: Dict[str, Any] = {}
        for pa in _universe_pair_aliases(pair):
            cc = _get_pair_cache(pa)
            if isinstance(cc, dict) and (cc.get("hourly_ts") or cc.get("hourly")):
                c = cc
                break
        if not c:
            p = _find_pair_file(pair)
            if not p:
                raise RuntimeError("no_local_pair_file")
            for pa in _universe_pair_aliases(pair):
                cc = _get_pair_cache(pa)
                if isinstance(cc, dict) and (cc.get("hourly_ts") or cc.get("hourly")):
                    c = cc
                    break

        hourly = (c.get("hourly") or []) if isinstance(c, dict) else []
        hourly_ts = (c.get("hourly_ts") or []) if isinstance(c, dict) else []
        
        if not hourly_ts:
             return {"median_turnover": 0.0, "median_spread_bps": 0.0, "gap_rate": 1.0, "jump_rate": 0.0, "age_days": 0}

        # Age
        now_ts = _now_ms()
        first_ts = hourly_ts[0]
        age_days = (now_ts - first_ts) / (86400 * 1000)

        # Last 7 days ~ 168 hours
        target_hours = 168
        recent_idx = max(0, len(hourly) - target_hours)
        recent = hourly[recent_idx:]
        recent_ts = hourly_ts[recent_idx:]
        
        if not recent:
             return {"median_turnover": 0.0, "median_spread_bps": 0.0, "gap_rate": 1.0, "jump_rate": 0.0, "age_days": age_days}

        # Gap rate: expected count vs actual count
        start_ts = recent_ts[0]
        end_ts = recent_ts[-1]
        expected_count = max(1, (end_ts - start_ts) // (3600 * 1000))
        actual_count = len(recent)
        gap_rate = max(0.0, 1.0 - (actual_count / float(expected_count))) if expected_count > 0 else 0.0
        
        turnovers = []
        jumps = 0
        closes = []
        
        for r in recent:
            # r: [ts, open, high, low, close, volume]
            op = float(r[1])
            hi = float(r[2])
            lo = float(r[3])
            cl = float(r[4])
            vol = float(r[5])
            
            turnovers.append(cl * vol)
            closes.append(cl)
            
            # Jump rate: log return > threshold (e.g. 5%) or high/low wick check
            # Simple jump: abs(log(close/open)) > 0.05
            if op > 0 and cl > 0:
                ret = abs(math.log(cl / op))
                if ret > 0.05: # 5% hourly move considered jump/spike
                    jumps += 1
            elif op <= 0 or cl <= 0:
                jumps += 1 # invalid price is a jump issue

        median_turnover = sorted(turnovers)[len(turnovers)//2] if turnovers else 0.0
        jump_rate = float(jumps) / float(len(recent)) if recent else 0.0
        
        # Funding rate check (placeholder until historical funding available)
        # Using a proxy or returning 0.0

        try:
            if (not math.isfinite(float(age_days))) or float(age_days) <= 0.0:
                raise RuntimeError("invalid_age_days")
            if float(age_days) < 30.0 or float(median_turnover) <= 0.0:
                ctx = _hl_meta_and_asset_ctxs_cached(int(_now_ms())).get(str(coin).upper().strip())
                if isinstance(ctx, dict):
                    day_ntl = ctx.get("dayNtlVlm")
                    try:
                        day_ntl_f = float(day_ntl) if day_ntl is not None else 0.0
                    except Exception:
                        day_ntl_f = 0.0
                    if math.isfinite(float(day_ntl_f)) and float(day_ntl_f) > 0.0:
                        hourly_turnover = float(day_ntl_f) / 24.0
                        median_turnover = float(max(float(median_turnover), float(hourly_turnover)))
                        if float(age_days) < 30.0:
                            age_days = 365.0
        except Exception:
            pass

        return {
            "median_turnover": float(median_turnover),
            "median_spread_bps": 0.0,
            "gap_rate": float(gap_rate),
            "jump_rate": float(jump_rate),
            "age_days": float(age_days),
        }
    except Exception:
        try:
            now_ms = _now_ms()
            ctx = _hl_meta_and_asset_ctxs_cached(int(now_ms)).get(str(coin).upper().strip())
            if isinstance(ctx, dict):
                day_ntl = ctx.get("dayNtlVlm")
                try:
                    day_ntl_f = float(day_ntl) if day_ntl is not None else 0.0
                except Exception:
                    day_ntl_f = 0.0
                if math.isfinite(float(day_ntl_f)) and float(day_ntl_f) > 0.0:
                    hourly_turnover = float(day_ntl_f) / 24.0
                    return {
                        "median_turnover": float(hourly_turnover),
                        "median_spread_bps": 0.0,
                        "gap_rate": 0.0,
                        "jump_rate": 0.0,
                        "age_days": 365.0,
                    }
        except Exception:
            pass

        try:
            now_ms = _now_ms()
            sym = _aster_symbol_from_coin(str(coin).upper().strip())
            tickers = _aster_24hr_tickers_all(int(now_ms))
            t0 = None
            for it in list(tickers):
                if not isinstance(it, dict):
                    continue
                if str(it.get("symbol") or "").upper().strip() == sym:
                    t0 = it
                    break
            if isinstance(t0, dict):
                qv = t0.get("quoteVolume", t0.get("quoteVol", t0.get("quote_volume")))
                try:
                    qv_f = float(qv) if qv is not None else 0.0
                except Exception:
                    qv_f = 0.0
                if math.isfinite(float(qv_f)) and float(qv_f) > 0.0:
                    hourly_turnover = float(qv_f) / 24.0
                    return {
                        "median_turnover": float(hourly_turnover),
                        "median_spread_bps": 0.0,
                        "gap_rate": 0.0,
                        "jump_rate": 0.0,
                        "age_days": 365.0,
                    }
        except Exception:
            pass
        return {"median_turnover": 0.0, "median_spread_bps": 0.0, "gap_rate": 1.0, "jump_rate": 0.0, "age_days": 0}

def _build_universe_stage_a(info: Any) -> Dict[str, Any]:
    # Stage A: Hard Filters
    # 1. Venue Fit (Hyperliquid)
    # 2. Liquidity & Microstructure
    # 3. Data Integrity
    # 4. Carry Risk (Funding)
    
    meta = info.meta()
    universe = meta.get("universe", [])
    mids = info.all_mids() or {}
    
    symbols_total = 0
    mids_total = 0
    try:
        symbols_total = len(universe) if isinstance(universe, list) else 0
    except Exception:
        symbols_total = 0

    try:
        scan_max = int(CONFIG.get("universe_stage_a_scan_max_coins", 400) or 400)
    except Exception:
        scan_max = 400
    scan_max = max(0, min(5000, int(scan_max)))
    if scan_max > 0 and isinstance(universe, list) and len(universe) > scan_max:
        prev_core = set()
        try:
            prev_core = {str(x or "").strip().upper() for x in (UNIVERSE_STATE.get("core") or [])}
        except Exception:
            prev_core = set()

        def _score_path(p: Path) -> int:
            s = 0
            ps = str(p).lower()
            if ps.endswith("-5m-futures.json"):
                s += 90
            elif ps.endswith("-5m.json"):
                s += 80
            elif ps.endswith("-1h-futures.json"):
                s += 60
            elif ps.endswith("-1h.json"):
                s += 50
            elif ps.endswith("-1d-futures.json"):
                s += 30
            elif ps.endswith("-1d.json"):
                s += 20
            if "/hyperliquid/" in ps or "\\hyperliquid\\" in ps:
                s += 18
            if "/gateio/" in ps or "\\gateio\\" in ps:
                s += 5
            if "/gate/" in ps or "\\gate\\" in ps:
                s += 2
            if "/binance/" in ps or "\\binance\\" in ps:
                s += 1
            return int(s)

        ranked = []
        for coin_meta in universe:
            if not isinstance(coin_meta, dict):
                continue
            name = str(coin_meta.get("name") or "").strip().upper()
            if not name:
                continue
            files = []
            try:
                files = _find_pair_files(f"{name}/USDT:USDT")
            except Exception:
                files = []
            best_score = 0
            best_mtime = 0.0
            for p in files:
                try:
                    sc = int(_score_path(p))
                except Exception:
                    sc = 0
                if sc <= 0:
                    continue
                try:
                    mt = float(p.stat().st_mtime)
                except Exception:
                    mt = 0.0
                if sc > best_score or (sc == best_score and mt > best_mtime):
                    best_score = int(sc)
                    best_mtime = float(mt)
            core_boost = 1 if name in prev_core else 0
            ranked.append((core_boost, best_score, best_mtime, coin_meta))
        ranked.sort(key=lambda x: (x[0], x[1], x[2]), reverse=True)
        universe = [x[3] for x in ranked[:scan_max]]
    
    min_turnover0 = float(CONFIG.get("filter_min_turnover_7d", 50000.0))
    max_gap0 = float(CONFIG.get("filter_max_gap_rate", 0.02))
    min_age_shadow0 = float(CONFIG.get("filter_min_age_days_shadow", 30))
    relax_enabled = bool(CONFIG.get("universe_stage_a_relax_enabled", True))
    try:
        relax_steps = int(CONFIG.get("universe_stage_a_relax_max_steps", 3) or 3)
    except Exception:
        relax_steps = 3
    relax_steps = max(0, min(10, int(relax_steps)))
    try:
        min_age_floor = float(CONFIG.get("universe_stage_a_relax_min_age_floor_days", 7) or 7)
    except Exception:
        min_age_floor = 7.0
    if (not math.isfinite(float(min_age_floor))) or float(min_age_floor) < 0.0:
        min_age_floor = 0.0
    try:
        turnover_floor = float(CONFIG.get("universe_stage_a_relax_min_turnover_floor", 5000.0) or 5000.0)
    except Exception:
        turnover_floor = 5000.0
    if (not math.isfinite(float(turnover_floor))) or float(turnover_floor) < 0.0:
        turnover_floor = 0.0
    try:
        gap_ceiling = float(CONFIG.get("universe_stage_a_relax_max_gap_ceiling", 0.20) or 0.20)
    except Exception:
        gap_ceiling = 0.20
    if (not math.isfinite(float(gap_ceiling))) or float(gap_ceiling) <= 0.0:
        gap_ceiling = 0.20
    gap_ceiling = float(_clip(float(gap_ceiling), 0.001, 0.99))
    try:
        target_min = int(CONFIG.get("universe_stage_a_target_min_candidates", 0) or 0)
    except Exception:
        target_min = 0
    if target_min <= 0:
        try:
            target_min = int(CONFIG.get("universe_core_size", 30) or 30)
        except Exception:
            target_min = 30
        try:
            min_keep = int(CONFIG.get("universe_min_stage_a_candidates", 25) or 25)
        except Exception:
            min_keep = 25
        target_min = max(int(min_keep), int(target_min))

    rows = []
    if isinstance(universe, list):
        for coin_meta in universe:
            if not isinstance(coin_meta, dict):
                continue
            name = str(coin_meta.get("name") or "").strip().upper()
            if not name:
                continue
            try:
                px = float(mids.get(name, 0.0))
            except Exception:
                px = 0.0
            if px > 0:
                mids_total += 1
            stats = _get_coin_stats_7d(name)
            turnover = float((stats or {}).get("median_turnover", 0.0) or 0.0)
            gap = float((stats or {}).get("gap_rate", 1.0) or 1.0)
            jump = float((stats or {}).get("jump_rate", 0.0) or 0.0)
            age = float((stats or {}).get("age_days", 0.0) or 0.0)
            rows.append(
                {
                    "coin": name,
                    "px": float(px),
                    "turnover": float(turnover),
                    "gap": float(gap),
                    "jump": float(jump),
                    "age": float(age),
                    "sz_decimals": coin_meta.get("szDecimals"),
                }
            )

    def _apply(min_turnover: float, max_gap: float, min_age_shadow: float) -> Tuple[List[str], Dict[str, List[str]]]:
        valid_coins: List[str] = []
        issues_map: Dict[str, List[str]] = {}
        for r in rows:
            name = str(r.get("coin") or "").strip().upper()
            if not name:
                continue
            try:
                px = float(r.get("px") or 0.0)
            except Exception:
                px = 0.0
            if px <= 0.0:
                issues_map[name] = ["no_price"]
                continue
            try:
                turnover = float(r.get("turnover") or 0.0)
            except Exception:
                turnover = 0.0
            try:
                gap = float(r.get("gap") or 1.0)
            except Exception:
                gap = 1.0
            try:
                jump = float(r.get("jump") or 0.0)
            except Exception:
                jump = 0.0
            try:
                age = float(r.get("age") or 0.0)
            except Exception:
                age = 0.0
            if turnover < float(min_turnover):
                issues_map[name] = [f"low_turnover_{int(turnover)}"]
                continue
            if gap > float(max_gap) and gap < 0.999:
                issues_map[name] = [f"high_gap_{round(gap,3)}"]
                continue
            if jump > 0.10 and jump < 0.999:
                issues_map[name] = [f"unstable_jumps_{round(jump,3)}"]
                continue
            if age > 0.0 and age < float(min_age_shadow):
                issues_map[name] = [f"too_young_{int(age)}"]
                continue
            valid_coins.append(name)
        return valid_coins, issues_map

    best_coins, best_issues = _apply(float(min_turnover0), float(max_gap0), float(min_age_shadow0))
    step_counts: Dict[str, Any] = {"0": int(len(best_coins))}
    best_filters = {"min_turnover": float(min_turnover0), "max_gap": float(max_gap0), "min_age_shadow": float(min_age_shadow0), "relax_step": 0, "step_counts": step_counts}
    if relax_enabled and len(best_coins) < int(target_min):
        for step in range(1, int(relax_steps) + 1):
            mult_turn = max(0.0, 0.5 ** float(step))
            min_turn = max(float(turnover_floor), float(min_turnover0) * float(mult_turn))
            max_gap = min(float(gap_ceiling), float(max_gap0) * float(2.0 ** float(step)))
            min_age = max(float(min_age_floor), float(min_age_shadow0) * float(mult_turn))
            coins_i, issues_i = _apply(float(min_turn), float(max_gap), float(min_age))
            step_counts[str(step)] = int(len(coins_i))
            if len(coins_i) > len(best_coins):
                best_coins, best_issues = coins_i, issues_i
                best_filters = {"min_turnover": float(min_turn), "max_gap": float(max_gap), "min_age_shadow": float(min_age), "relax_step": int(step), "step_counts": step_counts}
            if len(best_coins) >= int(target_min):
                break

    if not best_coins:
        fallback = []
        for c in ("BTC", "ETH", "SOL"):
            try:
                if float(mids.get(c, 0.0)) > 0:
                    fallback.append(c)
            except Exception:
                continue
        best_coins = fallback
    return {"candidates": best_coins, "issues": best_issues, "symbols_total": symbols_total, "mids_total": mids_total, "filters": best_filters}


def _simulate_signal_yield(pair: str, lookback_hours: int = 168) -> Dict[str, Any]:
    try:
        c = _get_pair_cache(pair)
        rows5 = c.get("raw5") or []
        if not isinstance(rows5, list) or len(rows5) < 60:
            return {}

        try:
            end_ts = int(rows5[-1][0])
        except Exception:
            end_ts = _now_ms()
        start_ts = int(end_ts) - int(lookback_hours) * 3600 * 1000

        try:
            fwd = int(CONFIG.get("universe_alpha_gate_forward_bars", 12) or 12)
        except Exception:
            fwd = 12
        fwd = max(1, min(240, int(fwd)))

        try:
            fee = float(CONFIG.get("universe_alpha_gate_fee_rate", 0.0) or 0.0)
        except Exception:
            fee = 0.0
        fee = max(0.0, min(0.01, float(fee)))

        recent: List[List[float]] = []
        for r in rows5:
            try:
                if int(r[0]) >= int(start_ts):
                    recent.append(r)
            except Exception:
                continue
        if len(recent) < (max(35, int(fwd) + 5)):
            return {}

        signals = 0
        trades = 0
        wins = 0
        pnl_sum = 0.0
        sum_pos = 0.0
        sum_neg = 0.0
        long_n = 0
        short_n = 0
        window_n = 60

        for i in range(len(recent) - int(fwd) - 1):
            if i < 30:
                continue
            w0 = max(0, int(i) - int(window_n) + 1)
            window = recent[w0 : int(i) + 1]

            sig_l = _carry_5m_signal_gate(window, carry_side="long")
            sig_s = _carry_5m_signal_gate(window, carry_side="short")

            long_ok = bool(sig_l.get("ok", False)) and str(sig_l.get("tag") or "") in ("rsi_deep", "rsi_mild")
            short_ok = bool(sig_s.get("ok", False)) and str(sig_s.get("tag") or "") in ("short_rsi_deep", "short_rsi_mild")

            if long_ok and short_ok:
                continue

            if not long_ok and not short_ok:
                continue

            signals += 1

            try:
                c0 = float(recent[i][4])
                c1 = float(recent[int(i) + int(fwd)][4])
            except Exception:
                continue
            if (not math.isfinite(float(c0))) or (not math.isfinite(float(c1))) or float(c0) <= 0.0:
                continue

            direction = 1.0 if long_ok else -1.0
            if long_ok:
                long_n += 1
            else:
                short_n += 1

            ret = float(direction) * ((float(c1) / float(c0)) - 1.0)
            ret = float(ret) - 2.0 * float(fee)

            trades += 1
            pnl_sum += float(ret)
            if float(ret) > 0.0:
                wins += 1
                sum_pos += float(ret)
            else:
                sum_neg += float(ret)

        win_rate = float(wins) / float(trades) if trades > 0 else 0.0
        avg_ret = float(pnl_sum) / float(trades) if trades > 0 else 0.0
        profit_factor = None
        if trades > 0:
            if float(sum_neg) < 0.0:
                profit_factor = float(sum_pos) / abs(float(sum_neg))
            elif float(sum_pos) > 0.0:
                profit_factor = float("inf")
            else:
                profit_factor = 0.0

        return {
            "signals_5m": int(signals),
            "count": int(trades),
            "shadow_win_rate": float(win_rate),
            "shadow_pnl": float(pnl_sum),
            "avg_ret": float(avg_ret),
            "profit_factor": (None if profit_factor is None else float(profit_factor)),
            "long_count": int(long_n),
            "short_count": int(short_n),
            "forward_bars": int(fwd),
            "fee_rate": float(fee),
        }
    except Exception:
        return {}


def _universe_beta_from_ret(x: "np.ndarray", y: "np.ndarray") -> Optional[float]:
    try:
        if x.size < 10 or y.size < 10:
            return None
        xv = float(np.var(x))
        if (not math.isfinite(float(xv))) or float(xv) <= 0.0:
            return None
        cov = float(np.mean((x - float(np.mean(x))) * (y - float(np.mean(y)))))
        b = cov / xv
        if not math.isfinite(float(b)):
            return None
        return float(b)
    except Exception:
        return None


def _universe_pair_aliases(pair: str) -> List[str]:
    p = str(pair or "").strip()
    if not p:
        return []
    p = p.replace(":USDT", "").replace(":USDC", "")
    out: List[str] = []
    if p not in out:
        out.append(p)
    try:
        coin0 = ""
        if "/" in p:
            coin0 = str(p.split("/", 1)[0] or "").strip()
        elif p.endswith("USDT") and len(p) > 4:
            coin0 = str(p[:-4] or "").strip()
        elif p.endswith("USDC") and len(p) > 4:
            coin0 = str(p[:-4] or "").strip()
        else:
            coin0 = str(p).strip()
    except Exception:
        coin0 = ""
    if coin0:
        for x in (
            coin0,
            f"{coin0}-PERP",
            f"{coin0}_PERP",
            f"{coin0}/USDT:USDT",
            f"{coin0}/USDT",
            f"{coin0}USDT",
            f"{coin0}_USDT",
            f"{coin0}_USDT_USDT",
        ):
            xs = str(x or "").strip()
            if xs and xs not in out:
                out.append(xs)
    if "/" in p:
        p2 = p.replace("/", "")
        if p2 not in out:
            out.append(p2)
    else:
        if p.endswith("USDT") and (not p.endswith("/USDT")):
            coin = p[:-4]
            p2 = f"{coin}/USDT"
            if p2 not in out:
                out.append(p2)
        if p.endswith("USDC") and (not p.endswith("/USDC")):
            coin = p[:-4]
            p2 = f"{coin}/USDC"
            if p2 not in out:
                out.append(p2)
    return out


def _universe_btc_exposure(pair: str, now_ms: int, window_bars: int) -> Dict[str, Any]:
    out: Dict[str, Any] = {"beta": None, "beta_std": None, "corr": None, "resid_vol": None, "last_ts": None, "age_ms": None, "valid": None}
    try:
        def _lr_series_from_rows(rows: Any) -> List[Tuple[int, float]]:
            if not isinstance(rows, list) or not rows:
                return []
            out_lr: List[Tuple[int, float]] = []
            prev = None
            prev_ts = None
            for r in rows:
                if not isinstance(r, (list, tuple)) or len(r) < 5:
                    continue
                try:
                    ts = int(r[0])
                    c = float(r[4])
                except Exception:
                    continue
                if (not math.isfinite(float(c))) or float(c) <= 0.0:
                    continue
                if prev is None:
                    prev = float(c)
                    prev_ts = int(ts)
                    continue
                try:
                    if float(prev) > 0.0:
                        v = float(math.log(float(c) / float(prev)))
                        if math.isfinite(float(v)):
                            out_lr.append((int(ts), float(v)))
                except Exception:
                    pass
                prev = float(c)
                prev_ts = int(ts)
            return out_lr

        def _lr_series_from_cache(c: Any) -> List[Tuple[int, float]]:
            if not isinstance(c, dict):
                return []
            rows = c.get("hourly") or []
            if isinstance(rows, list) and rows:
                try:
                    rows2 = sorted(rows, key=lambda x: int(x[0]) if isinstance(x, (list, tuple)) and len(x) > 0 else 0)
                except Exception:
                    rows2 = rows
                out_lr = _lr_series_from_rows(rows2)
                if out_lr:
                    return out_lr
            return []

        c_alt = {}
        for pa in _universe_pair_aliases(pair):
            c = _get_pair_cache(pa)
            if isinstance(c, dict) and (c.get("hourly_logret") or c.get("hourly")):
                c_alt = c
                break

        c_btc = {}
        for pb in _universe_pair_aliases("BTC/USDT"):
            c = _get_pair_cache(pb)
            if isinstance(c, dict) and (c.get("hourly_logret") or c.get("hourly")):
                c_btc = c
                break
        alt_s = _lr_series_from_cache(c_alt)
        btc_s = _lr_series_from_cache(c_btc)

        if (not alt_s) or (not btc_s):
            try:
                n = int(window_bars)
            except Exception:
                n = 240
            n = 240 if n <= 0 else int(n)
            lookback_ms = int(max(72 * 3600 * 1000, (n + 10) * 3600 * 1000))
            if not alt_s:
                try:
                    rows_alt = _hl_fetch_ohlcv_rows_cached(coin=pair, interval="1h", now_ms=int(now_ms), lookback_ms=int(lookback_ms))
                except Exception:
                    rows_alt = []
                alt_s = _lr_series_from_rows(rows_alt)
            if not btc_s:
                try:
                    rows_btc = _hl_fetch_ohlcv_rows_cached(coin="BTC", interval="1h", now_ms=int(now_ms), lookback_ms=int(lookback_ms))
                except Exception:
                    rows_btc = []
                btc_s = _lr_series_from_rows(rows_btc)

        if (not alt_s) or (not btc_s):
            return out

        btc_map: Dict[int, float] = {}
        for ts, lr in btc_s:
            btc_map[int(ts)] = float(lr)
        xs: List[float] = []
        ys: List[float] = []
        last_common_ts = 0
        for ts, lr in alt_s:
            v = btc_map.get(int(ts))
            if v is None:
                continue
            xs.append(float(v))
            ys.append(float(lr))
            last_common_ts = int(ts)

        if int(last_common_ts) > 0:
            try:
                out["last_ts"] = int(last_common_ts)
                out["age_ms"] = int(max(0, int(now_ms) - int(last_common_ts)))
            except Exception:
                out["last_ts"] = None
                out["age_ms"] = None
            ttl_data_sec = 0
            try:
                ttl_data_sec = int(CONFIG.get("strategy_btc_corr_ttl_sec", 0) or 0)
            except Exception:
                ttl_data_sec = 0
            if int(ttl_data_sec) <= 0:
                out["valid"] = True
            else:
                try:
                    out["valid"] = bool(int(out.get("age_ms") or 0) <= int(ttl_data_sec) * 1000)
                except Exception:
                    out["valid"] = None

        try:
            n = int(window_bars)
        except Exception:
            n = 240
        n = 240 if n <= 0 else int(n)
        if len(xs) < 30 or len(ys) < 30:
            return out
        x = np.asarray(xs[-n:], dtype=float)
        y = np.asarray(ys[-n:], dtype=float)

        mx = np.isfinite(x)
        my = np.isfinite(y)
        ok = mx & my
        x = x[ok]
        y = y[ok]
        if x.size < 30 or y.size < 30:
            return out

        corr = None
        try:
            cc = float(np.corrcoef(x, y)[0, 1])
            if math.isfinite(float(cc)):
                corr = float(cc)
        except Exception:
            corr = None

        corr_30d = None
        corr_60d = None
        corr_roll_std_30d = None
        corr_dual_ok = None
        try:
            try:
                w30 = int(CONFIG.get("strategy_btc_corr_dual_window_30d_bars_1h", 720) or 720)
            except Exception:
                w30 = 720
            try:
                w60 = int(CONFIG.get("strategy_btc_corr_dual_window_60d_bars_1h", 1440) or 1440)
            except Exception:
                w60 = 1440
            w30 = int(max(30, min(4000, int(w30))))
            w60 = int(max(w30, min(8000, int(w60))))
            if x.size >= w30 and y.size >= w30:
                cc30 = float(np.corrcoef(x[-w30:], y[-w30:])[0, 1])
                if math.isfinite(float(cc30)):
                    corr_30d = float(cc30)
            if x.size >= w60 and y.size >= w60:
                cc60 = float(np.corrcoef(x[-w60:], y[-w60:])[0, 1])
                if math.isfinite(float(cc60)):
                    corr_60d = float(cc60)
            try:
                rw = int(CONFIG.get("strategy_btc_corr_dual_window_roll_window_bars_1h", 168) or 168)
            except Exception:
                rw = 168
            try:
                rs = int(CONFIG.get("strategy_btc_corr_dual_window_roll_step_bars_1h", 24) or 24)
            except Exception:
                rs = 24
            rw = int(max(24, min(2000, int(rw))))
            rs = int(max(1, min(rw, int(rs))))
            if corr_30d is not None and x.size >= int(w30) and y.size >= int(w30) and int(w30) >= int(rw) * 3:
                corrs: List[float] = []
                i = int(w30) - int(rw)
                while i >= 0 and len(corrs) < 60:
                    seg_x = x[-int(w30) + int(i) : -int(w30) + int(i) + int(rw)]
                    seg_y = y[-int(w30) + int(i) : -int(w30) + int(i) + int(rw)]
                    if seg_x.size >= 24 and seg_y.size >= 24:
                        try:
                            cci = float(np.corrcoef(seg_x, seg_y)[0, 1])
                            if math.isfinite(float(cci)):
                                corrs.append(float(cci))
                        except Exception:
                            pass
                    i -= int(rs)
                if len(corrs) >= 6:
                    sdv = float(np.std(np.asarray(corrs, dtype=float), ddof=0))
                    if math.isfinite(float(sdv)):
                        corr_roll_std_30d = float(sdv)
            if corr_30d is not None and corr_60d is not None:
                try:
                    md = float(CONFIG.get("strategy_btc_corr_dual_window_max_abs_delta", 0.15) or 0.15)
                except Exception:
                    md = 0.15
                md = float(_clip(float(md), 0.0, 2.0))
                ok_delta = abs(float(corr_30d) - float(corr_60d)) <= float(md) + 1e-12
                try:
                    sd_max = float(CONFIG.get("strategy_btc_corr_dual_window_roll_std_max", 0.20) or 0.20)
                except Exception:
                    sd_max = 0.20
                sd_max = float(_clip(float(sd_max), 0.0, 5.0))
                ok_std = True if corr_roll_std_30d is None else (float(corr_roll_std_30d) <= float(sd_max) + 1e-12)
                corr_dual_ok = bool(ok_delta and ok_std)
        except Exception:
            corr_30d = None
            corr_60d = None
            corr_roll_std_30d = None
            corr_dual_ok = None

        beta = _universe_beta_from_ret(x, y)
        resid_vol = None
        if beta is not None:
            try:
                resid = y - float(beta) * x
                rv = float(np.std(resid, ddof=0))
                if math.isfinite(float(rv)):
                    resid_vol = float(rv)
            except Exception:
                resid_vol = None

        beta_std = None
        if beta is not None and x.size >= 120:
            try:
                seg = int(max(30, x.size // 5))
                betas: List[float] = []
                i = 0
                while i + seg <= x.size:
                    bx = x[i : i + seg]
                    by = y[i : i + seg]
                    b = _universe_beta_from_ret(bx, by)
                    if b is not None:
                        betas.append(float(b))
                    i += seg
                if len(betas) >= 2:
                    bs = float(np.std(np.asarray(betas, dtype=float), ddof=0))
                    if math.isfinite(float(bs)):
                        beta_std = float(bs)
            except Exception:
                beta_std = None

        out["beta"] = (None if beta is None else float(beta))
        out["beta_std"] = (None if beta_std is None else float(beta_std))
        out["corr"] = (None if corr is None else float(corr))
        out["corr_30d"] = (None if corr_30d is None else float(corr_30d))
        out["corr_60d"] = (None if corr_60d is None else float(corr_60d))
        out["corr_roll_std_30d"] = (None if corr_roll_std_30d is None else float(corr_roll_std_30d))
        out["corr_dual_ok"] = (None if corr_dual_ok is None else bool(corr_dual_ok))
        out["resid_vol"] = (None if resid_vol is None else float(resid_vol))
        return out
    except Exception:
        return out


def _universe_pearson_corr(xs: List[float], ys: List[float]) -> Optional[float]:
    pairs: List[Tuple[float, float]] = []
    for a, b in zip(xs, ys):
        try:
            fa = float(a)
            fb = float(b)
            if math.isfinite(fa) and math.isfinite(fb):
                pairs.append((fa, fb))
        except Exception:
            continue
    if len(pairs) < 10:
        return None
    mx = sum(p[0] for p in pairs) / float(len(pairs))
    my = sum(p[1] for p in pairs) / float(len(pairs))
    sxx = 0.0
    syy = 0.0
    sxy = 0.0
    for a, b in pairs:
        da = float(a) - float(mx)
        db = float(b) - float(my)
        sxx += da * da
        syy += db * db
        sxy += da * db
    if (not math.isfinite(sxx)) or (not math.isfinite(syy)) or (not math.isfinite(sxy)):
        return None
    if sxx <= 0.0 or syy <= 0.0:
        return None
    try:
        return float(sxy) / float(math.sqrt(float(sxx) * float(syy)))
    except Exception:
        return None


def _universe_rankdata(values: List[float]) -> List[float]:
    n = int(len(values))
    if n <= 0:
        return []
    order = list(range(n))
    order.sort(key=lambda i: values[i])
    ranks = [0.0] * n
    i = 0
    while i < n:
        j = i + 1
        v = values[order[i]]
        while j < n and values[order[j]] == v:
            j += 1
        avg = (float(i + 1) + float(j)) / 2.0
        for k in range(i, j):
            ranks[order[k]] = float(avg)
        i = j
    return ranks


def _universe_spearman_corr(xs: List[float], ys: List[float]) -> Optional[float]:
    pairs: List[Tuple[float, float]] = []
    for a, b in zip(xs, ys):
        try:
            fa = float(a)
            fb = float(b)
            if math.isfinite(fa) and math.isfinite(fb):
                pairs.append((fa, fb))
        except Exception:
            continue
    if len(pairs) < 10:
        return None
    ax = [p[0] for p in pairs]
    ay = [p[1] for p in pairs]
    rx = _universe_rankdata(ax)
    ry = _universe_rankdata(ay)
    return _universe_pearson_corr(rx, ry)


def _universe_tf_ms(timeframe: str) -> Optional[int]:
    tf = str(timeframe or "").strip().lower()
    if tf == "1h":
        return 3600 * 1000
    if tf == "30m":
        return 30 * 60 * 1000
    return None


def _universe_pair_close_by_ts(coin: str, now_ms: int, timeframe: str, lookback_ms: int) -> Dict[int, float]:
    out: Dict[int, float] = {}
    try:
        rows = _hl_fetch_ohlcv_rows_cached(coin=str(coin), interval=str(timeframe), now_ms=int(now_ms), lookback_ms=int(lookback_ms))
    except Exception:
        rows = []
    for r in rows or []:
        try:
            ts = int(r[0])
            close = float(r[4])
            if ts > 0 and math.isfinite(close) and close > 0.0:
                out[int(ts)] = float(close)
        except Exception:
            continue
    return out


def _universe_btc_corr_custom(pair: str, now_ms: int, timeframe: str, window_bars: int, method: str) -> Dict[str, Any]:
    out: Dict[str, Any] = {"beta": None, "beta_std": None, "corr": None, "resid_vol": None}
    tf_ms = _universe_tf_ms(timeframe)
    if tf_ms is None:
        return out
    n = int(max(10, min(2000, int(window_bars))))
    lookback_ms = int((n + 8) * int(tf_ms))
    a = _universe_pair_close_by_ts(str(pair), int(now_ms), str(timeframe), int(lookback_ms))
    b = _universe_pair_close_by_ts("BTC", int(now_ms), str(timeframe), int(lookback_ms))
    if not a or not b:
        return out
    ts = sorted(set(a.keys()) & set(b.keys()))
    if len(ts) < int(n + 2):
        return out
    ts = ts[-int(n + 2) :]
    ax: List[float] = []
    bx: List[float] = []
    for t0, t1 in zip(ts[:-1], ts[1:]):
        try:
            ca0 = float(a.get(int(t0)) or 0.0)
            ca1 = float(a.get(int(t1)) or 0.0)
            cb0 = float(b.get(int(t0)) or 0.0)
            cb1 = float(b.get(int(t1)) or 0.0)
            if ca0 > 0.0 and ca1 > 0.0 and cb0 > 0.0 and cb1 > 0.0:
                ax.append(float(math.log(ca1 / ca0)))
                bx.append(float(math.log(cb1 / cb0)))
        except Exception:
            continue
    corr = None
    mm = str(method or "").strip().lower()
    if mm == "spearman":
        corr = _universe_spearman_corr(ax, bx)
    else:
        corr = _universe_pearson_corr(ax, bx)
    if corr is not None:
        out["corr"] = float(corr)
    return out


def _universe_kmeans_assign(X: "np.ndarray", k: int, iters: int = 30) -> "np.ndarray":
    n = int(X.shape[0])
    if n <= 0:
        return np.zeros((0,), dtype=int)
    kk = int(min(max(1, int(k)), int(n)))
    if kk == 1:
        return np.zeros((n,), dtype=int)
    rng = np.random.RandomState(7)

    centers = np.zeros((kk, int(X.shape[1])), dtype=float)
    idx0 = int(rng.randint(0, n))
    centers[0] = X[idx0]
    d2 = np.sum((X - centers[0]) ** 2, axis=1)
    for j in range(1, kk):
        s = float(np.sum(d2))
        if (not math.isfinite(float(s))) or float(s) <= 0.0:
            centers[j] = X[int(rng.randint(0, n))]
            d2 = np.minimum(d2, np.sum((X - centers[j]) ** 2, axis=1))
            continue
        p = d2 / s
        try:
            idx = int(rng.choice(n, p=p))
        except Exception:
            idx = int(rng.randint(0, n))
        centers[j] = X[idx]
        d2 = np.minimum(d2, np.sum((X - centers[j]) ** 2, axis=1))

    labels = np.zeros((n,), dtype=int)
    for _ in range(int(max(1, iters))):
        dist = np.sum((X[:, None, :] - centers[None, :, :]) ** 2, axis=2)
        new_labels = np.argmin(dist, axis=1)
        if np.array_equal(new_labels, labels):
            break
        labels = new_labels
        for j in range(kk):
            m = labels == j
            if not bool(np.any(m)):
                centers[j] = X[int(rng.randint(0, n))]
                continue
            centers[j] = np.mean(X[m], axis=0)
    return labels


def _universe_ari_nmi(old_labels: List[int], new_labels: List[int]) -> Dict[str, Optional[float]]:
    out: Dict[str, Optional[float]] = {"ari": None, "nmi": None}
    try:
        if (not old_labels) or (not new_labels) or len(old_labels) != len(new_labels):
            return out
        n = int(len(old_labels))
        if n < 10:
            return out

        old_u = sorted(set(int(x) for x in old_labels))
        new_u = sorted(set(int(x) for x in new_labels))
        oi = {v: i for i, v in enumerate(old_u)}
        ni = {v: i for i, v in enumerate(new_u)}
        cont = np.zeros((len(old_u), len(new_u)), dtype=float)
        for a, b in zip(old_labels, new_labels):
            cont[oi[int(a)], ni[int(b)]] += 1.0

        def comb2(x: float) -> float:
            return float(x * (x - 1.0) * 0.5)

        sum_comb = float(np.sum([comb2(v) for v in cont.flatten()]))
        a = np.sum(cont, axis=1)
        b = np.sum(cont, axis=0)
        sum_comb_a = float(np.sum([comb2(v) for v in a]))
        sum_comb_b = float(np.sum([comb2(v) for v in b]))
        total = float(n)
        prod = (sum_comb_a * sum_comb_b) / comb2(total) if total > 1 else 0.0
        mean = 0.5 * (sum_comb_a + sum_comb_b)
        denom = mean - prod
        ari = None
        if math.isfinite(float(denom)) and float(denom) != 0.0:
            ari_v = (sum_comb - prod) / denom
            if math.isfinite(float(ari_v)):
                ari = float(ari_v)

        pxy = cont / total
        px = a / total
        py = b / total
        mi = 0.0
        for i in range(pxy.shape[0]):
            for j in range(pxy.shape[1]):
                v = float(pxy[i, j])
                if v <= 0.0:
                    continue
                den = float(px[i] * py[j])
                if den <= 0.0:
                    continue
                mi += v * float(math.log(v / den))
        hx = 0.0
        for v in px:
            vv = float(v)
            if vv > 0.0:
                hx -= vv * float(math.log(vv))
        hy = 0.0
        for v in py:
            vv = float(v)
            if vv > 0.0:
                hy -= vv * float(math.log(vv))
        nmi = None
        den = float(hx * hy)
        if den > 0.0 and math.isfinite(float(den)):
            nmi_v = mi / float(math.sqrt(den))
            if math.isfinite(float(nmi_v)):
                nmi = float(nmi_v)

        out["ari"] = ari
        out["nmi"] = nmi
        return out
    except Exception:
        return out


def _hl_info_shim_from_meta_ctx(now_ms: int) -> Any:
    try:
        resp = _hl_post_info({"type": "metaAndAssetCtxs"}, timeout_sec=float(CONFIG.get("hl_meta_ctx_timeout_sec", 10.0)))
    except Exception:
        return None
    if not isinstance(resp, list) or len(resp) < 2:
        return None
    meta = resp[0]
    ctxs = resp[1]
    if not isinstance(meta, dict) or not isinstance(ctxs, list):
        return None
    uni = meta.get("universe")
    if not isinstance(uni, list):
        return None

    mids: Dict[str, float] = {}
    n = min(len(uni), len(ctxs))
    for i in range(n):
        u = uni[i]
        c = ctxs[i]
        if not isinstance(u, dict) or not isinstance(c, dict):
            continue
        name = str(u.get("name") or "").strip().upper()
        if not name:
            continue
        try:
            mid = float(c.get("midPx") or 0.0)
            mid = mid if math.isfinite(float(mid)) else 0.0
        except Exception:
            mid = 0.0
        mids[name] = float(mid)

    class _InfoShim:
        def __init__(self, universe: List[Dict[str, Any]], mids_map: Dict[str, float]):
            self._meta = {"universe": universe}
            self._mids = mids_map

        def meta(self) -> Dict[str, Any]:
            return self._meta

        def all_mids(self) -> Dict[str, float]:
            return self._mids

    try:
        _ = int(now_ms)
    except Exception:
        pass
    return _InfoShim(uni, mids)

def _hl_coin_from_data_key(k: Any) -> str:
    try:
        s = str(k or "").strip().upper()
    except Exception:
        return ""
    if not s:
        return ""
    base = s.split("_", 1)[0].strip().upper()
    if base.endswith("USDT") and len(base) > 4:
        base = base[:-4]
    if base.endswith("USDC") and len(base) > 4:
        base = base[:-4]
    if not base or base in ("USDT", "USDC"):
        return ""
    return base

def _hl_info_shim_from_local_data(now_ms: int, max_coins: int = 800) -> Any:
    try:
        _build_data_index()
    except Exception:
        return None
    coins: List[str] = []
    try:
        for k, ps in (DATA_INDEX_ALL.items() if isinstance(DATA_INDEX_ALL, dict) else []):
            for p in (ps or []):
                sp = str(p).lower()
                if "hyperliquid" not in sp:
                    continue
                if not (sp.endswith("-5m-futures.json") or sp.endswith("-1h-futures.json") or sp.endswith("-1d-futures.json")):
                    continue
                c = _hl_coin_from_data_key(k)
                if c and c not in coins:
                    coins.append(c)
                    break
    except Exception:
        coins = []
    if not coins:
        return None
    try:
        max_coins_i = int(max_coins)
    except Exception:
        max_coins_i = 800
    max_coins_i = max(10, min(3000, int(max_coins_i)))
    coins = coins[:max_coins_i]
    uni = [{"name": c, "szDecimals": 0} for c in coins]
    mids = {c: 1.0 for c in coins}

    class _InfoShim:
        def __init__(self, universe: List[Dict[str, Any]], mids_map: Dict[str, float]):
            self._meta = {"universe": universe}
            self._mids = mids_map

        def meta(self) -> Dict[str, Any]:
            return self._meta

        def all_mids(self) -> Dict[str, float]:
            return self._mids

    try:
        _ = int(now_ms)
    except Exception:
        pass
    return _InfoShim(uni, mids)


def _build_universe_pipeline(now_ms: int) -> None:
    venue = str(CONFIG.get("universe_venue", "hyperliquid") or "hyperliquid").strip().lower() or "hyperliquid"
    is_aster = venue in ("aster", "aster_fapi", "aster-fapi")
    try:
        prev_meta = UNIVERSE_STATE.get("metadata")
        if not isinstance(prev_meta, dict):
            prev_meta = {}

        prev_candidates_set = set()
        for k in ("core", "shadow", "watchlist"):
            xs = UNIVERSE_STATE.get(k)
            if isinstance(xs, list):
                for x in xs:
                    s = str(x or "").strip().upper()
                    if s:
                        prev_candidates_set.add(s)
        prev_candidates = sorted(prev_candidates_set)

        if is_aster:
            top_n = 200
            try:
                top_n = int(CONFIG.get("universe_aster_top_n", 200) or 200)
            except Exception:
                top_n = 200
            top_n = max(30, min(800, int(top_n)))

            ex = _aster_exchange_info()
            syms = ex.get("symbols") if isinstance(ex, dict) else None
            allowed_sym_to_base = {}
            allowed_base_to_szdec = {}
            if isinstance(syms, list):
                for s in list(syms):
                    if not isinstance(s, dict):
                        continue
                    sym = str(s.get("symbol") or "").upper().strip()
                    if not sym:
                        continue
                    st = str(s.get("status") or "").upper().strip()
                    if st and st not in ("TRADING",):
                        continue
                    qa = str(s.get("quoteAsset") or "").upper().strip()
                    ct = str(s.get("contractType") or "").upper().strip()
                    if qa and qa != "USDT":
                        continue
                    if (not qa) and (not sym.endswith("USDT")):
                        continue
                    if ct and ct not in ("PERPETUAL",):
                        continue
                    ba = str(s.get("baseAsset") or "").upper().strip()
                    if not ba or ba in ("USDT", "USDC"):
                        continue
                    allowed_sym_to_base[sym] = ba

                    fs = s.get("filters") or []
                    step = ""
                    if isinstance(fs, list):
                        for f0 in list(fs):
                            if not isinstance(f0, dict):
                                continue
                            if str(f0.get("filterType") or "").upper().strip() == "LOT_SIZE":
                                step = str(f0.get("stepSize") or f0.get("step") or "").strip()
                                break
                    sd = 0
                    if step:
                        stp = step.lower()
                        if "e-" in stp:
                            try:
                                sd = int(stp.split("e-", 1)[1])
                            except Exception:
                                sd = 0
                        elif "." in stp:
                            try:
                                sd = len(stp.split(".", 1)[1].rstrip("0"))
                            except Exception:
                                sd = 0
                    try:
                        prev_sd = int(allowed_base_to_szdec.get(ba) or 0)
                    except Exception:
                        prev_sd = 0
                    allowed_base_to_szdec[ba] = int(max(int(prev_sd), int(sd)))

            tickers = _aster_24hr_tickers_all(int(now_ms))
            rows = []
            for t in list(tickers):
                if not isinstance(t, dict):
                    continue
                sym = str(t.get("symbol") or "").upper().strip()
                if not sym:
                    continue
                base = allowed_sym_to_base.get(sym)
                if not base:
                    continue
                qv = t.get("quoteVolume", t.get("quoteVol", t.get("quote_volume")))
                lp = t.get("lastPrice", t.get("last", t.get("price")))
                try:
                    qv_f = float(qv) if qv is not None else 0.0
                except Exception:
                    qv_f = 0.0
                try:
                    lp_f = float(lp) if lp is not None else 0.0
                except Exception:
                    lp_f = 0.0
                if not math.isfinite(float(qv_f)) or float(qv_f) <= 0.0:
                    continue
                if not math.isfinite(float(lp_f)) or float(lp_f) <= 0.0:
                    continue
                rows.append((base, float(qv_f), float(lp_f)))
            rows.sort(key=lambda x: x[1], reverse=True)
            rows = rows[: int(top_n)]
            coins0 = [r[0] for r in rows]
            mids0 = {r[0]: float(r[2]) for r in rows}

            class _AsterInfoShim:
                def __init__(self, coins, mids):
                    self._coins = list(coins)
                    self._mids = dict(mids)

                def meta(self):
                    uni = []
                    for c in self._coins:
                        try:
                            sd = int(allowed_base_to_szdec.get(c) or 0)
                        except Exception:
                            sd = 0
                        uni.append({"name": c, "szDecimals": int(max(0, sd))})
                    return {"universe": uni}

                def all_mids(self):
                    return dict(self._mids)

            info = _AsterInfoShim(coins0, mids0)
        else:
            info = _hl_info_shim_from_meta_ctx(int(now_ms))
            if info is None:
                info = _hl_info_shim_from_local_data(int(now_ms), max_coins=int(CONFIG.get("universe_local_fallback_max_coins", 800) or 800))
            if info is None:
                info = _hl_info()
        res_a = _build_universe_stage_a(info)
        candidates = res_a.get("candidates", [])

        try:
            min_keep = int(CONFIG.get("universe_min_stage_a_candidates", 25) or 25)
        except Exception:
            min_keep = 25
        try:
            symbols_total = int(res_a.get("symbols_total") or 0)
        except Exception:
            symbols_total = 0
        if (not is_aster) and (symbols_total < min_keep or (isinstance(candidates, list) and len(candidates) < min_keep)):
            shim = _hl_info_shim_from_meta_ctx(int(now_ms))
            if shim is not None:
                res_a2 = _build_universe_stage_a(shim)
                cand2 = res_a2.get("candidates", []) if isinstance(res_a2, dict) else []
                if isinstance(cand2, list) and (not isinstance(candidates, list) or len(cand2) > len(candidates)):
                    res_a = res_a2
                    candidates = cand2

        if (not is_aster) and isinstance(candidates, list) and len(candidates) < min_keep:
            shim_local = _hl_info_shim_from_local_data(int(now_ms), max_coins=int(CONFIG.get("universe_local_fallback_max_coins", 800) or 800))
            if shim_local is not None:
                res_a3 = _build_universe_stage_a(shim_local)
                cand3 = res_a3.get("candidates", []) if isinstance(res_a3, dict) else []
                if isinstance(cand3, list) and len(cand3) > len(candidates):
                    res_a = res_a3
                    candidates = cand3

        if (not is_aster) and isinstance(candidates, list) and len(candidates) < min_keep:
            try:
                mids_map = info.all_mids() or {}
            except Exception:
                mids_map = {}
            try:
                uni0 = info.meta().get("universe", [])
            except Exception:
                uni0 = []
            fill: List[str] = []
            for c in prev_candidates:
                cc = str(c or "").strip().upper()
                if cc and cc not in fill:
                    fill.append(cc)
            for c in (
                "BTC",
                "ETH",
                "SOL",
                "XRP",
                "BNB",
                "DOGE",
                "ADA",
                "AVAX",
                "LINK",
                "SUI",
                "TON",
                "NEAR",
                "APT",
                "ARB",
                "OP",
                "MATIC",
                "LTC",
                "BCH",
                "TRX",
                "DOT",
                "ATOM",
                "ETC",
                "FIL",
                "INJ",
                "UNI",
                "AAVE",
                "PEPE",
                "SHIB",
            ):
                cc = str(c or "").strip().upper()
                if cc and cc not in fill:
                    fill.append(cc)
            if isinstance(uni0, list):
                for cm in uni0:
                    if len(fill) >= int(min_keep):
                        break
                    if not isinstance(cm, dict):
                        continue
                    nm = str(cm.get("name") or "").strip().upper()
                    if nm and nm not in fill:
                        fill.append(nm)
            out_cands: List[str] = []
            seen = set()
            base_cands = list(candidates)
            for c in base_cands + fill:
                cc = str(c or "").strip().upper()
                if not cc or cc in seen:
                    continue
                try:
                    px = float(mids_map.get(cc, 0.0))
                except Exception:
                    px = 0.0
                if not math.isfinite(float(px)) or float(px) <= 0.0:
                    continue
                seen.add(cc)
                out_cands.append(cc)
            if len(out_cands) >= len(base_cands):
                candidates = out_cands
    except Exception:
        prev_candidates_set = set()
        for k in ("core", "shadow", "watchlist"):
            xs = UNIVERSE_STATE.get(k)
            if isinstance(xs, list):
                for x in xs:
                    s = str(x or "").strip().upper()
                    if s:
                        prev_candidates_set.add(s)
        prev_candidates = sorted(prev_candidates_set)

        res_a = None
        candidates = []
        if is_aster:
            try:
                tickers = _aster_24hr_tickers_all(int(now_ms))
                rows = []
                for t in list(tickers):
                    if not isinstance(t, dict):
                        continue
                    sym = str(t.get("symbol") or "").upper().strip()
                    if not sym.endswith("USDT"):
                        continue
                    base = sym[:-4]
                    if not base or base in ("USDT", "USDC"):
                        continue
                    qv = t.get("quoteVolume", t.get("quoteVol", t.get("quote_volume")))
                    try:
                        qv_f = float(qv) if qv is not None else 0.0
                    except Exception:
                        qv_f = 0.0
                    if not math.isfinite(float(qv_f)) or float(qv_f) <= 0.0:
                        continue
                    rows.append((base, float(qv_f)))
                rows.sort(key=lambda x: x[1], reverse=True)
                rows = rows[:200]
                candidates = [r[0] for r in rows]
                res_a = {"candidates": candidates, "issues": {}, "symbols_total": None, "mids_total": (len(candidates) if isinstance(candidates, list) else None)}
            except Exception:
                res_a = None
                candidates = []

        if not candidates:
            shim = _hl_info_shim_from_meta_ctx(int(now_ms))
            if shim is not None:
                res_a = _build_universe_stage_a(shim)
                candidates = res_a.get("candidates", []) if isinstance(res_a, dict) else []
            else:
                by_coin = _hl_meta_and_asset_ctxs_cached(now_ms)
                candidates = [c for c, ctx in (by_coin.items() if isinstance(by_coin, dict) else []) if float((ctx or {}).get("midPx") or 0.0) > 0.0]
                if not candidates:
                    shim_local = _hl_info_shim_from_local_data(int(now_ms), max_coins=int(CONFIG.get("universe_local_fallback_max_coins", 800) or 800))
                    if shim_local is not None:
                        res_a = _build_universe_stage_a(shim_local)
                        candidates = res_a.get("candidates", []) if isinstance(res_a, dict) else []
                if not candidates:
                    candidates = prev_candidates if prev_candidates else []
                    res_a = {"candidates": candidates, "issues": {}, "symbols_total": None, "mids_total": (len(candidates) if isinstance(candidates, list) else None)}

    if not isinstance(res_a, dict):
        res_a = {"candidates": [], "issues": {}, "symbols_total": None, "mids_total": None}
    if not isinstance(candidates, list):
        candidates = []
    candidates = [str(x).upper().strip() for x in candidates if str(x or "").strip()]

    if not candidates:
        try:
            by_coin = _hl_meta_and_asset_ctxs_cached(now_ms)
            candidates = [str(c).upper().strip() for c, ctx in (by_coin.items() if isinstance(by_coin, dict) else []) if float((ctx or {}).get("midPx") or 0.0) > 0.0]
        except Exception:
            candidates = []
    if not candidates:
        try:
            _build_data_index()
            coins = set()
            for k in (DATA_INDEX_ALL.keys() if isinstance(DATA_INDEX_ALL, dict) else []):
                base = str(k).split("_", 1)[0].upper().strip()
                if base and base not in ("USDT", "USDC"):
                    coins.add(base)
            candidates = sorted(coins)
        except Exception:
            candidates = []
    if not candidates:
        candidates = ["BTC", "ETH", "SOL"]

    res_a["candidates"] = candidates
    if "issues" not in res_a or not isinstance(res_a.get("issues"), dict):
        res_a["issues"] = {}
    if res_a.get("symbols_total") is None:
        res_a["symbols_total"] = int(len(candidates))
    if res_a.get("mids_total") is None:
        res_a["mids_total"] = int(len(candidates))
    
    # Stage B: Scoring & Ranking
    # Use simple factors for now: volatility (ATR%), liquidity (turnover), and recent return
    # Ideally: factor scoring using ML models
    
    cluster_timeframe = str(CONFIG.get("universe_cluster_timeframe", "1h") or "1h").strip().lower() or "1h"
    try:
        cluster_window_bars = int(CONFIG.get("universe_cluster_window_bars", 240) or 240)
    except Exception:
        cluster_window_bars = 240

    try:
        cluster_k_config = int(CONFIG.get("universe_cluster_k", 8) or 8)
    except Exception:
        cluster_k_config = 8

    scored_candidates = []
    for coin in candidates:
        stats = _get_coin_stats_7d(coin)
        pair = f"{coin}/USDT"

        rows_1h = []
        if is_aster:
            try:
                lim = int(max(int(cluster_window_bars) + 40, 200))
            except Exception:
                lim = 240
            lim = max(200, min(1000, int(lim)))
            try:
                rows_1h = _aster_klines_ohlcv_rows(coin=str(coin).upper().strip(), timeframe="1h", limit=int(lim))
            except Exception:
                rows_1h = []
        else:
            c = {}
            for pa in _universe_pair_aliases(pair):
                cc = _get_pair_cache(pa)
                if isinstance(cc, dict) and (cc.get("hourly") or cc.get("hourly_logret")):
                    c = cc
                    break
            rows_1h = c.get("hourly") or []
            if not isinstance(rows_1h, list):
                rows_1h = []

            if len(rows_1h) < 30:
                try:
                    lookback_ms = int(max((int(cluster_window_bars) + 20) * 3600 * 1000, 10 * 24 * 3600 * 1000))
                except Exception:
                    lookback_ms = 10 * 24 * 3600 * 1000
                try:
                    rows_1h = _hl_fetch_ohlcv_rows_cached(coin=pair, interval="1h", now_ms=int(now_ms), lookback_ms=int(lookback_ms))
                except Exception:
                    rows_1h = rows_1h if isinstance(rows_1h, list) else []

        atr_pct = 0.0
        adx = 0.0
        chop = 0.0
        vol_ratio = 1.0
        btc_corr_v: Optional[float] = None
        btc_exposure = {"beta": None, "beta_std": None, "corr": None, "resid_vol": None}

        try:
            if is_aster:
                btc_exposure = _aster_btc_exposure(str(coin).upper().strip(), int(cluster_window_bars))
            else:
                btc_exposure = _universe_btc_exposure(pair, now_ms, cluster_window_bars)
        except Exception:
            btc_exposure = {"beta": None, "beta_std": None, "corr": None, "resid_vol": None}

        try:
            v = (btc_exposure or {}).get("corr")
            if v is not None and math.isfinite(float(v)):
                btc_corr_v = float(v)
        except Exception:
            btc_corr_v = None

        if len(rows_1h) >= 30:
            closes = []
            highs = []
            lows = []
            vols = []
            for r in rows_1h:
                if not isinstance(r, (list, tuple)) or len(r) < 6:
                    continue
                try:
                    highs.append(float(r[2]))
                    lows.append(float(r[3]))
                    closes.append(float(r[4]))
                    vols.append(float(r[5]))
                except Exception:
                    continue

            atr = 0.0
            trs = []
            for i in range(1, len(closes)):
                try:
                    hl = float(highs[i] - lows[i])
                    hc = abs(float(highs[i] - closes[i - 1]))
                    lc = abs(float(lows[i] - closes[i - 1]))
                    tr = max(hl, hc, lc)
                    if math.isfinite(float(tr)):
                        trs.append(float(tr))
                except Exception:
                    continue
            n_atr = 14
            if trs:
                if len(trs) >= n_atr:
                    atr = float(sum(trs[-n_atr:]) / float(n_atr))
                else:
                    atr = float(sum(trs) / float(len(trs)))
            if closes and closes[-1] > 0 and math.isfinite(float(atr)):
                atr_pct = float(atr) / float(closes[-1])

            if vols:
                vol_24h = float(sum(vols[-24:])) if len(vols) >= 24 else float(sum(vols))
                if len(vols) >= 168:
                    vol_7d_avg = float(sum(vols[-168:]) / 7.0)
                elif len(vols) >= 24:
                    vol_7d_avg = float(sum(vols) / max(1.0, float(len(vols)) / 24.0))
                else:
                    vol_7d_avg = float(vol_24h)
                if vol_7d_avg > 0 and math.isfinite(float(vol_7d_avg)):
                    vol_ratio = float(vol_24h) / float(vol_7d_avg)

            n_chop = 14
            if len(closes) > n_chop and atr > 0:
                tr_sum_14 = 0.0
                max_hi = max(highs[-n_chop:])
                min_lo = min(lows[-n_chop:])
                for i in range(len(closes) - n_chop, len(closes)):
                    try:
                        hl = float(highs[i] - lows[i])
                        hc = abs(float(highs[i] - closes[i - 1]))
                        lc = abs(float(lows[i] - closes[i - 1]))
                        tr_sum_14 += max(hl, hc, lc)
                    except Exception:
                        continue
                range_hl = float(max_hi - min_lo)
                if range_hl > 0:
                    try:
                        chop_v = math.log10(float(tr_sum_14) / float(range_hl)) / math.log10(float(n_chop))
                        if math.isfinite(float(chop_v)):
                            chop = float(chop_v)
                    except Exception:
                        chop = 0.0

            if len(closes) > 24 and atr > 0:
                try:
                    adx_v = abs(float(closes[-1] - closes[-25])) / (float(atr) * 24.0)
                    if math.isfinite(float(adx_v)):
                        adx = float(adx_v)
                except Exception:
                    adx = 0.0

            if btc_corr_v is None:
                try:
                    if is_aster:
                        try:
                            lim2 = int(max(int(cluster_window_bars) + 40, 200))
                        except Exception:
                            lim2 = 240
                        lim2 = max(200, min(1000, int(lim2)))
                        btc_rows = _aster_klines_ohlcv_rows(coin="BTC", timeframe="1h", limit=int(lim2))
                        btc_closes = []
                        for r in list(btc_rows):
                            if not isinstance(r, (list, tuple)) or len(r) < 5:
                                continue
                            try:
                                btc_closes.append(float(r[4]))
                            except Exception:
                                continue
                        n = int(min(len(closes), len(btc_closes)))
                        if n >= 60:
                            a = closes[-n:]
                            b = btc_closes[-n:]
                            ra = []
                            rb = []
                            for i in range(1, n):
                                if float(a[i - 1]) > 0.0 and float(a[i]) > 0.0 and float(b[i - 1]) > 0.0 and float(b[i]) > 0.0:
                                    ra.append(math.log(float(a[i]) / float(a[i - 1])))
                                    rb.append(math.log(float(b[i]) / float(b[i - 1])))
                            m = int(min(len(ra), len(rb)))
                            if m >= 50:
                                ra = ra[-m:]
                                rb = rb[-m:]
                                ma = float(sum(ra)) / float(m)
                                mb = float(sum(rb)) / float(m)
                                va = 0.0
                                vb = 0.0
                                cov = 0.0
                                for i in range(m):
                                    da = float(ra[i] - ma)
                                    db = float(rb[i] - mb)
                                    va += da * da
                                    vb += db * db
                                    cov += da * db
                                if va > 0.0 and vb > 0.0:
                                    btc_corr_v = float(cov / math.sqrt(float(va) * float(vb)))
                    else:
                        c0 = _pair_corr_cached(pair, "BTC/USDT", now_ms, 72.0)
                        if math.isfinite(float(c0)):
                            btc_corr_v = float(c0)
                except Exception:
                    btc_corr_v = None

        btc_corr = float(btc_corr_v) if btc_corr_v is not None else 0.0

        # Turnover score (log)
        turnover = stats.get("median_turnover", 0.0)
        t_score = math.log(turnover + 1.0)
        
        # --- Factor Scoring ---
        
        # 1. Volatility Score (Bell Curve preference for ATR%)
        # Sweet spot: 0.5% to 2.0% hourly? No, ATR% usually 0.1% - 1% per hour
        # Let's say sweet spot is 0.2% - 0.8%
        # Score = 1.0 if in [0.002, 0.008], decays outside
        s_vol = 0.0
        if 0.002 <= atr_pct <= 0.008:
            s_vol = 1.0
        elif atr_pct < 0.002:
            s_vol = atr_pct / 0.002
        else:
            s_vol = max(0.0, 1.0 - (atr_pct - 0.008) * 50.0) # Decay fast if too volatile

        # 2. Trend Score
        # High ADX (trend strength), Low Chop
        # Normalize ADX proxy: > 0.5 is strong trend
        s_trend = min(1.0, adx * 2.0) * (1.0 - chop if chop < 1.0 else 0.0)
        
        # 3. Mean Reversion Score (High Chop, Low ADX)
        s_mr = (chop if chop < 1.0 else 1.0) * (1.0 - min(1.0, adx * 2.0))
        
        # 4. Liquidity Score (Log Turnover)
        # Normalize: log(10M) ~ 16, log(50k) ~ 10.8
        # Map [11, 18] -> [0, 1]
        s_liq = max(0.0, min(1.0, (t_score - 11.0) / 7.0))
        
        # 5. Correlation Readiness
        # Penalize high correlation > 0.8
        s_corr = 1.0
        if btc_corr > 0.8:
            s_corr = 0.5
        elif btc_corr > 0.9:
            s_corr = 0.2
            
        feedback_score = 0.0
        sim_stats = _simulate_signal_yield(pair, lookback_hours=168)
        tracker_stats = TRACKER_STATE.get("shadow_stats", {}).get(pair, {})

        alpha_src = None
        wr = 0.0
        count = 0
        pnl_shadow = 0.0
        avg_ret_shadow = 0.0
        pf_shadow = None

        if tracker_stats and tracker_stats.get("count", 0) > 10:
            alpha_src = "tracker"
            wr = float(tracker_stats.get("win_rate", 0.0))
            count = int(tracker_stats.get("count", 0))
            try:
                pnl_shadow = float(tracker_stats.get("shadow_pnl", tracker_stats.get("pnl", 0.0)) or 0.0)
            except Exception:
                pnl_shadow = 0.0
            try:
                avg_ret_shadow = float(tracker_stats.get("avg_ret", 0.0) or 0.0)
            except Exception:
                avg_ret_shadow = 0.0
            try:
                pf_shadow = float(tracker_stats.get("profit_factor")) if tracker_stats.get("profit_factor") is not None else None
            except Exception:
                pf_shadow = None
        elif sim_stats:
            alpha_src = "sim"
            wr = float(sim_stats.get("shadow_win_rate", 0.0))
            count = int(sim_stats.get("count", 0))
            try:
                pnl_shadow = float(sim_stats.get("shadow_pnl", 0.0) or 0.0)
            except Exception:
                pnl_shadow = 0.0
            try:
                avg_ret_shadow = float(sim_stats.get("avg_ret", 0.0) or 0.0)
            except Exception:
                avg_ret_shadow = 0.0
            try:
                pf_shadow = float(sim_stats.get("profit_factor")) if sim_stats.get("profit_factor") is not None else None
            except Exception:
                pf_shadow = None

        try:
            alpha_enabled = bool(CONFIG.get("universe_alpha_gate_enabled", True))
        except Exception:
            alpha_enabled = True
        try:
            alpha_enf = str(CONFIG.get("universe_alpha_gate_enforcement", "soft") or "soft").lower().strip()
        except Exception:
            alpha_enf = "soft"
        try:
            alpha_min_trades = int(CONFIG.get("universe_alpha_gate_min_trades", 8) or 8)
        except Exception:
            alpha_min_trades = 8
        try:
            alpha_min_pf = float(CONFIG.get("universe_alpha_gate_min_profit_factor", 1.0) or 1.0)
        except Exception:
            alpha_min_pf = 1.0
        try:
            alpha_min_pnl = float(CONFIG.get("universe_alpha_gate_min_pnl", 0.0) or 0.0)
        except Exception:
            alpha_min_pnl = 0.0

        alpha_pass = True
        if alpha_enabled:
            if int(count) < int(alpha_min_trades):
                alpha_pass = False
            else:
                pfv = 0.0
                try:
                    pfv = float(pf_shadow) if pf_shadow is not None else 0.0
                except Exception:
                    pfv = 0.0
                alpha_pass = (float(pnl_shadow) >= float(alpha_min_pnl) - 1e-12) and (float(pfv) >= float(alpha_min_pf) - 1e-12)

        if int(count) >= max(5, int(alpha_min_trades)):
            pfv = 0.0
            try:
                pfv = float(pf_shadow) if pf_shadow is not None else 0.0
            except Exception:
                pfv = 0.0
            s_wr = float(_clip((float(wr) - 0.5) / 0.10, -1.0, 1.0))
            s_pf = float(_clip((float(pfv) - 1.0) / 1.0, -1.0, 1.0))
            s_pnl = float(_clip(float(pnl_shadow) / 0.05, -1.0, 1.0))
            feedback_score = float(_clip(0.30 * float(s_wr) + 0.35 * float(s_pf) + 0.35 * float(s_pnl), -1.0, 1.0))
        
        # Composite Score
        # w_vol=0.2, w_trend=0.3, w_liq=0.4, w_corr=0.1
        # Add feedback as a modifier (not main driver initially, but nudges)
        # Let's renormalize: 0.2, 0.3, 0.3, 0.1, 0.1
        
        s_activity = max(s_trend, s_mr)
        
        final_score = (0.2 * s_vol) + (0.3 * s_activity) + (0.3 * s_liq) + (0.1 * s_corr) + (0.1 * feedback_score)
        
        # Boost for Volume Ratio > 2.0 (Breakout/News)
        if vol_ratio > 2.0:
            final_score *= 1.2
        
        scored_candidates.append({
            "coin": coin, 
            "score": final_score, 
            "turnover": turnover, 
            "atr_pct": atr_pct,
            "btc_corr": btc_corr,
            "vol_ratio": vol_ratio,
            "feedback": feedback_score,
            "alpha": {
                "enabled": bool(alpha_enabled),
                "enforcement": str(alpha_enf),
                "source": (None if alpha_src is None else str(alpha_src)),
                "pass": bool(alpha_pass),
                "count": int(count),
                "win_rate": float(wr),
                "pnl": float(pnl_shadow),
                "avg_ret": float(avg_ret_shadow),
                "profit_factor": (None if pf_shadow is None else float(pf_shadow)),
                "forward_bars": int(CONFIG.get("universe_alpha_gate_forward_bars", 12) or 12),
                "fee_rate": float(CONFIG.get("universe_alpha_gate_fee_rate", 0.0) or 0.0),
                "min_trades": int(alpha_min_trades),
                "min_profit_factor": float(alpha_min_pf),
                "min_pnl": float(alpha_min_pnl),
            },
            "age_days": float(stats.get("age_days", 0.0) or 0.0),
            "gap_rate": (1.0 if stats.get("gap_rate") is None else float(stats.get("gap_rate"))),
            "jump_rate": float(stats.get("jump_rate", 0.0) or 0.0),
            "btc_exposure": btc_exposure,
        })
        
    scored_candidates.sort(key=lambda x: x["score"], reverse=True)

    btc_corr_cov_denom = 0
    btc_corr_cov_num = 0
    try:
        dual_cov = False
        try:
            dual_cov = bool(CONFIG.get("strategy_btc_corr_dual_window_enabled", False))
        except Exception:
            dual_cov = False
        for it in scored_candidates:
            if not isinstance(it, dict):
                continue
            c0 = str(it.get("coin") or "").upper().strip()
            if not c0 or c0 == "BTC":
                continue
            btc_corr_cov_denom += 1
            ex0 = it.get("btc_exposure") if isinstance(it.get("btc_exposure"), dict) else {}
            if bool(dual_cov):
                ok0 = (ex0 or {}).get("corr_dual_ok")
                v30 = (ex0 or {}).get("corr_30d")
                v60 = (ex0 or {}).get("corr_60d")
                if bool(ok0) and v30 is not None and v60 is not None and math.isfinite(float(v30)) and math.isfinite(float(v60)):
                    btc_corr_cov_num += 1
            else:
                v0 = (ex0 or {}).get("corr")
                if v0 is not None and math.isfinite(float(v0)):
                    btc_corr_cov_num += 1
    except Exception:
        btc_corr_cov_denom = 0
        btc_corr_cov_num = 0
    btc_corr_cov = (float(btc_corr_cov_num) / float(btc_corr_cov_denom)) if btc_corr_cov_denom > 0 else None
    
    # Redundancy Removal (Correlation Check)
    # Iterate through ranked list, pick coin if max correlation with already picked coins < threshold
    final_ranked_coins = []
    picked_pairs = []
    
    corr_threshold = float(CONFIG.get("correlation_threshold", 0.85))
    lookback = float(CONFIG.get("correlation_lookback_hours", 72))
    corr_dual_enabled = False
    corr_dual_30d = 720.0
    corr_dual_60d = 1440.0
    corr_dual_max_abs_delta = 0.15
    try:
        corr_dual_enabled = bool(CONFIG.get("correlation_dual_window_enabled", False))
    except Exception:
        corr_dual_enabled = False
    if bool(corr_dual_enabled):
        try:
            corr_dual_30d = float(CONFIG.get("correlation_dual_window_30d_hours", 720) or 720)
        except Exception:
            corr_dual_30d = 720.0
        try:
            corr_dual_60d = float(CONFIG.get("correlation_dual_window_60d_hours", 1440) or 1440)
        except Exception:
            corr_dual_60d = 1440.0
        try:
            corr_dual_max_abs_delta = float(CONFIG.get("correlation_dual_window_max_abs_delta", 0.15) or 0.15)
        except Exception:
            corr_dual_max_abs_delta = 0.15
        if (not math.isfinite(float(corr_dual_30d))) or float(corr_dual_30d) <= 0.0:
            corr_dual_30d = 720.0
        if (not math.isfinite(float(corr_dual_60d))) or float(corr_dual_60d) <= 0.0:
            corr_dual_60d = 1440.0
        if float(corr_dual_60d) < float(corr_dual_30d):
            corr_dual_60d = float(corr_dual_30d)
        if (not math.isfinite(float(corr_dual_max_abs_delta))) or float(corr_dual_max_abs_delta) < 0.0:
            corr_dual_max_abs_delta = 0.15
        corr_dual_max_abs_delta = float(_clip(float(corr_dual_max_abs_delta), 0.0, 2.0))
    
    # We want to fill Core first, then Shadow, then Watchlist
    # But we apply dedup mainly for Core and Shadow to ensure diversity
    # Watchlist can be everything else
    
    for item in scored_candidates:
        coin = item["coin"]
        pair = f"{coin}/USDT"

        if is_aster:
            final_ranked_coins.append(coin)
            continue
        
        is_correlated = False
        for p_picked in picked_pairs:
             # Calculate correlation on the fly (cached)
             if bool(corr_dual_enabled):
                 c30 = _pair_corr_cached(pair, p_picked, now_ms, float(corr_dual_30d))
                 c60 = _pair_corr_cached(pair, p_picked, now_ms, float(corr_dual_60d))
                 if max(float(c30), float(c60)) > float(corr_threshold) + 1e-12:
                     is_correlated = True
                     break
                 if abs(float(c30) - float(c60)) > float(corr_dual_max_abs_delta) + 1e-12:
                     is_correlated = True
                     break
             else:
                 c = _pair_corr_cached(pair, p_picked, now_ms, lookback)
                 if c > corr_threshold:
                     is_correlated = True
                     break
        
        if not is_correlated:
            final_ranked_coins.append(coin)
            picked_pairs.append(pair)
        else:
            # If correlated, maybe push to end or skip for Core?
            # For now, we skip it for "Core consideration" but it still exists in candidate list
            # Actually, to strictly follow "Redundancy Removal", we should deprioritize it.
            # Let's append it to a "rejected" list and add them back at the end
            pass
            
    # Add back the skipped ones at the end (so they go to Watchlist/Shadow but not top Core)
    picked_set = set(final_ranked_coins)
    rest_coins = [x["coin"] for x in scored_candidates if x["coin"] not in picked_set]
    final_ranked_coins.extend(rest_coins)
    
    ranked_coins = final_ranked_coins
    
    # Stage D: Composition & Holding Period
    # 1. Min Hold Period Check
    # Ensure assets in Core don't get kicked out too fast unless they fail hard filters
    # We need previous state to check holding time
    prev_core = set(UNIVERSE_STATE.get("core") or [])
    prev_update = UNIVERSE_STATE.get("last_update") or 0
    
    min_hold_ms = 3 * 24 * 3600 * 1000 # 3 days
    
    # Identify coins that should be kept in Core due to holding period
    kept_core = []
    if prev_update > 0 and (now_ms - prev_update) < min_hold_ms:
        # If we are within hold period of previous update?
        # Actually min_hold applies to individual assets.
        # Since we don't track per-asset entry time in UNIVERSE_STATE yet, 
        # we can use a simplified rule: if in prev_core and passed hard filters (candidates), keep it.
        # But we also want to allow upgrades. 
        # Let's implementation: Prioritize prev_core items if they are in top 2*N scores?
        # Or strict hold: if in prev_core and in candidates, keep in Core.
        
        # Better approach: 
        # 1. Select Top K from ranked_coins as usual.
        # 2. But if a coin was in prev_core, is still valid (in candidates), 
        #    and is not in new Top K, but is 'close enough' (e.g. Top 1.5*K), keep it to avoid churn.
        pass

    # Composition: Trend vs Mean Reversion
    # We want roughly 60% Trend, 40% MR assets in Core?
    # Actually our strategies are dynamic, so maybe better to just ensure diversity in regimes.
    # We already have "max(trend, mr)" score.
    # Let's enforce that we don't have 100% low-vol assets.
    # The current scoring (0.3 * activity) already pushes for active assets.
    
    # Let's Apply simple Min Hold Logic:
    # If a coin was in Core, and is still in top 30 (of 20 slots), keep it in Core.
    # This reduces churn.
    
    final_core = []
    final_shadow = []
    
    # Capacity
    try:
        N_CORE = int(CONFIG.get("universe_core_size", 20) or 20)
    except Exception:
        N_CORE = 20
    N_CORE = max(1, int(N_CORE))
    try:
        N_SHADOW = int(CONFIG.get("universe_shadow_size", 30) or 30)
    except Exception:
        N_SHADOW = 30
    N_SHADOW = max(0, int(N_SHADOW))

    try:
        alpha_enabled_pool = bool(CONFIG.get("universe_alpha_gate_enabled", True))
    except Exception:
        alpha_enabled_pool = True
    try:
        alpha_enf_pool = str(CONFIG.get("universe_alpha_gate_enforcement", "soft") or "soft").lower().strip()
    except Exception:
        alpha_enf_pool = "soft"
    hard_alpha_pool = bool(alpha_enabled_pool) and str(alpha_enf_pool) == "hard"

    alpha_pass_map: Dict[str, bool] = {}
    try:
        for it in scored_candidates:
            if not isinstance(it, dict):
                continue
            c0 = str(it.get("coin") or "").upper().strip()
            if not c0:
                continue
            a0 = it.get("alpha") if isinstance(it.get("alpha"), dict) else None
            ok0 = bool(a0.get("pass", True)) if isinstance(a0, dict) else True
            alpha_pass_map[c0] = bool(ok0)
    except Exception:
        alpha_pass_map = {}
    
    # 1. Fill Core with high-ranking prev_core items (Churn Buffer)
    ranked_map = {c: i for i, c in enumerate(ranked_coins)}
    
    for c in prev_core:
        if c in ranked_map and ranked_map[c] < N_CORE * 1.5:
            if bool(hard_alpha_pool) and (not bool(alpha_pass_map.get(str(c).upper().strip(), True))):
                continue
            final_core.append(c)
            
    # 2. Fill rest of Core from top ranked
    for c in ranked_coins:
        if len(final_core) >= N_CORE:
            break
        if c not in final_core:
            if bool(hard_alpha_pool) and (not bool(alpha_pass_map.get(str(c).upper().strip(), True))):
                continue
            final_core.append(c)
            
    # 3. Fill Shadow
    remaining = [c for c in ranked_coins if c not in final_core]
    if bool(hard_alpha_pool):
        remaining_pass = [c for c in remaining if bool(alpha_pass_map.get(str(c).upper().strip(), True))]
        remaining_fail = [c for c in remaining if not bool(alpha_pass_map.get(str(c).upper().strip(), True))]
        final_shadow = remaining_pass[:N_SHADOW]
        final_watchlist = remaining_pass[N_SHADOW:] + remaining_fail
    else:
        final_shadow = remaining[:N_SHADOW]
        final_watchlist = remaining[N_SHADOW:]

    if not final_core:
        prev_list = UNIVERSE_STATE.get("core") or []
        if isinstance(prev_list, list) and prev_list:
            final_core = [str(x).upper().strip() for x in prev_list if str(x or "").strip()]
        if not final_core:
            final_core = ["BTC", "ETH", "SOL"]
        final_shadow = []
        final_watchlist = []

    btc_corr_degraded = False
    btc_corr_degrade_reason = None
    try:
        degrade_enabled = bool(CONFIG.get("universe_btc_corr_degrade_enabled", True))
    except Exception:
        degrade_enabled = True
    try:
        min_cov = float(CONFIG.get("universe_btc_corr_degrade_min_coverage", 0.25) or 0.25)
    except Exception:
        min_cov = 0.25
    if (not math.isfinite(float(min_cov))) or float(min_cov) < 0.0:
        min_cov = 0.0
    min_cov = float(_clip(float(min_cov), 0.0, 1.0))
    if bool(degrade_enabled) and bool(CONFIG.get("strategy_btc_corr_gate_enabled", True)):
        if btc_corr_cov is not None and btc_corr_cov_denom >= 10 and float(btc_corr_cov) < float(min_cov) - 1e-12:
            btc_corr_degraded = True
            btc_corr_degrade_reason = f"btc_corr_coverage<{float(min_cov):.4f}"
            final_core = ["BTC"]
            final_shadow = []
            final_watchlist = []
            try:
                TRACKER_STATE["entry_macro_gate_scope_suggested"] = {"scope": "btc_only", "ts": int(now_ms), "reason": str(btc_corr_degrade_reason)}
            except Exception:
                pass
    if not bool(btc_corr_degraded):
        try:
            min_core_floor = int(CONFIG.get("universe_min_core_floor", 10) or 10)
        except Exception:
            min_core_floor = 10
        try:
            min_shadow_floor = int(CONFIG.get("universe_min_shadow_floor", 8) or 8)
        except Exception:
            min_shadow_floor = 8
        try:
            min_watch_floor = int(CONFIG.get("universe_min_watchlist_floor", 8) or 8)
        except Exception:
            min_watch_floor = 8
        min_core_floor = int(max(1, min(200, int(min_core_floor))))
        min_shadow_floor = int(max(0, min(200, int(min_shadow_floor))))
        min_watch_floor = int(max(0, min(200, int(min_watch_floor))))
        need_boost = (len(final_core) < int(min_core_floor)) or (len(final_shadow) < int(min_shadow_floor)) or (len(final_watchlist) < int(min_watch_floor))
        if need_boost:
            ordered: List[str] = []
            seen = set()
            for src in (final_core, final_shadow, final_watchlist, ranked_coins, _universe_default_core_pool(min_n=int(max(20, min_core_floor + min_shadow_floor + min_watch_floor + 10)))):
                if not isinstance(src, list):
                    continue
                for x in src:
                    s = str(x or "").strip().upper()
                    if not s or s in ("USDT", "USDC") or s in seen:
                        continue
                    seen.add(s)
                    ordered.append(s)
            total = int(len(ordered))
            if total > 0:
                reserve = int(max(int(min_shadow_floor + min_watch_floor), int(total * 0.35)))
                core_target = int(min(int(N_CORE), max(int(min_core_floor), int(total - reserve))))
                core_target = int(max(1, min(int(core_target), int(total))))
                rem_n = int(max(0, int(total - core_target)))
                shadow_target = int(min(int(N_SHADOW), max(int(min_shadow_floor), min(int(rem_n), int(rem_n - min_watch_floor) if rem_n > min_watch_floor else 0))))
                shadow_target = int(max(0, min(int(shadow_target), int(rem_n))))
                watch_target = int(max(0, int(rem_n - shadow_target)))
                final_core = ordered[: int(core_target)]
                final_shadow = ordered[int(core_target) : int(core_target) + int(shadow_target)]
                final_watchlist = ordered[int(core_target) + int(shadow_target) : int(core_target) + int(shadow_target) + int(watch_target)]
    
    labels_by_coin: Dict[str, str] = {}
    clusters: Dict[str, Any] = {}
    pools: Dict[str, Any] = {}
    selection_hints: Dict[str, Any] = {}
    cluster_consistency: Dict[str, Any] = {}
    candidates_schema: List[Dict[str, Any]] = []

    cluster_hyperparams: Dict[str, Any] = {
        "method": "kmeans",
        "timeframe": str(cluster_timeframe),
        "window_bars": int(cluster_window_bars),
        "k_config": int(cluster_k_config),
        "k_used": None,
        "iters": 25,
        "features": ["beta", "corr_to_btc", "resid_vol", "log_turnover"],
        "standardize": {"mu": None, "sd": None},
        "n_samples": 0,
        "cluster_count": None,
        "cluster_count_prev": None,
        "cluster_count_change_rate": None,
    }

    try:
        feature_sets = [
            ["beta", "corr_to_btc", "resid_vol", "log_turnover"],
            ["beta", "corr_to_btc", "log_turnover"],
            ["beta", "corr_to_btc"],
        ]

        feats: List[List[float]] = []
        coins_for_cluster: List[str] = []
        used_features: List[str] = []
        for fset in feature_sets:
            feats = []
            coins_for_cluster = []
            used_features = list(fset)
            for item in scored_candidates:
                coin = str(item.get("coin") or "").upper().strip()
                if not coin:
                    continue
                ex = item.get("btc_exposure") or {}
                beta = ex.get("beta")
                corr = ex.get("corr")
                rv = ex.get("resid_vol")
                t = item.get("turnover")

                row: List[float] = []
                try:
                    for f in fset:
                        if f == "beta":
                            if beta is None:
                                raise ValueError("missing beta")
                            row.append(float(beta))
                        elif f == "corr_to_btc":
                            if corr is None:
                                raise ValueError("missing corr")
                            row.append(float(corr))
                        elif f == "resid_vol":
                            if rv is None:
                                raise ValueError("missing resid_vol")
                            row.append(float(rv))
                        elif f == "log_turnover":
                            if t is None:
                                raise ValueError("missing turnover")
                            row.append(float(math.log(float(t) + 1.0)))
                except Exception:
                    continue
                if (not row) or (not all(math.isfinite(float(v)) for v in row)):
                    continue
                feats.append(row)
                coins_for_cluster.append(coin)
            if len(feats) >= 3:
                break

        if feats and len(feats) >= 3:
            cluster_hyperparams["features"] = list(used_features)
            X = np.asarray(feats, dtype=float)
            mu = np.mean(X, axis=0)
            sd = np.std(X, axis=0, ddof=0)
            sd = np.where(sd <= 0.0, 1.0, sd)
            Xz = (X - mu) / sd
            k = int(cluster_k_config)
            cluster_hyperparams["k_used"] = int(k)
            cluster_hyperparams["n_samples"] = int(len(feats))
            try:
                cluster_hyperparams["standardize"] = {"mu": [float(x) for x in list(mu)], "sd": [float(x) for x in list(sd)]}
            except Exception:
                cluster_hyperparams["standardize"] = {"mu": None, "sd": None}
            y = _universe_kmeans_assign(Xz, k=k, iters=25)
            for coin, lab in zip(coins_for_cluster, list(y)):
                labels_by_coin[str(coin).upper().strip()] = f"C{int(lab)}"

            members_by_cluster: Dict[str, List[str]] = {}
            for coin, cid in labels_by_coin.items():
                members_by_cluster.setdefault(str(cid), []).append(str(coin))

            for cid, mem in members_by_cluster.items():
                mem_sorted = sorted(set(mem))
                beta_vals: List[float] = []
                corr_vals: List[float] = []
                rv_vals: List[float] = []
                to_vals: List[float] = []
                for coin in mem_sorted:
                    it = next((x for x in scored_candidates if str(x.get("coin") or "").upper().strip() == coin), None)
                    if not it:
                        continue
                    ex = it.get("btc_exposure") or {}
                    try:
                        if ex.get("beta") is not None:
                            beta_vals.append(float(ex.get("beta")))
                        if ex.get("corr") is not None:
                            corr_vals.append(float(ex.get("corr")))
                        if ex.get("resid_vol") is not None:
                            rv_vals.append(float(ex.get("resid_vol")))
                        if it.get("turnover") is not None:
                            to_vals.append(float(it.get("turnover")))
                    except Exception:
                        continue
                centroid = {
                    "avg_beta": (None if not beta_vals else float(np.mean(np.asarray(beta_vals, dtype=float)))),
                    "avg_corr_to_btc": (None if not corr_vals else float(np.mean(np.asarray(corr_vals, dtype=float)))),
                    "avg_resid_vol": (None if not rv_vals else float(np.mean(np.asarray(rv_vals, dtype=float)))),
                    "avg_turnover_7d_median": (None if not to_vals else float(np.mean(np.asarray(to_vals, dtype=float)))),
                }
                clusters[str(cid)] = {"cluster_id": str(cid), "members": mem_sorted, "centroid": centroid}

            pools["cluster"] = {str(cid): list(v.get("members") or []) for cid, v in clusters.items()}

        prev_clusters = prev_meta.get("clusters") if isinstance(prev_meta, dict) else None
        prev_hyp = prev_meta.get("clustering_hyperparams") if isinstance(prev_meta, dict) else None
        prev_cluster_count = None
        try:
            if isinstance(prev_hyp, dict) and prev_hyp.get("cluster_count") is not None:
                prev_cluster_count = int(prev_hyp.get("cluster_count"))
        except Exception:
            prev_cluster_count = None
        if prev_cluster_count is None:
            try:
                if isinstance(prev_clusters, dict) and prev_clusters:
                    prev_cluster_count = int(len(prev_clusters))
            except Exception:
                prev_cluster_count = None

        cur_cluster_count = None
        try:
            cur_cluster_count = int(len(clusters)) if isinstance(clusters, dict) else None
        except Exception:
            cur_cluster_count = None
        if cur_cluster_count is not None:
            cluster_hyperparams["cluster_count"] = int(cur_cluster_count)
        if prev_cluster_count is not None:
            cluster_hyperparams["cluster_count_prev"] = int(prev_cluster_count)
        try:
            if cur_cluster_count is not None and prev_cluster_count is not None:
                denom = max(1, int(prev_cluster_count))
                cluster_hyperparams["cluster_count_change_rate"] = float(abs(int(cur_cluster_count) - int(prev_cluster_count)) / float(denom))
        except Exception:
            cluster_hyperparams["cluster_count_change_rate"] = None

        prev_cons = prev_meta.get("cluster_consistency") if isinstance(prev_meta, dict) else None
        prev_run = None
        if isinstance(prev_cons, dict) and prev_cons.get("run_ms") is not None:
            try:
                prev_run = int(prev_cons.get("run_ms"))
            except Exception:
                prev_run = None

        old_label_map: Dict[str, str] = {}
        prev_centroids: Dict[str, Any] = {}
        if isinstance(prev_clusters, dict):
            for cid, cobj in prev_clusters.items():
                if isinstance(cobj, dict):
                    prev_centroids[str(cid)] = cobj.get("centroid")
                    mem = cobj.get("members") or []
                    if isinstance(mem, list):
                        for coin in mem:
                            if coin:
                                old_label_map[str(coin).upper().strip()] = str(cid)

        shared = sorted(set(old_label_map.keys()) & set(labels_by_coin.keys()))
        ari_nmi = {"ari": None, "nmi": None}
        if shared:
            old_l = []
            new_l = []
            old_id_map: Dict[str, int] = {}
            new_id_map: Dict[str, int] = {}
            for coin in shared:
                oc = old_label_map.get(coin)
                nc = labels_by_coin.get(coin)
                if oc is None or nc is None:
                    continue
                if oc not in old_id_map:
                    old_id_map[oc] = len(old_id_map)
                if nc not in new_id_map:
                    new_id_map[nc] = len(new_id_map)
                old_l.append(int(old_id_map[oc]))
                new_l.append(int(new_id_map[nc]))
            ari_nmi = _universe_ari_nmi(old_l, new_l)

        by_cluster_ret: Dict[str, float] = {}
        drift_by_cluster: Dict[str, float] = {}
        if shared and clusters and old_label_map:
            for cid, cobj in clusters.items():
                mem = cobj.get("members") if isinstance(cobj, dict) else None
                if not isinstance(mem, list) or not mem:
                    continue
                mem_u = [str(x).upper().strip() for x in mem if x]
                overlaps: Dict[str, int] = {}
                for coin in mem_u:
                    oc = old_label_map.get(coin)
                    if oc:
                        overlaps[str(oc)] = overlaps.get(str(oc), 0) + 1
                if not overlaps:
                    continue
                best_old = max(overlaps.items(), key=lambda kv: kv[1])[0]
                by_cluster_ret[str(cid)] = float(overlaps.get(best_old, 0)) / float(len(mem_u))
                prev_cent = prev_centroids.get(best_old)
                cur_cent = cobj.get("centroid") if isinstance(cobj, dict) else None
                if isinstance(prev_cent, dict) and isinstance(cur_cent, dict):
                    keys = ["avg_beta", "avg_corr_to_btc", "avg_resid_vol", "avg_turnover_7d_median"]
                    pv = []
                    cv = []
                    for k in keys:
                        if prev_cent.get(k) is None or cur_cent.get(k) is None:
                            continue
                        try:
                            pv.append(float(prev_cent.get(k)))
                            cv.append(float(cur_cent.get(k)))
                        except Exception:
                            continue
                    if pv and cv and len(pv) == len(cv):
                        try:
                            d = float(np.linalg.norm(np.asarray(cv, dtype=float) - np.asarray(pv, dtype=float)))
                            if math.isfinite(float(d)):
                                drift_by_cluster[str(cid)] = float(d)
                        except Exception:
                            pass

        avg_ret = None
        if by_cluster_ret:
            try:
                avg_ret = float(np.mean(np.asarray(list(by_cluster_ret.values()), dtype=float)))
            except Exception:
                avg_ret = None
        avg_drift = None
        if drift_by_cluster:
            try:
                avg_drift = float(np.mean(np.asarray(list(drift_by_cluster.values()), dtype=float)))
            except Exception:
                avg_drift = None

        status = None
        reasons: List[str] = []
        try:
            min_ari = float(CONFIG.get("universe_consistency_min_ari", 0.3) or 0.3)
        except Exception:
            min_ari = 0.3
        try:
            min_nmi = float(CONFIG.get("universe_consistency_min_nmi", 0.4) or 0.4)
        except Exception:
            min_nmi = 0.4
        ari_v = ari_nmi.get("ari")
        nmi_v = ari_nmi.get("nmi")
        if (ari_v is None) and (nmi_v is None):
            status = "ok"
        else:
            bad = False
            warn = False
            if ari_v is not None and math.isfinite(float(ari_v)) and float(ari_v) < float(min_ari):
                warn = True
                reasons.append("ari")
                if float(ari_v) < float(min_ari) * 0.5:
                    bad = True
            if nmi_v is not None and math.isfinite(float(nmi_v)) and float(nmi_v) < float(min_nmi):
                warn = True
                reasons.append("nmi")
                if float(nmi_v) < float(min_nmi) * 0.5:
                    bad = True
            status = ("breakdown" if bad else ("warn" if warn else "ok"))

        try:
            thr = float(CONFIG.get("universe_cluster_count_jump_threshold", 0.5) or 0.5)
        except Exception:
            thr = 0.5
        try:
            rate = cluster_hyperparams.get("cluster_count_change_rate")
            if rate is not None and math.isfinite(float(rate)) and float(rate) > float(thr):
                if "cluster_count_jump" not in reasons:
                    reasons.append("cluster_count_jump")
                if str(status) == "ok":
                    status = "warn"
        except Exception:
            pass

        cluster_consistency = {
            "run_ms": int(now_ms),
            "timeframe": str(cluster_timeframe),
            "window_bars": int(cluster_window_bars),
            "compare_to_run_ms": (None if prev_run is None else int(prev_run)),
            "ari": (None if ari_v is None else float(ari_v)),
            "nmi": (None if nmi_v is None else float(nmi_v)),
            "cluster_retention": {"avg_retention": avg_ret, "by_cluster": by_cluster_ret},
            "centroid_drift": {"avg_drift": avg_drift, "by_cluster": drift_by_cluster},
            "status": str(status),
            "reasons": reasons,
        }
    except Exception:
        labels_by_coin = {}
        clusters = {}
        pools = {}
        selection_hints = {}
        cluster_consistency = {"run_ms": int(now_ms), "timeframe": str(cluster_timeframe), "window_bars": int(cluster_window_bars), "status": "ok", "reasons": ["error"]}

    try:
        turnovers = [float(x.get("turnover") or 0.0) for x in scored_candidates]
        betas_abs = []
        for x in scored_candidates:
            ex = x.get("btc_exposure") or {}
            if ex.get("beta") is None:
                continue
            try:
                betas_abs.append(abs(float(ex.get("beta"))))
            except Exception:
                continue

        t_arr = np.asarray([v for v in turnovers if math.isfinite(float(v))], dtype=float)
        b_arr = np.asarray([v for v in betas_abs if math.isfinite(float(v))], dtype=float)
        t_q1 = float(np.quantile(t_arr, 0.33)) if t_arr.size > 0 else 0.0
        t_q2 = float(np.quantile(t_arr, 0.67)) if t_arr.size > 0 else 0.0
        b_q1 = float(np.quantile(b_arr, 0.33)) if b_arr.size > 0 else 0.0
        b_q2 = float(np.quantile(b_arr, 0.67)) if b_arr.size > 0 else 0.0

        pools_liq: Dict[str, List[str]] = {"HIGH": [], "MED": [], "LOW": []}
        pools_beta: Dict[str, List[str]] = {"HIGH": [], "MID": [], "LOW": []}
        pools_quality: Dict[str, List[str]] = {"GOOD": [], "OK": [], "BAD": []}

        for it in scored_candidates:
            coin = str(it.get("coin") or "").upper().strip()
            if not coin:
                continue
            t = float(it.get("turnover") or 0.0)
            if t >= t_q2:
                pools_liq["HIGH"].append(coin)
                liq_bucket = "HIGH"
            elif t >= t_q1:
                pools_liq["MED"].append(coin)
                liq_bucket = "MED"
            else:
                pools_liq["LOW"].append(coin)
                liq_bucket = "LOW"

            ex = it.get("btc_exposure") or {}
            beta_bucket = None
            try:
                ba = abs(float(ex.get("beta"))) if ex.get("beta") is not None else None
            except Exception:
                ba = None
            if ba is None:
                beta_bucket = "MID"
            elif ba >= b_q2:
                beta_bucket = "HIGH"
            elif ba >= b_q1:
                beta_bucket = "MID"
            else:
                beta_bucket = "LOW"
            pools_beta[str(beta_bucket)].append(coin)

            age = float(it.get("age_days") or 0.0)
            gap = (1.0 if it.get("gap_rate") is None else float(it.get("gap_rate")))
            jump = float(it.get("jump_rate") or 0.0)
            if age < 7.0 or gap > 0.20 or jump > 0.20:
                quality_bucket = "BAD"
            elif gap > 0.10 or jump > 0.15:
                quality_bucket = "OK"
            else:
                quality_bucket = "GOOD"
            pools_quality[str(quality_bucket)].append(coin)

            it["_liq_bucket"] = liq_bucket
            it["_beta_bucket"] = str(beta_bucket)
            it["_quality_bucket"] = str(quality_bucket)

        pools["liq"] = pools_liq
        pools["beta"] = pools_beta
        pools["quality"] = pools_quality
    except Exception:
        pass

    try:
        cand_issues = res_a.get("issues") if isinstance(res_a, dict) else None
        for r, it in enumerate(scored_candidates, start=1):
            if not isinstance(it, dict):
                continue
            try:
                coin = str(it.get("coin") or "").upper().strip()
            except Exception:
                coin = ""
            if not coin:
                continue

            ex = it.get("btc_exposure") if isinstance(it.get("btc_exposure"), dict) else {}
            cluster_id = labels_by_coin.get(coin)
            if cluster_id is None or str(cluster_id).strip() == "":
                cluster_id = f"COIN_{coin}"

            cluster_rank = None
            if cluster_id and str(cluster_id).startswith("COIN_"):
                cluster_rank = 1
            elif cluster_id:
                try:
                    same = [
                        x
                        for x in scored_candidates
                        if isinstance(x, dict) and labels_by_coin.get(str(x.get("coin") or "").upper().strip()) == cluster_id
                    ]
                    same.sort(key=lambda x: float(x.get("score") or 0.0), reverse=True)
                    for i, x in enumerate(same, start=1):
                        if str(x.get("coin") or "").upper().strip() == coin:
                            cluster_rank = i
                            break
                except Exception:
                    cluster_rank = None

            issues = []
            try:
                if isinstance(cand_issues, dict) and cand_issues.get(coin):
                    v = cand_issues.get(coin)
                    if isinstance(v, list):
                        issues = [str(x) for x in v if x]
                    else:
                        issues = [str(v)]
            except Exception:
                issues = []

            def _f(v: Any, d: float) -> float:
                try:
                    x = float(v)
                    return float(x) if math.isfinite(float(x)) else float(d)
                except Exception:
                    return float(d)

            candidates_schema.append(
                {
                    "coin": coin,
                    "rank": int(r),
                    "score": _f(it.get("score"), 0.0),
                    "source": "scored",
                    "issues": issues,
                    "liq": {
                        "turnover_7d_median": _f(it.get("turnover"), 0.0),
                        "age_days": _f(it.get("age_days"), 0.0),
                        "gap_rate_7d": _f((1.0 if it.get("gap_rate") is None else it.get("gap_rate")), 1.0),
                        "jump_rate_7d": _f(it.get("jump_rate"), 0.0),
                    },
                    "market": {"atr_pct_1h": _f(it.get("atr_pct"), 0.0), "vol_ratio_24h_over_7d": _f(it.get("vol_ratio"), 1.0)},
                    "alpha": (it.get("alpha") if isinstance(it.get("alpha"), dict) else None),
                    "btc_exposure": {
                        "beta": (None if ex.get("beta") is None else _f(ex.get("beta"), 0.0)),
                        "beta_std": (None if ex.get("beta_std") is None else _f(ex.get("beta_std"), 0.0)),
                        "corr": (None if ex.get("corr") is None else _f(ex.get("corr"), 0.0)),
                        "resid_vol": (None if ex.get("resid_vol") is None else _f(ex.get("resid_vol"), 0.0)),
                    },
                    "cluster": {"cluster_id": (None if cluster_id is None else str(cluster_id)), "cluster_rank": (None if cluster_rank is None else int(cluster_rank))},
                    "pools": {"liq_bucket": it.get("_liq_bucket"), "beta_bucket": it.get("_beta_bucket"), "quality_bucket": it.get("_quality_bucket")},
                }
            )
    except Exception:
        candidates_schema = []

    try:
        topk_per_cluster = int(CONFIG.get("universe_selection_topk_per_cluster", 1) or 1)
    except Exception:
        topk_per_cluster = 1
    try:
        max_candidates = int(CONFIG.get("universe_selection_btc_alt_max", 30) or 30)
    except Exception:
        max_candidates = 30
    excluded_coins = set()
    try:
        ex_c = str(CONFIG.get("universe_selection_excluded_coins", "") or "").strip()
        if ex_c:
            excluded_coins = set([str(x).upper().strip() for x in ex_c.split(",") if str(x).strip()])
    except Exception:
        excluded_coins = set()
    excluded_clusters = set()
    try:
        ex_k = str(CONFIG.get("universe_selection_excluded_clusters", "") or "").strip()
        if ex_k:
            excluded_clusters = set([str(x).strip() for x in ex_k.split(",") if str(x).strip()])
    except Exception:
        excluded_clusters = set()

    btc_alt_candidates: List[str] = []
    per_cluster = {}
    try:
        for it in scored_candidates:
            coin = str(it.get("coin") or "").upper().strip()
            if not coin or coin in excluded_coins or coin in ("BTC", "USDT", "USDC"):
                continue
            if str(it.get("_quality_bucket") or "") == "BAD":
                continue
            cid = labels_by_coin.get(coin)
            if cid and cid in excluded_clusters:
                continue
            key = str(cid or "")
            cur = int(per_cluster.get(key, 0))
            if key and cur >= int(topk_per_cluster):
                continue
            btc_alt_candidates.append(coin)
            if key:
                per_cluster[key] = cur + 1
            if len(btc_alt_candidates) >= int(max_candidates):
                break
    except Exception:
        btc_alt_candidates = []

    selection_hints = {
        "btc_alt_candidates": btc_alt_candidates,
        "topk_per_cluster": int(topk_per_cluster),
        "excluded_clusters": sorted(list(excluded_clusters)),
        "excluded_coins": sorted(list(excluded_coins)),
        "constraints": {
            "cluster_timeframe": str(cluster_timeframe),
            "cluster_window_bars": int(cluster_window_bars),
            "cluster_k": (int(cluster_k_config) if feats else None),
        },
    }

    trade_whitelist_auto = None
    try:
        auto_enabled = bool(CONFIG.get("trade_whitelist_auto_enabled", False))
    except Exception:
        auto_enabled = False
    if bool(auto_enabled):
        try:
            auto_source = str(CONFIG.get("trade_whitelist_auto_source", "universe_btc_alt_candidates") or "universe_btc_alt_candidates").strip().lower()
        except Exception:
            auto_source = "universe_btc_alt_candidates"
        try:
            auto_max = int(CONFIG.get("trade_whitelist_auto_max", 30) or 30)
        except Exception:
            auto_max = 30
        auto_max = max(0, int(auto_max))
        try:
            req_alpha = bool(CONFIG.get("trade_whitelist_auto_require_alpha_pass", True))
        except Exception:
            req_alpha = True

        coins0: List[str] = []
        if auto_source in ("universe_btc_alt_candidates", "btc_alt_candidates"):
            xs = selection_hints.get("btc_alt_candidates") if isinstance(selection_hints, dict) else None
            coins0 = [str(x).upper().strip() for x in (xs if isinstance(xs, list) else []) if str(x or "").strip()]
        elif auto_source in ("universe_core", "core"):
            coins0 = [str(x).upper().strip() for x in (final_core if isinstance(final_core, list) else []) if str(x or "").strip()]
        elif auto_source in ("universe_shadow", "shadow"):
            coins0 = [str(x).upper().strip() for x in (final_shadow if isinstance(final_shadow, list) else []) if str(x or "").strip()]
        elif auto_source in ("universe_core_shadow", "core_shadow", "core+shadow"):
            xs = []
            if isinstance(final_core, list):
                xs += final_core
            if isinstance(final_shadow, list):
                xs += final_shadow
            coins0 = [str(x).upper().strip() for x in xs if str(x or "").strip()]
        elif auto_source in ("universe_scored_top", "scored_top"):
            xs = []
            for it in (scored_candidates if isinstance(scored_candidates, list) else []):
                if not isinstance(it, dict):
                    continue
                c0 = str(it.get("coin") or "").upper().strip()
                if c0:
                    xs.append(c0)
            coins0 = xs

        seen = set()
        coins = []
        for c0 in coins0:
            c = str(c0 or "").upper().strip()
            if not c or c in seen:
                continue
            if c in ("USDT", "USDC"):
                continue
            if c == "BTC" and auto_source != "universe_core":
                continue
            seen.add(c)
            coins.append(c)
            if int(auto_max) > 0 and len(coins) >= int(auto_max):
                break

        coins_alpha = coins
        if bool(req_alpha) and isinstance(alpha_pass_map, dict) and alpha_pass_map:
            coins_alpha = [c for c in coins if bool(alpha_pass_map.get(str(c).upper().strip(), True))]
            if len(coins_alpha) < min(5, len(coins)):
                coins_alpha = coins

        wl_symbols = [f"{c}USDT" for c in coins_alpha]
        if wl_symbols:
            try:
                CONFIG["trade_whitelist"] = wl_symbols
                CONFIG["trade_whitelist_enabled"] = True
            except Exception:
                pass
        trade_whitelist_auto = {
            "enabled": True,
            "source": str(auto_source),
            "require_alpha_pass": bool(req_alpha),
            "max": int(auto_max),
            "coins": coins_alpha,
            "whitelist": wl_symbols,
            "run_ms": int(now_ms),
        }

    venue = "hyperliquid"
    try:
        venue = str(CONFIG.get("universe_venue", "hyperliquid") or "hyperliquid").strip().lower() or "hyperliquid"
    except Exception:
        venue = "hyperliquid"
    try:
        symbols_total = res_a.get("symbols_total") if isinstance(res_a, dict) else None
    except Exception:
        symbols_total = None
    try:
        mids_total = res_a.get("mids_total") if isinstance(res_a, dict) else None
    except Exception:
        mids_total = None
    market_snapshot = {
        "run_ms": int(now_ms),
        "venue": str(venue),
        "symbols_total": (int(symbols_total) if symbols_total is not None else None),
        "mids_total": (int(mids_total) if mids_total is not None else None),
        "stage_a_candidates": (int(len(candidates)) if isinstance(candidates, list) else 0),
        "scored_candidates": int(len(scored_candidates)),
        "core_size": int(len(final_core)),
        "shadow_size": int(len(final_shadow)),
        "watchlist_size": int(len(final_watchlist)),
        "btc_corr_coverage": {
            "n_with_corr": int(btc_corr_cov_num),
            "n_denom": int(btc_corr_cov_denom),
            "coverage": (None if btc_corr_cov is None else float(btc_corr_cov)),
        },
        "btc_corr_degraded": bool(btc_corr_degraded),
    }

    monitoring_hints = None
    try:
        alerts: List[Dict[str, Any]] = []
        try:
            stage_a_n = int(market_snapshot.get("stage_a_candidates") or 0)
        except Exception:
            stage_a_n = 0
        if stage_a_n < 10:
            alerts.append(
                {
                    "level": "crit",
                    "key": "coverage_drop",
                    "message": f"stage_a_candidates={stage_a_n} < 10",
                    "ts": int(now_ms),
                    "context": {"market_snapshot": market_snapshot},
                }
            )
        if bool(btc_corr_degraded):
            alerts.append(
                {
                    "level": "crit",
                    "key": "btc_corr_degraded",
                    "message": str(btc_corr_degrade_reason or "btc_corr_degraded"),
                    "ts": int(now_ms),
                    "context": {"market_snapshot": market_snapshot},
                }
            )

        try:
            cs = cluster_consistency if isinstance(cluster_consistency, dict) else {}
            st = str(cs.get("status") or "").strip().lower()
            if st in ("warn", "breakdown"):
                level = "warn" if st == "warn" else "crit"
                reasons = cs.get("reasons")
                if isinstance(reasons, list):
                    reasons_s = [str(x) for x in reasons if str(x).strip()][:8]
                else:
                    reasons_s = []
                msg = f"cluster_consistency={st}" + (f" reasons={reasons_s}" if reasons_s else "")
                alerts.append(
                    {
                        "level": level,
                        "key": "cluster_consistency",
                        "message": msg,
                        "ts": int(now_ms),
                        "context": {"cluster_consistency": cs, "market_snapshot": market_snapshot},
                    }
                )
        except Exception:
            pass

        monitoring_hints = {
            "alerts": alerts,
            "diagnostics": {
                "coverage": market_snapshot,
                "cluster_consistency": (cluster_consistency if isinstance(cluster_consistency, dict) else None),
            },
        }
    except Exception:
        monitoring_hints = None

    # Update State
    UNIVERSE_STATE["last_update"] = now_ms
    UNIVERSE_STATE["core"] = final_core
    UNIVERSE_STATE["shadow"] = final_shadow
    UNIVERSE_STATE["watchlist"] = final_watchlist
    UNIVERSE_STATE["counts"] = {"core": int(len(final_core)), "shadow": int(len(final_shadow)), "watchlist": int(len(final_watchlist))}
    UNIVERSE_STATE["metadata"] = {
        "stage_a_issues": res_a.get("issues"),
        "stage_a_filters": res_a.get("filters"),
        "market_snapshot": market_snapshot,
        "ranking_score": "composite_vol_trend_liq_corr_feedback",
        "dedup_threshold": corr_threshold,
        "scoring_weights": {"vol": 0.2, "trend_mr": 0.3, "liq": 0.4, "corr": 0.1, "feedback": 0.1},
        "top_scores": scored_candidates[:5],
        "churn_protection": "active",
        "candidates": candidates_schema,
        "candidates_ts": int(now_ms),
        "candidates_ttl_ms": int(CONFIG.get("three_screen_candidates_ttl_ms", 900000) or 900000),
        "clustering_hyperparams": cluster_hyperparams,
        "clusters": clusters,
        "cluster_consistency": cluster_consistency,
        "monitoring_hints": monitoring_hints,
        "btc_corr_coverage": (market_snapshot.get("btc_corr_coverage") if isinstance(market_snapshot, dict) else None),
        "btc_corr_degraded": bool(btc_corr_degraded),
        "btc_corr_degrade_reason": (None if btc_corr_degrade_reason is None else str(btc_corr_degrade_reason)),
        "pools": pools,
        "selection_hints": selection_hints,
        "trade_whitelist_auto": trade_whitelist_auto,
    }
    
    LOG.info(f"Universe Updated: Core={len(final_core)}, Shadow={len(final_shadow)}, Watchlist={len(final_watchlist)}")


def _hl_mid(coin: str) -> float:
    info = _hl_info()
    cache = HL_STATE.get("mids_cache")
    if not isinstance(cache, dict):
        cache = {}
        HL_STATE["mids_cache"] = cache
    entry = cache.get("")
    now_ms = _now_ms()
    if isinstance(entry, dict):
        try:
            if (int(now_ms) - int(entry.get("ts") or 0)) < 1000 and isinstance(entry.get("mids"), dict):
                px = (entry.get("mids") or {}).get(coin)
                if px is not None:
                    return float(px)
        except Exception:
            pass

    mids = None
    err = None
    try:
        mids = info.all_mids() or {}
    except Exception as e:
        err = e
        if isinstance(entry, dict) and isinstance(entry.get("mids"), dict):
            mids = entry.get("mids") or {}
    if mids is None:
        raise RuntimeError(str(err) if err is not None else "fetch_mids_failed")
    try:
        cache[""] = {"ts": int(now_ms), "mids": dict(mids)}
        HL_STATE["mids_cache"] = cache
    except Exception:
        pass

    px = (mids or {}).get(coin)
    if px is None:
        raise RuntimeError(f"missing_mid:{coin}")
    return float(px)


def _hl_coin_from_pair(pair: str) -> str:
    p = str(pair or "").strip().upper()
    if not p:
        raise RuntimeError("missing_pair")
    if ":" in p:
        p = p.split(":", 1)[0].strip()
    if "/" in p:
        return p.split("/", 1)[0]
    if "_" in p:
        return p.split("_", 1)[0]
    if "-" in p:
        return p.split("-", 1)[0]
    if p.endswith("USDT"):
        return p[:-4]
    if p.endswith("USDC"):
        return p[:-4]
    return p


class Intent(TypedDict, total=False):
    owner: Literal["strategy", "quant"]
    venue: str
    underlying: str
    pair: str
    side: Literal["long", "short"]
    action: Literal["open", "close", "reduce", "hold"]
    ts: int
    timeframe: str
    bar_open_ms: int
    score: float
    desired_notional_usdc: float
    owner_contrib: Dict[str, float]
    reason: str
    tag: str
    strategy_id: str
    event_id: str


def _intent_underlying_from_pair(venue: str, pair: str) -> str:
    v = str(venue or "").strip().lower()
    p = str(pair or "").strip()
    if not p:
        return ""
    if v == "hyperliquid":
        try:
            return str(_hl_coin_from_pair(p) or "").upper().strip()
        except Exception:
            return str(p).upper().split("-", 1)[0].split("/", 1)[0].strip()
    return str(p).upper().split("/", 1)[0].split(":", 1)[0].split("-", 1)[0].strip()


def _intent_bar_open_ms(ts_ms: int, timeframe: str) -> int:
    t = int(ts_ms or 0)
    if t <= 0:
        return 0
    tf = str(timeframe or "").strip().lower()
    if not tf:
        return int(t)
    try:
        tf_ms = int(_hl_interval_to_ms(tf))
    except Exception:
        tf_ms = 0
    if tf_ms <= 0:
        return int(t)
    return int((int(t) // int(tf_ms)) * int(tf_ms))


def _intent_score_from_signal_event(evt: Dict[str, Any]) -> Optional[float]:
    if not isinstance(evt, dict):
        return None
    c = evt.get("confidence")
    try:
        if c is not None and math.isfinite(float(c)):
            return float(_clip(float(c), 0.0, 1.0))
    except Exception:
        pass
    try:
        di = evt.get("decision_info")
        if isinstance(di, dict):
            pc = di.get("pc")
            if pc is not None and math.isfinite(float(pc)):
                return float(_clip(float(pc), 0.0, 1.0))
    except Exception:
        pass
    return None


def _intent_desired_notional_from_signal_event(evt: Dict[str, Any]) -> Optional[float]:
    if not isinstance(evt, dict):
        return None
    for k in ("desired_notional_usdc", "notional_usdc", "size", "size_usdc"):
        v = evt.get(k)
        try:
            if v is not None and math.isfinite(float(v)) and float(v) > 0.0:
                return float(v)
        except Exception:
            continue
    try:
        di = evt.get("decision_info")
        if isinstance(di, dict):
            out = di.get("out")
            if isinstance(out, dict):
                for k in ("notional_usdc", "size_usdc", "size"):
                    v = out.get(k)
                    if v is not None and math.isfinite(float(v)) and float(v) > 0.0:
                        return float(v)
    except Exception:
        pass
    return None


def _intent_from_signal_event(evt: Dict[str, Any], owner: str = "strategy") -> Optional[Intent]:
    if not isinstance(evt, dict):
        return None
    pair = str(evt.get("pair") or "").strip()
    side = str(evt.get("side") or "").strip().lower()
    action0 = str(evt.get("action") or "open").strip().lower()
    tf = str(evt.get("timeframe") or "").strip().lower()
    try:
        ts_ms = int(evt.get("ts") or 0)
    except Exception:
        ts_ms = 0
    try:
        bar_open_ms = int(evt.get("bar_open_ms") or 0)
    except Exception:
        bar_open_ms = 0
    if bar_open_ms <= 0 and ts_ms > 0:
        bar_open_ms = _intent_bar_open_ms(ts_ms=ts_ms, timeframe=tf)
    venue = str(evt.get("venue") or CONFIG.get("execution_venue", "hyperliquid") or "hyperliquid").strip().lower() or "hyperliquid"
    underlying = _intent_underlying_from_pair(venue=venue, pair=pair)

    if action0 == "observe":
        action = "hold"
    elif action0 in ("open", "close"):
        action = action0
    else:
        action = "open"

    if side not in ("long", "short") and action != "hold":
        return None

    intent: Intent = {
        "owner": ("quant" if str(owner).strip().lower() == "quant" else "strategy"),
        "venue": venue,
        "underlying": underlying,
        "pair": pair,
        "action": action,
        "ts": int(ts_ms or 0),
        "timeframe": tf,
        "bar_open_ms": int(bar_open_ms or 0),
    }
    if side in ("long", "short"):
        intent["side"] = side  # type: ignore
    sc = _intent_score_from_signal_event(evt)
    if sc is not None:
        intent["score"] = float(sc)
    dn = _intent_desired_notional_from_signal_event(evt)
    if dn is not None:
        intent["desired_notional_usdc"] = float(dn)
    try:
        r0 = evt.get("reason")
        if r0 is None:
            di = evt.get("decision_info")
            if isinstance(di, dict):
                out = di.get("out")
                if isinstance(out, dict):
                    r0 = out.get("reason")
        if r0 is not None and str(r0).strip() != "":
            intent["reason"] = str(r0)
    except Exception:
        pass
    try:
        if evt.get("tag") is not None:
            intent["tag"] = str(evt.get("tag"))
    except Exception:
        pass
    try:
        if evt.get("strategy_id") is not None:
            intent["strategy_id"] = str(evt.get("strategy_id"))
    except Exception:
        pass
    try:
        if evt.get("event_id") is not None:
            intent["event_id"] = str(evt.get("event_id"))
        elif evt.get("id") is not None:
            intent["event_id"] = str(evt.get("id"))
    except Exception:
        pass
    return intent


def _intent_from_quant_status(status: Dict[str, Any], owner: str = "quant") -> List[Intent]:
    if not isinstance(status, dict):
        return []
    owner0 = ("quant" if str(owner).strip().lower() == "quant" else "strategy")
    venue = str(CONFIG.get("execution_venue", "hyperliquid") or "hyperliquid").strip().lower() or "hyperliquid"
    tf = str(status.get("timeframe") or "").strip().lower()
    try:
        ts_ms = int(status.get("ts") or 0)
    except Exception:
        ts_ms = 0
    bar_open_ms = 0
    try:
        latest = status.get("latest")
        if isinstance(latest, dict) and latest.get("ts") is not None:
            bar_open_ms = int(latest.get("ts") or 0)
    except Exception:
        bar_open_ms = 0
    if bar_open_ms <= 0 and ts_ms > 0:
        bar_open_ms = _intent_bar_open_ms(ts_ms=ts_ms, timeframe=tf)

    desired = None
    try:
        cost = status.get("cost")
        if isinstance(cost, dict) and cost.get("notional_usdc") is not None:
            desired = float(cost.get("notional_usdc"))
    except Exception:
        desired = None
    if desired is None:
        try:
            desired = float(status.get("notional_usdc")) if status.get("notional_usdc") is not None else None
        except Exception:
            desired = None
    if desired is not None and ((not math.isfinite(float(desired))) or float(desired) <= 0.0):
        desired = None

    score = None
    try:
        latest = status.get("latest")
        if isinstance(latest, dict) and latest.get("z") is not None:
            z = float(latest.get("z"))
            if math.isfinite(float(z)):
                score = float(_clip(abs(float(z)) / 5.0, 0.0, 1.0))
    except Exception:
        score = None

    action0 = str(status.get("action") or "hold").strip().lower()
    reason = None
    try:
        r = status.get("reason")
        if r is not None:
            reason = str(r)
    except Exception:
        reason = None

    intents: List[Intent] = []

    if action0 in ("exit", "stop"):
        legs = None
        try:
            pos = status.get("position")
            if isinstance(pos, dict):
                legs = pos.get("legs")
        except Exception:
            legs = None
        if isinstance(legs, dict) and legs:
            for leg in legs.values():
                if not isinstance(leg, dict):
                    continue
                pair = str(leg.get("pair") or "").strip() or ""
                side = str(leg.get("side") or "").strip().lower()
                if not pair or side not in ("long", "short"):
                    continue
                underlying = _intent_underlying_from_pair(venue=venue, pair=pair)
                it: Intent = {
                    "owner": owner0,
                    "venue": venue,
                    "underlying": underlying,
                    "pair": pair,
                    "side": side,  # type: ignore
                    "action": "close",
                    "ts": int(ts_ms or 0),
                    "timeframe": tf,
                    "bar_open_ms": int(bar_open_ms or 0),
                }
                if desired is not None:
                    it["desired_notional_usdc"] = float(desired)
                if score is not None:
                    it["score"] = float(score)
                if reason is not None:
                    it["reason"] = str(reason)
                intents.append(it)
        return intents

    if action0 in ("hold", "pause"):
        it2: Intent = {
            "owner": owner0,
            "venue": venue,
            "underlying": "",
            "pair": "",
            "action": "hold",
            "ts": int(ts_ms or 0),
            "timeframe": tf,
            "bar_open_ms": int(bar_open_ms or 0),
        }
        if reason is not None:
            it2["reason"] = str(reason)
        intents.append(it2)
        return intents

    if action0 in ("long_btc_short_eth", "short_btc_long_eth"):
        mapping = {
            "long_btc_short_eth": [("BTC-PERP", "long"), ("ETH-PERP", "short")],
            "short_btc_long_eth": [("BTC-PERP", "short"), ("ETH-PERP", "long")],
        }
        for pair, side in mapping.get(action0, []):
            underlying = _intent_underlying_from_pair(venue=venue, pair=pair)
            it3: Intent = {
                "owner": owner0,
                "venue": venue,
                "underlying": underlying,
                "pair": pair,
                "side": side,  # type: ignore
                "action": "open",
                "ts": int(ts_ms or 0),
                "timeframe": tf,
                "bar_open_ms": int(bar_open_ms or 0),
            }
            if desired is not None:
                it3["desired_notional_usdc"] = float(desired)
            if score is not None:
                it3["score"] = float(score)
            if reason is not None:
                it3["reason"] = str(reason)
            intents.append(it3)
        return intents

    return intents


def _ab_norm_owner(owner: Any) -> str:
    o = str(owner or "").strip().lower()
    if not o:
        return "strategy"
    try:
        o2 = o.replace("-", "_")
        if "threescreen" in o2.replace("_", "") or o2.startswith(("three_screen", "threescreen")):
            return "three_screen"
    except Exception:
        pass
    if o == "quant" or o.startswith(("quant_", "quant-", "quant/")):
        return "quant"
    if o == "carry" or o.startswith(("carry_", "carry-", "carry/")):
        return "carry"
    if o == "strategy" or o.startswith(("strategy_", "strategy-", "strategy/")):
        return "strategy"
    return "strategy"


def _ab_norm_owner_or_empty(owner: Any) -> str:
    try:
        s = str(owner or "").strip()
    except Exception:
        s = ""
    if not s:
        return ""
    try:
        return str(_ab_norm_owner(s))
    except Exception:
        return ""


def _execution_account_id_for_book(book_id: Any, venue: Any = None) -> Optional[str]:
    b = _ab_norm_owner(book_id)
    v = str(venue or "").strip().lower()
    try:
        m = CONFIG.get("book_execution_account_id")
        if isinstance(m, dict):
            vv = m.get(b)
            if vv is not None:
                s = str(vv).strip()
                return s or None
    except Exception:
        pass
    try:
        m2 = CONFIG.get("book_execution_account_id_by_venue")
        if isinstance(m2, dict):
            vv2 = m2.get(b)
            if isinstance(vv2, dict):
                vv3 = vv2.get(v) if v else None
                if vv3 is not None:
                    s = str(vv3).strip()
                    return s or None
    except Exception:
        pass
    keys: List[str] = []
    if v:
        keys.append(f"{b}_execution_account_id_{v}")
        keys.append(f"book_{b}_execution_account_id_{v}")
    keys.append(f"{b}_execution_account_id")
    keys.append(f"book_{b}_execution_account_id")
    for k in keys:
        try:
            vv = CONFIG.get(k)
            if vv is not None:
                s = str(vv).strip()
                if s:
                    return s
        except Exception:
            continue
    try:
        vv = str(v).strip().lower() or "default"
    except Exception:
        vv = "default"
    try:
        bb = str(b).strip().lower() if b is not None else ""
    except Exception:
        bb = ""
    if bb:
        return f"book:{bb}@{vv}"
    return None


def _execution_account_id_for_record(book_id: Any, venue: Any = None) -> str:
    b = _ab_norm_owner(book_id)
    v = str(venue or "").strip().lower() or "default"
    try:
        eid = _execution_account_id_for_book(b, venue=v)
    except Exception:
        eid = None
    if eid is not None:
        try:
            s = str(eid).strip()
        except Exception:
            s = ""
        if s:
            return s
    return f"book:{b}@{v}"


