def _ab_open_positions_index() -> Tuple[Dict[str, Dict[str, Any]], Dict[str, Dict[str, Any]]]:
    by_order_id: Dict[str, Dict[str, Any]] = {}
    by_event_id: Dict[str, Dict[str, Any]] = {}
    ops: List[Dict[str, Any]] = []
    try:
        op0 = TRACKER_STATE.get("open_positions")
        if isinstance(op0, dict) and op0:
            ops.append(op0)
    except Exception:
        pass
    try:
        op1 = TRACKER_STATE.get("quant_open_positions")
        if isinstance(op1, dict) and op1:
            ops.append(op1)
    except Exception:
        pass
    try:
        op2 = TRACKER_STATE.get("carry_open_positions")
        if isinstance(op2, dict) and op2:
            ops.append(op2)
    except Exception:
        pass
    try:
        op3 = TRACKER_STATE.get("three_screen_open_positions")
        if isinstance(op3, dict) and op3:
            ops.append(op3)
    except Exception:
        pass
    if not ops:
        return by_order_id, by_event_id

    def _record(oid: Any, eid: Any, ab_owner: Any, owner_contrib: Any) -> None:
        try:
            oid_s = str(oid).strip()
        except Exception:
            oid_s = ""
        try:
            eid_s = str(eid).strip()
        except Exception:
            eid_s = ""
        rec: Dict[str, Any] = {}
        if ab_owner is not None:
            try:
                rec["ab_owner"] = str(ab_owner)
            except Exception:
                pass
        if isinstance(owner_contrib, dict) and owner_contrib:
            try:
                rec["owner_contrib"] = dict(owner_contrib)
            except Exception:
                pass
        if not rec:
            return
        if oid_s:
            by_order_id.setdefault(oid_s, {}).update(rec)
        if eid_s:
            by_event_id.setdefault(eid_s, {}).update(rec)

    for op in ops:
        for pos in op.values():
            if not isinstance(pos, dict):
                continue
            legs = pos.get("legs")
            if isinstance(legs, list) and legs:
                for leg in legs:
                    if not isinstance(leg, dict):
                        continue
                    _record(
                        oid=leg.get("order_id"),
                        eid=leg.get("event_id"),
                        ab_owner=(leg.get("ab_owner") if leg.get("ab_owner") is not None else pos.get("ab_owner")),
                        owner_contrib=(leg.get("owner_contrib") if leg.get("owner_contrib") is not None else pos.get("owner_contrib")),
                    )
            _record(
                oid=pos.get("order_id"),
                eid=pos.get("event_id"),
                ab_owner=pos.get("ab_owner"),
                owner_contrib=pos.get("owner_contrib"),
            )
            base_oid = pos.get("base_order_id")
            if base_oid is not None:
                _record(
                    oid=base_oid,
                    eid=pos.get("base_event_id"),
                    ab_owner=pos.get("ab_owner"),
                    owner_contrib=pos.get("owner_contrib"),
                )
    return by_order_id, by_event_id


def _ab_settlement_index() -> Dict[str, Any]:
    by_order_id: Dict[str, Any] = {}
    for r in (_ab_settlements_get() or []):
        if not isinstance(r, dict):
            continue
        oid = r.get("order_id")
        if oid is None:
            continue
        try:
            oid_s = str(oid).strip()
        except Exception:
            oid_s = ""
        if not oid_s:
            continue
        owner = _ab_norm_owner(r.get("owner"))
        try:
            pnl = float(r.get("pnl_usdc") or 0.0)
        except Exception:
            pnl = 0.0
        fees = None
        try:
            if r.get("fees_usdc") is not None:
                fees = float(r.get("fees_usdc") or 0.0)
            elif r.get("fee_abs") is not None:
                fees = float(r.get("fee_abs") or 0.0)
            elif r.get("fees_u") is not None:
                fees = float(r.get("fees_u") or 0.0)
        except Exception:
            fees = None
        funding = None
        try:
            if r.get("funding_usdc") is not None:
                funding = float(r.get("funding_usdc") or 0.0)
            elif r.get("funding_abs") is not None:
                funding = float(r.get("funding_abs") or 0.0)
            elif r.get("funding_u") is not None:
                funding = float(r.get("funding_u") or 0.0)
        except Exception:
            funding = None
        try:
            no = float(r.get("notional_usdc") or 0.0)
        except Exception:
            no = 0.0

        rec = by_order_id.get(oid_s)
        if not isinstance(rec, dict):
            rec = {
                "pnl_by_owner": {"strategy": 0.0, "quant": 0.0, "carry": 0.0},
                "fees_by_owner": {"strategy": 0.0, "quant": 0.0, "carry": 0.0},
                "funding_by_owner": {"strategy": 0.0, "quant": 0.0, "carry": 0.0},
                "notional_by_owner": {"strategy": 0.0, "quant": 0.0, "carry": 0.0},
                "last_ts": 0,
            }
            by_order_id[oid_s] = rec

        pnl_by_owner = rec.get("pnl_by_owner")
        if not isinstance(pnl_by_owner, dict):
            pnl_by_owner = {"strategy": 0.0, "quant": 0.0, "carry": 0.0}
            rec["pnl_by_owner"] = pnl_by_owner
        fees_by_owner = rec.get("fees_by_owner")
        if not isinstance(fees_by_owner, dict):
            fees_by_owner = {"strategy": 0.0, "quant": 0.0, "carry": 0.0}
            rec["fees_by_owner"] = fees_by_owner
        funding_by_owner = rec.get("funding_by_owner")
        if not isinstance(funding_by_owner, dict):
            funding_by_owner = {"strategy": 0.0, "quant": 0.0, "carry": 0.0}
            rec["funding_by_owner"] = funding_by_owner
        notional_by_owner = rec.get("notional_by_owner")
        if not isinstance(notional_by_owner, dict):
            notional_by_owner = {"strategy": 0.0, "quant": 0.0, "carry": 0.0}
            rec["notional_by_owner"] = notional_by_owner

        try:
            pnl_by_owner[owner] = float(pnl_by_owner.get(owner, 0.0) or 0.0) + float(pnl)
        except Exception:
            pass
        if fees is not None:
            try:
                fees_by_owner[owner] = float(fees_by_owner.get(owner, 0.0) or 0.0) + float(fees)
            except Exception:
                pass
        if funding is not None:
            try:
                funding_by_owner[owner] = float(funding_by_owner.get(owner, 0.0) or 0.0) + float(funding)
            except Exception:
                pass
        try:
            notional_by_owner[owner] = float(notional_by_owner.get(owner, 0.0) or 0.0) + float(no)
        except Exception:
            pass
        try:
            ts0 = int(r.get("ts") or 0)
        except Exception:
            ts0 = 0
        try:
            if ts0 > int(rec.get("last_ts") or 0):
                rec["last_ts"] = int(ts0)
        except Exception:
            pass
    return by_order_id


