def _paramopt_scenario_rule_engine(*, trigger_event: str, presets: List[str], stages: List[Dict[str, Any]], preset_selection: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    pset = {str(x).strip().lower() for x in (presets if isinstance(presets, list) else []) if str(x).strip()}
    trig = str(trigger_event or "").strip().lower()
    hard_fails: List[str] = []
    route_counts: Dict[str, int] = {}
    for stg in (stages if isinstance(stages, list) else []):
        if not isinstance(stg, dict):
            continue
        r0 = stg.get("result") if isinstance(stg.get("result"), dict) else {}
        a0 = r0.get("apply") if isinstance(r0.get("apply"), dict) else {}
        route = str(a0.get("mode") or "").strip() or "unknown"
        route_counts[route] = int(route_counts.get(route, 0)) + 1
        pol = r0.get("policy_auto_approval") if isinstance(r0.get("policy_auto_approval"), dict) else {}
        hfs = [str(x).strip() for x in (pol.get("hard_fails") if isinstance(pol.get("hard_fails"), list) else []) if str(x).strip()]
        hard_fails.extend(hfs)
    cause_codes = [str(x).strip().lower() for x in ((preset_selection or {}).get("cause_codes") if isinstance((preset_selection or {}).get("cause_codes"), list) else []) if str(x).strip()]
    has = lambda k: (str(k).strip().lower() in pset)
    has_o1 = has("o1")
    has_o2 = has("o2")
    has_o3 = has("o3")
    has_o4 = has("o4")
    has_o5 = has("o5")
    has_o6 = has("o6")
    has_o7 = has("o7")
    hit_exec = bool(("order_fail_rate" in hard_fails) or ("gates_not_passed" in hard_fails) or any(("exec" in x or "http" in x or "429" in x) for x in cause_codes))
    hit_exit = bool(has_o4 or has_o5)
    hit_systemic = bool(has_o7 or len(pset) >= 3)
    hit_macro = bool(has_o3 and (not hit_systemic))
    hit_quant_gen = bool(has_o2 and trig == "trade.cycle.trigger")
    hit_cost_exec = bool(has_o6 and (trig == "pnl.drawdown.trigger" or hit_exec))
    hit_freq = bool(has_o6 and trig == "trade.cycle.trigger")
    rules: List[Dict[str, Any]] = []
    if hit_systemic:
        rules.append({"rule_id": "R_G_SYSTEMIC", "scenario": "G", "why": "o7_or_multi_module", "signals": {"modules_n": int(len(pset)), "has_o7": bool(has_o7)}})
    if hit_exec:
        rules.append({"rule_id": "R_E_EXEC_ISSUE", "scenario": "E", "why": "execution_or_gate_fail", "signals": {"hard_fails": hard_fails[:8], "cause_codes": cause_codes[:8]}})
    if hit_exit:
        rules.append({"rule_id": "R_C_EXIT", "scenario": "C", "why": "exit_module_selected", "signals": {"has_o4": bool(has_o4), "has_o5": bool(has_o5)}})
    if hit_macro:
        rules.append({"rule_id": "R_D_REGIME", "scenario": "D", "why": "macro_overlay_selected", "signals": {"has_o3": bool(has_o3)}})
    if hit_quant_gen:
        rules.append({"rule_id": "R_F_QUANT_GEN", "scenario": "F", "why": "quant_cycle_trigger", "signals": {"trigger_event": str(trig)}})
    if hit_cost_exec:
        rules.append({"rule_id": "R_E_COST_EXEC", "scenario": "E", "why": "o6_with_drawdown_or_exec", "signals": {"trigger_event": str(trig), "has_o6": bool(has_o6)}})
    if hit_freq:
        rules.append({"rule_id": "R_B_FREQ", "scenario": "B", "why": "trade_cycle_with_o6", "signals": {"trigger_event": str(trig)}})
    if has_o1 or has_o2:
        rules.append({"rule_id": "R_A_ALPHA", "scenario": "A", "why": "entry_module_selected", "signals": {"has_o1": bool(has_o1), "has_o2": bool(has_o2)}})
    pri = {"G": 7, "E": 6, "C": 5, "D": 4, "F": 3, "B": 2, "A": 1}
    best = None
    for r in rules:
        sc = str(r.get("scenario") or "A")
        if best is None or int(pri.get(sc, 0)) > int(pri.get(str(best.get("scenario") or "A"), 0)):
            best = r
    if best is None:
        best = {"rule_id": "R_A_DEFAULT", "scenario": "A", "why": "fallback", "signals": {"trigger_event": str(trig), "presets": sorted(list(pset))}}
        rules.append(best)
    scen_title = {
        "A": "收益/风险退化",
        "B": "交易频率异常",
        "C": "出场行为异常",
        "D": "宏观/状态漂移",
        "E": "成本/执行退化",
        "F": "Quant泛化退化",
        "G": "系统级耦合",
    }
    sc0 = str(best.get("scenario") or "A")
    return {
        "scenario": sc0,
        "title": str(scen_title.get(sc0, "")),
        "rule_id": str(best.get("rule_id") or ""),
        "why": str(best.get("why") or ""),
        "route_counts": route_counts,
        "evidence": {"matched_rules": rules[:12], "hard_fails": hard_fails[:20], "cause_codes": cause_codes[:20], "trigger_event": str(trig), "presets": sorted(list(pset))},
    }


def _paramopt_scenario_targets_default() -> List[str]:
    return ["A", "B", "C", "D", "E", "F", "G"]


def _paramopt_scenario_target_plan(scenario: str) -> Dict[str, Any]:
    sc = str(scenario or "").strip().upper() or "A"
    if sc == "B":
        return {"scenario": "B", "trigger_event": "trade.cycle.trigger", "presets": ["o6"]}
    if sc == "C":
        return {"scenario": "C", "trigger_event": "loss.streak.trigger", "presets": ["o4"]}
    if sc == "D":
        return {"scenario": "D", "trigger_event": "loss.streak.trigger", "presets": ["o3"]}
    if sc == "E":
        return {"scenario": "E", "trigger_event": "pnl.drawdown.trigger", "presets": ["o6"]}
    if sc == "F":
        return {"scenario": "F", "trigger_event": "trade.cycle.trigger", "presets": ["o2"]}
    if sc == "G":
        return {"scenario": "G", "trigger_event": "loss.streak.trigger", "presets": ["o7"]}
    return {"scenario": "A", "trigger_event": "loss.streak.trigger", "presets": ["o1"]}


def _paramopt_ops_scenario_counts(ops_view: Dict[str, Any]) -> Dict[str, int]:
    out = {k: 0 for k in _paramopt_scenario_targets_default()}
    items = ops_view.get("scenario_share") if isinstance(ops_view, dict) and isinstance(ops_view.get("scenario_share"), list) else []
    for it in items:
        if not isinstance(it, dict):
            continue
        sc = str(it.get("scenario") or "").strip().upper()
        try:
            cnt = int(it.get("count") or 0)
        except Exception:
            cnt = 0
        if sc:
            out[sc] = int(out.get(sc, 0)) + int(cnt)
    return out


def _paramopt_chain_best_stage(chain_out: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    out0 = chain_out if isinstance(chain_out, dict) else {}
    stages = out0.get("stages") if isinstance(out0.get("stages"), list) else []
    best = None
    best_good = False
    best_score = None
    for stg in stages:
        if not isinstance(stg, dict):
            continue
        r0 = stg.get("result") if isinstance(stg.get("result"), dict) else {}
        good = _paramopt_stage_good_enough(r0)
        score = _to_float(((r0.get("best") if isinstance(r0.get("best"), dict) else {}).get("max")))
        if best is None:
            best = stg
            best_good = bool(good)
            best_score = score
            continue
        if bool(good) and (not bool(best_good)):
            best = stg
            best_good = True
            best_score = score
            continue
        if bool(good) == bool(best_good):
            if score is not None and (best_score is None or float(score) > float(best_score)):
                best = stg
                best_good = bool(good)
                best_score = score
    return best


def _paramopt_patch_change_rows(*, patch: Dict[str, Any], before: Optional[Dict[str, Any]] = None, mode: str = "after") -> List[Dict[str, Any]]:
    p0 = patch if isinstance(patch, dict) else {}
    b0 = before if isinstance(before, dict) else {}
    out: List[Dict[str, Any]] = []
    keys = [str(k) for k in p0.keys() if str(k).strip()]
    keys.sort()
    for k in keys:
        v_after = p0.get(k)
        v_before = (b0.get(k) if k in b0 else CONFIG.get(k))
        delta = None
        try:
            if isinstance(v_before, (int, float)) and isinstance(v_after, (int, float)):
                delta = float(v_after) - float(v_before)
        except Exception:
            delta = None
        row = {"key": str(k), "before": _json_sanitize(v_before), str(mode): _json_sanitize(v_after), "delta": (None if delta is None else float(delta))}
        out.append(row)
    return out


def _paramopt_scenarios_satisfaction_from_outbox(*, scenarios: List[str], max_runs: int = 400, max_lines: int = 60000, max_bytes: int = 12_000_000) -> Dict[str, Any]:
    sc_set = {str(x).strip().upper() for x in (scenarios if isinstance(scenarios, list) else []) if str(x).strip()}
    if not sc_set:
        sc_set = set(_paramopt_scenario_targets_default())
    satisfied = {k: False for k in sc_set}
    latest_good: Dict[str, Any] = {}
    latest_any: Dict[str, Any] = {}
    outbox = _agent_outbox_dir()
    cand: List[Path] = []
    try:
        p0 = outbox / "chat.jsonl"
        if p0.exists() and p0.is_file():
            cand.append(p0)
    except Exception:
        pass
    try:
        others = [p for p in outbox.glob("chat._*.jsonl") if p.is_file()]
        others.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others)
    except Exception:
        pass
    try:
        others = [p for p in outbox.glob("chat_*.jsonl") if p.is_file()]
        others.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others)
    except Exception:
        pass
    try:
        others_gz = [p for p in outbox.glob("chat._*.jsonl.gz") if p.is_file()]
        others_gz.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others_gz)
    except Exception:
        pass
    try:
        others_gz = [p for p in outbox.glob("chat_*.jsonl.gz") if p.is_file()]
        others_gz.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others_gz)
    except Exception:
        pass
    if not cand:
        return {"ok": True, "satisfied": satisfied, "latest_good": latest_good, "latest_any": latest_any}
    max_runs = max(10, min(2000, int(max_runs)))
    max_lines = max(1000, int(max_lines))
    max_bytes = max(1_000_000, int(max_bytes))
    max_files = 24
    seen = 0

    def _file_lines_tail(fp: Path) -> List[str]:
        try:
            if str(fp).lower().endswith(".gz"):
                return _tail_lines_gzip(fp, max_lines=max_lines)
            return _tail_lines(fp, max_lines=max_lines, max_bytes=max_bytes)
        except Exception:
            return []

    for fp in cand[:max_files]:
        lines = _file_lines_tail(fp)
        for s in reversed(lines):
            if seen >= int(max_runs):
                break
            try:
                obj = json.loads((s or "").strip())
            except Exception:
                continue
            if not isinstance(obj, dict):
                continue
            if str(obj.get("type") or "").strip() != "automation.paramopt.trigger":
                continue
            res = obj.get("result") if isinstance(obj.get("result"), dict) else {}
            presets = [str(x).strip().lower() for x in ((res.get("presets") if isinstance(res.get("presets"), list) else [])) if str(x).strip()]
            stages = res.get("stages") if isinstance(res.get("stages"), list) else []
            trig = str(res.get("trigger_event") or obj.get("trigger_event") or "").strip()
            cls = _paramopt_scenario_rule_engine(
                trigger_event=str(trig),
                presets=presets,
                stages=[x for x in stages if isinstance(x, dict)],
                preset_selection=(res.get("preset_selection") if isinstance(res.get("preset_selection"), dict) else None),
            )
            sc = str(cls.get("scenario") or "A").strip().upper() or "A"
            if sc not in sc_set:
                continue
            seen += 1
            good = False
            best_stage = _paramopt_chain_best_stage(res if isinstance(res, dict) else {})
            if isinstance(best_stage, dict):
                r0 = best_stage.get("result") if isinstance(best_stage.get("result"), dict) else {}
                good = _paramopt_stage_good_enough(r0)
            ent = {"trace_id": str(obj.get("trace_id") or ""), "ts": _to_int(obj.get("ts")) or 0, "scenario": sc, "trigger_event": trig, "presets": presets, "best_stage": _json_sanitize(best_stage), "good": bool(good)}
            if sc not in latest_any:
                latest_any[sc] = ent
            if bool(good) and (sc not in latest_good):
                latest_good[sc] = ent
                satisfied[sc] = True
            if all(bool(v) for v in satisfied.values()):
                break
        if seen >= int(max_runs) or all(bool(v) for v in satisfied.values()):
            break
    return {"ok": True, "satisfied": satisfied, "latest_good": latest_good, "latest_any": latest_any}


def _paramopt_run_chain_for_presets(
    *,
    trace_id: str,
    now_ms: int,
    trigger_event: str,
    presets: List[str],
    source: str,
    scenario_target: Optional[str],
    budget: Optional[Dict[str, Any]] = None,
    context_extra: Optional[Dict[str, Any]] = None,
    emit_chat_type: str = "automation.paramopt.trigger",
) -> Tuple[Dict[str, Any], int]:
    trig = str(trigger_event or "").strip() or "manual"
    base_trace_id = str((context_extra or {}).get("base_trace_id") or "").strip() or str(trace_id)
    tid = str(trace_id or "").strip() or uuid.uuid4().hex
    day = ""
    try:
        day = datetime.fromtimestamp(int(now_ms) / 1000.0, tz=timezone.utc).strftime("%Y-%m-%d")
    except Exception:
        day = ""

    b0 = (budget if isinstance(budget, dict) else {})
    preset = str(AUTOMATION.get("paramopt_daily_preset", "o6") or "o6").strip()
    family = str(AUTOMATION.get("paramopt_daily_family", EVAL_MODELS.get("active_family") or "xgb") or "xgb").strip().lower() or "xgb"
    eval_mode = str(AUTOMATION.get("paramopt_daily_eval_mode", "rolling") or "rolling").strip().lower() or "rolling"
    if eval_mode not in ("rolling", "backtest"):
        eval_mode = "rolling"
    try:
        folds = int(b0.get("folds") if b0.get("folds") is not None else (AUTOMATION.get("paramopt_daily_folds", 5) or 5))
    except Exception:
        folds = 5
    folds = max(3, min(12, int(folds)))
    try:
        n_init = int(b0.get("n_init") if b0.get("n_init") is not None else (AUTOMATION.get("paramopt_daily_n_init", 8) or 8))
    except Exception:
        n_init = 8
    try:
        n_iter = int(b0.get("n_iter") if b0.get("n_iter") is not None else (AUTOMATION.get("paramopt_daily_n_iter", 24) or 24))
    except Exception:
        n_iter = 24
    n_init = max(0, min(50, int(n_init)))
    n_iter = max(1, min(200, int(n_iter)))
    try:
        topk = int(b0.get("topk") if b0.get("topk") is not None else (AUTOMATION.get("paramopt_daily_topk", 3) or 3))
    except Exception:
        topk = 3
    topk = max(1, min(10, int(topk)))
    try:
        stage_n_init_ratio = float(b0.get("stage_n_init_ratio") if b0.get("stage_n_init_ratio") is not None else (AUTOMATION.get("paramopt_loss_check_stage_n_init_ratio", 0.5) or 0.5))
    except Exception:
        stage_n_init_ratio = 0.5
    try:
        stage_n_iter_ratio = float(b0.get("stage_n_iter_ratio") if b0.get("stage_n_iter_ratio") is not None else (AUTOMATION.get("paramopt_loss_check_stage_n_iter_ratio", 0.35) or 0.35))
    except Exception:
        stage_n_iter_ratio = 0.35
    stage_n_init_ratio = float(max(0.1, min(1.0, float(stage_n_init_ratio))))
    stage_n_iter_ratio = float(max(0.1, min(1.0, float(stage_n_iter_ratio))))

    ladder_enabled = bool(b0.get("ladder_enabled") if b0.get("ladder_enabled") is not None else AUTOMATION.get("paramopt_ladder_enabled", True))
    ladder_stop_on_good = bool(b0.get("ladder_stop_on_good") if b0.get("ladder_stop_on_good") is not None else AUTOMATION.get("paramopt_ladder_stop_on_good", True))
    round_factors = _paramopt_ladder_round_factors() if ladder_enabled else [1.0]

    auto_draft = bool(b0.get("auto_draft") if b0.get("auto_draft") is not None else AUTOMATION.get("paramopt_daily_auto_draft", True))
    skip_robustness = bool(b0.get("skip_robustness") if b0.get("skip_robustness") is not None else AUTOMATION.get("paramopt_daily_skip_robustness", False))
    include_suggest_only = bool(b0.get("include_suggest_only") if b0.get("include_suggest_only") is not None else AUTOMATION.get("paramopt_daily_include_suggest_only", True))
    reject_on_hard_fail = bool(b0.get("reject_on_hard_fail") if b0.get("reject_on_hard_fail") is not None else False)
    no_manual_approval = bool(b0.get("no_manual_approval") if b0.get("no_manual_approval") is not None else False)

    try:
        policy_relax_ratio = float(b0.get("policy_relax_ratio") if b0.get("policy_relax_ratio") is not None else (AUTOMATION.get("paramopt_loss_policy_relax_ratio", 0.90) or 0.90))
    except Exception:
        policy_relax_ratio = 0.90
    try:
        policy_min_rel_improvement = float(b0.get("policy_min_rel_improvement") if b0.get("policy_min_rel_improvement") is not None else (AUTOMATION.get("paramopt_loss_policy_min_rel_improvement", 0.0) or 0.0))
    except Exception:
        policy_min_rel_improvement = 0.0

    presets2 = [str(x).strip().lower() for x in (presets if isinstance(presets, list) else []) if str(x).strip()]
    presets2 = [p for p in presets2 if p in ("o1", "o2", "o3", "o4", "o5", "o6", "o7")]
    if not presets2:
        presets2 = [str(preset).strip().lower() or "o6"]
    stage_results: List[Dict[str, Any]] = []

    for i, p in enumerate(presets2):
        stage_trace_id = str(tid) if len(presets2) == 1 else hashlib.sha256(f"{tid}|{p}|{i}".encode("utf-8")).hexdigest()[:32]
        stage_n_init = int(max(0, min(50, int(round(float(n_init) * float(stage_n_init_ratio)))))) if len(presets2) > 1 else int(n_init)
        stage_n_iter = int(max(1, min(200, int(round(float(n_iter) * float(stage_n_iter_ratio)))))) if len(presets2) > 1 else int(n_iter)
        round_results: List[Dict[str, Any]] = []
        chosen_out: Optional[Dict[str, Any]] = None
        chosen_code = 0
        chosen_payload: Dict[str, Any] = {}
        best_score = None
        for ridx, rf in enumerate(round_factors):
            r_trace_id = str(stage_trace_id) if len(round_factors) == 1 else hashlib.sha256(f"{stage_trace_id}|round|{ridx + 1}".encode("utf-8")).hexdigest()[:32]
            rn_init = int(max(0, min(200, int(round(float(stage_n_init) * float(rf))))))
            rn_iter = int(max(1, min(500, int(round(float(stage_n_iter) * float(rf))))))
            ctx = {
                "source": str(source),
                "kind": "paramopt_scenario_target" if scenario_target else "paramopt_manual",
                "day": day,
                "trigger_event": str(trig),
                "base_trace_id": str(base_trace_id),
                "trace_group_id": str(tid),
                "scenario_target": (str(scenario_target).strip().upper() if scenario_target else None),
                "preset": str(p),
                "preset_index": int(i + 1),
                "preset_total": int(len(presets2)),
                "policy_relax_ratio": float(policy_relax_ratio),
                "policy_min_rel_improvement": float(policy_min_rel_improvement),
                "ladder_round": int(ridx + 1),
                "ladder_factor": float(rf),
                "ladder_enabled": bool(ladder_enabled),
            }
            if isinstance(context_extra, dict):
                for k, v in context_extra.items():
                    if k not in ctx:
                        ctx[str(k)] = v
            payload: Dict[str, Any] = {
                "trace_id": str(r_trace_id),
                "mode": "sandbox",
                "preset": str(p),
                "family": str(family),
                "eval_mode": str(eval_mode),
                "folds": int(folds),
                "n_init": int(rn_init),
                "n_iter": int(rn_iter),
                "topk": int(topk),
                "include_suggest_only": bool(include_suggest_only),
                "skip_robustness": bool(skip_robustness),
                "auto_draft": bool(auto_draft),
                "reject_on_hard_fail": bool(reject_on_hard_fail),
                "no_manual_approval": bool(no_manual_approval),
                "context": ctx,
                "doc_refs": _agent_doc_refs_48_default(),
            }
            stage_out, stage_code = _automation_local_post_json("/agent/paramopt/run", agent_paramopt_run, payload)
            if stage_out is None:
                stage_out = {"ok": False, "error": "paramopt_no_response", "ts": int(_now_ms()), "trace_id": str(r_trace_id), "http": int(stage_code)}
            score_now = _to_float(((stage_out.get("best") if isinstance(stage_out.get("best"), dict) else {}).get("max")))
            if chosen_out is None:
                chosen_out = stage_out
                chosen_code = int(stage_code)
                chosen_payload = payload
                best_score = score_now
            elif score_now is not None and (best_score is None or float(score_now) > float(best_score)):
                chosen_out = stage_out
                chosen_code = int(stage_code)
                chosen_payload = payload
                best_score = score_now
            round_results.append({"round": int(ridx + 1), "factor": float(rf), "trace_id": str(r_trace_id), "http": int(stage_code), "request": payload, "result": stage_out})
            if bool(ladder_stop_on_good) and _paramopt_stage_good_enough(stage_out):
                chosen_out = stage_out
                chosen_code = int(stage_code)
                chosen_payload = payload
                break
        if chosen_out is None:
            chosen_out = {"ok": False, "error": "paramopt_no_round_result", "ts": int(_now_ms()), "trace_id": str(stage_trace_id)}
        stage_results.append({"preset": str(p), "trace_id": str(chosen_out.get("trace_id") or stage_trace_id), "http": int(chosen_code), "request": chosen_payload, "result": chosen_out, "rounds": round_results})

    chain_ok = all(bool((x.get("result") if isinstance(x.get("result"), dict) else {}).get("ok")) for x in stage_results)
    route_counts: Dict[str, int] = {}
    stage_summaries: List[Dict[str, Any]] = []
    for stg in stage_results:
        sum0 = _paramopt_loss_chain_stage_summary(stg)
        stage_summaries.append(sum0)
        rk = str(sum0.get("route") or "unknown")
        route_counts[rk] = int(route_counts.get(rk, 0)) + 1
    out = {
        "ok": bool(chain_ok),
        "trace_id": str(tid),
        "source": str(source),
        "trigger_event": str(trig),
        "mode": "sandbox",
        "family": str(family),
        "eval_mode": str(eval_mode),
        "presets": presets2,
        "preset_selection": {"ok": True, "mode": "scenario_target" if scenario_target else "manual", "scenario_target": (str(scenario_target).strip().upper() if scenario_target else None)},
        "stages": stage_results,
        "summary": {
            "total": int(len(stage_results)),
            "ok": int(len([x for x in stage_summaries if bool(x.get("ok"))])),
            "failed": int(len([x for x in stage_summaries if not bool(x.get("ok"))])),
            "routes": route_counts,
            "stage_summaries": stage_summaries,
        },
    }
    code = 200 if bool(chain_ok) else 207
    try:
        TRACKER_STATE["paramopt_daily_last"] = {"ts": int(_now_ms()), "trace_id": str(tid), "http": int(code), "out": out}
    except Exception:
        pass
    try:
        _agent_outbox_append_jsonl(
            "chat.jsonl",
            {
                "id": uuid.uuid4().hex,
                "trace_id": str(tid),
                "ts": int(_now_ms()),
                "type": str(emit_chat_type or "automation.paramopt.trigger"),
                "channel": "workflow",
                "request": _json_sanitize({"trigger_event": str(trig), "presets": presets2, "scenario_target": (str(scenario_target).strip().upper() if scenario_target else None)}),
                "http": int(code),
                "result": _json_sanitize(out),
            },
        )
    except Exception:
        pass
    return out, int(code)

_PARAMOPT_OPS_VIEW_CACHE: Dict[str, Any] = {"sig": None, "ts_ms": 0, "value": None}
_PARAMOPT_LAST_WRAP_CACHE: Dict[str, Any] = {"sig": None, "ts_ms": 0, "value": None}


def _agent_outbox_chat_sig(*, outbox: Path, max_files: int = 8) -> str:
    try:
        max_files = int(max_files)
    except Exception:
        max_files = 8
    max_files = max(1, min(64, int(max_files)))
    items: List[Path] = []
    try:
        items = [p for p in outbox.glob("chat*.jsonl*") if p.is_file()]
        items.sort(key=lambda x: x.stat().st_mtime, reverse=True)
    except Exception:
        items = []
    parts: List[str] = []
    for p in items[:max_files]:
        try:
            st = p.stat()
            parts.append(f"{p.name}:{int(st.st_size)}:{int(st.st_mtime * 1000)}")
        except Exception:
            parts.append(str(p.name))
    return "|".join(parts)


def _paramopt_ops_view_recent(
    *,
    max_runs: int = 24,
    max_lines: int = 20000,
    max_bytes: int = 8_000_000,
    trigger_events: Optional[List[str]] = None,
) -> Dict[str, Any]:
    out = {
        "ok": True,
        "window_n": int(max_runs),
        "runs_n": 0,
        "success_rate": None,
        "success_rate_7": None,
        "success_rate_14": None,
        "avg_interval_sec": None,
        "trend": [],
        "scenario_share": [],
        "optimization_share": [],
        "module_share": [],
        "reject_topn": [],
        "market_stance": "balanced",
    }
    outbox = _agent_outbox_dir()
    cand: List[Path] = []
    try:
        p0 = outbox / "chat.jsonl"
        if p0.exists() and p0.is_file():
            cand.append(p0)
    except Exception:
        pass
    try:
        others = [p for p in outbox.glob("chat._*.jsonl") if p.is_file()]
        others.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others)
    except Exception:
        pass
    try:
        others = [p for p in outbox.glob("chat_*.jsonl") if p.is_file()]
        others.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others)
    except Exception:
        pass
    try:
        others_gz = [p for p in outbox.glob("chat._*.jsonl.gz") if p.is_file()]
        others_gz.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others_gz[:2])
    except Exception:
        pass
    try:
        others_gz = [p for p in outbox.glob("chat_*.jsonl.gz") if p.is_file()]
        others_gz.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others_gz[:2])
    except Exception:
        pass
    try:
        uniq = []
        seen = set()
        for p in cand:
            sp = str(p)
            if sp in seen:
                continue
            seen.add(sp)
            uniq.append(p)
        cand = uniq
    except Exception:
        pass
    if not cand:
        return out
    max_runs = max(3, min(200, int(max_runs)))
    max_lines = max(1000, int(max_lines))
    max_bytes = max(1_000_000, int(max_bytes))
    max_files = 4

    runs: List[Dict[str, Any]] = []
    runs_by_trace: Dict[str, Dict[str, Any]] = {}
    need_start: set = set()
    starts: Dict[str, Dict[str, Any]] = {}
    module_cnt: Dict[str, int] = {}
    scenario_cnt: Dict[str, int] = {}
    reject_cnt: Dict[str, int] = {}
    scanned = 0
    scanned_cap = max(2000, int(max_lines) * int(max_files))
    trig_allow: set = {str(x).strip().lower() for x in (trigger_events if isinstance(trigger_events, list) else []) if str(x).strip()}

    def _file_lines_tail(fp: Path) -> List[str]:
        try:
            if str(fp).lower().endswith(".gz"):
                return _tail_lines_gzip(fp, max_lines=max_lines)
            return _tail_lines(fp, max_lines=max_lines, max_bytes=max_bytes)
        except Exception:
            return []

    def _infer_presets_from_start(st: Dict[str, Any]) -> List[str]:
        req = st.get("requested") if isinstance(st.get("requested"), dict) else {}
        preset = req.get("preset")
        if isinstance(preset, str) and preset.strip():
            return [preset.strip().lower()]
        if isinstance(preset, list):
            return [str(x).strip().lower() for x in preset if str(x).strip()]
        presets = req.get("presets")
        if isinstance(presets, list):
            return [str(x).strip().lower() for x in presets if str(x).strip()]
        return []

    def _classify_and_emit_run(*, ts: int, ok: bool, presets: List[str], trig: str, stages: List[Dict[str, Any]], preset_selection: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        cls = _paramopt_scenario_rule_engine(
            trigger_event=str(trig),
            presets=presets,
            stages=[x for x in stages if isinstance(x, dict)],
            preset_selection=(preset_selection if isinstance(preset_selection, dict) else None),
        )
        scen = str(cls.get("scenario") or "A")
        scenario_cnt[scen] = int(scenario_cnt.get(scen, 0)) + 1
        for pz in presets:
            module_cnt[pz] = int(module_cnt.get(pz, 0)) + 1
        for stg in stages:
            if not isinstance(stg, dict):
                continue
            r0 = stg.get("result") if isinstance(stg.get("result"), dict) else {}
            a0 = r0.get("apply") if isinstance(r0.get("apply"), dict) else {}
            mode0 = str(a0.get("mode") or "").strip()
            if mode0 != "policy_auto_rejected":
                continue
            pol = r0.get("policy_auto_approval") if isinstance(r0.get("policy_auto_approval"), dict) else {}
            hfs = [str(x).strip() for x in (pol.get("hard_fails") if isinstance(pol.get("hard_fails"), list) else []) if str(x).strip()]
            if not hfs:
                hfs = [str(pol.get("decision") or "policy_fail").strip() or "policy_fail"]
            for x in hfs:
                reject_cnt[x] = int(reject_cnt.get(x, 0)) + 1
        return {
            "ts": int(ts),
            "ok": bool(ok),
            "presets": presets,
            "trigger_event": str(trig),
            "scenario": str(cls.get("scenario") or "A"),
            "scenario_title": str(cls.get("title") or ""),
            "scenario_rule_id": str(cls.get("rule_id") or ""),
            "scenario_why": str(cls.get("why") or ""),
            "scenario_evidence": (cls.get("evidence") if isinstance(cls.get("evidence"), dict) else {}),
        }

    for fp in cand[:max_files]:
        lines = _file_lines_tail(fp)
        for s in reversed(lines):
            scanned += 1
            if scanned > scanned_cap:
                break
            if len(runs) >= int(max_runs) and (not need_start):
                break
            try:
                obj = json.loads((s or "").strip())
            except Exception:
                continue
            if not isinstance(obj, dict):
                continue
            tp = str(obj.get("type") or "").strip()
            tid = str(obj.get("trace_id") or "").strip()
            if not tid:
                continue
            if tp == "paramopt.run.start":
                starts[tid] = obj
                if tid in runs_by_trace:
                    cur = runs_by_trace.get(tid) if isinstance(runs_by_trace.get(tid), dict) else {}
                    if cur and (not cur.get("presets")):
                        presets0 = _infer_presets_from_start(obj)
                        if presets0:
                            cur["presets"] = presets0
                            runs_by_trace[tid] = cur
                            need_start.discard(tid)
                continue
            if tp in ("automation.paramopt.trigger", "automation.paramopt.explore.trigger"):
                res = obj.get("result") if isinstance(obj.get("result"), dict) else {}
                ts = _to_int(obj.get("ts"))
                if ts is None:
                    ts = _to_int(res.get("ts"))
                ts = int(ts or 0)
                ok = bool(res.get("ok")) if ("ok" in res) else bool(obj.get("ok", False))
                trig = str(res.get("trigger_event") or obj.get("trigger_event") or "").strip()
                if trig_allow and str(trig).strip().lower() not in trig_allow:
                    continue
                presets = [str(x).strip().lower() for x in ((res.get("presets") if isinstance(res.get("presets"), list) else [])) if str(x).strip()]
                stages = res.get("stages") if isinstance(res.get("stages"), list) else []
                ent = _classify_and_emit_run(ts=ts, ok=ok, presets=presets, trig=trig, stages=[x for x in stages if isinstance(x, dict)], preset_selection=(res.get("preset_selection") if isinstance(res.get("preset_selection"), dict) else None))
                runs.append(ent)
                runs_by_trace[tid] = ent
                continue
            if tp == "paramopt.run.result":
                if trig_allow:
                    continue
                ts = _to_int(obj.get("ts"))
                ts = int(ts or 0)
                ok = bool(obj.get("ok", False))
                sum0 = obj.get("summary") if isinstance(obj.get("summary"), dict) else {}
                requested0 = (starts.get(tid) if isinstance(starts.get(tid), dict) else {})
                presets = _infer_presets_from_start(requested0) if requested0 else []
                if not presets:
                    need_start.add(tid)
                trig = "manual"
                if ("o6" in presets) and isinstance(sum0, dict):
                    eq = (sum0.get("gate") if isinstance(sum0.get("gate"), dict) else {}).get("exec_quality")
                    if isinstance(eq, dict) and ("pass" in eq) and (not bool(eq.get("pass"))):
                        trig = "pnl.drawdown.trigger"
                ent = _classify_and_emit_run(ts=ts, ok=ok, presets=presets, trig=str(trig), stages=[], preset_selection=None)
                runs.append(ent)
                runs_by_trace[tid] = ent
                continue
        if scanned > scanned_cap:
            break
    if not runs:
        return out
    runs_rev = list(reversed(runs))
    ok_n = 0
    trend = []
    for i, r in enumerate(runs_rev):
        if bool(r.get("ok")):
            ok_n += 1
        left7 = max(0, int(i + 1 - 7))
        left14 = max(0, int(i + 1 - 14))
        w7 = runs_rev[left7 : int(i + 1)]
        w14 = runs_rev[left14 : int(i + 1)]
        ok7 = int(len([x for x in w7 if bool(x.get("ok"))]))
        ok14 = int(len([x for x in w14 if bool(x.get("ok"))]))
        trend.append(
            {
                "idx": int(i + 1),
                "ts": int(r.get("ts") or 0),
                "ok": bool(r.get("ok")),
                "success_rate": float(ok_n / float(i + 1)),
                "rolling_success_rate_7": (None if len(w7) <= 0 else float(ok7 / float(len(w7)))),
                "rolling_success_rate_14": (None if len(w14) <= 0 else float(ok14 / float(len(w14)))),
                "presets": list(r.get("presets") or []),
                "trigger_event": str(r.get("trigger_event") or ""),
                "scenario": str(r.get("scenario") or "A"),
                "scenario_title": str(r.get("scenario_title") or ""),
                "scenario_rule_id": str(r.get("scenario_rule_id") or ""),
                "scenario_why": str(r.get("scenario_why") or ""),
                "scenario_evidence": (r.get("scenario_evidence") if isinstance(r.get("scenario_evidence"), dict) else {}),
            }
        )
    ts_arr = [int(r.get("ts") or 0) for r in runs_rev if int(r.get("ts") or 0) > 0]
    intervals = []
    for i in range(1, len(ts_arr)):
        d = int(ts_arr[i]) - int(ts_arr[i - 1])
        if d > 0:
            intervals.append(float(d / 1000.0))
    total_mod = int(sum(int(v) for v in module_cnt.values()))
    module_share = []
    for k, v in sorted(module_cnt.items(), key=lambda kv: kv[1], reverse=True):
        vv = int(v)
        module_share.append({"module": str(k), "count": vv, "share": (float(vv) / float(total_mod) if total_mod > 0 else 0.0)})
    scen_title = {
        "A": "收益/风险退化",
        "B": "交易频率异常",
        "C": "出场行为异常",
        "D": "宏观/状态漂移",
        "E": "成本/执行退化",
        "F": "Quant泛化退化",
        "G": "系统级耦合",
    }
    total_scen = int(sum(int(v) for v in scenario_cnt.values()))
    scenario_share = []
    for k, v in sorted(scenario_cnt.items(), key=lambda kv: kv[1], reverse=True):
        vv = int(v)
        scenario_share.append({"scenario": str(k), "title": str(scen_title.get(str(k), "")), "count": vv, "share": (float(vv) / float(total_scen) if total_scen > 0 else 0.0)})
    reject_topn = [{"reason": str(k), "count": int(v)} for (k, v) in sorted(reject_cnt.items(), key=lambda kv: kv[1], reverse=True)[:8]]
    off = int(module_cnt.get("o1", 0)) + int(module_cnt.get("o2", 0))
    deff = int(module_cnt.get("o3", 0)) + int(module_cnt.get("o4", 0)) + int(module_cnt.get("o5", 0)) + int(module_cnt.get("o6", 0))
    stance = "balanced"
    if deff - off >= 2:
        stance = "defensive"
    elif off - deff >= 2:
        stance = "offensive"
    out["runs_n"] = int(len(runs_rev))
    out["success_rate"] = float(ok_n / float(len(runs_rev)))
    tail7 = runs_rev[-7:] if len(runs_rev) >= 1 else []
    tail14 = runs_rev[-14:] if len(runs_rev) >= 1 else []
    out["success_rate_7"] = (None if not tail7 else float(len([x for x in tail7 if bool(x.get("ok"))]) / float(len(tail7))))
    out["success_rate_14"] = (None if not tail14 else float(len([x for x in tail14 if bool(x.get("ok"))]) / float(len(tail14))))
    out["avg_interval_sec"] = (None if not intervals else float(sum(intervals) / float(len(intervals))))
    out["trend"] = trend
    out["scenario_share"] = scenario_share
    out["optimization_share"] = module_share
    out["module_share"] = module_share
    out["reject_topn"] = reject_topn
    out["market_stance"] = str(stance)
    return out


def _paramopt_last_chain_wrap_from_outbox(*, max_files: int = 24, max_lines: int = 12000, max_bytes: int = 8_000_000) -> Optional[Dict[str, Any]]:
    outbox = _agent_outbox_dir()
    cand: List[Path] = []
    try:
        p0 = outbox / "chat.jsonl"
        if p0.exists() and p0.is_file():
            cand.append(p0)
    except Exception:
        pass
    try:
        others = [p for p in outbox.glob("chat._*.jsonl") if p.is_file()]
        others.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others)
    except Exception:
        pass
    try:
        others = [p for p in outbox.glob("chat_*.jsonl") if p.is_file()]
        others.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others)
    except Exception:
        pass
    try:
        others_gz = [p for p in outbox.glob("chat._*.jsonl.gz") if p.is_file()]
        others_gz.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others_gz)
    except Exception:
        pass
    try:
        others_gz = [p for p in outbox.glob("chat_*.jsonl.gz") if p.is_file()]
        others_gz.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others_gz)
    except Exception:
        pass
    if not cand:
        return None

    max_files = max(1, min(48, int(max_files)))
    max_lines = max(1000, int(max_lines))
    max_bytes = max(1_000_000, int(max_bytes))

    def _file_lines_tail(fp: Path) -> List[str]:
        try:
            if str(fp).lower().endswith(".gz"):
                return _tail_lines_gzip(fp, max_lines=max_lines)
            return _tail_lines(fp, max_lines=max_lines, max_bytes=max_bytes)
        except Exception:
            return []

    for fp in cand[:max_files]:
        lines = _file_lines_tail(fp)
        for s in reversed(lines):
            try:
                obj = json.loads((s or "").strip())
            except Exception:
                continue
            if not isinstance(obj, dict):
                continue
            res = obj.get("result") if isinstance(obj.get("result"), dict) else None
            if not isinstance(res, dict):
                continue
            if not (isinstance(res.get("summary"), dict) and isinstance(res.get("stages"), list)):
                continue
            tid = str(obj.get("trace_id") or "").strip()
            if not tid:
                continue
            ts = _to_int(obj.get("ts"))
            if ts is None:
                ts = _to_int(res.get("ts"))
            ts = int(ts or 0)
            http = _to_int(obj.get("http"))
            http = int(http or 200)
            return {"ts": int(ts), "trace_id": str(tid), "http": int(http), "out": _json_sanitize(res)}
    return None


def _agent_rca_report_find_from_outbox(trace_id: str, *, max_files: int = 20, max_lines: int = 12000, tail_bytes: int = 5000000) -> Optional[Dict[str, Any]]:
    tid = str(trace_id or "").strip()
    if not tid:
        return None
    outbox = _agent_outbox_dir()
    cand: List[Path] = []
    try:
        p0 = outbox / "rca.jsonl"
        if p0.exists() and p0.is_file():
            cand.append(p0)
    except Exception:
        pass
    try:
        others = [p for p in outbox.glob("rca._*.jsonl") if p.is_file()]
        others.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others)
    except Exception:
        pass
    try:
        others_gz = [p for p in outbox.glob("rca._*.jsonl.gz") if p.is_file()]
        others_gz.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others_gz)
    except Exception:
        pass
    if not cand:
        return None

    max_files = max(1, min(200, int(max_files)))
    for fp in cand[:max_files]:
        lines: List[str] = []
        try:
            if str(fp).lower().endswith(".gz"):
                lines = _tail_lines_gzip(fp, max_lines=max_lines)
            else:
                lines = _tail_lines(fp, max_lines=max_lines, max_bytes=tail_bytes)
        except Exception:
            lines = []
        for s in reversed(lines):
            try:
                obj = json.loads((s or "").strip())
            except Exception:
                continue
            if not isinstance(obj, dict):
                continue
            if str(obj.get("type") or "").strip() != "rca.report":
                continue
            if str(obj.get("trace_id") or "").strip() != tid:
                continue
            rep = obj.get("report")
            if isinstance(rep, dict):
                return rep
    return None


def _agent_changeset_draft_lookup(draft_id: str, *, max_lines: int = 5000, max_bytes: int = 3_000_000) -> Optional[Dict[str, Any]]:
    did = str(draft_id or "").strip()
    if not did:
        return None
    p = _agent_outbox_dir() / "changeset_drafts.jsonl"
    if not p.exists() or (not p.is_file()):
        return None
    lines = _tail_lines(p, max_lines=int(max_lines), max_bytes=int(max_bytes))
    for ln in reversed(lines):
        s = str(ln or "").strip("\n")
        if not s.strip():
            continue
        try:
            obj = json.loads(s)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        if str(obj.get("id") or "").strip() != did:
            continue
        return obj
    return None


def _paramopt_bt_tf_to_ms(tf: str) -> Optional[int]:
    s = str(tf or "").strip().lower()
    if not s:
        return None
    unit = s[-1]
    num_s = s[:-1].strip()
    try:
        n = int(num_s)
    except Exception:
        return None
    if n <= 0:
        return None
    if unit == "m":
        return int(n) * 60 * 1000
    if unit == "h":
        return int(n) * 60 * 60 * 1000
    if unit == "d":
        return int(n) * 24 * 60 * 60 * 1000
    return None


def _paramopt_bt_pair_to_filename(pair: str, tf: str, trading_mode: str) -> str:
    p = str(pair or "").strip()
    t = str(tf or "").strip()
    m = str(trading_mode or "").strip().lower() or "futures"
    stem = p.replace("/", "_").replace(":", "_")
    if m in ("futures", "swap"):
        return f"{stem}-{t}-futures.json"
    if m in ("spot",):
        return f"{stem}-{t}.json"
    return f"{stem}-{t}-{m}.json"


def _paramopt_bt_datadir_from_cfg(cfg: Dict[str, Any]) -> Path:
    raw = str(cfg.get("datadir") or "user_data/data").strip() or "user_data/data"
    if raw.startswith("/"):
        try:
            return Path(raw)
        except Exception:
            return _user_data_dir() / "data"
    s = raw.replace("\\", "/").lstrip("./")
    if s.startswith("user_data/"):
        s = s[len("user_data/"):]
    if not s:
        s = "data"
    return _user_data_dir() / s


def _paramopt_bt_ohlcv_path(*, cfg: Dict[str, Any], exchange: str, trading_mode: str, pair: str, tf: str) -> Path:
    dd = _paramopt_bt_datadir_from_cfg(cfg)
    ex = str(exchange or "").strip().lower() or "gate"
    tm = str(trading_mode or "").strip().lower() or "futures"
    fn = _paramopt_bt_pair_to_filename(pair, tf, tm)
    return dd / ex / tm / fn


def _paramopt_bt_ohlcv_first_last_ts_ms(path: Path) -> Optional[Tuple[int, int]]:
    if (not path.exists()) or (not path.is_file()):
        return None
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = json.load(f)
    except Exception:
        return None
    if not isinstance(raw, list) or (not raw):
        return None
    a0 = raw[0]
    b0 = raw[-1]
    if not (isinstance(a0, list) and len(a0) >= 1 and isinstance(b0, list) and len(b0) >= 1):
        return None
    try:
        a = int(float(a0[0]))
        b = int(float(b0[0]))
    except Exception:
        return None
    return (a, b) if a <= b else (b, a)


def _paramopt_bt_ensure_tf_from_5m(
    *,
    cfg: Dict[str, Any],
    exchange: str,
    trading_mode: str,
    pair: str,
    dst_tf: str,
) -> Dict[str, Any]:
    dst = str(dst_tf or "").strip()
    if not dst:
        return {"ok": False, "error": "bad_dst_tf"}
    if dst == "5m":
        return {"ok": True, "skipped": True, "dst_tf": dst}
    dst_ms = _paramopt_bt_tf_to_ms(dst)
    src_ms = _paramopt_bt_tf_to_ms("5m")
    if (dst_ms is None) or (src_ms is None) or int(dst_ms) <= int(src_ms) or (int(dst_ms) % int(src_ms) != 0):
        return {"ok": False, "error": "unsupported_tf", "dst_tf": dst}
    p_dst = _paramopt_bt_ohlcv_path(cfg=cfg, exchange=exchange, trading_mode=trading_mode, pair=pair, tf=dst)
    if p_dst.exists() and p_dst.is_file():
        return {"ok": True, "exists": True, "dst_path": str(p_dst)}
    p_src = _paramopt_bt_ohlcv_path(cfg=cfg, exchange=exchange, trading_mode=trading_mode, pair=pair, tf="5m")
    if not (p_src.exists() and p_src.is_file()):
        return {"ok": False, "error": "src_missing", "src_path": str(p_src), "dst_path": str(p_dst)}
    try:
        with open(p_src, "r", encoding="utf-8") as f:
            raw = json.load(f)
    except Exception as e:
        return {"ok": False, "error": "src_read_failed", "detail": str(e)}
    rows: List[List[float]] = []
    for r in raw:
        if not isinstance(r, list) or len(r) < 6:
            continue
        try:
            rows.append([float(r[0]), float(r[1]), float(r[2]), float(r[3]), float(r[4]), float(r[5])])
        except Exception:
            continue
    if not rows:
        return {"ok": False, "error": "src_empty"}
    try:
        out_rows = _resample(rows, int(dst_ms))
    except Exception as e:
        return {"ok": False, "error": "resample_failed", "detail": str(e)}
    try:
        p_dst.parent.mkdir(parents=True, exist_ok=True)
        with open(p_dst, "w", encoding="utf-8") as f:
            json.dump([[float(x[0]), float(x[1]), float(x[2]), float(x[3]), float(x[4]), float(x[5])] for x in out_rows], f, ensure_ascii=False)
    except Exception as e:
        return {"ok": False, "error": "dst_write_failed", "detail": str(e), "dst_path": str(p_dst)}
    return {"ok": True, "generated": True, "dst_tf": dst, "rows": int(len(out_rows)), "dst_path": str(p_dst), "src_path": str(p_src)}


def _paramopt_bt_timerange_intersect(want: Optional[str], have_ms: Optional[Tuple[int, int]], *, fallback_days: int, anchor_ms: Optional[int]) -> Optional[str]:
    if not have_ms:
        return want
    a, b = int(have_ms[0]), int(have_ms[1])
    if a <= 0 or b <= 0 or a >= b:
        return want
    w = str(want or "").strip()
    if "-" in w and len(w) >= 17:
        x, y = w.split("-", 1)
        x = x.strip()
        y = y.strip()
        try:
            wa = int(datetime.strptime(x[:8], "%Y%m%d").replace(tzinfo=timezone.utc).timestamp() * 1000)
            wb = int(datetime.strptime(y[:8], "%Y%m%d").replace(tzinfo=timezone.utc).timestamp() * 1000)
        except Exception:
            wa = None
            wb = None
        if wa is not None and wb is not None:
            sa = max(int(a), int(wa))
            sb = min(int(b), int(wb))
            if sa < sb:
                return datetime.fromtimestamp(sa / 1000.0, tz=timezone.utc).strftime("%Y%m%d") + "-" + datetime.fromtimestamp(sb / 1000.0, tz=timezone.utc).strftime("%Y%m%d")
    anc = int(anchor_ms) if anchor_ms is not None else int(b)
    try:
        sa = max(int(a), int(anc) - int(fallback_days) * 86400 * 1000)
    except Exception:
        sa = int(a)
    sb = min(int(b), int(anc))
    if sa >= sb:
        sa = int(a)
        sb = int(b)
    return datetime.fromtimestamp(sa / 1000.0, tz=timezone.utc).strftime("%Y%m%d") + "-" + datetime.fromtimestamp(sb / 1000.0, tz=timezone.utc).strftime("%Y%m%d")


def _paramopt_backtest_auto_align(*, trace_id: str, bt_config: str, bt_timerange: Optional[str], ctx: Dict[str, Any]) -> Dict[str, Any]:
    try:
        en = bool(AUTOMATION.get("paramopt_backtest_auto_align_enabled", True))
    except Exception:
        en = True
    if not bool(en):
        return {"ok": False, "error": "disabled"}
    base_tid = str(ctx.get("base_trace_id") or "").strip()
    if not base_tid:
        return {"ok": False, "error": "no_base_trace_id"}
    rep = _agent_rca_report_find_from_outbox(base_tid)
    if not isinstance(rep, dict):
        return {"ok": False, "error": "rca_not_found", "base_trace_id": base_tid}
    summ = rep.get("summary") if isinstance(rep.get("summary"), dict) else {}
    pair_raw = str(summ.get("pair") or "").strip()
    err = rep.get("error_norm") if isinstance(rep.get("error_norm"), dict) else {}
    venue = str(err.get("venue") or "").strip().lower()
    timeline = rep.get("timeline") if isinstance(rep.get("timeline"), list) else []
    anchor_ms = None
    for it in timeline:
        if not isinstance(it, dict):
            continue
        if str(it.get("type") or "").strip() == "event":
            try:
                anchor_ms = int(it.get("ts") or 0)
            except Exception:
                anchor_ms = None
            break
    if not anchor_ms:
        try:
            anchor_ms = int(rep.get("ts") or 0)
        except Exception:
            anchor_ms = None

    cand_pairs: List[str] = []
    if pair_raw and ("-PERP" in pair_raw.upper()):
        base = pair_raw.split("-", 1)[0].strip().upper()
        if base:
            cand_pairs = [f"{base}/USDT", f"{base}/USDT:USDT"]
    elif pair_raw and ("/" in pair_raw):
        p0 = pair_raw.split(":", 1)[0].strip()
        if p0:
            cand_pairs.append(p0)
        if pair_raw not in cand_pairs:
            cand_pairs.append(pair_raw)
    if not cand_pairs:
        cand_pairs = ["BTC/USDT", "ETH/USDT", "SOL/USDT"]

    prefer_hl = bool(venue and venue not in ("gate", "binance", "okx")) or ("-PERP" in pair_raw.upper())
    exchange_order = ["hyperliquid", "gate"] if prefer_hl else ["gate", "hyperliquid"]
    base_cfg_gate = "user_data/config_local_backtest.json"
    base_cfg_hl = "user_data/config_local_backtest_hyperliquid.json"
    chosen_exchange = None
    chosen_pair = None
    chosen_cfg = None
    chosen_tm = "futures"
    chosen_tf = "1h"
    cfg_obj = None

    for ex in exchange_order:
        base_cfg = base_cfg_hl if ex == "hyperliquid" else base_cfg_gate
        try:
            p = _user_data_dir() / base_cfg[len("user_data/"):] if base_cfg.startswith("user_data/") else Path(base_cfg)
            cfg0 = json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            cfg0 = None
        if not isinstance(cfg0, dict):
            continue
        tm = str(cfg0.get("trading_mode") or "futures").strip().lower() or "futures"
        for pr in cand_pairs[:6]:
            p_dst = _paramopt_bt_ohlcv_path(cfg=cfg0, exchange=ex, trading_mode=tm, pair=pr, tf=chosen_tf)
            p_src = _paramopt_bt_ohlcv_path(cfg=cfg0, exchange=ex, trading_mode=tm, pair=pr, tf="5m")
            if (p_dst.exists() and p_dst.is_file()) or (p_src.exists() and p_src.is_file()):
                chosen_exchange = ex
                chosen_pair = pr
                chosen_cfg = base_cfg
                chosen_tm = tm
                cfg_obj = cfg0
                break
        if chosen_exchange:
            break

    if not chosen_exchange or not chosen_pair or not chosen_cfg or not isinstance(cfg_obj, dict):
        return {"ok": False, "error": "no_data_match", "base_trace_id": base_tid, "pair_raw": pair_raw, "venue": venue, "candidates": cand_pairs}

    cfg2 = dict(cfg_obj)
    cfg2["timeframe"] = chosen_tf
    ex0 = cfg2.get("exchange") if isinstance(cfg2.get("exchange"), dict) else {}
    ex2 = dict(ex0)
    ex2["name"] = str(chosen_exchange)
    ex2["pair_whitelist"] = [str(chosen_pair)]
    cfg2["exchange"] = ex2

    did = str(trace_id or "").strip() or uuid.uuid4().hex
    out_dir = _user_data_dir() / "backtest_configs"
    try:
        out_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    fp = out_dir / (f"auto_{did}.json".replace("/", "_").replace("\\", "_").replace("..", "_"))
    try:
        fp.write_text(json.dumps(cfg2, ensure_ascii=False, indent=4), encoding="utf-8")
    except Exception as e:
        return {"ok": False, "error": "write_failed", "detail": str(e)}
    bt_cfg_path = "user_data/" + str(fp).replace("\\", "/").split("/user_data/", 1)[-1].lstrip("/")

    ensure_rep = _paramopt_bt_ensure_tf_from_5m(cfg=cfg2, exchange=chosen_exchange, trading_mode=chosen_tm, pair=chosen_pair, dst_tf=chosen_tf)
    cov = _paramopt_bt_ohlcv_first_last_ts_ms(_paramopt_bt_ohlcv_path(cfg=cfg2, exchange=chosen_exchange, trading_mode=chosen_tm, pair=chosen_pair, tf=chosen_tf))
    tr2 = _paramopt_bt_timerange_intersect(bt_timerange, cov, fallback_days=30, anchor_ms=anchor_ms)
    return {
        "ok": True,
        "base_trace_id": base_tid,
        "pair_raw": pair_raw,
        "venue": venue,
        "exchange": chosen_exchange,
        "pair": chosen_pair,
        "trading_mode": chosen_tm,
        "timeframe": chosen_tf,
        "bt_config": bt_cfg_path,
        "bt_timerange": tr2,
        "coverage_ms": (None if not cov else [int(cov[0]), int(cov[1])]),
        "ensure_timeframe": ensure_rep,
    }


def _paramopt_loss_check_presets(trigger_event: str) -> List[str]:
    allowed = {"o1", "o2", "o3", "o4", "o5", "o6", "o7"}
    cfg0 = AUTOMATION.get("paramopt_loss_check_presets")
    out: List[str] = []
    if isinstance(cfg0, list):
        for x in cfg0:
            p = str(x or "").strip().lower()
            if p in allowed and p not in out:
                out.append(p)
    if not out:
        out = ["o1", "o2", "o3", "o4", "o5", "o6", "o7"]
    trig = str(trigger_event or "").strip().lower()
    if trig == "pnl.drawdown.trigger":
        order = ["o6", "o3", "o4", "o5", "o1", "o2", "o7"]
        ranked = [x for x in order if x in out]
        rem = [x for x in out if x not in ranked]
        out = ranked + rem
    return out


def _paramopt_loss_reason_presets_select(
    *,
    trigger_event: str,
    base_trace_id: str,
    trigger: Dict[str, Any],
    default_presets: List[str],
) -> Dict[str, Any]:
    allowed = {"o1", "o2", "o3", "o4", "o5", "o6", "o7"}
    presets_in = [str(x).strip().lower() for x in (default_presets or []) if str(x).strip()]
    presets_in = [x for x in presets_in if x in allowed]
    if not presets_in:
        presets_in = ["o6"]

    try:
        max_modules = int(AUTOMATION.get("paramopt_loss_reason_max_modules", 2) or 2)
    except Exception:
        max_modules = 2
    max_modules = max(1, min(7, int(max_modules)))
    try:
        diversify_share = float(AUTOMATION.get("paramopt_loss_reason_diversify_owner_share", 0.55) or 0.55)
    except Exception:
        diversify_share = 0.55
    diversify_share = float(max(0.10, min(0.95, float(diversify_share))))

    base_tid = str(base_trace_id or "").strip()
    recent_ids = trigger.get("recent_trade_event_ids") if isinstance(trigger.get("recent_trade_event_ids"), list) else []
    last_tid = None
    try:
        if recent_ids:
            last_tid = str(recent_ids[-1]).strip() or None
    except Exception:
        last_tid = None
    pick_tid = last_tid or base_tid

    chain = None
    rep = None
    try:
        chain = _agent_trace_chain(pick_tid)
        if isinstance(chain, dict) and bool(chain.get("ok")):
            rep = _agent_rca_report_from_chain(chain)
    except Exception:
        chain = None
        rep = None

    evt_src = (chain.get("event") if isinstance(chain, dict) else None)
    if not isinstance(evt_src, dict):
        evt_src = None
    orders_src = (chain.get("orders") if isinstance(chain, dict) else None)
    orders_src = orders_src if isinstance(orders_src, list) else []
    settlements_src = (chain.get("settlements") if isinstance(chain, dict) else None)
    settlements_src = settlements_src if isinstance(settlements_src, list) else []
    data_source = "trace_chain"

    if (not settlements_src) and isinstance(rep, dict):
        try:
            ev0 = rep.get("evidence") if isinstance(rep.get("evidence"), list) else []
            for e in ev0:
                if not isinstance(e, dict):
                    continue
                if str(e.get("name") or "").strip() == "settlements":
                    det = e.get("detail")
                    if isinstance(det, list):
                        settlements_src = det
                        data_source = "rca_report"
                        break
        except Exception:
            pass

    if not settlements_src:
        rep2 = _agent_rca_report_find_from_outbox(pick_tid)
        if isinstance(rep2, dict):
            rep = rep2
            data_source = "outbox_rca"
            try:
                ev2 = rep2.get("evidence") if isinstance(rep2.get("evidence"), list) else []
                for e in ev2:
                    if not isinstance(e, dict):
                        continue
                    nm = str(e.get("name") or "").strip()
                    det = e.get("detail")
                    if nm == "event" and isinstance(det, dict):
                        evt_src = det
                    elif nm == "first_order" and isinstance(det, dict):
                        orders_src = [det]
                    elif nm == "settlements" and isinstance(det, list):
                        settlements_src = det
            except Exception:
                pass
    settlements = [s for s in settlements_src if isinstance(s, dict)]
    owner_loss: Dict[str, float] = {}
    for s in settlements:
        if not isinstance(s, dict):
            continue
        owner = str(s.get("owner") or "").strip() or "unknown"
        try:
            pnl = float(s.get("pnl_usdc") or 0.0)
        except Exception:
            pnl = 0.0
        w = max(0.0, -float(pnl))
        if w <= 0.0:
            continue
        owner_loss[owner] = float(owner_loss.get(owner, 0.0)) + float(w)
    tot = float(sum(owner_loss.values()) or 0.0)
    top_owner = None
    top_share = 0.0
    if owner_loss and tot > 0.0:
        top_owner = max(owner_loss.items(), key=lambda kv: float(kv[1]))[0]
        top_share = float(owner_loss.get(top_owner, 0.0)) / float(tot)

    def _owner_group(owner: Optional[str]) -> str:
        o = str(owner or "").strip().lower()
        if "quant" in o or "carry" in o:
            return "quant"
        if "macro" in o or "overlay" in o:
            return "macro"
        return "strategy"

    top_group = _owner_group(top_owner)
    groups = set([_owner_group(k) for k in owner_loss.keys() if str(k).strip()])

    causes = rep.get("causes") if isinstance(rep, dict) else None
    causes = causes if isinstance(causes, list) else []
    cause_codes = set()
    for c in causes:
        if not isinstance(c, dict):
            continue
        code = str(c.get("code") or "").strip()
        if code:
            cause_codes.add(code)

    error_norm = (rep.get("error_norm") if isinstance(rep, dict) else None)
    if not isinstance(error_norm, dict):
        error_norm = None
    err_type = (str(error_norm.get("type") or "").strip().lower() if isinstance(error_norm, dict) else "")

    exec_issue = ("execution_failure" in cause_codes) or ("rate_limited_429" in cause_codes) or (err_type in ("execution", "http"))
    gate_issue = ("gate_veto" in cause_codes) or (err_type == "risk")
    exit_issue = ("exit_trigger" in cause_codes)

    reason_scores = (rep.get("reason_scores") if isinstance(rep, dict) else None)
    try:
        rs2 = _agent_loss_reason_scores_tradfi_v1(
            trigger_event=str(trigger_event),
            event=(evt_src if isinstance(evt_src, dict) else None),
            orders=[o for o in (orders_src or []) if isinstance(o, dict)],
            settlements=[r for r in settlements if isinstance(r, dict)],
            error_norm=(error_norm if isinstance(error_norm, dict) else {}),
        )
        if isinstance(rs2, dict) and isinstance(rs2.get("scores"), dict):
            reason_scores = rs2
    except Exception:
        pass
    rs_scores = (reason_scores.get("scores") if isinstance(reason_scores, dict) and isinstance(reason_scores.get("scores"), dict) else None)
    def _rs(k: str) -> Optional[float]:
        if not isinstance(rs_scores, dict):
            return None
        it = rs_scores.get(k)
        if not isinstance(it, dict):
            return None
        v = it.get("score")
        if v is None:
            return None
        try:
            f = float(v)
        except Exception:
            return None
        return f if math.isfinite(float(f)) else None

    s_beta = _rs("beta_exposure")
    s_vol = _rs("vol_mismatch")
    s_liq = _rs("liquidity_shock")
    s_tail = _rs("tail_risk")
    s_corr = _rs("correlation_rise")
    try:
        min_score = float(AUTOMATION.get("paramopt_loss_reason_min_score", 0.55) or 0.55)
    except Exception:
        min_score = 0.55
    min_score = float(max(0.0, min(1.0, float(min_score))))

    picks: List[str] = []

    use_rs = bool(AUTOMATION.get("paramopt_loss_reason_use_scores", True))
    if use_rs and any((s is not None and float(s) >= float(min_score)) for s in [s_beta, s_vol, s_liq, s_tail, s_corr]):
        exit_module = "o5" if top_group == "quant" else "o4"
        mw: Dict[str, float] = {}
        def _add(m: str, w: float) -> None:
            if m not in presets_in:
                return
            mw[m] = float(mw.get(m, 0.0)) + float(w)

        if s_liq is not None:
            _add("o6", 1.00 * float(s_liq))
        if s_beta is not None:
            _add("o3", 0.90 * float(s_beta))
            _add("o6", 0.30 * float(s_beta))
        if s_vol is not None:
            _add(exit_module, 0.80 * float(s_vol))
            _add("o6", 0.40 * float(s_vol))
        if s_tail is not None:
            _add(exit_module, 0.90 * float(s_tail))
            _add("o6", 0.40 * float(s_tail))
        if s_corr is not None:
            _add("o7", 0.90 * float(s_corr))
            _add("o6", 0.20 * float(s_corr))
            _add("o3", 0.20 * float(s_corr))

        if gate_issue:
            _add("o3", 0.30)
            _add("o6", 0.15)
        if exec_issue:
            _add("o6", 0.25)
        if exit_issue:
            _add(exit_module, 0.20)

        ranked = sorted(mw.items(), key=lambda kv: float(kv[1]), reverse=True)
        picks = [m for (m, _) in ranked if m in presets_in]
    else:
        if exec_issue:
            picks.append("o6")
        if gate_issue:
            picks.extend(["o3", "o6"])
        if exit_issue:
            picks.append("o5" if top_group == "quant" else "o4")
        if not picks:
            if (len(groups) >= 2) and float(top_share) < float(diversify_share):
                picks = ["o7"]
            else:
                if top_group == "quant":
                    picks.append("o2")
                elif top_group == "macro":
                    picks.append("o3")
                else:
                    picks.append("o1")

    final: List[str] = []
    for p in picks:
        if p in presets_in and p not in final:
            final.append(p)
    if not final:
        final = [presets_in[0]]
    final = final[: int(max_modules)]

    return {
        "ok": True,
        "picked_trace_id": pick_tid,
        "trigger_event": str(trigger_event),
        "data_source": str(data_source),
        "cause_codes": sorted(list(cause_codes)),
        "reason_scores": (reason_scores if isinstance(reason_scores, dict) else None),
        "reason_scores_used": bool(use_rs),
        "reason_scores_threshold": float(min_score),
        "error_type": (None if not err_type else err_type),
        "top_owner": top_owner,
        "top_share": float(top_share),
        "groups": sorted(list(groups)),
        "settlements_n": int(len(settlements)),
        "max_modules": int(max_modules),
        "presets_in": presets_in,
        "presets": final,
    }


def _paramopt_loss_chain_stage_summary(stage: Dict[str, Any]) -> Dict[str, Any]:
    st = stage if isinstance(stage, dict) else {}
    out0 = st.get("result") if isinstance(st.get("result"), dict) else {}
    apply0 = out0.get("apply") if isinstance(out0.get("apply"), dict) else {}
    policy0 = out0.get("policy_auto_approval") if isinstance(out0.get("policy_auto_approval"), dict) else {}
    gate0 = out0.get("gate") if isinstance(out0.get("gate"), dict) else {}
    base0 = out0.get("baseline") if isinstance(out0.get("baseline"), dict) else {}
    base_m = base0.get("metrics") if isinstance(base0.get("metrics"), dict) else {}
    best0 = out0.get("best") if isinstance(out0.get("best"), dict) else {}
    best_m = best0.get("metrics") if isinstance(best0.get("metrics"), dict) else {}
    sel0 = out0.get("selected") if isinstance(out0.get("selected"), dict) else {}
    patch0 = sel0.get("config_patch") if isinstance(sel0.get("config_patch"), dict) else {}
    sug0 = sel0.get("config_suggest") if isinstance(sel0.get("config_suggest"), dict) else {}
    auto_apply0 = out0.get("auto_apply") if isinstance(out0.get("auto_apply"), dict) else {}
    route = "manual_approval"
    mode0 = str(apply0.get("mode") or "").strip()
    if mode0 == "policy_auto_approved":
        route = "auto_approved"
    elif mode0 == "policy_auto_rejected":
        route = "auto_rejected"
    elif mode0 == "approval_requested":
        route = "manual_approval"
    elif bool(policy0.get("pass", False)):
        route = "eligible_pending"
    return {
        "preset": st.get("preset"),
        "trace_id": st.get("trace_id"),
        "ok": bool(out0.get("ok", False)),
        "http": st.get("http"),
        "route": route,
        "apply_mode": mode0,
        "policy_decision": policy0.get("decision"),
        "policy_pass": policy0.get("pass"),
        "gate_pass": gate0.get("pass"),
        "approval_id": out0.get("approval_id"),
        "draft_id": out0.get("draft_id"),
        "auto_apply_ok": auto_apply0.get("ok"),
        "best_max": best0.get("max"),
        "baseline_metrics": {k: base_m.get(k) for k in ("sortino", "calmar", "profit_factor", "max_drawdown", "trades", "coverage_days")},
        "best_metrics": {k: best_m.get(k) for k in ("sortino", "calmar", "profit_factor", "max_drawdown", "trades", "coverage_days")},
        "patch_keys_n": int(len([k for k in patch0.keys() if str(k).strip()])),
        "suggest_keys_n": int(len([k for k in sug0.keys() if str(k).strip()])),
    }


def _paramopt_ladder_round_factors() -> List[float]:
    raw = AUTOMATION.get("paramopt_ladder_round_factors")
    vals: List[float] = []
    if isinstance(raw, list):
        for x in raw:
            try:
                v = float(x)
            except Exception:
                continue
            if v > 0:
                vals.append(float(v))
    if not vals:
        vals = [1.0, 1.35, 1.8]
    out = []
    for v in vals:
        vv = float(max(0.2, min(4.0, float(v))))
        if vv not in out:
            out.append(vv)
    try:
        max_rounds = int(AUTOMATION.get("paramopt_ladder_max_rounds", 3) or 3)
    except Exception:
        max_rounds = 3
    max_rounds = max(1, min(10, int(max_rounds)))
    return out[:max_rounds]


def _paramopt_stage_good_enough(stage_out: Dict[str, Any]) -> bool:
    r0 = stage_out if isinstance(stage_out, dict) else {}
    if not bool(r0.get("ok", False)):
        return False
    app0 = r0.get("apply") if isinstance(r0.get("apply"), dict) else {}
    mode0 = str(app0.get("mode") or "").strip()
    if mode0 == "policy_auto_approved":
        aa0 = r0.get("auto_apply") if isinstance(r0.get("auto_apply"), dict) else {}
        if aa0:
            return bool(aa0.get("ok", False))
        return True
    pol0 = r0.get("policy_auto_approval") if isinstance(r0.get("policy_auto_approval"), dict) else {}
    gate0 = r0.get("gate") if isinstance(r0.get("gate"), dict) else {}
    return bool(pol0.get("pass", False)) and bool(gate0.get("pass", False))


def _paramopt_fast_apply_allowed_keys_default() -> List[str]:
    rules = _agent_auto_config_rules()
    keys: List[str] = []
    for k, r in (rules.items() if isinstance(rules, dict) else []):
        if not isinstance(r, dict):
            continue
        if str(r.get("mode") or "").strip().lower() != "auto-tighten-only":
            continue
        ks = str(k or "").strip()
        if ks:
            keys.append(ks)
    deny = {
        "signals_v1_confirm_enabled",
        "signals_v1_confirm_m",
        "signals_v1_confirm_n",
        "live_trading_enabled",
        "serving_shadow_mode",
        "serving_canary_enabled",
        "serving_canary_size_frac",
    }
    out = []
    for k in sorted(set(keys)):
        if k in deny:
            continue
        if "confirm" in k.lower():
            continue
        out.append(k)
    return out


def _paramopt_fast_apply_allowed_keys() -> List[str]:
    raw = CONFIG.get("paramopt_fast_apply_allowed_keys")
    if isinstance(raw, list):
        out = []
        for x in raw:
            s = str(x or "").strip()
            if s:
                out.append(s)
        out2 = []
        for s in out:
            if s not in out2:
                out2.append(s)
        return out2
    return _paramopt_fast_apply_allowed_keys_default()


