def _system_monitor_route_inconsistency_record(*, data: Dict[str, Any], resp: Dict[str, Any], http_status: int) -> None:
    try:
        enabled = bool(CONFIG.get("system_monitor_enabled", True)) and bool(CONFIG.get("system_monitor_route_inconsistency_enabled", True))
    except Exception:
        enabled = False
    if not enabled:
        return

    try:
        hs = int(http_status)
    except Exception:
        hs = 0

    try:
        path = str(request.path or "").strip()
    except Exception:
        path = ""

    err = None
    try:
        err = resp.get("error") if isinstance(resp, dict) else None
    except Exception:
        err = None
    status = None
    try:
        status = resp.get("status") if isinstance(resp, dict) else None
    except Exception:
        status = None
    got = None
    try:
        got = resp.get("got") if isinstance(resp, dict) else None
    except Exception:
        got = None

    kind = None
    if err is not None:
        try:
            e0 = str(err).strip().lower()
        except Exception:
            e0 = ""
        if e0 in ("carry_trade_venue_hl_only", "venue_hl_only"):
            kind = e0
        elif "wrong_system" in e0 or "wrong system" in e0:
            kind = "wrong_system"
    if kind is None and status is not None:
        try:
            s0 = str(status).strip().lower()
        except Exception:
            s0 = ""
        if s0 == "ignored_wrong_system":
            kind = "ignored_wrong_system"
    if kind is None:
        return

    now_ms = int(_now_ms())
    tag = str((data or {}).get("tag") or "").strip()
    pair = str((data or {}).get("pair") or (data or {}).get("symbol") or "").strip() or None
    strategy_id = str((data or {}).get("strategy_id") or (data or {}).get("strategy") or "").strip() or None
    system_id = str((data or {}).get("system_id") or (data or {}).get("owner") or "").strip() or None

    idem = str((data or {}).get("idempotency_key") or "").strip() or None
    trace_id = str((data or {}).get("trace_id") or "").strip() or None

    item = {
        "ts": int(now_ms),
        "trace_id": trace_id,
        "idempotency_key": idem,
        "http_status": int(hs),
        "path": path,
        "kind": str(kind),
        "tag": (tag or None),
        "pair": pair,
        "strategy_id": strategy_id,
        "system_id": system_id,
        "error": (None if err is None else str(err)),
        "status": (None if status is None else str(status)),
        "got": got,
        "resp": (_json_sanitize(resp) if isinstance(resp, dict) else {"ok": False, "error": "non_dict_resp"}),
    }
    st = TRACKER_STATE.get("system_monitor_route_inconsistencies")
    if not isinstance(st, list):
        st = []
        TRACKER_STATE["system_monitor_route_inconsistencies"] = st
    st.append(item)
    try:
        max_n = int(CONFIG.get("system_monitor_route_inconsistency_max_keep", 800) or 800)
    except Exception:
        max_n = 800
    max_n = max(50, min(5000, int(max_n)))
    if len(st) > max_n:
        try:
            TRACKER_STATE["system_monitor_route_inconsistencies"] = list(st[-max_n:])
        except Exception:
            pass


def _system_monitor_route_inconsistency_process(now_ms: int) -> None:
    try:
        enabled = bool(CONFIG.get("system_monitor_enabled", True)) and bool(CONFIG.get("system_monitor_route_inconsistency_enabled", True))
    except Exception:
        enabled = False
    if not enabled:
        return

    st = _system_monitor_route_inconsistency_state_get()
    try:
        per = int(CONFIG.get("system_monitor_scan_period_seconds", 30) or 30)
    except Exception:
        per = 30
    per = max(5, min(3600, int(per)))
    last_scan = int(st.get("last_scan_ms") or 0)
    if last_scan > 0 and (int(now_ms) - last_scan) < int(per * 1000):
        return
    st["last_scan_ms"] = int(now_ms)

    try:
        win = int(CONFIG.get("system_monitor_route_inconsistency_window_seconds", 3600) or 3600)
    except Exception:
        win = 3600
    win = max(30, min(86400, int(win)))
    try:
        min_count = int(CONFIG.get("system_monitor_route_inconsistency_min_count", 1) or 1)
    except Exception:
        min_count = 1
    min_count = max(1, min(50, int(min_count)))

    items_all = TRACKER_STATE.get("system_monitor_route_inconsistencies")
    items = [x for x in (items_all or []) if isinstance(x, dict) and int(x.get("ts") or 0) >= int(now_ms) - int(win * 1000)]
    if not items:
        return

    by_key: Dict[str, List[Dict[str, Any]]] = {}
    meta: Dict[str, Dict[str, Any]] = {}
    for it in items:
        k = "|".join(
            [
                str(it.get("kind") or "unknown"),
                str(it.get("path") or ""),
                str(it.get("system_id") or ""),
                str(it.get("strategy_id") or ""),
                str(it.get("pair") or ""),
                str(it.get("http_status") or 0),
            ]
        )
        by_key.setdefault(k, []).append(it)
        if k not in meta:
            meta[k] = {
                "kind": it.get("kind"),
                "path": it.get("path"),
                "system_id": it.get("system_id"),
                "strategy_id": it.get("strategy_id"),
                "pair": it.get("pair"),
                "http_status": it.get("http_status"),
            }

    doc_refs = list(_agent_doc_refs_48_default())
    doc_refs.extend(
        [
            {"doc_path": "交易AI Agent 技术文档2.0.md", "section": "5.4.2", "rule": "系统运行状态监控（System Monitor）"},
            {"doc_path": "技术文档.md", "section": "0.3", "rule": "工程索引（必读入口）"},
            {"doc_path": "技术文档.md", "section": "0.3", "rule": "FAQ 快速定位（高频问题入口）"},
        ]
    )

    seen = st.get("seen") if isinstance(st.get("seen"), dict) else {}
    try:
        ttl = int(CONFIG.get("system_monitor_route_inconsistency_emit_ttl_seconds", 1800) or 1800)
    except Exception:
        ttl = 1800
    ttl = max(30, min(86400, int(ttl)))

    for k, lst in list(by_key.items()):
        if len(lst) < int(min_count):
            continue
        lst2 = sorted(lst, key=lambda x: int(x.get("ts") or 0))
        last = lst2[-1]
        last_ts = int(last.get("ts") or 0)
        stable = json.dumps({"k": k, "win": win, "last": last_ts // 10_000}, sort_keys=True, ensure_ascii=False)
        idem = hashlib.sha256(stable.encode("utf-8")).hexdigest()[:32]
        prev = seen.get(idem)
        try:
            if prev is not None and int(prev) > 0 and (int(now_ms) - int(prev)) < int(ttl * 1000):
                continue
        except Exception:
            pass
        seen[idem] = int(now_ms)
        st["seen"] = seen

        trigger_trace_id = hashlib.sha256(f"route_inconsistency|{idem}|{int(now_ms)}".encode("utf-8")).hexdigest()[:32]
        m = meta.get(k) if isinstance(meta.get(k), dict) else {}
        samples = [
            {
                "ts": int(x.get("ts") or 0),
                "trace_id": x.get("trace_id"),
                "http_status": x.get("http_status"),
                "path": x.get("path"),
                "kind": x.get("kind"),
                "system_id": x.get("system_id"),
                "strategy_id": x.get("strategy_id"),
                "pair": x.get("pair"),
                "error": x.get("error"),
                "status": x.get("status"),
                "got": x.get("got"),
            }
            for x in lst2[-10:]
        ]
        probe_tid = None
        for x in reversed(lst2):
            t0 = x.get("trace_id")
            if t0 is None:
                continue
            try:
                ts = str(t0).strip()
            except Exception:
                ts = ""
            if ts:
                probe_tid = ts
                break

        inputs_obj = {
            "window": {"sec": int(win), "since_ms": int(now_ms) - int(win * 1000), "until_ms": int(now_ms)},
            "kind": m.get("kind"),
            "path": m.get("path"),
            "http_status": m.get("http_status"),
            "system_id": m.get("system_id"),
            "strategy_id": m.get("strategy_id"),
            "pair": m.get("pair"),
            "min_count": int(min_count),
            "observed": int(len(lst2)),
        }
        outputs_obj = {
            "triggered": True,
            "idempotency_key": idem,
            "symptom_code": "route_inconsistency",
            "reason_code": str(m.get("kind") or ""),
            "dedupe_key": str(idem),
            "case_state": "observed",
            "next_actions": [
                {"kind": "readonly", "endpoint": "GET /engineering/index"},
                {"kind": "readonly", "endpoint": "GET /doc/snippet", "query": {"doc_path": "技术文档.md", "section": "0.3"}},
                {"kind": "readonly", "endpoint": "GET /audit/alerts/evaluate"},
                {"kind": "readonly", "endpoint": "GET /audit/data-quality"},
                {"kind": "readonly", "endpoint": "GET /audit/execution-quality"},
                {"kind": "readonly", "endpoint": "GET /signals/recent", "query": {"limit": 50}},
                {"kind": "readonly", "endpoint": "GET /orders/recent", "query": {"limit": 50}},
                {"kind": "readonly", "endpoint": "GET /tracker/stats"},
                {"kind": "readonly.verify", "endpoint": "GET /agent/trace/replay", "query": ({"trace_id": str(probe_tid), "max_orders": 120} if probe_tid else None)},
            ],
            "sandbox_plan": [
                {"kind": "backtest", "endpoint": "POST /automation/backtest/run"},
                {"kind": "rolling_verify", "endpoint": "POST /evaluation/rolling_verify"},
                {"kind": "monte_carlo", "endpoint": "POST /evaluation/monte_carlo"},
                {"kind": "gatecheck", "endpoint": "GET /evaluation/gate/check"},
                {"kind": "replay", "endpoint": "GET /agent/trace/replay"},
            ],
            "quick_locate": {
                "engineering_index": ["技术文档.md:0.3"],
                "faq": ["技术文档.md:0.3"],
                "suggested_checks": [
                    "GET /config/get 校验 execution_venue/carry_trade_venue 等路由开关",
                    "GET /orders/recent?limit=50 定位对应 trace_id/order_id 的真实路由与 owner",
                    "GET /tracker/stats 对齐 system_id=Strategy/Quant/Carry 的隔离状态",
                ],
            },
        }
        pb_hit = _system_monitor_playbook_hit(event="route.inconsistency.trigger", inputs=inputs_obj, outputs=outputs_obj)
        if pb_hit is not None:
            outputs_obj["playbook_hit"] = pb_hit
        _agent_emit_envelope_event(
            event="route.inconsistency.trigger",
            trace_id=trigger_trace_id,
            severity="warn",
            intent_level="L1",
            ts_ms=int(now_ms),
            inputs=inputs_obj,
            evidence=[
                {"type": "route_inconsistency", "source": "system_monitor", "samples": samples},
                {"type": "doc_ref", "doc_path": "技术文档.md", "section": "0.3"},
            ],
            outputs=outputs_obj,
            doc_refs=doc_refs,
        )


def _system_monitor_link_consistency_process(now_ms: int) -> None:
    try:
        enabled = bool(CONFIG.get("system_monitor_enabled", True)) and bool(CONFIG.get("system_monitor_link_consistency_enabled", True))
    except Exception:
        enabled = False
    if not enabled:
        return

    st = _system_monitor_link_consistency_state_get()
    try:
        per = int(CONFIG.get("system_monitor_scan_period_seconds", 30) or 30)
    except Exception:
        per = 30
    per = max(5, min(3600, int(per)))
    last_scan = int(st.get("last_scan_ms") or 0)
    if last_scan > 0 and (int(now_ms) - last_scan) < int(per * 1000):
        return
    st["last_scan_ms"] = int(now_ms)

    try:
        win = int(CONFIG.get("system_monitor_link_consistency_window_seconds", 3600) or 3600)
    except Exception:
        win = 3600
    win = max(30, min(86400, int(win)))
    try:
        min_count = int(CONFIG.get("system_monitor_link_consistency_min_count", 1) or 1)
    except Exception:
        min_count = 1
    min_count = max(1, min(50, int(min_count)))

    since_ms = int(now_ms) - int(win * 1000)
    anomalies: List[Dict[str, Any]] = []

    orders_in_win: List[Dict[str, Any]] = []
    try:
        for o in (ORDERS or {}).values():
            if not isinstance(o, dict):
                continue
            ts0 = int(o.get("ts") or 0)
            if ts0 < int(since_ms):
                continue
            orders_in_win.append(o)
    except Exception:
        orders_in_win = []

    order_ids = set()
    for o in orders_in_win:
        oid0 = o.get("order_id")
        if oid0 is None:
            oid0 = o.get("id")
        try:
            oid_s = str(oid0).strip()
        except Exception:
            oid_s = ""
        if oid_s:
            order_ids.add(oid_s)
        else:
            anomalies.append(
                {
                    "ts": int(o.get("ts") or 0),
                    "reason_code": "orphan.order.missing_order_id",
                    "order": {"pair": o.get("pair"), "side": o.get("side"), "tag": o.get("tag"), "strategy_id": o.get("strategy_id")},
                }
            )

        eid0 = o.get("base_event_id") if o.get("base_event_id") is not None else o.get("event_id")
        try:
            eid_s = str(eid0).strip()
        except Exception:
            eid_s = ""
        if not eid_s:
            anomalies.append(
                {
                    "ts": int(o.get("ts") or 0),
                    "reason_code": "orphan.order.missing_event_id",
                    "order_id": (oid_s or None),
                    "order": {"pair": o.get("pair"), "side": o.get("side"), "tag": o.get("tag"), "strategy_id": o.get("strategy_id")},
                }
            )
        else:
            if not isinstance(EVENTS.get(eid_s), dict):
                anomalies.append(
                    {
                        "ts": int(o.get("ts") or 0),
                        "reason_code": "orphan.order.event_not_found",
                        "order_id": (oid_s or None),
                        "event_id": eid_s,
                        "order": {"pair": o.get("pair"), "side": o.get("side"), "tag": o.get("tag"), "strategy_id": o.get("strategy_id")},
                    }
                )

    settlements_in_win: List[Dict[str, Any]] = []
    try:
        for r in (_ab_settlements_get() or []):
            if not isinstance(r, dict):
                continue
            ts0 = int(r.get("ts") or 0)
            if ts0 < int(since_ms):
                continue
            settlements_in_win.append(r)
    except Exception:
        settlements_in_win = []

    for r in settlements_in_win:
        try:
            oid_s = str(r.get("order_id") or "").strip()
        except Exception:
            oid_s = ""
        if not oid_s:
            anomalies.append({"ts": int(r.get("ts") or 0), "reason_code": "orphan.settlement.missing_order_id", "settlement": {"event_id": r.get("event_id"), "pnl_u": r.get("pnl_u"), "fees_u": r.get("fees_u")}})
        elif oid_s not in order_ids:
            anomalies.append({"ts": int(r.get("ts") or 0), "reason_code": "orphan.settlement.order_not_found", "order_id": oid_s, "settlement": {"event_id": r.get("event_id"), "pnl_u": r.get("pnl_u"), "fees_u": r.get("fees_u")}})
        try:
            eid_s = str(r.get("event_id") or "").strip()
        except Exception:
            eid_s = ""
        if not eid_s:
            anomalies.append({"ts": int(r.get("ts") or 0), "reason_code": "orphan.settlement.missing_event_id", "order_id": (oid_s or None), "settlement": {"pnl_u": r.get("pnl_u"), "fees_u": r.get("fees_u")}})

    if not anomalies:
        return

    by_code: Dict[str, List[Dict[str, Any]]] = {}
    for a in anomalies:
        rc = str(a.get("reason_code") or "").strip() or "unknown"
        by_code.setdefault(rc, []).append(a)

    doc_refs = list(_agent_doc_refs_48_default())
    doc_refs.extend(
        [
            {"doc_path": "交易AI Agent 技术文档2.0.md", "section": "5.4.2", "rule": "系统运行状态监控（System Monitor）"},
        ]
    )

    seen = st.get("seen") if isinstance(st.get("seen"), dict) else {}
    try:
        ttl = int(CONFIG.get("system_monitor_link_consistency_emit_ttl_seconds", 1800) or 1800)
    except Exception:
        ttl = 1800
    ttl = max(30, min(86400, int(ttl)))

    for code, lst in list(by_code.items()):
        if len(lst) < int(min_count):
            continue
        lst2 = sorted(lst, key=lambda x: int(x.get("ts") or 0))
        last_ts = int(lst2[-1].get("ts") or 0)
        stable = json.dumps({"code": code, "win": win, "last": last_ts // 10_000}, sort_keys=True, ensure_ascii=False)
        idem = hashlib.sha256(stable.encode("utf-8")).hexdigest()[:32]
        prev = seen.get(idem)
        try:
            if prev is not None and int(prev) > 0 and (int(now_ms) - int(prev)) < int(ttl * 1000):
                continue
        except Exception:
            pass
        seen[idem] = int(now_ms)
        st["seen"] = seen

        trigger_trace_id = hashlib.sha256(f"link_consistency|{idem}|{int(now_ms)}".encode("utf-8")).hexdigest()[:32]
        samples = lst2[-10:]
        inputs_obj = {
            "window": {"sec": int(win), "since_ms": int(since_ms), "until_ms": int(now_ms)},
            "code": str(code),
        }
        outputs_obj = {
            "triggered": True,
            "idempotency_key": idem,
            "symptom_code": "link_consistency",
            "reason_code": str(code),
            "dedupe_key": str(idem),
            "case_state": "observed",
            "observed": int(len(lst2)),
            "top": [{"reason_code": str(code), "count": int(len(lst2))}],
            "next_actions": [
                {"kind": "readonly", "endpoint": "GET /engineering/index"},
                {"kind": "readonly", "endpoint": "GET /doc/snippet", "query": {"doc_path": "交易AI Agent 技术文档2.0.md", "section": "5.4.2"}},
                {"kind": "readonly", "endpoint": "GET /signals/recent", "query": {"limit": 50}},
                {"kind": "readonly", "endpoint": "GET /orders/recent", "query": {"limit": 50}},
                {"kind": "readonly", "endpoint": "GET /tracker/stats"},
                {"kind": "readonly.verify", "endpoint": "GET /agent/trace/replay"},
            ],
            "sandbox_plan": [
                {"kind": "replay", "endpoint": "GET /agent/trace/replay"},
                {"kind": "stress", "endpoint": "GET /audit/execution-quality"},
            ],
        }
        _agent_emit_envelope_event(
            event="link.consistency.trigger",
            trace_id=trigger_trace_id,
            severity="warn",
            intent_level="L1",
            ts_ms=int(now_ms),
            inputs=inputs_obj,
            evidence=[
                {"type": "link_consistency", "source": "system_monitor", "samples": _json_sanitize(samples)},
            ],
            outputs=outputs_obj,
            doc_refs=doc_refs,
        )


def _system_monitor_exec_failure_record(*, data: Dict[str, Any], resp: Dict[str, Any], http_status: int) -> None:
    try:
        enabled = bool(CONFIG.get("system_monitor_enabled", True)) and bool(CONFIG.get("system_monitor_exec_failure_enabled", True))
    except Exception:
        enabled = False
    if not enabled:
        return
    try:
        execute = bool((data or {}).get("execute", False))
    except Exception:
        execute = False
    if not execute:
        return
    try:
        hs = int(http_status)
    except Exception:
        hs = 0
    if hs < 500:
        return
    now_ms = int(_now_ms())
    try:
        path = str(request.path or "").strip()
    except Exception:
        path = ""
    tag = str((data or {}).get("tag") or "").strip()
    pair = str((data or {}).get("pair") or (data or {}).get("symbol") or "").strip() or None
    strategy_id = str((data or {}).get("strategy_id") or (data or {}).get("strategy") or "").strip() or None
    system_id = str((data or {}).get("system_id") or (data or {}).get("owner") or "").strip() or None

    pairs: List[str] = []
    try:
        pr = (data or {}).get("pairs")
        if isinstance(pr, list):
            pairs = [str(x).strip() for x in pr if str(x or "").strip()][:6]
    except Exception:
        pairs = []
    if pair is not None and (not pairs):
        pairs = [str(pair)]
    if not pairs:
        try:
            if isinstance(resp, dict) and ("btc" in resp or "eth" in resp) and "/execution/pairs/btceth/" in str(path):
                pairs = ["BTC-PERP", "ETH-PERP"]
        except Exception:
            pairs = []

    idem = str((data or {}).get("idempotency_key") or "").strip()
    trace_id = str((data or {}).get("trace_id") or idem or "").strip() or hashlib.sha256(f"execfail|{path}|{tag}|{now_ms}".encode("utf-8")).hexdigest()[:32]
    item = {
        "ts": int(now_ms),
        "trace_id": trace_id,
        "idempotency_key": (idem or None),
        "http_status": int(hs),
        "path": path,
        "tag": (tag or None),
        "pair": pair,
        "pairs": (pairs if pairs else None),
        "strategy_id": strategy_id,
        "system_id": system_id,
        "resp": (_json_sanitize(resp) if isinstance(resp, dict) else {"ok": False, "error": "non_dict_resp"}),
    }
    st = TRACKER_STATE.get("system_monitor_exec_failures")
    if not isinstance(st, list):
        st = []
        TRACKER_STATE["system_monitor_exec_failures"] = st
    st.append(item)
    try:
        max_n = int(CONFIG.get("system_monitor_exec_failure_max_keep", 800) or 800)
    except Exception:
        max_n = 800
    max_n = max(50, min(5000, int(max_n)))
    if len(st) > max_n:
        try:
            TRACKER_STATE["system_monitor_exec_failures"] = list(st[-max_n:])
        except Exception:
            pass


def _system_monitor_pick_strategy_ref() -> Optional[Dict[str, str]]:
    try:
        reg = _strategy_registry_load()
    except Exception:
        reg = None
    entries = reg.get("entries") if isinstance(reg, dict) else None
    if not isinstance(entries, dict):
        return None
    items = [v for v in entries.values() if isinstance(v, dict)]
    items.sort(key=lambda x: str(x.get("updated_at") or ""), reverse=True)
    for it in items:
        sid = str(it.get("strategy_id") or "").strip()
        z = str(it.get("source_zip") or "").strip()
        if sid and z:
            return {"strategy_id": sid, "source_zip": z}
    return None


def _system_monitor_exec_failure_process(now_ms: int) -> None:
    try:
        enabled = bool(CONFIG.get("system_monitor_enabled", True)) and bool(CONFIG.get("system_monitor_exec_failure_enabled", True))
    except Exception:
        enabled = False
    if not enabled:
        return

    st = _system_monitor_exec_failure_state_get()
    try:
        per = int(CONFIG.get("system_monitor_scan_period_seconds", 30) or 30)
    except Exception:
        per = 30
    per = max(5, min(3600, int(per)))
    last_scan = int(st.get("last_scan_ms") or 0)
    if last_scan > 0 and (int(now_ms) - last_scan) < int(per * 1000):
        return
    st["last_scan_ms"] = int(now_ms)

    try:
        win = int(CONFIG.get("system_monitor_exec_failure_window_seconds", 120) or 120)
    except Exception:
        win = 120
    win = max(10, min(3600, int(win)))
    try:
        min_count = int(CONFIG.get("system_monitor_exec_failure_min_count", 1) or 1)
    except Exception:
        min_count = 1
    min_count = max(1, min(50, int(min_count)))

    items_all = TRACKER_STATE.get("system_monitor_exec_failures")
    items = [x for x in (items_all or []) if isinstance(x, dict) and int(x.get("ts") or 0) >= int(now_ms) - int(win * 1000)]
    if not items:
        return

    by_scope_key: Dict[str, List[Dict[str, Any]]] = {}
    scope_meta: Dict[str, Dict[str, Any]] = {}
    for it in items:
        path = str(it.get("path") or "").strip()
        hs = int(it.get("http_status") or 0)
        strategy_id = str(it.get("strategy_id") or "").strip() or None
        pair0 = str(it.get("pair") or "").strip() or None
        pairs0 = it.get("pairs") if isinstance(it.get("pairs"), list) else None
        pairs: List[str] = []
        if isinstance(pairs0, list):
            pairs = [str(x).strip() for x in pairs0 if str(x or "").strip()][:6]
        if (not pairs) and pair0 is not None:
            pairs = [str(pair0)]

        k0 = f"endpoint|{path}|{hs}"
        by_scope_key.setdefault(k0, []).append(it)
        scope_meta.setdefault(k0, {"scope": "endpoint", "path": path, "http_status": int(hs)})

        for p in pairs:
            kp = f"pair|{path}|{p}|{hs}"
            by_scope_key.setdefault(kp, []).append(it)
            scope_meta.setdefault(kp, {"scope": "pair", "path": path, "pair": p, "http_status": int(hs)})

        if strategy_id is not None:
            ks = f"strategy|{path}|{strategy_id}|{hs}"
            by_scope_key.setdefault(ks, []).append(it)
            scope_meta.setdefault(ks, {"scope": "strategy", "path": path, "strategy_id": strategy_id, "http_status": int(hs)})

    doc_refs = _agent_doc_refs_48_default()
    seen = st.get("seen") if isinstance(st.get("seen"), dict) else {}
    try:
        ttl = int(CONFIG.get("system_monitor_exec_failure_emit_ttl_seconds", 1800) or 1800)
    except Exception:
        ttl = 1800
    ttl = max(30, min(86400, int(ttl)))

    def _gates_for_scope(scope: str) -> List[str]:
        k = str(scope or "").strip().lower()
        if k not in ("endpoint", "pair", "strategy"):
            k = "endpoint"
        raw = CONFIG.get(f"system_monitor_exec_failure_gates_{k}")
        if not isinstance(raw, list):
            if k == "endpoint":
                return ["backtest", "gatecheck"]
            return ["backtest", "gatecheck", "rolling_verify"]
        out = [str(x).strip() for x in raw if str(x or "").strip()][:6]
        return (out if out else (["backtest", "gatecheck"] if k == "endpoint" else ["backtest", "gatecheck", "rolling_verify"]))

    def _rollback_plan_for_scope(meta: Dict[str, Any]) -> Dict[str, Any]:
        scope = str(meta.get("scope") or "endpoint").strip().lower() or "endpoint"
        path = str(meta.get("path") or "").strip()
        pair = str(meta.get("pair") or "").strip() or None
        sid = str(meta.get("strategy_id") or "").strip() or None
        patch: Dict[str, Any] = {}
        template_id = f"exec_failure.{scope}.default"
        if scope == "endpoint" and path.endswith("/execution/pairs/btceth/market_close"):
            template_id = "exec_failure.endpoint.btceth_close"
            patch = {
                "quant_pairs_btceth_close_verify_timeout_sec": 3.0,
                "quant_pairs_btceth_close_verify_poll_sec": 0.25,
            }
        if scope == "pair" and path.endswith("/execution/pairs/btceth/market_close"):
            template_id = "exec_failure.pair.btceth"
            patch = {"quant_auto_btceth_enabled": False}
        return {
            "template_id": template_id,
            "requires_approval": True,
            "config_patch": patch,
            "actions": [
                {"name": "stabilize_execution", "scope": scope, "path": path, "pair": pair, "strategy_id": sid},
                {"name": "sandbox_min_plan", "gates": _gates_for_scope(scope)},
                {"name": "prepare_rollback", "scope": scope, "hint": "fail->block_apply_and_rollback"},
            ],
        }

    for scope_key, lst in list(by_scope_key.items()):
        if len(lst) < int(min_count):
            continue
        lst2 = sorted(lst, key=lambda x: int(x.get("ts") or 0))
        last = lst2[-1]
        last_ts = int(last.get("ts") or 0)
        meta = scope_meta.get(scope_key) if isinstance(scope_meta.get(scope_key), dict) else {}
        stable = json.dumps({"k": scope_key, "win": win, "last": last_ts // 10_000}, sort_keys=True, ensure_ascii=False)
        idem = hashlib.sha256(stable.encode("utf-8")).hexdigest()[:32]
        prev = seen.get(idem)
        try:
            if prev is not None and int(prev) > 0 and (int(now_ms) - int(prev)) < int(ttl * 1000):
                continue
        except Exception:
            pass
        seen[idem] = int(now_ms)
        st["seen"] = seen

        trigger_trace_id = hashlib.sha256(f"exec_failure|{idem}|{int(now_ms)}".encode("utf-8")).hexdigest()[:32]
        samples = [
            {
                "ts": int(x.get("ts") or 0),
                "trace_id": x.get("trace_id"),
                "http_status": x.get("http_status"),
                "path": x.get("path"),
                "tag": x.get("tag"),
                "pair": x.get("pair"),
                "pairs": x.get("pairs"),
                "strategy_id": x.get("strategy_id"),
                "error": ((x.get("resp") or {}).get("error") if isinstance(x.get("resp"), dict) else None),
            }
            for x in lst2[-10:]
        ]

        base_trace_id = None
        try:
            base_trace_id = str(last.get("trace_id") or "").strip() or None
        except Exception:
            base_trace_id = None

        scope = str(meta.get("scope") or "endpoint").strip().lower() or "endpoint"
        group_key = "|".join(str(scope_key).split("|", 1)[1:])
        gates = _gates_for_scope(scope)
        rollback_plan = _rollback_plan_for_scope(meta)

        try:
            hs0 = int(meta.get("http_status") or 0)
        except Exception:
            hs0 = 0
        try:
            sev_unit = float(max(0.0, min(1.0, float(max(0, hs0 - 499)) / 50.0)))
        except Exception:
            sev_unit = 0.0
        try:
            ratio = float(len(lst2)) / float(max(1, int(min_count)))
        except Exception:
            ratio = 1.0
        delta_estimate = {
            "kind": "execution_availability_risk",
            "severity_score": float(max(0.0, min(1.0, float(ratio) * float(sev_unit)))),
            "observed": int(len(lst2)),
            "window_sec": int(win),
            "http_status": int(hs0),
            "expected_failed_calls": int(len(lst2)),
            "confidence": 0.3,
        }
        inputs_obj = {
            "window": {"sec": int(win), "since_ms": int(now_ms) - int(win * 1000), "until_ms": int(now_ms)},
            "scope": scope,
            "group_key": group_key,
            "path": meta.get("path"),
            "pair": meta.get("pair"),
            "strategy_id": meta.get("strategy_id"),
            "min_count": int(min_count),
            "observed": int(len(lst2)),
            "base_trace_id": base_trace_id,
        }
        outputs_obj = {
            "triggered": True,
            "idempotency_key": idem,
            "gate_plan": {"gates": gates, "policy_ref": "p3_default"},
            "rollback_plan": rollback_plan,
            "delta_estimate": delta_estimate,
        }
        pb_hit = _system_monitor_playbook_hit(event="execution.failure.trigger", inputs=inputs_obj, outputs=outputs_obj)
        if pb_hit is not None:
            outputs_obj["playbook_hit"] = pb_hit
        _agent_emit_envelope_event(
            event="execution.failure.trigger",
            trace_id=trigger_trace_id,
            severity="warn",
            intent_level="L1",
            ts_ms=int(now_ms),
            inputs=inputs_obj,
            evidence=[{"type": "exec_failure", "source": "system_monitor", "samples": samples}],
            outputs=outputs_obj,
            doc_refs=doc_refs,
        )

        rca_report = {
            "ok": True,
            "ts": int(_now_ms()),
            "trace_id": trigger_trace_id,
            "playbook_hit": pb_hit,
            "summary": {
                "scope": "execution",
                "scope_type": scope,
                "loss": None,
                "observed": int(len(lst2)),
                "window_sec": int(win),
                "group_key": group_key,
                "last_ts": int(last_ts),
                "path": meta.get("path"),
                "pair": meta.get("pair"),
                "strategy_id": meta.get("strategy_id"),
            },
            "timeline": [{"ts": int(x.get("ts") or 0), "type": "exec_failure", "path": x.get("path"), "tag": x.get("tag"), "http_status": x.get("http_status"), "trace_id": x.get("trace_id")} for x in lst2[-20:]],
            "causes": [
                {"code": "execution_5xx", "weight": 0.8, "summary": "执行侧出现 5xx（可能为交易所/代理/网络抖动）"},
                {"code": "close_path_unstable", "weight": 0.4, "summary": "平仓路径在短窗口内重复失败"},
            ],
            "evidence": [{"name": "exec_failure_samples", "detail": samples}],
            "recommendations": [
                "检查执行侧 5xx 的上游错误信息与响应体，确认是交易所限流/网关超时/连接问题",
                "对 close 增加幂等重试与退避，并确保双腿平仓具备可回滚/可重试的准原子语义",
                "将修复方案走最小沙箱：backtest + GateCheck，产出可复现报告后再走审批",
            ],
            "trigger": {"trigger_event": "execution.failure.trigger", "base_trace_id": base_trace_id, "idempotency_key": idem, "scope": scope, "group_key": group_key},
        }
        try:
            _agent_rca_emit(rca_report)
        except Exception:
            pass

        target_strategy_id = None
        try:
            if scope == "strategy":
                target_strategy_id = str(meta.get("strategy_id") or "").strip() or None
        except Exception:
            target_strategy_id = None

        strategy_ref = None
        try:
            if target_strategy_id:
                reg0 = _strategy_registry_load()
                entries0 = reg0.get("entries") if isinstance(reg0, dict) else None
                if isinstance(entries0, dict):
                    for v in entries0.values():
                        if not isinstance(v, dict):
                            continue
                        sid0 = str(v.get("strategy_id") or "").strip()
                        if sid0 != target_strategy_id:
                            continue
                        z0 = str(v.get("source_zip") or "").strip()
                        if sid0 and z0:
                            strategy_ref = {"strategy_id": sid0, "source_zip": z0}
                            break
        except Exception:
            strategy_ref = None
        if not isinstance(strategy_ref, dict):
            strategy_ref = _system_monitor_pick_strategy_ref()

        if isinstance(strategy_ref, dict) and strategy_ref.get("strategy_id") and strategy_ref.get("source_zip"):
            try:
                draft_req = {
                    "trace_id": trigger_trace_id,
                    "strategy_id": str(strategy_ref.get("strategy_id")),
                    "source_zip": str(strategy_ref.get("source_zip")),
                    "policy_ref": "gov_default",
                    "action": "config.apply",
                    "reason": f"exec_failure:{scope}:{group_key}",
                    "doc_refs": doc_refs,
                    "rca": rca_report,
                    "config_patch": (rollback_plan.get("config_patch") if isinstance(rollback_plan.get("config_patch"), dict) else {}),
                }
                draft = _agent_changeset_draft_build(draft_req)
                if isinstance(draft, dict) and bool(draft.get("ok")):
                    _agent_outbox_append_jsonl("changeset_drafts.jsonl", {"id": uuid.uuid4().hex, "trace_id": trigger_trace_id, "ts": int(_now_ms()), "type": "changeset.draft", "draft": draft})
                    _agent_emit_envelope_event(
                        event="change_bundle_draft",
                        trace_id=trigger_trace_id,
                        severity="info",
                        intent_level="L1",
                        ts_ms=int(_now_ms()),
                        inputs={"strategy_id": draft_req["strategy_id"], "source_zip": draft_req["source_zip"], "policy_ref": "gov_default", "base_trace_id": base_trace_id, "trigger_event": "execution.failure.trigger", "scope": scope, "group_key": group_key, "gate_plan": {"gates": gates, "policy_ref": "p3_default"}, "rollback_plan": rollback_plan},
                        evidence=[{"type": "rca", "source": "agent.rca", "trace_id": trigger_trace_id}],
                        outputs={"changeset_draft": {"strategy_id": draft_req["strategy_id"], "source_zip": draft_req["source_zip"], "ok": True}, "config_patch": draft_req.get("config_patch")},
                        doc_refs=doc_refs,
                    )
                    try:
                        approval_id = _approval_append({"trace_id": trigger_trace_id, "decision": "pending", "reason": f"exec_failure_change_bundle:{scope}", "changeset": draft.get("changeset") if isinstance(draft.get("changeset"), dict) else {}, "ts": int(_now_ms()), "scope": scope, "group_key": group_key})
                    except Exception:
                        approval_id = None
                    if approval_id:
                        _agent_emit_envelope_event(
                            event="approval.requested",
                            trace_id=trigger_trace_id,
                            severity="info",
                            intent_level="L1",
                            ts_ms=int(_now_ms()),
                            inputs={"approval_id": approval_id, "base_trace_id": base_trace_id, "trigger_event": "execution.failure.trigger", "scope": scope, "group_key": group_key},
                            evidence=[{"type": "changeset_draft", "source": "agent_outbox/changeset_drafts.jsonl", "trace_id": trigger_trace_id}],
                            outputs={"status": "pending"},
                            doc_refs=doc_refs,
                        )
            except Exception:
                pass

        candidates: List[Dict[str, Any]] = []
        try:
            reg = _strategy_registry_load()
            entries = reg.get("entries") if isinstance(reg, dict) else None
            if isinstance(entries, dict):
                items2 = [v for v in entries.values() if isinstance(v, dict)]
                items2.sort(key=lambda x: str(x.get("updated_at") or ""), reverse=True)
                if target_strategy_id:
                    pref = [x for x in items2 if str(x.get("strategy_id") or "").strip() == target_strategy_id]
                    rest = [x for x in items2 if str(x.get("strategy_id") or "").strip() != target_strategy_id]
                    items2 = pref + rest
                for it in items2:
                    sid = str(it.get("strategy_id") or "").strip()
                    z = str(it.get("source_zip") or "").strip()
                    if sid and z:
                        candidates.append({"strategy_id": sid, "source_zip": z})
                    if len(candidates) >= 3:
                        break
        except Exception:
            candidates = []

        sj_inputs = {
            "base_trace_id": base_trace_id,
            "scope": scope,
            "group_key": group_key,
            "path": meta.get("path"),
            "pair": meta.get("pair"),
            "strategy_id": meta.get("strategy_id"),
            "candidates": [{"strategy_id": c.get("strategy_id"), "source_zip": c.get("source_zip")} for c in candidates if isinstance(c, dict)],
            "data_snapshot": "latest",
            "config_snapshot": "user_data/config_local_backtest.json",
            "gates": gates,
        }
        sj_outputs = {"status": ("queued" if candidates else "blocked"), "block_reasons": ([] if candidates else ["no_candidate_in_registry"])}
        _agent_emit_envelope_event(
            event="sandbox.job.request",
            trace_id=trigger_trace_id,
            severity="info",
            intent_level="L1",
            ts_ms=int(now_ms),
            inputs=sj_inputs,
            evidence=[{"type": "rca", "source": "agent.rca", "trace_id": trigger_trace_id}, {"type": "strategy_registry", "source": "strategy_registry", "candidates_n": int(len(sj_inputs.get("candidates") or []))}],
            outputs={"sandbox_job_request": sj_outputs, "status": sj_outputs.get("status"), "block_reasons": sj_outputs.get("block_reasons")},
            doc_refs=doc_refs,
        )
        try:
            q_item = {
                "id": hashlib.sha256(f"sandbox|exec_failure|{scope}|{trigger_trace_id}|{idem}".encode("utf-8")).hexdigest()[:32],
                "trace_id": trigger_trace_id,
                "ts": int(_now_ms()),
                "type": "sandbox.job.request",
                "trigger": "execution.failure.trigger",
                "idempotency_key": idem,
                "inputs": sj_inputs,
                "outputs": sj_outputs,
            }
            _agent_outbox_append_jsonl("sandbox_queue.jsonl", q_item)
        except Exception:
            pass


def _sandbox_outbox_worker_enabled() -> bool:
    return bool(CONFIG.get("sandbox_outbox_worker_enabled", True))


def _agent_chat_outbox_worker_enabled() -> bool:
    return bool(CONFIG.get("agent_chat_outbox_worker_enabled", False))


def _agent_chat_worker_state_get() -> Dict[str, Any]:
    st = CONFIG.get("agent_chat_worker_state")
    if not isinstance(st, dict):
        st = {}
    processed = st.get("processed")
    if not isinstance(processed, dict):
        processed = {}
        st["processed"] = processed
    try:
        st["last_offset"] = int(st.get("last_offset") or 0)
    except Exception:
        st["last_offset"] = 0
    try:
        st["last_size"] = int(st.get("last_size") or 0)
    except Exception:
        st["last_size"] = 0
    return st


def _agent_chat_worker_state_set(st: Dict[str, Any]) -> None:
    if not isinstance(st, dict):
        return
    CONFIG["agent_chat_worker_state"] = st
    try:
        now_ms = int(_now_ms())
        last_ms = int(globals().get("_AGENT_CHAT_WORKER_LAST_SAVE_MS", 0) or 0)
        if now_ms - last_ms >= 60_000:
            _save_config()
            globals()["_AGENT_CHAT_WORKER_LAST_SAVE_MS"] = now_ms
    except Exception:
        pass


def _agent_chat_outbox_process_once(*, max_items: int = 1) -> Dict[str, Any]:
    try:
        if not _agent_chat_outbox_worker_enabled():
            return {"ok": True, "processed_n": 0, "skipped": "disabled"}
    except Exception:
        return {"ok": True, "processed_n": 0, "skipped": "disabled"}

    p = _agent_outbox_dir() / "chat.jsonl"
    if not p.exists():
        return {"ok": True, "processed_n": 0, "skipped": "missing_outbox"}

    st = _agent_chat_worker_state_get()
    processed = st.get("processed") if isinstance(st.get("processed"), dict) else {}
    last_offset = int(st.get("last_offset") or 0)
    last_size = int(st.get("last_size") or 0)
    last_offset0 = int(last_offset)
    last_size0 = int(last_size)
    reset0 = False

    try:
        cur_size = int(p.stat().st_size)
    except Exception:
        cur_size = 0
    if int(last_size) > 0 and int(cur_size) >= 0 and int(cur_size) < int(last_size):
        last_offset = 0
        processed = {}
        st["processed"] = processed
        reset0 = True

    processed_n = 0
    try:
        with open(p, "r", encoding="utf-8") as f:
            for i, line in enumerate(f):
                if i < int(last_offset):
                    continue
                if processed_n >= int(max(1, int(max_items))):
                    break
                raw = str(line or "").strip("\n")
                if not raw.strip():
                    last_offset = i + 1
                    continue
                try:
                    env = json.loads(raw)
                except Exception:
                    last_offset = i + 1
                    continue
                if not isinstance(env, dict):
                    last_offset = i + 1
                    continue
                if str(env.get("type") or "").strip() != "chat.command":
                    last_offset = i + 1
                    continue

                job_id = str(env.get("id") or "").strip()
                if not job_id:
                    try:
                        job_id = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:32]
                    except Exception:
                        job_id = uuid.uuid4().hex

                if processed.get(job_id) is not None:
                    last_offset = i + 1
                    continue

                trace_id = str(env.get("trace_id") or job_id).strip() or job_id
                cmd = {
                    "trace_id": trace_id,
                    "risk_level": env.get("risk_level"),
                    "intent": env.get("intent"),
                    "tool_plan": env.get("tool_plan"),
                    "frontend_evidence": env.get("frontend_evidence"),
                    "doc_refs": env.get("doc_refs"),
                }
                llm_cfg = env.get("llm") if isinstance(env.get("llm"), dict) else {}
                if "enabled" not in llm_cfg:
                    llm_cfg = dict(llm_cfg)
                    llm_cfg["enabled"] = bool(CONFIG.get("agent_chat_llm_enabled", True))
                if "provider" not in llm_cfg:
                    llm_cfg = dict(llm_cfg)
                    llm_cfg["provider"] = "ollama"

                def _run() -> None:
                    exec_mode = _agent_chat_driver_exec_mode()
                    if exec_mode == "subprocess":
                        _agent_chat_spawn_driver_subprocess(cmd, llm_cfg)
                        return
                    _agent_chat_driver_process(cmd, llm_cfg)

                threading.Thread(target=_run, daemon=True).start()

                try:
                    processed[job_id] = int(_now_ms())
                    if len(processed) > 4000:
                        ks = sorted(processed.items(), key=lambda kv: int(kv[1] or 0))
                        processed = dict(ks[-1200:])
                        st["processed"] = processed
                except Exception:
                    pass

                last_offset = i + 1
                processed_n += 1
    except Exception:
        return {"ok": False, "processed_n": int(processed_n), "error": "outbox_read_failed"}

    st["last_offset"] = int(last_offset)
    st["last_size"] = int(cur_size)
    st["processed"] = processed
    if processed_n > 0 or reset0 or int(last_offset) != int(last_offset0) or int(cur_size) != int(last_size0):
        _agent_chat_worker_state_set(st)
    return {"ok": True, "processed_n": int(processed_n), "last_offset": int(last_offset)}


def _agent_chat_outbox_worker_loop() -> None:
    while True:
        try:
            rep = _agent_chat_outbox_process_once(max_items=1)
            did = int((rep or {}).get("processed_n") or 0) if isinstance(rep, dict) else 0
            time.sleep(0.15 if did > 0 else 0.6)
        except Exception as e:
            try:
                globals()["_TWITTER_OUTBOX_LAST_ERROR"] = str(e)
                globals()["_TWITTER_OUTBOX_LAST_ERROR_MS"] = int(_now_ms())
            except Exception:
                pass
            time.sleep(2.0)


def _ensure_agent_chat_outbox_worker_started() -> None:
    try:
        if not _agent_chat_outbox_worker_enabled():
            return
    except Exception:
        return
    try:
        if ("pytest" in sys.modules) or bool(str(os.environ.get("PYTEST_CURRENT_TEST", "") or "").strip()):
            if not bool(CONFIG.get("agent_chat_outbox_worker_start_in_tests", False)):
                return
    except Exception:
        pass
    try:
        if _governance_is_test_mode() and (not bool(CONFIG.get("agent_chat_outbox_worker_start_in_tests", False))):
            return
    except Exception:
        pass
    try:
        flag = bool(globals().get("_AGENT_CHAT_OUTBOX_STARTED", False))
    except Exception:
        flag = False
    if flag:
        return
    try:
        t = threading.Thread(target=_agent_chat_outbox_worker_loop, daemon=True)
        t.start()
        globals()["_AGENT_CHAT_OUTBOX_STARTED"] = True
    except Exception:
        pass


