def _sandbox_gate_plan_make(inputs: Dict[str, Any]) -> Dict[str, Any]:
    gates_in = inputs.get("gates") if isinstance(inputs, dict) else None
    gates_raw = gates_in if isinstance(gates_in, list) else []
    gates = [str(x).strip().lower() for x in gates_raw if str(x or "").strip()]
    deep = ("robustness" in gates) or ("stress" in gates) or ("rolling" in gates)

    try:
        n_slices = int(CONFIG.get("sandbox_n_slices") or 0)
    except Exception:
        n_slices = 0
    if n_slices <= 0:
        try:
            base = int(CONFIG.get("gate_oos_rolls", 5) or 5)
        except Exception:
            base = 5
        n_slices = max(2, int(base) + 1)
    n_slices = max(2, min(24, int(n_slices)))

    n_bootstrap = 0
    n_shuffle = 0
    if deep:
        try:
            n_bootstrap = int(CONFIG.get("sandbox_n_bootstrap", 120) or 120)
        except Exception:
            n_bootstrap = 120
        try:
            n_shuffle = int(CONFIG.get("sandbox_n_shuffle", 120) or 120)
        except Exception:
            n_shuffle = 120
        n_bootstrap = max(0, min(2000, int(n_bootstrap)))
        n_shuffle = max(0, min(2000, int(n_shuffle)))

    eval_policy_ref = "p3_default"
    try:
        gplan = inputs.get("gate_plan") if isinstance(inputs, dict) else None
        if isinstance(gplan, dict) and gplan.get("policy_ref") is not None:
            eval_policy_ref = str(gplan.get("policy_ref") or "").strip() or "p3_default"
    except Exception:
        eval_policy_ref = "p3_default"

    return {
        "gates": gates,
        "deep_robustness": bool(deep),
        "eval_policy_ref": eval_policy_ref,
        "n_slices": int(n_slices),
        "n_bootstrap": int(n_bootstrap),
        "n_shuffle": int(n_shuffle),
    }


def _sandbox_backtest_zip_path(source_zip: str) -> Optional[Path]:
    s = str(source_zip or "").strip()
    if (not s) or (not s.lower().endswith(".zip")) or (".." in s) or ("/" in s) or ("\\" in s):
        return None
    p = _backtests_dir() / s
    if p.exists() and p.is_file():
        return p
    return None


def _sandbox_candidate_eval_and_sync(*, job_id: str, trace_id: str, strategy_id: str, source_zip: str, plan: Dict[str, Any]) -> Dict[str, Any]:
    sid = str(strategy_id or "").strip()
    z = str(source_zip or "").strip()
    if not sid or not z:
        return {"strategy_id": sid, "source_zip": z, "ok": False, "error": "missing_candidate_ref"}

    zip_path = _sandbox_backtest_zip_path(z)
    if zip_path is None:
        return {"strategy_id": sid, "source_zip": z, "ok": False, "error": "backtest_zip_not_found"}

    ent0 = _strategy_registry_get_entry(sid, z)
    family0 = (ent0.get("family") if isinstance(ent0, dict) else None) or "trend"
    stage0 = (ent0.get("stage") if isinstance(ent0, dict) else None) or "research"
    family = _strategy_family_normalize(family0) or "trend"
    stage = _strategy_stage_normalize(stage0) or "research"

    payload: Dict[str, Any] = {
        "strategy_id": sid,
        "family": family,
        "stage": stage,
        "eval_policy_ref": str(plan.get("eval_policy_ref") or "p3_default").strip() or "p3_default",
        "n_slices": int(plan.get("n_slices") or 6),
        "n_bootstrap": int(plan.get("n_bootstrap") or 0),
        "n_shuffle": int(plan.get("n_shuffle") or 0),
        "source": {"type": "sandbox", "job_id": str(job_id), "trace_id": str(trace_id)},
    }
    out, code = _strategy_registry_sync_from_zip_impl(data=payload, zip_path=Path(zip_path))
    if int(code) != 200 or (not isinstance(out, dict)) or (not bool(out.get("ok"))):
        return {
            "strategy_id": sid,
            "source_zip": z,
            "ok": False,
            "error": (out.get("error") if isinstance(out, dict) else "sync_failed") or "sync_failed",
            "code": int(code),
        }

    entry = out.get("entry") if isinstance(out.get("entry"), dict) else {}
    gate = entry.get("gate_result") if isinstance(entry.get("gate_result"), dict) else {}
    hard_fails = entry.get("hard_fails") if isinstance(entry.get("hard_fails"), list) else []
    hs = [str(x) for x in hard_fails if str(x or "").strip()][:50]
    gate_ok = bool(gate.get("ok", False)) and (not hs)
    return {
        "strategy_id": sid,
        "source_zip": z,
        "ok": True,
        "gate_ok": bool(gate_ok),
        "tier": entry.get("tier"),
        "robustness": entry.get("robustness"),
        "hard_fails": hs,
        "metrics_summary": (entry.get("metrics_summary") if isinstance(entry.get("metrics_summary"), dict) else {}),
        "oos_summary": (entry.get("oos_summary") if isinstance(entry.get("oos_summary"), dict) else {}),
        "gate_result": gate,
        "robustness_components": (entry.get("robustness_components") if isinstance(entry.get("robustness_components"), dict) else {}),
        "code_scan": (entry.get("code_scan") if isinstance(entry.get("code_scan"), dict) else {}),
        "backtest_spec": (entry.get("backtest_spec") if isinstance(entry.get("backtest_spec"), dict) else {}),
        "plan": dict(plan),
        "zip": str(zip_path.name),
    }


def _sandbox_gate_fail_diagnose_and_actions(
    *,
    trace_id: str,
    status: Optional[str],
    reasons: List[str],
    selected: Optional[Dict[str, Any]],
    plan: Dict[str, Any],
    base_trace_id: Optional[str],
    trigger_event: Optional[str],
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    tid = str(trace_id or "").strip() or uuid.uuid4().hex
    status0 = (None if status is None else str(status).strip().lower())
    hard_fails = []
    selected_sid = None
    selected_zip = None
    selected_metrics = {}
    selected_tier = None
    selected_rob = None
    if isinstance(selected, dict):
        selected_sid = str(selected.get("strategy_id") or "").strip() or None
        selected_zip = str(selected.get("source_zip") or "").strip() or None
        selected_tier = selected.get("tier")
        selected_rob = selected.get("robustness")
        selected_metrics = (selected.get("metrics_summary") if isinstance(selected.get("metrics_summary"), dict) else {})
        hf = selected.get("hard_fails") if isinstance(selected.get("hard_fails"), list) else []
        hard_fails = [str(x) for x in hf if str(x or "").strip()][:50]

    keys = [str(x or "").strip() for x in (hard_fails or reasons or []) if str(x or "").strip()]
    keys_low = [x.lower() for x in keys]
    primary = keys[0] if keys else ("blocked" if status0 == "blocked" else "sandbox_failed")

    code = "sandbox.gate_fail"
    summary = "沙箱门禁失败"
    if status0 == "blocked":
        code = "sandbox.blocked"
        summary = "沙箱任务被阻塞"
    elif any(x.startswith("min_trades<") for x in keys_low):
        code = "gate.min_trades"
        summary = "交易数不足，无法通过统计门禁"
    elif any(x.startswith("maxdd_pct>") for x in keys_low):
        code = "gate.max_drawdown"
        summary = "最大回撤超限，触发硬门禁"
    elif any(x.startswith("weekly_winrate<") for x in keys_low):
        code = "gate.weekly_winrate"
        summary = "周胜率不足，触发硬门禁"
    elif "max_daily_loss_exceed" in keys_low:
        code = "gate.max_daily_loss"
        summary = "单日最大亏损超限，触发硬门禁"
    elif "max_weekly_loss_exceed" in keys_low:
        code = "gate.max_weekly_loss"
        summary = "单周最大亏损超限，触发硬门禁"
    elif "cost_profile_missing" in keys_low or "missing_cost_profile" in keys_low:
        code = "gate.cost_profile_missing"
        summary = "缺少费用/滑点成本画像，无法进行可审计评估"
    elif "oos_fail" in keys_low:
        code = "gate.oos_fail"
        summary = "样本外（walk-forward）未通过稳健性门禁"
    elif "code_scan_missing" in keys_low:
        code = "gate.code_scan_missing"
        summary = "缺少代码扫描结果，触发硬门禁"
    elif "code_scan_fail" in keys_low or "strategy_code_scan_failed" in keys_low:
        code = "gate.code_scan_fail"
        summary = "代码扫描未通过，触发硬门禁"

    diagnosis = {
        "ok": True,
        "ts": int(_now_ms()),
        "code": str(code),
        "summary": str(summary),
        "primary": str(primary),
        "status": status0,
        "hard_fails": list(hard_fails),
        "reasons": [str(x) for x in reasons if str(x or "").strip()][:30],
        "selected": {
            "strategy_id": selected_sid,
            "source_zip": selected_zip,
            "tier": selected_tier,
            "robustness": selected_rob,
            "metrics_summary": selected_metrics,
        },
        "context": {
            "eval_policy_ref": str(plan.get("eval_policy_ref") or "p3_default").strip() or "p3_default",
            "base_trace_id": base_trace_id,
            "trigger_event": trigger_event,
        },
    }

    actions: List[Dict[str, Any]] = []

    actions.append(
        {
            "id": "verify.trace_replay",
            "kind": "readonly.verify",
            "priority": "high",
            "title": "只读复盘：trace 链路回放",
            "how": {"type": "http", "method": "GET", "path": "/agent/trace/replay", "query": {"trace_id": tid, "max_orders": 120}},
        }
    )
    actions.append(
        {
            "id": "verify.audit_replay",
            "kind": "readonly.verify",
            "priority": "medium",
            "title": "只读复盘：审计日志回放",
            "how": {"type": "http", "method": "GET", "path": "/agent/audit/replay", "query": {"trace_id": tid, "limit": 3000}},
        }
    )

    if selected_sid and selected_zip:
        actions.append(
            {
                "id": "verify.registry_entry",
                "kind": "readonly.verify",
                "priority": "medium",
                "title": "只读核对：策略注册表 entry",
                "how": {
                    "type": "http",
                    "method": "GET",
                    "path": "/search",
                    "query": {"q": selected_sid, "zip": selected_zip, "limit": 50, "offset": 0, "sort": "updated_desc"},
                },
            }
        )

    actions.append(
        {
            "id": "rca.analyze",
            "kind": "rca",
            "priority": "high",
            "title": "触发 RCA：生成诊断假设与验证计划",
            "how": {
                "type": "http",
                "method": "POST",
                "path": "/agent/rca/analyze",
                "json": {"trace_id": tid, "include_dq": False, "include_eq": False, "async": True},
            },
        }
    )

    actions.append(
        {
            "id": "paramopt.plan",
            "kind": "paramopt",
            "priority": "low",
            "title": "生成参数搜索空间（paramopt）",
            "how": {
                "type": "http",
                "method": "POST",
                "path": "/agent/paramopt/search_space",
                "json": {"trace_id": tid, "scopes": ["strategy"], "include_modes": ["suggest", "auto"]},
            },
        }
    )

    if any(x.startswith("min_trades<") for x in keys_low):
        actions.append(
            {
                "id": "sandbox.expand_timerange",
                "kind": "sandbox",
                "priority": "high",
                "title": "调整沙箱：扩大回测窗口或降低 min_trades 门槛",
                "how": {"type": "hint", "notes": {"suggest": ["扩大 timerange", "调整交易频率/过滤条件", "仅研究态可临时降低 policy.min_trades"]}},
            }
        )
    if any(x.startswith("maxdd_pct>") for x in keys_low):
        actions.append(
            {
                "id": "sandbox.reduce_dd",
                "kind": "sandbox",
                "priority": "high",
                "title": "调整策略：降低回撤以满足门禁",
                "how": {"type": "hint", "notes": {"suggest": ["收紧止损/风控", "降低杠杆/仓位", "减少逆势加仓"]}},
            }
        )
    if "cost_profile_missing" in keys_low or "missing_cost_profile" in keys_low:
        actions.append(
            {
                "id": "sandbox.fill_cost_profile",
                "kind": "sandbox",
                "priority": "high",
                "title": "补齐成本画像：fee 与 slippage_bps",
                "how": {"type": "hint", "notes": {"suggest": ["在 config 中补齐 fee 与 slippage_bps", "或设置可复用 cost_profile_id"]}},
            }
        )
    if "code_scan_missing" in keys_low or "code_scan_fail" in keys_low or "strategy_code_scan_failed" in keys_low:
        actions.append(
            {
                "id": "fix.code_scan",
                "kind": "fix",
                "priority": "high",
                "title": "修复代码扫描问题（禁止导入/网络/写文件等）",
                "how": {"type": "hint", "notes": {"suggest": ["定位 reports/code_scan.json", "移除命中规则的代码片段"]}},
            }
        )

    actions = actions[:12]
    return diagnosis, actions


def _sandbox_job_result_emit(*, trace_id: str, now_ms: int, inputs: Dict[str, Any], outputs: Dict[str, Any], evidence: List[Dict[str, Any]], doc_refs: List[Dict[str, str]]) -> None:
    try:
        sev = "info"
        try:
            gr = outputs.get("gate_result") if isinstance(outputs.get("gate_result"), dict) else {}
            if str(gr.get("decision") or "").strip().lower() == "fail":
                sev = "warn"
        except Exception:
            sev = "warn"
        _agent_emit_envelope_event(
            event="sandbox.job.result",
            trace_id=str(trace_id),
            severity=sev,
            intent_level="L1",
            ts_ms=int(now_ms),
            inputs=(inputs if isinstance(inputs, dict) else {}),
            evidence=(evidence if isinstance(evidence, list) else []),
            outputs=(outputs if isinstance(outputs, dict) else {}),
            doc_refs=doc_refs,
        )
    except Exception:
        pass
    try:
        gr2 = outputs.get("gate_result") if isinstance(outputs, dict) and isinstance(outputs.get("gate_result"), dict) else {}
        dec = str(gr2.get("decision") or "").strip().lower()
        if dec not in ("pass", "fail", "blocked", "inconclusive"):
            dec = "inconclusive"
        gating_report = {
            "trace_id": str(trace_id),
            "ts": int(now_ms),
            "decision": dec,
            "items": [
                {
                    "kind": "p3",
                    "pass": (dec == "pass"),
                    "detail": (gr2 if isinstance(gr2, dict) else {}),
                }
            ],
        }
        gating_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="gating_report.json", obj=gating_report)
        if gating_path and isinstance(gating_report, dict):
            gating_report["artifact_files"] = {"gating_report_json": gating_path}
        gating_ref = _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="gating_report", artifact=gating_report)
        try:
            _agent_pipeline_on_sandbox_gate_result(trace_id=str(trace_id), now_ms=int(now_ms), gate_result=(gr2 if isinstance(gr2, dict) else {}), gating_report_ref=gating_ref)
        except Exception:
            pass
    except Exception:
        pass


def _sandbox_job_changeset_draft_maybe_emit(*, trace_id: str, now_ms: int, base_trace_id: Optional[str], trigger_event: Optional[str], candidates: List[Dict[str, Any]], doc_refs: List[Dict[str, str]]) -> None:
    policy_ref = "gov_default"
    if not candidates:
        try:
            _agent_emit_envelope_event(
                event="change_bundle_draft",
                trace_id=str(trace_id),
                severity="warn",
                intent_level="L1",
                ts_ms=int(now_ms),
                inputs={"policy_ref": policy_ref, "base_trace_id": base_trace_id, "trigger_event": trigger_event},
                evidence=[{"type": "sandbox", "source": "sandbox.job.result", "trace_id": str(trace_id)}],
                outputs={"changeset_draft": None, "ok": False, "reasons": ["no_candidate"], "action": "config.apply"},
                doc_refs=doc_refs,
            )
        except Exception:
            pass
        return

    c0 = candidates[0] if isinstance(candidates[0], dict) else None
    if not isinstance(c0, dict):
        return
    sid = str(c0.get("strategy_id") or "").strip()
    z = str(c0.get("source_zip") or "").strip()
    if not sid or not z:
        return
    try:
        draft_req = {
            "trace_id": str(trace_id),
            "strategy_id": sid,
            "source_zip": z,
            "policy_ref": policy_ref,
            "action": "config.apply",
            "reason": (str(trigger_event or "sandbox.job.result").strip() or "sandbox.job.result"),
            "doc_refs": doc_refs,
        }
        draft = _agent_changeset_draft_build(draft_req)
        if not (isinstance(draft, dict) and bool(draft.get("ok"))):
            _agent_emit_envelope_event(
                event="change_bundle_draft",
                trace_id=str(trace_id),
                severity="warn",
                intent_level="L1",
                ts_ms=int(now_ms),
                inputs={"strategy_id": sid, "source_zip": z, "policy_ref": policy_ref, "base_trace_id": base_trace_id, "trigger_event": trigger_event},
                evidence=[{"type": "registry", "source": "strategy_registry", "strategy_id": sid, "source_zip": z}],
                outputs={"changeset_draft": None, "ok": False, "error": str(draft.get("error") if isinstance(draft, dict) else "draft_failed")},
                doc_refs=doc_refs,
            )
            return
        _agent_outbox_append_jsonl("changeset_drafts.jsonl", {"id": uuid.uuid4().hex, "trace_id": str(trace_id), "ts": int(_now_ms()), "type": "changeset.draft", "draft": draft})
        _agent_emit_envelope_event(
            event="change_bundle_draft",
            trace_id=str(trace_id),
            severity="info",
            intent_level="L1",
            ts_ms=int(_now_ms()),
            inputs={"strategy_id": sid, "source_zip": z, "policy_ref": policy_ref, "base_trace_id": base_trace_id, "trigger_event": trigger_event},
            evidence=[{"type": "registry", "source": "strategy_registry", "strategy_id": sid, "source_zip": z}],
            outputs={"changeset_draft": {"strategy_id": sid, "source_zip": z, "ok": True}},
            doc_refs=doc_refs,
        )
    except Exception:
        pass


def _sandbox_supply_chain_approval_maybe_emit(
    *,
    trace_id: str,
    now_ms: int,
    trigger_event: Optional[str],
    gate_decision: str,
    gate_result: Dict[str, Any],
    selected: Optional[Dict[str, Any]],
    doc_refs: List[Dict[str, Any]],
) -> Optional[str]:
    trig = (None if trigger_event is None else str(trigger_event).strip()) or ""
    if trig not in ("repo.fetch_strategy", "automation.supply_chain", "supply_chain"):
        return None
    if str(gate_decision or "").strip().lower() != "pass":
        return None
    sel = selected if isinstance(selected, dict) else None
    if not isinstance(sel, dict):
        return None
    sid = str(sel.get("strategy_id") or "").strip()
    z = str(sel.get("source_zip") or "").strip()
    if not sid or not z:
        return None

    approval_action = "strategy.supply_chain.approve"
    reason = "strategy_supply_chain"
    approval_id = None
    try:
        approval_id = _approval_append(
            {
                "trace_id": str(trace_id),
                "decision": "pending",
                "reason": reason,
                "action": approval_action,
                "scope": "governance",
                "gate_results": (gate_result if isinstance(gate_result, dict) else {}),
                "doc_refs": _doc_refs_sanitize(doc_refs),
                "evidence": {"selected": {"strategy_id": sid, "source_zip": z}, "trigger_event": trig},
                "ts": int(now_ms),
            }
        )
    except Exception:
        approval_id = None
    if not approval_id:
        return None

    try:
        pkg = {
            "trace_id": str(trace_id),
            "approval_id": str(approval_id),
            "action": approval_action,
            "ts": int(now_ms),
            "reason": reason,
            "selected": {"strategy_id": sid, "source_zip": z},
        }
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="approval_request", artifact=pkg)
    except Exception:
        pass
    return str(approval_id)


def _agent_pnl_escalate_after_sandbox_fail(
    *,
    trigger_trace_id: str,
    base_trace_id: Optional[str],
    trigger_event: Optional[str],
    gate_result: Dict[str, Any],
) -> None:
    gr = (gate_result if isinstance(gate_result, dict) else {})
    if str(gr.get("decision") or "").strip().lower() != "fail":
        return

    try:
        auto_enabled = bool(CONFIG.get("agent_pnl_auto_run_tasks", True))
    except Exception:
        auto_enabled = True
    if not auto_enabled:
        return

    st = _agent_pnl_trigger_state_get()
    now_ms = int(_now_ms())
    try:
        min_interval_sec = int(CONFIG.get("agent_pnl_auto_run_min_interval_sec", 1800) or 1800)
    except Exception:
        min_interval_sec = 1800
    min_interval_sec = max(60, min(7 * 86400, int(min_interval_sec)))
    last_ms = 0
    try:
        last_ms = int(st.get("last_auto_run_ms") or 0)
    except Exception:
        last_ms = 0
    if int(now_ms) - int(last_ms) < int(min_interval_sec) * 1000:
        return
    st["last_auto_run_ms"] = int(now_ms)
    try:
        _agent_pnl_trigger_state_save(st)
    except Exception:
        pass

    tid = (str(trigger_trace_id or "").strip() or uuid.uuid4().hex)
    btid = (None if base_trace_id is None else str(base_trace_id).strip()) or ""
    trig = (None if trigger_event is None else str(trigger_event).strip()) or "sandbox.job.result"

    reasons = gr.get("reasons") if isinstance(gr.get("reasons"), list) else []
    hard_fails: List[str] = [str(x) for x in reasons if str(x or "").strip()][:12]
    ctx = {"trigger_event": trig, "base_trace_id": btid, "sandbox_gate_fail": True, "sandbox_reasons": hard_fails}

    plan = {
        "ok": True,
        "trace_id": tid,
        "base_trace_id": btid,
        "trigger_event": trig,
        "actions": [
            {"id": "stop_bleeding", "type": "agent.repair", "mode": "suggest", "request": {"trace_id": tid, "mode": "suggest", "lookback_days": 7.0, "pair": None, "strategy": None, "context": ctx}},
            {
                "id": "paramopt_runtime_config",
                "type": "agent.paramopt",
                "mode": "suggest",
                "request": {"trace_id": tid, "mode": "suggest", "scopes": ["strategy"], "include_suggest_only": True, "family": "lr", "eval_mode": "rolling", "folds": 3, "n_init": 2, "n_iter": 3, "skip_robustness": True, "context": ctx},
            },
            {"id": "fallback_strategy_code_paramopt", "type": "strategy.code.paramopt", "mode": "plan_only", "request": {"trace_id": tid, "base_trace_id": btid, "trigger_event": trig}},
        ],
    }
    try:
        t = threading.Thread(
            target=_agent_pnl_auto_run_tasks,
            kwargs={"trigger_trace_id": str(tid), "base_trace_id": str(btid), "trigger_event": str(trig), "plan": dict(plan)},
            daemon=True,
        )
        t.start()
    except Exception:
        pass


def _sandbox_outbox_worker_loop() -> None:
    while True:
        try:
            try:
                rep = _sandbox_outbox_process_queue_once(max_items=1)
            except Exception:
                rep = {"ok": False}
            did = int(rep.get("processed_n") or 0) if isinstance(rep, dict) else 0
            time.sleep(0.2 if did > 0 else 0.8)
        except Exception:
            time.sleep(2.0)


def _sandbox_outbox_process_queue_once(*, max_items: int = 3) -> Dict[str, Any]:
    try:
        if not _sandbox_outbox_worker_enabled():
            return {"ok": True, "processed_n": 0, "skipped": "disabled"}
    except Exception:
        return {"ok": True, "processed_n": 0, "skipped": "disabled"}

    q = _agent_outbox_dir() / "sandbox_queue.jsonl"
    if not q.exists():
        return {"ok": True, "processed_n": 0, "skipped": "missing_queue"}

    st = _sandbox_worker_state_get()
    processed = st.get("processed") if isinstance(st.get("processed"), dict) else {}
    last_offset = int(st.get("last_offset") or 0)

    lines: List[str] = []
    try:
        with open(q, "r", encoding="utf-8") as f:
            lines = f.readlines()
    except Exception:
        return {"ok": False, "error": "queue_read_failed", "processed_n": 0}

    if last_offset > len(lines):
        last_offset = 0

    now_ms = int(_now_ms())
    doc_refs = _agent_doc_refs_48_default()
    pol = CONFIG.get("sandbox_policy") or {}
    try:
        lim = int(pol.get("concurrent_limit") or 2)
    except Exception:
        lim = 2
    lim = max(1, min(32, int(lim)))

    processed_n = 0
    for i in range(last_offset, len(lines)):
        if processed_n >= int(max(1, int(max_items))):
            break

        raw = lines[i].strip("\n")
        if not raw.strip():
            last_offset = i + 1
            continue
        try:
            env = json.loads(raw)
        except Exception:
            last_offset = i + 1
            continue
        if not isinstance(env, dict):
            last_offset = i + 1
            continue

        job_type = str(env.get("type") or "").strip() or str(env.get("event") or "").strip()
        if job_type not in ("sandbox.job.request", "sandbox.job"):
            last_offset = i + 1
            continue

        job_id = str(env.get("id") or "").strip()
        if not job_id:
            try:
                job_id = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:32]
            except Exception:
                job_id = uuid.uuid4().hex

        if processed.get(job_id) is not None:
            last_offset = i + 1
            continue

        sb_st = CONFIG.get("sandbox_state")
        if not isinstance(sb_st, dict):
            sb_st = {"running": 0, "queued": 0}
        try:
            stale_reset_ms = int(pol.get("stale_running_reset_ms", 300000) or 300000)
        except Exception:
            stale_reset_ms = 300000
        stale_reset_ms = max(30_000, min(86_400_000, int(stale_reset_ms)))
        try:
            running0 = int(sb_st.get("running") or 0)
        except Exception:
            running0 = 0
        if running0 > 0:
            last_mark = 0
            try:
                last_mark = max(int(sb_st.get("last_job_end_ms") or 0), int(sb_st.get("last_job_start_ms") or 0))
            except Exception:
                last_mark = 0
            if int(last_mark) > 0 and int(now_ms) - int(last_mark) > int(stale_reset_ms):
                sb_st["running"] = 0
                CONFIG["sandbox_state"] = sb_st
                try:
                    _save_config()
                except Exception:
                    pass
        if int(sb_st.get("running") or 0) >= int(lim):
            break

        trace_id = str(env.get("trace_id") or job_id).strip() or job_id
        inputs = env.get("inputs") if isinstance(env.get("inputs"), dict) else (env.get("payload") if isinstance(env.get("payload"), dict) else {})
        outputs = env.get("outputs") if isinstance(env.get("outputs"), dict) else {}
        trigger_event = str(env.get("trigger") or "").strip() or None
        base_trace_id = None
        try:
            base_trace_id = str(inputs.get("base_trace_id") or "").strip() or None
        except Exception:
            base_trace_id = None
        candidates_raw = inputs.get("candidates") if isinstance(inputs.get("candidates"), list) else []
        candidates: List[Dict[str, Any]] = []
        for c in candidates_raw:
            if isinstance(c, dict):
                sid = str(c.get("strategy_id") or "").strip()
                z = str(c.get("source_zip") or "").strip()
                if sid and z:
                    candidates.append({"strategy_id": sid, "source_zip": z})

        status = None
        try:
            status = str(outputs.get("status") or "").strip().lower() or None
        except Exception:
            status = None
        block_reasons = outputs.get("block_reasons") if isinstance(outputs.get("block_reasons"), list) else []
        base_reasons = [str(x) for x in block_reasons if str(x or "").strip()][:10]

        sb_st["running"] = int(sb_st.get("running") or 0) + 1
        if int(sb_st.get("queued") or 0) > 0:
            sb_st["queued"] = max(0, int(sb_st.get("queued") or 0) - 1)
        sb_st["last_job_start_ms"] = int(now_ms)
        sb_st["last_job_id"] = str(job_id)
        CONFIG["sandbox_state"] = sb_st
        try:
            _save_config()
        except Exception:
            pass

        try:
            plan = _sandbox_gate_plan_make(inputs if isinstance(inputs, dict) else {})
            cand_reports: List[Dict[str, Any]] = []
            if status != "blocked" and candidates:
                for c in candidates[:5]:
                    try:
                        rep = _sandbox_candidate_eval_and_sync(
                            job_id=job_id,
                            trace_id=trace_id,
                            strategy_id=str(c.get("strategy_id") or ""),
                            source_zip=str(c.get("source_zip") or ""),
                            plan=plan,
                        )
                    except Exception:
                        rep = {"strategy_id": str(c.get("strategy_id") or ""), "source_zip": str(c.get("source_zip") or ""), "ok": False, "error": "sandbox_eval_failed"}
                    if isinstance(rep, dict):
                        cand_reports.append(rep)

            selected = None
            for r in cand_reports:
                if bool(r.get("ok")) and bool(r.get("gate_ok")):
                    selected = r
                    break
            if selected is None and cand_reports:
                selected = cand_reports[0]

            gate_decision = "pass" if (isinstance(selected, dict) and bool(selected.get("gate_ok"))) else "fail"
            reasons: List[str] = []
            if gate_decision == "fail":
                if status == "blocked":
                    reasons = base_reasons or ["blocked"]
                elif isinstance(selected, dict) and isinstance(selected.get("hard_fails"), list) and selected.get("hard_fails"):
                    reasons = [str(x) for x in (selected.get("hard_fails") or []) if str(x or "").strip()][:20]
                elif isinstance(selected, dict) and selected.get("error") is not None:
                    reasons = [str(selected.get("error") or "sandbox_failed")]
                else:
                    reasons = base_reasons or ["sandbox_failed"]

            cand_summaries: List[Dict[str, Any]] = []
            for r in cand_reports:
                if not isinstance(r, dict):
                    continue
                cand_summaries.append(
                    {
                        "strategy_id": r.get("strategy_id"),
                        "source_zip": r.get("source_zip"),
                        "ok": bool(r.get("ok")),
                        "gate_ok": bool(r.get("gate_ok")),
                        "tier": r.get("tier"),
                        "robustness": r.get("robustness"),
                        "hard_fails": (r.get("hard_fails") if isinstance(r.get("hard_fails"), list) else []),
                        "robustness_components": (r.get("robustness_components") if isinstance(r.get("robustness_components"), dict) else {}),
                        "code_scan": (r.get("code_scan") if isinstance(r.get("code_scan"), dict) else {}),
                        "backtest_spec": (r.get("backtest_spec") if isinstance(r.get("backtest_spec"), dict) else {}),
                    }
                )

            gate_result = {
                "ok": True,
                "decision": gate_decision,
                "reasons": reasons,
                "plan": plan,
                "candidates": cand_summaries,
                "selected": ({"strategy_id": selected.get("strategy_id"), "source_zip": selected.get("source_zip")} if isinstance(selected, dict) else None),
            }

            if str(gate_decision) == "fail":
                diag, acts = _sandbox_gate_fail_diagnose_and_actions(
                    trace_id=trace_id,
                    status=status,
                    reasons=reasons,
                    selected=(selected if isinstance(selected, dict) else None),
                    plan=(plan if isinstance(plan, dict) else {}),
                    base_trace_id=base_trace_id,
                    trigger_event=trigger_event,
                )
                gate_result["diagnosis_summary"] = diag
                gate_result["candidate_actions"] = acts

            _sandbox_job_result_emit(
                trace_id=trace_id,
                now_ms=now_ms,
                inputs={"base_trace_id": base_trace_id, "trigger_event": trigger_event, "candidates": candidates},
                outputs={"gate_result": gate_result},
                evidence=[{"type": "sandbox_queue", "source": "agent_outbox/sandbox_queue.jsonl", "job_id": job_id}],
                doc_refs=doc_refs,
            )

            if str(gate_decision) == "fail" and isinstance(gate_result.get("candidate_actions"), list):
                try:
                    _agent_emit_envelope_event(
                        event="sandbox.next_actions",
                        trace_id=str(trace_id),
                        severity="info",
                        intent_level="L1",
                        ts_ms=int(_now_ms()),
                        inputs={"base_trace_id": base_trace_id, "trigger_event": trigger_event, "job_id": job_id},
                        evidence=[{"type": "sandbox", "source": "sandbox.job.result", "trace_id": str(trace_id)}],
                        outputs={"diagnosis_summary": gate_result.get("diagnosis_summary"), "candidate_actions": gate_result.get("candidate_actions")},
                        doc_refs=doc_refs,
                    )
                except Exception:
                    pass

                try:
                    auto_rca = bool(pol.get("auto_rca_on_fail", False))
                except Exception:
                    auto_rca = False
                if auto_rca:
                    try:
                        llm_provider = "ollama"
                        llm_model = ""
                        try:
                            llm_model = str(os.environ.get("AGENT_OLLAMA_MODEL", "") or "").strip()
                        except Exception:
                            llm_model = ""
                        if not llm_model:
                            try:
                                llm_model = str(CONFIG.get("agent_ollama_model") or "").strip()
                            except Exception:
                                llm_model = ""
                        if not llm_model:
                            llm_model = "qwen2.5:7b-instruct"
                        llm_cfg = {"enabled": bool(llm_model), "provider": llm_provider, "model": llm_model, "timeout_sec": 60}
                        t = threading.Thread(
                            target=_agent_rca_analyze_process,
                            args=(str(trace_id),),
                            kwargs={"include_dq": False, "include_eq": False, "llm_cfg": llm_cfg},
                            daemon=True,
                        )
                        t.start()
                    except Exception:
                        pass

            if str(gate_decision) != "fail" and isinstance(selected, dict) and selected.get("strategy_id") and selected.get("source_zip"):
                _sandbox_job_changeset_draft_maybe_emit(
                    trace_id=trace_id,
                    now_ms=now_ms,
                    base_trace_id=base_trace_id,
                    trigger_event=trigger_event,
                    candidates=[{"strategy_id": str(selected.get("strategy_id")), "source_zip": str(selected.get("source_zip"))}],
                    doc_refs=doc_refs,
                )
            else:
                _sandbox_job_changeset_draft_maybe_emit(
                    trace_id=trace_id,
                    now_ms=now_ms,
                    base_trace_id=base_trace_id,
                    trigger_event=trigger_event,
                    candidates=[],
                    doc_refs=doc_refs,
                )
            try:
                _sandbox_supply_chain_approval_maybe_emit(
                    trace_id=str(trace_id),
                    now_ms=int(now_ms),
                    trigger_event=trigger_event,
                    gate_decision=str(gate_decision),
                    gate_result=(gate_result if isinstance(gate_result, dict) else {}),
                    selected=(selected if isinstance(selected, dict) else None),
                    doc_refs=doc_refs,
                )
            except Exception:
                pass
            try:
                _agent_pnl_escalate_after_sandbox_fail(
                    trigger_trace_id=str(trace_id),
                    base_trace_id=base_trace_id,
                    trigger_event=trigger_event,
                    gate_result=gate_result,
                )
            except Exception:
                pass

            processed[job_id] = int(now_ms)
            if len(processed) > 2000:
                try:
                    ks = sorted(processed.items(), key=lambda kv: int(kv[1] or 0))
                    processed = dict(ks[-1500:])
                except Exception:
                    processed = dict(list(processed.items())[-1500:])
            st["processed"] = processed
            last_offset = i + 1
            st["last_offset"] = int(last_offset)
            _sandbox_worker_state_set(st)
            processed_n += 1
        finally:
            sb_st2 = CONFIG.get("sandbox_state")
            if not isinstance(sb_st2, dict):
                sb_st2 = {"running": 0, "queued": 0}
            sb_st2["running"] = max(0, int(sb_st2.get("running") or 0) - 1)
            sb_st2["last_job_end_ms"] = int(_now_ms())
            CONFIG["sandbox_state"] = sb_st2
            try:
                _save_config()
            except Exception:
                pass

    st["last_offset"] = int(last_offset)
    _sandbox_worker_state_set(st)
    return {"ok": True, "processed_n": int(processed_n), "last_offset": int(last_offset)}


def _ensure_sandbox_outbox_worker_started() -> None:
    try:
        if ("pytest" in sys.modules) or bool(str(os.environ.get("PYTEST_CURRENT_TEST", "") or "").strip()):
            if not bool(CONFIG.get("sandbox_outbox_worker_start_in_tests", False)):
                return
    except Exception:
        pass
    try:
        if _governance_is_test_mode() and (not bool(CONFIG.get("sandbox_outbox_worker_start_in_tests", False))):
            return
    except Exception:
        pass
    try:
        flag = bool(globals().get("_SANDBOX_OUTBOX_STARTED", False))
    except Exception:
        flag = False
    if flag:
        return
    try:
        t = threading.Thread(target=_sandbox_outbox_worker_loop, daemon=True)
        t.start()
        globals()["_SANDBOX_OUTBOX_STARTED"] = True
    except Exception:
        pass


def _ab_owner_cooldown_until_ms(owner: Any) -> int:
    o = _ab_norm_owner(owner)
    st = _ab_alloc_state_get()
    owners = st.get("owners")
    if not isinstance(owners, dict):
        return 0
    rec = owners.get(o)
    if not isinstance(rec, dict):
        return 0
    try:
        return int(rec.get("cooldown_until_ms") or 0)
    except Exception:
        return 0


def _ab_owner_in_cooldown(owner: Any, now_ms: int) -> bool:
    until = _ab_owner_cooldown_until_ms(owner)
    return int(until) > 0 and int(now_ms) < int(until)


def _ab_filter_intents_by_cooldown(intents: List[Intent], now_ms: int) -> List[Intent]:
    out: List[Intent] = []
    for it in list(intents or []):
        if not isinstance(it, dict):
            continue
        owner = _ab_norm_owner(it.get("owner"))
        action = str(it.get("action") or "hold").strip().lower()
        if action == "open" and _ab_owner_in_cooldown(owner, now_ms=int(now_ms)):
            _ab_record_intent_reject(it, reason="ab_cooldown", stage="cooldown", now_ms=int(now_ms))
            continue
        out.append(it)
    return out


def _ab_record_exit_settlement(pair: str, pos: Dict[str, Any], data: Dict[str, Any], now_ms: int, notional_usdc: float, ret_ratio: float, pnl_usdc: float) -> None:
    try:
        cap = int(CONFIG.get("ab_settlement_history_max", 10000) or 10000)
    except Exception:
        cap = 10000
    cap = max(500, int(cap))

    contrib = None
    try:
        if isinstance((pos or {}).get("owner_contrib"), dict):
            contrib = dict((pos or {}).get("owner_contrib") or {})
    except Exception:
        contrib = None
    if contrib is None:
        try:
            if isinstance(data.get("owner_contrib"), dict):
                contrib = dict(data.get("owner_contrib") or {})
        except Exception:
            contrib = None
    if contrib is None:
        try:
            ao = (pos or {}).get("ab_owner")
            if ao is None:
                ao = data.get("ab_owner")
            if ao is not None:
                contrib = {str(ao).strip().lower(): 1.0}
        except Exception:
            contrib = None
    if contrib is None:
        contrib = {"strategy": 1.0}

    weights: Dict[str, float] = {"strategy": 0.0, "quant": 0.0}
    for k in ("strategy", "quant"):
        try:
            v = contrib.get(k)
            if v is not None and math.isfinite(float(v)) and float(v) > 0.0:
                weights[k] = float(v)
        except Exception:
            continue
    s = float(weights.get("strategy", 0.0) + weights.get("quant", 0.0))
    if s <= 0.0:
        weights = {"strategy": 1.0, "quant": 0.0}
        s = 1.0

    duration_ms = None
    try:
        ts0 = int((pos or {}).get("entry_ts") or (pos or {}).get("ts") or 0)
        if ts0 > 0:
            duration_ms = int(max(0, int(now_ms) - int(ts0)))
    except Exception:
        duration_ms = None

    fees_usdc = None
    funding_usdc = None
    slippage_usdc = None
    try:
        if data.get("fee_abs") is not None:
            fees_usdc = float(data.get("fee_abs") or 0.0)
    except Exception:
        fees_usdc = None
    try:
        if data.get("funding_abs") is not None:
            funding_usdc = float(data.get("funding_abs") or 0.0)
    except Exception:
        funding_usdc = None
    try:
        if data.get("slippage_abs") is not None:
            slippage_usdc = float(data.get("slippage_abs") or 0.0)
    except Exception:
        slippage_usdc = None

    reason = None
    try:
        reason = data.get("exit_reason")
        if reason is None:
            reason = data.get("reason")
        if reason is None:
            reason = data.get("exit_tag")
    except Exception:
        reason = None

    h = _ab_settlements_get()
    sid = None
    gid = None
    sys_id = None
    try:
        sid = data.get("strategy_id") if isinstance(data, dict) else None
        if sid is None and isinstance(pos, dict):
            sid = pos.get("strategy_id")
    except Exception:
        sid = None
    try:
        gid = data.get("group_id") if isinstance(data, dict) else None
        if gid is None and isinstance(pos, dict):
            gid = pos.get("group_id")
    except Exception:
        gid = None
    try:
        sys_id = data.get("system_id") if isinstance(data, dict) else None
        if sys_id is None and isinstance(pos, dict):
            sys_id = pos.get("system_id")
        if sys_id is None and sid is not None:
            sys_id = _system_from_strategy_id(sid)
    except Exception:
        sys_id = None
    for owner in ("strategy", "quant"):
        w = float(weights.get(owner, 0.0))
        if w <= 0.0:
            continue
        share = float(w) / float(s)
        pnl_o = float(pnl_usdc) * float(share)
        h.append({
            "ts": int(now_ms),
            "pair": str(pair),
            "owner": str(owner),
            "pnl_usdc": float(pnl_o),
            "notional_usdc": float(notional_usdc) * float(share),
            "ret_ratio": float(ret_ratio),
            "duration_ms": duration_ms,
            "fee_abs": fees_usdc,
            "funding_abs": funding_usdc,
            "slippage_abs": slippage_usdc,
            "order_id": (str(data.get("order_id")) if data.get("order_id") is not None else None),
            "event_id": (str(data.get("event_id")) if data.get("event_id") is not None else None),
            "strategy_id": (None if sid is None else str(sid)),
            "group_id": (None if gid is None else str(gid)),
            "system_id": (None if sys_id is None else str(sys_id)),
            "reason": (None if reason is None else str(reason)),
        })

    if len(h) > cap:
        del h[: max(0, len(h) - cap)]


def _ab_eval_window_ms() -> int:
    return 72 * 60 * 60 * 1000


def _ab_eval_metrics_72h(now_ms: int) -> Dict[str, Any]:
    since_ms = int(now_ms) - int(_ab_eval_window_ms())
    items = [x for x in (_ab_settlements_get() or []) if isinstance(x, dict) and int(x.get("ts") or 0) >= int(since_ms)]
    items = sorted(items, key=lambda r: int(r.get("ts") or 0))

    rejects = TRACKER_STATE.get("ab_intent_rejects")
    rejects_72h: List[Dict[str, Any]] = []
    if isinstance(rejects, list) and rejects:
        for r in rejects:
            if not isinstance(r, dict):
                continue
            try:
                if int(r.get("ts") or 0) >= int(since_ms):
                    rejects_72h.append(r)
            except Exception:
                continue

    by_owner: Dict[str, List[Dict[str, Any]]] = {"strategy": [], "quant": []}
    for r in items:
        o = _ab_norm_owner(r.get("owner"))
        by_owner.setdefault(o, []).append(r)

    def _owner_metrics(rows: List[Dict[str, Any]]) -> Dict[str, Any]:
        pnl = 0.0
        gp = 0.0
        gl = 0.0
        wins = 0
        n = 0
        sum_notional = 0.0
        sum_dur = 0
        n_dur = 0
        fee = 0.0
        fund = 0.0
        slip = 0.0
        fee_n = 0
        fund_n = 0
        slip_n = 0
        eq = 0.0
        peak = 0.0
        max_dd = 0.0
        for r in rows:
            try:
                p = float(r.get("pnl_usdc") or 0.0)
            except Exception:
                p = 0.0
            try:
                no = float(r.get("notional_usdc") or 0.0)
            except Exception:
                no = 0.0
            pnl += float(p)
            sum_notional += float(no) if float(no) > 0.0 else 0.0
            n += 1
            if float(p) > 0.0:
                wins += 1
                gp += float(p)
            else:
                gl += abs(float(p))
            eq += float(p)
            if eq > peak:
                peak = float(eq)
            dd = float(eq) - float(peak)
            if dd < max_dd:
                max_dd = float(dd)
            try:
                d = r.get("duration_ms")
                if d is not None and int(d) >= 0:
                    sum_dur += int(d)
                    n_dur += 1
            except Exception:
                pass
            try:
                f = r.get("fee_abs")
                if f is not None and math.isfinite(float(f)):
                    fee += float(f)
                    fee_n += 1
            except Exception:
                pass
            try:
                fu = r.get("funding_abs")
                if fu is not None and math.isfinite(float(fu)):
                    fund += float(fu)
                    fund_n += 1
            except Exception:
                pass

            try:
                su = r.get("slippage_abs")
                if su is not None and math.isfinite(float(su)):
                    slip += float(su)
                    slip_n += 1
            except Exception:
                pass

        pf = None
        if gl > 0.0:
            pf = float(gp) / float(gl)
        elif n > 0 and gp > 0.0:
            pf = float("inf")

        win_rate = (float(wins) / float(n)) if n > 0 else None
        avg_hold_ms = (int(sum_dur / n_dur) if n_dur > 0 else None)
        dd_ret = (float(max_dd) / float(sum_notional)) if sum_notional > 1e-9 else None
        ret = (float(pnl) / float(sum_notional)) if sum_notional > 1e-9 else None
        erosion = None
        if sum_notional > 1e-9 and (fee_n > 0 or fund_n > 0 or slip_n > 0):
            erosion = float((fee + fund + slip) / float(sum_notional))

        return {
            "trades": int(n),
            "wins": int(wins),
            "win_rate": win_rate,
            "net_pnl_usdc": float(pnl),
            "profit_factor": pf,
            "max_dd_usdc": float(max_dd),
            "ret_ratio": ret,
            "max_dd_ret_ratio": dd_ret,
            "avg_hold_ms": avg_hold_ms,
            "fee_abs_sum": (float(fee) if fee_n > 0 else None),
            "funding_abs_sum": (float(fund) if fund_n > 0 else None),
            "slippage_abs_sum": (float(slip) if slip_n > 0 else None),
            "erosion_ret_ratio": erosion,
            "sum_notional_usdc": float(sum_notional),
        }

    rej_by_reason: Dict[str, int] = {}
    for r in rejects_72h:
        try:
            reason = str(r.get("reason") or "")
        except Exception:
            reason = ""
        if not reason:
            continue
        rej_by_reason[reason] = int(rej_by_reason.get(reason, 0)) + 1

    merge_events = TRACKER_STATE.get("ab_merge_events")
    merge_72h: List[Dict[str, Any]] = []
    if isinstance(merge_events, list) and merge_events:
        for r in merge_events:
            if not isinstance(r, dict):
                continue
            try:
                if int(r.get("ts") or 0) >= int(since_ms):
                    merge_72h.append(r)
            except Exception:
                continue

    merge_counts: Dict[str, int] = {"same_side_merge": 0, "conflict_arbitration": 0, "deadband_hold": 0}
    for r in merge_72h:
        try:
            k = str(r.get("kind") or "")
        except Exception:
            k = ""
        if k in merge_counts:
            merge_counts[k] = int(merge_counts.get(k, 0)) + 1

    owners_out: Dict[str, Any] = {
        "strategy": _owner_metrics(by_owner.get("strategy", [])),
        "quant": _owner_metrics(by_owner.get("quant", [])),
    }
    for k, rows in by_owner.items():
        if k in owners_out:
            continue
        owners_out[str(k)] = _owner_metrics(rows)
    return {
        "window_ms": int(_ab_eval_window_ms()),
        "since_ms": int(since_ms),
        "until_ms": int(now_ms),
        "owners": owners_out,
        "rejects": {"n": int(len(rejects_72h)), "by_reason": rej_by_reason},
        "merge_health": {"events_n": int(len(merge_72h)), "counts": merge_counts},
    }


