def _s005_features_from_row(row: Any) -> Tuple[int, Dict[str, Any]]:
    if pd is None:
        raise RuntimeError("pandas_unavailable")

    def _sf(v: object, default: float = 0.0) -> float:
        try:
            if v is None or pd.isna(v):
                return float(default)
            f = float(v)
            if not math.isfinite(f):
                return float(default)
            return f
        except Exception:
            return float(default)

    close_v = _sf(row.get("close", 0.0) if hasattr(row, "get") else 0.0)
    atr_h_v = _sf(row.get("atr_h", 0.0) if hasattr(row, "get") else 0.0)
    adx_val = _sf(row.get("adx_h", 0.0) if hasattr(row, "get") else 0.0)

    ts_ms = None
    try:
        if hasattr(row, "get") and (row.get("date") is not None):
            dt = pd.to_datetime(row.get("date"), utc=True, errors="coerce")
            if dt is not None and (not pd.isna(dt)):
                ts_ms = int(pd.Timestamp(dt).timestamp() * 1000)
    except Exception:
        ts_ms = None
    if ts_ms is None:
        try:
            if hasattr(row, "name") and isinstance(row.name, pd.Timestamp):
                ts_ms = int(pd.Timestamp(row.name).timestamp() * 1000)
        except Exception:
            ts_ms = None
    if ts_ms is None:
        ts_ms = _now_ms()

    adx_w_v = _sf(row.get("adx_w", 0.0) if hasattr(row, "get") else 0.0)

    ema_short_h_v = _sf(row.get("ema_short_h", 0.0) if hasattr(row, "get") else 0.0)
    ema_long_h_v = _sf(row.get("ema_long_h", 0.0) if hasattr(row, "get") else 0.0)
    donchian_upper_h_v = _sf(row.get("donchian_upper_h", 0.0) if hasattr(row, "get") else 0.0)
    donchian_lower_h_v = _sf(row.get("donchian_lower_h", 0.0) if hasattr(row, "get") else 0.0)
    ema_fast_w_v = _sf(row.get("ema_fast_w", 0.0) if hasattr(row, "get") else 0.0)
    ema_slow_w_v = _sf(row.get("ema_slow_w", 0.0) if hasattr(row, "get") else 0.0)
    ma_fast_d_v = _sf(row.get("ma_cross_fast_d", 0.0) if hasattr(row, "get") else 0.0)
    ma_slow_d_v = _sf(row.get("ma_cross_slow_d", 0.0) if hasattr(row, "get") else 0.0)
    btc_weekly_short_ok_raw = row.get("btc_weekly_short_ok", False) if hasattr(row, "get") else False
    if btc_weekly_short_ok_raw is None or (hasattr(pd, "isna") and pd.isna(btc_weekly_short_ok_raw)):
        btc_weekly_short_ok_v = 0.0
    else:
        btc_weekly_short_ok_v = 1.0 if bool(btc_weekly_short_ok_raw) else 0.0

    donch_mid = (donchian_upper_h_v + donchian_lower_h_v) / 2.0

    atr_pct_v = (float(atr_h_v) / float(close_v)) if float(close_v) > 0.0 else 0.0

    weekly_up = float(ema_fast_w_v) > float(ema_slow_w_v)
    weekly_down = float(ema_fast_w_v) < float(ema_slow_w_v)
    daily_up = float(ma_fast_d_v) > float(ma_slow_d_v)
    daily_down = float(ma_fast_d_v) < float(ma_slow_d_v)

    try:
        weekly_adx_thr = float(CONFIG.get("s005_weekly_adx_threshold", 25.0) or 25.0)
    except Exception:
        weekly_adx_thr = 25.0
    weekly_adx = float(adx_w_v) if float(adx_w_v) > 0.0 else float(adx_val)
    weekly_trend_strong = float(weekly_adx) > float(weekly_adx_thr)

    if not weekly_trend_strong:
        time_regime = "chop"
    else:
        if weekly_up and daily_up:
            time_regime = "uptrend_strong"
        elif weekly_up and daily_down:
            time_regime = "uptrend_reversal"
        elif weekly_down and daily_down:
            time_regime = "downtrend_strong"
        elif weekly_down and daily_up:
            time_regime = "downtrend_reversal"
        else:
            time_regime = "chop"

    try:
        highvol_atr_thr = float(CONFIG.get("s005_highvol_atr_pct", 0.035) or 0.035)
    except Exception:
        highvol_atr_thr = 0.035
    if float(atr_pct_v) >= float(highvol_atr_thr):
        regime = "highvol"
    else:
        regime = "chop" if str(time_regime) == "chop" else "trend"

    rsi_h_v = _sf(row.get("rsi_h", 0.0) if hasattr(row, "get") else 0.0)
    macdhist_d_v = _sf(row.get("macdhist_d", 0.0) if hasattr(row, "get") else 0.0)

    features: Dict[str, Any] = {
        "close": float(close_v),
        "volume": _sf(row.get("volume", 0.0) if hasattr(row, "get") else 0.0),
        "rsi": float(rsi_h_v),
        "rsi_d": _sf(row.get("rsi_d", 0.0) if hasattr(row, "get") else 0.0),
        "willr_d": _sf(row.get("willr_d", 0.0) if hasattr(row, "get") else 0.0),
        "macdhist": float(macdhist_d_v),
        "macd_d": _sf(row.get("macd_d", 0.0) if hasattr(row, "get") else 0.0),
        "macdsignal_d": _sf(row.get("macdsignal_d", 0.0) if hasattr(row, "get") else 0.0),
        "ma_cross_fast_d": float(ma_fast_d_v),
        "ma_cross_slow_d": float(ma_slow_d_v),
        "regime": str(regime),
        "time_regime": str(time_regime),
        "weekly_trend": ("up" if weekly_up else ("down" if weekly_down else "flat")),
        "daily_trend": ("up" if daily_up else ("down" if daily_down else "flat")),
        "adx_w": float(adx_w_v),
        "ema_short_h": float(ema_short_h_v),
        "ema_long_h": float(ema_long_h_v),
        "donchian_upper_h": float(donchian_upper_h_v),
        "donchian_lower_h": float(donchian_lower_h_v),
        "atr_h": float(atr_h_v),
        "atr_pct": float(atr_pct_v),
        "atr_ratio": _sf(row.get("atr_ratio", 0.0) if hasattr(row, "get") else 0.0),
        "adx": float(adx_val),
        "adx_h": float(adx_val),
        "chop": _sf(row.get("chop_h", 0.0) if hasattr(row, "get") else 0.0),
        "chop_h": _sf(row.get("chop_h", 0.0) if hasattr(row, "get") else 0.0),
        "bb_width_ratio": _sf(row.get("bb_width_ratio", 0.0) if hasattr(row, "get") else 0.0),
        "volume_ratio": _sf(row.get("volume_ratio", 0.0) if hasattr(row, "get") else 0.0),
        "ema_short_dist": ((float(close_v) - float(ema_short_h_v)) / float(close_v)) if float(close_v) > 0.0 else 0.0,
        "ema_long_dist": ((float(close_v) - float(ema_long_h_v)) / float(close_v)) if float(close_v) > 0.0 else 0.0,
        "donchian_upper_dist": ((float(close_v) - float(donchian_upper_h_v)) / float(close_v)) if float(close_v) > 0.0 else 0.0,
        "donchian_lower_dist": ((float(close_v) - float(donchian_lower_h_v)) / float(close_v)) if float(close_v) > 0.0 else 0.0,
        "donchian_mid_dist": ((float(close_v) - float(donch_mid)) / float(close_v)) if float(close_v) > 0.0 else 0.0,
        "btc_macdhist_slope_pct": _sf(row.get("btc_macdhist_slope_pct", 0.0) if hasattr(row, "get") else 0.0),
        "weekly_state": 1.0 if float(ema_fast_w_v) > float(ema_slow_w_v) else (-1.0 if float(ema_fast_w_v) < float(ema_slow_w_v) else 0.0),
        "btc_weekly_short_ok": float(btc_weekly_short_ok_v),
        "mom_ret_1d": _sf(row.get("mom_ret_1d", 0.0) if hasattr(row, "get") else 0.0),
        "mom_ret_3d": _sf(row.get("mom_ret_3d", 0.0) if hasattr(row, "get") else 0.0),
        "mom_macdhist_delta": _sf(row.get("mom_macdhist_delta", 0.0) if hasattr(row, "get") else 0.0),
        "mom_rsi_delta": _sf(row.get("mom_rsi_delta", 0.0) if hasattr(row, "get") else 0.0),
        "vol_z_20": _sf(row.get("vol_z_20", 0.0) if hasattr(row, "get") else 0.0),
        "vol_ratio_delta": _sf(row.get("vol_ratio_delta", 0.0) if hasattr(row, "get") else 0.0),
        "pot_adx_delta": _sf(row.get("pot_adx_delta", 0.0) if hasattr(row, "get") else 0.0),
        "pot_atr_pct": _sf(row.get("pot_atr_pct", 0.0) if hasattr(row, "get") else 0.0),
        "pot_dist_to_ema50": _sf(row.get("pot_dist_to_ema50", 0.0) if hasattr(row, "get") else 0.0),
    }
    try:
        features.update(_s005_flow_proxy_placeholders())
    except Exception:
        pass
    return int(ts_ms), features


