def _row_features_subset(row: Any, feature_set_id: str) -> Dict[str, Any]:
    keys = _feature_set_keys_get(str(feature_set_id) or "")
    if not keys:
        return {}
    src = row if hasattr(row, "get") else {}
    raw: Dict[str, Any] = {}
    for k in keys:
        try:
            raw[k] = (src.get(k) if hasattr(src, "get") else None)
        except Exception:
            raw[k] = None
    return _align_features(str(feature_set_id), raw)


def _param_value(v: Any) -> Any:
    if v is None:
        return None
    if hasattr(v, "value"):
        try:
            return getattr(v, "value")
        except Exception:
            return None
    return v


def _extract_params(obj: Any, names: List[str]) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    for n in names:
        try:
            out[n] = _param_value(getattr(obj, n, None))
        except Exception:
            out[n] = None
    return out


def _ensure_freqtrade_shims() -> None:

    if pd is None:
        raise RuntimeError("pandas_unavailable")

    def merge_informative_pair(
        dataframe: Any,
        informative: Any,
        timeframe: str,
        informative_timeframe: str,
        ffill: bool = True,
        append_timeframe: bool = True,
    ) -> Any:
        if dataframe is None:
            return dataframe
        if informative is None:
            return dataframe
        if len(informative) == 0:
            return dataframe

        df = dataframe.copy()
        inf = informative.copy()
        if "date" not in df.columns or "date" not in inf.columns:
            return df

        df["date"] = pd.to_datetime(df["date"], utc=True, errors="coerce")
        inf["date"] = pd.to_datetime(inf["date"], utc=True, errors="coerce")
        df = df.dropna(subset=["date"]).sort_values("date")
        inf = inf.dropna(subset=["date"]).sort_values("date")

        suffix = f"_{informative_timeframe}" if append_timeframe else ""
        keep_cols = [c for c in inf.columns if c != "date"]
        inf_ren = inf[["date", *keep_cols]].copy()
        inf_ren = inf_ren.rename(columns={c: f"{c}{suffix}" for c in keep_cols})

        merged = pd.merge_asof(df, inf_ren, on="date", direction="backward")
        if ffill:
            new_cols = [c for c in merged.columns if c.endswith(suffix) and c != "date"]
            if new_cols:
                tmp = merged[new_cols].ffill()
                try:
                    tmp = tmp.infer_objects(copy=False)
                except Exception:
                    pass
                merged[new_cols] = tmp
        return merged

    def stoploss_from_open(open_relative_stop: float, current_profit: float) -> float:
        try:
            op = float(open_relative_stop)
            cp = float(current_profit)
        except Exception:
            return float(open_relative_stop)
        denom = 1.0 + cp
        if denom <= 0:
            return op
        return (1.0 + op) / denom - 1.0

    class IStrategy:
        INTERFACE_VERSION = 2

        def __init__(self, *args: Any, **kwargs: Any):
            self.dp = None
            self.config = {}

    class IntParameter:
        def __init__(self, low: int, high: int, default: int = None, space: str = None, **kwargs: Any):
            self.low = low
            self.high = high
            self.default = (low if default is None else default)
            self.space = space
            self.value = int(self.default)

    class DecimalParameter:
        def __init__(self, low: float, high: float, default: float = None, space: str = None, **kwargs: Any):
            self.low = low
            self.high = high
            self.default = (low if default is None else default)
            self.space = space
            self.value = float(self.default)

    class BooleanParameter:
        def __init__(self, default: bool = False, space: str = None, **kwargs: Any):
            self.default = bool(default)
            self.space = space
            self.value = bool(self.default)

    class Trade:
        def __init__(self, enter_tag: str = None):
            self.enter_tag = enter_tag

    ft = types.ModuleType("freqtrade")
    ft.__path__ = []
    ft_strategy = types.ModuleType("freqtrade.strategy")
    ft_persistence = types.ModuleType("freqtrade.persistence")
    ft_enums = types.ModuleType("freqtrade.enums")

    ft_strategy.IStrategy = IStrategy
    ft_strategy.IntParameter = IntParameter
    ft_strategy.DecimalParameter = DecimalParameter
    ft_strategy.BooleanParameter = BooleanParameter
    ft_strategy.merge_informative_pair = merge_informative_pair
    ft_strategy.stoploss_from_open = stoploss_from_open

    ft_persistence.Trade = Trade

    class RunMode:
        def __init__(self, name: str):
            self._name = str(name)

        def __str__(self) -> str:
            return self._name

    ft_enums.RunMode = RunMode

    ft.strategy = ft_strategy
    ft.persistence = ft_persistence
    ft.enums = ft_enums

    sys.modules["freqtrade"] = ft
    sys.modules["freqtrade.strategy"] = ft_strategy
    sys.modules["freqtrade.persistence"] = ft_persistence
    sys.modules["freqtrade.enums"] = ft_enums


def _ensure_technical_shims() -> None:
    if pd is None:
        raise RuntimeError("pandas_unavailable")

    try:
        import technical  # type: ignore
        if getattr(technical, "__file__", None):
            return
    except Exception:
        pass

    if "technical" in sys.modules:
        mod_file = getattr(sys.modules["technical"], "__file__", None)
        if mod_file:
            return

    import numpy as np

    qtpylib = types.ModuleType("technical.qtpylib")

    def crossed_above(series1: Any, series2: Any) -> Any:
        s1 = pd.Series(series1)
        s2 = pd.Series(series2)
        return (s1 > s2) & (s1.shift(1) <= s2.shift(1))

    def crossed_below(series1: Any, series2: Any) -> Any:
        s1 = pd.Series(series1)
        s2 = pd.Series(series2)
        return (s1 < s2) & (s1.shift(1) >= s2.shift(1))

    def typical_price(dataframe: Any) -> Any:
        df = dataframe
        return (pd.Series(df["high"]) + pd.Series(df["low"]) + pd.Series(df["close"])) / 3.0

    def rolling_vwap(dataframe: Any, window: int = 20) -> Any:
        df = dataframe
        w = int(window)
        w = 2 if w < 2 else w
        tp = typical_price(df)
        vol = pd.Series(df["volume"]) if "volume" in getattr(df, "columns", []) else pd.Series([0.0] * len(tp))
        pv = tp * vol
        denom = vol.rolling(w).sum().replace(0, np.nan)
        return pv.rolling(w).sum() / denom

    def bollinger_bands(series: Any, window: int = 20, stds: float = 2.0) -> Dict[str, Any]:
        s = pd.Series(series)
        w = int(window)
        w = 2 if w < 2 else w
        m = s.rolling(w).mean()
        sd = s.rolling(w).std(ddof=0).replace(0, np.nan)
        return {
            "mid": m,
            "upper": m + float(stds) * sd,
            "lower": m - float(stds) * sd,
        }

    qtpylib.crossed_above = crossed_above
    qtpylib.crossed_below = crossed_below
    qtpylib.typical_price = typical_price
    qtpylib.bollinger_bands = bollinger_bands
    qtpylib.rolling_vwap = rolling_vwap

    technical_mod = types.ModuleType("technical")
    technical_mod.__path__ = []
    technical_mod.qtpylib = qtpylib

    sys.modules["technical"] = technical_mod
    sys.modules["technical.qtpylib"] = qtpylib


class _InlineDataProvider:
    def __init__(self, base_pair: str):
        self._base_pair = str(base_pair)

    def current_whitelist(self) -> List[str]:
        return [self._base_pair]

    def get_pair_dataframe(self, pair: str, timeframe: str) -> Any:
        coin = _hl_coin_from_pair(pair)
        return _hl_fetch_df(coin=coin, timeframe=timeframe).copy()

    def get_analyzed_dataframe(self, pair: str, timeframe: str) -> Tuple[Any, Any]:
        return self.get_pair_dataframe(pair, timeframe), None


def _run_strategy005_signal_hyperliquid(coin: str) -> Dict[str, Any]:
    if pd is None:
        return {"ok": False, "error": "pandas_unavailable"}
    try:
        _ensure_freqtrade_shims()
        _ensure_technical_shims()
    except Exception as e:
        return {"ok": False, "error": f"shim_failed:{e}"}
    try:
        mod = importlib.import_module("user_data.strategies.Strategy005")
        cls = getattr(mod, "Strategy005")
    except Exception as e:
        return {"ok": False, "error": f"strategy_import_failed:{e}"}

    pair = f"{_hl_coin_from_pair(coin)}-PERP"
    dp = _InlineDataProvider(base_pair=pair)
    try:
        strat = _instantiate_strategy(cls)
        setattr(strat, "dp", dp)
        setattr(strat, "config", {"trading_mode": "futures", "exchange": {"name": "hyperliquid"}})
    except Exception as e:
        return {"ok": False, "error": f"strategy_init_failed:{e}"}

    @contextlib.contextmanager
    def _suppress_strategy_export_env():
        keys = [
            "ML_EXPORT_URL",
            "ML_FEATURE_EXPORT_URL",
            "ML_EXPORT_TRIGGER_DECISION",
            "ML_EXPORT_THRESHOLD",
            "ML_EXPORT_SIZE",
        ]
        saved: Dict[str, Any] = {}
        for k in keys:
            saved[k] = os.environ.get(k) if k in os.environ else None
            os.environ[k] = ""
        try:
            yield
        finally:
            for k, v in saved.items():
                if v is None:
                    try:
                        if k in os.environ:
                            del os.environ[k]
                    except Exception:
                        pass
                else:
                    os.environ[k] = str(v)

    try:
        base_df = dp.get_pair_dataframe(pair, getattr(strat, "timeframe", "1h"))
        if base_df is None or len(base_df) < int(getattr(strat, "startup_candle_count", 200) or 200):
            return {"ok": False, "error": "insufficient_candles", "pair": pair, "count": (0 if base_df is None else int(len(base_df)))}
        meta = {"pair": pair}
        with _suppress_strategy_export_env():
            df = strat.populate_indicators(base_df.copy(), meta)
            df = strat.populate_entry_trend(df, meta)
            try:
                if hasattr(strat, "populate_exit_trend"):
                    df = strat.populate_exit_trend(df, meta)
            except Exception:
                pass
        if df is None or df.empty:
            return {"ok": False, "error": "strategy_no_output"}

        tf = str(getattr(strat, "timeframe", "1h"))
        now_ms = _now_ms()
        row, bar_open_ms, bar_close_ms = _last_closed_bar_from_df(df, tf, now_ms=now_ms)
        enter_long = int(row.get("enter_long", 0) or 0)
        enter_short = int(row.get("enter_short", 0) or 0)
        tag = row.get("enter_tag")
        side = None
        if enter_short == 1:
            side = "short"
        elif enter_long == 1:
            side = "long"

        ts_ms, features = _s005_features_from_row(row)
        try:
            features["coin"] = _hl_coin_from_pair(coin)
        except Exception:
            pass
        try:
            fx = _macro_flow_at(int(bar_open_ms))
            if isinstance(fx, dict):
                for k in ("rs_btc_vs_mkt", "rs_eth_vs_mkt", "rs_btc_vs_eth"):
                    if k in fx:
                        features[k] = fx.get(k)
        except Exception:
            pass
        try:
            features["exit_long"] = int(float(row.get("exit_long", 0) or 0))
        except Exception:
            features["exit_long"] = 0
        try:
            features["exit_short"] = int(float(row.get("exit_short", 0) or 0))
        except Exception:
            features["exit_short"] = 0
        ts_ms = int(bar_open_ms)
        bar_closed = True
        return {
            "ok": True,
            "coin": _hl_coin_from_pair(coin),
            "pair": pair,
            "timeframe": str(tf),
            "ts": int(ts_ms),
            "bar_open_ms": int(bar_open_ms),
            "bar_close_ms": int(bar_close_ms),
            "bar_closed": bool(bar_closed),
            "side": side,
            "tag": (None if tag is None or (pd is not None and pd.isna(tag)) else str(tag)),
            "features": features,
            "close": float(features.get("close") or 0.0),
        }
    except Exception as e:
        return {"ok": False, "error": f"strategy_run_failed:{e}"}


def _instantiate_strategy(cls: Any) -> Any:
    try:
        return cls()
    except Exception:
        pass
    try:
        return cls({})
    except Exception:
        pass
    return cls(config={})


def _run_freqtrade_strategy_signal_hyperliquid(
    strategy_module: str,
    class_name: str,
    coin: str,
    param_names: Optional[List[str]] = None,
) -> Dict[str, Any]:
    if pd is None:
        return {"ok": False, "error": "pandas_unavailable"}
    try:
        _ensure_freqtrade_shims()
        _ensure_technical_shims()
    except Exception as e:
        return {"ok": False, "error": f"shim_failed:{e}"}

    try:
        mod = importlib.import_module(str(strategy_module))
        cls = getattr(mod, str(class_name))
    except Exception as e:
        return {"ok": False, "error": f"strategy_import_failed:{e}", "module": str(strategy_module), "class": str(class_name)}

    pair = f"{_hl_coin_from_pair(coin)}-PERP"
    dp = _InlineDataProvider(base_pair=pair)
    try:
        strat = _instantiate_strategy(cls)
        setattr(strat, "dp", dp)
        setattr(strat, "config", {"trading_mode": "futures", "exchange": {"name": "hyperliquid"}})
    except Exception as e:
        return {"ok": False, "error": f"strategy_init_failed:{e}"}

    @contextlib.contextmanager
    def _suppress_strategy_export_env():
        keys = [
            "ML_EXPORT_URL",
            "ML_FEATURE_EXPORT_URL",
            "ML_EXPORT_TRIGGER_DECISION",
            "ML_EXPORT_THRESHOLD",
            "ML_EXPORT_SIZE",
        ]
        saved: Dict[str, Any] = {}
        for k in keys:
            saved[k] = os.environ.get(k) if k in os.environ else None
            os.environ[k] = ""
        try:
            yield
        finally:
            for k, v in saved.items():
                if v is None:
                    try:
                        if k in os.environ:
                            del os.environ[k]
                    except Exception:
                        pass
                else:
                    os.environ[k] = str(v)

    try:
        params = _extract_params(strat, list(param_names or []))
        tf = str(getattr(strat, "timeframe", "1h"))
        base_df = dp.get_pair_dataframe(pair, tf)
        if base_df is None:
            return {"ok": False, "error": "no_candles", "pair": pair, "timeframe": tf}
        need = int(getattr(strat, "startup_candle_count", 200) or 200)
        if len(base_df) < need:
            return {"ok": False, "error": "insufficient_candles", "pair": pair, "timeframe": tf, "count": int(len(base_df)), "need": int(need)}

        meta = {"pair": pair}
        with _suppress_strategy_export_env():
            df = strat.populate_indicators(base_df.copy(), meta)
            df = strat.populate_entry_trend(df, meta)
            try:
                if hasattr(strat, "populate_exit_trend"):
                    df = strat.populate_exit_trend(df, meta)
            except Exception:
                pass
        if df is None or df.empty:
            return {"ok": False, "error": "strategy_no_output"}

        now_ms = _now_ms()
        pos, row, bar_open_ms, bar_close_ms = _last_closed_bar_pos_from_df(df, tf, now_ms=now_ms)
        prev_row = None
        try:
            if pos > 0:
                prev_row = df.iloc[int(pos) - 1]
        except Exception:
            prev_row = None
        def _flag(v: Any) -> int:
            try:
                if v is None:
                    return 0
                if pd is not None and pd.isna(v):
                    return 0
                if isinstance(v, bool):
                    return 1 if v else 0
                return int(v)
            except Exception:
                return 0

        enter_long = _flag(row.get("enter_long", 0))
        enter_short = _flag(row.get("enter_short", 0))
        buy_flag = _flag(row.get("buy", 0))
        if enter_long == 0 and enter_short == 0 and buy_flag == 1:
            enter_long = 1
        side = None
        if enter_short == 1:
            side = "short"
        elif enter_long == 1:
            side = "long"
        tag = row.get("enter_tag")
        tag_s = "" if tag is None else str(tag)
        if (not tag_s.strip()) and ("buy_tag" in df.columns):
            tag = row.get("buy_tag")

        return {
            "ok": True,
            "coin": _hl_coin_from_pair(coin),
            "pair": pair,
            "timeframe": str(tf),
            "ts": int(bar_open_ms),
            "bar_open_ms": int(bar_open_ms),
            "bar_close_ms": int(bar_close_ms),
            "bar_closed": True,
            "side": side,
            "tag": (None if tag is None or (pd is not None and pd.isna(tag)) else str(tag)),
            "row": _json_sanitize(row.to_dict() if hasattr(row, "to_dict") else {}),
            "prev_row": _json_sanitize(prev_row.to_dict() if prev_row is not None and hasattr(prev_row, "to_dict") else {}),
            "params": _json_sanitize(dict(params or {})),
        }
    except Exception as e:
        return {"ok": False, "error": f"strategy_run_failed:{e}"}


def _emit_signal_v1(signal_payload: Dict[str, Any], trigger: bool, data: Dict[str, Any]) -> Any:
    now_ms = _now_ms()
    _signals_prune_dedup(now_ms)

    def _resp_alias_ids(resp: Any, *, evt_id: Optional[str] = None) -> Any:
        if not isinstance(resp, dict):
            return resp
        out = dict(resp)
        if out.get("event_id") is None:
            eid = out.get("id") if out.get("id") is not None else evt_id
            if eid is not None:
                out["event_id"] = str(eid)
        if out.get("trace_id") is None and out.get("event_id") is not None:
            out["trace_id"] = str(out.get("event_id"))
        return out

    def _ensure_ms(ts: int) -> int:
        if int(ts or 0) <= 0:
            return 0
        if int(ts) < 1000000000000:
            return int(ts) * 1000
        return int(ts)
    try:
        if int(signal_payload.get("signal_schema_version") or 0) < 1:
            signal_payload["signal_schema_version"] = 1
    except Exception:
        signal_payload["signal_schema_version"] = 1

    try:
        if signal_payload.get("strategy_id") is None and signal_payload.get("strategy") is not None:
            signal_payload["strategy_id"] = signal_payload.get("strategy")
    except Exception:
        pass

    try:
        sid_norm = ("" if signal_payload.get("strategy_id") is None else str(signal_payload.get("strategy_id"))).strip()
    except Exception:
        sid_norm = ""
    if sid_norm:
        sid_l = sid_norm.lower().replace("-", "").replace("_", "").strip()
        if sid_l == "threescreen":
            signal_payload["strategy_id"] = "ThreeScreen"

    try:
        tf = str(signal_payload.get("timeframe") or data.get("timeframe") or "").strip().lower()
    except Exception:
        tf = ""
    if tf == "60m":
        tf = "1h"
    if tf == "1day":
        tf = "1d"
    if not tf:
        try:
            sid = ("" if signal_payload.get("strategy_id") is None else str(signal_payload.get("strategy_id"))).strip()
        except Exception:
            sid = ""
        if sid:
            try:
                meta = _get_strategy_meta(sid)
                tf2 = str(meta.get("timeframe") or "").strip().lower()
                if tf2 == "60m":
                    tf2 = "1h"
                if tf2 == "1day":
                    tf2 = "1d"
                if tf2:
                    tf = tf2
                if not tf:
                    try:
                        import re
                        cands = [meta.get("feature_set_id"), meta.get("group_id"), sid]
                        for c in cands:
                            s = ("" if c is None else str(c)).strip().lower()
                            if not s:
                                continue
                            m = re.search(r"(\d{1,3})([mhd])", s)
                            if m:
                                tf = f"{int(m.group(1))}{m.group(2)}"
                                break
                    except Exception:
                        pass
            except Exception:
                pass
    if not tf:
        tf = str(CONFIG.get("signals_default_timeframe", "1h") or "1h").strip().lower() or "1h"
    signal_payload["timeframe"] = tf

    tf_ms = 0
    try:
        tf_ms = int(_hl_interval_to_ms(tf))
    except Exception:
        tf_ms = 0

    ts_event = None
    for k in ("ts", "bar_open_ms", "bar_close_ms", "ts_emit_ms"):
        if signal_payload.get(k) is not None:
            ts_event = signal_payload.get(k)
            break
    if ts_event is None:
        ts_event = now_ms
    try:
        ts_event_i = int(ts_event or 0)
    except Exception:
        ts_event_i = int(now_ms)
    if ts_event_i <= 0:
        ts_event_i = int(now_ms)
    ts_event_i = _ensure_ms(int(ts_event_i))

    try:
        bar_open_ms = int(signal_payload.get("bar_open_ms") or 0)
    except Exception:
        bar_open_ms = 0
    bar_open_ms = _ensure_ms(int(bar_open_ms))
    if bar_open_ms <= 0:
        if tf_ms > 0:
            bar_open_ms = int((int(ts_event_i) // int(tf_ms)) * int(tf_ms))
        else:
            bar_open_ms = int(ts_event_i)
        signal_payload["bar_open_ms"] = int(bar_open_ms)

    try:
        bar_close_ms = int(signal_payload.get("bar_close_ms") or 0)
    except Exception:
        bar_close_ms = 0
    bar_close_ms = _ensure_ms(int(bar_close_ms))
    if bar_close_ms <= 0:
        if tf_ms > 0:
            bar_close_ms = int(bar_open_ms) + int(tf_ms)
        else:
            bar_close_ms = int(bar_open_ms)
        signal_payload["bar_close_ms"] = int(bar_close_ms)

    try:
        if signal_payload.get("ts") is None:
            signal_payload["ts"] = int(bar_open_ms)
        else:
            ts_i = int(signal_payload.get("ts") or 0)
            ts_i = _ensure_ms(int(ts_i))
            if ts_i <= 0:
                signal_payload["ts"] = int(bar_open_ms)
            else:
                signal_payload["ts"] = int(ts_i)
    except Exception:
        signal_payload["ts"] = int(bar_open_ms)

    try:
        if signal_payload.get("ts_emit_ms") is None:
            signal_payload["ts_emit_ms"] = int(now_ms)
        else:
            signal_payload["ts_emit_ms"] = int(_ensure_ms(int(signal_payload.get("ts_emit_ms") or 0)) or int(now_ms))
    except Exception:
        pass

    try:
        action = str(signal_payload.get("action") or "open").strip().lower()
    except Exception:
        action = "open"
    if action not in ("open", "close", "observe"):
        action = "open"
    signal_payload["action"] = action

    try:
        side0 = str(signal_payload.get("side") or "").strip().lower()
        if side0:
            signal_payload["side"] = side0
    except Exception:
        pass

    try:
        sid = ("" if signal_payload.get("strategy_id") is None else str(signal_payload.get("strategy_id"))).strip()
        if sid:
            meta = _get_strategy_meta(sid)
            if signal_payload.get("strategy_version") is None:
                signal_payload["strategy_version"] = str(meta.get("strategy_version") or "1.0.0")
            if signal_payload.get("group_id") is None:
                signal_payload["group_id"] = str(meta.get("group_id") or "default")
            if signal_payload.get("feature_set_id") is None:
                signal_payload["feature_set_id"] = str(meta.get("feature_set_id") or "")
    except Exception:
        pass

    try:
        sid0 = ("" if signal_payload.get("strategy_id") is None else str(signal_payload.get("strategy_id"))).strip()
    except Exception:
        sid0 = ""
    if sid0 == "ThreeScreen":
        if signal_payload.get("group_id") in (None, "", "default"):
            try:
                signal_payload["group_id"] = str(CONFIG.get("three_screen_group_id_default", "ThreeScreen.v0") or "ThreeScreen.v0")
            except Exception:
                signal_payload["group_id"] = "ThreeScreen.v0"
        expected_book = _three_screen_phase_expected_book()
        if str(expected_book) == "strategy":
            try:
                force_strategy_book = bool(CONFIG.get("three_screen_phase0_force_ab_owner_strategy", True))
            except Exception:
                force_strategy_book = True
            if bool(force_strategy_book):
                signal_payload["ab_owner"] = "strategy"
                signal_payload["system_id"] = "strategy"
                signal_payload["book_id"] = "strategy"
                signal_payload["owner_contrib"] = {"strategy": 0.0, "quant": 0.0, "carry": 0.0, "three_screen": 1.0}
        else:
            signal_payload["ab_owner"] = str(expected_book)
            signal_payload["system_id"] = str(expected_book)
            signal_payload["book_id"] = str(expected_book)
            signal_payload["owner_contrib"] = {"strategy": 0.0, "quant": 0.0, "carry": 0.0, "three_screen": 1.0}

    try:
        sid0 = ("" if signal_payload.get("strategy_id") is None else str(signal_payload.get("strategy_id"))).strip() or None
        owner_kind0 = _owner_from_strategy_id(sid0)
        if signal_payload.get("ab_owner") is None:
            signal_payload["ab_owner"] = str(owner_kind0)
        if signal_payload.get("owner_contrib") is None:
            signal_payload["owner_contrib"] = {
                "strategy": (1.0 if str(owner_kind0) == "strategy" else 0.0),
                "quant": (1.0 if str(owner_kind0) == "quant" else 0.0),
                "carry": (1.0 if str(owner_kind0) == "carry" else 0.0),
                "three_screen": (1.0 if str(owner_kind0) == "three_screen" else 0.0),
            }
    except Exception:
        pass

    try:
        sid0 = ("" if signal_payload.get("strategy_id") is None else str(signal_payload.get("strategy_id"))).strip() or None
        if signal_payload.get("system_id") is None:
            signal_payload["system_id"] = str(_system_from_strategy_id(sid0))
    except Exception:
        pass

    def _tag_norm(v: Any) -> Optional[str]:
        try:
            s = ("" if v is None else str(v)).strip()
        except Exception:
            return None
        if (not s) or s.lower() in ("nan", "none", "null"):
            return None
        return s

    try:
        tag0 = _tag_norm(signal_payload.get("tag"))
        if tag0 is None:
            for k in ("enter_tag", "buy_tag", "entry_tag", "signal_tag"):
                tag1 = _tag_norm(signal_payload.get(k))
                if tag1 is not None:
                    signal_payload["tag"] = tag1
                    break
    except Exception:
        pass

    try:
        src = data.get("source")
        if src is not None:
            src_s = str(src).strip()
            if src_s:
                signal_payload["source"] = src_s
    except Exception:
        pass
    try:
        bar_closed0 = bool(signal_payload.get("bar_closed", True))
    except Exception:
        bar_closed0 = True
    if not bool(bar_closed0):
        allow_unclosed = False
        try:
            allow_unclosed = bool(CONFIG.get("signals_allow_unclosed_bars_for_quant", True))
        except Exception:
            allow_unclosed = False
        if bool(allow_unclosed) and str(signal_payload.get("action") or "open").strip().lower() == "open":
            try:
                ao = _ab_norm_owner_or_empty(signal_payload.get("ab_owner"))
            except Exception:
                ao = ""
            try:
                sys0 = _ab_norm_owner_or_empty(signal_payload.get("system_id"))
            except Exception:
                sys0 = ""
            try:
                bid0 = _ab_norm_owner_or_empty(signal_payload.get("book_id"))
            except Exception:
                bid0 = ""
            allow_unclosed = (ao in ("quant", "carry")) or (sys0 in ("quant", "carry")) or (bid0 in ("quant", "carry"))
        if bool(allow_unclosed):
            signal_payload["bar_closed"] = True
        else:
            signal_payload["action"] = "observe"
            signal_payload["trigger_block_reason"] = "bar_not_closed"
            trigger = False

    try:
        sid_ts = ("" if signal_payload.get("strategy_id") is None else str(signal_payload.get("strategy_id"))).strip()
    except Exception:
        sid_ts = ""
    if sid_ts == "ThreeScreen":
        feats = signal_payload.get("features")
        if not isinstance(feats, dict):
            feats = {}
            signal_payload["features"] = feats

        tf = str(signal_payload.get("timeframe") or "").strip()
        if tf not in ("5m", "1d", "1w"):
            signal_payload["action"] = "observe"
            signal_payload["trigger_block_reason"] = "invalid_timeframe"
            feats.setdefault("reject_reason", "invalid_timeframe")
            trigger = False
        else:
            if str(signal_payload.get("action") or "").strip().lower() == "open" and tf != "5m":
                signal_payload["action"] = "observe"
                signal_payload["trigger_block_reason"] = "non_5m_open"
                feats.setdefault("reject_reason", "non_5m_open")
                trigger = False

            if bool(trigger):
                try:
                    align_ok = bool(feats.get("align_with_weekly") is True)
                except Exception:
                    align_ok = False
                if not bool(align_ok):
                    try:
                        ddir0 = str(feats.get("daily_signal_dir") or "").strip().lower()
                    except Exception:
                        ddir0 = ""
                    try:
                        wdir0 = str(feats.get("weekly_trend_dir") or "").strip().lower()
                    except Exception:
                        wdir0 = ""
                    reason0 = "align_with_weekly_false"
                    if wdir0 not in ("long", "short"):
                        reason0 = "weekly_neutral"
                    elif ddir0 not in ("long", "short"):
                        reason0 = "daily_neutral"
                    elif ddir0 != wdir0:
                        reason0 = "daily_weekly_dir_mismatch"
                    signal_payload["action"] = "observe"
                    signal_payload["trigger_block_reason"] = str(reason0)
                    feats.setdefault("reject_reason", str(reason0))
                    trigger = False

            if bool(trigger):
                bar_close_ms0 = 0
                try:
                    bar_close_ms0 = int(signal_payload.get("bar_close_ms") or 0)
                except Exception:
                    bar_close_ms0 = 0
                try:
                    vu = int(feats.get("daily_valid_until_ms") or 0)
                except Exception:
                    vu = 0
                if vu > 0 and bar_close_ms0 > 0 and bar_close_ms0 > vu:
                    signal_payload["action"] = "observe"
                    signal_payload["trigger_block_reason"] = "daily_expired"
                    feats.setdefault("reject_reason", "daily_expired")
                    trigger = False

            if bool(trigger):
                bar_close_ms0 = 0
                try:
                    bar_close_ms0 = int(signal_payload.get("bar_close_ms") or 0)
                except Exception:
                    bar_close_ms0 = 0
                w_close = feats.get("weekly_bar_close_ms")
                d_close = feats.get("daily_bar_close_ms")
                try:
                    w_close_i = int(w_close) if w_close is not None else 0
                except Exception:
                    w_close_i = 0
                try:
                    d_close_i = int(d_close) if d_close is not None else 0
                except Exception:
                    d_close_i = 0
                if bar_close_ms0 > 0 and ((w_close_i > bar_close_ms0) or (d_close_i > bar_close_ms0)):
                    signal_payload["action"] = "observe"
                    signal_payload["trigger_block_reason"] = "mtf_bar_close_gt_5m"
                    feats.setdefault("reject_reason", "mtf_bar_close_gt_5m")
                    trigger = False

            if bool(trigger):
                try:
                    ddir = str(feats.get("daily_signal_dir") or "").strip().lower()
                except Exception:
                    ddir = ""
                try:
                    wdir = str(feats.get("weekly_trend_dir") or "").strip().lower()
                except Exception:
                    wdir = ""
                try:
                    wok = bool(feats.get("weekly_ok"))
                except Exception:
                    wok = True
                if not bool(wok):
                    signal_payload["action"] = "observe"
                    signal_payload["trigger_block_reason"] = "weekly_strength_below"
                    feats.setdefault("reject_reason", "weekly_strength_below")
                    trigger = False
                elif wdir not in ("long", "short"):
                    signal_payload["action"] = "observe"
                    signal_payload["trigger_block_reason"] = "weekly_neutral"
                    feats.setdefault("reject_reason", "weekly_neutral")
                    trigger = False
                elif ddir not in ("long", "short"):
                    signal_payload["action"] = "observe"
                    signal_payload["trigger_block_reason"] = "daily_neutral"
                    feats.setdefault("reject_reason", "daily_neutral")
                    trigger = False
                elif ddir != wdir:
                    signal_payload["action"] = "observe"
                    signal_payload["trigger_block_reason"] = "daily_weekly_dir_mismatch"
                    feats.setdefault("reject_reason", "daily_weekly_dir_mismatch")
                    trigger = False

            if bool(trigger):
                meta = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
                cts = 0
                ttl_ms = 0
                try:
                    if isinstance(meta, dict):
                        cts = int(meta.get("candidates_ts") or 0)
                except Exception:
                    cts = 0
                try:
                    if isinstance(meta, dict):
                        ttl_ms = int(meta.get("candidates_ttl_ms") or 0)
                except Exception:
                    ttl_ms = 0
                ttl_ms = int(ttl_ms) if int(ttl_ms) > 0 else int(CONFIG.get("three_screen_candidates_ttl_ms", 900000) or 900000)
                ttl_sec = int(max(0, int(ttl_ms) // 1000))
                try:
                    feats["candidates_ts"] = int(cts) if int(cts) > 0 else int(now_ms)
                    feats["candidates_ttl_sec"] = int(ttl_sec)
                except Exception:
                    pass

                stale = False
                if int(cts) > 0 and int(ttl_ms) > 0:
                    try:
                        stale = (int(now_ms) - int(cts)) > int(ttl_ms)
                    except Exception:
                        stale = False
                try:
                    enforce_ttl = bool(CONFIG.get("three_screen_candidates_ttl_enforce", True))
                except Exception:
                    enforce_ttl = True
                coin = _three_screen_pair_coin(signal_payload.get("pair"))
                if not coin:
                    coin = "BTC"
                if bool(enforce_ttl) and bool(stale) and coin != "BTC":
                    signal_payload["action"] = "observe"
                    signal_payload["trigger_block_reason"] = "candidates_stale"
                    feats.setdefault("reject_reason", "candidates_stale")
                    trigger = False

            if bool(trigger):
                coin = _three_screen_pair_coin(signal_payload.get("pair"))
                if not coin:
                    coin = "BTC"
                corr_30d = None
                corr_60d = None
                beta_30d = None
                vol_ratio_30d = None
                if coin == "BTC":
                    corr_30d = 1.0
                    corr_60d = 1.0
                    beta_30d = 1.0
                    vol_ratio_30d = None
                else:
                    try:
                        ex0 = _universe_btc_exposure(pair=str(signal_payload.get("pair") or ""), now_ms=int(now_ms), window_bars=int(CONFIG.get("strategy_btc_corr_window_bars_1h", 720) or 720))
                    except Exception:
                        ex0 = {}
                    if isinstance(ex0, dict):
                        corr_30d = ex0.get("corr_30d")
                        corr_60d = ex0.get("corr_60d")
                        beta_30d = ex0.get("beta")
                        vol_ratio_30d = None

                try:
                    feats["corr_30d"] = (None if corr_30d is None else float(corr_30d))
                except Exception:
                    feats["corr_30d"] = None
                try:
                    feats["corr_60d"] = (None if corr_60d is None else float(corr_60d))
                except Exception:
                    feats["corr_60d"] = None
                try:
                    feats["beta_30d"] = (None if beta_30d is None else float(beta_30d))
                except Exception:
                    feats["beta_30d"] = None
                feats["vol_ratio_30d"] = (None if vol_ratio_30d is None else float(vol_ratio_30d)) if vol_ratio_30d is not None else None

                try:
                    corr_thr = float(CONFIG.get("three_screen_btc_corr_threshold", 0.7) or 0.7)
                except Exception:
                    corr_thr = 0.7
                corr_thr = float(_clip(float(corr_thr), 0.0, 0.999))
                try:
                    corr_enforce = bool(CONFIG.get("three_screen_btc_corr_enforce", True))
                except Exception:
                    corr_enforce = True
                if bool(corr_enforce) and coin != "BTC":
                    try:
                        c30 = float(corr_30d) if corr_30d is not None else None
                    except Exception:
                        c30 = None
                    try:
                        c60 = float(corr_60d) if corr_60d is not None else None
                    except Exception:
                        c60 = None
                    if c30 is None or c60 is None or (not math.isfinite(float(c30))) or (not math.isfinite(float(c60))):
                        signal_payload["action"] = "observe"
                        signal_payload["trigger_block_reason"] = "btc_corr_missing"
                        feats.setdefault("reject_reason", "btc_corr_missing")
                        trigger = False
                    elif float(c30) + 1e-12 < float(corr_thr) or float(c60) + 1e-12 < float(corr_thr):
                        signal_payload["action"] = "observe"
                        signal_payload["trigger_block_reason"] = "btc_corr_low"
                        feats.setdefault("reject_reason", "btc_corr_low")
                        trigger = False

            if bool(trigger):
                coin = _three_screen_pair_coin(signal_payload.get("pair"))
                if not coin:
                    coin = "BTC"
                meta = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
                cand_list = meta.get("candidates") if isinstance(meta, dict) else None
                cand_by_coin: Dict[str, Dict[str, Any]] = {}
                if isinstance(cand_list, list):
                    for it in cand_list:
                        if not isinstance(it, dict):
                            continue
                        c0 = str(it.get("coin") or "").upper().strip()
                        if not c0:
                            continue
                        cand_by_coin[c0] = it

                try:
                    cand_enforce = bool(CONFIG.get("three_screen_candidates_enforce", True))
                except Exception:
                    cand_enforce = True
                if bool(cand_enforce) and coin != "BTC" and coin not in cand_by_coin:
                    signal_payload["action"] = "observe"
                    signal_payload["trigger_block_reason"] = "not_in_candidates"
                    feats.setdefault("reject_reason", "not_in_candidates")
                    trigger = False

            if bool(trigger):
                coin = _three_screen_pair_coin(signal_payload.get("pair"))
                if not coin:
                    coin = "BTC"
                meta = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
                cand_list = meta.get("candidates") if isinstance(meta, dict) else None

                try:
                    max_symbols = int(CONFIG.get("three_screen_portfolio_max_symbols", 5) or 5)
                except Exception:
                    max_symbols = 5
                max_symbols = int(max(1, min(10, int(max_symbols))))

                try:
                    trend_dir = str(feats.get("weekly_trend_dir") or "").strip().lower()
                except Exception:
                    trend_dir = ""
                if trend_dir not in ("long", "short"):
                    try:
                        trend_dir = str(feats.get("daily_signal_dir") or "").strip().lower()
                    except Exception:
                        trend_dir = ""
                if trend_dir not in ("long", "short"):
                    trend_dir = "neutral"

                stale0 = False
                try:
                    stale0 = bool(stale)
                except Exception:
                    stale0 = False
                try:
                    enforce_ttl0 = bool(enforce_ttl)
                except Exception:
                    enforce_ttl0 = bool(CONFIG.get("three_screen_candidates_ttl_enforce", True))

                corr_cache: Dict[str, Tuple[Optional[float], Optional[float]]] = {}
                def _corr_for_coin(c0: str) -> Tuple[Optional[float], Optional[float]]:
                    c1 = str(c0 or "").upper().strip()
                    if not c1:
                        return (None, None)
                    if c1 == "BTC":
                        return (1.0, 1.0)
                    hit = corr_cache.get(c1)
                    if isinstance(hit, tuple) and len(hit) == 2:
                        return hit
                    try:
                        ex0 = _universe_btc_exposure(pair=f"{c1}/USDT", now_ms=int(now_ms), window_bars=int(CONFIG.get("strategy_btc_corr_window_bars_1h", 720) or 720))
                    except Exception:
                        ex0 = {}
                    c30 = None
                    c60 = None
                    if isinstance(ex0, dict):
                        c30 = ex0.get("corr_30d")
                        c60 = ex0.get("corr_60d")
                    try:
                        c30 = (None if c30 is None else float(c30))
                    except Exception:
                        c30 = None
                    try:
                        c60 = (None if c60 is None else float(c60))
                    except Exception:
                        c60 = None
                    corr_cache[c1] = (c30, c60)
                    return (c30, c60)

                try:
                    corr_thr = float(CONFIG.get("three_screen_btc_corr_threshold", 0.7) or 0.7)
                except Exception:
                    corr_thr = 0.7
                corr_thr = float(_clip(float(corr_thr), 0.0, 0.999))

                symbols: List[str] = ["BTC"]
                weights: Dict[str, float] = {"BTC": 1.0}
                z_map: Dict[str, Optional[float]] = {}
                corr_map: Dict[str, Dict[str, Optional[float]]] = {"BTC": {"corr_30d": 1.0, "corr_60d": 1.0}}
                universe_score_map: Dict[str, float] = {}
                candidates_score_map: Dict[str, float] = {}
                beta_map: Dict[str, Optional[float]] = {}
                candidates_pc_map: Dict[str, Optional[float]] = {}
                candidates_score_eff_map: Dict[str, float] = {}
                candidates_pc_model_id: Optional[str] = None

                if bool(stale0) and bool(enforce_ttl0):
                    try:
                        feats["portfolio_symbols"] = symbols
                        feats["portfolio_weights"] = weights
                        feats["portfolio_side"] = str(trend_dir)
                        feats["portfolio_degraded"] = "candidates_stale"
                        feats["portfolio_candidates"] = [{"coin": "BTC", "weight": 1.0, "corr_30d": 1.0, "corr_60d": 1.0, "beta_30d": 1.0, "vol_ratio_30d": None, "z": None, "universe_score": None, "candidates_score": None, "candidates_pc": None}]
                    except Exception:
                        pass
                else:
                    alt_pool: List[Dict[str, Any]] = []
                    scan_n = int(max(1, min(30, max_symbols * 6)))
                    if isinstance(cand_list, list):
                        for it in cand_list[:scan_n]:
                            if not isinstance(it, dict):
                                continue
                            c0 = str(it.get("coin") or "").upper().strip()
                            if not c0 or c0 in ("BTC", "USDT", "USDC"):
                                continue
                            pools = it.get("pools") if isinstance(it.get("pools"), dict) else {}
                            if str(pools.get("quality_bucket") or "") == "BAD":
                                continue
                            c30, c60 = _corr_for_coin(c0)
                            if c30 is None or c60 is None:
                                continue
                            if (not math.isfinite(float(c30))) or (not math.isfinite(float(c60))):
                                continue
                            if float(c30) + 1e-12 < float(corr_thr) or float(c60) + 1e-12 < float(corr_thr):
                                continue
                            try:
                                us = float(it.get("score") or 0.0)
                            except Exception:
                                us = 0.0
                            if not math.isfinite(float(us)):
                                us = 0.0
                            universe_score_map[c0] = float(us)
                            corr_map[c0] = {"corr_30d": float(c30), "corr_60d": float(c60)}
                            alt_pool.append({"coin": c0, "universe_score": float(us), "corr_30d": float(c30), "corr_60d": float(c60)})

                    want_long = bool(trend_dir == "long")
                    for row in alt_pool:
                        c0 = str(row.get("coin") or "").upper().strip()
                        z0 = None
                        try:
                            snap = _quant_pairs_btcalt_latest_beta(tf="1h", alt=str(c0), limit=720)
                        except Exception:
                            snap = None
                        beta0 = None
                        if isinstance(snap, dict) and bool(snap.get("ok")):
                            try:
                                z0 = snap.get("z")
                                z0 = (None if z0 is None else float(z0))
                            except Exception:
                                z0 = None
                            try:
                                beta0 = snap.get("beta")
                                beta0 = (None if beta0 is None else float(beta0))
                            except Exception:
                                beta0 = None
                        if z0 is not None and math.isfinite(float(z0)):
                            z_map[c0] = float(z0)
                        else:
                            z_map[c0] = None
                        beta_map[c0] = (None if beta0 is None or (not math.isfinite(float(beta0))) else float(beta0))
                        cs = 0.0
                        if z0 is not None and math.isfinite(float(z0)):
                            cs = float(max(0.0, (-float(z0) if bool(want_long) else float(z0))))
                        try:
                            cs = float(_clip(float(cs), 0.0, 10.0))
                        except Exception:
                            cs = 0.0
                        if float(cs) <= 0.0:
                            cs = float(max(0.0, float(universe_score_map.get(c0, 0.0))))
                        candidates_score_map[c0] = float(cs)

                    candidates_score_eff_map = dict(candidates_score_map)
                    try:
                        candidates_pc_enabled = bool(CONFIG.get("three_screen_candidates_pc_enabled", False))
                    except Exception:
                        candidates_pc_enabled = False
                    candidates_pc_model_id_eff: Optional[str] = None
                    if bool(candidates_pc_enabled) and _arena_enabled() and trend_dir in ("long", "short"):
                        try:
                            candidates_pc_model_id = str(CONFIG.get("three_screen_candidates_pc_model_id") or "").strip()
                        except Exception:
                            candidates_pc_model_id = ""
                        if not candidates_pc_model_id:
                            candidates_pc_model_id = "__lr__"
                        try:
                            pc_weight = float(CONFIG.get("three_screen_candidates_pc_weight", 1.0) or 1.0)
                        except Exception:
                            pc_weight = 1.0
                        pc_weight = float(_clip(float(pc_weight), 0.0, 10.0))
                        try:
                            pc_topn = int(CONFIG.get("three_screen_candidates_pc_topn", 12) or 12)
                        except Exception:
                            pc_topn = 12
                        pc_topn = int(max(1, min(30, int(pc_topn))))

                        try:
                            ts_ref = int(signal_payload.get("bar_close_ms") or signal_payload.get("bar_open_ms") or now_ms)
                        except Exception:
                            ts_ref = int(now_ms)

                        strategy_features_base = dict(feats or {})
                        for k in (
                            "corr_30d",
                            "corr_60d",
                            "beta_30d",
                            "vol_ratio_30d",
                            "candidates_rank",
                            "candidates_score",
                            "candidates_pc",
                            "candidates_pc_model_id",
                            "portfolio_symbols",
                            "portfolio_weights",
                            "portfolio_candidates",
                            "portfolio_side",
                            "portfolio_degraded",
                        ):
                            strategy_features_base.pop(k, None)

                        ranked_for_pc = sorted(
                            [str(r.get("coin") or "").upper().strip() for r in alt_pool if str(r.get("coin") or "").upper().strip()],
                            key=lambda cc: float(candidates_score_map.get(str(cc).upper().strip(), 0.0)),
                            reverse=True,
                        )
                        ranked_for_pc = ranked_for_pc[:pc_topn]
                        if str(coin).upper().strip() != "BTC" and str(coin).upper().strip() and str(coin).upper().strip() not in ranked_for_pc:
                            ranked_for_pc.append(str(coin).upper().strip())

                        for c0 in ranked_for_pc:
                            if not c0 or c0 in ("BTC", "USDT", "USDC"):
                                continue
                            pair_spot = f"{c0}/USDC"
                            market_features: Dict[str, Any] = {}
                            try:
                                market_features = _ml3_features_at_timestamp(str(pair_spot), int(ts_ref)) or {}
                            except Exception:
                                market_features = {}
                            arena_features: Dict[str, Any] = dict(market_features or {})
                            try:
                                arena_features.update(dict(strategy_features_base or {}))
                            except Exception:
                                arena_features.update({})
                            try:
                                regime = _get_regime(arena_features, pair=str(pair_spot), ts=int(ts_ref), timeframe="5m")
                            except Exception:
                                regime = ""
                            try:
                                thr_base = float(_get_threshold(regime))
                            except Exception:
                                thr_base = 0.60
                            try:
                                arena_evt = _arena_snapshot_for_event(
                                    pair=str(pair_spot),
                                    side=str(trend_dir),
                                    tag="candidates_pc",
                                    ts=int(ts_ref),
                                    features=arena_features,
                                    regime=str(regime),
                                    thr=float(thr_base),
                                    feature_set_id="ThreeScreen.5m",
                                )
                            except Exception:
                                arena_evt = None
                            models = (arena_evt.get("models") if isinstance(arena_evt, dict) else None)
                            picked = None
                            if isinstance(models, dict):
                                if candidates_pc_model_id and candidates_pc_model_id in models:
                                    picked = candidates_pc_model_id
                                elif "__lr__" in models:
                                    picked = "__lr__"
                                elif "__xgb__" in models:
                                    picked = "__xgb__"
                                elif "__rf__" in models:
                                    picked = "__rf__"
                                else:
                                    best = None
                                    best_key = None
                                    for mid, mv in models.items():
                                        if not isinstance(mv, dict):
                                            continue
                                        try:
                                            eligible = bool(mv.get("eligible", True))
                                        except Exception:
                                            eligible = True
                                        if not bool(eligible):
                                            continue
                                        try:
                                            w = float(mv.get("weight") or 0.0)
                                        except Exception:
                                            w = 0.0
                                        try:
                                            pc1 = float(mv.get("pc") or 0.0)
                                        except Exception:
                                            pc1 = 0.0
                                        k = (float(w), float(pc1), str(mid))
                                        if best_key is None or k > best_key:
                                            best_key = k
                                            best = str(mid)
                                    picked = best
                            pc0 = None
                            if isinstance(models, dict) and picked and picked in models:
                                ci = models.get(str(picked)) or {}
                                try:
                                    pc0 = float(ci.get("pc")) if ci.get("pc") is not None else None
                                except Exception:
                                    pc0 = None
                            if candidates_pc_model_id_eff is None and picked:
                                candidates_pc_model_id_eff = str(picked)
                            candidates_pc_map[c0] = (None if pc0 is None or (not math.isfinite(float(pc0))) else float(pc0))
                            if candidates_pc_map.get(c0) is not None:
                                try:
                                    candidates_score_eff_map[c0] = float(candidates_score_map.get(c0, 0.0)) + float(pc_weight) * 10.0 * float(candidates_pc_map.get(c0) or 0.0)
                                except Exception:
                                    candidates_score_eff_map[c0] = float(candidates_score_map.get(c0, 0.0))

                    picked_alts = [str(coin)] if coin != "BTC" else []
                    others = [r for r in alt_pool if str(r.get("coin") or "").upper().strip() != str(coin)]
                    others.sort(key=lambda r: float(candidates_score_eff_map.get(str(r.get("coin") or "").upper().strip(), float(candidates_score_map.get(str(r.get("coin") or "").upper().strip(), 0.0)))), reverse=True)
                    for r in others:
                        c0 = str(r.get("coin") or "").upper().strip()
                        if not c0 or c0 in picked_alts:
                            continue
                        picked_alts.append(c0)
                        if len(picked_alts) >= max(0, int(max_symbols) - 1):
                            break

                    for a in picked_alts:
                        if a and a not in symbols:
                            symbols.append(str(a))
                    symbols = symbols[:int(max_symbols)]

                    try:
                        btc_w = float(CONFIG.get("three_screen_portfolio_btc_weight", 0.5) or 0.5)
                    except Exception:
                        btc_w = 0.5
                    btc_w = float(_clip(float(btc_w), 0.0, 1.0))

                    weights = {}
                    alts2 = [s for s in symbols if s != "BTC"]
                    if not alts2:
                        weights = {"BTC": 1.0}
                    else:
                        btc_w2 = float(_clip(float(btc_w), 0.0, 1.0 - 1e-9))
                        rem = float(max(0.0, 1.0 - float(btc_w2)))
                        weights["BTC"] = float(btc_w2)
                        score_sum = 0.0
                        for a in alts2:
                            score_sum += float(candidates_score_eff_map.get(str(a).upper().strip(), float(candidates_score_map.get(str(a).upper().strip(), 0.0))))
                        if float(score_sum) > 0.0:
                            for a in alts2:
                                sc = float(candidates_score_eff_map.get(str(a).upper().strip(), float(candidates_score_map.get(str(a).upper().strip(), 0.0))))
                                weights[str(a)] = float(rem) * (float(sc) / float(score_sum))
                        else:
                            each = float(rem / float(len(alts2))) if len(alts2) > 0 else 0.0
                            for a in alts2:
                                weights[str(a)] = float(each)

                    try:
                        cur_coin = str(coin).upper().strip()
                    except Exception:
                        cur_coin = "BTC"
                    try:
                        feats["candidates_score"] = (None if cur_coin == "BTC" else float(candidates_score_map.get(cur_coin, 0.0)))
                    except Exception:
                        feats["candidates_score"] = None
                    if cur_coin != "BTC":
                        try:
                            ranked_all = sorted(
                                [str(r.get("coin") or "").upper().strip() for r in alt_pool if str(r.get("coin") or "").upper().strip()],
                                key=lambda cc: float(candidates_score_eff_map.get(str(cc).upper().strip(), float(candidates_score_map.get(str(cc).upper().strip(), 0.0)))),
                                reverse=True,
                            )
                            feats["candidates_rank"] = (int(ranked_all.index(cur_coin)) + 1) if cur_coin in ranked_all else None
                        except Exception:
                            feats["candidates_rank"] = None
                        try:
                            feats["candidates_pc"] = (None if candidates_pc_map.get(cur_coin) is None else float(candidates_pc_map.get(cur_coin) or 0.0))
                        except Exception:
                            feats["candidates_pc"] = None
                        feats["candidates_pc_model_id"] = (str(candidates_pc_model_id_eff) if candidates_pc_model_id_eff else (None if candidates_pc_model_id is None else str(candidates_pc_model_id)))
                    else:
                        feats["candidates_rank"] = None
                        feats["candidates_pc"] = None
                        feats["candidates_pc_model_id"] = None

                    try:
                        port_rows: List[Dict[str, Any]] = []
                        for s in symbols:
                            c0 = str(s).upper().strip()
                            port_rows.append(
                                {
                                    "coin": c0,
                                    "weight": float(weights.get(c0, 0.0)),
                                    "corr_30d": (corr_map.get(c0) or {}).get("corr_30d"),
                                    "corr_60d": (corr_map.get(c0) or {}).get("corr_60d"),
                                    "beta_30d": (1.0 if c0 == "BTC" else beta_map.get(c0)),
                                    "vol_ratio_30d": None,
                                    "z": z_map.get(c0),
                                    "universe_score": (None if c0 == "BTC" else universe_score_map.get(c0)),
                                    "candidates_score": (None if c0 == "BTC" else candidates_score_map.get(c0)),
                                    "candidates_pc": (None if c0 == "BTC" else candidates_pc_map.get(c0)),
                                }
                            )
                        feats["portfolio_symbols"] = symbols
                        feats["portfolio_weights"] = weights
                        feats["portfolio_side"] = str(trend_dir)
                        feats["portfolio_candidates"] = port_rows
                    except Exception:
                        pass

    try:
        live0 = bool(CONFIG.get("live_trading_enabled", False)) and (not bool(CONFIG.get("dry_run", True)))
        if live0 and bool(trigger) and str(signal_payload.get("action") or "open").strip().lower() == "open":
            now_ms0 = int(now_ms)
            tf0 = str(signal_payload.get("timeframe") or "").strip().lower()
            try:
                tf_ms0 = int(_hl_interval_to_ms(tf0)) if tf0 else 0
            except Exception:
                tf_ms0 = 0
            try:
                bar_open_ms0 = int(signal_payload.get("bar_open_ms") or 0)
            except Exception:
                bar_open_ms0 = 0
            try:
                bar_close_ms0 = int(signal_payload.get("bar_close_ms") or 0)
            except Exception:
                bar_close_ms0 = 0
            if bar_close_ms0 <= 0 and bar_open_ms0 > 0 and tf_ms0 > 0:
                bar_close_ms0 = int(bar_open_ms0 + tf_ms0)
            try:
                ts_ref = int(bar_close_ms0 or bar_open_ms0 or int(signal_payload.get("ts") or 0) or 0)
            except Exception:
                ts_ref = 0
            if ts_ref > 0:
                max_age_ms = int(max((2 * tf_ms0) if tf_ms0 > 0 else 0, 10 * 60 * 1000))
                age_ms = int(now_ms0) - int(ts_ref)
                if int(age_ms) > int(max_age_ms) and tf_ms0 > 0:
                    try:
                        day_ms = 86_400_000
                        day0 = int((now_ms0 // day_ms) * day_ms)
                        is_day_start = (int(bar_open_ms0) > 0) and (int(bar_open_ms0) == int(day0))
                        is_1h_from_day_start = (int(bar_close_ms0) > 0) and (int(bar_close_ms0) == int(bar_open_ms0) + int(tf_ms0))
                    except Exception:
                        is_day_start = False
                        is_1h_from_day_start = False
                    if is_day_start and is_1h_from_day_start:
                        try:
                            repaired_open = int(((int(now_ms0) - int(tf_ms0)) // int(tf_ms0)) * int(tf_ms0))
                            repaired_close = int(repaired_open + int(tf_ms0))
                            signal_payload["bar_open_ms"] = int(repaired_open)
                            signal_payload["bar_close_ms"] = int(repaired_close)
                            signal_payload["ts"] = int(repaired_open)
                            signal_payload["ts_autofix"] = "day_start_to_last_closed"
                            ts_ref = int(repaired_close)
                            age_ms = int(now_ms0) - int(ts_ref)
                        except Exception:
                            pass
                if int(age_ms) > int(max_age_ms):
                    trigger = False
                    signal_payload["trigger_block_reason"] = "signal_stale"
                    signal_payload["trigger_block_age_ms"] = int(age_ms)
                    signal_payload["trigger_block_max_age_ms"] = int(max_age_ms)
    except Exception:
        pass

    if trigger and str(signal_payload.get("action") or "open").strip().lower() == "open" and str((data or {}).get("source") or "").strip().lower() != "feeder":
        try:
            if bool(CONFIG.get("signals_v1_confirm_enabled", False)):
                n = int(CONFIG.get("signals_v1_confirm_n", 2) or 2)
                m = int(CONFIG.get("signals_v1_confirm_m", 3) or 3)
                if n < 1:
                    n = 1
                if m < n:
                    m = n
                if m > 20:
                    m = 20
                if n > 20:
                    n = 20
                bar_open_ms = int(signal_payload.get("bar_open_ms") or 0)
                if bar_open_ms > 0:
                    ckey = _signals_confirm_key_v1(signal_payload)
                    buf = SIGNAL_CONFIRM_V1.get(ckey)
                    if not isinstance(buf, list):
                        buf = []
                    if not buf or int(buf[-1]) != int(bar_open_ms):
                        buf.append(int(bar_open_ms))
                    if len(buf) > int(m) * 5:
                        buf = buf[-int(m) * 5 :]
                    SIGNAL_CONFIRM_V1[ckey] = buf
                    recent = buf[-int(m) :]
                    ok_confirm = len(recent) >= int(n)
                    signal_payload["confirm"] = {"enabled": True, "n": int(n), "m": int(m), "count": int(len(recent)), "ok": bool(ok_confirm)}
                    if not ok_confirm:
                        trigger = False
        except Exception:
            pass

    if bool(trigger):
        try:
            src = str((data or {}).get("source") or "").strip().lower()
        except Exception:
            src = ""
        restrict_non_feeder = False
        try:
            restrict_non_feeder = bool(CONFIG.get("signals_v1_restrict_trigger_non_feeder", False))
        except Exception:
            restrict_non_feeder = False
        if restrict_non_feeder and src != "feeder":
            try:
                ao = _ab_norm_owner_or_empty(signal_payload.get("ab_owner"))
            except Exception:
                ao = ""
            try:
                sys0 = _ab_norm_owner_or_empty(signal_payload.get("system_id"))
            except Exception:
                sys0 = ""
            try:
                bid0 = _ab_norm_owner_or_empty(signal_payload.get("book_id"))
            except Exception:
                bid0 = ""
            if ao not in ("quant", "carry") and sys0 not in ("quant", "carry") and bid0 not in ("quant", "carry"):
                trigger = False
        try:
            if str(signal_payload.get("action") or "").strip().lower() != "open":
                trigger = False
        except Exception:
            trigger = False

    signal_payload["trigger_decision"] = bool(trigger)

    skey = _signals_dedup_key_v1(signal_payload)
    bkey = _signals_dedup_key_v1_base(signal_payload)
    upgrade_evt_id: Optional[str] = None
    upgrade_old_skey: Optional[str] = None
    with SIGNAL_DEDUP_LOCK:
        cached = SIGNAL_DEDUP.get(skey)
        if isinstance(cached, dict):
            cached_sig = cached.get("signal")
            try:
                cached_evt_id = cached.get("evt_id")
                if cached_evt_id is not None and not isinstance(EVENTS.get(str(cached_evt_id)), dict) and isinstance(cached_sig, dict):
                    ts0 = cached_sig.get("bar_open_ms")
                    if ts0 is None:
                        ts0 = cached_sig.get("bar_close_ms")
                    if ts0 is None:
                        ts0 = cached_sig.get("ts_emit_ms")
                    if ts0 is None:
                        ts0 = cached_sig.get("ts")
                    if ts0 is None:
                        ts0 = now_ms
                    try:
                        ts0 = int(ts0)
                    except Exception:
                        ts0 = int(now_ms)
                    EVENTS[str(cached_evt_id)] = {"id": str(cached_evt_id), "ts": int(_ensure_ms(int(ts0))), "ingested_ms": int(now_ms), **dict(cached_sig)}
            except Exception:
                pass
            if isinstance(cached_sig, dict):
                signal_payload.update(cached_sig)
            return _resp_alias_ids(cached.get("resp") or {"ok": True, "id": cached.get("evt_id"), "dedup": True}, evt_id=(None if cached.get("evt_id") is None else str(cached.get("evt_id"))))

        bc = SIGNAL_DEDUP_V1_BASE.get(bkey)
        if isinstance(bc, dict):
            bc_evt = bc.get("evt_id")
            bc_resp = bc.get("resp")
            bc_trig = bool(bc.get("trigger_decision", False))
            if bool(bc.get("inflight")) and not bc_evt:
                if isinstance(bc_resp, dict):
                    return bc_resp
                return {"ok": True, "dedup": True, "inflight": True}
            if bc_evt:
                try:
                    bc_sig = bc.get("signal")
                    if not isinstance(EVENTS.get(str(bc_evt)), dict) and isinstance(bc_sig, dict):
                        ts0 = bc_sig.get("bar_open_ms")
                        if ts0 is None:
                            ts0 = bc_sig.get("bar_close_ms")
                        if ts0 is None:
                            ts0 = bc_sig.get("ts_emit_ms")
                        if ts0 is None:
                            ts0 = bc_sig.get("ts")
                        if ts0 is None:
                            ts0 = now_ms
                        try:
                            ts0 = int(ts0)
                        except Exception:
                            ts0 = int(now_ms)
                        EVENTS[str(bc_evt)] = {"id": str(bc_evt), "ts": int(_ensure_ms(int(ts0))), "ingested_ms": int(now_ms), **dict(bc_sig)}
                except Exception:
                    pass
                if bc_trig or (not bool(trigger)):
                    if isinstance(bc_resp, dict):
                        return _resp_alias_ids(bc_resp, evt_id=str(bc_evt))
                    return _resp_alias_ids({"ok": True, "id": bc_evt, "dedup": True}, evt_id=str(bc_evt))
                try:
                    upgrade_evt_id = str(bc_evt)
                except Exception:
                    upgrade_evt_id = None
                try:
                    upgrade_old_skey = (None if bc.get("skey") is None else str(bc.get("skey")))
                except Exception:
                    upgrade_old_skey = None
                bc["inflight_upgrade"] = True
                bc["seen_ms"] = int(now_ms)

        if upgrade_evt_id is None and not isinstance(SIGNAL_DEDUP_V1_BASE.get(bkey), dict):
            SIGNAL_DEDUP_V1_BASE[bkey] = {
                "seen_ms": int(now_ms),
                "evt_id": None,
                "resp": None,
                "signal": None,
                "trigger_decision": bool(trigger),
                "inflight": True,
                "skey": str(skey),
            }

    def _upgrade_trigger(existing_evt_id: str) -> Optional[Dict[str, Any]]:
        evt = EVENTS.get(str(existing_evt_id))
        if not isinstance(evt, dict):
            return None
        resp_u: Dict[str, Any] = {
            "ok": True,
            "id": str(existing_evt_id),
            "event_id": str(existing_evt_id),
            "trace_id": str(existing_evt_id),
            "trigger_decision": True,
            "action": str(evt.get("action") or "open"),
        }
        dreq: Dict[str, Any] = {
            "pair": evt.get("pair"),
            "side": evt.get("side"),
            "tag": evt.get("tag"),
            "features": (evt.get("features") if isinstance(evt.get("features"), dict) else {}),
            "size": (data.get("size") if data.get("size") is not None else evt.get("size", 0.0)),
            "event_id": str(existing_evt_id),
        }
        if "threshold" in data:
            dreq["threshold"] = data.get("threshold")
        elif "threshold" in evt:
            dreq["threshold"] = evt.get("threshold")
        if "threshold_final" in data:
            dreq["threshold_final"] = data.get("threshold_final")
        elif "threshold_locked" in data:
            dreq["threshold_locked"] = data.get("threshold_locked")
        elif "threshold_absolute" in data:
            dreq["threshold_absolute"] = data.get("threshold_absolute")
        elif "threshold_final" in evt:
            dreq["threshold_final"] = evt.get("threshold_final")
        do_async = False
        try:
            do_async = (str(evt.get("strategy_id") or "") == "ThreeScreen") and bool(CONFIG.get("three_screen_trigger_decision_async", True))
        except Exception:
            do_async = False
        if bool(do_async):
            resp_u["auto_decision"] = True
            resp_u["decision"] = {"ok": True, "decision": "queued", "reason": "async", "event_id": str(existing_evt_id)}
            resp_u["decision_code"] = 202
            try:
                evt["trigger_decision"] = True
            except Exception:
                pass
            try:
                _archive_event(evt)
            except Exception:
                pass

            def _run_async_upgrade() -> None:
                try:
                    out_d0, code0 = _decision_entry_impl(dreq)
                except Exception as e:
                    err = str(e)
                    if len(err) > 800:
                        err = err[:800]
                    out_d0 = {"ok": False, "decision": "error", "reason": "decision_exception", "error": err}
                    code0 = 500
                try:
                    now_ms2 = int(_now_ms())
                    evt2 = EVENTS.get(str(existing_evt_id))
                    if isinstance(evt2, dict):
                        evt2["decision_info"] = _build_decision_info(evt2, dreq=dreq, out=out_d0, code=int(code0), now_ms=now_ms2)
                        try:
                            _archive_event(evt2)
                        except Exception:
                            pass
                except Exception:
                    pass

            try:
                threading.Thread(target=_run_async_upgrade, daemon=True).start()
            except Exception:
                pass
            return resp_u

        out_d, code = _decision_entry_impl(dreq)
        resp_u["auto_decision"] = True
        resp_u["decision"] = out_d
        resp_u["decision_code"] = int(code)
        try:
            evt["trigger_decision"] = True
        except Exception:
            pass
        try:
            evt["decision_info"] = _build_decision_info(evt, dreq=dreq, out=out_d, code=int(code), now_ms=now_ms)
            try:
                _archive_event(evt)
            except Exception:
                pass
        except Exception:
            pass
        return resp_u

    if upgrade_evt_id is not None and bool(trigger):
        try:
            resp_u = _upgrade_trigger(str(upgrade_evt_id))
        except Exception:
            with SIGNAL_DEDUP_LOCK:
                bc2 = SIGNAL_DEDUP_V1_BASE.get(bkey)
                if isinstance(bc2, dict):
                    bc2["inflight_upgrade"] = False
            raise
        if isinstance(resp_u, dict) and bool(resp_u.get("ok")):
            with SIGNAL_DEDUP_LOCK:
                SIGNAL_DEDUP[skey] = {"seen_ms": now_ms, "evt_id": str(upgrade_evt_id), "resp": resp_u, "signal": dict(signal_payload)}
                if upgrade_old_skey and str(upgrade_old_skey) and str(upgrade_old_skey) != str(skey):
                    SIGNAL_DEDUP[str(upgrade_old_skey)] = {"seen_ms": now_ms, "evt_id": str(upgrade_evt_id), "resp": resp_u, "signal": dict(signal_payload)}
                SIGNAL_DEDUP_V1_BASE[bkey] = {
                    "seen_ms": int(now_ms),
                    "evt_id": str(upgrade_evt_id),
                    "resp": resp_u,
                    "signal": dict(signal_payload),
                    "trigger_decision": True,
                    "inflight": False,
                    "inflight_upgrade": False,
                    "skey": str(skey),
                }
            return _resp_alias_ids(resp_u, evt_id=str(upgrade_evt_id))
        with SIGNAL_DEDUP_LOCK:
            bc2 = SIGNAL_DEDUP_V1_BASE.get(bkey)
            if isinstance(bc2, dict):
                bc2["inflight_upgrade"] = False

    feature_set_id = str(signal_payload.get("feature_set_id") or "").strip()
    features = signal_payload.get("features")
    if not isinstance(features, dict):
        features = {}
    if feature_set_id:
        try:
            features = _align_features(feature_set_id, dict(features or {}))
        except Exception:
            features = dict(features or {})
    else:
        features = dict(features or {})
    signal_payload["features"] = features
    signal_payload["strategy_features"] = dict(signal_payload.get("strategy_features") or features)

    if not isinstance(signal_payload.get("market_features"), dict):
        pair0 = str(signal_payload.get("pair") or "").strip()
        ts_mkt = signal_payload.get("bar_open_ms")
        if ts_mkt is None:
            ts_mkt = signal_payload.get("ts_emit_ms")
        try:
            ts_mkt_i = int(ts_mkt or 0)
        except Exception:
            ts_mkt_i = 0
        try:
            if pair0 and ts_mkt_i > 0:
                signal_payload["market_features"] = _ml3_features_at_timestamp(pair0, ts_mkt_i) or {}
            else:
                signal_payload["market_features"] = {}
        except Exception:
            signal_payload["market_features"] = {}

    try:
        merged_features: Dict[str, Any] = {}
        mf = signal_payload.get("market_features")
        if isinstance(mf, dict):
            merged_features.update(mf)
        sf = signal_payload.get("strategy_features")
        if isinstance(sf, dict):
            merged_features.update(sf)
        if merged_features:
            signal_payload["features"] = merged_features
    except Exception:
        pass

    if _arena_enabled() and _ab_norm_owner_or_empty(signal_payload.get("ab_owner")) not in ("quant", "carry") and _ab_norm_owner_or_empty(signal_payload.get("system_id")) not in ("quant", "carry"):
        try:
            now_ms2 = int(now_ms)
            _arena_init_if_needed(now_ms=now_ms2)
            pair_a = str(signal_payload.get("pair") or "").strip()
            side_a = str(signal_payload.get("side") or "").lower().strip()
            if pair_a and side_a in ("long", "short"):
                try:
                    ts_a = int(signal_payload.get("bar_open_ms") or signal_payload.get("ts_emit_ms") or now_ms2)
                except Exception:
                    ts_a = int(now_ms2)
                feats_a = signal_payload.get("features") if isinstance(signal_payload.get("features"), dict) else {}
                tf_a = signal_payload.get("timeframe")
                regime = _get_regime(feats_a, pair=str(pair_a), ts=int(ts_a), timeframe=(None if tf_a is None else str(tf_a)))
                thr = _get_threshold(regime)

                strategy_id = ("" if signal_payload.get("strategy_id") is None else str(signal_payload.get("strategy_id"))).strip() or None
                group_id = ("" if signal_payload.get("group_id") is None else str(signal_payload.get("group_id"))).strip() or None

                if strategy_id is not None:
                    st_ov = _get_strategy_threshold_override(strategy_id)
                    if st_ov is not None:
                        thr = max(float(thr), float(st_ov))
                if group_id is not None:
                    gmeta = _get_group_meta(group_id)
                    if "pc_threshold_min" in (gmeta or {}):
                        try:
                            thr = max(float(thr), float(gmeta.get("pc_threshold_min")))
                        except Exception:
                            pass
                    thr = float(_elastic_overlay_threshold(float(thr), group_id, now_ms2))

                try:
                    ov_all = CONFIG.get("arena_threshold_overrides")
                    ov = None
                    if isinstance(ov_all, dict):
                        if group_id is not None and isinstance(ov_all.get(str(group_id)), (dict, int, float, str)):
                            ov = ov_all.get(str(group_id))
                        elif strategy_id is not None and isinstance(ov_all.get(str(strategy_id)), (dict, int, float, str)):
                            ov = ov_all.get(str(strategy_id))
                        elif isinstance(ov_all.get("default"), (dict, int, float, str)):
                            ov = ov_all.get("default")

                    if isinstance(ov, dict):
                        rv = None
                        try:
                            rv = ov.get(str(regime))
                        except Exception:
                            rv = None
                        if rv is None:
                            try:
                                rv = ov.get("default")
                            except Exception:
                                rv = None
                        if rv is not None:
                            thr = float(rv)
                    elif ov is not None:
                        thr = float(ov)
                except Exception:
                    pass

                feature_set_id = ("" if signal_payload.get("feature_set_id") is None else str(signal_payload.get("feature_set_id"))).strip() or None
                arena_evt = _arena_snapshot_for_event(
                    pair=str(pair_a),
                    side=str(side_a),
                    tag=signal_payload.get("tag"),
                    ts=int(ts_a),
                    features=feats_a,
                    regime=str(regime),
                    thr=float(thr),
                    feature_set_id=feature_set_id,
                )
                try:
                    arena_evt["group_id"] = group_id
                    arena_evt["strategy_id"] = strategy_id
                    arena_evt["system_id"] = str(signal_payload.get("system_id") or _system_from_strategy_id(strategy_id))
                    if bool(CONFIG.get("elastic_gating_enabled", False)):
                        g0 = str(group_id or "global")
                        em = ((ELASTIC_STATE.get("by_group") or {}).get(g0) or {})
                        if isinstance(em, dict) and em:
                            arena_evt["elastic"] = dict(em)
                except Exception:
                    pass
                choice, explore = _arena_choose_executor(arena_evt)
                if choice is not None and isinstance(arena_evt.get("models"), dict):
                    arena_evt["chosen"] = str(choice)
                    arena_evt["explore"] = bool(explore)
                try:
                    if isinstance(arena_evt.get("models"), dict):
                        arena_evt["gate"] = _arena_entry_gate(arena_evt)
                except Exception:
                    pass
                signal_payload["arena"] = arena_evt
        except Exception:
            pass

    evt_id = str(signal_payload.get("event_id") or _gen_id("sig"))
    signal_payload["event_id"] = evt_id
    try:
        if signal_payload.get("book_run_id") is None:
            signal_payload["book_run_id"] = str(BOOK_RUN_ID)
    except Exception:
        pass
    try:
        if signal_payload.get("book_id") is None:
            b0 = _ab_norm_owner_or_empty(signal_payload.get("ab_owner"))
            if not b0:
                b0 = _ab_norm_owner_or_empty(signal_payload.get("system_id"))
            if b0:
                signal_payload["book_id"] = str(b0)
    except Exception:
        pass
    try:
        if signal_payload.get("execution_account_id") is None:
            b0 = _ab_norm_owner_or_empty(signal_payload.get("book_id"))
            if b0:
                signal_payload["execution_account_id"] = _execution_account_id_for_book(str(b0), venue=signal_payload.get("venue"))
    except Exception:
        pass
    ts0 = signal_payload.get("bar_open_ms")
    if ts0 is None:
        ts0 = signal_payload.get("bar_close_ms")
    if ts0 is None:
        ts0 = signal_payload.get("ts_emit_ms")
    if ts0 is None:
        ts0 = _now_ms()
    try:
        ts0 = int(ts0)
    except Exception:
        ts0 = _now_ms()
    EVENTS[evt_id] = {"id": evt_id, "ts": int(ts0), "ingested_ms": int(now_ms), **signal_payload}
    LOG.info(
        "signal id=%s strategy=%s pair=%s side=%s tag=%s",
        evt_id,
        str(signal_payload.get("strategy_id")),
        signal_payload.get("pair"),
        signal_payload.get("side"),
        str(signal_payload.get("tag")),
    )
    try:
        _archive_event(EVENTS.get(evt_id) or {})
    except Exception:
        pass
    resp: Dict[str, Any] = {
        "ok": True,
        "id": evt_id,
        "event_id": evt_id,
        "trace_id": evt_id,
        "trigger_decision": bool(trigger),
        "action": str(signal_payload.get("action") or "open"),
    }
    if trigger:
        dreq: Dict[str, Any] = {
            "pair": signal_payload.get("pair"),
            "side": signal_payload.get("side"),
            "tag": signal_payload.get("tag"),
            "features": signal_payload.get("features") or {},
            "size": (data.get("size") if data.get("size") is not None else signal_payload.get("size", 0.0)),
            "event_id": evt_id,
        }
        if "threshold" in data:
            dreq["threshold"] = data.get("threshold")
        elif "threshold" in signal_payload:
            dreq["threshold"] = signal_payload.get("threshold")
        if "threshold_final" in data:
            dreq["threshold_final"] = data.get("threshold_final")
        elif "threshold_locked" in data:
            dreq["threshold_locked"] = data.get("threshold_locked")
        elif "threshold_absolute" in data:
            dreq["threshold_absolute"] = data.get("threshold_absolute")
        elif "threshold_final" in signal_payload:
            dreq["threshold_final"] = signal_payload.get("threshold_final")
        try:
            do_async = False
            try:
                do_async = (str(signal_payload.get("strategy_id") or "") == "ThreeScreen") and bool(CONFIG.get("three_screen_trigger_decision_async", True))
            except Exception:
                do_async = False
            if bool(do_async):
                out_d = {"ok": True, "decision": "queued", "reason": "async", "event_id": str(evt_id)}
                code = 202

                def _run_async_decision() -> None:
                    try:
                        out_d0, code0 = _decision_entry_impl(dreq)
                    except Exception as e:
                        err = str(e)
                        if len(err) > 800:
                            err = err[:800]
                        out_d0 = {"ok": False, "decision": "error", "reason": "decision_exception", "error": err}
                        code0 = 500
                    try:
                        if str(signal_payload.get("strategy_id") or "") == "ThreeScreen":
                            evt0 = EVENTS.get(str(evt_id))
                            if isinstance(evt0, dict):
                                feats0 = evt0.get("features")
                                if isinstance(feats0, dict):
                                    d0 = str((out_d0 or {}).get("decision") or "").strip().lower()
                                    if d0 in ("hold", "reject"):
                                        rr0 = str(feats0.get("reject_reason") or "").strip()
                                        if not rr0:
                                            r0 = str((out_d0 or {}).get("reason") or (out_d0 or {}).get("error") or "").strip()
                                            if r0:
                                                feats0["reject_reason"] = r0
                    except Exception:
                        pass
                    try:
                        now_ms2 = int(_now_ms())
                        evt2 = EVENTS.get(str(evt_id))
                        if isinstance(evt2, dict):
                            evt2["decision_info"] = _build_decision_info(evt2, dreq=dreq, out=out_d0, code=int(code0), now_ms=now_ms2)
                            try:
                                _archive_event(evt2)
                            except Exception:
                                pass
                    except Exception:
                        pass

                try:
                    threading.Thread(target=_run_async_decision, daemon=True).start()
                except Exception:
                    pass
            else:
                out_d, code = _decision_entry_impl(dreq)
        except Exception as e:
            try:
                evt = EVENTS.get(str(evt_id))
                if isinstance(evt, dict):
                    err = str(e)
                    if len(err) > 800:
                        err = err[:800]
                    evt["decision_info"] = {
                        "ts_ms": int(now_ms),
                        "event_id": evt.get("id"),
                        "pair": str(evt.get("pair")),
                        "side": str((evt.get("side") or "")),
                        "tag": evt.get("tag"),
                        "decision": "error",
                        "decision_code": 500,
                        "reason": "decision_exception",
                        "error": err,
                        "out": None,
                    }
            except Exception:
                pass
            raise
        try:
            if str(signal_payload.get("strategy_id") or "") == "ThreeScreen":
                feats = signal_payload.get("features")
                if isinstance(feats, dict):
                    d0 = str((out_d or {}).get("decision") or "").strip().lower()
                    if d0 in ("hold", "reject"):
                        rr0 = str(feats.get("reject_reason") or "").strip()
                        if not rr0:
                            r0 = str((out_d or {}).get("reason") or (out_d or {}).get("error") or "").strip()
                            if r0:
                                feats["reject_reason"] = r0
                evt0 = EVENTS.get(str(evt_id))
                if isinstance(evt0, dict):
                    f0 = evt0.get("features")
                    if isinstance(f0, dict):
                        f0.update(dict(signal_payload.get("features") or {}))
        except Exception:
            pass
        resp["auto_decision"] = True
        resp["decision"] = out_d
        resp["decision_code"] = int(code)
        if not (isinstance(out_d, dict) and str(out_d.get("decision") or "").strip().lower() == "queued"):
            try:
                evt = EVENTS.get(str(evt_id))
                if isinstance(evt, dict):
                    evt["decision_info"] = _build_decision_info(evt, dreq=dreq, out=out_d, code=int(code), now_ms=now_ms)
                    try:
                        _archive_event(evt)
                    except Exception:
                        pass
            except Exception:
                pass
    with SIGNAL_DEDUP_LOCK:
        SIGNAL_DEDUP[skey] = {"seen_ms": now_ms, "evt_id": evt_id, "resp": resp, "signal": dict(signal_payload)}
        SIGNAL_DEDUP_V1_BASE[bkey] = {
            "seen_ms": int(now_ms),
            "evt_id": str(evt_id),
            "resp": resp,
            "signal": dict(signal_payload),
            "trigger_decision": bool(trigger),
            "inflight": False,
            "inflight_upgrade": False,
            "skey": str(skey),
        }
    try:
        _on_signal_ingest(evt_id)
    except Exception:
        pass
    return _resp_alias_ids(resp, evt_id=str(evt_id))


@app.route("/signals/v1", methods=["POST"])
def signals_v1():
    data = request.get_json(force=True) or {}
    payload = data
    if isinstance(data.get("signal"), dict):
        payload = data.get("signal")
    if not isinstance(payload, dict):
        return jsonify({"ok": False, "error": "invalid_payload"}), 400

    err_ts = _three_screen_validate_signal_v1(payload)
    if err_ts is not None:
        return jsonify({"ok": False, "error": str(err_ts)}), 400

    pair = payload.get("pair")
    side = str(payload.get("side") or "").lower()
    if side not in ("long", "short"):
        return jsonify({"ok": False, "error": "invalid_side"}), 400
    if not pair:
        return jsonify({"ok": False, "error": "missing_pair"}), 400

    trigger = None
    if "trigger_decision" in data:
        trigger = bool(data.get("trigger_decision"))
    elif "auto_decision" in data:
        trigger = bool(data.get("auto_decision"))
    elif "trigger_decision" in payload:
        trigger = bool(payload.get("trigger_decision"))
    elif "auto_decision" in payload:
        trigger = bool(payload.get("auto_decision"))
    else:
        trigger = bool(CONFIG.get("signals_auto_decision", False))

    action = str(payload.get("action") or "open").lower()
    if action != "open":
        try:
            payload["action"] = "observe"
        except Exception:
            pass
        trigger = False

    try:
        if not bool(payload.get("bar_closed", True)):
            allow_unclosed = False
            try:
                allow_unclosed = bool(CONFIG.get("signals_allow_unclosed_bars_for_quant", True))
            except Exception:
                allow_unclosed = False
            if bool(allow_unclosed):
                try:
                    ao = _ab_norm_owner_or_empty(payload.get("ab_owner"))
                except Exception:
                    ao = ""
                try:
                    sys0 = _ab_norm_owner_or_empty(payload.get("system_id"))
                except Exception:
                    sys0 = ""
                try:
                    bid0 = _ab_norm_owner_or_empty(payload.get("book_id"))
                except Exception:
                    bid0 = ""
                allow_unclosed = (ao in ("quant", "carry")) or (sys0 in ("quant", "carry")) or (bid0 in ("quant", "carry"))
            if bool(allow_unclosed):
                payload["bar_closed"] = True
            else:
                trigger = False
    except Exception:
        pass

    data2 = dict(data)
    try:
        if "size" not in data2 and payload.get("size") is not None:
            data2["size"] = payload.get("size")
    except Exception:
        pass
    try:
        if "threshold" not in data2 and payload.get("threshold") is not None:
            data2["threshold"] = payload.get("threshold")
    except Exception:
        pass

    try:
        if "threshold_final" not in data2 and payload.get("threshold_final") is not None:
            data2["threshold_final"] = payload.get("threshold_final")
    except Exception:
        pass

    resp = _emit_signal_v1(dict(payload), bool(trigger), dict(data2))
    return jsonify(resp)


@app.route("/three_screen/weekly/status", methods=["GET"])
def three_screen_weekly_status():
    now_ms = int(_now_ms())
    pair = request.args.get("pair")
    group_id = request.args.get("group_id")
    require_bar_closed = True
    try:
        v = request.args.get("require_bar_closed")
        if v is not None:
            require_bar_closed = bool(str(v or "").strip().lower() in ("1", "true", "yes", "y", "on"))
    except Exception:
        require_bar_closed = True

    auto_compute = True
    try:
        v = request.args.get("auto_compute")
        if v is not None:
            auto_compute = bool(str(v or "").strip().lower() in ("1", "true", "yes", "y", "on"))
        else:
            auto_compute = bool(CONFIG.get("three_screen_weekly_status_autofill", True))
    except Exception:
        auto_compute = True

    evt = _three_screen_pick_latest_event(
        timeframe="1w",
        coin=(None if pair is None else str(pair)),
        group_id=(None if group_id is None else str(group_id)),
        date_utc=None,
        require_bar_closed=bool(require_bar_closed),
    )
    if (not isinstance(evt, dict)) and bool(auto_compute):
        try:
            _three_screen_weekly_build_and_emit(coin=str(pair or "BTC"), group_id=(None if group_id is None else str(group_id)), emit=True)
        except Exception:
            pass
        evt = _three_screen_pick_latest_event(
            timeframe="1w",
            coin=(None if pair is None else str(pair)),
            group_id=(None if group_id is None else str(group_id)),
            date_utc=None,
            require_bar_closed=bool(require_bar_closed),
        )
    if not isinstance(evt, dict):
        ttl_ms = _three_screen_ttl_ms("1w")
        return jsonify(
            {
                "ok": True,
                "ts_ms": int(now_ms),
                "timeframe": "1w",
                "pair": _three_screen_pair_coin(pair or "BTC"),
                "group_id": (None if group_id is None else str(group_id)),
                "exists": False,
                "event_id": None,
                "bar_open_ms": 0,
                "bar_close_ms": 0,
                "bar_closed": None,
                "asof_week": None,
                "weekly_trend_dir": None,
                "weekly_trend_strength": None,
                "weekly_regime": None,
                "components": None,
                "reason_codes": [],
                "ttl_ms": int(ttl_ms),
                "data_age_ms": None,
                "stale": True,
                "trend": None,
                "weekly_components": None,
            }
        )

    feats = evt.get("features")
    if not isinstance(feats, dict):
        feats = evt.get("strategy_features")
    if not isinstance(feats, dict):
        feats = {}
    ttl_ms = _three_screen_ttl_ms("1w")
    bar_close_ms = _ensure_ms(int(evt.get("bar_close_ms") or 0))
    age_ms = None
    try:
        age_ms = int(now_ms) - int(bar_close_ms or int(evt.get("ts_emit_ms") or evt.get("ts") or now_ms))
        if age_ms < 0:
            age_ms = 0
    except Exception:
        age_ms = None
    stale = bool(age_ms is None or int(age_ms) > int(ttl_ms))
    if bool(stale) and bool(auto_compute):
        try:
            _three_screen_weekly_build_and_emit(coin=str(pair or "BTC"), group_id=(None if group_id is None else str(group_id)), emit=True)
        except Exception:
            pass
        evt2 = _three_screen_pick_latest_event(
            timeframe="1w",
            coin=(None if pair is None else str(pair)),
            group_id=(None if group_id is None else str(group_id)),
            date_utc=None,
            require_bar_closed=bool(require_bar_closed),
        )
        if isinstance(evt2, dict):
            evt = evt2
            feats = evt.get("features")
            if not isinstance(feats, dict):
                feats = evt.get("strategy_features")
            if not isinstance(feats, dict):
                feats = {}
            bar_close_ms = _ensure_ms(int(evt.get("bar_close_ms") or 0))
            try:
                age_ms = int(now_ms) - int(bar_close_ms or int(evt.get("ts_emit_ms") or evt.get("ts") or now_ms))
                if age_ms < 0:
                    age_ms = 0
            except Exception:
                age_ms = None
            stale = bool(age_ms is None or int(age_ms) > int(ttl_ms))
    try:
        strength = float(feats.get("weekly_trend_strength")) if feats.get("weekly_trend_strength") is not None else None
    except Exception:
        strength = None
    trend_dir = str(feats.get("weekly_trend_dir") or "neutral").strip().lower()
    if trend_dir not in ("long", "short", "neutral"):
        trend_dir = "neutral"
    reason = feats.get("weekly_reason")
    if reason is None:
        reason = evt.get("tag")

    asof_week = feats.get("weekly_asof_week")
    if asof_week is None or (isinstance(asof_week, str) and not asof_week.strip()):
        try:
            dt = datetime.utcfromtimestamp(float(bar_close_ms) / 1000.0) if bar_close_ms > 0 else datetime.utcnow()
            iso = dt.isocalendar()
            asof_week = f"{int(iso[0])}-W{int(iso[1]):02d}"
        except Exception:
            asof_week = None

    weekly_regime = (None if feats.get("weekly_regime") is None else str(feats.get("weekly_regime")))

    components = feats.get("weekly_components") if isinstance(feats.get("weekly_components"), dict) else None
    if components is None:
        try:
            cand = {}
            for k in ("adx", "macd_hist", "macd_slope", "donchian_breakout", "atr_pct", "atr_pct_quantile"):
                if feats.get(k) is not None:
                    cand[k] = feats.get(k)
            components = cand if cand else None
        except Exception:
            components = None

    reason_codes = feats.get("weekly_reason_codes") if isinstance(feats.get("weekly_reason_codes"), list) else None
    if reason_codes is None:
        reason_codes = []
        if reason is not None and str(reason).strip():
            reason_codes = [str(reason).strip()]

    weekly_trend_dir_a = feats.get("weekly_trend_dir_a")
    if weekly_trend_dir_a is not None:
        weekly_trend_dir_a = str(weekly_trend_dir_a).strip().lower()
        if weekly_trend_dir_a not in ("long", "short", "neutral"):
            weekly_trend_dir_a = None
    weekly_trend_dir_b = feats.get("weekly_trend_dir_b")
    if weekly_trend_dir_b is not None:
        weekly_trend_dir_b = str(weekly_trend_dir_b).strip().lower()
        if weekly_trend_dir_b not in ("long", "short", "neutral"):
            weekly_trend_dir_b = None
    try:
        weekly_trend_strength_a = float(feats.get("weekly_trend_strength_a")) if feats.get("weekly_trend_strength_a") is not None else None
    except Exception:
        weekly_trend_strength_a = None
    try:
        weekly_trend_strength_b = float(feats.get("weekly_trend_strength_b")) if feats.get("weekly_trend_strength_b") is not None else None
    except Exception:
        weekly_trend_strength_b = None
    try:
        weekly_ab_b_enabled = bool(feats.get("weekly_ab_b_enabled")) if feats.get("weekly_ab_b_enabled") is not None else None
    except Exception:
        weekly_ab_b_enabled = None
    try:
        weekly_ab_b_neutral_strength_mult = float(feats.get("weekly_ab_b_neutral_strength_mult")) if feats.get("weekly_ab_b_neutral_strength_mult") is not None else None
    except Exception:
        weekly_ab_b_neutral_strength_mult = None
    try:
        weekly_ab_b_veto_opposite = bool(feats.get("weekly_ab_b_veto_opposite")) if feats.get("weekly_ab_b_veto_opposite") is not None else None
    except Exception:
        weekly_ab_b_veto_opposite = None
    try:
        weekly_ab_b_dampened = bool(feats.get("weekly_ab_b_dampened")) if feats.get("weekly_ab_b_dampened") is not None else None
    except Exception:
        weekly_ab_b_dampened = None
    try:
        weekly_ab_b_vetoed = bool(feats.get("weekly_ab_b_vetoed")) if feats.get("weekly_ab_b_vetoed") is not None else None
    except Exception:
        weekly_ab_b_vetoed = None
    try:
        weekly_ab_b_score_long = float(feats.get("weekly_ab_b_score_long")) if feats.get("weekly_ab_b_score_long") is not None else None
    except Exception:
        weekly_ab_b_score_long = None
    try:
        weekly_ab_b_score_short = float(feats.get("weekly_ab_b_score_short")) if feats.get("weekly_ab_b_score_short") is not None else None
    except Exception:
        weekly_ab_b_score_short = None
    weekly_reason_codes_a = feats.get("weekly_reason_codes_a") if isinstance(feats.get("weekly_reason_codes_a"), list) else None
    weekly_reason_codes_b = feats.get("weekly_reason_codes_b") if isinstance(feats.get("weekly_reason_codes_b"), list) else None

    try:
        need_components = True
        if isinstance(components, dict) and components:
            need_keys = ("ema_fast", "ema_slow", "ema_slope", "ma_spread", "adx", "macd_hist")
            need_components = any((k not in components) or (components.get(k) is None) for k in need_keys)
        if bool(need_components) and pd is not None:
            c2 = _three_screen_pair_coin(evt.get("pair") or pair or "BTC")
            d2 = _macro_daily_df(str(c2 or "BTC"))
            w2, _, _ = _three_screen_weekly_last_closed(d2)
            if w2 is not None and len(w2) >= 10:
                feats2 = _three_screen_weekly_trend_features(w2)
                comps2 = feats2.get("weekly_components") if isinstance(feats2, dict) else None
                if isinstance(comps2, dict) and comps2:
                    components = comps2
                if weekly_reason_codes_a is None:
                    wrca2 = feats2.get("weekly_reason_codes_a") if isinstance(feats2, dict) else None
                    if isinstance(wrca2, list):
                        weekly_reason_codes_a = wrca2
                if weekly_reason_codes_b is None:
                    wrcb2 = feats2.get("weekly_reason_codes_b") if isinstance(feats2, dict) else None
                    if isinstance(wrcb2, list):
                        weekly_reason_codes_b = wrcb2
    except Exception:
        pass

    return jsonify(
        _json_sanitize(
            {
                "ok": True,
                "ts_ms": int(now_ms),
                "timeframe": "1w",
                "pair": _three_screen_pair_coin(evt.get("pair") or pair or "BTC"),
                "group_id": (None if evt.get("group_id") is None else str(evt.get("group_id"))),
                "exists": True,
                "event_id": (None if evt.get("id") is None else str(evt.get("id"))),
                "bar_open_ms": int(_ensure_ms(int(evt.get("bar_open_ms") or 0))),
                "bar_close_ms": int(bar_close_ms),
                "bar_closed": bool(evt.get("bar_closed", True)),
                "asof_week": (None if asof_week is None else str(asof_week)),
                "weekly_trend_dir": str(trend_dir),
                "weekly_trend_strength": strength,
                "weekly_trend_dir_a": weekly_trend_dir_a,
                "weekly_trend_strength_a": weekly_trend_strength_a,
                "weekly_trend_dir_b": weekly_trend_dir_b,
                "weekly_trend_strength_b": weekly_trend_strength_b,
                "weekly_ab_b_enabled": weekly_ab_b_enabled,
                "weekly_ab_b_neutral_strength_mult": weekly_ab_b_neutral_strength_mult,
                "weekly_ab_b_veto_opposite": weekly_ab_b_veto_opposite,
                "weekly_ab_b_dampened": weekly_ab_b_dampened,
                "weekly_ab_b_vetoed": weekly_ab_b_vetoed,
                "weekly_ab_b_score_long": weekly_ab_b_score_long,
                "weekly_ab_b_score_short": weekly_ab_b_score_short,
                "weekly_reason_codes_a": (weekly_reason_codes_a if isinstance(weekly_reason_codes_a, list) else []),
                "weekly_reason_codes_b": (weekly_reason_codes_b if isinstance(weekly_reason_codes_b, list) else []),
                "weekly_regime": weekly_regime,
                "components": components,
                "reason_codes": (reason_codes if isinstance(reason_codes, list) else []),
                "ttl_ms": int(ttl_ms),
                "data_age_ms": age_ms,
                "stale": bool(stale),
                "trend": {
                    "dir": str(trend_dir),
                    "strength": strength,
                    "asof_week": (None if asof_week is None else str(asof_week)),
                    "reason": (None if reason is None else str(reason)),
                },
                "weekly_components": (None if components is None else dict(components)),
            }
        )
    )


def _three_screen_weekly_offline_diagnostics(*, coin: str, lookback_weeks: int, lookback_days: int, bins: int) -> Dict[str, Any]:
    now_ms = int(_now_ms())
    if pd is None:
        return {"ok": False, "ts_ms": int(now_ms), "error": "pandas_unavailable"}
    coin0 = str(coin or "BTC").strip().upper() or "BTC"
    try:
        lb = int(lookback_weeks)
    except Exception:
        lb = 260
    lb = int(max(60, min(520, int(lb))))
    try:
        ld = int(lookback_days)
    except Exception:
        ld = 0
    if ld <= 0:
        ld = int(max(400, int(lb) * 7 + 90))
    ld = int(max(30, min(6000, int(ld))))
    try:
        b = int(bins)
    except Exception:
        b = 10
    b = int(max(2, min(50, int(b))))

    daily_meta = None
    try:
        daily, daily_meta = _macro_daily_df_with_lookback_meta(coin0, lookback_days=int(ld))
        weekly = _macro_weekly_df(daily)
    except Exception as e:
        return {"ok": False, "ts_ms": int(now_ms), "coin": str(coin0), "error": "fetch_failed", "detail": str(e)}
    if weekly is None or len(weekly) < 30:
        return {"ok": False, "ts_ms": int(now_ms), "coin": str(coin0), "error": "not_enough_weekly_bars", "weekly_bars": (0 if weekly is None else int(len(weekly))), "lookback_days": int(ld)}

    try:
        ff = _three_screen_weekly_feature_frame(weekly, lookback_weeks=int(lb))
    except Exception as e:
        return {"ok": False, "ts_ms": int(now_ms), "coin": str(coin0), "error": "feature_frame_failed", "detail": str(e)}
    if ff is None or len(ff) < 30:
        return {"ok": False, "ts_ms": int(now_ms), "coin": str(coin0), "error": "not_enough_feature_rows"}

    diag_cols_raw = ["ma_spread", "ema_slope", "adx", "donchian_pos", "atr_pct", "macd_hist"]
    diag_cols_strength = ["adx_quantile", "don_score", "atr_state", "macd_abs_quantile", "strength_mag"]
    use_raw = [c for c in diag_cols_raw if c in ff.columns]
    use_strength = [c for c in diag_cols_strength if c in ff.columns]

    def _corr_pack(cols: List[str]) -> Any:
        try:
            cm = ff[cols].astype(float).corr()
        except Exception:
            return None
        out_rows: List[Dict[str, Any]] = []
        for i in range(len(cols)):
            for j in range(i + 1, len(cols)):
                a = str(cols[i])
                b2 = str(cols[j])
                try:
                    v = float(cm.loc[a, b2])
                except Exception:
                    continue
                if math.isfinite(float(v)):
                    out_rows.append({"a": a, "b": b2, "corr": float(v)})
        out_rows.sort(key=lambda z: abs(float(z.get("corr") or 0.0)), reverse=True)
        return out_rows[:50]

    def _mi_pack(cols: List[str]) -> Any:
        rows: List[Dict[str, Any]] = []
        for i in range(len(cols)):
            for j in range(i + 1, len(cols)):
                a = str(cols[i])
                b2 = str(cols[j])
                try:
                    mi = float(_mi_pair_discrete(ff[a], ff[b2], bins=int(b)))
                except Exception:
                    mi = 0.0
                if math.isfinite(float(mi)) and float(mi) > 0.0:
                    rows.append({"a": a, "b": b2, "mi": float(mi)})
        rows.sort(key=lambda z: float(z.get("mi") or 0.0), reverse=True)
        return rows[:50]

    rep: Dict[str, Any] = {
        "ok": True,
        "ts_ms": int(now_ms),
        "coin": str(coin0),
        "n_rows": int(len(ff)),
        "lookback_weeks": int(lb),
        "lookback_days": int(ld),
        "bins": int(b),
        "daily_meta": (daily_meta if isinstance(daily_meta, dict) else None),
        "raw": {
            "features": use_raw,
            "corr_top": _corr_pack(use_raw) if len(use_raw) >= 2 else [],
            "mi_top": _mi_pack(use_raw) if len(use_raw) >= 2 else [],
            "vif": _vif_from_df(ff, use_raw) if len(use_raw) >= 2 else {},
            "pca": _pca_from_df(ff, use_raw, n_components=min(5, len(use_raw))) if len(use_raw) >= 2 else None,
        },
        "strength": {
            "features": use_strength,
            "corr_top": _corr_pack(use_strength) if len(use_strength) >= 2 else [],
            "mi_top": _mi_pack(use_strength) if len(use_strength) >= 2 else [],
            "vif": _vif_from_df(ff, use_strength) if len(use_strength) >= 2 else {},
            "pca": _pca_from_df(ff, use_strength, n_components=min(5, len(use_strength))) if len(use_strength) >= 2 else None,
        },
    }
    try:
        rep["range_approx"] = {
            "from": (None if ff.index.min() is None else str(pd.Timestamp(ff.index.min()).date())),
            "to": (None if ff.index.max() is None else str(pd.Timestamp(ff.index.max()).date())),
        }
    except Exception:
        pass
    return _json_sanitize(rep)


def _freqtrade_cli_run(args: List[str], *, timeout_sec: float) -> Dict[str, Any]:
    ft_bin = _freqtrade_bin()
    ft_py = _freqtrade_python()
    cmd: List[str]
    if ft_bin:
        cmd = [ft_bin] + [str(x) for x in (args or [])]
    elif ft_py:
        cmd = [ft_py, "-m", "freqtrade"] + [str(x) for x in (args or [])]
    else:
        return {"ok": False, "error": "freqtrade_not_found"}
    try:
        r = subprocess.run(
            cmd,
            cwd=str(Path(__file__).resolve().parent),
            capture_output=True,
            text=True,
            timeout=float(timeout_sec),
            env=dict(os.environ),
        )
    except Exception as e:
        return {"ok": False, "error": "freqtrade_run_exception", "detail": str(e), "cmd": cmd}
    return {
        "ok": (r.returncode == 0),
        "returncode": int(r.returncode),
        "stdout": str(r.stdout or ""),
        "stderr": str(r.stderr or ""),
        "cmd": cmd,
    }


def _three_screen_backfill_timerange_days(days: int) -> str:
    try:
        d = int(days)
    except Exception:
        d = 0
    d = int(max(14, min(3650, int(d))))
    try:
        end = datetime.utcnow().date() + timedelta(days=1)
    except Exception:
        end = datetime.now(timezone.utc).date() + timedelta(days=1)
    start = end - timedelta(days=int(d))
    return start.strftime("%Y%m%d") + "-" + end.strftime("%Y%m%d")


def _three_screen_backfill_local_daily_and_probe(*, coin: str, lookback_days: int, timeout_sec: float) -> Dict[str, Any]:
    now_ms = int(_now_ms())
    c0 = _three_screen_pair_coin(coin)
    c = str(c0 or coin or "").strip().upper()
    if not c:
        c = "BTC"
    pair = f"{c}/USDT"
    timerange = _three_screen_backfill_timerange_days(int(lookback_days))

    config_path = Path(__file__).resolve().parent / "user_data" / "config_freqtrade.json"
    if not config_path.exists():
        return {"ok": False, "ts_ms": int(now_ms), "coin": str(c), "pair": str(pair), "timerange": str(timerange), "error": "config_not_found", "config_path": str(config_path)}

    try:
        cfg = json.loads(config_path.read_text(encoding="utf-8"))
    except Exception as e:
        return {"ok": False, "ts_ms": int(now_ms), "coin": str(c), "pair": str(pair), "timerange": str(timerange), "error": "config_read_failed", "detail": str(e), "config_path": str(config_path)}

    cfg2 = dict(cfg) if isinstance(cfg, dict) else {}
    ex = cfg2.get("exchange") if isinstance(cfg2.get("exchange"), dict) else {}
    ex2 = dict(ex) if isinstance(ex, dict) else {}
    ex2["pair_whitelist"] = [str(pair)]
    cfg2["exchange"] = ex2

    tmp_path = None
    try:
        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False, encoding="utf-8") as fh:
            tmp_path = fh.name
            fh.write(json.dumps(cfg2, ensure_ascii=False))
    except Exception as e:
        return {"ok": False, "ts_ms": int(now_ms), "coin": str(c), "pair": str(pair), "timerange": str(timerange), "error": "temp_config_write_failed", "detail": str(e)}

    try:
        dl = _freqtrade_cli_run(
            ["download-data", "--config", str(tmp_path), "--timerange", str(timerange), "--prepend", "-t", "1d"],
            timeout_sec=float(timeout_sec),
        )
    finally:
        try:
            if tmp_path:
                os.unlink(str(tmp_path))
        except Exception:
            pass

    try:
        DATA_INDEX.clear()
        DATA_INDEX_ALL.clear()
        PAIR_CACHE.clear()
    except Exception:
        pass
    try:
        HL_CANDLES_CACHE.pop(f"local|{c}|1d", None)
        HL_CANDLES_CACHE.pop(f"local|{c}|1h", None)
    except Exception:
        pass

    local_daily_rows = 0
    local_weekly_rows = 0
    local_range = None
    try:
        if pd is not None:
            prev_max_stale = None
            prev_min_stale = None
            try:
                prev_max_stale = CONFIG.get("hl_candles_max_stale_bars")
                prev_min_stale = CONFIG.get("hl_candles_min_stale_ms")
                CONFIG["hl_candles_max_stale_bars"] = 45
                CONFIG["hl_candles_min_stale_ms"] = 0
            except Exception:
                prev_max_stale = None
                prev_min_stale = None
            try:
                dfi = _hl_fetch_df(coin=str(c), timeframe="1d", source="local")
            finally:
                try:
                    if prev_max_stale is None:
                        CONFIG.pop("hl_candles_max_stale_bars", None)
                    else:
                        CONFIG["hl_candles_max_stale_bars"] = prev_max_stale
                    if prev_min_stale is None:
                        CONFIG.pop("hl_candles_min_stale_ms", None)
                    else:
                        CONFIG["hl_candles_min_stale_ms"] = prev_min_stale
                except Exception:
                    pass
            d0 = dfi.copy()
            d0 = d0.dropna(subset=["date", "close"]).sort_values("date").reset_index(drop=True)
            d0["date"] = pd.to_datetime(d0["date"], utc=True, errors="coerce")
            d0 = d0.dropna(subset=["date"]).reset_index(drop=True)
            local_daily_rows = int(len(d0))
            if local_daily_rows > 0:
                try:
                    local_range = {
                        "from": (None if d0["date"].min() is None else str(pd.Timestamp(d0["date"].min()).date())),
                        "to": (None if d0["date"].max() is None else str(pd.Timestamp(d0["date"].max()).date())),
                    }
                except Exception:
                    local_range = None
            d0 = d0.set_index("date")
            w0 = _macro_weekly_df(d0) if local_daily_rows > 0 else None
            local_weekly_rows = 0 if w0 is None else int(len(w0))
    except Exception:
        pass

    return {
        "ok": bool(dl.get("ok")),
        "ts_ms": int(now_ms),
        "coin": str(c),
        "pair": str(pair),
        "timerange": str(timerange),
        "download": dl,
        "local_daily_rows": int(local_daily_rows),
        "local_weekly_rows": int(local_weekly_rows),
        "local_range": local_range,
    }


_THREE_SCREEN_BACKFILL_LOCK = threading.Lock()
_THREE_SCREEN_BACKFILL_JOBS: Dict[str, Dict[str, Any]] = {}


def _three_screen_backfill_jobs_prune(now_ms: int) -> None:
    try:
        cutoff = int(now_ms) - 24 * 3600 * 1000
    except Exception:
        cutoff = 0
    with _THREE_SCREEN_BACKFILL_LOCK:
        keys = list(_THREE_SCREEN_BACKFILL_JOBS.keys())
        for k in keys:
            j = _THREE_SCREEN_BACKFILL_JOBS.get(k)
            if not isinstance(j, dict):
                _THREE_SCREEN_BACKFILL_JOBS.pop(k, None)
                continue
            try:
                ts = int(j.get("ts_ms") or 0)
            except Exception:
                ts = 0
            if cutoff > 0 and ts > 0 and ts < cutoff:
                _THREE_SCREEN_BACKFILL_JOBS.pop(k, None)
        if len(_THREE_SCREEN_BACKFILL_JOBS) > 30:
            items = sorted(
                [(k2, int(((_THREE_SCREEN_BACKFILL_JOBS.get(k2) or {}) if isinstance(_THREE_SCREEN_BACKFILL_JOBS.get(k2), dict) else {}).get("ts_ms") or 0)) for k2 in _THREE_SCREEN_BACKFILL_JOBS.keys()],
                key=lambda x: x[1],
                reverse=True,
            )
            keep = set([k2 for k2, _ in items[:30]])
            for k2 in list(_THREE_SCREEN_BACKFILL_JOBS.keys()):
                if k2 not in keep:
                    _THREE_SCREEN_BACKFILL_JOBS.pop(k2, None)


def _three_screen_backfill_job_run(*, job_id: str, coin: str, group_id: str, lookback_days: int, timeout_sec: float) -> None:
    now_ms = int(_now_ms())
    try:
        with _THREE_SCREEN_BACKFILL_LOCK:
            j = _THREE_SCREEN_BACKFILL_JOBS.get(str(job_id))
            if isinstance(j, dict):
                j["status"] = "running"
                j["updated_ts_ms"] = int(now_ms)
    except Exception:
        pass

    rep = None
    weekly_emit = None
    err = None
    try:
        rep = _three_screen_backfill_local_daily_and_probe(coin=str(coin), lookback_days=int(lookback_days), timeout_sec=float(timeout_sec))
        if isinstance(rep, dict) and bool(rep.get("ok")):
            prev_src = None
            prev_max_stale = None
            prev_min_stale = None
            try:
                prev_src = CONFIG.get("hl_candles_source")
                CONFIG["hl_candles_source"] = "local"
                prev_max_stale = CONFIG.get("hl_candles_max_stale_bars")
                prev_min_stale = CONFIG.get("hl_candles_min_stale_ms")
                CONFIG["hl_candles_max_stale_bars"] = 45
                CONFIG["hl_candles_min_stale_ms"] = 0
            except Exception:
                prev_src = None
            try:
                weekly_emit = _three_screen_weekly_build_and_emit(coin=str(rep.get("coin") or coin), group_id=str(group_id), emit=True)
            finally:
                try:
                    if prev_src is None:
                        CONFIG.pop("hl_candles_source", None)
                    else:
                        CONFIG["hl_candles_source"] = prev_src
                    if prev_max_stale is None:
                        CONFIG.pop("hl_candles_max_stale_bars", None)
                    else:
                        CONFIG["hl_candles_max_stale_bars"] = prev_max_stale
                    if prev_min_stale is None:
                        CONFIG.pop("hl_candles_min_stale_ms", None)
                    else:
                        CONFIG["hl_candles_min_stale_ms"] = prev_min_stale
                except Exception:
                    pass
    except Exception as e:
        err = str(e)

    ok = bool(isinstance(rep, dict) and bool(rep.get("ok"))) and (weekly_emit is None or bool((weekly_emit or {}).get("ok", True)))
    end_ms = int(_now_ms())
    with _THREE_SCREEN_BACKFILL_LOCK:
        j2 = _THREE_SCREEN_BACKFILL_JOBS.get(str(job_id))
        if isinstance(j2, dict):
            j2["ok"] = bool(ok)
            j2["status"] = ("done" if bool(ok) else "error")
            j2["updated_ts_ms"] = int(end_ms)
            j2["backfill"] = rep
            j2["weekly_emit"] = weekly_emit
            if err:
                j2["error"] = str(err)


@app.route("/three_screen/backfill/status", methods=["GET"])
def three_screen_backfill_status():
    now_ms = int(_now_ms())
    job_id = request.args.get("job_id") or ""
    _three_screen_backfill_jobs_prune(int(now_ms))
    with _THREE_SCREEN_BACKFILL_LOCK:
        j = _THREE_SCREEN_BACKFILL_JOBS.get(str(job_id))
        if isinstance(j, dict):
            return jsonify(_json_sanitize({"ok": True, "ts_ms": int(now_ms), "job": j}))
    return jsonify(_json_sanitize({"ok": False, "ts_ms": int(now_ms), "error": "job_not_found", "job_id": str(job_id)}))


@app.route("/three_screen/backfill", methods=["POST"])
def three_screen_backfill():
    now_ms = int(_now_ms())
    payload = request.get_json(silent=True) if request.method == "POST" else None
    if not isinstance(payload, dict):
        payload = {}
    coin = payload.get("pair") or payload.get("coin") or "BTC"
    group_id = payload.get("group_id")
    lookback_days = payload.get("lookback_days")
    timeout_sec = payload.get("timeout_sec")
    sync = payload.get("sync")

    try:
        ld = int(lookback_days) if lookback_days is not None else int(CONFIG.get("three_screen_backfill_lookback_days", 900) or 900)
    except Exception:
        ld = 900
    ld = int(max(30, min(3650, int(ld))))
    try:
        to = float(timeout_sec) if timeout_sec is not None else float(CONFIG.get("three_screen_backfill_timeout_sec", 600.0) or 600.0)
    except Exception:
        to = 600.0
    to = float(max(30.0, min(7200.0, float(to))))

    try:
        gid = (None if group_id is None else str(group_id).strip())
    except Exception:
        gid = None
    if not gid:
        try:
            gid = str(CONFIG.get("three_screen_group_id_default", "ThreeScreen.v0") or "ThreeScreen.v0")
        except Exception:
            gid = "ThreeScreen.v0"

    try:
        sync0 = bool(sync) if isinstance(sync, bool) else bool(str(sync or "").strip().lower() in ("1", "true", "yes", "y", "on"))
    except Exception:
        sync0 = False
    if bool(sync0):
        rep = _three_screen_backfill_local_daily_and_probe(coin=str(coin), lookback_days=int(ld), timeout_sec=float(to))
        weekly_emit = None
        try:
            if bool(rep.get("ok")):
                prev_src = None
                prev_max_stale = None
                prev_min_stale = None
                try:
                    prev_src = CONFIG.get("hl_candles_source")
                    CONFIG["hl_candles_source"] = "local"
                    prev_max_stale = CONFIG.get("hl_candles_max_stale_bars")
                    prev_min_stale = CONFIG.get("hl_candles_min_stale_ms")
                    CONFIG["hl_candles_max_stale_bars"] = 45
                    CONFIG["hl_candles_min_stale_ms"] = 0
                except Exception:
                    prev_src = None
                try:
                    weekly_emit = _three_screen_weekly_build_and_emit(coin=str(rep.get("coin") or coin), group_id=str(gid), emit=True)
                finally:
                    try:
                        if prev_src is None:
                            CONFIG.pop("hl_candles_source", None)
                        else:
                            CONFIG["hl_candles_source"] = prev_src
                        if prev_max_stale is None:
                            CONFIG.pop("hl_candles_max_stale_bars", None)
                        else:
                            CONFIG["hl_candles_max_stale_bars"] = prev_max_stale
                        if prev_min_stale is None:
                            CONFIG.pop("hl_candles_min_stale_ms", None)
                        else:
                            CONFIG["hl_candles_min_stale_ms"] = prev_min_stale
                    except Exception:
                        pass
        except Exception as e:
            weekly_emit = {"ok": False, "error": "weekly_build_failed", "detail": str(e)}
        return jsonify(
            _json_sanitize(
                {
                    "ok": bool(rep.get("ok")) and (weekly_emit is None or bool(weekly_emit.get("ok", True))),
                    "ts_ms": int(now_ms),
                    "coin": rep.get("coin"),
                    "group_id": str(gid),
                    "lookback_days": int(ld),
                    "timeout_sec": float(to),
                    "backfill": rep,
                    "weekly_emit": weekly_emit,
                }
            )
        )

    _three_screen_backfill_jobs_prune(int(now_ms))
    job_id = str(uuid.uuid4())
    with _THREE_SCREEN_BACKFILL_LOCK:
        running = sum(1 for j in _THREE_SCREEN_BACKFILL_JOBS.values() if isinstance(j, dict) and str(j.get("status") or "") == "running")
        if running >= 2:
            return jsonify(_json_sanitize({"ok": False, "ts_ms": int(now_ms), "error": "too_many_running_jobs", "running": int(running)}))
        _THREE_SCREEN_BACKFILL_JOBS[job_id] = {
            "job_id": str(job_id),
            "ok": None,
            "status": "queued",
            "ts_ms": int(now_ms),
            "updated_ts_ms": int(now_ms),
            "coin": str(_three_screen_pair_coin(coin) or coin),
            "group_id": str(gid),
            "lookback_days": int(ld),
            "timeout_sec": float(to),
            "backfill": None,
            "weekly_emit": None,
            "error": None,
        }

    th = threading.Thread(
        target=_three_screen_backfill_job_run,
        kwargs={"job_id": str(job_id), "coin": str(coin), "group_id": str(gid), "lookback_days": int(ld), "timeout_sec": float(to)},
        daemon=True,
    )
    th.start()
    return jsonify(_json_sanitize({"ok": True, "ts_ms": int(now_ms), "job_id": str(job_id), "status": "queued"}))


