@app.route("/signals/hyperliquid/breakout", methods=["POST"])
def signals_hyperliquid_breakout():
    data = request.get_json(force=True) or {}
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    out = _run_freqtrade_strategy_signal_hyperliquid(
        "user_data.strategies.breakoutStrategy",
        "BreakoutStrategy",
        coin,
        param_names=["donchian_window", "tolerance_atr_mult", "bottom_confirmation_threshold", "bottom_accel_thr"],
    )
    if not bool(out.get("ok")):
        return jsonify(out), 400

    emit = bool(data.get("emit", True))
    trigger = bool(data.get("trigger_decision", CONFIG.get("signals_auto_decision", False)))
    if out.get("side") not in ("long", "short"):
        return jsonify({"ok": True, "signal": None, "diagnostic": out})
    if not bool(out.get("bar_closed", False)):
        return jsonify({"ok": True, "signal": None, "diagnostic": out})

