@app.route("/execution/hyperliquid/market_open", methods=["POST"])
def hyperliquid_market_open():
    data = request.get_json(force=True) or {}
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    side = str(data.get("side", "long") or "long").lower()
    if side not in ("long", "short"):
        side = "long"
    notional = float(data.get("notional_usdc", 10.0))
    slippage = float(data.get("slippage", 0.02))
    px = data.get("px")
    px = (float(px) if px is not None else None)

    tag = str(data.get("tag") or "hyperliquid_market_open")

    leverage = data.get("leverage")
    leverage = (int(leverage) if leverage is not None else None)
    is_cross = data.get("is_cross")
    is_cross = (bool(is_cross) if is_cross is not None else bool(CONFIG.get("hl_default_is_cross", False)))

    leverage_eff = leverage
    if leverage_eff is None:
        try:
            leverage_eff = int(CONFIG.get("hl_default_leverage", 3) or 3)
        except Exception:
            leverage_eff = 3
    leverage_eff = _entry_hard_clip_leverage(leverage_eff)

    execute = bool(data.get("execute", False))

    ab_owner = None
    try:
        ab_owner = data.get("ab_owner")
        if ab_owner is not None:
            ab_owner = _ab_norm_owner(ab_owner)
    except Exception:
        ab_owner = None
    owner_kind = "strategy" if ab_owner is None else str(ab_owner)
    if owner_kind not in ("strategy", "quant", "carry", "three_screen"):
        owner_kind = "strategy"
    strategy_id = data.get("strategy_id")
    if strategy_id is None:
        strategy_id = data.get("strategy")
    strategy_id = (None if strategy_id is None else str(strategy_id).strip() or None)

    idem = _execute_idempotency_precheck(data)
    if idem is not None:
        return idem
    guard = _check_execute_guard(data)
    if guard is not None:
        return guard
    cap = _cap_guard_trade_execute_or_error(execute=execute, action="open", venue="hyperliquid", symbol=coin, notional_usdc=notional, owner=owner_kind)
    if cap is not None:
        return cap

    ignore_cooldown_raw = data.get("ignore_cooldown")
    ignore_cooldown = False
    if ignore_cooldown_raw is not None:
        ignore_cooldown = str(ignore_cooldown_raw).strip().lower() in ("1", "true", "yes", "y", "on")
    if execute:
        try:
            if owner_kind != "carry" and str(CONFIG.get("execution_venue") or "").lower().strip() != "hyperliquid":
                return jsonify({"ok": False, "error": "execution_venue_not_hyperliquid"}), 400
        except Exception:
            return jsonify({"ok": False, "error": "execution_venue_not_hyperliquid"}), 400
        if not bool(_live_trading_enabled_for_owner(owner_kind)):
            if str(owner_kind) == "quant":
                return jsonify({"ok": False, "error": "quant_live_trading_disabled"}), 403
            return jsonify({"ok": False, "error": "live_trading_disabled"}), 403
        if bool(CONFIG.get("dry_run", True)):
            return jsonify({"ok": False, "error": "dry_run_enabled"}), 400
        if not _hl_enabled_for_trading_for_owner(owner_kind):
            return jsonify({"ok": False, "error": "hyperliquid_trading_disabled", "ab_owner": str(owner_kind)}), 403
        if Info is None or Exchange is None or Account is None:
            return jsonify({"ok": False, "error": "hyperliquid_sdk_unavailable"}), 400

        try:
            iso_err = _book_isolation_enforce_exec_or_error(
                book_id=str(_ab_norm_owner(owner_kind)),
                venue="hyperliquid",
                execution_account_id=_execution_account_id_for_book(str(_ab_norm_owner(owner_kind)), venue="hyperliquid"),
                book_run_id=str(BOOK_RUN_ID),
                now_ms=int(_now_ms()),
                context={"src": "hyperliquid_market_open", "coin": str(coin), "side": str(side), "tag": str(tag)},
            )
        except Exception:
            iso_err = None
        if isinstance(iso_err, dict) and iso_err:
            return jsonify(iso_err), 409

    try:
        req_notional = float(notional)
    except Exception:
        req_notional = 0.0
    if (not math.isfinite(float(req_notional))) or float(req_notional) <= 0.0:
        return jsonify({"ok": False, "error": "invalid_notional", "requested_notional_usdc": req_notional}), 400
    lo, hi = _effective_entry_notional_bounds("hyperliquid")
    if lo is not None and float(req_notional) < float(lo) - 1e-12:
        if str(data.get("auto_bump_to_min") or "").strip().lower() in ("1", "true", "yes", "y", "on") or str(data.get("adjust_to_min") or "").strip().lower() in ("1", "true", "yes", "y", "on"):
            notional = float(lo)
            req_notional = float(lo)
        else:
            return jsonify({"ok": False, "error": "notional_too_small", "requested_notional_usdc": float(req_notional), "min_notional_usdc": float(lo)}), 400
    if hi is not None and float(req_notional) > float(hi) + 1e-12:
        return jsonify({"ok": False, "error": "notional_exceeds_max", "requested_notional_usdc": float(req_notional), "max_notional_usdc": float(hi)}), 400

    # 统一执行开仓 Gate（含宏观硬门控），避免 dry-run 绕过风控
    gate_meta = {
        "src": "api_market_open",
        "tag": str(tag),
        "reserve_gate": bool(execute),
        "ignore_pair_side_cooldown": bool(ignore_cooldown),
        "ignore_coin_side_cooldown": bool(ignore_cooldown),
        "requested_notional_usdc": float(req_notional),
        "strategy_id": (None if strategy_id is None else str(strategy_id)),
        "system_id": str(owner_kind),
        "ab_owner": str(owner_kind),
    }
    if bool(ignore_cooldown):
        gate_meta["entry_inflight_cooldown_sec"] = 0
    gate_out, _ = _order_gate_open(
        pair=f"{coin}-PERP",
        side=str(side),
        now_ms=_now_ms(),
        features={},
        meta=gate_meta,
    )
    if not bool(gate_out.get("ok", False)):
        return jsonify({"ok": False, "error": "risk_gate_reject", "reason": gate_out.get("reason"), "details": gate_out}), 403

    order_id = _gen_id("ord")
    ts = _now_ms()
    is_buy = (side == "long")
    mode = "dry-run" if (not execute) else "real"
    status = "accepted" if (not execute) else "submitted"

    exec_info: Dict[str, Any] = {
        "venue": "hyperliquid",
        "coin": coin,
        "side": side,
        "is_buy": bool(is_buy),
        "notional_usdc": float(req_notional),
        "slippage": float(slippage),
        "px": px,
        "execute": bool(execute),
        "leverage": int(leverage_eff),
        "is_cross": bool(is_cross),
    }

    try:
        mid = _hl_mid(coin)
        exec_info["mid"] = float(mid)
        exec_info["sz"] = float(_hl_size_from_notional_usdc(coin, float(req_notional)))
        if leverage is not None:
            exec_info["max_leverage"] = int(_hl_max_leverage(coin))
    except Exception as e:
        exec_info["preflight_error"] = str(e)

    if execute:
        try:
            exec_info["leverage_resp"] = _hl_ensure_leverage(coin=coin, leverage=int(leverage_eff), is_cross=bool(is_cross), owner=owner_kind)
            out = _hl_market_open(coin=coin, is_buy=is_buy, notional_usdc=float(req_notional), slippage=slippage, px=px, owner=owner_kind)
            exec_info["resp"] = out.get("resp")
            exec_info["oid"] = _hl_extract_oid(out.get("resp"))
            try:
                r0 = out.get("resp")
                if isinstance(r0, dict):
                    st = str(r0.get("status") or "").strip().lower()
                    if st in ("err", "error", "failed", "failure"):
                        status = "failed"
                        exec_info["error"] = r0.get("response") or r0.get("error") or "hyperliquid_error"
            except Exception:
                pass
            try:
                st0 = (((out.get("resp") or {}).get("response") or {}).get("data") or {}).get("statuses", [{}])[0]
                if "filled" in st0:
                    status = "filled"
                elif "resting" in st0:
                    status = "submitted"
                elif "error" in st0:
                    status = "failed"
                    exec_info["error"] = st0.get("error")
            except Exception:
                pass
        except Exception as e:
            status = "failed"
            exec_info["error"] = str(e)

    ORDERS[order_id] = {
        "id": order_id,
        "pair": f"{coin}-PERP",
        "side": side,
        "action": "open",
        "size": float(exec_info.get("sz") or 0.0),
        "mode": mode,
        "tag": str(tag),
        "ts": ts,
        "status": status,
        "p": 0.0,
        "pc": 0.0,
        "regime": None,
        "gate": (dict(gate_out) if isinstance(gate_out, dict) else {"ok": True}),
        "ab_owner": str(owner_kind),
        "book_id": str(_ab_norm_owner(owner_kind)),
        "book_run_id": str(BOOK_RUN_ID),
        "execution_account_id": _execution_account_id_for_book(str(_ab_norm_owner(owner_kind)), venue="hyperliquid"),
        "exchange": "hyperliquid",
        "exchange_oid": exec_info.get("oid"),
        "exec": exec_info,
    }
    try:
        _archive_order(ORDERS.get(order_id) or {})
    except Exception:
        pass

    try:
        TRACKER_STATE["order_ts"].append(ts)
    except Exception:
        pass

    ok0 = str(status).lower() in ("accepted", "submitted", "filled")
    resp = {"ok": bool(ok0), "order_id": order_id, "order": ORDERS[order_id]}
    if not bool(ok0):
        resp["error"] = (exec_info.get("error") or "order_failed")
    http_status = 200 if bool(ok0) else 502
    try:
        _execute_idempotency_finalize(data, resp, int(http_status))
    except Exception:
        pass
    return jsonify(resp), int(http_status)


@app.route("/execution/hyperliquid/spot/market_open", methods=["POST"])
def hyperliquid_spot_market_open():
    data = request.get_json(force=True) or {}
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    trade_side = str(data.get("trade_side") or data.get("side") or ("buy" if bool(data.get("is_buy")) else "buy"))
    try:
        notional = float(
            data.get("notional_usdc")
            or data.get("notional_usd")
            or data.get("notional_usdt")
            or data.get("notional")
            or 10.0
        )
    except Exception:
        notional = 10.0
    quote = str(data.get("quote") or "USDC")
    execute = bool(data.get("execute", False))
    tag = str(data.get("tag") or "hyperliquid_spot_market_open")

    ignore_cooldown_raw = data.get("ignore_cooldown")
    ignore_cooldown = False
    if ignore_cooldown_raw is not None:
        ignore_cooldown = str(ignore_cooldown_raw).strip().lower() in ("1", "true", "yes", "y", "on")

    skip_gate_raw = data.get("skip_gate")
    skip_gate = False
    if skip_gate_raw is not None:
        skip_gate = str(skip_gate_raw).strip().lower() in ("1", "true", "yes", "y", "on")

    idem = _execute_idempotency_precheck(data)
    if idem is not None:
        return idem
    guard = _check_execute_guard(data)
    if guard is not None:
        return guard

    cap = _cap_guard_trade_execute_or_error(execute=execute, action="open", venue="hyperliquid", symbol=coin, notional_usdc=notional, owner=data.get("ab_owner"))
    if cap is not None:
        return cap

    owner_kind = "strategy"
    try:
        ao = data.get("ab_owner")
        if ao is not None:
            owner_kind = str(_ab_norm_owner(ao) or owner_kind)
    except Exception:
        owner_kind = "strategy"
    if owner_kind not in ("strategy", "quant", "carry", "three_screen"):
        owner_kind = "strategy"

    if execute:
        try:
            if owner_kind != "carry" and str(CONFIG.get("execution_venue") or "").lower().strip() != "hyperliquid":
                return jsonify({"ok": False, "error": "execution_venue_not_hyperliquid"}), 400
        except Exception:
            return jsonify({"ok": False, "error": "execution_venue_not_hyperliquid"}), 400

    resp_any = hyperliquid_spot_market_open_internal(
        coin=str(coin),
        trade_side=str(trade_side),
        notional_usdc=float(notional),
        execute=bool(execute),
        tag=str(tag),
        quote=str(quote),
        strategy_id=(None if data.get("strategy_id") is None else str(data.get("strategy_id"))),
        ab_owner=(None if data.get("ab_owner") is None else str(data.get("ab_owner"))),
        skip_gate=bool(skip_gate),
        ignore_cooldown=bool(ignore_cooldown),
    )
    resp_obj, http_status = _unpack_jsonify_resp(resp_any)
    try:
        _execute_idempotency_finalize(data, (resp_obj if isinstance(resp_obj, dict) else {}), int(http_status))
    except Exception:
        pass
    return resp_any


@app.route("/execution/hyperliquid/spot/market_close", methods=["POST"])
def hyperliquid_spot_market_close():
    data = request.get_json(force=True) or {}
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    qty = data.get("qty")
    if qty is None:
        qty = data.get("quantity")
    try:
        qty_f = float(qty) if qty is not None else None
    except Exception:
        qty_f = None
    if qty_f is None or (not math.isfinite(float(qty_f))) or float(qty_f) <= 0.0:
        return jsonify({"ok": False, "error": "missing_qty"}), 400

    quote = str(data.get("quote") or "USDC")
    execute = bool(data.get("execute", False))
    tag = str(data.get("tag") or "hyperliquid_spot_market_close")

    idem = _execute_idempotency_precheck(data)
    if idem is not None:
        return idem
    guard = _check_execute_guard(data)
    if guard is not None:
        return guard

    cap = _cap_guard_trade_execute_or_error(execute=execute, action="close", venue="hyperliquid", symbol=coin, notional_usdc=None, owner=data.get("ab_owner"))
    if cap is not None:
        return cap

    owner_kind = "strategy"
    try:
        ao = data.get("ab_owner")
        if ao is not None:
            owner_kind = str(_ab_norm_owner(ao) or owner_kind)
    except Exception:
        owner_kind = "strategy"
    if owner_kind not in ("strategy", "quant", "carry", "three_screen"):
        owner_kind = "strategy"

    if execute:
        try:
            if owner_kind != "carry" and str(CONFIG.get("execution_venue") or "").lower().strip() != "hyperliquid":
                return jsonify({"ok": False, "error": "execution_venue_not_hyperliquid"}), 400
        except Exception:
            return jsonify({"ok": False, "error": "execution_venue_not_hyperliquid"}), 400

    resp_any = hyperliquid_spot_market_close_internal(
        coin=str(coin),
        qty=float(qty_f),
        execute=bool(execute),
        tag=str(tag),
        quote=str(quote),
        strategy_id=(None if data.get("strategy_id") is None else str(data.get("strategy_id"))),
        ab_owner=(None if data.get("ab_owner") is None else str(data.get("ab_owner"))),
    )
    resp_obj, http_status = _unpack_jsonify_resp(resp_any)
    try:
        _execute_idempotency_finalize(data, (resp_obj if isinstance(resp_obj, dict) else {}), int(http_status))
    except Exception:
        pass
    return resp_any


@app.route("/execution/aster/market_open", methods=["POST"])
def aster_market_open():
    data = request.get_json(force=True) or {}
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    side = str(data.get("side", "long") or "long").lower()
    if side not in ("long", "short"):
        side = "long"
    try:
        notional = float(
            data.get("notional_usdt")
            or data.get("notional_usdc")
            or data.get("notional")
            or CONFIG.get("entry_fixed_notional_usdc", 200.0)
            or 200.0
        )
    except Exception:
        notional = float(CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0)

    req_notional = float(notional)
    if (not math.isfinite(float(req_notional))) or float(req_notional) <= 0.0:
        return jsonify({"ok": False, "error": "invalid_notional", "requested_notional_usdc": req_notional}), 400
    lo, hi = _effective_entry_notional_bounds("aster")
    if lo is not None and float(req_notional) < float(lo) - 1e-12:
        if str(data.get("auto_bump_to_min") or "").strip().lower() in ("1", "true", "yes", "y", "on") or str(data.get("adjust_to_min") or "").strip().lower() in ("1", "true", "yes", "y", "on"):
            notional = float(lo)
        else:
            return jsonify({"ok": False, "error": "notional_too_small", "requested_notional_usdc": float(req_notional), "min_notional_usdc": float(lo)}), 400
    if hi is not None and float(req_notional) > float(hi) + 1e-12:
        return jsonify({"ok": False, "error": "notional_exceeds_max", "requested_notional_usdc": float(req_notional), "max_notional_usdc": float(hi)}), 400
    leverage = data.get("leverage", 10)
    try:
        leverage = int(leverage) if leverage is not None else 10
    except Exception:
        leverage = 10
    leverage = _entry_hard_clip_leverage(leverage)
    execute = bool(data.get("execute", False))
    tag = str(data.get("tag") or "aster_market_open")

    ab_owner = None
    owner_contrib: Dict[str, float] = {"strategy": 0.0, "quant": 0.0, "carry": 0.0, "three_screen": 0.0}
    try:
        ab_owner = data.get("ab_owner")
        if ab_owner is not None:
            ab_owner = _ab_norm_owner(ab_owner)
    except Exception:
        ab_owner = None
    try:
        oc_raw = data.get("owner_contrib")
        if isinstance(oc_raw, dict) and oc_raw:
            for k in ("strategy", "quant", "carry", "three_screen"):
                try:
                    v = oc_raw.get(k)
                    if v is not None and math.isfinite(float(v)):
                        owner_contrib[k] = float(v)
                except Exception:
                    continue
    except Exception:
        pass
    if float(owner_contrib.get("strategy", 0.0) + owner_contrib.get("quant", 0.0) + owner_contrib.get("carry", 0.0) + owner_contrib.get("three_screen", 0.0)) <= 0.0 and ab_owner is not None:
        owner_contrib = {"strategy": 0.0, "quant": 0.0, "carry": 0.0, "three_screen": 0.0}
        owner_contrib[str(ab_owner)] = 1.0

    sid_in = data.get("strategy_id")
    if sid_in is None:
        sid_in = data.get("strategy")
    sys_in = _system_from_strategy_id(sid_in)
    owner_kind = _ab_infer_owner(ab_owner, sys_in, sid_in, tag=tag)
    if float(owner_contrib.get("strategy", 0.0) + owner_contrib.get("quant", 0.0) + owner_contrib.get("carry", 0.0) + owner_contrib.get("three_screen", 0.0)) <= 0.0:
        owner_contrib = {"strategy": 0.0, "quant": 0.0, "carry": 0.0, "three_screen": 0.0}
        owner_contrib[str(owner_kind)] = 1.0
    ab_owner_eff = (str(ab_owner) if ab_owner is not None else str(owner_kind))

    if ab_owner_eff == "carry" or str(sys_in) == "carry":
        resp = {"ok": False, "error": "carry_trade_venue_hl_only", "got": "aster"}
        try:
            _system_monitor_route_inconsistency_record(data=(data or {}), resp=dict(resp), http_status=400)
        except Exception:
            pass
        try:
            st = _system_monitor_route_inconsistency_state_get()
            st["last_scan_ms"] = 0
        except Exception:
            pass
        try:
            _system_monitor_route_inconsistency_process(int(_now_ms()))
        except Exception:
            pass
        return jsonify(resp), 400

    confirm_execute_raw = data.get("confirm_execute")
    confirm_execute = False
    if confirm_execute_raw is not None:
        confirm_execute = str(confirm_execute_raw).strip().lower() in ("1", "true", "yes", "y", "on")

    adjust_to_min_raw = data.get("adjust_to_min")

    auto_bump_raw = data.get("auto_bump_to_min")
    auto_bump_to_min = False
    if auto_bump_raw is not None:
        auto_bump_to_min = str(auto_bump_raw).strip().lower() in ("1", "true", "yes", "y", "on")
    elif adjust_to_min_raw is not None:
        auto_bump_to_min = str(adjust_to_min_raw).strip().lower() in ("1", "true", "yes", "y", "on")

    confirm_bump_raw = data.get("confirm_bump")
    confirm_bump = False
    if confirm_bump_raw is not None:
        confirm_bump = str(confirm_bump_raw).strip().lower() in ("1", "true", "yes", "y", "on")

    max_bump_ratio = data.get("max_bump_ratio")
    try:
        max_bump_ratio = (float(max_bump_ratio) if max_bump_ratio is not None else None)
    except Exception:
        max_bump_ratio = None
    if max_bump_ratio is not None and (not math.isfinite(float(max_bump_ratio)) or float(max_bump_ratio) <= 0):
        max_bump_ratio = None

    max_eff = data.get("max_effective_notional_usdc")
    try:
        max_eff = (float(max_eff) if max_eff is not None else None)
    except Exception:
        max_eff = None
    if max_eff is not None and (not math.isfinite(float(max_eff)) or float(max_eff) <= 0):
        max_eff = None
    ignore_cooldown_raw = data.get("ignore_cooldown")
    ignore_cooldown = False
    if ignore_cooldown_raw is not None:
        ignore_cooldown = str(ignore_cooldown_raw).strip().lower() in ("1", "true", "yes", "y", "on")

    ignore_pcf_raw = data.get("ignore_post_close_freeze")
    ignore_post_close_freeze = False
    if ignore_pcf_raw is not None:
        ignore_post_close_freeze = str(ignore_pcf_raw).strip().lower() in ("1", "true", "yes", "y", "on")

    if execute:
        if not bool(confirm_execute):
            return jsonify({"ok": False, "error": "confirm_execute_required"}), 400
        try:
            if str(CONFIG.get("execution_venue") or "").lower().strip() != "aster":
                return jsonify({"ok": False, "error": "execution_venue_not_aster"}), 400
        except Exception:
            return jsonify({"ok": False, "error": "execution_venue_not_aster"}), 400
        try:
            ip = str(request.remote_addr or "").strip()
        except Exception:
            ip = ""
        if ip not in ("127.0.0.1", "::1") and (not bool(CONFIG.get("live_execute_allow_remote", False))):
            return jsonify({"ok": False, "error": "live_execute_remote_forbidden"}), 403
        if not bool(_live_trading_enabled_for_owner(ab_owner_eff)):
            if ab_owner_eff == "quant":
                return jsonify({"ok": False, "error": "quant_live_trading_disabled"}), 403
            return jsonify({"ok": False, "error": "live_trading_disabled"}), 403
        if bool(CONFIG.get("dry_run", True)):
            return jsonify({"ok": False, "error": "dry_run_enabled"}), 400
        if not _aster_enabled_for_trading_for_owner(ab_owner_eff):
            return jsonify({"ok": False, "error": "aster_trading_disabled"}), 403
        try:
            iso_err = _book_isolation_enforce_exec_or_error(
                book_id=str(_ab_norm_owner(ab_owner_eff)),
                venue="aster",
                execution_account_id=_execution_account_id_for_book(str(_ab_norm_owner(ab_owner_eff)), venue="aster"),
                book_run_id=str(BOOK_RUN_ID),
                now_ms=int(_now_ms()),
                context={"src": "aster_market_open", "coin": str(coin), "side": str(side), "strategy_id": (None if sid_in is None else str(sid_in)), "ab_owner": str(ab_owner_eff)},
            )
        except Exception:
            iso_err = None
        if isinstance(iso_err, dict) and iso_err:
            return jsonify({"ok": False, "error": "book_isolation_violation", "details": iso_err}), 409

    gate_out, _ = _order_gate_open(
        pair=f"{coin}-PERP",
        side=str(side),
        now_ms=_now_ms(),
        features={},
        meta={
            "src": "api_market_open",
            "reserve_gate": bool(execute),
            "ignore_pair_side_cooldown": bool(ignore_cooldown),
            "ignore_coin_side_cooldown": bool(ignore_cooldown),
            "ignore_post_close_freeze": bool(ignore_post_close_freeze),
            "entry_inflight_cooldown_sec": (0 if bool(ignore_cooldown) else None),
            "requested_notional_usdc": float(req_notional),
            "requested_notional_usdt": float(req_notional),
            "ab_owner": str(ab_owner_eff),
            "system_id": str(ab_owner_eff),
        },
    )
    if not bool(gate_out.get("ok", False)):
        return jsonify({"ok": False, "error": "risk_gate_reject", "reason": gate_out.get("reason"), "details": gate_out}), 403

    order_id = _gen_id("ord")
    trace_id = _gen_id("sig")
    ts = _now_ms()
    is_buy = (side == "long")
    mode = "dry-run" if (not execute) else "real"
    status = "accepted" if (not execute) else "submitted"

    exec_info: Dict[str, Any] = {
        "venue": "aster",
        "coin": coin,
        "side": side,
        "is_buy": bool(is_buy),
        "notional_usdc": float(notional),
        "notional_usdt": float(notional),
        "requested_notional_usdc": float(req_notional),
        "requested_notional_usdt": float(req_notional),
        "execute": bool(execute),
        "leverage": leverage,
        "runtime_config": _runtime_config_subset(CONFIG),
        "adjust_to_min": (None if adjust_to_min_raw is None else bool(auto_bump_to_min)),
        "auto_bump_to_min": bool(auto_bump_to_min),
        "confirm_bump": bool(confirm_bump),
        "max_bump_ratio": max_bump_ratio,
        "max_effective_notional_usdc": max_eff,
        "ab_owner": str(ab_owner_eff),
        "owner_contrib": dict(owner_contrib),
    }

    try:
        pf = _aster_preflight_notional(coin=str(coin), notional_usd=float(notional))
        exec_info["mid"] = float(pf.get("mid") or 0.0)
        for k in (
            "symbol",
            "min_qty",
            "min_notional",
            "step_size",
            "raw_qty",
            "required_qty",
            "required_notional_usdc",
            "required_notional_usdt",
            "selected_qty",
            "selected_notional_usdc",
            "selected_notional_usdt",
            "floor_qty",
            "floor_notional_usdc",
            "floor_notional_usdt",
            "effective_notional_usdc",
            "effective_notional_usdt",
            "will_bump",
            "bump_ratio",
            "max_qty",
            "qty_capped",
            "qty_cap_reason",
            "effective_frac",
        ):
            if k in pf:
                exec_info[k] = pf.get(k)

        will_bump = bool(exec_info.get("will_bump", False))
        if will_bump:
            if not bool(auto_bump_to_min):
                need_usd = float(exec_info.get("required_notional_usdc") or 0.0)
                raise RuntimeError(f"notional_too_small:need_usd>={need_usd:.2f}")
            if bool(execute) and (not bool(confirm_bump)):
                raise RuntimeError("bump_confirmation_required")
            if max_bump_ratio is not None:
                br = exec_info.get("bump_ratio")
                try:
                    br_f = (float(br) if br is not None else None)
                except Exception:
                    br_f = None
                if br_f is not None and math.isfinite(float(br_f)) and float(br_f) > float(max_bump_ratio):
                    raise RuntimeError("bump_ratio_exceeds_max")
            if max_eff is not None:
                eff = exec_info.get("effective_notional_usdc")
                try:
                    eff_f = (float(eff) if eff is not None else 0.0)
                except Exception:
                    eff_f = 0.0
                if math.isfinite(float(eff_f)) and float(eff_f) > float(max_eff):
                    raise RuntimeError("effective_notional_exceeds_max")

        exec_info["qty"] = float(exec_info.get("selected_qty") or 0.0)
        try:
            exec_info["effective_notional_usdc"] = float(exec_info.get("selected_notional_usdc") or exec_info.get("effective_notional_usdc") or 0.0)
        except Exception:
            pass
        try:
            exec_info["effective_notional_usdt"] = float(exec_info.get("effective_notional_usdc") or 0.0)
        except Exception:
            pass

        _, max_cfg = _effective_entry_notional_bounds("aster")
        if max_cfg is None:
            try:
                max_cfg = float(CONFIG.get("aster_max_notional_usdc", 500.0) or 500.0)
            except Exception:
                max_cfg = 500.0
        if math.isfinite(float(max_cfg)) and float(max_cfg) > 0.0:
            try:
                eff0 = float(exec_info.get("effective_notional_usdc") or 0.0)
            except Exception:
                eff0 = 0.0
            if math.isfinite(float(eff0)) and float(eff0) > float(max_cfg) + 1e-12:
                return jsonify({
                    "ok": False,
                    "error": "notional_exceeds_max",
                    "effective_notional_usdc": float(eff0),
                    "requested_notional_usdc": float(req_notional),
                    "max_notional_usdc": float(max_cfg),
                }), 400
    except Exception as e:
        exec_info["preflight_error"] = str(e)

    if execute and exec_info.get("preflight_error") is None:
        try:
            if leverage is not None:
                exec_info["leverage_resp"] = _aster_update_leverage(coin=coin, leverage=int(leverage), owner=ab_owner_eff)
            out = _aster_market_order_qty(coin=coin, side=side, qty=float(exec_info.get("qty") or 0.0), reduce_only=False, owner=ab_owner_eff)
            exec_info["resp"] = out.get("resp")
            try:
                exec_info["oid"] = (out.get("resp") or {}).get("orderId")
            except Exception:
                exec_info["oid"] = None
            try:
                st = str((out.get("resp") or {}).get("status") or "")
                if st.upper() == "FILLED":
                    status = "filled"
                    try:
                        sym0 = str((out.get("resp") or {}).get("symbol") or _aster_symbol_from_coin(coin) or "").strip().upper() or None
                    except Exception:
                        sym0 = None
                    try:
                        oid0 = exec_info.get("oid")
                    except Exception:
                        oid0 = None
                    try:
                        if sym0 and oid0 is not None:
                            q0 = _aster_order_query(symbol=str(sym0), order_id=oid0, owner=ab_owner_eff)
                            if isinstance(q0, dict) and q0:
                                try:
                                    stq = str(q0.get("status") or "").upper().strip() or None
                                except Exception:
                                    stq = None
                                exec_info["order_query"] = {
                                    "status": stq,
                                    "executedQty": q0.get("executedQty"),
                                    "avgPrice": q0.get("avgPrice"),
                                    "updateTime": q0.get("updateTime"),
                                }
                                if stq in ("NEW", "PARTIALLY_FILLED"):
                                    status = "submitted"
                                elif stq in ("CANCELED", "CANCELLED"):
                                    status = "canceled"
                                elif stq in ("REJECTED", "EXPIRED"):
                                    status = "failed"
                    except Exception as e:
                        exec_info["order_query_error"] = str(e)
                elif st.upper() in ("NEW", "PARTIALLY_FILLED"):
                    status = "submitted"
                elif st.upper() in ("REJECTED", "EXPIRED"):
                    status = "failed"
            except Exception:
                pass
        except Exception as e:
            status = "failed"
            exec_info["error"] = str(e)
    elif execute and exec_info.get("preflight_error") is not None:
        status = "failed"
        exec_info["error"] = "preflight_failed:" + str(exec_info.get("preflight_error"))

    try:
        if bool(execute) and str(status).lower() in ("submitted", "filled") and exec_info.get("preflight_error") is None:
            try:
                system_id_open = str(ab_owner_eff)
            except Exception:
                system_id_open = "strategy"
            op = _tracker_open_positions_get(system_id_open)
            pair = f"{coin}-PERP"
            entry_ts = int(ts)
            exit_owner = _exit_owner_choose(pair=str(pair), side=str(side), entry_ts=int(entry_ts), seed_extra=str(order_id))
            op[pair] = {
                "pair": str(pair),
                "venue": "aster",
                "ts": int(entry_ts),
                "entry_ts": int(entry_ts),
                "last_sync_ts": int(entry_ts),
                "order_id": str(order_id),
                "event_id": str(trace_id),
                "system_id": str(system_id_open),
                "side": str(side),
                "notional_usdc": float(exec_info.get("effective_notional_usdc") or float(notional)),
                "requested_notional_usdc": float(req_notional),
                "base_qty": float(exec_info.get("qty") or 0.0),
                "mode": str(mode),
                "simulated": (not bool(execute)),
                "ab_owner": str(ab_owner_eff),
                "owner_contrib": dict(owner_contrib),
                "strategy_id": None,
                "strategy_version": "1.0.0",
                "group_id": "default",
                "feature_set_id": "",
                "exit_owner": str(exit_owner),
            }
    except Exception:
        pass

    ORDERS[order_id] = {
        "id": order_id,
        "pair": f"{coin}-PERP",
        "side": side,
        "action": "open",
        "size": float(exec_info.get("qty") or 0.0),
        "mode": mode,
        "tag": str(tag),
        "ts": ts,
        "status": status,
        "p": 0.0,
        "pc": 0.0,
        "regime": None,
        "system_id": str(ab_owner_eff),
        "ab_owner": str(ab_owner_eff),
        "book_id": str(_ab_norm_owner(ab_owner_eff)),
        "book_run_id": str(BOOK_RUN_ID),
        "execution_account_id": _execution_account_id_for_book(str(_ab_norm_owner(ab_owner_eff)), venue="aster"),
        "owner_contrib": dict(owner_contrib),
        "gate": (dict(gate_out) if isinstance(gate_out, dict) else {"ok": True}),
        "exchange": "aster",
        "exchange_oid": exec_info.get("oid"),
        "exec": exec_info,
        "event_id": str(trace_id),
        "base_event_id": str(trace_id),
    }
    try:
        _archive_order(ORDERS.get(order_id) or {})
    except Exception:
        pass

    try:
        TRACKER_STATE["order_ts"].append(ts)
    except Exception:
        pass

    try:
        _ensure_trace_event_for_order(str(trace_id), order=ORDERS.get(order_id) or {}, strategy_id=None)
    except Exception:
        pass
    try:
        _emit_order_submit_events(ORDERS.get(order_id) or {}, str(trace_id))
    except Exception:
        pass
    try:
        _on_signal_ingest(str(trace_id))
    except Exception:
        pass

    return jsonify({"ok": True, "order_id": order_id, "order": ORDERS[order_id]})


@app.route("/execution/aster/preflight", methods=["POST"])
def aster_preflight():
    data = request.get_json(force=True) or {}
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    notional = float(data.get("notional_usdt", data.get("notional_usdc", data.get("notional_usd", 10.0))) or 10.0)
    try:
        out = _aster_preflight_notional(coin=str(coin), notional_usd=float(notional))
    except Exception as e:
        out = {
            "ok": False,
            "error": str(e),
            "coin": str(coin),
            "requested_notional_usdc": float(notional),
            "base_url": str(_aster_base_url()),
        }
    try:
        min_cfg = float(CONFIG.get("aster_min_notional_usdc", 10.0) or 10.0)
    except Exception:
        min_cfg = 10.0
    try:
        max_cfg = float(CONFIG.get("aster_max_notional_usdc", 500.0) or 500.0)
    except Exception:
        max_cfg = 500.0
    if math.isfinite(float(max_cfg)) and float(max_cfg) > 0.0 and math.isfinite(float(min_cfg)) and float(min_cfg) > float(max_cfg):
        min_cfg = float(max_cfg)
    notional_final = float(notional)
    cfg_err = None
    if math.isfinite(float(min_cfg)) and float(min_cfg) > 0.0 and float(notional_final) < float(min_cfg) - 1e-12:
        if bool(CONFIG.get("aster_adjust_to_min", False)):
            notional_final = float(min_cfg)
        else:
            cfg_err = "notional_too_small"
    if cfg_err is None and math.isfinite(float(max_cfg)) and float(max_cfg) > 0.0 and float(notional_final) > float(max_cfg) + 1e-12:
        cfg_err = "notional_exceeds_max"
    out["cfg_min_notional_usdc"] = float(min_cfg)
    out["cfg_max_notional_usdc"] = float(max_cfg)
    out["cfg_adjust_to_min"] = bool(CONFIG.get("aster_adjust_to_min", False))
    out["cfg_notional_final_usdc"] = float(notional_final)
    if cfg_err is not None:
        out["cfg_error"] = str(cfg_err)
    if "ok" not in out:
        out["ok"] = True
    return jsonify(_json_sanitize(out))


@app.route("/three_screen/live/smoke_order", methods=["POST"])
def three_screen_live_smoke_order():
    if not _is_local_request():
        return jsonify({"ok": False, "error": "forbidden", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    if not bool(data.get("confirm_live", False)):
        return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms())}), 400
    guard = _check_execute_guard(data)
    if guard is not None:
        return guard

    now_ms = int(_now_ms())
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    gid = str(data.get("group_id") or CONFIG.get("three_screen_group_id_default", "ThreeScreen.v0") or "ThreeScreen.v0")
    venue = str(CONFIG.get("execution_venue", "aster") or "aster").strip().lower()
    if venue not in ("aster", "hyperliquid", "stub"):
        venue = "aster"

    try:
        notional = float(data.get("notional_usdc") or data.get("notional_usdt") or data.get("size") or 80.0)
    except Exception:
        notional = 80.0
    notional = float(max(1.0, notional))

    force = bool(data.get("force", True))
    auto_close = bool(data.get("auto_close", True))

    side = str(data.get("side") or "").strip().lower()
    if side not in ("long", "short"):
        w_evt = _three_screen_pick_latest_weekly_ok_event(coin=str(coin), group_id=str(gid), require_bar_closed=True, use_cache=False)
        wf = (w_evt.get("features") if isinstance(w_evt, dict) else None)
        if not isinstance(wf, dict):
            wf = (w_evt.get("strategy_features") if isinstance(w_evt, dict) else None)
        try:
            side = str((wf or {}).get("weekly_trend_dir") or "").strip().lower()
        except Exception:
            side = ""
    if side not in ("long", "short"):
        return jsonify({"ok": False, "error": "no_weekly_direction", "ts": int(now_ms), "coin": str(coin), "group_id": str(gid)}), 400

    rows_info = _three_screen_5m_last_closed_rows(int(now_ms), f"{coin}-PERP", lookback=int(CONFIG.get("three_screen_5m_lookback_bars", 120) or 120))
    if not bool(rows_info.get("ok")) or not isinstance(rows_info.get("rows"), list):
        return jsonify({"ok": False, "error": "insufficient_5m_rows", "ts": int(now_ms), "coin": str(coin), "group_id": str(gid), "details": rows_info}), 400
    bar_open_ms = int(rows_info.get("bar_open_ms") or 0)
    bar_close_ms = int(rows_info.get("bar_close_ms") or 0)
    if bar_open_ms <= 0 or bar_close_ms <= 0 or bar_close_ms <= bar_open_ms:
        return jsonify({"ok": False, "error": "invalid_bar_time", "ts": int(now_ms), "coin": str(coin), "group_id": str(gid)}), 400

    rows0 = rows_info.get("rows") or []
    last_ohlcv = (rows0[-1] if isinstance(rows0, list) and rows0 else None)
    ohlc = {"open": 0.0, "high": 0.0, "low": 0.0, "close": 0.0}
    if isinstance(last_ohlcv, (list, tuple)) and len(last_ohlcv) >= 5:
        try:
            ohlc["open"] = float(last_ohlcv[1])
        except Exception:
            ohlc["open"] = 0.0
        try:
            ohlc["high"] = float(last_ohlcv[2])
        except Exception:
            ohlc["high"] = 0.0
        try:
            ohlc["low"] = float(last_ohlcv[3])
        except Exception:
            ohlc["low"] = 0.0
        try:
            ohlc["close"] = float(last_ohlcv[4])
        except Exception:
            ohlc["close"] = 0.0

    gate = _carry_5m_signal_gate(rows0, str(side))
    tag_l = ""
    try:
        tag_l = str((gate or {}).get("tag") or "").strip().lower()
    except Exception:
        tag_l = ""
    candidate_ok = bool(isinstance(gate, dict) and bool(gate.get("ok")) and tag_l and ("insufficient" not in tag_l) and tag_l != "unknown_side")
    if (not bool(candidate_ok)) and (not bool(force)):
        return jsonify({"ok": True, "ts": int(now_ms), "coin": str(coin), "group_id": str(gid), "side": str(side), "skipped": True, "reason": "no_candidate", "gate": gate}), 200
    if not bool(candidate_ok):
        gate = {"ok": True, "tag": "force_smoke", "mode": "force", "touch_ok": True, "touch_status": "forced"}
        candidate_ok = True
        tag_l = "force_smoke"

    conf = 0.62
    if "deep" in tag_l or "confirm_bos" in tag_l:
        conf = 0.80
    elif "mild" in tag_l or "confirm_ema_turn" in tag_l:
        conf = 0.68
    if str(tag_l) == "force_smoke":
        conf = 0.90

    expected_book = _three_screen_phase_expected_book()
    feats: Dict[str, Any] = {
        "weekly_trend_dir": str(side),
        "weekly_trend_strength": 1.0 if side == "long" else -1.0,
        "weekly_strength_threshold": float(CONFIG.get("three_screen_weekly_strength_threshold", 0.55) or 0.55),
        "weekly_ok": True,
        "daily_signal_dir": str(side),
        "align_with_weekly": True,
        "allowed_side": str(side),
        "setup_valid": True,
        "candidate_ok": True,
        "candidate": (gate if isinstance(gate, dict) else None),
        "reject_reason": "smoke_override",
        "pair_5m": f"{coin}-PERP",
        "open": float(ohlc.get("open") or 0.0),
        "high": float(ohlc.get("high") or 0.0),
        "low": float(ohlc.get("low") or 0.0),
        "close": float(ohlc.get("close") or 0.0),
        "entry_rule_family": "three_screen_smoke",
        "entry_model_family": "rule_only",
        "entry_decision": "take",
        "entry_threshold": 0.60,
        "p_enter_long": (float(conf) if side == "long" else 0.0),
        "p_enter_short": (float(conf) if side == "short" else 0.0),
    }

    signal_payload = _build_signal_schema_v1(
        venue=str(venue),
        pair=f"{coin}/USDC",
        side=str(side),
        action="open",
        timeframe="5m",
        bar_open_ms=int(bar_open_ms),
        bar_close_ms=int(bar_close_ms),
        bar_closed=True,
        strategy_id="ThreeScreen",
        strategy_version="1.0.0",
        group_id=str(gid),
        feature_set_id="ThreeScreen.5m",
        tag=str(tag_l),
        confidence=float(conf),
        features=_align_features("ThreeScreen.5m", dict(feats)),
    )
    signal_payload["ab_owner"] = str(expected_book)
    signal_payload["book_id"] = str(expected_book)
    signal_payload["system_id"] = str(expected_book)
    signal_payload["book_run_id"] = _three_screen_default_book_run_id(bar_close_ms=bar_close_ms, group_id=gid)
    signal_payload["owner_contrib"] = {"strategy": 0.0, "quant": 0.0, "carry": 0.0, "three_screen": 1.0}

    ingested = _emit_signal_v1(signal_payload, True, {"source": "three_screen_live_smoke", "size": float(notional)})
    out = {"ok": True, "ts": int(now_ms), "coin": str(coin), "group_id": str(gid), "venue": str(venue), "notional_usdc": float(notional), "ingested": ingested}

    if bool(auto_close):
        try:
            resp = aster_market_close_internal(coin=str(coin), execute=True, tag="three_screen_smoke_auto_close", sz=None, exit_owner=str(expected_book), force=True, system_id=str(expected_book), ignore_post_close_freeze=True)
            if isinstance(resp, dict):
                out["auto_close"] = resp
            elif hasattr(resp, "get_json"):
                out["auto_close"] = resp.get_json(silent=True)
            else:
                out["auto_close"] = str(resp)
        except Exception as e:
            out["auto_close"] = {"ok": False, "error": str(e)}
    return jsonify(_json_sanitize(out))


@app.route("/execution/aster/market_close", methods=["POST"])
def aster_market_close():
    data = request.get_json(force=True) or {}
    raw_pair = str(data.get("pair") or "")
    coin = str(data.get("coin") or raw_pair or "BTC")
    coin = _hl_coin_from_pair(coin)
    sz = data.get("sz")
    sz = (float(sz) if sz is not None else None)
    action_type = "close" if sz is None else "reduce"
    if sz is not None:
        try:
            if float(sz) <= 0.0:
                action_type = "close"
        except Exception:
            pass
    exit_owner = data.get("exit_owner")
    exit_owner = (str(exit_owner) if exit_owner is not None else None)
    system_id_req = data.get("system_id")
    system_id_req = (str(system_id_req) if system_id_req is not None else None)
    force = bool(data.get("force", True))
    execute = bool(data.get("execute", False))
    confirm_execute_raw = data.get("confirm_execute")
    confirm_execute = False
    if confirm_execute_raw is not None:
        confirm_execute = str(confirm_execute_raw).strip().lower() in ("1", "true", "yes", "y", "on")
    tag = str(data.get("tag") or "aster_market_close")

    ignore_pcf_raw = data.get("ignore_post_close_freeze")
    ignore_post_close_freeze = False
    if ignore_pcf_raw is not None:
        ignore_post_close_freeze = str(ignore_pcf_raw).strip().lower() in ("1", "true", "yes", "y", "on")

    if execute:
        if not bool(confirm_execute):
            return jsonify({"ok": False, "error": "confirm_execute_required"}), 400
        try:
            if str(CONFIG.get("execution_venue") or "").lower().strip() != "aster":
                return jsonify({"ok": False, "error": "execution_venue_not_aster"}), 400
        except Exception:
            return jsonify({"ok": False, "error": "execution_venue_not_aster"}), 400
        try:
            ip = str(request.remote_addr or "").strip()
        except Exception:
            ip = ""
        if ip not in ("127.0.0.1", "::1") and (not bool(CONFIG.get("live_execute_allow_remote", False))):
            return jsonify({"ok": False, "error": "live_execute_remote_forbidden"}), 403
    return aster_market_close_internal(
        coin=str(coin),
        execute=bool(execute),
        tag=str(tag),
        sz=sz,
        exit_owner=exit_owner,
        force=bool(force),
        system_id=system_id_req,
        ignore_post_close_freeze=bool(ignore_post_close_freeze),
    )


@app.route("/execution/aster/spot/market_open", methods=["POST"])
def aster_spot_market_open():
    data = request.get_json(force=True) or {}
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    try:
        notional = float(
            data.get("notional_usd")
            or data.get("notional_usdt")
            or data.get("notional_usdc")
            or data.get("notional")
            or 10.0
        )
    except Exception:
        notional = 10.0
    execute = bool(data.get("execute", False))
    tag = str(data.get("tag") or "aster_spot_market_open")
    try:
        ab_owner = data.get("ab_owner")
        if ab_owner is None:
            ab_owner = data.get("book_id")
    except Exception:
        ab_owner = None
    ab_owner = (None if ab_owner is None else str(ab_owner).strip().lower() or None)
    strategy_id = (None if data.get("strategy_id") is None else str(data.get("strategy_id")).strip() or None)

    idem = _execute_idempotency_precheck(data)
    if idem is not None:
        return idem
    guard = _check_execute_guard(data)
    if guard is not None:
        return guard

    if execute:
        try:
            if str(CONFIG.get("execution_venue") or "").lower().strip() != "aster":
                return jsonify({"ok": False, "error": "execution_venue_not_aster"}), 400
        except Exception:
            return jsonify({"ok": False, "error": "execution_venue_not_aster"}), 400
        if not bool(CONFIG.get("live_trading_enabled", False)):
            return jsonify({"ok": False, "error": "live_trading_disabled"}), 403
        if bool(CONFIG.get("dry_run", True)):
            return jsonify({"ok": False, "error": "dry_run_enabled"}), 400
        if not _aster_enabled_for_trading():
            return jsonify({"ok": False, "error": "aster_trading_disabled"}), 403
        if not _aster_spot_enabled_for_trading():
            return jsonify({"ok": False, "error": "aster_spot_trading_disabled"}), 403

    _execute_idempotency_mark_inflight(data)

    try:
        resp = aster_spot_market_open_internal(coin=str(coin), notional_usd=float(notional), execute=bool(execute), tag=str(tag), strategy_id=strategy_id, ab_owner=ab_owner)
        http_status = 200 if bool(isinstance(resp, dict) and resp.get("ok")) else 400
    except Exception as e:
        resp = {"ok": False, "error": str(e)}
        http_status = 500

    try:
        _execute_idempotency_finalize(data, resp, int(http_status))
    except Exception:
        pass
    return jsonify(resp), int(http_status)


