@app.route("/execution/hyperliquid/set_leverage", methods=["POST"])
def hyperliquid_set_leverage():
    return jsonify({"ok": False, "error": "hyperliquid_disabled"}), 403
    data = request.get_json(force=True) or {}
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    leverage = data.get("leverage")
    if leverage is None:
        return jsonify({"ok": False, "error": "missing_leverage"}), 400
    lev = int(leverage)
    is_cross = data.get("is_cross")
    is_cross = (bool(is_cross) if is_cross is not None else bool(CONFIG.get("hl_default_is_cross", False)))

    execute = bool(data.get("execute", False))
    if execute:
        if not bool(CONFIG.get("live_trading_enabled", False)):
            return jsonify({"ok": False, "error": "live_trading_disabled"}), 403
        if bool(CONFIG.get("dry_run", True)):
            return jsonify({"ok": False, "error": "dry_run_enabled"}), 400
        if not _hl_enabled_for_trading():
            return jsonify({"ok": False, "error": "hyperliquid_trading_disabled"}), 403

    order_id = _gen_id("ord")
    ts = _now_ms()
    mode = "dry-run" if (not execute) else "real"
    status = "accepted" if (not execute) else "submitted"

    exec_info: Dict[str, Any] = {
        "venue": "hyperliquid",
        "coin": coin,
        "leverage": int(lev),
        "is_cross": bool(is_cross),
        "execute": bool(execute),
    }

    try:
        exec_info["max_leverage"] = int(_hl_max_leverage(coin))
    except Exception as e:
        exec_info["preflight_error"] = str(e)

    if execute:
        try:
            exec_info["resp"] = _hl_update_leverage(coin=coin, leverage=int(lev), is_cross=bool(is_cross))
        except Exception as e:
            status = "failed"
            exec_info["error"] = str(e)

    ORDERS[order_id] = {
        "id": order_id,
        "pair": f"{coin}-PERP",
        "side": "long",
        "size": 0.0,
        "mode": mode,
        "tag": "hyperliquid_set_leverage",
        "ts": ts,
        "status": status,
        "p": 0.0,
        "pc": 0.0,
        "regime": None,
        "exchange": "hyperliquid",
        "exchange_oid": None,
        "exec": exec_info,
    }
    try:
        _archive_order(ORDERS.get(order_id) or {})
    except Exception:
        pass

    try:
        TRACKER_STATE["order_ts"].append(ts)
    except Exception:
        pass

    return jsonify({"ok": True, "order_id": order_id, "order": ORDERS[order_id]})


def _tracker_clear_open_positions(raw_pair: str, coin: str) -> Dict[str, Any]:
    return _tracker_clear_open_positions_by_key(key="open_positions", raw_pair=str(raw_pair), coin=str(coin))


def _tracker_clear_quant_open_positions(raw_pair: str, coin: str) -> Dict[str, Any]:
    return _tracker_clear_open_positions_by_key(key="quant_open_positions", raw_pair=str(raw_pair), coin=str(coin))


def _tracker_clear_carry_open_positions(raw_pair: str, coin: str) -> Dict[str, Any]:
    return _tracker_clear_open_positions_by_key(key="carry_open_positions", raw_pair=str(raw_pair), coin=str(coin))


def _tracker_set_post_close_cooldown(raw_pair: str, coin: str, ts: int, system_id: Any = None) -> None:
    try:
        ph = float(CONFIG.get("coin_freeze_post_close_hours", 0) or 0)
    except Exception:
        ph = 0.0
    if ph <= 0.0:
        return
    try:
        pcd0 = TRACKER_STATE.get("post_close_cooldowns")
        if not isinstance(pcd0, dict):
            pcd0 = {}
            TRACKER_STATE["post_close_cooldowns"] = pcd0
        pcd = pcd0
        try:
            sid = str(system_id or "").strip().lower() or None
        except Exception:
            sid = None
        if sid:
            sub = pcd0.get(str(sid))
            if not isinstance(sub, dict):
                sub = {}
                pcd0[str(sid)] = sub
            pcd = sub

        try:
            pair_u = str(raw_pair or "").upper().strip()
        except Exception:
            pair_u = ""
        try:
            coin_u = str(coin or "").upper().strip()
        except Exception:
            coin_u = ""
        if raw_pair:
            pcd[str(raw_pair)] = int(ts)
        if pair_u:
            pcd[str(pair_u)] = int(ts)
        if coin:
            pcd[str(coin)] = int(ts)
        if coin_u:
            pcd[str(coin_u)] = int(ts)
            pcd[f"{coin_u}-PERP"] = int(ts)

        if coin_u:
            try:
                for k in _tracker_open_positions_all_keys():
                    try:
                        ku = str(k).upper().strip()
                    except Exception:
                        ku = ""
                    if ku.startswith(str(coin_u)):
                        pcd[str(k)] = int(ts)
                        if ku:
                            pcd[str(ku)] = int(ts)
            except Exception:
                pass
    except Exception:
        return


def _tracker_clear_open_positions_by_key(key: str, raw_pair: str, coin: str, set_post_close_cooldown: bool = True) -> Dict[str, Any]:
    op = TRACKER_STATE.get(str(key))
    if not isinstance(op, dict):
        return {"ok": False, "cleared": 0}
    candidates: List[str] = []
    if raw_pair:
        candidates.append(str(raw_pair))
    c = str(coin or "").upper()
    if c:
        candidates.extend([
            f"{c}/USDT",
            f"{c}-PERP",
            f"{c}-USDT-SWAP",
            f"{c}/USDC",
        ])
    cleared = 0
    for k in candidates:
        if k in op:
            try:
                del op[k]
                cleared += 1
            except Exception:
                pass
    if cleared > 0 and bool(set_post_close_cooldown):
        try:
            sid0 = None
            try:
                k0 = str(key)
            except Exception:
                k0 = ""
            if k0 == "quant_open_positions":
                sid0 = "quant"
            elif k0 == "carry_open_positions":
                sid0 = "carry"
            elif k0 == "open_positions":
                sid0 = "strategy"
            _tracker_set_post_close_cooldown(raw_pair=str(raw_pair), coin=str(coin), ts=int(_now_ms()), system_id=sid0)
        except Exception:
            pass
    return {"ok": True, "cleared": int(cleared), "candidates": candidates, "key": str(key)}


def _tracker_clear_open_positions_any(system_id: Any, raw_pair: str, coin: str, set_post_close_cooldown: bool = True) -> Dict[str, Any]:
    k = _tracker_open_positions_key(system_id)
    return _tracker_clear_open_positions_by_key(key=str(k), raw_pair=str(raw_pair), coin=str(coin), set_post_close_cooldown=bool(set_post_close_cooldown))


@app.route("/execution/hyperliquid/market_close", methods=["POST"])
def hyperliquid_market_close():
    data = request.get_json(force=True) or {}
    raw_pair = str(data.get("pair") or "")
    coin = str(data.get("coin") or raw_pair or "BTC")
    coin = _hl_coin_from_pair(coin)
    side = str(data.get("side", "long") or "long").lower()
    if side not in ("long", "short"):
        side = "long"
    slippage = float(data.get("slippage", 0.02))
    px = data.get("px")
    px = (float(px) if px is not None else None)
    sz = data.get("sz")
    sz = (float(sz) if sz is not None else None)
    action_type = "close" if sz is None else "reduce"
    if sz is not None:
        try:
            if float(sz) <= 0.0:
                action_type = "close"
        except Exception:
            pass
    exit_owner = data.get("exit_owner")
    exit_owner = (str(exit_owner) if exit_owner is not None else None)
    system_id_req = data.get("system_id")
    system_id_req = (str(system_id_req) if system_id_req is not None else None)
    force = bool(data.get("force", True))

    tag = str(data.get("tag") or "hyperliquid_market_close")

    idem = _execute_idempotency_precheck(data)
    if idem is not None:
        return idem
    guard = _check_execute_guard(data)
    if guard is not None:
        return guard

    pos_snapshot: Dict[str, Any] = {}
    system_id_close = None
    try:
        key0 = raw_pair if raw_pair else f"{str(coin)}-PERP"
        if system_id_req:
            system_id_close = system_id_req
        else:
            try:
                if str(exit_owner or "").strip().lower() == "carry_trade":
                    system_id_close = "carry"
            except Exception:
                system_id_close = None
        pos0 = _tracker_open_positions_get(system_id_close).get(str(key0))
        if pos0 is None:
            try:
                pos0 = _tracker_open_positions_get(None).get(str(key0))
            except Exception:
                pos0 = None
        if pos0 is None:
            try:
                pos0 = _tracker_open_positions_get("carry").get(str(key0))
            except Exception:
                pos0 = None
        if pos0 is None:
            try:
                pos0 = _tracker_open_positions_get("quant").get(str(key0))
            except Exception:
                pos0 = None
        if isinstance(pos0, dict):
            pos_snapshot = dict(pos0)
        if not system_id_close:
            try:
                system_id_close = (pos_snapshot or {}).get("system_id")
            except Exception:
                system_id_close = None
        if not system_id_close:
            try:
                system_id_close = _system_from_strategy_id((pos_snapshot or {}).get("strategy_id"))
            except Exception:
                system_id_close = None
    except Exception:
        pos_snapshot = {}

    if (not bool(force)) and exit_owner is not None:
        try:
            op = _tracker_open_positions_get(system_id_close)
            if isinstance(op, dict):
                key = raw_pair if raw_pair else f"{str(coin)}-PERP"
                pos = op.get(str(key))
                if isinstance(pos, dict):
                    cur_owner = str(pos.get("exit_owner") or "strategy")
                    if str(exit_owner) == "exit_feeder" and str(cur_owner) == "strategy" and (not bool(CONFIG.get("strategy_exit_enabled", False))):
                        cur_owner = "exit_feeder"
                    if str(cur_owner) != str(exit_owner):
                        return jsonify({"ok": True, "status": "ignored_not_owner", "pair": str(key), "owner": str(exit_owner), "cur_owner": str(cur_owner)}), 200
        except Exception:
            pass

    owner_kind = None
    try:
        ao_req = data.get("ab_owner")
        if ao_req is not None:
            owner_kind = _ab_norm_owner(ao_req)
    except Exception:
        owner_kind = None
    if owner_kind is None:
        try:
            ao_pos = str((pos_snapshot or {}).get("ab_owner") or "").strip().lower()
            if ao_pos in ("strategy", "quant", "carry", "three_screen"):
                owner_kind = ao_pos
        except Exception:
            owner_kind = None
    if owner_kind is None:
        owner_kind = "carry" if str(system_id_close or "").strip().lower() == "carry" else "strategy"
    if owner_kind not in ("strategy", "quant", "carry", "three_screen"):
        owner_kind = "strategy"

    execute = bool(data.get("execute", False))
    cap = _cap_guard_trade_execute_or_error(execute=execute, action="close", venue="hyperliquid", symbol=coin, notional_usdc=None, owner=owner_kind)
    if cap is not None:
        return cap
    if execute:
        try:
            if owner_kind != "carry" and str(CONFIG.get("execution_venue") or "").lower().strip() != "hyperliquid":
                return jsonify({"ok": False, "error": "execution_venue_not_hyperliquid"}), 400
        except Exception:
            return jsonify({"ok": False, "error": "execution_venue_not_hyperliquid"}), 400
        if not bool(CONFIG.get("live_trading_enabled", False)):
            return jsonify({"ok": False, "error": "live_trading_disabled"}), 403
        if bool(CONFIG.get("dry_run", True)):
            return jsonify({"ok": False, "error": "dry_run_enabled"}), 400
        if not _hl_enabled_for_trading_for_owner(owner_kind):
            return jsonify({"ok": False, "error": "hyperliquid_trading_disabled", "ab_owner": str(owner_kind)}), 403

        try:
            iso_err = _book_isolation_enforce_exec_or_error(
                book_id=str(_ab_norm_owner(owner_kind)),
                venue="hyperliquid",
                execution_account_id=_execution_account_id_for_book(str(_ab_norm_owner(owner_kind)), venue="hyperliquid"),
                book_run_id=str(BOOK_RUN_ID),
                now_ms=int(_now_ms()),
                context={"src": "hyperliquid_market_close", "coin": str(coin), "side": str(side), "tag": str(tag), "action": str(action_type)},
            )
        except Exception:
            iso_err = None
        if isinstance(iso_err, dict) and iso_err:
            return jsonify(iso_err), 409

    order_id = _gen_id("ord")
    trace_id = _gen_id("sig")
    ts = _now_ms()
    mode = "dry-run" if (not execute) else "real"
    status = "accepted" if (not execute) else "submitted"
    closed_final = False

    exec_info: Dict[str, Any] = {
        "venue": "hyperliquid",
        "coin": coin,
        "side": side,
        "slippage": float(slippage),
        "px": px,
        "sz": (float(sz) if sz is not None else None),
        "execute": bool(execute),
    }

    try:
        exec_info["open_orders"] = _hl_open_orders(coin=coin, owner=owner_kind)
        exec_info["user_state"] = _hl_user_state(owner=owner_kind)
    except Exception as e:
        exec_info["preflight_error"] = str(e)

    if execute:
        try:
            out = _hl_market_close(coin=coin, sz=sz, slippage=slippage, px=px, owner=owner_kind)
            exec_info["resp"] = out.get("resp")
            exec_info["oid"] = _hl_extract_oid(out.get("resp"))
            try:
                st0 = (((out.get("resp") or {}).get("response") or {}).get("data") or {}).get("statuses", [{}])[0]
                if "filled" in st0:
                    status = "filled"
                elif "resting" in st0:
                    status = "submitted"
                elif "error" in st0:
                    status = "failed"
                    exec_info["error"] = st0.get("error")
            except Exception:
                pass
        except Exception as e:
            status = "failed"
            exec_info["error"] = str(e)

    if (not execute) and status != "failed":
        try:
            _tracker_clear_open_positions_any(system_id=system_id_close, raw_pair=str(raw_pair), coin=str(coin))
        except Exception:
            pass
        try:
            closed_final = float(sz or 0.0) <= 0.0
        except Exception:
            closed_final = False

    if execute and status != "failed":
        try:
            exec_info["user_state_after"] = _hl_user_state(owner=owner_kind)
        except Exception as e:
            exec_info["user_state_after_error"] = str(e)

        try:
            closed = False
            us = exec_info.get("user_state_after")
            positions = ((us or {}).get("assetPositions") or []) if isinstance(us, dict) else []
            for ap in positions:
                if not isinstance(ap, dict):
                    continue
                pos = ap.get("position") or {}
                if not isinstance(pos, dict):
                    continue
                if str(pos.get("coin") or "").upper() != str(coin).upper():
                    continue
                try:
                    szi = float(pos.get("szi") or 0.0)
                except Exception:
                    szi = 0.0
                if abs(float(szi)) <= 1e-12:
                    closed = True
                else:
                    closed = False
                break
            if status == "filled":
                closed = True

            closed_final = bool(closed)

            if closed:
                _tracker_clear_open_positions_any(system_id=system_id_close, raw_pair=str(raw_pair), coin=str(coin))
        except Exception:
            pass

    ORDERS[order_id] = {
        "id": order_id,
        "system_id": (None if system_id_close is None else str(system_id_close)),
        "pair": f"{coin}-PERP",
        "side": side,
        "action": str(action_type),
        "size": float(sz or 0.0),
        "mode": mode,
        "tag": str(tag),
        "ts": ts,
        "status": status,
        "p": 0.0,
        "pc": 0.0,
        "regime": None,
        "exchange": "hyperliquid",
        "exchange_oid": exec_info.get("oid"),
        "exec": exec_info,
        "pos_snapshot": (dict(pos_snapshot) if isinstance(pos_snapshot, dict) and pos_snapshot else None),
        "event_id": str(trace_id),
        "base_event_id": str(trace_id),
    }
    try:
        _archive_order(ORDERS.get(order_id) or {})
    except Exception:
        pass

    try:
        TRACKER_STATE["order_ts"].append(ts)
    except Exception:
        pass

    try:
        exit_reason_raw = data.get("exit_reason")
        if exit_reason_raw is None:
            exit_reason_raw = data.get("reason")
        if exit_reason_raw is None:
            exit_reason_raw = data.get("exit_tag")
        if exit_reason_raw is None:
            exit_reason_raw = data.get("tag")
        exit_reason = (str(exit_reason_raw).strip() if exit_reason_raw is not None else "")
        dec = {"action": str(action_type), "reason": (exit_reason if exit_reason else "market_close")}
        _exit_record_gate_history(
            pair=str(raw_pair or f"{coin}-PERP"),
            pos=(pos_snapshot if isinstance(pos_snapshot, dict) else {}),
            dec=dec,
            now_ms=int(ts),
            owner=(str(exit_owner) if exit_owner is not None else "manual"),
            executed=(bool(execute) and str(status) != "failed"),
            shadow=(not bool(execute)),
            ok=(str(status) != "failed"),
            error=(exec_info.get("error") if isinstance(exec_info, dict) else None),
            order_id=str(order_id),
            exchange_oid=(exec_info.get("oid") if isinstance(exec_info, dict) else None),
            order_status=str(status),
            order_tag=str(ORDERS.get(order_id, {}).get("tag") or ""),
        )
    except Exception:
        pass

    try:
        if str(status) != "failed" and float(sz or 0.0) <= 0.0 and (bool(closed_final) or (not bool(execute))):
            exit_reason_raw = data.get("exit_reason")
            if exit_reason_raw is None:
                exit_reason_raw = data.get("reason")
            if exit_reason_raw is None:
                exit_reason_raw = data.get("exit_tag")
            if exit_reason_raw is None:
                exit_reason_raw = data.get("tag")
            exit_reason = (str(exit_reason_raw).strip() if exit_reason_raw is not None else "")
            _tracker_auto_exit_settle(
                pair=str(raw_pair or f"{coin}-PERP"),
                pos=(pos_snapshot if isinstance(pos_snapshot, dict) else {}),
                order_id=str(order_id),
                exit_reason=(exit_reason if exit_reason else "market_close"),
                exit_tag=str(ORDERS.get(order_id, {}).get("tag") or "market_close"),
            )
    except Exception:
        pass

    try:
        _ensure_trace_event_for_order(str(trace_id), order=ORDERS.get(order_id) or {}, strategy_id=None)
    except Exception:
        pass
    try:
        _emit_order_submit_events(ORDERS.get(order_id) or {}, str(trace_id))
    except Exception:
        pass
    try:
        _on_signal_ingest(str(trace_id))
    except Exception:
        pass

    ok0 = str(status).lower() in ("accepted", "submitted", "filled")
    resp = {"ok": bool(ok0), "order_id": order_id, "order": ORDERS[order_id]}
    if not bool(ok0):
        resp["error"] = (exec_info.get("error") if isinstance(exec_info, dict) else None) or "order_failed"
    http_status = 200 if bool(ok0) else 502
    try:
        _execute_idempotency_finalize(data, resp, int(http_status))
    except Exception:
        pass
    return jsonify(resp), int(http_status)


@app.route("/exit/feeder/tick", methods=["POST"])
def exit_feeder_tick():
    if not (_agent_write_auth_ok() or _agent_sandbox_task_auth_ok()):
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    execute = bool(data.get("execute", False))
    if execute and (not _agent_write_auth_ok()):
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    now_ms = _now_ms()
    try:
        if execute:
            if not bool(CONFIG.get("live_trading_enabled", False)):
                return jsonify({"ok": False, "error": "live_trading_disabled"}), 403
            if bool(CONFIG.get("dry_run", True)):
                return jsonify({"ok": False, "error": "dry_run_enabled"}), 400
            if str(CONFIG.get("execution_venue") or "").lower() == "hyperliquid":
                _hl_sync(update_orders=False)
    except Exception:
        pass
    try:
        _audit_emit_action(
            "exit.feeder.tick",
            _audit_base_payload(
                scope="execution",
                action=("exit_feeder.tick.execute" if bool(execute) else "exit_feeder.tick.sim"),
                trace_id=trace_id,
                extra={"execute": bool(execute)},
            ),
        )
    except Exception:
        pass
    out = _exit_pipeline_tick(now_ms=int(now_ms), execute=bool(execute))
    return jsonify(out)


def _sim_build_signal_payload(strategy_id: str, coin: str) -> Dict[str, Any]:
    sid = str(strategy_id or "").strip()
    c = _hl_coin_from_pair(str(coin or "BTC"))
    if sid == "Strategy005":
        out = _run_strategy005_signal_hyperliquid(c)
        if not bool(out.get("ok")):
            return {"ok": False, "error": out.get("error") or "signal_failed", "diagnostic": out}
        if out.get("side") not in ("long", "short") or not bool(out.get("bar_closed", False)):
            return {"ok": True, "signal": None, "diagnostic": out}

        meta = _get_strategy_meta(sid)
        strategy_version = str(meta.get("strategy_version") or "1.0.0")
        group_id = str(meta.get("group_id") or "trend_4h_mtf")
        feature_set_id = str(meta.get("feature_set_id") or "trend_4h_mtf_v1")
        features = _align_features(feature_set_id, out.get("features") or {})
        sig = _build_signal_schema_v1(
            venue="hyperliquid",
            pair=str(out.get("pair")),
            side=str(out.get("side")),
            action="open",
            timeframe=str(out.get("timeframe")),
            bar_open_ms=int(out.get("bar_open_ms") or out.get("ts") or 0),
            bar_close_ms=int(out.get("bar_close_ms") or 0),
            bar_closed=True,
            strategy_id=str(sid),
            strategy_version=strategy_version,
            group_id=group_id,
            feature_set_id=feature_set_id,
            tag=(None if out.get("tag") is None else str(out.get("tag"))),
            confidence=float(_signal_confidence(sid, group_id, out.get("tag"), features)),
            features=features,
        )
        return {"ok": True, "signal": sig, "diagnostic": out}

    strategy_map = {
        "MultiGroupStrategy": ("user_data.strategies.MultiGroupStrategy", "MultiGroupStrategy", "trend_4h_mtf", "trend_4h_mtf_v1", None),
        "BreakoutStrategy": (
            "user_data.strategies.breakoutStrategy",
            "BreakoutStrategy",
            "breakout_1h_confirmed",
            "breakout_1h_v1",
            ["donchian_window", "tolerance_atr_mult", "bottom_confirmation_threshold", "bottom_accel_thr"],
        ),
        "Bot2Strategy": (
            "user_data.strategies.AdaptiveVolatilityStrategy_forced",
            "Bot2Strategy",
            "trend_4h_mtf",
            "trend_4h_mtf_v1",
            [
                "anti_chase_max_dev",
                "anti_chase_max_rsi",
                "anti_chase_bb_percent",
                "anti_chase_adx_slope_min",
                "anti_chase_recent_pump_max",
                "buy_vol_threshold",
            ],
        ),
        "RegimeHybridStrategy": ("user_data.strategies.RegimeHybridStrategy", "RegimeHybridStrategy", "regime_hybrid", "regime_hybrid_v1", None),
    }
    if sid not in strategy_map:
        return {"ok": False, "error": "unsupported_strategy", "strategy_id": sid}

    module, cls, default_group, default_fs, params = strategy_map[sid]
    out = _run_freqtrade_strategy_signal_hyperliquid(str(module), str(cls), c, param_names=params)
    if not bool(out.get("ok")):
        return {"ok": False, "error": out.get("error") or "signal_failed", "diagnostic": out}
    if out.get("side") not in ("long", "short") or not bool(out.get("bar_closed", False)):
        return {"ok": True, "signal": None, "diagnostic": out}

    meta = _get_strategy_meta(sid)
    strategy_version = str(meta.get("strategy_version") or "1.0.0")
    group_id = str(meta.get("group_id") or default_group)
    feature_set_id = str(meta.get("feature_set_id") or default_fs)
    features = _build_features_fixed(
        feature_set_id,
        out.get("row") or {},
        prev_row=(out.get("prev_row") or None),
        params=(out.get("params") or None),
    )
    sig = _build_signal_schema_v1(
        venue="hyperliquid",
        pair=str(out.get("pair")),
        side=str(out.get("side")),
        action="open",
        timeframe=str(out.get("timeframe")),
        bar_open_ms=int(out.get("bar_open_ms") or out.get("ts") or 0),
        bar_close_ms=int(out.get("bar_close_ms") or 0),
        bar_closed=True,
        strategy_id=str(sid),
        strategy_version=strategy_version,
        group_id=group_id,
        feature_set_id=feature_set_id,
        tag=(None if out.get("tag") is None else str(out.get("tag"))),
        confidence=float(_signal_confidence(sid, group_id, out.get("tag"), features)),
        features=features,
    )
    return {"ok": True, "signal": sig, "diagnostic": out}


@app.route("/sim/pipeline/run", methods=["POST"])
def sim_pipeline_run():
    data = request.get_json(force=True) or {}
    now_ms = _now_ms()

    execute = bool(data.get("execute", False))
    if execute:
        if not bool(CONFIG.get("live_trading_enabled", False)):
            return jsonify({"ok": False, "error": "live_trading_disabled"}), 403
        if bool(CONFIG.get("dry_run", True)):
            return jsonify({"ok": False, "error": "dry_run_enabled"}), 400

    try:
        force_exit_l1 = bool(data.get("force_exit_l1_enabled", True))
    except Exception:
        force_exit_l1 = True

    pos_list = data.get("positions")
    if isinstance(pos_list, dict):
        pos_list = [pos_list]
    if pos_list is not None and not isinstance(pos_list, list):
        return jsonify({"ok": False, "error": "invalid_positions"}), 400

    try:
        notional_usdc = float(data.get("notional_usdc") or data.get("size") or 0.0)
    except Exception:
        notional_usdc = 0.0
    if notional_usdc <= 0.0:
        notional_usdc = float(CONFIG.get("arena_shadow_notional_u", 10.0) or 10.0)

    profit_pct = 0.02
    try:
        if data.get("profit_pct") is not None:
            profit_pct = float(data.get("profit_pct") or 0.0)
    except Exception:
        profit_pct = 0.02
    dd_target = 0.6
    try:
        if data.get("dd") is not None:
            dd_target = float(data.get("dd") or 0.0)
    except Exception:
        dd_target = 0.6
    dd_target = float(_clip(float(dd_target), 0.0, 0.95))

    exit_owner = str(data.get("exit_owner") or "exit_feeder")
    if exit_owner not in ("exit_feeder", "strategy"):
        exit_owner = "exit_feeder"

    simulate_fill = bool(data.get("simulate_fill", True))

    reduce_frac = None
    try:
        if data.get("reduce_frac") is not None:
            reduce_frac = float(data.get("reduce_frac") or 0.0)
    except Exception:
        reduce_frac = None
    if reduce_frac is not None:
        reduce_frac = float(_clip(float(reduce_frac), 0.0, 0.99))
        if reduce_frac <= 0.0:
            reduce_frac = None

    orig_exit_l1_enabled = CONFIG.get("exit_l1_enabled")
    if force_exit_l1:
        CONFIG["exit_l1_enabled"] = True

    reduce_cfg_keys = ("exit_l2_reduce_frac", "exit_l1_reduce_base_frac", "exit_l1_reduce_max_frac")
    orig_reduce_cfg: Dict[str, Any] = {}
    if reduce_frac is not None:
        for k in reduce_cfg_keys:
            orig_reduce_cfg[k] = CONFIG.get(k)
        CONFIG["exit_l2_reduce_frac"] = float(reduce_frac)
        CONFIG["exit_l1_reduce_base_frac"] = float(reduce_frac)
        CONFIG["exit_l1_reduce_max_frac"] = float(reduce_frac)

    orig_open_positions_raw = TRACKER_STATE.get("open_positions")

    orig_exit_inflight_raw = TRACKER_STATE.get("exit_inflight")

    new_oids: List[str] = []
    try:
        sim_open_positions = {}
        entry_info: Dict[str, Any] = {"ok": True, "entry": None}

        if isinstance(pos_list, list) and pos_list:
            for it in pos_list:
                if not isinstance(it, dict):
                    continue
                pair = str(it.get("pair") or "").strip()
                if not pair:
                    continue
                side = str(it.get("side") or "long").lower().strip()
                if side not in ("long", "short"):
                    side = "long"
                sim_open_positions[pair] = {
                    "pair": pair,
                    "ts": int(it.get("ts") or now_ms),
                    "entry_ts": int(it.get("entry_ts") or it.get("ts") or now_ms),
                    "last_sync_ts": int(now_ms),
                    "side": side,
                    "notional_usdc": float(_to_float(it.get("notional_usdc", notional_usdc))),
                    "hl_szi": float(_to_float(it.get("hl_szi", 0.0))),
                    "hl_unrealized_pnl_u": float(_to_float(it.get("hl_unrealized_pnl_u", 0.0))),
                    "hl_position_value_usdc": float(_to_float(it.get("hl_position_value_usdc", 0.0))),
                    "unrealized_pnl_pct": float(_to_float(it.get("unrealized_pnl_pct", 0.0))),
                    "mfe_pnl_u": it.get("mfe_pnl_u"),
                    "mae_pnl_u": it.get("mae_pnl_u"),
                    "strategy_id": (None if it.get("strategy_id") is None else str(it.get("strategy_id"))),
                    "strategy_version": (None if it.get("strategy_version") is None else str(it.get("strategy_version"))),
                    "group_id": (None if it.get("group_id") is None else str(it.get("group_id"))),
                    "feature_set_id": (None if it.get("feature_set_id") is None else str(it.get("feature_set_id"))),
                    "exit_owner": str(it.get("exit_owner") or exit_owner),
                    "origin": "sim",
                }

                for k in (
                    "exit_risk_gate_trigger_ts",
                    "exit_risk_gate_trigger_side",
                    "exit_risk_gate_trigger_thr",
                    "exit_risk_gate_trigger_hold_risk",
                    "exit_risk_gate_trigger_clear_ts",
                    "exit_risk_gate_last_hold_risk",
                    "exit_risk_gate_last_thr",
                    "exit_risk_gate_last_ts",
                    "exit_snapshot_ts",
                ):
                    if it.get(k) is not None:
                        sim_open_positions[pair][k] = it.get(k)

                if isinstance(it.get("exit_snapshot"), dict):
                    sim_open_positions[pair]["exit_snapshot"] = dict(it.get("exit_snapshot") or {})
                if isinstance(it.get("features"), dict):
                    evt_id = _exit_observe_event(pair=pair, side=side, strategy_id=sim_open_positions[pair].get("strategy_id"), features=dict(it.get("features") or {}), ts=int(now_ms))
                    sim_open_positions[pair]["last_observe_ts"] = int(now_ms)
                    sim_open_positions[pair]["last_observe_event_id"] = str(evt_id)
        else:
            strategy_id = str(data.get("strategy_id") or "Strategy005").strip() or "Strategy005"
            coin = str(data.get("coin") or data.get("pair") or "BTC")
            built = _sim_build_signal_payload(strategy_id=strategy_id, coin=str(coin))
            if not bool(built.get("ok")):
                return jsonify(_json_sanitize(built)), 400
            sig = built.get("signal")
            if not isinstance(sig, dict):
                entry_info = {"ok": True, "entry": None, "diagnostic": built.get("diagnostic")}
            else:
                ingested = _emit_signal_v1(dict(sig), True, {"size": float(notional_usdc), "source": "sim"})
                entry_info = {"ok": True, "entry": {"signal": sig, "ingested": ingested, "diagnostic": built.get("diagnostic")}}
                pair = str(sig.get("pair") or "")
                pos = (TRACKER_STATE.get("open_positions") or {}).get(pair)
                if isinstance(pos, dict):
                    sim_open_positions[pair] = dict(pos)

        if not sim_open_positions:
            return jsonify({"ok": True, "ts": int(now_ms), "entry": _json_sanitize(entry_info), "exit": {"ok": True, "stats": {"actions": 0}, "orders": []}})

        exit_features = data.get("exit_features")
        if exit_features is not None and not isinstance(exit_features, dict):
            exit_features = None

        for pair, pos in list(sim_open_positions.items()):
            if not isinstance(pos, dict):
                continue
            side = str(pos.get("side") or "long").lower().strip()
            if side not in ("long", "short"):
                side = "long"
            pos["exit_owner"] = str(exit_owner)
            pos.setdefault("origin", "sim")
            try:
                pv = float(pos.get("hl_position_value_usdc") or pos.get("notional_usdc") or notional_usdc)
            except Exception:
                pv = float(notional_usdc)
            pv = float(max(1e-9, pv))
            u = float(pv) * float(profit_pct)
            mfe = float(u) / float(max(1e-6, 1.0 - float(dd_target))) if float(u) > 0.0 else float(u)
            pos["hl_position_value_usdc"] = float(pv)
            pos["hl_unrealized_pnl_u"] = float(u)
            pos["unrealized_pnl_pct"] = float(profit_pct)
            pos["mfe_pnl_u"] = float(mfe)
            if pos.get("mae_pnl_u") is None:
                pos["mae_pnl_u"] = float(min(0.0, float(u)))

            try:
                szi = float(pos.get("hl_szi") or 0.0)
            except Exception:
                szi = 0.0
            if abs(float(szi)) <= 1e-12:
                coin = _hl_coin_from_pair(pair)
                mid = None
                try:
                    mid = float(_hl_mid(coin))
                except Exception:
                    mid = None
                if mid is not None and mid > 0.0:
                    base_sz = float(pv) / float(mid)
                else:
                    base_sz = float(max(0.0001, float(pv) / 1000.0))
                szi = base_sz if side == "long" else -base_sz
                pos["hl_szi"] = float(szi)

            if isinstance(exit_features, dict):
                evt_id = _exit_observe_event(pair=str(pair), side=str(side), strategy_id=(pos.get("strategy_id") if pos.get("strategy_id") is not None else None), features=dict(exit_features), ts=int(now_ms))
                pos["last_observe_ts"] = int(now_ms)
                pos["last_observe_event_id"] = str(evt_id)

            sim_open_positions[pair] = pos

        TRACKER_STATE["open_positions"] = dict(sim_open_positions)
        TRACKER_STATE["exit_inflight"] = {}

        before_oids = set(ORDERS.keys()) if isinstance(ORDERS, dict) else set()
        exit_stats = _exit_pipeline_tick(now_ms=int(now_ms), execute=bool(execute))
        after_oids = set(ORDERS.keys()) if isinstance(ORDERS, dict) else set()
        new_oids = [oid for oid in list(after_oids) if oid not in before_oids]
        new_orders = []
        for oid in new_oids:
            o = ORDERS.get(oid)
            if isinstance(o, dict):
                new_orders.append(dict(o))
        new_orders.sort(key=lambda x: int(x.get("ts") or 0))

        if (not execute) and simulate_fill and isinstance(TRACKER_STATE.get("open_positions"), dict):
            opx = TRACKER_STATE.get("open_positions")
            for o in list(new_orders):
                try:
                    pair = str(o.get("pair") or "")
                except Exception:
                    pair = ""
                if not pair or pair not in opx:
                    continue
                pos = opx.get(pair)
                if not isinstance(pos, dict):
                    continue
                tag = str(o.get("tag") or "")
                try:
                    sz = float(o.get("size") or 0.0)
                except Exception:
                    sz = 0.0
                if ":reduce_" in tag and sz > 0.0:
                    try:
                        szi = float(pos.get("hl_szi") or 0.0)
                    except Exception:
                        szi = 0.0
                    if abs(float(szi)) > 1e-12:
                        frac = float(_clip(float(sz) / abs(float(szi)), 0.0, 1.0))
                        pos["hl_szi"] = float(szi) * float(1.0 - frac)
                        try:
                            pos["notional_usdc"] = float(pos.get("notional_usdc") or 0.0) * float(1.0 - frac)
                        except Exception:
                            pass
                        try:
                            pos["hl_position_value_usdc"] = float(pos.get("hl_position_value_usdc") or 0.0) * float(1.0 - frac)
                        except Exception:
                            pass
                        try:
                            pos["hl_unrealized_pnl_u"] = float(pos.get("hl_unrealized_pnl_u") or 0.0) * float(1.0 - frac)
                        except Exception:
                            pass
                        opx[pair] = pos
                else:
                    del opx[pair]
            TRACKER_STATE["open_positions"] = opx

        positions_after = []
        try:
            for p, v in (TRACKER_STATE.get("open_positions") or {}).items():
                if isinstance(v, dict):
                    positions_after.append(dict(v))
        except Exception:
            positions_after = []

        return jsonify(
            _json_sanitize(
                {
                    "ok": True,
                    "ts": int(now_ms),
                    "entry": entry_info,
                    "exit": {"stats": exit_stats, "orders": new_orders, "positions_after": positions_after},
                }
            )
        )
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        TRACKER_STATE["open_positions"] = orig_open_positions_raw
        TRACKER_STATE["exit_inflight"] = orig_exit_inflight_raw
        if force_exit_l1:
            CONFIG["exit_l1_enabled"] = orig_exit_l1_enabled
        if orig_reduce_cfg:
            for k, v in orig_reduce_cfg.items():
                if v is None:
                    try:
                        CONFIG.pop(k, None)
                    except Exception:
                        pass
                else:
                    CONFIG[k] = v
        if (not execute) and isinstance(ORDERS, dict) and new_oids:
            for oid in list(new_oids):
                try:
                    ORDERS.pop(str(oid), None)
                except Exception:
                    pass


@app.route("/execution/hyperliquid/cancel", methods=["POST"])
def hyperliquid_cancel():
    return jsonify({"ok": False, "error": "hyperliquid_disabled"}), 403
    data = request.get_json(force=True) or {}
    coin = str(data.get("coin") or data.get("pair") or "BTC")
    coin = _hl_coin_from_pair(coin)
    oid = data.get("oid")
    if oid is None:
        return jsonify({"ok": False, "error": "missing_oid"}), 400

    execute = bool(data.get("execute", False))
    if execute:
        if not bool(CONFIG.get("live_trading_enabled", False)):
            return jsonify({"ok": False, "error": "live_trading_disabled"}), 403
        if bool(CONFIG.get("dry_run", True)):
            return jsonify({"ok": False, "error": "dry_run_enabled"}), 400
        if not _hl_enabled_for_trading():
            return jsonify({"ok": False, "error": "hyperliquid_trading_disabled"}), 403

    order_id = _gen_id("ord")
    ts = _now_ms()
    mode = "dry-run" if (not execute) else "real"
    status = "accepted" if (not execute) else "submitted"

    exec_info: Dict[str, Any] = {
        "venue": "hyperliquid",
        "coin": coin,
        "oid": oid,
        "execute": bool(execute),
    }

    if execute:
        try:
            out = _hl_cancel(coin=coin, oid=oid)
            exec_info["resp"] = out.get("resp")
        except Exception as e:
            status = "failed"
            exec_info["error"] = str(e)

    ORDERS[order_id] = {
        "id": order_id,
        "pair": f"{coin}-PERP",
        "side": "long",
        "size": 0.0,
        "mode": mode,
        "tag": "hyperliquid_cancel",
        "ts": ts,
        "status": status,
        "p": 0.0,
        "pc": 0.0,
        "regime": None,
        "exchange": "hyperliquid",
        "exchange_oid": int(oid),
        "exec": exec_info,
    }
    try:
        _archive_order(ORDERS.get(order_id) or {})
    except Exception:
        pass

    try:
        TRACKER_STATE["order_ts"].append(ts)
    except Exception:
        pass

    return jsonify({"ok": True, "order_id": order_id, "order": ORDERS[order_id]})


@app.route("/execution/hyperliquid/cancel_all", methods=["POST"])
def hyperliquid_cancel_all():
    return jsonify({"ok": False, "error": "hyperliquid_disabled"}), 403
    data = request.get_json(force=True) or {}
    coin = data.get("coin") or data.get("pair")
    coin = (_hl_coin_from_pair(str(coin)) if coin else None)

    execute = bool(data.get("execute", False))
    if execute:
        if not bool(CONFIG.get("live_trading_enabled", False)):
            return jsonify({"ok": False, "error": "live_trading_disabled"}), 403
        if bool(CONFIG.get("dry_run", True)):
            return jsonify({"ok": False, "error": "dry_run_enabled"}), 400
        if not _hl_enabled_for_trading():
            return jsonify({"ok": False, "error": "hyperliquid_trading_disabled"}), 403

    order_id = _gen_id("ord")
    ts = _now_ms()
    mode = "dry-run" if (not execute) else "real"
    status = "accepted" if (not execute) else "submitted"

    exec_info: Dict[str, Any] = {
        "venue": "hyperliquid",
        "coin": coin,
        "execute": bool(execute),
    }

    try:
        open_orders = _hl_open_orders(coin=coin)
        exec_info["open_orders"] = open_orders
        if execute:
            cancelled = []
            for o in list(open_orders):
                try:
                    oc = str(o.get("coin") or o.get("asset") or o.get("symbol") or o.get("name") or "")
                    oid = o.get("oid")
                    if oid is None:
                        continue
                    c = _hl_coin_from_pair(oc) if oc else (coin or "")
                    if not c:
                        continue
                    out = _hl_cancel(coin=c, oid=oid)
                    cancelled.append({"coin": c, "oid": int(oid), "resp": out.get("resp")})
                except Exception as e:
                    cancelled.append({"coin": coin, "oid": o.get("oid"), "error": str(e)})
            exec_info["cancelled"] = cancelled
    except Exception as e:
        status = "failed" if execute else status
        exec_info["error"] = str(e)

    ORDERS[order_id] = {
        "id": order_id,
        "pair": f"{(coin or 'ALL')}-PERP",
        "side": "long",
        "size": 0.0,
        "mode": mode,
        "tag": "hyperliquid_cancel_all",
        "ts": ts,
        "status": status,
        "p": 0.0,
        "pc": 0.0,
        "regime": None,
        "exchange": "hyperliquid",
        "exchange_oid": None,
        "exec": exec_info,
    }

    try:
        TRACKER_STATE["order_ts"].append(ts)
    except Exception:
        pass

    return jsonify({"ok": True, "order_id": order_id, "order": ORDERS[order_id]})


@app.route("/execution/hyperliquid/open_orders", methods=["GET"])
def hyperliquid_open_orders():
    if not (_is_local_request() or _config_auth_ok()):
        return jsonify({"ok": False, "error": "forbidden"}), 403
    try:
        coin = request.args.get("coin") or request.args.get("pair")
        ab_owner = request.args.get("ab_owner") or request.args.get("owner")
        owner_kind = None
        if ab_owner is not None:
            try:
                owner_kind = _ab_norm_owner(ab_owner)
            except Exception:
                owner_kind = None
        orders = _hl_open_orders(coin=coin, owner=owner_kind)
        return jsonify({"ok": True, "coin": (_hl_coin_from_pair(coin) if coin else None), "orders": orders, "ab_owner": (None if owner_kind is None else str(owner_kind))})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


