def _hl_extract_account_value(user_state: Dict[str, Any]) -> float:
    if not isinstance(user_state, dict):
        return 0.0
    for k in ("marginSummary", "crossMarginSummary"):
        try:
            ms = user_state.get(k) or {}
            if isinstance(ms, dict) and "accountValue" in ms:
                return float(ms.get("accountValue") or 0.0)
        except Exception:
            continue
    try:
        return float(user_state.get("accountValue") or 0.0)
    except Exception:
        return 0.0


def _hl_extract_positions(user_state: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(user_state, dict):
        return []
    raw = user_state.get("assetPositions")
    if isinstance(raw, list):
        out: List[Dict[str, Any]] = []
        for it in raw:
            if isinstance(it, dict):
                p = it.get("position")
                if isinstance(p, dict):
                    out.append(p)
                else:
                    out.append(it)
        return out
    raw2 = user_state.get("positions")
    if isinstance(raw2, list):
        return [x for x in raw2 if isinstance(x, dict)]
    return []


def _hl_sync(update_orders: bool = True) -> Dict[str, Any]:
    now_ms = _now_ms()
    st = _hl_user_state()
    oo = _hl_open_orders()

    open_oids = set()
    for o in list(oo):
        try:
            oid = o.get("oid")
            if oid is not None:
                open_oids.add(int(oid))
        except Exception:
            continue

    positions = _hl_extract_positions(st)
    pos_by_coin: Dict[str, Dict[str, Any]] = {}
    open_pairs: Dict[str, Dict[str, Any]] = {}
    for p in list(positions):
        try:
            coin = str(p.get("coin") or p.get("name") or p.get("asset") or "").upper()
            if not coin:
                continue
            sz = _to_float(p.get("szi", p.get("sz", p.get("size", 0.0))))
            if abs(float(sz)) < 1e-12:
                continue
            pos_by_coin[coin] = p
            pair = f"{coin}-PERP"
            side = "long" if float(sz) > 0 else "short"
            mid_px = None
            try:
                v = float(_hl_mid(coin))
                mid_px = v if math.isfinite(float(v)) and float(v) > 0 else None
            except Exception:
                mid_px = None
            notional = None
            try:
                pv = p.get("positionValue")
                if pv is None:
                    pv = p.get("positionValueUsd")
                if pv is not None:
                    notional = abs(_to_float(pv))
            except Exception:
                notional = None
            if notional is None:
                try:
                    px0 = float(mid_px) if mid_px is not None else float(_hl_mid(coin))
                    notional = abs(float(sz) * float(px0))
                except Exception:
                    notional = 0.0

            liq_px = 0.0
            try:
                liq_px = float(_to_float(p.get("liquidationPx", p.get("liqPx", p.get("liquidationPrice", 0.0)))))
            except Exception:
                liq_px = 0.0
            entry_px = 0.0
            try:
                entry_px = float(_to_float(p.get("entryPx", p.get("avgEntryPx", p.get("averageEntryPrice", 0.0)))))
            except Exception:
                entry_px = 0.0

            unreal = 0.0
            try:
                unreal = _to_float(p.get("unrealizedPnl", p.get("unrealizedPnlUsd", 0.0)))
            except Exception:
                unreal = 0.0
            pos_value = None
            try:
                pv2 = p.get("positionValue")
                if pv2 is None:
                    pv2 = p.get("positionValueUsd")
                if pv2 is not None:
                    pos_value = abs(_to_float(pv2))
            except Exception:
                pos_value = None
            if pos_value is None:
                pos_value = float(notional)
            pnl_pct = 0.0
            try:
                pnl_pct = float(unreal) / float(pos_value) if float(pos_value) > 0 else 0.0
            except Exception:
                pnl_pct = 0.0

            hl_lev = None
            try:
                lv0 = p.get("leverage")
                if lv0 is None:
                    lv0 = p.get("lev")
                if lv0 is not None:
                    lvf = float(lv0)
                    if math.isfinite(lvf) and lvf > 0.0:
                        hl_lev = int(max(1, int(round(lvf))))
            except Exception:
                hl_lev = None

            open_pairs[pair] = {
                "pair": str(pair),
                "ts": int(now_ms),
                "side": side,
                "notional_usdc": float(notional),
                "hl_szi": float(sz),
                "hl_unrealized_pnl_u": float(unreal),
                "hl_position_value_usdc": float(pos_value),
                "unrealized_pnl_pct": float(pnl_pct),
                "hl_leverage": hl_lev,
                "hl_mid_px": float(mid_px or 0.0),
                "hl_entry_px": float(entry_px),
                "hl_liquidation_px": float(liq_px),
            }
        except Exception:
            continue

    hl_pruned_open_positions = 0
    try:
        prev = TRACKER_STATE.get("open_positions")
        if not isinstance(prev, dict):
            prev = {}
            TRACKER_STATE["open_positions"] = prev
        for p, cur in list(prev.items()):
            if not isinstance(cur, dict):
                continue
            meta = open_pairs.get(p)
            if not isinstance(meta, dict):
                continue
            cur["pair"] = str(p)
            try:
                cur["last_sync_ts"] = int(meta.get("ts") or now_ms)
            except Exception:
                pass
            if cur.get("side") is None:
                cur["side"] = meta.get("side")
            try:
                if float(_to_float(cur.get("notional_usdc", 0.0))) <= 0.0:
                    cur["notional_usdc"] = float(_to_float(meta.get("notional_usdc", 0.0)))
            except Exception:
                pass
            try:
                cur["hl_szi"] = float(meta.get("hl_szi") or cur.get("hl_szi") or 0.0)
            except Exception:
                pass
            try:
                cur["hl_unrealized_pnl_u"] = float(meta.get("hl_unrealized_pnl_u") or 0.0)
            except Exception:
                pass
            try:
                cur["hl_position_value_usdc"] = float(meta.get("hl_position_value_usdc") or cur.get("hl_position_value_usdc") or 0.0)
            except Exception:
                pass
            try:
                cur["unrealized_pnl_pct"] = float(meta.get("unrealized_pnl_pct") or 0.0)
            except Exception:
                pass
            try:
                cur["hl_mid_px"] = float(meta.get("hl_mid_px") or cur.get("hl_mid_px") or 0.0)
            except Exception:
                pass
            try:
                cur["hl_entry_px"] = float(meta.get("hl_entry_px") or cur.get("hl_entry_px") or 0.0)
            except Exception:
                pass
            try:
                cur["hl_liquidation_px"] = float(meta.get("hl_liquidation_px") or cur.get("hl_liquidation_px") or 0.0)
            except Exception:
                pass
            try:
                if cur.get("hl_leverage") is None and meta.get("hl_leverage") is not None:
                    cur["hl_leverage"] = int(meta.get("hl_leverage") or 0)
            except Exception:
                pass
            try:
                u = float(cur.get("hl_unrealized_pnl_u") or 0.0)
                mx = cur.get("mfe_pnl_u")
                mn = cur.get("mae_pnl_u")
                cur["mfe_pnl_u"] = float(u) if mx is None else float(max(float(mx), float(u)))
                cur["mae_pnl_u"] = float(u) if mn is None else float(min(float(mn), float(u)))
            except Exception:
                pass
            try:
                eo = cur.get("exit_owner")
                eo_s = ("" if eo is None else str(eo)).strip()
                if eo_s not in ("strategy", "exit_feeder"):
                    seed_extra = str(cur.get("order_id") or "")
                    try:
                        entry_ts = int(cur.get("entry_ts") or cur.get("ts") or now_ms)
                    except Exception:
                        entry_ts = int(now_ms)
                    cur["exit_owner"] = _exit_owner_choose(pair=str(p), side=str(cur.get("side") or "long"), entry_ts=int(entry_ts), seed_extra=seed_extra)
            except Exception:
                pass
            prev[p] = cur

        for p, meta in list(open_pairs.items()):
            if p in prev:
                continue
            try:
                entry_ts = int(meta.get("ts") or now_ms)
            except Exception:
                entry_ts = int(now_ms)
            side = str(meta.get("side") or "long")
            try:
                notional_usdc = float(_to_float(meta.get("notional_usdc", 0.0)))
            except Exception:
                notional_usdc = 0.0
            try:
                exit_owner = _exit_owner_choose(pair=str(p), side=str(side), entry_ts=int(entry_ts), seed_extra="hl_sync")
            except Exception:
                exit_owner = "strategy"
            prev[p] = {
                "pair": str(p),
                "ts": int(entry_ts),
                "entry_ts": int(entry_ts),
                "last_sync_ts": int(entry_ts),
                "order_id": None,
                "event_id": None,
                "side": str(side),
                "notional_usdc": float(notional_usdc),
                "strategy_id": None,
                "strategy_version": "hl_sync",
                "group_id": "hl_sync",
                "feature_set_id": "",
                "exit_owner": str(exit_owner),
                "hl_szi": float(_to_float(meta.get("hl_szi", 0.0))),
                "hl_unrealized_pnl_u": float(_to_float(meta.get("hl_unrealized_pnl_u", 0.0))),
                "hl_position_value_usdc": float(_to_float(meta.get("hl_position_value_usdc", 0.0))),
                "unrealized_pnl_pct": float(_to_float(meta.get("unrealized_pnl_pct", 0.0))),
                "hl_leverage": (None if meta.get("hl_leverage") is None else int(meta.get("hl_leverage") or 0)),
                "hl_mid_px": float(_to_float(meta.get("hl_mid_px", 0.0))),
                "hl_entry_px": float(_to_float(meta.get("hl_entry_px", 0.0))),
                "hl_liquidation_px": float(_to_float(meta.get("hl_liquidation_px", 0.0))),
            }

        hl_pairs = set(open_pairs.keys())
        for p in list(prev.keys()):
            if p not in hl_pairs:
                try:
                    cur = prev.get(p)
                    if isinstance(cur, dict):
                        mode0 = str(cur.get("mode") or "").lower().strip()
                        sim0 = bool(cur.get("simulated", False)) or (mode0 in ("dry-run", "dryrun", "paper", "sim", "simulated"))
                        if sim0 and bool(CONFIG.get("dry_run", True)):
                            continue
                except Exception:
                    pass
                try:
                    try:
                        sys0 = None
                        if isinstance(cur, dict):
                            sys0 = cur.get("system_id")
                            if sys0 is None:
                                sys0 = cur.get("exit_owner")
                        _tracker_set_post_close_cooldown(raw_pair=str(p), coin=str(_hl_coin_from_pair(str(p)) or ""), ts=int(now_ms), system_id=_system_from_strategy_id(sys0 if sys0 is not None else "strategy"))
                    except Exception:
                        pass
                    del prev[p]
                    hl_pruned_open_positions += 1
                except Exception:
                    pass
    except Exception:
        pass

    account_value = float(_hl_extract_account_value(st))
    today_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    wk = _week_key(now_ms)
    hl_state = TRACKER_STATE.get("hl")
    if not isinstance(hl_state, dict):
        hl_state = {}
        TRACKER_STATE["hl"] = hl_state
    hl_state["account_value"] = account_value
    hl_state["unrealized_pnl"] = float(sum(_to_float((p.get("unrealizedPnl") or p.get("unrealizedPnlUsd") or 0.0)) for p in positions))
    hl_state["ts"] = int(now_ms)
    hl_state["open_position_count"] = int(len(open_pairs))
    hl_state["pruned_open_positions"] = int(hl_pruned_open_positions)

    try:
        day_base = hl_state.get("baseline_day")
        if not isinstance(day_base, dict) or str(day_base.get("day")) != today_str or float(day_base.get("account_value") or 0.0) <= 0.0:
            day_base = {"day": today_str, "account_value": account_value}
            hl_state["baseline_day"] = day_base
        wk_base = hl_state.get("baseline_week")
        if not isinstance(wk_base, dict) or str(wk_base.get("wk")) != wk or float(wk_base.get("account_value") or 0.0) <= 0.0:
            wk_base = {"wk": wk, "account_value": account_value}
            hl_state["baseline_week"] = wk_base

        bday = float(day_base.get("account_value") or 0.0)
        bwk = float(wk_base.get("account_value") or 0.0)
        _tracker_pnl_set("daily", "__account__", today_str, (float(account_value) - bday) / bday if bday > 0 else 0.0)
        _tracker_pnl_set("weekly", "__account__", wk, (float(account_value) - bwk) / bwk if bwk > 0 else 0.0)
    except Exception:
        pass

    updated_orders = 0
    if update_orders:
        for o in list(ORDERS.values()):
            try:
                if str(o.get("exchange") or "").lower() != "hyperliquid":
                    continue
                if str(o.get("status") or "").lower() != "submitted":
                    continue
                prev_status = str(o.get("status") or "").strip().lower()
                oid = o.get("exchange_oid")
                if oid is None:
                    continue
                ioid = int(oid)
                if ioid in open_oids:
                    continue

                age_ms = int(now_ms) - int(o.get("ts") or 0)
                if age_ms < 30_000:
                    continue

                pair = str(o.get("pair") or "")
                coin = _hl_coin_from_pair(pair)
                tag = str(o.get("tag") or "").lower()
                is_close = ("close" in tag)
                has_pos = bool(coin and coin in pos_by_coin)

                if is_close:
                    if has_pos:
                        continue
                    o["status"] = "filled"
                    o["sync"] = {"ts": int(now_ms), "method": "open_orders_absent_close_no_position"}
                    updated_orders += 1
                    if prev_status != "filled":
                        try:
                            tid0 = str(o.get("base_event_id") or o.get("event_id") or "").strip()
                        except Exception:
                            tid0 = ""
                        if tid0:
                            try:
                                _emit_order_submit_events(o, str(tid0))
                            except Exception:
                                pass
                    try:
                        _archive_order(o)
                    except Exception:
                        pass
                    try:
                        pair0 = str(o.get("pair") or "")
                        if pair0:
                            pos0 = o.get("pos_snapshot")
                            if not isinstance(pos0, dict):
                                pos0 = {}
                            _tracker_auto_exit_settle(
                                pair=pair0,
                                pos=pos0,
                                order_id=str(o.get("id") or ""),
                                exit_reason=str(o.get("tag") or "hl_sync_close_filled"),
                                exit_tag=str(o.get("tag") or "hl_sync_close_filled"),
                            )
                    except Exception:
                        pass
                    continue

                if has_pos:
                    o["status"] = "filled"
                    o["sync"] = {"ts": int(now_ms), "method": "open_orders_absent_open_has_position"}
                    updated_orders += 1
                    if prev_status != "filled":
                        try:
                            tid0 = str(o.get("base_event_id") or o.get("event_id") or "").strip()
                        except Exception:
                            tid0 = ""
                        if tid0:
                            try:
                                _emit_order_submit_events(o, str(tid0))
                            except Exception:
                                pass
                    try:
                        _archive_order(o)
                    except Exception:
                        pass
                    continue

                if age_ms >= 10 * 60_000:
                    o["status"] = "failed"
                    o["sync"] = {"ts": int(now_ms), "method": "open_orders_absent_open_no_position"}
                    updated_orders += 1
                    try:
                        _archive_order(o)
                    except Exception:
                        pass
            except Exception:
                continue

    return {
        "ok": True,
        "ts": int(now_ms),
        "open_orders": len(oo),
        "open_positions": len(open_pairs),
        "account_value": account_value,
        "orders_updated": int(updated_orders),
    }


def _tracker_sync_trigger_append(
    venue: str,
    *,
    ts: int,
    trigger: Optional[str],
    trace_id: Optional[str],
    update_orders: bool,
    ok: Optional[bool],
    error: Optional[str],
    skipped: bool = False,
    until: Optional[int] = None,
) -> None:
    vn = str(venue or "").strip().lower()
    if not vn:
        return
    st = TRACKER_STATE.get(vn)
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE[vn] = st

    tr = None if trigger is None else str(trigger).strip()
    if tr:
        tr = tr[:160]
    else:
        tr = "unknown"

    tid = None if trace_id is None else str(trace_id).strip()
    if tid:
        tid = tid[:96]
    else:
        tid = None

    err = None if error is None else str(error).strip()
    if err:
        err = err[:280]

    rec = {
        "ts": int(ts),
        "trigger": tr,
        "trace_id": tid,
        "update_orders": bool(update_orders),
        "ok": (None if ok is None else bool(ok)),
        "skipped": bool(skipped),
        "error": err,
        "until": (None if until is None else int(until)),
    }
    try:
        hist = st.get("sync_trigger_history")
        if not isinstance(hist, list):
            hist = []
            st["sync_trigger_history"] = hist
        hist.append(rec)
        if len(hist) > 420:
            st["sync_trigger_history"] = hist[-360:]
    except Exception:
        return


def _hl_sync_record(update_orders: bool = True, *, trigger: Optional[str] = None, trace_id: Optional[str] = None) -> Dict[str, Any]:
    now_ms = _now_ms()
    hl_state = TRACKER_STATE.get("hl")
    if not isinstance(hl_state, dict):
        hl_state = {}
        TRACKER_STATE["hl"] = hl_state
    try:
        until_ms = int(hl_state.get("rate_limit_until_ts") or 0)
    except Exception:
        until_ms = 0
    if int(until_ms) > 0 and int(now_ms) < int(until_ms):
        hl_state["sync_ok"] = False
        hl_state["ts"] = int(now_ms)
        hl_state["last_sync_ts"] = int(now_ms)
        hl_state["last_sync_error"] = "rate_limited"
        _tracker_sync_trigger_append(
            "hl",
            ts=int(now_ms),
            trigger=trigger,
            trace_id=trace_id,
            update_orders=bool(update_orders),
            ok=False,
            error="rate_limited",
            skipped=True,
            until=int(until_ms),
        )
        try:
            hist = hl_state.get("sync_history")
            if not isinstance(hist, list):
                hist = []
                hl_state["sync_history"] = hist
            hist.append({"ts": int(now_ms), "ok": False, "error": "rate_limited", "skipped": True, "until": int(until_ms)})
            if len(hist) > 220:
                hl_state["sync_history"] = hist[-200:]
        except Exception:
            pass
        return {"ok": False, "ts": int(now_ms), "skipped": True, "reason": "rate_limited", "until": int(until_ms)}
    try:
        out = _hl_sync(update_orders=update_orders)
        hl_state["sync_ok"] = True
        hl_state["last_sync_ts"] = int(out.get("ts") or now_ms)
        hl_state["last_sync_error"] = None
        hl_state["rate_limit_until_ts"] = 0
        hl_state["rate_limit_backoff_ms"] = 0
        _tracker_sync_trigger_append(
            "hl",
            ts=int(out.get("ts") or now_ms),
            trigger=trigger,
            trace_id=trace_id,
            update_orders=bool(update_orders),
            ok=True,
            error=None,
            skipped=False,
            until=None,
        )
        try:
            hist = hl_state.get("sync_history")
            if not isinstance(hist, list):
                hist = []
                hl_state["sync_history"] = hist
            hist.append({"ts": int(out.get("ts") or now_ms), "ok": True, "error": None})
            if len(hist) > 220:
                hl_state["sync_history"] = hist[-200:]
        except Exception:
            pass
        return out
    except Exception as e:
        err = str(e)
        hl_state["sync_ok"] = False
        hl_state["ts"] = int(now_ms)
        hl_state["last_sync_ts"] = int(now_ms)
        hl_state["last_sync_error"] = err
        try:
            is_429 = ("429" in err) or ("too many requests" in err.lower())
        except Exception:
            is_429 = False
        if bool(is_429):
            try:
                backoff0 = int(hl_state.get("rate_limit_backoff_ms") or 0)
            except Exception:
                backoff0 = 0
            backoff_ms = 30_000 if int(backoff0) <= 0 else int(backoff0) * 2
            backoff_ms = max(10_000, min(300_000, int(backoff_ms)))
            hl_state["rate_limit_backoff_ms"] = int(backoff_ms)
            hl_state["rate_limit_until_ts"] = int(now_ms) + int(backoff_ms)
        else:
            hl_state["rate_limit_until_ts"] = 0
            hl_state["rate_limit_backoff_ms"] = 0

        _tracker_sync_trigger_append(
            "hl",
            ts=int(now_ms),
            trigger=trigger,
            trace_id=trace_id,
            update_orders=bool(update_orders),
            ok=False,
            error=err,
            skipped=False,
            until=(None if int(hl_state.get("rate_limit_until_ts") or 0) <= 0 else int(hl_state.get("rate_limit_until_ts") or 0)),
        )
        try:
            hist = hl_state.get("sync_history")
            if not isinstance(hist, list):
                hist = []
                hl_state["sync_history"] = hist
            hist.append({"ts": int(now_ms), "ok": False, "error": err, "until": hl_state.get("rate_limit_until_ts")})
            if len(hist) > 220:
                hl_state["sync_history"] = hist[-200:]
        except Exception:
            pass
        return {"ok": False, "ts": int(now_ms), "error": err}


@app.route("/execution/hyperliquid/sync", methods=["POST"])
def hyperliquid_sync():
    return jsonify({"ok": False, "error": "hyperliquid_disabled"}), 403
    data = request.get_json(force=True) or {}
    update_orders = bool(data.get("update_orders", True))
    try:
        return jsonify(_hl_sync_record(update_orders=update_orders))
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


@app.route("/execution/aster/sync", methods=["POST"])
def aster_sync():
    data = request.get_json(force=True) or {}
    update_orders = bool(data.get("update_orders", True))
    try:
        return jsonify(_aster_sync_record(update_orders=update_orders))
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500

