def _eval_history_max() -> int:
    try:
        n = int(CONFIG.get("eval_history_max", 2000) or 2000)
    except Exception:
        n = 2000
    return max(50, min(20000, int(n)))

def _evaluation_history_append(run: Dict[str, Any]) -> None:
    if not isinstance(run, dict):
        return
    row = _json_sanitize(dict(run))
    if not isinstance(row, dict):
        return
    if row.get("id") is None:
        row["id"] = _gen_id("run")
    if row.get("ts") is None:
        row["ts"] = int(_now_ms())
    met = row.get("metrics")
    if isinstance(met, dict):
        keep_keys = (
            "auc",
            "pr_auc",
            "brier",
            "logloss",
            "ece",
            "coverage",
            "win_rate",
            "mean_return",
            "sharpe",
            "sortino",
            "max_drawdown",
            "profit_factor",
            "total_return",
            "n",
        )
        row["metrics"] = {k: met.get(k) for k in keep_keys if k in met}
    EVAL_HISTORY.append(row)
    cap = _eval_history_max()
    if cap > 0 and len(EVAL_HISTORY) > cap:
        EVAL_HISTORY[:] = EVAL_HISTORY[-cap:]

