def _p1_exec_state() -> Dict[str, Any]:
    st = TRACKER_STATE.get("p1_exec")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["p1_exec"] = st
    if not isinstance(st.get("order_events"), list):
        st["order_events"] = []
    if not isinstance(st.get("restart_events"), list):
        st["restart_events"] = []
    try:
        st["consecutive_failures"] = int(st.get("consecutive_failures") or 0)
    except Exception:
        st["consecutive_failures"] = 0
    return st


def _p1_exec_prune(*, now_ms: int) -> None:
    st = _p1_exec_state()
    try:
        max_events = int(CONFIG.get("p1_exec_max_events", 5000) or 5000)
    except Exception:
        max_events = 5000
    max_events = max(100, min(200000, int(max_events)))

    try:
        keep_sec = int(CONFIG.get("p1_exec_keep_seconds", 3 * 3600) or (3 * 3600))
    except Exception:
        keep_sec = 3 * 3600
    keep_sec = max(1800, min(72 * 3600, int(keep_sec)))
    since = int(now_ms) - int(keep_sec) * 1000

    ev = st.get("order_events")
    if isinstance(ev, list) and ev:
        out_ev = []
        for it in ev:
            if not isinstance(it, dict):
                continue
            try:
                t = int(it.get("ts") or 0)
            except Exception:
                t = 0
            if t <= 0 or t < int(since):
                continue
            out_ev.append({"ts": int(t), "ok": bool(it.get("ok", True))})
        if len(out_ev) > int(max_events):
            out_ev = out_ev[-int(max_events):]
        st["order_events"] = out_ev

    rs = st.get("restart_events")
    if isinstance(rs, list) and rs:
        out_rs = []
        for it in rs:
            try:
                t = int(it)
            except Exception:
                t = 0
            if t <= 0 or t < int(since):
                continue
            out_rs.append(int(t))
        if len(out_rs) > 2000:
            out_rs = out_rs[-2000:]
        st["restart_events"] = out_rs


def _p1_exec_boot_record(now_ms: int) -> None:
    st = _p1_exec_state()
    try:
        st["restart_events"].append(int(now_ms))
    except Exception:
        st["restart_events"] = [int(now_ms)]
    try:
        _p1_exec_prune(now_ms=int(now_ms))
    except Exception:
        pass
    try:
        _snapshot_tracker_state_write(int(now_ms))
    except Exception:
        pass


def _p1_exec_record_order_from_archive(order: Dict[str, Any]) -> None:
    if not isinstance(order, dict):
        return
    try:
        mode = str(order.get("mode") or "").strip().lower()
    except Exception:
        mode = ""
    if mode != "real":
        return
    try:
        ts = int(order.get("ts") or _now_ms())
    except Exception:
        ts = int(_now_ms())
    try:
        st = str(order.get("status") or "").strip().lower()
    except Exception:
        st = ""
    nonfatal_failed = False
    if st == "failed":
        try:
            action = str(order.get("action") or "").strip().lower()
        except Exception:
            action = ""
        try:
            tag = str(order.get("tag") or "").strip().lower()
        except Exception:
            tag = ""
        try:
            exec0 = order.get("exec") if isinstance(order.get("exec"), dict) else {}
        except Exception:
            exec0 = {}
        try:
            exec_err = str((exec0 or {}).get("error") or "").strip()
        except Exception:
            exec_err = ""
        exec_err_l = exec_err.lower()
        if exec_err_l and ("qty_capped_too_small" in exec_err_l):
            nonfatal_failed = True
        is_exit_like = (action in ("close", "reduce")) or ("market_close" in tag) or ("reduce" in tag)
        if is_exit_like and exec_err_l:
            if (
                ("size_underflow" in exec_err_l)
                or ("reduceonly order is rejected" in exec_err_l)
                or ("no position" in exec_err_l)
                or ("position is zero" in exec_err_l)
                or ("position_amt" in exec_err_l and "<=" in exec_err_l and "0" in exec_err_l)
                or ("-2022" in exec_err_l)
            ):
                nonfatal_failed = True
    failed = (st == "failed") and (not nonfatal_failed)
    ok = (not failed)

    s = _p1_exec_state()
    try:
        s["order_events"].append({"ts": int(ts), "ok": bool(ok)})
    except Exception:
        s["order_events"] = [{"ts": int(ts), "ok": bool(ok)}]
    if failed:
        try:
            s["consecutive_failures"] = int(s.get("consecutive_failures") or 0) + 1
        except Exception:
            s["consecutive_failures"] = 1
    else:
        s["consecutive_failures"] = 0
    try:
        _p1_exec_prune(now_ms=int(ts))
    except Exception:
        pass


def _p1_exec_gate_status(now_ms: int) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    enabled = bool(CONFIG.get("p1_exec_gate_enabled", True))
    if not enabled:
        return {"ok": True, "blocked": False, "enabled": False, "ts": ts}

    fail_open = bool(CONFIG.get("p1_exec_gate_fail_open", False))

    try:
        window_sec = int(CONFIG.get("p1_exec_order_window_sec", 30 * 60) or (30 * 60))
    except Exception:
        window_sec = 30 * 60
    window_sec = max(60, min(24 * 3600, int(window_sec)))
    try:
        fail_rate_thr = float(CONFIG.get("p1_exec_order_fail_rate_thr", 0.10) or 0.10)
    except Exception:
        fail_rate_thr = 0.10
    fail_rate_thr = max(0.0, min(1.0, float(fail_rate_thr)))
    try:
        consec_thr = int(CONFIG.get("p1_exec_order_consecutive_failures_thr", 3) or 3)
    except Exception:
        consec_thr = 3
    consec_thr = max(1, min(100, int(consec_thr)))

    try:
        restart_window_sec = int(CONFIG.get("p1_exec_restart_window_sec", 3600) or 3600)
    except Exception:
        restart_window_sec = 3600
    restart_window_sec = max(60, min(24 * 3600, int(restart_window_sec)))
    try:
        restart_thr = int(CONFIG.get("p1_exec_restart_thr", 3) or 3)
    except Exception:
        restart_thr = 3
    restart_thr = max(1, min(100, int(restart_thr)))

    st = _p1_exec_state()
    try:
        _p1_exec_prune(now_ms=int(ts))
    except Exception:
        pass

    since = int(ts) - int(window_sec) * 1000
    ev = st.get("order_events")
    recent = []
    if isinstance(ev, list) and ev:
        for it in ev:
            if not isinstance(it, dict):
                continue
            try:
                t = int(it.get("ts") or 0)
            except Exception:
                t = 0
            if t <= 0 or t < int(since):
                continue
            recent.append(it)

    n = int(len(recent))
    fails = 0
    for it in recent:
        try:
            if not bool(it.get("ok", True)):
                fails += 1
        except Exception:
            pass
    fail_rate = (float(fails) / float(n)) if n > 0 else 0.0

    try:
        consec = int(st.get("consecutive_failures") or 0)
    except Exception:
        consec = 0

    restart_since = int(ts) - int(restart_window_sec) * 1000
    rs0 = st.get("restart_events")
    rs = []
    if isinstance(rs0, list) and rs0:
        for it in rs0:
            try:
                t = int(it)
            except Exception:
                t = 0
            if t <= 0 or t < int(restart_since):
                continue
            rs.append(int(t))
    restart_n = int(len(rs))

    reasons: List[str] = []
    if n > 0 and float(fail_rate) > float(fail_rate_thr):
        reasons.append("order_fail_rate_high")
    if int(consec) >= int(consec_thr):
        reasons.append("order_fail_streak")
    if int(restart_n) >= int(restart_thr):
        reasons.append("process_restart_frequent")

    blocked = bool(reasons)
    if blocked and fail_open:
        blocked = False

    return {
        "ok": (not blocked),
        "blocked": bool(blocked),
        "enabled": True,
        "fail_open": bool(fail_open),
        "ts": ts,
        "reasons": reasons,
        "metrics": {
            "order_window_sec": int(window_sec),
            "order_n": int(n),
            "order_fail_n": int(fails),
            "order_fail_rate": float(fail_rate),
            "order_consecutive_failures": int(consec),
            "restart_window_sec": int(restart_window_sec),
            "restart_n": int(restart_n),
        },
        "thresholds": {
            "order_fail_rate_thr": float(fail_rate_thr),
            "order_consecutive_failures_thr": int(consec_thr),
            "restart_thr": int(restart_thr),
        },
    }

def _exit_owner_state() -> Dict[str, Any]:
    st = TRACKER_STATE.get("exit_owner_state")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["exit_owner_state"] = st
    w = st.get("weights")
    if not isinstance(w, dict):
        try:
            init_w = float(CONFIG.get("exit_owner_init_exit_feeder_weight", 0.50) or 0.50)
        except Exception:
            init_w = 0.50
        init_w = max(0.0, min(1.0, float(init_w)))
        w = {"exit_feeder": float(init_w), "strategy": float(1.0 - float(init_w))}
        st["weights"] = w
    h = st.get("history")
    if not isinstance(h, list):
        h = []
        st["history"] = h
    if st.get("last_reweight_idx") is None:
        st["last_reweight_idx"] = 0
    return st

def _exit_owner_choose(pair: str, side: str, entry_ts: int, seed_extra: str = None) -> str:
    if not bool(CONFIG.get("strategy_exit_enabled", False)):
        return "exit_feeder"
    st = _exit_owner_state()
    w = st.get("weights") or {}
    try:
        wf = float((w or {}).get("exit_feeder") or 0.50)
    except Exception:
        wf = 0.50
    wf = max(0.0, min(1.0, float(wf)))
    seed = f"{str(pair)}|{str(side)}|{int(entry_ts)}|{str(seed_extra or '')}"
    hx = hashlib.md5(seed.encode("utf-8")).hexdigest()
    try:
        u = int(hx[:12], 16) / float(int("f" * 12, 16))
    except Exception:
        u = random.random()
    return "exit_feeder" if float(u) < float(wf) else "strategy"

def _exit_owner_record(pair: str, owner: str, pnl_pct: float, pnl_u: float, action: str, reason: str, ts: int, kind: str = "execute") -> None:
    st = _exit_owner_state()
    h = st.get("history")
    if not isinstance(h, list):
        h = []
        st["history"] = h
    rec = {
        "ts": int(ts),
        "pair": str(pair),
        "owner": str(owner),
        "kind": (None if kind is None else str(kind)),
        "action": (None if action is None else str(action)),
        "reason": (None if reason is None else str(reason)),
        "pnl_pct": float(pnl_pct),
        "pnl_u": float(pnl_u),
    }
    h.append(rec)
    try:
        cap = int(CONFIG.get("arena_history_max", 2000) or 2000)
    except Exception:
        cap = 2000
    cap = max(100, int(cap))
    if len(h) > cap:
        del h[: max(0, len(h) - cap)]
    if str(kind or "").lower().strip() == "settle":
        _exit_owner_reweight_if_needed()


def _exit_seq_state() -> Dict[str, Any]:
    st = TRACKER_STATE.get("exit_snapshots")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["exit_snapshots"] = st
    return st


def _exit_seq_record_snapshot(pair: str, ts: int, features: Dict[str, Any]) -> None:
    if not pair or not isinstance(features, dict):
        return
    try:
        cap = int(CONFIG.get("exit_seq_len", 64) or 64)
    except Exception:
        cap = 64
    cap = max(8, min(512, int(cap)))
    cap = int(cap) * 2
    st = _exit_seq_state()
    h = st.get(str(pair))
    if not isinstance(h, list):
        h = []
        st[str(pair)] = h
    rec = {"ts": int(ts), "features": dict(features)}
    if h and isinstance(h[-1], dict) and int(h[-1].get("ts") or 0) == int(ts):
        h[-1] = rec
    else:
        h.append(rec)
    if len(h) > cap:
        del h[: max(0, len(h) - cap)]


def _exit_seq_get_history(pair: str, end_ts: int, max_len: int) -> List[Dict[str, Any]]:
    st = _exit_seq_state()
    h0 = st.get(str(pair))
    if not isinstance(h0, list) or not h0:
        return []
    items = []
    for it in h0:
        if not isinstance(it, dict):
            continue
        try:
            ts = int(it.get("ts") or 0)
        except Exception:
            ts = 0
        if ts <= 0 or ts > int(end_ts):
            continue
        fs = it.get("features")
        if not isinstance(fs, dict) or not fs:
            continue
        items.append((ts, fs))
    if not items:
        return []
    items.sort(key=lambda x: int(x[0]))
    if max_len > 0 and len(items) > int(max_len):
        items = items[-int(max_len):]
    return [dict(fs) for _, fs in items]


def _exit_seq_transform_from_history(history: List[Dict[str, Any]]) -> Dict[str, float]:
    if not isinstance(history, list) or not history:
        return {}
    last = history[-1] if isinstance(history[-1], dict) else {}
    out = _exit_ml_transform_features(last)

    try:
        max_keys = int(CONFIG.get("exit_seq_keys_max", 60) or 60)
    except Exception:
        max_keys = 60
    max_keys = max(10, min(400, int(max_keys)))

    def _num(v: Any) -> Optional[float]:
        try:
            x = float(v)
        except Exception:
            return None
        if not math.isfinite(x):
            return None
        return float(x)

    cand: Dict[str, int] = {}
    for fs in history:
        if not isinstance(fs, dict):
            continue
        for k, v in fs.items():
            if _num(v) is None:
                continue
            ks = str(k)
            if ks.startswith("__"):
                continue
            cand[ks] = int(cand.get(ks, 0)) + 1

    keys = [k for k, c in cand.items() if int(c) >= 2]

    def _prio(k: str) -> Tuple[int, int, str]:
        if k.startswith("pos_"):
            p = 0
        elif "atr" in k or "adx" in k or "rsi" in k:
            p = 1
        elif k.startswith("macro_"):
            p = 2
        else:
            p = 3
        return (p, -int(cand.get(k, 0)), str(k))

    keys.sort(key=_prio)
    if len(keys) > int(max_keys):
        keys = keys[: int(max_keys)]

    try:
        atr = float(last.get("atr_pct") if last.get("atr_pct") is not None else last.get("macro_atr_pct"))
    except Exception:
        atr = 0.0
    denom = max(1e-9, abs(float(atr)))

    for k in keys:
        vals: List[float] = []
        for fs in history:
            if not isinstance(fs, dict):
                continue
            x = _num(fs.get(k))
            if x is None:
                continue
            vals.append(float(x))
        if len(vals) < 2:
            continue
        x0 = float(vals[-1])
        x1 = float(vals[-2])
        d1 = float(x0 - x1)
        out[f"{k}__d1"] = float(d1)
        out[f"{k}__d1n"] = float(d1 / float(denom))

        if len(vals) >= 3:
            prev_d1 = float(x1 - float(vals[-3]))
            out[f"{k}__d2"] = float(d1 - prev_d1)
            out[f"{k}__turn"] = 1.0 if (float(d1) * float(prev_d1)) < 0.0 else 0.0
        else:
            out[f"{k}__turn"] = 0.0

        w = min(8, len(vals))
        if w >= 2:
            seg = vals[-w:]
            mu = float(sum(seg)) / float(w)
            var = float(sum((float(a) - mu) ** 2 for a in seg)) / float(max(1, w - 1))
            sd = float(math.sqrt(max(0.0, var)))
            out[f"{k}__mean8"] = float(mu)
            out[f"{k}__std8"] = float(sd)

    return out

def _exit_owner_reweight_if_needed() -> None:
    st = _exit_owner_state()
    h = st.get("history")
    if not isinstance(h, list) or not h:
        return

    settle = [r for r in h if isinstance(r, dict) and str(r.get("kind") or "").lower().strip() == "settle"]
    if not settle:
        return
    try:
        every = int(CONFIG.get("exit_owner_reweight_every", 30) or 30)
    except Exception:
        every = 30
    every = max(1, int(every))
    try:
        last_idx = int(st.get("last_reweight_idx") or 0)
    except Exception:
        last_idx = 0
    if (len(settle) - last_idx) < every:
        return

    window = settle[last_idx:]
    by_owner: Dict[str, List[float]] = {"exit_feeder": [], "strategy": []}
    for r in window:
        if not isinstance(r, dict):
            continue
        o = str(r.get("owner") or "")
        if o not in by_owner:
            continue
        try:
            by_owner[o].append(float(r.get("pnl_pct") or 0.0))
        except Exception:
            by_owner[o].append(0.0)

    if len(by_owner["exit_feeder"]) < 5 or len(by_owner["strategy"]) < 5:
        st["last_reweight_idx"] = int(len(settle))
        return

    try:
        lam = float(CONFIG.get("exit_owner_reweight_lambda", 0.30) or 0.30)
    except Exception:
        lam = 0.30
    try:
        mu = float(CONFIG.get("exit_owner_reweight_mu", 0.50) or 0.50)
    except Exception:
        mu = 0.50

    def _score(xs: List[float]) -> float:
        if not xs:
            return -1e18
        n = len(xs)
        m = sum(xs) / float(n)
        var = sum((x - m) ** 2 for x in xs) / float(max(1, n - 1))
        sd = math.sqrt(var) if var > 1e-12 else 0.0
        downside = sum(max(0.0, -float(x)) for x in xs) / float(n)
        return float(m) - float(lam) * float(sd) - float(mu) * float(downside)

    s_feeder = _score(by_owner["exit_feeder"])
    s_strat = _score(by_owner["strategy"])

    try:
        step = float(CONFIG.get("exit_owner_weight_step", 0.05) or 0.05)
    except Exception:
        step = 0.05
    try:
        w_floor = float(CONFIG.get("exit_owner_weight_floor", 0.05) or 0.05)
    except Exception:
        w_floor = 0.05
    try:
        w_cap = float(CONFIG.get("exit_owner_weight_cap", 0.95) or 0.95)
    except Exception:
        w_cap = 0.95
    step = max(0.0, min(0.50, float(step)))
    w_floor = max(0.0, min(1.0, float(w_floor)))
    w_cap = max(float(w_floor), min(1.0, float(w_cap)))

    w = st.get("weights")
    if not isinstance(w, dict):
        w = {"exit_feeder": 0.50, "strategy": 0.50}
        st["weights"] = w
    try:
        cur = float(w.get("exit_feeder") or 0.50)
    except Exception:
        cur = 0.50
    if float(s_feeder) > float(s_strat):
        cur = float(cur) + float(step)
    else:
        cur = float(cur) - float(step)
    cur = max(float(w_floor), min(float(w_cap), float(cur)))
    w["exit_feeder"] = float(cur)
    w["strategy"] = float(1.0 - float(cur))
    st["ts"] = int(_now_ms())
    st["last_reweight_idx"] = int(len(settle))

def _user_data_dir() -> Path:
    p = os.environ.get("ML_USER_DATA_DIR") or os.environ.get("FT_USER_DATA_DIR")
    if p:
        try:
            return Path(str(p)).expanduser()
        except Exception:
            return Path(os.path.dirname(__file__)) / "user_data"
    return Path(os.path.dirname(__file__)) / "user_data"


def _runtime_config_path() -> Path:
    return _user_data_dir() / "ml_config.json"

def _characterization_baseline_path() -> Path:
    raw = str(CONFIG.get("characterization_baseline_path", "user_data/datasets/characterization_baseline.json") or "").strip() or "user_data/datasets/characterization_baseline.json"
    if raw.startswith("/"):
        try:
            return Path(raw)
        except Exception:
            return _user_data_dir() / "datasets" / "characterization_baseline.json"
    s = raw.replace("\\", "/").lstrip("./")
    if s.startswith("user_data/"):
        s = s[len("user_data/"):]
    if not s:
        s = "datasets/characterization_baseline.json"
    return _user_data_dir() / s

def _characterization_suite_id() -> str:
    return str(CONFIG.get("characterization_suite_id", "p3_v1") or "p3_v1").strip() or "p3_v1"

def _characterization_gate_enabled() -> bool:
    try:
        en = bool(CONFIG.get("characterization_gate_enabled", False))
    except Exception:
        en = False
    if not bool(en):
        return False
    try:
        if bool(CONFIG.get("characterization_gate_bypass_in_test_mode", True)) and _governance_is_test_mode():
            return False
    except Exception:
        pass
    return True

def _characterization_gate_should_run(*, action: str, config_keys: Optional[List[str]] = None) -> bool:
    if not _characterization_gate_enabled():
        return False
    act = str(action or "").strip() or ""
    acts = CONFIG.get("characterization_gate_actions")
    allowed: List[str] = []
    if isinstance(acts, list):
        for x in acts:
            s = str(x or "").strip()
            if s:
                allowed.append(s)
    if allowed and act and act not in allowed:
        return False
    if act in ("strategy.registry.sync_from_zip", "strategy.registry.run_and_sync"):
        return True
    ck = config_keys if isinstance(config_keys, list) else []
    if not ck:
        return False
    guard = CONFIG.get("characterization_gate_config_keys")
    guard_keys: List[str] = []
    if isinstance(guard, list):
        for x in guard:
            s = str(x or "").strip()
            if s:
                guard_keys.append(s)
    if not guard_keys:
        guard_keys = [
            "signals_dedup_ttl_sec",
            "signals_dedup_bucket_sec",
            "signals_v1_confirm_enabled",
            "signals_v1_confirm_n",
            "signals_v1_confirm_m",
        ]
    sck = set([str(x) for x in ck])
    return any((k in sck) for k in guard_keys)

def _characterization_obj_canonicalize(obj: Any) -> Any:
    drop = {
        "id",
        "event_id",
        "trace_id",
        "order_id",
        "ts",
        "ts_ms",
        "ts_emit_ms",
        "ingested_ms",
        "book_run_id",
        "execution_account_id",
        "exchange_oid",
        "approval_id",
        "trace_id",
    }
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            ks = str(k)
            if ks in drop:
                continue
            out[ks] = _characterization_obj_canonicalize(v)
        return out
    if isinstance(obj, list):
        return [_characterization_obj_canonicalize(x) for x in obj]
    if isinstance(obj, float):
        if not math.isfinite(float(obj)):
            return None
        return float(obj)
    return obj

def _characterization_deep_diff(a: Any, b: Any, path: str = "") -> List[Dict[str, Any]]:
    diffs: List[Dict[str, Any]] = []
    if type(a) != type(b):
        diffs.append({"path": path or "/", "a": a, "b": b, "kind": "type"})
        return diffs
    if isinstance(a, dict):
        keys = sorted(set(a.keys()) | set(b.keys()))
        for k in keys:
            p2 = f"{path}/{k}" if path else f"/{k}"
            if k not in a:
                diffs.append({"path": p2, "a": None, "b": b.get(k), "kind": "missing_a"})
                continue
            if k not in b:
                diffs.append({"path": p2, "a": a.get(k), "b": None, "kind": "missing_b"})
                continue
            diffs.extend(_characterization_deep_diff(a.get(k), b.get(k), p2))
        return diffs
    if isinstance(a, list):
        if len(a) != len(b):
            diffs.append({"path": path or "/", "a": len(a), "b": len(b), "kind": "len"})
            n = min(len(a), len(b))
        else:
            n = len(a)
        for i in range(n):
            p2 = f"{path}[{i}]"
            diffs.extend(_characterization_deep_diff(a[i], b[i], p2))
        return diffs
    if a != b:
        diffs.append({"path": path or "/", "a": a, "b": b, "kind": "value"})
    return diffs

