def _characterization_suite_run(*, fixed_now_ms: int) -> Dict[str, Any]:
    fixed_now_ms = int(fixed_now_ms)
    suite_id = _characterization_suite_id()
    _MISSING = object()
    _ctx_prev_fixed_now = _MISSING
    _ctx_prev_id_counter = _MISSING
    orig_config = dict(CONFIG)
    orig_events = dict(EVENTS)
    orig_orders = dict(ORDERS)
    orig_tracker = dict(TRACKER_STATE)
    orig_active_model = dict(ACTIVE_MODEL) if isinstance(ACTIVE_MODEL, dict) else {"name": None, "obj": None}
    orig_arena_state = dict(ARENA_STATE) if isinstance(ARENA_STATE, dict) else {}
    orig_elastic_state = dict(ELASTIC_STATE) if isinstance(ELASTIC_STATE, dict) else {"by_group": {}, "ts": 0}
    orig_calibrator = dict(CALIBRATOR) if isinstance(CALIBRATOR, dict) else {"method": None, "model": None, "by_regime": {}}
    orig_scaler = dict(SCALER) if isinstance(SCALER, dict) else {"type": None, "params": {}, "ts": None}
    orig_dyn_thr = dict(DYNAMIC_THRESHOLDS) if isinstance(DYNAMIC_THRESHOLDS, dict) else {"by_regime": {}, "ts": None}
    try:
        orig_signal_dedup = dict(SIGNAL_DEDUP)
    except Exception:
        orig_signal_dedup = {}
    try:
        orig_signal_dedup_base = dict(SIGNAL_DEDUP_V1_BASE)
    except Exception:
        orig_signal_dedup_base = {}
    try:
        orig_online_dedup = set(ONLINE_DEDUP)
    except Exception:
        orig_online_dedup = set()

    try:
        _characterization_exclusive_inc()
        _ctx_prev_fixed_now = getattr(_RUNTIME_CTX, "fixed_now_ms", _MISSING)
        _ctx_prev_id_counter = getattr(_RUNTIME_CTX, "id_counter", _MISSING)
        _RUNTIME_CTX.fixed_now_ms = int(fixed_now_ms)
        _RUNTIME_CTX.id_counter = {"sig": 0, "ord": 0}

        try:
            import random as _rnd
            _rnd.seed(0)
        except Exception:
            pass
        try:
            import numpy as _np
            _np.random.seed(0)
        except Exception:
            pass

        CONFIG["dry_run"] = True
        CONFIG["execution_venue"] = "stub"
        EVENTS.clear()
        ORDERS.clear()
        TRACKER_STATE.clear()
        try:
            ACTIVE_MODEL.clear()
            ACTIVE_MODEL.update({"name": "__committee__", "obj": None})
        except Exception:
            pass
        try:
            ARENA_STATE.clear()
            ARENA_STATE.update({
                "inited": False,
                "pool_u": 0.0,
                "models": {},
                "history": [],
                "attrib": [],
                "model_calib": {},
                "layer2": {"last_train_ms": 0, "attrib_count": 0, "updated": {}},
                "diversity": {},
                "ts": 0,
            })
        except Exception:
            pass
        try:
            ELASTIC_STATE.clear()
            ELASTIC_STATE.update({"by_group": {}, "ts": 0})
        except Exception:
            pass
        try:
            CALIBRATOR.clear()
            CALIBRATOR.update({"method": None, "model": None, "by_regime": {}})
        except Exception:
            pass
        try:
            SCALER.clear()
            SCALER.update({"type": None, "params": {}, "ts": None})
        except Exception:
            pass
        try:
            DYNAMIC_THRESHOLDS.clear()
            DYNAMIC_THRESHOLDS.update({"by_regime": {}, "ts": None})
        except Exception:
            pass
        try:
            with SIGNAL_DEDUP_LOCK:
                SIGNAL_DEDUP.clear()
                SIGNAL_DEDUP_V1_BASE.clear()
        except Exception:
            pass
        try:
            ONLINE_DEDUP.clear()
        except Exception:
            pass

        rows: List[Dict[str, Any]] = []
        for case in _characterization_cases():
            name = str(case.get("name") or "").strip() or "case"
            kind = str(case.get("kind") or "").strip() or ""
            if isinstance(case.get("setup"), dict):
                for k, v in case.get("setup").items():
                    TRACKER_STATE[str(k)] = v
            if kind == "emit":
                sp = case.get("signal_payload") if isinstance(case.get("signal_payload"), dict) else {}
                trig = bool(case.get("trigger", False))
                dat = case.get("data") if isinstance(case.get("data"), dict) else {}
                resp = _emit_signal_v1(dict(sp), bool(trig), dict(dat))
                evt_id = str((sp.get("event_id") if isinstance(sp, dict) else None) or "")
                evt = EVENTS.get(evt_id) if evt_id else None
                rec = {"name": name, "kind": "emit", "resp": _characterization_obj_canonicalize(resp), "event": _characterization_obj_canonicalize(evt)}
                rows.append(rec)
            elif kind == "decision":
                dreq = case.get("dreq") if isinstance(case.get("dreq"), dict) else {}
                eid = str(dreq.get("event_id") or "").strip()
                if eid and isinstance(case.get("event_stub"), dict):
                    st = dict(case.get("event_stub") or {})
                    st["id"] = eid
                    st["event_id"] = eid
                    st["ts"] = int(fixed_now_ms)
                    st["ingested_ms"] = int(fixed_now_ms)
                    st["pair"] = str(dreq.get("pair") or st.get("pair") or "BTC/USDT")
                    st["side"] = str(dreq.get("side") or st.get("side") or "long")
                    st["tag"] = dreq.get("tag")
                    st["features"] = dict(dreq.get("features") or {})
                    EVENTS[eid] = st
                out, code = _decision_entry_impl(dict(dreq))
                rec = {"name": name, "kind": "decision", "code": int(code), "out": _characterization_obj_canonicalize(out)}
                rows.append(rec)
        return {"ok": True, "ts": int(fixed_now_ms), "suite_id": suite_id, "cases": rows}
    finally:
        try:
            if _ctx_prev_fixed_now is _MISSING:
                try:
                    delattr(_RUNTIME_CTX, "fixed_now_ms")
                except Exception:
                    pass
            else:
                _RUNTIME_CTX.fixed_now_ms = _ctx_prev_fixed_now
            if _ctx_prev_id_counter is _MISSING:
                try:
                    delattr(_RUNTIME_CTX, "id_counter")
                except Exception:
                    pass
            else:
                _RUNTIME_CTX.id_counter = _ctx_prev_id_counter
        except Exception:
            pass
        try:
            _characterization_exclusive_dec()
        except Exception:
            pass
        CONFIG.clear()
        CONFIG.update(orig_config)
        EVENTS.clear()
        EVENTS.update(orig_events)
        ORDERS.clear()
        ORDERS.update(orig_orders)
        TRACKER_STATE.clear()
        TRACKER_STATE.update(orig_tracker)
        try:
            ACTIVE_MODEL.clear()
            ACTIVE_MODEL.update(orig_active_model)
        except Exception:
            pass
        try:
            ARENA_STATE.clear()
            ARENA_STATE.update(orig_arena_state)
        except Exception:
            pass
        try:
            ELASTIC_STATE.clear()
            ELASTIC_STATE.update(orig_elastic_state)
        except Exception:
            pass
        try:
            CALIBRATOR.clear()
            CALIBRATOR.update(orig_calibrator)
        except Exception:
            pass
        try:
            SCALER.clear()
            SCALER.update(orig_scaler)
        except Exception:
            pass
        try:
            DYNAMIC_THRESHOLDS.clear()
            DYNAMIC_THRESHOLDS.update(orig_dyn_thr)
        except Exception:
            pass
        try:
            with SIGNAL_DEDUP_LOCK:
                SIGNAL_DEDUP.clear()
                SIGNAL_DEDUP.update(orig_signal_dedup)
                SIGNAL_DEDUP_V1_BASE.clear()
                SIGNAL_DEDUP_V1_BASE.update(orig_signal_dedup_base)
        except Exception:
            pass
        try:
            ONLINE_DEDUP.clear()
            for x in orig_online_dedup:
                ONLINE_DEDUP.add(x)
        except Exception:
            pass

def _characterization_baseline_load() -> Optional[Dict[str, Any]]:
    p = _characterization_baseline_path()
    if not p.exists() or (not p.is_file()):
        return None
    try:
        with open(p, "r", encoding="utf-8") as f:
            obj = json.load(f)
        return (obj if isinstance(obj, dict) else None)
    except Exception:
        return None

def _characterization_baseline_write(baseline: Dict[str, Any]) -> Dict[str, Any]:
    p = _characterization_baseline_path()
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    tmp = str(p) + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(baseline, f, ensure_ascii=False)
        os.replace(tmp, p)
        return {"ok": True, "path": str(p)}
    except Exception as e:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass
        return {"ok": False, "error": str(e), "path": str(p)}

def _characterization_compare_current_to_baseline(*, fixed_now_ms: int) -> Tuple[Dict[str, Any], int]:
    base = _characterization_baseline_load()
    if base is None:
        return {"ok": False, "error": "characterization_baseline_not_found", "path": str(_characterization_baseline_path())}, 404
    cur = _characterization_suite_run(fixed_now_ms=int(fixed_now_ms))
    if not bool(cur.get("ok")):
        return {"ok": False, "error": "characterization_suite_failed", "current": cur}, 500
    exp = _characterization_obj_canonicalize(base.get("suite"))
    got = _characterization_obj_canonicalize(cur)
    diffs = _characterization_deep_diff(exp, got, "")
    try:
        max_d = int(CONFIG.get("characterization_max_diffs", 50) or 50)
    except Exception:
        max_d = 50
    max_d = max(1, min(500, int(max_d)))
    out = {"ok": (not bool(diffs)), "ts": int(_now_ms()), "suite_id": _characterization_suite_id(), "path": str(_characterization_baseline_path()), "diffs": diffs[:max_d], "diff_count": int(len(diffs)), "baseline_meta": (base.get("meta") if isinstance(base.get("meta"), dict) else {})}
    return out, (200 if out["ok"] else 400)

def _characterization_gate_check_or_error(*, action: str, config_keys: Optional[List[str]] = None) -> Tuple[Optional[Dict[str, Any]], Optional[int]]:
    if not _characterization_gate_should_run(action=str(action), config_keys=config_keys):
        return None, None
    out, code = _characterization_compare_current_to_baseline(fixed_now_ms=1_700_000_000_000)
    if int(code) == 200 and bool(out.get("ok")):
        return None, None
    err = {"ok": False, "error": "characterization_gate_failed", "action": str(action), "result": out}
    return err, (400 if int(code) != 404 else 412)

def _load_user_env() -> None:
    try:
        from dotenv import load_dotenv
    except Exception:
        return
    try:
        p = _user_data_dir() / ".env"
        if p.exists():
            load_dotenv(dotenv_path=str(p), override=False)
    except Exception:
        pass

_load_user_env()

_ENV_RELOAD_LOCK = threading.Lock()

def _parse_dotenv_file(path: Path) -> Dict[str, str]:
    out: Dict[str, str] = {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            for raw in f:
                line = str(raw).strip()
                if not line:
                    continue
                if line.startswith("#"):
                    continue
                if line.startswith("export "):
                    line = line[len("export "):].strip()
                if "=" not in line:
                    continue
                k, v = line.split("=", 1)
                k = str(k).strip()
                v = str(v).strip()
                if not k:
                    continue
                if (len(v) >= 2) and ((v[0] == v[-1]) and (v[0] in ("\"", "'"))):
                    v = v[1:-1]
                out[k] = v
    except Exception:
        return {}
    return out

def _reload_dotenv_runtime(override: bool = True, prune: bool = False) -> Dict[str, Any]:
    ts = _now_ms()
    prefixes = ("HYPERLIQUID_", "ASTER_", "DEX_", "AUTH_", "TWITTER_")
    candidates: List[Path] = []
    try:
        allow_project_dotenv = str(os.environ.get("ML_ALLOW_PROJECT_DOTENV", "") or "").strip().lower() in ("1", "true", "yes", "y", "on")
    except Exception:
        allow_project_dotenv = False
    try:
        strict_user_dotenv = str(os.environ.get("ML_STRICT_USER_DOTENV", "") or "").strip().lower() in ("1", "true", "yes", "y", "on")
    except Exception:
        strict_user_dotenv = False
    try:
        candidates.append(_user_data_dir() / ".env")
    except Exception:
        pass

    allow_fallback = bool(allow_project_dotenv)
    if (not allow_fallback) and (not strict_user_dotenv):
        try:
            allow_fallback = not (_user_data_dir() / ".env").exists()
        except Exception:
            allow_fallback = True

    if allow_fallback:
        try:
            candidates.append(Path(os.path.dirname(__file__)) / ".env")
        except Exception:
            pass
        try:
            candidates.append(Path(os.getcwd()) / ".env")
        except Exception:
            pass

    seen: set = set()
    sources: List[str] = []
    merged: Dict[str, str] = {}
    for p in candidates:
        try:
            rp = p.resolve()
        except Exception:
            rp = p
        if str(rp) in seen:
            continue
        seen.add(str(rp))
        try:
            if not p.exists():
                continue
        except Exception:
            continue
        kv = _parse_dotenv_file(p)
        if kv:
            sources.append(str(p))
            merged.update(kv)

    updated: List[str] = []
    pruned: List[str] = []

    target_keys = [k for k in merged.keys() if str(k).startswith(prefixes)]
    for k in sorted(target_keys):
        v = str(merged.get(k) or "")
        if (not override) and (k in os.environ):
            continue
        os.environ[k] = v
        updated.append(k)

    if prune:
        keep = set(target_keys)
        to_del = [k for k in os.environ.keys() if str(k).startswith(prefixes) and (k not in keep)]
        for k in sorted(to_del):
            try:
                del os.environ[k]
                pruned.append(k)
            except Exception:
                pass

    try:
        HL_STATE["exchange"] = None
        HL_STATE["account"] = None
        HL_STATE["vault"] = None
        HL_STATE.pop("pk_fp", None)
        HL_STATE.pop("sz_decimals", None)
        HL_STATE.pop("max_leverage", None)
    except Exception:
        pass

    return {"ok": True, "ts": int(ts), "sources": sources, "updated": updated, "pruned": pruned}

def _append_jsonl(path: Path, obj: Dict[str, Any]) -> None:
    try:
        if _governance_is_test_mode():
            return
    except Exception:
        pass
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with open(path, "a", encoding="utf-8") as f:
            f.write(json.dumps(_json_sanitize(obj), ensure_ascii=False) + "\n")
    except Exception:
        pass


def _tail_lines(path: Path, max_lines: int, max_bytes: int = 2000000) -> List[str]:
    try:
        max_lines = int(max_lines)
    except Exception:
        max_lines = 2000
    max_lines = max(1, min(20000, int(max_lines)))
    try:
        max_bytes = int(max_bytes)
    except Exception:
        max_bytes = 2000000
    max_bytes = max(1024, min(20000000, int(max_bytes)))

    try:
        with open(path, "rb") as f:
            f.seek(0, os.SEEK_END)
            end = int(f.tell())
            pos = int(end)
            buf = b""
            while pos > 0 and (end - pos) < max_bytes and buf.count(b"\n") <= max_lines:
                step = min(65536, pos)
                pos -= step
                f.seek(pos)
                buf = f.read(step) + buf
            txt = buf.decode("utf-8", errors="ignore")
            lines = [x for x in txt.splitlines() if (x or "").strip()]
            if len(lines) > max_lines:
                lines = lines[-max_lines:]
            return lines
    except Exception:
        return []

def _tail_lines_gzip(path: Path, max_lines: int) -> List[str]:
    try:
        max_lines = int(max_lines)
    except Exception:
        max_lines = 2000
    max_lines = max(1, min(20000, int(max_lines)))
    try:
        from collections import deque
        q = deque(maxlen=int(max_lines))
        with gzip.open(path, "rt", encoding="utf-8", errors="ignore") as f:
            for line in f:
                s = (line or "").strip()
                if not s:
                    continue
                q.append(s)
        return list(q)
    except Exception:
        return []


def _runtime_protect_dir() -> Path:
    try:
        p = (Path(os.path.dirname(__file__)) / "backups" / "runtime_protect").resolve(strict=False)
    except Exception:
        p = Path(os.path.dirname(__file__)) / "backups" / "runtime_protect"
    try:
        p.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    return p


def _runtime_backup_file(src: Path, *, now_ms: int, stem: str, max_keep: int = 50) -> Optional[str]:
    sp = Path(src)
    if (not sp.exists()) or (not sp.is_file()):
        return None
    d = _runtime_protect_dir()
    try:
        dt = datetime.fromtimestamp(int(now_ms) / 1000.0, tz=timezone.utc)
    except Exception:
        dt = datetime.now(timezone.utc)
    ts = dt.strftime("%Y%m%d_%H%M%S")
    uid = uuid.uuid4().hex[:8]
    name = f"{str(stem)}_{ts}_{uid}.bak"
    dp = d / name
    try:
        shutil.copy2(sp, dp)
    except Exception:
        return None
    try:
        max_keep = int(max_keep)
    except Exception:
        max_keep = 50
    max_keep = max(1, min(500, int(max_keep)))
    try:
        items = [p for p in d.glob(f"{str(stem)}_*.bak") if p.is_file()]
        items.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        for p in items[max_keep:]:
            try:
                p.unlink()
            except Exception:
                pass
    except Exception:
        pass
    return str(dp)


def _should_backup_before_overwrite(old_size: int, new_size: int) -> bool:
    try:
        old_size = int(old_size)
        new_size = int(new_size)
    except Exception:
        return False
    if old_size <= 0:
        return False
    if new_size <= 0:
        return True
    if old_size >= 10000 and new_size <= max(2000, int(old_size * 0.2)):
        return True
    if old_size >= 2000 and new_size <= 512:
        return True
    return False
def _snapshot_tracker_state_write(now_ms: int) -> None:
    try:
        p = _user_data_dir() / "tracker_state.json"
        try:
            max_gh = int(CONFIG.get("gate_history_max", 5000) or 5000)
        except Exception:
            max_gh = 5000
        max_gh = max(0, min(50000, int(max_gh)))
        gh = TRACKER_STATE.get("gate_history")
        if not isinstance(gh, list):
            gh = []
        gh_out = list(gh)
        if max_gh > 0 and len(gh_out) > max_gh:
            gh_out = gh_out[-max_gh:]
        try:
            cap_sett = int(CONFIG.get("ab_settlement_history_max", 10000) or 10000)
        except Exception:
            cap_sett = 10000
        cap_sett = max(0, min(200000, int(cap_sett)))
        ab_sett = TRACKER_STATE.get("ab_settlements")
        if not isinstance(ab_sett, list):
            ab_sett = []
        ab_sett_out = list(ab_sett)
        if cap_sett > 0 and len(ab_sett_out) > cap_sett:
            ab_sett_out = ab_sett_out[-cap_sett:]
        exit_settled = TRACKER_STATE.get("exit_settled")
        if not isinstance(exit_settled, dict):
            exit_settled = {}
        eval_hist_cap = _eval_history_max()
        eval_history_out = list(EVAL_HISTORY)
        if eval_hist_cap > 0 and len(eval_history_out) > eval_hist_cap:
            eval_history_out = eval_history_out[-eval_hist_cap:]
        data = {
            "ts": int(now_ms),
            "open_positions": dict(TRACKER_STATE.get("open_positions") or {}),
            "carry_open_positions": dict(TRACKER_STATE.get("carry_open_positions") or {}),
            "quant_open_positions": dict(TRACKER_STATE.get("quant_open_positions") or {}),
            "three_screen_open_positions": dict(TRACKER_STATE.get("three_screen_open_positions") or {}),
            "cooldowns": dict(TRACKER_STATE.get("cooldowns") or {}),
            "post_close_cooldowns": dict(TRACKER_STATE.get("post_close_cooldowns") or {}),
            "strategy_perf": dict(TRACKER_STATE.get("strategy_perf") or {}),
            "daily_pnl": _json_sanitize(dict(TRACKER_STATE.get("daily_pnl") or {})),
            "weekly_pnl": _json_sanitize(dict(TRACKER_STATE.get("weekly_pnl") or {})),
            "loss_ladder": _json_sanitize(dict(TRACKER_STATE.get("loss_ladder") or {})),
            "gate_history": _json_sanitize(gh_out),
            "ab_settlements": _json_sanitize(ab_sett_out),
            "exit_settled": _json_sanitize(dict(exit_settled)),
            "p1_exec": _json_sanitize(dict(_p1_exec_state())),
            "carry_funding_ledger": _json_sanitize(list(TRACKER_STATE.get("carry_funding_ledger") or [])[-5000:]),
            "carry_funding_ledger_seen": _json_sanitize(dict(TRACKER_STATE.get("carry_funding_ledger_seen") or {})),
            "btc_corr_threshold_review_auto": _json_sanitize(dict(TRACKER_STATE.get("btc_corr_threshold_review_auto") or {})),
            "evaluation_history": _json_sanitize(eval_history_out),
            "online_state": _json_sanitize(dict(ONLINE_STATE or {})),
        }
        payload = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
        try:
            old_size = int(p.stat().st_size) if p.exists() and p.is_file() else 0
        except Exception:
            old_size = 0
        try:
            new_size = int(len(payload.encode("utf-8")))
        except Exception:
            new_size = int(len(payload))
        if _should_backup_before_overwrite(int(old_size), int(new_size)):
            _runtime_backup_file(p, now_ms=int(now_ms), stem="tracker_state")
        tmp = str(p) + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(payload)
        os.replace(tmp, p)
    except Exception:
        pass

