        led = data.get("carry_funding_ledger") or []
        if isinstance(led, list) and (not isinstance(TRACKER_STATE.get("carry_funding_ledger"), list) or len(TRACKER_STATE.get("carry_funding_ledger") or []) == 0):
            TRACKER_STATE["carry_funding_ledger"] = list(led)[-5000:]

