def _archive_order(order: Dict[str, Any]) -> None:
    strict_real = False
    try:
        strict_real = bool(_book_isolation_enabled() and _book_isolation_enforce_write_strict_real_orders())
    except Exception:
        strict_real = False
    if strict_real:
        try:
            md = str(order.get("mode") or "").strip().lower()
        except Exception:
            md = ""
        if md == "real":
            try:
                vios = _order_isolation_violations_for_real_order(order)
            except Exception:
                vios = [{"type": "order_isolation_check_failed"}]
            if vios:
                try:
                    _book_isolation_record_violation({
                        "book_id": (None if order.get("book_id") is None else str(order.get("book_id"))),
                        "book_run_id": (None if order.get("book_run_id") is None else str(order.get("book_run_id"))),
                        "execution_account_id": (None if order.get("execution_account_id") is None else str(order.get("execution_account_id"))),
                        "venue": str(order.get("exchange") or order.get("venue") or "default"),
                        "violations": list(vios),
                        "context": {"src": "archive_order", "order_id": (None if order.get("id") is None else str(order.get("id")))},
                    })
                except Exception:
                    pass
                return
    try:
        _order_isolation_fixup_inplace(order)
    except Exception:
        pass
    try:
        ts = int(order.get("ts") or _now_ms())
    except Exception:
        ts = _now_ms()
    day = datetime.fromtimestamp(ts / 1000.0, tz=timezone.utc).strftime("%Y%m%d")
    p = _user_data_dir() / "datasets" / (day + "_orders.jsonl")
    _append_jsonl(p, order)
    try:
        _p1_exec_record_order_from_archive(order)
    except Exception:
        pass


def _orders_archive_backfill_isolation(max_files: int = 60) -> Dict[str, Any]:
    out = {"ok": True, "scanned_files": 0, "changed_files": 0, "changed_lines": 0}
    try:
        ds = _user_data_dir() / "datasets"
        if (not ds.exists()) or (not ds.is_dir()):
            return out
        files = [p for p in ds.glob("*_orders.jsonl") if p.is_file()]
        files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        files = files[: max(1, int(max_files))]
    except Exception:
        return out

    for p in files:
        try:
            out["scanned_files"] = int(out.get("scanned_files") or 0) + 1
        except Exception:
            pass
        tmp = str(p) + ".tmp"
        changed = False
        try:
            with open(p, "r", encoding="utf-8") as fin, open(tmp, "w", encoding="utf-8") as fout:
                for line in fin:
                    raw = line.rstrip("\n")
                    if not raw.strip():
                        fout.write("\n")
                        continue
                    try:
                        obj = json.loads(raw)
                    except Exception:
                        fout.write(raw + "\n")
                        continue
                    if not isinstance(obj, dict):
                        fout.write(raw + "\n")
                        continue
                    before = (
                        obj.get("book_id"),
                        obj.get("ab_owner"),
                        obj.get("system_id"),
                        obj.get("execution_account_id"),
                        obj.get("book_run_id"),
                    )
                    try:
                        _order_isolation_fixup_inplace(obj)
                    except Exception:
                        pass
                    after = (
                        obj.get("book_id"),
                        obj.get("ab_owner"),
                        obj.get("system_id"),
                        obj.get("execution_account_id"),
                        obj.get("book_run_id"),
                    )
                    if before != after:
                        changed = True
                        try:
                            out["changed_lines"] = int(out.get("changed_lines") or 0) + 1
                        except Exception:
                            pass
                    fout.write(json.dumps(obj, ensure_ascii=False) + "\n")
        except Exception:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except Exception:
                pass
            continue

        if changed:
            try:
                os.replace(tmp, p)
                out["changed_files"] = int(out.get("changed_files") or 0) + 1
            except Exception:
                try:
                    if os.path.exists(tmp):
                        os.remove(tmp)
                except Exception:
                    pass
        else:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except Exception:
                pass

    return out


