def _pair_to_base(pair: str) -> str:
    if not pair:
        return ""
    s = str(pair)
    s = s.replace("/", "_")
    s = s.replace(":", "_")
    u = s.upper()
    if u.endswith("-PERP"):
        coin = u[: -len("-PERP")]
        if coin and ("_" not in coin) and ("-" not in coin):
            return f"{coin}_USDT_USDT"
    if u.endswith("_PERP"):
        coin = u[: -len("_PERP")]
        if coin and ("_" not in coin) and ("-" not in coin):
            return f"{coin}_USDT_USDT"
    return u

_DATA_INDEX_LOCK = threading.Lock()

def _build_data_index():
    with _DATA_INDEX_LOCK:
        if DATA_INDEX:
            return
        for root in _data_dirs():
            for f in root.rglob("*-5m.json"):
                key = f.name.replace("-5m.json", "")
                DATA_INDEX_ALL.setdefault(key, []).append(f)
                if key not in DATA_INDEX:
                    DATA_INDEX[key] = f
            for f in root.rglob("*-5m-futures.json"):
                key = f.name.replace("-5m-futures.json", "")
                DATA_INDEX_ALL.setdefault(key, []).append(f)
                if key not in DATA_INDEX:
                    DATA_INDEX[key] = f
            for f in root.rglob("*-1h.json"):
                key = f.name.replace("-1h.json", "")
                DATA_INDEX_ALL.setdefault(key, []).append(f)
                if key not in DATA_INDEX:
                    DATA_INDEX[key] = f
            for f in root.rglob("*-1h-futures.json"):
                key = f.name.replace("-1h-futures.json", "")
                DATA_INDEX_ALL.setdefault(key, []).append(f)
                if key not in DATA_INDEX:
                    DATA_INDEX[key] = f
            for f in root.rglob("*-1d.json"):
                key = f.name.replace("-1d.json", "")
                DATA_INDEX_ALL.setdefault(key, []).append(f)
                if key not in DATA_INDEX:
                    DATA_INDEX[key] = f
            for f in root.rglob("*-1d-futures.json"):
                key = f.name.replace("-1d-futures.json", "")
                DATA_INDEX_ALL.setdefault(key, []).append(f)
                if key not in DATA_INDEX:
                    DATA_INDEX[key] = f


_PERP_AUTOFILL_GUARD = threading.Lock()
_PERP_AUTOFILL_LAST: Dict[str, int] = {}


def _data_index_register_file(f: Path) -> None:
    try:
        ff = Path(f)
    except Exception:
        return
    try:
        if not ff.exists() or (not ff.is_file()):
            return
    except Exception:
        return
    nm = str(ff.name)
    key = None
    if nm.endswith("-5m-futures.json"):
        key = nm.replace("-5m-futures.json", "")
    elif nm.endswith("-5m.json"):
        key = nm.replace("-5m.json", "")
    elif nm.endswith("-1h-futures.json"):
        key = nm.replace("-1h-futures.json", "")
    elif nm.endswith("-1h.json"):
        key = nm.replace("-1h.json", "")
    elif nm.endswith("-1d-futures.json"):
        key = nm.replace("-1d-futures.json", "")
    elif nm.endswith("-1d.json"):
        key = nm.replace("-1d.json", "")
    if not key:
        return
    try:
        DATA_INDEX_ALL.setdefault(str(key), []).append(ff)
    except Exception:
        pass
    try:
        cur = DATA_INDEX.get(str(key))
        if cur is None:
            DATA_INDEX[str(key)] = ff
        else:
            cur_s = str(cur).lower()
            new_s = str(ff).lower()
            if ("-5m-futures.json" in new_s) and ("-5m-futures.json" not in cur_s):
                DATA_INDEX[str(key)] = ff
            elif ("-5m.json" in new_s) and ("-5m.json" not in cur_s) and ("-5m-futures.json" not in cur_s):
                DATA_INDEX[str(key)] = ff
    except Exception:
        pass


def _perp_coin_from_pair(pair: str) -> str:
    u = str(pair or "").upper().strip()
    if not u:
        return ""
    if u.endswith("-PERP"):
        c = u[: -len("-PERP")]
        if c and ("_" not in c) and ("-" not in c) and (":" not in c) and ("/" not in c):
            return c
    if u.endswith("_PERP"):
        c = u[: -len("_PERP")]
        if c and ("_" not in c) and ("-" not in c) and (":" not in c) and ("/" not in c):
            return c
    base = _pair_to_base(u)
    if not base:
        return ""
    return str(base.split("_")[0] or "").upper().strip()


def _perp_5m_file_path(pair: str) -> Optional[Path]:
    base = _pair_to_base(pair)
    if not base:
        return None
    ex = str(CONFIG.get("perp_5m_autofill_exchange", "hyperliquid") or "hyperliquid").strip().lower()
    if not ex:
        ex = "hyperliquid"
    return _user_data_dir() / "data" / ex / "futures" / f"{base}-5m-futures.json"


def _write_json_atomic(path: Path, obj: Any) -> bool:
    p = Path(path)
    tmp = str(p) + ".tmp"
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, separators=(",", ":"))
            f.write("\n")
        os.replace(tmp, str(p))
        return True
    except Exception:
        try:
            if os.path.exists(tmp):
                os.unlink(tmp)
        except Exception:
            pass
        return False


def _ensure_perp_5m_data(pair: str, ts_ms: int = None, *, force: bool = False) -> Dict[str, Any]:
    try:
        enabled = bool(CONFIG.get("perp_5m_autofill_enabled", True))
    except Exception:
        enabled = True
    if not enabled:
        return {"ok": True, "updated": False, "enabled": False}

    p = _perp_5m_file_path(pair)
    if p is None:
        return {"ok": True, "updated": False, "enabled": True, "skipped": "bad_pair"}

    try:
        now_ms = int(ts_ms) if ts_ms is not None else int(_now_ms())
    except Exception:
        now_ms = int(_now_ms())

    coin = _perp_coin_from_pair(pair)
    if not coin:
        return {"ok": True, "updated": False, "enabled": True, "skipped": "bad_coin"}

    try:
        lookback_days = int(CONFIG.get("perp_5m_autofill_lookback_days", CONFIG.get("candles_sync_lookback_days", 30)) or 30)
    except Exception:
        lookback_days = 30
    lookback_days = max(1, min(3650, int(lookback_days)))
    lookback_ms = int(lookback_days) * 24 * 3600 * 1000

    try:
        max_rows = int(CONFIG.get("perp_5m_autofill_max_rows", 250000) or 250000)
    except Exception:
        max_rows = 250000
    max_rows = max(1000, min(2000000, int(max_rows)))
    try:
        min_keep_days = max(90, int(lookback_days))
    except Exception:
        min_keep_days = 90
    min_keep_days = max(1, min(3650, int(min_keep_days)))
    try:
        min_rows_needed = int(min_keep_days) * 288 + 288
    except Exception:
        min_rows_needed = 90 * 288 + 288
    min_rows_needed = max(1000, min(2000000, int(min_rows_needed)))
    if int(max_rows) < int(min_rows_needed):
        max_rows = int(min_rows_needed)

    try:
        max_stale_bars = int(CONFIG.get("perp_5m_autofill_max_stale_bars", 6) or 6)
    except Exception:
        max_stale_bars = 6
    max_stale_bars = max(1, min(500, int(max_stale_bars)))

    try:
        min_cover_bars = int(CONFIG.get("perp_5m_autofill_min_cover_bars", 24) or 24)
    except Exception:
        min_cover_bars = 24
    min_cover_bars = max(0, min(20000, int(min_cover_bars)))

    interval_ms = 5 * 60 * 1000
    need = bool(force)
    existing_rows: List[List[float]] = []
    try:
        if p.exists() and p.is_file():
            existing_rows = _read_5m_rows(p)
    except Exception:
        existing_rows = []
    if (not need) and (not existing_rows):
        need = True
    if (not need) and existing_rows:
        try:
            lo = int(existing_rows[0][0])
            hi = int(existing_rows[-1][0])
        except Exception:
            lo = 0
            hi = 0
        if hi <= 0:
            need = True
        else:
            if int(now_ms) - int(hi) > int(max_stale_bars) * int(interval_ms):
                need = True
            if ts_ms is not None:
                t = int(ts_ms)
                if t < lo or t > hi:
                    need = True
                elif min_cover_bars > 0:
                    if t - lo < int(min_cover_bars) * int(interval_ms):
                        need = True
                    if hi - t < int(min_cover_bars) * int(interval_ms):
                        need = True
    if not need:
        try:
            _data_index_register_file(p)
        except Exception:
            pass
        return {"ok": True, "updated": False, "enabled": True, "path": str(p)}

    base_key = _pair_to_base(pair)
    try:
        lock_sec = int(CONFIG.get("perp_5m_autofill_lock_seconds", 30) or 30)
    except Exception:
        lock_sec = 30
    lock_sec = max(0, min(3600, int(lock_sec)))
    with _PERP_AUTOFILL_GUARD:
        last = int(_PERP_AUTOFILL_LAST.get(str(base_key), 0) or 0)
        if lock_sec > 0 and last > 0 and (int(now_ms) - int(last)) < int(lock_sec) * 1000:
            return {"ok": True, "updated": False, "enabled": True, "path": str(p), "skipped": "rate_limited"}
        _PERP_AUTOFILL_LAST[str(base_key)] = int(now_ms)

    try:
        rows = _hl_fetch_ohlcv_rows_cached(coin=coin, interval="5m", now_ms=int(now_ms), lookback_ms=int(lookback_ms), ttl_sec=10)
    except Exception as e:
        return {"ok": False, "updated": False, "enabled": True, "path": str(p), "error": str(e)}

    if not isinstance(rows, list) or not rows:
        return {"ok": True, "updated": False, "enabled": True, "path": str(p), "skipped": "no_rows"}

    merged: Dict[int, List[float]] = {}
    for r in existing_rows:
        if not isinstance(r, (list, tuple)) or len(r) < 6:
            continue
        try:
            ts = int(r[0])
        except Exception:
            continue
        merged[int(ts)] = [float(r[0]), float(r[1]), float(r[2]), float(r[3]), float(r[4]), float(r[5])]
    for r in rows:
        if not isinstance(r, (list, tuple)) or len(r) < 6:
            continue
        try:
            ts = int(r[0])
        except Exception:
            continue
        try:
            merged[int(ts)] = [float(r[0]), float(r[1]), float(r[2]), float(r[3]), float(r[4]), float(r[5])]
        except Exception:
            continue

    ts_sorted = sorted(merged.keys())
    if not ts_sorted:
        return {"ok": True, "updated": False, "enabled": True, "path": str(p), "skipped": "merge_empty"}
    if max_rows > 0 and len(ts_sorted) > int(max_rows):
        ts_sorted = ts_sorted[-int(max_rows):]
    out_rows = [merged[int(ts)] for ts in ts_sorted]
    ok = _write_json_atomic(p, out_rows)
    if ok:
        _data_index_register_file(p)
        try:
            if isinstance(DATA_INDEX_ALL.get(str(base_key)), list):
                uniq = []
                seen = set()
                for x in DATA_INDEX_ALL.get(str(base_key), []) or []:
                    sx = str(x)
                    if sx in seen:
                        continue
                    seen.add(sx)
                    uniq.append(x)
                DATA_INDEX_ALL[str(base_key)] = uniq
        except Exception:
            pass
        return {"ok": True, "updated": True, "enabled": True, "path": str(p), "rows": int(len(out_rows))}
    return {"ok": False, "updated": False, "enabled": True, "path": str(p), "skipped": "write_failed"}


def _coin_from_symbol_like(sym: str) -> str:
    s = str(sym or "").upper().strip()
    if not s:
        return ""
    s = s.replace("/", "").replace(":", "").replace("_", "").replace("-", "")
    for q in ("USDT", "USDC", "USD"):
        if s.endswith(q) and len(s) > len(q):
            return s[: -len(q)]
    if s.endswith("PERP") and len(s) > 4:
        return s[:-4]
    return ""


def _candles_sync_pairs() -> List[str]:
    coins: List[str] = []
    try:
        for c in (UNIVERSE_STATE.get("core") or []):
            cc = str(c or "").upper().strip()
            if cc:
                coins.append(cc)
    except Exception:
        pass
    try:
        for p in (TRACKER_STATE.get("open_positions") or {}).keys():
            cc = _perp_coin_from_pair(str(p))
            if cc:
                coins.append(cc)
    except Exception:
        pass
    try:
        for x in (CONFIG.get("trade_whitelist") or []):
            cc = _coin_from_symbol_like(str(x))
            if cc:
                coins.append(cc)
    except Exception:
        pass
    try:
        ex = CONFIG.get("exchange") if isinstance(CONFIG.get("exchange"), dict) else {}
        for x in (ex.get("pair_whitelist") or []):
            cc = _coin_from_symbol_like(str(x))
            if cc:
                coins.append(cc)
    except Exception:
        pass
    uniq: List[str] = []
    seen = set()
    for c in coins:
        if not c:
            continue
        if c in seen:
            continue
        seen.add(c)
        uniq.append(c)
    return [f"{c}-PERP" for c in uniq]


def _candles_sync_tick(now_ms: int) -> Dict[str, Any]:
    out: Dict[str, Any] = {"ok": True, "enabled": bool(CONFIG.get("candles_sync_enabled", True)), "ts": int(now_ms), "pairs": 0, "updated": 0, "errors": 0, "results": []}
    if not bool(out.get("enabled")):
        return out
    try:
        max_pairs = int(CONFIG.get("candles_sync_max_pairs_per_run", 80) or 80)
    except Exception:
        max_pairs = 80
    max_pairs = max(0, min(500, int(max_pairs)))
    pairs = _candles_sync_pairs()
    if max_pairs > 0:
        pairs = pairs[:max_pairs]
    out["pairs"] = int(len(pairs))
    results: List[Dict[str, Any]] = []
    for pair in pairs:
        try:
            r = _ensure_perp_5m_data(str(pair), ts_ms=int(now_ms), force=False)
            if bool(r.get("updated")):
                out["updated"] = int(out.get("updated") or 0) + 1
            results.append({"pair": str(pair), **({k: r.get(k) for k in ("ok", "updated", "rows", "skipped", "error", "path") if k in r})})
        except Exception as e:
            out["errors"] = int(out.get("errors") or 0) + 1
            results.append({"pair": str(pair), "ok": False, "error": str(e)})
    out["results"] = results[:200]
    return out

def _find_pair_file(pair: str) -> Path:
    _build_data_index()
    want_futures = (":" in str(pair or "")) or (str(CONFIG.get("trading_mode") or "").lower() == "futures") or bool(_perp_coin_from_pair(str(pair or "")))
    ex_name = str(((CONFIG.get("exchange") or {}).get("name") if isinstance(CONFIG.get("exchange"), dict) else "") or "").lower()
    base = _pair_to_base(str(pair or ""))
    candidates = []
    if base:
        candidates.extend(DATA_INDEX_ALL.get(base, []) or [])
    if base:
        prefix = base.split("_")[0]
        for k, vs in DATA_INDEX_ALL.items():
            if str(k).startswith(prefix):
                candidates.extend(vs or [])

    if not candidates:
        return None

    def _score_path(p: Path) -> int:
        s = 0
        ps = str(p).lower()
        if ps.endswith("-5m-futures.json"):
            s += 90
        elif ps.endswith("-5m.json"):
            s += 80
        elif ps.endswith("-1h-futures.json"):
            s += 60
        elif ps.endswith("-1h.json"):
            s += 50
        elif ps.endswith("-1d-futures.json"):
            s += 30
        elif ps.endswith("-1d.json"):
            s += 20
        if want_futures and "futures" in ps:
            s += 40
        if "/hyperliquid/" in ps or "\\hyperliquid\\" in ps:
            s += 18
        if ex_name and ex_name in ps:
            s += 12
        if "/gateio/" in ps or "\\gateio\\" in ps:
            s += 5
        if "/gate/" in ps or "\\gate\\" in ps:
            s += 2
        if "/binance/" in ps or "\\binance\\" in ps:
            s += 1
        return int(s)

    candidates = sorted(candidates, key=lambda p: (-_score_path(p), str(p)))
    return candidates[0]

def _find_pair_files(pair: str) -> List[Path]:
    _build_data_index()
    base = _pair_to_base(pair)
    cands: List[Path] = []
    if base:
        exact = DATA_INDEX_ALL.get(base, []) or []
        if exact:
            cands.extend(exact)
        else:
            prefix = base.split("_")[0]
            for k, vs in DATA_INDEX_ALL.items():
                if str(k).startswith(prefix):
                    cands.extend(vs or [])

    seen = set()
    out: List[Path] = []
    for p in cands:
        sp = str(p)
        if sp in seen:
            continue
        seen.add(sp)
        out.append(p)
    return out

def _read_5m_rows(path: Path) -> List[List[float]]:
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return json.load(fh)
    except Exception:
        return []

def _get_pair_cache(pair: str, ts_ms: int = None) -> Dict[str, Any]:
    pair_s = str(pair or "")
    want_futures = (":" in pair_s) or (str(CONFIG.get("trading_mode") or "").lower() == "futures") or bool(_perp_coin_from_pair(pair_s))
    ex_name = str(((CONFIG.get("exchange") or {}).get("name") if isinstance(CONFIG.get("exchange"), dict) else "") or "").lower()
    if want_futures:
        try:
            _ensure_perp_5m_data(pair, ts_ms=int(ts_ms) if ts_ms is not None else None, force=False)
        except Exception:
            pass
    candidates = _find_pair_files(pair)
    if not candidates:
        if want_futures:
            try:
                _ensure_perp_5m_data(pair, ts_ms=int(ts_ms) if ts_ms is not None else None, force=False)
            except Exception:
                pass
            candidates = _find_pair_files(pair)
        if not candidates:
            return {}

    def _score_path(p: Path) -> int:
        s = 0
        ps = str(p).lower()
        if ps.endswith("-5m-futures.json"):
            s += 90
        elif ps.endswith("-5m.json"):
            s += 80
        elif ps.endswith("-1h-futures.json"):
            s += 60
        elif ps.endswith("-1h.json"):
            s += 50
        elif ps.endswith("-1d-futures.json"):
            s += 30
        elif ps.endswith("-1d.json"):
            s += 20
        if want_futures and "futures" in ps:
            s += 40
        if "/hyperliquid/" in ps or "\\hyperliquid\\" in ps:
            s += 18
        if ex_name and ex_name in ps:
            s += 12
        if "/gateio/" in ps or "\\gateio\\" in ps:
            s += 5
        if "/gate/" in ps or "\\gate\\" in ps:
            s += 2
        if "/binance/" in ps or "\\binance\\" in ps:
            s += 1
        return int(s)

    candidates = sorted(candidates, key=lambda p: (-_score_path(p), str(p)))

    chosen: Optional[Path] = None
    if ts_ms is None:
        chosen = candidates[0]
    else:
        t = int(ts_ms)
        for p in candidates:
            key = str(p)
            cached = PAIR_CACHE.get(key)
            if cached and isinstance(cached.get("raw_ts"), list) and cached.get("raw_ts"):
                try:
                    lo = int(cached["raw_ts"][0])
                    hi = int(cached["raw_ts"][-1])
                    if lo <= t <= hi:
                        chosen = p
                        break
                except Exception:
                    pass

            raw = _read_5m_rows(p)
            if not raw:
                continue
            try:
                lo = int(raw[0][0])
                hi = int(raw[-1][0])
                if lo <= t <= hi:
                    chosen = p
                    break
            except Exception:
                continue
        if chosen is None and want_futures:
            try:
                _ensure_perp_5m_data(pair, ts_ms=int(t), force=False)
            except Exception:
                pass
            try:
                candidates2 = _find_pair_files(pair)
                if candidates2:
                    candidates = sorted(candidates2, key=lambda p: (-_score_path(p), str(p)))
            except Exception:
                pass
            for p in candidates:
                raw = _read_5m_rows(p)
                if not raw:
                    continue
                try:
                    lo = int(raw[0][0])
                    hi = int(raw[-1][0])
                    if lo <= t <= hi:
                        chosen = p
                        break
                except Exception:
                    continue
        if chosen is None:
            chosen = candidates[0]

    p = chosen
    key = str(p)
    try:
        mtime = float(p.stat().st_mtime)
    except Exception:
        mtime = 0.0
    cached = PAIR_CACHE.get(key)
    if cached and float(cached.get("mtime", 0.0)) == mtime:
        return cached
    raw = _read_5m_rows(p)
    if not raw:
        PAIR_CACHE[key] = {"mtime": mtime, "raw_ts": [], "raw_close": [], "raw5": [], "hourly": [], "hourly_ts": [], "atr_pct_h": [], "di": {}}
        return PAIR_CACHE[key]
    try:
        raw5_tail = int(CONFIG.get("pair_cache_raw5_tail_bars", 2500) or 2500)
    except Exception:
        raw5_tail = 2500
    raw5_tail = max(0, min(20000, int(raw5_tail)))
    raw5 = raw[-raw5_tail:] if raw5_tail > 0 else []
    raw_ts = [int(r[0]) for r in raw]
    raw_close = [float(r[4]) for r in raw]
    hourly = _resample(raw, 60 * 60 * 1000)
    hourly_ts = [int(r[0]) for r in hourly]
    hourly_close = [float(r[4]) for r in hourly]
    hourly_logret: List[float] = []
    prev = None
    for px in hourly_close:
        if prev is None or px <= 0.0 or prev <= 0.0:
            hourly_logret.append(0.0)
        else:
            try:
                hourly_logret.append(float(math.log(float(px) / float(prev))))
            except Exception:
                hourly_logret.append(0.0)
        prev = px
    atr_pct_h: List[float] = []
    if len(hourly) >= 20:
        high = [float(r[2]) for r in hourly]
        low = [float(r[3]) for r in hourly]
        close = [float(r[4]) for r in hourly]
        atr = _atr(high, low, close, 14)
        for a, c in zip(atr, close):
            atr_pct_h.append((float(a) / float(c)) if float(c) > 0 else 0.0)
    daily = _resample(raw, 24 * 60 * 60 * 1000)
    di = _compute_daily_indicators(daily) if daily else {"ts": []}
    for k in ("ema_fast_d", "ema_slow_d", "ma_cross_fast_d", "ma_cross_slow_d", "rsi_d", "willr_d", "macd_d", "macdsignal_d", "macdhist_d"):
        if k in di and isinstance(di.get(k), list):
            di[k] = [0.0] + di[k][:-1]
    PAIR_CACHE[key] = {
        "mtime": mtime,
        "raw_ts": raw_ts,
        "raw_close": raw_close,
        "raw5": raw5,
        "hourly": hourly,
        "hourly_ts": hourly_ts,
        "hourly_close": hourly_close,
        "hourly_logret": hourly_logret,
        "atr_pct_h": atr_pct_h,
        "di": di,
    }
    return PAIR_CACHE[key]


def _q(xs: List[float], q: float) -> float:
    if not xs:
        return 0.0
    try:
        qq = float(q)
    except Exception:
        qq = 0.5
    qq = max(0.0, min(1.0, qq))
    ys = sorted(float(x) for x in xs)
    if len(ys) == 1:
        return float(ys[0])
    pos = qq * (len(ys) - 1)
    i0 = int(math.floor(pos))
    i1 = int(math.ceil(pos))
    i0 = max(0, min(len(ys) - 1, i0))
    i1 = max(0, min(len(ys) - 1, i1))
    if i0 == i1:
        return float(ys[i0])
    w = float(pos - i0)
    return float(ys[i0] * (1.0 - w) + ys[i1] * w)


def _audit_bar_closed_stats(limit: int = 2000, pair: Optional[str] = None) -> Dict[str, Any]:
    try:
        limit = int(limit)
    except Exception:
        limit = 2000
    limit = max(100, min(20000, int(limit)))

    events: List[Dict[str, Any]] = []
    try:
        events = [e for e in EVENTS.values() if isinstance(e, dict)]
    except Exception:
        events = []

    if len(events) < limit:
        try:
            ds = _user_data_dir() / "datasets"
            files = (
                [x for x in ds.glob("*_events.jsonl") if x.is_file()] +
                [x for x in ds.glob("*_events.jsonl.gz") if x.is_file()]
            ) if ds.exists() else []
            files.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        except Exception:
            files = []
        try:
            tail_bytes = int(CONFIG.get("events_archive_tail_bytes", 2000000) or 2000000)
        except Exception:
            tail_bytes = 2000000
        for fp in files[:3]:
            if len(events) >= limit:
                break
            lines = _tail_lines(fp, max_lines=max(100, limit - len(events)), max_bytes=tail_bytes)
            for s in reversed(lines):
                if len(events) >= limit:
                    break
                try:
                    evt = json.loads((s or "").strip())
                except Exception:
                    continue
                if isinstance(evt, dict):
                    events.append(evt)

    pair_n = None if pair is None else str(pair).strip().upper()
    if pair_n is not None and not pair_n:
        pair_n = None

    n = 0
    closed_true = 0
    closed_false = 0
    missing = 0
    by_strategy: Dict[str, Dict[str, int]] = {}

    for evt in events[:limit]:
        if not isinstance(evt, dict):
            continue
        if pair_n is not None:
            try:
                p0 = str(evt.get("pair") or "").strip().upper()
                if p0 and p0 != pair_n:
                    continue
            except Exception:
                continue
        n += 1
        sid = str(evt.get("strategy_id") or "").strip() or "__none__"
        if sid not in by_strategy:
            by_strategy[sid] = {"n": 0, "closed_false": 0, "missing": 0}
        by_strategy[sid]["n"] += 1
        bc = evt.get("bar_closed")
        if bc is None:
            missing += 1
            by_strategy[sid]["missing"] += 1
        else:
            if bool(bc):
                closed_true += 1
            else:
                closed_false += 1
                by_strategy[sid]["closed_false"] += 1

    rate_true = (float(closed_true) / float(n)) if n > 0 else 0.0
    out_by_strategy: Dict[str, Any] = {}
    for k, v in by_strategy.items():
        out_by_strategy[k] = {
            "n": int(v.get("n", 0)),
            "closed_false": int(v.get("closed_false", 0)),
            "missing": int(v.get("missing", 0)),
        }
    return {
        "n": int(n),
        "closed_true": int(closed_true),
        "closed_false": int(closed_false),
        "missing": int(missing),
        "rate_true": float(rate_true),
        "by_strategy": out_by_strategy,
    }


def _audit_data_quality(pair: str, start_ts_ms: int, end_ts_ms: int, max_points: int = 5000, ret_abs_thr: float = 0.10) -> Dict[str, Any]:
    p = _find_pair_file(pair)
    if p is None:
        return {"ok": False, "error": "pair_data_not_found", "pair": str(pair)}
    raw = _read_5m_rows(p)
    if not raw:
        return {"ok": False, "error": "pair_data_empty", "pair": str(pair), "file": str(p)}

    try:
        start_ts_ms = int(start_ts_ms)
        end_ts_ms = int(end_ts_ms)
    except Exception:
        return {"ok": False, "error": "bad_timerange", "pair": str(pair)}

    if end_ts_ms < start_ts_ms:
        start_ts_ms, end_ts_ms = end_ts_ms, start_ts_ms

    try:
        max_points = int(max_points)
    except Exception:
        max_points = 5000
    max_points = max(200, min(200000, int(max_points)))

    try:
        ret_abs_thr = float(ret_abs_thr)
    except Exception:
        ret_abs_thr = 0.10
    if (not math.isfinite(float(ret_abs_thr))) or float(ret_abs_thr) <= 0.0:
        ret_abs_thr = 0.10
    ret_abs_thr = float(min(0.80, max(0.01, float(ret_abs_thr))))

    try:
        data_start_ts = int(raw[0][0])
        data_end_ts = int(raw[-1][0])
    except Exception:
        data_start_ts = 0
        data_end_ts = 0

    beg = max(int(start_ts_ms), int(data_start_ts))
    end = min(int(end_ts_ms), int(data_end_ts) if int(data_end_ts) > 0 else int(end_ts_ms))
    if end <= beg:
        beg = int(max(0, min(int(start_ts_ms), int(end_ts_ms))))
        end = int(max(int(start_ts_ms), int(end_ts_ms)))

    rows: List[List[float]] = []
    for r in raw:
        try:
            t = int(r[0])
        except Exception:
            continue
        if t < beg or t > end:
            continue
        rows.append(r)

    if not rows:
        return {
            "ok": False,
            "error": "no_rows_in_range",
            "pair": str(pair),
            "file": str(p),
            "data_start_ts": int(data_start_ts),
            "data_end_ts": int(data_end_ts),
            "start_ts": int(start_ts_ms),
            "end_ts": int(end_ts_ms),
        }

    deltas: List[int] = []
    prev_ts = None
    for r in rows:
        try:
            t = int(r[0])
        except Exception:
            continue
        if prev_ts is not None:
            dt = int(t - prev_ts)
            if dt > 0:
                deltas.append(dt)
        prev_ts = t
    step_ms = int(_q([float(x) for x in deltas[: min(5000, len(deltas))]], 0.5)) if deltas else 300000
    if step_ms <= 0:
        step_ms = 300000

    expected_rows = int(((int(rows[-1][0]) - int(rows[0][0])) // int(step_ms)) + 1)
    if expected_rows <= 0:
        expected_rows = int(len(rows))
    missing_rows = int(max(0, expected_rows - int(len(rows))))
    missing_rate = float(missing_rows) / float(expected_rows) if expected_rows > 0 else 0.0

    gap_n = 0
    max_gap_ms = 0
    missing_bars_est = 0
    prev_ts = None
    for r in rows:
        try:
            t = int(r[0])
        except Exception:
            continue
        if prev_ts is not None:
            dt = int(t - prev_ts)
            if dt > int(step_ms * 1.5):
                gap_n += 1
                max_gap_ms = max(int(max_gap_ms), int(dt))
                missing_bars_est += max(0, int(round(float(dt) / float(step_ms))) - 1)
        prev_ts = t

    invalid: Dict[str, int] = {"ts": 0, "open": 0, "high": 0, "low": 0, "close": 0, "volume": 0}
    closes: List[float] = []
    vols: List[float] = []
    ts_list: List[int] = []
    for r in rows[:max_points]:
        if not isinstance(r, (list, tuple)) or len(r) < 6:
            continue
        try:
            t = int(r[0])
        except Exception:
            invalid["ts"] += 1
            continue
        ts_list.append(t)

        def _getf(i: int, k: str) -> float:
            try:
                v = float(r[i])
            except Exception:
                invalid[k] += 1
                return float("nan")
            if not math.isfinite(float(v)):
                invalid[k] += 1
                return float("nan")
            return float(v)

        o = _getf(1, "open")
        h = _getf(2, "high")
        l = _getf(3, "low")
        c0 = _getf(4, "close")
        v0 = _getf(5, "volume")
        if math.isfinite(c0) and c0 > 0:
            closes.append(float(c0))
        else:
            invalid["close"] += 1
        if math.isfinite(v0) and v0 >= 0:
            vols.append(float(v0))
        else:
            invalid["volume"] += 1
        if math.isfinite(o) and math.isfinite(h) and math.isfinite(l) and math.isfinite(c0):
            if float(h) < max(float(o), float(c0)) or float(l) > min(float(o), float(c0)):
                invalid["high"] += 1

    rets: List[float] = []
    for i in range(1, len(closes)):
        p0 = float(closes[i - 1])
        p1 = float(closes[i])
        if p0 <= 0:
            continue
        rr = (p1 - p0) / p0
        if math.isfinite(rr):
            rets.append(float(rr))

    ret_mean = float(sum(rets) / len(rets)) if rets else 0.0
    ret_std = 0.0
    if len(rets) >= 2:
        m = ret_mean
        var = sum((x - m) ** 2 for x in rets) / float(len(rets) - 1)
        ret_std = float(math.sqrt(max(0.0, var)))
    ret_p01 = _q(rets, 0.01)
    ret_p50 = _q(rets, 0.50)
    ret_p99 = _q(rets, 0.99)
    abs_p99 = _q([abs(x) for x in rets], 0.99)
    outlier_n = 0
    for x in rets:
        if abs(float(x)) >= float(ret_abs_thr):
            outlier_n += 1

    v_p50 = _q(vols, 0.50)
    v_p95 = _q(vols, 0.95)
    v_p99 = _q(vols, 0.99)
    v_zeros = 0
    for v in vols:
        if float(v) == 0.0:
            v_zeros += 1

    c = _get_pair_cache(pair, ts_ms=int(rows[len(rows) // 2][0]))
    hourly_ts = c.get("hourly_ts") or []
    di = c.get("di") or {}
    di_ts = di.get("ts") if isinstance(di, dict) else []

    def _offset_stats(base_ts: List[int], ref_ts: List[int]) -> Dict[str, Any]:
        offs: List[float] = []
        neg = 0
        for t in base_ts:
            try:
                idx = bisect_right(ref_ts, int(t)) - 1
            except Exception:
                idx = -1
            if idx < 0:
                continue
            try:
                rt = int(ref_ts[idx])
            except Exception:
                continue
            off = int(t - rt)
            if off < 0:
                neg += 1
            offs.append(float(off))
        return {
            "n": int(len(offs)),
            "negative_offsets": int(neg),
            "min_offset_ms": float(_q(offs, 0.0)) if offs else 0.0,
            "p50_offset_ms": float(_q(offs, 0.50)) if offs else 0.0,
            "p95_offset_ms": float(_q(offs, 0.95)) if offs else 0.0,
        }

    sample_ts = ts_list
    if len(sample_ts) > 2000:
        step = max(1, len(sample_ts) // 2000)
        sample_ts = sample_ts[::step]
    align_h = _offset_stats(sample_ts, hourly_ts if isinstance(hourly_ts, list) else [])
    align_d = _offset_stats(sample_ts, di_ts if isinstance(di_ts, list) else [])

    di_shifted = True
    try:
        for k in ("ema_fast_d", "ema_slow_d", "ma_cross_fast_d", "ma_cross_slow_d", "rsi_d", "willr_d", "macd_d", "macdsignal_d", "macdhist_d"):
            v = di.get(k)
            if not isinstance(v, list) or not v:
                continue
            if float(v[0]) != 0.0:
                di_shifted = False
                break
    except Exception:
        di_shifted = False

    now_ms = _now_ms()
    last_bar_age_ms = None
    try:
        last_bar_age_ms = int(max(0, int(now_ms) - int(rows[-1][0])))
    except Exception:
        last_bar_age_ms = None

    flags: List[str] = []
    if float(missing_rate) >= 0.02:
        flags.append("missing_rate_high")
    if int(max_gap_ms) >= int(12 * step_ms):
        flags.append("max_gap_large")
    if int(outlier_n) >= max(20, int(0.01 * max(1, len(rets)))):
        flags.append("return_outliers_many")
    if int(align_h.get("negative_offsets", 0)) > 0 or int(align_d.get("negative_offsets", 0)) > 0:
        flags.append("informative_alignment_negative_offset")
    if not bool(di_shifted):
        flags.append("daily_indicator_not_shifted")

    return {
        "ok": True,
        "pair": str(pair),
        "file": str(p),
        "range": {
            "start_ts": int(rows[0][0]),
            "end_ts": int(rows[-1][0]),
            "n_rows": int(len(rows)),
            "expected_step_ms": int(step_ms),
            "expected_rows": int(expected_rows),
            "missing_rows": int(missing_rows),
            "missing_rate": float(missing_rate),
            "gaps": int(gap_n),
            "max_gap_ms": int(max_gap_ms),
            "missing_bars_est": int(missing_bars_est),
            "data_start_ts": int(data_start_ts),
            "data_end_ts": int(data_end_ts),
            "last_bar_age_ms": (None if last_bar_age_ms is None else int(last_bar_age_ms)),
        },
        "invalid": {k: int(v) for k, v in invalid.items()},
        "returns": {
            "n": int(len(rets)),
            "mean": float(ret_mean),
            "std": float(ret_std),
            "p01": float(ret_p01),
            "p50": float(ret_p50),
            "p99": float(ret_p99),
            "abs_p99": float(abs_p99),
            "outlier_abs_thr": float(ret_abs_thr),
            "outlier_n": int(outlier_n),
        },
        "volume": {
            "n": int(len(vols)),
            "p50": float(v_p50),
            "p95": float(v_p95),
            "p99": float(v_p99),
            "zeros": int(v_zeros),
        },
        "alignment": {
            "hourly": align_h,
            "daily": align_d,
            "di_shifted": bool(di_shifted),
        },
        "lookahead_risk": {
            "flags": flags,
        },
    }


def _load_recent_jsonl_records(suffix: str, limit: int = 2000, max_files: int = 7, tail_bytes: int = 2000000) -> List[Dict[str, Any]]:
    try:
        limit = int(limit)
    except Exception:
        limit = 2000
    limit = max(1, min(200000, int(limit)))
    try:
        max_files = int(max_files)
    except Exception:
        max_files = 7
    max_files = max(1, min(60, int(max_files)))
    try:
        tail_bytes = int(tail_bytes)
    except Exception:
        tail_bytes = 2000000
    tail_bytes = max(1024, min(20000000, int(tail_bytes)))

    ds = _user_data_dir() / "datasets"
    if not ds.exists():
        return []
    try:
        files = [x for x in ds.glob(f"*_{str(suffix).strip()}" + ".jsonl") if x.is_file()]
        files.sort(key=lambda x: x.stat().st_mtime, reverse=True)
    except Exception:
        files = []

    out: List[Dict[str, Any]] = []
    for fp in files[:max_files]:
        if len(out) >= limit:
            break
        lines = _tail_lines(fp, max_lines=max(100, min(20000, limit - len(out))), max_bytes=tail_bytes)
        for s in reversed(lines):
            if len(out) >= limit:
                break
            try:
                obj = json.loads((s or "").strip())
            except Exception:
                continue
            if isinstance(obj, dict):
                out.append(obj)
    return out


def _audit_execution_quality(
    start_ts_ms: int,
    end_ts_ms: int,
    pair: Optional[str] = None,
    strategy_id: Optional[str] = None,
    max_points: int = 5000,
    include_shadow: bool = False,
) -> Dict[str, Any]:
    try:
        start_ts_ms = int(start_ts_ms)
        end_ts_ms = int(end_ts_ms)
    except Exception:
        return {"ok": False, "error": "bad_timerange"}
    if end_ts_ms < start_ts_ms:
        start_ts_ms, end_ts_ms = end_ts_ms, start_ts_ms

    try:
        max_points = int(max_points)
    except Exception:
        max_points = 5000
    max_points = max(200, min(200000, int(max_points)))

    pair_n = None if pair is None else str(pair).strip().upper()
    if pair_n is not None and not pair_n:
        pair_n = None
    sid_n = None if strategy_id is None else str(strategy_id).strip()
    if sid_n is not None and not sid_n:
        sid_n = None

    mem_orders = [o for o in ORDERS.values() if isinstance(o, dict)]
    arch_orders = _load_recent_jsonl_records("orders", limit=max_points, max_files=30, tail_bytes=int(CONFIG.get("events_archive_tail_bytes", 2000000) or 2000000))
    orders0 = mem_orders + arch_orders

    def _ord_ts(o: Dict[str, Any]) -> int:
        try:
            return int(o.get("ingested_ms") or o.get("received_ms") or o.get("ts") or 0)
        except Exception:
            return 0

    base_orders: List[Dict[str, Any]] = []
    for o in orders0:
        if not isinstance(o, dict):
            continue
        ts0 = _ord_ts(o)
        if ts0 <= 0 or ts0 < int(start_ts_ms) or ts0 > int(end_ts_ms):
            continue
        if pair_n is not None:
            try:
                if str(o.get("pair") or "").strip().upper() != pair_n:
                    continue
            except Exception:
                continue
        if sid_n is not None:
            try:
                if str(o.get("strategy_id") or "").strip() != sid_n:
                    continue
            except Exception:
                continue
        if not include_shadow:
            exec0 = o.get("exec") if isinstance(o.get("exec"), dict) else {}
            try:
                status0 = str(o.get("status") or "").strip().lower()
            except Exception:
                status0 = ""
            try:
                entry_type0 = str(o.get("entry_type") or "").strip().lower()
            except Exception:
                entry_type0 = ""
            try:
                shadow0 = bool(exec0.get("shadow", False))
            except Exception:
                shadow0 = False
            if status0 == "observed" or entry_type0 == "shadow" or shadow0:
                continue
        base_orders.append(o)

    base_orders.sort(key=_ord_ts, reverse=True)
    base_orders = base_orders[:max_points]

    mem_events = [e for e in EVENTS.values() if isinstance(e, dict)]
    arch_events = _load_recent_jsonl_records("events", limit=max(2000, max_points), max_files=30, tail_bytes=int(CONFIG.get("events_archive_tail_bytes", 2000000) or 2000000))
    ev_by_id: Dict[str, Dict[str, Any]] = {}
    for e in mem_events + arch_events:
        if not isinstance(e, dict):
            continue
        try:
            eid = str(e.get("id") or e.get("event_id") or "").strip()
        except Exception:
            eid = ""
        if not eid:
            continue
        if eid not in ev_by_id:
            ev_by_id[eid] = e

    status_counts: Dict[str, int] = {}
    side_counts: Dict[str, int] = {}
    action_counts: Dict[str, int] = {}
    by_strategy: Dict[str, Dict[str, Any]] = {}

    fail_statuses = {"failed", "rejected", "error"}
    ok_statuses = {"accepted", "submitted", "filled"}
    n_failed = 0
    n_ok = 0

    cancel_n = 0
    cancel_failed_n = 0
    cancel_status: Dict[str, int] = {}

    lat_ms: List[float] = []
    lat_by_strategy: Dict[str, List[float]] = {}

    fill_lat_ms: List[float] = []
    slip_bps: List[float] = []

    def _slip_bps_pick(o: Dict[str, Any]) -> Optional[float]:
        def _flt(v: Any) -> Optional[float]:
            try:
                x = float(v)
            except Exception:
                return None
            return x if math.isfinite(x) else None

        ex = o.get("exec") if isinstance(o.get("exec"), dict) else {}
        mid = _flt(ex.get("mid"))
        px = _flt(ex.get("px") or ex.get("price") or ex.get("fill_px") or ex.get("avg_px"))
        if (
            mid is not None
            and px is not None
            and math.isfinite(float(mid))
            and math.isfinite(float(px))
            and float(mid) > 0.0
            and float(px) > 0.0
        ):
            return abs(float(px) - float(mid)) / float(mid) * 10000.0
        sb = _flt(ex.get("slippage_bps"))
        if sb is not None and math.isfinite(float(sb)):
            return abs(float(sb))
        sr = _flt(ex.get("slippage"))
        if sr is not None and math.isfinite(float(sr)):
            return abs(float(sr)) * 10000.0
        return None

    def _is_nonfatal_failed(o: Dict[str, Any], *, status0: str, action0: str, tag0: str) -> bool:
        if status0 not in fail_statuses:
            return False
        try:
            exec0 = o.get("exec") if isinstance(o.get("exec"), dict) else {}
        except Exception:
            exec0 = {}
        try:
            exec_err = str((exec0 or {}).get("error") or "").strip().lower()
        except Exception:
            exec_err = ""
        if not exec_err:
            return False
        if "qty_capped_too_small" in exec_err:
            return True
        is_exit_like = (action0 in ("close", "reduce")) or ("market_close" in tag0) or ("reduce" in tag0)
        if is_exit_like:
            if (
                ("size_underflow" in exec_err)
                or ("reduceonly order is rejected" in exec_err)
                or ("no position" in exec_err)
                or ("position is zero" in exec_err)
                or ("position_amt" in exec_err and "<=" in exec_err and "0" in exec_err)
                or ("-2022" in exec_err)
            ):
                return True
        return False

    nonfatal_failed_n = 0

    for o in base_orders:
        try:
            status0 = str(o.get("status") or "").strip().lower() or "unknown"
        except Exception:
            status0 = "unknown"
        status_counts[status0] = int(status_counts.get(status0, 0)) + 1
        try:
            side0 = str(o.get("side") or "").strip().lower() or "unknown"
        except Exception:
            side0 = "unknown"
        side_counts[side0] = int(side_counts.get(side0, 0)) + 1
        try:
            action0 = str(o.get("action") or "").strip().lower() or "unknown"
        except Exception:
            action0 = "unknown"
        action_counts[action0] = int(action_counts.get(action0, 0)) + 1
        try:
            tag0 = str(o.get("tag") or "").strip().lower()
        except Exception:
            tag0 = ""

        nonfatal_failed = _is_nonfatal_failed(o, status0=status0, action0=action0, tag0=tag0)
        if status0 in fail_statuses and (not nonfatal_failed):
            n_failed += 1
        if status0 in fail_statuses and nonfatal_failed:
            nonfatal_failed_n += 1
        if status0 in ok_statuses:
            n_ok += 1
        is_cancel = ("cancel" in tag0) or (action0 == "cancel")
        if is_cancel:
            cancel_n += 1
            cancel_status[status0] = int(cancel_status.get(status0, 0)) + 1
            if status0 in fail_statuses:
                cancel_failed_n += 1

        s0 = _slip_bps_pick(o)
        if s0 is not None and math.isfinite(float(s0)):
            slip_bps.append(float(s0))

        if status0 == "filled":
            t0 = None
            t1 = None
            try:
                t0 = int(o.get("ts") or 0)
            except Exception:
                t0 = None
            sync = o.get("sync") if isinstance(o.get("sync"), dict) else {}
            try:
                t1 = int(sync.get("ts") or 0)
            except Exception:
                t1 = None
            if t0 is not None and t1 is not None and t0 > 0 and t1 > 0 and t1 >= t0:
                fill_lat_ms.append(float(int(t1 - t0)))

        sid0 = str(o.get("strategy_id") or "").strip() or "__none__"
        if sid0 not in by_strategy:
            by_strategy[sid0] = {"n": 0, "status": {}, "side": {}, "action": {}}
        by_strategy[sid0]["n"] = int(by_strategy[sid0].get("n", 0)) + 1
        bs_status = by_strategy[sid0].get("status") if isinstance(by_strategy[sid0].get("status"), dict) else {}
        bs_status[status0] = int(bs_status.get(status0, 0)) + 1
        by_strategy[sid0]["status"] = bs_status
        bs_side = by_strategy[sid0].get("side") if isinstance(by_strategy[sid0].get("side"), dict) else {}
        bs_side[side0] = int(bs_side.get(side0, 0)) + 1
        by_strategy[sid0]["side"] = bs_side
        bs_action = by_strategy[sid0].get("action") if isinstance(by_strategy[sid0].get("action"), dict) else {}
        bs_action[action0] = int(bs_action.get(action0, 0)) + 1
        by_strategy[sid0]["action"] = bs_action

        eid = o.get("event_id")
        eid_s = "" if eid is None else str(eid).strip()
        if not eid_s:
            continue
        evt = ev_by_id.get(eid_s)
        if not isinstance(evt, dict):
            continue
        try:
            t_sig = int(evt.get("ts_emit_ms") or evt.get("ingested_ms") or evt.get("received_ms") or evt.get("ts") or 0)
            t_ord = _ord_ts(o)
            l = int(t_ord - t_sig)
        except Exception:
            l = -1
        if l < 0:
            continue
        lat_ms.append(float(l))
        lat_by_strategy.setdefault(sid0, []).append(float(l))

    def _lat_stats(xs: List[float]) -> Dict[str, Any]:
        if not xs:
            return {"n": 0, "p50_ms": 0.0, "p95_ms": 0.0, "p99_ms": 0.0, "mean_ms": 0.0}
        m = float(sum(xs) / float(len(xs)))
        return {
            "n": int(len(xs)),
            "mean_ms": float(m),
            "p50_ms": float(_q(xs, 0.50)),
            "p95_ms": float(_q(xs, 0.95)),
            "p99_ms": float(_q(xs, 0.99)),
        }

    def _bps_stats(xs: List[float]) -> Dict[str, Any]:
        if not xs:
            return {"n": 0, "p50_bps": 0.0, "p95_bps": 0.0, "p99_bps": 0.0, "mean_bps": 0.0}
        m = float(sum(xs) / float(len(xs)))
        return {
            "n": int(len(xs)),
            "mean_bps": float(m),
            "p50_bps": float(_q(xs, 0.50)),
            "p95_bps": float(_q(xs, 0.95)),
            "p99_bps": float(_q(xs, 0.99)),
        }

    out_by_strategy: Dict[str, Any] = {}
    for sid0, st in by_strategy.items():
        out_by_strategy[sid0] = {
            "n": int(st.get("n", 0) or 0),
            "status": dict(st.get("status") or {}),
            "side": dict(st.get("side") or {}),
            "action": dict(st.get("action") or {}),
            "latency": _lat_stats(lat_by_strategy.get(sid0, []) or []),
        }

    denom_n = int(len(base_orders) - int(nonfatal_failed_n))
    if denom_n < 0:
        denom_n = 0
    return {
        "ok": True,
        "pair": (None if pair_n is None else str(pair_n)),
        "strategy_id": (None if sid_n is None else str(sid_n)),
        "range": {
            "start_ts": int(start_ts_ms),
            "end_ts": int(end_ts_ms),
            "lookback_ms": int(max(0, int(end_ts_ms) - int(start_ts_ms))),
        },
        "n_orders": int(len(base_orders)),
        "n_orders_effective": int(denom_n),
        "n_orders_nonfatal_failed": int(nonfatal_failed_n),
        "order_success_rate": (float(n_ok) / float(denom_n) if denom_n > 0 else None),
        "order_fail_rate": (float(n_failed) / float(denom_n) if denom_n > 0 else None),
        "status": {k: int(v) for k, v in status_counts.items()},
        "side": {k: int(v) for k, v in side_counts.items()},
        "action": {k: int(v) for k, v in action_counts.items()},
        "latency": _lat_stats(lat_ms),
        "submit_to_fill_latency": _lat_stats(fill_lat_ms),
        "slippage": _bps_stats(slip_bps),
        "cancel": {
            "n": int(cancel_n),
            "fail_rate": (float(cancel_failed_n) / float(cancel_n) if cancel_n > 0 else None),
            "status": {k: int(v) for k, v in cancel_status.items()},
        },
        "by_strategy": out_by_strategy,
    }


def _monitor_alerts_eval(dq: Optional[Dict[str, Any]] = None, eq: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    alerts: List[Dict[str, Any]] = []
    dq0 = dq if isinstance(dq, dict) else {}
    eq0 = eq if isinstance(eq, dict) else {}

    dq_ok = bool(dq0.get("ok"))
    if dq_ok:
        r = dq0.get("range") if isinstance(dq0.get("range"), dict) else {}
        mr = float(r.get("missing_rate") or 0.0)
        if math.isfinite(mr) and mr >= 0.02:
            alerts.append({"id": "dq_missing_rate_high", "severity": "high", "value": float(mr), "threshold": 0.02})
        try:
            mg = int(r.get("max_gap_ms") or 0)
            step = int(r.get("expected_step_ms") or 300000)
        except Exception:
            mg = 0
            step = 300000
        if int(mg) >= int(12 * max(1, step)):
            alerts.append({"id": "dq_max_gap_large", "severity": "medium", "value": int(mg), "threshold": int(12 * max(1, step))})

        align = dq0.get("alignment") if isinstance(dq0.get("alignment"), dict) else {}
        di_shifted = bool(align.get("di_shifted", True))
        if not di_shifted:
            alerts.append({"id": "dq_daily_indicator_not_shifted", "severity": "high", "value": 0, "threshold": 1})

        bar = dq0.get("bar_closed") if isinstance(dq0.get("bar_closed"), dict) else {}
        try:
            rate_true = float(bar.get("rate_true") or 0.0)
        except Exception:
            rate_true = 0.0
        if math.isfinite(rate_true) and rate_true > 0 and rate_true < 0.99:
            alerts.append({"id": "dq_bar_closed_rate_low", "severity": "high", "value": float(rate_true), "threshold": 0.99})

    eq_ok = bool(eq0.get("ok"))
    if eq_ok:
        n = int(eq0.get("n_orders") or 0)
        st = eq0.get("status") if isinstance(eq0.get("status"), dict) else {}
        failed = int(st.get("failed") or st.get("error") or 0)
        if n > 20:
            fr = float(failed) / float(n) if n > 0 else 0.0
            if fr >= 0.2:
                alerts.append({"id": "eq_fail_rate_high", "severity": "high", "value": float(fr), "threshold": 0.2})
        lat = eq0.get("latency") if isinstance(eq0.get("latency"), dict) else {}
        try:
            p95 = float(lat.get("p95_ms") or 0.0)
        except Exception:
            p95 = 0.0
        if math.isfinite(p95) and p95 >= 5000:
            alerts.append({"id": "eq_latency_p95_high", "severity": "medium", "value": float(p95), "threshold": 5000.0})

    return {"ok": True, "alerts": alerts, "dq_ok": bool(dq_ok), "eq_ok": bool(eq_ok)}


def _sli_online_state() -> Dict[str, Any]:
    st = TRACKER_STATE.get("sli_online")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["sli_online"] = st
    if not isinstance(st.get("series"), dict):
        st["series"] = {}
    if not isinstance(st.get("pending_tracker_update"), dict):
        st["pending_tracker_update"] = {}
    if not isinstance(st.get("last_alert_ms"), dict):
        st["last_alert_ms"] = {}
    if not isinstance(st.get("recent_breaches"), list):
        st["recent_breaches"] = []
    return st


def _sli_online_enabled() -> bool:
    try:
        return bool(CONFIG.get("sli_online_enabled", True))
    except Exception:
        return True


def _sli_online_window_ms() -> int:
    try:
        sec = int(CONFIG.get("sli_online_window_sec", 1800) or 1800)
    except Exception:
        sec = 1800
    sec = max(60, min(7 * 86400, int(sec)))
    return int(sec) * 1000


def _sli_online_max_samples() -> int:
    try:
        n = int(CONFIG.get("sli_online_max_samples", 5000) or 5000)
    except Exception:
        n = 5000
    return max(200, min(50000, int(n)))


def _sli_online_tracker_update_ttl_ms() -> int:
    try:
        sec = int(CONFIG.get("sli_online_tracker_update_ttl_sec", 180) or 180)
    except Exception:
        sec = 180
    sec = max(10, min(3600, int(sec)))
    return int(sec) * 1000


def _sli_online_alert_cooldown_ms() -> int:
    try:
        sec = int(CONFIG.get("sli_online_alert_cooldown_sec", 300) or 300)
    except Exception:
        sec = 300
    sec = max(10, min(3600, int(sec)))
    return int(sec) * 1000


def _sli_prune_points(points: Any, *, cutoff_ms: int, max_len: int) -> List[List[float]]:
    pts = points if isinstance(points, list) else []
    i = 0
    for j, it in enumerate(pts):
        if not isinstance(it, list) or len(it) < 2:
            continue
        try:
            ts = int(it[0] or 0)
        except Exception:
            ts = 0
        if ts >= int(cutoff_ms):
            i = j
            break
        i = j + 1
    if i > 0:
        pts = pts[i:]
    if len(pts) > int(max_len):
        pts = pts[-int(max_len):]
    out: List[List[float]] = []
    for it in pts:
        if not isinstance(it, list) or len(it) < 2:
            continue
        try:
            ts = int(it[0] or 0)
            v = float(it[1])
        except Exception:
            continue
        out.append([float(ts), float(v)])
    return out


def _sli_online_observe(metric: str, value: float, *, now_ms: int) -> None:
    if not _sli_online_enabled():
        return
    m = str(metric or "").strip()
    if not m:
        return
    st = _sli_online_state()
    series = st.get("series") if isinstance(st.get("series"), dict) else {}
    pts = series.get(m)
    cutoff = int(now_ms) - int(_sli_online_window_ms())
    max_len = _sli_online_max_samples()
    pts2 = _sli_prune_points(pts, cutoff_ms=cutoff, max_len=max_len)
    pts2.append([float(int(now_ms)), float(value)])
    if len(pts2) > int(max_len):
        pts2 = pts2[-int(max_len):]
    series[m] = pts2
    st["series"] = series


def _sli_online_note_order_created(order_id: str, *, now_ms: int) -> None:
    if not _sli_online_enabled():
        return
    oid = str(order_id or "").strip()
    if not oid:
        return
    try:
        o = ORDERS.get(oid)
    except Exception:
        o = None
    if not isinstance(o, dict):
        return
    try:
        mode = str(o.get("mode") or "").strip().lower()
    except Exception:
        mode = ""
    if mode != "real":
        return
    try:
        st0 = str(o.get("status") or "").strip().lower()
    except Exception:
        st0 = ""
    if st0 == "failed":
        return
    st = _sli_online_state()
    pending = st.get("pending_tracker_update") if isinstance(st.get("pending_tracker_update"), dict) else {}
    pending[oid] = int(now_ms)
    st["pending_tracker_update"] = pending


def _sli_online_note_tracker_update(order_id: str, *, now_ms: int) -> None:
    if not _sli_online_enabled():
        return
    oid = str(order_id or "").strip()
    if not oid:
        return
    st = _sli_online_state()
    pending = st.get("pending_tracker_update") if isinstance(st.get("pending_tracker_update"), dict) else {}
    if oid not in pending:
        return
    try:
        del pending[oid]
    except Exception:
        pass
    st["pending_tracker_update"] = pending
    _sli_online_observe("order_to_tracker_update_complete", 1.0, now_ms=int(now_ms))


def _sli_online_expire_pending(now_ms: int) -> None:
    if not _sli_online_enabled():
        return
    st = _sli_online_state()
    pending = st.get("pending_tracker_update") if isinstance(st.get("pending_tracker_update"), dict) else {}
    if not pending:
        return
    ttl_ms = int(_sli_online_tracker_update_ttl_ms())
    expired: List[str] = []
    for oid, ts0 in list(pending.items()):
        try:
            ts = int(ts0 or 0)
        except Exception:
            ts = 0
        if ts <= 0:
            expired.append(str(oid))
            continue
        if (int(now_ms) - int(ts)) >= int(ttl_ms):
            expired.append(str(oid))
    if not expired:
        return
    for oid in expired:
        try:
            if oid in pending:
                del pending[oid]
        except Exception:
            pass
        _sli_online_observe("order_to_tracker_update_complete", 0.0, now_ms=int(now_ms))
    st["pending_tracker_update"] = pending


def _sli_stats_ms(values: List[float]) -> Dict[str, Any]:
    xs = [float(x) for x in (values or []) if x is not None and math.isfinite(float(x))]
    if not xs:
        return {"n": 0, "mean_ms": 0.0, "p50_ms": 0.0, "p95_ms": 0.0, "p99_ms": 0.0}
    m = float(sum(xs) / float(len(xs)))
    return {
        "n": int(len(xs)),
        "mean_ms": float(m),
        "p50_ms": float(_q(xs, 0.50)),
        "p95_ms": float(_q(xs, 0.95)),
        "p99_ms": float(_q(xs, 0.99)),
    }


def _sli_rate(values01: List[float]) -> Dict[str, Any]:
    xs = [float(x) for x in (values01 or []) if x is not None and math.isfinite(float(x))]
    if not xs:
        return {"n": 0, "ok": 0, "rate": None}
    ok = sum(1 for x in xs if float(x) >= 0.5)
    return {"n": int(len(xs)), "ok": int(ok), "rate": (float(ok) / float(len(xs)) if len(xs) > 0 else None)}


def _sli_online_snapshot(now_ms: int) -> Dict[str, Any]:
    if not _sli_online_enabled():
        return {"ok": True, "enabled": False, "ts": int(now_ms)}
    st = _sli_online_state()
    _sli_online_expire_pending(int(now_ms))
    series = st.get("series") if isinstance(st.get("series"), dict) else {}
    cutoff = int(now_ms) - int(_sli_online_window_ms())
    max_len = _sli_online_max_samples()

    def _vals(metric: str) -> List[float]:
        pts2 = _sli_prune_points(series.get(metric), cutoff_ms=cutoff, max_len=max_len)
        series[metric] = pts2
        out = []
        for it in pts2:
            try:
                out.append(float(it[1]))
            except Exception:
                continue
        return out

    lat_sd = _vals("signal_to_decision_ms")
    rate_do = _vals("decision_to_order_success")
    rate_ot = _vals("order_to_tracker_update_complete")

    pending = st.get("pending_tracker_update") if isinstance(st.get("pending_tracker_update"), dict) else {}

    snap = {
        "ok": True,
        "enabled": True,
        "ts": int(now_ms),
        "window_sec": int(_sli_online_window_ms() // 1000),
        "max_samples": int(max_len),
        "signal_to_decision_latency": _sli_stats_ms(lat_sd),
        "decision_to_order_success": _sli_rate(rate_do),
        "order_to_tracker_update_complete": {**_sli_rate(rate_ot), "pending": int(len(pending))},
    }
    st["series"] = series
    st["last_snapshot"] = dict(snap)
    return snap


def _sli_online_eval_slo(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    alerts: List[Dict[str, Any]] = []
    snap = snapshot if isinstance(snapshot, dict) else {}

    lat = (snap.get("signal_to_decision_latency") if isinstance(snap.get("signal_to_decision_latency"), dict) else {})
    try:
        p95_ms = float(lat.get("p95_ms") or 0.0)
    except Exception:
        p95_ms = 0.0
    p95_thr = None
    try:
        v = CONFIG.get("slo_signal_to_decision_p95_ms_max")
        if v is not None and math.isfinite(float(v)):
            p95_thr = float(v)
    except Exception:
        p95_thr = None
    if p95_thr is not None and math.isfinite(p95_ms) and p95_ms > 0 and float(p95_ms) >= float(p95_thr):
        alerts.append({"id": "slo_signal_to_decision_p95_high", "severity": "medium", "value": float(p95_ms), "threshold": float(p95_thr)})

    do = (snap.get("decision_to_order_success") if isinstance(snap.get("decision_to_order_success"), dict) else {})
    try:
        do_rate = do.get("rate")
        do_rate = (None if do_rate is None else float(do_rate))
    except Exception:
        do_rate = None
    do_thr = None
    try:
        v = CONFIG.get("slo_decision_to_order_success_min")
        if v is not None and math.isfinite(float(v)):
            do_thr = float(v)
    except Exception:
        do_thr = None
    if do_thr is not None and do_rate is not None and math.isfinite(float(do_rate)) and float(do_rate) < float(do_thr):
        alerts.append({"id": "slo_decision_to_order_success_low", "severity": "high", "value": float(do_rate), "threshold": float(do_thr)})

    ot = (snap.get("order_to_tracker_update_complete") if isinstance(snap.get("order_to_tracker_update_complete"), dict) else {})
    try:
        ot_rate = ot.get("rate")
        ot_rate = (None if ot_rate is None else float(ot_rate))
    except Exception:
        ot_rate = None
    ot_thr = None
    try:
        v = CONFIG.get("slo_order_to_tracker_update_complete_min")
        if v is not None and math.isfinite(float(v)):
            ot_thr = float(v)
    except Exception:
        ot_thr = None
    if ot_thr is not None and ot_rate is not None and math.isfinite(float(ot_rate)) and float(ot_rate) < float(ot_thr):
        alerts.append({"id": "slo_order_to_tracker_update_complete_low", "severity": "high", "value": float(ot_rate), "threshold": float(ot_thr)})

    return {"ok": True, "alerts": alerts}


def _sli_online_maybe_emit_alert(now_ms: int) -> None:
    if not _sli_online_enabled():
        return
    snap = _sli_online_snapshot(int(now_ms))
    rep = _sli_online_eval_slo(snap)
    alerts = rep.get("alerts") if isinstance(rep, dict) else []
    if not isinstance(alerts, list) or not alerts:
        return
    high = [a for a in alerts if isinstance(a, dict) and str(a.get("severity") or "").strip().lower() in ("p0", "critical", "fatal", "high")]
    triggered = bool(high)
    if not triggered:
        return
    st = _sli_online_state()
    last_map = st.get("last_alert_ms") if isinstance(st.get("last_alert_ms"), dict) else {}
    key = "|".join(sorted([str(a.get("id") or "") for a in high if isinstance(a, dict)]))
    try:
        last = int(last_map.get(key) or 0)
    except Exception:
        last = 0
    cooldown = int(_sli_online_alert_cooldown_ms())
    if last > 0 and (int(now_ms) - int(last)) < int(cooldown):
        return
    last_map[key] = int(now_ms)
    st["last_alert_ms"] = last_map

    trace_id = hashlib.sha256(f"sli_slo|{int(now_ms)}|{key}".encode("utf-8")).hexdigest()[:32]
    try:
        _agent_emit_envelope_event(
            event="sli.slo.breach",
            trace_id=trace_id,
            severity="warn",
            intent_level="L0",
            ts_ms=int(now_ms),
            inputs={"window_sec": int(snap.get("window_sec") or 0)},
            evidence=[{"type": "sli_online", "snapshot": snap}],
            outputs={"triggered": True, "alerts": alerts},
            doc_refs=_agent_doc_refs_48_default(),
        )
    except Exception:
        pass

    st["last_breach_trace_id"] = str(trace_id)
    recent = st.get("recent_breaches") if isinstance(st.get("recent_breaches"), list) else []
    recent.append({"trace_id": str(trace_id), "ts": int(now_ms), "alerts": alerts})
    if len(recent) > 50:
        recent = recent[-50:]
    st["recent_breaches"] = recent


def _monitor_alerts_poll_run(now_ms: int) -> Dict[str, Any]:
    pair = _agent_push_cfg_str("monitor_alerts_poll_pair", None)
    try:
        lookback_days = float(_agent_push_cfg_float("monitor_alerts_poll_lookback_days", 1.0, lo=0.05, hi=60.0))
    except Exception:
        lookback_days = 1.0
    start_ms = int(now_ms) - int(float(lookback_days) * 86400.0 * 1000.0)

    dq = None
    if pair:
        try:
            dq = _audit_data_quality(pair=str(pair).upper(), start_ts_ms=int(start_ms), end_ts_ms=int(now_ms), max_points=5000, ret_abs_thr=0.10)
        except Exception as e:
            dq = {"ok": False, "error": str(e)}
        try:
            if isinstance(dq, dict) and bool(dq.get("ok")):
                dq["bar_closed"] = _audit_bar_closed_stats(limit=2000, pair=str(pair).upper())
        except Exception:
            pass

    eq = None
    try:
        eq = _audit_execution_quality(start_ts_ms=int(start_ms), end_ts_ms=int(now_ms), pair=(None if not pair else str(pair).upper()), max_points=5000, include_shadow=False)
    except Exception as e:
        eq = {"ok": False, "error": str(e)}

    rep = _monitor_alerts_eval(dq=dq, eq=eq)
    sli = None
    try:
        sli = _sli_online_snapshot(int(now_ms))
        rep["sli_online"] = sli
    except Exception:
        sli = None
    alerts = rep.get("alerts") if isinstance(rep, dict) else []
    high = [a for a in (alerts if isinstance(alerts, list) else []) if isinstance(a, dict) and str(a.get("severity") or "").strip().lower() in ("p0", "critical", "fatal", "high")]
    triggered = bool(high)

    score = 0.0
    try:
        score = float(min(1.0, 0.5 * float(len(high)) + 0.15 * float(len(alerts) if isinstance(alerts, list) else 0)))
    except Exception:
        score = 0.0
    delta_estimate = {"kind": "monitoring_risk", "severity_score": float(max(0.0, min(1.0, score))), "alerts": int(len(alerts) if isinstance(alerts, list) else 0), "high": int(len(high)), "confidence": 0.4}

    if triggered:
        trace_id = hashlib.sha256(f"monitor_alerts|{int(now_ms)}|{str(pair or 'all')}".encode("utf-8")).hexdigest()[:32]
        _agent_emit_envelope_event(
            event="monitor.alerts.trigger",
            trace_id=trace_id,
            severity="warn",
            intent_level="L0",
            ts_ms=int(now_ms),
            inputs={"pair": pair, "lookback_days": float(lookback_days), "range": {"start_ms": int(start_ms), "end_ms": int(now_ms)}},
            evidence=[{"type": "monitor_alerts", "source": "poll", "dq": dq, "eq": eq}],
            outputs={"triggered": True, "alerts": alerts, "delta_estimate": delta_estimate},
            doc_refs=_agent_doc_refs_48_default(),
        )
    try:
        if sli is not None:
            _sli_online_maybe_emit_alert(int(now_ms))
    except Exception:
        pass
    return {"ok": True, "triggered": triggered, "pair": pair, "rep": rep, "dq": dq, "eq": eq, "delta_estimate": delta_estimate}


def _shadow_observation_report_build(*, trace_id: str, now_ms: int, monitor_out: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    tid = str(trace_id or "").strip()
    out: Dict[str, Any] = {"ok": True, "trace_id": tid, "ts": int(ts)}
    try:
        out["serving"] = {
            "dry_run": bool(CONFIG.get("dry_run", True)),
            "serving_shadow_mode": bool(CONFIG.get("serving_shadow_mode", False)),
            "serving_canary_enabled": bool(CONFIG.get("serving_canary_enabled", False)),
        }
    except Exception:
        out["serving"] = None
    try:
        resp = metrics()
        if hasattr(resp, "get_json"):
            out["metrics"] = resp.get_json(force=True) or {}
    except Exception:
        pass
    try:
        with app.test_request_context(
            "/audit/alerts/evaluate",
            method="GET",
            content_type="application/json",
            environ_base={"REMOTE_ADDR": "127.0.0.1"},
        ):
            resp2 = audit_alerts_evaluate()
        resp2_0 = resp2[0] if isinstance(resp2, tuple) and resp2 else resp2
        if hasattr(resp2_0, "get_json"):
            out["alerts"] = resp2_0.get_json(force=True) or {}
    except Exception:
        pass
    try:
        with app.test_request_context(
            "/automation/serving/pipeline/guard/eval",
            method="GET",
            content_type="application/json",
            environ_base={"REMOTE_ADDR": "127.0.0.1"},
        ):
            resp3 = automation_serving_pipeline_guard_eval()
        resp3_0 = resp3[0] if isinstance(resp3, tuple) and resp3 else resp3
        if hasattr(resp3_0, "get_json"):
            out["serving_guard"] = resp3_0.get_json(force=True) or {}
    except Exception:
        pass
    try:
        st = _agent_pipeline_state_find_latest(trace_id=tid)
        if isinstance(st, dict):
            out["pipeline_state"] = {"status": st.get("status"), "ts": st.get("ts"), "shadow_only": bool(st.get("shadow_only", False))}
    except Exception:
        pass
    if isinstance(monitor_out, dict):
        out["monitor"] = _json_sanitize(monitor_out)
    return out


def _shadow_observation_emit(*, trace_id: str, now_ms: int, kind: str, monitor_out: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
    tid = str(trace_id or "").strip()
    if not tid:
        return None
    ts = int(now_ms or _now_ms())
    rep = _shadow_observation_report_build(trace_id=tid, now_ms=int(ts), monitor_out=monitor_out)
    try:
        art = _agent_pipeline_artifact_common_fields(trace_id=str(tid), created_at_ms=int(ts), producer_kind="agent")
        art.update({"ts": int(ts), "kind": str(kind), "report": rep})
        path = _agent_pipeline_package_write(trace_id=str(tid), filename=f"{str(kind)}.json", obj=art)
        if path and isinstance(art, dict):
            art["artifact_files"] = {f"{str(kind)}_json": path}
        return _agent_pipeline_artifact_validate_and_emit(trace_id=str(tid), kind=str(kind), artifact=art)
    except Exception:
        return None


def _resample(rows: List[List[float]], bucket_ms: int) -> List[Tuple[int, float, float, float, float, float]]:
    out = []
    if not rows:
        return out
    cur_beg = None
    cur_open = cur_high = cur_low = cur_close = cur_vol = None
    for ts, o, h, l, c, v in rows:
        b = (int(ts) // bucket_ms) * bucket_ms
        if cur_beg is None:
            cur_beg = b
            cur_open = o
            cur_high = h
            cur_low = l
            cur_close = c
            cur_vol = v
            continue
        if b != cur_beg:
            out.append((cur_beg, float(cur_open), float(cur_high), float(cur_low), float(cur_close), float(cur_vol)))
            cur_beg = b
            cur_open = o
            cur_high = h
            cur_low = l
            cur_close = c
            cur_vol = v
        else:
            cur_high = max(cur_high, h)
            cur_low = min(cur_low, l)
            cur_close = c
            cur_vol += v
    out.append((cur_beg, float(cur_open), float(cur_high), float(cur_low), float(cur_close), float(cur_vol)))
    return out


def _resample_closed(rows: List[List[float]], bucket_ms: int, now_ms: int = None) -> List[Tuple[int, float, float, float, float, float]]:
    out = _resample(rows, bucket_ms)
    if not out:
        return out
    t_now = int(_now_ms() if now_ms is None else now_ms)
    closed: List[Tuple[int, float, float, float, float, float]] = []
    for r in out:
        try:
            b = int(r[0])
        except Exception:
            continue
        if int(b) + int(bucket_ms) <= int(t_now):
            closed.append(r)
    return closed

def _ema(series: List[float], period: int) -> List[float]:
    res = []
    if period <= 1:
        return series[:]
    k = 2.0 / (period + 1.0)
    ema = None
    for x in series:
        if ema is None:
            ema = x
        else:
            ema = x * k + ema * (1.0 - k)
        res.append(ema)
    return res

def _rsi(close: List[float], period: int = 14) -> List[float]:
    res = []
    avg_gain = None
    avg_loss = None
    prev = None
    for i, x in enumerate(close):
        if prev is None:
            prev = x
            res.append(50.0)
            continue
        change = x - prev
        gain = max(0.0, change)
        loss = max(0.0, -change)
        if avg_gain is None:
            avg_gain = gain
            avg_loss = loss
        else:
            if i <= period:
                avg_gain = (avg_gain * (i - 1) + gain) / i
                avg_loss = (avg_loss * (i - 1) + loss) / i
            else:
                avg_gain = (avg_gain * (period - 1) + gain) / period
                avg_loss = (avg_loss * (period - 1) + loss) / period
        rs = (avg_gain / avg_loss) if avg_loss > 0 else math.inf
        rsi = 100.0 - (100.0 / (1.0 + rs)) if math.isfinite(rs) else 100.0
        res.append(rsi)
        prev = x
    return res

def _willr(high: List[float], low: List[float], close: List[float], period: int = 14) -> List[float]:
    res = []
    for i in range(len(close)):
        beg = max(0, i - period + 1)
        hh = max(high[beg:i+1]) if i >= beg else high[i]
        ll = min(low[beg:i+1]) if i >= beg else low[i]
        denom = (hh - ll) if (hh - ll) != 0 else 1e-10
        val = -100.0 * ((hh - close[i]) / denom)
        res.append(val)
    return res

def _macd(close: List[float], fast: int = 12, slow: int = 26, signal: int = 9) -> Tuple[List[float], List[float], List[float]]:
    ema_fast = _ema(close, fast)
    ema_slow = _ema(close, slow)
    macd_line = [a - b for a, b in zip(ema_fast, ema_slow)]
    signal_line = _ema(macd_line, signal)
    hist = [a - b for a, b in zip(macd_line, signal_line)]
    return macd_line, signal_line, hist

def _atr(high: List[float], low: List[float], close: List[float], period: int = 14) -> List[float]:
    trs = []
    prev_close = None
    for i in range(len(close)):
        c = close[i]
        h = high[i]
        l = low[i]
        if prev_close is None:
            tr = h - l
        else:
            tr = max(h - l, abs(h - prev_close), abs(l - prev_close))
        trs.append(tr)
        prev_close = c
    res = []
    avg = None
    for i, tr in enumerate(trs):
        if avg is None:
            avg = tr
        else:
            if i <= period:
                avg = (avg * (i - 1) + tr) / i
            else:
                avg = (avg * (period - 1) + tr) / period
        res.append(avg)
    return res

def _atr_pct_latest(pair: str) -> float:
    c = _get_pair_cache(pair)
    atr_pct_h = c.get("atr_pct_h") or []
    if not atr_pct_h:
        return 0.0
    return float(atr_pct_h[-1])

def _kelly_payoff_ratio(regime: str = None, pair: str = None) -> float:
    lookback = int(CONFIG.get("kelly_lookback_samples", 2000))
    min_n = int(CONFIG.get("kelly_min_samples", 200))
    ss = EVAL_SAMPLES
    if lookback > 0 and len(ss) > lookback:
        ss = ss[-lookback:]
    if regime is not None:
        ss = [s for s in ss if str((s.get("features") or {}).get("regime") or "trend") == str(regime)]
    if pair is not None:
        ss = [s for s in ss if str(s.get("pair") or "") == str(pair)]
    if len(ss) < min_n:
        return float(CONFIG.get("kelly_default_b", 1.0))
    gains: List[float] = []
    losses: List[float] = []
    for s in ss:
        t = s.get("targets") or {}
        r = t.get("return_tk_raw")
        if r is None:
            r = t.get("return_tk")
        if r is None:
            r = 1.0 if int(s.get("label", 0)) == 1 else -1.0
        rr = float(r)
        if rr > 0:
            gains.append(rr)
        elif rr < 0:
            losses.append(-rr)
    if len(gains) < max(10, min_n // 10) or len(losses) < max(10, min_n // 10):
        return float(CONFIG.get("kelly_default_b", 1.0))
    g = sum(gains) / float(len(gains))
    l = sum(losses) / float(len(losses))
    if l <= 1e-12 or g <= 1e-12:
        return float(CONFIG.get("kelly_default_b", 1.0))
    return max(0.01, min(50.0, float(g / l)))

def _size_from_pc_atr(pc: float, pair: str, features: Dict[str, Any]) -> float:
    min_size = float(CONFIG.get("min_trade_size", 0.001))
    max_size = float(CONFIG.get("max_trade_size", 0.1))
    atr_pct = _atr_pct_latest(pair)
    target_r = float(CONFIG.get("stake_target_atr_pct", CONFIG.get("weight_target_atr_pct", 0.03)))
    scale = (target_r / atr_pct) if atr_pct > 1e-12 else 1.0
    scale = _clip(float(scale), float(CONFIG.get("stake_atr_scale_min", 0.25)), float(CONFIG.get("stake_atr_scale_max", 4.0)))
    regime = _get_regime(features, pair=str(pair))
    b = _kelly_payoff_ratio(regime=regime, pair=(pair if bool(CONFIG.get("kelly_by_pair", False)) else None))
    p = _clip(float(pc), 1e-6, 1.0 - 1e-6)
    f_kelly = ((p * (b + 1.0)) - 1.0) / b if b > 1e-12 else 0.0
    f_kelly = _clip(float(f_kelly), 0.0, 1.0)
    f = float(CONFIG.get("kelly_multiplier", 0.5)) * float(f_kelly)
    f = _clip(float(f), 0.0, 1.0)
    qty = (min_size + (max_size - min_size) * f) * scale
    return max(min_size, min(max_size, qty))


def _clip_aster_entry_notional_usdc(notional_usdc: float) -> float:
    x = float(notional_usdc)
    if (not math.isfinite(x)) or x <= 0.0:
        return x
    mins: List[float] = []
    maxs: List[float] = []
    for k in ("aster_min_notional_usdc", "entry_min_notional_usdc"):
        try:
            v = float(CONFIG.get(k)) if CONFIG.get(k) is not None else None
        except Exception:
            v = None
        if v is not None and math.isfinite(float(v)) and float(v) > 0.0:
            mins.append(float(v))
    for k in ("aster_max_notional_usdc", "entry_max_notional_usdc"):
        try:
            v = float(CONFIG.get(k)) if CONFIG.get(k) is not None else None
        except Exception:
            v = None
        if v is not None and math.isfinite(float(v)) and float(v) > 0.0:
            maxs.append(float(v))

    lo = max(mins) if mins else None
    hi = min(maxs) if maxs else None
    if lo is not None and x < float(lo):
        x = float(lo)
    if hi is not None and x > float(hi):
        x = float(hi)
    return float(x)


def _effective_entry_notional_bounds(venue: str, cfg: Optional[Dict[str, Any]] = None) -> Tuple[Optional[float], Optional[float]]:
    cfg0 = CONFIG if cfg is None else cfg

    def _f(k: str) -> Optional[float]:
        try:
            v = cfg0.get(k)
            if v is None:
                return None
            x = float(v)
        except Exception:
            return None
        if not math.isfinite(float(x)):
            return None
        return float(x)

    def _pos(x: Optional[float]) -> Optional[float]:
        if x is None:
            return None
        if float(x) <= 0.0:
            return None
        return float(x)

    v = str(venue or "").lower().strip()

    entry_min = _pos(_f("entry_min_notional_usdc"))
    entry_max = _pos(_f("entry_max_notional_usdc"))

    venue_min = None
    venue_max = None
    if v == "aster":
        venue_min = _pos(_f("aster_min_notional_usdc"))
        venue_max = _pos(_f("aster_max_notional_usdc"))
    elif v == "hyperliquid":
        venue_min = _pos(_f("hl_min_notional_usdc"))
        venue_max = _pos(_f("hl_max_notional_usdc"))

    lo = max([x for x in (entry_min, venue_min) if x is not None], default=None)
    hi = min([x for x in (entry_max, venue_max) if x is not None], default=None)
    return (None if lo is None else float(lo)), (None if hi is None else float(hi))


def _notional_diagnostics_from_cfg(cfg: Dict[str, Any]) -> Dict[str, Any]:
    def _f(k: str) -> Optional[float]:
        try:
            v = cfg.get(k)
            if v is None:
                return None
            x = float(v)
        except Exception:
            return None
        if not math.isfinite(float(x)):
            return None
        return float(x)

    def _pos(x: Optional[float]) -> Optional[float]:
        if x is None:
            return None
        if float(x) <= 0.0:
            return None
        return float(x)

    venue = str(cfg.get("execution_venue", "stub") or "stub").lower().strip()
    aster_enabled = (venue == "aster") or bool(cfg.get("aster_trading_enabled", False))
    hl_enabled = (venue == "hyperliquid") or bool(cfg.get("hl_trading_enabled", False))

    entry_min = _pos(_f("entry_min_notional_usdc"))
    entry_max = _pos(_f("entry_max_notional_usdc"))

    aster_min = _pos(_f("aster_min_notional_usdc"))
    aster_max = _pos(_f("aster_max_notional_usdc"))

    hl_min = _pos(_f("hl_min_notional_usdc"))
    hl_max = _pos(_f("hl_max_notional_usdc"))

    issues: List[Dict[str, Any]] = []
    if entry_min is not None and entry_max is not None and float(entry_min) > float(entry_max) + 1e-12:
        issues.append({"code": "entry_min_gt_entry_max", "severity": "high", "entry_min_notional_usdc": float(entry_min), "entry_max_notional_usdc": float(entry_max)})
    if aster_enabled and aster_min is not None and aster_max is not None and float(aster_min) > float(aster_max) + 1e-12:
        issues.append({"code": "aster_min_gt_aster_max", "severity": "high", "aster_min_notional_usdc": float(aster_min), "aster_max_notional_usdc": float(aster_max)})
    if hl_enabled and hl_min is not None and hl_max is not None and float(hl_min) > float(hl_max) + 1e-12:
        issues.append({"code": "hl_min_gt_hl_max", "severity": "high", "hl_min_notional_usdc": float(hl_min), "hl_max_notional_usdc": float(hl_max)})

    if aster_enabled:
        aster_eff_min, aster_eff_max = _effective_entry_notional_bounds("aster", cfg=cfg)
        if aster_eff_min is not None and aster_eff_max is not None and float(aster_eff_min) > float(aster_eff_max) + 1e-12:
            issues.append({"code": "aster_effective_range_empty", "severity": "high", "effective_min_notional_usdc": float(aster_eff_min), "effective_max_notional_usdc": float(aster_eff_max)})
    else:
        aster_eff_min, aster_eff_max = None, None

    if hl_enabled:
        hl_eff_min, hl_eff_max = _effective_entry_notional_bounds("hyperliquid", cfg=cfg)
        if hl_eff_min is not None and hl_eff_max is not None and float(hl_eff_min) > float(hl_eff_max) + 1e-12:
            issues.append({"code": "hl_effective_range_empty", "severity": "high", "effective_min_notional_usdc": float(hl_eff_min), "effective_max_notional_usdc": float(hl_eff_max)})
    else:
        hl_eff_min, hl_eff_max = None, None

    if aster_enabled and entry_max is not None and aster_max is not None and float(entry_max) > float(aster_max) + 1e-12:
        issues.append({"code": "entry_max_gt_aster_max", "severity": "medium", "entry_max_notional_usdc": float(entry_max), "aster_max_notional_usdc": float(aster_max)})
    if hl_enabled and entry_max is not None and hl_max is not None and float(entry_max) > float(hl_max) + 1e-12:
        issues.append({"code": "entry_max_gt_hl_max", "severity": "medium", "entry_max_notional_usdc": float(entry_max), "hl_max_notional_usdc": float(hl_max)})

    ok = True
    for it in issues:
        if str(it.get("severity")) == "high":
            ok = False
            break

    return {
        "ok": bool(ok),
        "venue": str(venue),
        "entry": {"min_notional_usdc": (None if entry_min is None else float(entry_min)), "max_notional_usdc": (None if entry_max is None else float(entry_max))},
        "aster": {
            "min_notional_usdc": (None if aster_min is None else float(aster_min)),
            "max_notional_usdc": (None if aster_max is None else float(aster_max)),
            "effective_min_notional_usdc": (None if aster_eff_min is None else float(aster_eff_min)),
            "effective_max_notional_usdc": (None if aster_eff_max is None else float(aster_eff_max)),
        },
        "hyperliquid": {
            "min_notional_usdc": (None if hl_min is None else float(hl_min)),
            "max_notional_usdc": (None if hl_max is None else float(hl_max)),
            "effective_min_notional_usdc": (None if hl_eff_min is None else float(hl_eff_min)),
            "effective_max_notional_usdc": (None if hl_eff_max is None else float(hl_eff_max)),
        },
        "issues": issues,
    }

def _compute_daily_indicators(daily_rows: List[Tuple[int, float, float, float, float, float]]) -> Dict[str, List[float]]:
    ts = [r[0] for r in daily_rows]
    close = [r[4] for r in daily_rows]
    high = [r[2] for r in daily_rows]
    low = [r[3] for r in daily_rows]
    ema_fast_d = _ema(close, 21)
    ema_slow_d = _ema(close, 59)
    ma_cross_fast_d = _ema(close, 66)
    ma_cross_slow_d = _ema(close, 121)
    rsi_d = _rsi(close, 14)
    willr_d = _willr(high, low, close, 14)
    macd_d, macdsignal_d, macdhist_d = _macd(close)
    return {
        "ts": ts,
        "ema_fast_d": ema_fast_d,
        "ema_slow_d": ema_slow_d,
        "ma_cross_fast_d": ma_cross_fast_d,
        "ma_cross_slow_d": ma_cross_slow_d,
        "rsi_d": rsi_d,
        "willr_d": willr_d,
        "macd_d": macd_d,
        "macdsignal_d": macdsignal_d,
        "macdhist_d": macdhist_d,
    }

def _features_at_timestamp(pair: str, open_ts: int) -> Dict[str, float]:
    c = _get_pair_cache(pair)
    hourly = c.get("hourly") or []
    hourly_ts = c.get("hourly_ts") or []
    hourly_close = c.get("hourly_close") or []
    hourly_logret = c.get("hourly_logret") or []
    di = c.get("di") or {}
    if not hourly or not hourly_ts or not di or not di.get("ts"):
        return {}
    di_ts = di["ts"]
    idx_d = max(0, min(len(di_ts) - 1, bisect_right(di_ts, int(open_ts)) - 1))
    idx_h = max(0, min(len(hourly_ts) - 1, bisect_right(hourly_ts, int(open_ts)) - 1))
    h_row = hourly[idx_h]
    f = {
        "close": float(h_row[4]),
        "volume": float(h_row[5]),
        "rsi_d": float(di["rsi_d"][idx_d]),
        "willr_d": float(di["willr_d"][idx_d]),
        "macd_d": float(di["macd_d"][idx_d]),
        "macdsignal_d": float(di["macdsignal_d"][idx_d]),
        "ma_cross_fast_d": float(di["ma_cross_fast_d"][idx_d]),
        "ma_cross_slow_d": float(di["ma_cross_slow_d"][idx_d]),
    }

    def _rv(end_idx: int, window_h: int) -> float:
        if not isinstance(hourly_logret, list) or len(hourly_logret) < (window_h + 2):
            return 0.0
        if end_idx <= 0:
            return 0.0
        end = max(1, min(int(end_idx), len(hourly_logret) - 1))
        beg = max(1, end - int(window_h) + 1)
        xs = [float(x) for x in hourly_logret[beg : end + 1]]
        if len(xs) < 2:
            return 0.0
        m = sum(xs) / float(len(xs))
        var = sum((x - m) ** 2 for x in xs) / float(max(1, len(xs) - 1))
        if var <= 0.0:
            return 0.0
        return float(math.sqrt(float(var)) * math.sqrt(float(len(xs))))

    rv_24h = _rv(idx_h, 24)
    rv_72h = _rv(idx_h, 72)
    rv_168h = _rv(idx_h, 168)
    f["rv_24h"] = float(rv_24h)
    f["rv_72h"] = float(rv_72h)
    f["rv_168h"] = float(rv_168h)
    f["rv_ratio_24_168"] = float((rv_24h / rv_168h) if rv_168h > 1e-12 else 0.0)

    funding_rate = 0.0
    basis_dev = 0.0
    try:
        fr, prem = _hl_funding_at_ts(_hl_coin_from_pair(pair), int(open_ts))
        funding_rate = float(fr)
        basis_dev = float(prem)
    except Exception:
        funding_rate = 0.0
        basis_dev = 0.0

    mark_oracle_dev = 0.0
    oi = 0.0
    try:
        ctx = _hl_asset_ctx_for_pair_near_realtime(pair=str(pair), ts_ms=int(open_ts))
    except Exception:
        ctx = {}
    if isinstance(ctx, dict) and ctx:
        try:
            if (not math.isfinite(float(funding_rate))) or float(funding_rate) == 0.0:
                funding_rate = float(ctx.get("funding") or 0.0)
        except Exception:
            pass
        try:
            if (not math.isfinite(float(basis_dev))) or float(basis_dev) == 0.0:
                basis_dev = float(ctx.get("premium") or 0.0)
        except Exception:
            pass
        try:
            mpx = float(ctx.get("markPx") or 0.0)
            opx = float(ctx.get("oraclePx") or 0.0)
            if opx > 0.0 and math.isfinite(mpx) and math.isfinite(opx):
                mark_oracle_dev = float((mpx - opx) / opx)
        except Exception:
            mark_oracle_dev = 0.0
        try:
            oi = float(ctx.get("openInterest") or 0.0)
        except Exception:
            oi = 0.0

    if not math.isfinite(float(funding_rate)):
        funding_rate = 0.0
    if not math.isfinite(float(basis_dev)):
        basis_dev = 0.0
    if not math.isfinite(float(mark_oracle_dev)):
        mark_oracle_dev = 0.0
    if not math.isfinite(float(oi)):
        oi = 0.0

    f["funding_rate"] = float(funding_rate)
    f["basis_dev"] = float(basis_dev)
    f["mark_oracle_dev"] = float(mark_oracle_dev)
    f["oi"] = float(oi)
    return f

def _models_dir() -> Path:
    candidates = _models_dirs_all()
    if not candidates:
        return Path(os.path.dirname(__file__)) / "models"

    def _count_artifacts(p: Path) -> int:
        try:
            if not p.exists():
                return 0
            return len(list(p.glob("*.pkl"))) + len(list(p.glob("*.pth")))
        except Exception:
            return 0

    best = candidates[0]
    best_n = _count_artifacts(best)
    for p in candidates[1:]:
        n = _count_artifacts(p)
        if n > best_n:
            best, best_n = p, n
    return best


def _models_dirs_all() -> List[Path]:
    p1 = Path(os.path.dirname(__file__)) / "user_data" / "models" / "ml3"
    p2 = Path(os.path.dirname(__file__)) / "user_data" / "models"
    p3 = Path(os.path.dirname(__file__)) / "models"
    out: List[Path] = []
    for p in (p1, p2, p3):
        if p.exists() and p not in out:
            out.append(p)
    return out

