def _safe_path_seg(s: str, *, fallback: str = "x", max_len: int = 80) -> str:
    raw = "" if s is None else str(s)
    raw = raw.strip()
    if not raw:
        return fallback
    raw = raw.replace(":", "__")
    out = []
    last_us = False
    for ch in raw:
        ok = ("a" <= ch <= "z") or ("A" <= ch <= "Z") or ("0" <= ch <= "9") or ch in {"-", "_", ".", "@"}
        if ok:
            out.append(ch)
            last_us = False
        else:
            if not last_us:
                out.append("_")
                last_us = True
    s2 = "".join(out).strip("._-")
    if not s2:
        s2 = fallback
    if len(s2) > int(max_len):
        s2 = s2[: int(max_len)]
    return s2

def _repo_slug_from_url(repo_url: Optional[str], repo_id: Optional[str] = None) -> str:
    s = "" if repo_url is None else str(repo_url).strip()
    if "github.com/" in s:
        try:
            parts = s.split("github.com/", 1)[1]
            parts = parts.split("?", 1)[0].split("#", 1)[0].strip("/")
            segs = [p for p in parts.split("/") if p]
            if len(segs) >= 2:
                owner = _safe_path_seg(segs[0], fallback="gh", max_len=60)
                repo = _safe_path_seg(segs[1].replace(".git", ""), fallback="repo", max_len=80)
                return f"{owner}__{repo}"
        except Exception:
            pass
    if s:
        return _safe_path_seg(s.rsplit("/", 1)[-1].replace(".git", ""), fallback=(repo_id or "repo"), max_len=100)
    return _safe_path_seg(repo_id or "repo", fallback="repo", max_len=100)

def _github_asset_dirs_prepare() -> Dict[str, Any]:
    root = _github_strategies_dir()
    cats = {
        "by_family": root / "_by_family",
        "by_stage": root / "_by_stage",
        "by_tier": root / "_by_tier",
        "by_market": root / "_by_market",
        "by_tag": root / "_by_tag",
    }
    for p in cats.values():
        try:
            p.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
    return {"root": root, "cats": {k: str(v) for k, v in cats.items()}}

def _github_mirror_path(*, repo_slug: str, subpath: Optional[str], strategy_id: str) -> Path:
    root = _github_strategies_dir()
    repo_dir = root / _safe_path_seg(repo_slug, fallback="repo", max_len=120)
    p = repo_dir
    if subpath:
        try:
            segs = [x for x in str(subpath).replace("\\", "/").split("/") if x and x not in {".", ".."}]
        except Exception:
            segs = []
        for seg in segs[:10]:
            p = p / _safe_path_seg(seg, fallback="p", max_len=80)
    name = _safe_path_seg(strategy_id, fallback="strategy", max_len=120)
    if not name.lower().endswith(".py"):
        name = f"{name}.py"
    return p / name

def _symlink_or_copy(src: Path, dst: Path) -> Tuple[bool, str]:
    sp = Path(src)
    dp = Path(dst)
    try:
        dp.parent.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    try:
        if dp.exists() or dp.is_symlink():
            try:
                if dp.is_symlink():
                    cur = os.readlink(str(dp))
                    if str(cur) == str(sp):
                        return True, "kept"
                dp.unlink()
            except Exception:
                try:
                    if dp.exists() and dp.is_file():
                        dp.unlink()
                except Exception:
                    pass
    except Exception:
        pass
    try:
        os.symlink(str(sp), str(dp))
        return True, "symlink"
    except Exception:
        try:
            shutil.copy2(sp, dp)
            return True, "copy"
        except Exception as e:
            return False, str(e)

def _strategy_market_bucket(entry: Dict[str, Any], mirror_path: Optional[Path]) -> str:
    try:
        src_ms = entry.get("metrics_summary") if isinstance(entry.get("metrics_summary"), dict) else {}
        bt = entry.get("backtest_spec") if isinstance(entry.get("backtest_spec"), dict) else {}
        mt = (bt.get("market_type") if bt.get("market_type") is not None else src_ms.get("market_type"))
        mt_s = str(mt or "").strip().lower()
        if mt_s in {"spot", "futures"}:
            return mt_s
    except Exception:
        pass
    if mirror_path is not None and mirror_path.exists() and mirror_path.is_file():
        try:
            sig = _strategy_signature_scan(mirror_path)
            if isinstance(sig, dict):
                s2 = sig.get("signals") if isinstance(sig.get("signals"), dict) else {}
                if bool(s2.get("explicit_futures")):
                    return "futures"
                return "spot"
        except Exception:
            pass
    return "unknown"

def _github_asset_reconcile_for_entry(entry: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(entry, dict):
        return {"ok": False, "error": "bad_entry"}
    src = entry.get("source") if isinstance(entry.get("source"), dict) else {}
    if str(src.get("kind") or "").strip().lower() != "github":
        return {"ok": True, "skipped": True}

    _github_asset_dirs_prepare()
    repo_url = str(src.get("repo_url") or "").strip()
    repo_id = str(src.get("repo_id") or "").strip()
    repo_slug = _repo_slug_from_url(repo_url, repo_id=repo_id or None)
    subpath = (None if src.get("path") is None else str(src.get("path") or "").strip()) or None
    sid = str(entry.get("strategy_id") or "").strip()
    if not sid:
        return {"ok": False, "error": "missing_strategy_id"}

    mirror = None
    mirror_in = str(src.get("asset_mirror_path") or "").strip()
    if mirror_in:
        try:
            mirror = Path(mirror_in)
        except Exception:
            mirror = None
    if mirror is None:
        mirror = _github_mirror_path(repo_slug=repo_slug, subpath=subpath, strategy_id=sid)

    copied_from = None
    mirror_ok = False
    try:
        if mirror.exists() and mirror.is_file():
            try:
                txt = mirror.read_text(encoding="utf-8", errors="ignore")
            except Exception:
                txt = mirror.read_text(errors="ignore")
            low = txt.lower()
            sid_low = sid.lower()
            if sid_low and (f"class {sid_low}" in low or f"class\t{sid_low}" in low):
                mirror_ok = True
    except Exception:
        mirror_ok = False

    if not mirror_ok:
        spath = str(src.get("sandbox_path") or "").strip()
        picked = None
        if spath:
            sp = Path(spath)
            if sp.exists() and sp.is_dir():
                try:
                    cands = list(sp.glob("*.py"))
                except Exception:
                    cands = []
                sid_low = sid.lower()
                exact = [x for x in cands if x.stem.lower() == sid_low]
                contain = [x for x in cands if sid_low and sid_low in x.stem.lower()]
                picked = exact[0] if exact else (contain[0] if contain else None)
        if picked is None:
            try:
                root = _github_strategies_dir()
                name = sid if sid.lower().endswith(".py") else f"{sid}.py"
                sid_low = sid.lower()
                found: List[Path] = []
                for dirpath, dirnames, filenames in os.walk(str(root)):
                    dirnames[:] = [d for d in dirnames if (not str(d).startswith("_by_")) and d != "__pycache__"]
                    if name not in filenames:
                        continue
                    p0 = Path(dirpath) / name
                    try:
                        low = p0.read_text(encoding="utf-8", errors="ignore").lower()
                    except Exception:
                        try:
                            low = p0.read_text(errors="ignore").lower()
                        except Exception:
                            low = ""
                    if sid_low and (f"class {sid_low}" in low or f"class\t{sid_low}" in low):
                        found.append(p0)
                    if len(found) >= 3:
                        break
                if found:
                    picked = found[0]
            except Exception:
                pass
        if picked is None and repo_url:
            commit = str(src.get("commit") or "").strip() or None
            branch = (None if src.get("branch") is None else str(src.get("branch") or "").strip()) or None
            ok, head, repo_path, err = _repo_ensure_cached(repo_url, branch=branch, commit=commit)
            if ok and repo_path is not None:
                cm = str(commit or head or "").strip() or "HEAD"
                ok2, sand, copied, _e2, _diff = _strategy_sandbox_stage_from_git(repo_path, subpath, repo_id or _repo_id_from_url(repo_url), cm, strategy_name=sid)
                if ok2 and sand:
                    try:
                        sp2 = Path(sand)
                        cands2 = list(sp2.glob("*.py"))
                    except Exception:
                        cands2 = []
                    sid_low = sid.lower()
                    exact2 = [x for x in cands2 if x.stem.lower() == sid_low]
                    contain2 = [x for x in cands2 if sid_low and sid_low in x.stem.lower()]
                    picked = exact2[0] if exact2 else (contain2[0] if contain2 else None)
            else:
                copied_from = f"repo_fetch_failed:{str(err)}"
        if picked is not None and picked.exists() and picked.is_file():
            try:
                mirror.parent.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            try:
                shutil.copy2(picked, mirror)
                copied_from = str(picked)
            except Exception as e:
                return {"ok": False, "error": "mirror_write_failed", "detail": str(e)}

    market = _strategy_market_bucket(entry, mirror)
    family = _strategy_family_normalize(entry.get("family")) or "trend"
    stage = _strategy_stage_normalize(entry.get("stage")) or "research"
    tier = str(entry.get("tier") or "unrated").strip().upper() or "UNRATED"
    tags = entry.get("tags") if isinstance(entry.get("tags"), list) else []
    tags2: List[str] = []
    for t in tags:
        s = str(t or "").strip()
        if s and s not in tags2:
            tags2.append(s)
        if len(tags2) >= 12:
            break

    base_name = f"{_safe_path_seg(repo_slug, fallback='repo', max_len=80)}__{_safe_path_seg(sid, fallback='strategy', max_len=120)}.py"
    root = _github_strategies_dir()
    links: List[str] = []
    targets: List[Tuple[Path, Path]] = []
    targets.append((mirror, root / "_by_family" / _safe_path_seg(family, fallback="trend", max_len=40) / base_name))
    targets.append((mirror, root / "_by_stage" / _safe_path_seg(stage, fallback="research", max_len=40) / base_name))
    targets.append((mirror, root / "_by_tier" / _safe_path_seg(tier, fallback="UNRATED", max_len=40) / base_name))
    targets.append((mirror, root / "_by_market" / _safe_path_seg(market, fallback="unknown", max_len=40) / base_name))
    for t in tags2[:8]:
        targets.append((mirror, root / "_by_tag" / _safe_path_seg(t, fallback="tag", max_len=60) / base_name))

    link_states: List[Dict[str, Any]] = []
    for sp, dp in targets:
        ok, mode = _symlink_or_copy(sp, dp)
        link_states.append({"ok": bool(ok), "mode": mode, "dst": str(dp)})
        if ok:
            links.append(str(dp))

    src2 = dict(src)
    src2["asset_repo_slug"] = repo_slug
    src2["asset_mirror_path"] = str(mirror)
    src2["asset_links"] = links
    src2["asset_bucket"] = {"family": family, "stage": stage, "tier": tier, "market": market}
    entry["source"] = src2
    return {"ok": True, "mirror": str(mirror), "copied_from": copied_from, "links": link_states}

def _repo_whitelist_list() -> List[str]:
    raw = CONFIG.get("repo_whitelist")
    if not isinstance(raw, list):
        return []
    out: List[str] = []
    for it in raw:
        s = str(it or "").strip()
        if not s:
            continue
        s_norm = _normalize_repo_url(s) or s
        if s_norm and s_norm not in out:
            out.append(s_norm)
    return out

def _repo_whitelist_set(items: List[str]) -> List[str]:
    out: List[str] = []
    for it in items:
        s = str(it or "").strip()
        if not s:
            continue
        s_norm = _normalize_repo_url(s) or s
        if s_norm and s_norm not in out:
            out.append(s_norm)
    CONFIG["repo_whitelist"] = out
    try:
        _save_config()
    except Exception:
        pass
    return out

def _repo_registry_get() -> Dict[str, Any]:
    raw = CONFIG.get("repo_registry")
    if not isinstance(raw, dict):
        return {}
    return raw

def _repo_registry_put(reg: Dict[str, Any]) -> None:
    CONFIG["repo_registry"] = reg
    try:
        _save_config()
    except Exception:
        pass

def _repo_fetch_enabled() -> bool:
    return bool(CONFIG.get("repo_fetch_enabled", False))

def _parse_github_tree_url(url: str) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    s = "" if url is None else str(url).strip()
    if not s:
        return None, None, None
    if "github.com/" not in s:
        return None, None, None
    try:
        parts = s.split("github.com/", 1)[1]
        parts = parts.split("?", 1)[0].split("#", 1)[0]
        parts = parts.strip("/")
        segs = [p for p in parts.split("/") if p]
        if len(segs) < 2:
            return None, None, None
        owner, repo = segs[0], segs[1]
        if repo.endswith(".git"):
            repo = repo[:-4]
        branch = None
        subpath = None
        if len(segs) >= 4 and segs[2] in {"tree", "blob"}:
            branch = segs[3]
            rest = segs[4:]
            if rest:
                subpath = "/".join(rest)
        repo_url = f"https://github.com/{owner}/{repo}.git"
        return repo_url, branch, subpath
    except Exception:
        return None, None, None

def _normalize_repo_url(repo_url: str) -> Optional[str]:
    s = "" if repo_url is None else str(repo_url).strip()
    if not s:
        return None
    if "github.com/" in s:
        repo_git, _, _ = _parse_github_tree_url(s)
        if repo_git:
            return repo_git
        s2 = s.split("?", 1)[0].split("#", 1)[0].rstrip("/")
        if s2.startswith("https://github.com/") or s2.startswith("http://github.com/"):
            segs = s2.split("/")
            if len(segs) >= 5:
                base = "/".join(segs[:5])
                if not base.endswith(".git"):
                    base = base + ".git"
                return base
    return s

def _repo_url_allowed(repo_url: str) -> bool:
    wl = _repo_whitelist_list()
    if not wl:
        return False
    repo_n = _normalize_repo_url(repo_url) or str(repo_url).strip()
    wl_n = {_normalize_repo_url(x) or str(x).strip() for x in wl if str(x or "").strip()}
    return repo_n in wl_n

def _repo_id_from_url(repo_url: str) -> str:
    h = hashlib.sha1(str(repo_url).encode("utf-8")).hexdigest()
    return h[:16]

def _git_available() -> bool:
    return bool(shutil.which("git"))

def _git_run(args: List[str], cwd: Path, timeout_sec: float = 60.0) -> Tuple[bool, str, str]:
    try:
        env = dict(os.environ)
        env["GIT_TERMINAL_PROMPT"] = "0"
        r = subprocess.run(args, cwd=str(cwd), capture_output=True, text=True, timeout=float(timeout_sec), env=env)
        ok = (r.returncode == 0)
        out = r.stdout or ""
        err = r.stderr or ""
        if (not ok) and ("http2" in err.lower()):
            args2 = list(args)
            if args2 and (str(args2[0]) == "git") and ("http.version=HTTP/1.1" not in " ".join([str(x) for x in args2])):
                args2 = ["git", "-c", "http.version=HTTP/1.1", *args2[1:]]
                r2 = subprocess.run(args2, cwd=str(cwd), capture_output=True, text=True, timeout=float(timeout_sec), env=env)
                return (r2.returncode == 0, r2.stdout or "", r2.stderr or "")
        return (ok, out, err)
    except Exception as e:
        return (False, "", str(e))

def _repo_update_registry(repo_id: str, repo_url: str, repo_path: Path, commit: str) -> None:
    reg = _repo_registry_get()
    reg[str(repo_id)] = {
        "repo_url": str(repo_url),
        "path": str(repo_path),
        "commit": str(commit or ""),
        "ts": int(_now_ms()),
    }
    _repo_registry_put(reg)

def _repo_checkout(repo_path: Path, branch: Optional[str] = None, commit: Optional[str] = None) -> Tuple[bool, Optional[str], str]:
    if branch:
        ok, _, err = _git_run(["git", "checkout", str(branch)], cwd=repo_path, timeout_sec=30.0)
        if not ok:
            return False, None, err
        _git_run(["git", "reset", "--hard", f"origin/{str(branch)}"], cwd=repo_path, timeout_sec=30.0)
    if commit:
        ok, _, err = _git_run(["git", "checkout", str(commit)], cwd=repo_path, timeout_sec=30.0)
        if not ok:
            return False, None, err
    ok, out, err = _git_run(["git", "rev-parse", "HEAD"], cwd=repo_path, timeout_sec=15.0)
    if not ok:
        return False, None, err
    return True, str(out).strip(), ""

def _repo_ensure_cached(repo_url: str, branch: Optional[str] = None, commit: Optional[str] = None) -> Tuple[bool, Optional[str], Optional[Path], str]:
    if not _git_available():
        return False, None, None, "git_not_available"
    repo_id = _repo_id_from_url(repo_url)
    repo_path = _agent_repo_dir() / repo_id
    if repo_path.exists() and (repo_path / ".git").exists():
        _git_run(["git", "fetch", "--all", "--prune"], cwd=repo_path, timeout_sec=60.0)
    else:
        ok, _, err = _git_run(["git", "clone", str(repo_url), str(repo_path)], cwd=_agent_repo_dir(), timeout_sec=120.0)
        if not ok:
            return False, None, None, err
    if (not branch) and (not commit):
        ok, out, _ = _git_run(["git", "symbolic-ref", "refs/remotes/origin/HEAD"], cwd=repo_path, timeout_sec=10.0)
        ref = str(out or "").strip() if ok else ""
        if ref.startswith("refs/remotes/origin/"):
            branch = ref.rsplit("/", 1)[-1].strip() or None
    ok, head, err = _repo_checkout(repo_path, branch=branch, commit=commit)
    if not ok:
        return False, None, None, err
    return True, head, repo_path, ""


def _repo_resolve_commit(repo_path: Path, branch: Optional[str] = None, commit: Optional[str] = None) -> Tuple[bool, Optional[str], str]:
    ref = None
    if commit:
        ref = str(commit).strip()
    elif branch:
        ref = f"origin/{str(branch).strip()}"
    if not ref:
        ref = "HEAD"
    ok, out, err = _git_run(["git", "rev-parse", f"{ref}^{{commit}}"], cwd=repo_path, timeout_sec=15.0)
    if not ok:
        if (not branch) and (not commit):
            ok2, out2, _ = _git_run(["git", "symbolic-ref", "refs/remotes/origin/HEAD"], cwd=repo_path, timeout_sec=10.0)
            ref2 = str(out2 or "").strip() if ok2 else ""
            if ref2.startswith("refs/remotes/origin/"):
                b2 = ref2.rsplit("/", 1)[-1].strip()
                if b2:
                    ok3, out3, err3 = _git_run(["git", "rev-parse", f"origin/{b2}^{{commit}}"], cwd=repo_path, timeout_sec=15.0)
                    if ok3:
                        return True, str(out3).strip(), ""
                    return False, None, err3
        return False, None, err
    return True, str(out).strip(), ""


def _repo_ensure_cached_meta(repo_url: str, branch: Optional[str] = None, commit: Optional[str] = None) -> Tuple[bool, Optional[str], Optional[Path], str]:
    if not _git_available():
        return False, None, None, "git_not_available"
    repo_id = _repo_id_from_url(repo_url)
    repo_path = _agent_repo_dir() / repo_id
    if repo_path.exists() and (repo_path / ".git").exists():
        _git_run(["git", "fetch", "--all", "--prune"], cwd=repo_path, timeout_sec=60.0)
    else:
        ok, _, err = _git_run(
            ["git", "clone", "--filter=blob:none", "--no-checkout", str(repo_url), str(repo_path)],
            cwd=_agent_repo_dir(),
            timeout_sec=120.0,
        )
        if not ok:
            return False, None, None, err
    ok, head, err = _repo_resolve_commit(repo_path, branch=branch, commit=commit)
    if not ok:
        return False, None, None, err
    return True, head, repo_path, ""


def _repo_list_files(repo_path: Path, commit: str, subpath: Optional[str] = None) -> List[str]:
    args = ["git", "ls-tree", "-r", "--name-only", str(commit)]
    sp = (None if subpath is None else str(subpath).strip())
    if sp:
        args += ["--", sp]
    ok, out, _ = _git_run(args, cwd=repo_path, timeout_sec=20.0)
    if not ok:
        return []
    items = []
    for line in str(out).splitlines():
        s = str(line).strip()
        if s:
            items.append(s)
    return items


def _repo_show_bytes(repo_path: Path, commit: str, file_path: str, *, max_bytes: int = 2_000_000) -> Tuple[bool, Optional[bytes], str]:
    p = str(file_path or "").strip()
    if (not p) or (".." in p) or p.startswith("/") or p.startswith("\\"):
        return False, None, "bad_file_path"
    ok, out, err = _git_run(["git", "show", f"{str(commit)}:{p}"], cwd=repo_path, timeout_sec=30.0)
    if not ok:
        return False, None, err
    try:
        b = str(out).encode("utf-8", errors="ignore")
    except Exception:
        return False, None, "encode_failed"
    if len(b) > int(max_bytes):
        return False, None, "file_too_large"
    return True, b, ""


def _strategy_signature_extract(path: str, content: str) -> Dict[str, Any]:
    out: Dict[str, Any] = {"file": str(Path(path).name), "class_name": None, "timeframe": None, "pairlist_mode": None, "required_parameters": None}
    try:
        tree = ast.parse(content, filename=str(path))
    except Exception as e:
        out["parse_error"] = str(e)
        return out

    def _is_istrategy_base(b: ast.expr) -> bool:
        try:
            if isinstance(b, ast.Name):
                return str(b.id) == "IStrategy"
            if isinstance(b, ast.Attribute):
                return str(b.attr) == "IStrategy"
        except Exception:
            return False
        return False

    target_cls: Optional[ast.ClassDef] = None
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        if any(_is_istrategy_base(b) for b in (node.bases or [])):
            target_cls = node
            out["class_name"] = str(node.name)
            break

    def _lit(v: ast.AST) -> Any:
        try:
            return ast.literal_eval(v)
        except Exception:
            return None

    if target_cls is not None:
        for node in target_cls.body:
            if isinstance(node, ast.Assign) and node.targets:
                t0 = node.targets[0]
                if isinstance(t0, ast.Name):
                    key = str(t0.id)
                    if key in {"timeframe", "pairlist_mode", "required_parameters"}:
                        out[key] = _lit(node.value)
            if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                key = str(node.target.id)
                if key in {"timeframe", "pairlist_mode", "required_parameters"}:
                    out[key] = _lit(node.value) if node.value is not None else None
    return out


def _strategy_schema_compat(signature: Dict[str, Any]) -> Dict[str, Any]:
    reasons: List[str] = []
    cls = signature.get("class_name")
    tf = signature.get("timeframe")
    if not cls:
        reasons.append("missing_istrategy_class")
    if not (isinstance(tf, str) and tf.strip()):
        reasons.append("missing_timeframe")
    rp = signature.get("required_parameters")
    if rp is not None and not isinstance(rp, (list, tuple, dict)):
        reasons.append("bad_required_parameters_type")
    pm = signature.get("pairlist_mode")
    if pm is not None and not (isinstance(pm, str) and pm.strip()):
        reasons.append("bad_pairlist_mode")
    status = "pass" if not reasons else ("fail" if any(r in {"missing_istrategy_class", "missing_timeframe"} for r in reasons) else "warn")
    return {"status": status, "reasons": reasons}


def _strategy_dependency_scan(content: str) -> Dict[str, Any]:
    try:
        tree = ast.parse(content)
    except Exception:
        return {"imports": [], "unknown": [], "allowlist": []}
    mods: List[str] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names or []:
                m = str(getattr(a, "name", "") or "")
                if m:
                    mods.append(m.split(".", 1)[0])
        if isinstance(node, ast.ImportFrom):
            m = str(getattr(node, "module", "") or "")
            if m:
                mods.append(m.split(".", 1)[0])
    uniq = []
    for m in mods:
        if m and m not in uniq:
            uniq.append(m)
    allow = {
        "collections",
        "copy",
        "dataclasses",
        "datetime",
        "decimal",
        "enum",
        "functools",
        "itertools",
        "json",
        "logging",
        "math",
        "operator",
        "os",
        "pathlib",
        "pprint",
        "random",
        "re",
        "statistics",
        "time",
        "typing",
        "uuid",

        "freqtrade",
        "numpy",
        "pandas",
        "qtpylib",
        "talib",
        "technical",
    }
    unknown = [m for m in uniq if m not in allow]
    return {"imports": uniq, "unknown": unknown, "allowlist": sorted(list(allow))}

def _strategy_existing_ids() -> set:
    out: set = set()
    try:
        p = _user_data_dir() / "strategies"
        for fp in p.rglob("*.py"):
            if not fp.is_file():
                continue
            try:
                txt = fp.read_text(encoding="utf-8", errors="ignore")
            except Exception:
                continue
            try:
                tree = ast.parse(txt)
            except Exception:
                continue
            for node in tree.body:
                if not isinstance(node, ast.ClassDef):
                    continue
                is_is = False
                for b in (node.bases or []):
                    try:
                        if isinstance(b, ast.Name) and str(b.id) == "IStrategy":
                            is_is = True
                        elif isinstance(b, ast.Attribute) and str(b.attr) == "IStrategy":
                            is_is = True
                    except Exception:
                        continue
                if is_is:
                    nm = str(node.name or "").strip()
                    if nm:
                        out.add(nm)
    except Exception:
        pass
    try:
        p = _user_data_dir() / "strategy_registry.db"
        if p.exists() and p.is_file():
            conn = sqlite3.connect(str(p))
            try:
                cur = conn.execute("select strategy_id from registry_entries")
                for row in cur.fetchall():
                    try:
                        nm = str(row[0] or "").strip()
                    except Exception:
                        nm = ""
                    if nm:
                        out.add(nm)
            finally:
                try:
                    conn.close()
                except Exception:
                    pass
    except Exception:
        pass
    return out

def _strategy_name_sanitize(name: str) -> str:
    s = re.sub(r"[^A-Za-z0-9_]+", "_", str(name or "").strip())
    if not s:
        return "Strategy"
    if s[0].isdigit():
        s = "S_" + s
    return s[:80]

def _strategy_code_canon_bytes(text: str) -> bytes:
    try:
        s = str(text or "")
        s = s.replace("\r\n", "\n").replace("\r", "\n")
        lines = s.split("\n")
        s2 = "\n".join([ln.rstrip() for ln in lines])
        return s2.encode("utf-8", errors="ignore")
    except Exception:
        try:
            return str(text or "").encode("utf-8", errors="ignore")
        except Exception:
            return b""

def _strategy_code_sha256(text: str) -> str:
    return hashlib.sha256(_strategy_code_canon_bytes(text)).hexdigest()

def _strategy_find_existing_file_for_class(cls: str) -> Optional[Path]:
    name = str(cls or "").strip()
    if not name:
        return None
    root = _user_data_dir() / "strategies"
    pat = None
    try:
        pat = re.compile(rf"(^\s*class\s+){re.escape(name)}(\s*\()", flags=re.MULTILINE)
    except Exception:
        pat = None
    try:
        for fp in root.rglob("*.py"):
            if not fp.is_file():
                continue
            if "__pycache__" in fp.parts:
                continue
            if fp.name == f"{name}.py":
                return fp
    except Exception:
        pass
    try:
        for fp in root.rglob("*.py"):
            if not fp.is_file():
                continue
            if "__pycache__" in fp.parts:
                continue
            if fp.name.lower() == f"{name.lower()}.py":
                return fp
            if pat is None:
                continue
            try:
                txt = fp.read_text(encoding="utf-8", errors="ignore")
            except Exception:
                continue
            if pat.search(txt):
                return fp
    except Exception:
        pass
    return None

def _strategy_existing_class_sha256(cls: str) -> Optional[str]:
    fp = _strategy_find_existing_file_for_class(cls)
    if fp is None:
        return None
    try:
        txt = fp.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        try:
            txt = fp.read_text(errors="ignore")
        except Exception:
            return None
    return _strategy_code_sha256(txt)

def _strategy_name_unique(base: str, *, existing: set, repo_id: str) -> str:
    b0 = _strategy_name_sanitize(base)
    if b0 not in existing:
        return b0
    for i in range(2, 2000):
        cand = _strategy_name_sanitize(f"{b0}_{i}")
        if cand not in existing:
            return cand
    suf = _strategy_name_sanitize(f"{b0}_ft_{str(repo_id)[:6]}")
    if suf not in existing:
        return suf
    for i in range(2, 2000):
        cand = _strategy_name_sanitize(f"{suf}_{i}")
        if cand not in existing:
            return cand
    return _strategy_name_sanitize(f"{b0}_{uuid.uuid4().hex[:6]}")

def _strategy_rewrite_class_name(src: str, old: str, new: str) -> Tuple[bool, str]:
    if not old or not new or old == new:
        return True, src
    try:
        pat = re.compile(rf"(^\s*class\s+){re.escape(str(old))}(\s*\()", flags=re.MULTILINE)
        out, n = pat.subn(rf"\1{str(new)}\2", src, count=1)
        if n <= 0:
            return False, src
        return True, out
    except Exception:
        return False, src

def _strategy_sandbox_align_and_dedupe(sandbox_root: Path, *, repo_id: str, preferred_name: Optional[str] = None) -> Dict[str, Any]:
    out: Dict[str, Any] = {"ok": True, "renamed": [], "effective_strategy_name": None}
    root = Path(sandbox_root)
    try:
        root = root.resolve()
    except Exception:
        return {"ok": False, "error": "bad_sandbox_path"}
    py_files = [p for p in root.glob("*.py") if p.is_file()]
    if not py_files:
        return {"ok": False, "error": "no_strategy_files"}
    existing = _strategy_existing_ids()
    renamed: List[Dict[str, Any]] = []
    effective = None
    for fp in py_files[:50]:
        try:
            txt0 = fp.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue
        sig0 = _strategy_signature_extract(str(fp), txt0)
        cls0 = str(sig0.get("class_name") or "").strip()
        if not cls0:
            continue
        target = cls0
        if preferred_name and len(py_files) == 1:
            pn = str(preferred_name).strip()
            if pn and pn.lower().endswith(".py"):
                pn = Path(pn).stem
            if pn:
                target = pn
        target = _strategy_name_sanitize(target)
        if target != cls0:
            ok_rw, txt1 = _strategy_rewrite_class_name(txt0, cls0, target)
            if ok_rw:
                try:
                    fp.write_text(txt1, encoding="utf-8")
                    cls0 = target
                except Exception:
                    pass
        try:
            if cls0 in existing:
                ex_sha = _strategy_existing_class_sha256(cls0)
                if ex_sha:
                    try:
                        cur_txt = fp.read_text(encoding="utf-8", errors="ignore")
                    except Exception:
                        cur_txt = txt0 if cls0 == str(sig0.get("class_name") or "").strip() else fp.read_text(errors="ignore")
                    cur_sha = _strategy_code_sha256(cur_txt)
                    if cur_sha == ex_sha:
                        ex_fp = _strategy_find_existing_file_for_class(cls0)
                        return {"ok": False, "error": "duplicate_strategy_same_content", "strategy_name": cls0, "existing_path": (None if ex_fp is None else str(ex_fp))}
        except Exception:
            pass
        unique = _strategy_name_unique(cls0, existing=existing, repo_id=repo_id)
        old_file = fp.name
        old_cls = str(sig0.get("class_name") or "").strip()
        if unique != cls0:
            ok_rw2, txt2 = _strategy_rewrite_class_name(txt0 if cls0 == old_cls else fp.read_text(encoding="utf-8", errors="ignore"), cls0, unique)
            if ok_rw2:
                try:
                    fp.write_text(txt2, encoding="utf-8")
                except Exception:
                    pass
        new_file = f"{unique}.py"
        if fp.name != new_file:
            try:
                (root / new_file).unlink()
            except Exception:
                pass
            try:
                fp.rename(root / new_file)
            except Exception:
                pass
        existing.add(unique)
        if len(py_files) == 1:
            effective = unique
        if old_file != new_file or old_cls != unique:
            renamed.append({"from_file": old_file, "to_file": new_file, "from_class": old_cls, "to_class": unique})
    out["renamed"] = renamed
    out["effective_strategy_name"] = effective
    return out


def _strategy_futures_risk_scan(content: str, signature: Dict[str, Any]) -> Dict[str, Any]:
    low = str(content or "").lower()
    flags: List[str] = []

    can_short_attr = False
    can_short_true = False
    has_leverage_method = False
    has_leverage_attr = False
    has_stoploss = False
    has_minimal_roi = False
    has_trailing_stop = False
    has_protections = False

    try:
        tree = ast.parse(content)
        target_cls = signature.get("class_name")
        class_nodes = [n for n in ast.walk(tree) if isinstance(n, ast.ClassDef)]
        if isinstance(target_cls, str) and target_cls.strip():
            class_nodes = [n for n in class_nodes if str(getattr(n, "name", "")) == target_cls] or class_nodes

        def _is_true_literal(node: ast.AST) -> bool:
            return isinstance(node, ast.Constant) and node.value is True

        for cls in class_nodes:
            for node in cls.body:
                if isinstance(node, ast.FunctionDef):
                    if str(node.name) == "leverage":
                        has_leverage_method = True
                    continue
                if isinstance(node, ast.Assign) and node.targets:
                    t0 = node.targets[0]
                    if isinstance(t0, ast.Name):
                        key = str(t0.id)
                        if key == "can_short":
                            can_short_attr = True
                            can_short_true = can_short_true or _is_true_literal(node.value)
                        elif key == "leverage":
                            has_leverage_attr = True
                        elif key == "stoploss":
                            has_stoploss = True
                        elif key == "minimal_roi":
                            has_minimal_roi = True
                        elif key == "trailing_stop":
                            has_trailing_stop = True
                        elif key == "protections":
                            has_protections = True
                if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                    key = str(node.target.id)
                    if key == "can_short":
                        can_short_attr = True
                        if node.value is not None:
                            can_short_true = can_short_true or _is_true_literal(node.value)
                    elif key == "leverage":
                        has_leverage_attr = True
                    elif key == "stoploss":
                        has_stoploss = True
                    elif key == "minimal_roi":
                        has_minimal_roi = True
                    elif key == "trailing_stop":
                        has_trailing_stop = True
                    elif key == "protections":
                        has_protections = True
    except Exception:
        can_short_attr = ("can_short" in low)
        can_short_true = ("can_short = true" in low)
        has_leverage_method = ("def leverage" in low)
        has_leverage_attr = ("leverage" in low)
        has_stoploss = ("stoploss" in low)
        has_minimal_roi = ("minimal_roi" in low)
        has_trailing_stop = ("trailing_stop" in low)
        has_protections = ("protections" in low)

    explicit_futures = bool(can_short_true or has_leverage_method or has_leverage_attr)
    if can_short_attr:
        flags.append("mentions_can_short")
    if has_leverage_method or has_leverage_attr:
        flags.append("mentions_leverage")
    if "position_adjustment" in low or "adjust_trade_position" in low:
        flags.append("uses_position_adjustment")

    if explicit_futures:
        if not has_stoploss:
            flags.append("missing_stoploss")
        if not has_minimal_roi:
            flags.append("missing_minimal_roi")
        if not has_trailing_stop:
            flags.append("missing_trailing_stop")
        if not has_protections:
            flags.append("missing_protections")

    out = {
        "flags": flags,
        "signals": {
            "explicit_futures": bool(explicit_futures),
            "has_can_short_attr": bool(can_short_attr),
            "has_can_short": bool(can_short_true),
            "has_leverage": bool(has_leverage_method or has_leverage_attr),
            "has_stoploss": bool(has_stoploss),
            "has_minimal_roi": bool(has_minimal_roi),
            "has_trailing_stop": bool(has_trailing_stop),
            "has_protections": bool(has_protections),
        },
    }
    try:
        out["timeframe"] = signature.get("timeframe")
        out["pairlist_mode"] = signature.get("pairlist_mode")
    except Exception:
        pass
    return out


def _strategy_sandbox_stage_from_git(
    repo_path: Path,
    subpath: Optional[str],
    repo_id: str,
    commit: str,
    strategy_name: Optional[str] = None,
    *,
    max_bytes_per_file: int = 2_000_000,
) -> Tuple[bool, Optional[str], List[str], str, Optional[str]]:
    all_files = _repo_list_files(repo_path, str(commit), subpath=subpath)
    py_files = [p for p in all_files if str(p).lower().endswith(".py")]
    if not py_files:
        return False, None, [], "no_strategy_files", None
    if strategy_name:
        nm = str(strategy_name).strip().lower()
        if nm:
            if not nm.endswith(".py"):
                nm2 = nm + ".py"
            else:
                nm2 = nm
            filt = [p for p in py_files if str(Path(p).name).lower() in {nm2, nm} or str(Path(p).stem).lower() == nm.replace(".py", "")]
            if filt:
                py_files = filt
            else:
                return False, None, [], "strategy_file_not_found", None

    sandbox_root = _strategy_sandbox_dir() / str(repo_id) / str(commit or "HEAD")
    try:
        if sandbox_root.exists():
            shutil.rmtree(sandbox_root)
    except Exception:
        pass
    try:
        sandbox_root.mkdir(parents=True, exist_ok=True)
    except Exception:
        return False, None, [], "sandbox_create_failed", None

    copied: List[str] = []
    used_names: set = set()
    for rp in py_files:
        ok, b, _ = _repo_show_bytes(repo_path, str(commit), str(rp), max_bytes=int(max_bytes_per_file))
        if (not ok) or b is None:
            continue
        name = str(Path(rp).name)
        if name in used_names:
            continue
        used_names.add(name)
        dst = sandbox_root / name
        try:
            dst.write_bytes(b)
            copied.append(str(dst.name))
        except Exception:
            continue
    if not copied:
        return False, None, [], "sandbox_copy_failed", None
    diff_summary = None
    ok, out, _ = _git_run(["git", "show", "--stat", "-1", str(commit or "HEAD")], cwd=repo_path, timeout_sec=20.0)
    if ok:
        diff_summary = str(out).strip()
    return True, str(sandbox_root), copied, "", diff_summary

def _repo_scan_commits(repo_path: Path, since_commit: Optional[str] = None, max_items: int = 20) -> List[Dict[str, Any]]:
    n = max(1, min(200, int(max_items or 20)))
    args = ["git", "log", f"-n", str(n), "--pretty=format:%H|%ct|%s"]
    if since_commit:
        args = ["git", "log", f"{since_commit}..HEAD", f"-n", str(n), "--pretty=format:%H|%ct|%s"]
    ok, out, _ = _git_run(args, cwd=repo_path, timeout_sec=30.0)
    if not ok:
        return []
    items: List[Dict[str, Any]] = []
    for line in str(out).splitlines():
        parts = line.split("|", 2)
        if len(parts) < 3:
            continue
        h, ts, msg = parts[0], parts[1], parts[2]
        try:
            ts_ms = int(float(ts) * 1000.0)
        except Exception:
            ts_ms = 0
        items.append({"commit": h, "ts": ts_ms, "message": msg})
    return items

def _safe_subpath(root: Path, subpath: Optional[str]) -> Optional[Path]:
    if subpath is None:
        return root
    s = str(subpath).strip()
    if not s:
        return root
    p = Path(s)
    if p.is_absolute() or ".." in p.parts:
        return None
    return root / p

def _strategy_pick_files(root: Path, strategy_name: Optional[str] = None) -> List[Path]:
    if not root.exists():
        return []
    py_files = [p for p in root.rglob("*.py") if p.is_file()]
    if not strategy_name:
        return py_files
    name = str(strategy_name).strip().lower()
    if not name:
        return py_files
    if name.endswith(".py"):
        matched = [p for p in py_files if p.name.lower() == name]
    else:
        matched = [p for p in py_files if p.stem.lower() == name]
    if len(matched) == 1:
        return matched
    return []

def _strategy_scan_forbidden(files: List[Path]) -> List[Dict[str, Any]]:
    def _scan_python(path: str, content: str) -> List[Dict[str, Any]]:
        issues: List[Dict[str, Any]] = []
        try:
            tree = ast.parse(content, filename=path)
        except SyntaxError as e:
            issues.append({
                "file": str(Path(path).name),
                "rule": "syntax_error",
                "severity": "high",
                "line": int(getattr(e, "lineno", 0) or 0),
                "col": int(getattr(e, "offset", 0) or 0),
            })
            return issues
        except Exception:
            issues.append({"file": str(Path(path).name), "rule": "parse_failed", "severity": "high"})
            return issues

        alias_to_mod: Dict[str, str] = {}

        def _root_mod(mod: str) -> str:
            s = str(mod or "").strip()
            return s.split(".", 1)[0] if s else ""

        class V(ast.NodeVisitor):
            def visit_Import(self, node: ast.Import):
                for a in node.names or []:
                    try:
                        m = str(a.name or "")
                        root = _root_mod(m)
                        asn = str(a.asname or root)
                        if asn:
                            alias_to_mod[asn] = root
                        if root in {"ccxt", "requests", "subprocess", "socket", "aiohttp", "websocket", "websockets", "paramiko", "urllib", "importlib"}:
                            issues.append({"file": str(Path(path).name), "rule": f"ban_import_{root}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                    except Exception:
                        continue
                self.generic_visit(node)

            def visit_ImportFrom(self, node: ast.ImportFrom):
                m = str(node.module or "")
                root = _root_mod(m)
                try:
                    if root:
                        for a in node.names or []:
                            asn = str(a.asname or a.name or "")
                            if asn:
                                alias_to_mod[asn] = root
                except Exception:
                    pass
                if root in {"ccxt", "requests", "subprocess", "socket", "aiohttp", "websocket", "websockets", "paramiko", "urllib", "importlib"}:
                    issues.append({"file": str(Path(path).name), "rule": f"ban_import_{root}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                self.generic_visit(node)

            def visit_Call(self, node: ast.Call):
                fn = node.func

                def _name(n: ast.AST) -> Optional[str]:
                    if isinstance(n, ast.Name):
                        return str(n.id)
                    return None

                def _attr(n: ast.AST) -> Optional[Tuple[str, str]]:
                    if isinstance(n, ast.Attribute):
                        base = _name(n.value)
                        if base:
                            return base, str(n.attr)
                    return None

                nm = _name(fn)
                if nm in {"eval", "exec"}:
                    issues.append({"file": str(Path(path).name), "rule": f"ban_{nm}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                if nm == "__import__":
                    try:
                        a0 = node.args[0] if node.args else None
                        if isinstance(a0, ast.Constant) and isinstance(a0.value, str):
                            root = _root_mod(a0.value)
                            if root in {"ccxt", "requests", "subprocess", "socket", "aiohttp", "websocket", "websockets", "paramiko", "urllib"}:
                                issues.append({"file": str(Path(path).name), "rule": f"ban_dynamic_import_{root}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                    except Exception:
                        pass

                at = _attr(fn)
                if at is not None:
                    base, attr = at
                    base_mod = alias_to_mod.get(base, base)
                    if base_mod == "os" and attr in {"system", "popen", "spawnl", "spawnlp", "spawnv", "spawnvp", "execl", "execle", "execlp", "execlpe", "execv", "execve", "execvp", "execvpe"}:
                        issues.append({"file": str(Path(path).name), "rule": f"ban_os_{attr}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                    if base_mod == "subprocess":
                        issues.append({"file": str(Path(path).name), "rule": "ban_subprocess_call", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                    if base_mod == "importlib" and attr in {"import_module"}:
                        issues.append({"file": str(Path(path).name), "rule": "ban_dynamic_import_importlib", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                self.generic_visit(node)

        V().visit(tree)
        return issues

    hits: List[Dict[str, Any]] = []
    raw = CONFIG.get("strategy_inject_ban_tokens")
    tokens = [str(x).lower() for x in raw] if isinstance(raw, list) else []
    if not tokens:
        tokens = []
    for fp in files:
        try:
            text = fp.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue
        issues = _scan_python(str(fp), text)
        for it in issues:
            hits.append(dict(it))
        low = text.lower()
        for t in tokens:
            if t and t in low:
                hits.append({"file": str(fp.name), "rule": "ban_token", "token": t, "severity": "high"})
    return hits

def _strategy_inject_from_sandbox(sandbox_path: str, strategy_name: Optional[str] = None) -> Dict[str, Any]:
    draft = _strategy_inject_draft_build({"sandbox_path": sandbox_path, "strategy_name": strategy_name})
    if not bool(draft.get("ok")):
        return draft
    try:
        _strategy_inject_draft_append(draft)
    except Exception:
        pass
    return draft


def _strategy_inject_drafts_log_path() -> Path:
    return _agent_outbox_dir() / "strategy_inject_drafts.jsonl"


def _strategy_inject_draft_lookup(draft_id: str, *, max_lines: int = 4000, max_bytes: int = 2_000_000) -> Optional[Dict[str, Any]]:
    did = str(draft_id or "").strip()
    if not did:
        return None
    p = _strategy_inject_drafts_log_path()
    if not p.exists() or (not p.is_file()):
        return None
    lines = _tail_lines(p, max_lines=int(max_lines), max_bytes=int(max_bytes))
    for ln in reversed(lines):
        s = str(ln or "").strip("\n")
        if not s.strip():
            continue
        try:
            obj = json.loads(s)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        if str(obj.get("id") or "").strip() != did:
            continue
        return obj
    return None


def _strategy_inject_draft_build(data: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(data, dict):
        data = {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    label = str(data.get("label") or "").strip() or "strategy.inject.draft"
    reason = str(data.get("reason") or "").strip() or "draft"
    doc_refs = _doc_refs_sanitize(data.get("doc_refs"))

    if not _repo_fetch_enabled():
        return {"ok": False, "error": "repo_fetch_disabled", "ts": int(_now_ms()), "trace_id": trace_id}
    st_name = str(data.get("strategy_name") or data.get("strategy") or "").strip()
    if not st_name:
        return {"ok": False, "error": "missing_strategy_name", "ts": int(_now_ms()), "trace_id": trace_id}
    allow = CONFIG.get("strategy_inject_allowlist")
    allowlist = [str(x).strip() for x in allow] if isinstance(allow, list) else []
    if allowlist and (st_name not in allowlist):
        return {"ok": False, "error": "strategy_not_allowed", "strategy": st_name, "ts": int(_now_ms()), "trace_id": trace_id}

    sandbox_path = str(data.get("sandbox_path") or "").strip()
    if not sandbox_path:
        return {"ok": False, "error": "missing_sandbox_path", "ts": int(_now_ms()), "trace_id": trace_id}
    root = Path(sandbox_path).expanduser()
    try:
        root = root.resolve()
    except Exception:
        return {"ok": False, "error": "bad_sandbox_path", "ts": int(_now_ms()), "trace_id": trace_id}
    base = _strategy_sandbox_dir().resolve()
    try:
        if not str(root).startswith(str(base)):
            return {"ok": False, "error": "sandbox_outside_base", "ts": int(_now_ms()), "trace_id": trace_id}
    except Exception:
        return {"ok": False, "error": "sandbox_outside_base", "ts": int(_now_ms()), "trace_id": trace_id}

    files = _strategy_pick_files(root, strategy_name=st_name)
    if not files:
        return {"ok": False, "error": "strategy_file_not_found", "ts": int(_now_ms()), "trace_id": trace_id}

    hits = _strategy_scan_forbidden(files)
    if hits:
        return {"ok": False, "error": "strategy_forbidden_tokens", "hits": hits, "ts": int(_now_ms()), "trace_id": trace_id}

    fp = files[0]
    try:
        b = fp.read_bytes()
    except Exception:
        return {"ok": False, "error": "read_failed", "ts": int(_now_ms()), "trace_id": trace_id}
    max_bytes = int(data.get("max_bytes") or 2_000_000)
    max_bytes = max(1, min(5_000_000, max_bytes))
    if len(b) > max_bytes:
        return {"ok": False, "error": "file_too_large", "size": int(len(b)), "max_bytes": int(max_bytes), "ts": int(_now_ms()), "trace_id": trace_id}

    sha = hashlib.sha256(b).hexdigest()
    content_b64 = base64.b64encode(b).decode("ascii")

    gate_result = {"ok": True, "hits": [], "sha256": sha, "size": int(len(b))}
    draft = {
        "ok": True,
        "ts": int(_now_ms()),
        "trace_id": trace_id,
        "evidence": {
            "sandbox": {"path": str(root)},
        },
        "candidate": {
            "strategy_name": st_name,
            "file": {
                "name": str(fp.name),
                "size": int(len(b)),
                "sha256": sha,
                "content_b64": content_b64,
            },
        },
        "gate_result": gate_result,
        "rollback_plan": {"rollback_point_id": None, "trigger": None},
        "doc_refs": doc_refs,
        "changeset": {
            "policy_ref": str(data.get("policy_ref") or "gov_default"),
            "action": str(data.get("action") or "strategy.inject.apply"),
            "label": label,
            "reason": reason,
            "strategy_name": st_name,
            "file": {"name": str(fp.name), "sha256": sha, "size": int(len(b))},
            "doc_refs": doc_refs,
        },
    }
    return draft


def _strategy_inject_draft_append(draft: Dict[str, Any]) -> Optional[str]:
    if not isinstance(draft, dict) or not bool(draft.get("ok")):
        return None
    did = uuid.uuid4().hex
    trace_id = str(draft.get("trace_id") or "").strip() or did
    item = {"id": did, "trace_id": trace_id, "ts": int(_now_ms()), "type": "strategy.inject.draft", "draft": draft}
    _agent_outbox_append_jsonl("strategy_inject_drafts.jsonl", item)
    _agent_outbox_append_jsonl("changeset_drafts.jsonl", {"id": uuid.uuid4().hex, "trace_id": trace_id, "ts": int(_now_ms()), "type": "changeset.draft", "draft": draft})
    return did


def _strategy_target_path(strategy_name: str) -> Optional[Path]:
    name = str(strategy_name or "").strip()
    if not name:
        return None
    if "/" in name or "\\" in name or ".." in name:
        return None
    if not name.lower().endswith(".py"):
        name = f"{name}.py"
    if "/" in name or "\\" in name or ".." in name:
        return None
    d = _user_data_dir() / "strategies"
    try:
        d.mkdir(parents=True, exist_ok=True)
    except Exception:
        return None
    return d / name


def _strategy_write_atomic(path: Path, content: bytes) -> bool:
    p = Path(path)
    tmp = p.with_name(p.name + ".tmp")
    try:
        with open(tmp, "wb") as f:
            f.write(content)
        os.replace(tmp, p)
        return True
    except Exception:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        return False


def _strategy_snapshot_attach_to_rollback(pt: Dict[str, Any], snapshot: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not isinstance(pt, dict) or not pt:
        return None
    pid = str(pt.get("id") or "").strip()
    if not pid:
        return None
    try:
        pts = _rollback_points_get()
        out = []
        updated = None
        for x in pts:
            if not isinstance(x, dict):
                continue
            if str(x.get("id") or "").strip() != pid:
                out.append(x)
                continue
            y = dict(x)
            y["strategy_snapshot"] = snapshot if isinstance(snapshot, dict) else {}
            out.append(y)
            updated = y
        if updated is None:
            return None
        _rollback_points_put(out)
        return updated
    except Exception:
        return None


@app.route("/strategy/inject/draft", methods=["POST"])
def strategy_inject_draft():
    if not _agent_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    draft = _strategy_inject_draft_build(data)
    if not bool(draft.get("ok")):
        return jsonify(draft), 400
    did = None
    try:
        did = _strategy_inject_draft_append(draft)
    except Exception:
        did = None
    out = dict(draft)
    if did:
        out["draft_id"] = did
    return jsonify(out), 200


@app.route("/strategy/inject/approval/request", methods=["POST"])
def strategy_inject_approval_request():
    if not (_agent_write_auth_ok() or _governance_write_auth_ok()):
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    did = str(data.get("draft_id") or "").strip()
    if not did:
        return jsonify({"ok": False, "error": "missing_draft_id", "ts": int(_now_ms()), "trace_id": trace_id}), 400
    obj = _strategy_inject_draft_lookup(did)
    if not isinstance(obj, dict) or not obj:
        return jsonify({"ok": False, "error": "draft_not_found", "draft_id": did, "ts": int(_now_ms()), "trace_id": trace_id}), 404
    draft = obj.get("draft") if isinstance(obj.get("draft"), dict) else {}
    chg = draft.get("changeset") if isinstance(draft.get("changeset"), dict) else {}
    gate = draft.get("gate_result") if isinstance(draft.get("gate_result"), dict) else {}
    doc_refs = _doc_refs_sanitize(draft.get("doc_refs"))
    evidence = draft.get("evidence") if isinstance(draft.get("evidence"), dict) else {}
    reason = str(data.get("reason") or chg.get("reason") or "strategy.inject.apply").strip() or "strategy.inject.apply"
    env = _governance_env_name()
    urgent = bool(data.get("urgent", False))
    category = (None if data.get("category") is None else str(data.get("category") or "").strip().lower()) or None
    if category in ("bugfix", "hotfix", "repair"):
        urgent = True
    try:
        mip_enabled = bool(CONFIG.get("governance_r3_mip_enabled", True))
    except Exception:
        mip_enabled = True
    if env == "explore":
        return jsonify({"ok": True, "ts": int(_now_ms()), "trace_id": trace_id, "draft_id": did, "status": "no_approval_explore"}), 200
    if mip_enabled and (not urgent):
        bucket = _mip_bucket_id()
        mip_item = {
            "ts": int(_now_ms()),
            "type": "mip.proposal",
            "bucket_id": bucket,
            "status": "pending",
            "trace_id": str(trace_id),
            "draft_id": str(did),
            "action": "strategy.inject.apply",
            "reason": reason,
            "changeset": chg,
            "gate_results": gate,
            "doc_refs": doc_refs,
            "evidence": evidence,
        }
        try:
            mip_id = _mip_append(mip_item)
        except Exception:
            mip_id = None
        if not mip_id:
            return jsonify({"ok": False, "error": "mip_create_failed", "ts": int(_now_ms()), "trace_id": trace_id, "draft_id": did}), 500
        try:
            _audit_emit_action(
                "mip.proposal",
                _audit_base_payload(scope="governance", action="mip.proposal", trace_id=trace_id, extra={"ok": True, "mip_id": mip_id, "draft_id": did, "bucket_id": bucket, "action": "strategy.inject.apply"}),
            )
        except Exception:
            pass
        return jsonify({"ok": True, "ts": int(_now_ms()), "trace_id": trace_id, "draft_id": did, "status": "mip_pending", "mip_id": mip_id, "bucket_id": bucket}), 200
    ev2 = dict(evidence) if isinstance(evidence, dict) else {}
    if urgent:
        try:
            fast_days = int(CONFIG.get("governance_r3_bugfix_fastlane_days", 3) or 3)
        except Exception:
            fast_days = 3
        fast_days = max(1, min(14, int(fast_days)))
        ev2["fast_lane"] = True
        ev2["fast_lane_deadline_ts"] = int(_now_ms() + int(fast_days) * 86400 * 1000)
        if category:
            ev2["category"] = str(category)
    ent = {
        "trace_id": trace_id,
        "decision": "pending",
        "reason": (f"fast_lane_bugfix:{reason}" if urgent else reason),
        "action": "strategy.inject.apply",
        "draft_id": did,
        "changeset": chg,
        "gate_results": gate,
        "doc_refs": doc_refs,
        "evidence": ev2,
        "ts": int(_now_ms()),
        "scope": "governance",
    }
    rid = _approval_append(ent)
    if not rid:
        return jsonify({"ok": False, "error": "approval_create_failed", "ts": int(_now_ms()), "trace_id": trace_id}), 500
    try:
        _audit_emit_action(
            "approval.requested",
            _audit_base_payload(scope="governance", action="approval.requested", trace_id=trace_id, extra={"ok": True, "approval_id": rid, "draft_id": did, "action": "strategy.inject.apply"}),
        )
    except Exception:
        pass
    return jsonify({"ok": True, "ts": int(_now_ms()), "trace_id": trace_id, "approval_id": rid, "draft_id": did}), 200


@app.route("/strategy/inject/apply", methods=["POST"])
def strategy_inject_apply():
    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    confirm_live = bool(data.get("confirm_live", False))
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="strategy.inject.apply")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    did = str(data.get("draft_id") or "").strip()
    if not did:
        return jsonify({"ok": False, "error": "missing_draft_id", "ts": int(_now_ms()), "trace_id": trace_id}), 400
    obj = _strategy_inject_draft_lookup(did, max_lines=8000, max_bytes=6_000_000)
    if not isinstance(obj, dict) or not obj:
        return jsonify({"ok": False, "error": "draft_not_found", "draft_id": did, "ts": int(_now_ms()), "trace_id": trace_id}), 404
    draft = obj.get("draft") if isinstance(obj.get("draft"), dict) else {}
    cand = draft.get("candidate") if isinstance(draft.get("candidate"), dict) else {}
    chg = draft.get("changeset") if isinstance(draft.get("changeset"), dict) else {}
    st_name = str(cand.get("strategy_name") or chg.get("strategy_name") or "").strip()
    if not st_name:
        return jsonify({"ok": False, "error": "missing_strategy_name", "ts": int(_now_ms()), "trace_id": trace_id}), 400
    fobj = cand.get("file") if isinstance(cand.get("file"), dict) else {}
    content_b64 = str(fobj.get("content_b64") or "").strip()
    if not content_b64:
        return jsonify({"ok": False, "error": "missing_content", "ts": int(_now_ms()), "trace_id": trace_id}), 400
    try:
        content = base64.b64decode(content_b64.encode("ascii"), validate=True)
    except Exception:
        return jsonify({"ok": False, "error": "bad_content", "ts": int(_now_ms()), "trace_id": trace_id}), 400

    sha = hashlib.sha256(content).hexdigest()
    expected_sha = str(fobj.get("sha256") or "").strip()
    if expected_sha and expected_sha != sha:
        return jsonify({"ok": False, "error": "sha_mismatch", "expected": expected_sha, "got": sha, "ts": int(_now_ms()), "trace_id": trace_id}), 400
    name = str(fobj.get("name") or "").strip()
    if name and ("/" in name or "\\" in name or ".." in name):
        return jsonify({"ok": False, "error": "bad_filename", "ts": int(_now_ms()), "trace_id": trace_id}), 400

    allow = CONFIG.get("strategy_inject_allowlist")
    allowlist = [str(x).strip() for x in allow] if isinstance(allow, list) else []
    if allowlist and (st_name not in allowlist):
        return jsonify({"ok": False, "error": "strategy_not_allowed", "strategy": st_name, "ts": int(_now_ms()), "trace_id": trace_id}), 403

    try:
        txt = content.decode("utf-8")
    except Exception:
        txt = content.decode("utf-8", errors="ignore")
    tmp_root = _strategy_sandbox_dir() / "_inject_apply" / uuid.uuid4().hex
    try:
        tmp_root.mkdir(parents=True, exist_ok=True)
    except Exception:
        return jsonify({"ok": False, "error": "tempdir_failed", "ts": int(_now_ms()), "trace_id": trace_id}), 500
    tmp_fp = tmp_root / (name or (f"{st_name}.py" if not st_name.lower().endswith(".py") else st_name))
    try:
        tmp_fp.write_bytes(content)
    except Exception:
        try:
            shutil.rmtree(tmp_root)
        except Exception:
            pass
        return jsonify({"ok": False, "error": "temp_write_failed", "ts": int(_now_ms()), "trace_id": trace_id}), 500
    hits = _strategy_scan_forbidden([tmp_fp])
    try:
        shutil.rmtree(tmp_root)
    except Exception:
        pass
    if hits:
        return jsonify({"ok": False, "error": "strategy_forbidden_tokens", "hits": hits, "ts": int(_now_ms()), "trace_id": trace_id}), 400

    if not _is_local_request():
        if not bool(confirm_live):
            return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms()), "trace_id": trace_id}), 400

    dst = _strategy_target_path(st_name)
    if dst is None:
        return jsonify({"ok": False, "error": "bad_target_path", "ts": int(_now_ms()), "trace_id": trace_id}), 400

    before = None
    existed = False
    try:
        if dst.exists() and dst.is_file():
            existed = True
            b0 = dst.read_bytes()
            before = {"name": dst.name, "size": int(len(b0)), "sha256": hashlib.sha256(b0).hexdigest(), "content_b64": base64.b64encode(b0).decode("ascii") if len(b0) <= 2_000_000 else None}
    except Exception:
        before = None

    rb_pt = _rollback_snapshot_append(label="strategy.inject.apply", reason="l3_preflight")
    if rb_pt is None:
        return jsonify({"ok": False, "error": "rollback_snapshot_failed", "ts": int(_now_ms()), "trace_id": trace_id}), 500
    rb_pt2 = _strategy_snapshot_attach_to_rollback(rb_pt, {"draft_id": did, "strategy_name": st_name, "target": str(dst), "before": before, "after": {"sha256": sha, "size": int(len(content))}})
    if rb_pt2 is not None:
        rb_pt = rb_pt2

    ok = _strategy_write_atomic(dst, content)
    audit_payload = {
        "trace_id": trace_id,
        "approval_id": approval_id,
        "draft_id": did,
        "strategy_name": st_name,
        "target": str(dst),
        "rollback_point_id": rb_pt.get("id"),
        "before": before,
        "after": {"name": dst.name, "sha256": sha, "size": int(len(content))},
        "ok": bool(ok),
    }
    try:
        _agent_outbox_append_jsonl("audit_actions.jsonl", {"name": "strategy.inject.apply", "ts": int(_now_ms()), "payload": audit_payload})
    except Exception:
        pass
    try:
        _audit_emit_action("strategy.inject.apply", _audit_base_payload(scope="governance", action="strategy.inject.apply", trace_id=trace_id, extra=audit_payload))
    except Exception:
        pass

    if not ok:
        rb_res = None
        try:
            if existed and before and before.get("content_b64"):
                b_prev = base64.b64decode(str(before.get("content_b64") or "").encode("ascii"), validate=True)
                rb_ok = _strategy_write_atomic(dst, b_prev)
                rb_res = {"ok": bool(rb_ok), "restore": "write"}
            elif (not existed) and dst.exists():
                dst.unlink()
                rb_res = {"ok": True, "restore": "delete"}
            else:
                rb_res = {"ok": False, "error": "no_snapshot"}
        except Exception as e:
            rb_res = {"ok": False, "error": str(e)}
        try:
            _agent_outbox_append_jsonl("audit_actions.jsonl", {"name": "strategy.inject.rollback", "ts": int(_now_ms()), "payload": {"trace_id": trace_id, "draft_id": did, "rollback": rb_res, "rollback_point_id": rb_pt.get("id")}})
        except Exception:
            pass
        return jsonify({"ok": False, "error": "apply_failed", "ts": int(_now_ms()), "trace_id": trace_id, "approval_id": approval_id, "rollback_point": rb_pt, "rollback": rb_res}), 500

    return jsonify({"ok": True, "ts": int(_now_ms()), "trace_id": trace_id, "approval_id": approval_id, "draft_id": did, "rollback_point": rb_pt, "applied": {"strategy_name": st_name, "target": str(dst), "sha256": sha, "size": int(len(content))}}), 200

def _strategy_sandbox_stage(repo_path: Path, subpath: Optional[str], repo_id: str, commit: str, strategy_name: Optional[str] = None) -> Tuple[bool, Optional[str], List[str], str, Optional[str]]:
    root = _safe_subpath(repo_path, subpath)
    if root is None:
        return False, None, [], "bad_path", None
    files = _strategy_pick_files(root, strategy_name=strategy_name)
    if not files:
        return False, None, [], "no_strategy_files", None
    sandbox_root = _strategy_sandbox_dir() / str(repo_id) / str(commit or "HEAD")
    try:
        if sandbox_root.exists():
            shutil.rmtree(sandbox_root)
    except Exception:
        pass
    try:
        sandbox_root.mkdir(parents=True, exist_ok=True)
    except Exception:
        return False, None, [], "sandbox_create_failed", None
    copied: List[str] = []
    for fp in files:
        try:
            dst = sandbox_root / fp.name
            shutil.copy2(fp, dst)
            copied.append(str(dst.name))
        except Exception:
            continue
    if not copied:
        return False, None, [], "sandbox_copy_failed", None
    diff_summary = None
    ok, out, _ = _git_run(["git", "show", "--stat", "-1", str(commit or "HEAD")], cwd=repo_path, timeout_sec=20.0)
    if ok:
        diff_summary = str(out).strip()
    return True, str(sandbox_root), copied, "", diff_summary

def _backtest_last_result_zip_name() -> Optional[str]:
    try:
        p = _backtests_dir() / ".last_result.json"
        if not p.exists():
            return None
        obj = json.loads(p.read_text() or "{}")
        if not isinstance(obj, dict):
            return None
        name = obj.get("latest_backtest")
        if name is None:
            return None
        s = str(name).strip()
        if not s:
            return None
        if not s.lower().endswith(".zip"):
            return None
        return s
    except Exception:
        return None

def _backtest_pick_latest_zip_path() -> Optional[Path]:
    try:
        name = _backtest_last_result_zip_name()
        if name:
            p = _backtests_dir() / name
            if p.exists():
                return p
        zips = list(_backtests_dir().glob("*.zip"))
        if not zips:
            return None
        zips.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        return zips[0]
    except Exception:
        return None


def _loss_quantile_mag(losses: List[float], q: float) -> float:
    xs = [float(x) for x in (losses or []) if x is not None and math.isfinite(float(x)) and float(x) >= 0.0]
    if not xs:
        return 0.0
    ys = sorted(xs)
    qq = float(_clip(float(q), 0.0, 1.0))
    pos = int(round(qq * float(len(ys) - 1)))
    pos = max(0, min(len(ys) - 1, int(pos)))
    return float(ys[pos])


def _loss_es_mag(losses: List[float], q: float) -> float:
    xs = [float(x) for x in (losses or []) if x is not None and math.isfinite(float(x)) and float(x) >= 0.0]
    if not xs:
        return 0.0
    thr = _loss_quantile_mag(xs, q)
    tail = [x for x in xs if float(x) >= float(thr)]
    if not tail:
        return float(thr)
    return float(sum(tail) / float(len(tail)))


def _gtw_risk_budget_from_latest_backtest() -> Optional[Dict[str, Any]]:
    p = _backtest_pick_latest_zip_path()
    if p is None or (not isinstance(p, Path)) or (not p.exists()) or (not p.is_file()):
        return None
    cfg = _backtest_zip_load_config_json(p) or {}
    main = _backtest_zip_load_main_json(p) or {}
    sb = _backtest_zip_strategy_block(main, None)
    base_u = None
    try:
        base_u = float((sb or {}).get("starting_balance"))
    except Exception:
        base_u = None
    if base_u is None or (not math.isfinite(float(base_u))) or float(base_u) <= 0.0:
        return None
    trades = _backtest_zip_strategy_trades(p, strategy=None) or []
    if not trades:
        return None
    try:
        a = _bt_assumptions_merge(_bt_assumptions_default(cfg), None)
    except Exception:
        a = _bt_assumptions_default(cfg) or {}
    rng = random.Random(1)
    rows: List[Dict[str, Any]] = []
    for t in trades[-6000:]:
        rr = None
        try:
            rr = _bt_trade_exec_row(t, cfg=cfg, assumptions=a, rng=rng)
        except Exception:
            rr = None
        if isinstance(rr, dict):
            rows.append(rr)
    if not rows:
        return None

    try:
        stress_cost_pct = float(CONFIG.get("eval_stress_cost_pct", 0.003) or 0.003)
    except Exception:
        stress_cost_pct = 0.003
    stress_cost_pct = float(_clip(stress_cost_pct, 0.0, 0.05))

    daily: Dict[str, float] = {}
    daily_stress: Dict[str, float] = {}
    for r in rows:
        try:
            pnl = float(r.get("pnl_net_u") or 0.0)
        except Exception:
            pnl = 0.0
        if pnl == 0.0:
            continue
        try:
            ts = int(r.get("ts") or 0)
        except Exception:
            ts = 0
        if ts <= 0:
            continue
        try:
            dt = datetime.utcfromtimestamp(max(0, ts) / 1000.0)
            day = dt.strftime("%Y-%m-%d")
        except Exception:
            continue
        daily[day] = float(daily.get(day, 0.0)) + float(pnl)
        try:
            stake_u = float(r.get("stake_u") or 0.0)
        except Exception:
            stake_u = 0.0
        extra_cost = abs(float(stake_u)) * float(stress_cost_pct) * 2.0
        daily_stress[day] = float(daily_stress.get(day, 0.0)) + float(pnl) - float(extra_cost)

    if not daily:
        return None

    losses = [float(-v) for v in daily.values() if float(v) < 0.0]
    var_99_u = _loss_quantile_mag(losses, 0.99)
    es_97_5_u = _loss_es_mag(losses, 0.975)

    losses_stress = [float(-v) for v in daily_stress.values() if float(v) < 0.0]
    var_99_stress_u = _loss_quantile_mag(losses_stress, 0.99)
    es_97_5_stress_u = _loss_es_mag(losses_stress, 0.975)
    stress_loss_u = float(max(var_99_stress_u, es_97_5_stress_u))

    return {
        "zip": str(p.name),
        "base_equity_u": float(base_u),
        "n_trades": int(len(rows)),
        "n_days": int(len(daily)),
        "var_99": float(var_99_u) / float(base_u),
        "es_97_5": float(es_97_5_u) / float(base_u),
        "stress_loss": float(stress_loss_u) / float(base_u),
        "stress_cost_pct": float(stress_cost_pct),
    }

def _backtest_zip_metrics(zip_path: Path) -> Optional[Dict[str, Any]]:
    try:
        import zipfile

        p = Path(zip_path)
        if not p.exists() or (not p.is_file()):
            return None
        with zipfile.ZipFile(p, "r") as zf:
            names = zf.namelist()
            main_json = None
            for n in names:
                if not str(n).endswith(".json"):
                    continue
                if "_config" in str(n):
                    continue
                if "_Strategy" in str(n):
                    continue
                if str(n).startswith("backtest-result-"):
                    main_json = str(n)
                    break
            if main_json is None:
                return None
            data = json.loads(zf.read(main_json))
        if not isinstance(data, dict):
            return None

        out: Dict[str, Any] = {
            "zip": str(p.name),
            "strategies": [],
        }
        sc = data.get("strategy_comparison")
        sm = data.get("strategy")
        if not isinstance(sm, dict):
            sm = {}

        if isinstance(sc, list):
            for row in sc:
                if not isinstance(row, dict):
                    continue
                name = row.get("key")
                if name is None:
                    continue
                key = str(name)
                base: Dict[str, Any] = {"key": key}
                for k in (
                    "trades",
                    "wins",
                    "draws",
                    "losses",
                    "winrate",
                    "profit_total_abs",
                    "profit_total_pct",
                    "profit_mean_pct",
                    "profit_factor",
                    "sharpe",
                    "sortino",
                    "calmar",
                    "sqn",
                    "cagr",
                    "expectancy",
                    "expectancy_ratio",
                    "max_drawdown_account",
                    "max_drawdown_abs",
                ):
                    if k in row:
                        base[k] = row.get(k)

                s0 = sm.get(key)
                if isinstance(s0, dict):
                    for k in (
                        "timeframe",
                        "timeframe_detail",
                        "timerange",
                        "backtest_start_ts",
                        "backtest_end_ts",
                        "backtest_days",
                        "final_balance",
                        "starting_balance",
                        "stake_currency",
                        "max_open_trades",
                        "exit_reason_summary",
                        "rejected_signals",
                        "timedout_entry_orders",
                        "timedout_exit_orders",
                        "canceled_entry_orders",
                        "replaced_entry_orders",
                    ):
                        if k in s0:
                            base[k] = s0.get(k)
                out["strategies"].append(base)

        return out
    except Exception:
        return None


def _backtest_zip_load_main_json(zip_path: Path) -> Optional[Dict[str, Any]]:
    try:
        import zipfile

        p = Path(zip_path)
        if not p.exists() or (not p.is_file()):
            return None
        with zipfile.ZipFile(p, "r") as zf:
            names = zf.namelist()
            main_json = None
            for n in names:
                if not str(n).endswith(".json"):
                    continue
                if "_config" in str(n):
                    continue
                if "_Strategy" in str(n):
                    continue
                if str(n).startswith("backtest-result-"):
                    main_json = str(n)
                    break
            if main_json is None:
                return None
            data = json.loads(zf.read(main_json))
        return data if isinstance(data, dict) else None
    except Exception:
        return None


def _backtest_zip_load_config_json(zip_path: Path) -> Optional[Dict[str, Any]]:
    try:
        import zipfile

        p = Path(zip_path)
        if not p.exists() or (not p.is_file()):
            return None
        with zipfile.ZipFile(p, "r") as zf:
            names = [n for n in zf.namelist() if str(n).endswith("_config.json")]
            if not names:
                return None
            data = json.loads(zf.read(names[0]))
        return data if isinstance(data, dict) else None
    except Exception:
        return None


def _backtest_zip_strategy_trades(zip_path: Path, strategy: Optional[str] = None) -> Optional[List[Dict[str, Any]]]:
    data = _backtest_zip_load_main_json(zip_path)
    if not isinstance(data, dict):
        return None
    sm = data.get("strategy")
    if not isinstance(sm, dict) or not sm:
        return None
    st = None if strategy is None else str(strategy)
    block = None
    if st and st in sm and isinstance(sm.get(st), dict):
        block = sm.get(st)
    if block is None:
        for v in sm.values():
            if isinstance(v, dict):
                block = v
                break
    if not isinstance(block, dict):
        return None
    trades = block.get("trades")
    if not isinstance(trades, list):
        return None
    out: List[Dict[str, Any]] = []
    for t in trades:
        if isinstance(t, dict):
            out.append(t)
    return out


def _strategy_registry_path() -> Path:
    return _user_data_dir() / "strategy_registry.json"


def _strategy_registry_db_path() -> Path:
    return _user_data_dir() / "strategy_registry.db"


def _strategy_registry_backend() -> str:
    try:
        s = str((CONFIG or {}).get("strategy_registry_backend") or "sqlite").strip().lower()
    except Exception:
        s = "sqlite"
    return s if s in ("sqlite", "json") else "sqlite"


def _strategy_registry_sqlite_enabled() -> bool:
    return _strategy_registry_backend() == "sqlite"


def _strategy_registry_db_conn() -> sqlite3.Connection:
    p = _strategy_registry_db_path()
    p.parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(str(p), timeout=5.0, isolation_level=None)
    conn.row_factory = sqlite3.Row
    return conn


def _strategy_registry_db_init() -> None:
    with contextlib.closing(_strategy_registry_db_conn()) as conn:
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA synchronous=NORMAL")
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS registry_entries (
                k TEXT PRIMARY KEY,
                strategy_id TEXT,
                source_zip TEXT,
                family TEXT,
                stage TEXT,
                tier TEXT,
                updated_at TEXT,
                bundle_id TEXT,
                cost_profile_id TEXT,
                tags_text TEXT,
                tier_reason TEXT,
                entry_json TEXT
            )
            """
        )
        conn.execute("CREATE INDEX IF NOT EXISTS idx_registry_family ON registry_entries(family)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_registry_tier ON registry_entries(tier)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_registry_updated ON registry_entries(updated_at)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_registry_bundle ON registry_entries(bundle_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_registry_cost ON registry_entries(cost_profile_id)")

        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS registry_events (
                id TEXT PRIMARY KEY,
                ts INTEGER,
                trace_id TEXT,
                actor TEXT,
                kind TEXT,
                strategy_id TEXT,
                source_zip TEXT,
                event_json TEXT
            )
            """
        )
        conn.execute("CREATE INDEX IF NOT EXISTS idx_events_key_ts ON registry_events(strategy_id, source_zip, ts)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_events_ts ON registry_events(ts)")

        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS eval_policies (
                ref TEXT,
                policy_hash TEXT,
                policy_json TEXT,
                created_at TEXT,
                PRIMARY KEY (ref, policy_hash)
            )
            """
        )
        conn.execute("CREATE INDEX IF NOT EXISTS idx_eval_policies_ref ON eval_policies(ref)")

        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS approvals (
                id TEXT PRIMARY KEY,
                ts INTEGER,
                actor TEXT,
                role TEXT,
                bundle_id TEXT,
                strategy_id TEXT,
                source_zip TEXT,
                eval_policy_ref TEXT,
                policy_hash TEXT,
                gate_result_hash TEXT,
                note TEXT,
                record_json TEXT
            )
            """
        )
        conn.execute("CREATE INDEX IF NOT EXISTS idx_approvals_bundle ON approvals(bundle_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_approvals_key_ts ON approvals(strategy_id, source_zip, ts)")

    _strategy_registry_db_migrate_from_json()


def _strategy_registry_db_migrate_from_json() -> None:
    try:
        p = _strategy_registry_path()
        if not p.exists() or not p.is_file():
            return
        reg = _strategy_registry_load_json_only()
        entries = reg.get("entries") if isinstance(reg.get("entries"), dict) else {}
        if not entries:
            return
        with contextlib.closing(_strategy_registry_db_conn()) as conn:
            try:
                conn.execute("BEGIN")
            except Exception:
                pass
            for k, e in entries.items():
                if not isinstance(e, dict):
                    continue
                try:
                    _strategy_registry_db_upsert_entry(conn, e)
                except Exception:
                    continue
            try:
                conn.execute("COMMIT")
            except Exception:
                try:
                    conn.commit()
                except Exception:
                    pass
    except Exception:
        return

    try:
        evp = _strategy_registry_events_path()
        if not evp.exists() or not evp.is_file():
            return
        lines = _tail_lines(evp, max_lines=20000, max_bytes=10_000_000)
        if not lines:
            return
        with contextlib.closing(_strategy_registry_db_conn()) as conn:
            for ln in lines:
                try:
                    obj = json.loads(ln)
                except Exception:
                    continue
                if not isinstance(obj, dict):
                    continue
                evt_id = str(obj.get("id") or "").strip()
                if not evt_id:
                    continue
                try:
                    conn.execute(
                        "INSERT OR IGNORE INTO registry_events (id, ts, trace_id, actor, kind, strategy_id, source_zip, event_json) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                        (
                            evt_id,
                            int(obj.get("ts") or 0),
                            (None if obj.get("trace_id") is None else str(obj.get("trace_id"))),
                            (None if obj.get("actor") is None else str(obj.get("actor"))),
                            (None if obj.get("kind") is None else str(obj.get("kind"))),
                            (None if obj.get("strategy_id") is None else str(obj.get("strategy_id"))),
                            (None if obj.get("source_zip") is None else str(obj.get("source_zip"))),
                            json.dumps(obj, ensure_ascii=False, separators=(",", ":")),
                        ),
                    )
                except Exception:
                    continue
    except Exception:
        return


def _strategy_registry_load_json_only() -> Dict[str, Any]:
    p = _strategy_registry_path()
    try:
        if p.exists() and p.is_file():
            with open(p, "r", encoding="utf-8") as f:
                obj = json.load(f)
            reg = obj if isinstance(obj, dict) else {}
            return _strategy_registry_normalize(reg)
    except Exception:
        return {}
    return _strategy_registry_normalize({})


def _strategy_registry_db_upsert_entry(conn: sqlite3.Connection, entry: Dict[str, Any]) -> None:
    e = dict(entry)
    sid = str(e.get("strategy_id") or "").strip()
    z = str(e.get("source_zip") or "").strip()
    if not sid or not z:
        return
    k = _strategy_registry_key(sid, z)
    fam = _strategy_family_normalize(e.get("family")) or "trend"
    stage = _strategy_stage_normalize(e.get("stage")) or "research"
    tier = str(e.get("tier") or "").strip()
    updated_at = str(e.get("updated_at") or "").strip()
    bundle_id = str(e.get("bundle_id") or "").strip() or None
    cost_profile_id = _strategy_cost_profile_id_from_entry(e)
    tags = e.get("tags")
    tags_text = ""
    if isinstance(tags, list):
        tags_text = ",".join([str(x).strip() for x in tags if str(x or "").strip()])
    tier_reason = str(e.get("tier_reason") or "").strip() or None
    entry_json = json.dumps(e, ensure_ascii=False, separators=(",", ":"))
    conn.execute(
        """
        INSERT INTO registry_entries (k, strategy_id, source_zip, family, stage, tier, updated_at, bundle_id, cost_profile_id, tags_text, tier_reason, entry_json)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(k) DO UPDATE SET
            strategy_id=excluded.strategy_id,
            source_zip=excluded.source_zip,
            family=excluded.family,
            stage=excluded.stage,
            tier=excluded.tier,
            updated_at=excluded.updated_at,
            bundle_id=excluded.bundle_id,
            cost_profile_id=excluded.cost_profile_id,
            tags_text=excluded.tags_text,
            tier_reason=excluded.tier_reason,
            entry_json=excluded.entry_json
        """,
        (k, sid, z, fam, stage, tier, updated_at, bundle_id, cost_profile_id, tags_text, tier_reason, entry_json),
    )


def _strategy_registry_db_upsert_eval_policy(
    conn: sqlite3.Connection,
    *,
    ref: str,
    policy_hash: str,
    policy: Dict[str, Any],
    created_at: str,
) -> None:
    r = str(ref or "").strip()
    h = str(policy_hash or "").strip().lower()
    if not r or not h:
        return
    if len(h) != 64:
        return
    try:
        int(h, 16)
    except Exception:
        return
    conn.execute(
        "INSERT OR IGNORE INTO eval_policies (ref, policy_hash, policy_json, created_at) VALUES (?, ?, ?, ?)",
        (
            r,
            h,
            json.dumps(policy or {}, ensure_ascii=False, separators=(",", ":")),
            str(created_at or "").strip() or datetime.now(timezone.utc).isoformat(),
        ),
    )


def _strategy_cost_profile_id_from_entry(entry: Dict[str, Any]) -> Optional[str]:
    bs = entry.get("backtest_spec") if isinstance(entry.get("backtest_spec"), dict) else None
    if not isinstance(bs, dict):
        return None
    got = bs.get("cost_profile_id")
    if isinstance(got, str):
        s = got.strip().lower()
        if len(s) == 64:
            try:
                int(s, 16)
                return s
            except Exception:
                pass
    fees_bps = bs.get("fees_bps")
    slippage_bps = bs.get("slippage_bps")
    mt = bs.get("market_type")
    if fees_bps is None or slippage_bps is None:
        return None
    try:
        f = float(fees_bps)
        s = float(slippage_bps)
        if not math.isfinite(f) or not math.isfinite(s):
            return None
    except Exception:
        return None
    lm = bs.get("leverage_mode")
    sc = bs.get("stake_currency")
    seed = {
        "fees_bps": float(fees_bps),
        "slippage_bps": float(slippage_bps),
        "market_type": (None if mt is None else str(mt).strip()),
        "leverage_mode": (None if lm is None else str(lm).strip()),
        "stake_currency": (None if sc is None else str(sc).strip()),
    }
    b = json.dumps(seed, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(b).hexdigest()


def _strategy_registry_events_path() -> Path:
    return _user_data_dir() / "strategy_registry_events.jsonl"


def _strategy_registry_events_tail(
    *,
    strategy_id: str,
    source_zip: str,
    limit: int = 20,
    kinds: Optional[set] = None,
) -> List[Dict[str, Any]]:
    sid = str(strategy_id or "").strip()
    z = str(source_zip or "").strip()
    if (not sid) or (not z):
        return []
    try:
        limit_n = int(limit)
    except Exception:
        limit_n = 20
    limit_n = max(1, min(200, int(limit_n)))
    p = _strategy_registry_events_path()
    if (not p.exists()) or (not p.is_file()):
        return []
    lines = _tail_lines(p, max_lines=max(2000, limit_n * 50), max_bytes=2000000)
    out: List[Dict[str, Any]] = []
    for ln in reversed(lines):
        try:
            obj = json.loads(ln)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        if str(obj.get("strategy_id") or "").strip() != sid:
            continue
        if str(obj.get("source_zip") or "").strip() != z:
            continue
        k = str(obj.get("kind") or "").strip().lower()
        if kinds is not None and k not in kinds:
            continue
        out.append(
            {
                "id": obj.get("id"),
                "ts": obj.get("ts"),
                "kind": obj.get("kind"),
                "trace_id": obj.get("trace_id"),
            }
        )
        if len(out) >= limit_n:
            break
    out.reverse()
    return out


def _strategy_bundles_dir() -> Path:
    return _user_data_dir() / "strategy_bundles"


def _strategy_registry_load() -> Dict[str, Any]:
    if _strategy_registry_sqlite_enabled():
        try:
            _strategy_registry_db_init()
            with contextlib.closing(_strategy_registry_db_conn()) as conn:
                reg: Dict[str, Any] = {"schema_version": 3, "entries": {}}
                rows = conn.execute("SELECT entry_json FROM registry_entries").fetchall()
                out_entries: Dict[str, Any] = {}
                for r in rows:
                    try:
                        e = json.loads(r[0])
                    except Exception:
                        continue
                    if isinstance(e, dict):
                        sid = str(e.get("strategy_id") or "").strip()
                        z = str(e.get("source_zip") or "").strip()
                        if sid and z:
                            out_entries[_strategy_registry_key(sid, z)] = e
                reg["entries"] = out_entries
                return _strategy_registry_normalize(reg)
        except Exception:
            return _strategy_registry_load_json_only()
    return _strategy_registry_load_json_only()


def _strategy_registry_save(reg: Dict[str, Any]) -> bool:
    if _strategy_registry_sqlite_enabled():
        try:
            _strategy_registry_db_init()
            out = _strategy_registry_normalize(reg)
            entries = out.get("entries") if isinstance(out.get("entries"), dict) else {}
            with contextlib.closing(_strategy_registry_db_conn()) as conn:
                for e in entries.values():
                    if isinstance(e, dict):
                        _strategy_registry_db_upsert_entry(conn, e)
            return True
        except Exception:
            pass
    p = _strategy_registry_path()
    try:
        out = _strategy_registry_normalize(reg)
        p.parent.mkdir(parents=True, exist_ok=True)
        with open(p, "w", encoding="utf-8") as f:
            json.dump(out, f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False


def _strategy_registry_key(strategy_id: str, source_zip: str) -> str:
    sid = str(strategy_id or "").strip()
    z = str(source_zip or "").strip()
    return f"{sid}|{z}"


def _strategy_registry_normalize(reg: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(reg, dict):
        return {"schema_version": 2, "entries": {}}
    if isinstance(reg.get("entries"), dict):
        raw_entries = reg.get("entries")
        out_entries: Dict[str, Any] = {}
        for k0, v0 in raw_entries.items():
            if not isinstance(v0, dict):
                continue
            sid = str(v0.get("strategy_id") or "").strip()
            z = str(v0.get("source_zip") or "").strip()
            if (not sid) or (not z):
                try:
                    parts = str(k0 or "").split("|", 1)
                    if not sid and len(parts) >= 1:
                        sid = str(parts[0] or "").strip()
                    if not z and len(parts) >= 2:
                        z = str(parts[1] or "").strip()
                except Exception:
                    pass
            if (not sid) or (not z):
                continue
            e = dict(v0)
            e["strategy_id"] = sid
            e["source_zip"] = z

            fam_n = _strategy_family_normalize(e.get("family")) if e.get("family") is not None else None
            if fam_n is not None:
                e["family"] = fam_n
            stage_n = _strategy_stage_normalize(e.get("stage")) if e.get("stage") is not None else None
            if stage_n is not None:
                e["stage"] = stage_n
            rb_n = _strategy_robustness_normalize(e.get("robustness")) if e.get("robustness") is not None else None
            if rb_n is not None:
                e["robustness"] = rb_n

            k2 = _strategy_registry_key(sid, z)
            ex = out_entries.get(k2)
            if isinstance(ex, dict):
                ts1 = str(ex.get("updated_at") or "")
                ts2 = str(e.get("updated_at") or "")
                if ts2 and (not ts1 or ts2 >= ts1):
                    out_entries[k2] = e
            else:
                out_entries[k2] = e
        out = dict(reg)
        out.setdefault("schema_version", 2)
        out["entries"] = out_entries
        return out
    out_entries: Dict[str, Any] = {}
    legacy = reg.get("strategies") if isinstance(reg.get("strategies"), dict) else {}
    if isinstance(legacy, dict):
        for sid, it in legacy.items():
            if not isinstance(it, dict):
                continue
            s = str(sid or "").strip()
            if not s:
                continue
            e = dict(it)
            if "strategy_id" not in e:
                e["strategy_id"] = s
            if "source_zip" not in e:
                e["source_zip"] = "*"
            key = _strategy_registry_key(e.get("strategy_id"), e.get("source_zip"))
            out_entries[key] = e
    return {"schema_version": 2, "entries": out_entries}


def _strategy_registry_pick(entries: Dict[str, Any], strategy_id: str, source_zip: str) -> Dict[str, Any]:
    sid = str(strategy_id or "").strip()
    z = str(source_zip or "").strip()
    if not sid:
        return {}
    k_exact = _strategy_registry_key(sid, z)
    it = entries.get(k_exact)
    if isinstance(it, dict):
        return it
    k_any = _strategy_registry_key(sid, "*")
    it2 = entries.get(k_any)
    if isinstance(it2, dict):
        return it2
    best: Optional[Dict[str, Any]] = None
    best_ts = ""
    for k, v in entries.items():
        if not isinstance(v, dict):
            continue
        if str(v.get("strategy_id") or "").strip() != sid:
            continue
        ts = str(v.get("updated_at") or "")
        if (not best) or ts > best_ts:
            best = v
            best_ts = ts
    return best or {}


def _strategy_family_normalize(v: Any) -> Optional[str]:
    s = str(v or "").strip().lower()
    if s in ("trend", "tf"):
        return "trend"
    if s in ("mean_reversion", "meanreversion", "mr"):
        return "mean_reversion"
    if s in ("carry", "cr"):
        return "carry"
    if s in ("breakout", "bo"):
        return "breakout"
    return None


def _strategy_stage_normalize(v: Any) -> Optional[str]:
    s = str(v or "").strip().lower()
    if s in ("research", "model", "deployment"):
        return s
    return None


def _strategy_robustness_normalize(v: Any) -> Optional[str]:
    s = str(v or "").strip().lower()
    if s in ("", "unknown", "na", "n/a", "none"):
        return "unknown"
    if s in ("pass", "ok", "good", "success"):
        return "pass"
    if s in ("warn", "warning"):
        return "warn"
    if s in ("fail", "failed", "bad"):
        return "fail"
    return None


def _strategy_lifecycle_normalize(v: Any) -> Optional[str]:
    s = str(v or "").strip().lower()
    if s in (
        "research_draft",
        "research_validated",
        "model_candidate",
        "approved",
        "deployed_canary",
        "deployed_full",
        "deprecated",
        "rolled_back",
    ):
        return s
    return None


def _strategy_lifecycle_expected_stage(state: Any) -> Optional[str]:
    st = _strategy_lifecycle_normalize(state)
    if st in ("research_draft", "research_validated"):
        return "research"
    if st in ("model_candidate", "approved"):
        return "model"
    if st in ("deployed_canary", "deployed_full", "deprecated", "rolled_back"):
        return "deployment"
    return None


def _strategy_lifecycle_transition_ok(from_state: Any, to_state: Any) -> bool:
    fr = _strategy_lifecycle_normalize(from_state) or "research_draft"
    to = _strategy_lifecycle_normalize(to_state)
    if to is None:
        return False
    if fr == to:
        return True
    if to == "deprecated":
        return True
    if to == "rolled_back":
        return fr in ("deployed_canary", "deployed_full")
    allowed: Dict[str, Tuple[str, ...]] = {
        "research_draft": ("research_validated",),
        "research_validated": ("model_candidate",),
        "model_candidate": ("approved",),
        "approved": ("deployed_canary",),
        "deployed_canary": ("deployed_full",),
        "deployed_full": (),
    }
    return to in allowed.get(fr, ())


def _strategy_gate_ok(gate_result: Any) -> Optional[bool]:
    if not isinstance(gate_result, dict):
        return None
    if "ok" not in gate_result:
        return None
    try:
        return bool(gate_result.get("ok"))
    except Exception:
        return None


def _iso_from_any(v: Any) -> Optional[str]:
    if v is None:
        return None
    if isinstance(v, (int, float)):
        try:
            x = float(v)
        except Exception:
            return None
        if not math.isfinite(x) or x <= 0:
            return None
        if x > 1e12:
            ts_ms = int(x)
        else:
            ts_ms = int(x * 1000.0)
        try:
            return datetime.fromtimestamp(ts_ms / 1000.0, tz=timezone.utc).isoformat()
        except Exception:
            return None
    s = str(v or "").strip()
    if not s:
        return None
    try:
        if s.endswith("Z"):
            s2 = s[:-1] + "+00:00"
        else:
            s2 = s
        dt = datetime.fromisoformat(s2)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc).isoformat()
    except Exception:
        return None


def _strategy_lifecycle_prereq_ok(*, to_state: str, entry: Dict[str, Any]) -> Tuple[bool, str]:
    st = _strategy_lifecycle_normalize(to_state)
    if st is None:
        return False, "invalid_lifecycle_state"

    tier = _strategy_tier_normalize(entry.get("tier")) or "unrated"
    robust = _strategy_robustness_normalize(entry.get("robustness")) or "unknown"
    gate_ok = _strategy_gate_ok(entry.get("gate_result"))
    has_bundle = bool(str(entry.get("bundle_id") or "").strip())
    rollout = entry.get("rollout") if isinstance(entry.get("rollout"), dict) else None
    rollout_status = str((rollout or {}).get("status") or "").strip().lower() if rollout else ""
    eval_policy_ref = str(entry.get("eval_policy_ref") or "").strip()
    approved_by = str(entry.get("approved_by") or "").strip()
    approved_at = _iso_from_any(entry.get("approved_at"))

    if st == "research_validated":
        ms = entry.get("metrics_summary") if isinstance(entry.get("metrics_summary"), dict) else None
        bs = entry.get("backtest_spec") if isinstance(entry.get("backtest_spec"), dict) else None
        if not ms:
            return False, "metrics_required"
        if not bs:
            return False, "backtest_spec_required"
        if ms.get("profit_factor") is None or ms.get("max_drawdown_pct") is None or ms.get("trades") is None or ms.get("winrate") is None:
            return False, "metrics_summary_incomplete"
        if (bs.get("timeframe") is None) or (str(bs.get("timeframe") or "").strip() == ""):
            return False, "timeframe_required"
        if (bs.get("timerange") is None) and (bs.get("start") is None or bs.get("end") is None):
            return False, "timerange_required"

    if st == "model_candidate":
        if tier == "unrated":
            return False, "tier_required"
        if robust == "fail":
            return False, "robustness_fail"
        if not eval_policy_ref:
            return False, "eval_policy_required"
        if not has_bundle:
            return False, "bundle_required"
    if st == "approved":
        if tier not in ("A", "B", "C"):
            return False, "tier_required"
        if robust == "fail":
            return False, "robustness_fail"
        if gate_ok is not True:
            return False, "gate_required"
        if not eval_policy_ref:
            return False, "eval_policy_required"
        if not approved_by or not approved_at:
            return False, "approval_required"
    if st in ("deployed_canary", "deployed_full"):
        if tier not in ("A", "B", "C"):
            return False, "tier_required"
        if robust == "fail":
            return False, "robustness_fail"
        if gate_ok is not True:
            return False, "gate_required"
        if not eval_policy_ref:
            return False, "eval_policy_required"
        if not approved_by or not approved_at:
            return False, "approval_required"
        if not has_bundle:
            return False, "bundle_required"
        if st == "deployed_canary" and rollout_status not in ("canary", "planned", "full", "completed"):
            return False, "rollout_required"
        if st == "deployed_full" and rollout_status not in ("full", "completed"):
            return False, "rollout_full_required"
    if st == "rolled_back":
        rb = entry.get("rollback") if isinstance(entry.get("rollback"), dict) else None
        if not rb or not str(rb.get("to_bundle_id") or "").strip():
            return False, "rollback_to_bundle_required"

    return True, ""


def _strategy_tier_normalize(v: Any) -> Optional[str]:
    if v is None:
        return None
    s = str(v or "").strip().lower()
    if s in ("a", "b", "c"):
        return s.upper()
    if s == "unrated":
        return "unrated"
    return None


def _strategy_econ_driver_validate(*, family: str, econ_driver: Any) -> bool:
    if econ_driver is None:
        return True
    s = str(econ_driver or "").strip().lower()
    if not s:
        return True
    fam = _strategy_family_normalize(family) or "trend"
    if fam == "trend":
        return s == "trend" or s.startswith("trend:") or s.startswith("trend/")
    if fam == "mean_reversion":
        return s == "mean_reversion" or s.startswith("mean_reversion:") or s.startswith("mean_reversion/")
    if fam == "carry":
        return s == "carry" or s.startswith("carry:") or s.startswith("carry/")
    if fam == "breakout":
        return s == "breakout" or s.startswith("breakout:") or s.startswith("breakout/")
    return True


def _strategy_oos_pass_from_summary(oos_summary: Any) -> Optional[bool]:
    if not isinstance(oos_summary, dict):
        return None
    if "pass" in oos_summary:
        try:
            return bool(oos_summary.get("pass"))
        except Exception:
            return None
    wf = oos_summary.get("walk_forward") if isinstance(oos_summary.get("walk_forward"), dict) else None
    if not isinstance(wf, dict):
        return None
    summ = wf.get("summary") if isinstance(wf.get("summary"), dict) else None
    if not isinstance(summ, dict):
        return None
    ok_rate = _to_float(summ.get("oos_ok_rate"))
    hf = _to_int(summ.get("oos_hard_fail_n"))
    if ok_rate is None or hf is None:
        return None
    if hf <= 0 and ok_rate >= 0.6:
        return True
    if ok_rate >= 0.75:
        return True
    return False


def _strategy_robustness_from_oos_summary(oos_summary: Any) -> Optional[str]:
    if not isinstance(oos_summary, dict):
        return None
    p = _strategy_oos_pass_from_summary(oos_summary)
    if p is None:
        return None
    if not bool(p):
        return "fail"
    wf = oos_summary.get("walk_forward") if isinstance(oos_summary.get("walk_forward"), dict) else None
    summ = wf.get("summary") if isinstance(wf, dict) else None
    if not isinstance(summ, dict):
        return "pass"
    ok_rate = _to_float(summ.get("oos_ok_rate"))
    hf = _to_int(summ.get("oos_hard_fail_n"))
    if ok_rate is None or hf is None:
        return "pass"
    if hf > 0 or ok_rate < 0.75:
        return "warn"
    return "pass"


def _norm_dd_pct(v: Any) -> Optional[float]:
    try:
        x = float(v)
    except Exception:
        return None
    if not math.isfinite(x):
        return None
    if x < 0:
        x = abs(x)
    if x > 1.5:
        return x / 100.0
    return x


def _to_float(v: Any) -> Optional[float]:
    try:
        x = float(v)
        return x if math.isfinite(x) else None
    except Exception:
        return None


def _to_int(v: Any) -> Optional[int]:
    try:
        x = int(v)
        return x
    except Exception:
        return None


def _strategy_extras_from_trades(trades: List[Dict[str, Any]], backtest_days: Optional[float]) -> Dict[str, Any]:
    profits: List[float] = []
    for t in trades:
        p = _to_float((t or {}).get("profit_abs"))
        if p is None:
            continue
        profits.append(p)

    wins = [p for p in profits if p > 0]
    losses = [p for p in profits if p < 0]

    avg_win = (sum(wins) / len(wins)) if wins else None
    avg_loss_abs = (abs(sum(losses) / len(losses))) if losses else None
    avg_win_loss_ratio = None
    if avg_win is not None and avg_loss_abs is not None and avg_loss_abs > 0:
        avg_win_loss_ratio = avg_win / avg_loss_abs

    gross_profit = sum(wins) if wins else 0.0
    tail_loss_ratio = None
    if gross_profit > 0 and losses:
        worst = sorted(profits)[:10]
        tail = sum([p for p in worst if p < 0])
        tail_loss_ratio = abs(tail) / gross_profit

    seq_losses = 0
    max_seq_losses = 0
    for p in profits:
        if p < 0:
            seq_losses += 1
            if seq_losses > max_seq_losses:
                max_seq_losses = seq_losses
        else:
            seq_losses = 0

    signal_density = None
    try:
        d = float(backtest_days) if backtest_days is not None else None
        if d is not None and math.isfinite(d) and d > 0:
            signal_density = len(profits) / d
    except Exception:
        signal_density = None

    return {
        "avg_win_loss_ratio": avg_win_loss_ratio,
        "tail_loss_ratio": tail_loss_ratio,
        "max_consecutive_losses": int(max_seq_losses),
        "signal_density": signal_density,
        "gross_profit_abs": gross_profit,
    }


def _tier_eval(
    *,
    family: str,
    profit_factor: Optional[float],
    max_drawdown_pct: Optional[float],
    winrate: Optional[float],
    trades: Optional[int],
    backtest_days: Optional[float],
    extras: Dict[str, Any],
    robustness: str,
    signal_density_p50: Optional[float],
    cost_explicit: Optional[bool] = None,
    oos_pass: Optional[bool] = None,
) -> str:
    fam = (family or "").strip().lower() or "trend"
    pf = profit_factor
    dd = max_drawdown_pct
    wr = winrate
    n = trades
    robust = (robustness or "").strip().lower() or "warn"

    def ok_robust(levels: Tuple[str, ...]) -> bool:
        return robust in levels

    if cost_explicit is not None and (not bool(cost_explicit)):
        return "unrated"

    if pf is None or dd is None or wr is None or n is None:
        return "unrated"

    days = backtest_days
    if days is None or (not isinstance(days, (int, float))) or (not math.isfinite(float(days))) or float(days) < 180:
        return "unrated"

    if robust == "fail":
        return "unrated"

    if fam not in ("mean_reversion", "mr", "meanreversion"):
        rolling_pass = robust == "pass"
        if n < 120:
            if n < 80:
                return "unrated"
            if not (rolling_pass or bool(oos_pass)):
                return "unrated"

    if fam in ("mean_reversion", "mr", "meanreversion"):
        tail = _to_float(extras.get("tail_loss_ratio"))
        mcl = _to_int(extras.get("max_consecutive_losses"))
        if tail is None or mcl is None:
            return "unrated"

        if pf >= 1.25 and dd <= 0.16 and wr >= 0.48 and tail <= 0.55 and mcl <= 8 and n >= 150 and ok_robust(("pass",)):
            return "A"
        if pf >= 1.12 and dd <= 0.22 and wr >= 0.45 and tail <= 0.75 and mcl <= 10 and n >= 120 and ok_robust(("pass", "warn")):
            return "B"
        if pf >= 1.05 and dd <= 0.30 and wr >= 0.40 and tail <= 0.90 and mcl <= 12 and n >= 100 and ok_robust(("pass", "warn")):
            return "C"
        return "unrated"

    awlr = _to_float(extras.get("avg_win_loss_ratio"))
    sd = _to_float(extras.get("signal_density"))
    if awlr is None:
        return "unrated"

    density_ok_a = True
    if sd is not None and signal_density_p50 is not None and math.isfinite(signal_density_p50) and signal_density_p50 > 0:
        density_ok_a = sd <= signal_density_p50

    if pf >= 1.30 and dd <= 0.18 and wr >= 0.34 and awlr >= 1.60 and n >= 120 and ok_robust(("pass",)) and density_ok_a:
        return "A"
    if pf >= 1.15 and dd <= 0.25 and wr >= 0.32 and awlr >= 1.35 and n >= 100 and ok_robust(("pass", "warn")):
        return "B"
    if pf >= 1.05 and dd <= 0.35 and wr >= 0.30 and awlr >= 1.20 and n >= 80 and ok_robust(("pass", "warn")):
        return "C"
    return "unrated"


def _tier_reason(
    *,
    family: str,
    profit_factor: Optional[float],
    max_drawdown_pct: Optional[float],
    winrate: Optional[float],
    trades: Optional[int],
    backtest_days: Optional[float],
    extras: Dict[str, Any],
    robustness: str,
    signal_density_p50: Optional[float],
    cost_explicit: Optional[bool] = None,
    oos_pass: Optional[bool] = None,
) -> str:
    fam = (family or "").strip().lower() or "trend"
    pf = profit_factor
    dd = max_drawdown_pct
    wr = winrate
    n = trades
    days = backtest_days
    robust = (robustness or "").strip().lower() or "unknown"
    awlr = _to_float(extras.get("avg_win_loss_ratio"))
    tail = _to_float(extras.get("tail_loss_ratio"))
    mcl = _to_int(extras.get("max_consecutive_losses"))
    sd = _to_float(extras.get("signal_density"))

    bits: List[str] = []
    if pf is not None:
        bits.append(f"pf={pf:.2f}")
    if dd is not None:
        bits.append(f"dd={dd * 100:.1f}%")
    if wr is not None:
        bits.append(f"wr={wr * 100:.1f}%")
    if n is not None:
        bits.append(f"trades={n}")
    if days is not None and math.isfinite(float(days)):
        bits.append(f"days={float(days):.0f}")
    if fam in ("mean_reversion", "mr", "meanreversion"):
        if tail is not None:
            bits.append(f"tail={tail:.2f}")
        if mcl is not None:
            bits.append(f"mcl={mcl}")
    else:
        if awlr is not None:
            bits.append(f"awlr={awlr:.2f}")
        if sd is not None:
            if signal_density_p50 is not None and math.isfinite(float(signal_density_p50)):
                bits.append(f"sd={sd:.2f} (p50={float(signal_density_p50):.2f})")
            else:
                bits.append(f"sd={sd:.2f}")
    bits.append(f"robust={robust}")

    prereq: List[str] = []
    if cost_explicit is not None and (not bool(cost_explicit)):
        prereq.append("cost_missing")
    if days is None or (not math.isfinite(float(days))) or float(days) < 180:
        prereq.append("days<180")
    if robust == "fail":
        prereq.append("robust=fail")
    if fam not in ("mean_reversion", "mr", "meanreversion"):
        rolling_pass = robust == "pass"
        if n is not None and n < 120 and n >= 80 and (not (rolling_pass or bool(oos_pass))):
            prereq.append("trend_relax_requires_rolling_or_oos_pass")
    if prereq:
        return "prereq_fail:" + ",".join(prereq) + "; " + "; ".join(bits)
    return "; ".join(bits)


def _strategy_source_path(strategy_id: str) -> Optional[Path]:
    sid = (strategy_id or "").strip()
    if not sid:
        return None
    root = _user_data_dir() / "strategies"
    p0 = root / f"{sid}.py"
    if p0.exists() and p0.is_file():
        return p0
    try:
        files = list(root.glob("*.py"))
    except Exception:
        files = []
    sid_low = sid.lower()
    for p in files:
        if p.name.lower() == f"{sid_low}.py":
            return p
    for p in files:
        if sid_low in p.name.lower():
            return p
    return None


def _cost_profile_norm(*, fees_bps: Any, slippage_bps: Any, market_type: Any, leverage_mode: Any, stake_currency: Any) -> Dict[str, Any]:
    fb = _to_float(fees_bps)
    sb = _to_float(slippage_bps)
    mt = None if market_type is None else str(market_type).strip()
    lm = None if leverage_mode is None else str(leverage_mode).strip()
    sc = None if stake_currency is None else str(stake_currency).strip()
    return {
        "fees_bps": (None if fb is None or (not math.isfinite(float(fb))) else float(fb)),
        "slippage_bps": (None if sb is None or (not math.isfinite(float(sb))) else float(sb)),
        "market_type": (None if not mt else mt),
        "leverage_mode": (None if not lm else lm),
        "stake_currency": (None if not sc else sc),
    }


def _cost_profile_id(cost_profile: Dict[str, Any]) -> Optional[str]:
    try:
        b = json.dumps(cost_profile or {}, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(b).hexdigest()
    except Exception:
        return None


def _json_canon_dumps(obj: Any) -> str:
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def _sha256_hex(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def _json_hash(obj: Any) -> Optional[str]:
    try:
        return _sha256_hex(_json_canon_dumps(obj).encode("utf-8"))
    except Exception:
        return None


def _eval_policy_resolve(ref: str) -> Dict[str, Any]:
    r = str(ref or "").strip()
    if not r:
        return {}
    mp = (CONFIG or {}).get("eval_policies")
    if not isinstance(mp, dict):
        mp = (CONFIG or {}).get("eval_policy_registry")
    if not isinstance(mp, dict):
        return {}
    v = mp.get(r)
    return dict(v) if isinstance(v, dict) else {}


def _gate_result_hash_seed(gate_result: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(gate_result, dict):
        return None
    seed = dict(gate_result)
    if "ts" in seed:
        seed.pop("ts", None)
    return seed


def _bundle_v1_build(
    *,
    zip_path: Path,
    strategy_id: str,
    family: str,
    tier: str,
    stage: str,
    tags: List[str],
    eval_policy_ref: str,
    robustness: str,
    governance_overrides: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    p = Path(zip_path)
    if (not p.exists()) or (not p.is_file()):
        return {"ok": False, "error": "backtest_zip_not_found"}

    cfg = _backtest_zip_load_config_json(p) or {}
    main = _backtest_zip_load_main_json(p) or {}
    metrics = _backtest_zip_metrics(p) or {}

    by_key: Dict[str, Any] = {}
    for row in (metrics.get("strategies") if isinstance(metrics, dict) else []) or []:
        if isinstance(row, dict):
            k = str(row.get("key") or "").strip()
            if k:
                by_key[k] = row

    row = by_key.get(strategy_id) or (by_key.get("".join(strategy_id.split())) if strategy_id else None) or {}
    backtest_days = _to_float(row.get("backtest_days"))
    trades_n = _to_int(row.get("trades"))
    pf = _to_float(row.get("profit_factor"))
    wr = _to_float(row.get("winrate"))
    dd = _norm_dd_pct(row.get("max_drawdown_account"))

    sm = main.get("strategy") if isinstance(main, dict) else None
    trades: List[Dict[str, Any]] = []
    if isinstance(sm, dict):
        block = sm.get(strategy_id) if strategy_id in sm else None
        if not isinstance(block, dict):
            for k0, v0 in sm.items():
                if str(k0).strip() == str(strategy_id).strip() and isinstance(v0, dict):
                    block = v0
                    break
        if isinstance(block, dict):
            ts = block.get("trades")
            if isinstance(ts, list):
                for t in ts:
                    if isinstance(t, dict):
                        trades.append(t)

    extras = _strategy_extras_from_trades(trades, backtest_days)
    bundle_created_at = datetime.now(timezone.utc).isoformat()

    def _sha256(b: bytes) -> str:
        return hashlib.sha256(b).hexdigest()

    src_path = _strategy_source_path(strategy_id)

    reg = _strategy_registry_load()
    entries = reg.get("entries") if isinstance(reg.get("entries"), dict) else {}
    reg_entry = _strategy_registry_pick(entries, strategy_id, str(p.name))
    reg_source = (reg_entry.get("source") if isinstance(reg_entry, dict) else None)
    picked_strategy_path: Optional[Path] = None
    if src_path is not None and src_path.exists() and src_path.is_file():
        picked_strategy_path = src_path
    else:
        sandbox_path = (str(reg_source.get("sandbox_path") or "").strip() if isinstance(reg_source, dict) else "")
        if sandbox_path:
            sp = Path(sandbox_path)
            if sp.exists() and sp.is_dir():
                try:
                    cands = list(sp.glob("*.py"))
                except Exception:
                    cands = []
                sid_low = str(strategy_id).strip().lower()
                exact = [x for x in cands if x.stem.lower() == sid_low]
                contain = [x for x in cands if sid_low and sid_low in x.stem.lower()]
                picked_strategy_path = (exact[0] if exact else (contain[0] if contain else (cands[0] if cands else None)))

    source_path = None
    if isinstance(reg_source, dict) and str(reg_source.get("path") or "").strip():
        source_path = str(reg_source.get("path") or "").strip()
    elif picked_strategy_path is not None:
        source_path = picked_strategy_path.name
    source = {
        "zip": str(p.name),
        "repo_url": (str(reg_source.get("repo_url") or "").strip() if isinstance(reg_source, dict) else None) or None,
        "commit": (str(reg_source.get("commit") or "").strip() if isinstance(reg_source, dict) else None) or None,
        "path": source_path,
    }

    timerange = cfg.get("timerange")
    timeframe = cfg.get("timeframe")
    ex = cfg.get("exchange") if isinstance(cfg.get("exchange"), dict) else {}
    pair_whitelist = ex.get("pair_whitelist") if isinstance(ex.get("pair_whitelist"), list) else []
    market_type = cfg.get("trading_mode") or cfg.get("market_type")
    leverage_mode = cfg.get("margin_mode") or cfg.get("leverage_mode")
    fees_bps = None
    try:
        fee = cfg.get("fee")
        if fee is not None:
            fees_bps = float(fee) * 10000.0
    except Exception:
        fees_bps = None
    slippage_bps = None
    try:
        if cfg.get("slippage_bps") is not None:
            slippage_bps = float(cfg.get("slippage_bps"))
    except Exception:
        slippage_bps = None

    cost_profile = _cost_profile_norm(
        fees_bps=fees_bps,
        slippage_bps=slippage_bps,
        market_type=market_type,
        leverage_mode=leverage_mode,
        stake_currency=cfg.get("stake_currency"),
    )
    if cost_profile.get("fees_bps") is None or cost_profile.get("slippage_bps") is None:
        return {"ok": False, "error": "missing_cost_profile"}
    cost_profile_id = _cost_profile_id(cost_profile)
    if not cost_profile_id:
        return {"ok": False, "error": "cost_profile_id_failed"}

    config_version = None
    try:
        cfg_norm = json.dumps(cfg, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        config_version = hashlib.sha256(cfg_norm).hexdigest()
    except Exception:
        config_version = None

    data_snapshot_id = None
    try:
        snapshot_obj = {
            "datadir": cfg.get("datadir"),
            "timerange": timerange,
            "timeframe": timeframe,
            "pair_universe": [str(x) for x in pair_whitelist if str(x or "").strip()],
        }
        snap_norm = json.dumps(snapshot_obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        data_snapshot_id = hashlib.sha256(snap_norm).hexdigest()
    except Exception:
        data_snapshot_id = None

    starting_balance = cfg.get("dry_run_wallet") if cfg.get("dry_run_wallet") is not None else cfg.get("starting_balance")

    files: Dict[str, bytes] = {}

    if picked_strategy_path is None or (not picked_strategy_path.exists()) or (not picked_strategy_path.is_file()):
        return {"ok": False, "error": "strategy_source_not_found"}

    scan_hits = _strategy_scan_forbidden([picked_strategy_path])
    scan_obj = {
        "ok": (not bool(scan_hits)),
        "ts": int(_now_ms()),
        "ruleset_version": 2,
        "files": [str(picked_strategy_path.name)],
        "issues": scan_hits,
    }
    if scan_hits:
        return {"ok": False, "error": "strategy_code_scan_failed", "scan": scan_obj}

    try:
        src_bytes = picked_strategy_path.read_bytes()
        files[f"strategy/{picked_strategy_path.name}"] = src_bytes
    except Exception:
        return {"ok": False, "error": "strategy_source_read_failed"}

    files["config/config.json"] = json.dumps(cfg, ensure_ascii=False, indent=2).encode("utf-8")
    files["data_ref/data_ref.json"] = json.dumps(
        {
            "backtest_zip": str(p.name),
            "data_snapshot_id": data_snapshot_id,
            "config_version": config_version,
            "timerange": timerange,
            "timeframe": timeframe,
            "pair_universe": pair_whitelist,
            "datadir": cfg.get("datadir"),
        },
        ensure_ascii=False,
        indent=2,
    ).encode("utf-8")

    try:
        files["reports/backtest_result.zip"] = p.read_bytes()
    except Exception:
        pass

    try:
        if isinstance(reg_entry, dict) and reg_entry:
            files["reports/registry_entry.json"] = json.dumps(reg_entry, ensure_ascii=False, indent=2).encode("utf-8")
    except Exception:
        pass

    try:
        files["reports/code_scan.json"] = json.dumps(scan_obj, ensure_ascii=False, indent=2).encode("utf-8")
    except Exception:
        pass

    manifest_seed = {
        "bundle_version": "1.0",
        "bundle_id": None,
        "created_at": bundle_created_at,
        "strategy": {
            "strategy_id": strategy_id,
            "family": family,
            "tier": tier,
            "tags": tags,
            "source": source,
        },
        "backtest_spec": {
            "data_snapshot_id": data_snapshot_id,
            "config_version": config_version,
            "timerange": timerange,
            "timeframe": timeframe,
            "pair_universe": pair_whitelist,
            "fees_bps": fees_bps,
            "slippage_bps": slippage_bps,
            "cost_profile_id": cost_profile_id,
            "starting_balance": starting_balance,
            "stake_currency": cfg.get("stake_currency"),
            "market_type": (None if market_type is None else str(market_type)),
            "leverage_mode": (None if leverage_mode is None else str(leverage_mode)),
        },
        "results": {
            "metrics_summary": {
                "profit_factor": pf,
                "max_drawdown_pct": dd,
                "trades": trades_n,
                "winrate": wr,
            },
            "signal_density": extras.get("signal_density"),
            "robustness": (str(robustness or "unknown").strip() or "unknown"),
            "code_scan": scan_obj,
            "extras": {
                "avg_win_loss_ratio": extras.get("avg_win_loss_ratio"),
                "tail_loss_ratio": extras.get("tail_loss_ratio"),
                "max_consecutive_losses": extras.get("max_consecutive_losses"),
            },
        },
        "governance": {
            "stage": stage,
            "eval_policy_ref": eval_policy_ref,
            "approved_by": None,
            "approved_at": None,
            "rollout_plan": None,
        },
    }

    gov = manifest_seed.get("governance") if isinstance(manifest_seed.get("governance"), dict) else None
    if gov is not None and isinstance(governance_overrides, dict):
        for k, v in governance_overrides.items():
            if v is None:
                continue
            gov[str(k)] = v

    other_hashes = {k: _sha256(v) for k, v in files.items()}
    seed_norm = json.dumps(manifest_seed, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    hashes_norm = json.dumps(other_hashes, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    bundle_id = hashlib.sha256(seed_norm + hashes_norm).hexdigest()

    manifest = dict(manifest_seed)
    manifest["bundle_id"] = bundle_id
    files["manifest.json"] = json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8")

    checksums = {k: _sha256(v) for k, v in files.items()}
    files["checksums/sha256.json"] = json.dumps(checksums, ensure_ascii=False, indent=2).encode("utf-8")

    out_dir = _strategy_bundles_dir()
    try:
        out_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    safe_sid = "".join([c for c in strategy_id if c.isalnum() or c in ("-", "_", ".")]) or "strategy"
    safe_zip = "".join([c for c in p.stem if c.isalnum() or c in ("-", "_", ".")])
    out_name = f"strategy_bundle_{safe_sid}_{safe_zip}_{bundle_id[:10]}.zip"
    out_path = out_dir / out_name

    try:
        with zipfile.ZipFile(out_path, "w", compression=zipfile.ZIP_DEFLATED) as zf:
            for k, v in files.items():
                zf.writestr(k, v)
    except Exception as e:
        return {"ok": False, "error": str(e)}

    return {"ok": True, "bundle": out_name, "path": str(out_path), "manifest": manifest}


def _equity_metrics_from_exec_rows(rows: List[Dict[str, Any]], limit: int = 5000, base_equity_u: Optional[float] = None) -> Dict[str, Any]:
    rs = [r for r in (rows or []) if isinstance(r, dict)]
    rs.sort(key=lambda x: int(x.get("ts") or 0))
    if limit and len(rs) > int(limit):
        rs = rs[-int(limit):]

    pts: List[Dict[str, Any]] = []
    cum = 0.0
    for r in rs:
        pnl = float(r.get("pnl_net_u") or 0.0)
        if pnl == 0.0:
            continue
        cum += float(pnl)
        pts.append({"ts": int(r.get("ts") or 0), "ret": float(pnl), "cum": float(cum)})

    maxdd = 0.0
    peak = -1e18
    peak_ts = 0
    max_recovery_ms: Optional[int] = None
    in_drawdown = False
    dd_start_ts = 0
    dd_peak = -1e18
    for p in pts:
        x = float(p.get("cum", 0.0))
        ts = int(p.get("ts") or 0)
        if x >= peak:
            if in_drawdown and dd_peak > -1e17:
                rec = ts - int(dd_start_ts or 0)
                if rec >= 0:
                    max_recovery_ms = rec if max_recovery_ms is None else max(max_recovery_ms, rec)
            peak = x
            peak_ts = ts
            in_drawdown = False
            dd_start_ts = ts
            dd_peak = x
        else:
            if not in_drawdown:
                in_drawdown = True
                dd_start_ts = peak_ts
                dd_peak = peak
            maxdd = max(maxdd, peak - x)

    total = float(cum)
    calmar = (float(total) / float(max(1e-9, maxdd))) if pts else None

    rets = [float(p.get("ret", 0.0)) for p in pts]
    sharpe = None
    if len(rets) >= 2:
        mu = sum(rets) / float(len(rets))
        var_ = sum((x - mu) ** 2 for x in rets) / float(max(1, len(rets) - 1))
        sd = math.sqrt(max(0.0, var_))
        if sd > 0.0:
            sharpe = float(total) / float(sd)

    neg = [x for x in rets if x < 0.0]
    sortino = None
    if len(neg) >= 2:
        mu = sum(neg) / float(len(neg))
        var_ = sum((x - mu) ** 2 for x in neg) / float(max(1, len(neg) - 1))
        sd = math.sqrt(max(0.0, var_))
        if sd > 0.0:
            sortino = float(total) / float(sd)

    wins = 0
    losses = 0
    trades = 0
    fees_sum = 0.0
    funding_sum = 0.0
    daily: Dict[str, float] = {}
    weekly: Dict[str, float] = {}
    for r in rs:
        pnl = float(r.get("pnl_net_u") or 0.0)
        if pnl == 0.0:
            continue
        trades += 1
        if pnl > 0.0:
            wins += 1
        else:
            losses += 1
        fees_sum += float(r.get("fees_u") or 0.0)
        funding_sum += float(r.get("funding_u") or 0.0)
        ts = int(r.get("ts") or 0)
        try:
            dt = datetime.datetime.utcfromtimestamp(max(0, ts) / 1000.0)
            day = dt.strftime("%Y-%m-%d")
            iso = dt.isocalendar()
            wk = f"{iso[0]:04d}-W{iso[1]:02d}"
            daily[day] = float(daily.get(day, 0.0)) + float(pnl)
            weekly[wk] = float(weekly.get(wk, 0.0)) + float(pnl)
        except Exception:
            pass

    winrate = float(wins) / float(max(1, trades)) if trades > 0 else None
    max_daily_loss_u = min(daily.values()) if daily else None
    max_weekly_loss_u = min(weekly.values()) if weekly else None
    base_u = None
    try:
        if base_equity_u is not None and math.isfinite(float(base_equity_u)) and float(base_equity_u) > 0.0:
            base_u = float(base_equity_u)
    except Exception:
        base_u = None
    total_pct = (float(total) / float(base_u)) if base_u else None
    maxdd_pct = (float(maxdd) / float(base_u)) if base_u else None
    max_daily_loss_pct = (float(max_daily_loss_u) / float(base_u)) if (base_u and max_daily_loss_u is not None) else None
    max_weekly_loss_pct = (float(max_weekly_loss_u) / float(base_u)) if (base_u and max_weekly_loss_u is not None) else None

    return {
        "schema_version": 2,
        "ts": _now_ms(),
        "equity": pts,
        "total": float(total),
        "total_pct": total_pct,
        "maxdd": float(maxdd),
        "maxdd_pct": maxdd_pct,
        "calmar": calmar,
        "sharpe": sharpe,
        "sortino": sortino,
        "dd_recovery_ms_max": (None if max_recovery_ms is None else int(max_recovery_ms)),
        "trades": int(trades),
        "wins": int(wins),
        "losses": int(losses),
        "winrate": winrate,
        "fees_u": float(fees_sum),
        "funding_u": float(funding_sum),
        "daily_pnl_u": daily,
        "weekly_pnl_u": weekly,
        "max_daily_loss_u": max_daily_loss_u,
        "max_weekly_loss_u": max_weekly_loss_u,
        "max_daily_loss_pct": max_daily_loss_pct,
        "max_weekly_loss_pct": max_weekly_loss_pct,
        "base_equity_u": base_u,
    }


def _bt_trade_exec_row(
    trade: Dict[str, Any],
    cfg: Optional[Dict[str, Any]] = None,
    assumptions: Optional[Dict[str, Any]] = None,
    rng: Optional[random.Random] = None,
) -> Optional[Dict[str, Any]]:
    if not isinstance(trade, dict):
        return None
    a = assumptions or {}
    r = rng or random.Random()

    def _ts_ms_from_any(v: Any) -> int:
        if v is None:
            return 0
        if isinstance(v, (int, float)):
            try:
                x = float(v)
            except Exception:
                return 0
            if not math.isfinite(float(x)):
                return 0
            if x <= 0:
                return 0
            if x >= 1e12:
                return int(x)
            if x >= 1e9:
                return int(x * 1000)
            return 0
        if isinstance(v, str):
            s = str(v).strip()
            if not s:
                return 0
            s2 = s.replace("Z", "+00:00")
            if s2.endswith(" UTC"):
                s2 = s2[:-4] + "+00:00"
            try:
                from datetime import datetime, timezone
                dt = datetime.fromisoformat(s2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                return int(dt.timestamp() * 1000)
            except Exception:
                pass
            for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M:%S.%f"):
                try:
                    from datetime import datetime, timezone
                    dt = datetime.strptime(s2, fmt).replace(tzinfo=timezone.utc)
                    return int(dt.timestamp() * 1000)
                except Exception:
                    continue
        return 0

    try:
        open_ts = int(trade.get("open_timestamp") or 0)
    except Exception:
        open_ts = 0
    try:
        close_ts = int(trade.get("close_timestamp") or 0)
    except Exception:
        close_ts = 0
    if open_ts <= 0:
        open_ts = _ts_ms_from_any(trade.get("open_date")) or _ts_ms_from_any(trade.get("open_date_utc")) or _ts_ms_from_any(trade.get("open_datetime"))
    if close_ts <= 0:
        close_ts = _ts_ms_from_any(trade.get("close_date")) or _ts_ms_from_any(trade.get("close_date_utc")) or _ts_ms_from_any(trade.get("close_datetime"))
    ts = int(close_ts) if int(close_ts) > 0 else int(open_ts)

    pair = str(trade.get("pair") or "")
    is_short = bool(trade.get("is_short") or False)
    side = "short" if is_short else "long"

    leverage = None
    try:
        lv = trade.get("leverage")
        leverage = (None if lv is None else float(lv))
    except Exception:
        leverage = None
    if leverage is not None and (not math.isfinite(float(leverage))):
        leverage = None

    try:
        stake = float(trade.get("stake_amount") or 0.0)
    except Exception:
        stake = 0.0
    if not math.isfinite(float(stake)):
        stake = 0.0
    if stake <= 0.0:
        return None

    try:
        profit_ratio = float(trade.get("profit_ratio") or 0.0)
    except Exception:
        profit_ratio = 0.0
    if not math.isfinite(float(profit_ratio)):
        profit_ratio = 0.0
    pnl_gross = float(profit_ratio) * float(stake)

    fee_rate = None
    try:
        v = a.get("fee_rate")
        if v is not None and str(v) != "":
            fee_rate = float(v)
    except Exception:
        fee_rate = None
    if fee_rate is None:
        try:
            v = (cfg or {}).get("fee")
            if v is not None and str(v) != "":
                fee_rate = float(v)
        except Exception:
            fee_rate = None
    if fee_rate is None:
        try:
            fo = trade.get("fee_open")
            fc = trade.get("fee_close")
            fo_v = None if fo is None else float(fo)
            fc_v = None if fc is None else float(fc)
            if fo_v is not None and fc_v is not None:
                fee_rate = 0.5 * float(fo_v + fc_v)
            elif fo_v is not None:
                fee_rate = float(fo_v)
            elif fc_v is not None:
                fee_rate = float(fc_v)
        except Exception:
            fee_rate = None
    if fee_rate is None or (not math.isfinite(float(fee_rate))) or float(fee_rate) < 0.0:
        fee_rate = 0.0

    try:
        slippage_bps = float(a.get("slippage_bps", 0.0) or 0.0)
    except Exception:
        slippage_bps = 0.0
    if not math.isfinite(float(slippage_bps)):
        slippage_bps = 0.0
    try:
        latency_ms = float(a.get("latency_ms", 0.0) or 0.0)
    except Exception:
        latency_ms = 0.0
    if not math.isfinite(float(latency_ms)):
        latency_ms = 0.0
    try:
        latency_slip_bps_per_s = float(a.get("latency_slippage_bps_per_s", 0.0) or 0.0)
    except Exception:
        latency_slip_bps_per_s = 0.0
    if not math.isfinite(float(latency_slip_bps_per_s)):
        latency_slip_bps_per_s = 0.0
    slippage_bps_eff = float(slippage_bps) + (float(latency_ms) / 1000.0) * float(latency_slip_bps_per_s)
    slip_cost = abs(float(stake)) * (float(slippage_bps_eff) / 10000.0) * 2.0
    pnl_gross_adj = float(pnl_gross) - float(slip_cost)

    try:
        p_entry_fail = float(a.get("p_entry_fail", 0.0) or 0.0)
    except Exception:
        p_entry_fail = 0.0
    p_entry_fail = max(0.0, min(1.0, float(p_entry_fail)))
    if r.random() < p_entry_fail:
        return {
            "ts": int(ts),
            "open_ts": int(open_ts),
            "close_ts": int(close_ts),
            "pair": pair,
            "side": side,
            "pnl_gross_u": 0.0,
            "fees_u": 0.0,
            "funding_u": 0.0,
            "pnl_net_u": 0.0,
            "stake_u": float(stake),
            "leverage": leverage,
            "fill_ratio": 0.0,
            "dropped": True,
        }

    fill_ratio = 1.0
    try:
        pf_min = float(a.get("partial_fill_min", 1.0) if a.get("partial_fill_min") is not None else 1.0)
        pf_max = float(a.get("partial_fill_max", 1.0) if a.get("partial_fill_max") is not None else 1.0)
    except Exception:
        pf_min, pf_max = 1.0, 1.0
    pf_min = max(0.0, min(1.0, float(pf_min)))
    pf_max = max(0.0, min(1.0, float(pf_max)))
    if pf_max < pf_min:
        pf_min, pf_max = pf_max, pf_min
    if pf_min < 1.0 or pf_max < 1.0:
        try:
            a0 = float(a.get("partial_fill_beta_a", 0.0) or 0.0)
            b0 = float(a.get("partial_fill_beta_b", 0.0) or 0.0)
        except Exception:
            a0, b0 = 0.0, 0.0
        if a0 > 0.0 and b0 > 0.0:
            z = r.betavariate(float(a0), float(b0))
            fill_ratio = float(pf_min) + (float(pf_max) - float(pf_min)) * float(z)
        else:
            fill_ratio = float(pf_max)
    fill_ratio = max(0.0, min(1.0, float(fill_ratio)))

    fees_u = abs(float(stake) * float(fill_ratio)) * float(fee_rate) * 2.0

    funding_u = 0.0
    try:
        use_trade_funding = bool(a.get("use_trade_funding", True))
    except Exception:
        use_trade_funding = True
    if use_trade_funding:
        try:
            ff = trade.get("funding_fees")
            funding_u = abs(float(ff or 0.0))
        except Exception:
            funding_u = 0.0
    else:
        try:
            fr = float(a.get("funding_rate_per_day", 0.0) or 0.0)
        except Exception:
            fr = 0.0
        if not math.isfinite(float(fr)):
            fr = 0.0
        try:
            dur_min = float(trade.get("trade_duration") or 0.0)
        except Exception:
            dur_min = 0.0
        hold_days = max(0.0, float(dur_min) / 1440.0)
        funding_u = abs(float(stake) * float(fill_ratio)) * float(fr) * float(hold_days)

    try:
        p_exit_fail = float(a.get("p_exit_fail", 0.0) or 0.0)
    except Exception:
        p_exit_fail = 0.0
    p_exit_fail = max(0.0, min(1.0, float(p_exit_fail)))
    try:
        exit_fail_slip_bps = float(a.get("exit_fail_slippage_bps", 0.0) or 0.0)
    except Exception:
        exit_fail_slip_bps = 0.0
    if not math.isfinite(float(exit_fail_slip_bps)):
        exit_fail_slip_bps = 0.0
    exit_fail_cost = 0.0
    if p_exit_fail > 0.0 and r.random() < p_exit_fail:
        exit_fail_cost = abs(float(stake) * float(fill_ratio)) * (float(exit_fail_slip_bps) / 10000.0)

    pnl_gross_u = float(pnl_gross_adj) * float(fill_ratio)
    pnl_net_u = float(pnl_gross_u) - float(fees_u) - float(funding_u) - float(exit_fail_cost)
    if not math.isfinite(float(pnl_net_u)):
        pnl_net_u = 0.0
    return {
        "ts": int(ts),
        "open_ts": int(open_ts),
        "close_ts": int(close_ts),
        "pair": pair,
        "side": side,
        "pnl_gross_u": float(pnl_gross_u),
        "fees_u": float(fees_u),
        "funding_u": float(funding_u),
        "pnl_net_u": float(pnl_net_u),
        "stake_u": float(stake),
        "leverage": leverage,
        "fill_ratio": float(fill_ratio),
        "dropped": False,
    }


def _bt_assumptions_default(cfg: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    fee_rate = None
    try:
        v = (cfg or {}).get("fee")
        fee_rate = (None if v is None else float(v))
    except Exception:
        fee_rate = None
    if fee_rate is None or (not math.isfinite(float(fee_rate))) or float(fee_rate) < 0.0:
        fee_rate = 0.0
    return {
        "fee_rate": float(fee_rate),
        "slippage_bps": 3.0,
        "latency_ms": 120.0,
        "latency_slippage_bps_per_s": 1.0,
        "p_entry_fail": 0.005,
        "p_exit_fail": 0.002,
        "exit_fail_slippage_bps": 10.0,
        "partial_fill_min": 0.85,
        "partial_fill_max": 1.0,
        "partial_fill_beta_a": 2.0,
        "partial_fill_beta_b": 5.0,
        "use_trade_funding": True,
        "funding_rate_per_day": 0.0,
    }


def _bt_assumptions_merge(base: Optional[Dict[str, Any]], overrides: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    if isinstance(base, dict):
        out.update(base)
    if isinstance(overrides, dict):
        for k, v in overrides.items():
            kk = str(k)
            if v is None:
                continue
            out[kk] = v
    return out


def _backtest_zip_strategy_block(main_json: Optional[Dict[str, Any]], strategy: Optional[str]) -> Optional[Dict[str, Any]]:
    if not isinstance(main_json, dict):
        return None
    sm = main_json.get("strategy")
    if not isinstance(sm, dict) or not sm:
        return None
    st = None if strategy is None else str(strategy)
    if st and st in sm and isinstance(sm.get(st), dict):
        return sm.get(st)
    for v in sm.values():
        if isinstance(v, dict):
            return v
    return None


def _bt_aligned_metrics_from_zip(
    zip_path: Path,
    strategy: Optional[str] = None,
    assumptions: Optional[Dict[str, Any]] = None,
    seed: Optional[int] = None,
) -> Dict[str, Any]:
    p = Path(zip_path)
    cfg = _backtest_zip_load_config_json(p) or {}
    base_a = _bt_assumptions_default(cfg)
    a = _bt_assumptions_merge(base_a, assumptions)

    main = _backtest_zip_load_main_json(p)
    sb = _backtest_zip_strategy_block(main, strategy)

    base_equity_u = None
    try:
        v = (sb or {}).get("starting_balance")
        base_equity_u = (None if v is None else float(v))
    except Exception:
        base_equity_u = None
    if base_equity_u is not None and ((not math.isfinite(float(base_equity_u))) or float(base_equity_u) <= 0.0):
        base_equity_u = None

    trades = _backtest_zip_strategy_trades(p, strategy=strategy) or []
    rng = random.Random(1 if seed is None else int(seed))

    rows: List[Dict[str, Any]] = []
    for t in trades:
        try:
            rr = _bt_trade_exec_row(t, cfg=cfg, assumptions=a, rng=rng)
        except Exception:
            rr = None
        if isinstance(rr, dict):
            rows.append(rr)

    snap = _equity_metrics_from_exec_rows(rows, limit=0, base_equity_u=base_equity_u)

    lev_avg = None
    lev_max = None
    levs: List[float] = []
    for r in rows:
        try:
            lv = r.get("leverage")
            if lv is None:
                continue
            x = float(lv)
            if math.isfinite(x) and x > 0.0:
                levs.append(x)
        except Exception:
            continue
    if levs:
        lev_avg = float(sum(levs)) / float(len(levs))
        lev_max = float(max(levs))

    hold_hours_dist = None
    try:
        hold_hours: List[float] = []
        for r in rows:
            try:
                o = int(r.get("open_ts") or 0)
                c = int(r.get("close_ts") or 0)
            except Exception:
                continue
            if o > 0 and c > o:
                hold_hours.append(float(c - o) / 3_600_000.0)
        hold_hours_dist = _dist_summary(hold_hours) if hold_hours else None
        if isinstance(hold_hours_dist, dict) and int(hold_hours_dist.get("n") or 0) <= 0:
            hold_hours_dist = None
    except Exception:
        hold_hours_dist = None

    return {
        "ok": True,
        "schema_version": int(snap.get("schema_version") or 2),
        "assumptions": a,
        "base_equity_u": snap.get("base_equity_u"),
        "total": snap.get("total"),
        "total_pct": snap.get("total_pct"),
        "maxdd": snap.get("maxdd"),
        "maxdd_pct": snap.get("maxdd_pct"),
        "calmar": snap.get("calmar"),
        "sharpe": snap.get("sharpe"),
        "sortino": snap.get("sortino"),
        "dd_recovery_ms_max": snap.get("dd_recovery_ms_max"),
        "trades": snap.get("trades"),
        "wins": snap.get("wins"),
        "losses": snap.get("losses"),
        "winrate": snap.get("winrate"),
        "fees_u": snap.get("fees_u"),
        "funding_u": snap.get("funding_u"),
        "daily_pnl_u": snap.get("daily_pnl_u"),
        "weekly_pnl_u": snap.get("weekly_pnl_u"),
        "max_daily_loss_u": snap.get("max_daily_loss_u"),
        "max_weekly_loss_u": snap.get("max_weekly_loss_u"),
        "max_daily_loss_pct": snap.get("max_daily_loss_pct"),
        "max_weekly_loss_pct": snap.get("max_weekly_loss_pct"),
        "trade_exec_n": int(len(rows)),
        "leverage_avg": lev_avg,
        "leverage_max": lev_max,
        "hold_hours_dist": hold_hours_dist,
    }


def _dist_summary(xs: List[float]) -> Dict[str, Any]:
    vals = [float(x) for x in (xs or []) if x is not None and math.isfinite(float(x))]
    vals.sort()
    n = len(vals)
    if n <= 0:
        return {"n": 0}

    def _q(p: float) -> float:
        if n == 1:
            return float(vals[0])
        i = float(p) * float(n - 1)
        lo = int(math.floor(i))
        hi = int(math.ceil(i))
        if lo == hi:
            return float(vals[lo])
        w = i - float(lo)
        return float(vals[lo]) * (1.0 - float(w)) + float(vals[hi]) * float(w)

    mean = float(sum(vals)) / float(n)
    sd = 0.0
    if n >= 2:
        var = sum((float(x) - mean) ** 2 for x in vals) / float(max(1, n - 1))
        sd = float(math.sqrt(max(0.0, float(var))))

    return {
        "n": int(n),
        "mean": float(mean),
        "std": float(sd),
        "min": float(vals[0]),
        "p05": float(_q(0.05)),
        "p50": float(_q(0.50)),
        "p95": float(_q(0.95)),
        "max": float(vals[-1]),
    }


def _bt_state_for_row(r: Dict[str, Any], vol_ratio_thr: float, trend_dist_thr: float) -> str:
    try:
        pair = str(r.get("pair") or "")
        ts = int(r.get("open_ts") or r.get("ts") or 0)
    except Exception:
        pair, ts = "", 0
    if (not pair) or ts <= 0:
        return "unknown"
    f = _ml3_features_at_timestamp(pair, int(ts)) or {}
    if not isinstance(f, dict) or not f:
        return "unknown"
    try:
        vr = float(f.get("rv_ratio_24_168") or 0.0)
    except Exception:
        vr = 0.0
    try:
        dist = float(f.get("dist_ma20") or 0.0)
    except Exception:
        dist = 0.0
    if math.isfinite(float(vr)) and float(vr) >= float(vol_ratio_thr):
        return "high_vol"
    if math.isfinite(float(dist)) and abs(float(dist)) >= float(trend_dist_thr):
        return "trend"
    return "chop"


def _equity_metrics_from_pnls(pnls: List[float], base_equity_u: Optional[float] = None) -> Dict[str, Any]:
    rows: List[Dict[str, Any]] = []
    t = 0
    for p in pnls or []:
        t += 1
        try:
            x = float(p)
        except Exception:
            x = 0.0
        if not math.isfinite(float(x)):
            x = 0.0
        rows.append({"ts": int(t), "pnl_net_u": float(x)})
    return _equity_metrics_from_exec_rows(rows, limit=0, base_equity_u=base_equity_u)


def _bt_robustness_from_zip(
    zip_path: Path,
    strategy: Optional[str] = None,
    assumptions: Optional[Dict[str, Any]] = None,
    sensitivity: Optional[Dict[str, Any]] = None,
    policy: Optional[Dict[str, Any]] = None,
    seed: Optional[int] = None,
    n_slices: int = 6,
    n_bootstrap: int = 200,
    n_shuffle: int = 200,
    vol_ratio_thr: float = 1.5,
    trend_dist_thr: float = 0.01,
) -> Dict[str, Any]:
    p = Path(zip_path)
    cfg = _backtest_zip_load_config_json(p) or {}
    a = _bt_assumptions_merge(_bt_assumptions_default(cfg), assumptions)
    main = _backtest_zip_load_main_json(p)
    sb = _backtest_zip_strategy_block(main, strategy)
    tf0 = None
    try:
        tf0 = str(cfg.get("timeframe") or "").strip() or None
    except Exception:
        tf0 = None
    pair_n = 1
    try:
        ex0 = cfg.get("exchange") if isinstance(cfg.get("exchange"), dict) else {}
        wl0 = ex0.get("pair_whitelist") if isinstance(ex0.get("pair_whitelist"), list) else []
        pair_n = max(1, int(len(wl0)))
    except Exception:
        pair_n = 1
    fam0 = None
    try:
        fam0 = (None if not strategy else (_infer_strategy_family_from_id(str(strategy)) or None))
    except Exception:
        fam0 = None

    def _policy_scaled(policy_in: Optional[Dict[str, Any]], *, from_ts: Optional[int], to_ts: Optional[int]) -> Dict[str, Any]:
        outp = dict(policy_in or {})
        if tf0 is None:
            return outp
        if from_ts is None or to_ts is None:
            return outp
        try:
            span_ms = max(0, int(to_ts) - int(from_ts))
            days = float(span_ms) / (24.0 * 3600.0 * 1000.0)
        except Exception:
            days = None
        if days is None or (not math.isfinite(float(days))) or float(days) <= 0.0:
            return outp
        try:
            thr0 = _bt_trade_thresholds(tf0, float(days), int(pair_n), family=fam0)
            mt = int(thr0.get("min_trades_required"))
            if mt > 0:
                outp["min_trades"] = int(mt)
        except Exception:
            pass
        return outp
    base_equity_u = None
    try:
        v = (sb or {}).get("starting_balance")
        base_equity_u = (None if v is None else float(v))
    except Exception:
        base_equity_u = None
    if base_equity_u is not None and ((not math.isfinite(float(base_equity_u))) or float(base_equity_u) <= 0.0):
        base_equity_u = None

    trades = _backtest_zip_strategy_trades(p, strategy=strategy) or []
    rng = random.Random(1 if seed is None else int(seed))

    rows: List[Dict[str, Any]] = []
    for t in trades:
        try:
            rr = _bt_trade_exec_row(t, cfg=cfg, assumptions=a, rng=rng)
        except Exception:
            rr = None
        if isinstance(rr, dict):
            rows.append(rr)

    ts_min = None
    ts_max = None
    for r in rows:
        try:
            ts = int(r.get("ts") or 0)
        except Exception:
            ts = 0
        if ts <= 0:
            continue
        ts_min = ts if ts_min is None else min(int(ts_min), int(ts))
        ts_max = ts if ts_max is None else max(int(ts_max), int(ts))

    base = _equity_metrics_from_exec_rows(rows, limit=0, base_equity_u=base_equity_u)
    base_eval = None
    try:
        base_eval = _eval_standard_pack(base, policy=_policy_scaled(policy, from_ts=(None if ts_min is None else int(ts_min)), to_ts=(None if ts_max is None else int(ts_max))))
    except Exception:
        base_eval = None

    slices: List[Dict[str, Any]] = []
    ns = max(1, min(24, int(n_slices or 0)))
    if ts_min is not None and ts_max is not None and int(ts_max) > int(ts_min) and rows:
        span = int(ts_max) - int(ts_min)
        step = max(1, int(span / ns))
        for i in range(ns):
            a0 = int(ts_min) + int(i) * int(step)
            b0 = (int(ts_min) + int(i + 1) * int(step)) if i < (ns - 1) else int(ts_max) + 1
            part = [r for r in rows if int(r.get("ts") or 0) >= a0 and int(r.get("ts") or 0) < b0]
            m = _equity_metrics_from_exec_rows(part, limit=0, base_equity_u=base_equity_u)
            slices.append({"i": int(i), "from_ts": int(a0), "to_ts": int(b0), "n": int(len(part)), "metrics": m})

    walk_forward = None
    if slices and len(slices) >= 2 and rows:
        folds: List[Dict[str, Any]] = []
        oos_scores_ok: List[float] = []
        oos_totals: List[float] = []
        oos_maxdds: List[float] = []
        oos_hard_fail_n = 0
        for i in range(1, len(slices)):
            try:
                test_from = int(slices[i].get("from_ts") or 0)
                test_to = int(slices[i].get("to_ts") or 0)
            except Exception:
                test_from, test_to = 0, 0
            if test_from <= 0 or test_to <= 0 or test_to <= test_from:
                continue

            train_from = int(slices[0].get("from_ts") or 0)
            train_to = int(test_from)
            train_rows = [r for r in rows if int(r.get("ts") or 0) >= train_from and int(r.get("ts") or 0) < train_to]
            test_rows = [r for r in rows if int(r.get("ts") or 0) >= test_from and int(r.get("ts") or 0) < test_to]
            train_m = _equity_metrics_from_exec_rows(train_rows, limit=0, base_equity_u=base_equity_u)
            test_m = _equity_metrics_from_exec_rows(test_rows, limit=0, base_equity_u=base_equity_u)
            try:
                train_ev = _eval_standard_pack(train_m, policy=_policy_scaled(policy, from_ts=int(train_from), to_ts=int(train_to)))
            except Exception:
                train_ev = None
            try:
                test_ev = _eval_standard_pack(test_m, policy=_policy_scaled(policy, from_ts=int(test_from), to_ts=int(test_to)))
            except Exception:
                test_ev = None
            folds.append(
                {
                    "i": int(i),
                    "train": {"from_ts": int(train_from), "to_ts": int(train_to), "n": int(len(train_rows)), "metrics": train_m, "eval": train_ev},
                    "test": {"from_ts": int(test_from), "to_ts": int(test_to), "n": int(len(test_rows)), "metrics": test_m, "eval": test_ev},
                }
            )

            try:
                v = None if test_ev is None else test_ev.get("score")
                if v is not None:
                    vv = float(v)
                    if math.isfinite(float(vv)) and vv > -1e17:
                        oos_scores_ok.append(float(vv))
            except Exception:
                pass
            try:
                v = float(test_m.get("total") or 0.0)
                if math.isfinite(float(v)):
                    oos_totals.append(float(v))
            except Exception:
                pass
            try:
                v = float(test_m.get("maxdd") or 0.0)
                if math.isfinite(float(v)):
                    oos_maxdds.append(float(v))
            except Exception:
                pass
            try:
                hf = [] if test_ev is None else (test_ev.get("hard_fails") or [])
                if isinstance(hf, list) and len(hf) > 0:
                    oos_hard_fail_n += 1
            except Exception:
                pass

        if folds:
            walk_forward = {
                "n_folds": int(len(folds)),
                "folds": folds,
                "summary": {
                    "oos_hard_fail_n": int(oos_hard_fail_n),
                    "oos_ok_rate": float((len(folds) - int(oos_hard_fail_n)) / float(len(folds))) if len(folds) > 0 else None,
                    "oos_score_ok": (_dist_summary(oos_scores_ok) if oos_scores_ok else None),
                    "oos_total": (_dist_summary(oos_totals) if oos_totals else None),
                    "oos_maxdd": (_dist_summary(oos_maxdds) if oos_maxdds else None),
                },
            }

    by_state: Dict[str, List[Dict[str, Any]]] = {}
    for r in rows:
        st = _bt_state_for_row(r, float(vol_ratio_thr), float(trend_dist_thr))
        by_state.setdefault(str(st), []).append(r)
    state_metrics: Dict[str, Any] = {}
    for st, rs in by_state.items():
        state_metrics[str(st)] = {
            "n": int(len(rs)),
            "metrics": _equity_metrics_from_exec_rows(rs, limit=0, base_equity_u=base_equity_u),
        }

    base_pnls: List[float] = []
    for r in rows:
        try:
            x = float(r.get("pnl_net_u") or 0.0)
        except Exception:
            x = 0.0
        if math.isfinite(float(x)) and float(x) != 0.0:
            base_pnls.append(float(x))

    boot_stats = None
    shuf_stats = None
    nb = max(0, min(5000, int(n_bootstrap or 0)))
    nj = max(0, min(5000, int(n_shuffle or 0)))

    if base_pnls and nb > 0:
        rng_b = random.Random(10_000 + (1 if seed is None else int(seed)))
        totals: List[float] = []
        maxdds: List[float] = []
        calmars: List[float] = []
        sharpes: List[float] = []
        sortinos: List[float] = []
        for _ in range(nb):
            draw = [float(base_pnls[rng_b.randrange(0, len(base_pnls))]) for _ in range(len(base_pnls))]
            m = _equity_metrics_from_pnls(draw, base_equity_u=base_equity_u)
            try:
                totals.append(float(m.get("total") or 0.0))
            except Exception:
                totals.append(0.0)
            try:
                maxdds.append(float(m.get("maxdd") or 0.0))
            except Exception:
                maxdds.append(0.0)
            for k, arr in (("calmar", calmars), ("sharpe", sharpes), ("sortino", sortinos)):
                try:
                    v = m.get(k)
                    arr.append(0.0 if v is None else float(v))
                except Exception:
                    arr.append(0.0)
        boot_stats = {
            "n": int(nb),
            "total": _dist_summary(totals),
            "maxdd": _dist_summary(maxdds),
            "calmar": _dist_summary(calmars),
            "sharpe": _dist_summary(sharpes),
            "sortino": _dist_summary(sortinos),
        }

    if base_pnls and nj > 0:
        rng_s = random.Random(20_000 + (1 if seed is None else int(seed)))
        totals: List[float] = []
        maxdds: List[float] = []
        calmars: List[float] = []
        sharpes: List[float] = []
        sortinos: List[float] = []
        for _ in range(nj):
            draw = list(base_pnls)
            rng_s.shuffle(draw)
            m = _equity_metrics_from_pnls(draw, base_equity_u=base_equity_u)
            try:
                totals.append(float(m.get("total") or 0.0))
            except Exception:
                totals.append(0.0)
            try:
                maxdds.append(float(m.get("maxdd") or 0.0))
            except Exception:
                maxdds.append(0.0)
            for k, arr in (("calmar", calmars), ("sharpe", sharpes), ("sortino", sortinos)):
                try:
                    v = m.get(k)
                    arr.append(0.0 if v is None else float(v))
                except Exception:
                    arr.append(0.0)
        shuf_stats = {
            "n": int(nj),
            "total": _dist_summary(totals),
            "maxdd": _dist_summary(maxdds),
            "calmar": _dist_summary(calmars),
            "sharpe": _dist_summary(sharpes),
            "sortino": _dist_summary(sortinos),
        }

    sens_cfg = sensitivity if isinstance(sensitivity, dict) else None
    if sens_cfg is None:
        try:
            fee0 = float(a.get("fee_rate") or 0.0)
        except Exception:
            fee0 = 0.0
        sens_cfg = {
            "x_key": "slippage_bps",
            "x_values": [0.0, 3.0, 6.0, 10.0],
            "y_key": "fee_rate",
            "y_values": [float(fee0), float(fee0) * 2.0, float(fee0) * 4.0],
            "metric": "score",
        }

    sens_out = None
    try:
        x_key = str(sens_cfg.get("x_key") or "slippage_bps")
        y_key = str(sens_cfg.get("y_key") or "fee_rate")
        metric = str(sens_cfg.get("metric") or "score")
        x_vals = sens_cfg.get("x_values")
        y_vals = sens_cfg.get("y_values")
        if not isinstance(x_vals, list):
            x_vals = [0.0, 3.0, 6.0, 10.0]
        if not isinstance(y_vals, list):
            y_vals = [float(a.get("fee_rate") or 0.0), float(a.get("fee_rate") or 0.0) * 2.0, float(a.get("fee_rate") or 0.0) * 4.0]
        x_vals_f: List[float] = []
        y_vals_f: List[float] = []
        for v in x_vals:
            try:
                x = float(v)
                if math.isfinite(x):
                    x_vals_f.append(float(x))
            except Exception:
                continue
        for v in y_vals:
            try:
                y = float(v)
                if math.isfinite(y):
                    y_vals_f.append(float(y))
            except Exception:
                continue
        x_vals_f = x_vals_f[:30]
        y_vals_f = y_vals_f[:30]

        def _metric_from(m: Dict[str, Any]) -> Optional[float]:
            if metric in ("score", "eval.score"):
                try:
                    ev = _eval_standard_pack(m)
                    v = ev.get("score")
                    return None if v is None else float(v)
                except Exception:
                    return None
            try:
                v = m.get(metric)
                return None if v is None else float(v)
            except Exception:
                return None

        def _sim_metrics(a_over: Dict[str, Any], seed1: int) -> Dict[str, Any]:
            rng1 = random.Random(int(seed1))
            rs: List[Dict[str, Any]] = []
            for t in trades:
                try:
                    rr = _bt_trade_exec_row(t, cfg=cfg, assumptions=a_over, rng=rng1)
                except Exception:
                    rr = None
                if isinstance(rr, dict):
                    rs.append(rr)
            return _equity_metrics_from_exec_rows(rs, limit=0, base_equity_u=base_equity_u)

        grid: List[List[Optional[float]]] = []
        seed0 = 30_000 + (1 if seed is None else int(seed))
        for j, y in enumerate(y_vals_f):
            row: List[Optional[float]] = []
            for i, x in enumerate(x_vals_f):
                a2 = dict(a)
                a2[str(x_key)] = float(x)
                a2[str(y_key)] = float(y)
                m2 = _sim_metrics(a2, seed1=(seed0 + 997 * int(i) + 131 * int(j)))
                v2 = _metric_from(m2)
                if v2 is not None and (not math.isfinite(float(v2))):
                    v2 = None
                row.append(v2)
            grid.append(row)

        sens_out = {
            "x": {"key": str(x_key), "values": [float(x) for x in x_vals_f]},
            "y": {"key": str(y_key), "values": [float(y) for y in y_vals_f]},
            "metric": str(metric),
            "grid": grid,
        }
    except Exception:
        sens_out = None

    return {
        "ok": True,
        "ts": _now_ms(),
        "zip": str(p.name),
        "strategy": (None if strategy is None else str(strategy)),
        "assumptions": a,
        "base_equity_u": base.get("base_equity_u"),
        "base": base,
        "eval": base_eval,
        "time_slices": slices,
        "walk_forward": walk_forward,
        "market_state_slices": state_metrics,
        "bootstrap": boot_stats,
        "shuffle": shuf_stats,
        "sensitivity": sens_out,
    }


def _eval_standard_pack(metrics: Dict[str, Any], policy: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    p = policy or {}

    def _f(v: Any) -> Optional[float]:
        try:
            x = float(v)
            return x if math.isfinite(x) else None
        except Exception:
            return None

    def _i(v: Any) -> Optional[int]:
        try:
            x = int(v)
            return x
        except Exception:
            return None

    trades = _i(metrics.get("trades")) or 0
    winrate = _f(metrics.get("winrate"))
    calmar = _f(metrics.get("calmar"))
    sharpe = _f(metrics.get("sharpe"))
    maxdd_pct = _f(metrics.get("maxdd_pct"))
    total_pct = _f(metrics.get("total_pct"))
    max_daily_loss_pct = _f(metrics.get("max_daily_loss_pct"))
    max_weekly_loss_pct = _f(metrics.get("max_weekly_loss_pct"))
    dd_rec_ms = _i(metrics.get("dd_recovery_ms_max"))

    min_trades = int(p.get("min_trades", 80) or 80)
    max_dd_pct = _f(p.get("max_drawdown_pct", 0.25))
    min_weekly_winrate = _f(p.get("min_weekly_winrate", 0.45))
    max_daily_loss_lim = _f(p.get("max_daily_loss_pct"))
    max_weekly_loss_lim = _f(p.get("max_weekly_loss_pct"))

    weekly = metrics.get("weekly_pnl_u") if isinstance(metrics, dict) else None
    wk_winrate = None
    if isinstance(weekly, dict) and weekly:
        pos = 0
        tot = 0
        for v in weekly.values():
            vv = _f(v)
            if vv is None:
                continue
            tot += 1
            if vv > 0:
                pos += 1
        wk_winrate = (float(pos) / float(tot)) if tot > 0 else None

    hard_fails: List[str] = []
    if trades < int(min_trades):
        hard_fails.append(f"min_trades<{min_trades}")
    if max_dd_pct is not None and maxdd_pct is not None and float(maxdd_pct) > float(max_dd_pct):
        hard_fails.append(f"maxdd_pct>{max_dd_pct}")
    if min_weekly_winrate is not None and wk_winrate is not None and float(wk_winrate) < float(min_weekly_winrate):
        hard_fails.append(f"weekly_winrate<{min_weekly_winrate}")
    if max_daily_loss_lim is not None and max_daily_loss_pct is not None and float(max_daily_loss_pct) < -abs(float(max_daily_loss_lim)):
        hard_fails.append("max_daily_loss_exceed")
    if max_weekly_loss_lim is not None and max_weekly_loss_pct is not None and float(max_weekly_loss_pct) < -abs(float(max_weekly_loss_lim)):
        hard_fails.append("max_weekly_loss_exceed")

    def _clip(x: Optional[float], lo: float, hi: float) -> float:
        if x is None:
            return 0.0
        return float(max(lo, min(hi, float(x))))

    score = 0.0
    score += 0.40 * _clip(calmar, -5.0, 5.0)
    score += 0.30 * _clip(sharpe, -5.0, 5.0)
    score += 0.15 * _clip(total_pct, -5.0, 5.0)
    score += 0.10 * _clip((None if winrate is None else (2.0 * float(winrate) - 1.0)), -1.0, 1.0)
    score -= 0.05 * _clip((None if dd_rec_ms is None else float(dd_rec_ms) / (7.0 * 24.0 * 3600.0 * 1000.0)), 0.0, 5.0)
    if hard_fails:
        score = -1e18

    return {
        "ok": True,
        "policy": {
            "min_trades": int(min_trades),
            "max_drawdown_pct": max_dd_pct,
            "min_weekly_winrate": min_weekly_winrate,
            "max_daily_loss_pct": max_daily_loss_lim,
            "max_weekly_loss_pct": max_weekly_loss_lim,
        },
        "metrics": {
            "trades": int(trades),
            "winrate": winrate,
            "weekly_winrate": wk_winrate,
            "calmar": calmar,
            "sharpe": sharpe,
            "total_pct": total_pct,
            "maxdd_pct": maxdd_pct,
            "dd_recovery_ms_max": (None if dd_rec_ms is None else int(dd_rec_ms)),
            "max_daily_loss_pct": max_daily_loss_pct,
            "max_weekly_loss_pct": max_weekly_loss_pct,
        },
        "hard_fails": hard_fails,
        "score": float(score),
        "objective": "maximize score (calmar/sharpe/return) with hard risk constraints",
    }


def _bt_metrics_pick_strategy(metrics: Any, strategy: Optional[str]) -> Optional[Dict[str, Any]]:
    if not isinstance(metrics, dict):
        return None
    rows = metrics.get("strategies")
    if not isinstance(rows, list) or not rows:
        return None
    if strategy:
        for r in rows:
            if not isinstance(r, dict):
                continue
            if str(r.get("key") or "") == str(strategy):
                return dict(r)
    for r in rows:
        if isinstance(r, dict):
            return dict(r)
    return None


def _bt_metrics_slim(row: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(row, dict):
        return None
    out: Dict[str, Any] = {}
    for k in (
        "key",
        "trades",
        "wins",
        "losses",
        "draws",
        "winrate",
        "rejected_signals",
        "timedout_entry_orders",
        "timedout_exit_orders",
        "canceled_entry_orders",
        "replaced_entry_orders",
        "profit_total_pct",
        "profit_total_abs",
        "profit_factor",
        "sharpe",
        "sortino",
        "calmar",
        "sqn",
        "cagr",
        "max_drawdown_account",
        "max_drawdown_abs",
        "backtest_start_ts",
        "backtest_end_ts",
        "backtest_days",
        "timeframe",
        "timeframe_detail",
        "timerange",
    ):
        if k in row and row.get(k) is not None:
            out[k] = row.get(k)

    try:
        total_trades = int(out.get("trades") or 0)
    except Exception:
        total_trades = 0
    denom = max(1, int(total_trades))

    sl_trades = 0
    ers = row.get("exit_reason_summary") if isinstance(row.get("exit_reason_summary"), list) else []
    if ers:
        for it in ers[:200]:
            if not isinstance(it, dict):
                continue
            key = str(it.get("key") or "").strip().lower()
            if not key:
                continue
            is_sl = ("stoploss" in key) or ("stop_loss" in key) or ("l0_stop_loss" in key) or (key == "stop")
            if not is_sl:
                continue
            try:
                sl_trades += int(it.get("trades") or 0)
            except Exception:
                continue
    if sl_trades > 0:
        out["stoploss_trades"] = int(sl_trades)
        out["stoploss_hit_rate"] = float(sl_trades) / float(denom)

    try:
        to_entry = int(out.get("timedout_entry_orders") or 0)
    except Exception:
        to_entry = 0
    try:
        to_exit = int(out.get("timedout_exit_orders") or 0)
    except Exception:
        to_exit = 0
    try:
        canceled = int(out.get("canceled_entry_orders") or 0)
    except Exception:
        canceled = 0
    try:
        replaced = int(out.get("replaced_entry_orders") or 0)
    except Exception:
        replaced = 0
    issue_total = int(to_entry) + int(to_exit) + int(canceled) + int(replaced)
    if issue_total > 0:
        out["exec_risk_trigger_count"] = int(issue_total)
        out["exec_risk_trigger_rate"] = float(issue_total) / float(denom)
    fat = int(canceled) + int(replaced)
    if fat > 0:
        out["fat_finger_count"] = int(fat)
        out["fat_finger_rate"] = float(fat) / float(denom)
    return out


def _bt_summaries_aggregate(summaries: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(summaries, list) or not summaries:
        return None
    rows = [s for s in summaries if isinstance(s, dict)]
    if not rows:
        return None
    trades_total = 0
    wins_total = 0
    losses_total = 0
    draws_total = 0
    ok_n = 0
    profit_total_pct_sum = 0.0
    profit_total_abs_sum = 0.0
    profit_factor_vals: List[float] = []
    sharpe_vals: List[float] = []
    sortino_vals: List[float] = []
    calmar_vals: List[float] = []
    sqn_vals: List[float] = []
    cagr_vals: List[float] = []
    max_dd_account = None
    max_dd_abs = None

    for r in rows:
        ok_n += 1
        try:
            trades_total += int(r.get("trades") or 0)
        except Exception:
            pass
        try:
            wins_total += int(r.get("wins") or 0)
        except Exception:
            pass
        try:
            losses_total += int(r.get("losses") or 0)
        except Exception:
            pass
        try:
            draws_total += int(r.get("draws") or 0)
        except Exception:
            pass
        try:
            profit_total_pct_sum += float(r.get("profit_total_pct") or 0.0)
        except Exception:
            pass
        try:
            profit_total_abs_sum += float(r.get("profit_total_abs") or 0.0)
        except Exception:
            pass
        for k, arr in (
            ("profit_factor", profit_factor_vals),
            ("sharpe", sharpe_vals),
            ("sortino", sortino_vals),
            ("calmar", calmar_vals),
            ("sqn", sqn_vals),
            ("cagr", cagr_vals),
        ):
            try:
                v = r.get(k)
                if v is not None:
                    arr.append(float(v))
            except Exception:
                pass
        try:
            v = r.get("max_drawdown_account")
            if v is not None:
                v0 = float(v)
                if max_dd_account is None or float(v0) > float(max_dd_account):
                    max_dd_account = float(v0)
        except Exception:
            pass
        try:
            v = r.get("max_drawdown_abs")
            if v is not None:
                v0 = float(v)
                if max_dd_abs is None or float(v0) > float(max_dd_abs):
                    max_dd_abs = float(v0)
        except Exception:
            pass

    winrate = None
    try:
        denom = int(trades_total)
        if denom <= 0:
            denom = int(wins_total) + int(losses_total) + int(draws_total)
        denom = max(1, int(denom))
        winrate = float(wins_total) / float(denom)
    except Exception:
        winrate = None

    def _mean(xs: List[float]) -> Optional[float]:
        if not xs:
            return None
        try:
            return float(sum(xs)) / float(len(xs))
        except Exception:
            return None

    out: Dict[str, Any] = {
        "n": int(ok_n),
        "trades": int(trades_total),
        "wins": int(wins_total),
        "losses": int(losses_total),
        "draws": int(draws_total),
        "winrate": winrate,
        "profit_total_pct_sum": float(profit_total_pct_sum),
        "profit_total_abs_sum": float(profit_total_abs_sum),
        "profit_factor_mean": _mean(profit_factor_vals),
        "sharpe_mean": _mean(sharpe_vals),
        "sortino_mean": _mean(sortino_vals),
        "calmar_mean": _mean(calmar_vals),
        "sqn_mean": _mean(sqn_vals),
        "cagr_mean": _mean(cagr_vals),
    }
    if max_dd_account is not None:
        out["max_drawdown_account_max"] = float(max_dd_account)
    if max_dd_abs is not None:
        out["max_drawdown_abs_max"] = float(max_dd_abs)
    return out

def _freqtrade_available() -> bool:
    return bool(_freqtrade_bin() or _freqtrade_python())


_FREQTRADE_BIN_CACHE: Optional[str] = None
_FREQTRADE_PY_CACHE: Optional[str] = None
_FREQTRADE_PY_PROBE_CACHE: Dict[str, bool] = {}


def _resolve_exec_path(p: str) -> Optional[str]:
    s = str(p or "").strip()
    if not s:
        return None
    pp = Path(s).expanduser()
    if not pp.is_absolute():
        try:
            pp = (Path(__file__).resolve().parent / pp).resolve()
        except Exception:
            pp = Path(__file__).resolve().parent / pp
    try:
        if pp.exists() and pp.is_file():
            return str(pp)
    except Exception:
        return None
    return None


def _freqtrade_bin() -> Optional[str]:
    global _FREQTRADE_BIN_CACHE
    try:
        if _FREQTRADE_BIN_CACHE:
            return _FREQTRADE_BIN_CACHE
    except Exception:
        pass
    candidates: List[str] = []
    for k in ("FREQTRADE_BIN", "FT_FREQTRADE_BIN", "FT_BIN"):
        try:
            v = str(os.environ.get(k) or "").strip()
        except Exception:
            v = ""
        if v:
            candidates.append(v)
    try:
        w = shutil.which("freqtrade")
        if w:
            candidates.append(w)
    except Exception:
        pass
    candidates.extend([
        "/opt/anaconda3/bin/freqtrade",
        "/opt/homebrew/bin/freqtrade",
        "/usr/local/bin/freqtrade",
    ])
    for c in candidates:
        p = _resolve_exec_path(c)
        if not p:
            continue
        try:
            _FREQTRADE_BIN_CACHE = p
        except Exception:
            pass
        return p
    return None


def _python_can_import_freqtrade(py: str) -> bool:
    key = str(py or "").strip()
    if not key:
        return False
    try:
        if key in _FREQTRADE_PY_PROBE_CACHE:
            return bool(_FREQTRADE_PY_PROBE_CACHE[key])
    except Exception:
        pass
    try:
        r = subprocess.run(
            [key, "-c", "import importlib.util, sys; sys.exit(0 if importlib.util.find_spec('freqtrade') else 2)"],
            capture_output=True,
            text=True,
            timeout=5.0,
            env=_sandbox_env_base(os.environ.copy()),
        )
        ok = (int(r.returncode) == 0)
    except Exception:
        ok = False
    try:
        _FREQTRADE_PY_PROBE_CACHE[key] = bool(ok)
    except Exception:
        pass
    return bool(ok)


def _freqtrade_python() -> Optional[str]:
    global _FREQTRADE_PY_CACHE
    try:
        if _FREQTRADE_PY_CACHE:
            return _FREQTRADE_PY_CACHE
    except Exception:
        pass
    candidates: List[str] = []
    for k in ("FREQTRADE_PYTHON", "FT_PYTHON", "SANDBOX_PYTHON"):
        try:
            v = str(os.environ.get(k) or "").strip()
        except Exception:
            v = ""
        if v:
            candidates.append(v)
    try:
        candidates.append(str(sys.executable))
    except Exception:
        pass
    try:
        w = shutil.which("python")
        if w:
            candidates.append(w)
    except Exception:
        pass
    try:
        w3 = shutil.which("python3")
        if w3:
            candidates.append(w3)
    except Exception:
        pass
    candidates.extend([
        "/opt/anaconda3/bin/python",
        "/opt/homebrew/bin/python3",
        "/usr/local/bin/python3",
        "/usr/bin/python3",
    ])
    for c in candidates:
        p = _resolve_exec_path(c)
        if not p:
            continue
        if _python_can_import_freqtrade(p):
            try:
                _FREQTRADE_PY_CACHE = p
            except Exception:
                pass
            return p
    return None

def _env_key_sensitive(k: str) -> bool:
    ku = str(k or "").strip().upper()
    if not ku:
        return False
    if ku in {
        "CONFIG_TOKEN",
        "MAINTENANCE_TOKEN",
        "HTTP_PROXY",
        "HTTPS_PROXY",
        "ALL_PROXY",
        "NO_PROXY",
    }:
        return True
    if any(x in ku for x in [
        "TOKEN",
        "SECRET",
        "PASSWORD",
        "PASSPHRASE",
        "APIKEY",
        "API_KEY",
        "ACCESS_KEY",
        "PRIVATE_KEY",
        "BEARER",
        "OAUTH",
        "WEBHOOK",
        "TELEGRAM",
        "TWITTER",
    ]):
        return True
    if any(ku.startswith(p) for p in [
        "BINANCE",
        "BYBIT",
        "OKX",
        "KUCOIN",
        "KRAKEN",
        "BITGET",
        "GATEIO",
        "COINBASE",
        "HUOBI",
        "MEXC",
    ]):
        return True
    return False


def _sandbox_env_base(env: Dict[str, str]) -> Dict[str, str]:
    out = dict(env or {})
    for k in list(out.keys()):
        if _env_key_sensitive(k):
            out.pop(k, None)
    return out


_BACKTEST_DATA_READY: Dict[str, int] = {}
_BACKTEST_DATA_LOCK = threading.Lock()
_SANDBOX_STATE_LOCK = threading.Lock()


def _sandbox_policy_get() -> Dict[str, Any]:
    pol = CONFIG.get("sandbox_policy")
    return pol if isinstance(pol, dict) else {}


def _sandbox_state_inc_running(*, kind: str) -> Tuple[bool, Dict[str, Any]]:
    pol = _sandbox_policy_get()
    try:
        lim = int(pol.get("concurrent_limit") or 8)
    except Exception:
        lim = 2
    lim = max(1, min(32, int(lim)))
    now_ms = int(_now_ms())
    with _SANDBOX_STATE_LOCK:
        st = CONFIG.get("sandbox_state")
        if not isinstance(st, dict):
            st = {"running": 0, "queued": 0}
        try:
            last_start = int(st.get(f"last_{str(kind or 'task').strip()}_start_ms") or 0)
        except Exception:
            last_start = 0
        if int(st.get("running") or 0) > 0 and last_start > 0:
            ttl_ms = 0
            try:
                ttl_ms = int((float(pol.get("timeout_sec") or 1800.0) + 120.0) * 1000.0)
            except Exception:
                ttl_ms = int((1800.0 + 120.0) * 1000.0)
            ttl_ms = int(max(60_000, min(24 * 3600 * 1000, ttl_ms)))
            if (now_ms - last_start) > ttl_ms:
                st["running"] = 0
        if int(st.get("running") or 0) >= int(lim):
            return False, {"ok": False, "error": "sandbox_concurrency_limit", "limit": int(lim), "state": dict(st), "ts": now_ms}
        st["running"] = int(st.get("running") or 0) + 1
        st[f"last_{str(kind or 'task').strip()}_start_ms"] = now_ms
        CONFIG["sandbox_state"] = st
    return True, {"ok": True, "limit": int(lim), "ts": now_ms}


def _sandbox_state_dec_running(*, kind: str) -> None:
    now_ms = int(_now_ms())
    with _SANDBOX_STATE_LOCK:
        st = CONFIG.get("sandbox_state")
        if not isinstance(st, dict):
            st = {"running": 0, "queued": 0}
        st["running"] = max(0, int(st.get("running") or 0) - 1)
        st[f"last_{str(kind or 'task').strip()}_end_ms"] = now_ms
        CONFIG["sandbox_state"] = st


def _sandbox_preexec_make(*, pol: Dict[str, Any], timeout_sec: float) -> Any:
    try:
        t = float(timeout_sec or 0.0)
    except Exception:
        t = 0.0
    try:
        pol_timeout = pol.get("timeout_sec")
        if pol_timeout is not None:
            t = min(float(t or 0.0), float(pol_timeout))
    except Exception:
        pass
    t = float(max(1.0, t))

    mem_bytes = None
    try:
        mg = pol.get("mem_gb")
        if mg is not None:
            mem_bytes = int(float(mg) * 1024.0 * 1024.0 * 1024.0)
    except Exception:
        mem_bytes = None
    if mem_bytes is not None:
        mem_bytes = int(max(256 * 1024 * 1024, min(256 * 1024 * 1024 * 1024, int(mem_bytes))))

    try:
        nofile = int(pol.get("max_nofile") or 1024)
    except Exception:
        nofile = 1024
    nofile = int(max(64, min(8192, int(nofile))))

    try:
        nproc = int(pol.get("max_nproc") or 128)
    except Exception:
        nproc = 128
    nproc = int(max(16, min(4096, int(nproc))))

    try:
        fsize_mb = int(pol.get("max_fsize_mb") or 4096)
    except Exception:
        fsize_mb = 4096
    fsize_mb = int(max(16, min(65536, int(fsize_mb))))
    fsize_bytes = int(fsize_mb) * 1024 * 1024

    cpu_soft = int(max(2, min(24 * 3600, int(math.ceil(t)) + 20)))
    cpu_hard = int(max(cpu_soft, min(24 * 3600, cpu_soft + 20)))

    def _fn() -> None:
        try:
            os.nice(10)
        except Exception:
            pass
        try:
            resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
        except Exception:
            pass
        try:
            resource.setrlimit(resource.RLIMIT_CPU, (int(cpu_soft), int(cpu_hard)))
        except Exception:
            pass
        try:
            resource.setrlimit(resource.RLIMIT_FSIZE, (int(fsize_bytes), int(fsize_bytes)))
        except Exception:
            pass
        try:
            resource.setrlimit(resource.RLIMIT_NOFILE, (int(nofile), int(nofile)))
        except Exception:
            pass
        try:
            if hasattr(resource, "RLIMIT_NPROC"):
                resource.setrlimit(getattr(resource, "RLIMIT_NPROC"), (int(nproc), int(nproc)))
        except Exception:
            pass
        if mem_bytes is not None:
            try:
                if hasattr(resource, "RLIMIT_AS"):
                    resource.setrlimit(getattr(resource, "RLIMIT_AS"), (int(mem_bytes), int(mem_bytes)))
            except Exception:
                pass
            try:
                if hasattr(resource, "RLIMIT_DATA"):
                    resource.setrlimit(getattr(resource, "RLIMIT_DATA"), (int(mem_bytes), int(mem_bytes)))
            except Exception:
                pass
            try:
                if hasattr(resource, "RLIMIT_RSS"):
                    resource.setrlimit(getattr(resource, "RLIMIT_RSS"), (int(mem_bytes), int(mem_bytes)))
            except Exception:
                pass

    return _fn

def _run_backtest(
    config_path: str = "user_data/config_local_backtest.json",
    timerange: str = None,
    strategy: str = None,
    strategy_path: Optional[str] = None,
    env_overrides: Optional[Dict[str, Any]] = None,
    timeout_sec: float = 1800,
    import_samples: bool = True,
) -> Dict[str, Any]:
    if not _freqtrade_available():
        return {"ok": False, "error": "freqtrade_not_available"}

    env_overrides2: Dict[str, Any] = {}
    try:
        if isinstance(env_overrides, dict):
            env_overrides2 = dict(env_overrides)
    except Exception:
        env_overrides2 = {}

    try:
        if "FT_STRATEGY_PARAMS_JSON" not in env_overrides2:
            s005: Dict[str, Any] = {}
            try:
                cfg_items = (CONFIG or {}).items() if isinstance(CONFIG, dict) else []
            except Exception:
                cfg_items = []
            for k, v in cfg_items:
                kk = str(k)
                if not kk.startswith("s005_"):
                    continue
                name = kk[len("s005_"):].strip()
                if not name:
                    continue
                s005[name] = v
            if s005:
                st = str(strategy or "").strip()
                if (not st) or (st == "Strategy005"):
                    env_overrides2["FT_STRATEGY_PARAMS_JSON"] = json.dumps({"Strategy005": s005}, ensure_ascii=False, sort_keys=True)
    except Exception:
        pass

    env_overrides = env_overrides2

    pol = _sandbox_policy_get()
    try:
        p = Path(str(config_path)).expanduser()
        try:
            p = p.resolve()
        except Exception:
            p = p
        if p.exists() and p.is_file() and p.name.lower().endswith(".json"):
            try:
                cfg_bt = json.loads(p.read_text(encoding="utf-8"))
            except Exception:
                cfg_bt = None
            if isinstance(cfg_bt, dict):
                pol_bt = cfg_bt.get("sandbox_policy")
                if isinstance(pol_bt, dict) and pol_bt:
                    merged = dict(pol) if isinstance(pol, dict) else {}
                    for k, v in pol_bt.items():
                        merged[str(k)] = v
                    pol = merged
    except Exception:
        pass
    deny_network = True
    try:
        if pol.get("deny_network") is not None:
            deny_network = bool(pol.get("deny_network"))
    except Exception:
        deny_network = True

    allow_hosts_extra: List[str] = []
    try:
        ah = pol.get("allow_hosts")
        if isinstance(ah, list):
            for it in ah[:100]:
                s = str(it or "").strip().lower()
                if not s:
                    continue
                if len(s) > 253:
                    continue
                bad = False
                for ch in s:
                    if not (ch.isalnum() or ch in ".-:"):
                        bad = True
                        break
                if bad:
                    continue
                if s.startswith(".") or s.endswith("."):
                    continue
                allow_hosts_extra.append(s)
    except Exception:
        allow_hosts_extra = []

    allow_hosts = ["127.0.0.1", "::1", "localhost"]
    for h in allow_hosts_extra:
        if h not in allow_hosts:
            allow_hosts.append(h)
    allow_hosts_literal = "{" + ", ".join([repr(x) for x in allow_hosts]) + "}"

    auto_download = True
    try:
        auto_download = bool(CONFIG.get("backtest_auto_download_data", True))
    except Exception:
        auto_download = True
    if bool(deny_network) and not (isinstance(pol, dict) and ("auto_download_data" in pol)):
        auto_download = False
    if isinstance(pol, dict) and pol.get("auto_download_data") is not None:
        try:
            auto_download = bool(pol.get("auto_download_data"))
        except Exception:
            pass

    try:
        pol_timeout = pol.get("timeout_sec")
        if pol_timeout is not None:
            timeout_sec = min(float(timeout_sec or 1800), float(pol_timeout))
    except Exception:
        pass

    def _timerange_shift_days(tr: str, days: int) -> Optional[str]:
        s = str(tr or "").strip()
        if not s or "-" not in s:
            return None
        a, b = s.split("-", 1)
        a = a.strip()
        b = b.strip()
        if len(a) < 8 or len(b) < 8:
            return None
        try:
            start = datetime.strptime(a[:8], "%Y%m%d")
            end = datetime.strptime(b[:8], "%Y%m%d")
        except Exception:
            return None
        try:
            start2 = start - timedelta(days=int(days))
        except Exception:
            start2 = start
        return start2.strftime("%Y%m%d") + "-" + end.strftime("%Y%m%d")

    def _tf_to_ms(tf: str) -> Optional[int]:
        s = str(tf or "").strip().lower()
        if not s:
            return None
        unit = s[-1]
        num_s = s[:-1].strip()
        try:
            n = int(num_s)
        except Exception:
            return None
        if n <= 0:
            return None
        if unit == "m":
            return int(n) * 60 * 1000
        if unit == "h":
            return int(n) * 60 * 60 * 1000
        if unit == "d":
            return int(n) * 24 * 60 * 60 * 1000
        return None

    def _pair_to_filename(pair: str, tf: str, mode: str) -> str:
        p = str(pair or "").strip()
        t = str(tf or "").strip()
        m = str(mode or "").strip().lower() or "futures"
        stem = p.replace("/", "_").replace(":", "_")
        if m in ("futures", "swap"):
            return f"{stem}-{t}-futures.json"
        if m in ("spot",):
            return f"{stem}-{t}.json"
        return f"{stem}-{t}-{m}.json"

    def _datadir_from_cfg(cfg: Dict[str, Any]) -> Path:
        raw = str(cfg.get("datadir") or "user_data/data").strip() or "user_data/data"
        if raw.startswith("/"):
            try:
                return Path(raw)
            except Exception:
                return _user_data_dir() / "data"
        s = raw.replace("\\", "/").lstrip("./")
        if s.startswith("user_data/"):
            s = s[len("user_data/"):]
        if not s:
            s = "data"
        return _user_data_dir() / s

    def _bt_ohlcv_path(cfg: Dict[str, Any], *, exchange: str, trading_mode: str, pair: str, tf: str) -> Path:
        dd = _datadir_from_cfg(cfg)
        ex = str(exchange or "").strip().lower() or "gate"
        tm = str(trading_mode or "").strip().lower() or "futures"
        fn = _pair_to_filename(pair, tf, tm)
        return dd / ex / tm / fn

    def _ohlcv_first_last_ts_ms(path: Path) -> Optional[Tuple[int, int]]:
        if not path.exists() or (not path.is_file()):
            return None
        try:
            with open(path, "r", encoding="utf-8") as f:
                raw = json.load(f)
        except Exception:
            return None
        if not isinstance(raw, list) or (not raw):
            return None
        first = raw[0] if isinstance(raw[0], list) and len(raw[0]) >= 1 else None
        last = raw[-1] if isinstance(raw[-1], list) and len(raw[-1]) >= 1 else None
        if first is None or last is None:
            return None
        try:
            a = int(float(first[0]))
            b = int(float(last[0]))
        except Exception:
            return None
        return (a, b) if a <= b else (b, a)

    def _ensure_timeframe_from_source(cfg: Dict[str, Any], *, exchange: str, trading_mode: str, pair: str, src_tf: str, dst_tf: str) -> Dict[str, Any]:
        src = str(src_tf or "").strip()
        dst = str(dst_tf or "").strip()
        if not src or not dst or src == dst:
            return {"ok": True, "skipped": True, "pair": str(pair), "exchange": str(exchange), "trading_mode": str(trading_mode), "src_tf": src, "dst_tf": dst}
        src_ms = _tf_to_ms(src)
        dst_ms = _tf_to_ms(dst)
        if (src_ms is None) or (dst_ms is None) or (dst_ms <= src_ms) or (dst_ms % src_ms != 0):
            return {"ok": False, "error": "bad_timeframes", "pair": str(pair), "src_tf": src, "dst_tf": dst}
        p_src = _bt_ohlcv_path(cfg, exchange=exchange, trading_mode=trading_mode, pair=pair, tf=src)
        p_dst = _bt_ohlcv_path(cfg, exchange=exchange, trading_mode=trading_mode, pair=pair, tf=dst)
        if p_dst.exists() and p_dst.is_file():
            return {"ok": True, "exists": True, "pair": str(pair), "dst_path": str(p_dst)}
        if not (p_src.exists() and p_src.is_file()):
            return {"ok": False, "error": "source_data_missing", "pair": str(pair), "src_path": str(p_src), "dst_path": str(p_dst)}
        try:
            with open(p_src, "r", encoding="utf-8") as f:
                raw = json.load(f)
        except Exception as e:
            return {"ok": False, "error": "source_data_read_failed", "pair": str(pair), "src_path": str(p_src), "dst_path": str(p_dst), "detail": str(e)}
        rows: List[List[float]] = []
        for r in raw:
            if not isinstance(r, list) or len(r) < 6:
                continue
            try:
                rows.append([float(r[0]), float(r[1]), float(r[2]), float(r[3]), float(r[4]), float(r[5])])
            except Exception:
                continue
        if not rows:
            return {"ok": False, "error": "source_data_empty", "pair": str(pair), "src_path": str(p_src), "dst_path": str(p_dst)}
        try:
            bucket_ms = int(dst_ms)
            out_rows = _resample(rows, int(bucket_ms))
        except Exception as e:
            return {"ok": False, "error": "resample_failed", "pair": str(pair), "detail": str(e)}
        try:
            p_dst.parent.mkdir(parents=True, exist_ok=True)
            with open(p_dst, "w", encoding="utf-8") as f:
                json.dump([[float(x[0]), float(x[1]), float(x[2]), float(x[3]), float(x[4]), float(x[5])] for x in out_rows], f, ensure_ascii=False)
        except Exception as e:
            return {"ok": False, "error": "write_failed", "pair": str(pair), "dst_path": str(p_dst), "detail": str(e)}
        return {"ok": True, "generated": True, "pair": str(pair), "src_path": str(p_src), "dst_path": str(p_dst), "src_tf": src, "dst_tf": dst, "rows": int(len(out_rows))}

    def _timerange_intersect(
        want: Optional[str],
        have_ms: Optional[Tuple[int, int]],
        *,
        fallback_days: int = 30,
        anchor_ms: Optional[int] = None,
    ) -> Optional[str]:
        if not have_ms:
            return want
        have_a, have_b = int(have_ms[0]), int(have_ms[1])
        if have_a <= 0 or have_b <= 0 or have_a >= have_b:
            return want
        w = str(want or "").strip()
        if "-" in w and len(w) >= 17:
            a0, b0 = w.split("-", 1)
            a0 = a0.strip()
            b0 = b0.strip()
            try:
                wa = int(datetime.strptime(a0[:8], "%Y%m%d").replace(tzinfo=timezone.utc).timestamp() * 1000)
                wb = int(datetime.strptime(b0[:8], "%Y%m%d").replace(tzinfo=timezone.utc).timestamp() * 1000)
            except Exception:
                wa = None
                wb = None
            if wa is not None and wb is not None:
                sa = max(int(have_a), int(wa))
                sb = min(int(have_b), int(wb))
                if sa < sb:
                    return datetime.fromtimestamp(sa / 1000.0, tz=timezone.utc).strftime("%Y%m%d") + "-" + datetime.fromtimestamp(sb / 1000.0, tz=timezone.utc).strftime("%Y%m%d")
        anc = int(anchor_ms) if anchor_ms is not None else int(have_b)
        try:
            sa = max(int(have_a), int(anc) - int(fallback_days) * 86400 * 1000)
        except Exception:
            sa = int(have_a)
        sb = min(int(have_b), int(anc))
        if sa >= sb:
            sa = int(have_a)
            sb = int(have_b)
        return datetime.fromtimestamp(sa / 1000.0, tz=timezone.utc).strftime("%Y%m%d") + "-" + datetime.fromtimestamp(sb / 1000.0, tz=timezone.utc).strftime("%Y%m%d")

    def _materialize_bt_config(base_cfg_path: str, *, trace_id: str, updates: Dict[str, Any]) -> Optional[str]:
        p = Path(str(base_cfg_path)).expanduser()
        try:
            p = p.resolve()
        except Exception:
            p = p
        if not (p.exists() and p.is_file()):
            return None
        try:
            base_cfg = json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            return None
        if not isinstance(base_cfg, dict):
            return None
        cfg2 = dict(base_cfg)
        for k, v in (updates or {}).items():
            cfg2[str(k)] = v
        try:
            tid = str(trace_id or "").strip() or uuid.uuid4().hex
        except Exception:
            tid = uuid.uuid4().hex
        out_dir = _user_data_dir() / "backtest_configs"
        try:
            out_dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        out_fp = out_dir / (f"auto_{tid}.json".replace("/", "_").replace("\\", "_").replace("..", "_"))
        try:
            out_fp.write_text(json.dumps(cfg2, ensure_ascii=False, indent=4), encoding="utf-8")
        except Exception:
            return None
        rel = "user_data/" + str(out_fp).replace("\\", "/").split("/user_data/", 1)[-1].lstrip("/")
        return rel

    def _auto_align_backtest_inputs() -> Dict[str, Any]:
        try:
            en = bool(AUTOMATION.get("paramopt_backtest_auto_align_enabled", True))
        except Exception:
            en = True
        if not bool(en):
            return {"ok": False, "error": "disabled"}

        try:
            ctx0 = env_overrides.get("_paramopt_ctx") if isinstance(env_overrides, dict) else None
        except Exception:
            ctx0 = None
        ctx0 = ctx0 if isinstance(ctx0, dict) else {}
        base_tid = None
        for k in ("base_trace_id", "base_event_id", "base_event_trace_id"):
            try:
                v = ctx0.get(k)
            except Exception:
                v = None
            if v:
                base_tid = str(v).strip()
                break
        if not base_tid:
            return {"ok": False, "error": "no_base_trace_id"}

        rep = _agent_rca_report_find_from_outbox(base_tid)
        if not isinstance(rep, dict):
            return {"ok": False, "error": "rca_not_found", "base_trace_id": base_tid}
        summ = rep.get("summary") if isinstance(rep.get("summary"), dict) else {}
        pair_raw = str(summ.get("pair") or "").strip()
        err = rep.get("error_norm") if isinstance(rep.get("error_norm"), dict) else {}
        venue = str(err.get("venue") or "").strip().lower()
        timeline = rep.get("timeline") if isinstance(rep.get("timeline"), list) else []
        anchor_ms = None
        for it in timeline:
            if not isinstance(it, dict):
                continue
            if str(it.get("type") or "").strip() == "event":
                try:
                    anchor_ms = int(it.get("ts") or 0)
                except Exception:
                    anchor_ms = None
                break
        if not anchor_ms:
            try:
                anchor_ms = int(rep.get("ts") or 0)
            except Exception:
                anchor_ms = None

        cand_pairs: List[str] = []
        if pair_raw and ("-PERP" in pair_raw.upper()):
            base = pair_raw.split("-", 1)[0].strip().upper()
            if base:
                cand_pairs = [f"{base}/USDT", f"{base}/USDT:USDT"]
        elif pair_raw and ("/" in pair_raw):
            p0 = pair_raw.split(":", 1)[0].strip()
            if p0:
                cand_pairs.append(p0)
            if pair_raw not in cand_pairs:
                cand_pairs.append(pair_raw)
        if not cand_pairs:
            cand_pairs = ["BTC/USDT", "ETH/USDT", "SOL/USDT"]

        prefer_hl = bool(venue and venue not in ("gate", "binance", "okx")) or ("-PERP" in pair_raw.upper())
        exchange_order = (["hyperliquid", "gate"] if prefer_hl else ["gate", "hyperliquid"])
        chosen_exchange = None
        chosen_pair = None
        chosen_cfg_path = None
        chosen_trading_mode = "futures"
        chosen_tf = "1h"

        base_cfg_gate = "user_data/config_local_backtest.json"
        base_cfg_hl = "user_data/config_local_backtest_hyperliquid.json"
        for ex in exchange_order:
            base_cfg = base_cfg_hl if ex == "hyperliquid" else base_cfg_gate
            try:
                p = (Path(os.path.dirname(__file__)) / base_cfg).resolve(strict=False) if base_cfg.startswith("user_data/") else Path(base_cfg)
                cfg = json.loads(p.read_text(encoding="utf-8"))
            except Exception:
                cfg = None
            if not isinstance(cfg, dict):
                continue
            tm = str(cfg.get("trading_mode") or "futures").strip().lower() or "futures"
            for pr in cand_pairs[:6]:
                p_dst = _bt_ohlcv_path(cfg, exchange=ex, trading_mode=tm, pair=pr, tf=chosen_tf)
                if p_dst.exists() and p_dst.is_file():
                    chosen_exchange = ex
                    chosen_pair = pr
                    chosen_cfg_path = base_cfg
                    chosen_trading_mode = tm
                    break
                p_src = _bt_ohlcv_path(cfg, exchange=ex, trading_mode=tm, pair=pr, tf="5m")
                if p_src.exists() and p_src.is_file():
                    chosen_exchange = ex
                    chosen_pair = pr
                    chosen_cfg_path = base_cfg
                    chosen_trading_mode = tm
                    break
            if chosen_exchange:
                break

        if not chosen_exchange or not chosen_pair or not chosen_cfg_path:
            return {"ok": False, "error": "no_exchange_pair_data", "base_trace_id": base_tid, "pair_raw": pair_raw, "venue": venue, "candidates": cand_pairs}

        cfg_updates = {}
        try:
            p = (Path(os.path.dirname(__file__)) / chosen_cfg_path).resolve(strict=False) if chosen_cfg_path.startswith("user_data/") else Path(chosen_cfg_path)
            cfg_base = json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            cfg_base = None
        if not isinstance(cfg_base, dict):
            return {"ok": False, "error": "base_config_load_failed", "config": chosen_cfg_path}
        cfg2 = dict(cfg_base)
        cfg2["timeframe"] = chosen_tf
        ex0 = cfg2.get("exchange") if isinstance(cfg2.get("exchange"), dict) else {}
        ex2 = dict(ex0)
        ex2["name"] = str(chosen_exchange)
        ex2["pair_whitelist"] = [str(chosen_pair)]
        cfg2["exchange"] = ex2
        cfg_updates = cfg2
        mat = _materialize_bt_config(chosen_cfg_path, trace_id=str(trace_id), updates=cfg_updates)
        if not mat:
            return {"ok": False, "error": "materialize_failed", "config": chosen_cfg_path}

        ensure_rep = _ensure_timeframe_from_source(cfg2, exchange=chosen_exchange, trading_mode=chosen_trading_mode, pair=chosen_pair, src_tf="5m", dst_tf=chosen_tf)
        cov = _ohlcv_first_last_ts_ms(_bt_ohlcv_path(cfg2, exchange=chosen_exchange, trading_mode=chosen_trading_mode, pair=chosen_pair, tf=chosen_tf))
        tr2 = _timerange_intersect(timerange, cov, fallback_days=30, anchor_ms=anchor_ms)
        return {
            "ok": True,
            "base_trace_id": base_tid,
            "venue": venue,
            "pair_raw": pair_raw,
            "exchange": str(chosen_exchange),
            "pair": str(chosen_pair),
            "trading_mode": str(chosen_trading_mode),
            "timeframe": str(chosen_tf),
            "config_path": str(mat),
            "timerange": tr2,
            "coverage_ms": (None if not cov else [int(cov[0]), int(cov[1])]),
            "ensure_timeframe": ensure_rep,
        }

    def _run_freqtrade(args: List[str], *, timeout: float) -> Dict[str, Any]:
        cmd2 = None
        ft_bin = _freqtrade_bin()
        ft_py = _freqtrade_python()
        if bool(deny_network):
            if not ft_py:
                return {"ok": False, "error": "freqtrade_python_not_available"}
            script = "\n".join([
                "import sys, runpy",
                "try:",
                "    import socket",
                "    _real_getaddrinfo = socket.getaddrinfo",
                "    _real_create_connection = socket.create_connection",
                "    _real_connect = socket.socket.connect",
                "    _real_connect_ex = socket.socket.connect_ex",
                f"    _allow_hosts = {allow_hosts_literal}",
                "    _allow_ips = set()",
                "    for _h in list(_allow_hosts):",
                "        try:",
                "            rs = _real_getaddrinfo(_h, None)",
                "            for _r in rs:",
                "                try:",
                "                    _allow_ips.add(_r[4][0])",
                "                except Exception:",
                "                    pass",
                "        except Exception:",
                "            pass",
                "    def _refresh_allow_ips():",
                "        for _h2 in list(_allow_hosts):",
                "            if _h2 in ('127.0.0.1', '::1', 'localhost'):",
                "                continue",
                "            for _ in range(4):",
                "                try:",
                "                    rs2 = _real_getaddrinfo(_h2, None)",
                "                except Exception:",
                "                    continue",
                "                try:",
                "                    for _r2 in rs2:",
                "                        try:",
                "                            _allow_ips.add(_r2[4][0])",
                "                        except Exception:",
                "                            pass",
                "                except Exception:",
                "                    pass",
                "    def _host_allowed(h):",
                "        if h is None:",
                "            return True",
                "        try:",
                "            if isinstance(h, (bytes, bytearray)):",
                "                try:",
                "                    h = h.decode('utf-8', 'ignore')",
                "                except Exception:",
                "                    h = str(h)",
                "            hs = str(h).strip().lower()",
                "        except Exception:",
                "            return False",
                "        if (hs in _allow_hosts) or (hs in _allow_ips):",
                "            return True",
                "        try:",
                "            if any(ch.isdigit() for ch in hs) and ('.' in hs or ':' in hs):",
                "                _refresh_allow_ips()",
                "                if hs in _allow_ips:",
                "                    return True",
                "        except Exception:",
                "            pass",
                "        return False",
                "    def _blocked_getaddrinfo(host, *a, **k):",
                "        if _host_allowed(host):",
                "            rs = _real_getaddrinfo(host, *a, **k)",
                "            try:",
                "                for _r in rs:",
                "                    try:",
                "                        _allow_ips.add(_r[4][0])",
                "                    except Exception:",
                "                        pass",
                "            except Exception:",
                "                pass",
                "            return rs",
                "        raise RuntimeError('network_disabled:getaddrinfo:' + repr(host))",
                "    def _ip_like(x):",
                "        try:",
                "            s = str(x).strip().lower()",
                "        except Exception:",
                "            return False",
                "        if not s:",
                "            return False",
                "        if ('.' not in s) and (':' not in s):",
                "            return False",
                "        try:",
                "            return any(ch.isdigit() for ch in s)",
                "        except Exception:",
                "            return False",
                "    def _blocked_create_connection(address, *a, **k):",
                "        h = None",
                "        p = None",
                "        try:",
                "            if isinstance(address, tuple) and len(address) >= 1:",
                "                h = address[0]",
                "            if isinstance(address, tuple) and len(address) >= 2:",
                "                p = address[1]",
                "        except Exception:",
                "            h = None",
                "        if _host_allowed(h):",
                "            return _real_create_connection(address, *a, **k)",
                "        raise RuntimeError('network_disabled:create_connection:' + repr(h))",
                "    def _blocked_connect(self, address):",
                "        h = None",
                "        p = None",
                "        try:",
                "            if isinstance(address, tuple) and len(address) >= 1:",
                "                h = address[0]",
                "            if isinstance(address, tuple) and len(address) >= 2:",
                "                p = address[1]",
                "        except Exception:",
                "            h = None",
                "        if _host_allowed(h):",
                "            return _real_connect(self, address)",
                "        raise RuntimeError('network_disabled:connect:' + repr(h))",
                "    def _blocked_connect_ex(self, address):",
                "        h = None",
                "        p = None",
                "        try:",
                "            if isinstance(address, tuple) and len(address) >= 1:",
                "                h = address[0]",
                "            if isinstance(address, tuple) and len(address) >= 2:",
                "                p = address[1]",
                "        except Exception:",
                "            h = None",
                "        if _host_allowed(h):",
                "            return _real_connect_ex(self, address)",
                "        raise RuntimeError('network_disabled:connect_ex:' + repr(h))",
                "    socket.getaddrinfo = _blocked_getaddrinfo",
                "    socket.create_connection = _blocked_create_connection",
                "    socket.socket.connect = _blocked_connect",
                "    socket.socket.connect_ex = _blocked_connect_ex",
                "except Exception:",
                "    pass",
                "sys.argv = ['freqtrade'] + sys.argv[1:]",
                "runpy.run_module('freqtrade', run_name='__main__')",
            ])
            cmd2 = [ft_py, "-c", script] + args
        else:
            if ft_bin:
                cmd2 = [ft_bin] + args
            elif ft_py:
                cmd2 = [ft_py, "-m", "freqtrade"] + args
            else:
                return {"ok": False, "error": "freqtrade_not_available"}

        env = _sandbox_env_base(os.environ.copy())
        try:
            cpu_cores = pol.get("cpu_cores")
            if cpu_cores is not None:
                n = int(cpu_cores)
                n = max(1, min(64, int(n)))
                for k in [
                    "OMP_NUM_THREADS",
                    "OPENBLAS_NUM_THREADS",
                    "MKL_NUM_THREADS",
                    "VECLIB_MAXIMUM_THREADS",
                    "NUMEXPR_MAX_THREADS",
                ]:
                    env[k] = str(n)
        except Exception:
            pass
        if env_overrides:
            for k, v in (env_overrides or {}).items():
                kk = str(k)
                if _env_key_sensitive(kk):
                    continue
                if v is None:
                    env.pop(kk, None)
                else:
                    env[kk] = str(v)
        preexec = _sandbox_preexec_make(pol=pol if isinstance(pol, dict) else {}, timeout_sec=float(timeout or 1800))
        r2 = subprocess.run(
            cmd2,
            cwd=str(Path(os.path.dirname(__file__))),
            capture_output=True,
            text=True,
            timeout=float(timeout or 1800),
            env=env,
            preexec_fn=preexec,
            start_new_session=True,
        )
        ok2 = (int(r2.returncode) == 0)
        return {
            "ok": bool(ok2),
            "error": (None if ok2 else "freqtrade_cmd_failed"),
            "stdout": r2.stdout[-1000:],
            "stderr": r2.stderr[-1000:],
            "cmd": cmd2,
            "returncode": r2.returncode,
        }

    ok_slot, slot = _sandbox_state_inc_running(kind="backtest")
    if (not ok_slot) and (isinstance(slot, dict) and str(slot.get("error") or "") == "sandbox_concurrency_limit"):
        t0 = time.time()
        try:
            t_budget = float(timeout_sec or 0.0)
        except Exception:
            t_budget = 0.0
        wait_deadline = t0 + float(max(2.0, min(30.0, t_budget * 0.30 if t_budget > 0 else 10.0)))
        sleep_s = 1.0
        while time.time() < wait_deadline:
            time.sleep(float(sleep_s))
            ok_slot, slot = _sandbox_state_inc_running(kind="backtest")
            if ok_slot:
                break
            if not (isinstance(slot, dict) and str(slot.get("error") or "") == "sandbox_concurrency_limit"):
                break
            sleep_s = min(5.0, sleep_s * 1.5)
    if not ok_slot:
        return dict(slot)
    try:
        download_info: Optional[Dict[str, Any]] = None
        if bool(auto_download) and bool(timerange):
            try:
                cfg_bt = None
                try:
                    p0 = Path(str(config_path)).expanduser()
                    try:
                        p0 = p0.resolve()
                    except Exception:
                        p0 = p0
                    if p0.exists() and p0.is_file():
                        cfg_bt = json.loads(p0.read_text(encoding="utf-8"))
                except Exception:
                    cfg_bt = None

                cfg_tf = None
                try:
                    cfg_tf = (None if not isinstance(cfg_bt, dict) else str(cfg_bt.get("timeframe") or "").strip())
                except Exception:
                    cfg_tf = None
                tf_base = (cfg_tf or "1h").strip()
                tfs = [tf_base]
                if "1d" not in tfs:
                    tfs.append("1d")

                warm_days = 365
                try:
                    warm_days = int(CONFIG.get("backtest_warmup_days", 365) or 365)
                except Exception:
                    warm_days = 365
                warm_days = max(0, min(3650, int(warm_days)))
                timerange_warm = _timerange_shift_days(str(timerange), warm_days) if warm_days > 0 else str(timerange)
                if timerange_warm is None:
                    timerange_warm = str(timerange)

                cache_key = "|".join([
                    "cfg=" + str(config_path),
                    "tr=" + str(timerange),
                    "tr_warm=" + str(timerange_warm),
                    "tfs=" + ",".join(tfs),
                ])
                do_dl = True
                with _BACKTEST_DATA_LOCK:
                    last_ms = _BACKTEST_DATA_READY.get(cache_key)
                    now_ms = int(_now_ms())
                    if last_ms is not None and (now_ms - int(last_ms)) < 12 * 3600 * 1000:
                        do_dl = False

                if do_dl:
                    dl_timeout = float(max(60.0, min(float(timeout_sec or 1800), 3600.0)))
                    if tf_base != "1d":
                        dl1 = _run_freqtrade(
                            ["download-data", "--config", str(config_path), "--timerange", str(timerange), "--prepend", "-t", str(tf_base)],
                            timeout=dl_timeout,
                        )
                        if not bool(dl1.get("ok")):
                            download_info = {"ok": False, "error": "download_data_failed", "step": "download_base_tf", "details": dl1}
                            dl1 = None

                    dl2 = _run_freqtrade(
                        ["download-data", "--config", str(config_path), "--timerange", str(timerange_warm), "--prepend", "-t", "1d"],
                        timeout=dl_timeout,
                    )
                    if not bool(dl2.get("ok")):
                        download_info = {"ok": False, "error": "download_data_failed", "step": "download_1d", "details": dl2}
                        dl2 = None

                    if download_info is None:
                        download_info = {"ok": True, "ts": int(_now_ms()), "timerange": str(timerange_warm), "tfs": list(tfs)}
                        with _BACKTEST_DATA_LOCK:
                            _BACKTEST_DATA_READY[cache_key] = int(_now_ms())
            except Exception as e:
                download_info = {"ok": False, "error": "download_data_exception", "details": str(e)}

        before_zip = _backtest_last_result_zip_name()
        before_zip_set = set()
        try:
            before_zip_set = set([p.name for p in list(_backtests_dir().glob("*.zip"))][:5000])
        except Exception:
            before_zip_set = set()

        base_args = ["backtesting", "--config", config_path]
        if timerange:
            base_args.extend(["--timerange", timerange])
        if strategy:
            base_args.extend(["--strategy", str(strategy)])
        if strategy_path:
            sp = Path(str(strategy_path)).expanduser()
            try:
                sp = sp.resolve()
            except Exception:
                sp = None
            if sp is not None:
                bases = []
                try:
                    bases.append(_user_data_dir().resolve())
                except Exception:
                    pass
                try:
                    bases.append(_strategy_sandbox_dir().resolve())
                except Exception:
                    pass
                try:
                    if any(str(sp).startswith(str(b)) for b in bases if b is not None):
                        base_args.extend(["--strategy-path", str(sp)])
                except Exception:
                    pass

        bt = _run_freqtrade(base_args, timeout=float(timeout_sec or 1800))
        ok = bool(bt.get("ok"))
        if ok and bool(import_samples):
            try:
                _import_backtests_samples(10)
            except Exception:
                pass
        after_zip = _backtest_last_result_zip_name()
        zip_name = after_zip or before_zip
        if ok:
            try:
                after_zips = list(_backtests_dir().glob("*.zip"))
            except Exception:
                after_zips = []
            if after_zips:
                if before_zip_set:
                    created = [p for p in after_zips if p.name not in before_zip_set]
                else:
                    created = []
                if created:
                    try:
                        created.sort(key=lambda x: x.stat().st_mtime, reverse=True)
                    except Exception:
                        pass
                    zip_name = created[0].name
                else:
                    if after_zip and before_zip and str(after_zip) == str(before_zip):
                        try:
                            after_zips.sort(key=lambda x: x.stat().st_mtime, reverse=True)
                        except Exception:
                            pass
                        zip_name = after_zips[0].name
        zip_path = (_backtests_dir() / zip_name) if zip_name else None
        metrics = _backtest_zip_metrics(zip_path) if ok and zip_path is not None else None
        picked = _bt_metrics_pick_strategy(metrics, strategy)
        metrics_summary = _bt_metrics_slim(picked)
        return {
            "ok": ok,
            "error": (None if ok else (bt.get("error") or "backtest_failed")),
            "stdout": bt.get("stdout"),
            "stderr": bt.get("stderr"),
            "cmd": bt.get("cmd"),
            "returncode": bt.get("returncode"),
            "result_zip": (None if zip_name is None else str(zip_name)),
            "metrics": metrics,
            "metrics_summary": metrics_summary,
            "download": download_info,
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}
    finally:
        _sandbox_state_dec_running(kind="backtest")


def _backtest_results_list(limit: int = 30) -> List[Dict[str, Any]]:
    lim = int(limit or 0)
    lim = max(1, min(500, lim))
    out: List[Dict[str, Any]] = []
    try:
        p = _backtests_dir()
        if not p.exists():
            return []
        zips = list(p.glob("*.zip"))
        zips.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        for z in zips[:lim]:
            try:
                st = z.stat()
                out.append({
                    "name": str(z.name),
                    "size_bytes": int(st.st_size),
                    "mtime_ms": int(float(st.st_mtime) * 1000.0),
                })
            except Exception:
                continue
    except Exception:
        return []
    return out


def _backtest_report_from_zip(
    zip_path: Optional[Path],
    strategy: Optional[str] = None,
    policy: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    if zip_path is None:
        return {"ok": False, "error": "no_backtest_zip"}
    p = Path(zip_path)
    if (not p.exists()) or (not p.is_file()):
        return {"ok": False, "error": "backtest_zip_not_found", "zip": str(p.name)}
    metrics = _backtest_zip_metrics(p)
    picked = _bt_metrics_pick_strategy(metrics, strategy)
    summary = _bt_metrics_slim(picked)
    aligned = None
    aligned_eval = None
    try:
        aligned = _bt_aligned_metrics_from_zip(p, strategy=strategy)
    except Exception:
        aligned = None
    try:
        if isinstance(aligned, dict) and bool(aligned.get("ok")):
            aligned_eval = _eval_standard_pack(aligned, policy=policy)
    except Exception:
        aligned_eval = None
    return {
        "ok": True,
        "ts": _now_ms(),
        "kind": "freqtrade_backtest",
        "zip": str(p.name),
        "strategy": (None if strategy is None else str(strategy)),
        "metrics_summary": summary,
        "metrics": metrics,
        "aligned_metrics": aligned,
        "eval": aligned_eval,
        "source": {
            "zip": str(p.name),
            "has_metrics": bool(metrics),
            "has_metrics_summary": bool(summary),
            "has_aligned_metrics": bool(aligned) if isinstance(aligned, dict) else False,
        },
    }


def _orders_exec_equity_metrics(limit: int = 5000) -> Dict[str, Any]:
    ords = list(ORDERS.values()) if isinstance(ORDERS, dict) else []
    rows: List[Dict[str, Any]] = []
    for o in ords:
        if not isinstance(o, dict):
            continue
        try:
            ts = int(o.get("ts") or 0)
        except Exception:
            ts = 0
        ex = o.get("exec")
        exd = ex if isinstance(ex, dict) else {}
        if not exd:
            continue
        pnl_net = exd.get("pnl_net_u")
        pnl_gross = exd.get("pnl_gross_u")
        if pnl_net is None and pnl_gross is None:
            continue
        try:
            pnl = float(_to_float(pnl_net if pnl_net is not None else pnl_gross))
        except Exception:
            pnl = 0.0
        if not math.isfinite(float(pnl)):
            pnl = 0.0

        try:
            fees_u = float(_to_float(exd.get("fees_u", 0.0)))
        except Exception:
            fees_u = 0.0
        if not math.isfinite(float(fees_u)):
            fees_u = 0.0

        try:
            funding_u = float(_to_float(exd.get("funding_u", 0.0)))
        except Exception:
            funding_u = 0.0
        if not math.isfinite(float(funding_u)):
            funding_u = 0.0

        rows.append({
            "ts": int(ts),
            "pnl_net_u": float(pnl),
            "fees_u": float(fees_u),
            "funding_u": float(funding_u),
            "status": str(o.get("status") or ""),
            "action": str(o.get("action") or ""),
            "pair": str(o.get("pair") or ""),
            "side": str(o.get("side") or ""),
        })

    snap = _equity_metrics_from_exec_rows(rows, limit=limit, base_equity_u=None)
    return {
        "schema_version": int(snap.get("schema_version") or 2),
        "ts": int(snap.get("ts") or _now_ms()),
        "equity": snap.get("equity") or [],
        "total": float(snap.get("total") or 0.0),
        "maxdd": float(snap.get("maxdd") or 0.0),
        "calmar": snap.get("calmar"),
        "sortino": snap.get("sortino"),
        "trades": int(snap.get("trades") or 0),
        "wins": int(snap.get("wins") or 0),
        "losses": int(snap.get("losses") or 0),
        "winrate": snap.get("winrate"),
        "fees_u": float(snap.get("fees_u") or 0.0),
        "funding_u": float(snap.get("funding_u") or 0.0),
    }


def _reset_runtime_state() -> Dict[str, Any]:
    EVENTS.clear()
    ORDERS.clear()
    with SIGNAL_DEDUP_LOCK:
        SIGNAL_DEDUP.clear()
        SIGNAL_DEDUP_V1_BASE.clear()
    ONLINE_DEDUP.clear()
    EVAL_SAMPLES.clear()
    EVAL_HISTORY.clear()
    EVAL_DEDUP.clear()
    CORR_CACHE.clear()
    PAIR_CACHE.clear()
    DATA_INDEX.clear()
    DATA_INDEX_ALL.clear()
    try:
        _PERP_AUTOFILL_LAST.clear()
    except Exception:
        pass
    CALIBRATOR.clear()
    CALIBRATOR.update({"method": None, "model": None, "by_regime": {}})
    SCALER.clear()
    SCALER.update({"type": None, "params": {}, "ts": None})
    DYNAMIC_THRESHOLDS.clear()
    DYNAMIC_THRESHOLDS.update({"by_regime": {}, "ts": None})
    ONLINE_STATE.clear()
    ONLINE_STATE.update({"version": int(ONLINE_STATE.get("version", 0) or 0) + 1, "last_label_ms": 0, "last_train_ms": 0})
    ARENA_STATE.clear()
    ARENA_STATE.update({
        "inited": False,
        "pool_u": 0.0,
        "models": {},
        "history": [],
        "attrib": [],
        "model_calib": {},
        "layer2": {"last_train_ms": 0, "attrib_count": 0, "updated": {}},
        "diversity": {},
        "ts": 0,
    })
    TRACKER_STATE.clear()
    TRACKER_STATE.update({
        "daily_pnl": {},
        "weekly_pnl": {},
        "open_positions": {},
        "quant_open_positions": {},
        "carry_open_positions": {},
        "order_ts": [],
        "cooldowns": {},
        "coin_cooldowns": {},
        "post_close_cooldowns": {},
        "entry_inflight": {},
        "hl": {},
        "aster": {},
        "gate_history": [],
        "strategy_weights": {},
        "strategy_perf": {},
        "strategy_subportfolios": {},
        "exit_inflight": {},
        "exit_owner_state": {},
        "exit_snapshots": {},
        "exit_settled": {},
        "ab_alloc_state": {},
        "ab_settlements": [],
        "ab_intent_rejects": [],
        "ab_merge_events": [],
        "feeders": {},
        "scheduler": {},
    })
    return {
        "ok": True,
        "events": len(EVENTS),
        "orders": len(ORDERS),
        "samples": len(EVAL_SAMPLES),
    }

def _auto_train(family: str = None, params: Dict[str, Any] = None) -> Dict[str, Any]:
    fam = (family or AUTOMATION.get("training_family") or "xgb").lower()
    ps = params or {}
    try:
        min_samples = int(CONFIG.get("auto_train_min_samples", 500) or 500)
    except Exception:
        min_samples = 500
    min_samples = max(20, min(50000, int(min_samples)))

    if len(EVAL_SAMPLES) < int(min_samples):
        try:
            bootstrap_max = int(CONFIG.get("auto_train_bootstrap_max_samples", 5000) or 5000)
        except Exception:
            bootstrap_max = 5000
        bootstrap_max = max(100, min(200000, int(bootstrap_max)))
        _import_backtests_samples(10, max_samples=int(bootstrap_max))

    if len(EVAL_SAMPLES) < 20:
        return {"ok": False, "error": "no_samples", "family": fam, "min_samples": int(min_samples), "total_samples": int(len(EVAL_SAMPLES))}
    # Fallback to EVENTS-derived bootstrap
    train_set = EVAL_SAMPLES[:] if EVAL_SAMPLES else []
    feature_set_id = _infer_feature_set_id(train_set)
    keys_fit = _eval_feature_keys(None, feature_set_id)
    keys = _eval_feature_keys(fam, feature_set_id)

    if not keys_fit:
        return {"ok": False, "error": "no_feature_keys", "family": fam}

    try:
        stype = str(CONFIG.get("scaler_type", "robust"))
        SCALER.clear()
        SCALER.update(_fit_scaler(train_set, keys_fit, stype))
        _save_scaler()
    except Exception:
        pass

    model = {}
    if fam == "lr":
        model = _lr_train(train_set, {**ps, "keys": keys, "feature_set_id": feature_set_id})
    elif fam == "rf":
        model = _rf_train(train_set, {**ps, "keys": keys, "feature_set_id": feature_set_id})
    elif fam == "xgb":
        model = _xgb_train(train_set, {"n_estimators": 100, "learning_rate": 0.1, "max_depth": 4, **ps, "keys": keys, "feature_set_id": feature_set_id})
    elif fam == "nn":
        model = _nn_train(train_set, {"hidden_size": 16, "lr": 0.01, "epochs": 50, **ps, "keys": keys, "feature_set_id": feature_set_id})
    elif fam == "lstm":
        model = _lstm_train(train_set, {"seq_len": 3, "hidden_size": 16, "lr": 0.01, "epochs": int(CONFIG.get("lstm_epochs", 20)), **ps, "keys": keys, "feature_set_id": feature_set_id})
    else:
        model = _lr_train(train_set, {**ps, "keys": keys, "feature_set_id": feature_set_id})
    EVAL_MODELS[fam] = model
    EVAL_MODELS["active_family"] = fam
    preds, labels = [], []
    for s in train_set:
        labels.append(int(s.get("label",0)))
        if fam == "lr":
            preds.append(_lr_predict(model.get("weights", {}), float(model.get("bias", 0.0)), s.get("features", {})))
        elif fam == "rf":
            preds.append(_rf_predict(model, s.get("features", {})))
        elif fam == "xgb":
            preds.append(_xgb_predict(model, s.get("features", {})))
        elif fam == "nn":
            preds.append(_nn_predict(model, s.get("features", {})))
        elif fam == "lstm":
            preds.append(_lstm_predict(model, s.get("features", {})))
        else:
            preds.append(_score(s.get("features", {}), "long"))
    metrics = _compute_metrics(preds, labels)
    run = {"id": _gen_id("auto"), "family": fam, "params": ps, "metrics": metrics, "ts": _now_ms()}
    _evaluation_history_append(run)
    return {"ok": True, "family": fam, "metrics": metrics, "run": run}


def _strategy_feeders_tick(now: datetime) -> None:
    feeders = AUTOMATION.get("strategy_feeders") or []
    if not feeders:
        feeders = [
            {"strategy_id": "Strategy005", "coins": [], "trigger_decision": True, "emit": True},
            {"strategy_id": "RegimeHybridStrategy", "coins": [], "trigger_decision": True, "emit": True},
            {"strategy_id": "BreakoutStrategy", "coins": [], "trigger_decision": True, "emit": True},
            {"strategy_id": "MultiGroupStrategy", "coins": [], "trigger_decision": True, "emit": True},
            {"strategy_id": "OttStrategy", "coins": [], "trigger_decision": True, "emit": True},
        ]

    core = UNIVERSE_STATE.get("core")
    core_coins = core if isinstance(core, list) else []
    if not core_coins:
        try:
            _build_universe_pipeline(int(now.timestamp() * 1000))
            LAST_RUN["universe"] = now
        except Exception:
            pass
        core = UNIVERSE_STATE.get("core")
        core_coins = core if isinstance(core, list) else []
    if not core_coins:
        UNIVERSE_STATE["core"] = ["BTC", "ETH", "SOL"]
        core_coins = ["BTC", "ETH", "SOL"]
    try:
        max_core = int(CONFIG.get("strategy_feeder_max_core_coins", 12) or 12)
    except Exception:
        max_core = 12
    max_core = int(max(1, min(100, int(max_core))))
    if len(core_coins) > int(max_core):
        core_coins = list(core_coins)[: int(max_core)]

    try:
        per = int(AUTOMATION.get("feeders_period_seconds", 60))
    except Exception:
        per = 60

    fd_stats: Dict[str, Any] = {
        "ts": int(now.timestamp() * 1000),
        "period_seconds": int(per),
        "n_strategies": int(len(feeders or [])),
        "n_core": int(len(core_coins or [])),
        "calls": 0,
        "emits": 0,
        "ingested": 0,
        "null_signals": 0,
        "errors": 0,
        "per_strategy": {},
    }
    try:
        TRACKER_STATE["feeders"] = fd_stats
    except Exception:
        pass

    if core_coins:
        for fd in list(feeders or []):
            try:
                sid = str((fd or {}).get("strategy_id") or "")
                trig = bool((fd or {}).get("trigger_decision", CONFIG.get("signals_auto_decision", False)))
                emit = bool((fd or {}).get("emit", True))
                fd_coins_raw = (fd or {}).get("coins")
                fd_coins = fd_coins_raw if isinstance(fd_coins_raw, list) else []
                coins_eff = [str(x).strip() for x in fd_coins if str(x).strip()] if fd_coins else core_coins
                ps = (fd_stats.get("per_strategy") or {}).get(sid)
                if not isinstance(ps, dict):
                    ps = {"calls": 0, "emits": 0, "ingested": 0, "null_signals": 0, "errors": 0}
                fd_stats["per_strategy"][sid] = ps
                for c in coins_eff:
                    fd_stats["calls"] += 1
                    ps["calls"] += 1
                    try:
                        r = _strategy_feeder_emit(sid, str(c), emit, trig)
                        if isinstance(r, dict) and (r.get("ok") is False):
                            fd_stats["errors"] += 1
                            ps["errors"] += 1
                            continue
                        ing = r.get("ingested")
                        if ing is not None:
                            fd_stats["emits"] += 1
                            ps["emits"] += 1
                            if isinstance(ing, dict) and bool(ing.get("ok", False)):
                                fd_stats["ingested"] += 1
                                ps["ingested"] += 1
                        else:
                            if r.get("signal") is None:
                                fd_stats["null_signals"] += 1
                                ps["null_signals"] += 1
                    except Exception:
                        fd_stats["errors"] += 1
                        ps["errors"] += 1
            except Exception as e:
                LOG.error("feeder_error %s", str(e))
                try:
                    fd_stats["errors"] += 1
                except Exception:
                    pass

    try:
        TRACKER_STATE["feeders"] = fd_stats
    except Exception:
        pass

def _btc_corr_threshold_review_auto_run(now_ms: int) -> None:
    try:
        enabled = bool(CONFIG.get("universe_btc_corr_threshold_review_auto_enabled", True))
    except Exception:
        enabled = True
    if not bool(enabled):
        return
    try:
        pool = str(CONFIG.get("universe_btc_corr_threshold_review_auto_pool", "core") or "core").strip().lower()
    except Exception:
        pool = "core"
    if pool not in ("core", "shadow", "watchlist", "all"):
        pool = "core"
    try:
        months = int(CONFIG.get("universe_btc_corr_threshold_review_auto_months", 6) or 6)
    except Exception:
        months = 6
    months = int(max(1, min(24, int(months))))
    try:
        target_allow_frac = float(CONFIG.get("universe_btc_corr_threshold_review_auto_target_allow_frac", 0.30) or 0.30)
    except Exception:
        target_allow_frac = 0.30
    if (not math.isfinite(float(target_allow_frac))) or float(target_allow_frac) <= 0.0 or float(target_allow_frac) >= 1.0:
        target_allow_frac = 0.30
    target_allow_frac = float(_clip(float(target_allow_frac), 0.01, 0.99))
    try:
        timeframe = str(CONFIG.get("universe_btc_corr_threshold_review_auto_timeframe", "1h") or "1h").strip().lower()
    except Exception:
        timeframe = "1h"
    if timeframe not in ("30m", "1h"):
        timeframe = "1h"
    try:
        method = str(CONFIG.get("universe_btc_corr_threshold_review_auto_method", "pearson") or "pearson").strip().lower()
    except Exception:
        method = "pearson"
    if method not in ("pearson", "spearman"):
        method = "pearson"
    try:
        if "strategy_btc_corr_lookback_bars" in CONFIG:
            lookback_h = float(CONFIG.get("strategy_btc_corr_lookback_bars", 72) or 72)
        else:
            lookback_h = float(CONFIG.get("strategy_btc_corr_lookback_hours", 72) or 72)
    except Exception:
        lookback_h = 72.0
    if (not math.isfinite(float(lookback_h))) or float(lookback_h) <= 0.0:
        lookback_h = 72.0
    if timeframe == "30m":
        window_bars = int(max(10, min(2000, int(round(float(lookback_h) * 2.0)))))
    else:
        window_bars = int(max(30, min(1000, int(round(float(lookback_h))))))
    try:
        max_n = int(CONFIG.get("universe_btc_corr_threshold_review_auto_max_n", 120) or 120)
    except Exception:
        max_n = 120
    max_n = int(max(1, min(500, int(max_n))))
    try:
        include_btc = bool(CONFIG.get("strategy_btc_corr_gate_apply_to_btc", False))
    except Exception:
        include_btc = False
    try:
        out = _btc_corr_threshold_review_compute_from_state(
            now_ms=int(now_ms),
            pool=str(pool),
            max_n=int(max_n),
            months=int(months),
            refresh=False,
            include_btc=bool(include_btc),
            end_ms=int(now_ms),
            timeframe=str(timeframe),
            method=str(method),
            target_allow_frac=float(target_allow_frac),
            window_bars=int(window_bars),
        )
    except Exception as e:
        out = {"ok": False, "ts": int(now_ms), "error": str(e)}
    try:
        md = UNIVERSE_STATE.get("metadata")
        if not isinstance(md, dict):
            md = {}
            UNIVERSE_STATE["metadata"] = md
        md["btc_corr_threshold_review_auto"] = out
    except Exception:
        pass
    try:
        TRACKER_STATE["btc_corr_threshold_review_auto"] = out
    except Exception:
        pass


def _automation_local_post_json(path: str, handler: Any, payload: Dict[str, Any]) -> Tuple[Optional[Dict[str, Any]], int]:
    try:
        with app.test_request_context(str(path), method="POST", json=(payload or {}), environ_base={"REMOTE_ADDR": "127.0.0.1"}):
            rv = handler()
        code = 200
        resp = rv
        if isinstance(rv, tuple) and len(rv) >= 2:
            resp = rv[0]
            try:
                code = int(rv[1])
            except Exception:
                code = 200
        if hasattr(resp, "get_json"):
            try:
                d = resp.get_json(silent=True)
                if isinstance(d, dict):
                    return d, int(code)
            except Exception:
                pass
        try:
            raw = resp.get_data(as_text=True) if hasattr(resp, "get_data") else None
        except Exception:
            raw = None
        if raw:
            try:
                d2 = json.loads(raw)
                if isinstance(d2, dict):
                    return d2, int(code)
            except Exception:
                pass
        return None, int(code)
    except Exception:
        return None, 500


def _shadow_automation_maybe_start_from_monitor(*, now_ms: int, monitor_out: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    if not bool(AUTOMATION.get("enable_shadow_automation_loop", False)):
        return None
    if not isinstance(monitor_out, dict) or not bool(monitor_out.get("triggered", False)):
        return None

    rep = monitor_out.get("rep") if isinstance(monitor_out.get("rep"), dict) else {}
    alerts = rep.get("alerts") if isinstance(rep.get("alerts"), list) else []
    high = [a for a in alerts if isinstance(a, dict) and str(a.get("severity") or "").strip().lower() in ("p1", "p2")]
    if not high:
        return None

    st = TRACKER_STATE.get("shadow_automation") if isinstance(TRACKER_STATE.get("shadow_automation"), dict) else {}
    if not isinstance(st, dict):
        st = {}
    last_run_ms = 0
    try:
        last_run_ms = int(st.get("last_run_ms") or 0)
    except Exception:
        last_run_ms = 0
    try:
        cd_min = int(AUTOMATION.get("shadow_automation_cooldown_minutes", 60) or 60)
    except Exception:
        cd_min = 60
    cd_min = max(1, min(7 * 24 * 60, int(cd_min)))
    if int(last_run_ms) > 0 and int(now_ms) - int(last_run_ms) < int(cd_min) * 60 * 1000:
        return None

    pair = str(monitor_out.get("pair") or "all").strip() or "all"
    trace_id = hashlib.sha256(f"shadow_auto|{int(now_ms)}|{pair}|{len(high)}".encode("utf-8")).hexdigest()[:32]

    st["last_run_ms"] = int(now_ms)
    st["last_trace_id"] = str(trace_id)
    st["active_trace_id"] = str(trace_id)
    TRACKER_STATE["shadow_automation"] = st

    try:
        cand_limit = int(AUTOMATION.get("shadow_automation_candidate_limit", 3) or 3)
    except Exception:
        cand_limit = 3
    cand_limit = max(1, min(10, int(cand_limit)))
    baseline_enabled = bool(AUTOMATION.get("shadow_automation_baseline_enabled", True))
    skip_paramopt = bool(AUTOMATION.get("shadow_automation_skip_paramopt", True))

    payload = {
        "trace_id": str(trace_id),
        "trigger_event": "monitor.alerts.trigger",
        "objective": {"kind": "shadow_automation", "source": "monitor.alerts", "pair": pair, "severity": "P1P2", "alerts": int(len(alerts))},
        "risk_budget": {"never_live": True},
        "shadow_only": True,
        "gray_rollout_mode": "execute",
        "candidate_limit": int(cand_limit),
        "baseline_enabled": bool(baseline_enabled),
        "skip_paramopt": bool(skip_paramopt),
        "queue_sandbox": True,
        "gates": ["backtest", "robustness", "stress", "rolling_verify", "monte_carlo"],
        "doc_refs": _agent_doc_refs_48_default(),
    }
    out, code = _automation_local_post_json("/agent/pipeline/run", agent_pipeline_run, payload)
    if out is None:
        out = {"ok": False, "error": "pipeline_no_response", "http": int(code), "trace_id": str(trace_id), "ts": int(now_ms)}
    try:
        _agent_outbox_append_jsonl(
            "chat.jsonl",
            {
                "id": uuid.uuid4().hex,
                "trace_id": str(trace_id),
                "ts": int(now_ms),
                "type": "automation.shadow.pipeline.start",
                "channel": "workflow",
                "request": _json_sanitize(payload),
                "monitor": _json_sanitize(monitor_out),
                "http": int(code),
                "result": _json_sanitize(out),
            },
        )
    except Exception:
        pass
    try:
        _ensure_sandbox_outbox_worker_started()
    except Exception:
        pass
    try:
        _shadow_observation_emit(trace_id=str(trace_id), now_ms=int(now_ms), kind="shadow_observation_initial", monitor_out=monitor_out)
    except Exception:
        pass
    return {"ok": True, "trace_id": str(trace_id), "http": int(code), "result": out, "ts": int(now_ms)}


def _gtw_state_get() -> Dict[str, Any]:
    st = TRACKER_STATE.get("gtw") if isinstance(TRACKER_STATE.get("gtw"), dict) else {}
    if not isinstance(st, dict):
        st = {}
    if "cooldown_until_ms" not in st:
        st["cooldown_until_ms"] = 0
    if "cooldown_level" not in st:
        st["cooldown_level"] = "none"
    if "confirmed_regime" not in st:
        st["confirmed_regime"] = "UNKNOWN"
    if "regime_persistence" not in st:
        st["regime_persistence"] = 0
    if "candidate_regime" not in st:
        st["candidate_regime"] = None
    if "candidate_regime_count" not in st:
        st["candidate_regime_count"] = 0
    if "candidate_regime_conf_sum" not in st:
        st["candidate_regime_conf_sum"] = 0.0
    TRACKER_STATE["gtw"] = st
    return st


def _gtw_macro_eval(*, now_ms: int, trace_id: str) -> Dict[str, Any]:
    ts = int(now_ms)
    st = _gtw_state_get()
    rr = _pipeline_regime_report_build(trace_id=str(trace_id), now_ms=int(ts))
    trend = str(rr.get("trend") or "").strip().lower() or "sideways"
    vol = str(rr.get("volatility") or "").strip().lower() or "normal"
    try:
        conf0 = float(rr.get("confidence") or 0.0)
    except Exception:
        conf0 = 0.0
    conf0 = float(_clip(conf0, 0.0, 1.0))
    mg = rr.get("macro_gate") if isinstance(rr.get("macro_gate"), dict) else {}
    try:
        mg_pass = bool(mg.get("pass")) if isinstance(mg, dict) else True
    except Exception:
        mg_pass = True

    raw = "TRANSITION"
    if vol == "high":
        raw = "HIGH_VOL"
    elif not mg_pass:
        if trend == "down":
            raw = "RISK_OFF"
        else:
            raw = "TRANSITION"
    else:
        if trend == "up" and vol in ("normal", "elevated"):
            raw = "RISK_ON"
        elif trend == "down":
            raw = "TRANSITION"
        else:
            raw = "TRANSITION"

    try:
        confirm_n = int(AUTOMATION.get("gtw_regime_confirm_n", 2) or 2)
    except Exception:
        confirm_n = 2
    confirm_n = max(1, min(10, int(confirm_n)))
    try:
        dwell = int(AUTOMATION.get("gtw_transition_min_dwell_cycles", 3) or 3)
    except Exception:
        dwell = 3
    dwell = max(0, min(100, int(dwell)))

    confirmed = str(st.get("confirmed_regime") or "UNKNOWN")
    persistence = int(st.get("regime_persistence") or 0)
    if raw == confirmed:
        persistence += 1
        st["candidate_regime"] = None
        st["candidate_regime_count"] = 0
        st["candidate_regime_conf_sum"] = 0.0
    else:
        if confirmed == "TRANSITION" and persistence < int(dwell) and raw not in ("RISK_OFF", "HIGH_VOL"):
            persistence += 1
        else:
            cand = st.get("candidate_regime")
            if str(cand or "") != str(raw):
                st["candidate_regime"] = str(raw)
                st["candidate_regime_count"] = 1
                st["candidate_regime_conf_sum"] = float(conf0)
            else:
                st["candidate_regime_count"] = int(st.get("candidate_regime_count") or 0) + 1
                st["candidate_regime_conf_sum"] = float(st.get("candidate_regime_conf_sum") or 0.0) + float(conf0)
            c_cnt = int(st.get("candidate_regime_count") or 0)
            c_sum = float(st.get("candidate_regime_conf_sum") or 0.0)
            if c_cnt >= int(confirm_n) and c_sum >= float(confirm_n) * 0.60:
                confirmed = str(raw)
                persistence = 1
                st["candidate_regime"] = None
                st["candidate_regime_count"] = 0
                st["candidate_regime_conf_sum"] = 0.0
            else:
                persistence += 1

    st["confirmed_regime"] = confirmed
    st["regime_persistence"] = int(max(0, persistence))
    TRACKER_STATE["gtw"] = st

    probs = {confirmed: float(conf0), "UNKNOWN": float(max(0.0, 1.0 - float(conf0)))}
    out = {
        "raw_regime": str(raw),
        "regime": str(confirmed),
        "confidence": float(conf0),
        "regime_probs": probs,
        "regime_persistence": int(st.get("regime_persistence") or 0),
        "regime_switch_score": float(st.get("candidate_regime_conf_sum") or 0.0),
        "transition_min_dwell_cycles": int(dwell),
        "regime_report": rr,
    }
    return out


def _gtw_trade_eval(*, now_ms: int) -> Dict[str, Any]:
    ts = int(now_ms)
    triggers = _agent_pnl_trigger_eval(int(ts))
    try:
        stats = _system_monitor_get_json_get("/tracker/stats", {"ts": int(ts)}) or {}
    except Exception:
        stats = {}
    return {"ts": int(ts), "pnl_triggers": triggers, "tracker_stats": stats}


def _gtw_decision_id(now_ms: int, seed: str) -> str:
    s = str(seed or "").strip() or "poll"
    nonce = uuid.uuid4().hex
    return hashlib.sha256(f"gtw|{int(now_ms)}|{s}|{nonce}".encode("utf-8")).hexdigest()[:32]


def _gtw_path_idempotency_key(decision_id: str, path_id: str) -> str:
    return hashlib.sha256(f"gtw|{str(decision_id)}|{str(path_id)}".encode("utf-8")).hexdigest()[:32]


def _gtw_path_model_allowed_path_ids() -> List[str]:
    return ["paramopt_automation", "strategy_supply_chain", "strategy_shadow_loop"]


def _gtw_path_model_meta_path(version: str) -> Path:
    v = str(version or "").strip()
    if not v:
        return Path("models") / "gtw_path_model.json"
    return Path("models") / f"gtw_path_model_{v}.json"


def _gtw_path_model_load_meta(version: str) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:
    p = _gtw_path_model_meta_path(str(version))
    try:
        if not p.exists() or not p.is_file():
            return None, "meta_not_found"
    except Exception:
        return None, "meta_not_found"
    try:
        obj = json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        return None, "meta_parse_failed"
    if not isinstance(obj, dict):
        return None, "meta_bad_type"
    return obj, None


def _gtw_path_model_features_from_snapshot(snap_obj: Any) -> Dict[str, float]:
    s = snap_obj if isinstance(snap_obj, dict) else {}
    trade = s.get("trade") if isinstance(s.get("trade"), dict) else {}
    macro = s.get("macro") if isinstance(s.get("macro"), dict) else {}
    trig = trade.get("pnl_triggers") if isinstance(trade.get("pnl_triggers"), list) else []
    has_trig = bool(trig)
    sev = 0.0
    try:
        for t in trig:
            if isinstance(t, dict) and str(t.get("trigger") or "").strip() == "pnl.drawdown.trigger":
                sev = 2.0
                break
        if has_trig and sev <= 0:
            sev = 1.0
    except Exception:
        sev = 0.0
    regime = str(macro.get("regime") or "UNKNOWN").strip() or "UNKNOWN"
    try:
        conf = float(macro.get("confidence") or 0.0)
    except Exception:
        conf = 0.0
    try:
        persist = float(macro.get("regime_persistence") or 0.0)
    except Exception:
        persist = 0.0
    try:
        switch = float(macro.get("regime_switch_score") or 0.0)
    except Exception:
        switch = 0.0
    try:
        dwell = float(macro.get("transition_min_dwell_cycles") or 0.0)
    except Exception:
        dwell = 0.0
    feats: Dict[str, float] = {
        "macro_conf": float(_clip(conf, 0.0, 1.0)),
        "macro_persistence": float(max(0.0, persist)),
        "macro_switch_score": float(max(0.0, switch)),
        "macro_dwell_cycles": float(max(0.0, dwell)),
        "has_pnl_trigger": (1.0 if has_trig else 0.0),
        "trigger_severity": float(sev),
    }
    for r in ("TREND", "RANGE", "VOLATILE", "RISK_OFF", "HIGH_VOL", "LOW_LIQUIDITY", "UNKNOWN"):
        feats[f"regime_{r}"] = (1.0 if regime == r else 0.0)
    return feats


def _gtw_path_model_predict(*, version: str, snap_obj: Any) -> Dict[str, Any]:
    meta, err = _gtw_path_model_load_meta(str(version))
    if err or not isinstance(meta, dict):
        return {"ok": False, "error": (err or "meta_unavailable")}
    model_type = str(meta.get("model_type") or "").strip().lower()
    model_path = str(meta.get("model_path") or "").strip()
    feature_names = meta.get("feature_names") if isinstance(meta.get("feature_names"), list) else []
    path_ids = meta.get("path_ids") if isinstance(meta.get("path_ids"), list) else _gtw_path_model_allowed_path_ids()
    path_ids = [str(x).strip() for x in path_ids if str(x).strip()][:10]
    if not path_ids:
        path_ids = _gtw_path_model_allowed_path_ids()
    feats = _gtw_path_model_features_from_snapshot(snap_obj)
    x_names = [str(x).strip() for x in feature_names if str(x).strip()] if feature_names else sorted(list(feats.keys()))
    x = [float(feats.get(k, 0.0) or 0.0) for k in x_names]
    if not model_type:
        return {"ok": False, "error": "model_type_missing", "meta": _json_sanitize(meta), "features": {"names": x_names, "values": x}}
    if not model_path:
        return {"ok": False, "error": "model_path_missing", "meta": _json_sanitize(meta), "features": {"names": x_names, "values": x}}

    probs: Optional[List[float]] = None
    raw_detail: Any = None
    if model_type in ("sklearn_pickle", "sklearn", "pickle"):
        try:
            import pickle
            with open(model_path, "rb") as f:
                m = pickle.load(f)
            if hasattr(m, "predict_proba"):
                p = m.predict_proba([x])
                if hasattr(p, "tolist"):
                    p = p.tolist()
                if isinstance(p, list) and p and isinstance(p[0], list):
                    probs = [float(v) for v in p[0][: len(path_ids)]]
                raw_detail = {"classes_": (getattr(m, "classes_", None))}
            else:
                return {"ok": False, "error": "predict_proba_missing", "model_type": model_type, "meta": _json_sanitize(meta)}
        except Exception:
            return {"ok": False, "error": "model_load_or_predict_failed", "model_type": model_type, "meta": _json_sanitize(meta)}
    elif model_type in ("xgb", "xgboost"):
        try:
            import xgboost as xgb
            booster = xgb.Booster()
            booster.load_model(model_path)
            dm = xgb.DMatrix([x], feature_names=x_names)
            p = booster.predict(dm)
            if hasattr(p, "tolist"):
                p = p.tolist()
            if isinstance(p, list) and p and isinstance(p[0], list):
                probs = [float(v) for v in p[0][: len(path_ids)]]
            elif isinstance(p, list) and p and isinstance(p[0], (int, float)):
                probs = [float(v) for v in p[: len(path_ids)]]
            raw_detail = {"booster": "loaded"}
        except Exception:
            return {"ok": False, "error": "model_load_or_predict_failed", "model_type": model_type, "meta": _json_sanitize(meta)}
    else:
        return {"ok": False, "error": "unsupported_model_type", "model_type": model_type, "meta": _json_sanitize(meta)}

    if not isinstance(probs, list) or (not probs):
        return {"ok": False, "error": "predict_empty", "model_type": model_type, "meta": _json_sanitize(meta)}
    probs = [float(_clip(float(v), 0.0, 1.0)) for v in probs]
    sm = float(sum(probs))
    if sm > 0:
        probs = [float(v / sm) for v in probs]
    best_i = max(range(len(probs)), key=lambda i: float(probs[i]))
    best_pid = str(path_ids[best_i])
    conf = float(probs[best_i])
    scores = [{"path_id": str(path_ids[i]), "score": float(probs[i])} for i in range(len(probs))]
    scores.sort(key=lambda d: float(d.get("score") or 0.0), reverse=True)
    return {
        "ok": True,
        "model_type": model_type,
        "model_version": str(version or "").strip() or None,
        "scores": scores,
        "recommended_path_id": best_pid,
        "confidence": float(conf),
        "features": {"names": x_names, "values": x},
        "detail": raw_detail,
        "meta": _json_sanitize(meta),
    }


def _gtw_path_model_result_slim(res: Any) -> Optional[Dict[str, Any]]:
    r = res if isinstance(res, dict) else {}
    if not r:
        return None
    out: Dict[str, Any] = {
        "ok": bool(r.get("ok", False)),
        "error": (None if r.get("error") is None else str(r.get("error"))),
        "model_type": (None if r.get("model_type") is None else str(r.get("model_type"))),
        "model_version": (None if r.get("model_version") is None else str(r.get("model_version"))),
        "recommended_path_id": (None if r.get("recommended_path_id") is None else str(r.get("recommended_path_id"))),
        "confidence": (None if r.get("confidence") is None else float(r.get("confidence") or 0.0)),
    }
    scores = r.get("scores") if isinstance(r.get("scores"), list) else []
    out["scores"] = [{"path_id": str(s.get("path_id") or ""), "score": float(s.get("score") or 0.0)} for s in scores if isinstance(s, dict)][:10]
    return _json_sanitize(out)


def _gtw_training_sample_build(*, pkg: Dict[str, Any]) -> Dict[str, Any]:
    p = pkg if isinstance(pkg, dict) else {}
    try:
        ts = int(p.get("created_at_ms") or _now_ms())
    except Exception:
        ts = int(_now_ms())
    decision_id = str(p.get("decision_id") or "").strip()
    lineage = p.get("lineage") if isinstance(p.get("lineage"), dict) else {}
    try:
        data_snapshot_hash = str(lineage.get("data_snapshot_hash") or "").strip() or None
    except Exception:
        data_snapshot_hash = None
    analysis = p.get("analysis") if isinstance(p.get("analysis"), dict) else {}
    rationale = p.get("rationale") if isinstance(p.get("rationale"), dict) else {}
    policy = p.get("policy") if isinstance(p.get("policy"), dict) else {}
    path_selection = p.get("path_selection") if isinstance(p.get("path_selection"), dict) else {}
    path_plans = p.get("path_plans") if isinstance(p.get("path_plans"), list) else []
    inputs = p.get("inputs") if isinstance(p.get("inputs"), dict) else {}
    return _json_sanitize(
        {
            "schema_version": "v1",
            "ts": int(ts),
            "decision_id": decision_id,
            "data_snapshot_hash": data_snapshot_hash,
            "inputs": inputs,
            "analysis": analysis,
            "policy": policy,
            "path_selection": path_selection,
            "path_plans": [
                {
                    "path_id": str(x.get("path_id") or ""),
                    "enabled": bool(x.get("enabled", False)),
                    "disabled_reason": (None if x.get("disabled_reason") is None else str(x.get("disabled_reason"))),
                    "idempotency_key": str(x.get("idempotency_key") or ""),
                    "preconditions": (x.get("preconditions") if isinstance(x.get("preconditions"), list) else []),
                }
                for x in path_plans
                if isinstance(x, dict)
            ],
            "rationale": {"why": rationale.get("why"), "evidence": (rationale.get("evidence") if isinstance(rationale.get("evidence"), list) else [])},
        }
    )


def _gtw_training_outcome_build(*, decision_id: str, pkg: Dict[str, Any], rep: Dict[str, Any]) -> Dict[str, Any]:
    p = pkg if isinstance(pkg, dict) else {}
    r = rep if isinstance(rep, dict) else {}
    lineage = p.get("lineage") if isinstance(p.get("lineage"), dict) else {}
    try:
        data_snapshot_hash = str(lineage.get("data_snapshot_hash") or "").strip() or None
    except Exception:
        data_snapshot_hash = None
    try:
        ts = int(r.get("ts") or _now_ms())
    except Exception:
        ts = int(_now_ms())
    triggered = r.get("triggered") if isinstance(r.get("triggered"), list) else []
    cooldown_applied = r.get("cooldown_applied") if isinstance(r.get("cooldown_applied"), dict) else None
    return _json_sanitize(
        {
            "schema_version": "v1",
            "ts": int(ts),
            "decision_id": str(decision_id),
            "data_snapshot_hash": data_snapshot_hash,
            "triggered": triggered,
            "cooldown_applied": cooldown_applied,
        }
    )


def _gtw_build_decision_package(*, now_ms: int, decision_id: str, polling_kind: str, trigger_event: Optional[str], force_path_ids: Optional[List[str]]) -> Dict[str, Any]:
    ts = int(now_ms)
    st = _gtw_state_get()
    trade = _gtw_trade_eval(now_ms=int(ts))
    macro = _gtw_macro_eval(now_ms=int(ts), trace_id=str(decision_id))
    regime = str(macro.get("regime") or "UNKNOWN")
    try:
        conf = float(macro.get("confidence") or 0.0)
    except Exception:
        conf = 0.0
    conf = float(_clip(conf, 0.0, 1.0))

    shadow_enabled = bool(AUTOMATION.get("enable_shadow_automation_loop", False))
    allow_auto = bool(AUTOMATION.get("enable_gtw", False))
    auto_scope = "none"
    if allow_auto and conf >= 0.50 and regime not in ("RISK_OFF", "HIGH_VOL"):
        auto_scope = "tighten_only"

    disabled: List[str] = []
    cooldown_until_ms = int(st.get("cooldown_until_ms") or 0)
    if cooldown_until_ms > 0 and int(ts) < cooldown_until_ms:
        disabled.append("cooldown_active")

    max_daily_loss = None
    try:
        mdl = float(CONFIG.get("max_daily_loss", CONFIG.get("account_max_daily_loss", -0.05)) or -0.05)
        max_daily_loss = float(abs(mdl))
    except Exception:
        max_daily_loss = None
    max_weekly_loss = None
    try:
        mwl = float(CONFIG.get("max_weekly_loss", CONFIG.get("account_max_weekly_loss", -0.12)) or -0.12)
        max_weekly_loss = float(abs(mwl))
    except Exception:
        max_weekly_loss = None
    max_drawdown = None
    try:
        max_drawdown = float(CONFIG.get("agent_pnl_drawdown_thr", None))
    except Exception:
        max_drawdown = None

    risk_off = regime in ("RISK_OFF", "HIGH_VOL", "LOW_LIQUIDITY")
    risk_budget: Dict[str, Any] = {
        "max_new_exposure": (0.0 if risk_off else None),
        "max_param_change": (0.0 if risk_off else None),
        "max_strategy_turnover": (0.0 if risk_off else None),
        "max_gross_exposure": (0.0 if risk_off else None),
        "max_net_exposure": (0.0 if risk_off else None),
        "max_leverage": (0.0 if risk_off else None),
        "max_single_asset_exposure": (0.0 if risk_off else None),
        "max_sector_exposure": (0.0 if risk_off else None),
        "max_corr_exposure": (0.0 if risk_off else None),
        "max_turnover": (0.0 if risk_off else None),
        "max_daily_loss": (None if max_daily_loss is None else float(max_daily_loss)),
        "max_weekly_loss": (None if max_weekly_loss is None else float(max_weekly_loss)),
        "max_drawdown": (None if max_drawdown is None else float(max_drawdown)),
        "var_99": None,
        "es_97_5": None,
        "stress_loss": None,
    }
    risk_budget_source = None
    try:
        rb = _gtw_risk_budget_from_latest_backtest()
        if isinstance(rb, dict) and bool(rb.get("base_equity_u")):
            v0 = rb.get("var_99")
            e0 = rb.get("es_97_5")
            s0 = rb.get("stress_loss")
            if v0 is not None and math.isfinite(float(v0)) and float(v0) >= 0.0:
                risk_budget["var_99"] = float(v0)
            if e0 is not None and math.isfinite(float(e0)) and float(e0) >= 0.0:
                risk_budget["es_97_5"] = float(e0)
            if s0 is not None and math.isfinite(float(s0)) and float(s0) >= 0.0:
                risk_budget["stress_loss"] = float(s0)
            risk_budget_source = rb
    except Exception:
        risk_budget_source = None

    try:
        high_risk_thr = float(AUTOMATION.get("gtw_high_risk_confidence_min", 0.75) or 0.75)
    except Exception:
        high_risk_thr = 0.75
    high_risk_thr = float(_clip(high_risk_thr, 0.0, 1.0))

    pnl_trigs = trade.get("pnl_triggers") if isinstance(trade.get("pnl_triggers"), list) else []
    has_pnl_trigger = bool(pnl_trigs)
    severity = "none"
    if has_pnl_trigger:
        severity = "p2"
        for t in pnl_trigs:
            if isinstance(t, dict) and str(t.get("trigger") or "").strip() == "pnl.drawdown.trigger":
                severity = "p1"
                break

    cb_active = False
    cb_reason_code = None
    cb_reason = None
    if bool(AUTOMATION.get("gtw_circuit_breaker_enabled", True)) and has_pnl_trigger:
        for t in pnl_trigs:
            if not isinstance(t, dict):
                continue
            trig = str(t.get("trigger") or "").strip()
            if trig == "pnl.drawdown.trigger" and bool(AUTOMATION.get("gtw_circuit_breaker_on_drawdown", True)):
                cb_active = True
                cb_reason_code = "pnl_drawdown"
                cb_reason = _json_sanitize(t)
                break
            if trig == "loss.streak.trigger" and bool(AUTOMATION.get("gtw_circuit_breaker_on_loss_streak", False)):
                cb_active = True
                cb_reason_code = "loss_streak"
                cb_reason = _json_sanitize(t)
                break
    if cb_active:
        disabled.append("circuit_breaker_active")
        try:
            cd_min = int(AUTOMATION.get("gtw_cb_cooldown_minutes", 60) or 60)
        except Exception:
            cd_min = 60
        cd_min = max(1, min(7 * 24 * 60, int(cd_min)))
        if bool(AUTOMATION.get("gtw_apply_cooldown_on_trigger", True)):
            try:
                until0 = int(ts) + int(cd_min) * 60_000
                prev_until = int(st.get("cooldown_until_ms") or 0)
                st["cooldown_until_ms"] = int(max(prev_until, until0))
                st["cooldown_level"] = "deep" if severity == "p1" else "normal"
                TRACKER_STATE["gtw"] = st
                cooldown_until_ms = int(st.get("cooldown_until_ms") or 0)
            except Exception:
                pass

    scores: Dict[str, float] = {"paramopt_automation": 0.0, "strategy_supply_chain": 0.0, "strategy_shadow_loop": 0.0}
    breakdown: Dict[str, Dict[str, Any]] = {k: {} for k in scores}

    if has_pnl_trigger:
        scores["paramopt_automation"] += 0.80
        breakdown["paramopt_automation"]["pnl_trigger"] = True
        scores["strategy_supply_chain"] += 0.55
        breakdown["strategy_supply_chain"]["pnl_trigger"] = True
        scores["strategy_shadow_loop"] += 0.25
        breakdown["strategy_shadow_loop"]["pnl_trigger"] = True

    if regime in ("RISK_OFF", "HIGH_VOL"):
        scores["paramopt_automation"] -= 0.15
        scores["strategy_supply_chain"] -= 0.40
        scores["strategy_shadow_loop"] -= 0.40
        breakdown["strategy_supply_chain"]["macro_block"] = regime
        breakdown["strategy_shadow_loop"]["macro_block"] = regime
    if conf < 0.50:
        scores["strategy_supply_chain"] -= 0.20
        scores["strategy_shadow_loop"] -= 0.25
        breakdown["strategy_supply_chain"]["low_conf"] = float(conf)
        breakdown["strategy_shadow_loop"]["low_conf"] = float(conf)

    if not shadow_enabled:
        scores["paramopt_automation"] -= 1.0
        breakdown["paramopt_automation"]["shadow_required"] = True

    items = [
        {
            "path_id": k,
            "score": float(v),
            "breakdown": breakdown.get(k),
            "top_rules": (sorted([str(x) for x in (breakdown.get(k) or {}).keys() if str(x).strip()]) if isinstance(breakdown.get(k), dict) else []),
        }
        for k, v in scores.items()
    ]
    items.sort(key=lambda x: float(x.get("score") or 0.0), reverse=True)

    model_shadow_enabled = bool(AUTOMATION.get("gtw_path_model_shadow_enabled", False))
    model_rank_enabled = bool(AUTOMATION.get("gtw_path_model_rank_enabled", False))
    model_fail_open = bool(AUTOMATION.get("gtw_path_model_fail_open", True))
    model_rank_mode = str(AUTOMATION.get("gtw_path_model_rank_mode", "override_if_margin") or "override_if_margin").strip()
    if model_rank_mode not in ("override_if_margin", "rank_within_allowed"):
        model_rank_mode = "override_if_margin"
    try:
        model_margin = float(AUTOMATION.get("gtw_path_model_override_margin", 0.05) or 0.05)
    except Exception:
        model_margin = 0.05
    model_margin = float(_clip(model_margin, 0.0, 1.0))
    try:
        model_min_conf = float(AUTOMATION.get("gtw_path_model_min_conf", 0.55) or 0.55)
    except Exception:
        model_min_conf = 0.55
    model_min_conf = float(_clip(model_min_conf, 0.0, 1.0))
    model_version = str(AUTOMATION.get("gtw_path_model_version") or "").strip()
    model_pred = None

    try:
        max_paths = int(AUTOMATION.get("gtw_max_paths_per_run", 2) or 2)
    except Exception:
        max_paths = 2
    max_paths = max(0, min(2, int(max_paths)))
    chosen: List[str] = []
    for it in items:
        pid = str(it.get("path_id") or "")
        sc = float(it.get("score") or 0.0)
        if sc <= 0.35:
            continue
        if pid in chosen:
            continue
        if pid in ("strategy_supply_chain", "strategy_shadow_loop"):
            if conf < float(high_risk_thr) or regime == "RISK_OFF":
                continue
        chosen.append(pid)
        if len(chosen) >= int(max_paths):
            break
    if "strategy_shadow_loop" in chosen and len(chosen) > 1:
        chosen = ["strategy_shadow_loop"]
    chosen_scorecard = list(chosen)

    allowed_path_ids = {"paramopt_automation", "strategy_supply_chain", "strategy_shadow_loop"}
    forced: List[str] = []
    try:
        forced = [str(x).strip() for x in (force_path_ids or []) if str(x).strip() in allowed_path_ids]
    except Exception:
        forced = []
    if forced:
        chosen = list(dict.fromkeys(forced))
    chosen_after_force = list(chosen)
    chosen_before_model = list(chosen)
    model_rank_effective = False

    if (model_shadow_enabled or model_rank_enabled) and (not forced):
        try:
            if model_version:
                model_pred = _gtw_path_model_predict(version=model_version, snap_obj=snap_obj)
            else:
                model_pred = {"ok": False, "error": "model_version_missing"}
        except Exception:
            model_pred = {"ok": False, "error": "model_predict_exception"}

        try:
            if bool(model_rank_enabled):
                if isinstance(model_pred, dict) and bool(model_pred.get("ok")):
                    mc = float(model_pred.get("confidence") or 0.0)
                    if mc >= float(model_min_conf):
                        mscores = model_pred.get("scores") if isinstance(model_pred.get("scores"), list) else []
                        model_by_pid: Dict[str, float] = {}
                        for s in mscores:
                            if not isinstance(s, dict):
                                continue
                            pid0 = str(s.get("path_id") or "").strip()
                            if not pid0:
                                continue
                            try:
                                model_by_pid[pid0] = float(s.get("score") or 0.0)
                            except Exception:
                                continue
                        allowed = []
                        for pid0 in _gtw_path_model_allowed_path_ids():
                            if disabled:
                                continue
                            if pid0 == "paramopt_automation" and (not shadow_enabled):
                                continue
                            if pid0 in ("strategy_supply_chain", "strategy_shadow_loop"):
                                if conf < float(high_risk_thr) or regime == "RISK_OFF":
                                    continue
                            allowed.append(pid0)
                        if allowed:
                            def _m(pid0: str) -> float:
                                return float(model_by_pid.get(pid0, -1e9))
                            allowed_sorted = sorted(allowed, key=lambda pid0: _m(pid0), reverse=True)
                            top_model = allowed_sorted[0]
                            rule_top = (chosen[0] if chosen else None)
                            if model_rank_mode == "rank_within_allowed":
                                chosen = []
                                for pid0 in allowed_sorted:
                                    if _m(pid0) <= -1e8:
                                        continue
                                    chosen.append(pid0)
                                    if len(chosen) >= int(max_paths):
                                        break
                                model_rank_effective = True
                            else:
                                if rule_top and top_model and rule_top != top_model:
                                    margin = float(_m(top_model) - _m(rule_top))
                                    if margin >= float(model_margin):
                                        chosen = [top_model]
                                        model_rank_effective = True
                            if "strategy_shadow_loop" in chosen and len(chosen) > 1:
                                chosen = ["strategy_shadow_loop"]
                else:
                    if not bool(model_fail_open):
                        disabled.append("path_model_unavailable")
        except Exception:
            pass
    chosen_after_model = list(chosen)

    path_plans: List[Dict[str, Any]] = []
    for pid in ("paramopt_automation", "strategy_supply_chain", "strategy_shadow_loop"):
        idem = _gtw_path_idempotency_key(decision_id, pid)
        enabled = pid in chosen and (not disabled)
        is_forced = pid in forced
        dis_reason = None
        pre: List[Dict[str, Any]] = []
        if disabled:
            enabled = False
            dis_reason = disabled[0]
            pre.append({"code": "cooldown_or_disabled", "ok": False, "reason": str(dis_reason)})
        if pid == "paramopt_automation" and not shadow_enabled:
            enabled = False
            dis_reason = "shadow_disabled"
            pre.append({"code": "shadow_enabled", "ok": False, "reason": "shadow_disabled"})
        if pid in ("strategy_supply_chain", "strategy_shadow_loop"):
            if conf < float(high_risk_thr):
                enabled = False
                dis_reason = "low_confidence"
                pre.append({"code": "macro_confidence", "ok": False, "reason": "low_confidence"})
            if regime == "RISK_OFF":
                enabled = False
                dis_reason = "risk_off"
                pre.append({"code": "macro_regime_not_risk_off", "ok": False, "reason": "risk_off"})
        if not pre:
            pre.append({"code": "ok", "ok": True, "reason": None})
        if is_forced and (not disabled):
            enabled = True
            dis_reason = None
        plan_payload: Dict[str, Any] = {"decision_id": str(decision_id), "path_id": str(pid), "trigger_event": str(trigger_event or ""), "severity": severity, "forced": bool(is_forced)}
        required_gates = ["P3"] if pid in ("strategy_supply_chain", "strategy_shadow_loop", "paramopt_automation") else []
        approval_required = True if pid in ("strategy_supply_chain", "strategy_shadow_loop") else True
        path_plans.append(
            {
                "path_id": pid,
                "enabled": bool(enabled),
                "workflow_card_id": pid,
                "idempotency_key": str(idem),
                "disabled_reason": (None if dis_reason is None else str(dis_reason)),
                "trigger": {"type": ("pnl" if has_pnl_trigger else "poll"), "metrics": {"has_pnl_trigger": bool(has_pnl_trigger)}, "thresholds": {}},
                "preconditions": pre,
                "override": ({"forced": True, "source": "force_path_ids"} if is_forced else None),
                "plan": {
                    "run_mode": "sandbox",
                    "payload": plan_payload,
                    "expected_artifacts": None,
                    "required_gates": required_gates,
                    "approval": {"required": bool(approval_required), "auto_policy_id": None},
                    "rollback": {
                        "conditions": {
                            "min_trades": 20,
                            "min_duration_sec": 6 * 3600,
                            "max_drawdown_pct": 0.12,
                            "min_profit_factor": 1.00,
                        },
                        "plan_ref": None,
                    },
                    "observe_criteria": {
                        "baseline_ref": "previous",
                        "min_trades": 20,
                        "min_duration_sec": 6 * 3600,
                        "targets": {
                            "min_rel_improvement": 0.02,
                            "min_profit_factor": 1.10,
                            "max_drawdown_pct": 0.12,
                        },
                        "stability_checks": {"segment_consistency": {"enabled": True, "segments": 3, "min_pass_ratio": 0.67}},
                        "risk_checks": {"max_new_exposure": (0.0 if regime in ("RISK_OFF", "HIGH_VOL") else None)},
                        "bootstrap": {"enabled": True, "n": 200, "alpha": 0.10},
                    },
                },
                "candidates": None,
            }
        )

    policy = {
        "capability_level": "R2",
        "allow_auto_execute": bool(allow_auto) and (not bool(disabled)) and (not bool(cb_active)),
        "auto_execute_scope": (str(auto_scope) if (bool(allow_auto) and (not bool(disabled)) and (not bool(cb_active))) else "none"),
        "cooldown_level": str(st.get("cooldown_level") or "none"),
        "cooldown_until_ms": int(cooldown_until_ms) if int(cooldown_until_ms) > 0 else None,
        "circuit_breaker": {"active": bool(cb_active), "reason_code": cb_reason_code, "reason": cb_reason},
        "disabled_reasons": (disabled if disabled else None),
    }

    run_mode = "sandbox"
    try:
        run_mode = ("dry_run" if bool(CONFIG.get("dry_run", True)) else "prod")
    except Exception:
        run_mode = "sandbox"

    data_snapshot_hash = None
    snap_obj = None
    try:
        snap_obj = {
            "as_of_ts_ms": int(ts),
            "trade": trade,
            "macro": macro,
            "automation": {"enable_gtw": bool(AUTOMATION.get("enable_gtw", False)), "enable_shadow_automation_loop": bool(AUTOMATION.get("enable_shadow_automation_loop", False))},
        }
        data_snapshot_hash = hashlib.sha256(_stable_json_dumps(_json_sanitize(snap_obj)).encode("utf-8")).hexdigest()
    except Exception:
        data_snapshot_hash = None

    evidence: List[Dict[str, Any]] = [
        {"type": "pnl_triggers", "value": _json_sanitize(pnl_trigs)},
        {"type": "macro_regime", "value": _json_sanitize(macro)},
        {"type": "path_selection", "value": {"method": ("force_path_ids" if forced else "rules_scorecard"), "chosen_path_ids": chosen, "scores": items[:3]}},
    ]
    try:
        if bool(model_shadow_enabled) or bool(model_rank_enabled):
            rule_top = (chosen_before_model[0] if isinstance(chosen_before_model, list) and chosen_before_model else None)
            final_top = (chosen_after_model[0] if isinstance(chosen_after_model, list) and chosen_after_model else None)

            allowed_set: List[str] = []
            for pid0 in _gtw_path_model_allowed_path_ids():
                if disabled:
                    continue
                if pid0 == "paramopt_automation" and (not shadow_enabled):
                    continue
                if pid0 in ("strategy_supply_chain", "strategy_shadow_loop"):
                    if conf < float(high_risk_thr) or regime == "RISK_OFF":
                        continue
                allowed_set.append(pid0)

            model_ok = bool(isinstance(model_pred, dict) and bool(model_pred.get("ok")))
            model_err = None if (not isinstance(model_pred, dict) or model_pred.get("error") is None) else str(model_pred.get("error"))
            model_rec = None
            model_conf = None
            model_scores: List[Dict[str, Any]] = []
            try:
                if isinstance(model_pred, dict) and bool(model_pred.get("ok")):
                    model_rec = str(model_pred.get("recommended_path_id") or "").strip() or None
                    model_conf = float(model_pred.get("confidence") or 0.0)
                    ms = model_pred.get("scores") if isinstance(model_pred.get("scores"), list) else []
                    for s in ms[:10]:
                        if not isinstance(s, dict):
                            continue
                        pid0 = str(s.get("path_id") or "").strip()
                        if not pid0:
                            continue
                        try:
                            sc0 = float(s.get("score") or 0.0)
                        except Exception:
                            sc0 = 0.0
                        model_scores.append({"path_id": pid0, "score": float(sc0)})
            except Exception:
                model_rec = None
                model_conf = None
                model_scores = []

            reason_codes: List[str] = []
            detail: Dict[str, Any] = {}
            if forced:
                reason_codes.append("forced_override")
            else:
                if not model_version:
                    reason_codes.append("model_version_missing")
                if not model_ok:
                    reason_codes.append("model_unavailable")
                else:
                    if model_conf is not None and float(model_conf) < float(model_min_conf):
                        reason_codes.append("model_low_confidence")
                    if model_rec and (model_rec not in allowed_set):
                        reason_codes.append("model_recommended_not_allowed")
                        detail["allowed_set"] = allowed_set
                    if model_rec and rule_top and model_rec != rule_top:
                        if not bool(model_rank_enabled):
                            reason_codes.append("rank_disabled")
                        elif model_rank_mode == "override_if_margin":
                            mb = {str(x.get("path_id")): float(x.get("score") or 0.0) for x in model_scores if isinstance(x, dict) and str(x.get("path_id") or "").strip()}
                            try:
                                margin = float(mb.get(str(model_rec), 0.0) - mb.get(str(rule_top), 0.0))
                            except Exception:
                                margin = None
                            detail["override_margin"] = margin
                            if (margin is not None) and (float(margin) < float(model_margin)):
                                reason_codes.append("margin_insufficient")
                    if model_rank_enabled and model_ok and (model_conf is not None) and float(model_conf) >= float(model_min_conf):
                        detail["rank_effective"] = bool(model_rank_effective)
                        if model_rank_enabled and (not model_rank_effective) and model_rec and rule_top and model_rec != rule_top:
                            reason_codes.append("rank_not_applied")

            same_as_model = bool(model_rec and rule_top and model_rec == rule_top)
            evidence.append(
                {
                    "type": "path_model_vs_rules",
                    "value": _json_sanitize(
                        {
                            "rules": {"method": ("force_path_ids" if forced else "rules_scorecard"), "chosen_path_ids": chosen_before_model, "top": rule_top, "scores_top": items[:3]},
                            "model": {
                                "shadow_enabled": bool(model_shadow_enabled),
                                "rank_enabled": bool(model_rank_enabled),
                                "rank_mode": str(model_rank_mode),
                                "min_conf": float(model_min_conf),
                                "override_margin": float(model_margin),
                                "version": (model_version if model_version else None),
                                "ok": bool(model_ok),
                                "error": model_err,
                                "recommended_path_id": model_rec,
                                "confidence": model_conf,
                                "scores_top": model_scores[:3],
                            },
                            "constraints": {
                                "disabled_reasons": (disabled if disabled else None),
                                "macro": {"regime": str(regime), "confidence": float(conf), "high_risk_confidence_min": float(high_risk_thr)},
                                "shadow_enabled": bool(shadow_enabled),
                            },
                            "decision": {"final_method": ("force_path_ids" if forced else ("path_model" if model_rank_effective else "rules_scorecard")), "final_chosen_path_ids": chosen_after_model, "top": final_top},
                            "diff": {"same_as_model": bool(same_as_model), "reason_codes": reason_codes, "detail": detail},
                        }
                    ),
                }
            )
    except Exception:
        pass
    if isinstance(risk_budget_source, dict):
        evidence.append({"type": "risk_budget_backtest", "value": _json_sanitize(risk_budget_source)})

    pkg = {
        "schema_version": "v1",
        "decision_id": str(decision_id),
        "created_at_ms": int(ts),
        "gtw_trace_id": str(decision_id),
        "inputs": {
            "polling_kind": str(polling_kind),
            "trigger_event": (str(trigger_event) if trigger_event else None),
            "feature_snapshot": _json_sanitize(snap_obj),
            "scorecard": {"method": ("force_path_ids" if forced else "rules_scorecard"), "scores": items, "chosen_path_ids": chosen},
            "path_model": {
                "shadow_enabled": bool(model_shadow_enabled),
                "rank_enabled": bool(model_rank_enabled),
                "rank_mode": str(model_rank_mode),
                "min_conf": float(model_min_conf),
                "override_margin": float(model_margin),
                "version": (model_version if model_version else None),
                "result": _gtw_path_model_result_slim(model_pred),
            },
        },
        "lineage": {
            "as_of_ts_ms": int(ts),
            "data_snapshot_id": str(decision_id),
            "data_snapshot_hash": data_snapshot_hash,
            "timerange": None,
            "pairs_hash": None,
            "features_version": None,
            "trade_model_version": None,
            "macro_model_version": None,
            "path_model_version": (model_version if model_version else None),
            "cost_assumption_version": None,
            "execution_config_version": None,
            "macro_release_cutoff_ts_ms": None,
            "macro_revision_id": None,
            "source_artifacts": [{"kind": "regime_report", "trace_id": str(decision_id), "sha256": None}],
        },
        "run_context": {
            "mode": str(run_mode),
            "polling": {"kind": str(polling_kind), "interval_sec": (int(AUTOMATION.get("gtw_poll_interval_sec", 900) or 900) if polling_kind == "poll" else None), "event_type": (str(trigger_event) if trigger_event else None)},
            "timerange": None,
            "lookback_days": 7,
            "pairs": None,
            "exchange": None,
            "overrides": ({"force_path_ids": forced} if forced else None),
        },
        "analysis": {
            "trade": {"template_id": "trade_analysis_v1", "summary": _json_sanitize(trade), "artifacts": None, "has_pnl_trigger": bool(has_pnl_trigger), "severity": str(severity)},
            "macro": {
                "regime": str(regime),
                "confidence": float(conf),
                "regime_probs": _json_sanitize(macro.get("regime_probs")),
                "regime_persistence": int(macro.get("regime_persistence") or 0),
                "regime_switch_score": float(macro.get("regime_switch_score") or 0.0),
                "transition_min_dwell_cycles": int(macro.get("transition_min_dwell_cycles") or 0),
                "risk_budget": _json_sanitize(risk_budget),
                "constraints": None,
            },
        },
        "rationale": {
            "why": "gtw_orchestrate",
            "evidence": evidence,
            "risks": None,
            "alternatives": None,
        },
        "expected_impact": {
            "target_metrics": {
                "baseline_ref": "previous",
                "min_rel_improvement": 0.02,
                "min_profit_factor": 1.10,
                "max_drawdown_pct": 0.12,
            },
            "risk_tradeoff": None,
            "notes": None,
        },
        "path_selection": {"method": ("force_path_ids" if forced else "rules_scorecard"), "scores": items, "chosen_path_ids": chosen},
        "policy": policy,
        "path_plans": path_plans,
        "feedback": None,
    }
    return pkg


def _gtw_trigger_paths(*, now_ms: int, decision_id: str, pkg: Dict[str, Any]) -> Dict[str, Any]:
    ts = int(now_ms)
    path_plans = pkg.get("path_plans") if isinstance(pkg.get("path_plans"), list) else []
    triggered: List[Dict[str, Any]] = []
    trade_obj = (pkg.get("analysis") if isinstance(pkg.get("analysis"), dict) else {}).get("trade") if isinstance(pkg.get("analysis"), dict) else {}
    severity = str((trade_obj or {}).get("severity") or "none").strip().lower() or "none"
    has_pnl_trigger = bool((trade_obj or {}).get("has_pnl_trigger", False))
    try:
        rc = pkg.get("run_context") if isinstance(pkg.get("run_context"), dict) else {}
    except Exception:
        rc = {}
    try:
        lookback_days = int(float(rc.get("lookback_days") or 0))
    except Exception:
        lookback_days = 0
    lookback_days = max(1, min(365, int(lookback_days))) if lookback_days else 60

    already: Dict[str, Dict[str, Any]] = {}
    try:
        rows = _pipeline_artifacts_tail(tail_bytes=800_000, max_lines=6000)
        for r in rows:
            if not isinstance(r, dict):
                continue
            if str(r.get("trace_id") or "") != str(decision_id):
                continue
            if str(r.get("kind") or "") != "gtw.path_trigger":
                continue
            art = r.get("artifact") if isinstance(r.get("artifact"), dict) else {}
            pid0 = str(art.get("path_id") or "").strip()
            idem0 = (None if art.get("idempotency_key") is None else str(art.get("idempotency_key") or "").strip()) or None
            if not pid0:
                continue
            already[f"{pid0}|{idem0 or ''}"] = art
    except Exception:
        already = {}

    def _summarize(out0: Optional[Dict[str, Any]], http: int) -> Optional[str]:
        if not isinstance(out0, dict) or not out0:
            return (None if int(http) == 200 else f"http_{int(http)}")
        for k in ("error", "reason", "blocked_reason"):
            v = out0.get(k)
            if v is not None and str(v).strip():
                return str(v)[:180]
        for k in ("approval_id", "trace_id", "queued"):
            v = out0.get(k)
            if v is not None and str(v).strip():
                return f"{k}={str(v)[:120]}"
        ok0 = out0.get("ok")
        if ok0 is not None:
            return ("ok" if bool(ok0) else "not_ok")
        return None

    def _call_local_post(path: str, fn: Any, payload: Dict[str, Any]) -> Tuple[Optional[Dict[str, Any]], int]:
        try:
            with app.test_request_context(
                path,
                method="POST",
                data=json.dumps(payload or {}),
                content_type="application/json",
                environ_base={"REMOTE_ADDR": "127.0.0.1"},
            ):
                resp = fn()
        except Exception:
            return None, 500
        if isinstance(resp, tuple) and resp:
            resp0, code0 = resp[0], resp[1]
        else:
            resp0, code0 = resp, 200
        try:
            if hasattr(resp0, "get_json"):
                out0 = resp0.get_json() or {}
                return (out0 if isinstance(out0, dict) else None), int(code0)
        except Exception:
            return None, int(code0)
        return None, int(code0)

    for p in path_plans:
        if not isinstance(p, dict):
            continue
        if not bool(p.get("enabled", False)):
            continue
        pid = str(p.get("path_id") or "").strip()
        if not pid:
            continue
        idem = str(p.get("idempotency_key") or "").strip() or None
        prev = already.get(f"{pid}|{idem or ''}")
        if isinstance(prev, dict) and prev:
            triggered.append(
                {
                    "path_id": pid,
                    "idempotency_key": idem,
                    "trace_id": str(prev.get("trace_id") or ""),
                    "status": str(prev.get("status") or "DONE"),
                    "summary": (None if prev.get("summary") is None else str(prev.get("summary"))),
                    "http": int(prev.get("http") or 200),
                    "ok": True if str(prev.get("status") or "") == "DONE" else False,
                    "result": (prev.get("result") if isinstance(prev.get("result"), dict) else _json_sanitize(prev.get("result"))),
                    "deduped": True,
                }
            )
            continue
        child_trace = hashlib.sha256(f"{decision_id}|{pid}|{idem or 'noidem'}".encode("utf-8")).hexdigest()[:32]
        payload0 = {"mode": "new", "trace_id": str(child_trace), "decision_id": str(decision_id), "path_id": str(pid), "gtw_path_id": str(pid), "idempotency_key": idem}
        out, code = None, 500
        if pid == "paramopt_automation":
            payload0 = {"mode": "sandbox", "trace_id": str(child_trace), "confirm_live": True, "decision_id": str(decision_id), "path_id": str(pid), "gtw_path_id": str(pid), "idempotency_key": idem}
            out, code = _call_local_post("/automation/paramopt/trigger", automation_paramopt_trigger, payload0)
        elif pid == "strategy_supply_chain":
            payload0 = {"mode": "auto", "trace_id": str(child_trace), "timerange_days": int(max(60, int(lookback_days))), "timeout_sec": 900, "enqueue_sandbox": True, "decision_id": str(decision_id), "path_id": str(pid), "gtw_path_id": str(pid), "idempotency_key": idem}
            out, code = _call_local_post("/automation/supply_chain/run", automation_supply_chain_run, payload0)
        elif pid == "strategy_shadow_loop":
            payload0 = {"mode": "new", "trace_id": str(child_trace), "decision_id": str(decision_id), "path_id": str(pid), "gtw_path_id": str(pid), "idempotency_key": idem}
            out, code = _call_local_post("/automation/shadow_loop/run", automation_shadow_loop_run, payload0)
        else:
            continue
        ok0 = (bool(out.get("ok")) if isinstance(out, dict) and out.get("ok") is not None else (int(code) == 200))
        status0 = ("DONE" if bool(ok0) else "FAIL")
        summary0 = _summarize(out if isinstance(out, dict) else None, int(code))
        triggered.append({"path_id": pid, "idempotency_key": idem, "trace_id": str(child_trace), "status": status0, "summary": summary0, "http": int(code), "ok": bool(ok0), "result": _json_sanitize(out)})
        try:
            _agent_pipeline_artifact_validate_and_emit(
                trace_id=str(decision_id),
                kind="gtw.path_trigger",
                artifact={"ts": int(ts), "decision_id": str(decision_id), "path_id": pid, "idempotency_key": idem, "trace_id": str(child_trace), "status": status0, "summary": summary0, "http": int(code), "result": _json_sanitize(out)},
            )
        except Exception:
            pass

    cooldown_applied = None
    try:
        if bool(AUTOMATION.get("gtw_apply_cooldown_on_trigger", True)) and bool(has_pnl_trigger) and bool(triggered):
            cd_level = None
            cd_ms = 0
            if severity == "p1":
                cd_level = "deep"
                cd_ms = int(AUTOMATION.get("gtw_cooldown_deep_hours", 24) or 24) * 3600 * 1000
            elif severity == "p2":
                cd_level = "normal"
                cd_ms = int(AUTOMATION.get("gtw_cooldown_normal_minutes", 30) or 30) * 60 * 1000
            if cd_level and int(cd_ms) > 0:
                st = _gtw_state_get()
                until0 = int(ts) + int(cd_ms)
                prev_until = int(st.get("cooldown_until_ms") or 0)
                st["cooldown_until_ms"] = int(max(prev_until, until0))
                st["cooldown_level"] = str(cd_level)
                TRACKER_STATE["gtw"] = st
                cooldown_applied = {"level": str(cd_level), "until_ms": int(st["cooldown_until_ms"]), "reason": f"pnl_trigger_{severity}"}
                try:
                    _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.cooldown", artifact={"ts": int(ts), "decision_id": str(decision_id), "cooldown": cooldown_applied, "triggered": triggered})
                except Exception:
                    pass
    except Exception:
        cooldown_applied = None

    return {"ok": True, "ts": int(ts), "decision_id": str(decision_id), "triggered": triggered, "cooldown_applied": cooldown_applied}


def _gtw_run_once(*, now_ms: int, polling_kind: str, trigger_event: Optional[str], force: bool, force_path_ids: Optional[List[str]]) -> Dict[str, Any]:
    ts = int(now_ms)
    if not bool(AUTOMATION.get("enable_gtw", False)) and (not bool(force)):
        return {"ok": False, "error": "gtw_disabled", "ts": int(ts)}
    st = _gtw_state_get()
    try:
        cd_until = int(st.get("cooldown_until_ms") or 0)
    except Exception:
        cd_until = 0
    if cd_until > 0 and int(ts) < int(cd_until) and (not bool(force)):
        return {"ok": False, "error": "cooldown_active", "cooldown_until_ms": int(cd_until), "ts": int(ts)}

    decision_id = _gtw_decision_id(int(ts), seed=str(trigger_event or polling_kind or "poll"))
    st["last_run_ms"] = int(ts)
    st["last_trace_id"] = str(decision_id)
    st["active_trace_id"] = str(decision_id)
    st["last_decision_id"] = str(decision_id)
    TRACKER_STATE["gtw"] = st

    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.trade_analysis", artifact={"ts": int(ts), "trade": _json_sanitize(_gtw_trade_eval(now_ms=int(ts)))})
    except Exception:
        pass
    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.macro_analysis", artifact={"ts": int(ts), "macro": _json_sanitize(_gtw_macro_eval(now_ms=int(ts), trace_id=str(decision_id)))})
    except Exception:
        pass

    pkg = _gtw_build_decision_package(now_ms=int(ts), decision_id=str(decision_id), polling_kind=str(polling_kind), trigger_event=(str(trigger_event) if trigger_event else None), force_path_ids=(force_path_ids if isinstance(force_path_ids, list) else None))
    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.decision_package", artifact=pkg)
    except Exception:
        pass
    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.training.sample", artifact=_gtw_training_sample_build(pkg=pkg))
    except Exception:
        pass
    try:
        inp = pkg.get("inputs") if isinstance(pkg, dict) else {}
        pm = inp.get("path_model") if isinstance(inp, dict) and isinstance(inp.get("path_model"), dict) else {}
        if bool(pm.get("shadow_enabled", False)) or bool(pm.get("rank_enabled", False)):
            _agent_pipeline_artifact_validate_and_emit(
                trace_id=str(decision_id),
                kind="gtw.path_model.shadow",
                artifact={
                    "ts": int(ts),
                    "decision_id": str(decision_id),
                    "shadow_enabled": bool(pm.get("shadow_enabled", False)),
                    "rank_enabled": bool(pm.get("rank_enabled", False)),
                    "rank_mode": (None if pm.get("rank_mode") is None else str(pm.get("rank_mode"))),
                    "min_conf": (None if pm.get("min_conf") is None else float(pm.get("min_conf") or 0.0)),
                    "override_margin": (None if pm.get("override_margin") is None else float(pm.get("override_margin") or 0.0)),
                    "version": (None if pm.get("version") is None else str(pm.get("version"))),
                    "result": (pm.get("result") if isinstance(pm.get("result"), dict) else None),
                },
            )
    except Exception:
        pass

    try:
        _agent_outbox_append_jsonl("chat.jsonl", {"id": uuid.uuid4().hex, "trace_id": str(decision_id), "ts": int(ts), "type": "gtw.decision", "channel": "workflow", "decision_id": str(decision_id), "trigger_event": (str(trigger_event) if trigger_event else None), "package": _json_sanitize(pkg)})
    except Exception:
        pass

    def _bg_trigger():
        with app.app_context():
            try:
                rep = _gtw_trigger_paths(now_ms=int(_now_ms()), decision_id=str(decision_id), pkg=pkg)
                try:
                    triggered0 = rep.get("triggered") if isinstance(rep, dict) else None
                    fb: List[Dict[str, Any]] = []
                    if isinstance(triggered0, list):
                        for t in triggered0:
                            if not isinstance(t, dict):
                                continue
                            pid0 = str(t.get("path_id") or "").strip()
                            if not pid0:
                                continue
                            st0 = str(t.get("status") or "").strip().upper() or "PENDING"
                            if st0 in ("DONE", "FAIL", "BLOCKED", "RUNNING", "PENDING"):
                                st1 = st0
                            elif st0 in ("OK", "SUCCESS"):
                                st1 = "DONE"
                            else:
                                st1 = ("DONE" if bool(t.get("ok", False)) else "FAIL")
                            fb.append(
                                {
                                    "path_id": pid0,
                                    "status": st1,
                                    "updated_at_ms": int(_now_ms()),
                                    "trace_id": (None if not str(t.get("trace_id") or "").strip() else str(t.get("trace_id") or "").strip()),
                                    "summary": {"http": t.get("http"), "summary": t.get("summary"), "deduped": t.get("deduped")},
                                }
                            )
                    pkg2 = dict(pkg) if isinstance(pkg, dict) else {"schema_version": "v1", "decision_id": str(decision_id)}
                    pkg2["feedback"] = fb if fb else None
                    _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.decision_package", artifact=pkg2)
                except Exception:
                    pass
                try:
                    _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.triggered", artifact=rep)
                except Exception:
                    pass
                try:
                    _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.training.outcome", artifact=_gtw_training_outcome_build(decision_id=str(decision_id), pkg=pkg2, rep=rep if isinstance(rep, dict) else {}))
                except Exception:
                    pass
                try:
                    st2 = _gtw_state_get()
                    st2["last_triggered"] = _json_sanitize(rep)
                    TRACKER_STATE["gtw"] = st2
                except Exception:
                    pass
            except Exception:
                pass

    try:
        threading.Thread(target=_bg_trigger, daemon=True).start()
    except Exception:
        pass

    return {"ok": True, "ts": int(ts), "decision_id": str(decision_id), "trace_id": str(decision_id), "package": _json_sanitize(pkg)}


def _shadow_automation_apply_shadow_patch(*, trace_id: str, now_ms: int) -> Optional[Dict[str, Any]]:
    tid = str(trace_id or "").strip()
    if not tid:
        return None
    st = _agent_pipeline_state_find_latest(trace_id=tid)
    if not isinstance(st, dict):
        return None
    stages = st.get("stages") if isinstance(st.get("stages"), list) else []
    patch = None
    for s in stages:
        if isinstance(s, dict) and str(s.get("name") or "").strip() == "strategy_modification":
            refs = s.get("refs") if isinstance(s.get("refs"), dict) else {}
            p0 = refs.get("config_patch") if isinstance(refs.get("config_patch"), dict) else None
            if isinstance(p0, dict) and p0:
                patch = dict(p0)
            break
    if not isinstance(patch, dict) or not patch:
        patch = {}
    for k in ("serving_canary_enabled", "serving_canary_size_frac", "serving_canary_pairs", "dry_run", "live_trading_enabled", "hl_trading_enabled", "aster_trading_enabled"):
        try:
            patch.pop(k, None)
        except Exception:
            pass
    patch["serving_shadow_mode"] = True
    val = _agent_config_patch_validate(patch, base_cfg=CONFIG, allow_suggest_only=False)
    if not bool(val.get("ok")):
        rep = {"ok": False, "error": "shadow_patch_invalid", "violations": val.get("violations"), "ts": int(now_ms)}
        try:
            art0 = _agent_pipeline_artifact_common_fields(trace_id=str(tid), created_at_ms=int(now_ms), producer_kind="agent")
            art0.update({"ts": int(now_ms), "ok": False, "result": rep})
            _agent_pipeline_artifact_validate_and_emit(trace_id=str(tid), kind="shadow_config_apply", artifact=art0)
        except Exception:
            pass
        return rep
    safe_patch = val.get("patch") if isinstance(val.get("patch"), dict) else {}
    try:
        CONFIG["dry_run"] = True
    except Exception:
        pass
    try:
        _apply_serving_phase("shadow")
    except Exception:
        pass
    if not safe_patch:
        return {"ok": True, "skipped": "empty_patch", "ts": int(now_ms)}
    payload = {"trace_id": str(tid), "auto_approve": True, "config_patch": safe_patch}
    out, code = _automation_local_post_json("/config/set", config_set, payload)
    rep2 = {"ok": (bool(out.get("ok")) if isinstance(out, dict) else False) and int(code) == 200, "http": int(code), "patch": safe_patch, "response": (out if isinstance(out, dict) else None), "ts": int(now_ms)}
    try:
        art = _agent_pipeline_artifact_common_fields(trace_id=str(tid), created_at_ms=int(now_ms), producer_kind="agent")
        art.update({"ts": int(now_ms), "ok": bool(rep2.get("ok")), "http": int(code), "patch": safe_patch, "response": _json_sanitize(out)})
        path = _agent_pipeline_package_write(trace_id=str(tid), filename="shadow_config_apply.json", obj=art)
        if path:
            art["artifact_files"] = {"shadow_config_apply_json": path}
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(tid), kind="shadow_config_apply", artifact=art)
    except Exception:
        pass
    return rep2


def _shadow_observation_maybe_emit_daily(*, now_ms: int) -> None:
    if not bool(AUTOMATION.get("shadow_observation_daily_enabled", False)):
        return
    try:
        if not bool(CONFIG.get("serving_shadow_mode", False)):
            return
    except Exception:
        return
    st = TRACKER_STATE.get("shadow_automation") if isinstance(TRACKER_STATE.get("shadow_automation"), dict) else {}
    tid = str((st or {}).get("active_trace_id") or "").strip()
    if not tid:
        return
    day = datetime.fromtimestamp(int(now_ms) / 1000.0, tz=timezone.utc).strftime("%Y-%m-%d")
    seen = TRACKER_STATE.get("shadow_daily") if isinstance(TRACKER_STATE.get("shadow_daily"), dict) else {}
    if isinstance(seen, dict) and str(seen.get("day") or "") == str(day) and str(seen.get("trace_id") or "") == str(tid):
        return
    ref = _shadow_observation_emit(trace_id=str(tid), now_ms=int(now_ms), kind="shadow_daily_report", monitor_out=None)
    try:
        TRACKER_STATE["shadow_daily"] = {"day": str(day), "trace_id": str(tid), "ts": int(now_ms), "artifact": ref}
    except Exception:
        pass


def _automation_paramopt_shadow_gate(*, now_ms: int, paramopt_out: Dict[str, Any]) -> Dict[str, Any]:
    if not bool(AUTOMATION.get("paramopt_daily_shadow_gate_enabled", True)):
        return {"ok": True, "enabled": False, "pass": False, "reason": "disabled"}
    if not isinstance(paramopt_out, dict) or not bool(paramopt_out.get("ok", False)):
        return {"ok": False, "enabled": True, "pass": False, "error": "paramopt_not_ok"}
    gate = paramopt_out.get("gate") if isinstance(paramopt_out.get("gate"), dict) else {}
    if gate and (not bool(gate.get("pass", True))):
        return {"ok": True, "enabled": True, "pass": False, "reason": "paramopt_gate_fail", "fails": gate.get("fails")}

    eval_mode = str(paramopt_out.get("eval_mode") or "").strip().lower()
    score_system = str(paramopt_out.get("score_system") or "mixed").strip().lower() or "mixed"
    best = paramopt_out.get("best") if isinstance(paramopt_out.get("best"), dict) else {}
    best_score = best.get("max")
    try:
        best_score_f = float(best_score)
    except Exception:
        best_score_f = None
    baseline = paramopt_out.get("baseline") if isinstance(paramopt_out.get("baseline"), dict) else None
    if best_score_f is None or not math.isfinite(float(best_score_f)) or baseline is None:
        return {"ok": True, "enabled": True, "pass": False, "reason": "missing_scores"}

    base_score = None
    base_meta = None
    try:
        if eval_mode == "backtest":
            base_score, base_meta = _paramopt_score_backtest(baseline, baseline=None, system=score_system)
        else:
            base_score, base_meta = _paramopt_score_rolling(baseline, baseline=None, system=score_system)
        base_score = float(base_score)
    except Exception:
        base_score = None
        base_meta = None
    if base_score is None or not math.isfinite(float(base_score)):
        return {"ok": True, "enabled": True, "pass": False, "reason": "baseline_score_failed"}

    thr = None
    try:
        thr = float(AUTOMATION.get("paramopt_daily_shadow_gate_min_rel_improvement", None))
    except Exception:
        thr = None
    if thr is None:
        try:
            thr = float(CONFIG.get("online_auto_promote_min_rel_improvement", 0.05) or 0.05)
        except Exception:
            thr = 0.05
    if not math.isfinite(float(thr)):
        thr = 0.05
    thr = float(max(0.0, min(10.0, float(thr))))

    delta = float(best_score_f) - float(base_score)
    denom = float(max(1.0, abs(float(base_score))))
    rel = float(delta) / float(denom)
    improve_pass = float(rel) >= float(thr) - 1e-12

    stable_required = bool(AUTOMATION.get("paramopt_daily_shadow_gate_require_stable", True))
    stable_pass = True
    stable_evidence = None
    if stable_required:
        try:
            rep = _monitor_alerts_poll_run(int(now_ms))
        except Exception as e:
            rep = {"ok": False, "error": str(e)}
        stable_evidence = rep
        stable_pass = bool(isinstance(rep, dict) and bool(rep.get("ok", True)) and (not bool(rep.get("triggered", False))))

    already_shadow = bool(CONFIG.get("serving_shadow_mode", False))
    if improve_pass and stable_pass:
        try:
            sp = AUTOMATION.get("serving_pipeline") if isinstance(AUTOMATION.get("serving_pipeline"), dict) else {}
            sp2 = dict(sp)
            sp2["enabled"] = True
            sp2["phase"] = "shadow"
            AUTOMATION["serving_pipeline"] = sp2
        except Exception:
            pass
        if not already_shadow:
            try:
                _apply_serving_phase("shadow")
            except Exception:
                pass
            try:
                _save_config()
            except Exception:
                pass
        return {
            "ok": True,
            "enabled": True,
            "pass": True,
            "action": ("already_shadow" if already_shadow else "shadow_entered"),
            "improvement": {"baseline_score": float(base_score), "best_score": float(best_score_f), "delta": float(delta), "rel": float(rel), "threshold": float(thr)},
            "baseline_score_meta": base_meta,
            "stable": {"required": bool(stable_required), "pass": bool(stable_pass), "evidence": stable_evidence},
        }
    return {
        "ok": True,
        "enabled": True,
        "pass": False,
        "reason": ("improvement_below_threshold" if not improve_pass else "system_unstable"),
        "improvement": {"baseline_score": float(base_score), "best_score": float(best_score_f), "delta": float(delta), "rel": float(rel), "threshold": float(thr)},
        "baseline_score_meta": base_meta,
        "stable": {"required": bool(stable_required), "pass": bool(stable_pass), "evidence": stable_evidence},
    }


def _automation_paramopt_daily_run(now_ms: int) -> Dict[str, Any]:
    ts_ms = int(now_ms or _now_ms())
    now_dt = datetime.fromtimestamp(float(ts_ms) / 1000.0, tz=timezone.utc)
    day = now_dt.strftime("%Y%m%d")
    trace_id = hashlib.sha256(f"paramopt_daily|{day}".encode("utf-8")).hexdigest()[:16]

    mode = str(AUTOMATION.get("paramopt_daily_mode", "sandbox") or "sandbox").strip().lower()
    if mode not in ("suggest", "sandbox"):
        mode = "sandbox"
    preset = str(AUTOMATION.get("paramopt_daily_preset", "o6") or "o6").strip()
    family = str(AUTOMATION.get("paramopt_daily_family", EVAL_MODELS.get("active_family") or "xgb") or "xgb").strip().lower() or "xgb"
    eval_mode = str(AUTOMATION.get("paramopt_daily_eval_mode", "rolling") or "rolling").strip().lower() or "rolling"
    if eval_mode not in ("rolling", "backtest"):
        eval_mode = "rolling"
    try:
        folds = int(AUTOMATION.get("paramopt_daily_folds", 5) or 5)
    except Exception:
        folds = 5
    folds = max(3, min(12, int(folds)))
    try:
        n_init = int(AUTOMATION.get("paramopt_daily_n_init", 8) or 8)
    except Exception:
        n_init = 8
    try:
        n_iter = int(AUTOMATION.get("paramopt_daily_n_iter", 24) or 24)
    except Exception:
        n_iter = 24
    n_init = max(0, min(50, int(n_init)))
    n_iter = max(1, min(200, int(n_iter)))
    try:
        topk = int(AUTOMATION.get("paramopt_daily_topk", 3) or 3)
    except Exception:
        topk = 3
    topk = max(1, min(10, int(topk)))

    payload: Dict[str, Any] = {
        "trace_id": trace_id,
        "mode": mode,
        "preset": preset,
        "family": family,
        "eval_mode": eval_mode,
        "folds": int(folds),
        "n_init": int(n_init),
        "n_iter": int(n_iter),
        "topk": int(topk),
        "include_suggest_only": bool(AUTOMATION.get("paramopt_daily_include_suggest_only", True)),
        "skip_robustness": bool(AUTOMATION.get("paramopt_daily_skip_robustness", False)),
        "auto_draft": bool(AUTOMATION.get("paramopt_daily_auto_draft", True)),
        "opt_class": "system",
        "context": {"source": "scheduler", "kind": "paramopt_daily", "day": day, "opt_class": "system"},
        "doc_refs": _agent_doc_refs_48_default(),
    }
    try:
        _agent_pipeline_artifact_validate_and_emit(
            trace_id=str(trace_id),
            kind="paramopt_daily_trigger",
            artifact={"ts": int(ts_ms), "trigger": "scheduler", "day": str(day), "mode": str(mode), "preset": str(preset), "family": str(family), "eval_mode": str(eval_mode)},
        )
    except Exception:
        pass
    out, code = _automation_local_post_json("/agent/paramopt/run", agent_paramopt_run, payload)
    if out is None:
        out = {"ok": False, "error": "paramopt_no_response", "ts": int(ts_ms), "trace_id": trace_id, "http": int(code)}
    try:
        TRACKER_STATE["paramopt_daily_last"] = {"ts": int(ts_ms), "trace_id": trace_id, "http": int(code), "out": out}
    except Exception:
        pass
    try:
        st = _paramopt_automation_state_get()
        st["last_run_ms"] = int(ts_ms)
        st["last_trace_id"] = str(trace_id)
        st["active_trace_id"] = str(trace_id)
        st["source"] = "scheduler"
        st["trigger_event"] = "scheduler"
        TRACKER_STATE["paramopt_automation"] = st
    except Exception:
        pass
    shadow_gate = {}
    try:
        if isinstance(out, dict) and bool(out.get("ok", False)):
            shadow_gate = _automation_paramopt_shadow_gate(now_ms=int(ts_ms), paramopt_out=out)
    except Exception:
        shadow_gate = {"ok": False, "error": "shadow_gate_failed"}
    try:
        _agent_outbox_append_jsonl(
            "chat.jsonl",
            {
                "id": uuid.uuid4().hex,
                "trace_id": trace_id,
                "ts": int(ts_ms),
                "type": "automation.paramopt.daily",
                "channel": "chat",
                "request": payload,
                "http": int(code),
                "result": (out if isinstance(out, dict) else {}),
                "shadow_gate": shadow_gate,
            },
        )
    except Exception:
        pass
    return {"ok": True, "trace_id": trace_id, "ts": int(ts_ms), "http": int(code), "result": out, "shadow_gate": shadow_gate}


def _automation_paramopt_strategy_cycle_run(now_ms: int) -> Dict[str, Any]:
    ts_ms = int(now_ms or _now_ms())
    if not bool(AUTOMATION.get("enable_paramopt_strategy_cycle", False)):
        return {"ok": False, "error": "strategy_cycle_disabled", "ts": int(ts_ms)}
    if not bool(AUTOMATION.get("enable_paramopt_daily", False)):
        return {"ok": False, "error": "paramopt_daily_disabled", "ts": int(ts_ms)}
    try:
        topn = int(AUTOMATION.get("paramopt_strategy_cycle_topn", 1) or 1)
    except Exception:
        topn = 1
    topn = max(1, min(5, int(topn)))
    try:
        mode = str(AUTOMATION.get("paramopt_strategy_cycle_mode", "sandbox") or "sandbox").strip().lower()
    except Exception:
        mode = "sandbox"
    if mode not in ("suggest", "sandbox"):
        mode = "sandbox"
    family = str(AUTOMATION.get("paramopt_strategy_cycle_family", EVAL_MODELS.get("active_family") or "xgb") or "xgb").strip().lower() or "xgb"
    eval_mode = str(AUTOMATION.get("paramopt_strategy_cycle_eval_mode", "rolling") or "rolling").strip().lower() or "rolling"
    if eval_mode not in ("rolling", "backtest"):
        eval_mode = "rolling"
    try:
        folds = int(AUTOMATION.get("paramopt_strategy_cycle_folds", 5) or 5)
    except Exception:
        folds = 5
    folds = max(3, min(12, int(folds)))
    try:
        n_init = int(AUTOMATION.get("paramopt_strategy_cycle_n_init", 8) or 8)
    except Exception:
        n_init = 8
    try:
        n_iter = int(AUTOMATION.get("paramopt_strategy_cycle_n_iter", 24) or 24)
    except Exception:
        n_iter = 24
    n_init = max(0, min(50, int(n_init)))
    n_iter = max(1, min(200, int(n_iter)))
    try:
        bucket_hours = int(AUTOMATION.get("strategy_scheduler_bucket_hours", 8) or 8)
    except Exception:
        bucket_hours = 8
    bucket_hours = max(1, min(48, int(bucket_hours)))
    bucket_sec = int(bucket_hours) * 3600
    try:
        per_id_cooldown_sec = int(AUTOMATION.get("paramopt_strategy_per_id_cooldown_sec", 24 * 3600) or (24 * 3600))
    except Exception:
        per_id_cooldown_sec = 24 * 3600
    per_id_cooldown_sec = max(3600, min(7 * 24 * 3600, int(per_id_cooldown_sec)))

    sw = TRACKER_STATE.get("strategy_weights") if isinstance(TRACKER_STATE.get("strategy_weights"), dict) else {}
    pairs = []
    for sid, w in sw.items():
        s = str(sid or "").strip()
        if not s:
            continue
        try:
            wf = float(w)
        except Exception:
            wf = 0.0
        pairs.append((s, wf))
    pairs.sort(key=lambda x: float(x[1]), reverse=True)
    targets = [sid for sid, _ in pairs[:topn]]
    if not targets:
        return {"ok": False, "error": "no_active_strategies", "ts": int(ts_ms)}

    st0 = TRACKER_STATE.get("paramopt_strategy_cycle") if isinstance(TRACKER_STATE.get("paramopt_strategy_cycle"), dict) else {}
    last_by = st0.get("last_by_strategy") if isinstance(st0.get("last_by_strategy"), dict) else {}
    ran: List[Dict[str, Any]] = []
    skipped: List[Dict[str, Any]] = []
    for sid in targets:
        last_ms = int(last_by.get(sid) or 0) if isinstance(last_by, dict) else 0
        if last_ms > 0 and int(ts_ms) - int(last_ms) < int(per_id_cooldown_sec * 1000):
            skipped.append({"strategy_id": sid, "reason": "cooldown", "last_ms": int(last_ms), "cooldown_sec": int(per_id_cooldown_sec)})
            continue
        bucket = int(ts_ms // int(bucket_sec * 1000))
        trace_id = hashlib.sha256(f"paramopt_strategy_cycle|{sid}|{bucket}".encode("utf-8")).hexdigest()[:16]
        payload = {
            "trace_id": trace_id,
            "mode": mode,
            "family": family,
            "eval_mode": eval_mode,
            "folds": int(folds),
            "n_init": int(n_init),
            "n_iter": int(n_iter),
            "include_suggest_only": True,
            "skip_robustness": bool(AUTOMATION.get("paramopt_strategy_cycle_skip_robustness", False)),
            "auto_draft": bool(AUTOMATION.get("paramopt_strategy_cycle_auto_draft", True)),
            "opt_class": "strategy",
            "strategy_id": str(sid),
            "scopes": ["strategy"],
            "context": {"source": "scheduler", "kind": "paramopt_strategy_cycle", "opt_class": "strategy", "strategy_id": str(sid)},
            "doc_refs": _agent_doc_refs_48_default(),
        }
        out, code = _automation_local_post_json("/agent/paramopt/run", agent_paramopt_run, payload)
        ran.append({"strategy_id": sid, "trace_id": trace_id, "http": int(code), "ok": bool(isinstance(out, dict) and out.get("ok")), "out": out})
        try:
            last_by[sid] = int(ts_ms)
        except Exception:
            pass

    try:
        TRACKER_STATE["paramopt_strategy_cycle"] = {
            "ts": int(ts_ms),
            "targets": targets,
            "ran": ran[:10],
            "skipped": skipped[:10],
            "last_by_strategy": last_by,
            "scheduler_bucket_hours": int(bucket_hours),
            "strategy_per_id_cooldown_sec": int(per_id_cooldown_sec),
        }
    except Exception:
        pass
    try:
        _agent_outbox_append_jsonl(
            "chat.jsonl",
            {
                "id": uuid.uuid4().hex,
                "trace_id": f"strategy_cycle:{int(ts_ms)}",
                "ts": int(ts_ms),
                "type": "automation.paramopt.strategy_cycle",
                "channel": "chat",
                "targets": targets,
                "ran": ran,
                "skipped": skipped,
            },
        )
    except Exception:
        pass
    return {"ok": True, "ts": int(ts_ms), "targets": targets, "ran": ran, "skipped": skipped}


