def _sys_monitor_auto_alerts_build(*, now_ms: int, health: Optional[Dict[str, Any]] = None, metrics: Optional[Dict[str, Any]] = None, tracker: Optional[Dict[str, Any]] = None, signals: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    alerts: List[Dict[str, Any]] = []
    if isinstance(health, dict) and health.get("ok") is False:
        alerts.append({"id": "backend_health", "severity": "P0", "value": health.get("error"), "threshold": "ok=true"})
    if isinstance(metrics, dict) and metrics.get("ok") is False:
        alerts.append({"id": "metrics_recent", "severity": "P1", "value": metrics.get("error"), "threshold": "ok=true"})
    if isinstance(tracker, dict) and tracker.get("ok") is False:
        alerts.append({"id": "tracker_stats", "severity": "P1", "value": tracker.get("error"), "threshold": "ok=true"})
    if isinstance(signals, dict) and signals.get("ok") is False:
        alerts.append({"id": "signals_recent", "severity": "P1", "value": signals.get("error"), "threshold": "ok=true"})
    if isinstance(signals, dict) and signals.get("ok") is True:
        try:
            items = signals.get("items") if isinstance(signals.get("items"), list) else None
            n = int(len(items) if items is not None else int(signals.get("count") or 0))
        except Exception:
            n = 0
        if n <= 0:
            alerts.append({"id": "signals_empty", "severity": "P2", "value": int(n), "threshold": ">0"})
    out: List[Dict[str, Any]] = []
    seen = set()
    for a in alerts:
        if not isinstance(a, dict):
            continue
        aid = str(a.get("id") or "").strip()
        if not aid or aid in seen:
            continue
        a2 = dict(a)
        a2["ts"] = int(now_ms)
        out.append(a2)
        seen.add(aid)
    return out[:20]


def _sys_monitor_auto_maybe_trigger_bugfix(*, now_ms: int, alerts: List[Dict[str, Any]], trace_id: str) -> None:
    sev_rank = {"p0": 0, "critical": 0, "fatal": 0, "high": 1, "p1": 1, "p2": 2, "p3": 3}
    worst = 9
    for a in (alerts or []):
        if not isinstance(a, dict):
            continue
        s = str(a.get("severity") or "").strip().lower()
        worst = min(worst, int(sev_rank.get(s, 9)))
    if worst > 1:
        return
    cooldown = int(AUTOMATION.get("sys_monitor_auto_alert_cooldown_sec", 1800) or 1800)
    cooldown = max(60, min(24 * 3600, int(cooldown)))
    st = TRACKER_STATE.get("sys_monitor_auto") if isinstance(TRACKER_STATE.get("sys_monitor_auto"), dict) else {}
    try:
        last_ms = int((st or {}).get("last_bugfix_ms") or 0)
    except Exception:
        last_ms = 0
    if int(last_ms) > 0 and int(now_ms) - int(last_ms) < int(cooldown) * 1000:
        return
    try:
        st2 = dict(st) if isinstance(st, dict) else {}
        st2["last_bugfix_ms"] = int(now_ms)
        TRACKER_STATE["sys_monitor_auto"] = st2
    except Exception:
        pass
    def _bg_bugfix():
        with app.app_context():
            try:
                _agent_workflow_sys_monitor_bugfix_process(str(trace_id), {"trace_id": str(trace_id), "async": True, "lookback_days": 1.0, "signals_limit": 80, "signals_per_pair": 2, "include_alerts": True, "include_tracker": True, "include_signals": True})
            except Exception:
                pass
    try:
        threading.Thread(target=_bg_bugfix, daemon=True).start()
    except Exception:
        pass


def _sys_monitor_feedback_hist_get() -> List[Dict[str, Any]]:
    st = TRACKER_STATE.get("monitoring_feedback_5m")
    if isinstance(st, list):
        return [x for x in st if isinstance(x, dict)]
    return []


def _sys_monitor_feedback_hist_append(point: Dict[str, Any], *, max_keep: int) -> None:
    if not isinstance(point, dict):
        return
    ts = int(point.get("ts") or 0)
    if ts <= 0:
        return
    cur = _sys_monitor_feedback_hist_get()
    cur.append(point)
    if len(cur) > int(max_keep):
        cur = cur[-int(max_keep):]
    TRACKER_STATE["monitoring_feedback_5m"] = cur


def _sys_monitor_quantile(values: List[float], q: float) -> Optional[float]:
    xs = []
    for v in (values or []):
        try:
            fv = float(v)
        except Exception:
            continue
        if not math.isfinite(fv):
            continue
        xs.append(fv)
    if not xs:
        return None
    xs.sort()
    if q <= 0.0:
        return float(xs[0])
    if q >= 1.0:
        return float(xs[-1])
    pos = (len(xs) - 1) * float(q)
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return float(xs[lo])
    w = float(pos - lo)
    return float(xs[lo] * (1.0 - w) + xs[hi] * w)


def _sys_monitor_feedback_baseline(*, now_ms: int, metric: str, hour_utc: int, window_days: float, min_samples: int) -> Dict[str, Any]:
    hist = _sys_monitor_feedback_hist_get()
    start_ms = int(now_ms) - int(float(window_days) * 86400.0 * 1000.0)
    vals: List[float] = []
    for p in hist:
        try:
            ts = int(p.get("ts") or 0)
        except Exception:
            continue
        if ts <= 0 or ts < int(start_ms):
            continue
        try:
            h = int(p.get("hour_utc") or -1)
        except Exception:
            h = -1
        if h != int(hour_utc):
            continue
        m = p.get("metrics") if isinstance(p.get("metrics"), dict) else {}
        if metric not in m:
            continue
        try:
            vals.append(float(m.get(metric)))
        except Exception:
            continue
    out: Dict[str, Any] = {"ok": True, "metric": str(metric), "window_days": float(window_days), "samples": int(len(vals))}
    if len(vals) < int(min_samples):
        out["ok"] = False
        return out
    out["p01"] = _sys_monitor_quantile(vals, 0.01)
    out["p05"] = _sys_monitor_quantile(vals, 0.05)
    out["p50"] = _sys_monitor_quantile(vals, 0.50)
    out["p95"] = _sys_monitor_quantile(vals, 0.95)
    out["p99"] = _sys_monitor_quantile(vals, 0.99)
    return out


def _sys_monitor_route_json(fn, path: str) -> Dict[str, Any]:
    p = str(path or "").strip() or "/"
    try:
        with app.test_request_context(p, method="GET", content_type="application/json", environ_base={"REMOTE_ADDR": "127.0.0.1"}):
            resp = fn()
        resp0 = resp[0] if isinstance(resp, tuple) and resp else resp
        if hasattr(resp0, "get_json"):
            out = resp0.get_json(force=True) or {}
            if isinstance(out, dict):
                return out
            if isinstance(out, list):
                return {"ok": True, "items": out}
            return {"ok": True, "value": out}
        if isinstance(resp0, dict):
            return resp0
        if isinstance(resp0, list):
            return {"ok": True, "items": resp0}
        return {"ok": True, "value": resp0}
    except Exception as e:
        return {"ok": False, "error": str(e), "path": p}


def _sys_monitor_feedback_5m_poll_run(now_ms: int) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    try:
        hour_utc = int(datetime.fromtimestamp(ts / 1000.0, tz=timezone.utc).hour)
    except Exception:
        hour_utc = 0
    try:
        window_days = float(AUTOMATION.get("sys_monitor_feedback_baseline_days", 30.0) or 30.0)
    except Exception:
        window_days = 30.0
    window_days = float(max(1.0, min(365.0, float(window_days))))
    try:
        min_samples = int(AUTOMATION.get("sys_monitor_feedback_min_samples", 200) or 200)
    except Exception:
        min_samples = 200
    min_samples = int(max(50, min(20000, int(min_samples))))
    try:
        consecutive_n = int(AUTOMATION.get("sys_monitor_feedback_consecutive_n", 3) or 3)
    except Exception:
        consecutive_n = 3
    consecutive_n = int(max(1, min(12, int(consecutive_n))))

    trace_id = hashlib.sha256(f"sysmon.feedback|{int(ts)//300000}".encode("utf-8")).hexdigest()[:32]

    signals_strategy = _sys_monitor_route_json(signals_recent, f"/signals/recent?ab_owner=strategy&include_shadow=1&include_stale=1&limit=200&sort=ingest")
    orders_strategy = _sys_monitor_route_json(orders_recent, f"/orders/recent?ab_owner=strategy&include_shadow=1&limit=200&sort=ingest&no_default_filter=1")
    reject_stats = _sys_monitor_route_json(signals_reject_stats, f"/signals/reject_stats?limit=2000&include_shadow=1")
    gating = _sys_monitor_route_json(gating_state, f"/gating/state")
    universe = _sys_monitor_route_json(universe_status, f"/universe/status")

    quant_cands = _sys_monitor_route_json(quant_pairs_btcalt_candidates, f"/quant/pairs/btcalt/candidates?cache_ttl_sec=300&max_alts=12&include_snap=0")
    quant_alt_orders = _sys_monitor_route_json(quant_pairs_btcalt_orders_recent, f"/quant/pairs/btcalt/orders/recent?limit=200")
    quant_eth_orders = _sys_monitor_route_json(quant_pairs_btceth_orders_recent, f"/quant/pairs/btceth/orders/recent?limit=200")

    ts_weekly = _sys_monitor_route_json(three_screen_weekly_status, f"/three_screen/weekly/status")
    ts_daily = _sys_monitor_route_json(three_screen_daily_signal, f"/three_screen/daily/signal?auto_compute=0")
    ts_5m = _sys_monitor_route_json(three_screen_5m_signal, f"/three_screen/5m/signal?auto_compute=0")

    metrics: Dict[str, Any] = {}

    def _last_age_sec(items: Any, ts_key: str = "ts") -> Optional[float]:
        if not isinstance(items, list) or not items:
            return None
        best = 0
        for it in items[:5000]:
            if not isinstance(it, dict):
                continue
            try:
                v = int(it.get("ingested_ms") or it.get("received_ms") or it.get(ts_key) or 0)
            except Exception:
                v = 0
            if 0 < v < 1000000000000:
                v = v * 1000
            if v > best:
                best = v
        if best <= 0:
            return None
        return float(max(0, ts - best) / 1000.0)

    sig_items = signals_strategy.get("items") if isinstance(signals_strategy.get("items"), list) else None
    ord_items = orders_strategy.get("orders") if isinstance(orders_strategy.get("orders"), list) else (orders_strategy.get("items") if isinstance(orders_strategy.get("items"), list) else None)
    metrics["strategy_last_signal_age_sec"] = _last_age_sec(sig_items, "ts")
    metrics["strategy_last_order_age_sec"] = _last_age_sec(ord_items, "ts")

    sig_1h = 0
    if isinstance(sig_items, list):
        for it in sig_items:
            if not isinstance(it, dict):
                continue
            try:
                v = int(it.get("ingested_ms") or it.get("received_ms") or it.get("ts") or 0)
            except Exception:
                v = 0
            if 0 < v < 1000000000000:
                v = v * 1000
            if v >= int(ts) - 3600 * 1000:
                sig_1h += 1
    metrics["strategy_signals_1h"] = int(sig_1h)

    ord_6h = 0
    if isinstance(ord_items, list):
        for it in ord_items:
            if not isinstance(it, dict):
                continue
            try:
                v = int(it.get("ingested_ms") or it.get("received_ms") or it.get("ts") or 0)
            except Exception:
                v = 0
            if 0 < v < 1000000000000:
                v = v * 1000
            if v >= int(ts) - 6 * 3600 * 1000:
                ord_6h += 1
    metrics["strategy_orders_6h"] = int(ord_6h)

    gap_rate = None
    if isinstance(sig_items, list) and isinstance(ord_items, list):
        order_eids = set()
        for o in ord_items[:5000]:
            if not isinstance(o, dict):
                continue
            for k in ("event_id", "signal_id", "eid", "event"):
                v = o.get(k)
                if v is None:
                    continue
                s = str(v).strip()
                if s:
                    order_eids.add(s)
        open_sigs = []
        for s in sig_items[:5000]:
            if not isinstance(s, dict):
                continue
            act = str(s.get("action") or "").strip().lower()
            if act not in ("enter", "open", "entry"):
                continue
            try:
                t0 = int(s.get("ingested_ms") or s.get("received_ms") or s.get("ts") or 0)
            except Exception:
                t0 = 0
            if 0 < t0 < 1000000000000:
                t0 = t0 * 1000
            if t0 <= 0 or t0 < int(ts) - 2 * 3600 * 1000:
                continue
            if int(ts) - int(t0) < 5 * 60 * 1000:
                continue
            sid = str(s.get("id") or s.get("eid") or "").strip()
            if not sid:
                continue
            open_sigs.append(sid)
        if open_sigs:
            miss = sum(1 for sid in open_sigs if sid not in order_eids)
            gap_rate = float(miss) / float(len(open_sigs))
    metrics["strategy_signal_to_order_gap_rate"] = (None if gap_rate is None else float(gap_rate))

    vote_missing = None
    if isinstance(sig_items, list):
        total = 0
        miss = 0
        for s in sig_items[:200]:
            if not isinstance(s, dict):
                continue
            total += 1
            ok = False
            for k in ("arena", "votes", "vote", "arena_votes", "vote_result", "gating", "gate"):
                if k in s:
                    ok = True
                    break
            if not ok:
                miss += 1
        if total > 0:
            vote_missing = float(miss) / float(total)
    metrics["strategy_vote_fields_missing_rate"] = (None if vote_missing is None else float(vote_missing))

    top_share = None
    entropy = None
    reasons = reject_stats.get("by_reason") if isinstance(reject_stats.get("by_reason"), dict) else {}
    if reasons:
        tot = 0
        mx = 0
        for v in reasons.values():
            try:
                iv = int(v)
            except Exception:
                continue
            if iv <= 0:
                continue
            tot += iv
            mx = max(mx, iv)
        if tot > 0:
            top_share = float(mx) / float(tot)
            ent = 0.0
            for v in reasons.values():
                try:
                    iv = int(v)
                except Exception:
                    continue
                if iv <= 0:
                    continue
                p = float(iv) / float(tot)
                ent -= p * math.log(max(1e-12, p))
            entropy = float(ent)
    metrics["reject_top_reason_share"] = (None if top_share is None else float(top_share))
    metrics["reject_reason_entropy"] = (None if entropy is None else float(entropy))

    alts = quant_cands.get("alts") if isinstance(quant_cands.get("alts"), list) else []
    metrics["quant_candidates_alts_len"] = int(len(alts))

    metrics["quant_btcalt_last_order_age_sec"] = _last_age_sec((quant_alt_orders.get("orders") if isinstance(quant_alt_orders.get("orders"), list) else quant_alt_orders.get("items")), "ts")
    metrics["quant_btceth_last_order_age_sec"] = _last_age_sec((quant_eth_orders.get("orders") if isinstance(quant_eth_orders.get("orders"), list) else quant_eth_orders.get("items")), "ts")

    metrics["three_screen_weekly_ok"] = bool(ts_weekly.get("ok", False))
    metrics["three_screen_daily_ok"] = bool(ts_daily.get("ok", False))
    metrics["three_screen_5m_ok"] = bool(ts_5m.get("ok", False))
    core = universe.get("core") if isinstance(universe.get("core"), list) else []
    shadow = universe.get("shadow") if isinstance(universe.get("shadow"), list) else []
    watchlist = universe.get("watchlist") if isinstance(universe.get("watchlist"), list) else []
    metrics["universe_core_len"] = int(len(core))
    metrics["universe_shadow_len"] = int(len(shadow))
    metrics["universe_watchlist_len"] = int(len(watchlist))
    try:
        uni_last = int(universe.get("last_update") or 0)
    except Exception:
        uni_last = 0
    if 0 < int(uni_last) < 1000000000000:
        uni_last = int(uni_last) * 1000
    if int(uni_last) > 0:
        metrics["universe_last_update_age_sec"] = float(max(0, int(ts) - int(uni_last)) / 1000.0)
    else:
        metrics["universe_last_update_age_sec"] = None

    alerts: List[Dict[str, Any]] = []

    def _baseline_p99(metric_name: str) -> Optional[float]:
        b = _sys_monitor_feedback_baseline(now_ms=int(ts), metric=str(metric_name), hour_utc=int(hour_utc), window_days=float(window_days), min_samples=int(min_samples))
        if not bool(b.get("ok")):
            return None
        try:
            v = b.get("p99")
            if v is None:
                return None
            return float(v)
        except Exception:
            return None

    def _baseline_p01(metric_name: str) -> Optional[float]:
        b = _sys_monitor_feedback_baseline(now_ms=int(ts), metric=str(metric_name), hour_utc=int(hour_utc), window_days=float(window_days), min_samples=int(min_samples))
        if not bool(b.get("ok")):
            return None
        try:
            v = b.get("p01")
            if v is None:
                return None
            return float(v)
        except Exception:
            return None

    def _add_alert(aid: str, severity: str, value: Any, threshold: Any) -> None:
        alerts.append({"id": str(aid), "severity": str(severity), "value": value, "threshold": threshold, "ts": int(ts)})

    age_sig = metrics.get("strategy_last_signal_age_sec")
    if isinstance(age_sig, (int, float)) and math.isfinite(float(age_sig)):
        thr = _baseline_p99("strategy_last_signal_age_sec")
        thr2 = (float(thr) + 300.0) if thr is not None else 6.0 * 3600.0
        if float(age_sig) > float(thr2):
            _add_alert("strategy_signals_stale", "P1", float(age_sig), float(thr2))

    sig1h = metrics.get("strategy_signals_1h")
    if isinstance(sig1h, int):
        thr = _baseline_p01("strategy_signals_1h")
        thr2 = (int(max(0, math.floor(thr))) if thr is not None else 0)
        if int(sig1h) <= int(thr2):
            _add_alert("strategy_signals_sparse", "P2", int(sig1h), int(thr2))

    gap = metrics.get("strategy_signal_to_order_gap_rate")
    if isinstance(gap, (int, float)) and math.isfinite(float(gap)):
        thr = _baseline_p99("strategy_signal_to_order_gap_rate")
        thr2 = (float(thr) if thr is not None else 0.8)
        if float(gap) > float(thr2):
            _add_alert("strategy_signal_order_gap", "P1", float(gap), float(thr2))

    vm = metrics.get("strategy_vote_fields_missing_rate")
    if isinstance(vm, (int, float)) and math.isfinite(float(vm)):
        if float(vm) > 0.8:
            _add_alert("strategy_vote_fields_missing", "P2", float(vm), 0.8)

    rt = metrics.get("reject_top_reason_share")
    if isinstance(rt, (int, float)) and math.isfinite(float(rt)):
        thr = _baseline_p99("reject_top_reason_share")
        thr2 = (float(thr) if thr is not None else 0.90)
        if float(rt) > float(thr2):
            _add_alert("reject_distribution_spike", "P1", float(rt), float(thr2))

    alt_n = metrics.get("quant_candidates_alts_len")
    if isinstance(alt_n, int):
        thr = _baseline_p01("quant_candidates_alts_len")
        thr2 = (int(max(0, math.floor(thr))) if thr is not None else 0)
        if int(alt_n) <= int(thr2):
            _add_alert("quant_candidates_empty", "P1", int(alt_n), int(thr2))

    core_n = metrics.get("universe_core_len")
    if isinstance(core_n, int):
        thr = _baseline_p01("universe_core_len")
        thr2 = (int(max(0, math.floor(thr))) if thr is not None else 0)
        if int(core_n) <= int(thr2):
            _add_alert("universe_pool_core_empty", "P1", int(core_n), int(thr2))

    upd_age = metrics.get("universe_last_update_age_sec")
    if isinstance(upd_age, (int, float)) and math.isfinite(float(upd_age)):
        thr = _baseline_p99("universe_last_update_age_sec")
        thr2 = (float(thr) if thr is not None else 3600.0)
        if float(upd_age) > float(thr2):
            _add_alert("universe_update_stale", "P1", float(upd_age), float(thr2))

    qa = metrics.get("quant_btcalt_last_order_age_sec")
    if isinstance(qa, (int, float)) and math.isfinite(float(qa)) and int(alt_n or 0) > 0:
        thr = _baseline_p99("quant_btcalt_last_order_age_sec")
        thr2 = (float(thr) if thr is not None else 24.0 * 3600.0)
        if float(qa) > float(thr2):
            _add_alert("quant_orders_stale", "P1", float(qa), float(thr2))

    if metrics.get("three_screen_weekly_ok") is False or metrics.get("three_screen_daily_ok") is False or metrics.get("three_screen_5m_ok") is False:
        _add_alert("three_screen_endpoint_fail", "P1", {"weekly_ok": metrics.get("three_screen_weekly_ok"), "daily_ok": metrics.get("three_screen_daily_ok"), "5m_ok": metrics.get("three_screen_5m_ok")}, True)

    try:
        st = TRACKER_STATE.get("sys_monitor_auto") if isinstance(TRACKER_STATE.get("sys_monitor_auto"), dict) else {}
        st2 = dict(st) if isinstance(st, dict) else {}
        st2["last_feedback_ms"] = int(ts)
        st2["last_feedback_trace_id"] = str(trace_id)
        TRACKER_STATE["sys_monitor_auto"] = st2
    except Exception:
        pass

    try:
        max_keep = int(max(2000, min(50000, int(float(window_days) * 86400.0 / 300.0) + 2000)))
    except Exception:
        max_keep = 20000
    try:
        _sys_monitor_feedback_hist_append({"ts": int(ts), "hour_utc": int(hour_utc), "metrics": _json_sanitize(metrics)}, max_keep=int(max_keep))
    except Exception:
        pass

    sev_rank = {"p0": 0, "critical": 0, "fatal": 0, "high": 1, "p1": 1, "p2": 2, "p3": 3}
    present: Dict[str, Dict[str, Any]] = {}
    for a in alerts:
        if not isinstance(a, dict):
            continue
        aid = str(a.get("id") or "").strip()
        if not aid:
            continue
        present[aid] = a

    try:
        poll_sec = int(AUTOMATION.get("sys_monitor_feedback_poll_interval_sec", 300) or 300)
    except Exception:
        poll_sec = 300
    poll_sec = max(60, min(24 * 3600, int(poll_sec)))

    st = TRACKER_STATE.get("sys_monitor_auto") if isinstance(TRACKER_STATE.get("sys_monitor_auto"), dict) else {}
    try:
        prev_counts0 = st.get("feedback_counts") if isinstance(st.get("feedback_counts"), dict) else {}
    except Exception:
        prev_counts0 = {}
    prev_counts = {str(k): (v if isinstance(v, dict) else {}) for k, v in prev_counts0.items()}

    new_counts: Dict[str, Dict[str, Any]] = {}
    for aid, a in present.items():
        prev = prev_counts.get(aid) if isinstance(prev_counts.get(aid), dict) else {}
        try:
            pc = int(prev.get("count") or 0)
        except Exception:
            pc = 0
        try:
            pts = int(prev.get("last_ts") or 0)
        except Exception:
            pts = 0
        if int(pts) > 0 and (int(ts) - int(pts)) > int(poll_sec) * 1000 * 3:
            pc = 0
        nc = int(pc) + 1
        new_counts[aid] = {"count": int(nc), "last_ts": int(ts), "severity": str(a.get("severity") or "")}

    hits: List[Dict[str, Any]] = []
    for aid, a in present.items():
        try:
            s = str(a.get("severity") or "").strip().lower()
        except Exception:
            s = ""
        if int(sev_rank.get(s, 9)) > 1:
            continue
        try:
            c = int((new_counts.get(aid) or {}).get("count") or 0)
        except Exception:
            c = 0
        if int(c) >= int(consecutive_n):
            a2 = dict(a)
            a2["consecutive"] = int(c)
            hits.append(a2)

    triggered = bool(hits)
    try:
        st2 = dict(st) if isinstance(st, dict) else {}
        st2["feedback_counts"] = new_counts
        st2["last_feedback_triggered"] = bool(triggered)
        st2["last_feedback_alerts"] = _json_sanitize(alerts)
        st2["last_feedback_hits"] = _json_sanitize(hits)
        TRACKER_STATE["sys_monitor_auto"] = st2
    except Exception:
        pass

    if triggered:
        _agent_emit_envelope_event(
            event="monitor.alerts.trigger",
            trace_id=str(trace_id),
            severity="warn",
            intent_level="L0",
            ts_ms=int(ts),
            inputs={"pair": None, "source": "sys_monitor.feedback_5m", "consecutive_n": int(consecutive_n)},
            evidence=[{"type": "sys_monitor_feedback_5m", "metrics": metrics, "alerts": alerts, "hits": hits, "gating": gating, "reject_stats": reject_stats}],
            outputs={"triggered": True, "hits": hits, "alerts": alerts, "idempotency_key": f"sysmon.feedback|{int(ts)//300000}"},
            doc_refs=_agent_doc_refs_48_default(),
        )
        _sys_monitor_auto_maybe_trigger_bugfix(now_ms=int(ts), alerts=alerts, trace_id=str(trace_id))

    return {"ok": True, "ts": int(ts), "trace_id": str(trace_id), "metrics": metrics, "alerts": alerts, "hits": hits, "triggered": bool(triggered), "consecutive_n": int(consecutive_n)}


def _sys_monitor_auto_light_poll_run(now_ms: int) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    trace_id = hashlib.sha256(f"sysmon.light|{int(ts)//3600000}".encode("utf-8")).hexdigest()[:32]
    health = None
    metrics = None
    tracker = None
    signals = None
    try:
        health = _skill_health_get({})
    except Exception as e:
        health = {"ok": False, "error": str(e), "ts": int(ts)}
    try:
        metrics = _skill_metrics_recent({})
    except Exception as e:
        metrics = {"ok": False, "error": str(e), "ts": int(ts)}
    try:
        tracker = _skill_tracker_stats({"view": "summary"})
    except Exception as e:
        tracker = {"ok": False, "error": str(e), "ts": int(ts)}
    try:
        signals = _skill_signals_recent({"limit": 20, "diverse": True, "per_pair": 1})
    except Exception as e:
        signals = {"ok": False, "error": str(e), "ts": int(ts)}

    alerts = _sys_monitor_auto_alerts_build(now_ms=int(ts), health=health, metrics=metrics, tracker=tracker, signals=signals)
    high = [a for a in alerts if isinstance(a, dict) and str(a.get("severity") or "").strip().lower() in ("p0", "p1", "critical", "fatal", "high")]
    triggered = bool(high)

    try:
        st = TRACKER_STATE.get("sys_monitor_auto") if isinstance(TRACKER_STATE.get("sys_monitor_auto"), dict) else {}
        st2 = dict(st) if isinstance(st, dict) else {}
        st2["last_light_ms"] = int(ts)
        st2["last_light_trace_id"] = str(trace_id)
        TRACKER_STATE["sys_monitor_auto"] = st2
    except Exception:
        pass

    if triggered:
        _agent_emit_envelope_event(
            event="monitor.alerts.trigger",
            trace_id=str(trace_id),
            severity="warn",
            intent_level="L0",
            ts_ms=int(ts),
            inputs={"pair": None, "source": "sys_monitor.light_poll", "range": {"end_ms": int(ts)}},
            evidence=[{"type": "sys_monitor_light_poll", "health": health, "metrics": metrics, "tracker": tracker, "signals": signals}],
            outputs={"triggered": True, "alerts": alerts, "idempotency_key": f"sysmon.light|{int(ts)//3600000}"},
            doc_refs=_agent_doc_refs_48_default(),
        )
        _sys_monitor_auto_maybe_trigger_bugfix(now_ms=int(ts), alerts=alerts, trace_id=str(trace_id))
    return {"ok": True, "ts": int(ts), "trace_id": str(trace_id), "triggered": bool(triggered), "alerts": alerts}


def _sys_monitor_auto_global_poll_run(now_ms: int) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    try:
        lookback_days = float(AUTOMATION.get("sys_monitor_global_poll_lookback_days", 7.0) or 7.0)
    except Exception:
        lookback_days = 7.0
    lookback_days = float(max(0.1, min(3650.0, lookback_days)))
    try:
        timerange_days = int(AUTOMATION.get("sys_monitor_global_poll_timerange_days", 60) or 60)
    except Exception:
        timerange_days = 60
    timerange_days = int(max(1, min(3650, int(timerange_days))))
    try:
        timeout_sec = float(AUTOMATION.get("sys_monitor_global_poll_timeout_sec", 1800) or 1800)
    except Exception:
        timeout_sec = 1800.0
    timeout_sec = float(max(30.0, min(6 * 3600.0, timeout_sec)))

    trace_id = hashlib.sha256(f"sysmon.global|{datetime.fromtimestamp(ts/1000, timezone.utc).strftime('%Y%m%d')}".encode("utf-8")).hexdigest()[:32]
    pair = _system_monitor_default_pair()
    config_path = "user_data/config_local_backtest.json"
    strategy = _system_monitor_default_strategy(config_path)
    timerange = _agent_pick_timerange_for_config(config_path=config_path, days=int(timerange_days))

    try:
        st = TRACKER_STATE.get("system_monitor") if isinstance(TRACKER_STATE.get("system_monitor"), dict) else {}
        if not isinstance(st, dict):
            st = {}
        st["last_trace_id"] = str(trace_id)
        st["active_trace_id"] = str(trace_id)
        st["last_run_ms"] = int(ts)
        st["source"] = "scheduler"
        TRACKER_STATE["system_monitor"] = st
    except Exception:
        pass

    link_rep = None
    try:
        link_rep = _system_monitor_link_check(pair=str(pair), lookback_days=float(lookback_days), trace_id=str(trace_id))
    except Exception as e:
        link_rep = {"ok": False, "ts": int(_now_ms()), "trace_id": str(trace_id), "error": str(e)}
    try:
        link_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="system_monitor_link_check.json", obj=link_rep)
        if link_path and isinstance(link_rep, dict):
            link_rep["artifact_files"] = {"system_monitor_link_check_json": link_path}
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="system_monitor_link_check", artifact=(link_rep if isinstance(link_rep, dict) else {"ok": False, "ts": int(_now_ms()), "trace_id": str(trace_id), "error": "link_check_bad_type"}))
    except Exception:
        pass

    faq_hits: List[str] = []
    cfg_patch = None
    preauth: Dict[str, Any] = {"ok": False, "allowed": False}
    try:
        faq_hits = _system_monitor_faq_hits_from_link_report(link_rep if isinstance(link_rep, dict) else None)
    except Exception:
        faq_hits = []
    try:
        cfg_patch = _system_monitor_stopgap_config_patch(faq_hits=faq_hits)
    except Exception:
        cfg_patch = None
    try:
        if isinstance(cfg_patch, dict) and cfg_patch:
            lvl = _config_patch_level_info(cfg_patch, base_cfg=CONFIG)
            preauth = {"ok": True, "allowed": (str(lvl.get("level") or "").strip().upper() == "A"), "level_info": _json_sanitize(lvl)}
    except Exception:
        preauth = {"ok": False, "allowed": False}

    bt_rep = None
    try:
        bt_rep = _run_backtest(config_path, timerange, strategy=str(strategy), strategy_path=None, env_overrides=None, timeout_sec=float(timeout_sec))
    except Exception as e:
        bt_rep = {"ok": False, "error": str(e)}
    try:
        bt_art = {"ok": bool(bt_rep.get("ok")) if isinstance(bt_rep, dict) else False, "ts": int(_now_ms()), "trace_id": str(trace_id), "pair": str(pair), "strategy": str(strategy), "timerange": str(timerange), "result": _json_sanitize(bt_rep)}
        bt_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="system_monitor_backtest.json", obj=bt_art)
        if bt_path and isinstance(bt_art, dict):
            bt_art["artifact_files"] = {"system_monitor_backtest_json": bt_path}
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="system_monitor_backtest", artifact=bt_art)
    except Exception:
        pass

    try:
        st = TRACKER_STATE.get("sys_monitor_auto") if isinstance(TRACKER_STATE.get("sys_monitor_auto"), dict) else {}
        st2 = dict(st) if isinstance(st, dict) else {}
        st2["last_global_ms"] = int(ts)
        st2["last_global_trace_id"] = str(trace_id)
        TRACKER_STATE["sys_monitor_auto"] = st2
    except Exception:
        pass

    alerts = []
    try:
        if isinstance(link_rep, dict) and link_rep.get("ok") is False:
            alerts.append({"id": "link_check_failed", "severity": "P1", "value": link_rep.get("error"), "threshold": "ok=true"})
    except Exception:
        pass
    try:
        if isinstance(bt_rep, dict) and bt_rep.get("ok") is False:
            alerts.append({"id": "backtest_failed", "severity": "P1", "value": bt_rep.get("error"), "threshold": "ok=true"})
    except Exception:
        pass
    try:
        if faq_hits:
            alerts.append({"id": "faq_hits", "severity": "P2", "value": ",".join([str(x) for x in faq_hits[:12]]), "threshold": "none"})
    except Exception:
        pass

    if alerts:
        _agent_emit_envelope_event(
            event="monitor.alerts.trigger",
            trace_id=str(trace_id),
            severity="warn",
            intent_level="L0",
            ts_ms=int(ts),
            inputs={"pair": str(pair), "source": "sys_monitor.global_poll", "lookback_days": float(lookback_days), "timerange_days": int(timerange_days)},
            evidence=[{"type": "sys_monitor_global_poll", "link_check": link_rep, "backtest": bt_rep, "faq_hits": faq_hits, "preauthorized": preauth, "proposed_config_patch": cfg_patch}],
            outputs={"triggered": True, "alerts": alerts, "idempotency_key": f"sysmon.global|{datetime.fromtimestamp(ts/1000, timezone.utc).strftime('%Y%m%d')}"},
            doc_refs=_agent_doc_refs_48_default(),
        )
        _sys_monitor_auto_maybe_trigger_bugfix(now_ms=int(ts), alerts=alerts, trace_id=str(trace_id))

    return {"ok": True, "ts": int(ts), "trace_id": str(trace_id), "pair": str(pair), "strategy": str(strategy), "timerange": str(timerange), "lookback_days": float(lookback_days), "timerange_days": int(timerange_days), "link_check": _json_sanitize(link_rep), "backtest": _json_sanitize(bt_rep), "faq_hits": [str(x) for x in faq_hits if str(x).strip()][:12], "preauthorized": _json_sanitize(preauth), "proposed_config_patch": (_json_sanitize(cfg_patch) if isinstance(cfg_patch, dict) else None)}

def _ensure_scheduler_started():
    try:
        if bool(str(os.environ.get("PYTEST_CURRENT_TEST", "") or "").strip()):
            return
    except Exception:
        pass
    try:
        flag = bool(globals().get("_SCHEDULER_STARTED", False))
    except Exception:
        flag = False
    enabled = os.environ.get("SCHEDULER_ENABLED", "1")
    try:
        enabled = str(enabled).strip().lower() in ("1", "true", "yes", "on")
    except Exception:
        enabled = True
    th = globals().get("_SCHEDULER_THREAD")
    try:
        th_alive = bool(th is not None and hasattr(th, "is_alive") and th.is_alive())
    except Exception:
        th_alive = False

    if enabled and ((not flag) or (not th_alive)):
        try:
            t = threading.Thread(target=_scheduler_loop, daemon=True)
            t.start()
            globals()["_SCHEDULER_STARTED"] = True
            globals()["_SCHEDULER_THREAD"] = t
        except Exception:
            pass


def _ensure_carry_worker_started():
    try:
        if bool(str(os.environ.get("PYTEST_CURRENT_TEST", "") or "").strip()):
            return
    except Exception:
        pass
    try:
        import carry_service

        carry_service.ensure_carry_worker_started(sys.modules[__name__])
    except Exception:
        pass


def _quant_btcalts_strategy_mode_default() -> str:
    try:
        v = str(CONFIG.get("quant_auto_btcalts_strategy_mode", "B") or "B").strip().upper()
    except Exception:
        v = "B"
    if v not in ("A", "B", "C"):
        v = "B"
    return v


def _quant_auto_btcalts_tick(now_ms: int) -> Dict[str, Any]:
    ts_ms = int(now_ms or _now_ms())
    try:
        qa_mode = str(CONFIG.get("quant_auto_mode", "off") or "off").strip().lower()
    except Exception:
        qa_mode = "off"
    if qa_mode not in ("off", "monitor", "paper", "live"):
        qa_mode = "off"
    enabled = bool(CONFIG.get("quant_auto_enabled", False)) and bool(CONFIG.get("quant_auto_btcalts_enabled", False))

    try:
        venue = str(CONFIG.get("execution_venue") or "aster").strip().lower() or "aster"
    except Exception:
        venue = "aster"

    execute = bool(qa_mode == "live")
    live_blocked_reason = None
    token_required = str(os.environ.get("WEBHOOK_EXECUTE_TOKEN", "") or "").strip()
    if bool(execute):
        if not bool(_live_trading_enabled_for_owner("quant")):
            execute = False
            live_blocked_reason = "quant_live_trading_disabled"
        elif bool(CONFIG.get("dry_run", True)):
            execute = False
            live_blocked_reason = "dry_run_enabled"
        elif str(venue) == "aster" and (not _aster_enabled_for_trading_for_owner("quant")):
            execute = False
            live_blocked_reason = "aster_trading_disabled"

    try:
        tf = str(_quant_pairs_btcalt_params().get("timeframe") or "1h").strip().lower() or "1h"
    except Exception:
        tf = "1h"
    if tf == "60m":
        tf = "1h"

    tier_auto = _quant_btcalts_strategy_mode_default()

    hf_plan_default = None
    hf_plan_override = False
    try:
        raw_hf = CONFIG.get("quant_auto_btcalts_btc_hedge_frac")
        if raw_hf is not None and str(raw_hf).strip() != "":
            hf0 = float(raw_hf)
            if math.isfinite(float(hf0)):
                hf_plan_default = float(hf0)
                hf_plan_override = True
    except Exception:
        hf_plan_default = None
    if hf_plan_default is None and tier_auto in ("B", "C"):
        try:
            raw_hf = CONFIG.get("quant_pairs_btcalt_btc_hedge_frac")
            if raw_hf is None:
                raw_hf = CONFIG.get("btcalts_btc_hedge_frac")
            if raw_hf is not None and str(raw_hf).strip() != "":
                hf0 = float(raw_hf)
                if math.isfinite(float(hf0)):
                    hf_plan_default = float(hf0)
                    hf_plan_override = True
        except Exception:
            hf_plan_default = None
    if hf_plan_default is None:
        if tier_auto == "A":
            hf_plan_default = 0.0
        elif tier_auto == "B":
            hf_plan_default = float(CONFIG.get("quant_auto_btcalts_net_hedge_frac", 0.75) or 0.75)
        else:
            hf_plan_default = 1.0
    hf_plan_default = float(_clip(float(hf_plan_default), 0.0, 1.0))

    try:
        macro_trend_required = bool(CONFIG.get("quant_auto_btcalts_macro_trend_required", False))
    except Exception:
        macro_trend_required = False
    try:
        z_bias_min = float(CONFIG.get("quant_auto_btcalts_z_bias_min", 1.5) or 1.5)
    except Exception:
        z_bias_min = 1.5
    z_bias_min = float(_clip(float(z_bias_min), 0.0, 20.0))
    try:
        z_bias_weight = float(CONFIG.get("quant_auto_btcalts_z_bias_weight", 0.25) or 0.25)
    except Exception:
        z_bias_weight = 0.25
    z_bias_weight = float(_clip(float(z_bias_weight), 0.0, 5.0))

    try:
        dynamic_hedge_enabled = bool(CONFIG.get("quant_auto_btcalts_dynamic_hedge_enabled", False))
    except Exception:
        dynamic_hedge_enabled = False
    dynamic_hedge_enabled = bool(dynamic_hedge_enabled and float(hf_plan_default) > 0.0)
    try:
        dynamic_hedge_step = float(CONFIG.get("quant_auto_btcalts_dynamic_hedge_step", 0.1) or 0.1)
    except Exception:
        dynamic_hedge_step = 0.1
    dynamic_hedge_step = float(_clip(float(dynamic_hedge_step), 0.01, 1.0))

    try:
        nontrend_notional_mult = float(CONFIG.get("quant_auto_btcalts_notional_nontrend_mult", 1.0) or 1.0)
    except Exception:
        nontrend_notional_mult = 1.0
    nontrend_notional_mult = float(_clip(float(nontrend_notional_mult), 0.0, 1.0))

    try:
        open_per_tick_nontrend = int(CONFIG.get("quant_auto_btcalts_open_per_tick_nontrend", 1) or 1)
    except Exception:
        open_per_tick_nontrend = 1
    open_per_tick_nontrend = int(max(1, min(10, int(open_per_tick_nontrend))))

    try:
        max_btcalts_nontrend_cfg = int(CONFIG.get("quant_auto_btcalts_max_open_pairs_nontrend", 1) or 1)
    except Exception:
        max_btcalts_nontrend_cfg = 1
    max_btcalts_nontrend_cfg = int(max(1, min(200, int(max_btcalts_nontrend_cfg))))

    cooldown_map = TRACKER_STATE.get("quant_auto_btcalts_cooldown")
    if not isinstance(cooldown_map, dict):
        cooldown_map = {}
        TRACKER_STATE["quant_auto_btcalts_cooldown"] = cooldown_map

    macro = None
    try:
        macro = {
            "btc_dir": _macro_btc_dir_snapshot(timeframe="1h", horizon_h=12, short_n=3),
        }
    except Exception:
        macro = None
    try:
        h_ms = 3_600_000
        last_closed_1h = int((int(ts_ms) // int(h_ms)) * int(h_ms) - 1)
        ts_shape = int(last_closed_1h if last_closed_1h > 0 else ts_ms)
        try:
            update_h = int(CONFIG.get("entry_macro_btceth_shape_update_hours", 12) or 12)
        except Exception:
            update_h = 12
        update_h = int(max(1, min(24 * 30, int(update_h))))
        if int(update_h) > 1:
            try:
                t0 = int(_macro_align_nhour_close_ts(int(ts_shape), int(update_h)))
                if t0 > 0:
                    ts_shape = int(t0)
            except Exception:
                pass
        shape_snap = _entry_macro_btceth_shape_at(int(ts_shape), allow_disabled=True)
        if isinstance(macro, dict):
            macro["shape"] = shape_snap
    except Exception:
        pass

    def _resp_json(obj: Any) -> Dict[str, Any]:
        r = obj
        if isinstance(r, tuple) and r:
            r = r[0]
        if hasattr(r, "get_json"):
            try:
                d = r.get_json(silent=True)
                if isinstance(d, dict):
                    return d
            except Exception:
                pass
        try:
            raw = r.get_data(as_text=True)
        except Exception:
            raw = None
        if raw:
            try:
                d2 = json.loads(raw)
                if isinstance(d2, dict):
                    return d2
            except Exception:
                pass
        return {"ok": False, "error": "bad_response"}

    def _call_status(alt: str) -> Dict[str, Any]:
        try:
            with app.test_request_context(
                "/quant/pairs/btcalt/status",
                method="GET",
                query_string={"alt": str(alt), "timeframe": str(tf), "limit": 1200, "strategy_mode": str(tier_auto)},
                environ_base={"REMOTE_ADDR": "127.0.0.1"},
            ):
                return _resp_json(quant_pairs_btcalt_status())
        except Exception as e:
            return {"ok": False, "error": str(e), "alt": str(alt), "timeframe": str(tf)}

    def _call_exec_open(alt: str, direction: str, notional_usdc: float, btc_hedge_frac: float, mode: str = None) -> Dict[str, Any]:
        payload = {
            "venue": str(venue),
            "execute": bool(execute),
            "confirm_execute": True,
            "tag": "quant_auto_btcalts",
            "strategy_id": "quant_auto_btcalts",
            "timeframe": str(tf),
            "alt": str(alt),
            "direction": str(direction),
            "mode": (str(mode).strip().lower() if mode is not None and str(mode).strip() != "" else None),
            "notional_usdc": float(notional_usdc),
            "strategy_mode": str(tier_auto),
            "btc_hedge_frac": float(btc_hedge_frac),
        }
        headers = {}
        if bool(payload.get("execute")) and bool(CONFIG.get("execute_guard_enabled", True)) and token_required:
            headers["X-Execute-Token"] = token_required
        try:
            with app.test_request_context(
                "/execution/pairs/btcalt/market_open",
                method="POST",
                json=payload,
                headers=headers,
                environ_base={"REMOTE_ADDR": "127.0.0.1"},
            ):
                return _resp_json(execution_pairs_btcalt_market_open())
        except Exception as e:
            return {"ok": False, "error": str(e), "alt": str(alt), "direction": str(direction)}

    def _call_exec_close(alt: str, force_orphan_close: bool = False) -> Dict[str, Any]:
        payload = {
            "venue": str(venue),
            "execute": bool(execute),
            "confirm_execute": True,
            "tag": "quant_auto_btcalts_close",
            "alt": str(alt),
        }
        if bool(force_orphan_close):
            payload["force_orphan_close"] = True
        headers = {}
        if bool(payload.get("execute")) and bool(CONFIG.get("execute_guard_enabled", True)) and token_required:
            headers["X-Execute-Token"] = token_required
        try:
            with app.test_request_context(
                "/execution/pairs/btcalt/market_close",
                method="POST",
                json=payload,
                headers=headers,
                environ_base={"REMOTE_ADDR": "127.0.0.1"},
            ):
                return _resp_json(execution_pairs_btcalt_market_close())
        except Exception as e:
            return {"ok": False, "error": str(e), "alt": str(alt)}

    op = TRACKER_STATE.get("quant_open_positions")
    if not isinstance(op, dict):
        op = {}
        TRACKER_STATE["quant_open_positions"] = op

    def _pos_is_btcalts(pos: Any) -> bool:
        if not isinstance(pos, dict):
            return False
        try:
            sid = str(pos.get("strategy_id") or "").strip().lower()
        except Exception:
            sid = ""
        try:
            tag = str(pos.get("tag") or "").strip().lower()
        except Exception:
            tag = ""
        return ("btcalt" in sid) or ("btcalt" in tag) or ("quant_auto_btcalts" in sid) or ("quant_auto_btcalts" in tag)

    active_alts: List[str] = []
    orphan_alts: List[str] = []
    try:
        for k, v in op.items():
            kk = str(k or "").strip().upper()
            if (not kk) or kk == "BTC-PERP":
                continue
            if not kk.endswith("-PERP"):
                continue
            coin = kk[:-5]
            if not coin:
                continue
            if _pos_is_btcalts(v):
                if coin not in active_alts:
                    active_alts.append(str(coin))
                continue
            if not isinstance(v, dict):
                continue
            try:
                sid0 = str(v.get("strategy_id") or "").strip()
            except Exception:
                sid0 = ""
            try:
                tag0 = str(v.get("tag") or "").strip()
            except Exception:
                tag0 = ""
            if sid0 or tag0:
                continue
            try:
                sys0 = str(v.get("system_id") or "").strip().lower()
            except Exception:
                sys0 = ""
            try:
                owner0 = str(v.get("ab_owner") or v.get("owner") or "").strip().lower()
            except Exception:
                owner0 = ""
            if sys0 != "quant" and owner0 != "quant":
                continue
            if coin in ("BTC", "ETH", "USDT", "USDC"):
                continue
            if coin not in orphan_alts:
                orphan_alts.append(str(coin))
    except Exception:
        active_alts = []
        orphan_alts = []
    btcalts_active_pairs = int(len(active_alts))
    orphan_set = {str(x).strip().upper() for x in list(orphan_alts) if str(x).strip()}

    desired = {"action": "hold", "reason": None, "alt": (str(active_alts[0]) if active_alts else None), "direction": None, "score": None}
    decisions: List[Dict[str, Any]] = []

    rebalance_out = None

    one_leg_grace_sec = None
    try:
        one_leg_grace_sec = CONFIG.get("quant_auto_btcalts_one_leg_grace_sec")
    except Exception:
        one_leg_grace_sec = None
    if one_leg_grace_sec is None:
        try:
            one_leg_grace_sec = CONFIG.get("quant_pairs_btcalt_one_leg_grace_sec")
        except Exception:
            one_leg_grace_sec = None
    if one_leg_grace_sec is None:
        one_leg_grace_sec = 300
    try:
        one_leg_grace_sec = float(one_leg_grace_sec)
    except Exception:
        one_leg_grace_sec = 300.0
    one_leg_grace_sec = float(_clip(float(one_leg_grace_sec), 0.0, 3600.0))
    one_leg_grace_ms = int(one_leg_grace_sec * 1000.0)

    try:
        one_leg_retry_sec = float(CONFIG.get("quant_auto_btcalts_one_leg_retry_sec", 60.0) or 60.0)
    except Exception:
        one_leg_retry_sec = 60.0
    if tier_auto in ("B", "C"):
        try:
            v = CONFIG.get("quant_auto_btcalts_one_leg_retry_sec_bc")
            if v is None:
                v = CONFIG.get("quant_pairs_btcalt_one_leg_retry_sec_bc")
            if v is not None and str(v).strip() != "":
                one_leg_retry_sec = float(v)
            else:
                one_leg_retry_sec = 120.0
        except Exception:
            one_leg_retry_sec = 120.0
    one_leg_retry_sec = float(_clip(float(one_leg_retry_sec), 1.0, 600.0))
    one_leg_retry_ms = int(one_leg_retry_sec * 1000.0)

    pending_hedges = TRACKER_STATE.get("quant_auto_btcalts_pending_hedges")
    if not isinstance(pending_hedges, dict):
        pending_hedges = {}
        TRACKER_STATE["quant_auto_btcalts_pending_hedges"] = pending_hedges
    one_leg_last_try = TRACKER_STATE.get("quant_auto_btcalts_one_leg_last_try_ms")
    if not isinstance(one_leg_last_try, dict):
        one_leg_last_try = {}
        TRACKER_STATE["quant_auto_btcalts_one_leg_last_try_ms"] = one_leg_last_try

    closes: List[Dict[str, Any]] = []
    for a0 in list(active_alts) + list(orphan_alts):
        st0 = _call_status(str(a0))
        hedge = None
        hedge_skip = None
        try:
            pos_pack = (st0.get("position") if isinstance(st0, dict) else None)
        except Exception:
            pos_pack = None
        if (
            isinstance(pos_pack, dict)
            and bool(pos_pack.get("any"))
            and (not bool(pos_pack.get("pair_ok")))
            and float(one_leg_grace_ms) > 0.0
            and float(hf_plan_default) > 0.0
        ):
            legs_pack = (pos_pack.get("legs") if isinstance(pos_pack.get("legs"), dict) else {})
            if isinstance(legs_pack, dict) and ("alt" in legs_pack) and ("btc" not in legs_pack):
                pos_alt = None
                try:
                    pos_alt = op.get(f"{str(a0).strip().upper()}-PERP")
                except Exception:
                    pos_alt = None
                tag_pos = None
                try:
                    tag_pos = (pos_alt.get("tag") if isinstance(pos_alt, dict) else None)
                except Exception:
                    tag_pos = None
                try:
                    entry_ts0 = pos_pack.get("entry_ts")
                except Exception:
                    entry_ts0 = None
                if entry_ts0 is None and isinstance(pos_alt, dict):
                    try:
                        entry_ts0 = pos_alt.get("entry_ts") or pos_alt.get("ts")
                    except Exception:
                        entry_ts0 = None
                if entry_ts0 is not None and tag_pos is not None and str(tag_pos).strip() != "":
                    try:
                        age_ms = int(ts_ms) - int(entry_ts0)
                    except Exception:
                        age_ms = 0
                    if int(age_ms) <= int(one_leg_grace_ms):
                        try:
                            last_try_ms = int(one_leg_last_try.get(str(tag_pos)) or 0)
                        except Exception:
                            last_try_ms = 0
                        if last_try_ms <= 0 or (int(ts_ms) - int(last_try_ms)) >= int(one_leg_retry_ms):
                            alt_side = ""
                            try:
                                alt_side = str((pos_alt or {}).get("side") or "").strip().lower()
                            except Exception:
                                alt_side = ""
                            btc_side = None
                            if alt_side == "long":
                                btc_side = "short"
                            elif alt_side == "short":
                                btc_side = "long"
                            notional_alt = 0.0
                            try:
                                notional_alt = float((pos_alt or {}).get("notional_usdc") or 0.0)
                            except Exception:
                                notional_alt = 0.0
                            beta_abs2 = 1.0
                            try:
                                beta_abs2 = float((pos_alt or {}).get("beta_abs") or 1.0)
                            except Exception:
                                beta_abs2 = 1.0
                            beta_abs2 = float(_clip(float(beta_abs2), 0.2, 5.0))
                            hf2 = float(hf_plan_default)
                            try:
                                if (pos_alt or {}).get("btc_hedge_frac") is not None:
                                    hf2 = float((pos_alt or {}).get("btc_hedge_frac"))
                            except Exception:
                                hf2 = float(hf_plan_default)
                            hf2 = float(_clip(float(hf2), 0.0, 1.0))
                            notional_btc2 = float(notional_alt) * float(beta_abs2) * float(hf2)
                            if btc_side is None or (not math.isfinite(float(notional_btc2))) or float(notional_btc2) <= 0.0:
                                hedge_skip = "invalid_hedge_params"
                            else:
                                if bool(execute) and str(venue).strip().lower() == "aster":
                                    pf_btc = None
                                    try:
                                        pf_btc = _aster_preflight_notional("BTC", float(notional_btc2))
                                    except Exception as e:
                                        pf_btc = {"ok": False, "reason": "preflight_error", "error": str(e)}
                                    if isinstance(pf_btc, dict) and pf_btc.get("ok") is False:
                                        hedge_skip = "btc_leg_preflight_reject"
                                    else:
                                        req_btc = None
                                        try:
                                            if isinstance(pf_btc, dict) and pf_btc.get("required_notional_usdc") is not None:
                                                req_btc = float(pf_btc.get("required_notional_usdc"))
                                        except Exception:
                                            req_btc = None
                                        if req_btc is not None and math.isfinite(float(req_btc)) and float(req_btc) > float(notional_btc2) + 1e-9:
                                            notional_btc2 = float(req_btc)
                                if hedge_skip is None:
                                    one_leg_last_try[str(tag_pos)] = int(ts_ms)
                                    try:
                                        retry_attempts = int(CONFIG.get("quant_auto_btcalts_btc_market_retry_attempts", 1) or 1)
                                    except Exception:
                                        retry_attempts = 1
                                    retry_attempts = int(max(1, min(5, int(retry_attempts))))
                                    try:
                                        retry_sleep_sec = float(CONFIG.get("quant_auto_btcalts_btc_market_retry_sleep_sec", 0.0) or 0.0)
                                    except Exception:
                                        retry_sleep_sec = 0.0
                                    retry_sleep_sec = float(_clip(float(retry_sleep_sec), 0.0, 5.0))

                                    for i_try in range(int(retry_attempts)):
                                        hedge, _ = _pairs_quant_open_leg(
                                            venue=str(venue),
                                            coin="BTC",
                                            side=str(btc_side),
                                            notional_usdc=float(notional_btc2),
                                            execute=bool(execute),
                                            tag=str(tag_pos),
                                            strategy_id="quant_auto_btcalts",
                                            maker=False,
                                            ignore_cooldown=True,
                                            ignore_post_close_freeze=True,
                                        )
                                        if isinstance(hedge, dict) and bool(hedge.get("ok")):
                                            break
                                        try:
                                            _aster_sync_record(update_orders=True)
                                        except Exception:
                                            pass
                                        try:
                                            opq = TRACKER_STATE.get("quant_open_positions")
                                            pos_btc = (opq.get("BTC-PERP") if isinstance(opq, dict) else None)
                                            if isinstance(pos_btc, dict):
                                                try:
                                                    sz_btc0 = float(pos_btc.get("base_sz", pos_btc.get("base_qty", 0.0)) or 0.0)
                                                except Exception:
                                                    sz_btc0 = 0.0
                                                if math.isfinite(float(sz_btc0)) and abs(float(sz_btc0)) > 1e-12:
                                                    hedge = {"ok": True, "position_detected": True, "position": _json_sanitize(pos_btc)}
                                                    break
                                        except Exception:
                                            pass
                                        if float(retry_sleep_sec) > 0.0 and i_try + 1 < int(retry_attempts):
                                            time.sleep(float(retry_sleep_sec))
                                    if isinstance(hedge, dict) and bool(hedge.get("ok")):
                                        try:
                                            opq = TRACKER_STATE.get("quant_open_positions")
                                            if isinstance(opq, dict) and isinstance(pos_alt, dict):
                                                pos_btc = opq.get("BTC-PERP")
                                                if isinstance(pos_btc, dict):
                                                    try:
                                                        pos_btc["pair_type"] = "btcalt"
                                                        pos_btc["pair_group"] = str(pos_alt.get("pair_group") or "")
                                                        pos_btc["alt"] = str(a0).strip().upper()
                                                        pos_btc["beta_abs"] = float(beta_abs2)
                                                        pos_btc["btc_hedge_frac"] = float(hf2)
                                                    except Exception:
                                                        pass
                                        except Exception:
                                            pass
                                        try:
                                            pending_hedges.pop(str(tag_pos), None)
                                        except Exception:
                                            pass
                    else:
                        hedge_skip = "one_leg_grace_expired"
                        try:
                            pending_hedges.pop(str(tag_pos), None)
                        except Exception:
                            pass
        act0 = str(st0.get("action") or "hold").strip().lower() if isinstance(st0, dict) else "hold"
        reason0 = (st0.get("reason") if isinstance(st0, dict) else None)
        d0 = {"action": str(act0), "reason": reason0, "alt": str(a0), "direction": None, "score": None, "hedge": (_json_sanitize(hedge) if isinstance(hedge, dict) else None), "hedge_skip": hedge_skip}
        decisions.append(d0)
        if act0 == "stop":
            desired["action"] = "stop"
            desired["reason"] = reason0
        elif act0 == "exit" and str(desired.get("action")) not in ("stop",):
            desired["action"] = "exit"
            desired["reason"] = reason0
        if act0 in ("exit", "stop"):
            if qa_mode in ("paper", "live") and bool(enabled):
                force_orphan_close = bool(str(a0).strip().upper() in orphan_set)
                close_out = _call_exec_close(str(a0), force_orphan_close=bool(force_orphan_close))
                if bool(close_out.get("ok")):
                    try:
                        cd_bars = int(CONFIG.get("quant_auto_btcalts_cooldown_bars", 12) or 12)
                    except Exception:
                        cd_bars = 12
                    cd_bars = int(max(0, min(2000, int(cd_bars))))
                    try:
                        cd_ms = int(_hl_interval_to_ms(str(tf))) * int(cd_bars)
                    except Exception:
                        cd_ms = 0
                    if cd_ms > 0:
                        cooldown_map[str(a0).upper().strip()] = int(ts_ms + int(cd_ms))
                closes.append({"alt": str(a0), "decision": dict(d0), "close": close_out})
            else:
                closes.append({"alt": str(a0), "decision": dict(d0), "close": None})

    if closes:
        return {
            "ok": True,
            "ts": int(ts_ms),
            "mode": str(qa_mode),
            "enabled": bool(enabled),
            "venue": str(venue),
            "execute": bool(execute),
            "live_blocked_reason": live_blocked_reason,
            "macro": macro,
            "position": ({"alt": str(active_alts[0])} if active_alts else None),
            "positions": [{"alt": str(x)} for x in active_alts],
            "decision": dict(desired),
            "decisions": decisions,
            "closes": closes,
            "rebalance": None,
        }

    if qa_mode == "off" or (not bool(enabled)):
        return {
            "ok": True,
            "ts": int(ts_ms),
            "mode": str(qa_mode),
            "enabled": bool(enabled),
            "venue": str(venue),
            "execute": bool(execute),
            "live_blocked_reason": live_blocked_reason,
            "macro": macro,
            "position": None,
            "decision": dict(desired),
            "rebalance": None,
        }

    try:
        max_total = int(CONFIG.get("quant_auto_max_open_pairs_total", 0) or 0)
    except Exception:
        max_total = 0
    try:
        max_btcalts_cfg = int(CONFIG.get("quant_auto_btcalts_max_open_pairs", 1) or 1)
    except Exception:
        max_btcalts_cfg = 1
    max_total = int(max(0, min(200, int(max_total))))
    max_btcalts_cfg = int(max(1, min(200, int(max_btcalts_cfg))))
    max_btcalts = int(max_btcalts_cfg)
    max_btcalts_nontrend = int(min(int(max_btcalts), int(max_btcalts_nontrend_cfg)))

    btc_pos_any = op.get("BTC-PERP")
    if isinstance(btc_pos_any, dict) and _pos_is_btcalts(btc_pos_any) and (not active_alts):
        return {
            "ok": True,
            "ts": int(ts_ms),
            "mode": str(qa_mode),
            "enabled": bool(enabled),
            "venue": str(venue),
            "execute": bool(execute),
            "live_blocked_reason": live_blocked_reason,
            "macro": macro,
            "position": None,
            "decision": dict(desired),
            "blocked": "dangling_btc_leg",
            "rebalance": None,
        }

    if float(hf_plan_default) > 0.0 and isinstance(btc_pos_any, dict) and (not _pos_is_btcalts(btc_pos_any)):
        return {
            "ok": True,
            "ts": int(ts_ms),
            "mode": str(qa_mode),
            "enabled": bool(enabled),
            "venue": str(venue),
            "execute": bool(execute),
            "live_blocked_reason": live_blocked_reason,
            "macro": macro,
            "position": None,
            "decision": dict(desired),
            "blocked": "btc_leg_busy",
            "rebalance": None,
        }

    def _call_exec_btc_rebalance(side: str, notional_usdc: float, ignore_cooldown: bool) -> Dict[str, Any]:
        try:
            idem_bucket = int(ts_ms) // 60000
        except Exception:
            idem_bucket = int(_now_ms()) // 60000
        payload = {
            "coin": "BTC",
            "side": str(side),
            "notional_usdc": float(notional_usdc),
            "execute": bool(execute),
            "confirm_execute": True,
            "tag": "quant_auto_btcalts_rebalance",
            "strategy_id": "quant_auto_btcalts",
            "idempotency_key": f"quant_auto_btcalts_rebalance|{str(side)}|{int(idem_bucket)}",
            "ignore_cooldown": bool(ignore_cooldown),
            "ab_owner": "quant",
            "owner_contrib": {"quant": 1.0},
        }
        headers = {}
        if bool(payload.get("execute")) and bool(CONFIG.get("execute_guard_enabled", True)) and token_required:
            headers["X-Execute-Token"] = token_required
        try:
            if str(venue) == "hyperliquid":
                with app.test_request_context(
                    "/execution/hyperliquid/market_open",
                    method="POST",
                    json=payload,
                    headers=headers,
                    environ_base={"REMOTE_ADDR": "127.0.0.1"},
                ):
                    return _resp_json(hyperliquid_market_open())
            with app.test_request_context(
                "/execution/aster/market_open",
                method="POST",
                json=payload,
                headers=headers,
                environ_base={"REMOTE_ADDR": "127.0.0.1"},
            ):
                return _resp_json(aster_market_open())
        except Exception as e:
            return {"ok": False, "error": str(e), "coin": "BTC", "side": str(side), "notional_usdc": float(notional_usdc)}

    rb_state = TRACKER_STATE.get("quant_auto_btcalts_rebalance_state")
    if not isinstance(rb_state, dict):
        rb_state = {}
        TRACKER_STATE["quant_auto_btcalts_rebalance_state"] = rb_state
    rb_info = None
    rb_exec = None
    rb_skip = None
    combo0 = None

    try:
        rb_enabled = bool(CONFIG.get("quant_auto_btcalts_rebalance_execute", CONFIG.get("quant_auto_btcalts_rebalance_enabled", False)))
    except Exception:
        rb_enabled = False
    try:
        rb_min = float(CONFIG.get("quant_auto_btcalts_rebalance_min_notional_usdc", 50.0) or 50.0)
    except Exception:
        rb_min = 50.0
    rb_min = float(max(0.0, float(rb_min)))
    try:
        rb_cd_s = float(CONFIG.get("quant_auto_btcalts_rebalance_cooldown_sec", 600) or 600)
    except Exception:
        rb_cd_s = 600.0
    rb_cd_s = float(_clip(float(rb_cd_s), 0.0, 24.0 * 3600.0))
    rb_cd_ms = int(round(float(rb_cd_s) * 1000.0))
    try:
        rb_max = float(CONFIG.get("quant_auto_btcalts_rebalance_max_notional_usdc", 0.0) or 0.0)
    except Exception:
        rb_max = 0.0
    rb_max = float(max(0.0, float(rb_max)))
    try:
        rb_ignore_cd = bool(CONFIG.get("quant_auto_btcalts_rebalance_ignore_cooldown", False))
    except Exception:
        rb_ignore_cd = False

    if qa_mode in ("monitor", "paper", "live") and bool(enabled):
        btc_pos = op.get("BTC-PERP")
        if isinstance(btc_pos, dict) and (not _pos_is_btcalts(btc_pos)):
            rb_skip = "btc_leg_busy"
        else:
            try:
                combo0 = _quant_pairs_combo_supervision_internal(now_ms=int(ts_ms))
            except Exception as e:
                combo0 = {"ok": False, "error": str(e)}

            try:
                rb_info = (combo0.get("state") if isinstance(combo0, dict) else None)
            except Exception:
                rb_info = None
            if isinstance(combo0, dict) and isinstance(rb_info, dict):
                try:
                    needed = bool(rb_info.get("rebalance_needed", False))
                except Exception:
                    needed = False
                try:
                    delta0 = float(rb_info.get("rebalance_delta_btc_leg_usdc") or 0.0)
                except Exception:
                    delta0 = 0.0

                if not bool(active_alts):
                    rb_skip = "no_active_alts"
                elif (not needed) or (not math.isfinite(float(delta0))) or abs(float(delta0)) <= 0.0:
                    rb_skip = "not_needed"
                else:
                    try:
                        last_rb = int(rb_state.get("last_ms") or 0)
                    except Exception:
                        last_rb = 0
                    if last_rb > 0 and int(rb_cd_ms) > 0 and (int(ts_ms) - int(last_rb)) < int(rb_cd_ms):
                        rb_skip = "cooldown"
                    else:
                        if float(rb_max) > 0.0:
                            delta0 = float(math.copysign(min(abs(float(delta0)), float(rb_max)), float(delta0)))

                        cur_signed = 0.0
                        try:
                            cur_signed = float(rb_info.get("net_btc_leg_usdc") or 0.0)
                        except Exception:
                            cur_signed = 0.0
                        if (not math.isfinite(float(cur_signed))):
                            cur_signed = 0.0

                        desired_signed = float(cur_signed) + float(delta0)
                        cur_abs = abs(float(cur_signed))
                        desired_abs = abs(float(desired_signed))
                        add_gross = max(0.0, float(desired_abs) - float(cur_abs))

                        pool = None
                        cap0 = 0.0
                        used0 = 0.0
                        try:
                            pool = _quant_pairs_btcalt_sub_pool_snapshot(now_ms=int(ts_ms))
                        except Exception:
                            pool = None
                        try:
                            cap0 = float((pool or {}).get("cap_usdc") or 0.0)
                        except Exception:
                            cap0 = 0.0
                        try:
                            used0 = float((pool or {}).get("used_usdc") or 0.0)
                        except Exception:
                            used0 = 0.0
                        free0 = float(cap0) - float(used0)

                        delta1 = float(delta0)
                        if math.isfinite(float(cap0)) and float(cap0) > 0.0 and math.isfinite(float(used0)) and float(free0) < float(add_gross) - 1e-9:
                            free_add = float(max(0.0, float(free0)))
                            abs_cap = float(cur_abs) + float(free_add)
                            desired_abs2 = min(float(desired_abs), float(abs_cap))
                            desired_signed2 = float(math.copysign(float(desired_abs2), float(desired_signed)))
                            delta1 = float(desired_signed2) - float(cur_signed)

                        if (not math.isfinite(float(delta1))) or abs(float(delta1)) < float(rb_min) - 1e-9:
                            rb_skip = "delta_too_small"
                        else:
                            side_rb = ("long" if float(delta1) > 0.0 else "short")
                            ntl_rb = abs(float(delta1))
                            if bool(rb_enabled) and qa_mode in ("paper", "live"):
                                rb_exec = _call_exec_btc_rebalance(side=str(side_rb), notional_usdc=float(ntl_rb), ignore_cooldown=bool(rb_ignore_cd))
                                if isinstance(rb_exec, dict) and bool(rb_exec.get("ok", False)):
                                    rb_state["last_ms"] = int(ts_ms)
                            else:
                                rb_exec = None
                                rb_skip = "disabled"

                            rb_state["last_info"] = {
                                "ts": int(ts_ms),
                                "delta_btc_leg_usdc": float(delta1),
                                "side": str(side_rb),
                                "notional_usdc": float(ntl_rb),
                                "execute": bool(execute),
                                "venue": str(venue),
                                "resp": (_json_sanitize(rb_exec) if isinstance(rb_exec, dict) else None),
                            }

    rebalance_out = {
        "enabled": bool(rb_enabled),
        "min_notional_usdc": float(rb_min),
        "cooldown_sec": float(rb_cd_s),
        "max_notional_usdc": float(rb_max),
        "ignore_cooldown": bool(rb_ignore_cd),
        "combo": (_json_sanitize(combo0) if isinstance(combo0, dict) else None),
        "skip": (None if rb_skip is None else str(rb_skip)),
        "exec": (_json_sanitize(rb_exec) if isinstance(rb_exec, dict) else None),
    }

    open_slots = _ab_open_slots("quant")
    btcalts_active_pairs = int(len(active_alts))
    if (max_total > 0 and open_slots >= max_total) or (btcalts_active_pairs >= max_btcalts):
        return {
            "ok": True,
            "ts": int(ts_ms),
            "mode": str(qa_mode),
            "enabled": bool(enabled),
            "venue": str(venue),
            "execute": bool(execute),
            "live_blocked_reason": live_blocked_reason,
            "macro": macro,
            "position": None,
            "decision": dict(desired),
            "blocked": "capacity",
            "open_slots": int(open_slots),
            "max_total": int(max_total),
            "max_btcalts": int(max_btcalts),
            "max_btcalts_cfg": int(max_btcalts_cfg),
            "btcalts_active_pairs": int(btcalts_active_pairs),
            "rebalance": rebalance_out,
        }

    try:
        max_per_cluster = int(CONFIG.get("quant_auto_btcalts_max_per_cluster", 1) or 1)
    except Exception:
        max_per_cluster = 1
    max_per_cluster = int(max(1, min(50, int(max_per_cluster))))

    try:
        meta0 = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
        cand0 = (meta0.get("candidates") if isinstance(meta0, dict) else None)
        if (not isinstance(cand0, list)) or (not cand0):
            _build_universe_pipeline(int(ts_ms))
    except Exception:
        pass

    cluster_map: Dict[str, str] = {}
    liq_turnover_7d_median: Dict[str, float] = {}
    liq_depth_usdc: Dict[str, float] = {}
    try:
        meta = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
        cand_schema = (meta.get("candidates") if isinstance(meta, dict) else None)
        if isinstance(cand_schema, list):
            for it in cand_schema:
                if not isinstance(it, dict):
                    continue
                coin = str(it.get("coin") or "").upper().strip()
                if not coin:
                    continue
                cobj = it.get("cluster") if isinstance(it.get("cluster"), dict) else None
                cid = (cobj.get("cluster_id") if isinstance(cobj, dict) else None)
                if cid is not None:
                    cid_s = str(cid).strip()
                    if cid_s:
                        cluster_map[coin] = cid_s
                liq = it.get("liq") if isinstance(it.get("liq"), dict) else None
                if isinstance(liq, dict):
                    tv = liq.get("turnover_7d_median")
                    if tv is None:
                        tv = liq.get("turnover")
                    try:
                        t = float(tv or 0.0)
                    except Exception:
                        t = 0.0
                    if (not math.isfinite(float(t))) or float(t) < 0.0:
                        t = 0.0
                    liq_turnover_7d_median[coin] = float(t)

                    dv = None
                    if liq.get("depth_usdc") is not None:
                        dv = liq.get("depth_usdc")
                    elif liq.get("depth_1pct_usdc") is not None:
                        dv = liq.get("depth_1pct_usdc")
                    try:
                        d = float(dv or 0.0)
                    except Exception:
                        d = 0.0
                    if (not math.isfinite(float(d))) or float(d) < 0.0:
                        d = 0.0
                    liq_depth_usdc[coin] = float(d)
    except Exception:
        cluster_map = {}
        liq_turnover_7d_median = {}
        liq_depth_usdc = {}

    universe_consistency = {}
    universe_consistency_ok = True
    universe_consistency_reasons: List[str] = []
    try:
        meta = UNIVERSE_STATE.get("metadata") if isinstance(UNIVERSE_STATE, dict) else None
        cc = (meta.get("cluster_consistency") if isinstance(meta, dict) else None)
        if isinstance(cc, dict):
            universe_consistency = cc
            st = str(cc.get("status") or "").strip().lower()
            if st in ("warn", "breakdown", "error"):
                universe_consistency_ok = False
                universe_consistency_reasons.append(f"status={st}")
            try:
                thr_ari = float(CONFIG.get("quant_pairs_btcalt_universe_consistency_min_ari", 0.3) or 0.3)
            except Exception:
                thr_ari = 0.3
            try:
                thr_nmi = float(CONFIG.get("quant_pairs_btcalt_universe_consistency_min_nmi", 0.4) or 0.4)
            except Exception:
                thr_nmi = 0.4
            try:
                ari = float(cc.get("ari")) if cc.get("ari") is not None else None
            except Exception:
                ari = None
            try:
                nmi = float(cc.get("nmi")) if cc.get("nmi") is not None else None
            except Exception:
                nmi = None
            if math.isfinite(float(thr_ari)) and float(thr_ari) >= 0.0 and ari is not None and math.isfinite(float(ari)):
                if float(ari) + 1e-12 < float(thr_ari):
                    universe_consistency_ok = False
                    universe_consistency_reasons.append("ari_below_threshold")
            if math.isfinite(float(thr_nmi)) and float(thr_nmi) >= 0.0 and nmi is not None and math.isfinite(float(nmi)):
                if float(nmi) + 1e-12 < float(thr_nmi):
                    universe_consistency_ok = False
                    universe_consistency_reasons.append("nmi_below_threshold")
    except Exception:
        universe_consistency = {}
        universe_consistency_ok = True
        universe_consistency_reasons = []

    if not bool(universe_consistency_ok):
        return {
            "ok": True,
            "ts": int(ts_ms),
            "mode": str(qa_mode),
            "enabled": bool(enabled),
            "venue": str(venue),
            "execute": bool(execute),
            "live_blocked_reason": live_blocked_reason,
            "macro": macro,
            "position": None,
            "decision": dict(desired),
            "blocked": "universe_consistency",
            "universe_consistency": universe_consistency,
            "universe_consistency_reasons": universe_consistency_reasons,
            "rebalance": rebalance_out,
        }

    cluster_counts: Dict[str, int] = {}
    try:
        for k, v in op.items():
            kk = str(k or "").strip().upper()
            if (not kk) or (not kk.endswith("-PERP")) or kk == "BTC-PERP":
                continue
            if not _pos_is_btcalts(v):
                continue
            coin = kk[:-5]
            cid = cluster_map.get(str(coin))
            if not cid:
                continue
            cluster_counts[str(cid)] = int(cluster_counts.get(str(cid), 0)) + 1
    except Exception:
        cluster_counts = {}

    try:
        liq_top_n = int(max(10, min(50, int(max_alts) * 5)))
    except Exception:
        liq_top_n = 30
    try:
        candidates = _universe_btc_alt_candidates(int(liq_top_n))
    except TypeError:
        candidates = _universe_btc_alt_candidates()
    if not candidates:
        candidates = ["ETH", "SOL"]
    candidates = [str(x).upper().strip() for x in candidates if str(x).upper().strip() and str(x).upper().strip() not in ("BTC", "USDT", "USDC")]

    try:
        scan_n = int(CONFIG.get("quant_auto_btcalts_scan_n", 12) or 12)
    except Exception:
        scan_n = 12
    scan_n = int(max(1, min(50, int(scan_n))))

    try:
        capacity_turnover_frac = float(CONFIG.get("quant_auto_btcalts_capacity_turnover_frac", CONFIG.get("quant_pairs_btcalt_capacity_turnover_frac", 0.0)) or 0.0)
    except Exception:
        capacity_turnover_frac = 0.0
    capacity_turnover_frac = float(_clip(float(capacity_turnover_frac), 0.0, 1.0))

    try:
        capacity_depth_frac = float(CONFIG.get("quant_auto_btcalts_capacity_depth_frac", CONFIG.get("quant_pairs_btcalt_capacity_depth_frac", 0.0)) or 0.0)
    except Exception:
        capacity_depth_frac = 0.0
    capacity_depth_frac = float(_clip(float(capacity_depth_frac), 0.0, 1.0))

    trend_dir = 0
    trend_dir_w = 0
    trend_dir_d = 0
    risk_budget_tier = "neutral"
    crash_switch = False
    target_net_bias = 0.0
    max_net_exposure = 0.0
    allow_open_by_macro = True
    allow_addon_by_macro = False
    try:
        if isinstance(macro, dict) and isinstance(macro.get("btc_dir"), dict) and bool(macro["btc_dir"].get("ok")):
            v = macro["btc_dir"].get("dir_h")
            if v is None:
                v = macro["btc_dir"].get("dir")
            trend_dir = int(v or 0)
            trend_dir_w = int(macro["btc_dir"].get("dir_w") or 0)
            trend_dir_d = int(macro["btc_dir"].get("dir_d") or 0)
            risk_budget_tier = str(macro["btc_dir"].get("risk_budget_tier") or "neutral")
            crash_switch = bool(macro["btc_dir"].get("crash_switch"))
            if macro["btc_dir"].get("target_net_bias") is not None:
                target_net_bias = float(macro["btc_dir"].get("target_net_bias"))
            if macro["btc_dir"].get("max_net_exposure") is not None:
                max_net_exposure = float(macro["btc_dir"].get("max_net_exposure"))
            allow_open_by_macro = bool(macro["btc_dir"].get("allow_open", True))
            allow_addon_by_macro = bool(macro["btc_dir"].get("allow_addon", False))
    except Exception:
        trend_dir = 0
        trend_dir_w = 0
        trend_dir_d = 0
        risk_budget_tier = "neutral"
        crash_switch = False
        target_net_bias = 0.0
        max_net_exposure = 0.0
        allow_open_by_macro = True
        allow_addon_by_macro = False
    trend_dir = int(_clip(float(trend_dir), -1.0, 1.0))
    trend_dir_w = int(_clip(float(trend_dir_w), -1.0, 1.0))
    trend_dir_d = int(_clip(float(trend_dir_d), -1.0, 1.0))
    if int(trend_dir_w) == 0 and int(trend_dir) != 0:
        trend_dir_w = int(trend_dir)
    if int(trend_dir_d) == 0 and int(trend_dir) != 0:
        trend_dir_d = int(trend_dir)
    trend_dir_follow = int(trend_dir_w if int(trend_dir_w) != 0 else (trend_dir_d if int(trend_dir_d) != 0 else trend_dir))

    chg_dir = 0
    chg_strength = None
    try:
        if isinstance(macro, dict) and isinstance(macro.get("btc_dir"), dict) and bool(macro["btc_dir"].get("ok")):
            v = macro["btc_dir"].get("dir_short")
            if v is None:
                v = macro["btc_dir"].get("dir")
            chg_dir = int(v or 0)
            if macro["btc_dir"].get("chg_strength") is not None:
                chg_strength = float(macro["btc_dir"].get("chg_strength"))
    except Exception:
        chg_dir = 0
        chg_strength = None
    chg_dir = int(_clip(float(chg_dir), -1.0, 1.0))
    if chg_strength is not None:
        try:
            if not math.isfinite(float(chg_strength)):
                chg_strength = None
        except Exception:
            chg_strength = None

    macro_strong_thr = 0.12
    try:
        macro_strong_thr = float(CONFIG.get("quant_auto_btcalts_macro_strong_chg_strength_min", CONFIG.get("quant_pairs_btcalt_macro_strong_chg_strength_min", 0.12)) or 0.12)
    except Exception:
        macro_strong_thr = 0.12
    macro_strong_thr = float(_clip(float(macro_strong_thr), 0.0, 5.0))
    macro_is_strong_trend = (
        int(trend_dir_follow) != 0
        and int(trend_dir_d) == int(trend_dir_follow)
        and int(chg_dir) == int(trend_dir_follow)
        and str(risk_budget_tier) in ("risk_on", "neutral")
        and chg_strength is not None
        and float(chg_strength) >= float(macro_strong_thr)
    )

    macro_gate = None
    macro_notional_mult = 1.0
    hf_tick_default = float(hf_plan_default)
    if tier_auto == "B":
        try:
            mult_neutral = float(CONFIG.get("quant_auto_btcalts_macro_neutral_notional_mult", 0.35) or 0.35)
        except Exception:
            mult_neutral = 0.35
        try:
            mult_unstable = float(CONFIG.get("quant_auto_btcalts_macro_unstable_notional_mult", 0.6) or 0.6)
        except Exception:
            mult_unstable = 0.6
        try:
            mult_conflict = float(CONFIG.get("quant_auto_btcalts_macro_conflict_notional_mult", 0.1) or 0.1)
        except Exception:
            mult_conflict = 0.1
        try:
            mult_aligned = float(CONFIG.get("quant_auto_btcalts_macro_aligned_notional_mult", 1.0) or 1.0)
        except Exception:
            mult_aligned = 1.0

        if bool(crash_switch) or str(risk_budget_tier) == "risk_off":
            macro_gate = "risk_off"
            macro_notional_mult = 0.0
        elif str(risk_budget_tier) == "risk_off_pre":
            macro_gate = "conflict"
            macro_notional_mult = float(_clip(float(mult_conflict), 0.0, 1.0))
        elif int(trend_dir_follow) == 0:
            macro_gate = "neutral"
            macro_notional_mult = float(_clip(float(mult_neutral), 0.0, 1.0))
        elif int(chg_dir) == 0:
            macro_gate = "unstable"
            macro_notional_mult = float(_clip(float(mult_unstable), 0.0, 1.0))
        elif int(chg_dir) == int(trend_dir_follow):
            macro_gate = "aligned"
            macro_notional_mult = float(_clip(float(mult_aligned), 0.0, 2.0))
        else:
            macro_gate = "conflict"
            macro_notional_mult = float(_clip(float(mult_conflict), 0.0, 1.0))

        conflict_block_open = False
        try:
            conflict_block_open = bool(CONFIG.get("quant_auto_btcalts_macro_conflict_block_open", False))
        except Exception:
            conflict_block_open = False

        if macro_gate in ("conflict", "risk_off") and (bool(macro_trend_required) or bool(conflict_block_open) or bool(crash_switch)):
            return {
                "ok": True,
                "ts": int(ts_ms),
                "mode": str(qa_mode),
                "enabled": bool(enabled),
                "venue": str(venue),
                "execute": bool(execute),
                "live_blocked_reason": live_blocked_reason,
                "macro": macro,
                "position": None,
                "decision": dict(desired),
                "blocked": "macro_conflict",
                "trend_dir": int(trend_dir_follow),
                "chg_dir": int(chg_dir),
            }

        if not bool(hf_plan_override):
            try:
                if str(macro_gate) == "aligned":
                    hf_tick_default = float(CONFIG.get("quant_auto_btcalts_net_hedge_frac_aligned", 0.6) or 0.6)
                elif str(macro_gate) == "neutral":
                    hf_tick_default = float(CONFIG.get("quant_auto_btcalts_net_hedge_frac_neutral", 0.9) or 0.9)
                elif str(macro_gate) == "unstable":
                    hf_tick_default = float(CONFIG.get("quant_auto_btcalts_net_hedge_frac_unstable", 0.8) or 0.8)
                elif str(macro_gate) == "conflict":
                    hf_tick_default = float(CONFIG.get("quant_auto_btcalts_net_hedge_frac_conflict", 1.0) or 1.0)
                elif str(macro_gate) == "risk_off":
                    hf_tick_default = float(CONFIG.get("quant_auto_btcalts_net_hedge_frac_conflict", 1.0) or 1.0)
            except Exception:
                hf_tick_default = float(hf_plan_default)
        hf_tick_default = float(_clip(float(hf_tick_default), 0.0, 1.0))
    if isinstance(macro, dict):
        macro["btcalts_gate"] = {
            "tier": str(tier_auto),
            "trend_dir": int(trend_dir_follow),
            "trend_dir_w": int(trend_dir_w),
            "trend_dir_d": int(trend_dir_d),
            "chg_dir": int(chg_dir),
            "chg_strength": (None if chg_strength is None else float(chg_strength)),
            "strong_trend": bool(macro_is_strong_trend),
            "strong_thr": float(macro_strong_thr),
            "risk_budget_tier": str(risk_budget_tier),
            "crash_switch": bool(crash_switch),
            "target_net_bias": float(target_net_bias),
            "max_net_exposure": float(max_net_exposure),
            "allow_open": bool(allow_open_by_macro),
            "allow_addon": bool(allow_addon_by_macro),
            "state": (None if macro_gate is None else str(macro_gate)),
            "notional_mult": float(macro_notional_mult),
            "net_hedge_frac": float(hf_tick_default),
        }

    active_set = set([str(x).upper().strip() for x in active_alts])

    scored: List[Dict[str, Any]] = []
    for alt in candidates[:scan_n]:
        if str(alt).upper().strip() in active_set:
            continue
        cd_until = cooldown_map.get(str(alt).upper().strip())
        try:
            if cd_until is not None and int(cd_until) > int(ts_ms):
                continue
        except Exception:
            pass
        st = _call_status(str(alt))
        if not bool(st.get("ok")):
            continue
        act = str(st.get("action") or "hold").strip().lower()
        if act not in ("long_alt_short_btc", "short_alt_long_btc"):
            continue
        if tier_auto in ("A", "B") and bool(macro_is_strong_trend):
            if int(trend_dir_follow) == 1 and act == "short_alt_long_btc":
                continue
            if int(trend_dir_follow) == -1 and act == "long_alt_short_btc":
                continue
        if bool(macro_trend_required):
            if int(trend_dir_follow) == 0 or (not bool(allow_open_by_macro)):
                continue
            if int(trend_dir_follow) == 1 and act == "short_alt_long_btc":
                continue
            if int(trend_dir_follow) == -1 and act == "long_alt_short_btc":
                continue
        latest = (st.get("latest") if isinstance(st.get("latest"), dict) else {})
        z = latest.get("z")
        corr = latest.get("corr")
        zf = None
        try:
            zf = float(z) if z is not None else None
        except Exception:
            zf = None
        corrf = None
        try:
            corrf = float(corr) if corr is not None else None
        except Exception:
            corrf = None
        rs_latest = (((st.get("rs") or {}).get("latest") or {}) if isinstance(st.get("rs"), dict) else {})
        rs_score = rs_latest.get("rs_score")
        rsf = None
        try:
            rsf = float(rs_score) if rs_score is not None else None
        except Exception:
            rsf = None
        reg_latest = (((st.get("regime") or {}).get("latest") or {}) if isinstance(st.get("regime"), dict) else {})
        reg_mode = str(reg_latest.get("regime") or "range").strip().lower()
        trade_mode0 = str(st.get("trade_mode") or "").strip().lower()
        if trade_mode0 not in ("trend", "range"):
            trade_mode0 = ("trend" if str(reg_mode) == "trend" else "range")
        score = 0.0
        if str(trade_mode0) == "trend":
            if rsf is not None and math.isfinite(float(rsf)):
                score = abs(float(rsf))
            elif zf is not None and math.isfinite(float(zf)):
                score = abs(float(zf))
            if z_bias_min > 0.0 and z_bias_weight > 0.0 and zf is not None and math.isfinite(float(zf)) and abs(float(zf)) >= float(z_bias_min):
                if act == "short_alt_long_btc" and float(zf) >= float(z_bias_min):
                    score = float(score) + float(z_bias_weight) * abs(float(zf))
                elif act == "long_alt_short_btc" and float(zf) <= -float(z_bias_min):
                    score = float(score) + float(z_bias_weight) * abs(float(zf))
        else:
            if zf is not None and math.isfinite(float(zf)):
                score = abs(float(zf))
            elif rsf is not None and math.isfinite(float(rsf)):
                score = abs(float(rsf))
        cid = cluster_map.get(str(alt))
        scored.append({"alt": str(alt), "action": str(act), "score": float(score), "corr": corrf, "status": st, "cluster_id": cid})

    scored.sort(key=lambda x: float(x.get("score") or 0.0), reverse=True)
    try:
        open_per_tick = int(CONFIG.get("quant_auto_btcalts_open_per_tick", 1) or 1)
    except Exception:
        open_per_tick = 1
    open_per_tick = int(max(1, min(10, int(open_per_tick))))
    if float(hf_plan_default) > 0.0:
        open_per_tick = 1

    opened: List[Dict[str, Any]] = []
    opened_nontrend = 0
    slots_left = int(max_btcalts) - int(len(active_alts))
    pool0 = None
    try:
        pool0 = _quant_pairs_btcalt_sub_pool_snapshot(now_ms=int(ts_ms))
    except Exception:
        pool0 = None
    try:
        cap0_pool = float((pool0 or {}).get("cap_usdc") or 0.0)
    except Exception:
        cap0_pool = 0.0
    try:
        used0_pool = float((pool0 or {}).get("used_usdc") or 0.0)
    except Exception:
        used0_pool = 0.0
    used_eff_pool = float(used0_pool) if math.isfinite(float(used0_pool)) else 0.0
    try:
        selector_topk = int(CONFIG.get("quant_auto_btcalts_selector_topk", 3) or 3)
    except Exception:
        selector_topk = 3
    selector_topk = int(max(1, min(50, int(selector_topk))))

    remaining: List[Dict[str, Any]] = list(scored)
    while remaining:
        if int(slots_left) <= 0 or int(len(opened)) >= int(open_per_tick):
            break

        shortlist: List[Dict[str, Any]] = []
        for it in remaining:
            if len(shortlist) >= int(selector_topk):
                break
            if not isinstance(it, dict):
                continue
            cid = it.get("cluster_id")
            if cid is not None and str(cid).strip() != "":
                cc = int(cluster_counts.get(str(cid), 0))
                if cc >= int(max_per_cluster):
                    continue
            shortlist.append(it)

        if not shortlist:
            break

        def _key_pick(x: Dict[str, Any]):
            c = x.get("corr")
            try:
                cf = float(c) if c is not None else float("nan")
            except Exception:
                cf = float("nan")
            if not math.isfinite(float(cf)):
                cf = -1e9
            try:
                sf = float(x.get("score") or 0.0)
            except Exception:
                sf = 0.0
            if not math.isfinite(float(sf)):
                sf = 0.0
            return (float(cf), float(sf))

        it = max(shortlist, key=_key_pick)
        try:
            remaining.remove(it)
        except Exception:
            remaining = [x for x in remaining if x is not it]

        cid = it.get("cluster_id")
        alt = str(it.get("alt") or "").upper().strip()
        direction = str(it.get("action") or "").strip().lower()
        if not alt or direction not in ("long_alt_short_btc", "short_alt_long_btc"):
            continue

        desired["alt"] = alt
        desired["direction"] = direction
        desired["score"] = float(it.get("score") or 0.0)
        desired["action"] = "open"

        try:
            notional_alt = float(CONFIG.get("quant_pairs_btcalt_notional_usdc", CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0) or 200.0)
        except Exception:
            notional_alt = float(CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0)
        notional_alt = float(notional_alt) if math.isfinite(float(notional_alt)) and float(notional_alt) > 0.0 else float(200.0)
        try:
            cap = float(CONFIG.get("quant_auto_pair_notional_usdc_max") or 0.0)
        except Exception:
            cap = 0.0
        if math.isfinite(float(cap)) and float(cap) > 0.0:
            notional_alt = float(min(float(notional_alt), float(cap)))

        if tier_auto == "B" and math.isfinite(float(macro_notional_mult)):
            notional_alt = float(notional_alt) * float(max(0.0, float(macro_notional_mult)))

        reg_mode0 = "range"
        try:
            st_it = (it.get("status") if isinstance(it.get("status"), dict) else {})
            reg_pack = (st_it.get("regime") if isinstance(st_it.get("regime"), dict) else {})
            reg_latest = (reg_pack.get("latest") if isinstance(reg_pack.get("latest"), dict) else {})
            reg_mode0 = str(reg_latest.get("regime") or "range").strip().lower()
        except Exception:
            reg_mode0 = "range"

        is_nontrend = (tier_auto == "B" and str(reg_mode0) != "trend")
        if bool(is_nontrend):
            if int(len(active_alts)) + int(len(opened)) >= int(max_btcalts_nontrend):
                continue
            if int(opened_nontrend) >= int(open_per_tick_nontrend):
                continue
        if tier_auto == "B" and str(reg_mode0) != "trend" and float(nontrend_notional_mult) < 1.0:
            notional_alt = float(notional_alt) * float(nontrend_notional_mult)

        if float(capacity_turnover_frac) > 0.0:
            try:
                t = float(liq_turnover_7d_median.get(str(alt), 0.0) or 0.0)
            except Exception:
                t = 0.0
            if math.isfinite(float(t)) and float(t) > 0.0:
                cap_turnover = float(t) * float(capacity_turnover_frac)
                if math.isfinite(float(cap_turnover)) and float(cap_turnover) > 0.0:
                    notional_alt = float(min(float(notional_alt), float(cap_turnover)))

        if float(capacity_depth_frac) > 0.0:
            try:
                d = float(liq_depth_usdc.get(str(alt), 0.0) or 0.0)
            except Exception:
                d = 0.0
            if math.isfinite(float(d)) and float(d) > 0.0:
                cap_depth = float(d) * float(capacity_depth_frac)
                if math.isfinite(float(cap_depth)) and float(cap_depth) > 0.0:
                    notional_alt = float(min(float(notional_alt), float(cap_depth)))

        beta_abs = None
        try:
            latest = (((it.get("status") or {}).get("latest") or {}) if isinstance(it.get("status"), dict) else {})
            beta_abs = abs(float(latest.get("beta"))) if latest.get("beta") is not None else None
        except Exception:
            beta_abs = None
        if beta_abs is None or (not math.isfinite(float(beta_abs))) or float(beta_abs) <= 0.0:
            beta_abs = 1.0
        beta_abs = float(_clip(float(beta_abs), 0.2, 5.0))

        hedge_frac = float(hf_tick_default)
        notional_btc = float(notional_alt) * float(beta_abs) * float(hedge_frac)
        req0 = float(abs(float(notional_alt)) + abs(float(notional_btc)))
        if math.isfinite(float(cap0_pool)) and float(cap0_pool) > 0.0 and math.isfinite(float(used_eff_pool)) and (float(used_eff_pool) + float(req0) > float(cap0_pool) + 1e-9):
            continue

        combo = None
        try:
            combo_enabled = bool(CONFIG.get("quant_pairs_combo_supervision_enabled", False))
        except Exception:
            combo_enabled = False
        if bool(combo_enabled):
            try:
                signed_nb = float(notional_btc) if str(direction).strip().lower() == "short_alt_long_btc" else -float(notional_btc)
                alt_side0 = ("long" if str(direction).strip().lower() == "long_alt_short_btc" else "short")
                combo = _quant_pairs_combo_supervision_internal(
                    new_alt_coin=str(alt),
                    new_btc_signed_notional_usdc=float(signed_nb),
                    new_alt_side=str(alt_side0),
                    new_alt_notional_usdc=float(notional_alt),
                    new_alt_beta_abs=float(beta_abs),
                    now_ms=int(ts_ms),
                )
            except Exception as e:
                combo = {"ok": False, "error": str(e)}

        if bool(combo_enabled) and qa_mode in ("monitor", "paper", "live"):
            if isinstance(combo, dict) and not bool(combo.get("ok", True)) and bool(dynamic_hedge_enabled):
                try:
                    reasons = list(combo.get("reasons") or []) if isinstance(combo.get("reasons"), list) else []
                except Exception:
                    reasons = []
                if "net_btc_exposure" in set([str(x) for x in reasons]):
                    hf_try = float(hedge_frac)
                    while hf_try < 1.0 - 1e-12:
                        hf_try = float(min(1.0, float(hf_try) + float(dynamic_hedge_step)))
                        nb_try = float(notional_alt) * float(beta_abs) * float(hf_try)
                        req_try = float(abs(float(notional_alt)) + abs(float(nb_try)))
                        if math.isfinite(float(cap0_pool)) and float(cap0_pool) > 0.0 and math.isfinite(float(used_eff_pool)) and (float(used_eff_pool) + float(req_try) > float(cap0_pool) + 1e-9):
                            break
                        signed_nb_try = float(nb_try) if str(direction).strip().lower() == "short_alt_long_btc" else -float(nb_try)
                        alt_side0 = ("long" if str(direction).strip().lower() == "long_alt_short_btc" else "short")
                        combo_try = _quant_pairs_combo_supervision_internal(
                            new_alt_coin=str(alt),
                            new_btc_signed_notional_usdc=float(signed_nb_try),
                            new_alt_side=str(alt_side0),
                            new_alt_notional_usdc=float(notional_alt),
                            new_alt_beta_abs=float(beta_abs),
                            now_ms=int(ts_ms),
                        )
                        if isinstance(combo_try, dict) and bool(combo_try.get("ok", False)):
                            hedge_frac = float(hf_try)
                            notional_btc = float(nb_try)
                            req0 = float(req_try)
                            combo = combo_try
                            break
                if isinstance(combo, dict) and not bool(combo.get("ok", True)):
                    continue
            elif isinstance(combo, dict) and not bool(combo.get("ok", True)):
                continue

        open_out = None
        if qa_mode in ("paper", "live") and bool(enabled):
            open_out = _call_exec_open(alt=str(alt), direction=str(direction), notional_usdc=float(notional_alt), btc_hedge_frac=float(hedge_frac), mode=str(reg_mode0))
        used_eff_pool = float(used_eff_pool) + float(req0)
        opened.append({
            "alt": str(alt),
            "direction": str(direction),
            "score": float(it.get("score") or 0.0),
            "regime": str(reg_mode0),
            "notional_alt": float(notional_alt),
            "turnover_7d_median": float(liq_turnover_7d_median.get(str(alt), 0.0) or 0.0),
            "capacity_turnover_frac": float(capacity_turnover_frac),
            "beta_abs": float(beta_abs),
            "btc_hedge_frac": float(hedge_frac),
            "open": open_out,
            "combo": (_json_sanitize(combo) if isinstance(combo, dict) else None),
        })
        if bool(is_nontrend):
            opened_nontrend += 1
        slots_left = int(slots_left) - 1
        if cid is not None and str(cid).strip() != "":
            cluster_counts[str(cid)] = int(cluster_counts.get(str(cid), 0)) + 1

    if not opened:
        return {
            "ok": True,
            "ts": int(ts_ms),
            "mode": str(qa_mode),
            "enabled": bool(enabled),
            "venue": str(venue),
            "execute": bool(execute),
            "live_blocked_reason": live_blocked_reason,
            "macro": macro,
            "position": None,
            "decision": dict(desired),
            "candidates_scanned": int(min(len(candidates), scan_n)),
            "open": None,
            "opens": [],
            "rebalance": rebalance_out,
        }
    return {
        "ok": True,
        "ts": int(ts_ms),
        "mode": str(qa_mode),
        "enabled": bool(enabled),
        "venue": str(venue),
        "execute": bool(execute),
        "live_blocked_reason": live_blocked_reason,
        "macro": macro,
        "position": None,
        "decision": dict(desired),
        "candidates_scanned": int(min(len(candidates), scan_n)),
        "ranked": [{"alt": str(x.get("alt")), "action": str(x.get("action")), "score": float(x.get("score") or 0.0)} for x in scored[:10]],
        "open": (opened[0].get("open") if len(opened) == 1 else None),
        "opens": opened,
        "rebalance": rebalance_out,
    }


def _quant_btceth_state_machine_tick(now_ms: int) -> Dict[str, Any]:
    ts_ms = int(now_ms or _now_ms())
    try:
        qa_mode = str(CONFIG.get("quant_auto_mode", "off") or "off").strip().lower()
    except Exception:
        qa_mode = "off"
    if qa_mode not in ("off", "monitor", "paper", "live"):
        qa_mode = "off"

    enabled = bool(CONFIG.get("quant_auto_enabled", False)) and bool(CONFIG.get("quant_auto_btceth_enabled", False))

    try:
        venue = str(CONFIG.get("execution_venue") or "aster").strip().lower() or "aster"
    except Exception:
        venue = "aster"

    execute = bool(qa_mode == "live")
    live_blocked_reason = None
    token_required = str(os.environ.get("WEBHOOK_EXECUTE_TOKEN", "") or "").strip()
    if bool(execute):
        if not bool(_live_trading_enabled_for_owner("quant")):
            execute = False
            live_blocked_reason = "quant_live_trading_disabled"
        elif bool(CONFIG.get("dry_run", True)):
            execute = False
            live_blocked_reason = "dry_run_enabled"
        elif str(venue) == "aster" and (not _aster_enabled_for_trading_for_owner("quant")):
            execute = False
            live_blocked_reason = "aster_trading_disabled"

    try:
        tf = str(_quant_pairs_btceth_params().get("timeframe") or "1h").strip().lower() or "1h"
    except Exception:
        tf = "1h"
    if tf == "60m":
        tf = "1h"

    sid = "quant_auto_btceth"
    st_key = "quant_auto_btceth_state"
    st = TRACKER_STATE.get(st_key)
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE[st_key] = st

    cooldown_until_ms = 0
    try:
        cooldown_until_ms = int(st.get("cooldown_until_ms") or 0)
    except Exception:
        cooldown_until_ms = 0

    def _resp_json(obj: Any) -> Dict[str, Any]:
        r = obj
        if isinstance(r, tuple) and r:
            r = r[0]
        if hasattr(r, "get_json"):
            try:
                d = r.get_json(silent=True)
                if isinstance(d, dict):
                    return d
            except Exception:
                pass
        try:
            raw = r.get_data(as_text=True)
        except Exception:
            raw = None
        if raw:
            try:
                d2 = json.loads(raw)
                if isinstance(d2, dict):
                    return d2
            except Exception:
                pass
        return {"ok": False, "error": "bad_response"}

    def _call_status() -> Dict[str, Any]:
        try:
            with app.test_request_context(
                "/quant/pairs/btceth/status",
                method="GET",
                query_string={"timeframe": str(tf), "limit": 1200},
                environ_base={"REMOTE_ADDR": "127.0.0.1"},
            ):
                return _resp_json(quant_pairs_btceth_status())
        except Exception as e:
            return {"ok": False, "error": str(e), "timeframe": str(tf)}

    def _call_exec_open(direction: str, notional_usdc: float) -> Dict[str, Any]:
        ignore_post_close_freeze = False
        try:
            ignore_post_close_freeze = bool(CONFIG.get("quant_pairs_btceth_ignore_post_close_freeze", False))
        except Exception:
            ignore_post_close_freeze = False
        payload = {
            "venue": str(venue),
            "execute": bool(execute),
            "confirm_execute": True,
            "tag": "quant_auto_btceth",
            "strategy_id": str(sid),
            "timeframe": str(tf),
            "direction": str(direction),
            "notional_usdc": float(notional_usdc),
            "ignore_post_close_freeze": bool(ignore_post_close_freeze),
        }
        headers = {}
        if bool(payload.get("execute")) and bool(CONFIG.get("execute_guard_enabled", True)) and token_required:
            headers["X-Execute-Token"] = token_required
        try:
            with app.test_request_context(
                "/execution/pairs/btceth/market_open",
                method="POST",
                json=payload,
                headers=headers,
                environ_base={"REMOTE_ADDR": "127.0.0.1"},
            ):
                return _resp_json(execution_pairs_btceth_market_open())
        except Exception as e:
            return {"ok": False, "error": str(e), "direction": str(direction)}

    def _call_exec_close() -> Dict[str, Any]:
        payload = {
            "venue": str(venue),
            "execute": bool(execute),
            "confirm_execute": True,
            "tag": "quant_auto_btceth_close",
        }
        headers = {}
        if bool(payload.get("execute")) and bool(CONFIG.get("execute_guard_enabled", True)) and token_required:
            headers["X-Execute-Token"] = token_required
        try:
            with app.test_request_context(
                "/execution/pairs/btceth/market_close",
                method="POST",
                json=payload,
                headers=headers,
                environ_base={"REMOTE_ADDR": "127.0.0.1"},
            ):
                return _resp_json(execution_pairs_btceth_market_close())
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def _pos_is_btceth(pos: Any) -> bool:
        if not isinstance(pos, dict):
            return False
        try:
            sid0 = str(pos.get("strategy_id") or "").strip().lower()
        except Exception:
            sid0 = ""
        try:
            tag0 = str(pos.get("tag") or "").strip().lower()
        except Exception:
            tag0 = ""
        return ("btceth" in sid0) or ("btceth" in tag0) or ("quant_auto_btceth" in sid0) or ("quant_auto_btceth" in tag0)

    opq = TRACKER_STATE.get("quant_open_positions")
    if not isinstance(opq, dict):
        opq = {}
    opt = TRACKER_STATE.get("open_positions")
    if not isinstance(opt, dict):
        opt = {}

    def _side_norm(s: Any) -> str:
        try:
            s0 = str(s or "").strip().lower()
        except Exception:
            s0 = ""
        if s0 in ("buy", "long"):
            return "long"
        if s0 in ("sell", "short"):
            return "short"
        return ""

    def _pos_notional(pos: Any) -> float:
        if not isinstance(pos, dict):
            return 0.0
        try:
            v = float(pos.get("notional_usdc") or 0.0)
        except Exception:
            v = 0.0
        return float(v) if math.isfinite(float(v)) else 0.0

    def _likely_btceth_pair(b: Any, e: Any) -> bool:
        if not isinstance(b, dict) or not isinstance(e, dict):
            return False
        sb = _side_norm(b.get("side"))
        se = _side_norm(e.get("side"))
        if sb not in ("long", "short") or se not in ("long", "short"):
            return False
        if sb == se:
            return False
        nb = abs(_pos_notional(b))
        ne = abs(_pos_notional(e))
        if nb <= 0.0 or ne <= 0.0:
            return False
        r = ne / nb if nb > 0.0 else float("nan")
        if not math.isfinite(float(r)):
            return False
        return bool(0.05 <= float(r) <= 20.0)

    btc_q = opq.get("BTC-PERP")
    eth_q = opq.get("ETH-PERP")
    btc_t = opt.get("BTC-PERP")
    eth_t = opt.get("ETH-PERP")

    btc_leg = None
    eth_leg = None
    pos_source_sm = None

    if (isinstance(btc_q, dict) or isinstance(eth_q, dict)) and (bool(_pos_is_btceth(btc_q)) or bool(_pos_is_btceth(eth_q)) or bool(_likely_btceth_pair(btc_q, eth_q))):
        btc_leg = btc_q if isinstance(btc_q, dict) else None
        eth_leg = eth_q if isinstance(eth_q, dict) else None
        pos_source_sm = "quant"
    elif (isinstance(btc_t, dict) or isinstance(eth_t, dict)) and (bool(_pos_is_btceth(btc_t)) or bool(_pos_is_btceth(eth_t)) or bool(_likely_btceth_pair(btc_t, eth_t))):
        btc_leg = btc_t if isinstance(btc_t, dict) else None
        eth_leg = eth_t if isinstance(eth_t, dict) else None
        pos_source_sm = "tracker"
    else:
        btc_any = (btc_q if isinstance(btc_q, dict) else (btc_t if isinstance(btc_t, dict) else None))
        eth_any = (eth_q if isinstance(eth_q, dict) else (eth_t if isinstance(eth_t, dict) else None))
        if (isinstance(btc_any, dict) or isinstance(eth_any, dict)) and (bool(_pos_is_btceth(btc_any)) or bool(_pos_is_btceth(eth_any)) or bool(_likely_btceth_pair(btc_any, eth_any))):
            btc_leg = btc_any if isinstance(btc_any, dict) else None
            eth_leg = eth_any if isinstance(eth_any, dict) else None
            pos_source_sm = "mixed"

    pos_any = bool(isinstance(btc_leg, dict) or isinstance(eth_leg, dict))
    pos_pair_ok = bool(isinstance(btc_leg, dict) and isinstance(eth_leg, dict))

    try:
        spm = CONFIG.get("strategy_pool_meta")
        if not isinstance(spm, dict):
            spm = {}
            CONFIG["strategy_pool_meta"] = spm
        if sid not in spm or not isinstance(spm.get(sid), dict):
            spm[sid] = {}
        qd = CONFIG.get("quant_auto_daily_loss_limit_pct")
        qw = CONFIG.get("quant_auto_weekly_loss_limit_pct")
        if qd is not None:
            spm[sid]["max_daily_loss"] = float(qd)
        if qw is not None:
            spm[sid]["max_weekly_loss"] = float(qw)
    except Exception:
        pass

    subp_gate, _ = _subportfolio_gate_check(strategy_id=str(sid), now_ms=int(ts_ms))
    risk_reject = bool(isinstance(subp_gate, dict) and bool(subp_gate.get("enabled")) and (not bool(subp_gate.get("ok"))))

    risk_hard_reason = None
    if risk_reject:
        try:
            risk_hard_reason = str(subp_gate.get("reason") or "").strip() or None
        except Exception:
            risk_hard_reason = None

    if risk_hard_reason in ("strategy_daily_loss_limit", "strategy_weekly_loss_limit"):
        try:
            if qa_mode in ("paper", "live"):
                rb_pt = _rollback_snapshot_append(label="quant.auto.btceth", reason=str(risk_hard_reason))
                if rb_pt is not None:
                    CONFIG["quant_auto_mode"] = "monitor"
                    qa_mode = "monitor"
        except Exception:
            pass

    status = _call_status()

    desired_action = "hold"
    desired_reason = None
    latest = None
    gate = None
    try:
        desired_action = str(status.get("action") or "hold").strip().lower()
    except Exception:
        desired_action = "hold"
    desired_reason = (status.get("reason") if isinstance(status, dict) else None)
    latest = (status.get("latest") if isinstance(status.get("latest"), dict) else None)
    gate = (status.get("gate") if isinstance(status.get("gate"), dict) else None)
    position_pack = (status.get("position") if isinstance(status.get("position"), dict) else None)
    pnl_pack = (status.get("pnl") if isinstance(status.get("pnl"), dict) else None)

    state = str(st.get("state") or "FLAT").strip().upper() or "FLAT"
    if state not in ("FLAT", "LONG_SPREAD", "SHORT_SPREAD", "COOLDOWN", "EMERGENCY_EXITING"):
        state = "FLAT"

    inferred_state = None
    if bool(pos_any):
        if not bool(pos_pair_ok):
            inferred_state = "EMERGENCY_EXITING"
        else:
            try:
                btc_side = str((btc_leg or {}).get("side") or "").strip().lower()
            except Exception:
                btc_side = ""
            try:
                eth_side = str((eth_leg or {}).get("side") or "").strip().lower()
            except Exception:
                eth_side = ""
            if btc_side == "short" and eth_side == "long":
                inferred_state = "LONG_SPREAD"
            elif btc_side == "long" and eth_side == "short":
                inferred_state = "SHORT_SPREAD"
            else:
                inferred_state = "EMERGENCY_EXITING"
    else:
        if int(cooldown_until_ms) > int(ts_ms):
            inferred_state = "COOLDOWN"
        else:
            inferred_state = "FLAT"

    if inferred_state is not None:
        state = str(inferred_state)

    emergency_close = False
    emergency_reason = None

    try:
        eclose = bool(CONFIG.get("quant_pairs_btceth_emergency_close_on_gate_violation", True))
    except Exception:
        eclose = True

    if bool(pos_any) and bool(eclose):
        try:
            if isinstance(gate, dict) and bool(gate.get("enabled")) and bool(gate.get("blocked")):
                emergency_close = True
                br = None
                try:
                    br = str(gate.get("blocked_reason") or "").strip() or None
                except Exception:
                    br = None
                emergency_reason = ("stationarity_gate:" + str(br) if br else "stationarity_gate")
        except Exception:
            pass

        try:
            cm = float(_quant_pairs_btceth_params().get("corr_min") or 0.0)
        except Exception:
            cm = 0.0
        if isinstance(latest, dict) and cm > 0:
            try:
                corr_last = float(latest.get("corr")) if latest.get("corr") is not None else float("nan")
            except Exception:
                corr_last = float("nan")
            if math.isfinite(float(corr_last)) and float(corr_last) < float(cm):
                emergency_close = True
                emergency_reason = "corr_below_min"

        beta_abs_max = None
        try:
            beta_abs_max = float(CONFIG.get("quant_pairs_btceth_beta_abs_max")) if CONFIG.get("quant_pairs_btceth_beta_abs_max") is not None else None
        except Exception:
            beta_abs_max = None
        if beta_abs_max is None:
            beta_abs_max = 3.0
        if isinstance(latest, dict):
            try:
                beta_last = float(latest.get("beta")) if latest.get("beta") is not None else float("nan")
            except Exception:
                beta_last = float("nan")
            if math.isfinite(float(beta_last)) and float(beta_abs_max) > 0 and abs(float(beta_last)) > float(beta_abs_max):
                emergency_close = True
                emergency_reason = "beta_abs_max"

    did_open = None
    did_close = None
    settle = None

    if not bool(enabled) or qa_mode in ("off", "monitor"):
        st.update({
            "ts": int(ts_ms),
            "state": str(state),
            "mode": str(qa_mode),
            "enabled": bool(enabled),
            "venue": str(venue),
            "execute": bool(execute),
            "live_blocked_reason": live_blocked_reason,
            "cooldown_until_ms": int(cooldown_until_ms),
            "status": status,
            "subportfolio": subp_gate,
        })
        return dict(st)

    if state in ("LONG_SPREAD", "SHORT_SPREAD", "EMERGENCY_EXITING") and bool(pos_any):
        close_needed = False
        close_reason = None

        if state == "EMERGENCY_EXITING":
            close_needed = True
            close_reason = "emergency_exiting"
        elif not bool(pos_pair_ok):
            close_needed = True
            close_reason = "one_leg_open"
        elif bool(emergency_close):
            close_needed = True
            close_reason = str(emergency_reason or "emergency")
        elif bool(risk_reject):
            close_needed = True
            close_reason = str(risk_hard_reason or "risk_reject")
        else:
            if desired_action in ("exit", "stop"):
                close_needed = True
                close_reason = str(desired_reason or desired_action)

        if bool(close_needed):
            pnl_est = 0.0
            if isinstance(pnl_pack, dict) and bool(pnl_pack.get("ok")):
                try:
                    ps = str(status.get("position_source") or "").strip().lower() if isinstance(status, dict) else ""
                except Exception:
                    ps = ""
                if pos_source_sm is not None and ps and ps != str(pos_source_sm):
                    pnl_pack = None
            if isinstance(pnl_pack, dict) and bool(pnl_pack.get("ok")):
                v = (pnl_pack.get("net_est_usdc") if pnl_pack.get("net_est_usdc") is not None else pnl_pack.get("unrealized_gross_usdc"))
                try:
                    pnl_est = float(v or 0.0)
                except Exception:
                    pnl_est = 0.0
                pnl_est = 0.0 if (not math.isfinite(float(pnl_est))) else float(pnl_est)

            did_close = _call_exec_close()

            ok_close = bool(did_close.get("ok")) if isinstance(did_close, dict) else False
            if ok_close:
                try:
                    settle = _subportfolio_settle(strategy_id=str(sid), pnl_usdc=float(pnl_est), now_ms=int(ts_ms))
                except Exception:
                    settle = None
                try:
                    cd_bars = int(CONFIG.get("quant_pairs_btceth_cooldown_bars_after_exit", 4) or 4)
                except Exception:
                    cd_bars = 4
                cd_bars = int(max(0, min(2000, int(cd_bars))))
                try:
                    cd_ms = int(_hl_interval_to_ms(str(tf))) * int(cd_bars)
                except Exception:
                    cd_ms = 0
                if cd_ms > 0:
                    cooldown_until_ms = int(ts_ms + int(cd_ms))
                    try:
                        cds = TRACKER_STATE.get("quant_pairs_btceth_cooldowns")
                        if not isinstance(cds, dict):
                            cds = {}
                            TRACKER_STATE["quant_pairs_btceth_cooldowns"] = cds
                        cds["exit"] = int(cooldown_until_ms)
                    except Exception:
                        pass
                state = "COOLDOWN" if int(cooldown_until_ms) > int(ts_ms) else "FLAT"
                st["last_close_reason"] = str(close_reason or "close")
                st["last_close_pnl_est_usdc"] = float(pnl_est)
            else:
                state = "EMERGENCY_EXITING"
                st["last_close_reason"] = str(close_reason or "close")

    elif state == "COOLDOWN":
        if int(cooldown_until_ms) <= int(ts_ms):
            state = "FLAT"

    if state == "FLAT" and (not bool(pos_any)):
        if int(cooldown_until_ms) > int(ts_ms):
            state = "COOLDOWN"
        else:
            if bool(risk_reject):
                desired_action = "hold"
                desired_reason = ("risk_reject:" + str(risk_hard_reason) if risk_hard_reason else "risk_reject")
            if desired_action in ("long_btc_short_eth", "short_btc_long_eth") and bool(enabled) and qa_mode in ("paper", "live"):
                try:
                    notional = float(CONFIG.get("quant_pairs_btceth_notional_usdc", CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0) or 200.0)
                except Exception:
                    notional = float(CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0)
                notional = float(notional) if math.isfinite(float(notional)) and float(notional) > 0.0 else float(200.0)
                try:
                    cap = float(CONFIG.get("quant_auto_pair_notional_usdc_max") or 0.0)
                except Exception:
                    cap = 0.0
                if math.isfinite(float(cap)) and float(cap) > 0.0:
                    notional = float(min(float(notional), float(cap)))

                combo = None
                try:
                    combo_enabled = bool(CONFIG.get("quant_pairs_combo_supervision_enabled", False))
                except Exception:
                    combo_enabled = False
                if bool(combo_enabled):
                    try:
                        signed_nb = float(notional) if str(desired_action) == "long_btc_short_eth" else -float(notional)
                        try:
                            w = float(CONFIG.get("quant_pairs_combo_btceth_btc_weight", 0.0) or 0.0)
                        except Exception:
                            w = 0.0
                        if not math.isfinite(float(w)):
                            w = 0.0
                        w = float(_clip(float(w), 0.0, 10.0))
                        signed_nb = float(signed_nb) * float(w)
                        combo = _quant_pairs_combo_supervision_internal(
                            new_alt_coin="ETH",
                            new_btc_signed_notional_usdc=float(signed_nb),
                            now_ms=int(ts_ms),
                        )
                    except Exception as e:
                        combo = {"ok": False, "error": str(e)}

                if isinstance(combo, dict) and (not bool(combo.get("ok", True))):
                    did_open = {"ok": False, "error": "combo_supervision_block", "pair_type": "btceth", "direction": str(desired_action), "combo": _json_sanitize(combo)}
                    st["last_open_reject_reason"] = "combo_supervision_block"
                else:
                    did_open = _call_exec_open(direction=str(desired_action), notional_usdc=float(notional))
                    if isinstance(did_open, dict) and bool(did_open.get("ok")):
                        if desired_action == "long_btc_short_eth":
                            state = "SHORT_SPREAD"
                        elif desired_action == "short_btc_long_eth":
                            state = "LONG_SPREAD"

    st.update({
        "ok": True,
        "ts": int(ts_ms),
        "state": str(state),
        "mode": str(qa_mode),
        "enabled": bool(enabled),
        "venue": str(venue),
        "execute": bool(execute),
        "live_blocked_reason": live_blocked_reason,
        "cooldown_until_ms": int(cooldown_until_ms),
        "position_source_sm": (None if pos_source_sm is None else str(pos_source_sm)),
        "status": status,
        "subportfolio": subp_gate,
        "open": did_open,
        "close": did_close,
        "settle": settle,
    })
    return dict(st)


