def _apply_execution_venue_policy(cfg: Dict[str, Any]) -> None:
    try:
        venue = str(cfg.get("execution_venue", "stub") or "stub").lower().strip()
    except Exception:
        venue = "stub"
    if venue not in ("stub", "aster", "hyperliquid"):
        venue = "stub"
        cfg["execution_venue"] = "stub"

    if venue == "hyperliquid":
        try:
            mn = cfg.get("hl_min_notional_usdc")
            mnf = float(mn) if mn is not None else None
            if mnf is None or (not math.isfinite(mnf)) or mnf <= 0.0:
                cfg["hl_min_notional_usdc"] = 10.0
        except Exception:
            cfg["hl_min_notional_usdc"] = 10.0

        try:
            mx = cfg.get("hl_max_notional_usdc")
            mxf = float(mx) if mx is not None else None
            if mxf is not None and ((not math.isfinite(mxf)) or mxf <= 0.0):
                cfg["hl_max_notional_usdc"] = None
        except Exception:
            pass
    elif venue == "aster":
        try:
            n = cfg.get("notional_usdc")
            nf = float(n) if n is not None else None
            if nf is None or (not math.isfinite(nf)) or nf <= 0.0:
                cfg["notional_usdc"] = 400.0
        except Exception:
            cfg["notional_usdc"] = 400.0

        try:
            lev = cfg.get("leverage")
            li = int(lev) if lev is not None else None
            if li is None or li <= 0:
                cfg["leverage"] = 10
        except Exception:
            cfg["leverage"] = 10

        try:
            mn = cfg.get("aster_min_notional_usdc")
            mnf = float(mn) if mn is not None else None
            if mnf is None or (not math.isfinite(mnf)) or mnf <= 0.0:
                cfg["aster_min_notional_usdc"] = 10.0
        except Exception:
            cfg["aster_min_notional_usdc"] = 10.0

        try:
            mx = cfg.get("aster_max_notional_usdc")
            mxf = float(mx) if mx is not None else None
            if mxf is None or (not math.isfinite(mxf)) or mxf <= 0.0:
                cfg["aster_max_notional_usdc"] = 500.0
        except Exception:
            cfg["aster_max_notional_usdc"] = 500.0

        try:
            cfg["aster_qty_cap_max_enabled"] = bool(cfg.get("aster_qty_cap_max_enabled", True))
        except Exception:
            cfg["aster_qty_cap_max_enabled"] = True
        try:
            v = float(cfg.get("aster_qty_cap_min_effective_frac", 0.2) or 0.2)
        except Exception:
            v = 0.2
        if (not math.isfinite(float(v))) or float(v) <= 0:
            v = 0.0
        if float(v) > 1.0:
            v = 1.0
        cfg["aster_qty_cap_min_effective_frac"] = float(v)

        try:
            mnf = float(cfg.get("aster_min_notional_usdc") or 0.0)
        except Exception:
            mnf = 10.0
        try:
            mxf = float(cfg.get("aster_max_notional_usdc") or 0.0)
        except Exception:
            mxf = 500.0
        if mnf <= 0.0:
            mnf = 10.0
            cfg["aster_min_notional_usdc"] = float(mnf)
        if mxf <= 0.0:
            mxf = 500.0
            cfg["aster_max_notional_usdc"] = float(mxf)
        if mxf < mnf:
            cfg["aster_max_notional_usdc"] = float(mnf)
            mxf = float(mnf)
        try:
            ef = float(cfg.get("entry_fixed_notional_usdc") or 0.0)
        except Exception:
            ef = 0.0
        if ef > 0.0 and ef > mxf + 1e-12:
            cfg["entry_fixed_notional_usdc"] = float(mxf)


def _load_config():
    global _CONFIG_LOADED
    if bool(_CONFIG_LOADED):
        return
    p = _runtime_config_path()
    if p.exists():
        try:
            with open(p, "r") as f:
                cfg = json.load(f)
                a = None
                if isinstance(cfg, dict):
                    a = cfg.get("automation")
                    cfg2 = dict(cfg)
                    try:
                        del cfg2["automation"]
                    except Exception:
                        pass

                    rp = cfg2.get("rollback_points")
                    if isinstance(rp, list):
                        try:
                            max_points = int(cfg2.get("rollback_max_points", 20) or 20)
                        except Exception:
                            max_points = 20
                        max_points = max(1, min(200, int(max_points)))
                        try:
                            hist_cap = int(cfg2.get("arena_history_max", 2000) or 2000)
                        except Exception:
                            hist_cap = 2000
                        try:
                            attrib_cap = int(cfg2.get("arena_attrib_max", 5000) or 5000)
                        except Exception:
                            attrib_cap = 5000
                        hist_cap = max(50, min(200, int(hist_cap)))
                        attrib_cap = max(50, min(200, int(attrib_cap)))
                        pts = [p for p in rp if isinstance(p, dict)]
                        pts = sorted(pts, key=lambda z: int(z.get("ts") or 0), reverse=True)[:max_points]
                        out_pts: List[Dict[str, Any]] = []
                        for pt in pts:
                            p2 = dict(pt)
                            st = p2.get("arena_state")
                            if isinstance(st, dict):
                                st2 = dict(st)
                                hist = st2.get("history")
                                if isinstance(hist, list) and len(hist) > hist_cap:
                                    st2["history"] = hist[-hist_cap:]
                                attrib = st2.get("attrib")
                                if isinstance(attrib, list) and len(attrib) > attrib_cap:
                                    st2["attrib"] = attrib[-attrib_cap:]
                                p2["arena_state"] = st2
                            out_pts.append(p2)
                        cfg2["rollback_points"] = out_pts

                    CONFIG.update(cfg2)
                    try:
                        st0 = CONFIG.get("sandbox_state")
                        if isinstance(st0, dict):
                            st1 = dict(st0)
                            st1["running"] = 0
                            st1["queued"] = 0
                            CONFIG["sandbox_state"] = st1
                    except Exception:
                        pass
                    try:
                        _normalize_runtime_config_by_doc(CONFIG)
                    except Exception:
                        pass
                    try:
                        _enforce_env_runtime_policy(CONFIG)
                    except Exception:
                        pass
                    try:
                        _apply_execution_venue_policy(CONFIG)
                    except Exception:
                        pass
                try:
                    if isinstance(a, dict):
                        for k, v in a.items():
                            if k in AUTOMATION:
                                AUTOMATION[k] = v
                except Exception:
                    pass
                LOG.info("Config loaded from %s", p)
        except Exception as e:
            LOG.error("Failed to load config: %s", e)
    _CONFIG_LOADED = True


def _normalize_runtime_config_by_doc(cfg: Dict[str, Any]) -> None:
    if not isinstance(cfg, dict):
        return
    try:
        d = float(cfg.get("max_daily_loss"))
        if math.isfinite(float(d)):
            if d < -0.05:
                cfg["max_daily_loss"] = -0.05
    except Exception:
        pass


def _enforce_env_runtime_policy(cfg: Dict[str, Any]) -> None:
    if not isinstance(cfg, dict):
        return
    env = _governance_env_name()
    if env == "explore":
        cfg["dry_run"] = True
        cfg["live_trading_enabled"] = False
        cfg["strategy_live_trading_enabled"] = False
        cfg["three_screen_live_trading_enabled"] = False
        cfg["quant_live_trading_enabled"] = False
        cfg["serving_shadow_mode"] = True
        cfg["serving_canary_enabled"] = False
        cfg["config_allow_remote"] = False
        cfg["maintenance_allow_remote"] = False
        ap0 = cfg.get("agent_push")
        ap = (dict(ap0) if isinstance(ap0, dict) else {})
        ap["twitter_enabled"] = False
        cfg["agent_push"] = ap
        for k in list(cfg.keys()):
            ks = str(k)
            if ks.endswith("_trading_enabled"):
                cfg[ks] = False
        return
    if env == "pilot":
        cfg["config_allow_remote"] = False
        cfg["maintenance_allow_remote"] = False
        ap0 = cfg.get("agent_push")
        ap = (dict(ap0) if isinstance(ap0, dict) else {})
        ap.setdefault("twitter_enabled", False)
        cfg["agent_push"] = ap
        cfg["serving_canary_enabled"] = True
        try:
            frac = float(cfg.get("serving_canary_size_frac", 0.05) or 0.05)
        except Exception:
            frac = 0.05
        frac = max(0.001, min(0.10, float(frac)))
        cfg["serving_canary_size_frac"] = float(frac)
        cfg["trade_whitelist_enabled"] = True
        cfg["trade_whitelist_enforcement"] = "hard"
        cfg["whitelist_gate_enabled"] = True
        try:
            hard_cap = 200.0
            v = float(cfg.get("pilot_canary_max_notional_usdc", hard_cap) or hard_cap)
            if (not math.isfinite(float(v))) or float(v) < 0.0:
                v = hard_cap
            v = float(min(float(hard_cap), float(v)))
            cfg["pilot_canary_max_notional_usdc"] = float(v)
            cfg["entry_max_notional_usdc"] = float(v)
        except Exception:
            cfg["pilot_canary_max_notional_usdc"] = 200.0
            cfg["entry_max_notional_usdc"] = 200.0
        return
    try:
        w = float(cfg.get("max_weekly_loss"))
        if math.isfinite(float(w)):
            if w < -0.12:
                cfg["max_weekly_loss"] = -0.12
    except Exception:
        pass
    try:
        m0 = cfg.get("agent_outbox_retention_days_by_stem")
    except Exception:
        m0 = None
    try:
        m = dict(m0) if isinstance(m0, dict) else {}
        for k, min_days in (("approvals", 36500), ("pipeline_artifacts", 36500), ("chat", 36500)):
            try:
                cur = int(m.get(k) or 0)
            except Exception:
                cur = 0
            if cur < int(min_days):
                m[str(k)] = int(min_days)
        cfg["agent_outbox_retention_days_by_stem"] = m
    except Exception:
        pass


