def _md_extract_section(path: Path, section_key: str, max_chars: int = 20000) -> Dict[str, Any]:
    sk = str(section_key or "").strip()
    if not sk:
        return {"ok": False, "error": "missing_section"}
    try:
        raw = path.read_text(encoding="utf-8")
    except Exception:
        try:
            raw = path.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            return {"ok": False, "error": "read_failed"}

    lines = raw.splitlines()
    patt = re.compile(r"^(#+)\s+" + re.escape(sk) + r"(?:\s+|$)(.*)$")
    start_i = -1
    level = 0
    title = ""
    for i, line in enumerate(lines):
        m = patt.match(line)
        if not m:
            continue
        start_i = i
        level = len(m.group(1) or "")
        tail = str(m.group(2) or "").strip()
        title = tail.lstrip("-: ")
        break
    if start_i < 0:
        return {"ok": False, "error": "section_not_found"}

    end_i = len(lines)
    next_patt = re.compile(r"^(#{1,%d})\s+" % int(level))
    for j in range(start_i + 1, len(lines)):
        if next_patt.match(lines[j]):
            end_i = j
            break

    text_full = "\n".join(lines[start_i:end_i]).strip()
    truncated = False
    text = text_full
    if max_chars > 0 and len(text) > int(max_chars):
        text = text[: int(max_chars)]
        truncated = True
    doc_refs = [{"doc_path": str(path.name), "section": sk, "start_line": int(start_i + 1), "end_line": int(end_i), "line_range": f"L{int(start_i + 1)}-L{int(end_i)}"}]
    return {
        "ok": True,
        "doc_path": str(path.name),
        "section": sk,
        "title": title,
        "start_line": int(start_i + 1),
        "end_line": int(end_i),
        "text": text,
        "doc_refs": doc_refs,
        "truncated": bool(truncated),
    }


def _md_extract_lines(path: Path, *, start_line: int, end_line: int, max_chars: int = 20000) -> Dict[str, Any]:
    try:
        s0 = int(start_line)
    except Exception:
        s0 = 1
    try:
        e0 = int(end_line)
    except Exception:
        e0 = s0
    if s0 <= 0:
        s0 = 1
    if e0 <= 0:
        e0 = s0
    if e0 < s0:
        s0, e0 = e0, s0

    out = _text_extract_lines_streaming(path, start_line=int(s0), end_line=int(e0), max_chars=int(max_chars), redact=False)
    if not bool(out.get("ok")):
        return out
    text = str(out.get("text") or "")
    e0 = int(out.get("end_line") or e0)
    doc_refs = [{"doc_path": str(path.name), "section": "(lines)", "start_line": int(s0), "end_line": int(e0), "line_range": f"L{int(s0)}-L{int(e0)}"}]
    return {
        "ok": True,
        "doc_path": str(path.name),
        "section": "(lines)",
        "title": "",
        "start_line": int(s0),
        "end_line": int(e0),
        "text": text,
        "doc_refs": doc_refs,
        "truncated": bool(out.get("truncated", False)),
    }


_SENSITIVE_INLINE_RE = re.compile(r"(?i)\b(api[_-]?key|secret|token|password|passwd|access[_-]?key|private[_-]?key|mnemonic|seed)\b\s*[:=]\s*([^\s,;\"']+)")
_SENSITIVE_BEARER_RE = re.compile(r"(?i)\b(bearer)\s+([a-z0-9\-\._=]{12,})")
_SENSITIVE_KNOWN_PREFIX_RE = re.compile(r"(?i)\b(ghp_[a-z0-9]{20,}|sk-[a-z0-9]{16,}|xox[baprs]-[a-z0-9-]{10,}|hf_[a-z0-9]{10,})\b")
_PRIVATE_KEY_BLOCK_RE = re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----", re.MULTILINE)


def _find_sensitive_pos(text: str) -> Optional[int]:
    s = str(text or "")
    if not s:
        return None
    hits: List[int] = []
    for patt in (_PRIVATE_KEY_BLOCK_RE, _SENSITIVE_BEARER_RE, _SENSITIVE_KNOWN_PREFIX_RE, _SENSITIVE_INLINE_RE):
        try:
            m = patt.search(s)
        except Exception:
            m = None
        if m:
            try:
                hits.append(int(m.start()))
            except Exception:
                pass
    return (min(hits) if hits else None)


def _redact_sensitive_text(text: str) -> str:
    s = str(text or "")
    if not s:
        return s
    s = _PRIVATE_KEY_BLOCK_RE.sub("[REDACTED_PRIVATE_KEY_BLOCK]", s)
    s = _SENSITIVE_BEARER_RE.sub(lambda m: f"{m.group(1)} [REDACTED]", s)
    s = _SENSITIVE_KNOWN_PREFIX_RE.sub("[REDACTED]", s)

    def _sub_inline(m: re.Match) -> str:
        k = str(m.group(1) or "")
        return f"{k}=[REDACTED]"

    s = _SENSITIVE_INLINE_RE.sub(_sub_inline, s)
    return s


def _text_extract_lines_streaming(path: Path, *, start_line: int, end_line: int, max_chars: int, redact: bool) -> Dict[str, Any]:
    s0 = int(start_line)
    e0 = int(end_line)
    if s0 <= 0:
        s0 = 1
    if e0 <= 0:
        e0 = s0
    if e0 < s0:
        s0, e0 = e0, s0
    max_chars = int(max_chars)
    if max_chars <= 0:
        max_chars = 20000

    try:
        st = path.stat()
        size = int(st.st_size)
    except Exception:
        size = 0
    if size > 8 * 1024 * 1024:
        return {"ok": False, "error": "file_too_large", "size": int(size), "max_size": int(8 * 1024 * 1024)}

    buf: List[str] = []
    end_hit = 0
    truncated = False
    used_chars = 0
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            for i, ln in enumerate(f, start=1):
                if i < s0:
                    continue
                if i > e0:
                    break
                if "\x00" in ln:
                    return {"ok": False, "error": "binary_file"}
                ln2 = str(ln).rstrip("\n")
                buf.append(ln2)
                used_chars += len(ln2) + 1
                end_hit = int(i)
                if used_chars > int(max_chars) + 2000:
                    truncated = True
                    break
    except Exception:
        return {"ok": False, "error": "read_failed"}
    if not buf:
        if s0 > 1:
            return {"ok": False, "error": "start_line_out_of_range"}
        return {"ok": False, "error": "empty"}
    txt_full = "\n".join(buf).strip("\n")
    txt = txt_full
    if redact:
        txt = _redact_sensitive_text(txt)
    if len(txt) > int(max_chars):
        txt = txt[: int(max_chars)]
        truncated = True
    return {"ok": True, "start_line": int(s0), "end_line": int(end_hit or e0), "text": txt, "truncated": bool(truncated)}


def _project_root_dir() -> Path:
    return Path(__file__).resolve().parent


_CODE_LINES_CACHE: Dict[str, Any] = {}


def _code_file_lines_cached(path: Path) -> List[str]:
    p = str(path)
    try:
        st = path.stat()
        mtime = float(st.st_mtime)
        size = int(st.st_size)
    except Exception:
        mtime = 0.0
        size = 0
    if int(size) > 2 * 1024 * 1024:
        return []
    try:
        hit = _CODE_LINES_CACHE.get(p)
    except Exception:
        hit = None
    if isinstance(hit, dict) and float(hit.get("mtime") or 0.0) == float(mtime) and isinstance(hit.get("lines"), list):
        return [str(x) for x in (hit.get("lines") or [])]
    try:
        raw = path.read_text(encoding="utf-8")
    except Exception:
        try:
            raw = path.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            raw = ""
    if "\x00" in raw:
        return []
    lines = raw.splitlines()
    _CODE_LINES_CACHE[p] = {"mtime": float(mtime), "lines": lines}
    return lines


def _text_search_streaming(path: Path, query_lower: str, *, max_hits: int, max_scan_bytes: int = 12 * 1024 * 1024) -> Tuple[List[Dict[str, Any]], int]:
    q = str(query_lower or "").strip().lower()
    if not q:
        return [], 0
    hits: List[Dict[str, Any]] = []
    scanned = 0
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            for i, ln in enumerate(f, start=1):
                scanned += len(ln)
                if scanned > int(max_scan_bytes):
                    break
                if "\x00" in ln:
                    break
                if q in str(ln or "").lower():
                    t = _redact_sensitive_text(_clip_str(str(ln or "").strip(), 280))
                    hits.append({"file": str(path.name), "line": int(i), "text": t})
                    if len(hits) >= int(max_hits):
                        break
    except Exception:
        return [], 0
    return hits, int(scanned)


def _code_retrieve_snippets_streaming(path: Path, query: str, *, max_sections: int, max_chars_total: int, context_lines: int) -> List[Dict[str, Any]]:
    q = str(query or "").strip().lower()
    if not q:
        return []
    toks: List[str] = []
    for t in re.split(r"[^a-z0-9_\u4e00-\u9fff]+", q):
        t = str(t or "").strip().lower()
        if len(t) >= 3:
            toks.append(t)
    if not toks:
        toks = [q[:32]]

    out: List[Dict[str, Any]] = []
    used = 0
    prev: deque[Tuple[int, str]] = deque(maxlen=int(context_lines))
    collecting = False
    block: List[Tuple[int, str]] = []
    collect_until = 0

    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            for i, ln in enumerate(f, start=1):
                if "\x00" in ln:
                    break
                line_s = str(ln).rstrip("\n")
                blob = line_s.lower()
                hit = any((tok in blob) for tok in toks[:12])
                if hit and (not collecting):
                    collecting = True
                    block = list(prev) + [(int(i), line_s)]
                    collect_until = int(i) + int(context_lines)
                elif collecting:
                    block.append((int(i), line_s))
                    if int(i) >= int(collect_until):
                        collecting = False
                        s_ln = int(block[0][0]) if block else int(i)
                        e_ln = int(block[-1][0]) if block else int(i)
                        txt = "\n".join([x[1] for x in block]).strip("\n")
                        remaining = int(max_chars_total) - int(used)
                        if remaining <= 0:
                            break
                        if len(txt) > remaining:
                            txt = txt[:remaining]
                        out.append({"ok": True, "file_path": str(path.name), "start_line": int(s_ln), "end_line": int(e_ln), "text": txt})
                        used += len(txt)
                        block = []
                        if len(out) >= int(max_sections):
                            break
                prev.append((int(i), line_s))
    except Exception:
        return []
    return out


def _code_retrieve_snippets(path: Path, query: str, *, max_sections: int = 4, max_chars_total: int = 6500, context_lines: int = 8) -> List[Dict[str, Any]]:
    q = str(query or "").strip().lower()
    if not q:
        return []
    toks: List[str] = []
    for t in re.split(r"[^a-z0-9_\u4e00-\u9fff]+", q):
        t = str(t or "").strip().lower()
        if len(t) >= 3:
            toks.append(t)
    if not toks:
        toks = [q[:32]]

    lines = _code_file_lines_cached(path)
    if not lines:
        return _code_retrieve_snippets_streaming(path, query, max_sections=max_sections, max_chars_total=max_chars_total, context_lines=context_lines)

    scored: List[Tuple[int, int, int]] = []
    min_score = 2 if len(toks) >= 4 else 1
    for i, ln in enumerate(lines):
        blob = str(ln or "").lower()
        score = 0
        for tok in toks[:12]:
            if tok and tok in blob:
                score += 1
        if score >= min_score:
            s = max(0, int(i) - int(context_lines))
            e = min(len(lines), int(i) + int(context_lines) + 1)
            scored.append((int(score), int(s), int(e)))
    if not scored:
        return []
    scored.sort(key=lambda x: (-int(x[0]), int(x[1])))

    merged: List[Tuple[int, int]] = []
    for _sc, s, e in scored[: max_sections * 6]:
        if not merged:
            merged.append((int(s), int(e)))
            continue
        ps, pe = merged[-1]
        if int(s) <= int(pe) + 2:
            merged[-1] = (int(ps), int(max(int(pe), int(e))))
        else:
            merged.append((int(s), int(e)))
        if len(merged) >= max_sections:
            break

    out: List[Dict[str, Any]] = []
    used = 0
    for s, e in merged:
        txt = "\n".join(lines[int(s) : int(e)]).strip("\n")
        if not txt:
            continue
        remaining = int(max_chars_total) - int(used)
        if remaining <= 0:
            break
        if len(txt) > remaining:
            txt = txt[:remaining]
        out.append({
            "ok": True,
            "file_path": str(path.name),
            "start_line": int(s) + 1,
            "end_line": int(e),
            "text": txt,
        })
        used += len(txt)
        if len(out) >= int(max_sections):
            break
    return out


def _agent_code_allowed_resolve(path0: str) -> Optional[Path]:
    s = str(path0 or "").strip()
    if not s:
        return None
    s_posix = s.replace("\\", "/")
    if ".." in [x for x in s_posix.split("/") if x]:
        return None
    root = _project_root_dir()
    p = None
    try:
        if s.startswith("/"):
            p = Path(s).resolve()
        else:
            p = (root / s).resolve()
    except Exception:
        return None
    try:
        if not str(p).startswith(str(root)):
            return None
    except Exception:
        return None
    if not p.exists() or (not p.is_file()):
        return None
    return p


_DOC_MD_CACHE: Dict[str, Any] = {}


def _md_split_sections(raw: str) -> List[Dict[str, Any]]:
    lines = str(raw or "").splitlines()
    heads: List[Tuple[int, int, str]] = []
    for i, line in enumerate(lines):
        m = re.match(r"^(#+)\s+(.+?)\s*$", str(line or ""))
        if not m:
            continue
        level = len(m.group(1) or "")
        title = str(m.group(2) or "").strip()
        if title:
            heads.append((i, level, title))
    if not heads:
        return []

    out: List[Dict[str, Any]] = []
    for idx, (start_i, level, title) in enumerate(heads):
        end_i = len(lines)
        for j in range(idx + 1, len(heads)):
            ni, nl, _nt = heads[j]
            if nl <= level:
                end_i = ni
                break
        text = "\n".join(lines[start_i:end_i]).strip()
        out.append({
            "section": title,
            "start_line": int(start_i + 1),
            "end_line": int(end_i),
            "text": text,
        })
    return out


def _doc_md_sections_cached(path: Path) -> List[Dict[str, Any]]:
    key = str(path)
    try:
        st = path.stat()
        mtime = float(st.st_mtime)
    except Exception:
        st = None
        mtime = -1.0

    c = _DOC_MD_CACHE.get(key)
    if isinstance(c, dict) and float(c.get("mtime") or -1.0) == mtime and isinstance(c.get("sections"), list):
        return c.get("sections")

    try:
        raw = path.read_text(encoding="utf-8")
    except Exception:
        try:
            raw = path.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            raw = ""
    sections = _md_split_sections(raw)
    _DOC_MD_CACHE[key] = {"mtime": mtime, "sections": sections}
    return sections


def _search_tokens(text: str, *, max_tokens: int = 180) -> List[str]:
    t = str(text or "").strip()
    if not t:
        return []
    tokens: List[str] = []
    tl = t.lower()
    tokens.extend(re.findall(r"[a-z0-9_]{2,}", tl))
    tokens.extend([x for x in re.findall(r"\d{2,}", tl) if x])

    cjk_runs = re.findall(r"[\u4e00-\u9fff]{2,}", t)
    for run in cjk_runs[:20]:
        s = str(run)
        if len(s) <= 20:
            tokens.append(s)
        n = min(len(s) - 1, 60)
        for i in range(n):
            tokens.append(s[i : i + 2])

    seen: set = set()
    uniq: List[str] = []
    for x in tokens:
        v = str(x or "").strip()
        if not v:
            continue
        if v in seen:
            continue
        seen.add(v)
        uniq.append(v)
        if len(uniq) >= int(max_tokens):
            break
    return uniq


def _doc_retrieve_snippets(path: Path, query: str, *, max_sections: int = 4, max_chars_total: int = 6000) -> List[Dict[str, Any]]:
    q = str(query or "").strip()
    if not q:
        return []
    try:
        max_sections = int(max_sections)
    except Exception:
        max_sections = 4
    max_sections = max(1, min(8, int(max_sections)))
    try:
        max_chars_total = int(max_chars_total)
    except Exception:
        max_chars_total = 6000
    max_chars_total = max(1200, min(20000, int(max_chars_total)))

    q_tokens = _search_tokens(q, max_tokens=120)
    if not q_tokens:
        return []
    min_score = 2 if len(q_tokens) >= 10 else 1

    sections = _doc_md_sections_cached(path)
    scored: List[Tuple[int, int, Dict[str, Any]]] = []
    for i, sec in enumerate(sections):
        if not isinstance(sec, dict):
            continue
        text = str(sec.get("text") or "")
        if not text.strip():
            continue
        blob = text.lower()
        head = str(sec.get("section") or "").lower()
        score = 0
        for tok in q_tokens:
            if tok in blob:
                score += 1
            if tok in head:
                score += 2
        if score >= min_score:
            scored.append((score, i, sec))
    scored.sort(key=lambda x: (-int(x[0]), int(x[1])))

    out: List[Dict[str, Any]] = []
    used = 0
    for score, _i, sec in scored[: max_sections * 3]:
        txt = str(sec.get("text") or "").strip()
        if not txt:
            continue
        remaining = max_chars_total - used
        if remaining <= 0:
            break
        if len(txt) > remaining:
            txt = txt[:remaining]
        out.append({
            "ok": True,
            "doc_path": str(path.name),
            "section": str(sec.get("section") or "").strip(),
            "title": "",
            "start_line": int(sec.get("start_line") or 1),
            "end_line": int(sec.get("end_line") or 1),
            "text": txt,
            "score": int(score),
        })
        used += len(txt)
        if len(out) >= max_sections:
            break
    return out


@app.route("/doc/snippet", methods=["GET"])
def doc_snippet_get():
    doc_raw = str(request.args.get("doc") or "技术文档.md").strip()
    try:
        doc = str(Path(doc_raw).name).strip()
    except Exception:
        doc = doc_raw
    if not doc:
        doc = "技术文档.md"
    section = str(request.args.get("section") or "").strip()
    start_line_raw = request.args.get("start_line")
    end_line_raw = request.args.get("end_line")
    try:
        max_chars = int(request.args.get("max_chars") or 20000)
    except Exception:
        max_chars = 20000
    max_chars = max(2000, min(200000, int(max_chars)))

    allowed = _doc_allowed_map()
    p = allowed.get(doc)
    if not p:
        return jsonify({"ok": False, "error": "doc_not_allowed"}), 400
    if not p.exists():
        return jsonify({"ok": False, "error": "doc_not_found"}), 404

    if start_line_raw is not None or end_line_raw is not None:
        try:
            start_line = int(start_line_raw or 1)
        except Exception:
            start_line = 1
        try:
            end_line = int(end_line_raw or start_line)
        except Exception:
            end_line = start_line
        out = _md_extract_lines(p, start_line=start_line, end_line=end_line, max_chars=max_chars)
        code = 200 if bool(out.get("ok")) else 404
        return jsonify(out), code

    if not section:
        out = _md_extract_lines(p, start_line=1, end_line=10**9, max_chars=max_chars)
        code = 200 if bool(out.get("ok")) else 404
        return jsonify(out), code

    out = _md_extract_section(p, section_key=section, max_chars=max_chars)
    code = 200 if bool(out.get("ok")) else 404
    return jsonify(out), code


@app.route("/strategy/params", methods=["GET"])
def strategy_params():
    cfg = CONFIG or {}
    sm = cfg.get("strategy_meta") or {}
    gm = cfg.get("signal_group_meta") or {}
    out = {}
    if isinstance(sm, dict):
        for sid, meta in sm.items():
            out[sid] = {
                "group_id": str((meta or {}).get("group_id") or ""),
                "feature_set_id": str((meta or {}).get("feature_set_id") or ""),
                "params": {}
            }
    try:
        rh_path = str(_user_data_dir() / "strategies" / "RegimeHybridStrategy.json")
        if os.path.exists(rh_path):
            with open(rh_path, "r", encoding="utf-8") as f:
                rh = json.load(f)
            out.setdefault("RegimeHybridStrategy", {"group_id": str((sm.get("RegimeHybridStrategy") or {}).get("group_id") or ""), "feature_set_id": str((sm.get("RegimeHybridStrategy") or {}).get("feature_set_id") or ""), "params": {}})
            params_root = rh.get("params") or {}
            b = rh.get("buy_params") or params_root.get("buy") or {}
            s = rh.get("sell_params") or params_root.get("sell") or {}
            mo = params_root.get("max_open_trades") or {}
            out["RegimeHybridStrategy"]["params"].update({
                "adx_threshold": b.get("adx_threshold"),
                "entry_votes_required": b.get("entry_votes_required"),
                "volume_mult": b.get("volume_mult"),
                "buy_rsi": b.get("buy_rsi"),
                "ema_fast": b.get("ema_fast"),
                "ema_medium": b.get("ema_medium"),
                "ema_slow": b.get("ema_slow"),
                "tolerance_atr_mult": b.get("tolerance_atr_mult"),
                "atr_multiplier": s.get("atr_multiplier"),
                "sell_rsi": s.get("sell_rsi"),
                "trail_atr_multiplier": s.get("trail_atr_multiplier"),
                "max_open_trades": mo.get("max_open_trades"),
            })
    except Exception:
        pass
    try:
        g_trend = gm.get("trend_4h_mtf") or {}
        out.setdefault("Strategy005", {"group_id": str((sm.get("Strategy005") or {}).get("group_id") or ""), "feature_set_id": str((sm.get("Strategy005") or {}).get("feature_set_id") or ""), "params": {}})
        out["Strategy005"]["params"].update({
            "pc_threshold_min": g_trend.get("pc_threshold_min"),
        })
        out.setdefault("MultiGroupStrategy", {"group_id": str((sm.get("MultiGroupStrategy") or {}).get("group_id") or ""), "feature_set_id": str((sm.get("MultiGroupStrategy") or {}).get("feature_set_id") or ""), "params": {}})
        out["MultiGroupStrategy"]["params"].update({
            "pc_threshold_min": g_trend.get("pc_threshold_min"),
        })
        g_br = gm.get("breakout_1h_confirmed") or {}
        out.setdefault("BreakoutStrategy", {"group_id": str((sm.get("BreakoutStrategy") or {}).get("group_id") or ""), "feature_set_id": str((sm.get("BreakoutStrategy") or {}).get("feature_set_id") or ""), "params": {}})
        out["BreakoutStrategy"]["params"].update({
            "pc_threshold_min": g_br.get("pc_threshold_min"),
            "buy_votes": None,
            "rsi_threshold": 70,
        })
    except Exception:
        pass
    return jsonify({"ok": True, "strategies": out})


