def _monitor_center_p_enter_snapshot(now_ms: int, strategy_id: Optional[str] = None) -> Dict[str, Any]:
    try:
        enabled = bool(CONFIG.get("monitor_center_enabled", True))
    except Exception:
        enabled = True
    if not enabled:
        return {"ok": False, "enabled": False}
    try:
        recent_min = int(CONFIG.get("monitor_center_p_enter_recent_minutes", 60) or 60)
    except Exception:
        recent_min = 60
    try:
        ref_h = int(CONFIG.get("monitor_center_p_enter_ref_hours", 24) or 24)
    except Exception:
        ref_h = 24
    try:
        ref_excl_min = int(CONFIG.get("monitor_center_p_enter_ref_exclude_minutes", 60) or 60)
    except Exception:
        ref_excl_min = 60
    try:
        bins = int(CONFIG.get("monitor_center_p_enter_bins", 10) or 10)
    except Exception:
        bins = 10
    try:
        min_recent = int(CONFIG.get("monitor_center_p_enter_min_recent", 100) or 100)
    except Exception:
        min_recent = 100
    try:
        min_ref = int(CONFIG.get("monitor_center_p_enter_min_ref", 300) or 300)
    except Exception:
        min_ref = 300

    recent_ms = int(max(1, recent_min)) * 60_000
    ref_ms = int(max(1, ref_h)) * 3600_000
    excl_ms = int(max(0, ref_excl_min)) * 60_000

    r = _monitor_center_collect_pc(since_ms=int(now_ms) - int(recent_ms), until_ms=int(now_ms), strategy_id=strategy_id)
    b = _monitor_center_collect_pc(since_ms=int(now_ms) - int(ref_ms), until_ms=int(now_ms) - int(excl_ms), strategy_id=strategy_id)
    r_pc = r.get("pc") if isinstance(r.get("pc"), list) else []
    b_pc = b.get("pc") if isinstance(b.get("pc"), list) else []

    r_hist = _monitor_center_hist01(r_pc, bins=int(bins))
    b_hist = _monitor_center_hist01(b_pc, bins=int(bins))
    psi = _monitor_center_psi(r_hist, b_hist)

    r_mean = (float(sum(r_pc)) / float(len(r_pc)) if r_pc else None)
    b_mean = (float(sum(b_pc)) / float(len(b_pc)) if b_pc else None)

    out = {
        "ok": True,
        "enabled": True,
        "ts": int(now_ms),
        "scope": (None if strategy_id is None else {"strategy_id": str(strategy_id)}),
        "recent": {
            "window_minutes": int(recent_min),
            "counts": {k: int(r.get(k) or 0) for k in ("total", "triggered", "executed", "enters", "holds", "rejects")},
            "pc_n": int(len(r_pc)),
            "pc_mean": (None if r_mean is None else float(r_mean)),
            "pc_q10": _monitor_center_quantile(r_pc, 0.10),
            "pc_q50": _monitor_center_quantile(r_pc, 0.50),
            "pc_q90": _monitor_center_quantile(r_pc, 0.90),
            "hist": r_hist,
        },
        "ref": {
            "window_hours": int(ref_h),
            "exclude_minutes": int(ref_excl_min),
            "counts": {k: int(b.get(k) or 0) for k in ("total", "triggered", "executed", "enters", "holds", "rejects")},
            "pc_n": int(len(b_pc)),
            "pc_mean": (None if b_mean is None else float(b_mean)),
            "pc_q10": _monitor_center_quantile(b_pc, 0.10),
            "pc_q50": _monitor_center_quantile(b_pc, 0.50),
            "pc_q90": _monitor_center_quantile(b_pc, 0.90),
            "hist": b_hist,
        },
        "drift": {"psi": (None if psi is None else float(psi)), "min_recent": int(min_recent), "min_ref": int(min_ref)},
    }

    stage = 0
    reason = None
    if int(len(r_pc)) >= int(min_recent) and int(len(b_pc)) >= int(min_ref) and psi is not None:
        try:
            s1 = float(CONFIG.get("monitor_center_p_enter_psi_stage1", 0.10) or 0.10)
        except Exception:
            s1 = 0.10
        try:
            s2 = float(CONFIG.get("monitor_center_p_enter_psi_stage2", 0.20) or 0.20)
        except Exception:
            s2 = 0.20
        try:
            s3 = float(CONFIG.get("monitor_center_p_enter_psi_stage3", 0.30) or 0.30)
        except Exception:
            s3 = 0.30
        if float(psi) >= float(s3):
            stage = 3
            reason = "p_enter_drift_stage3"
        elif float(psi) >= float(s2):
            stage = 2
            reason = "p_enter_drift_stage2"
        elif float(psi) >= float(s1):
            stage = 1
            reason = "p_enter_drift_stage1"
    out["drift"]["stage"] = int(stage)
    out["drift"]["reason"] = reason
    return out

def _monitor_center_update(now_ms: int) -> Dict[str, Any]:
    try:
        enabled = bool(CONFIG.get("monitor_center_enabled", True))
    except Exception:
        enabled = True
    if not enabled:
        TRACKER_STATE["monitor_center"] = {"ok": False, "enabled": False, "ts": int(now_ms)}
        return dict(TRACKER_STATE.get("monitor_center") or {})

    try:
        ord_wm = int(CONFIG.get("monitor_center_order_window_minutes", 60) or 60)
    except Exception:
        ord_wm = 60
    try:
        settle_wh = int(CONFIG.get("monitor_center_settle_window_hours", 24) or 24)
    except Exception:
        settle_wh = 24
    try:
        ord_ref_h = int(CONFIG.get("monitor_center_order_ref_hours", 24) or 24)
    except Exception:
        ord_ref_h = 24
    try:
        ord_ref_excl_min = int(CONFIG.get("monitor_center_order_ref_exclude_minutes", 60) or 60)
    except Exception:
        ord_ref_excl_min = 60
    try:
        settle_ref_h = int(CONFIG.get("monitor_center_settle_ref_hours", 168) or 168)
    except Exception:
        settle_ref_h = 168
    try:
        settle_ref_excl_h = int(CONFIG.get("monitor_center_settle_ref_exclude_hours", 24) or 24)
    except Exception:
        settle_ref_excl_h = 24
    try:
        min_orders_recent = int(CONFIG.get("monitor_center_orders_min_recent", 20) or 20)
    except Exception:
        min_orders_recent = 20
    try:
        min_orders_ref = int(CONFIG.get("monitor_center_orders_min_ref", 80) or 80)
    except Exception:
        min_orders_ref = 80
    try:
        min_settle_recent = int(CONFIG.get("monitor_center_settlements_min_recent", 30) or 30)
    except Exception:
        min_settle_recent = 30
    try:
        min_settle_ref = int(CONFIG.get("monitor_center_settlements_min_ref", 120) or 120)
    except Exception:
        min_settle_ref = 120
    p_enter = _monitor_center_p_enter_snapshot(int(now_ms))
    orders = _monitor_center_orders_snapshot(now_ms=int(now_ms), window_minutes=int(ord_wm))
    settles = _monitor_center_settlements_snapshot(now_ms=int(now_ms), window_hours=int(settle_wh))
    ord_recent = _monitor_center_orders_collect(since_ms=int(now_ms) - int(max(1, int(ord_wm))) * 60_000, until_ms=int(now_ms))
    ord_ref = _monitor_center_orders_collect(
        since_ms=int(now_ms) - int(max(1, int(ord_ref_h))) * 3600_000,
        until_ms=int(now_ms) - int(max(0, int(ord_ref_excl_min))) * 60_000,
    )
    settle_recent = _monitor_center_settlements_collect(since_ms=int(now_ms) - int(max(1, int(settle_wh))) * 3600_000, until_ms=int(now_ms))
    settle_ref = _monitor_center_settlements_collect(
        since_ms=int(now_ms) - int(max(1, int(settle_ref_h))) * 3600_000,
        until_ms=int(now_ms) - int(max(0, int(settle_ref_excl_h))) * 3600_000,
    )

    ts_sid = "ThreeScreen"
    p_enter_ts: Dict[str, Any] = {"ok": False, "enabled": False, "ts": int(now_ms), "scope": {"strategy_id": str(ts_sid)}}
    orders_ts: Dict[str, Any] = {}
    settles_ts: Dict[str, Any] = {}
    ord_recent_ts: Dict[str, Any] = {}
    ord_ref_ts: Dict[str, Any] = {}
    settle_recent_ts: Dict[str, Any] = {}
    settle_ref_ts: Dict[str, Any] = {}
    try:
        p_enter_ts = _monitor_center_p_enter_snapshot(int(now_ms), strategy_id=str(ts_sid))
    except Exception:
        pass
    try:
        orders_ts = _monitor_center_orders_snapshot(now_ms=int(now_ms), window_minutes=int(ord_wm), strategy_id=str(ts_sid))
    except Exception:
        orders_ts = {}
    try:
        settles_ts = _monitor_center_settlements_snapshot(now_ms=int(now_ms), window_hours=int(settle_wh), strategy_id=str(ts_sid))
    except Exception:
        settles_ts = {}
    try:
        ord_recent_ts = _monitor_center_orders_collect(since_ms=int(now_ms) - int(max(1, int(ord_wm))) * 60_000, until_ms=int(now_ms), strategy_id=str(ts_sid))
    except Exception:
        ord_recent_ts = {}
    try:
        ord_ref_ts = _monitor_center_orders_collect(
            since_ms=int(now_ms) - int(max(1, int(ord_ref_h))) * 3600_000,
            until_ms=int(now_ms) - int(max(0, int(ord_ref_excl_min))) * 60_000,
            strategy_id=str(ts_sid),
        )
    except Exception:
        ord_ref_ts = {}
    try:
        settle_recent_ts = _monitor_center_settlements_collect(
            since_ms=int(now_ms) - int(max(1, int(settle_wh))) * 3600_000,
            until_ms=int(now_ms),
            strategy_id=str(ts_sid),
        )
    except Exception:
        settle_recent_ts = {}
    try:
        settle_ref_ts = _monitor_center_settlements_collect(
            since_ms=int(now_ms) - int(max(1, int(settle_ref_h))) * 3600_000,
            until_ms=int(now_ms) - int(max(0, int(settle_ref_excl_h))) * 3600_000,
            strategy_id=str(ts_sid),
        )
    except Exception:
        settle_ref_ts = {}

    issues: List[str] = []
    stage = 0
    try:
        pstage = int(((p_enter or {}).get("drift") or {}).get("stage") or 0)
    except Exception:
        pstage = 0
    if pstage > 0:
        stage = max(stage, int(pstage))
        issues.append(str(((p_enter or {}).get("drift") or {}).get("reason") or "p_enter_drift"))

    try:
        pr = (p_enter or {}).get("recent") if isinstance((p_enter or {}).get("recent"), dict) else {}
        pb = (p_enter or {}).get("ref") if isinstance((p_enter or {}).get("ref"), dict) else {}
        cr = pr.get("counts") if isinstance(pr.get("counts"), dict) else {}
        cb = pb.get("counts") if isinstance(pb.get("counts"), dict) else {}
        tr_tot = int(cr.get("total") or 0)
        tb_tot = int(cb.get("total") or 0)
        tr_trig = int(cr.get("triggered") or 0)
        tb_trig = int(cb.get("triggered") or 0)
    except Exception:
        tr_tot, tb_tot, tr_trig, tb_trig = 0, 0, 0, 0
    if tr_tot >= 50 and tb_tot >= 200:
        try:
            s1 = float(CONFIG.get("monitor_center_trigger_rate_drop_stage1", 0.40) or 0.40)
        except Exception:
            s1 = 0.40
        try:
            s2 = float(CONFIG.get("monitor_center_trigger_rate_drop_stage2", 0.60) or 0.60)
        except Exception:
            s2 = 0.60
        try:
            s3 = float(CONFIG.get("monitor_center_trigger_rate_drop_stage3", 0.80) or 0.80)
        except Exception:
            s3 = 0.80
        tr_recent = float(tr_trig) / float(max(1, tr_tot))
        tr_ref = float(tb_trig) / float(max(1, tb_tot))
        tr_stage = _monitor_center_deviation_stage(recent=float(tr_recent), ref=float(tr_ref), s1=float(s1), s2=float(s2), s3=float(s3), kind="drop")
        if tr_stage > 0:
            stage = max(stage, int(tr_stage))
            issues.append("trigger_rate_drop")

    try:
        r_total = int(ord_recent.get("total_open") or 0)
        b_total = int(ord_ref.get("total_open") or 0)
    except Exception:
        r_total, b_total = 0, 0
    if r_total >= int(min_orders_recent) and b_total >= int(min_orders_ref):
        try:
            s1 = float(CONFIG.get("monitor_center_fill_rate_drop_stage1", 0.30) or 0.30)
        except Exception:
            s1 = 0.30
        try:
            s2 = float(CONFIG.get("monitor_center_fill_rate_drop_stage2", 0.50) or 0.50)
        except Exception:
            s2 = 0.50
        try:
            s3 = float(CONFIG.get("monitor_center_fill_rate_drop_stage3", 0.70) or 0.70)
        except Exception:
            s3 = 0.70
        fr_stage = _monitor_center_deviation_stage(
            recent=float(ord_recent.get("fill_rate") or 0.0),
            ref=float(ord_ref.get("fill_rate") or 0.0),
            s1=float(s1),
            s2=float(s2),
            s3=float(s3),
            kind="drop",
        )
        if fr_stage > 0:
            stage = max(stage, int(fr_stage))
            issues.append("fill_rate_drop")

    try:
        r_n = int(settle_recent.get("n") or 0)
        b_n = int(settle_ref.get("n") or 0)
    except Exception:
        r_n, b_n = 0, 0
    if r_n >= int(min_settle_recent) and b_n >= int(min_settle_ref):
        try:
            rs = settle_recent.get("slippage_ratio_mean")
            bs = settle_ref.get("slippage_ratio_mean")
            if rs is not None and bs is not None and math.isfinite(float(rs)) and math.isfinite(float(bs)) and float(bs) > 0:
                try:
                    s1 = float(CONFIG.get("monitor_center_slippage_rise_stage1", 0.50) or 0.50)
                except Exception:
                    s1 = 0.50
                try:
                    s2 = float(CONFIG.get("monitor_center_slippage_rise_stage2", 1.00) or 1.00)
                except Exception:
                    s2 = 1.00
                try:
                    s3 = float(CONFIG.get("monitor_center_slippage_rise_stage3", 1.50) or 1.50)
                except Exception:
                    s3 = 1.50
                st_s = _monitor_center_deviation_stage(recent=float(rs), ref=float(bs), s1=float(s1), s2=float(s2), s3=float(s3), kind="rise")
                if st_s > 0:
                    stage = max(stage, int(st_s))
                    issues.append("slippage_rise")
        except Exception:
            pass

        try:
            rr = settle_recent.get("net_ret_mean")
            br = settle_ref.get("net_ret_mean")
            if rr is not None and br is not None and math.isfinite(float(rr)) and math.isfinite(float(br)):
                try:
                    base_min = float(CONFIG.get("monitor_center_net_ret_ref_min_abs", 0.001) or 0.001)
                except Exception:
                    base_min = 0.001
                if float(abs(float(br))) >= float(base_min) - 1e-12:
                    try:
                        s1 = float(CONFIG.get("monitor_center_net_ret_drop_stage1", 0.50) or 0.50)
                    except Exception:
                        s1 = 0.50
                    try:
                        s2 = float(CONFIG.get("monitor_center_net_ret_drop_stage2", 0.75) or 0.75)
                    except Exception:
                        s2 = 0.75
                    try:
                        s3 = float(CONFIG.get("monitor_center_net_ret_drop_stage3", 0.90) or 0.90)
                    except Exception:
                        s3 = 0.90
                    st_r = _monitor_center_deviation_stage(recent=float(rr), ref=float(br), s1=float(s1), s2=float(s2), s3=float(s3), kind="drop")
                    if st_r > 0:
                        stage = max(stage, int(st_r))
                        issues.append("net_ret_drop")
        except Exception:
            pass

    degradation = {
        "ok": True,
        "ts": int(now_ms),
        "stage": int(stage),
        "issues": [str(x) for x in issues if str(x or "").strip()][:20],
        "inputs": {
            "orders_recent": {"window_minutes": int(ord_wm), "n": int(ord_recent.get("total_open") or 0)},
            "orders_ref": {"window_hours": int(ord_ref_h), "exclude_minutes": int(ord_ref_excl_min), "n": int(ord_ref.get("total_open") or 0)},
            "settle_recent": {"window_hours": int(settle_wh), "n": int(settle_recent.get("n") or 0)},
            "settle_ref": {"window_hours": int(settle_ref_h), "exclude_hours": int(settle_ref_excl_h), "n": int(settle_ref.get("n") or 0)},
        },
    }

    try:
        auto_en = bool(CONFIG.get("monitor_center_auto_degrade_enabled", True))
    except Exception:
        auto_en = True

    TRACKER_STATE["entry_degradation_global"] = {"ts": int(now_ms), "source": "monitor_center", "enabled": bool(auto_en), "stage": int(stage), "issues": degradation.get("issues")}

    issues_ts: List[str] = []
    stage_ts = 0
    try:
        pstage_ts = int(((p_enter_ts or {}).get("drift") or {}).get("stage") or 0)
    except Exception:
        pstage_ts = 0
    if pstage_ts > 0:
        stage_ts = max(stage_ts, int(pstage_ts))
        issues_ts.append(str(((p_enter_ts or {}).get("drift") or {}).get("reason") or "p_enter_drift"))

    try:
        pr = (p_enter_ts or {}).get("recent") if isinstance((p_enter_ts or {}).get("recent"), dict) else {}
        pb = (p_enter_ts or {}).get("ref") if isinstance((p_enter_ts or {}).get("ref"), dict) else {}
        cr = pr.get("counts") if isinstance(pr.get("counts"), dict) else {}
        cb = pb.get("counts") if isinstance(pb.get("counts"), dict) else {}
        tr_tot = int(cr.get("total") or 0)
        tb_tot = int(cb.get("total") or 0)
        tr_trig = int(cr.get("triggered") or 0)
        tb_trig = int(cb.get("triggered") or 0)
    except Exception:
        tr_tot, tb_tot, tr_trig, tb_trig = 0, 0, 0, 0
    if tr_tot >= 50 and tb_tot >= 200:
        try:
            s1 = float(CONFIG.get("monitor_center_trigger_rate_drop_stage1", 0.40) or 0.40)
        except Exception:
            s1 = 0.40
        try:
            s2 = float(CONFIG.get("monitor_center_trigger_rate_drop_stage2", 0.60) or 0.60)
        except Exception:
            s2 = 0.60
        try:
            s3 = float(CONFIG.get("monitor_center_trigger_rate_drop_stage3", 0.80) or 0.80)
        except Exception:
            s3 = 0.80
        tr_recent = float(tr_trig) / float(max(1, tr_tot))
        tr_ref = float(tb_trig) / float(max(1, tb_tot))
        tr_stage = _monitor_center_deviation_stage(recent=float(tr_recent), ref=float(tr_ref), s1=float(s1), s2=float(s2), s3=float(s3), kind="drop")
        if tr_stage > 0:
            stage_ts = max(stage_ts, int(tr_stage))
            issues_ts.append("trigger_rate_drop")

    try:
        r_total = int(ord_recent_ts.get("total_open") or 0)
        b_total = int(ord_ref_ts.get("total_open") or 0)
    except Exception:
        r_total, b_total = 0, 0
    if r_total >= int(min_orders_recent) and b_total >= int(min_orders_ref):
        try:
            s1 = float(CONFIG.get("monitor_center_fill_rate_drop_stage1", 0.30) or 0.30)
        except Exception:
            s1 = 0.30
        try:
            s2 = float(CONFIG.get("monitor_center_fill_rate_drop_stage2", 0.50) or 0.50)
        except Exception:
            s2 = 0.50
        try:
            s3 = float(CONFIG.get("monitor_center_fill_rate_drop_stage3", 0.70) or 0.70)
        except Exception:
            s3 = 0.70
        fr_stage = _monitor_center_deviation_stage(
            recent=float(ord_recent_ts.get("fill_rate") or 0.0),
            ref=float(ord_ref_ts.get("fill_rate") or 0.0),
            s1=float(s1),
            s2=float(s2),
            s3=float(s3),
            kind="drop",
        )
        if fr_stage > 0:
            stage_ts = max(stage_ts, int(fr_stage))
            issues_ts.append("fill_rate_drop")

    try:
        r_n = int(settle_recent_ts.get("n") or 0)
        b_n = int(settle_ref_ts.get("n") or 0)
    except Exception:
        r_n, b_n = 0, 0
    if r_n >= int(min_settle_recent) and b_n >= int(min_settle_ref):
        try:
            rs = settle_recent_ts.get("slippage_ratio_mean")
            bs = settle_ref_ts.get("slippage_ratio_mean")
            if rs is not None and bs is not None and math.isfinite(float(rs)) and math.isfinite(float(bs)) and float(bs) > 0:
                try:
                    s1 = float(CONFIG.get("monitor_center_slippage_rise_stage1", 0.50) or 0.50)
                except Exception:
                    s1 = 0.50
                try:
                    s2 = float(CONFIG.get("monitor_center_slippage_rise_stage2", 1.00) or 1.00)
                except Exception:
                    s2 = 1.00
                try:
                    s3 = float(CONFIG.get("monitor_center_slippage_rise_stage3", 1.50) or 1.50)
                except Exception:
                    s3 = 1.50
                st_s = _monitor_center_deviation_stage(recent=float(rs), ref=float(bs), s1=float(s1), s2=float(s2), s3=float(s3), kind="rise")
                if st_s > 0:
                    stage_ts = max(stage_ts, int(st_s))
                    issues_ts.append("slippage_rise")
        except Exception:
            pass

        try:
            rr = settle_recent_ts.get("net_ret_mean")
            br = settle_ref_ts.get("net_ret_mean")
            if rr is not None and br is not None and math.isfinite(float(rr)) and math.isfinite(float(br)):
                try:
                    base_min = float(CONFIG.get("monitor_center_net_ret_ref_min_abs", 0.001) or 0.001)
                except Exception:
                    base_min = 0.001
                if float(abs(float(br))) >= float(base_min) - 1e-12:
                    try:
                        s1 = float(CONFIG.get("monitor_center_net_ret_drop_stage1", 0.50) or 0.50)
                    except Exception:
                        s1 = 0.50
                    try:
                        s2 = float(CONFIG.get("monitor_center_net_ret_drop_stage2", 0.75) or 0.75)
                    except Exception:
                        s2 = 0.75
                    try:
                        s3 = float(CONFIG.get("monitor_center_net_ret_drop_stage3", 0.90) or 0.90)
                    except Exception:
                        s3 = 0.90
                    st_r = _monitor_center_deviation_stage(recent=float(rr), ref=float(br), s1=float(s1), s2=float(s2), s3=float(s3), kind="drop")
                    if st_r > 0:
                        stage_ts = max(stage_ts, int(st_r))
                        issues_ts.append("net_ret_drop")
        except Exception:
            pass

    degradation_ts = {
        "ok": True,
        "ts": int(now_ms),
        "scope": {"strategy_id": str(ts_sid)},
        "stage": int(stage_ts),
        "issues": [str(x) for x in issues_ts if str(x or "").strip()][:20],
        "inputs": {
            "orders_recent": {"window_minutes": int(ord_wm), "n": int(ord_recent_ts.get("total_open") or 0)},
            "orders_ref": {"window_hours": int(ord_ref_h), "exclude_minutes": int(ord_ref_excl_min), "n": int(ord_ref_ts.get("total_open") or 0)},
            "settle_recent": {"window_hours": int(settle_wh), "n": int(settle_recent_ts.get("n") or 0)},
            "settle_ref": {"window_hours": int(settle_ref_h), "exclude_hours": int(settle_ref_excl_h), "n": int(settle_ref_ts.get("n") or 0)},
        },
    }
    TRACKER_STATE["entry_degradation"] = {"ts": int(now_ms), "source": "monitor_center", "enabled": bool(auto_en), "stage": int(stage_ts), "issues": degradation_ts.get("issues"), "scope": {"strategy_id": str(ts_sid)}}

    out = {
        "ok": True,
        "enabled": True,
        "ts": int(now_ms),
        "p_enter": p_enter,
        "orders": orders,
        "settlements": settles,
        "orders_ref": {"window_hours": int(ord_ref_h), "exclude_minutes": int(ord_ref_excl_min), **dict(ord_ref)},
        "settlements_ref": {"window_hours": int(settle_ref_h), "exclude_hours": int(settle_ref_excl_h), **dict(settle_ref)},
        "degradation": degradation,
        "three_screen": {
            "ok": True,
            "scope": {"strategy_id": str(ts_sid)},
            "p_enter": p_enter_ts,
            "orders": orders_ts,
            "settlements": settles_ts,
            "orders_ref": {"window_hours": int(ord_ref_h), "exclude_minutes": int(ord_ref_excl_min), **dict(ord_ref_ts)},
            "settlements_ref": {"window_hours": int(settle_ref_h), "exclude_hours": int(settle_ref_excl_h), **dict(settle_ref_ts)},
            "degradation": degradation_ts,
        },
    }
    TRACKER_STATE["monitor_center"] = out
    return dict(out)

def _run_janitor(now_ms: int) -> Dict[str, Any]:
    stats: Dict[str, Any] = {"deleted_events": 0, "deleted_orders": 0, "deleted_samples": 0, "arena_history_trim": 0, "arena_attrib_trim": 0, "cache_trim": 0}
    try:
        protect_core = bool(CONFIG.get("janitor_cache_protect_core", True))
        protect_universe = bool(CONFIG.get("janitor_protect_universe", True))
        protect_open = bool(CONFIG.get("janitor_protect_open_positions", True))
        protected_pairs = set()
        protected_coins = set()
        if protect_universe:
            try:
                for c in (UNIVERSE_STATE.get("core") or []):
                    protected_coins.add(str(c).upper())
            except Exception:
                pass
        if protect_open:
            try:
                for p in (TRACKER_STATE.get("open_positions") or {}).keys():
                    protected_pairs.add(str(p).upper())
            except Exception:
                pass
        # EVENTS cleanup
        try:
            ttl_h = float(CONFIG.get("events_ttl_hours", 24) or 24)
        except Exception:
            ttl_h = 24.0
        try:
            max_n = int(CONFIG.get("events_max_count", 10000) or 10000)
        except Exception:
            max_n = 10000
        ttl_ms = int(ttl_h * 3600 * 1000)
        evs = list(EVENTS.items())
        evs.sort(key=lambda kv: int((kv[1] or {}).get("ts") or 0))
        # preserve event_ids used by orders
        used_eids = set()
        try:
            for o in ORDERS.values():
                eid = (o or {}).get("event_id")
                if eid:
                    used_eids.add(str(eid))
        except Exception:
            pass
        # remove by ttl
        for k, v in evs:
            ts = int((v or {}).get("ts") or 0)
            pair_s = str((v or {}).get("pair") or "").upper()
            if ts > 0 and (now_ms - ts) > ttl_ms and (str(k) not in used_eids) and (pair_s not in protected_pairs):
                try:
                    del EVENTS[str(k)]
                    stats["deleted_events"] += 1
                except Exception:
                    pass
        # remove by max_n
        if max_n > 0 and len(EVENTS) > max_n:
            evs2 = list(EVENTS.items())
            evs2.sort(key=lambda kv: int((kv[1] or {}).get("ts") or 0))
            excess = len(EVENTS) - int(max_n)
            i = 0
            for k, v in evs2:
                if i >= excess:
                    break
                if str(k) in used_eids:
                    continue
                pair_s = str((v or {}).get("pair") or "").upper()
                if pair_s in protected_pairs:
                    continue
                try:
                    del EVENTS[str(k)]
                    stats["deleted_events"] += 1
                    i += 1
                except Exception:
                    pass
        # ORDERS cleanup
        def _is_terminal_order(o: Dict[str, Any]) -> bool:
            try:
                st = str((o or {}).get("status") or "").strip().lower()
            except Exception:
                st = ""
            if not st:
                return False
            return st in {"filled", "failed", "canceled", "cancelled", "rejected", "closed", "expired"}
        try:
            ttl_h_o = float(CONFIG.get("orders_ttl_hours", 72) or 72)
        except Exception:
            ttl_h_o = 72.0
        try:
            max_n_o = int(CONFIG.get("orders_max_count", 10000) or 10000)
        except Exception:
            max_n_o = 10000
        ttl_ms_o = int(ttl_h_o * 3600 * 1000)
        ords = list(ORDERS.items())
        ords.sort(key=lambda kv: int((kv[1] or {}).get("ts") or 0))
        for k, v in ords:
            ts = int((v or {}).get("ts") or 0)
            pair_s = str((v or {}).get("pair") or "").upper()
            if not _is_terminal_order(v):
                continue
            if ts > 0 and (now_ms - ts) > ttl_ms_o and (pair_s not in protected_pairs):
                try:
                    del ORDERS[str(k)]
                    stats["deleted_orders"] += 1
                except Exception:
                    pass
        if max_n_o > 0 and len(ORDERS) > max_n_o:
            ords2 = list(ORDERS.items())
            ords2.sort(key=lambda kv: int((kv[1] or {}).get("ts") or 0))
            excess = len(ORDERS) - int(max_n_o)
            i = 0
            for k, v in ords2:
                if i >= excess:
                    break
                if not _is_terminal_order(v):
                    continue
                pair_s = str((v or {}).get("pair") or "").upper()
                if pair_s in protected_pairs:
                    continue
                try:
                    del ORDERS[str(k)]
                    stats["deleted_orders"] += 1
                    i += 1
                except Exception:
                    pass

        # EVAL_SAMPLES cleanup (bounded memory)
        try:
            ttl_h_s = float(CONFIG.get("eval_samples_ttl_hours", 0) or 0)
        except Exception:
            ttl_h_s = 0.0
        try:
            max_n_s = int(CONFIG.get("eval_samples_max_count", 200000) or 200000)
        except Exception:
            max_n_s = 200000
        try:
            protect_recent = int(CONFIG.get("eval_samples_protect_recent", 5000) or 5000)
        except Exception:
            protect_recent = 5000
        protect_recent = max(0, min(100000, int(protect_recent)))
        if isinstance(EVAL_SAMPLES, list) and EVAL_SAMPLES:
            if ttl_h_s > 0:
                ttl_ms_s = int(float(ttl_h_s) * 3600.0 * 1000.0)
                cutoff = int(now_ms) - int(ttl_ms_s)
                n0 = int(len(EVAL_SAMPLES))
                if protect_recent > 0 and n0 > protect_recent:
                    head = EVAL_SAMPLES[:-protect_recent]
                    tail = EVAL_SAMPLES[-protect_recent:]
                else:
                    head = EVAL_SAMPLES
                    tail = []
                kept_head = []
                for s in head:
                    try:
                        ts = int((s or {}).get("ts") or 0)
                    except Exception:
                        ts = 0
                    if ts <= 0 or ts >= cutoff:
                        kept_head.append(s)
                if tail:
                    EVAL_SAMPLES[:] = kept_head + tail
                else:
                    EVAL_SAMPLES[:] = kept_head
                stats["deleted_samples"] += int(max(0, n0 - len(EVAL_SAMPLES)))

            if max_n_s > 0 and len(EVAL_SAMPLES) > max_n_s:
                n0 = int(len(EVAL_SAMPLES))
                EVAL_SAMPLES[:] = EVAL_SAMPLES[-int(max_n_s):]
                stats["deleted_samples"] += int(max(0, n0 - len(EVAL_SAMPLES)))
        # ARENA history/attrib trim
        try:
            ah_max = int(CONFIG.get("arena_history_max", 2000) or 2000)
        except Exception:
            ah_max = 2000
        try:
            at_max = int(CONFIG.get("arena_attrib_max", 5000) or 5000)
        except Exception:
            at_max = 5000
        try:
            hist = ARENA_STATE.get("history")
            if isinstance(hist, list) and ah_max > 0 and len(hist) > ah_max:
                ARENA_STATE["history"] = hist[-ah_max:]
                stats["arena_history_trim"] = int(len(hist) - ah_max)
        except Exception:
            pass
        try:
            attrib = ARENA_STATE.get("attrib")
            if isinstance(attrib, list) and at_max > 0 and len(attrib) > at_max:
                ARENA_STATE["attrib"] = attrib[-at_max:]
                stats["arena_attrib_trim"] = int(len(attrib) - at_max)
        except Exception:
            pass
        # HL candles cache size cap
        try:
            cmax = int(CONFIG.get("hl_candles_cache_max_items", 1000) or 1000)
        except Exception:
            cmax = 1000
        try:
            if cmax > 0 and isinstance(HL_CANDLES_CACHE, dict) and len(HL_CANDLES_CACHE) > cmax:
                ks = list(HL_CANDLES_CACHE.keys())
                cap = max(0, len(HL_CANDLES_CACHE) - cmax)
                removed = 0
                for k in ks:
                    if removed >= cap:
                        break
                    k_s = str(k).upper()
                    if protect_core:
                        skip = False
                        for pc in protected_coins:
                            if pc and pc in k_s:
                                skip = True
                                break
                        if skip:
                            continue
                    try:
                        del HL_CANDLES_CACHE[str(k)]
                        stats["cache_trim"] += 1
                        removed += 1
                    except Exception:
                        pass
        except Exception:
            pass
        # correlation cache size cap
        try:
            ccmax = int(CONFIG.get("correlation_cache_max_items", 3000) or 3000)
        except Exception:
            ccmax = 3000
        try:
            if ccmax > 0 and isinstance(CORR_CACHE, dict) and len(CORR_CACHE) > ccmax:
                ks = list(CORR_CACHE.keys())
                cap = max(0, len(CORR_CACHE) - ccmax)
                removed = 0
                for k in ks:
                    if removed >= cap:
                        break
                    k_s = str(k).upper()
                    if protect_core:
                        skip = False
                        for pp in list(protected_pairs) or []:
                            if pp and pp in k_s:
                                skip = True
                                break
                        if skip:
                            continue
                    try:
                        del CORR_CACHE[str(k)]
                        stats["cache_trim"] += 1
                        removed += 1
                    except Exception:
                        pass
        except Exception:
            pass

        try:
            pcmax = int(CONFIG.get("pair_cache_max_items", 400) or 400)
        except Exception:
            pcmax = 400
        try:
            if pcmax > 0 and isinstance(PAIR_CACHE, dict) and len(PAIR_CACHE) > pcmax:
                items = list(PAIR_CACHE.items())
                items.sort(key=lambda kv: float((kv[1] or {}).get("mtime", 0.0)) if isinstance(kv[1], dict) else 0.0)
                cap = max(0, len(PAIR_CACHE) - pcmax)
                removed = 0
                for k, _ in items:
                    if removed >= cap:
                        break
                    k_s = str(k).upper()
                    if protect_core:
                        skip = False
                        for pc in protected_coins:
                            if pc and pc in k_s:
                                skip = True
                                break
                        if skip:
                            continue
                    try:
                        del PAIR_CACHE[str(k)]
                        stats["cache_trim"] += 1
                        removed += 1
                    except Exception:
                        pass
        except Exception:
            pass

        try:
            fcmax = int(CONFIG.get("hl_funding_cache_max_items", 1000) or 1000)
        except Exception:
            fcmax = 1000
        try:
            if fcmax > 0 and isinstance(HL_FUNDING_HISTORY_CACHE, dict) and len(HL_FUNDING_HISTORY_CACHE) > fcmax:
                ks = list(HL_FUNDING_HISTORY_CACHE.keys())
                cap = max(0, len(HL_FUNDING_HISTORY_CACHE) - fcmax)
                removed = 0
                for k in ks:
                    if removed >= cap:
                        break
                    try:
                        del HL_FUNDING_HISTORY_CACHE[str(k)]
                        stats["cache_trim"] += 1
                        removed += 1
                    except Exception:
                        pass
        except Exception:
            pass

        try:
            mcmax = int(CONFIG.get("macro_cache_max_items", 2000) or 2000)
        except Exception:
            mcmax = 2000
        try:
            items = MACRO_CACHE.get("items")
            if mcmax > 0 and isinstance(items, dict) and len(items) > mcmax:
                ks = list(items.keys())
                cap = max(0, len(items) - mcmax)
                removed = 0
                for k in ks:
                    if removed >= cap:
                        break
                    try:
                        del items[str(k)]
                        stats["cache_trim"] += 1
                        removed += 1
                    except Exception:
                        pass
        except Exception:
            pass

        try:
            ammax = int(CONFIG.get("artifact_meta_cache_max_items", 500) or 500)
        except Exception:
            ammax = 500
        try:
            if ammax > 0 and isinstance(_ARTIFACT_META_CACHE, dict) and len(_ARTIFACT_META_CACHE) > ammax:
                ks = list(_ARTIFACT_META_CACHE.keys())
                cap = max(0, len(_ARTIFACT_META_CACHE) - ammax)
                removed = 0
                for k in ks:
                    if removed >= cap:
                        break
                    try:
                        del _ARTIFACT_META_CACHE[str(k)]
                        stats["cache_trim"] += 1
                        removed += 1
                    except Exception:
                        pass
        except Exception:
            pass
        try:
            akmax = int(CONFIG.get("arena_feature_keys_cache_max_items", 2000) or 2000)
        except Exception:
            akmax = 2000
        try:
            if akmax > 0 and isinstance(_ARENA_FEATURE_KEYS_CACHE, dict) and len(_ARENA_FEATURE_KEYS_CACHE) > akmax:
                ks = list(_ARENA_FEATURE_KEYS_CACHE.keys())
                cap = max(0, len(_ARENA_FEATURE_KEYS_CACHE) - akmax)
                removed = 0
                for k in ks:
                    if removed >= cap:
                        break
                    try:
                        del _ARENA_FEATURE_KEYS_CACHE[k]
                        stats["cache_trim"] += 1
                        removed += 1
                    except Exception:
                        pass
        except Exception:
            pass
    except Exception:
        pass
    return {"ok": True, "ts": int(now_ms), **stats}


def _path_is_within(child: Path, parent: Path) -> bool:
    try:
        c = Path(child).expanduser().resolve(strict=False)
        p = Path(parent).expanduser().resolve(strict=False)
    except Exception:
        return False
    if c == p:
        return True
    try:
        return p in c.parents
    except Exception:
        return False


def _disk_retention_protected_paths() -> List[Path]:
    raw = CONFIG.get("disk_retention_protected_paths")
    items = raw if isinstance(raw, list) else []
    out: List[Path] = []
    for it in items:
        s = str(it or "").strip()
        if not s:
            continue
        try:
            p0 = Path(s).expanduser()
            if p0.is_absolute():
                out.append(p0.resolve(strict=False))
                continue
        except Exception:
            pass

        if s == "user_data" or s.startswith("user_data/"):
            rel = "" if s == "user_data" else s.split("/", 1)[1]
            try:
                out.append((_user_data_dir() / rel).resolve(strict=False))
            except Exception:
                continue
        else:
            try:
                out.append((Path(os.path.dirname(__file__)) / s).resolve(strict=False))
            except Exception:
                continue
    for s in (
        "user_data/datasets",
        "user_data/data",
        "user_data/tracker_state.json",
        "user_data/arena_state.json",
        "user_data/ml_config.json",
    ):
        rel = "" if s == "user_data" else s.split("/", 1)[1]
        try:
            out.append((_user_data_dir() / rel).resolve(strict=False))
        except Exception:
            pass
    uniq: List[Path] = []
    seen = set()
    for p in out:
        k = str(p)
        if k in seen:
            continue
        seen.add(k)
        uniq.append(p)
    return uniq


def _disk_retention_is_protected(path: Path, protected: List[Path]) -> bool:
    p = Path(path)
    for base in protected or []:
        if _path_is_within(p, base):
            return True
    return False


def _dir_size_bytes(path: Path, *, glob_pat: str = "*") -> int:
    total = 0
    try:
        for q in Path(path).glob(glob_pat):
            try:
                if q.is_file():
                    total += int(q.stat().st_size)
            except Exception:
                pass
    except Exception:
        return int(total)
    return int(total)


def _gzip_compress_file(src: Path, dst: Path, *, keep_src: bool = False) -> Tuple[bool, int, int]:
    s = Path(src)
    d = Path(dst)
    try:
        b0 = int(s.stat().st_size)
    except Exception:
        b0 = 0
    tmp = d.with_suffix(d.suffix + ".tmp")
    try:
        with open(s, "rb") as f_in:
            with gzip.open(tmp, "wb", compresslevel=6) as f_out:
                shutil.copyfileobj(f_in, f_out, length=1024 * 1024)
        os.replace(str(tmp), str(d))
        try:
            b1 = int(d.stat().st_size)
        except Exception:
            b1 = 0
        if not bool(keep_src):
            try:
                os.unlink(str(s))
            except Exception:
                pass
        return True, int(b0), int(b1)
    except Exception:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        try:
            if d.exists() and (not s.exists()):
                return True, int(b0), int(d.stat().st_size)
        except Exception:
            pass
        return False, int(b0), 0


def _run_datasets_archive(now_ms: int, *, dry_run: Optional[bool] = None) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "ok": True,
        "enabled": bool(CONFIG.get("datasets_archive_enabled", True)),
        "dry_run": None,
        "scanned": 0,
        "candidates": 0,
        "compressed": 0,
        "processed": 0,
        "bytes_freed": 0,
        "bytes_before": 0,
        "bytes_after": 0,
        "planned": [],
    }
    enabled = bool(out.get("enabled"))
    if not enabled:
        out["dry_run"] = bool(dry_run) if dry_run is not None else bool(CONFIG.get("datasets_archive_dry_run", True))
        return out

    try:
        do_dry = bool(CONFIG.get("datasets_archive_dry_run", True)) if dry_run is None else bool(dry_run)
    except Exception:
        do_dry = True
    out["dry_run"] = bool(do_dry)

    try:
        gzip_after_days = int(CONFIG.get("datasets_archive_gzip_after_days", 7) or 7)
    except Exception:
        gzip_after_days = 7
    gzip_after_days = max(0, min(36500, int(gzip_after_days)))

    try:
        max_files = int(CONFIG.get("datasets_archive_max_files_per_run", 50) or 50)
    except Exception:
        max_files = 50
    try:
        max_bytes = int(CONFIG.get("datasets_archive_max_bytes_per_run", 1073741824) or 1073741824)
    except Exception:
        max_bytes = 1073741824
    max_files = max(0, int(max_files))
    max_bytes = max(0, int(max_bytes))

    ds = _user_data_dir() / "datasets"
    if (not ds.exists()) or (not ds.is_dir()):
        return out

    pats = ["*_events.jsonl", "*_orders.jsonl", "*_funding_rates_*.jsonl"]
    items: List[Dict[str, Any]] = []
    for pat in pats:
        try:
            for p in ds.glob(pat):
                if not p.is_file():
                    continue
                try:
                    st = p.stat()
                except Exception:
                    continue
                items.append({
                    "path": p,
                    "name": p.name,
                    "size": int(st.st_size),
                    "mtime_ms": int(float(st.st_mtime) * 1000.0),
                })
        except Exception:
            pass

    items = [it for it in items if isinstance(it.get("path"), Path)]
    try:
        out["scanned"] = int(len(items))
    except Exception:
        out["scanned"] = 0

    def _recent_hot(mtime_ms: int) -> bool:
        try:
            return (int(now_ms) - int(mtime_ms)) < int(10 * 60 * 1000)
        except Exception:
            return False

    candidates: List[Dict[str, Any]] = []
    for it in items:
        p = it.get("path")
        if not isinstance(p, Path):
            continue
        if str(p.name).lower().endswith(".jsonl.gz"):
            continue
        try:
            if _recent_hot(int(it.get("mtime_ms") or 0)):
                continue
        except Exception:
            pass
        age = _age_days_from_day_prefix(str(it.get("name") or ""), now_ms=int(now_ms), mtime_ms=int(it.get("mtime_ms") or 0))
        if age < int(gzip_after_days):
            continue
        dst = Path(str(p) + ".gz")
        if dst.exists():
            continue
        candidates.append({**it, "age_days": int(age), "dst": dst})

    candidates.sort(key=lambda x: (int(x.get("mtime_ms") or 0), -int(x.get("size") or 0)))
    out["candidates"] = int(len(candidates))

    bytes_before = int(sum(int(it.get("size") or 0) for it in candidates))
    out["bytes_before"] = int(bytes_before)

    planned: List[Dict[str, Any]] = []
    compressed = 0
    processed = 0
    bytes_processed = 0
    bytes_freed = 0
    bytes_after = 0

    def _can_process(size_hint: int) -> bool:
        if max_files > 0 and processed >= max_files:
            return False
        if max_bytes > 0 and bytes_processed >= max_bytes:
            return False
        if max_bytes > 0 and (bytes_processed + int(size_hint)) > max_bytes:
            return False
        return True

    for it in candidates:
        p = it.get("path")
        dst = it.get("dst")
        if not isinstance(p, Path) or not isinstance(dst, Path):
            continue
        size0 = int(it.get("size") or 0)
        if not _can_process(size0):
            break

        rec = {
            "action": "gzip",
            "src": str(p),
            "dst": str(dst),
            "size": int(size0),
            "age_days": int(it.get("age_days") or 0),
        }
        if do_dry:
            planned.append(rec)
        else:
            ok, b0, b1 = _gzip_compress_file(p, dst, keep_src=True)
            if ok:
                compressed += 1
                bytes_after += int(size0) + int(b1)
        processed += 1
        bytes_processed += int(size0)

    out["planned"] = planned[:50]
    out["compressed"] = int(compressed)
    out["processed"] = int(processed)
    out["bytes_freed"] = int(bytes_freed)
    out["bytes_after"] = int(bytes_after)

    try:
        if not do_dry and (compressed > 0 or processed > 0):
            LOG.info("datasets_archive %s", json.dumps({
                "compressed": int(compressed),
                "processed": int(processed),
                "bytes_freed": int(bytes_freed),
                "gzip_after_days": int(gzip_after_days),
            }, ensure_ascii=False, separators=(",", ":"))[:2000])
    except Exception:
        pass
    return out


def _run_datasets_cleanup(now_ms: int, *, dry_run: Optional[bool] = None) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "ok": True,
        "enabled": bool(CONFIG.get("datasets_cleanup_enabled", False)),
        "dry_run": None,
        "scanned": 0,
        "candidates": 0,
        "deleted": 0,
        "processed": 0,
        "bytes_freed": 0,
        "planned": [],
        "by_type": {"events": {"deleted": 0, "bytes_freed": 0}, "orders": {"deleted": 0, "bytes_freed": 0}, "funding": {"deleted": 0, "bytes_freed": 0}},
    }
    enabled = bool(out.get("enabled"))
    if not enabled:
        out["dry_run"] = bool(dry_run) if dry_run is not None else bool(CONFIG.get("datasets_cleanup_dry_run", True))
        return out

    try:
        do_dry = bool(CONFIG.get("datasets_cleanup_dry_run", True)) if dry_run is None else bool(dry_run)
    except Exception:
        do_dry = True
    out["dry_run"] = bool(do_dry)

    def _keep_days(key: str, default_v: int) -> int:
        try:
            v = int(CONFIG.get(key, default_v) or default_v)
        except Exception:
            v = int(default_v)
        return max(0, min(36500, int(v)))

    keep_events = _keep_days("datasets_cleanup_keep_days_events", 30)
    keep_orders = _keep_days("datasets_cleanup_keep_days_orders", 365)
    keep_funding = _keep_days("datasets_cleanup_keep_days_funding", 90)
    keep_by_kind = {"events": int(keep_events), "orders": int(keep_orders), "funding": int(keep_funding)}

    try:
        max_files = int(CONFIG.get("datasets_cleanup_max_files_per_run", 200) or 200)
    except Exception:
        max_files = 200
    try:
        max_bytes = int(CONFIG.get("datasets_cleanup_max_bytes_per_run", 2147483648) or 2147483648)
    except Exception:
        max_bytes = 2147483648
    max_files = max(0, int(max_files))
    max_bytes = max(0, int(max_bytes))

    ds = _user_data_dir() / "datasets"
    if (not ds.exists()) or (not ds.is_dir()):
        return out

    def _recent_hot(mtime_ms: int) -> bool:
        try:
            return (int(now_ms) - int(mtime_ms)) < int(10 * 60 * 1000)
        except Exception:
            return False

    def _kind_for_name(name: str) -> Optional[str]:
        nm = str(name or "").lower()
        if "_events.jsonl" in nm:
            return "events"
        if "_orders.jsonl" in nm:
            return "orders"
        if "funding_rates" in nm:
            return "funding"
        return None

    items: List[Dict[str, Any]] = []
    for p in ds.glob("*.jsonl.gz"):
        try:
            if not p.is_file():
                continue
            kind = _kind_for_name(p.name)
            if kind is None:
                continue
            st = p.stat()
            mtime_ms = int(float(st.st_mtime) * 1000.0)
            age = _age_days_from_day_prefix(str(p.name), now_ms=int(now_ms), mtime_ms=int(mtime_ms))
            if int(age) < 2 and _recent_hot(mtime_ms):
                continue
            keep = int(keep_by_kind.get(kind, 0))
            if keep <= 0:
                continue
            if int(age) <= int(keep):
                continue
            items.append({
                "path": p,
                "name": p.name,
                "kind": kind,
                "size": int(st.st_size),
                "mtime_ms": int(mtime_ms),
                "age_days": int(age),
                "keep_days": int(keep),
            })
        except Exception:
            continue

    out["scanned"] = int(len(list(ds.glob("*.jsonl.gz"))))
    items.sort(key=lambda x: (int(x.get("mtime_ms") or 0), -int(x.get("size") or 0)))
    out["candidates"] = int(len(items))

    planned: List[Dict[str, Any]] = []
    deleted = 0
    processed = 0
    bytes_processed = 0
    bytes_freed = 0

    def _can_process(size_hint: int) -> bool:
        if max_files > 0 and processed >= max_files:
            return False
        if max_bytes > 0 and bytes_processed >= max_bytes:
            return False
        if max_bytes > 0 and (bytes_processed + int(size_hint)) > max_bytes:
            return False
        return True

    for it in items:
        p = it.get("path")
        if not isinstance(p, Path):
            continue
        size0 = int(it.get("size") or 0)
        if not _can_process(size0):
            break
        rec = {
            "action": "delete",
            "path": str(p),
            "kind": str(it.get("kind") or ""),
            "size": int(size0),
            "age_days": int(it.get("age_days") or 0),
            "keep_days": int(it.get("keep_days") or 0),
        }
        if do_dry:
            planned.append(rec)
        else:
            try:
                p.unlink()
                deleted += 1
                bytes_freed += int(size0)
                kind = str(it.get("kind") or "")
                if kind in out.get("by_type"):
                    out["by_type"][kind]["deleted"] = int(out["by_type"][kind].get("deleted") or 0) + 1
                    out["by_type"][kind]["bytes_freed"] = int(out["by_type"][kind].get("bytes_freed") or 0) + int(size0)
            except Exception:
                pass
        processed += 1
        bytes_processed += int(size0)

    out["planned"] = planned[:50]
    out["deleted"] = int(deleted)
    out["processed"] = int(processed)
    out["bytes_freed"] = int(bytes_freed)

    try:
        if not do_dry and processed > 0:
            LOG.info("datasets_cleanup %s", json.dumps({
                "deleted": int(deleted),
                "processed": int(processed),
                "bytes_freed": int(bytes_freed),
                "keep_days": keep_by_kind,
            }, ensure_ascii=False, separators=(",", ":"))[:2000])
    except Exception:
        pass
    return out


def _parse_outbox_stem_and_day(name: str) -> Tuple[str, Optional[str]]:
    nm = str(name or "")
    m = re.match(r"^(?P<stem>.+?)_(?P<day>\d{8})(?:_\d+)?\.jsonl(?:\.gz)?$", nm)
    if m:
        return str(m.group("stem") or ""), str(m.group("day") or "")
    if nm.lower().endswith(".jsonl.gz"):
        return nm[:-9], None
    if nm.lower().endswith(".jsonl"):
        return nm[:-5], None
    return nm, None


def _retention_agent_outbox(now_ms: int, *, dry_run: bool, protected: List[Path]) -> Dict[str, Any]:
    outbox = _agent_outbox_dir()
    try:
        gzip_after_days = int(CONFIG.get("agent_outbox_gzip_after_days", 7) or 7)
    except Exception:
        gzip_after_days = 7
    gzip_after_days = max(0, min(3650, int(gzip_after_days)))
    try:
        default_keep = int(CONFIG.get("agent_outbox_retention_days_default", 180) or 180)
    except Exception:
        default_keep = 180
    default_keep = max(1, min(36500, int(default_keep)))
    m0 = CONFIG.get("agent_outbox_retention_days_by_stem")
    keep_by_stem = m0 if isinstance(m0, dict) else {}
    try:
        budget = int(CONFIG.get("agent_outbox_budget_bytes", 0) or 0)
    except Exception:
        budget = 0

    try:
        max_files = int(CONFIG.get("disk_retention_max_files_per_run", 200) or 200)
    except Exception:
        max_files = 200
    try:
        max_bytes = int(CONFIG.get("disk_retention_max_bytes_per_run", 536870912) or 536870912)
    except Exception:
        max_bytes = 536870912
    max_files = max(0, int(max_files))
    max_bytes = max(0, int(max_bytes))

    items: List[Dict[str, Any]] = []
    for pat in ("*.jsonl", "*.jsonl.gz"):
        try:
            for p in outbox.glob(pat):
                if not p.is_file():
                    continue
                try:
                    st = p.stat()
                except Exception:
                    continue
                items.append({
                    "path": p,
                    "name": p.name,
                    "size": int(st.st_size),
                    "mtime_ms": int(float(st.st_mtime) * 1000.0),
                })
        except Exception:
            pass

    items.sort(key=lambda x: int(x.get("mtime_ms") or 0))
    bytes_before = int(sum(int(it.get("size") or 0) for it in items))
    protected_skipped = 0
    planned: List[Dict[str, Any]] = []
    compressed = 0
    deleted = 0
    bytes_freed = 0
    processed = 0
    bytes_processed = 0

    def _can_process(size_hint: int) -> bool:
        if max_files > 0 and processed >= max_files:
            return False
        if max_bytes > 0 and bytes_processed >= max_bytes:
            return False
        if max_bytes > 0 and (bytes_processed + int(size_hint)) > max_bytes:
            return False
        return True

    def _age_days(mtime_ms: int) -> int:
        try:
            return int(max(0, (int(now_ms) - int(mtime_ms)) // (24 * 3600 * 1000)))
        except Exception:
            return 0

    def _keep_days_for(stem: str) -> int:
        try:
            v = keep_by_stem.get(str(stem))
            if v is None:
                return int(default_keep)
            return max(1, int(v))
        except Exception:
            return int(default_keep)

    def _recent_hot(mtime_ms: int) -> bool:
        try:
            return (int(now_ms) - int(mtime_ms)) < int(10 * 60 * 1000)
        except Exception:
            return False

    candidates_compress: List[Dict[str, Any]] = []
    candidates_delete: List[Dict[str, Any]] = []
    for it in items:
        p = it.get("path")
        if not isinstance(p, Path):
            continue
        if _disk_retention_is_protected(p, protected):
            protected_skipped += 1
            continue
        if _recent_hot(int(it.get("mtime_ms") or 0)):
            continue
        stem, _day = _parse_outbox_stem_and_day(str(it.get("name") or ""))
        age = _age_days(int(it.get("mtime_ms") or 0))
        keep_days = _keep_days_for(stem)
        name_low = str(it.get("name") or "").lower()
        if name_low.endswith(".jsonl"):
            if age >= int(gzip_after_days) and re.search(r"_\d{8}\.jsonl$", str(it.get("name") or "")):
                candidates_compress.append({**it, "stem": stem, "age_days": age, "keep_days": keep_days})
        if age > int(keep_days) and (name_low.endswith(".jsonl") or name_low.endswith(".jsonl.gz")):
            if re.search(r"_\d{8}\.jsonl(\.gz)?$", str(it.get("name") or "")):
                candidates_delete.append({**it, "stem": stem, "age_days": age, "keep_days": keep_days})

    candidates_compress.sort(key=lambda x: int(x.get("mtime_ms") or 0))
    candidates_delete.sort(key=lambda x: int(x.get("mtime_ms") or 0))

    def _do_compress(rec: Dict[str, Any], reason: str) -> bool:
        nonlocal processed, bytes_processed, bytes_freed, compressed
        p = rec.get("path")
        if not isinstance(p, Path):
            return False
        if not _can_process(int(rec.get("size") or 0)):
            return False
        dst = p.with_suffix(p.suffix + ".gz")
        planned.append({"action": "compress", "path": str(p), "dst": str(dst), "size": int(rec.get("size") or 0), "reason": str(reason)})
        processed += 1
        bytes_processed += int(rec.get("size") or 0)
        if dry_run:
            return True
        ok, b0, b1 = _gzip_compress_file(p, dst, keep_src=False)
        if ok:
            compressed += 1
            bytes_freed += int(max(0, int(b0) - int(b1)))
            return True
        return False

    def _do_delete(rec: Dict[str, Any], reason: str) -> bool:
        nonlocal processed, bytes_processed, bytes_freed, deleted
        p = rec.get("path")
        if not isinstance(p, Path):
            return False
        if not _can_process(int(rec.get("size") or 0)):
            return False
        planned.append({"action": "delete", "path": str(p), "size": int(rec.get("size") or 0), "reason": str(reason)})
        processed += 1
        bytes_processed += int(rec.get("size") or 0)
        if dry_run:
            bytes_freed += int(rec.get("size") or 0)
            return True
        try:
            os.unlink(str(p))
            deleted += 1
            bytes_freed += int(rec.get("size") or 0)
            return True
        except Exception:
            return False

    for rec in candidates_compress:
        if not _do_compress(rec, reason="age_gte_gzip_after_days"):
            break

    bytes_after_est = int(max(0, bytes_before - bytes_freed))
    if budget > 0 and bytes_after_est > budget:
        if candidates_compress:
            pass
        more_compress: List[Dict[str, Any]] = []
        for it in items:
            p = it.get("path")
            if not isinstance(p, Path):
                continue
            if _disk_retention_is_protected(p, protected):
                continue
            if _recent_hot(int(it.get("mtime_ms") or 0)):
                continue
            name_low = str(it.get("name") or "").lower()
            if name_low.endswith(".jsonl") and re.search(r"_\d{8}\.jsonl$", str(it.get("name") or "")):
                age = _age_days(int(it.get("mtime_ms") or 0))
                if age >= 1 and age < int(gzip_after_days):
                    stem, _day = _parse_outbox_stem_and_day(str(it.get("name") or ""))
                    more_compress.append({**it, "stem": stem, "age_days": age})
        more_compress.sort(key=lambda x: int(x.get("mtime_ms") or 0))
        for rec in more_compress:
            if bytes_after_est <= budget:
                break
            if not _do_compress(rec, reason="budget_exceeded"):
                break
            bytes_after_est = int(max(0, bytes_before - bytes_freed))

        for rec in candidates_delete:
            if bytes_after_est <= budget:
                break
            if not _do_delete(rec, reason="budget_exceeded_or_keep_days"):
                break
            bytes_after_est = int(max(0, bytes_before - bytes_freed))
    else:
        for rec in candidates_delete:
            if not _do_delete(rec, reason="age_gt_keep_days"):
                break
            bytes_after_est = int(max(0, bytes_before - bytes_freed))

    if not dry_run:
        bytes_after_est = _dir_size_bytes(outbox, glob_pat="*")

    return {
        "dir": str(outbox),
        "dry_run": bool(dry_run),
        "bytes_before": int(bytes_before),
        "bytes_after": int(bytes_after_est),
        "bytes_freed": int(bytes_freed),
        "compressed": int(compressed),
        "deleted": int(deleted),
        "processed": int(processed),
        "protected_skipped": int(protected_skipped),
        "planned": planned[:200],
        "planned_truncated": bool(len(planned) > 200),
    }


def _retention_backtest_results(now_ms: int, *, dry_run: bool, protected: List[Path]) -> Dict[str, Any]:
    base = _user_data_dir() / "backtest_results"
    try:
        base.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    try:
        keep_days = int(CONFIG.get("backtest_results_keep_days", 30) or 30)
    except Exception:
        keep_days = 30
    keep_days = max(1, min(36500, int(keep_days)))
    try:
        keep_max = int(CONFIG.get("backtest_results_keep_max", 200) or 200)
    except Exception:
        keep_max = 200
    keep_max = max(0, int(keep_max))
    try:
        min_keep = int(CONFIG.get("backtest_results_min_keep", 50) or 50)
    except Exception:
        min_keep = 50
    min_keep = max(0, int(min_keep))
    try:
        budget = int(CONFIG.get("backtest_results_budget_bytes", 0) or 0)
    except Exception:
        budget = 0

    try:
        max_files = int(CONFIG.get("disk_retention_max_files_per_run", 200) or 200)
    except Exception:
        max_files = 200
    try:
        max_bytes = int(CONFIG.get("disk_retention_max_bytes_per_run", 536870912) or 536870912)
    except Exception:
        max_bytes = 536870912
    max_files = max(0, int(max_files))
    max_bytes = max(0, int(max_bytes))

    items: List[Dict[str, Any]] = []
    try:
        for p in base.glob("*.zip"):
            if not p.is_file():
                continue
            if _disk_retention_is_protected(p, protected):
                continue
            try:
                st = p.stat()
            except Exception:
                continue
            items.append({"path": p, "name": p.name, "size": int(st.st_size), "mtime_ms": int(float(st.st_mtime) * 1000.0)})
    except Exception:
        pass
    items.sort(key=lambda x: int(x.get("mtime_ms") or 0))
    bytes_before = int(sum(int(it.get("size") or 0) for it in items))

    processed = 0
    bytes_processed = 0
    deleted = 0
    bytes_freed = 0
    planned: List[Dict[str, Any]] = []

    def _can_process(size_hint: int) -> bool:
        if max_files > 0 and processed >= max_files:
            return False
        if max_bytes > 0 and bytes_processed >= max_bytes:
            return False
        if max_bytes > 0 and (bytes_processed + int(size_hint)) > max_bytes:
            return False
        return True

    def _age_days(mtime_ms: int) -> int:
        try:
            return int(max(0, (int(now_ms) - int(mtime_ms)) // (24 * 3600 * 1000)))
        except Exception:
            return 0

    def _recent_hot(mtime_ms: int) -> bool:
        try:
            return (int(now_ms) - int(mtime_ms)) < int(10 * 60 * 1000)
        except Exception:
            return False

    candidates = [it for it in items if not _recent_hot(int(it.get("mtime_ms") or 0))]
    cutoff_days = [it for it in candidates if _age_days(int(it.get("mtime_ms") or 0)) > int(keep_days)]
    excess_n = []
    if keep_max > 0 and len(candidates) > keep_max:
        excess_n = candidates[: max(0, len(candidates) - int(keep_max))]
    to_drop_map = {str(it.get("path")): it for it in (cutoff_days + excess_n)}
    to_drop = list(to_drop_map.values())
    to_drop.sort(key=lambda x: int(x.get("mtime_ms") or 0))

    if min_keep > 0 and len(items) - len(to_drop) < min_keep:
        allow = max(0, len(items) - int(min_keep))
        to_drop = to_drop[:allow]

    bytes_after_est = int(bytes_before)
    for it in to_drop:
        if not _can_process(int(it.get("size") or 0)):
            break
        p = it.get("path")
        if not isinstance(p, Path):
            continue
        planned.append({"action": "delete", "path": str(p), "size": int(it.get("size") or 0), "reason": "keep_days_or_keep_max"})
        processed += 1
        bytes_processed += int(it.get("size") or 0)
        if dry_run:
            deleted += 1
            bytes_freed += int(it.get("size") or 0)
            bytes_after_est = int(max(0, bytes_after_est - int(it.get("size") or 0)))
            continue
        try:
            os.unlink(str(p))
            deleted += 1
            bytes_freed += int(it.get("size") or 0)
            bytes_after_est = int(max(0, bytes_after_est - int(it.get("size") or 0)))
        except Exception:
            pass

    if budget > 0 and bytes_after_est > budget:
        remaining = [it for it in items if str(it.get("path")) not in {str(x.get("path")) for x in to_drop}]
        remaining.sort(key=lambda x: int(x.get("mtime_ms") or 0))
        for it in remaining:
            if bytes_after_est <= budget:
                break
            if min_keep > 0 and (len(items) - deleted) <= min_keep:
                break
            if not _can_process(int(it.get("size") or 0)):
                break
            p = it.get("path")
            if not isinstance(p, Path):
                continue
            planned.append({"action": "delete", "path": str(p), "size": int(it.get("size") or 0), "reason": "budget_exceeded"})
            processed += 1
            bytes_processed += int(it.get("size") or 0)
            if dry_run:
                deleted += 1
                bytes_freed += int(it.get("size") or 0)
                bytes_after_est = int(max(0, bytes_after_est - int(it.get("size") or 0)))
                continue
            try:
                os.unlink(str(p))
                deleted += 1
                bytes_freed += int(it.get("size") or 0)
                bytes_after_est = int(max(0, bytes_after_est - int(it.get("size") or 0)))
            except Exception:
                pass

    if not dry_run:
        bytes_after_est = _dir_size_bytes(base, glob_pat="*.zip")

    return {
        "dir": str(base),
        "dry_run": bool(dry_run),
        "bytes_before": int(bytes_before),
        "bytes_after": int(bytes_after_est),
        "bytes_freed": int(bytes_freed),
        "deleted": int(deleted),
        "processed": int(processed),
        "planned": planned[:200],
        "planned_truncated": bool(len(planned) > 200),
    }


def _retention_aggregated_voting_logs(now_ms: int, *, dry_run: bool, protected: List[Path]) -> Dict[str, Any]:
    p = _user_data_dir() / "aggregated_voting_logs.jsonl"
    if _disk_retention_is_protected(p, protected):
        return {"path": str(p), "dry_run": bool(dry_run), "processed": 0, "skipped": "protected"}

    try:
        keep_days = int(CONFIG.get("aggregated_voting_logs_keep_days", CONFIG.get("agent_outbox_retention_days_default", 180)) or 180)
    except Exception:
        keep_days = 180
    keep_days = max(1, min(36500, int(keep_days)))
    cutoff_ms = int(now_ms) - int(keep_days) * 86400000

    try:
        max_files = int(CONFIG.get("disk_retention_max_files_per_run", 200) or 200)
    except Exception:
        max_files = 200
    try:
        max_bytes = int(CONFIG.get("disk_retention_max_bytes_per_run", 536870912) or 536870912)
    except Exception:
        max_bytes = 536870912
    max_files = max(0, int(max_files))
    max_bytes = max(0, int(max_bytes))

    try:
        if not p.exists() or (not p.is_file()):
            return {"path": str(p), "dry_run": bool(dry_run), "processed": 0, "skipped": "not_found"}
    except Exception:
        return {"path": str(p), "dry_run": bool(dry_run), "processed": 0, "skipped": "stat_error"}

    try:
        bytes_before = int(p.stat().st_size)
    except Exception:
        bytes_before = 0

    if max_files <= 0:
        return {"path": str(p), "dry_run": bool(dry_run), "processed": 0, "skipped": "budget_max_files"}
    if max_bytes > 0 and bytes_before > max_bytes:
        return {"path": str(p), "dry_run": bool(dry_run), "processed": 0, "skipped": "budget_max_bytes"}

    scanned = 0
    kept = 0
    dropped = 0
    tmp = str(p) + ".tmp"
    try:
        fout = None
        if not dry_run:
            fout = open(tmp, "w", encoding="utf-8")
        with open(p, "r", encoding="utf-8") as f:
            for raw in f:
                scanned += 1
                line = raw.rstrip("\n")
                if not line.strip():
                    continue
                obj = None
                try:
                    obj = json.loads(line)
                except Exception:
                    obj = None
                ts = None
                try:
                    if isinstance(obj, dict) and obj.get("ts") is not None:
                        ts = int(obj.get("ts") or 0)
                except Exception:
                    ts = None
                ts_ms = None
                if ts is not None and ts > 0:
                    ts_ms = int(ts) * 1000 if int(ts) < 1000000000000 else int(ts)
                if ts_ms is None or ts_ms >= int(cutoff_ms):
                    kept += 1
                    if fout is not None:
                        fout.write(line + "\n")
                else:
                    dropped += 1
        if fout is not None:
            fout.close()
            fout = None
    except Exception:
        try:
            if fout is not None:
                fout.close()
        except Exception:
            pass
        try:
            if not dry_run:
                os.unlink(tmp)
        except Exception:
            pass
        return {"path": str(p), "dry_run": bool(dry_run), "processed": 0, "skipped": "read_error"}

    if dropped <= 0:
        try:
            if not dry_run:
                os.unlink(tmp)
        except Exception:
            pass
        return {
            "path": str(p),
            "dry_run": bool(dry_run),
            "keep_days": int(keep_days),
            "bytes_before": int(bytes_before),
            "bytes_after": int(bytes_before),
            "bytes_freed": 0,
            "scanned_lines": int(scanned),
            "kept_lines": int(kept),
            "dropped_lines": int(dropped),
            "processed": 0,
        }

    if dry_run:
        try:
            os.unlink(tmp)
        except Exception:
            pass
        return {
            "path": str(p),
            "dry_run": bool(dry_run),
            "keep_days": int(keep_days),
            "bytes_before": int(bytes_before),
            "bytes_after": int(bytes_before),
            "bytes_freed": 0,
            "scanned_lines": int(scanned),
            "kept_lines": int(kept),
            "dropped_lines": int(dropped),
            "processed": 1,
            "planned": [{"action": "rewrite", "path": str(p), "reason": "keep_days"}],
        }

    try:
        os.replace(tmp, p)
    except Exception:
        try:
            os.unlink(tmp)
        except Exception:
            pass
        return {"path": str(p), "dry_run": bool(dry_run), "processed": 0, "skipped": "write_error"}

    try:
        bytes_after = int(p.stat().st_size)
    except Exception:
        bytes_after = int(bytes_before)
    return {
        "path": str(p),
        "dry_run": bool(dry_run),
        "keep_days": int(keep_days),
        "bytes_before": int(bytes_before),
        "bytes_after": int(bytes_after),
        "bytes_freed": int(max(0, int(bytes_before) - int(bytes_after))),
        "scanned_lines": int(scanned),
        "kept_lines": int(kept),
        "dropped_lines": int(dropped),
        "processed": 1,
        "planned": [{"action": "rewrite", "path": str(p), "reason": "keep_days"}],
    }


def _run_disk_retention(now_ms: int, *, dry_run: Optional[bool] = None) -> Dict[str, Any]:
    t0 = time.time()
    try:
        cfg_dry = bool(CONFIG.get("disk_retention_dry_run", True))
    except Exception:
        cfg_dry = True
    do_dry = cfg_dry if dry_run is None else bool(dry_run)
    protected = _disk_retention_protected_paths()

    try:
        _agent_outbox_rollover_all(now_ms=int(now_ms))
    except Exception:
        pass

    rep_outbox = _retention_agent_outbox(int(now_ms), dry_run=bool(do_dry), protected=protected)
    rep_bt = _retention_backtest_results(int(now_ms), dry_run=bool(do_dry), protected=protected)
    rep_voting = _retention_aggregated_voting_logs(int(now_ms), dry_run=bool(do_dry), protected=protected)

    dur_ms = int(max(0.0, (time.time() - t0) * 1000.0))
    policies_hit: List[str] = []
    try:
        if int(rep_outbox.get("processed") or 0) > 0:
            policies_hit.append("agent_outbox")
    except Exception:
        pass
    try:
        if int(rep_bt.get("processed") or 0) > 0:
            policies_hit.append("backtest_results")
    except Exception:
        pass
    try:
        if int(rep_voting.get("processed") or 0) > 0:
            policies_hit.append("aggregated_voting_logs")
    except Exception:
        pass

    out = {
        "ok": True,
        "ts": int(now_ms),
        "duration_ms": int(dur_ms),
        "dry_run": bool(do_dry),
        "policies_hit": policies_hit,
        "protected_paths": [str(p) for p in protected],
        "protected_touched": [],
        "agent_outbox": rep_outbox,
        "backtest_results": rep_bt,
        "aggregated_voting_logs": rep_voting,
    }
    try:
        LOG.info("disk_retention %s", json.dumps({
            "ts": int(now_ms),
            "duration_ms": int(dur_ms),
            "dry_run": bool(do_dry),
            "policies_hit": policies_hit,
            "agent_outbox": {
                "processed": int(rep_outbox.get("processed") or 0),
                "compressed": int(rep_outbox.get("compressed") or 0),
                "deleted": int(rep_outbox.get("deleted") or 0),
                "bytes_freed": int(rep_outbox.get("bytes_freed") or 0),
            },
            "backtest_results": {
                "processed": int(rep_bt.get("processed") or 0),
                "deleted": int(rep_bt.get("deleted") or 0),
                "bytes_freed": int(rep_bt.get("bytes_freed") or 0),
            },
            "aggregated_voting_logs": {
                "processed": int(rep_voting.get("processed") or 0),
                "bytes_freed": int(rep_voting.get("bytes_freed") or 0),
                "dropped_lines": int(rep_voting.get("dropped_lines") or 0),
            },
            "protected_paths": [str(p) for p in protected],
            "protected_touched": [],
        }, ensure_ascii=False, separators=(",", ":"))[:2000])
    except Exception:
        pass
    return out


@app.route("/maintenance/retention/run", methods=["POST"])
def maintenance_retention_run():
    if not _maintenance_auth_ok():
        return jsonify({"ok": False, "error": "maintenance_forbidden"}), 403
    try:
        dr = request.args.get("dry_run")
    except Exception:
        dr = None
    dry_opt: Optional[bool] = None
    if dr is not None and str(dr).strip():
        v = str(dr).strip().lower()
        dry_opt = v in ("1", "true", "yes", "y", "on")
        if v in ("0", "false", "no", "n", "off"):
            dry_opt = False
    try:
        out = _run_disk_retention(_now_ms(), dry_run=dry_opt)
        return jsonify(_json_sanitize(out))
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


