    dir1h_stability_bars = int(max(2, min(12, int(dir1h_stability_bars))))
    if (not math.isfinite(float(dir1h_w_btc))) or (not math.isfinite(float(dir1h_w_eth))):
        dir1h_w_btc, dir1h_w_eth = 0.70, 0.30
    w_sum1h = float(dir1h_w_btc) + float(dir1h_w_eth)
    if (not math.isfinite(float(w_sum1h))) or float(w_sum1h) <= 0.0:
        dir1h_w_btc, dir1h_w_eth = 0.70, 0.30
        w_sum1h = 1.0
    dir1h_w_btc = float(dir1h_w_btc) / float(w_sum1h)
    dir1h_w_eth = float(dir1h_w_eth) / float(w_sum1h)
    macro_ts = int(now_ms)
