@app.route("/health", methods=["GET"])
def health():
    try:
        _ensure_scheduler_started()
    except Exception:
        pass
    try:
        _ensure_carry_worker_started()
    except Exception:
        pass
    try:
        _ensure_twitter_outbox_worker_started()
    except Exception:
        pass
    try:
        sch = TRACKER_STATE.get("scheduler")
    except Exception:
        sch = None
    try:
        started = bool(globals().get("_SCHEDULER_STARTED", False))
    except Exception:
        started = False
    th = globals().get("_SCHEDULER_THREAD")
    try:
        alive = bool(th is not None and hasattr(th, "is_alive") and th.is_alive())
    except Exception:
        alive = False
    try:
        c_started = bool(globals().get("_CARRY_WORKER_STARTED", False))
    except Exception:
        c_started = False
    c_th = globals().get("_CARRY_WORKER_THREAD")
    try:
        c_alive = bool(c_th is not None and hasattr(c_th, "is_alive") and c_th.is_alive())
    except Exception:
        c_alive = False
    tw_th = globals().get("_TWITTER_OUTBOX_THREAD")
    try:
        tw_started = bool(globals().get("_TWITTER_OUTBOX_STARTED", False))
    except Exception:
        tw_started = False
    try:
        tw_alive = bool(tw_th is not None and hasattr(tw_th, "is_alive") and tw_th.is_alive())
    except Exception:
        tw_alive = False
    tw_hb = None
    try:
        tw_hb = int(globals().get("_TWITTER_OUTBOX_HEARTBEAT_MS") or 0) or None
    except Exception:
        tw_hb = None
    tw_hb_age_sec = None
    try:
        if tw_hb is not None:
            tw_hb_age_sec = max(0.0, (float(_now_ms()) - float(tw_hb)) / 1000.0)
    except Exception:
        tw_hb_age_sec = None
    tw_outbox_path = None
    tw_last_offset = None
    tw_lines_n = None
    tw_last_error = None
    tw_last_error_ms = None
    tw_stage = None
    try:
        tw_outbox_path = globals().get("_TWITTER_OUTBOX_PATH")
        tw_last_offset = globals().get("_TWITTER_OUTBOX_LAST_OFFSET")
        tw_lines_n = globals().get("_TWITTER_OUTBOX_LINES_N")
        tw_last_error = globals().get("_TWITTER_OUTBOX_LAST_ERROR")
        tw_last_error_ms = globals().get("_TWITTER_OUTBOX_LAST_ERROR_MS")
        tw_stage = globals().get("_TWITTER_OUTBOX_STAGE")
    except Exception:
        tw_outbox_path = None
        tw_last_offset = None
        tw_lines_n = None
        tw_last_error = None
        tw_last_error_ms = None
        tw_stage = None
    return jsonify({
        "ok": True,
        "ts": _now_ms(),
        "scheduler": (sch if isinstance(sch, dict) else {}),
        "scheduler_thread": {"started": bool(started), "alive": bool(alive)},
        "carry_worker_thread": {"started": bool(c_started), "alive": bool(c_alive)},
        "twitter_outbox_worker_thread": {"started": bool(tw_started), "alive": bool(tw_alive), "heartbeat_ms": tw_hb, "heartbeat_age_sec": tw_hb_age_sec, "outbox_path": tw_outbox_path, "lines_n": tw_lines_n, "last_offset": tw_last_offset, "last_error": tw_last_error, "last_error_ms": tw_last_error_ms, "stage": tw_stage},
    })


@app.route("/selfcheck", methods=["GET", "POST"])
def selfcheck():
    data = request.get_json(force=True) if request.method == "POST" else {}
    now_ms = _now_ms()

    cfg_path = _runtime_config_path()
    models_dir = _models_dir()
    scaler_path = _scaler_path()
    try:
        models_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    artifacts = 0
    try:
        artifacts = len(list(models_dir.glob("*.pkl"))) + len(list(models_dir.glob("*.pth")))
    except Exception:
        artifacts = 0

    ft_cli = bool(shutil.which("freqtrade"))
    ft_py = bool(_freqtrade_py_available())

    checks: Dict[str, Any] = {
        "config_file": {"exists": bool(cfg_path.exists()), "path": str(cfg_path)},
        "models_dir": {"exists": bool(models_dir.exists()), "path": str(models_dir), "artifacts": int(artifacts)},
        "scaler_file": {"exists": bool(scaler_path.exists()), "path": str(scaler_path)},
        "freqtrade": {"available": bool(_freqtrade_available()), "cli_available": bool(ft_cli), "py_available": bool(ft_py)},
        "hyperliquid_sdk": {"available": bool(Info is not None and Exchange is not None)},
        "active_model": {"name": ACTIVE_MODEL.get("name"), "loaded": bool(ACTIVE_MODEL.get("obj") is not None or ACTIVE_MODEL.get("name") == "__committee__")},
        "online_state": {
            "version": int(ONLINE_STATE.get("version") or 0),
            "train_sample_count": int(ONLINE_STATE.get("train_sample_count") or 0),
            "last_label_ms": int(ONLINE_STATE.get("last_label_ms") or 0),
            "last_train_ms": int(ONLINE_STATE.get("last_train_ms") or 0),
            "last_promote_ms": int(ONLINE_STATE.get("last_promote_ms") or 0),
        },
        "strategy_imports": (
            [
                _selfcheck_import("user_data.strategies.breakoutStrategy"),
                _selfcheck_import("user_data.strategies.AdaptiveVolatilityStrategy_forced"),
            ]
            if ft_py
            else [
                {"ok": True, "module": "user_data.strategies.breakoutStrategy", "skipped": True, "reason": "freqtrade_python_unavailable"},
                {"ok": True, "module": "user_data.strategies.AdaptiveVolatilityStrategy_forced", "skipped": True, "reason": "freqtrade_python_unavailable"},
            ]
        ),
    }

    try:
        checks["sli_online"] = _sli_online_snapshot(int(now_ms))
    except Exception:
        pass

    try:
        now0 = int(now_ms)
        st0 = TRACKER_STATE.get("btc_tv_signal")
        if not isinstance(st0, dict):
            st0 = {}
        try:
            ts0 = int(st0.get("ts") or st0.get("recv_ms") or 0)
        except Exception:
            ts0 = 0
        checks["btc_tv"] = {
            "present": bool(st0),
            "dir": (st0.get("dir") if isinstance(st0.get("dir"), str) else None),
            "ts": (int(ts0) if int(ts0) > 0 else None),
            "age_ms": (int(now0 - int(ts0)) if int(ts0) > 0 else None),
        }
    except Exception:
        pass

    do_hl_ping = bool((data or {}).get("hl_ping", False))
    if do_hl_ping:
        try:
            base_url = _hl_base_url()
            info = _hl_info()
            mids = info.all_mids() or {}
            checks["hyperliquid_ping"] = {
                "ok": True,
                "base_url": str(base_url),
                "btc_mid": (float(mids.get("BTC")) if mids.get("BTC") is not None else None),
                "trading_enabled": bool(_hl_enabled_for_trading_for_owner("strategy") or _hl_enabled_for_trading_for_owner("quant") or _hl_enabled_for_trading_for_owner("carry")),
                "has_account": bool(_hl_account_address()),
            }
        except Exception as e:
            checks["hyperliquid_ping"] = {"ok": False, "error": str(e)}

    smoke_res = None
    if bool((data or {}).get("smoke", False)):
        smoke_res = _selfcheck_smoke(now_ms=now_ms, cleanup=bool((data or {}).get("cleanup", True)))

    btc_tv_smoke = None
    if bool((data or {}).get("btc_tv_smoke", False)):
        old = TRACKER_STATE.get("btc_tv_signal")
        old_cfg = {
            "entry_btc_tv_hard_gate_enabled": CONFIG.get("entry_btc_tv_hard_gate_enabled"),
            "entry_btc_tv_hard_gate_fail_open": CONFIG.get("entry_btc_tv_hard_gate_fail_open"),
            "entry_btc_tv_hard_gate_apply_to_addon": CONFIG.get("entry_btc_tv_hard_gate_apply_to_addon"),
            "entry_btc_tv_hard_gate_apply_to_btc": CONFIG.get("entry_btc_tv_hard_gate_apply_to_btc"),
            "entry_btc_tv_hard_gate_ttl_sec": CONFIG.get("entry_btc_tv_hard_gate_ttl_sec"),
        }
        try:
            CONFIG["entry_btc_tv_hard_gate_enabled"] = True
            CONFIG["entry_btc_tv_hard_gate_fail_open"] = False
            CONFIG["entry_btc_tv_hard_gate_apply_to_addon"] = True
            CONFIG["entry_btc_tv_hard_gate_apply_to_btc"] = False
            CONFIG["entry_btc_tv_hard_gate_ttl_sec"] = 7200
            TRACKER_STATE["btc_tv_signal"] = {"sig_id": "selfcheck", "symbol": "BTCUSDT", "dir": "long", "ts": int(now_ms), "recv_ms": int(now_ms)}
            ok_long, _ = _order_gate_open(pair="SOL-PERP", side="long", now_ms=int(now_ms), features={}, meta={"src": "selfcheck"})
            ok_short, _ = _order_gate_open(pair="SOL-PERP", side="short", now_ms=int(now_ms), features={}, meta={"src": "selfcheck"})
            btc_tv_smoke = {
                "state": dict(TRACKER_STATE.get("btc_tv_signal") or {}),
                "sol_long": ok_long,
                "sol_short": ok_short,
            }
        except Exception as e:
            btc_tv_smoke = {"ok": False, "error": str(e)}
        finally:
            TRACKER_STATE["btc_tv_signal"] = old
            for k, v in old_cfg.items():
                if v is None:
                    if k in CONFIG:
                        try:
                            del CONFIG[k]
                        except Exception:
                            pass
                else:
                    CONFIG[k] = v

    ok = True
    if not bool(checks["models_dir"].get("exists")):
        ok = False
    if smoke_res is not None and (not bool(smoke_res.get("ok", False))):
        ok = False

    warnings: List[Dict[str, Any]] = []
    try:
        if (not bool(CONFIG.get("dry_run", True))) and str(CONFIG.get("execution_venue", "stub")).lower() == "hyperliquid":
            if bool(CONFIG.get("live_trading_enabled", False)):
                warnings.append({"code": "dry_run_disabled", "severity": "high"})
            else:
                warnings.append({"code": "dry_run_disabled_but_live_off", "severity": "medium"})
    except Exception:
        pass
    try:
        if ft_cli and (not ft_py):
            warnings.append({"code": "freqtrade_cli_only", "severity": "medium"})
    except Exception:
        pass
    for it in (checks.get("strategy_imports") or []):
        if isinstance(it, dict) and (not bool(it.get("ok", True))):
            warnings.append({"code": "strategy_import_failed", "severity": "low", "module": it.get("module"), "error": it.get("error")})

    notional_diag = None
    try:
        notional_diag = _notional_diagnostics_from_cfg(CONFIG)
        checks["notional_config"] = notional_diag
        if isinstance(notional_diag, dict) and (not bool(notional_diag.get("ok", True))):
            warnings.append({"code": "notional_config_invalid", "severity": "high", "issues": notional_diag.get("issues")})
            ok = False
    except Exception:
        pass

    return jsonify({
        "ok": bool(ok),
        "ts": int(now_ms),
        "config": {
            "dry_run": bool(CONFIG.get("dry_run", True)),
            "execution_venue": str(CONFIG.get("execution_venue", "stub")),
            "live_trading_enabled": bool(CONFIG.get("live_trading_enabled", False)),
            "signals_auto_decision": bool(CONFIG.get("signals_auto_decision", False)),
            "arena_enabled": bool(CONFIG.get("arena_enabled", False)),
        },
        "checks": checks,
        "warnings": warnings,
        "smoke": smoke_res,
        "btc_tv_smoke": btc_tv_smoke,
    })


@app.route("/selfcheck/trace", methods=["GET"])
def selfcheck_trace():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    trace_id = str(request.args.get("trace_id") or "").strip()
    if not trace_id:
        try:
            st = TRACKER_STATE.get("sli_online")
            if isinstance(st, dict) and st.get("last_breach_trace_id") is not None:
                trace_id = str(st.get("last_breach_trace_id") or "").strip()
        except Exception:
            trace_id = ""
    if not trace_id:
        return jsonify({"ok": False, "error": "trace_id_not_found", "ts": int(_now_ms())}), 400
    try:
        max_orders = int(request.args.get("max_orders") or 80)
    except Exception:
        max_orders = 80
    max_orders = max(1, min(500, int(max_orders)))
    out = _agent_trace_chain(trace_id, max_orders=max_orders)
    code = 200 if bool(out.get("ok")) else 400
    out["ts"] = int(_now_ms())
    return jsonify(out), int(code)

