@app.route("/universe/core", methods=["GET"])
def universe_core():
    _ensure_universe_core_ready(int(_now_ms()))
    # Returns just the list of core pairs for Freqtrade RemotePairList
    state = UNIVERSE_STATE.get("core") or []
    # Freqtrade expects pairs. 
    # If using Gate.io futures, pairs might need suffix if not added by PairList config
    # My generated pairs are "BTC", "ETH" etc.
    # Freqtrade config has "stake_currency": "USDT".
    # RemotePairList adds stake currency? No.
    # I should return full pairs e.g. "BTC/USDT:USDT" or just "BTC/USDT" depending on exchange.
    # Strategy005 uses Gate.io. Pairs usually "BTC/USDT:USDT".
    # Let's return them formatted.
    
    formatted = []
    for c in state:
        s = str(c or "").strip()
        if not s:
            continue
        if ("/" in s) or (":" in s) or ("-" in s):
            formatted.append(s)
        else:
            formatted.append(f"{s}/USDT:USDT")
        
    return jsonify({"pairs": formatted})


def _json_sanitize(x: Any) -> Any:
    seen: set = set()

    def _rec(v: Any, depth: int) -> Any:
        if v is None:
            return None
        if isinstance(v, bool):
            return bool(v)
        if isinstance(v, (int, str)):
            return v
        if isinstance(v, float):
            return float(v) if math.isfinite(float(v)) else None
        if isinstance(v, Decimal):
            try:
                vf = float(v)
                return float(vf) if math.isfinite(float(vf)) else None
            except Exception:
                return str(v)
        if depth >= 60:
            try:
                return str(v)
            except Exception:
                return None

        try:
            vid = id(v)
            if vid in seen:
                return "<cycle>"
        except Exception:
            vid = None
        if vid is not None:
            try:
                seen.add(vid)
            except Exception:
                pass

        if isinstance(v, dict):
            out: Dict[str, Any] = {}
            for k, vv in v.items():
                try:
                    ks = str(k)
                except Exception:
                    ks = repr(k)
                out[ks] = _rec(vv, depth + 1)
            return out
        if isinstance(v, (list, tuple, set)):
            return [_rec(vv, depth + 1) for vv in list(v)]
        try:
            if hasattr(v, "item"):
                return _rec(v.item(), depth + 1)
        except Exception:
            pass
        try:
            return str(v)
        except Exception:
            return None

    try:
        return _rec(x, 0)
    except Exception:
        try:
            return str(x)
        except Exception:
            return None


def _config_public_view(cfg: Any) -> Dict[str, Any]:
    src = cfg if isinstance(cfg, dict) else {}
    out: Dict[str, Any] = {}
    for k, v in (src or {}).items():
        try:
            ks = str(k)
        except Exception:
            ks = repr(k)
        k_low = str(ks).lower()
        if any(x in k_low for x in ("secret", "token", "apikey", "api_key", "private", "passwd", "password", "hmac")) or k_low.endswith("_key"):
            out[ks] = "<redacted>"
        else:
            out[ks] = v
    return out

