    if zip_path is None or (not Path(zip_path).exists()) or (not Path(zip_path).is_file()):
        return jsonify({"ok": False, "error": "backtest_zip_not_found", "zip": s}), 404

    strategy = request.args.get("strategy")
    st = None if strategy is None else str(strategy)
    trades = _backtest_zip_strategy_trades(Path(zip_path), strategy=st)
    if not isinstance(trades, list):
        return jsonify({"ok": False, "error": "no_trades", "zip": str(Path(zip_path).name)}), 404

    start_ts = _bt_parse_ts(request.args.get("start_ts"))
    end_ts = _bt_parse_ts(request.args.get("end_ts"))
    if end_ts is None:
        end_ts = int(now_ms)

    timeframe = str(request.args.get("timeframe") or "1h").strip().lower()
    if timeframe not in ("1h", "30m"):
        timeframe = "1h"
    method = str(request.args.get("method") or "pearson").strip().lower()
    if method not in ("pearson", "spearman"):
        method = "pearson"
    try:
        window_bars = int(float(request.args.get("window_bars") or 72))
    except Exception:
        window_bars = 72
    window_bars = int(max(10, min(2000, int(window_bars))))

    thresholds = _bt_parse_thresholds(request.args.get("thresholds"))
    if not thresholds:
        try:
            thr_lo = float(request.args.get("thr_lo") or 0.50)
        except Exception:
            thr_lo = 0.50
        try:
            thr_hi = float(request.args.get("thr_hi") or 0.90)
        except Exception:
            thr_hi = 0.90
        try:
            thr_step = float(request.args.get("thr_step") or 0.05)
        except Exception:
            thr_step = 0.05
        thresholds = _bt_threshold_grid(float(thr_lo), float(thr_hi), float(thr_step))
    thresholds = sorted(set(float(_clip(float(x), -1.0, 1.0)) for x in thresholds))[:80]
    if not thresholds:
        thresholds = [0.70]

    try:
        months = int(request.args.get("months") or 12)
    except Exception:
        months = 12
    months = int(max(1, min(36, int(months))))
    try:
        train_months = int(request.args.get("train_months") or 3)
    except Exception:
        train_months = 3
    train_months = int(max(1, min(24, int(train_months))))
    objective = str(request.args.get("objective") or "profit_dd").strip().lower()
    try:
        dd_penalty = float(request.args.get("dd_penalty") or 0.75)
    except Exception:
        dd_penalty = 0.75

    cfg_zip = _backtest_zip_load_config_json(Path(zip_path)) or {}
    try:
        fee_default = float(cfg_zip.get("fee") or 0.0)
        if not math.isfinite(float(fee_default)) or float(fee_default) < 0.0:
            fee_default = 0.0
    except Exception:
        fee_default = 0.0
    try:
        fee = float(request.args.get("fee") or fee_default)
    except Exception:
        fee = fee_default
    try:
        slippage = float(request.args.get("slippage") or 0.0)
    except Exception:
        slippage = 0.0
    fee = float(max(0.0, min(0.02, float(fee))))
    slippage = float(max(0.0, min(0.02, float(slippage))))

    starting_balance = _bt_pick_starting_balance(Path(zip_path), strategy=st)
    corr_cache: Dict[str, Any] = {}

    end_month_start = _bt_month_start_utc(int(end_ts))
    dt_end_month = datetime.fromtimestamp(float(end_month_start) / 1000.0, tz=timezone.utc)
    month_starts: List[int] = []
    for i in range(int(months)):
        dt_m = _bt_add_months(dt_end_month, -int(months - 1 - i))
        month_starts.append(int(dt_m.timestamp() * 1000))
    month_ranges: List[Tuple[int, int]] = []
    for i, ms0 in enumerate(month_starts):
        if i + 1 < len(month_starts):
            ms1 = month_starts[i + 1]
        else:
            ms1 = int(end_ts)
            try:
                ms1 = int(_bt_add_months(datetime.fromtimestamp(float(ms0) / 1000.0, tz=timezone.utc), 1).timestamp() * 1000)
                ms1 = int(min(int(ms1), int(end_ts)))
            except Exception:
                ms1 = int(end_ts)
        month_ranges.append((int(ms0), int(ms1)))

    corr_enriched_all = _bt_enrich_corr(trades, start_ts, end_ts, str(timeframe), int(window_bars), str(method), corr_cache)

    per_month: List[Dict[str, Any]] = []
    for ms0, ms1 in month_ranges:
        corr_enriched_m = [t for t in corr_enriched_all if int(t.get("open_timestamp") or 0) >= int(ms0) and int(t.get("open_timestamp") or 0) < int(ms1)]
        enriched = _bt_apply_costs(corr_enriched_m, float(fee), float(slippage))
        block = _bt_ab_eval_from_trades(enriched, thresholds, starting_balance=float(starting_balance))
        best = None
        best_thr = None
        for row in block.get("ab") or []:
            if not isinstance(row, dict):
                continue
            m0 = row.get("metrics")
            sc = _bt_objective_score(m0 if isinstance(m0, dict) else {}, str(objective), float(dd_penalty))
            if sc is None:
                continue
            if best is None or float(sc) > float(best):
                best = float(sc)
                best_thr = row.get("thr")
        per_month.append(
            {
                "month_start": int(ms0),
                "month_end": int(ms1),
                "n_base": int((block.get("base") or {}).get("n") or 0),
                "n_with_corr": int((block.get("with_corr") or {}).get("n") or 0),
                "best_thr": (None if best_thr is None else float(best_thr)),
                "best_score": (None if best is None else float(best)),
                "ab": block.get("ab"),
            }
        )

    wf_rows: List[Dict[str, Any]] = []
    for i in range(len(month_ranges)):
        if i < int(train_months):
            continue
        train_ranges = month_ranges[i - int(train_months) : i]
        test_range = month_ranges[i]
        train_trades: List[Dict[str, Any]] = []
        test_trades: List[Dict[str, Any]] = []
        for t in corr_enriched_all:
            try:
                ots = int(t.get("open_timestamp") or 0)
            except Exception:
                ots = 0
            if ots <= 0:
                continue
            for a, b in train_ranges:
                if int(a) <= ots < int(b):
                    train_trades.append(t)
                    break
            if int(test_range[0]) <= ots < int(test_range[1]):
                test_trades.append(t)

        train_en = _bt_apply_costs(train_trades, float(fee), float(slippage))
        train_block = _bt_ab_eval_from_trades(train_en, thresholds, starting_balance=float(starting_balance))
        chosen_thr = None
        chosen_score = None
        for row in train_block.get("ab") or []:
            if not isinstance(row, dict):
                continue
            m0 = row.get("metrics")
            sc = _bt_objective_score(m0 if isinstance(m0, dict) else {}, str(objective), float(dd_penalty))
            if sc is None:
                continue
            if chosen_score is None or float(sc) > float(chosen_score):
                chosen_score = float(sc)
                chosen_thr = row.get("thr")
        if chosen_thr is None:
            continue
        test_en = _bt_apply_costs(test_trades, float(fee), float(slippage))
        test_block = _bt_ab_eval_from_trades(test_en, [float(chosen_thr)], starting_balance=float(starting_balance))
        test_row = None
        try:
            ab0 = test_block.get("ab") or []
            if isinstance(ab0, list) and ab0:
                test_row = ab0[0]
        except Exception:
            test_row = None
        wf_rows.append(
            {
                "train_months": int(train_months),
                "train_start": int(train_ranges[0][0]),
                "train_end": int(train_ranges[-1][1]),
                "test_start": int(test_range[0]),
                "test_end": int(test_range[1]),
                "chosen_thr": float(chosen_thr),
                "train_score": (None if chosen_score is None else float(chosen_score)),
                "test": test_row,
            }
        )

    chosen_thrs = [float(r.get("chosen_thr")) for r in wf_rows if r.get("chosen_thr") is not None and math.isfinite(float(r.get("chosen_thr")))]
    chosen_thrs.sort()
    rec = None
    if chosen_thrs:
        def _q(xs: List[float], q: float) -> float:
            qv = float(_clip(float(q), 0.0, 1.0))
            n = len(xs)
            if n == 1:
                return float(xs[0])
            pos = float(qv) * float(n - 1)
            i0 = int(math.floor(pos))
            i1 = int(math.ceil(pos))
            i0 = int(max(0, min(n - 1, i0)))
            i1 = int(max(0, min(n - 1, i1)))
            if i0 == i1:
                return float(xs[i0])
            w = float(pos) - float(i0)
            return float(xs[i0]) * (1.0 - float(w)) + float(xs[i1]) * float(w)
        rec = {"low": float(_q(chosen_thrs, 0.25)), "mid": float(_q(chosen_thrs, 0.50)), "high": float(_q(chosen_thrs, 0.75))}

    return jsonify(
        _json_sanitize(
            {
                "ok": True,
                "ts": int(now_ms),
                "zip": str(Path(zip_path).name),
                "strategy": (None if strategy is None else str(strategy)),
                "timerange": {"start_ts": start_ts, "end_ts": end_ts},
                "corr": {"timeframe": str(timeframe), "window_bars": int(window_bars), "method": str(method)},
                "assumptions": {"fee": float(fee), "slippage": float(slippage)},
                "objective": {"name": str(objective), "dd_penalty": float(dd_penalty)},
                "thresholds": thresholds,
                "starting_balance": float(starting_balance),
                "months": per_month,
                "walkforward": wf_rows,
                "recommended_thr": rec,
            }
        )
    )


