@app.route("/config/get", methods=["GET"])
def config_get():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    out = dict(CONFIG)
    include_rollbacks = False
    try:
        v = request.args.get("include_rollbacks")
        if v is not None:
            include_rollbacks = bool(str(v or "").strip().lower() in ("1", "true", "yes", "y", "on"))
    except Exception:
        include_rollbacks = False
    if not bool(include_rollbacks):
        try:
            out.pop("rollback_points", None)
        except Exception:
            pass

    try:
        for k in list(out.keys()):
            kl = str(k or "").lower()
            if any(x in kl for x in ("secret", "token", "apikey", "api_key", "private", "passwd", "password", "hmac")) or kl.endswith("_key"):
                out[k] = "<redacted>"
    except Exception:
        pass
    try:
        out["automation"] = dict(AUTOMATION or {})
    except Exception:
        out["automation"] = None
    try:
        out["runtime_config_version"] = _runtime_config_version(CONFIG)
    except Exception:
        out["runtime_config_version"] = None
    try:
        lo = float(out.get("threshold_grid_lo", 0.40) or 0.40)
    except Exception:
        lo = 0.40
    try:
        hi = float(out.get("threshold_grid_hi", 0.90) or 0.90)
    except Exception:
        hi = 0.90
    try:
        ok = math.isfinite(float(lo)) and math.isfinite(float(hi)) and (0.0 < float(lo) < 1.0) and (0.0 < float(hi) < 1.0) and (float(hi) > float(lo))
    except Exception:
        ok = False
    if not ok:
        lo, hi = 0.40, 0.90
    out["threshold_grid_lo"] = float(lo)
    out["threshold_grid_hi"] = float(hi)
    hard_min = 0.10
    for k, dflt in (("threshold_trend", 0.65), ("threshold_chop", 0.70)):
        try:
            v = float(out.get(k, dflt))
        except Exception:
            v = float(dflt)
        try:
            if (not math.isfinite(float(v))) or (float(v) <= float(hard_min)):
                v = float(dflt)
        except Exception:
            v = float(dflt)
        out[k] = float(_clip(float(v), float(lo), float(hi)))
    try:
        out["notional_diagnostics"] = _notional_diagnostics_from_cfg(out)
    except Exception:
        out["notional_diagnostics"] = None
    try:
        env = _governance_env_name()
        out["_governance_env"] = env
        out["governance_env"] = env
    except Exception:
        out["_governance_env"] = None
        out["governance_env"] = None
    try:
        out["_user_data_dir"] = str(_user_data_dir().resolve())
    except Exception:
        out["_user_data_dir"] = None
    try:
        out["_code_dir"] = str(Path(__file__).resolve().parent)
    except Exception:
        out["_code_dir"] = None
    return jsonify(_json_sanitize(out))


