def _carry_active_metrics(now_ms: int, venue: str, coin: str) -> Dict[str, Any]:
    now_ms = int(now_ms)
    v = str(venue or "").strip().lower()
    c = str(coin or "").strip().upper()
    out: Dict[str, Any] = {"ok": True, "venue": str(v), "coin": str(c)}
    if not c:
        out["ok"] = False
        out["error"] = "missing_coin"
        return out

    if v not in ("hyperliquid", "hl"):
        v = "hyperliquid"
        out["venue"] = str(v)

    if v in ("hyperliquid", "hl"):
        try:
            ctx = _hl_ctx(str(c))
        except Exception:
            ctx = None
        if isinstance(ctx, dict):
            try:
                out["funding_rate"] = float(_to_float(ctx.get("funding", ctx.get("fundingRate", 0.0)), 0.0))
            except Exception:
                pass
            try:
                prem = float(_to_float(ctx.get("premium", 0.0), 0.0))
                if math.isfinite(float(prem)):
                    out["basis_bps"] = float(prem) * 10_000.0
            except Exception:
                pass
        return out

    out["ok"] = False
    out["error"] = "unsupported_venue"
    return out


def _carry_hl_spread_bps_quick(coin: str, now_ms: int, ttl_ms: int = 2000) -> Optional[float]:
    c = str(_hl_coin_from_pair(coin)).upper().strip()
    if not c:
        return None
    key = f"{c}"
    hit = HL_CARRY_BOOK_CACHE.get(key)
    if isinstance(hit, dict):
        try:
            ts0 = int(hit.get("ts") or 0)
        except Exception:
            ts0 = 0
        if ts0 > 0 and (int(now_ms) - int(ts0)) <= int(ttl_ms):
            v0 = hit.get("spread_bps")
            try:
                v0f = float(v0)
                return v0f if math.isfinite(float(v0f)) and v0f >= 0.0 else None
            except Exception:
                return None

    spread_bps: Optional[float] = None
    try:
        resp = _hl_post_info({"type": "l2Book", "coin": str(c)}, timeout_sec=float(CONFIG.get("hl_l2book_timeout_sec", 2.0) or 2.0))
    except Exception:
        resp = None

    try:
        bids = None
        asks = None
        if isinstance(resp, dict):
            bids = resp.get("levels")[0] if isinstance(resp.get("levels"), list) and len(resp.get("levels")) >= 2 else resp.get("bids")
            asks = resp.get("levels")[1] if isinstance(resp.get("levels"), list) and len(resp.get("levels")) >= 2 else resp.get("asks")
        if isinstance(bids, list) and bids and isinstance(asks, list) and asks:
            b0 = bids[0]
            a0 = asks[0]
            bp = _to_float((b0 or {}).get("px") if isinstance(b0, dict) else (b0[0] if isinstance(b0, (list, tuple)) and b0 else b0), 0.0)
            ap = _to_float((a0 or {}).get("px") if isinstance(a0, dict) else (a0[0] if isinstance(a0, (list, tuple)) and a0 else a0), 0.0)
            if float(bp) > 0.0 and float(ap) > 0.0 and float(ap) >= float(bp):
                spread_bps = (float(ap) / float(bp) - 1.0) * 10_000.0
                if not math.isfinite(float(spread_bps)) or float(spread_bps) < 0.0:
                    spread_bps = None
    except Exception:
        spread_bps = None

    HL_CARRY_BOOK_CACHE[key] = {"ts": int(now_ms), "spread_bps": (None if spread_bps is None else float(spread_bps))}
    return spread_bps


def _carry_hl_depth_quote_usd_quick(coin: str, now_ms: int, window_bps: float = 10.0, ttl_ms: int = 2000) -> Optional[float]:
    c = str(_hl_coin_from_pair(coin)).upper().strip()
    if not c:
        return None
    wb = float(window_bps)
    if (not math.isfinite(wb)) or wb <= 0.0:
        wb = 10.0
    wb = float(_clip(float(wb), 0.5, 500.0))
    key = f"{c}|{float(wb):.4f}"
    hit = HL_CARRY_DEPTH_CACHE.get(key)
    if isinstance(hit, dict):
        try:
            ts0 = int(hit.get("ts") or 0)
        except Exception:
            ts0 = 0
        if ts0 > 0 and (int(now_ms) - int(ts0)) <= int(ttl_ms):
            v0 = hit.get("depth_quote")
            try:
                v0f = float(v0)
                return v0f if math.isfinite(float(v0f)) and v0f >= 0.0 else None
            except Exception:
                return None

    resp = None
    try:
        resp = _hl_post_info({"type": "l2Book", "coin": str(c)}, timeout_sec=float(CONFIG.get("hl_l2book_timeout_sec", 2.0) or 2.0))
    except Exception:
        resp = None

    depth_quote: Optional[float] = None
    try:
        bids = None
        asks = None
        if isinstance(resp, dict):
            bids = resp.get("levels")[0] if isinstance(resp.get("levels"), list) and len(resp.get("levels")) >= 2 else resp.get("bids")
            asks = resp.get("levels")[1] if isinstance(resp.get("levels"), list) and len(resp.get("levels")) >= 2 else resp.get("asks")
        if isinstance(bids, list) and bids and isinstance(asks, list) and asks:
            b0 = bids[0]
            a0 = asks[0]
            bp = _to_float((b0 or {}).get("px") if isinstance(b0, dict) else (b0[0] if isinstance(b0, (list, tuple)) and b0 else b0), 0.0)
            ap = _to_float((a0 or {}).get("px") if isinstance(a0, dict) else (a0[0] if isinstance(a0, (list, tuple)) and a0 else a0), 0.0)
            if float(bp) > 0.0 and float(ap) > 0.0:
                mid = 0.5 * (float(bp) + float(ap))
                lo = float(mid) * (1.0 - float(wb) / 10_000.0)
                hi = float(mid) * (1.0 + float(wb) / 10_000.0)
                bid_q = 0.0
                ask_q = 0.0
                for lv in bids:
                    px = _to_float((lv or {}).get("px") if isinstance(lv, dict) else (lv[0] if isinstance(lv, (list, tuple)) and lv else lv), 0.0)
                    if float(px) < float(lo):
                        break
                    sz = _to_float((lv or {}).get("sz") if isinstance(lv, dict) else (lv[1] if isinstance(lv, (list, tuple)) and len(lv) >= 2 else 0.0), 0.0)
                    if float(px) > 0.0 and float(sz) > 0.0:
                        bid_q += float(px) * float(sz)
                for lv in asks:
                    px = _to_float((lv or {}).get("px") if isinstance(lv, dict) else (lv[0] if isinstance(lv, (list, tuple)) and lv else lv), 0.0)
                    if float(px) > float(hi):
                        break
                    sz = _to_float((lv or {}).get("sz") if isinstance(lv, dict) else (lv[1] if isinstance(lv, (list, tuple)) and len(lv) >= 2 else 0.0), 0.0)
                    if float(px) > 0.0 and float(sz) > 0.0:
                        ask_q += float(px) * float(sz)
                q = float(min(float(bid_q), float(ask_q)))
                if math.isfinite(float(q)) and float(q) > 0.0:
                    depth_quote = float(q)
    except Exception:
        depth_quote = None

    HL_CARRY_DEPTH_CACHE[key] = {"ts": int(now_ms), "depth_quote": (None if depth_quote is None else float(depth_quote))}
    return depth_quote


def _carry_rsi(closes: List[float], n: int = 14) -> Optional[float]:
    if not closes or len(closes) < (n + 2):
        return None
    gains: List[float] = []
    losses: List[float] = []
    for i in range(1, len(closes)):
        ch = float(closes[i] - closes[i - 1])
        gains.append(max(ch, 0.0))
        losses.append(max(-ch, 0.0))
    if len(gains) < n:
        return None
    avg_g = sum(gains[:n]) / float(n)
    avg_l = sum(losses[:n]) / float(n)
    for i in range(n, len(gains)):
        avg_g = (avg_g * (float(n) - 1.0) + gains[i]) / float(n)
        avg_l = (avg_l * (float(n) - 1.0) + losses[i]) / float(n)
    if avg_l <= 0.0:
        return 100.0
    rs = avg_g / avg_l
    rsi = 100.0 - (100.0 / (1.0 + rs))
    return float(rsi) if math.isfinite(float(rsi)) else None


def _ema(series: List[float], n: int) -> List[float]:
    if not series or n <= 1:
        return list(series or [])
    out: List[float] = []
    k = 2.0 / (float(n) + 1.0)
    ema_v: Optional[float] = None
    for x in series:
        v = float(x)
        if ema_v is None:
            ema_v = v
        else:
            ema_v = (v - ema_v) * k + ema_v
        out.append(float(ema_v))
    return out


def _carry_tema(closes: List[float], n: int = 9) -> Optional[float]:
    if not closes or len(closes) < (n + 3):
        return None
    e1 = _ema(closes, int(n))
    e2 = _ema(e1, int(n))
    e3 = _ema(e2, int(n))
    if not e3:
        return None
    tema = 3.0 * float(e1[-1]) - 3.0 * float(e2[-1]) + float(e3[-1])
    return float(tema) if math.isfinite(float(tema)) else None


def _carry_bb_mid(closes: List[float], n: int = 20) -> Optional[float]:
    if not closes or len(closes) < n:
        return None
    w = closes[-n:]
    mu = sum(w) / float(n)
    return float(mu) if math.isfinite(float(mu)) else None


def _carry_5m_signal_gate(rows5: List[List[float]], carry_side: str) -> Dict[str, Any]:
    if not rows5 or len(rows5) < 30:
        return {"ok": True, "tag": "insufficient"}
    closes: List[float] = []
    vols: List[float] = []
    for r in rows5:
        try:
            closes.append(float(r[4]))
            vols.append(float(r[5]))
        except Exception:
            return {"ok": True, "tag": "insufficient"}

    rsi = _carry_rsi(closes, n=14)
    tema = _carry_tema(closes, n=9)
    bb_mid = _carry_bb_mid(closes, n=20)
    if rsi is None or tema is None or bb_mid is None:
        return {"ok": True, "tag": "insufficient"}

    tema_prev = None
    try:
        tema_prev = _carry_tema(closes[:-1], n=9)
    except Exception:
        tema_prev = None
    if tema_prev is None:
        return {"ok": True, "tag": "insufficient"}

    vol_mean = 0.0
    try:
        vol_mean = sum(vols[-20:]) / float(min(20, len(vols)))
    except Exception:
        vol_mean = 0.0
    vol_ok = float(vols[-1] or 0.0) > float(vol_mean) * 0.5 if vol_mean > 0 else True

    side = str(carry_side or "").strip().lower()
    if side == "short":
        deep = (float(rsi) > 72.0) and (float(tema) >= float(bb_mid)) and (float(tema) < float(tema_prev)) and bool(vol_ok)
        mild = (float(rsi) > 68.0) and (float(tema) >= float(bb_mid)) and (float(tema) < float(tema_prev))
        if deep:
            return {"ok": True, "tag": "short_rsi_deep", "rsi": float(rsi), "tema": float(tema), "bb_mid": float(bb_mid)}
        if mild:
            return {"ok": True, "tag": "short_rsi_mild", "rsi": float(rsi), "tema": float(tema), "bb_mid": float(bb_mid)}
        return {"ok": False, "tag": "short_no_signal", "rsi": float(rsi), "tema": float(tema), "bb_mid": float(bb_mid)}
    if side == "long":
        deep = (float(rsi) < 27.0) and (float(tema) <= float(bb_mid)) and (float(tema) > float(tema_prev)) and bool(vol_ok)
        mild = (float(rsi) < 32.0) and (float(tema) <= float(bb_mid)) and (float(tema) > float(tema_prev))
        if deep:
            return {"ok": True, "tag": "rsi_deep", "rsi": float(rsi), "tema": float(tema), "bb_mid": float(bb_mid)}
        if mild:
            return {"ok": True, "tag": "rsi_mild", "rsi": float(rsi), "tema": float(tema), "bb_mid": float(bb_mid)}
        return {"ok": False, "tag": "long_no_signal", "rsi": float(rsi), "tema": float(tema), "bb_mid": float(bb_mid)}
    return {"ok": True, "tag": "unknown_side"}


def _carry_best_timing_score_rows(rows5: List[List[float]], carry_side: str) -> Dict[str, Any]:
    if not rows5 or len(rows5) < 50:
        return {"ok": True, "tag": "insufficient", "score": 0.0}
    closes: List[float] = []
    for r in rows5:
        try:
            closes.append(float(r[4]))
        except Exception:
            return {"ok": True, "tag": "insufficient", "score": 0.0}
    rsi = _carry_rsi(closes, n=14)
    tema = _carry_tema(closes, n=9)
    bb_mid = _carry_bb_mid(closes, n=20)
    if rsi is None or tema is None or bb_mid is None:
        return {"ok": True, "tag": "insufficient", "score": 0.0}
    try:
        rsi_prev = _carry_rsi(closes[:-1], n=14)
    except Exception:
        rsi_prev = None
    try:
        tema_prev = _carry_tema(closes[:-1], n=9)
    except Exception:
        tema_prev = None
    if rsi_prev is None or tema_prev is None:
        return {"ok": True, "tag": "insufficient", "score": 0.0}

    def _ret(a: float, b: float) -> float:
        if (not math.isfinite(a)) or (not math.isfinite(b)) or b == 0.0:
            return 0.0
        return (float(a) / float(b)) - 1.0

    try:
        slope_now = _ret(float(closes[-1]), float(closes[-13]))
        slope_prev = _ret(float(closes[-13]), float(closes[-26]))
    except Exception:
        slope_now = 0.0
        slope_prev = 0.0

    side = str(carry_side or "").strip().lower()
    if side == "short":
        trend_mag = float(_clip((float(slope_prev) - float(slope_now)) / 0.008, 0.0, 1.0))
        trend_flip = 1.0 if (float(slope_prev) > 0.001 and float(slope_now) < -0.0005) else 0.0
        trend_score = float(_clip(0.55 * float(trend_mag) + 0.45 * float(trend_flip), 0.0, 1.0))
        rsi_hot = float(_clip((float(rsi_prev) - 65.0) / 12.0, 0.0, 1.0))
        rsi_drop = float(_clip((float(rsi_prev) - float(rsi)) / 10.0, 0.0, 1.0))
        cross = 1.0 if (float(tema_prev) >= float(bb_mid) and float(tema) < float(bb_mid)) else 0.0
        mean_score = float(_clip(max(float(rsi_hot) * float(rsi_drop), 0.85 * float(cross)), 0.0, 1.0))
        score = float(_clip(0.55 * float(trend_score) + 0.45 * float(mean_score), 0.0, 1.0))
        return {
            "ok": True,
            "tag": "short",
            "score": float(score),
            "trend_score": float(trend_score),
            "mean_score": float(mean_score),
            "rsi": float(rsi),
            "rsi_prev": float(rsi_prev),
            "tema": float(tema),
            "tema_prev": float(tema_prev),
            "bb_mid": float(bb_mid),
            "slope_now": float(slope_now),
            "slope_prev": float(slope_prev),
        }
    if side == "long":
        trend_mag = float(_clip((float(slope_now) - float(slope_prev)) / 0.008, 0.0, 1.0))
        trend_flip = 1.0 if (float(slope_prev) < -0.001 and float(slope_now) > 0.0005) else 0.0
        trend_score = float(_clip(0.55 * float(trend_mag) + 0.45 * float(trend_flip), 0.0, 1.0))
        rsi_cold = float(_clip((35.0 - float(rsi_prev)) / 12.0, 0.0, 1.0))
        rsi_rise = float(_clip((float(rsi) - float(rsi_prev)) / 10.0, 0.0, 1.0))
        cross = 1.0 if (float(tema_prev) <= float(bb_mid) and float(tema) > float(bb_mid)) else 0.0
        mean_score = float(_clip(max(float(rsi_cold) * float(rsi_rise), 0.85 * float(cross)), 0.0, 1.0))
        score = float(_clip(0.55 * float(trend_score) + 0.45 * float(mean_score), 0.0, 1.0))
        return {
            "ok": True,
            "tag": "long",
            "score": float(score),
            "trend_score": float(trend_score),
            "mean_score": float(mean_score),
            "rsi": float(rsi),
            "rsi_prev": float(rsi_prev),
            "tema": float(tema),
            "tema_prev": float(tema_prev),
            "bb_mid": float(bb_mid),
            "slope_now": float(slope_now),
            "slope_prev": float(slope_prev),
        }
    return {"ok": True, "tag": "unknown_side", "score": 0.0}


def _carry_unhedge_exit_score_rows(rows5: List[List[float]], carry_side: str) -> Dict[str, Any]:
    if not rows5 or len(rows5) < 40:
        return {"ok": True, "tag": "insufficient", "score": 0.0}
    closes: List[float] = []
    vols: List[float] = []
    for r in rows5:
        try:
            closes.append(float(r[4]))
            vols.append(float(r[5]))
        except Exception:
            return {"ok": True, "tag": "insufficient", "score": 0.0}
    rsi = _carry_rsi(closes, n=14)
    tema = _carry_tema(closes, n=9)
    bb_mid = _carry_bb_mid(closes, n=20)
    if rsi is None or tema is None or bb_mid is None:
        return {"ok": True, "tag": "insufficient", "score": 0.0}
    try:
        tema_prev = _carry_tema(closes[:-1], n=9)
    except Exception:
        tema_prev = None
    if tema_prev is None:
        return {"ok": True, "tag": "insufficient", "score": 0.0}
    vol_mean = 0.0
    try:
        vol_mean = sum(vols[-20:]) / float(min(20, len(vols)))
    except Exception:
        vol_mean = 0.0
    vol_ok = float(vols[-1] or 0.0) > float(vol_mean) * 0.5 if vol_mean > 0 else True
    side = str(carry_side or "").strip().lower()
    if side == "short":
        rsi_score = float(_clip((40.0 - float(rsi)) / 18.0, 0.0, 1.0))
        turn = 1.0 if (float(tema) <= float(bb_mid) and float(tema) > float(tema_prev)) else 0.0
        score = float(_clip(0.65 * float(rsi_score) + 0.35 * float(turn), 0.0, 1.0))
        if not bool(vol_ok):
            score = float(score) * 0.85
        return {"ok": True, "tag": "short", "score": float(score), "rsi": float(rsi), "tema": float(tema), "tema_prev": float(tema_prev), "bb_mid": float(bb_mid)}
    if side == "long":
        rsi_score = float(_clip((float(rsi) - 60.0) / 18.0, 0.0, 1.0))
        turn = 1.0 if (float(tema) >= float(bb_mid) and float(tema) < float(tema_prev)) else 0.0
        score = float(_clip(0.65 * float(rsi_score) + 0.35 * float(turn), 0.0, 1.0))
        if not bool(vol_ok):
            score = float(score) * 0.85
        return {"ok": True, "tag": "long", "score": float(score), "rsi": float(rsi), "tema": float(tema), "tema_prev": float(tema_prev), "bb_mid": float(bb_mid)}
    return {"ok": True, "tag": "unknown_side", "score": 0.0}


def _carry_ott_reversal_rows(rows: List[List[float]], pds: int = 3, percent: float = 2.2, shift: int = 2, cross_lookback: int = 6) -> Dict[str, Any]:
    if not rows or len(rows) < 60:
        return {"ok": True, "tag": "insufficient", "cross_dir": 0, "dir": 0}
    closes: List[float] = []
    for r in rows:
        try:
            closes.append(float(r[4]))
        except Exception:
            return {"ok": True, "tag": "insufficient", "cross_dir": 0, "dir": 0}
    if len(closes) < 60:
        return {"ok": True, "tag": "insufficient", "cross_dir": 0, "dir": 0}

    p = int(max(1, min(20, int(pds))))
    pc = float(_clip(float(percent), 0.1, 10.0))
    sh = int(max(0, min(10, int(shift))))
    lb = int(max(1, min(50, int(cross_lookback))))

    alpha = 2.0 / (float(p) + 1.0)

    diff: List[float] = [0.0]
    for i in range(1, len(closes)):
        diff.append(float(closes[i]) - float(closes[i - 1]))
    ud: List[float] = [0.0 if d <= 0.0 else float(d) for d in diff]
    dd: List[float] = [0.0 if d >= 0.0 else float(-d) for d in diff]

    cmo: List[float] = [0.0 for _ in closes]
    win = 9
    sum_ud = 0.0
    sum_dd = 0.0
    for i in range(len(closes)):
        sum_ud += float(ud[i])
        sum_dd += float(dd[i])
        if i >= win:
            sum_ud -= float(ud[i - win])
            sum_dd -= float(dd[i - win])
        denom = float(sum_ud) + float(sum_dd)
        if i >= (win - 1) and denom > 1e-12 and math.isfinite(float(denom)):
            cmo[i] = abs((float(sum_ud) - float(sum_dd)) / float(denom))
        else:
            cmo[i] = 0.0

    var: List[float] = [float(closes[0])]
    for i in range(1, len(closes)):
        cm = float(cmo[i])
        v_prev = float(var[-1])
        cl = float(closes[i])
        var.append((float(alpha) * float(cm) * float(cl)) + (1.0 - float(alpha) * float(cm)) * float(v_prev))

    fark: List[float] = [float(v) * float(pc) * 0.01 for v in var]
    new_long_stop: List[float] = [float(var[i]) - float(fark[i]) for i in range(len(var))]
    new_short_stop: List[float] = [float(var[i]) + float(fark[i]) for i in range(len(var))]
    long_stop: List[float] = [float(new_long_stop[0])]
    short_stop: List[float] = [float(new_short_stop[0])]
    for i in range(1, len(var)):
        prev_ls = float(long_stop[-1])
        prev_ss = float(short_stop[-1])
        nl = float(new_long_stop[i])
        ns = float(new_short_stop[i])
        if float(var[i]) > float(prev_ls):
            long_stop.append(max(float(prev_ls), float(nl)))
        else:
            long_stop.append(float(nl))
        if float(var[i]) < float(prev_ss):
            short_stop.append(min(float(prev_ss), float(ns)))
        else:
            short_stop.append(float(ns))

    direction: List[int] = [1]
    for i in range(1, len(var)):
        if float(var[i]) > float(short_stop[i - 1]) and float(var[i - 1]) <= float(short_stop[i - 1]):
            direction.append(1)
        elif float(var[i]) < float(long_stop[i - 1]) and float(var[i - 1]) >= float(long_stop[i - 1]):
            direction.append(-1)
        else:
            direction.append(int(direction[-1]))

    mt: List[float] = [float(long_stop[i]) if int(direction[i]) == 1 else float(short_stop[i]) for i in range(len(var))]
    ott_raw: List[float] = []
    for i in range(len(var)):
        if float(var[i]) > float(mt[i]):
            ott_raw.append(float(mt[i]) * (200.0 + float(pc)) / 200.0)
        else:
            ott_raw.append(float(mt[i]) * (200.0 - float(pc)) / 200.0)

    ott: List[Optional[float]] = [None for _ in range(len(var))]
    for i in range(len(var)):
        j = i - int(sh)
        if j >= 0:
            ott[i] = float(ott_raw[j])

    cross_dir = 0
    last_i = len(var) - 1
    start = max(1, last_i - lb + 1)
    for i in range(last_i, start - 1, -1):
        if ott[i] is None or ott[i - 1] is None:
            continue
        v0 = float(var[i - 1])
        v1 = float(var[i])
        o0 = float(ott[i - 1])
        o1 = float(ott[i])
        if float(v1) > float(o1) and float(v0) <= float(o0):
            cross_dir = 1
            break
        if float(v1) < float(o1) and float(v0) >= float(o0):
            cross_dir = -1
            break

    return {
        "ok": True,
        "tag": "ok",
        "cross_dir": int(cross_dir),
        "dir": int(direction[-1]),
        "var": float(var[-1]),
        "ott": (None if ott[-1] is None else float(ott[-1])),
        "pds": int(p),
        "percent": float(pc),
        "shift": int(sh),
        "cross_lookback": int(lb),
    }


def _carry_unhedge_gate(now_ms: int, venue: str, pair: str, coin: str, p: Dict[str, Any], macro_dir: int, ott: Dict[str, Any], cfg: Optional[Dict[str, Any]] = None, state: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    c = (cfg if isinstance(cfg, dict) else {})
    st = (state if isinstance(state, dict) else {})
    enabled = bool(c.get("carry_trade_unhedge_gate_enabled", CONFIG.get("carry_trade_unhedge_gate_enabled", True)))
    if not bool(enabled):
        return {"ok": True, "tag": "disabled"}

    try:
        persist_s = float(c.get("carry_trade_unhedge_gate_persist_sec", CONFIG.get("carry_trade_unhedge_gate_persist_sec", 120)) or 120)
    except Exception:
        persist_s = 120.0
    persist_ms = int(round(float(_clip(float(persist_s), 0.0, 24.0 * 3600.0)) * 1000.0))

    try:
        timeout_s = float(c.get("carry_trade_unhedge_gate_timeout_sec", CONFIG.get("carry_trade_unhedge_gate_timeout_sec", 1200)) or 1200)
    except Exception:
        timeout_s = 1200.0
    timeout_ms = int(round(float(_clip(float(timeout_s), 0.0, 30.0 * 24.0 * 3600.0)) * 1000.0))
    timeout_action = str(c.get("carry_trade_unhedge_gate_timeout_action", CONFIG.get("carry_trade_unhedge_gate_timeout_action", "close_both")) or "close_both").strip().lower()
    if timeout_action not in ("close_both", "unhedge"):
        timeout_action = "close_both"

    try:
        funding_flip_abs_min = float(c.get("carry_trade_unhedge_gate_funding_flip_abs_min", CONFIG.get("carry_trade_unhedge_gate_funding_flip_abs_min", 0.00002)) or 0.00002)
    except Exception:
        funding_flip_abs_min = 0.00002
    funding_flip_abs_min = float(max(0.0, float(funding_flip_abs_min)))

    try:
        basis_abs_bps_max = float(c.get("carry_trade_unhedge_gate_basis_abs_bps_max", CONFIG.get("carry_trade_unhedge_gate_basis_abs_bps_max", 120.0)) or 120.0)
    except Exception:
        basis_abs_bps_max = 120.0
    basis_abs_bps_max = float(max(0.0, float(basis_abs_bps_max)))

    try:
        basis_widen_mult = float(c.get("carry_trade_unhedge_gate_basis_widen_mult", CONFIG.get("carry_trade_unhedge_gate_basis_widen_mult", 2.0)) or 2.0)
    except Exception:
        basis_widen_mult = 2.0
    basis_widen_mult = float(_clip(float(basis_widen_mult), 1.0, 100.0))

    try:
        basis_widen_abs_min_bps = float(c.get("carry_trade_unhedge_gate_basis_widen_abs_min_bps", CONFIG.get("carry_trade_unhedge_gate_basis_widen_abs_min_bps", 25.0)) or 25.0)
    except Exception:
        basis_widen_abs_min_bps = 25.0
    basis_widen_abs_min_bps = float(max(0.0, float(basis_widen_abs_min_bps)))

    try:
        spread_bps_max = float(c.get("carry_trade_unhedge_gate_spread_bps_max", CONFIG.get("carry_trade_unhedge_gate_spread_bps_max", 60.0)) or 60.0)
    except Exception:
        spread_bps_max = 60.0
    spread_bps_max = float(max(0.0, float(spread_bps_max)))

    try:
        conf_n = int(c.get("carry_trade_unhedge_gate_ott_confirm_n", CONFIG.get("carry_trade_unhedge_gate_ott_confirm_n", 2)) or 2)
    except Exception:
        conf_n = 2
    try:
        conf_m = int(c.get("carry_trade_unhedge_gate_ott_confirm_m", CONFIG.get("carry_trade_unhedge_gate_ott_confirm_m", 3)) or 3)
    except Exception:
        conf_m = 3
    conf_n = int(_clip(float(conf_n), 1.0, 10.0))
    conf_m = int(_clip(float(conf_m), float(conf_n), 30.0))
    try:
        conf_age_s = float(c.get("carry_trade_unhedge_gate_ott_confirm_max_age_sec", CONFIG.get("carry_trade_unhedge_gate_ott_confirm_max_age_sec", 600)) or 600)
    except Exception:
        conf_age_s = 600.0
    conf_age_ms = int(round(float(_clip(float(conf_age_s), 30.0, 24.0 * 3600.0)) * 1000.0))

    metrics = None
    try:
        metrics = p.get("active_metrics") if isinstance(p.get("active_metrics"), dict) else None
    except Exception:
        metrics = None
    if not isinstance(metrics, dict):
        try:
            metrics = _carry_active_metrics(int(now_ms), venue=str(venue), coin=str(coin))
        except Exception:
            metrics = {}

    fr = None
    basis_bps = None
    spread_bps = None
    try:
        fr = float(metrics.get("funding_rate")) if isinstance(metrics, dict) and metrics.get("funding_rate") is not None else None
    except Exception:
        fr = None
    try:
        basis_bps = float(metrics.get("basis_bps")) if isinstance(metrics, dict) and metrics.get("basis_bps") is not None else None
    except Exception:
        basis_bps = None
    try:
        spread_bps = float(metrics.get("spread_bps")) if isinstance(metrics, dict) and metrics.get("spread_bps") is not None else None
    except Exception:
        spread_bps = None

    hard_flags: List[str] = []
    spread_flag = False
    if spread_bps is not None and math.isfinite(float(spread_bps)) and float(spread_bps_max) > 0.0 and float(spread_bps) >= float(spread_bps_max):
        spread_flag = True
    if fr is not None and math.isfinite(float(fr)) and float(funding_flip_abs_min) > 0.0:
        try:
            s0 = str(p.get("side") or "short").strip().lower()
        except Exception:
            s0 = "short"
        if str(s0) == "long":
            if float(fr) >= float(funding_flip_abs_min):
                hard_flags.append("funding_flip")
        else:
            if float(fr) <= -float(funding_flip_abs_min):
                hard_flags.append("funding_flip")
    if basis_bps is not None and math.isfinite(float(basis_bps)):
        if float(basis_abs_bps_max) > 0.0 and abs(float(basis_bps)) >= float(basis_abs_bps_max):
            hard_flags.append("basis_abs")
        entry_basis = None
        try:
            cand = p.get("candidate")
            if isinstance(cand, dict) and cand.get("basis_bps") is not None:
                entry_basis = float(cand.get("basis_bps"))
        except Exception:
            entry_basis = None
        if entry_basis is not None and math.isfinite(float(entry_basis)):
            ae = abs(float(entry_basis))
            an = abs(float(basis_bps))
            thr = max(float(ae) * float(basis_widen_mult), float(ae) + float(basis_widen_abs_min_bps))
            if float(an) >= float(thr):
                hard_flags.append("basis_widen")

    mdir = int(macro_dir or 0)
    cross_dir = 0
    try:
        cross_dir = int((ott.get("cross_dir") if isinstance(ott, dict) else 0) or 0)
    except Exception:
        cross_dir = 0

    votes_by_pair = st.get("unhedge_ott_votes_by_pair")
    if not isinstance(votes_by_pair, dict):
        votes_by_pair = {}
        st["unhedge_ott_votes_by_pair"] = votes_by_pair
    hist = votes_by_pair.get(str(pair))
    if not isinstance(hist, list):
        hist = []
    hist.append({"ts": int(now_ms), "cross_dir": int(cross_dir), "macro_dir": int(mdir)})
    if len(hist) > max(12, int(conf_m) * 4):
        hist = hist[-max(12, int(conf_m) * 4) :]
    votes_by_pair[str(pair)] = hist

    recent = []
    for x in reversed(hist):
        try:
            ts0 = int(x.get("ts") or 0)
        except Exception:
            ts0 = 0
        if ts0 <= 0:
            continue
        if int(now_ms) - int(ts0) > int(conf_age_ms):
            break
        recent.append(x)
        if len(recent) >= int(conf_m):
            break
    recent = list(reversed(recent))
    match = 0
    nonzero = 0
    for x in recent:
        try:
            cd = int(x.get("cross_dir") or 0)
        except Exception:
            cd = 0
        if int(cd) != 0:
            nonzero += 1
        if int(cd) == int(mdir) and int(mdir) != 0:
            match += 1
    ott_ok = True
    if int(mdir) != 0 and int(conf_n) > 0:
        ott_ok = (int(match) >= int(conf_n))
    if int(mdir) != 0 and int(nonzero) == 0 and int(conf_n) > 0:
        ott_ok = False

    flags: List[str] = []
    if bool(spread_flag):
        flags.append("spread_high")
    flags.extend(list(hard_flags))
    if not bool(ott_ok):
        flags.append("ott_unstable")

    mview = {
        "funding_rate": (None if fr is None else float(fr)),
        "basis_bps": (None if basis_bps is None else float(basis_bps)),
        "spread_bps": (None if spread_bps is None else float(spread_bps)),
        "macro_dir": int(mdir),
        "ott_cross_dir": int(cross_dir),
        "ott_votes": {"n": int(conf_n), "m": int(conf_m), "match": int(match), "nonzero": int(nonzero)},
    }

    gs = p.get("unhedge_gate") if isinstance(p.get("unhedge_gate"), dict) else {}
    first_ts = 0
    try:
        first_ts = int(gs.get("ts_first") or 0)
    except Exception:
        first_ts = 0

    hard_now = bool(spread_flag) or bool(hard_flags)
    if bool(hard_now):
        if first_ts <= 0:
            first_ts = int(now_ms)
    else:
        first_ts = 0

    age_ms = (0 if first_ts <= 0 else max(0, int(now_ms) - int(first_ts)))

    spread_triggered = True
    if bool(spread_flag) and int(persist_ms) > 0:
        spread_triggered = int(age_ms) >= int(persist_ms)
    hard_triggered = bool(hard_flags) or (bool(spread_flag) and bool(spread_triggered))

    timeout_hit = bool(hard_now) and int(timeout_ms) > 0 and int(age_ms) >= int(timeout_ms)

    action = "allow"
    ok = True
    if bool(timeout_hit):
        action = ("force_close_both" if str(timeout_action) == "close_both" else "force_unhedge")
        ok = False
    elif bool(hard_triggered) or (not bool(ott_ok)):
        action = "block"
        ok = False

    out = {
        "ok": bool(ok),
        "tag": ("ok" if bool(ok) else action),
        "action": str(action),
        "ts_first": (None if first_ts <= 0 else int(first_ts)),
        "ts_last": int(now_ms),
        "age_ms": int(age_ms),
        "persist_ms": int(persist_ms),
        "timeout_ms": int(timeout_ms),
        "flags": list(flags),
        "metrics": dict(mview),
    }
    try:
        p["unhedge_gate"] = dict(out)
    except Exception:
        pass
    return out


def _carry_macro_dir_gate(timeframe: str = "1h", horizon_h: int = 12, short_n: int = 3) -> Dict[str, Any]:
    try:
        snap = _macro_btc_dir_snapshot(timeframe=str(timeframe), horizon_h=int(horizon_h), short_n=int(short_n))
    except Exception as e:
        return {"ok": False, "error": str(e), "dir": 0}
    if not isinstance(snap, dict) or not bool(snap.get("ok", False)):
        return {"ok": False, "error": str((snap or {}).get("error") if isinstance(snap, dict) else "no_data"), "dir": 0, "snap": (snap if isinstance(snap, dict) else None)}
    try:
        d = int(snap.get("dir_h") or 0)
    except Exception:
        d = 0
    if int(d) == 0:
        try:
            d = int(snap.get("dir_short") or 0)
        except Exception:
            d = 0
    return {"ok": True, "dir": int(d), "snap": dict(snap)}


def _carry_1m_spike_gate(coin: str, now_ms: int) -> Dict[str, Any]:
    rows1 = _carry_hl_fetch_ohlcv_rows_quick(coin=coin, interval="1m", now_ms=int(now_ms), lookback_ms=90 * 60 * 1000, ttl_sec=8, timeout_sec=2.0)
    return _carry_1m_spike_gate_rows(rows1)


def _carry_1m_spike_gate_rows(rows1: List[List[float]]) -> Dict[str, Any]:
    if not rows1 or len(rows1) < 40:
        return {"ok": True, "tag": "insufficient"}
    atr_now = _carry_atr_pct(rows1, n=14)
    if atr_now is None:
        return {"ok": True, "tag": "insufficient"}
    atr_hist: List[float] = []
    for i in range(20, len(rows1)):
        atr_i = _carry_atr_pct(rows1[: i + 1], n=14)
        if atr_i is not None and math.isfinite(float(atr_i)) and float(atr_i) > 0.0:
            atr_hist.append(float(atr_i))
    if not atr_hist:
        return {"ok": True, "tag": "insufficient"}
    base = sorted(atr_hist[-60:])[len(atr_hist[-60:]) // 2]
    if base <= 0.0:
        return {"ok": True, "tag": "insufficient"}
    try:
        mult = float(CONFIG.get("carry_trade_1m_spike_atr_mult", 2.5) or 2.5)
    except Exception:
        mult = 2.5
    mult = float(_clip(float(mult), 1.0, 10.0))
    spike = float(atr_now) >= float(mult) * float(base)
    return {"ok": (not bool(spike)), "tag": ("spike" if spike else "ok"), "atr_now": float(atr_now), "atr_base": float(base), "mult": float(mult)}


def _carry_hedge_dyn_leverage(
    coin: Optional[str],
    atr_pct_5m: Optional[float],
    spread_bps: Optional[float],
    depth_quote_usd: Optional[float],
    notional_usdc: Optional[float],
    cfg: Optional[Dict[str, Any]] = None,
) -> int:
    c = (cfg if isinstance(cfg, dict) else {})
    enabled = bool(c.get("carry_trade_hedge_dyn_leverage_enabled", CONFIG.get("carry_trade_hedge_dyn_leverage_enabled", False)))
    if not bool(enabled):
        try:
            return int(CONFIG.get("hl_default_leverage", 3) or 3)
        except Exception:
            return 3
    try:
        lev_min = int(c.get("carry_trade_hedge_leverage_min", CONFIG.get("carry_trade_hedge_leverage_min", 3)) or 3)
    except Exception:
        lev_min = 3
    try:
        lev_max = int(c.get("carry_trade_hedge_leverage_max", CONFIG.get("carry_trade_hedge_leverage_max", 10)) or 10)
    except Exception:
        lev_max = 10
    lev_min = max(1, min(100, int(lev_min)))
    lev_max = max(1, min(100, int(lev_max)))
    if lev_min > lev_max:
        lev_min = lev_max
    try:
        target_move_r = float(c.get("carry_trade_hedge_leverage_target_move_r", CONFIG.get("carry_trade_hedge_leverage_target_move_r", 0.06)) or 0.06)
    except Exception:
        target_move_r = 0.06
    try:
        atr_floor = float(c.get("carry_trade_hedge_leverage_atr_floor", CONFIG.get("carry_trade_hedge_leverage_atr_floor", 0.003)) or 0.003)
    except Exception:
        atr_floor = 0.003
    target_move_r = float(_clip(float(target_move_r), 0.001, 0.50))
    atr_floor = float(_clip(float(atr_floor), 0.0001, 0.20))
    a = None if atr_pct_5m is None else float(atr_pct_5m)
    if a is None or (not math.isfinite(float(a))) or float(a) <= 0.0:
        a = float(atr_floor)
    denom = max(float(a), float(atr_floor))
    raw = float(target_move_r) / float(denom) if denom > 0.0 else float(lev_min)
    lev_atr = int(round(raw))
    lev_atr = int(_clip(int(lev_atr), int(lev_min), int(lev_max)))

    try:
        sp_good = float(c.get("carry_trade_hedge_leverage_spread_good_bps", CONFIG.get("carry_trade_hedge_leverage_spread_good_bps", 8.0)) or 8.0)
    except Exception:
        sp_good = 8.0
    try:
        sp_bad = float(c.get("carry_trade_hedge_leverage_spread_bad_bps", CONFIG.get("carry_trade_hedge_leverage_spread_bad_bps", 30.0)) or 30.0)
    except Exception:
        sp_bad = 30.0
    sp_good = float(_clip(float(sp_good), 0.0, 5000.0))
    sp_bad = float(_clip(float(sp_bad), 0.0, 5000.0))
    if sp_good > sp_bad:
        sp_good, sp_bad = sp_bad, sp_good

    lev_liq = float(lev_max)
    sp = None if spread_bps is None else float(spread_bps)
    if sp is not None and math.isfinite(float(sp)) and float(sp) >= 0.0 and float(sp_bad) > 0.0:
        if float(sp) <= float(sp_good) + 1e-12:
            lev_liq = float(lev_max)
        elif float(sp) >= float(sp_bad) - 1e-12:
            lev_liq = float(lev_min)
        else:
            x = (float(sp_bad) - float(sp)) / max(float(sp_bad) - float(sp_good), 1e-12)
            x = float(_clip(float(x), 0.0, 1.0))
            lev_liq = float(lev_min) + (float(lev_max) - float(lev_min)) * float(x)

    use_depth = bool(c.get("carry_trade_hedge_leverage_use_depth", CONFIG.get("carry_trade_hedge_leverage_use_depth", False)))
    if bool(use_depth) and depth_quote_usd is not None:
        dq = None
        try:
            dq = float(depth_quote_usd)
        except Exception:
            dq = None
        if dq is not None and math.isfinite(float(dq)) and float(dq) > 0.0:
            try:
                depth_mult = float(c.get("carry_trade_hedge_leverage_depth_notional_mult", CONFIG.get("carry_trade_hedge_leverage_depth_notional_mult", 3.0)) or 3.0)
            except Exception:
                depth_mult = 3.0
            depth_mult = float(_clip(float(depth_mult), 0.1, 1000.0))
            ntl = None
            try:
                ntl = float(notional_usdc) if notional_usdc is not None else None
            except Exception:
                ntl = None
            if ntl is not None and math.isfinite(float(ntl)) and float(ntl) > 0.0:
                ref = float(ntl) * float(depth_mult)
                ratio = float(dq) / max(float(ref), 1e-12)
                ratio = float(_clip(float(ratio), 0.0, 1.0))
                lev_liq2 = float(lev_min) + (float(lev_max) - float(lev_min)) * float(ratio)
                lev_liq = float(min(float(lev_liq), float(lev_liq2)))

    majors = c.get("carry_trade_hedge_leverage_major_coins", CONFIG.get("carry_trade_hedge_leverage_major_coins", ["BTC", "ETH", "SOL"]))
    major_items: List[str] = []
    if isinstance(majors, str):
        major_items = [x for x in [y.strip() for y in str(majors).replace(";", ",").split(",")] if x]
    elif isinstance(majors, (list, tuple)):
        major_items = [str(x) for x in majors if str(x).strip()]
    major_set = set([str(x).upper().strip() for x in major_items if str(x).strip()])
    coin_u = str(coin or "").upper().strip()
    try:
        alt_max = int(c.get("carry_trade_hedge_leverage_alt_max", CONFIG.get("carry_trade_hedge_leverage_alt_max", 6)) or 6)
    except Exception:
        alt_max = 6
    alt_max = max(1, min(100, int(alt_max)))
    tier_max = int(lev_max) if (coin_u and coin_u in major_set) else int(min(int(lev_max), int(alt_max)))
    tier_max = max(int(lev_min), int(tier_max))

    lev = float(min(float(lev_atr), float(lev_liq), float(tier_max)))
    lev_i = int(_clip(int(round(lev)), int(lev_min), int(lev_max)))
    return int(max(1, min(100, int(lev_i))))


def _carry_universe_parse_coin_list(x: Any) -> List[str]:
    if x is None:
        return []
    if isinstance(x, (list, tuple, set)):
        out = []
        for it in x:
            s = str(it or "").strip()
            if s:
                out.append(s)
        return out
    s = str(x or "").strip()
    if not s:
        return []
    s = s.replace(";", ",")
    return [p for p in [y.strip() for y in s.split(",")] if p]


def _carry_universe_build_hl(now_ms: int, cfg: Dict[str, Any]) -> Dict[str, Any]:
    now_ms = int(now_ms)
    allow = set([str(x).upper().strip() for x in _carry_universe_parse_coin_list(cfg.get("carry_universe_allowlist")) if str(x).strip()])
    deny = set([str(x).upper().strip() for x in _carry_universe_parse_coin_list(cfg.get("carry_universe_denylist")) if str(x).strip()])

    try:
        min_abs_funding = float(cfg.get("carry_universe_min_abs_funding") if cfg.get("carry_universe_min_abs_funding") is not None else cfg.get("carry_trade_min_abs_funding"))
    except Exception:
        min_abs_funding = float(CONFIG.get("carry_universe_min_abs_funding", 0.00005) or 0.00005)
    try:
        max_spread_bps = float(cfg.get("carry_universe_max_spread_bps") if cfg.get("carry_universe_max_spread_bps") is not None else cfg.get("carry_trade_max_spread_bps"))
    except Exception:
        max_spread_bps = float(CONFIG.get("carry_universe_max_spread_bps", 15) or 15)
    try:
        min_day_ntl = float(cfg.get("carry_universe_min_day_ntl", CONFIG.get("carry_universe_min_day_ntl", 0.0)) or 0.0)
    except Exception:
        min_day_ntl = 0.0
    try:
        max_coins = int(cfg.get("carry_universe_max_coins", CONFIG.get("carry_universe_max_coins", 200)) or 200)
    except Exception:
        max_coins = 200
    max_coins = max(1, min(2000, int(max_coins)))

    ctxs = _hl_meta_and_asset_ctxs_cached(int(now_ms))
    if (not isinstance(ctxs, dict)) or (not ctxs):
        raise RuntimeError("hl_meta_and_asset_ctxs_empty")
    items: List[Dict[str, Any]] = []
    for coin, ctx in (ctxs or {}).items():
        if not isinstance(ctx, dict):
            continue
        coin_u = str(coin).upper().strip()
        if not coin_u:
            continue
        if allow and coin_u not in allow:
            continue
        if deny and coin_u in deny:
            continue
        try:
            fr = float(ctx.get("funding") or 0.0)
        except Exception:
            fr = 0.0
        if (not math.isfinite(float(fr))) or abs(float(fr)) < float(min_abs_funding):
            continue

        try:
            day_ntl = float(ctx.get("dayNtlVlm") or 0.0)
        except Exception:
            day_ntl = 0.0
        if float(min_day_ntl) > 0.0 and ((not math.isfinite(float(day_ntl))) or float(day_ntl) < float(min_day_ntl)):
            continue

        spread_bps = _carry_hl_spread_bps_quick(coin=coin_u, now_ms=int(now_ms))
        if spread_bps is not None and float(max_spread_bps) > 0.0 and float(spread_bps) > float(max_spread_bps):
            continue

        mark_px = float(_to_float(ctx.get("markPx"), 0.0))
        oracle_px = float(_to_float(ctx.get("oraclePx"), 0.0))
        prem = float(_to_float(ctx.get("premium"), 0.0))
        basis_bps = 0.0
        if mark_px > 0.0 and oracle_px > 0.0:
            basis_bps = (mark_px / oracle_px - 1.0) * 10_000.0
        elif prem != 0.0:
            basis_bps = float(prem) * 10_000.0

        items.append(
            {
                "coin": str(coin_u),
                "funding_rate": float(fr),
                "spread_bps": (None if spread_bps is None else float(spread_bps)),
                "day_ntl": float(day_ntl),
                "basis_bps": float(basis_bps),
            }
        )

    items.sort(key=lambda x: (abs(float(x.get("funding_rate") or 0.0)), float(x.get("day_ntl") or 0.0)), reverse=True)
    if max_coins > 0:
        items = items[: int(max_coins)]

    meta = {str(it.get("coin")): dict(it) for it in items if str(it.get("coin") or "").strip()}
    coins = [str(it.get("coin")) for it in items if str(it.get("coin") or "").strip()]
    return {"ts": int(now_ms), "venue": "hyperliquid", "coins": coins, "metadata": meta, "last_error": None}


def _carry_universe_refresh(now_ms: int, cfg: Dict[str, Any], *, force: bool = False) -> Dict[str, Any]:
    now_ms = int(now_ms)
    try:
        enabled = bool(cfg.get("carry_universe_enabled", CONFIG.get("carry_universe_enabled", True)))
    except Exception:
        enabled = bool(CONFIG.get("carry_universe_enabled", True))
    if not bool(enabled):
        return {"ok": True, "enabled": False, "refreshed": False}

    try:
        venue = str(cfg.get("carry_universe_venue", CONFIG.get("carry_universe_venue", "hyperliquid")) or "hyperliquid").strip().lower() or "hyperliquid"
    except Exception:
        venue = "hyperliquid"
    if venue not in ("hyperliquid", "hl"):
        return {"ok": False, "enabled": True, "refreshed": False, "error": "unsupported_venue", "venue": str(venue)}

    try:
        refresh_s = float(cfg.get("carry_universe_refresh_seconds", CONFIG.get("carry_universe_refresh_seconds", 3600)) or 3600)
    except Exception:
        refresh_s = 3600.0
    refresh_s = float(_clip(float(refresh_s), 5.0, 3600.0))

    try:
        with CARRY_UNIVERSE_LOCK:
            ts0 = int(CARRY_UNIVERSE_STATE.get("ts") or 0)
            v0 = str(CARRY_UNIVERSE_STATE.get("venue") or "hyperliquid")
    except Exception:
        ts0 = 0
        v0 = "hyperliquid"
    age_ms = int(now_ms) - int(ts0)
    if (not bool(force)) and ts0 > 0 and int(age_ms) < int(refresh_s * 1000.0):
        return {"ok": True, "enabled": True, "refreshed": False, "ts": int(ts0), "age_ms": int(age_ms), "venue": str(v0)}

    try:
        built = _carry_universe_build_hl(int(now_ms), dict(cfg))
    except Exception as e:
        with CARRY_UNIVERSE_LOCK:
            try:
                CARRY_UNIVERSE_STATE["last_error"] = {"ts": int(now_ms), "error": str(e)}
            except Exception:
                pass
        return {"ok": False, "enabled": True, "refreshed": False, "error": str(e), "venue": str(venue)}

    with CARRY_UNIVERSE_LOCK:
        CARRY_UNIVERSE_STATE.clear()
        CARRY_UNIVERSE_STATE.update(dict(built) if isinstance(built, dict) else {"ts": int(now_ms), "venue": "hyperliquid", "coins": [], "metadata": {}, "last_error": None})
        ts1 = int(CARRY_UNIVERSE_STATE.get("ts") or 0)
        n1 = int(len(CARRY_UNIVERSE_STATE.get("coins") or [])) if isinstance(CARRY_UNIVERSE_STATE.get("coins"), list) else 0
        v1 = str(CARRY_UNIVERSE_STATE.get("venue") or "hyperliquid")
    return {"ok": True, "enabled": True, "refreshed": True, "ts": int(ts1), "n": int(n1), "venue": str(v1)}


def _carry_universe_coin_set(cfg: Dict[str, Any]) -> set:
    try:
        enabled = bool(cfg.get("carry_universe_enabled", CONFIG.get("carry_universe_enabled", True)))
    except Exception:
        enabled = bool(CONFIG.get("carry_universe_enabled", True))
    if not bool(enabled):
        return set()
    try:
        venue = str(cfg.get("carry_universe_venue", CONFIG.get("carry_universe_venue", "hyperliquid")) or "hyperliquid").strip().lower() or "hyperliquid"
    except Exception:
        venue = "hyperliquid"
    if venue not in ("hyperliquid", "hl"):
        return set()
    with CARRY_UNIVERSE_LOCK:
        try:
            st_venue = str(CARRY_UNIVERSE_STATE.get("venue") or "hyperliquid").strip().lower() or "hyperliquid"
        except Exception:
            st_venue = "hyperliquid"
        if st_venue not in ("hyperliquid", "hl"):
            return set()
        coins = CARRY_UNIVERSE_STATE.get("coins") if isinstance(CARRY_UNIVERSE_STATE, dict) else None
        if not isinstance(coins, list) or not coins:
            return set()
        return set([str(x).upper().strip() for x in coins if str(x).strip()])


def _carry_candidates_hl(now_ms: int, n: int, cfg: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    c = (cfg if isinstance(cfg, dict) else {})

    def _cfg_get(k: str, dflt: Any) -> Any:
        try:
            if k in c:
                v = c.get(k)
            else:
                v = CONFIG.get(k, dflt)
            if v is None:
                return dflt
            if isinstance(v, str) and (not v.strip()):
                return dflt
            return v
        except Exception:
            return dflt
    try:
        _carry_universe_refresh(int(now_ms), dict(c))
    except Exception:
        pass
    try:
        hold_h = float(c.get("carry_trade_expected_hold_hours", CONFIG.get("carry_trade_expected_hold_hours", 72)) or 72)
    except Exception:
        hold_h = 72.0
    hold_h = float(_clip(float(hold_h), 1.0, 24.0 * 30.0))
    period_h = 1.0
    exp_periods = max(1.0, float(hold_h) / float(period_h))
    try:
        min_abs_funding = float(_cfg_get("carry_trade_min_abs_funding", 0.00005))
    except Exception:
        min_abs_funding = 0.00005
    try:
        cost_bps = float(_cfg_get("carry_trade_cost_buffer_bps", 8))
    except Exception:
        cost_bps = 8.0
    try:
        max_atr_pct = float(_cfg_get("carry_trade_max_atr_pct_5m", 0.012))
    except Exception:
        max_atr_pct = 0.012
    try:
        veto_adx = float(_cfg_get("carry_trade_trend_veto_adx", 35))
    except Exception:
        veto_adx = 35.0

    try:
        max_spread_bps = float(_cfg_get("carry_trade_max_spread_bps", 15))
    except Exception:
        max_spread_bps = 15.0

    try:
        open_edge_thr = float(_cfg_get("carry_trade_open_edge_threshold", 0.0))
    except Exception:
        open_edge_thr = 0.0
    open_edge_thr = float(max(0.0, float(open_edge_thr)))

    try:
        use_1m_filter = bool(c.get("carry_trade_use_1m_filter", CONFIG.get("carry_trade_use_1m_filter", True)))
    except Exception:
        use_1m_filter = True

    try:
        signal_gate_enabled = bool(c.get("carry_trade_signal_gate_enabled", CONFIG.get("carry_trade_signal_gate_enabled", True)))
    except Exception:
        signal_gate_enabled = True

    corr_gate_enabled = bool(c.get("carry_trade_corr_gate_enabled", CONFIG.get("carry_trade_corr_gate_enabled", True)))
    try:
        corr_thr = float(c.get("carry_trade_corr_threshold", CONFIG.get("carry_trade_corr_threshold", 0.80)) or 0.80)
    except Exception:
        corr_thr = 0.80
    corr_thr = float(_clip(float(corr_thr), 0.0, 1.0))
    try:
        corr_n = int(c.get("carry_trade_corr_lookback_bars_5m", CONFIG.get("carry_trade_corr_lookback_bars_5m", 288)) or 288)
    except Exception:
        corr_n = 288
    corr_n = max(20, min(2000, int(corr_n)))
    refs = c.get("carry_trade_corr_refs", CONFIG.get("carry_trade_corr_refs", ["BTC", "SOL"]))
    if not isinstance(refs, list):
        refs = ["BTC", "SOL"]
    ref_coins = [str(x or "").strip().upper() for x in refs if str(x or "").strip()]
    ref_coins = [x for x in ref_coins if x]

    liq_gate_enabled = bool(c.get("carry_trade_liquidity_gate_enabled", CONFIG.get("carry_trade_liquidity_gate_enabled", True)))
    try:
        min_vol_usdc_5m = float(_cfg_get("carry_trade_min_vol_usdc_5m", 200000.0))
    except Exception:
        min_vol_usdc_5m = 200000.0
    min_vol_usdc_5m = float(max(0.0, float(min_vol_usdc_5m)))

    min_abs_funding = float(_clip(float(min_abs_funding), 0.0, 0.01))
    cost_bps = float(_clip(float(cost_bps), 0.0, 200.0))
    max_atr_pct = float(_clip(float(max_atr_pct), 0.0, 0.20))
    veto_adx = float(_clip(float(veto_adx), 0.0, 100.0))
    max_spread_bps = float(_clip(float(max_spread_bps), 0.0, 500.0))

    try:
        risk_atr_mult = float(c.get("carry_trade_risk_atr_mult", CONFIG.get("carry_trade_risk_atr_mult", 0.75)) or 0.75)
    except Exception:
        risk_atr_mult = 0.75
    try:
        risk_spread_mult = float(c.get("carry_trade_risk_spread_mult", CONFIG.get("carry_trade_risk_spread_mult", 0.50)) or 0.50)
    except Exception:
        risk_spread_mult = 0.50
    try:
        risk_jump_mult = float(c.get("carry_trade_risk_jump_mult", CONFIG.get("carry_trade_risk_jump_mult", 0.25)) or 0.25)
    except Exception:
        risk_jump_mult = 0.25
    try:
        risk_basis_mult = float(c.get("carry_trade_risk_basis_mult", CONFIG.get("carry_trade_risk_basis_mult", 0.05)) or 0.05)
    except Exception:
        risk_basis_mult = 0.05

    risk_atr_mult = float(_clip(float(risk_atr_mult), 0.0, 10.0))
    risk_spread_mult = float(_clip(float(risk_spread_mult), 0.0, 10.0))
    risk_jump_mult = float(_clip(float(risk_jump_mult), 0.0, 10.0))
    risk_basis_mult = float(_clip(float(risk_basis_mult), 0.0, 10.0))

    ctxs = _hl_meta_and_asset_ctxs_cached(int(now_ms))
    try:
        carry_uni_enabled = bool(c.get("carry_universe_enabled", CONFIG.get("carry_universe_enabled", True)))
    except Exception:
        carry_uni_enabled = bool(CONFIG.get("carry_universe_enabled", True))
    try:
        uni_set = _carry_universe_coin_set(dict(c))
        if (not bool(carry_uni_enabled)) and (not uni_set):
            core = UNIVERSE_STATE.get("core") or []
            shadow = UNIVERSE_STATE.get("shadow") or []
            uni_set = set(str(x).upper().strip() for x in (list(core) + list(shadow)) if str(x).strip())
    except Exception:
        uni_set = set()

    min_turnover_h = float(CONFIG.get("filter_min_turnover_7d", 0.0) or 0.0)
    min_day_ntl = float(min_turnover_h) * 24.0 if float(min_turnover_h) > 0.0 else 0.0
    prelim: List[Dict[str, Any]] = []
    cost_ratio = float(cost_bps) / 10_000.0
    for coin, ctx in (ctxs or {}).items():
        if not isinstance(ctx, dict):
            continue
        coin_u = str(coin).upper().strip()
        if uni_set and coin_u not in uni_set:
            continue
        try:
            fr_raw = float(ctx.get("funding") or 0.0)
        except Exception:
            fr_raw = 0.0
        if not math.isfinite(float(fr_raw)):
            continue

        try:
            _carry_funding_sample_add(int(now_ms), str(coin_u), float(fr_raw), "hl_ctx")
        except Exception:
            pass

        fr = float(fr_raw)
        est = None
        try:
            est = _carry_funding_estimate(int(now_ms), str(coin_u), dict(c))
        except Exception:
            est = None
        if isinstance(est, dict) and bool(est.get("ok")):
            try:
                fr_est = float(est.get("est") or 0.0)
            except Exception:
                fr_est = 0.0
            if math.isfinite(float(fr_est)) and (float(fr_est) * float(fr_raw) > 0.0):
                fr = float(fr_est)

        if abs(float(fr)) < float(min_abs_funding):
            continue

        try:
            day_ntl = float(ctx.get("dayNtlVlm") or 0.0)
        except Exception:
            day_ntl = 0.0
        if float(min_day_ntl) > 0.0 and (not math.isfinite(float(day_ntl)) or float(day_ntl) < float(min_day_ntl)):
            continue

        spread_bps = _carry_hl_spread_bps_quick(coin=coin_u, now_ms=int(now_ms))
        if spread_bps is not None and float(max_spread_bps) > 0.0 and float(spread_bps) > float(max_spread_bps):
            continue
        mark_px = float(_to_float(ctx.get("markPx"), 0.0))
        oracle_px = float(_to_float(ctx.get("oraclePx"), 0.0))
        prem = float(_to_float(ctx.get("premium"), 0.0))
        basis_bps = 0.0
        if mark_px > 0.0 and oracle_px > 0.0:
            basis_bps = (mark_px / oracle_px - 1.0) * 10_000.0
        elif prem != 0.0:
            basis_bps = float(prem) * 10_000.0

        carry_side = "short" if float(fr) > 0.0 else "long"
        carry_edge = abs(float(fr)) * float(exp_periods) - float(cost_ratio)
        prelim.append(
            {
                "coin": str(coin_u),
                "funding_rate": float(fr),
                "funding_rate_raw": float(fr_raw),
                "funding_est": (dict(est) if isinstance(est, dict) else None),
                "basis_bps": float(basis_bps),
                "carry_side": str(carry_side),
                "carry_edge": float(carry_edge),
                "expected_periods": float(exp_periods),
                "expected_hold_hours": float(hold_h),
                "spread_bps": (None if spread_bps is None else float(spread_bps)),
                "day_ntl": float(day_ntl),
            }
        )

    prelim.sort(key=lambda x: abs(float(x.get("funding_rate") or 0.0)), reverse=True)
    m = min(max(int(n) * 2, 12), 20)
    prelim = prelim[:m]

    ref_rets: Dict[str, List[float]] = {}
    if corr_gate_enabled and ref_coins:
        for rc in ref_coins:
            try:
                rowsr = _carry_hl_fetch_ohlcv_rows_quick(coin=rc, interval="5m", now_ms=int(now_ms), lookback_ms=max(6 * 60 * 60 * 1000, int(corr_n + 40) * 5 * 60 * 1000))
            except Exception:
                rowsr = []
            ref_rets[rc] = _carry_close_returns(rowsr, max_len=int(corr_n))

    out: List[Dict[str, Any]] = []
    for it in prelim:
        coin = str(it.get("coin") or "").strip().upper()
        if not coin:
            continue
        rows5 = _carry_hl_fetch_ohlcv_rows_quick(coin=coin, interval="5m", now_ms=int(now_ms), lookback_ms=6 * 60 * 60 * 1000)
        atr_pct_5m = _carry_atr_pct(rows5, n=14)
        adx_5m = _carry_adx(rows5, n=14)

        vol_usdc_5m = None
        try:
            if rows5 and len(rows5[-1]) >= 6:
                vol_usdc_5m = float(rows5[-1][5]) * float(rows5[-1][4])
        except Exception:
            vol_usdc_5m = None

        corr_by_ref: Dict[str, Optional[float]] = {}
        corr_max_abs = None
        if corr_gate_enabled and ref_coins:
            cret = _carry_close_returns(rows5, max_len=int(corr_n))
            for rc in ref_coins:
                if str(rc) == str(coin):
                    corr_by_ref[rc] = None
                    continue
                cc = _carry_corr(cret, ref_rets.get(rc) or [])
                corr_by_ref[rc] = (None if cc is None else float(cc))
                if cc is not None:
                    a = abs(float(cc))
                    corr_max_abs = a if corr_max_abs is None else max(float(corr_max_abs), float(a))

        sig = {"ok": True, "tag": "disabled"}
        if bool(signal_gate_enabled):
            sig = _carry_5m_signal_gate(rows5, carry_side=str(it.get("carry_side") or ""))
        if not bool(sig.get("ok", True)):
            out.append(
                {
                    "coin": coin,
                    "funding_rate": float(it.get("funding_rate") or 0.0),
                    "funding_rate_raw": (None if it.get("funding_rate_raw") is None else float(it.get("funding_rate_raw") or 0.0)),
                    "funding_est": (dict(it.get("funding_est")) if isinstance(it.get("funding_est"), dict) else None),
                    "basis_bps": float(it.get("basis_bps") or 0.0),
                    "carry_side": str(it.get("carry_side") or ""),
                    "expected_edge": float(it.get("carry_edge") or 0.0),
                    "atr_pct_5m": (None if atr_pct_5m is None else float(atr_pct_5m)),
                    "adx_5m": (None if adx_5m is None else float(adx_5m)),
                    "vol_usdc_5m": (None if vol_usdc_5m is None else float(vol_usdc_5m)),
                    "corr": {k: (None if v is None else float(v)) for k, v in corr_by_ref.items()},
                    "corr_max_abs": (None if corr_max_abs is None else float(corr_max_abs)),
                    "spread_bps": it.get("spread_bps"),
                    "liquidity_day_ntl": float(it.get("day_ntl") or 0.0),
                    "vetoed": True,
                    "veto_reason": "signal_filter",
                    "signal_tag": str(sig.get("tag") or ""),
                }
            )
            continue

        spike = {"ok": True, "tag": "disabled"}
        if bool(use_1m_filter):
            try:
                spike = _carry_1m_spike_gate(coin=coin, now_ms=int(now_ms))
            except Exception:
                spike = {"ok": True, "tag": "error"}
        if not bool(spike.get("ok", True)):
            out.append(
                {
                    "coin": coin,
                    "funding_rate": float(it.get("funding_rate") or 0.0),
                    "funding_rate_raw": (None if it.get("funding_rate_raw") is None else float(it.get("funding_rate_raw") or 0.0)),
                    "funding_est": (dict(it.get("funding_est")) if isinstance(it.get("funding_est"), dict) else None),
                    "basis_bps": float(it.get("basis_bps") or 0.0),
                    "carry_side": str(it.get("carry_side") or ""),
                    "expected_edge": float(it.get("carry_edge") or 0.0),
                    "atr_pct_5m": (None if atr_pct_5m is None else float(atr_pct_5m)),
                    "adx_5m": (None if adx_5m is None else float(adx_5m)),
                    "vol_usdc_5m": (None if vol_usdc_5m is None else float(vol_usdc_5m)),
                    "corr": {k: (None if v is None else float(v)) for k, v in corr_by_ref.items()},
                    "corr_max_abs": (None if corr_max_abs is None else float(corr_max_abs)),
                    "spread_bps": it.get("spread_bps"),
                    "liquidity_day_ntl": float(it.get("day_ntl") or 0.0),
                    "vetoed": True,
                    "veto_reason": "spike_1m",
                    "spike_1m": dict(spike),
                    "signal_tag": str(sig.get("tag") or ""),
                }
            )
            continue

        slope_pct = 0.0
        try:
            if rows5 and len(rows5) >= 16:
                c0 = float(rows5[-1][4])
                c1 = float(rows5[-15][4])
                if c1 > 0.0:
                    slope_pct = (c0 / c1) - 1.0
        except Exception:
            slope_pct = 0.0

        vetoed = False
        veto_reason: Optional[str] = None
        if atr_pct_5m is not None and float(max_atr_pct) > 0.0 and float(atr_pct_5m) > float(max_atr_pct):
            vetoed = True
            veto_reason = "atr_too_high"
        if (not vetoed) and liq_gate_enabled and float(min_vol_usdc_5m) > 0.0:
            if vol_usdc_5m is None or float(vol_usdc_5m) < float(min_vol_usdc_5m):
                vetoed = True
                veto_reason = "liq_low"
        if (not vetoed) and adx_5m is not None and float(adx_5m) >= float(veto_adx):
            fr = float(it.get("funding_rate") or 0.0)
            if (float(fr) > 0.0 and float(slope_pct) > 0.0) or (float(fr) < 0.0 and float(slope_pct) < 0.0):
                vetoed = True
                veto_reason = "trend_veto"
        if (not vetoed) and corr_gate_enabled and float(corr_thr) > 0.0 and corr_max_abs is not None and float(corr_max_abs) >= float(corr_thr):
            vetoed = True
            veto_reason = "corr_high"

        carry_edge = float(it.get("carry_edge") or 0.0)
        risk_penalty = 0.0
        if atr_pct_5m is not None:
            risk_penalty += float(risk_atr_mult) * float(atr_pct_5m)
        try:
            sp0 = it.get("spread_bps")
            sp = float(sp0) if sp0 is not None else 0.0
        except Exception:
            sp = 0.0
        if math.isfinite(float(sp)) and float(sp) > 0.0:
            risk_penalty += float(risk_spread_mult) * (float(sp) / 10_000.0)

        jump_rate = 0.0
        try:
            stats = _get_coin_stats_7d(coin)
            jump_rate = float(stats.get("jump_rate") or 0.0)
        except Exception:
            jump_rate = 0.0
        if math.isfinite(float(jump_rate)) and float(jump_rate) > 0.0:
            risk_penalty += float(risk_jump_mult) * float(jump_rate)

        risk_penalty += float(risk_basis_mult) * abs(float(it.get("basis_bps") or 0.0)) / 10_000.0
        expected_edge = float(carry_edge) - float(risk_penalty)

        if (not bool(vetoed)) and float(open_edge_thr) > 0.0 and float(expected_edge) < float(open_edge_thr):
            vetoed = True
            veto_reason = "edge_below_threshold"

        out.append(
            {
                "coin": coin,
                "funding_rate": float(it.get("funding_rate") or 0.0),
                "funding_rate_raw": (None if it.get("funding_rate_raw") is None else float(it.get("funding_rate_raw") or 0.0)),
                "funding_est": (dict(it.get("funding_est")) if isinstance(it.get("funding_est"), dict) else None),
                "basis_bps": float(it.get("basis_bps") or 0.0),
                "carry_side": str(it.get("carry_side") or ""),
                "carry_edge": float(carry_edge),
                "expected_edge": float(expected_edge),
                "atr_pct_5m": (None if atr_pct_5m is None else float(atr_pct_5m)),
                "adx_5m": (None if adx_5m is None else float(adx_5m)),
                "vol_usdc_5m": (None if vol_usdc_5m is None else float(vol_usdc_5m)),
                "corr": {k: (None if v is None else float(v)) for k, v in corr_by_ref.items()},
                "corr_max_abs": (None if corr_max_abs is None else float(corr_max_abs)),
                "spread_bps": it.get("spread_bps"),
                "liquidity_day_ntl": float(it.get("day_ntl") or 0.0),
                "jump_score": float(jump_rate),
                "risk_penalty": float(risk_penalty),
                "vetoed": bool(vetoed),
                "veto_reason": veto_reason,
                "signal_tag": str(sig.get("tag") or ""),
            }
        )

    out.sort(key=lambda x: float(x.get("expected_edge") or 0.0), reverse=True)
    return out[: max(1, int(n))]


def _carry_state_get() -> Dict[str, Any]:
    st = TRACKER_STATE.get("carry")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["carry"] = st
    return st


def _carry_cost_sample_add(now_ms: int, coin: str, bps: Optional[float], kind: str) -> None:
    if bps is None:
        return
    try:
        b = float(bps)
    except Exception:
        return
    if (not math.isfinite(float(b))) or float(b) <= 0.0:
        return
    st = _carry_state_get()
    samples = st.get("cost_samples")
    if not isinstance(samples, list):
        samples = []
        st["cost_samples"] = samples
    try:
        samples.append({"ts": int(now_ms), "coin": str(coin or "").strip().upper(), "bps": float(b), "kind": str(kind or "")})
    except Exception:
        return
    while len(samples) > 5000:
        try:
            samples.pop(0)
        except Exception:
            break


def _carry_funding_sample_add(now_ms: int, coin: str, funding_rate: Optional[float], kind: str) -> None:
    if funding_rate is None:
        return
    try:
        fr = float(funding_rate)
    except Exception:
        return
    if not math.isfinite(float(fr)):
        return
    st = _carry_state_get()
    samples = st.get("funding_samples")
    if not isinstance(samples, list):
        samples = []
        st["funding_samples"] = samples
    try:
        samples.append({"ts": int(now_ms), "coin": str(coin or "").strip().upper(), "funding_rate": float(fr), "kind": str(kind or "")})
    except Exception:
        return
    try:
        max_n = int(CONFIG.get("carry_trade_funding_samples_max", 20000) or 20000)
    except Exception:
        max_n = 20000
    max_n = max(1000, min(2_000_000, int(max_n)))
    while len(samples) > int(max_n):
        try:
            samples.pop(0)
        except Exception:
            break


def _carry_funding_estimate(now_ms: int, coin: str, cfg: Dict[str, Any]) -> Dict[str, Any]:
    st = _carry_state_get()
    samples = st.get("funding_samples")
    if not isinstance(samples, list) or not samples:
        return {"ok": False, "reason": "no_samples"}

    c = str(coin or "").strip().upper()
    if not c:
        return {"ok": False, "reason": "empty_coin"}

    try:
        lookback_h = float(cfg.get("carry_trade_funding_samples_lookback_hours", CONFIG.get("carry_trade_funding_samples_lookback_hours", 168)) or 168)
    except Exception:
        lookback_h = 168.0
    lookback_h = float(_clip(float(lookback_h), 1.0, 24.0 * 60.0))
    prune_before_ms = int(now_ms) - int(round(float(lookback_h) * 3600.0 * 1000.0))

    while samples:
        it0 = samples[0]
        if not isinstance(it0, dict):
            try:
                samples.pop(0)
            except Exception:
                break
            continue
        try:
            ts0 = int(it0.get("ts") or 0)
        except Exception:
            ts0 = 0
        if ts0 > 0 and ts0 < int(prune_before_ms):
            try:
                samples.pop(0)
            except Exception:
                break
            continue
        break

    try:
        win_h = float(cfg.get("carry_trade_funding_est_window_hours", CONFIG.get("carry_trade_funding_est_window_hours", 48)) or 48)
    except Exception:
        win_h = 48.0
    win_h = float(_clip(float(win_h), 1.0, 24.0 * 30.0))
    since_ms = int(now_ms) - int(round(float(win_h) * 3600.0 * 1000.0))

    vals: List[float] = []
    for it in reversed(samples):
        if not isinstance(it, dict):
            continue
        if str(it.get("coin") or "").strip().upper() != str(c):
            continue
        try:
            ts = int(it.get("ts") or 0)
        except Exception:
            ts = 0
        if ts > 0 and ts < int(since_ms):
            break
        try:
            fr = float(it.get("funding_rate") or 0.0)
        except Exception:
            continue
        if math.isfinite(float(fr)):
            vals.append(float(fr))

    try:
        min_samples = int(cfg.get("carry_trade_funding_est_min_samples", CONFIG.get("carry_trade_funding_est_min_samples", 6)) or 6)
    except Exception:
        min_samples = 6
    min_samples = max(1, min(2000, int(min_samples)))
    if len(vals) < int(min_samples):
        return {"ok": False, "reason": "insufficient_samples", "n": int(len(vals)), "min": int(min_samples)}

    try:
        est_kind = str(cfg.get("carry_trade_funding_estimator", CONFIG.get("carry_trade_funding_estimator", "mean")) or "mean").strip().lower() or "mean"
    except Exception:
        est_kind = "mean"

    est = None
    if est_kind == "median":
        vals2 = list(vals)
        vals2.sort()
        mid = int(len(vals2) // 2)
        if len(vals2) % 2 == 1:
            est = float(vals2[mid])
        else:
            est = 0.5 * (float(vals2[mid - 1]) + float(vals2[mid]))
    elif est_kind in ("p25", "q25"):
        vals2 = list(vals)
        vals2.sort()
        idx = int(math.ceil(0.25 * float(len(vals2)))) - 1
        idx = max(0, min(len(vals2) - 1, int(idx)))
        est = float(vals2[idx])
    elif est_kind in ("p75", "q75"):
        vals2 = list(vals)
        vals2.sort()
        idx = int(math.ceil(0.75 * float(len(vals2)))) - 1
        idx = max(0, min(len(vals2) - 1, int(idx)))
        est = float(vals2[idx])
    else:
        try:
            est = float(sum(vals)) / float(len(vals))
        except Exception:
            est = None

    if est is None or (not math.isfinite(float(est))):
        return {"ok": False, "reason": "bad_est"}
    return {"ok": True, "coin": str(c), "est": float(est), "n": int(len(vals)), "window_h": float(win_h), "estimator": str(est_kind)}


def _carry_cost_buffer_p95_bps(now_ms: int, cfg: Dict[str, Any]) -> Optional[float]:
    st = _carry_state_get()
    samples = st.get("cost_samples")
    if not isinstance(samples, list) or not samples:
        return None
    try:
        lookback_h = float(cfg.get("carry_trade_cost_buffer_p95_lookback_hours", CONFIG.get("carry_trade_cost_buffer_p95_lookback_hours", 72)) or 72)
    except Exception:
        lookback_h = 72.0
    lookback_h = float(_clip(float(lookback_h), 0.0, 24.0 * 30.0))
    since_ms = int(now_ms) - int(round(float(lookback_h) * 3600.0 * 1000.0))
    try:
        lookback_n = int(cfg.get("carry_trade_cost_buffer_p95_lookback_n", CONFIG.get("carry_trade_cost_buffer_p95_lookback_n", 300)) or 300)
    except Exception:
        lookback_n = 300
    lookback_n = max(1, min(5000, int(lookback_n)))
    vals: List[float] = []
    for it in reversed(samples):
        if len(vals) >= int(lookback_n):
            break
        if not isinstance(it, dict):
            continue
        try:
            ts = int(it.get("ts") or 0)
        except Exception:
            ts = 0
        if ts > 0 and ts < int(since_ms):
            break
        try:
            bps = float(it.get("bps") or 0.0)
        except Exception:
            continue
        if math.isfinite(float(bps)) and float(bps) > 0.0:
            vals.append(float(bps))
    if not vals:
        return None
    try:
        min_samples = int(cfg.get("carry_trade_cost_buffer_p95_min_samples", CONFIG.get("carry_trade_cost_buffer_p95_min_samples", 20)) or 20)
    except Exception:
        min_samples = 20
    if len(vals) < int(max(1, min(2000, int(min_samples)))):
        return None
    vals.sort()
    idx = int(math.ceil(0.95 * float(len(vals)))) - 1
    idx = max(0, min(len(vals) - 1, int(idx)))
    return float(vals[idx])


def _carry_basis_bps_now_hl(coin: str, now_ms: int) -> Optional[float]:
    c = str(coin or "").strip().upper()
    if not c:
        return None
    ctx = None
    try:
        ctx = _hl_meta_and_asset_ctxs_cached(int(now_ms)).get(c)
    except Exception:
        ctx = None
    if not isinstance(ctx, dict):
        return None
    try:
        mark_px = float(_to_float(ctx.get("markPx"), 0.0))
        oracle_px = float(_to_float(ctx.get("oraclePx"), 0.0))
        prem = float(_to_float(ctx.get("premium"), 0.0))
    except Exception:
        return None
    if mark_px > 0.0 and oracle_px > 0.0:
        return float((mark_px / oracle_px - 1.0) * 10_000.0)
    if prem != 0.0:
        return float(prem) * 10_000.0
    return 0.0


def _carry_post_funding_trailing_step(now_ms: int, p: Dict[str, Any], cfg: Dict[str, Any], venue: str) -> Tuple[bool, str]:
    coin = str(p.get("coin") or "").strip().upper()
    if not coin:
        return False, "post_funding_exit"

    try:
        enabled = bool(cfg.get("carry_trade_post_funding_trailing_enabled", CONFIG.get("carry_trade_post_funding_trailing_enabled", False)))
    except Exception:
        enabled = False
    if not bool(enabled):
        return False, "post_funding_exit"
    if str(venue or "").strip().lower() not in ("hyperliquid", "hl"):
        return False, "post_funding_exit"

    try:
        max_hold_min = float(cfg.get("carry_trade_post_funding_trailing_max_hold_min", CONFIG.get("carry_trade_post_funding_trailing_max_hold_min", 3)) or 3)
    except Exception:
        max_hold_min = 3.0
    max_hold_min = float(_clip(float(max_hold_min), 0.0, 60.0))
    max_hold_ms = int(round(float(max_hold_min) * 60_000.0))

    try:
        arm_min_r = float(cfg.get("carry_trade_post_funding_trailing_arm_min_r", CONFIG.get("carry_trade_post_funding_trailing_arm_min_r", 0.001)) or 0.001)
    except Exception:
        arm_min_r = 0.001
    arm_min_r = float(_clip(float(arm_min_r), 0.0, 0.20))
    try:
        dist_r = float(cfg.get("carry_trade_post_funding_trailing_dist_r", CONFIG.get("carry_trade_post_funding_trailing_dist_r", 0.003)) or 0.003)
    except Exception:
        dist_r = 0.003
    dist_r = float(_clip(float(dist_r), 0.0, 0.50))

    start_ts = 0
    try:
        start_ts = int(p.get("post_funding_start_ts") or 0)
    except Exception:
        start_ts = 0
    if start_ts <= 0:
        start_ts = int(now_ms)
        p["post_funding_start_ts"] = int(start_ts)

    if max_hold_ms > 0 and (int(now_ms) - int(start_ts)) >= int(max_hold_ms):
        return False, "post_funding_max_hold"

    pnl_pct = None
    try:
        pnl_pct = float(p.get("unrealized_pnl_pct")) if p.get("unrealized_pnl_pct") is not None else None
    except Exception:
        pnl_pct = None
    if pnl_pct is None or (not math.isfinite(float(pnl_pct))):
        return False, "post_funding_exit"

    best = None
    try:
        best = float(p.get("post_funding_best_pnl_pct")) if p.get("post_funding_best_pnl_pct") is not None else None
    except Exception:
        best = None
    if best is None or (not math.isfinite(float(best))):
        best = float(pnl_pct)
    best = float(max(float(best), float(pnl_pct)))
    p["post_funding_best_pnl_pct"] = float(best)

    try:
        require_basis = bool(cfg.get("carry_trade_post_funding_require_basis_reversion", CONFIG.get("carry_trade_post_funding_require_basis_reversion", True)))
    except Exception:
        require_basis = True
    if bool(require_basis):
        basis_entry = None
        try:
            cand = p.get("candidate")
            if isinstance(cand, dict):
                basis_entry = cand.get("basis_bps")
        except Exception:
            basis_entry = None
        try:
            basis_now = _carry_basis_bps_now_hl(str(coin), int(now_ms))
        except Exception:
            basis_now = None
        if basis_entry is None or basis_now is None or (not math.isfinite(float(basis_entry))) or (not math.isfinite(float(basis_now))):
            return False, "post_funding_exit"
        try:
            mult = float(cfg.get("carry_trade_post_funding_basis_reversion_mult", CONFIG.get("carry_trade_post_funding_basis_reversion_mult", 0.85)) or 0.85)
        except Exception:
            mult = 0.85
        mult = float(_clip(float(mult), 0.0, 2.0))
        if abs(float(basis_now)) > abs(float(basis_entry)) * float(mult):
            return False, "post_funding_exit"

    spread_bps = _carry_hl_spread_bps_quick(coin=str(coin), now_ms=int(now_ms))
    try:
        max_spread_bps = float(cfg.get("carry_trade_max_spread_bps", CONFIG.get("carry_trade_max_spread_bps", 15)) or 15)
    except Exception:
        max_spread_bps = 15.0
    if spread_bps is not None and math.isfinite(float(spread_bps)) and float(max_spread_bps) > 0.0 and float(spread_bps) > float(max_spread_bps):
        return False, "post_funding_exit"

    try:
        use_1m_filter = bool(cfg.get("carry_trade_use_1m_filter", CONFIG.get("carry_trade_use_1m_filter", True)))
    except Exception:
        use_1m_filter = True
    if bool(use_1m_filter):
        try:
            sg = _carry_1m_spike_gate(str(coin), int(now_ms))
        except Exception:
            sg = {"ok": True}
        if not bool(sg.get("ok", True)):
            return False, "post_funding_exit"

    if float(best) >= float(arm_min_r) and float(dist_r) > 0.0 and (float(best) - float(pnl_pct)) >= float(dist_r):
        return False, "post_funding_trailing"

    return True, "hold"


def _carry_positions_get() -> Dict[str, Dict[str, Any]]:
    pos = TRACKER_STATE.get("carry_positions")
    if not isinstance(pos, dict):
        pos = {}
        TRACKER_STATE["carry_positions"] = pos
    out: Dict[str, Dict[str, Any]] = {}
    for k, v in pos.items():
        if isinstance(v, dict):
            out[str(k)] = v
    if out is not pos:
        TRACKER_STATE["carry_positions"] = out
    return out


def _carry_mid_px(coin: str, venue: str) -> Optional[float]:
    c = str(coin or "").strip().upper()
    if not c:
        return None
    v = str(venue or "").strip().lower()
    try:
        px = float(_hl_mid(c))
        return px if math.isfinite(px) and px > 0.0 else None
    except Exception:
        return None
    return None


def _carry_execute_allowed(venue: str) -> bool:
    try:
        if not bool(_carry_live_trading_enabled()):
            return False
    except Exception:
        return False
    v = str(venue or "").strip().lower()
    if v not in ("hyperliquid", "hl"):
        v = "hyperliquid"
    try:
        return bool(_hl_enabled_for_trading_for_owner("carry"))
    except Exception:
        return False


def _carry_live_trading_enabled() -> bool:
    base = bool(CONFIG.get("live_trading_enabled", False)) and (not bool(CONFIG.get("dry_run", True)))
    if not bool(base):
        return False
    return bool(_cfg_inherit_bool(CONFIG.get("carry_trade_live_enabled"), bool(base)))


def _carry_should_open_window(now_ms: int, next_ts: int, cfg: Dict[str, Any]) -> Tuple[bool, str]:
    if int(next_ts or 0) <= 0:
        return False, "no_schedule"
    try:
        pre = float(cfg.get("carry_trade_pre_funding_window_min", CONFIG.get("carry_trade_pre_funding_window_min", 5)) or 5)
    except Exception:
        pre = 5.0
    pre = float(_clip(float(pre), 0.0, 24.0 * 60.0))
    m = float(int(next_ts) - int(now_ms)) / 60_000.0
    if m <= 0.0:
        return False, "after_funding"
    if m > float(pre):
        return False, "wait"
    return True, "pre_funding"


def _carry_in_no_exit_window(now_ms: int, next_ts: int, cfg: Dict[str, Any]) -> bool:
    if int(next_ts or 0) <= 0:
        return False
    try:
        no_exit = float(cfg.get("carry_trade_no_exit_pre_funding_min", CONFIG.get("carry_trade_no_exit_pre_funding_min", 5)) or 5)
    except Exception:
        no_exit = 5.0
    no_exit = float(_clip(float(no_exit), 0.0, 60.0))
    m = float(int(next_ts) - int(now_ms)) / 60_000.0
    return (m > 0.0) and (m <= float(no_exit))


def _carry_trade_tick_hedge(
    now_ms: int,
    state: Dict[str, Any],
    venue: str,
    eff: Dict[str, Any],
    cfg_eff: Dict[str, Any],
    gate: Dict[str, Any],
    enabled_effective: bool,
    sandbox: bool,
    execute: bool,
) -> Dict[str, Any]:
    now_ms = int(now_ms)
    venue = str(venue or "").strip().lower() or "hyperliquid"

    clk = _carry_funding_clock(int(now_ms), str(venue))
    try:
        next_ts = int(clk.get("next_ts") or 0)
    except Exception:
        next_ts = 0
    try:
        last_ts = int(clk.get("last_ts") or 0)
    except Exception:
        last_ts = 0

    minutes_to_next = 0.0
    try:
        if int(next_ts) > 0:
            minutes_to_next = float(int(next_ts) - int(now_ms)) / 60_000.0
    except Exception:
        minutes_to_next = 0.0
    window_state = _carry_window_state(float(minutes_to_next))
    state["window_state"] = str(window_state)

    try:
        post_grace = float(cfg_eff.get("carry_trade_post_funding_grace_min", CONFIG.get("carry_trade_post_funding_grace_min", 1)) or 1)
    except Exception:
        post_grace = 1.0
    post_grace = float(_clip(float(post_grace), 0.0, 10.0))
    post_grace_ms = int(round(float(post_grace) * 60_000.0))

    try:
        cooldown_min = float(cfg_eff.get("carry_trade_cooldown_min", CONFIG.get("carry_trade_cooldown_min", 10)) or 10)
    except Exception:
        cooldown_min = 10.0
    cooldown_min = float(_clip(float(cooldown_min), 0.0, 10_000.0))
    cooldown_ms = int(round(float(cooldown_min) * 60_000.0))

    cb_enabled = bool(cfg_eff.get("carry_trade_hedge_circuit_breaker_enabled", CONFIG.get("carry_trade_hedge_circuit_breaker_enabled", False)))
    try:
        cb_ret_1m_min_r = float(cfg_eff.get("carry_trade_hedge_cb_ret_1m_min_r", CONFIG.get("carry_trade_hedge_cb_ret_1m_min_r", 0.015)) or 0.015)
    except Exception:
        cb_ret_1m_min_r = 0.015
    cb_ret_1m_min_r = float(_clip(float(cb_ret_1m_min_r), 0.0, 0.50))
    try:
        cb_ret_5m_atr_mult = float(cfg_eff.get("carry_trade_hedge_cb_ret_5m_atr_mult", CONFIG.get("carry_trade_hedge_cb_ret_5m_atr_mult", 2.5)) or 2.5)
    except Exception:
        cb_ret_5m_atr_mult = 2.5
    cb_ret_5m_atr_mult = float(_clip(float(cb_ret_5m_atr_mult), 0.0, 50.0))
    try:
        cb_spread_bps_thr = float(cfg_eff.get("carry_trade_hedge_cb_spread_bps", CONFIG.get("carry_trade_hedge_cb_spread_bps", 35)) or 35)
    except Exception:
        cb_spread_bps_thr = 35.0
    cb_spread_bps_thr = float(_clip(float(cb_spread_bps_thr), 0.0, 5000.0))
    try:
        cb_cooldown_min = float(cfg_eff.get("carry_trade_hedge_cb_cooldown_min", CONFIG.get("carry_trade_hedge_cb_cooldown_min", 60)) or 60)
    except Exception:
        cb_cooldown_min = 60.0
    cb_cooldown_min = float(_clip(float(cb_cooldown_min), 0.0, 10_000.0))
    cb_cooldown_ms = int(round(float(cb_cooldown_min) * 60_000.0))

    try:
        emergency_r = float(cfg_eff.get("carry_trade_emergency_stoploss_r", CONFIG.get("carry_trade_emergency_stoploss_r", -0.015)) or -0.015)
    except Exception:
        emergency_r = -0.015
    if not math.isfinite(float(emergency_r)):
        emergency_r = -0.015

    dyn_emergency_enabled = bool(cfg_eff.get("carry_trade_emergency_stoploss_dynamic_enabled", CONFIG.get("carry_trade_emergency_stoploss_dynamic_enabled", True)))
    try:
        dyn_emergency_mult = float(cfg_eff.get("carry_trade_emergency_stoploss_atr_mult", CONFIG.get("carry_trade_emergency_stoploss_atr_mult", 2.0)) or 2.0)
    except Exception:
        dyn_emergency_mult = 2.0
    dyn_emergency_mult = float(_clip(float(dyn_emergency_mult), 0.1, 20.0))
    try:
        dyn_emergency_min_r = float(cfg_eff.get("carry_trade_emergency_stoploss_min_r", CONFIG.get("carry_trade_emergency_stoploss_min_r", -0.08)) or -0.08)
    except Exception:
        dyn_emergency_min_r = -0.08
    try:
        dyn_emergency_max_r = float(cfg_eff.get("carry_trade_emergency_stoploss_max_r", CONFIG.get("carry_trade_emergency_stoploss_max_r", -0.008)) or -0.008)
    except Exception:
        dyn_emergency_max_r = -0.008
    if dyn_emergency_min_r > dyn_emergency_max_r:
        dyn_emergency_min_r, dyn_emergency_max_r = dyn_emergency_max_r, dyn_emergency_min_r

    pool_refresh_s = None
    try:
        pool_refresh_s = float(cfg_eff.get("carry_trade_pool_refresh_seconds", CONFIG.get("carry_trade_pool_refresh_seconds", 900)) or 900)
    except Exception:
        pool_refresh_s = 900.0
    pool_refresh_s = float(_clip(float(pool_refresh_s), 5.0, 3600.0))

    pos = _carry_positions_get()

    if execute or any((isinstance(v, dict) and str(v.get("venue") or "").lower() == str(venue)) for v in pos.values()):
        try:
            last_sync_ts = 0
            try:
                h_st = TRACKER_STATE.get("hl")
                if isinstance(h_st, dict):
                    last_sync_ts = int(h_st.get("last_sync_ts") or 0)
            except Exception:
                last_sync_ts = 0
            if last_sync_ts <= 0 or (int(now_ms) - int(last_sync_ts)) >= 10_000:

                def _bg_sync_hl():
                    with app.app_context():
                        try:
                            _hl_sync_record(update_orders=False, trigger="carry.status.refresh", trace_id=None)
                        except Exception:
                            pass

                threading.Thread(target=_bg_sync_hl, daemon=True).start()
        except Exception:
            pass

    open_pos = (TRACKER_STATE.get("carry_open_positions") or {})
    if not isinstance(open_pos, dict):
        open_pos = {}

    events = state.get("events")
    if not isinstance(events, list):
        events = []
        state["events"] = events
    while len(events) > 200:
        try:
            events.pop(0)
        except Exception:
            break

    def _ev(kind: str, payload: Dict[str, Any]):
        try:
            base = {
                "ts": int(now_ms),
                "kind": str(kind),
                "strategy_id": "carry_trade",
                "strategy_version": "1.0.0",
                "group_id": f"carry_{str(venue)}",
                "feature_set_id": "carry_v1",
            }
            base.update(dict(payload or {}))
            events.append(base)
        except Exception:
            pass

    ohlcv_fetch = _carry_hl_fetch_ohlcv_rows_quick

    try:
        state["step"] = "universe_refresh"
        state["step_ts"] = int(now_ms)
    except Exception:
        pass
    try:
        _carry_universe_refresh(int(now_ms), dict(cfg_eff))
    except Exception as e:
        try:
            state["last_error"] = {"ts": int(now_ms), "error": str(e)}
        except Exception:
            pass
        try:
            state["step"] = "universe_refresh_error"
            state["step_ts"] = int(now_ms)
        except Exception:
            pass

    pool_ts = None
    try:
        pool_ts = int(state.get("pool_ts") or 0)
    except Exception:
        pool_ts = 0
    pool_age_ms = int(now_ms) - int(pool_ts)
    pool = state.get("pool")
    if not isinstance(pool, list):
        pool = []
    if pool_ts <= 0 or pool_age_ms >= int(pool_refresh_s * 1000.0):
        try:
            state["step"] = "pool_refresh"
            state["step_ts"] = int(now_ms)
        except Exception:
            pass
        try:
            n_pool = int(cfg_eff.get("carry_trade_candidates_top_n", CONFIG.get("carry_trade_candidates_top_n", 10)) or 10)
        except Exception:
            n_pool = 10
        n_pool = max(1, min(200, int(n_pool)))
        try:
            pool = _carry_candidates_hl(int(now_ms), int(n_pool), cfg=dict(cfg_eff))
        except Exception as e:
            pool = []
            try:
                state["last_error"] = {"ts": int(now_ms), "error": str(e)}
            except Exception:
                pass
            try:
                state["pool_last_error"] = {"ts": int(now_ms), "error": str(e)}
            except Exception:
                pass
            try:
                state["step"] = "pool_refresh_error"
                state["step_ts"] = int(now_ms)
            except Exception:
                pass
        state["pool"] = pool
        state["pool_ts"] = int(now_ms)
        try:
            last_err = (HL_META_ASSET_CTX_CACHE.get("last_error") if isinstance(HL_META_ASSET_CTX_CACHE, dict) else None)
        except Exception:
            last_err = None
        try:
            if (not isinstance(pool, list) or len(pool) == 0) and last_err is not None:
                state["pool_last_error"] = (dict(last_err) if isinstance(last_err, dict) else {"ts": int(now_ms), "error": str(last_err)})
            elif isinstance(pool, list) and len(pool) > 0:
                state["pool_last_error"] = None
        except Exception:
            pass

    for pair, p in list(pos.items()):
        if not isinstance(p, dict):
            continue
        if str(p.get("venue") or "").strip().lower() != str(venue):
            continue
        if str(p.get("mode") or "").strip().lower() != "hedge":
            continue
        coin = str(p.get("coin") or "").strip().upper()
        if not coin:
            continue

        st_prev = str(p.get("status") or "").strip().lower()

        mid = _carry_mid_px(str(coin), str(venue))
        if mid is not None:
            try:
                p["last_mid"] = float(mid)
            except Exception:
                pass
        pnl_pct = None
        try:
            pnl_pct = float(p.get("unrealized_pnl_pct")) if p.get("unrealized_pnl_pct") is not None else None
        except Exception:
            pnl_pct = None
        if bool(p.get("execute", False)):
            if str(pair) in open_pos and isinstance(open_pos.get(pair), dict):
                try:
                    p["unrealized_pnl_pct"] = float(open_pos[pair].get("unrealized_pnl_pct") or 0.0)
                except Exception:
                    pass
                p["is_open"] = True
            else:
                st0 = str(p.get("status") or "").strip().lower()
                if st0 in ("closing", "open", "opened", "paper_opened"):
                    p["is_open"] = False
                    p["status"] = "closed"
                    p["closed_ts"] = int(now_ms)
                    p["close_reason"] = "perp_closed_detected"
                    try:
                        if coin:
                            state.setdefault("cooldown_by_coin", {})
                            cd = state.get("cooldown_by_coin")
                            if isinstance(cd, dict):
                                cd[str(coin).upper()] = int(now_ms) + int(cooldown_ms)
                    except Exception:
                        pass
        else:
            if mid is not None:
                try:
                    entry_mid = float(p.get("entry_mid") or 0.0)
                    if entry_mid > 0.0:
                        r = (float(mid) / float(entry_mid) - 1.0)
                        r = -float(r)
                        p["unrealized_pnl_pct"] = float(r)
                except Exception:
                    pass

        spot_entry_mid = None
        try:
            spot_entry_mid = float(((p.get("spot") or {}) if isinstance(p.get("spot"), dict) else {}).get("entry_mid") or 0.0)
        except Exception:
            spot_entry_mid = None
        if mid is not None and spot_entry_mid is not None and math.isfinite(float(spot_entry_mid)) and float(spot_entry_mid) > 0.0:
            try:
                p["spot_pnl_pct"] = float(float(mid) / float(spot_entry_mid) - 1.0)
            except Exception:
                pass

        meta0 = None
        try:
            meta0 = open_pos.get(str(pair)) if isinstance(open_pos, dict) else None
        except Exception:
            meta0 = None
        perp_u = None
        perp_qty = None
        perp_liq_px = None
        if isinstance(meta0, dict):
            try:
                perp_u = float(
                    _to_float(
                        meta0.get(
                            "hl_unrealized_pnl_u",
                            meta0.get(
                                "aster_unrealized_pnl_u",
                                meta0.get("unrealized_pnl_u", 0.0),
                            ),
                        ),
                        0.0,
                    )
                )
            except Exception:
                perp_u = None
            try:
                perp_qty = abs(
                    float(
                        _to_float(
                            meta0.get(
                                "hl_szi",
                                meta0.get(
                                    "aster_position_amt",
                                    meta0.get(
                                        "position_amt",
                                        meta0.get("base_qty", 0.0),
                                    ),
                                ),
                            ),
                            0.0,
                        )
                    )
                )
            except Exception:
                perp_qty = None
            try:
                perp_liq_px = float(
                    _to_float(
                        meta0.get(
                            "hl_liquidation_px",
                            meta0.get(
                                "hl_liq_px",
                                meta0.get(
                                    "liq_px",
                                    meta0.get(
                                        "liquidation_px",
                                        meta0.get("aster_liquidation_px", 0.0),
                                    ),
                                ),
                            ),
                        ),
                        0.0,
                    )
                )
            except Exception:
                perp_liq_px = None
        if perp_u is not None and math.isfinite(float(perp_u)):
            try:
                p["perp_unrealized_pnl_usdc"] = float(perp_u)
            except Exception:
                pass
        if perp_qty is not None and math.isfinite(float(perp_qty)):
            try:
                p["perp_base_qty"] = float(perp_qty)
            except Exception:
                pass
        if perp_liq_px is not None and math.isfinite(float(perp_liq_px)) and float(perp_liq_px) > 0.0:
            try:
                p["perp_liquidation_px"] = float(perp_liq_px)
            except Exception:
                pass

        spot_qty0 = None
        try:
            spot_qty0 = float(((p.get("spot") or {}) if isinstance(p.get("spot"), dict) else {}).get("qty") or 0.0)
        except Exception:
            spot_qty0 = None
        if spot_qty0 is None or (not math.isfinite(float(spot_qty0))) or abs(float(spot_qty0)) <= 0.0:
            if mid is not None:
                try:
                    ntl0 = float(p.get("notional_usdc") or 0.0)
                except Exception:
                    ntl0 = 0.0
                if math.isfinite(float(ntl0)) and float(ntl0) > 0.0 and math.isfinite(float(mid)) and float(mid) > 0.0:
                    spot_qty0 = float(ntl0) / float(mid)

        spot_pnl_u = None
        if spot_qty0 is not None and mid is not None and spot_entry_mid is not None:
            try:
                if math.isfinite(float(spot_qty0)) and math.isfinite(float(mid)) and math.isfinite(float(spot_entry_mid)) and float(mid) > 0.0 and float(spot_entry_mid) > 0.0:
                    spot_pnl_u = float(spot_qty0) * (float(mid) - float(spot_entry_mid))
            except Exception:
                spot_pnl_u = None
        if spot_pnl_u is not None and math.isfinite(float(spot_pnl_u)):
            try:
                p["spot_pnl_usdc_est"] = float(spot_pnl_u)
            except Exception:
                pass
        try:
            ntl = float(p.get("notional_usdc") or 0.0)
        except Exception:
            ntl = 0.0
        try:
            perp_p = float(p.get("unrealized_pnl_pct") or 0.0)
        except Exception:
            perp_p = 0.0
        try:
            spot_p = float(p.get("spot_pnl_pct") or 0.0)
        except Exception:
            spot_p = 0.0
        if math.isfinite(float(ntl)) and float(ntl) > 0.0 and math.isfinite(float(perp_p)) and math.isfinite(float(spot_p)):
            try:
                p["net_pnl_usdc_est"] = float(ntl) * (float(perp_p) + float(spot_p))
            except Exception:
                pass

        net_u0 = None
        try:
            net_u0 = float(p.get("net_pnl_usdc_est")) if p.get("net_pnl_usdc_est") is not None else None
        except Exception:
            net_u0 = None
        if net_u0 is not None and math.isfinite(float(net_u0)):
            peak0 = None
            try:
                peak0 = float(p.get("net_pnl_peak_usdc_est")) if p.get("net_pnl_peak_usdc_est") is not None else None
            except Exception:
                peak0 = None
            if peak0 is None or (not math.isfinite(float(peak0))):
                peak0 = float(net_u0)
            peak0 = float(max(float(peak0), float(net_u0)))
            try:
                p["net_pnl_peak_usdc_est"] = float(peak0)
            except Exception:
                pass
            dd0 = float(peak0) - float(net_u0)
            if math.isfinite(float(dd0)) and float(dd0) >= 0.0:
                maxdd0 = None
                try:
                    maxdd0 = float(p.get("max_drawdown_usdc_est")) if p.get("max_drawdown_usdc_est") is not None else None
                except Exception:
                    maxdd0 = None
                if maxdd0 is None or (not math.isfinite(float(maxdd0))):
                    maxdd0 = float(dd0)
                maxdd0 = float(max(float(maxdd0), float(dd0)))
                try:
                    p["max_drawdown_usdc_est"] = float(maxdd0)
                except Exception:
                    pass
                try:
                    ntl2 = float(p.get("notional_usdc") or 0.0)
                except Exception:
                    ntl2 = 0.0
                if math.isfinite(float(ntl2)) and float(ntl2) > 0.0:
                    try:
                        p["max_drawdown_pct"] = float(maxdd0) / float(ntl2)
                    except Exception:
                        pass

        fr0 = None
        try:
            cand0 = p.get("candidate")
            if isinstance(cand0, dict) and cand0.get("funding_rate") is not None:
                fr0 = float(cand0.get("funding_rate"))
        except Exception:
            fr0 = None
        if fr0 is None:
            try:
                am0 = p.get("active_metrics")
                if isinstance(am0, dict) and am0.get("funding_rate") is not None:
                    fr0 = float(am0.get("funding_rate"))
            except Exception:
                fr0 = None

        if fr0 is not None and math.isfinite(float(fr0)) and math.isfinite(float(ntl)) and float(ntl) > 0.0:
            try:
                side0 = str(p.get("side") or "short").strip().lower()
            except Exception:
                side0 = "short"
            sign = 1.0 if str(side0) == "short" else -1.0
            try:
                p["funding_pnl_next_usdc_est"] = float(ntl) * float(sign) * float(fr0)
            except Exception:
                pass

        price_u = None
        try:
            a = 0.0
            ok0 = True
            if perp_u is None or (not math.isfinite(float(perp_u))):
                ok0 = False
            else:
                a += float(perp_u)
            if spot_pnl_u is None or (not math.isfinite(float(spot_pnl_u))):
                ok0 = False
            else:
                a += float(spot_pnl_u)
            if ok0:
                price_u = float(a)
        except Exception:
            price_u = None
        if price_u is not None and math.isfinite(float(price_u)):
            try:
                p["price_move_pnl_usdc_est"] = float(price_u)
            except Exception:
                pass

        liq_warn_thr = None
        try:
            liq_warn_thr = float(
                cfg_eff.get(
                    "carry_trade_liq_warn_buffer_pct",
                    CONFIG.get("carry_trade_liq_warn_buffer_pct", CONFIG.get("exit_l0_liq_buffer_pct", 0.02)),
                )
                or 0.02
            )
        except Exception:
            liq_warn_thr = None
        if liq_warn_thr is not None and math.isfinite(float(liq_warn_thr)):
            liq_warn_thr = float(_clip(float(liq_warn_thr), 0.0, 0.5))
        else:
            liq_warn_thr = None
        if liq_warn_thr is not None:
            liq_px0 = None
            try:
                liq_px0 = float(p.get("perp_liquidation_px")) if p.get("perp_liquidation_px") is not None else None
            except Exception:
                liq_px0 = None
            mid0 = None
            try:
                mid0 = float(p.get("last_mid")) if p.get("last_mid") is not None else None
            except Exception:
                mid0 = None
            if liq_px0 is not None and mid0 is not None and math.isfinite(float(liq_px0)) and math.isfinite(float(mid0)) and float(liq_px0) > 0.0 and float(mid0) > 0.0:
                try:
                    side0 = str(p.get("side") or "short").strip().lower()
                except Exception:
                    side0 = "short"
                buf = None
                try:
                    if side0 == "short":
                        buf = float(liq_px0) / float(mid0) - 1.0
                    else:
                        buf = float(mid0) / float(liq_px0) - 1.0
                except Exception:
                    buf = None
                if buf is not None and math.isfinite(float(buf)):
                    try:
                        p["liq_buffer_pct"] = float(buf)
                    except Exception:
                        pass
                    warn_now = bool(float(buf) <= float(liq_warn_thr))
                    warn_prev = bool(p.get("liq_warn_active", False))
                    if warn_now and (not warn_prev):
                        try:
                            p["liq_warn_count"] = int(p.get("liq_warn_count") or 0) + 1
                        except Exception:
                            p["liq_warn_count"] = 1
                        try:
                            p["last_liq_warn_ts"] = int(now_ms)
                        except Exception:
                            pass
                    p["liq_warn_active"] = bool(warn_now)

        st_now = str(p.get("status") or "").strip().lower()
        if st_prev in ("open", "opened", "paper_opened", "closing") and st_now == "closed" and (not bool(p.get("history_recorded", False))):
            try:
                entry_ts0 = int(p.get("entry_ts") or 0)
            except Exception:
                entry_ts0 = 0
            try:
                close_ts0 = int(p.get("closed_ts") or 0)
            except Exception:
                close_ts0 = 0
            rec = {
                "venue": str(venue),
                "pair": str(pair),
                "coin": str(coin),
                "entry_ts": int(entry_ts0),
                "close_ts": int(close_ts0 if close_ts0 > 0 else now_ms),
                "notional_usdc": float(_to_float(p.get("notional_usdc"), 0.0)),
                "price_move_pnl_usdc_est": float(_to_float(p.get("price_move_pnl_usdc_est"), 0.0)),
                "max_drawdown_usdc_est": float(_to_float(p.get("max_drawdown_usdc_est"), 0.0)),
                "max_drawdown_pct": _to_float(p.get("max_drawdown_pct"), None),
                "liq_warn_count": int(_to_float(p.get("liq_warn_count"), 0.0)),
                "close_reason": str(p.get("close_reason") or ""),
            }
            h = _carry_trade_history_get()
            h.append(rec)
            if len(h) > 5000:
                del h[: max(0, len(h) - 5000)]
            p["history_recorded"] = True
        pos[pair] = p

    to_unhedge: List[Tuple[str, Dict[str, Any], str, str]] = []
    to_spot_exit: List[Tuple[str, Dict[str, Any], str]] = []
    to_perp_exit: List[Tuple[str, Dict[str, Any], str]] = []
    to_close_both: List[Tuple[str, Dict[str, Any], str]] = []

    try:
        min_hold_min = float(cfg_eff.get("carry_trade_hedge_min_hold_min", CONFIG.get("carry_trade_hedge_min_hold_min", 4320)) or 4320)
    except Exception:
        min_hold_min = 4320.0
    min_hold_min = float(_clip(float(min_hold_min), 0.0, 10_000.0))
    min_hold_ms = int(round(float(min_hold_min) * 60_000.0))
    unhedge_enabled = bool(cfg_eff.get("carry_trade_hedge_unhedge_enabled", CONFIG.get("carry_trade_hedge_unhedge_enabled", True)))
    try:
        trig_score_thr = float(cfg_eff.get("carry_trade_hedge_unhedge_trigger_score", CONFIG.get("carry_trade_hedge_unhedge_trigger_score", 0.80)) or 0.80)
    except Exception:
        trig_score_thr = 0.80
    trig_score_thr = float(_clip(float(trig_score_thr), 0.0, 1.0))
    try:
        best_wait_min = float(cfg_eff.get("carry_trade_hedge_best_timing_wait_min", CONFIG.get("carry_trade_hedge_best_timing_wait_min", 6)) or 6)
    except Exception:
        best_wait_min = 6.0
    best_wait_min = float(_clip(float(best_wait_min), 0.0, 10_000.0))
    best_wait_ms = int(round(float(best_wait_min) * 60_000.0))
    try:
        intent_max_min = float(cfg_eff.get("carry_trade_hedge_unhedge_intent_max_min", CONFIG.get("carry_trade_hedge_unhedge_intent_max_min", 20)) or 20)
    except Exception:
        intent_max_min = 20.0
    intent_max_min = float(_clip(float(intent_max_min), 0.0, 10_000.0))
    intent_max_ms = int(round(float(intent_max_min) * 60_000.0))
    try:
        ott_tf = str(cfg_eff.get("carry_trade_hedge_ott_timeframe", CONFIG.get("carry_trade_hedge_ott_timeframe", "5m")) or "5m").strip().lower() or "5m"
    except Exception:
        ott_tf = "5m"
    ott_tf_ms = 0
    try:
        ott_tf_ms = int(_hl_interval_to_ms(str(ott_tf)))
    except Exception:
        ott_tf_ms = 0
    ott_lookback_ms = 7 * 24 * 60 * 60 * 1000
    if int(ott_tf_ms) > 0 and int(ott_tf_ms) <= 15 * 60 * 1000:
        ott_lookback_ms = 3 * 24 * 60 * 60 * 1000
    try:
        exit_score_thr = float(cfg_eff.get("carry_trade_hedge_unhedge_exit_score", CONFIG.get("carry_trade_hedge_unhedge_exit_score", 0.65)) or 0.65)
    except Exception:
        exit_score_thr = 0.65
    exit_score_thr = float(_clip(float(exit_score_thr), 0.0, 1.0))
    try:
        unhedge_timeout_min = float(cfg_eff.get("carry_trade_hedge_unhedge_timeout_min", CONFIG.get("carry_trade_hedge_unhedge_timeout_min", 60)) or 60)
    except Exception:
        unhedge_timeout_min = 60.0
    unhedge_timeout_min = float(_clip(float(unhedge_timeout_min), 0.0, 10_000.0))
    unhedge_timeout_ms = int(round(float(unhedge_timeout_min) * 60_000.0))
    try:
        unhedge_cd_min = float(cfg_eff.get("carry_trade_hedge_unhedge_cooldown_min", CONFIG.get("carry_trade_hedge_unhedge_cooldown_min", 30)) or 30)
    except Exception:
        unhedge_cd_min = 30.0
    unhedge_cd_min = float(_clip(float(unhedge_cd_min), 0.0, 10_000.0))
    unhedge_cd_ms = int(round(float(unhedge_cd_min) * 60_000.0))
    allow_pre_unhedge = bool(cfg_eff.get("carry_trade_hedge_allow_pre_funding_unhedge", CONFIG.get("carry_trade_hedge_allow_pre_funding_unhedge", True)))
    rotate_enabled = bool(cfg_eff.get("carry_trade_hedge_rotate_enabled", CONFIG.get("carry_trade_hedge_rotate_enabled", True)))
    try:
        rotate_edge_min = float(cfg_eff.get("carry_trade_hedge_rotate_edge_diff_min", CONFIG.get("carry_trade_hedge_rotate_edge_diff_min", 0.00003)) or 0.00003)
    except Exception:
        rotate_edge_min = 0.00003
    rotate_edge_min = float(max(0.0, float(rotate_edge_min)))
    rotate_require_net = bool(cfg_eff.get("carry_trade_hedge_rotate_require_net_profit", CONFIG.get("carry_trade_hedge_rotate_require_net_profit", True)))

    try:
        open_edge_thr = float(cfg_eff.get("carry_trade_open_edge_threshold", CONFIG.get("carry_trade_open_edge_threshold", 0.0)) or 0.0)
    except Exception:
        open_edge_thr = 0.0
    open_edge_thr = float(max(0.0, float(open_edge_thr)))

    strict_min_hold = bool(cfg_eff.get("carry_trade_hedge_min_hold_strict", CONFIG.get("carry_trade_hedge_min_hold_strict", True)))

    active_mon_enabled = bool(cfg_eff.get("carry_trade_active_monitor_enabled", CONFIG.get("carry_trade_active_monitor_enabled", True)))
    try:
        active_persist_s = float(cfg_eff.get("carry_trade_active_monitor_persist_sec", CONFIG.get("carry_trade_active_monitor_persist_sec", 120)) or 120)
    except Exception:
        active_persist_s = 120.0
    active_persist_s = float(_clip(float(active_persist_s), 0.0, 24.0 * 3600.0))
    active_persist_ms = int(round(float(active_persist_s) * 1000.0))
    try:
        funding_flip_abs_min = float(cfg_eff.get("carry_trade_active_monitor_funding_flip_abs_min", CONFIG.get("carry_trade_active_monitor_funding_flip_abs_min", 0.00002)) or 0.00002)
    except Exception:
        funding_flip_abs_min = 0.00002
    funding_flip_abs_min = float(max(0.0, float(funding_flip_abs_min)))
    try:
        basis_abs_bps_max = float(cfg_eff.get("carry_trade_active_monitor_basis_abs_bps_max", CONFIG.get("carry_trade_active_monitor_basis_abs_bps_max", 120.0)) or 120.0)
    except Exception:
        basis_abs_bps_max = 120.0
    basis_abs_bps_max = float(max(0.0, float(basis_abs_bps_max)))
    try:
        basis_widen_mult = float(cfg_eff.get("carry_trade_active_monitor_basis_widen_mult", CONFIG.get("carry_trade_active_monitor_basis_widen_mult", 2.0)) or 2.0)
    except Exception:
        basis_widen_mult = 2.0
    basis_widen_mult = float(_clip(float(basis_widen_mult), 1.0, 100.0))
    try:
        basis_widen_abs_min_bps = float(cfg_eff.get("carry_trade_active_monitor_basis_widen_abs_min_bps", CONFIG.get("carry_trade_active_monitor_basis_widen_abs_min_bps", 25.0)) or 25.0)
    except Exception:
        basis_widen_abs_min_bps = 25.0
    basis_widen_abs_min_bps = float(max(0.0, float(basis_widen_abs_min_bps)))
    try:
        spread_bps_max = float(cfg_eff.get("carry_trade_active_monitor_spread_bps_max", CONFIG.get("carry_trade_active_monitor_spread_bps_max", 60.0)) or 60.0)
    except Exception:
        spread_bps_max = 60.0
    spread_bps_max = float(max(0.0, float(spread_bps_max)))

    rebalance_enabled = bool(cfg_eff.get("carry_trade_hedge_rebalance_enabled", CONFIG.get("carry_trade_hedge_rebalance_enabled", True)))
    try:
        rebalance_mismatch_pct = float(cfg_eff.get("carry_trade_hedge_rebalance_mismatch_pct", CONFIG.get("carry_trade_hedge_rebalance_mismatch_pct", 0.03)) or 0.03)
    except Exception:
        rebalance_mismatch_pct = 0.03
    rebalance_mismatch_pct = float(_clip(float(rebalance_mismatch_pct), 0.0, 1.0))
    rebalance_reduce_only = bool(cfg_eff.get("carry_trade_hedge_rebalance_reduce_only", CONFIG.get("carry_trade_hedge_rebalance_reduce_only", True)))
    rebalance_skip_no_exit = bool(cfg_eff.get("carry_trade_hedge_rebalance_skip_no_exit", CONFIG.get("carry_trade_hedge_rebalance_skip_no_exit", True)))
    try:
        rebalance_min_notional = float(cfg_eff.get("carry_trade_hedge_rebalance_min_notional_usdc", CONFIG.get("carry_trade_hedge_rebalance_min_notional_usdc", 12.0)) or 12.0)
    except Exception:
        rebalance_min_notional = 12.0
    rebalance_min_notional = float(max(0.0, float(rebalance_min_notional)))

    try:
        rebalance_cd_s = float(cfg_eff.get("carry_trade_hedge_rebalance_cooldown_sec", CONFIG.get("carry_trade_hedge_rebalance_cooldown_sec", 600)) or 600)
    except Exception:
        rebalance_cd_s = 600.0
    rebalance_cd_s = float(_clip(float(rebalance_cd_s), 0.0, 24.0 * 3600.0))
    rebalance_cd_ms = int(round(float(rebalance_cd_s) * 1000.0))

    macro = _carry_macro_dir_gate(timeframe="1h", horizon_h=12, short_n=3)
    try:
        state["macro"] = dict(macro)
    except Exception:
        pass

    for pair, p in list(pos.items()):
        if not isinstance(p, dict):
            continue
        if str(p.get("venue") or "").strip().lower() != str(venue):
            continue
        if str(p.get("mode") or "").strip().lower() != "hedge":
            continue
        st0 = str(p.get("status") or "").strip().lower()
        if st0 not in ("open", "opened", "paper_opened", "closing"):
            continue
        coin = str(p.get("coin") or "").strip().upper()
        if not coin:
            continue

        pnl_pct = None
        try:
            pnl_pct = float(p.get("unrealized_pnl_pct")) if p.get("unrealized_pnl_pct") is not None else None
        except Exception:
            pnl_pct = None
        emergency_r_eff = float(emergency_r)
        if bool(dyn_emergency_enabled) and pnl_pct is not None and math.isfinite(float(pnl_pct)):
            atr_pct = None
            try:
                cand = p.get("candidate")
                if isinstance(cand, dict):
                    atr_pct = cand.get("atr_pct_5m")
            except Exception:
                atr_pct = None
            if atr_pct is None:
                try:
                    rows5 = ohlcv_fetch(coin=coin, interval="5m", now_ms=int(now_ms), lookback_ms=6 * 60 * 60 * 1000, ttl_sec=10, timeout_sec=2.0)
                    atr_pct = _carry_atr_pct(rows5, n=14)
                except Exception:
                    atr_pct = None
            try:
                if atr_pct is not None and math.isfinite(float(atr_pct)) and float(atr_pct) > 0.0:
                    r_dyn = -abs(float(atr_pct)) * float(dyn_emergency_mult)
                    emergency_r_eff = float(min(float(emergency_r_eff), float(r_dyn)))
            except Exception:
                pass
        emergency_r_eff = float(_clip(float(emergency_r_eff), float(dyn_emergency_min_r), float(dyn_emergency_max_r)))
        try:
            p["emergency_r_eff"] = float(emergency_r_eff)
        except Exception:
            pass
        emergency = (pnl_pct is not None and math.isfinite(float(pnl_pct)) and float(pnl_pct) <= float(emergency_r_eff))

        tgt_ts = None
        try:
            tgt_ts = int(p.get("target_funding_ts") or 0)
        except Exception:
            tgt_ts = 0
        post_due = (tgt_ts > 0 and int(now_ms) >= int(tgt_ts) + int(post_grace_ms))

        hard_disable = (not bool(enabled_effective)) and (bool(gate.get("paused")) or str(gate.get("reason") or "").strip().lower() in ("pnl_drawdown", "regime_panic", "regime_panic_pause", "paused"))
        soft_disable = (not bool(enabled_effective)) and (not bool(hard_disable))

        stage = str(p.get("hedge_stage") or "hedged").strip().lower() or "hedged"

        liq_risk = False
        liq_info: Dict[str, Any] = {}
        try:
            liq_buf = float(cfg_eff.get("carry_trade_hedge_liq_buffer_pct", CONFIG.get("carry_trade_hedge_liq_buffer_pct", 0.015)) or 0.015)
        except Exception:
            liq_buf = 0.015
        liq_buf = float(_clip(float(liq_buf), 0.0, 0.50))
        if float(liq_buf) > 0.0 and stage not in ("unhedged", "unhedged_perp"):
            meta = open_pos.get(str(pair)) if isinstance(open_pos, dict) else None
            if isinstance(meta, dict):
                liq_px = None
                try:
                    liq_px = float(
                        meta.get("hl_liquidation_px")
                        or meta.get("hl_liq_px")
                        or meta.get("liq_px")
                        or meta.get("liquidation_px")
                        or meta.get("aster_liquidation_px")
                        or 0.0
                    )
                except Exception:
                    liq_px = None
                mid = None
                try:
                    mid = float(p.get("last_mid")) if p.get("last_mid") is not None else None
                except Exception:
                    mid = None
                if mid is None:
                    mid0 = _carry_mid_px(str(coin), str(venue))
                    try:
                        mid = (None if mid0 is None else float(mid0))
                    except Exception:
                        mid = None
                if liq_px is not None and mid is not None and math.isfinite(float(liq_px)) and math.isfinite(float(mid)) and float(liq_px) > 0.0 and float(mid) > 0.0:
                    try:
                        side0 = str(meta.get("side") or p.get("side") or "").strip().lower()
                    except Exception:
                        side0 = ""
                    if str(side0) == "long":
                        dist_r = 1.0 - float(liq_px) / float(mid)
                    else:
                        dist_r = float(liq_px) / float(mid) - 1.0
                    liq_info = {"liq_px": float(liq_px), "mid": float(mid), "dist_r": float(dist_r), "buffer_r": float(liq_buf)}
                    if math.isfinite(float(dist_r)) and float(dist_r) <= float(liq_buf):
                        liq_risk = True
        if bool(liq_info):
            try:
                p["liq_risk"] = dict(liq_info)
            except Exception:
                pass
        if bool(liq_risk):
            if stage == "unhedged_spot":
                to_perp_exit.append((pair, p, "liq_risk"))
            else:
                to_close_both.append((pair, p, "liq_risk"))
            continue

        if emergency:
            if stage in ("unhedged", "unhedged_perp"):
                to_spot_exit.append((pair, p, "emergency"))
            elif stage == "unhedged_spot":
                to_perp_exit.append((pair, p, "emergency"))
            else:
                to_close_both.append((pair, p, "emergency"))
            continue
        if hard_disable:
            if stage in ("unhedged", "unhedged_perp"):
                to_spot_exit.append((pair, p, "hard_disable"))
            elif stage == "unhedged_spot":
                to_perp_exit.append((pair, p, "hard_disable"))
            else:
                to_close_both.append((pair, p, "hard_disable"))
            continue

        if bool(active_mon_enabled) and coin:
            metrics = _carry_active_metrics(int(now_ms), venue=str(venue), coin=str(coin))
            fr = None
            basis_bps = None
            spread_bps = None
            try:
                fr = float(metrics.get("funding_rate")) if metrics.get("funding_rate") is not None else None
            except Exception:
                fr = None
            try:
                basis_bps = float(metrics.get("basis_bps")) if metrics.get("basis_bps") is not None else None
            except Exception:
                basis_bps = None
            try:
                spread_bps = float(metrics.get("spread_bps")) if metrics.get("spread_bps") is not None else None
            except Exception:
                spread_bps = None

            flags: List[str] = []
            if fr is not None and math.isfinite(float(fr)) and float(funding_flip_abs_min) > 0.0:
                try:
                    s0 = str(p.get("side") or "short").strip().lower()
                except Exception:
                    s0 = "short"
                if str(s0) == "long":
                    if float(fr) >= float(funding_flip_abs_min):
                        flags.append("funding_flip")
                else:
                    if float(fr) <= -float(funding_flip_abs_min):
                        flags.append("funding_flip")
            if basis_bps is not None and math.isfinite(float(basis_bps)):
                if float(basis_abs_bps_max) > 0.0 and abs(float(basis_bps)) >= float(basis_abs_bps_max):
                    flags.append("basis_abs")
                entry_basis = None
                try:
                    cand = p.get("candidate")
                    if isinstance(cand, dict) and cand.get("basis_bps") is not None:
                        entry_basis = float(cand.get("basis_bps"))
                except Exception:
                    entry_basis = None
                if entry_basis is not None and math.isfinite(float(entry_basis)):
                    ae = abs(float(entry_basis))
                    an = abs(float(basis_bps))
                    thr = max(float(ae) * float(basis_widen_mult), float(ae) + float(basis_widen_abs_min_bps))
                    if float(an) >= float(thr):
                        flags.append("basis_widen")
            if spread_bps is not None and math.isfinite(float(spread_bps)) and float(spread_bps_max) > 0.0 and float(spread_bps) >= float(spread_bps_max):
                flags.append("spread_high")

            mview = {
                "funding_rate": (None if fr is None else float(fr)),
                "basis_bps": (None if basis_bps is None else float(basis_bps)),
                "spread_bps": (None if spread_bps is None else float(spread_bps)),
            }
            try:
                p["active_metrics"] = dict(mview)
            except Exception:
                pass

            if flags:
                mon0 = p.get("active_monitor") if isinstance(p.get("active_monitor"), dict) else {}
                first_ts = 0
                try:
                    first_ts = int(mon0.get("ts_first") or 0)
                except Exception:
                    first_ts = 0
                if first_ts <= 0:
                    first_ts = int(now_ms)
                triggered = True
                if int(active_persist_ms) > 0:
                    triggered = (int(now_ms) - int(first_ts)) >= int(active_persist_ms)
                p["active_monitor"] = {
                    "ok": False,
                    "ts_first": int(first_ts),
                    "ts_last": int(now_ms),
                    "persist_ms": int(active_persist_ms),
                    "flags": list(flags),
                    "metrics": dict(mview),
                    "triggered": bool(triggered),
                    "trigger_ts": (int(now_ms) if bool(triggered) else None),
                }
                if bool(triggered):
                    if stage not in ("unhedged", "unhedged_perp", "unhedged_spot") and bool(strict_min_hold):
                        et0 = 0
                        try:
                            et0 = int(p.get("entry_ts") or 0)
                        except Exception:
                            et0 = 0
                        if et0 > 0 and int(min_hold_ms) > 0 and (int(now_ms) - int(et0)) < int(min_hold_ms):
                            pos[pair] = p
                            continue
                    try:
                        in_no_exit = bool(_carry_in_no_exit_window(int(now_ms), int(next_ts), dict(cfg_eff)))
                    except Exception:
                        in_no_exit = False
                    if bool(in_no_exit) and (not bool(allow_pre_unhedge)) and (not bool(post_due)):
                        pos[pair] = p
                        continue
                    if stage in ("unhedged", "unhedged_perp"):
                        to_spot_exit.append((pair, p, "active_monitor"))
                    elif stage == "unhedged_spot":
                        to_perp_exit.append((pair, p, "active_monitor"))
                    else:
                        to_close_both.append((pair, p, "active_monitor"))
                    continue
            else:
                p["active_monitor"] = {"ok": True, "ts": int(now_ms), "metrics": dict(mview)}

        if bool(cb_enabled) and coin:
            cb_hit = False
            cb_info: Dict[str, Any] = {"ok": True}
            try:
                spread_now = _carry_hl_spread_bps_quick(coin=str(coin), now_ms=int(now_ms))
            except Exception:
                spread_now = None
            if spread_now is not None:
                try:
                    cb_info["spread_bps"] = float(spread_now)
                except Exception:
                    pass
                if float(cb_spread_bps_thr) > 0.0 and math.isfinite(float(spread_now)) and float(spread_now) >= float(cb_spread_bps_thr):
                    cb_hit = True
                    cb_info["hit_spread"] = True
            try:
                rows1 = ohlcv_fetch(coin=str(coin), interval="1m", now_ms=int(now_ms), lookback_ms=90 * 60 * 1000, ttl_sec=8, timeout_sec=2.0)
            except Exception:
                rows1 = []
            try:
                if rows1 and len(rows1) >= 2 and len(rows1[-1]) >= 5 and len(rows1[-2]) >= 5:
                    c1 = float(rows1[-1][4])
                    c0 = float(rows1[-2][4])
                    if math.isfinite(float(c1)) and math.isfinite(float(c0)) and float(c0) > 0.0:
                        ret_1m = float(c1) / float(c0) - 1.0
                        cb_info["ret_1m"] = float(ret_1m)
                        if float(cb_ret_1m_min_r) > 0.0 and abs(float(ret_1m)) >= float(cb_ret_1m_min_r):
                            cb_hit = True
                            cb_info["hit_ret_1m"] = True
            except Exception:
                pass
            try:
                rows5 = ohlcv_fetch(coin=str(coin), interval="5m", now_ms=int(now_ms), lookback_ms=6 * 60 * 60 * 1000, ttl_sec=10, timeout_sec=2.0)
            except Exception:
                rows5 = []
            atr5 = _carry_atr_pct(rows5, n=14)
            if atr5 is not None:
                try:
                    cb_info["atr_pct_5m"] = float(atr5)
                except Exception:
                    pass
            try:
                if rows5 and len(rows5) >= 2 and len(rows5[-1]) >= 5 and len(rows5[-2]) >= 5:
                    c1 = float(rows5[-1][4])
                    c0 = float(rows5[-2][4])
                    if math.isfinite(float(c1)) and math.isfinite(float(c0)) and float(c0) > 0.0:
                        ret_5m = float(c1) / float(c0) - 1.0
                        cb_info["ret_5m"] = float(ret_5m)
                        if atr5 is not None and math.isfinite(float(atr5)) and float(atr5) > 0.0 and float(cb_ret_5m_atr_mult) > 0.0:
                            if abs(float(ret_5m)) >= float(cb_ret_5m_atr_mult) * float(atr5):
                                cb_hit = True
                                cb_info["hit_ret_5m_atr"] = True
            except Exception:
                pass
            if bool(cb_hit):
                cb_info["ok"] = False
                cb_info["tag"] = "circuit_breaker"
                try:
                    p["circuit_breaker"] = dict(cb_info)
                except Exception:
                    pass
                if stage in ("unhedged", "unhedged_perp"):
                    to_spot_exit.append((pair, p, "circuit_breaker"))
                elif stage == "unhedged_spot":
                    to_perp_exit.append((pair, p, "circuit_breaker"))
                else:
                    to_close_both.append((pair, p, "circuit_breaker"))
                continue

        if bool(rebalance_enabled) and stage == "hedged" and float(rebalance_mismatch_pct) > 0.0:
            try:
                in_no_exit = bool(_carry_in_no_exit_window(int(now_ms), int(next_ts), dict(cfg_eff)))
            except Exception:
                in_no_exit = False
            if (not bool(in_no_exit)) or (not bool(rebalance_skip_no_exit)) or bool(allow_pre_unhedge):
                rb_by_pair = state.get("rebalance_by_pair")
                if not isinstance(rb_by_pair, dict):
                    rb_by_pair = {}
                    state["rebalance_by_pair"] = rb_by_pair
                try:
                    last_rb = int(rb_by_pair.get(str(pair)) or 0)
                except Exception:
                    last_rb = 0
                if last_rb <= 0 or int(rebalance_cd_ms) <= 0 or (int(now_ms) - int(last_rb)) >= int(rebalance_cd_ms):
                    live_pos = None
                    try:
                        live_pos = (open_pos.get(str(pair)) if isinstance(open_pos, dict) else None)
                    except Exception:
                        live_pos = None
                    perp_qty = 0.0
                    try:
                        if isinstance(live_pos, dict):
                            perp_qty = abs(
                                float(
                                    _to_float(
                                        live_pos.get(
                                            "hl_szi",
                                            live_pos.get(
                                                "aster_position_amt",
                                                live_pos.get(
                                                    "position_amt",
                                                    live_pos.get("base_qty", 0.0),
                                                ),
                                            ),
                                        )
                                    )
                                )
                            )
                    except Exception:
                        perp_qty = 0.0
                    spot_qty = 0.0
                    try:
                        spot_meta = p.get("spot") if isinstance(p.get("spot"), dict) else {}
                        spot_qty = abs(float(_to_float(spot_meta.get("qty", 0.0))))
                    except Exception:
                        spot_qty = 0.0
                    mx = max(float(perp_qty), float(spot_qty))
                    if mx > 0.0:
                        mismatch = abs(float(perp_qty) - float(spot_qty)) / float(mx)
                        if float(mismatch) >= float(rebalance_mismatch_pct):
                            mid_rb = _carry_mid_px(str(coin), str(venue))
                            if mid_rb is None:
                                try:
                                    mid_rb = float(_hl_mid(str(coin)))
                                except Exception:
                                    mid_rb = None
                            if mid_rb is not None and math.isfinite(float(mid_rb)) and float(mid_rb) > 0.0:
                                rb_tag = f"carry_rebalance|{int(now_ms)}"
                                try:
                                    ntl_target = float(p.get("notional_usdc") or 0.0)
                                except Exception:
                                    ntl_target = 0.0
                                target_qty0 = None
                                if math.isfinite(float(ntl_target)) and float(ntl_target) > 0.0:
                                    target_qty0 = float(ntl_target) / float(mid_rb)
                                    if (not math.isfinite(float(target_qty0))) or float(target_qty0) <= 0.0:
                                        target_qty0 = None

                                if bool(rebalance_reduce_only):
                                    target_qty = min(float(perp_qty), float(spot_qty))
                                    if target_qty0 is not None:
                                        target_qty = min(float(target_qty), float(target_qty0))
                                else:
                                    if target_qty0 is not None:
                                        target_qty = float(target_qty0)
                                    else:
                                        target_qty = max(float(perp_qty), float(spot_qty))

                                actions: List[Dict[str, Any]] = []
                                any_ok = False
                                all_ok = True

                                delta_p = float(perp_qty) - float(target_qty)
                                if math.isfinite(float(delta_p)) and abs(float(delta_p)) > 0.0:
                                    dn = abs(float(delta_p)) * float(mid_rb)
                                    if math.isfinite(float(dn)) and float(dn) >= float(rebalance_min_notional):
                                        if float(delta_p) > 0.0:
                                            try:
                                                qty_adj = float(_hl_round_sz(str(coin), abs(float(delta_p))))
                                            except Exception:
                                                qty_adj = abs(float(delta_p))
                                            ok0 = False
                                            od0 = None
                                            code0 = 0
                                            try:
                                                od0, code0 = _unpack_jsonify_resp(hyperliquid_market_close_internal(coin=str(coin), execute=bool(execute), tag=str(rb_tag) + "|perp_reduce", sz=float(qty_adj), exit_owner="carry_trade", force=True))
                                                ok0 = bool(isinstance(od0, dict) and bool(od0.get("ok", True)) and int(code0) < 500)
                                            except Exception as e:
                                                od0 = {"ok": False, "err": str(e)}
                                                code0 = 0
                                                ok0 = False
                                            actions.append({"leg": "perp", "action": "reduce", "qty": float(qty_adj), "notional_usdc": float(dn), "ok": bool(ok0), "http": int(code0), "resp": (od0 if isinstance(od0, dict) else None)})
                                            any_ok = bool(any_ok) or bool(ok0)
                                            all_ok = bool(all_ok) and bool(ok0)
                                        else:
                                            if not bool(rebalance_reduce_only):
                                                add_notional = float(dn)
                                                try:
                                                    side_perp = str(p.get("side") or "short").strip().lower()
                                                except Exception:
                                                    side_perp = "short"
                                                if str(side_perp) not in ("long", "short"):
                                                    side_perp = "short"
                                                ok0 = False
                                                od0 = None
                                                code0 = 0
                                                try:
                                                    lev0 = None
                                                    try:
                                                        lev0 = p.get("perp_leverage")
                                                    except Exception:
                                                        lev0 = None
                                                    od0, code0 = _unpack_jsonify_resp(hyperliquid_market_open_internal(coin=str(coin), side=str(side_perp), notional_usdc=float(add_notional), execute=bool(execute), tag=str(rb_tag) + "|perp_add", strategy_id="CarryTrade", ab_owner="carry", leverage=(None if lev0 is None else int(lev0)), skip_gate=True))
                                                    ok0 = bool(isinstance(od0, dict) and bool(od0.get("ok", True)) and int(code0) < 500)
                                                except Exception as e:
                                                    od0 = {"ok": False, "err": str(e)}
                                                    code0 = 0
                                                    ok0 = False
                                                actions.append({"leg": "perp", "action": "add", "notional_usdc": float(add_notional), "ok": bool(ok0), "http": int(code0), "resp": (od0 if isinstance(od0, dict) else None)})
                                                any_ok = bool(any_ok) or bool(ok0)
                                                all_ok = bool(all_ok) and bool(ok0)

                                delta_s = float(spot_qty) - float(target_qty)
                                if math.isfinite(float(delta_s)) and abs(float(delta_s)) > 0.0:
                                    dn = abs(float(delta_s)) * float(mid_rb)
                                    if math.isfinite(float(dn)) and float(dn) >= float(rebalance_min_notional):
                                        if float(delta_s) > 0.0:
                                            try:
                                                spot_name = _hl_spot_name_from_coin(str(coin), quote="USDC")
                                                qty_adj = float(_hl_round_sz_by_name(str(spot_name), abs(float(delta_s))))
                                            except Exception:
                                                qty_adj = abs(float(delta_s))
                                            ok0 = False
                                            od0 = None
                                            try:
                                                data0, code0 = _unpack_jsonify_resp(hyperliquid_spot_market_close_internal(coin=str(coin), qty=float(qty_adj), execute=bool(execute), tag=str(rb_tag) + "|spot_reduce", strategy_id="CarryTrade", ab_owner="carry"))
                                                od0 = {"http": int(code0), "resp": (data0 if isinstance(data0, dict) else None)}
                                                ok0 = bool(isinstance(data0, dict) and bool(data0.get("ok", False)) and int(code0) < 500)
                                            except Exception as e:
                                                od0 = {"ok": False, "err": str(e)}
                                                ok0 = False
                                            actions.append({"leg": "spot", "action": "reduce", "qty": float(qty_adj), "notional_usdc": float(dn), "ok": bool(ok0), "resp": (od0 if isinstance(od0, dict) else None)})
                                            if bool(ok0):
                                                try:
                                                    spot_meta = p.get("spot") if isinstance(p.get("spot"), dict) else {}
                                                    spot_meta["qty"] = max(0.0, float(spot_qty) - float(qty_adj))
                                                    p["spot"] = spot_meta
                                                except Exception:
                                                    pass
                                            any_ok = bool(any_ok) or bool(ok0)
                                            all_ok = bool(all_ok) and bool(ok0)
                                        else:
                                            if not bool(rebalance_reduce_only):
                                                add_notional = float(dn)
                                                ok0 = False
                                                od0 = None
                                                add_qty = None
                                                try:
                                                    data0, code0 = _unpack_jsonify_resp(hyperliquid_spot_market_open_internal(coin=str(coin), notional_usdc=float(add_notional), execute=bool(execute), tag=str(rb_tag) + "|spot_add", quote="USDC", strategy_id="CarryTrade", ab_owner="carry", skip_gate=True))
                                                    od0 = {"http": int(code0), "resp": (data0 if isinstance(data0, dict) else None)}
                                                    ok0 = bool(isinstance(data0, dict) and bool(data0.get("ok", False)) and int(code0) < 500)
                                                    try:
                                                        add_qty = float(_to_float((((data0.get("order") or {}) if isinstance(data0.get("order"), dict) else {}).get("exec") or {}).get("sz"), 0.0)) if isinstance(data0, dict) else None
                                                    except Exception:
                                                        add_qty = None
                                                except Exception as e:
                                                    od0 = {"ok": False, "err": str(e)}
                                                    ok0 = False
                                                actions.append({"leg": "spot", "action": "add", "notional_usdc": float(add_notional), "qty": (None if add_qty is None else float(add_qty)), "ok": bool(ok0), "resp": (od0 if isinstance(od0, dict) else None)})
                                                if bool(ok0):
                                                    try:
                                                        spot_meta = p.get("spot") if isinstance(p.get("spot"), dict) else {}
                                                        inc = abs(float(delta_s)) if add_qty is None else float(add_qty)
                                                        spot_meta["qty"] = max(0.0, float(spot_qty) + float(inc))
                                                        p["spot"] = spot_meta
                                                    except Exception:
                                                        pass
                                                any_ok = bool(any_ok) or bool(ok0)
                                                all_ok = bool(all_ok) and bool(ok0)

                                rb_info: Dict[str, Any] = {
                                    "ok": bool(all_ok) and bool(any_ok),
                                    "reduce_only": bool(rebalance_reduce_only),
                                    "mismatch": float(mismatch),
                                    "mid": float(mid_rb),
                                    "perp_qty": float(perp_qty),
                                    "spot_qty": float(spot_qty),
                                    "target_qty": float(target_qty),
                                    "actions": list(actions),
                                }
                                if bool(rb_info.get("ok")):
                                    rb_by_pair[str(pair)] = int(now_ms)
                                try:
                                    p["last_rebalance"] = dict(rb_info)
                                except Exception:
                                    pass
                                _ev("rebalance", {"pair": str(pair), "coin": str(coin), "ok": bool(rb_info.get("ok")), "mismatch": float(mismatch), "info": rb_info})

        if stage in ("unhedged", "unhedged_perp"):
            try:
                rows5 = ohlcv_fetch(coin=coin, interval="5m", now_ms=int(now_ms), lookback_ms=6 * 60 * 60 * 1000, ttl_sec=10, timeout_sec=2.0)
            except Exception:
                rows5 = []
            ex = _carry_unhedge_exit_score_rows(rows5, carry_side="long")
            try:
                p["unhedge_exit_score"] = float(ex.get("score") or 0.0)
            except Exception:
                pass
            deadline = 0
            try:
                deadline = int(p.get("unhedge_deadline_ts") or 0)
            except Exception:
                deadline = 0
            if bool(soft_disable):
                to_spot_exit.append((pair, p, "disabled"))
                continue
            if float(ex.get("score") or 0.0) >= float(exit_score_thr):
                to_spot_exit.append((pair, p, "unhedge_exit"))
                continue
            if deadline > 0 and int(now_ms) >= int(deadline):
                to_spot_exit.append((pair, p, "unhedge_timeout"))
                continue
            pos[pair] = p
            continue

        if stage == "unhedged_spot":
            try:
                rows5 = ohlcv_fetch(coin=coin, interval="5m", now_ms=int(now_ms), lookback_ms=6 * 60 * 60 * 1000, ttl_sec=10, timeout_sec=2.0)
            except Exception:
                rows5 = []
            ex = _carry_unhedge_exit_score_rows(rows5, carry_side="short")
            try:
                p["unhedge_exit_score"] = float(ex.get("score") or 0.0)
            except Exception:
                pass
            deadline = 0
            try:
                deadline = int(p.get("unhedge_deadline_ts") or 0)
            except Exception:
                deadline = 0
            if bool(soft_disable):
                to_perp_exit.append((pair, p, "disabled"))
                continue
            if float(ex.get("score") or 0.0) >= float(exit_score_thr):
                to_perp_exit.append((pair, p, "unhedge_exit"))
                continue
            if deadline > 0 and int(now_ms) >= int(deadline):
                to_perp_exit.append((pair, p, "unhedge_timeout"))
                continue
            pos[pair] = p
            continue

        in_no_exit = bool(_carry_in_no_exit_window(int(now_ms), int(next_ts), dict(cfg_eff)))
        if bool(soft_disable):
            if not bool(in_no_exit):
                to_close_both.append((pair, p, "disabled"))
            continue

        if not bool(unhedge_enabled):
            if post_due:
                if bool(strict_min_hold):
                    et0 = 0
                    try:
                        et0 = int(p.get("entry_ts") or 0)
                    except Exception:
                        et0 = 0
                    if et0 > 0 and int(min_hold_ms) > 0 and (int(now_ms) - int(et0)) < int(min_hold_ms):
                        try:
                            p["target_funding_ts"] = int(next_ts)
                        except Exception:
                            pass
                        pos[pair] = p
                        continue
                to_close_both.append((pair, p, "post_funding_exit"))
            pos[pair] = p
            continue

        try:
            rows5 = ohlcv_fetch(coin=coin, interval="5m", now_ms=int(now_ms), lookback_ms=6 * 60 * 60 * 1000, ttl_sec=10, timeout_sec=2.0)
        except Exception:
            rows5 = []
        reversal_dir = 0
        ott = {"ok": True, "tag": "disabled", "cross_dir": 0}
        try:
            mdir = int((macro.get("dir") if isinstance(macro, dict) else 0) or 0)
        except Exception:
            mdir = 0
        if int(mdir) != 0:
            try:
                rows_ott = ohlcv_fetch(coin=coin, interval=str(ott_tf), now_ms=int(now_ms), lookback_ms=int(ott_lookback_ms), ttl_sec=30, timeout_sec=2.0)
            except Exception:
                rows_ott = []
            try:
                ott = _carry_ott_reversal_rows(rows_ott, pds=3, percent=2.2, shift=2, cross_lookback=6)
            except Exception:
                ott = {"ok": True, "tag": "error", "cross_dir": 0}
            try:
                if int(ott.get("cross_dir") or 0) == int(mdir):
                    reversal_dir = int(mdir)
            except Exception:
                reversal_dir = 0
        try:
            p["macro_dir"] = int(mdir)
            p["ott_reversal"] = dict(ott) if isinstance(ott, dict) else {"raw": ott}
            p["reversal_dir"] = int(reversal_dir)
        except Exception:
            pass

        ug = _carry_unhedge_gate(int(now_ms), venue=str(venue), pair=str(pair), coin=str(coin), p=p, macro_dir=int(mdir), ott=(ott if isinstance(ott, dict) else {}), cfg=dict(cfg_eff), state=state)
        if isinstance(ug, dict) and str(ug.get("action") or "") == "force_close_both":
            to_close_both.append((pair, p, "unhedge_gate_timeout"))
            continue
        if isinstance(ug, dict) and str(ug.get("action") or "") == "force_unhedge":
            try:
                p["unhedge_intent_ts"] = int(now_ms)
            except Exception:
                pass
            to_unhedge.append((pair, p, "unhedge_gate_timeout", "perp"))
            continue
        if isinstance(ug, dict) and (not bool(ug.get("ok", True))):
            try:
                p["unhedge_intent_ts"] = 0
            except Exception:
                pass
            if post_due:
                if bool(strict_min_hold):
                    et0 = 0
                    try:
                        et0 = int(p.get("entry_ts") or 0)
                    except Exception:
                        et0 = 0
                    if et0 > 0 and int(min_hold_ms) > 0 and (int(now_ms) - int(et0)) < int(min_hold_ms):
                        try:
                            p["target_funding_ts"] = int(next_ts)
                        except Exception:
                            pass
                        pos[pair] = p
                        continue
                to_close_both.append((pair, p, "post_funding_exit"))
                continue
            pos[pair] = p
            continue

        timing_side = "long" if int(reversal_dir) >= 0 else "short"
        sc = _carry_best_timing_score_rows(rows5, carry_side=str(timing_side))
        try:
            p["best_timing_score"] = float(sc.get("score") or 0.0)
        except Exception:
            pass
        try:
            p["best_timing_side"] = str(timing_side)
        except Exception:
            pass
        score_ok = float(sc.get("score") or 0.0) >= float(trig_score_thr)

        intent_ts = 0
        try:
            intent_ts = int(p.get("unhedge_intent_ts") or 0)
        except Exception:
            intent_ts = 0
        if int(reversal_dir) != 0:
            if intent_ts <= 0:
                intent_ts = int(now_ms)
                try:
                    p["unhedge_intent_ts"] = int(intent_ts)
                except Exception:
                    pass
        else:
            if intent_ts > 0:
                try:
                    p["unhedge_intent_ts"] = 0
                except Exception:
                    pass
            intent_ts = 0
        intent_age_ms = 0
        if int(intent_ts) > 0:
            intent_age_ms = max(0, int(now_ms) - int(intent_ts))

        held_ok = True
        try:
            et = int(p.get("entry_ts") or 0)
        except Exception:
            et = 0
        if et > 0 and int(min_hold_ms) > 0:
            held_ok = (int(now_ms) - int(et)) >= int(min_hold_ms)
        if (not bool(held_ok)) and (not bool(strict_min_hold)) and bool(score_ok):
            held_ok = True

        net_ok = True
        if bool(rotate_require_net):
            try:
                net_est = float(p.get("net_pnl_usdc_est") or 0.0)
            except Exception:
                net_est = 0.0
            net_ok = float(net_est) >= 0.0
            if (not bool(net_ok)) and (not bool(strict_min_hold)) and bool(score_ok):
                net_ok = True

        cd_unhedge_until = 0
        try:
            cd_unhedge_until = int(((state.get("unhedge_cooldown_by_coin") or {}) if isinstance(state.get("unhedge_cooldown_by_coin"), dict) else {}).get(str(coin).upper()) or 0)
        except Exception:
            cd_unhedge_until = 0
        if cd_unhedge_until > 0 and int(now_ms) < int(cd_unhedge_until):
            pos[pair] = p
            continue

        trigger_ok = (bool(held_ok) and bool(net_ok) and ((int(reversal_dir) != 0) or bool(post_due)))
        exec_macro_ott = False
        if int(reversal_dir) != 0:
            waited_ok = (int(best_wait_ms) <= 0) or (int(intent_age_ms) >= int(best_wait_ms))
            force_ok = (int(intent_max_ms) > 0 and int(intent_age_ms) >= int(intent_max_ms))
            exec_macro_ott = bool(force_ok) or (bool(waited_ok) and bool(score_ok))
        exec_post_due = bool(post_due) and bool(score_ok)
        exec_ok = bool(trigger_ok) and (bool(exec_post_due) or bool(exec_macro_ott))
        if bool(exec_ok):
            if (not bool(in_no_exit)) or bool(allow_pre_unhedge) or bool(post_due):
                if post_due:
                    to_unhedge.append((pair, p, "post_funding_best_timing", "perp"))
                else:
                    leg = "perp" if int(reversal_dir) == 1 else "spot"
                    reason = "macro_ott_best_timing" if bool(score_ok) else "macro_ott_intent_timeout"
                    to_unhedge.append((pair, p, str(reason), str(leg)))
                continue

        if post_due:
            if bool(strict_min_hold):
                et0 = 0
                try:
                    et0 = int(p.get("entry_ts") or 0)
                except Exception:
                    et0 = 0
                if et0 > 0 and int(min_hold_ms) > 0 and (int(now_ms) - int(et0)) < int(min_hold_ms):
                    try:
                        p["target_funding_ts"] = int(next_ts)
                    except Exception:
                        pass
                    pos[pair] = p
                    continue
            to_close_both.append((pair, p, "post_funding_exit"))
            continue

        pos[pair] = p

    active_pairs = []
    for pair, p in pos.items():
        if not isinstance(p, dict):
            continue
        if str(p.get("venue") or "").strip().lower() != str(venue):
            continue
        if str(p.get("mode") or "").strip().lower() != "hedge":
            continue
        if str(p.get("status") or "").strip().lower() in ("open", "opened", "paper_opened", "closing"):
            active_pairs.append(str(pair))

    cd_by_coin = state.get("cooldown_by_coin")
    if not isinstance(cd_by_coin, dict):
        cd_by_coin = {}
        state["cooldown_by_coin"] = cd_by_coin

    for pair, p, reason, leg in to_unhedge:
        st0 = str(p.get("status") or "").strip().lower()
        if st0 == "closing":
            continue
        coin = str(p.get("coin") or "").strip().upper()
        do_exec = bool(p.get("execute", False))
        tag = f"carry_unhedge|{reason}|{str(leg)}"
        ok = False
        info: Dict[str, Any] = {}
        if str(leg) == "spot":
            spot = p.get("spot") if isinstance(p.get("spot"), dict) else {}
            qty = None
            try:
                qty = float(spot.get("qty") or 0.0)
            except Exception:
                qty = None
            if qty is None or (not math.isfinite(float(qty))) or float(qty) <= 0.0:
                mid = _carry_mid_px(str(coin), str(venue))
                try:
                    ntl = float(p.get("notional_usdc") or 0.0)
                except Exception:
                    ntl = 0.0
                if mid is not None and math.isfinite(float(mid)) and float(mid) > 0.0 and math.isfinite(float(ntl)) and float(ntl) > 0.0:
                    try:
                        spot_name = _hl_spot_name_from_coin(str(coin), quote="USDC")
                        qty = float(_hl_round_sz_by_name(str(spot_name), float(ntl) / float(mid)))
                    except Exception:
                        qty = None
            if qty is None or (not math.isfinite(float(qty))) or float(qty) <= 0.0:
                info = {"ok": False, "err": "missing_spot_qty"}
                ok = False
            else:
                try:
                    data, code = _unpack_jsonify_resp(hyperliquid_spot_market_close_internal(coin=str(coin), qty=float(qty), execute=bool(do_exec), tag=str(tag), strategy_id="CarryTrade", ab_owner="carry"))
                    info = {"http": int(code), "resp": (data if isinstance(data, dict) else None)}
                    ok = bool(isinstance(data, dict) and bool(data.get("ok", False)) and int(code) < 500)
                except Exception as e:
                    info = {"ok": False, "err": str(e)}
                    ok = False
            p["last_unhedge"] = dict(info)
            if ok:
                p["hedge_stage"] = "unhedged_spot"
                p["unhedge_ts"] = int(now_ms)
                p["unhedge_deadline_ts"] = int(now_ms) + int(unhedge_timeout_ms)
                state.setdefault("unhedge_cooldown_by_coin", {})
                ucd = state.get("unhedge_cooldown_by_coin")
                if isinstance(ucd, dict) and coin:
                    ucd[str(coin).upper()] = int(now_ms) + int(unhedge_cd_ms)
        else:
            try:
                data, code = _unpack_jsonify_resp(hyperliquid_market_close_internal(coin=str(coin), execute=bool(do_exec), tag=str(tag), sz=None, exit_owner="carry_trade", force=True))
                info = {"http": int(code), "resp": (data if isinstance(data, dict) else None)}
                if isinstance(data, dict) and bool(data.get("ok", True)) and int(code) < 500:
                    ok = True
            except Exception as e:
                info = {"error": str(e)}
                ok = False
            p["last_unhedge"] = dict(info)
            if ok:
                p["hedge_stage"] = "unhedged_perp"
                p["unhedge_ts"] = int(now_ms)
                p["unhedge_deadline_ts"] = int(now_ms) + int(unhedge_timeout_ms)
                state.setdefault("unhedge_cooldown_by_coin", {})
                ucd = state.get("unhedge_cooldown_by_coin")
                if isinstance(ucd, dict) and coin:
                    ucd[str(coin).upper()] = int(now_ms) + int(unhedge_cd_ms)
        _ev("unhedge", {"pair": str(pair), "coin": str(coin), "reason": str(reason), "leg": str(leg), "execute": bool(do_exec), "ok": bool(ok)})
        pos[pair] = p

    for pair, p, reason in to_perp_exit:
        st0 = str(p.get("status") or "").strip().lower()
        if st0 == "closing":
            continue
        coin = str(p.get("coin") or "").strip().upper()
        do_exec = bool(p.get("execute", False))
        tag = f"carry_perp_exit|{reason}"
        ok_perp = False
        info: Dict[str, Any] = {}
        try:
            data, code = _unpack_jsonify_resp(hyperliquid_market_close_internal(coin=str(coin), execute=bool(do_exec), tag=str(tag), sz=None, exit_owner="carry_trade", force=True))
            info = {"http": int(code), "resp": (data if isinstance(data, dict) else None)}
            if isinstance(data, dict) and bool(data.get("ok", True)) and int(code) < 500:
                ok_perp = True
        except Exception as e:
            info = {"error": str(e)}
            ok_perp = False
        p["last_perp_exit"] = dict(info)
        if ok_perp:
            p["status"] = "closed" if (not bool(do_exec)) else "closing"
            if not bool(do_exec):
                p["closed_ts"] = int(now_ms)
            try:
                if coin:
                    cd_eff = int(cb_cooldown_ms) if str(reason) == "circuit_breaker" else int(cooldown_ms)
                    cd_by_coin[str(coin).upper()] = int(now_ms) + int(cd_eff)
            except Exception:
                pass
            p["hedge_stage"] = "closed"
        _ev("perp_exit", {"pair": str(pair), "coin": str(coin), "reason": str(reason), "execute": bool(do_exec), "ok": bool(ok_perp)})
        pos[pair] = p

    for pair, p, reason in to_spot_exit:
        st0 = str(p.get("status") or "").strip().lower()
        if st0 == "closing":
            continue
        coin = str(p.get("coin") or "").strip().upper()
        do_exec = bool(p.get("execute", False))
        tag = f"carry_spot_exit|{reason}"
        spot = p.get("spot") if isinstance(p.get("spot"), dict) else {}
        qty = None
        try:
            qty = float(spot.get("qty") or 0.0)
        except Exception:
            qty = None
        if qty is None or (not math.isfinite(float(qty))) or float(qty) <= 0.0:
            mid = _carry_mid_px(str(coin), str(venue))
            try:
                ntl = float(p.get("notional_usdc") or 0.0)
            except Exception:
                ntl = 0.0
            if mid is not None and math.isfinite(float(mid)) and float(mid) > 0.0 and math.isfinite(float(ntl)) and float(ntl) > 0.0:
                try:
                    spot_name = _hl_spot_name_from_coin(str(coin), quote="USDC")
                    qty = float(_hl_round_sz_by_name(str(spot_name), float(ntl) / float(mid)))
                except Exception:
                    qty = None
        ok_spot = False
        info: Dict[str, Any] = {}
        if qty is None or (not math.isfinite(float(qty))) or float(qty) <= 0.0:
            info = {"ok": False, "err": "missing_spot_qty"}
            ok_spot = False
        else:
            try:
                data, code = _unpack_jsonify_resp(hyperliquid_spot_market_close_internal(coin=str(coin), qty=float(qty), execute=bool(do_exec), tag=str(tag), strategy_id="CarryTrade", ab_owner="carry"))
                info = {"http": int(code), "resp": (data if isinstance(data, dict) else None)}
                ok_spot = bool(isinstance(data, dict) and bool(data.get("ok", False)) and int(code) < 500)
            except Exception as e:
                info = {"ok": False, "err": str(e)}
                ok_spot = False
        p["last_spot_exit"] = dict(info)
        if ok_spot:
            p["status"] = "closed" if (not bool(do_exec)) else "closing"
            if not bool(do_exec):
                p["closed_ts"] = int(now_ms)
            try:
                if coin:
                    cd_eff = int(cb_cooldown_ms) if str(reason) == "circuit_breaker" else int(cooldown_ms)
                    cd_by_coin[str(coin).upper()] = int(now_ms) + int(cd_eff)
            except Exception:
                pass
            p["hedge_stage"] = "closed"
        _ev("spot_exit", {"pair": str(pair), "coin": str(coin), "reason": str(reason), "execute": bool(do_exec), "ok": bool(ok_spot), "qty": (None if qty is None else float(qty))})
        pos[pair] = p

    for pair, p, reason in to_close_both:
        st0 = str(p.get("status") or "").strip().lower()
        if st0 == "closing":
            continue
        coin = str(p.get("coin") or "").strip().upper()
        do_exec = bool(p.get("execute", False))
        tag = f"carry_close|{reason}"
        ok_perp = False
        perp_info: Dict[str, Any] = {}
        try:
            data, code = _unpack_jsonify_resp(hyperliquid_market_close_internal(coin=str(coin), execute=bool(do_exec), tag=str(tag), sz=None, exit_owner="carry_trade", force=bool(reason in ("emergency", "hard_disable", "circuit_breaker"))))
            perp_info = {"http": int(code), "resp": (data if isinstance(data, dict) else None)}
            if isinstance(data, dict) and bool(data.get("ok", True)) and int(code) < 500:
                ok_perp = True
        except Exception as e:
            perp_info = {"error": str(e)}
            ok_perp = False
        p["last_close_perp"] = dict(perp_info)
        if not bool(ok_perp):
            _ev("close", {"pair": str(pair), "coin": str(coin), "reason": str(reason), "execute": bool(do_exec), "ok": False, "leg": "perp"})
            pos[pair] = p
            continue

        spot = p.get("spot") if isinstance(p.get("spot"), dict) else {}
        qty = None
        try:
            qty = float(spot.get("qty") or 0.0)
        except Exception:
            qty = None
        if qty is None or (not math.isfinite(float(qty))) or float(qty) <= 0.0:
            mid = _carry_mid_px(str(coin), str(venue))
            try:
                ntl = float(p.get("notional_usdc") or 0.0)
            except Exception:
                ntl = 0.0
            if mid is not None and math.isfinite(float(mid)) and float(mid) > 0.0 and math.isfinite(float(ntl)) and float(ntl) > 0.0:
                try:
                    spot_name = _hl_spot_name_from_coin(str(coin), quote="USDC")
                    qty = float(_hl_round_sz_by_name(str(spot_name), float(ntl) / float(mid)))
                except Exception:
                    qty = None
        ok_spot = False
        spot_info: Dict[str, Any] = {}
        if qty is None or (not math.isfinite(float(qty))) or float(qty) <= 0.0:
            spot_info = {"ok": False, "err": "missing_spot_qty"}
            ok_spot = False
        else:
            try:
                data, code = _unpack_jsonify_resp(hyperliquid_spot_market_close_internal(coin=str(coin), qty=float(qty), execute=bool(do_exec), tag=str(tag) + "|spot", strategy_id="CarryTrade", ab_owner="carry"))
                spot_info = {"http": int(code), "resp": (data if isinstance(data, dict) else None)}
                ok_spot = bool(isinstance(data, dict) and bool(data.get("ok", False)) and int(code) < 500)
            except Exception as e:
                spot_info = {"ok": False, "err": str(e)}
                ok_spot = False
        p["last_close_spot"] = dict(spot_info)
        if ok_spot:
            if do_exec:
                p["status"] = "closing"
            else:
                p["status"] = "closed"
                p["closed_ts"] = int(now_ms)
            try:
                if coin:
                    cd_eff = int(cb_cooldown_ms) if str(reason) == "circuit_breaker" else int(cooldown_ms)
                    cd_by_coin[str(coin).upper()] = int(now_ms) + int(cd_eff)
            except Exception:
                pass
            p["hedge_stage"] = "closed"
        else:
            p["hedge_stage"] = "unhedged_perp"
            p["unhedge_ts"] = int(now_ms)
            p["unhedge_deadline_ts"] = int(now_ms) + int(unhedge_timeout_ms)
        _ev("close", {"pair": str(pair), "coin": str(coin), "reason": str(reason), "execute": bool(do_exec), "ok": bool(ok_spot), "leg": "both"})
        pos[pair] = p

    open_ok, open_reason = _carry_should_open_window(int(now_ms), int(next_ts), dict(cfg_eff))
    if (not bool(enabled_effective)):
        open_ok = False
        open_reason = "disabled"

    try:
        max_open_positions = int(cfg_eff.get("carry_trade_max_open_positions", CONFIG.get("carry_trade_max_open_positions", 1)) or 1)
    except Exception:
        max_open_positions = 1
    max_open_positions = max(0, min(20, int(max_open_positions)))
    have_open = len([p for p in active_pairs if p])
    slots = int(max(0, int(max_open_positions) - int(have_open)))

    if bool(rotate_enabled) and have_open > 0 and open_ok and isinstance(pool, list) and pool:
        in_no_exit = bool(_carry_in_no_exit_window(int(now_ms), int(next_ts), dict(cfg_eff)))
        active = None
        for pair0, p0 in pos.items():
            if not isinstance(p0, dict):
                continue
            if str(p0.get("venue") or "").strip().lower() != str(venue):
                continue
            if str(p0.get("mode") or "").strip().lower() != "hedge":
                continue
            if str(p0.get("status") or "").strip().lower() in ("open", "opened", "paper_opened"):
                active = (pair0, p0)
                break
        if active is not None:
            pair0, p0 = active
            coin0 = str(p0.get("coin") or "").strip().upper()
            cur_edge = 0.0
            try:
                cur_edge = float(((p0.get("candidate") or {}) if isinstance(p0.get("candidate"), dict) else {}).get("expected_edge") or 0.0)
            except Exception:
                cur_edge = 0.0
            best_new = None
            for x in pool:
                if not isinstance(x, dict) or bool(x.get("vetoed")):
                    continue
                if str(x.get("carry_side") or "").strip().lower() != "short":
                    continue
                coinx = str(x.get("coin") or "").strip().upper()
                if not coinx or coinx == coin0:
                    continue
                if float(x.get("expected_edge") or 0.0) < float(open_edge_thr):
                    continue
                best_new = x
                break
            if best_new is not None:
                try:
                    new_edge = float(best_new.get("expected_edge") or 0.0)
                except Exception:
                    new_edge = 0.0
                if (float(new_edge) - float(cur_edge)) >= float(rotate_edge_min):
                    try:
                        best_score = float(p0.get("best_timing_score") or 0.0)
                    except Exception:
                        best_score = 0.0
                    if not math.isfinite(float(best_score)):
                        best_score = 0.0
                    if float(best_score) <= 0.0:
                        try:
                            rows5 = ohlcv_fetch(coin=coin0, interval="5m", now_ms=int(now_ms), lookback_ms=6 * 60 * 60 * 1000, ttl_sec=10, timeout_sec=2.0)
                        except Exception:
                            rows5 = []
                        sc0 = _carry_best_timing_score_rows(rows5, carry_side="long")
                        try:
                            best_score = float(sc0.get("score") or 0.0)
                        except Exception:
                            best_score = 0.0
                        if not math.isfinite(float(best_score)):
                            best_score = 0.0
                        try:
                            p0["best_timing_score"] = float(best_score)
                        except Exception:
                            pass
                    score_ok = float(best_score) >= float(trig_score_thr)

                    held_ok = True
                    try:
                        et0 = int(p0.get("entry_ts") or 0)
                    except Exception:
                        et0 = 0
                    if et0 > 0 and int(min_hold_ms) > 0:
                        held_ok = (int(now_ms) - int(et0)) >= int(min_hold_ms)
                    if (not bool(held_ok)) and (not bool(strict_min_hold)) and bool(score_ok):
                        held_ok = True

                    net_ok = True
                    if bool(rotate_require_net):
                        try:
                            net_est = float(p0.get("net_pnl_usdc_est") or 0.0)
                        except Exception:
                            net_est = 0.0
                        net_ok = float(net_est) >= 0.0
                        if (not bool(net_ok)) and (not bool(strict_min_hold)) and bool(score_ok):
                            net_ok = True

                    can_rotate = True
                    can_rotate = bool(held_ok) and bool(net_ok)
                    if (not bool(can_rotate)) and (not bool(strict_min_hold)) and bool(score_ok):
                        can_rotate = True
                    if bool(in_no_exit) and (not bool(allow_pre_unhedge)) and (not bool(score_ok)):
                        can_rotate = False

                    if bool(can_rotate):
                        to_close_both.append((str(pair0), p0, "rotate"))
                        open_ok = False
                        open_reason = "rotate"

    try:
        open_top_k = int(cfg_eff.get("carry_trade_open_top_k", CONFIG.get("carry_trade_open_top_k", 1)) or 1)
    except Exception:
        open_top_k = 1
    open_top_k = max(0, min(20, int(open_top_k)))
    k_eff = min(int(open_top_k), int(slots))

    if open_ok and k_eff > 0:
        try:
            raw_notional = cfg_eff.get("carry_trade_notional_usdc")
            if raw_notional is None:
                raw_notional = CONFIG.get("carry_trade_notional_usdc")
            if raw_notional is None:
                raw_notional = CONFIG.get("entry_fixed_notional_usdc", 200.0)
            notional = float(raw_notional or 200.0)
        except Exception:
            notional = 200.0
        if not math.isfinite(float(notional)) or float(notional) <= 0.0:
            notional = 200.0

        picked: List[Dict[str, Any]] = []
        for x in (pool or []):
            if not isinstance(x, dict):
                continue
            if bool(x.get("vetoed")):
                continue
            if str(x.get("carry_side") or "").strip().lower() != "short":
                continue
            coin = str(x.get("coin") or "").strip().upper()
            if not coin:
                continue
            pair = f"{coin}-PERP"
            if pair in open_pos:
                continue
            if pair in active_pairs:
                continue
            cd_until = cd_by_coin.get(str(coin))
            try:
                cd_until_ms = int(cd_until) if cd_until is not None else 0
            except Exception:
                cd_until_ms = 0
            if cd_until_ms > 0 and int(now_ms) < int(cd_until_ms):
                continue
            edge0 = x.get("carry_edge")
            if edge0 is None:
                edge0 = x.get("expected_edge")
            if float(edge0 or 0.0) < float(open_edge_thr):
                continue
            picked.append(x)
            if len(picked) >= int(k_eff):
                break

        for x in picked:
            coin = str(x.get("coin") or "").strip().upper()
            pair = f"{coin}-PERP"
            tag = f"carry_open|{int(next_ts)}"
            do_exec = bool(execute)

            lev = None
            try:
                dyn_lev_enabled = bool(cfg_eff.get("carry_trade_hedge_dyn_leverage_enabled", CONFIG.get("carry_trade_hedge_dyn_leverage_enabled", False)))
                if bool(dyn_lev_enabled):
                    sp = None
                    try:
                        sp = float(x.get("spread_bps")) if x.get("spread_bps") is not None else None
                    except Exception:
                        sp = None
                    use_depth = bool(cfg_eff.get("carry_trade_hedge_leverage_use_depth", CONFIG.get("carry_trade_hedge_leverage_use_depth", False)))
                    dq = None
                    if bool(use_depth):
                        try:
                            wb = float(cfg_eff.get("carry_trade_hedge_leverage_depth_window_bps", CONFIG.get("carry_trade_hedge_leverage_depth_window_bps", 10.0)) or 10.0)
                        except Exception:
                            wb = 10.0
                        dq = _carry_hl_depth_quote_usd_quick(coin=str(coin), now_ms=int(now_ms), window_bps=float(wb))
                    lev = int(_carry_hedge_dyn_leverage(
                        coin=str(coin),
                        atr_pct_5m=(None if x.get("atr_pct_5m") is None else float(x.get("atr_pct_5m"))),
                        spread_bps=sp,
                        depth_quote_usd=dq,
                        notional_usdc=float(notional),
                        cfg=cfg_eff,
                    ))
                else:
                    lev = None
            except Exception:
                lev = None

            spot_symbol = None
            try:
                spot_symbol = str(_hl_spot_name_from_coin_checked(str(coin), quote="USDC"))
            except Exception as e:
                pos[pair] = {
                    "pair": str(pair),
                    "coin": str(coin),
                    "venue": str(venue),
                    "mode": "hedge",
                    "side": "short",
                    "notional_usdc": float(notional),
                    "perp_leverage": (None if lev is None else int(lev)),
                    "execute": bool(do_exec),
                    "status": "failed",
                    "entry_ts": int(now_ms),
                    "target_funding_ts": int(next_ts),
                    "open_resp": {"spot": {"http": 400, "resp": {"ok": False, "error": "invalid_spot_symbol", "detail": str(e)}}},
                    "candidate": dict(x),
                }
                _ev("open", {"pair": str(pair), "coin": str(coin), "mode": "hedge", "execute": bool(do_exec), "ok": False, "reason": "spot_not_supported"})
                continue

            spot_data: Dict[str, Any] = {}
            spot_code = 0
            ok_spot = False
            try:
                spot_data, spot_code = _unpack_jsonify_resp(hyperliquid_spot_market_open_internal(coin=str(coin), notional_usdc=float(notional), execute=bool(do_exec), tag=str(tag) + "|spot", quote="USDC", strategy_id="CarryTrade", ab_owner="carry", skip_gate=True))
                ok_spot = bool(isinstance(spot_data, dict) and bool(spot_data.get("ok", False)) and int(spot_code) < 500)
                if bool(ok_spot):
                    pf = None
                    try:
                        od = spot_data.get("order") if isinstance(spot_data, dict) else None
                        ex0 = (od.get("exec") if isinstance(od, dict) and isinstance(od.get("exec"), dict) else None)
                        if isinstance(ex0, dict):
                            pf = ex0.get("preflight_error") if ex0.get("preflight_error") is not None else ex0.get("error")
                    except Exception:
                        pf = None
                    if pf is not None:
                        ok_spot = False
            except Exception as e:
                spot_data = {"ok": False, "err": str(e)}
                ok_spot = False
            if not bool(ok_spot):
                pos[pair] = {
                    "pair": str(pair),
                    "coin": str(coin),
                    "venue": str(venue),
                    "mode": "hedge",
                    "side": "short",
                    "notional_usdc": float(notional),
                    "perp_leverage": (None if lev is None else int(lev)),
                    "execute": bool(do_exec),
                    "status": "failed",
                    "entry_ts": int(now_ms),
                    "target_funding_ts": int(next_ts),
                    "open_resp": {"spot": dict(spot_data), "spot_http": (None if int(spot_code) <= 0 else int(spot_code))},
                    "candidate": dict(x),
                }
                _ev("open", {"pair": str(pair), "coin": str(coin), "mode": "hedge", "execute": bool(do_exec), "ok": False, "reason": "spot_failed"})
                continue

            perp_data = None
            perp_code = 0
            ok_perp = False
            rollback = None
            try:
                perp_data, perp_code = _unpack_jsonify_resp(hyperliquid_market_open_internal(coin=str(coin), side="short", notional_usdc=float(notional), execute=bool(do_exec), tag=str(tag), strategy_id="CarryTrade", ab_owner="carry", leverage=lev, skip_gate=True))
            except Exception as e:
                perp_data = {"ok": False, "error": str(e)}
                perp_code = 500
            if isinstance(perp_data, dict):
                ok_perp = bool(perp_data.get("ok", False)) and int(perp_code) < 500

            if (not bool(ok_perp)) and bool(do_exec):
                rb_qty = None
                try:
                    od = spot_data.get("order") if isinstance(spot_data, dict) else None
                    if isinstance(od, dict):
                        if od.get("executedQty") is not None:
                            rb_qty = float(_to_float(od.get("executedQty"), 0.0))
                        if rb_qty is None and (od.get("exec") is not None or od.get("sz") is not None):
                            ex0 = od.get("exec") if isinstance(od.get("exec"), dict) else od
                            if isinstance(ex0, dict) and ex0.get("sz") is not None:
                                rb_qty = float(_to_float(ex0.get("sz"), 0.0))
                except Exception:
                    rb_qty = None
                if rb_qty is None:
                    try:
                        rb_qty = float(_hl_spot_size_from_notional_usdc(str(coin), float(notional), quote="USDC"))
                    except Exception:
                        rb_qty = None
                if rb_qty is not None and math.isfinite(float(rb_qty)) and float(rb_qty) > 0.0:
                    try:
                        rb_data, rb_code = _unpack_jsonify_resp(hyperliquid_spot_market_close_internal(coin=str(coin), qty=float(rb_qty), execute=True, tag=str(tag) + "|rollback_spot", quote="USDC", strategy_id="CarryTrade", ab_owner="carry"))
                        rollback = {"http": int(rb_code), "resp": rb_data}
                    except Exception as e:
                        rollback = {"http": 0, "error": str(e)}

            mid0 = _carry_mid_px(str(coin), str(venue))
            spot_qty = None
            spot_quote = None
            try:
                od = spot_data.get("order") if isinstance(spot_data, dict) else None
                if isinstance(od, dict):
                    if od.get("executedQty") is not None:
                        spot_qty = float(_to_float(od.get("executedQty"), 0.0))
                    if od.get("cummulativeQuoteQty") is not None:
                        spot_quote = float(_to_float(od.get("cummulativeQuoteQty"), 0.0))
                    if spot_qty is None and (od.get("exec") is not None or od.get("sz") is not None):
                        ex0 = od.get("exec") if isinstance(od.get("exec"), dict) else od
                        if isinstance(ex0, dict):
                            if ex0.get("sz") is not None:
                                spot_qty = float(_to_float(ex0.get("sz"), 0.0))
                            if ex0.get("notional_usdc") is not None:
                                spot_quote = float(_to_float(ex0.get("notional_usdc"), 0.0))
            except Exception:
                spot_qty = None
                spot_quote = None
            pos[pair] = {
                "pair": str(pair),
                "coin": str(coin),
                "venue": str(venue),
                "mode": "hedge",
                "side": "short",
                "notional_usdc": float(notional),
                "perp_leverage": (None if lev is None else int(lev)),
                "execute": bool(do_exec),
                "status": ("opened" if bool(do_exec) else "paper_opened") if (bool(ok_perp) and bool(ok_spot)) else "failed",
                "hedge_stage": ("hedged" if (bool(ok_perp) and bool(ok_spot)) else "failed"),
                "entry_ts": int(now_ms),
                "target_funding_ts": int(next_ts),
                "entry_mid": (None if mid0 is None else float(mid0)),
                "spot": {
                    "symbol": (spot_symbol if spot_symbol is not None else str(coin)),
                    "entry_mid": (None if mid0 is None else float(mid0)),
                    "qty": (None if spot_qty is None else float(spot_qty)),
                    "quote": (None if spot_quote is None else float(spot_quote)),
                    "open": dict(spot_data),
                },
                "order_id": (None if not isinstance(perp_data, dict) else perp_data.get("order_id")),
                "open_resp": {"perp": {"http": int(perp_code), "resp": perp_data}, "spot": dict(spot_data), "spot_http": (None if int(spot_code) <= 0 else int(spot_code)), "rollback": (None if rollback is None else dict(rollback))},
                "candidate": dict(x),
            }
            _ev("open", {"pair": str(pair), "coin": str(coin), "mode": "hedge", "execute": bool(do_exec), "ok": bool(ok_perp and ok_spot), "reason": (str(open_reason) if bool(ok_perp and ok_spot) else "perp_failed")})

    state["tick_ts"] = int(now_ms)
    state["venue"] = str(venue)
    state["enabled_effective"] = bool(enabled_effective)
    state["sandbox"] = bool(sandbox)
    state["execute"] = bool(execute)
    state["gate"] = dict(gate)
    state["profile"] = (None if not isinstance(eff, dict) else str(eff.get("profile") or ""))
    state["next_funding_ts"] = int(next_ts)
    state["last_funding_ts"] = int(last_ts)
    state["open_window"] = {"ok": bool(open_ok), "reason": str(open_reason)}
    state["positions_count"] = int(len([1 for p in pos.values() if isinstance(p, dict) and str(p.get("venue") or "").lower() == str(venue) and str(p.get("mode") or "").lower() == "hedge" and str(p.get("status") or "").lower() in ("open", "opened", "paper_opened", "closing")]))
    return {
        "ok": True,
        "ts": int(now_ms),
        "venue": str(venue),
        "enabled_effective": bool(enabled_effective),
        "sandbox": bool(sandbox),
        "execute": bool(execute),
        "pool_ts": int(state.get("pool_ts") or 0),
        "pool_n": int(len(state.get("pool") or [])) if isinstance(state.get("pool"), list) else 0,
        "positions_count": int(state.get("positions_count") or 0),
        "open_window": dict(state.get("open_window") or {}),
    }


def _carry_trade_tick(now_ms: int) -> Dict[str, Any]:
    now_ms = int(now_ms)
    state = _carry_state_get()
    base_venue = "hyperliquid"

    try:
        state["step"] = "start"
        state["step_ts"] = int(now_ms)
    except Exception:
        pass

    eff0 = _carry_cfg_effective(int(now_ms), venue=str(base_venue))
    cfg_eff0 = (eff0.get("cfg_effective") if isinstance(eff0, dict) else None)
    cfg_eff0 = (cfg_eff0 if isinstance(cfg_eff0, dict) else {})
    venue_eff = "hyperliquid"

    eff = eff0
    if str(venue_eff) != str(base_venue):
        eff = _carry_cfg_effective(int(now_ms), venue=str(venue_eff))
    cfg_eff = (eff.get("cfg_effective") if isinstance(eff, dict) else None)
    cfg_eff = (cfg_eff if isinstance(cfg_eff, dict) else {})
    gate = (eff.get("gate") if isinstance(eff, dict) else None)
    gate = (gate if isinstance(gate, dict) else {})

    carry_mode = str(cfg_eff.get("carry_trade_mode", "perp") or "perp").strip().lower() or "perp"

    venue = "hyperliquid"
    enabled_effective = bool(gate.get("enabled_effective", bool(cfg_eff.get("carry_trade_enabled", False))))
    sandbox = bool(cfg_eff.get("carry_trade_sandbox", True))
    execute = bool(enabled_effective) and (not bool(sandbox)) and bool(_carry_execute_allowed(str(venue)))

    if str(carry_mode) == "hedge":
        return _carry_trade_tick_hedge(
            now_ms=int(now_ms),
            state=state,
            venue=str(venue),
            eff=dict(eff) if isinstance(eff, dict) else {},
            cfg_eff=dict(cfg_eff),
            gate=dict(gate),
            enabled_effective=bool(enabled_effective),
            sandbox=bool(sandbox),
            execute=bool(execute),
        )

    clk = _carry_funding_clock(int(now_ms), str(venue))
    try:
        next_ts = int(clk.get("next_ts") or 0)
    except Exception:
        next_ts = 0
    try:
        last_ts = int(clk.get("last_ts") or 0)
    except Exception:
        last_ts = 0

    minutes_to_next = 0.0
    try:
        if int(next_ts) > 0:
            minutes_to_next = float(int(next_ts) - int(now_ms)) / 60_000.0
    except Exception:
        minutes_to_next = 0.0
    window_state = _carry_window_state(float(minutes_to_next))
    state["window_state"] = str(window_state)

    try:
        post_grace = float(cfg_eff.get("carry_trade_post_funding_grace_min", CONFIG.get("carry_trade_post_funding_grace_min", 1)) or 1)
    except Exception:
        post_grace = 1.0
    post_grace = float(_clip(float(post_grace), 0.0, 10.0))
    post_grace_ms = int(round(float(post_grace) * 60_000.0))

    cooldown_min = None
    try:
        cooldown_min = float(cfg_eff.get("carry_trade_cooldown_min", CONFIG.get("carry_trade_cooldown_min", 10)) or 10)
    except Exception:
        cooldown_min = 10.0
    cooldown_min = float(_clip(float(cooldown_min), 0.0, 10_000.0))
    cooldown_ms = int(round(float(cooldown_min) * 60_000.0))

    try:
        emergency_r = float(cfg_eff.get("carry_trade_emergency_stoploss_r", CONFIG.get("carry_trade_emergency_stoploss_r", -0.015)) or -0.015)
    except Exception:
        emergency_r = -0.015
    if not math.isfinite(float(emergency_r)):
        emergency_r = -0.015

    dyn_emergency_enabled = bool(cfg_eff.get("carry_trade_emergency_stoploss_dynamic_enabled", CONFIG.get("carry_trade_emergency_stoploss_dynamic_enabled", True)))
    try:
        dyn_emergency_mult = float(cfg_eff.get("carry_trade_emergency_stoploss_atr_mult", CONFIG.get("carry_trade_emergency_stoploss_atr_mult", 2.0)) or 2.0)
    except Exception:
        dyn_emergency_mult = 2.0
    dyn_emergency_mult = float(_clip(float(dyn_emergency_mult), 0.1, 20.0))
    try:
        dyn_emergency_min_r = float(cfg_eff.get("carry_trade_emergency_stoploss_min_r", CONFIG.get("carry_trade_emergency_stoploss_min_r", -0.08)) or -0.08)
    except Exception:
        dyn_emergency_min_r = -0.08
    try:
        dyn_emergency_max_r = float(cfg_eff.get("carry_trade_emergency_stoploss_max_r", CONFIG.get("carry_trade_emergency_stoploss_max_r", -0.008)) or -0.008)
    except Exception:
        dyn_emergency_max_r = -0.008
    if dyn_emergency_min_r > dyn_emergency_max_r:
        dyn_emergency_min_r, dyn_emergency_max_r = dyn_emergency_max_r, dyn_emergency_min_r

    pool_refresh_s = None
    try:
        pool_refresh_s = float(cfg_eff.get("carry_trade_pool_refresh_seconds", CONFIG.get("carry_trade_pool_refresh_seconds", 900)) or 900)
    except Exception:
        pool_refresh_s = 900.0
    pool_refresh_s = float(_clip(float(pool_refresh_s), 5.0, 3600.0))

    pos = _carry_positions_get()

    if execute or any((isinstance(v, dict) and str(v.get("venue") or "").lower() == str(venue)) for v in pos.values()):
        try:
            if str(venue) in ("hyperliquid", "hl"):
                last_sync_ts = 0
                try:
                    hl_st = TRACKER_STATE.get("hl")
                    if isinstance(hl_st, dict):
                        last_sync_ts = int(hl_st.get("last_sync_ts") or 0)
                except Exception:
                    last_sync_ts = 0
                if last_sync_ts <= 0 or (int(now_ms) - int(last_sync_ts)) >= 10_000:
                    def _bg_sync_hl():
                        with app.app_context():
                            try:
                                _hl_sync_record(update_orders=False, trigger="carry.tick.autosync", trace_id=None)
                            except Exception:
                                pass
                    threading.Thread(target=_bg_sync_hl, daemon=True).start()
        except Exception:
            pass

    open_pos = (TRACKER_STATE.get("carry_open_positions") or {})
    if not isinstance(open_pos, dict):
        open_pos = {}

    events = state.get("events")
    if not isinstance(events, list):
        events = []
        state["events"] = events
    while len(events) > 200:
        try:
            events.pop(0)
        except Exception:
            break

    def _ev(kind: str, payload: Dict[str, Any]):
        try:
            base = {
                "ts": int(now_ms),
                "kind": str(kind),
                "strategy_id": "carry_trade",
                "strategy_version": "1.0.0",
                "group_id": f"carry_{str(venue)}",
                "feature_set_id": "carry_v1",
            }
            base.update(dict(payload or {}))
            events.append(base)
        except Exception:
            pass

    pool_ts = None
    try:
        pool_ts = int(state.get("pool_ts") or 0)
    except Exception:
        pool_ts = 0
    pool_age_ms = int(now_ms) - int(pool_ts)
    pool = state.get("pool")
    if not isinstance(pool, list):
        pool = []
    if pool_ts <= 0 or pool_age_ms >= int(pool_refresh_s * 1000.0):
        try:
            n_pool = int(cfg_eff.get("carry_trade_candidates_top_n", CONFIG.get("carry_trade_candidates_top_n", 10)) or 10)
        except Exception:
            n_pool = 10
        n_pool = max(1, min(200, int(n_pool)))
        try:
            pool = _carry_candidates_hl(int(now_ms), int(n_pool), cfg=dict(cfg_eff))
        except Exception:
            pool = []
        state["pool"] = pool
        state["pool_ts"] = int(now_ms)

    for pair, p in list(pos.items()):
        if not isinstance(p, dict):
            continue
        if str(p.get("venue") or "").strip().lower() != str(venue):
            continue
        if bool(p.get("execute", False)):
            if pair in open_pos and isinstance(open_pos.get(pair), dict):
                try:
                    p["unrealized_pnl_pct"] = float(open_pos[pair].get("unrealized_pnl_pct") or 0.0)
                except Exception:
                    pass
                p["is_open"] = True
            else:
                st0 = str(p.get("status") or "").strip().lower()
                if st0 in ("closing", "open", "opened", "paper_opened"):
                    p["is_open"] = False
                    p["status"] = "closed"
                    p["closed_ts"] = int(now_ms)
                    try:
                        coin0 = str(p.get("coin") or "")
                        if coin0:
                            state.setdefault("cooldown_by_coin", {})
                            cd = state.get("cooldown_by_coin")
                            if isinstance(cd, dict):
                                cd[str(coin0).upper()] = int(now_ms) + int(cooldown_ms)
                    except Exception:
                        pass
        else:
            mid = _carry_mid_px(str(p.get("coin") or ""), str(venue))
            if mid is not None:
                try:
                    p["last_mid"] = float(mid)
                except Exception:
                    pass
                try:
                    entry_mid = float(p.get("entry_mid") or 0.0)
                    if entry_mid > 0.0:
                        side = str(p.get("side") or "long").lower()
                        r = (float(mid) / float(entry_mid) - 1.0)
                        if side == "short":
                            r = -float(r)
                        p["unrealized_pnl_pct"] = float(r)
                except Exception:
                    pass

        pos[pair] = p

    to_reduce: List[Tuple[str, Dict[str, Any], str, float]] = []
    to_close: List[Tuple[str, Dict[str, Any], str]] = []
    for pair, p in list(pos.items()):
        if not isinstance(p, dict):
            continue
        if str(p.get("venue") or "").strip().lower() != str(venue):
            continue
        st0 = str(p.get("status") or "").strip().lower()
        if st0 not in ("open", "opened", "paper_opened", "closing"):
            continue
        coin = str(p.get("coin") or "").strip().upper()
        if not coin:
            continue
        pnl_pct = None
        try:
            pnl_pct = float(p.get("unrealized_pnl_pct")) if p.get("unrealized_pnl_pct") is not None else None
        except Exception:
            pnl_pct = None
        emergency_r_eff = float(emergency_r)
        if bool(dyn_emergency_enabled) and pnl_pct is not None and math.isfinite(float(pnl_pct)):
            atr_pct = None
            try:
                cand = p.get("candidate")
                if isinstance(cand, dict):
                    atr_pct = cand.get("atr_pct_5m")
            except Exception:
                atr_pct = None
            if atr_pct is None and str(venue) in ("hyperliquid", "hl"):
                try:
                    rows5 = _carry_hl_fetch_ohlcv_rows_quick(coin=coin, interval="5m", now_ms=int(now_ms), lookback_ms=6 * 60 * 60 * 1000, ttl_sec=8, timeout_sec=2.0)
                    atr_pct = _carry_atr_pct(rows5, n=14)
                except Exception:
                    atr_pct = None
            try:
                if atr_pct is not None and math.isfinite(float(atr_pct)) and float(atr_pct) > 0.0:
                    r_dyn = -abs(float(atr_pct)) * float(dyn_emergency_mult)
                    emergency_r_eff = float(min(float(emergency_r_eff), float(r_dyn)))
            except Exception:
                pass
        emergency_r_eff = float(_clip(float(emergency_r_eff), float(dyn_emergency_min_r), float(dyn_emergency_max_r)))
        try:
            p["emergency_r_eff"] = float(emergency_r_eff)
        except Exception:
            pass
        emergency = (pnl_pct is not None and math.isfinite(float(pnl_pct)) and float(pnl_pct) <= float(emergency_r_eff))

        tgt_ts = None
        try:
            tgt_ts = int(p.get("target_funding_ts") or 0)
        except Exception:
            tgt_ts = 0
        post_due = (tgt_ts > 0 and int(now_ms) >= int(tgt_ts) + int(post_grace_ms))

        hard_disable = (not bool(enabled_effective)) and (bool(gate.get("paused")) or str(gate.get("reason") or "").strip().lower() in ("pnl_drawdown", "regime_panic", "regime_panic_pause", "paused"))
        soft_disable = (not bool(enabled_effective)) and (not bool(hard_disable))

        if emergency:
            to_close.append((pair, p, "emergency"))
            continue
        if hard_disable:
            to_close.append((pair, p, "hard_disable"))
            continue
        if post_due:
            hold, why = _carry_post_funding_trailing_step(int(now_ms), p, dict(cfg_eff), str(venue))
            pos[pair] = p
            if not bool(hold):
                to_close.append((pair, p, str(why or "post_funding_exit")))
            continue
        if soft_disable:
            in_no_exit = bool(_carry_in_no_exit_window(int(now_ms), int(next_ts), dict(cfg_eff)))
            if not bool(in_no_exit):
                to_close.append((pair, p, "disabled"))
                continue

            try:
                reduce_enabled = bool(cfg_eff.get("carry_trade_soft_no_exit_reduce_enabled", CONFIG.get("carry_trade_soft_no_exit_reduce_enabled", False)))
            except Exception:
                reduce_enabled = False
            if not bool(reduce_enabled):
                continue

            try:
                cd_sec = int(cfg_eff.get("carry_trade_soft_no_exit_reduce_cooldown_sec", CONFIG.get("carry_trade_soft_no_exit_reduce_cooldown_sec", 900)) or 900)
            except Exception:
                cd_sec = 900
            cd_sec = max(0, min(24 * 3600, int(cd_sec)))
            last_reduce_ts = 0
            try:
                last_reduce_ts = int(p.get("soft_no_exit_reduce_ts") or 0)
            except Exception:
                last_reduce_ts = 0
            if last_reduce_ts > 0 and (int(now_ms) - int(last_reduce_ts)) < int(cd_sec) * 1000:
                continue

            try:
                reduce_frac = float(cfg_eff.get("carry_trade_soft_no_exit_reduce_frac", CONFIG.get("carry_trade_soft_no_exit_reduce_frac", 0.5)) or 0.5)
            except Exception:
                reduce_frac = 0.5
            reduce_frac = float(_clip(float(reduce_frac), 0.05, 0.95))

            spike_detected = False
            try:
                spike_required = bool(cfg_eff.get("carry_trade_soft_no_exit_reduce_spike_required", CONFIG.get("carry_trade_soft_no_exit_reduce_spike_required", True)))
            except Exception:
                spike_required = True
            if bool(spike_required):
                try:
                    sg = _carry_1m_spike_gate(str(coin), int(now_ms))
                except Exception:
                    sg = {"ok": True}
                spike_detected = (not bool(sg.get("ok", True)))
                if not bool(spike_detected):
                    continue

            spread_bps = None
            try:
                spread_bps = _carry_hl_spread_bps_quick(coin=str(coin), now_ms=int(now_ms))
            except Exception:
                spread_bps = None
            spread_high = False
            try:
                max_spread_bps = float(cfg_eff.get("carry_trade_max_spread_bps", CONFIG.get("carry_trade_max_spread_bps", 15)) or 15)
            except Exception:
                max_spread_bps = 15.0
            try:
                spread_mult = float(cfg_eff.get("carry_trade_soft_no_exit_reduce_spread_mult", CONFIG.get("carry_trade_soft_no_exit_reduce_spread_mult", 1.2)) or 1.2)
            except Exception:
                spread_mult = 1.2
            spread_mult = float(_clip(float(spread_mult), 1.0, 5.0))
            if spread_bps is not None and math.isfinite(float(spread_bps)) and float(max_spread_bps) > 0.0:
                spread_high = float(spread_bps) >= float(max_spread_bps) * float(spread_mult)
            if (not bool(spike_detected)) and (not bool(spread_high)):
                continue

            base_sz = None
            try:
                meta = open_pos.get(pair)
                if isinstance(meta, dict):
                    if meta.get("hl_szi") is not None:
                        base_sz = abs(float(meta.get("hl_szi") or 0.0))
                    elif meta.get("base_qty") is not None:
                        base_sz = abs(float(meta.get("base_qty") or 0.0))
            except Exception:
                base_sz = None
            if base_sz is None or (not math.isfinite(float(base_sz))) or float(base_sz) <= 0.0:
                continue
            reduce_sz = float(base_sz) * float(reduce_frac)
            if (not math.isfinite(float(reduce_sz))) or float(reduce_sz) <= 0.0:
                continue
            to_reduce.append((pair, p, "soft_no_exit", float(reduce_sz)))
            continue

    cost_adaptive_enabled = bool(cfg_eff.get("carry_trade_cost_buffer_adaptive_enabled", False))

    for pair, p, reason, reduce_sz in to_reduce:
        st0 = str(p.get("status") or "").strip().lower()
        if st0 == "closing":
            continue
        coin = str(p.get("coin") or "").strip().upper()
        do_exec = bool(p.get("execute", False))
        tag = f"carry_reduce|{reason}"
        reduce_ok = False
        reduce_info: Dict[str, Any] = {}
        try:
            if bool(cost_adaptive_enabled) and str(venue) in ("hyperliquid", "hl"):
                _carry_cost_sample_add(int(now_ms), str(coin), _carry_hl_spread_bps_quick(coin=str(coin), now_ms=int(now_ms)), "reduce")
        except Exception:
            pass
        try:
            data, code = _unpack_jsonify_resp(hyperliquid_market_close_internal(coin=str(coin), execute=bool(do_exec), tag=str(tag), sz=float(reduce_sz), exit_owner="carry_trade", force=False))
            reduce_info = {"http": int(code), "resp": (data if isinstance(data, dict) else None), "sz": float(reduce_sz)}
            if isinstance(data, dict) and bool(data.get("ok", True)) and int(code) < 500:
                reduce_ok = True
        except Exception as e:
            reduce_info = {"error": str(e), "sz": float(reduce_sz)}
            reduce_ok = False
        p["last_reduce"] = dict(reduce_info)
        if reduce_ok:
            try:
                p["soft_no_exit_reduce_ts"] = int(now_ms)
            except Exception:
                pass
        _ev("reduce", {"pair": str(pair), "coin": str(coin), "reason": str(reason), "execute": bool(do_exec), "ok": bool(reduce_ok), "sz": float(reduce_sz)})
        pos[pair] = p

    for pair, p, reason in to_close:
        st0 = str(p.get("status") or "").strip().lower()
        if st0 == "closing":
            continue
        coin = str(p.get("coin") or "").strip().upper()
        do_exec = bool(p.get("execute", False))
        tag = f"carry_close|{reason}"
        close_ok = False
        close_info: Dict[str, Any] = {}
        try:
            if bool(cost_adaptive_enabled) and str(venue) in ("hyperliquid", "hl"):
                _carry_cost_sample_add(int(now_ms), str(coin), _carry_hl_spread_bps_quick(coin=str(coin), now_ms=int(now_ms)), "close")
        except Exception:
            pass
        try:
            data, code = _unpack_jsonify_resp(hyperliquid_market_close_internal(coin=str(coin), execute=bool(do_exec), tag=str(tag), sz=None, exit_owner="carry_trade", force=bool(reason in ("emergency", "hard_disable"))))
            close_info = {"http": int(code), "resp": (data if isinstance(data, dict) else None)}
            if isinstance(data, dict) and bool(data.get("ok", True)) and int(code) < 500:
                close_ok = True
        except Exception as e:
            close_info = {"error": str(e)}
            close_ok = False

        p["last_close"] = dict(close_info)
        if close_ok:
            if do_exec:
                p["status"] = "closing"
            else:
                p["status"] = "closed"
                p["closed_ts"] = int(now_ms)
            try:
                if coin:
                    state.setdefault("cooldown_by_coin", {})
                    cd = state.get("cooldown_by_coin")
                    if isinstance(cd, dict):
                        cd[str(coin).upper()] = int(now_ms) + int(cooldown_ms)
            except Exception:
                pass
        _ev("close", {"pair": str(pair), "coin": str(coin), "reason": str(reason), "execute": bool(do_exec), "ok": bool(close_ok)})
        pos[pair] = p

    open_ok, open_reason = _carry_should_open_window(int(now_ms), int(next_ts), dict(cfg_eff))
    if (not bool(enabled_effective)):
        open_ok = False
        open_reason = "disabled"

    cd_by_coin = state.get("cooldown_by_coin")
    if not isinstance(cd_by_coin, dict):
        cd_by_coin = {}
        state["cooldown_by_coin"] = cd_by_coin

    active_pairs = set()
    for pair, p in pos.items():
        if not isinstance(p, dict):
            continue
        if str(p.get("venue") or "").strip().lower() != str(venue):
            continue
        if str(p.get("status") or "").strip().lower() in ("open", "opened", "paper_opened", "closing"):
            active_pairs.add(str(pair))

    try:
        max_open_positions = int(cfg_eff.get("carry_trade_max_open_positions", CONFIG.get("carry_trade_max_open_positions", 1)) or 1)
    except Exception:
        max_open_positions = 1
    max_open_positions = max(0, min(20, int(max_open_positions)))
    have_open = len([p for p in active_pairs if p])
    slots = int(max(0, int(max_open_positions) - int(have_open)))

    corr_hit = False
    try:
        corr_thr = float(cfg_eff.get("carry_trade_corr_threshold", CONFIG.get("carry_trade_corr_threshold", 0.80)) or 0.80)
    except Exception:
        corr_thr = 0.80
    corr_thr = float(_clip(float(corr_thr), 0.0, 1.0))
    for x in pool:
        try:
            if not isinstance(x, dict) or bool(x.get("vetoed")):
                continue
            cm = x.get("corr_max_abs")
            if cm is not None and math.isfinite(float(cm)) and float(cm) >= float(corr_thr):
                corr_hit = True
                break
        except Exception:
            continue
    try:
        open_top_k = int(cfg_eff.get("carry_trade_open_top_k", CONFIG.get("carry_trade_open_top_k", 1)) or 1)
    except Exception:
        open_top_k = 1
    open_top_k = max(0, min(20, int(open_top_k)))
    if corr_hit:
        open_top_k = min(int(open_top_k), 1)
    k_eff = min(int(open_top_k), int(slots))

    if open_ok and k_eff > 0:
        try:
            notional = float(CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0)
        except Exception:
            notional = 200.0
        if not math.isfinite(float(notional)) or float(notional) <= 0.0:
            notional = 200.0

        picked: List[Dict[str, Any]] = []
        for x in (pool or []):
            if not isinstance(x, dict):
                continue
            if bool(x.get("vetoed")):
                continue
            coin = str(x.get("coin") or "").strip().upper()
            if not coin:
                continue
            pair = f"{coin}-PERP"
            if pair in open_pos:
                continue
            if pair in active_pairs:
                continue
            cd_until = cd_by_coin.get(str(coin))
            try:
                cd_until_ms = int(cd_until) if cd_until is not None else 0
            except Exception:
                cd_until_ms = 0
            if cd_until_ms > 0 and int(now_ms) < int(cd_until_ms):
                continue
            if float(x.get("expected_edge") or 0.0) < float(open_edge_thr):
                continue
            picked.append(x)
            if len(picked) >= int(k_eff):
                break

        for x in picked:
            coin = str(x.get("coin") or "").strip().upper()
            side = str(x.get("carry_side") or "").strip().lower()
            if side not in ("long", "short"):
                continue
            pair = f"{coin}-PERP"
            tag = f"carry_open|{int(next_ts)}"
            do_exec = bool(execute)
            out_data = None
            http_code = 0
            ok_open = False
            try:
                if bool(cost_adaptive_enabled) and str(venue) in ("hyperliquid", "hl"):
                    _carry_cost_sample_add(int(now_ms), str(coin), _carry_hl_spread_bps_quick(coin=str(coin), now_ms=int(now_ms)), "open")
            except Exception:
                pass
            try:
                out_data, http_code = _unpack_jsonify_resp(hyperliquid_market_open_internal(coin=str(coin), side=str(side), notional_usdc=float(notional), execute=bool(do_exec), tag=str(tag), strategy_id="CarryTrade", ab_owner="carry"))
            except Exception as e:
                out_data = {"ok": False, "error": str(e)}
                http_code = 500
            if isinstance(out_data, dict):
                ok_open = bool(out_data.get("ok", False)) and int(http_code) < 500
            mid0 = _carry_mid_px(str(coin), str(venue))
            pos[pair] = {
                "pair": str(pair),
                "coin": str(coin),
                "venue": str(venue),
                "side": str(side),
                "notional_usdc": float(notional),
                "execute": bool(do_exec),
                "status": ("opened" if bool(do_exec) else "paper_opened") if ok_open else "failed",
                "entry_ts": int(now_ms),
                "target_funding_ts": int(next_ts),
                "entry_mid": (None if mid0 is None else float(mid0)),
                "order_id": (None if not isinstance(out_data, dict) else out_data.get("order_id")),
                "open_resp": {"http": int(http_code), "resp": out_data},
                "candidate": dict(x),
            }
            _ev("open", {"pair": str(pair), "coin": str(coin), "side": str(side), "execute": bool(do_exec), "ok": bool(ok_open), "reason": str(open_reason)})

    state["tick_ts"] = int(now_ms)
    state["venue"] = str(venue)
    state["enabled_effective"] = bool(enabled_effective)
    state["sandbox"] = bool(sandbox)
    state["execute"] = bool(execute)
    state["gate"] = dict(gate)
    state["profile"] = (None if not isinstance(eff, dict) else str(eff.get("profile") or ""))
    state["next_funding_ts"] = int(next_ts)
    state["last_funding_ts"] = int(last_ts)
    state["open_window"] = {"ok": bool(open_ok), "reason": str(open_reason)}
    state["positions_count"] = int(len([1 for p in pos.values() if isinstance(p, dict) and str(p.get("venue") or "").lower() == str(venue) and str(p.get("status") or "").lower() in ("open", "opened", "paper_opened", "closing")]))
    return {
        "ok": True,
        "ts": int(now_ms),
        "venue": str(venue),
        "enabled_effective": bool(enabled_effective),
        "sandbox": bool(sandbox),
        "execute": bool(execute),
        "pool_ts": int(state.get("pool_ts") or 0),
        "pool_n": int(len(state.get("pool") or [])) if isinstance(state.get("pool"), list) else 0,
        "positions_count": int(state.get("positions_count") or 0),
        "open_window": dict(state.get("open_window") or {}),
    }


def _carry_trade_tick_safe(now_ms: int) -> Dict[str, Any]:
    now_ms = int(now_ms)
    st = _carry_state_get()
    try:
        st["tick_ts"] = int(now_ms)
    except Exception:
        pass
    try:
        out = _carry_trade_tick(now_ms=int(now_ms))
        try:
            if isinstance(out, dict) and bool(out.get("ok")):
                st["step"] = "idle"
                st["step_ts"] = int(now_ms)
                st["last_error"] = None
        except Exception:
            pass
        return out
    except Exception as e:
        try:
            st["tick_ts"] = int(now_ms)
        except Exception:
            pass
        try:
            st["last_error"] = {"ts": int(now_ms), "error": str(e)}
        except Exception:
            pass
        try:
            st["step"] = "error"
            st["step_ts"] = int(now_ms)
        except Exception:
            pass
        try:
            v0 = str(st.get("venue") or CONFIG.get("carry_trade_venue") or "hyperliquid")
        except Exception:
            v0 = "hyperliquid"
        return {"ok": False, "ts": int(now_ms), "venue": str(v0), "error": str(e)}


@app.route("/legacy/carry/status", methods=["GET"])
def carry_status():
    now_ms = int(_now_ms())
    venue_eff = "hyperliquid"
    eff = _carry_cfg_effective(int(now_ms), venue=str(venue_eff))
    cfg_eff = (eff.get("cfg_effective") if isinstance(eff, dict) else None)
    cfg_eff = (cfg_eff if isinstance(cfg_eff, dict) else {})
    carry_mode = str(cfg_eff.get("carry_trade_mode", "perp") or "perp").strip().lower() or "perp"

    clk = _carry_funding_clock(int(now_ms), str(venue_eff))
    minutes_to_next = 0.0
    try:
        if int(clk.get("next_ts") or 0) > 0:
            minutes_to_next = (float(int(clk.get("next_ts") or 0) - int(now_ms))) / 60_000.0
    except Exception:
        minutes_to_next = 0.0

    pnl = _carry_pnl_breakdown(int(now_ms), venue=str(clk.get("venue") or venue_eff), cfg=dict(cfg_eff))
    try:
        _carry_funding_ledger_tick(int(now_ms), dict(clk), dict(pnl) if isinstance(pnl, dict) else {})
    except Exception:
        pass
    try:
        funding_income = _carry_funding_income_view(int(now_ms), dict(clk), dict(pnl) if isinstance(pnl, dict) else {})
    except Exception:
        funding_income = {"ok": False}
    eng = _carry_state_get()
    eng_view = {
        "tick_ts": (None if not isinstance(eng, dict) else eng.get("tick_ts")),
        "pool_ts": (None if not isinstance(eng, dict) else eng.get("pool_ts")),
        "pool_n": (None if not isinstance(eng, dict) else (len(eng.get("pool") or []) if isinstance(eng.get("pool"), list) else None)),
        "pool_refreshing": (None if not isinstance(eng, dict) else eng.get("pool_refreshing")),
        "pool_refreshing_ok": (None if not isinstance(eng, dict) else eng.get("pool_refreshing_ok")),
        "pool_last_error": (None if not isinstance(eng, dict) else eng.get("pool_last_error")),
        "positions_count": (None if not isinstance(eng, dict) else eng.get("positions_count")),
        "open_window": (None if not isinstance(eng, dict) else eng.get("open_window")),
    }

    carry_universe_view = None
    try:
        if str(venue_eff).strip().lower() in ("hyperliquid", "hl"):
            with CARRY_UNIVERSE_LOCK:
                coins0 = CARRY_UNIVERSE_STATE.get("coins") if isinstance(CARRY_UNIVERSE_STATE, dict) else None
                n0 = int(len(coins0)) if isinstance(coins0, list) else 0
                carry_universe_view = {
                    "ts": int(CARRY_UNIVERSE_STATE.get("ts") or 0),
                    "venue": str(CARRY_UNIVERSE_STATE.get("venue") or "hyperliquid"),
                    "n": int(n0),
                    "last_error": (None if CARRY_UNIVERSE_STATE.get("last_error") is None else dict(CARRY_UNIVERSE_STATE.get("last_error")) if isinstance(CARRY_UNIVERSE_STATE.get("last_error"), dict) else {"raw": CARRY_UNIVERSE_STATE.get("last_error")}),
                }
    except Exception:
        carry_universe_view = None

    include_positions_q = request.args.get("include_positions")
    include_positions = False
    if include_positions_q is not None:
        v = str(include_positions_q).strip().lower()
        include_positions = v in ("1", "true", "yes", "on")

    include_events_q = request.args.get("include_events")
    include_events = False
    if include_events_q is not None:
        v = str(include_events_q).strip().lower()
        include_events = v in ("1", "true", "yes", "on")

    positions_view = None
    if bool(include_positions):
        v = str(clk.get("venue") or venue).strip().lower() or str(venue)
        pos = _carry_positions_get()
        out: List[Dict[str, Any]] = []
        for pair, p in pos.items():
            if not isinstance(p, dict):
                continue
            if str(p.get("venue") or "").strip().lower() != str(v):
                continue
            out.append(
                {
                    "pair": str(pair),
                    "coin": (None if p.get("coin") is None else str(p.get("coin"))),
                    "mode": (None if p.get("mode") is None else str(p.get("mode"))),
                    "status": (None if p.get("status") is None else str(p.get("status"))),
                    "hedge_stage": (None if p.get("hedge_stage") is None else str(p.get("hedge_stage"))),
                    "entry_ts": (None if p.get("entry_ts") is None else int(p.get("entry_ts") or 0)),
                    "target_funding_ts": (None if p.get("target_funding_ts") is None else int(p.get("target_funding_ts") or 0)),
                    "unhedge_ts": (None if p.get("unhedge_ts") is None else int(p.get("unhedge_ts") or 0)),
                    "unhedge_deadline_ts": (None if p.get("unhedge_deadline_ts") is None else int(p.get("unhedge_deadline_ts") or 0)),
                    "macro_dir": (None if p.get("macro_dir") is None else int(p.get("macro_dir") or 0)),
                    "reversal_dir": (None if p.get("reversal_dir") is None else int(p.get("reversal_dir") or 0)),
                    "best_timing_score": (None if p.get("best_timing_score") is None else float(p.get("best_timing_score") or 0.0)),
                    "unhedge_exit_score": (None if p.get("unhedge_exit_score") is None else float(p.get("unhedge_exit_score") or 0.0)),
                    "net_pnl_usdc_est": (None if p.get("net_pnl_usdc_est") is None else float(p.get("net_pnl_usdc_est") or 0.0)),
                    "last_unhedge": (None if p.get("last_unhedge") is None else (dict(p.get("last_unhedge")) if isinstance(p.get("last_unhedge"), dict) else {"raw": p.get("last_unhedge")})),
                    "active_monitor": (None if p.get("active_monitor") is None else (dict(p.get("active_monitor")) if isinstance(p.get("active_monitor"), dict) else {"raw": p.get("active_monitor")})),
                }
            )
        positions_view = {"n": int(len(out)), "items": out}

    active_position = None
    try:
        v = str(clk.get("venue") or venue).strip().lower() or str(venue)
        pos = _carry_positions_get()
        for pair, p in pos.items():
            if not isinstance(p, dict):
                continue
            if str(p.get("venue") or "").strip().lower() != str(v):
                continue
            if str(p.get("status") or "").strip().lower() not in ("open", "opened", "paper_opened", "closing"):
                continue
            active_position = {
                "pair": str(pair),
                "coin": (None if p.get("coin") is None else str(p.get("coin"))),
                "mode": (None if p.get("mode") is None else str(p.get("mode"))),
                "status": (None if p.get("status") is None else str(p.get("status"))),
                "hedge_stage": (None if p.get("hedge_stage") is None else str(p.get("hedge_stage"))),
                "entry_ts": (None if p.get("entry_ts") is None else int(p.get("entry_ts") or 0)),
            }
            break
    except Exception:
        active_position = None

    events_view = None
    if bool(include_events):
        try:
            evs = (eng.get("events") if isinstance(eng, dict) else None)
            if not isinstance(evs, list):
                evs = []
            tail_n = 50
            try:
                tail_n = int(request.args.get("events_n") or 50)
            except Exception:
                tail_n = 50
            tail_n = max(1, min(200, int(tail_n)))
            events_view = {"n": int(min(len(evs), tail_n)), "items": list(evs)[-int(tail_n) :]}
        except Exception:
            events_view = {"n": 0, "items": []}

    payload = {
        "ok": True,
        "ts": int(now_ms),
        "venue": str(clk.get("venue") or venue_eff),
        "enabled": bool((eff.get("cfg_base") or {}).get("carry_trade_enabled", False)),
        "enabled_effective": bool(((eff.get("gate") or {}).get("enabled_effective")) if isinstance(eff, dict) else False),
        "live_enabled": bool(_carry_live_trading_enabled()),
        "sandbox": bool((eff.get("cfg_effective") or {}).get("carry_trade_sandbox", True)),
        "execute_allowed": bool(_carry_execute_allowed(str(clk.get("venue") or venue_eff))),
        "execute_effective": bool(((eff.get("gate") or {}).get("enabled_effective")) if isinstance(eff, dict) else False)
        and (not bool((eff.get("cfg_effective") or {}).get("carry_trade_sandbox", True)))
        and bool(_carry_execute_allowed(str(clk.get("venue") or venue_eff))),
        "next_funding_ts": int(clk.get("next_ts") or 0),
        "minutes_to_funding": float(minutes_to_next),
        "window_state": _carry_window_state(float(clk.get("minutes_to") or 0.0)),
        "base_ts": int(clk.get("base_ts") or 0),
        "minutes_to_base": float(clk.get("minutes_to") or 0.0),
        "funding_pnl": (None if not isinstance(pnl, dict) or pnl.get("funding_pnl") is None else float(pnl.get("funding_pnl") or 0.0)),
        "price_move_pnl": (None if not isinstance(pnl, dict) or pnl.get("price_move_pnl") is None else float(pnl.get("price_move_pnl") or 0.0)),
        "costs": (None if not isinstance(pnl, dict) or pnl.get("costs") is None else float(pnl.get("costs") or 0.0)),
        "pnl": pnl,
        "funding_income": funding_income,
        "profile": str(eff.get("profile") or ""),
        "profiles": (eff.get("profiles") or {}),
        "regime": (eff.get("regime") or {}),
        "gate": (eff.get("gate") or {}),
        "cfg_base": (eff.get("cfg_base") or {}),
        "cfg_effective": (eff.get("cfg_effective") or {}),
        "status": {
            "step_raw": (None if not isinstance(eng, dict) else eng.get("step")),
            "step": _carry_status_step_map(
                (
                    (None if not isinstance(eng, dict) else eng.get("step"))
                    or ("paused" if not bool(((eff.get("gate") or {}).get("enabled_effective")) if isinstance(eff, dict) else False) else "idle")
                )
            ),
            "step_ts": (None if not isinstance(eng, dict) else (eng.get("step_ts") or eng.get("tick_ts"))),
            "last_error": (None if not isinstance(eng, dict) else eng.get("last_error")),
        },
        "engine": eng_view,
        "carry_universe": carry_universe_view,
        "active_position": active_position,
    }
    if positions_view is not None:
        payload["positions"] = positions_view
    if events_view is not None:
        payload["events"] = events_view
    return jsonify(payload)


@app.route("/legacy/carry/candidates", methods=["GET"])
def carry_candidates():
    now_ms = int(_now_ms())
    try:
        n = int(request.args.get("n") or (CONFIG.get("carry_trade_candidates_top_n") or 10))
    except Exception:
        n = int(CONFIG.get("carry_trade_candidates_top_n") or 10)
    n = max(1, min(200, int(n)))

    venue_eff = "hyperliquid"
    eff = _carry_cfg_effective(int(now_ms), venue=str(venue_eff))
    cfg_eff = (eff.get("cfg_effective") if isinstance(eff, dict) else None)
    cfg_eff = (cfg_eff if isinstance(cfg_eff, dict) else {})
    carry_mode = str(cfg_eff.get("carry_trade_mode", "perp") or "perp").strip().lower() or "perp"

    clk = _carry_funding_clock(int(now_ms), str(venue_eff))
    minutes_to_next = 0.0
    try:
        if int(clk.get("next_ts") or 0) > 0:
            minutes_to_next = (float(int(clk.get("next_ts") or 0) - int(now_ms))) / 60_000.0
    except Exception:
        minutes_to_next = 0.0

    ws = _carry_window_state(float(clk.get("minutes_to") or 0.0))
    if str(ws) == "WAIT":
        n = min(int(n), 8)

    refresh_q = request.args.get("refresh")
    refresh = False
    if refresh_q is not None:
        v = str(refresh_q).strip().lower()
        refresh = v in ("1", "true", "yes", "on")

    cache_info: Dict[str, Any] = {"ok": False}

    pool_state: Dict[str, Any] = {"ok": False}

    universe_state: Dict[str, Any] = {"ok": True, "n": 0, "ts": 0, "venue": str(venue_eff), "last_error": None}
    try:
        with CARRY_UNIVERSE_LOCK:
            coins0 = CARRY_UNIVERSE_STATE.get("coins") if isinstance(CARRY_UNIVERSE_STATE, dict) else None
            n0 = int(len(coins0)) if isinstance(coins0, list) else 0
            universe_state = {
                "ok": True,
                "ts": int(CARRY_UNIVERSE_STATE.get("ts") or 0),
                "venue": str(CARRY_UNIVERSE_STATE.get("venue") or str(venue_eff)),
                "n": int(n0),
                "last_error": (
                    None
                    if CARRY_UNIVERSE_STATE.get("last_error") is None
                    else dict(CARRY_UNIVERSE_STATE.get("last_error"))
                    if isinstance(CARRY_UNIVERSE_STATE.get("last_error"), dict)
                    else {"raw": CARRY_UNIVERSE_STATE.get("last_error")}
                ),
            }
    except Exception as e:
        universe_state = {"ok": False, "error": str(e)}

    refresh_scheduled = False

    candidates: List[Dict[str, Any]] = []
    if venue_eff in ("hyperliquid", "hl"):
        try:
            cfg_eff = (eff.get("cfg_effective") if isinstance(eff, dict) else None)
            st = _carry_state_get()
            cached_pool = (st.get("pool") if isinstance(st, dict) else None)
            cached_venue = (st.get("venue") if isinstance(st, dict) else None)
            try:
                cached_ts = int((st.get("pool_ts") if isinstance(st, dict) else 0) or 0)
            except Exception:
                cached_ts = 0

            try:
                if isinstance(st, dict) and bool(st.get("pool_refreshing", False)):
                    ts0 = int(st.get("pool_refreshing_ts") or 0)
                    max_ms = int((cfg_eff or {}).get("carry_trade_pool_refresh_max_ms", CONFIG.get("carry_trade_pool_refresh_max_ms", 30000)) or 30000)
                    max_ms = max(1000, min(600000, int(max_ms)))
                    if ts0 > 0 and (int(now_ms) - int(ts0)) > int(max_ms):
                        st["pool_refreshing"] = False
                        st["pool_refreshing_done_ts"] = int(now_ms)
                        st["pool_refreshing_ok"] = False
                        st["pool_last_error"] = {"ts": int(now_ms), "error": "pool_refresh_timeout"}
            except Exception:
                pass
            if isinstance(cached_pool, list) and str(cached_venue or "").strip().lower() == str(venue_eff) and cached_ts > 0:
                candidates = list(cached_pool)[: int(n)]
                try:
                    cache_info = {"ok": True, "venue": str(cached_venue), "pool_ts": int(cached_ts), "age_ms": int(now_ms) - int(cached_ts), "pool_n": int(len(cached_pool))}
                except Exception:
                    cache_info = {"ok": True}

            if isinstance(st, dict):
                pool_state = {
                    "ok": True,
                    "venue": (None if st.get("venue") is None else str(st.get("venue"))),
                    "pool_ts": (None if st.get("pool_ts") is None else int(st.get("pool_ts") or 0)),
                    "pool_n": (len(st.get("pool") or []) if isinstance(st.get("pool"), list) else None),
                    "refreshing": bool(st.get("pool_refreshing", False)),
                    "refreshing_ts": (None if st.get("pool_refreshing_ts") is None else int(st.get("pool_refreshing_ts") or 0)),
                    "refreshing_done_ts": (None if st.get("pool_refreshing_done_ts") is None else int(st.get("pool_refreshing_done_ts") or 0)),
                    "refreshing_ok": (None if st.get("pool_refreshing_ok") is None else bool(st.get("pool_refreshing_ok"))),
                    "last_error": (None if st.get("pool_last_error") is None else (dict(st.get("pool_last_error")) if isinstance(st.get("pool_last_error"), dict) else {"raw": st.get("pool_last_error")})),
                }

            cache_stale = False
            try:
                cache_stale = bool(cache_info.get("ok")) and int(cache_info.get("age_ms") or 0) >= 20_000
            except Exception:
                cache_stale = False

            if bool(refresh) or (not candidates) or bool(cache_stale):
                if isinstance(st, dict) and (not bool(st.get("pool_refreshing", False))):
                    st["pool_refreshing"] = True
                    st["pool_refreshing_ts"] = int(now_ms)

                    def _bg_refresh_pool():
                        with app.app_context():
                            ok = False
                            try:
                                cfg0 = (cfg_eff if isinstance(cfg_eff, dict) else None)
                                n_pool = 10
                                try:
                                    n_pool = int((cfg0 or {}).get("carry_trade_candidates_top_n", CONFIG.get("carry_trade_candidates_top_n", 10)) or 10)
                                except Exception:
                                    n_pool = 10
                                n_pool = max(int(n), max(1, min(200, int(n_pool))))
                                pool2 = _carry_candidates_hl(int(_now_ms()), int(n_pool), cfg=(cfg0 if isinstance(cfg0, dict) else None))
                                st2 = _carry_state_get()
                                st2["pool"] = list(pool2) if isinstance(pool2, list) else []
                                st2["pool_ts"] = int(_now_ms())
                                st2["venue"] = str(venue_eff)
                                last_err = None
                                try:
                                    last_err = (HL_META_ASSET_CTX_CACHE.get("last_error") if isinstance(HL_META_ASSET_CTX_CACHE, dict) else None)
                                except Exception:
                                    last_err = None
                                if ((not isinstance(pool2, list)) or (len(pool2) == 0)) and last_err is not None:
                                    st2["pool_last_error"] = (
                                        dict(last_err)
                                        if isinstance(last_err, dict)
                                        else {"ts": int(_now_ms()), "error": str(last_err)}
                                    )
                                else:
                                    st2["pool_last_error"] = None
                                ok = True
                            except Exception as e:
                                ok = False
                                try:
                                    st2 = _carry_state_get()
                                    st2["pool_last_error"] = {"ts": int(_now_ms()), "error": str(e)}
                                except Exception:
                                    pass
                            try:
                                st2 = _carry_state_get()
                                st2["pool_refreshing"] = False
                                st2["pool_refreshing_done_ts"] = int(_now_ms())
                                st2["pool_refreshing_ok"] = bool(ok)
                            except Exception:
                                pass

                    threading.Thread(target=_bg_refresh_pool, daemon=True).start()
                    refresh_scheduled = True

            if bool(refresh):
                try:
                    if isinstance(pool_state, dict):
                        pool_state["refreshing"] = True
                        pool_state["refreshing_ts"] = int(now_ms)
                except Exception:
                    pass
        except Exception:
            candidates = []

    gate = ({} if not isinstance(eff, dict) else (eff.get("gate") or {}))
    if isinstance(gate, dict) and (not bool(gate.get("enabled_effective", True))):
        for x in candidates:
            if isinstance(x, dict):
                x["vetoed"] = True
                if not x.get("veto_reason"):
                    x["veto_reason"] = "module_paused"

    for x in candidates:
        if not isinstance(x, dict):
            continue
        try:
            if str(x.get("carry_side") or "").strip().lower() == "long":
                x["vetoed"] = True
                if not x.get("veto_reason"):
                    x["veto_reason"] = "long_carry_not_supported"
        except Exception:
            continue

    try:
        corr_thr = float((eff.get("cfg_effective") or {}).get("carry_trade_corr_threshold", CONFIG.get("carry_trade_corr_threshold", 0.80)) or 0.80)
    except Exception:
        corr_thr = 0.80
    corr_thr = float(_clip(float(corr_thr), 0.0, 1.0))
    corr_hit = False
    for x in candidates:
        try:
            if bool(x.get("vetoed")):
                continue
            cm = x.get("corr_max_abs")
            if cm is not None and math.isfinite(float(cm)) and float(cm) >= float(corr_thr):
                corr_hit = True
                break
        except Exception:
            continue
    recommended_open_top_k = None
    try:
        base_k = int((eff.get("cfg_effective") or {}).get("carry_trade_open_top_k", CONFIG.get("carry_trade_open_top_k", 1)) or 1)
        recommended_open_top_k = int(max(1, 1 if corr_hit else base_k))
    except Exception:
        recommended_open_top_k = None

    try:
        with CARRY_UNIVERSE_LOCK:
            coins0 = CARRY_UNIVERSE_STATE.get("coins") if isinstance(CARRY_UNIVERSE_STATE, dict) else None
            n0 = int(len(coins0)) if isinstance(coins0, list) else 0
            universe_state = {
                "ok": True,
                "ts": int(CARRY_UNIVERSE_STATE.get("ts") or 0),
                "venue": str(CARRY_UNIVERSE_STATE.get("venue") or str(venue_eff)),
                "n": int(n0),
                "last_error": (
                    None
                    if CARRY_UNIVERSE_STATE.get("last_error") is None
                    else dict(CARRY_UNIVERSE_STATE.get("last_error"))
                    if isinstance(CARRY_UNIVERSE_STATE.get("last_error"), dict)
                    else {"raw": CARRY_UNIVERSE_STATE.get("last_error")}
                ),
            }
    except Exception as e:
        universe_state = {"ok": False, "error": str(e)}

    return jsonify(
        {
            "ok": True,
            "ts": int(now_ms),
            "venue": str(clk.get("venue") or venue_eff),
            "n": int(n),
            "cache": cache_info,
            "pool": pool_state,
            "universe": universe_state,
            "refresh_scheduled": bool(refresh_scheduled),
            "next_funding_ts": int(clk.get("next_ts") or 0),
            "minutes_to_funding": float(minutes_to_next),
            "window_state": str(ws),
            "profile": (None if not isinstance(eff, dict) else str(eff.get("profile") or "")),
            "regime": ({} if not isinstance(eff, dict) else (eff.get("regime") or {})),
            "gate": gate,
            "cfg_effective": ({} if not isinstance(eff, dict) else (eff.get("cfg_effective") or {})),
            "recommended_open_top_k": recommended_open_top_k,
            "candidates": candidates,
        }
    )


@app.route("/legacy/carry/universe", methods=["GET"])
def carry_universe():
    now_ms = int(_now_ms())
    venue_eff = "hyperliquid"
    eff = _carry_cfg_effective(int(now_ms), venue=str(venue_eff))
    cfg_eff = (eff.get("cfg_effective") if isinstance(eff, dict) else None)
    cfg_eff = (cfg_eff if isinstance(cfg_eff, dict) else {})

    refresh_q = request.args.get("refresh")
    refresh = False
    if refresh_q is not None:
        v = str(refresh_q).strip().lower()
        refresh = v in ("1", "true", "yes", "on")

    refresh_out = None
    try:
        if bool(refresh):
            refresh_out = _carry_universe_refresh(int(now_ms), dict(cfg_eff), force=True)
    except Exception as e:
        refresh_out = {"ok": False, "error": str(e)}

    auto_refresh_scheduled = False
    if not bool(refresh):
        try:
            enabled = bool(cfg_eff.get("carry_universe_enabled", CONFIG.get("carry_universe_enabled", True)))
        except Exception:
            enabled = bool(CONFIG.get("carry_universe_enabled", True))
        if bool(enabled):
            try:
                with CARRY_UNIVERSE_LOCK:
                    ts0 = int(CARRY_UNIVERSE_STATE.get("ts") or 0)
                    coins0 = CARRY_UNIVERSE_STATE.get("coins") if isinstance(CARRY_UNIVERSE_STATE, dict) else None
                    need = ts0 <= 0 or (not isinstance(coins0, list)) or len(coins0) == 0
                    refreshing = bool(CARRY_UNIVERSE_STATE.get("refreshing", False))
                    if bool(need) and (not bool(refreshing)):
                        CARRY_UNIVERSE_STATE["refreshing"] = True
                        CARRY_UNIVERSE_STATE["refreshing_ts"] = int(now_ms)

                        def _bg_refresh_uni():
                            with app.app_context():
                                ok = False
                                out = None
                                try:
                                    out = _carry_universe_refresh(int(_now_ms()), dict(cfg_eff), force=True)
                                    ok = bool(isinstance(out, dict) and out.get("ok"))
                                except Exception as e:
                                    ok = False
                                    out = {"ok": False, "error": str(e)}
                                try:
                                    with CARRY_UNIVERSE_LOCK:
                                        CARRY_UNIVERSE_STATE["refreshing"] = False
                                        CARRY_UNIVERSE_STATE["refreshing_done_ts"] = int(_now_ms())
                                        CARRY_UNIVERSE_STATE["refreshing_ok"] = bool(ok)
                                        if not bool(ok):
                                            CARRY_UNIVERSE_STATE["last_error"] = (dict(out) if isinstance(out, dict) else {"ts": int(_now_ms()), "error": "carry_universe_refresh_failed"})
                                except Exception:
                                    pass

                        threading.Thread(target=_bg_refresh_uni, daemon=True).start()
                        auto_refresh_scheduled = True
            except Exception:
                pass

    view = {"ok": True, "ts": int(now_ms), "venue": str(venue_eff), "auto_refresh_scheduled": bool(auto_refresh_scheduled)}
    try:
        with CARRY_UNIVERSE_LOCK:
            coins0 = CARRY_UNIVERSE_STATE.get("coins") if isinstance(CARRY_UNIVERSE_STATE, dict) else None
            meta0 = CARRY_UNIVERSE_STATE.get("metadata") if isinstance(CARRY_UNIVERSE_STATE, dict) else None
            n0 = int(len(coins0)) if isinstance(coins0, list) else 0
            view["state"] = {
                "ts": int(CARRY_UNIVERSE_STATE.get("ts") or 0),
                "venue": str(CARRY_UNIVERSE_STATE.get("venue") or "hyperliquid"),
                "n": int(n0),
                "coins": (list(coins0) if isinstance(coins0, list) else []),
                "metadata": (dict(meta0) if isinstance(meta0, dict) else {}),
                "last_error": (None if CARRY_UNIVERSE_STATE.get("last_error") is None else dict(CARRY_UNIVERSE_STATE.get("last_error")) if isinstance(CARRY_UNIVERSE_STATE.get("last_error"), dict) else {"raw": CARRY_UNIVERSE_STATE.get("last_error")}),
                "refreshing": bool(CARRY_UNIVERSE_STATE.get("refreshing", False)),
                "refreshing_ts": (None if CARRY_UNIVERSE_STATE.get("refreshing_ts") is None else int(CARRY_UNIVERSE_STATE.get("refreshing_ts") or 0)),
                "refreshing_done_ts": (None if CARRY_UNIVERSE_STATE.get("refreshing_done_ts") is None else int(CARRY_UNIVERSE_STATE.get("refreshing_done_ts") or 0)),
                "refreshing_ok": (None if CARRY_UNIVERSE_STATE.get("refreshing_ok") is None else bool(CARRY_UNIVERSE_STATE.get("refreshing_ok"))),
            }
    except Exception as e:
        view["state"] = {"ok": False, "error": str(e)}

    view["cfg_effective"] = {k: v for k, v in dict(cfg_eff).items() if str(k).startswith("carry_universe_")}
    if refresh_out is not None:
        view["refresh"] = refresh_out
    return jsonify(view)


@app.route("/legacy/carry/config", methods=["POST"])
def carry_config_set():
    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "config_forbidden"}), 403

    raw = request.get_json(force=True) or {}
    if not isinstance(raw, dict):
        return jsonify({"ok": False, "error": "bad_payload"}), 400

    confirm_live = bool(raw.get("confirm_live", False))
    trace_id = str(raw.get("trace_id") or "").strip() or uuid.uuid4().hex
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(raw, trace_id=trace_id, action="carry.config.set")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    if (not _is_local_request()) and (not bool(confirm_live)):
        return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms())}), 400

    data: Dict[str, Any] = {}
    for k, v in raw.items():
        kk = str(k or "").strip()
        if kk in ("confirm_live", "approval_id", "trace_id"):
            continue
        if (not kk.startswith("carry_trade_")) and (not kk.startswith("carry_universe_")):
            continue
        if kk not in CONFIG:
            continue
        if kk == "carry_trade_venue":
            vv = str(v or "").strip().lower()
            if vv not in ("", "hyperliquid", "hl"):
                return jsonify({"ok": False, "error": "carry_trade_venue_hl_only", "got": vv}), 400
            data[kk] = "hyperliquid"
            continue
        data[kk] = v

    try:
        v0 = data.get("carry_trade_venue")
        if v0 is None:
            v0 = CONFIG.get("carry_trade_venue")
        venue_eff = str(v0 or "").strip().lower()
        m0 = data.get("carry_trade_mode")
        if m0 is None:
            m0 = CONFIG.get("carry_trade_mode")
        mode_eff = str(m0 or "perp").strip().lower() or "perp"
    except Exception:
        pass

    rb_pt = None
    if data:
        rb_pt = _rollback_snapshot_append(label="carry.config.set", reason="l2_preflight", config_keys=sorted([str(k) for k in data.keys() if str(k)]))
        if rb_pt is None:
            return jsonify({"ok": False, "error": "rollback_snapshot_failed", "ts": int(_now_ms())}), 500

    out, code = _config_set_impl(data, confirm_live=bool(confirm_live), action="carry.config.set")
    if int(code) != 200 or not isinstance(out, dict) or not bool(out.get("ok")):
        try:
            _audit_emit_action(
                "carry.config.set",
                _audit_base_payload(scope="governance", action="carry.config.set", trace_id=trace_id, extra={"ok": False, "http": int(code), "keys": sorted([str(k) for k in data.keys() if str(k)])[:200], "approval_id": approval_id, "rollback_point": (rb_pt.get("id") if isinstance(rb_pt, dict) else None), "error": (out.get("error") if isinstance(out, dict) else None)}),
            )
        except Exception:
            pass
        return jsonify(out), int(code)
    changed = {k: CONFIG.get(k) for k in data.keys()}
    try:
        _audit_emit_action(
            "carry.config.set",
            _audit_base_payload(scope="governance", action="carry.config.set", trace_id=trace_id, extra={"ok": True, "keys": sorted([str(k) for k in data.keys() if str(k)])[:200], "approval_id": approval_id, "rollback_point": (rb_pt.get("id") if isinstance(rb_pt, dict) else None)}),
        )
    except Exception:
        pass
    return (
        jsonify(
            {
                "ok": True,
                "trace_id": trace_id,
                "approval_id": approval_id,
                "changed": changed,
                "config": {k: CONFIG.get(k) for k in CONFIG.keys() if str(k).startswith("carry_trade_") or str(k).startswith("carry_universe_")},
                "rollback_point": ({"id": rb_pt.get("id"), "ts": rb_pt.get("ts"), "label": rb_pt.get("label"), "reason": rb_pt.get("reason")} if isinstance(rb_pt, dict) else None),
            }
        ),
        200,
    )


