@app.route("/carry/acceptance", methods=["GET"])
def carry_acceptance():
    now_ms = int(_now_ms())
    try:
        lookback_days = int(request.args.get("lookback_days") or 90)
    except Exception:
        lookback_days = 90
    lookback_days = max(1, min(3650, int(lookback_days)))

    venue_eff = "hyperliquid"
    eff = _carry_cfg_effective(int(now_ms), venue=str(venue_eff))
    cfg_eff = (eff.get("cfg_effective") if isinstance(eff, dict) else None)
    cfg_eff = (cfg_eff if isinstance(cfg_eff, dict) else {})

    out = _carry_acceptance_report(int(now_ms), venue=str(venue_eff), lookback_days=int(lookback_days), cfg=dict(cfg_eff))
