@app.route("/auth/me", methods=["GET"])
def auth_me():
    u = _auth_user()
    if not u:
        return jsonify({"ok": False, "ts": int(_now_ms())}), 200
    actor = str(u.get("actor") or "").strip()
    role = str(u.get("role") or "").strip()
    csrf = str(u.get("csrf") or "").strip()
    return jsonify({"ok": True, "actor": actor, "role": role, "csrf_token": csrf, "ts": int(_now_ms())}), 200


@app.route("/auth/login", methods=["POST"])
def auth_login():
    data = request.get_json(force=True) or {}
    user = str(data.get("username") or "").strip()
    pwd = str(data.get("password") or "").strip()
    admin_user = str(os.environ.get("AUTH_ADMIN_USER", "") or "").strip()
    admin_pwd = str(os.environ.get("AUTH_ADMIN_PASSWORD", "") or "").strip()
    if not admin_user:
        admin_user = "admin"
    if (not admin_pwd) or (not hmac.compare_digest(user, admin_user)) or (not hmac.compare_digest(pwd, admin_pwd)):
        try:
            pl = _audit_base_payload("auth", "login.fail", extra={"username": user})
            _audit_emit_action("auth.login.fail", pl)
        except Exception:
            pass
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403

    now = int(time.time())
    try:
        ttl_min = int(os.environ.get("AUTH_SESSION_TTL_MIN", "120") or 120)
    except Exception:
        ttl_min = 120
    ttl_min = max(5, min(7 * 24 * 60, int(ttl_min)))
    exp = now + ttl_min * 60
    csrf = uuid.uuid4().hex
    payload = {"iat": now, "exp": exp, "actor": admin_user, "role": "admin", "csrf": csrf}
    tok = _jwt_make(payload)

    resp = jsonify({"ok": True, "actor": admin_user, "role": "admin", "csrf_token": csrf, "ts": int(_now_ms())})
    try:
        secure = bool(_bool_env("AUTH_COOKIE_SECURE", False))
    except Exception:
        secure = False
    resp.set_cookie(_auth_cookie_name(), tok, max_age=ttl_min * 60, httponly=True, secure=secure, samesite="Lax", path="/")
    resp.set_cookie(_csrf_cookie_name(), csrf, max_age=ttl_min * 60, httponly=False, secure=secure, samesite="Lax", path="/")
    try:
        pl = _audit_base_payload("auth", "login.ok", extra={"username": admin_user})
        _audit_emit_action("auth.login.ok", pl)
    except Exception:
        pass
    return resp, 200


@app.route("/auth/logout", methods=["POST"])
def auth_logout():
    try:
        if _auth_user() and (not _csrf_ok()):
            return jsonify({"ok": False, "error": "csrf_required", "ts": int(_now_ms())}), 403
    except Exception:
        pass
    actor = None
    try:
        u = _auth_user()
        if u:
            actor = str(u.get("actor") or "").strip() or None
    except Exception:
        actor = None
    resp = jsonify({"ok": True, "ts": int(_now_ms())})
    try:
        secure = bool(_bool_env("AUTH_COOKIE_SECURE", False))
    except Exception:
        secure = False
    resp.set_cookie(_auth_cookie_name(), "", max_age=0, expires=0, httponly=True, secure=secure, samesite="Lax", path="/")
    resp.set_cookie(_csrf_cookie_name(), "", max_age=0, expires=0, httponly=False, secure=secure, samesite="Lax", path="/")
    try:
        pl = _audit_base_payload("auth", "logout", extra={"actor": actor})
        _audit_emit_action("auth.logout", pl)
    except Exception:
        pass
    return resp, 200


