@app.route("/live/plan", methods=["POST"])
def live_plan():
    now_ms = _now_ms()
    try:
        data = request.get_json(force=True) or {}
    except Exception:
        data = {}
    sid = str((data.get("strategy_id") or "quant_pairs_btceth")).strip()
    if not sid:
        return jsonify({"ok": False, "error": "missing_strategy_id", "ts": int(now_ms)}), 400
    if sid != "quant_pairs_btceth":
        return jsonify({"ok": False, "error": "unsupported_strategy", "strategy_id": sid, "ts": int(now_ms)}), 400
    direction = str(data.get("direction") or "").strip()
    if not direction:
        direction = "long_btc_short_eth"
    if direction not in ("long_btc_short_eth", "short_btc_long_eth"):
        return jsonify({"ok": False, "error": "invalid_direction", "strategy_id": sid, "direction": direction, "ts": int(now_ms)}), 400
    try:
        if data.get("notional_usdc") is not None:
            notional = float(data.get("notional_usdc"))
        else:
            notional = float(CONFIG.get("quant_pairs_btceth_notional_usdc", CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0) or 200.0)
    except Exception:
        notional = float(CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0)
    if (not math.isfinite(float(notional))) or float(notional) <= 0.0:
        notional = 200.0
    tf = str(data.get("timeframe") or "1h").strip().lower() or "1h"
    if tf == "60m":
        tf = "1h"
    beta_abs = 1.0
    try:
        snapb = _quant_pairs_btceth_latest_beta(tf=tf)
        b = None
        if isinstance(snapb, dict):
            b = snapb.get("beta")
        if b is not None:
            beta_abs = abs(float(b))
    except Exception:
        beta_abs = 1.0
    if (not math.isfinite(float(beta_abs))) or float(beta_abs) <= 0.0:
        beta_abs = 1.0
    beta_abs = float(_clip(float(beta_abs), 0.2, 5.0))
    nb = float(notional)
    ne = float(notional) * float(beta_abs)
    legs: List[Dict[str, Any]] = []
    if direction == "long_btc_short_eth":
        legs.append({"symbol": "BTC-PERP", "side": "long", "notional_usdc": float(nb)})
        legs.append({"symbol": "ETH-PERP", "side": "short", "notional_usdc": float(ne)})
    else:
        legs.append({"symbol": "BTC-PERP", "side": "short", "notional_usdc": float(nb)})
        legs.append({"symbol": "ETH-PERP", "side": "long", "notional_usdc": float(ne)})
    try:
        subp_gate, _ = _subportfolio_gate_check(strategy_id=sid, now_ms=int(now_ms))
    except Exception as e:
        subp_gate = {"ok": False, "enabled": False, "error": str(e)}
    try:
        op_stats = _open_positions_stats(strategy_id=sid)
    except Exception:
        op_stats = {"n": 0, "notional_usdc": 0.0}
    risk = {
        "subportfolio": subp_gate,
        "open_positions": op_stats,
    }
    resp = {
        "ok": True,
        "ts": int(now_ms),
        "strategy_id": sid,
        "timeframe": tf,
        "direction": direction,
        "notional_usdc": float(notional),
        "legs": legs,
        "risk": risk,
    }
    return jsonify(resp), 200


@app.route("/live/preflight", methods=["GET"])
def live_preflight():
    now_ms = _now_ms()
    sync_q = request.args.get("sync")
    update_orders_q = request.args.get("update_orders")
    if sync_q is None:
        do_sync = False
    else:
        v = str(sync_q).strip().lower()
        do_sync = v in ("1", "true", "yes", "on")
    if update_orders_q is None:
        update_orders = False
    else:
        u = str(update_orders_q).strip().lower()
        update_orders = u in ("1", "true", "yes", "on")

    venue = str(CONFIG.get("execution_venue") or "").lower().strip()
    live_enabled = bool(CONFIG.get("live_trading_enabled", False)) and (not bool(CONFIG.get("dry_run", True)))

    blockers: List[str] = []
    warnings: List[str] = []

    try:
        preflight_timeout_sec = float(CONFIG.get("live_preflight_timeout_sec", 6.0) or 6.0)
    except Exception:
        preflight_timeout_sec = 6.0
    if (not math.isfinite(float(preflight_timeout_sec))) or float(preflight_timeout_sec) <= 0.0:
        preflight_timeout_sec = 6.0

    def _call_with_timeout(fn, timeout_sec: float):
        box: Dict[str, Any] = {}

        def _runner() -> None:
            try:
                box["ok"] = True
                box["val"] = fn()
            except Exception as e:
                box["ok"] = False
                box["err"] = str(e)

        t = threading.Thread(target=_runner, daemon=True)
        t.start()
        t.join(timeout=float(timeout_sec))
        if t.is_alive():
            return {"ok": False, "error": "timeout"}
        if not bool(box.get("ok", False)):
            return {"ok": False, "error": str(box.get("err") or "error")}
        return box.get("val")

    if venue not in ("hyperliquid", "aster"):
        blockers.append("invalid_execution_venue")
    if not bool(CONFIG.get("live_trading_enabled", False)):
        blockers.append("live_trading_disabled")
    if bool(CONFIG.get("dry_run", True)):
        blockers.append("dry_run_enabled")

    hl_ping: Optional[Dict[str, Any]] = None
    aster_ping: Optional[Dict[str, Any]] = None
    aster_owners: Optional[Dict[str, Any]] = None

    if venue == "hyperliquid":
        if not _hl_enabled_for_trading_for_owner("strategy"):
            blockers.append("hyperliquid_trading_disabled")
        try:
            hl_ping_raw = _call_with_timeout(_hl_ping_payload, timeout_sec=float(preflight_timeout_sec))
        except Exception:
            hl_ping_raw = {"ok": False, "error": "timeout"}
        hl_ping = hl_ping_raw if isinstance(hl_ping_raw, dict) else {"ok": False, "error": "bad_ping"}
        if not bool(hl_ping.get("sdk_available", False)):
            blockers.append("hyperliquid_sdk_unavailable")
        if not bool(hl_ping.get("has_account", False)):
            blockers.append("missing_HYPERLIQUID_ACCOUNT_ADDRESS")
        if not bool(hl_ping.get("has_api_key", False)):
            blockers.append("missing_HYPERLIQUID_API_PRIVATE_KEY")
        if not bool(CONFIG.get("tracker_autosync_hl_enabled", True)):
            warnings.append("tracker_autosync_hl_disabled")
    elif venue == "aster":
        if not _aster_enabled_for_trading_for_owner("strategy"):
            blockers.append("aster_trading_disabled")

        base_url = _aster_base_url()
        mode = str(_aster_auth_mode("strategy") or "none").lower().strip()
        has_api_key = bool(_aster_api_key("strategy"))
        has_secret = bool(_aster_secret_key("strategy"))
        has_user = bool(_aster_user("strategy"))
        has_signer = bool(_aster_signer("strategy"))
        has_signer_private_key = bool(_aster_signer_private_key("strategy"))

        try:
            aster_ping_raw = _call_with_timeout(lambda: _aster_ping_payload(owner="strategy"), timeout_sec=float(preflight_timeout_sec))
        except Exception:
            aster_ping_raw = {"ok": False, "error": "timeout"}
        aster_ping = aster_ping_raw if isinstance(aster_ping_raw, dict) else {"ok": False, "error": "bad_ping"}
        if not isinstance(aster_ping, dict):
            aster_ping = {"ok": False, "error": "bad_ping"}
        aster_ping.setdefault("base_url", base_url)
        aster_ping.setdefault("trading_enabled", _aster_enabled_for_trading_for_owner("strategy"))
        aster_ping.setdefault("auth_mode", mode)
        aster_ping.setdefault("has_api_key", has_api_key)
        aster_ping.setdefault("has_secret", has_secret)
        aster_ping.setdefault("has_user", has_user)
        aster_ping.setdefault("has_signer", has_signer)
        aster_ping.setdefault("has_signer_private_key", has_signer_private_key)
        if not bool(aster_ping.get("ok", False)):
            blockers.append("aster_ping_failed")
        if mode not in ("v1", "v3"):
            blockers.append("aster_auth_unavailable")
        if mode == "v3":
            if not bool(has_user):
                blockers.append("missing_ASTER_USER")
            if not bool(has_signer):
                blockers.append("missing_ASTER_SIGNER")
            if not bool(has_signer_private_key):
                blockers.append("missing_ASTER_SIGNER_PRIVATE_KEY")
        elif mode == "v1":
            if not bool(has_api_key):
                blockers.append("missing_ASTER_API_KEY")
            if not bool(has_secret):
                blockers.append("missing_ASTER_SECRET_KEY")
        if not bool(CONFIG.get("tracker_autosync_aster_enabled", True)):
            warnings.append("tracker_autosync_aster_disabled")

        aster_owners = {}
        for owner0 in ("strategy", "quant", "carry", "three_screen"):
            try:
                omode = str(_aster_auth_mode(owner0) or "none").lower().strip()
            except Exception:
                omode = "none"
            o_trading_enabled = _aster_enabled_for_trading_for_owner(owner0)
            o_has_api_key = bool(_aster_api_key(owner0))
            o_has_secret = bool(_aster_secret_key(owner0))
            o_has_user = bool(_aster_user(owner0))
            o_has_signer = bool(_aster_signer(owner0))
            o_has_signer_private_key = bool(_aster_signer_private_key(owner0))
            owner_blockers: List[str] = []
            if not bool(o_trading_enabled):
                owner_blockers.append("aster_trading_disabled")
            if omode not in ("v1", "v3"):
                owner_blockers.append("aster_auth_unavailable")
            if omode == "v3":
                if not bool(o_has_user):
                    owner_blockers.append("missing_ASTER_USER")
                if not bool(o_has_signer):
                    owner_blockers.append("missing_ASTER_SIGNER")
                if not bool(o_has_signer_private_key):
                    owner_blockers.append("missing_ASTER_SIGNER_PRIVATE_KEY")
            elif omode == "v1":
                if not bool(o_has_api_key):
                    owner_blockers.append("missing_ASTER_API_KEY")
                if not bool(o_has_secret):
                    owner_blockers.append("missing_ASTER_SECRET_KEY")
            aster_owners[str(owner0)] = {
                "ready": (len(owner_blockers) == 0),
                "blockers": list(owner_blockers),
                "status": {
                    "base_url": base_url,
                    "trading_enabled": bool(o_trading_enabled),
                    "auth_mode": omode,
                    "has_api_key": bool(o_has_api_key),
                    "has_secret": bool(o_has_secret),
                    "has_user": bool(o_has_user),
                    "has_signer": bool(o_has_signer),
                    "has_signer_private_key": bool(o_has_signer_private_key),
                },
            }

    sync_out = None
    if do_sync and venue == "hyperliquid":
        try:
            try:
                req_tid = str(request.headers.get("X-Trace-Id") or "").strip() or None
            except Exception:
                req_tid = None
            sync_out = _hl_sync_record(update_orders=bool(update_orders), trigger="preflight.sync", trace_id=req_tid)
        except Exception as e:
            sync_out = {"ok": False, "ts": int(now_ms), "error": str(e)}
    if do_sync and venue == "aster":
        try:
            sync_out = _aster_sync_record(update_orders=bool(update_orders))
        except Exception as e:
            sync_out = {"ok": False, "ts": int(now_ms), "error": str(e)}

    exchange_pairs: List[str] = []
    tracker_pairs: List[str] = []
    missing_in_tracker: List[str] = []
    missing_on_exchange: List[str] = []
    fetch_err = None

    def _sync_key(x: Any) -> str:
        s = str(x or "").strip().upper()
        if not s:
            return ""
        if "-PERP" in s:
            return s
        if "/" in s:
            try:
                base = s.split("/", 1)[0]
                base = base.split(":", 1)[0].split("-", 1)[0].strip().upper()
            except Exception:
                base = ""
            return f"{base}-PERP" if base else ""
        return s

    try:
        tracker_ops: List[Dict[str, Any]] = []
        for k0 in ("open_positions", "carry_open_positions", "quant_open_positions", "three_screen_open_positions"):
            op0 = TRACKER_STATE.get(k0)
            if isinstance(op0, dict) and op0:
                tracker_ops.append(op0)
        for tracker_op in tracker_ops:
            for k, v in tracker_op.items():
                pair = str(k)
                if not pair.strip():
                    continue
                try:
                    if isinstance(v, dict):
                        if bool(v.get("simulated", False)):
                            continue
                        if str(v.get("mode") or "").strip().lower() == "dry-run":
                            continue
                except Exception:
                    pass
                if venue == "aster":
                    if isinstance(v, dict) and str(v.get("venue") or "").lower().strip() != "aster":
                        continue
                elif venue == "hyperliquid":
                    if isinstance(v, dict) and str(v.get("venue") or "").lower().strip() == "aster":
                        continue
                tracker_pairs.append(pair)
    except Exception:
        tracker_pairs = []

    if venue == "hyperliquid":
        try:
            us_raw = _call_with_timeout(_hl_user_state, timeout_sec=float(preflight_timeout_sec))
            if isinstance(us_raw, dict) and us_raw.get("ok") is False and us_raw.get("error") == "timeout":
                raise RuntimeError("timeout")
            positions = _hl_extract_positions(us_raw)
            for p in list(positions):
                if not isinstance(p, dict):
                    continue
                coin = str(p.get("coin") or p.get("name") or p.get("asset") or "").upper().strip()
                if not coin:
                    continue
                sz = _to_float(p.get("szi", p.get("sz", p.get("size", 0.0))))
                if abs(float(sz)) < 1e-12:
                    continue
                exchange_pairs.append(f"{coin}-PERP")
        except Exception as e:
            fetch_err = str(e)
            exchange_pairs = []
    elif venue == "aster":
        owners_to_fetch: List[str] = []
        try:
            if isinstance(aster_owners, dict):
                for owner0 in ("quant", "strategy", "carry", "three_screen"):
                    st = aster_owners.get(str(owner0))
                    if isinstance(st, dict) and bool(st.get("ready")):
                        owners_to_fetch.append(str(owner0))
        except Exception:
            owners_to_fetch = []
        if not owners_to_fetch:
            owners_to_fetch = ["strategy"]

        errs: Dict[str, str] = {}
        for owner0 in owners_to_fetch:
            try:
                pos_raw = _call_with_timeout(lambda: _aster_fetch_positions(owner=owner0), timeout_sec=float(preflight_timeout_sec))
                if isinstance(pos_raw, dict) and pos_raw.get("ok") is False and pos_raw.get("error") == "timeout":
                    raise RuntimeError("timeout")
                if isinstance(pos_raw, (list, tuple)) and len(pos_raw) == 2:
                    positions0, err0 = pos_raw
                else:
                    positions0, err0 = [], "bad_positions"
                if err0 is not None:
                    errs[str(owner0)] = str(err0)
                    continue
                for p in list(positions0 or []):
                    if not isinstance(p, dict):
                        continue
                    coin = str(p.get("coin") or "").upper().strip()
                    if not coin:
                        continue
                    exchange_pairs.append(f"{coin}-PERP")
            except Exception as e:
                errs[str(owner0)] = str(e)

        if exchange_pairs:
            fetch_err = None
        else:
            fetch_err = (";".join([f"{k}:{v}" for k, v in sorted(list(errs.items()))]) if errs else "bad_positions")
            exchange_pairs = []

    ex_set = set([k for k in [_sync_key(x) for x in exchange_pairs] if k])
    tr_set = set([k for k in [_sync_key(x) for x in tracker_pairs] if k])
    missing_in_tracker = sorted(list(ex_set - tr_set))
    missing_on_exchange = sorted(list(tr_set - ex_set))

    if live_enabled and (missing_in_tracker or missing_on_exchange):
        blockers.append("positions_not_synced")

    if fetch_err is not None:
        if venue == "hyperliquid":
            blockers.append("hyperliquid_user_state_unavailable")
        elif venue == "aster":
            blockers.append("aster_positions_unavailable")

    ready = len(blockers) == 0
    return jsonify({
        "ok": True,
        "ts": int(now_ms),
        "ready": bool(ready),
        "blockers": blockers,
        "warnings": warnings,
        "execute_guard": {
            "enabled": bool(CONFIG.get("execute_guard_enabled", True)),
            "token_required": bool(str(os.environ.get("WEBHOOK_EXECUTE_TOKEN", "") or "").strip()),
            "allow_remote": bool(CONFIG.get("live_execute_allow_remote", False)),
        },
        "config": {
            "execution_venue": venue,
            "dry_run": bool(CONFIG.get("dry_run", True)),
            "live_trading_enabled": bool(CONFIG.get("live_trading_enabled", False)),
            "hl_trading_enabled": bool(CONFIG.get("hl_trading_enabled", False)),
            "aster_trading_enabled": bool(CONFIG.get("aster_trading_enabled", False)),
            "tracker_autosync_hl_enabled": bool(CONFIG.get("tracker_autosync_hl_enabled", True)),
            "tracker_autosync_aster_enabled": bool(CONFIG.get("tracker_autosync_aster_enabled", True)),
        },
        "hyperliquid": {
            "ping": hl_ping,
            "sync": (sync_out if venue == "hyperliquid" else None),
            "user_state_error": (fetch_err if venue == "hyperliquid" else None),
        },
        "aster": {
            "ping": aster_ping,
            "owners": aster_owners,
            "sync": (sync_out if venue == "aster" else None),
            "positions_error": (fetch_err if venue == "aster" else None),
        },
        "positions": {
            "exchange": exchange_pairs,
            "tracker": tracker_pairs,
            "missing_in_tracker": missing_in_tracker[:50],
            "missing_on_exchange": missing_on_exchange[:50],
            "missing_in_tracker_n": int(len(missing_in_tracker)),
            "missing_on_exchange_n": int(len(missing_on_exchange)),
        },
    })


def _signals_prune_dedup(now_ms: int) -> None:
    ttl_sec = int(CONFIG.get("signals_dedup_ttl_sec", 3600) or 3600)
    with SIGNAL_DEDUP_LOCK:
        if ttl_sec <= 0:
            try:
                if SIGNAL_DEDUP:
                    SIGNAL_DEDUP.clear()
                if SIGNAL_DEDUP_V1_BASE:
                    SIGNAL_DEDUP_V1_BASE.clear()
            except Exception:
                pass
            return
        ttl_ms = ttl_sec * 1000
        if len(SIGNAL_DEDUP) > 20000:
            SIGNAL_DEDUP.clear()
            try:
                if SIGNAL_DEDUP_V1_BASE:
                    SIGNAL_DEDUP_V1_BASE.clear()
            except Exception:
                pass
            return
        if len(SIGNAL_DEDUP_V1_BASE) > 20000:
            SIGNAL_DEDUP_V1_BASE.clear()
            return
        dead = []
        for k, v in list(SIGNAL_DEDUP.items()):
            try:
                if now_ms - int(v.get("seen_ms") or 0) > ttl_ms:
                    dead.append(k)
            except Exception:
                dead.append(k)
        for k in dead:
            try:
                del SIGNAL_DEDUP[k]
            except Exception:
                pass

        inflight_ttl_ms = 30000
        dead2 = []
        for k, v in list(SIGNAL_DEDUP_V1_BASE.items()):
            try:
                age_ms = now_ms - int(v.get("seen_ms") or 0)
                if bool(v.get("inflight")) or bool(v.get("inflight_upgrade")):
                    if age_ms > inflight_ttl_ms:
                        dead2.append(k)
                elif age_ms > ttl_ms:
                    dead2.append(k)
            except Exception:
                dead2.append(k)
        for k in dead2:
            try:
                del SIGNAL_DEDUP_V1_BASE[k]
            except Exception:
                pass


def _signals_dedup_key(pair: str, side: str, strategy_id: Any, ts: Any) -> str:
    p = str(pair or "").strip()
    s = str(side or "").strip().lower()
    try:
        ti = int(ts or 0)
    except Exception:
        ti = 0
    sid = "" if strategy_id is None else str(strategy_id).strip()
    try:
        bucket_sec = int(CONFIG.get("signals_dedup_bucket_sec", 60) or 60)
    except Exception:
        bucket_sec = 60
    if int(bucket_sec) <= 0:
        bucket_sec = 60
    bucket = int(ti // (int(bucket_sec) * 1000)) if int(ti) > 0 else 0
    return f"{p}|{s}|{sid}|{bucket}"


def _arena_aggregate(arena_evt: Any) -> Dict[str, Any]:
    if not isinstance(arena_evt, dict):
        return {}
    models = arena_evt.get("models")
    if not isinstance(models, dict) or not models:
        return {}
    rows = []
    for name, m in models.items():
        if not isinstance(m, dict):
            continue
        eligible = bool(m.get("eligible", True))
        try:
            w = float(m.get("weight") or 0.0)
        except Exception:
            w = 0.0
        try:
            pc = float(m.get("pc") or 0.0)
        except Exception:
            pc = 0.0
        rows.append({"name": str(name), "eligible": eligible, "weight": float(w), "pc": float(pc), "take": bool(m.get("take", False))})

    elig = [r for r in rows if bool(r.get("eligible", True))]
    use = elig if elig else rows
    if not use:
        return {}

    wsum = sum(max(0.0, float(r.get("weight") or 0.0)) for r in use)
    pc_mean = sum(float(r.get("pc") or 0.0) for r in use) / float(len(use))
    if wsum > 1e-12:
        pc_weighted = sum(float(r.get("pc") or 0.0) * max(0.0, float(r.get("weight") or 0.0)) for r in use) / float(wsum)
    else:
        pc_weighted = float(pc_mean)

    return {
        "threshold": arena_evt.get("threshold"),
        "regime": arena_evt.get("regime"),
        "chosen": arena_evt.get("chosen"),
        "explore": bool(arena_evt.get("explore", False)),
        "n_models": int(len(rows)),
        "n_eligible": int(len(elig)),
        "n_take": int(sum(1 for r in use if bool(r.get("take", False)))),
        "pc_mean": float(pc_mean),
        "pc_weighted": float(pc_weighted),
    }


def _coin_norm_from_any_symbol(sym: str) -> str:
    s = str(sym or "").strip().upper()
    if not s:
        return ""
    s = s.split(":")[0].strip()
    if s.endswith("-PERP") and len(s) > 5:
        return s[:-5]
    try:
        if ("-" in s) or ("/" in s):
            c = _hl_coin_from_pair(s)
            c = str(c or "").strip().upper()
            if c:
                return c
    except Exception:
        pass
    for suf in ("USDT", "USDC", "USD"):
        if s.endswith(suf) and len(s) > len(suf):
            return s[: -len(suf)]
    if "/" in s:
        return s.split("/")[0].strip()
    if "-" in s:
        return s.split("-")[0].strip()
    return s


def _trade_whitelist_coin_set() -> set:
    wl0 = CONFIG.get("trade_whitelist")
    wl = wl0 if isinstance(wl0, list) else []
    coins = set()
    for w in wl:
        c = _coin_norm_from_any_symbol(str(w or ""))
        if c:
            coins.add(str(c).upper().strip())
    return coins


def _whitelist_gate_state() -> Dict[str, Any]:
    st = TRACKER_STATE.get("whitelist_gate_state")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["whitelist_gate_state"] = st
    return st


def _whitelist_gate_vote_rule(now_ms: int) -> str:
    base_rule = str(CONFIG.get("whitelist_gate_vote_rule_base", "2of5") or "2of5").lower().strip()
    relax_rule = str(CONFIG.get("whitelist_gate_vote_rule_relax", "1of5") or "1of5").lower().strip()
    if base_rule not in ("2of5", "3of5", "1of5"):
        base_rule = "2of5"
    if relax_rule not in ("1of5", "2of5", "3of5"):
        relax_rule = "1of5"
    if not bool(CONFIG.get("whitelist_gate_dynamic_enabled", True)):
        return base_rule

    try:
        eval_h = int(CONFIG.get("whitelist_gate_eval_window_hours", 24) or 24)
    except Exception:
        eval_h = 24
    eval_h = max(1, int(eval_h))
    try:
        target_per_day = float(CONFIG.get("whitelist_gate_target_entries_per_day", 2) or 2)
    except Exception:
        target_per_day = 2.0
    try:
        resume_per_day = float(CONFIG.get("whitelist_gate_resume_entries_per_day", 4) or 4)
    except Exception:
        resume_per_day = 4.0

    start_ms = int(now_ms) - int(eval_h) * 3600 * 1000
    wl_coins = _trade_whitelist_coin_set()
    gh = TRACKER_STATE.get("gate_history")
    n_pass = 0
    if wl_coins and isinstance(gh, list):
        for rec in gh:
            if not isinstance(rec, dict):
                continue
            try:
                ts = int(rec.get("ts") or 0)
            except Exception:
                ts = 0
            if ts < int(start_ms):
                continue
            if not bool(rec.get("ok", False)):
                continue
            coin = _coin_norm_from_any_symbol(str(rec.get("pair") or ""))
            coin = str(coin or "").upper().strip()
            if coin and coin in wl_coins:
                n_pass += 1

    target_in_window = float(target_per_day) * (float(eval_h) / 24.0)
    resume_in_window = float(resume_per_day) * (float(eval_h) / 24.0)

    try:
        pnl_days = int(CONFIG.get("whitelist_gate_pnl_window_days", 7) or 7)
    except Exception:
        pnl_days = 7
    pnl_days = max(1, int(pnl_days))
    try:
        pnl_floor = float(CONFIG.get("whitelist_gate_pnl_floor", 0.0) or 0.0)
    except Exception:
        pnl_floor = 0.0
    try:
        dd_ceiling = float(CONFIG.get("whitelist_gate_dd_ceiling", 0.05) or 0.05)
    except Exception:
        dd_ceiling = 0.05
    dd_ceiling = max(0.0, float(dd_ceiling))

    dp = TRACKER_STATE.get("daily_pnl")
    pnl_sum = 0.0
    maxdd = 0.0
    if isinstance(dp, dict) and dp:
        days = []
        try:
            now_dt = datetime.fromtimestamp(int(now_ms) / 1000.0, tz=timezone.utc)
        except Exception:
            now_dt = datetime.now(timezone.utc)
        for i in range(int(pnl_days) - 1, -1, -1):
            d = (now_dt - timedelta(days=int(i))).strftime("%Y-%m-%d")
            days.append(d)
        cum = 0.0
        peak = 0.0
        for d in days:
            try:
                v = float(dp.get(d, 0.0) or 0.0)
            except Exception:
                v = 0.0
            cum += float(v)
            if float(cum) > float(peak):
                peak = float(cum)
            dd = float(peak) - float(cum)
            if dd > float(maxdd):
                maxdd = float(dd)
        pnl_sum = float(cum)

    perf_ok = (float(pnl_sum) >= float(pnl_floor)) and (float(maxdd) <= float(dd_ceiling) + 1e-12)

    st = _whitelist_gate_state()
    cur = str(st.get("mode") or base_rule).lower().strip()
    if cur not in (base_rule, relax_rule):
        cur = base_rule

    desired = base_rule
    if not bool(perf_ok):
        desired = base_rule
    else:
        if float(n_pass) < float(target_in_window) - 1e-12:
            desired = relax_rule
        elif float(n_pass) >= float(resume_in_window) - 1e-12:
            desired = base_rule
        else:
            desired = cur

    try:
        min_sw_h = int(CONFIG.get("whitelist_gate_min_switch_interval_hours", 12) or 12)
    except Exception:
        min_sw_h = 12
    min_sw_ms = max(0, int(min_sw_h)) * 3600 * 1000
    try:
        last_sw = int(st.get("last_switch_ms") or 0)
    except Exception:
        last_sw = 0

    if desired != cur and min_sw_ms > 0 and (int(now_ms) - int(last_sw)) < int(min_sw_ms):
        desired = cur

    if desired != cur:
        st["mode"] = str(desired)
        st["last_switch_ms"] = int(now_ms)
    else:
        st["mode"] = str(cur)
    st["last_eval_ms"] = int(now_ms)
    st["n_pass_window"] = int(n_pass)
    st["eval_window_hours"] = int(eval_h)
    st["pnl_sum_days"] = float(pnl_sum)
    st["maxdd_days"] = float(maxdd)
    return str(st.get("mode") or base_rule)


def _arena_entry_gate(arena_evt: Any) -> Dict[str, Any]:
    if not isinstance(arena_evt, dict):
        return {"ok": False, "pass": False, "reason": "invalid_arena_evt"}
    models = arena_evt.get("models")
    if not isinstance(models, dict) or not models:
        return {"ok": False, "pass": False, "reason": "missing_models"}

    try:
        group_id = str((arena_evt.get("group_id") if isinstance(arena_evt, dict) else None) or "").strip()
    except Exception:
        group_id = ""
    try:
        strategy_id = str((arena_evt.get("strategy_id") if isinstance(arena_evt, dict) else None) or "").strip()
    except Exception:
        strategy_id = ""

    gate_overrides = CONFIG.get("arena_entry_gate_overrides")
    ov: Optional[Dict[str, Any]] = None
    if isinstance(gate_overrides, dict):
        try:
            if group_id and isinstance(gate_overrides.get(group_id), dict):
                ov = gate_overrides.get(group_id)
            elif strategy_id and isinstance(gate_overrides.get(strategy_id), dict):
                ov = gate_overrides.get(strategy_id)
            elif isinstance(gate_overrides.get("default"), dict):
                ov = gate_overrides.get("default")
        except Exception:
            ov = None
    try:
        v = (ov.get("min_votes") if isinstance(ov, dict) else None)
        if v is None:
            v = CONFIG.get("arena_entry_min_votes", 3)
        min_votes = int(v if v is not None else 3)
    except Exception:
        min_votes = 3
    min_votes = max(1, int(min_votes))
    try:
        v = (ov.get("min_weight_sum") if isinstance(ov, dict) else None)
        if v is None:
            v = CONFIG.get("arena_entry_min_weight_sum", 0.55)
        min_w = float(v if v is not None else 0.55)
    except Exception:
        min_w = 0.55
    min_w = float(_clip(float(min_w), 0.0, 1.0))
    try:
        v = (ov.get("weight_sum_floor_votes") if isinstance(ov, dict) else None)
        if v is None:
            v = CONFIG.get("arena_entry_weight_sum_floor_votes", 2)
        floor_votes = int(v if v is not None else 2)
    except Exception:
        floor_votes = 2
    floor_votes = max(1, int(floor_votes))
    try:
        v = (ov.get("eligible_only") if isinstance(ov, dict) else None)
        if v is None:
            v = CONFIG.get("arena_entry_vote_eligible_only", True)
        eligible_only = bool(v)
    except Exception:
        eligible_only = True

    use_dyn_thr = bool(CONFIG.get("arena_dynamic_threshold_enabled", False))
    has_model_thr = False
    if bool(use_dyn_thr):
        try:
            for _, m in models.items():
                if not isinstance(m, dict):
                    continue
                if m.get("thr") is not None:
                    has_model_thr = True
                    break
        except Exception:
            has_model_thr = False
    vote_thr = None
    try:
        if arena_evt.get("threshold") is not None:
            thr0 = float(arena_evt.get("threshold"))
        else:
            thr0 = None
    except Exception:
        thr0 = None
    if thr0 is not None and ((not bool(use_dyn_thr)) or (not bool(has_model_thr))):
        vote_thr = float(thr0)

    try:
        cap_floor_u = float(CONFIG.get("arena_capital_floor_u", 10.0) or 10.0)
    except Exception:
        cap_floor_u = 10.0
    cap_floor_u = max(0.0, float(cap_floor_u))

    def _build_rows(only_eligible: bool, require_cap: bool) -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        for name, m in models.items():
            if not isinstance(m, dict):
                continue
            eligible = bool(m.get("eligible", True))
            if only_eligible and (not eligible):
                continue
            try:
                cap_u = float(m.get("capital_u") or 0.0)
            except Exception:
                cap_u = 0.0
            if require_cap and cap_floor_u > 0.0 and float(cap_u) < float(cap_floor_u):
                continue
            try:
                pc = float(m.get("pc") or 0.0)
            except Exception:
                pc = 0.0
            if vote_thr is not None:
                take = bool(float(pc) >= float(vote_thr))
            else:
                take = bool(m.get("take", False))
            try:
                w = float(m.get("weight") or 0.0)
            except Exception:
                w = 0.0
            out.append({"name": str(name), "eligible": eligible, "take": take, "weight": float(w)})
        return out

    rows = _build_rows(bool(eligible_only), True)
    if not rows:
        rows = _build_rows(bool(eligible_only), False)
    if eligible_only and (not rows):
        rows = _build_rows(False, False)

    if not rows:
        return {"ok": False, "pass": False, "reason": "no_models_considered"}

    takers = [r for r in rows if bool(r.get("take", False))]
    n_take = int(len(takers))
    w_take = float(sum(max(0.0, float(r.get("weight") or 0.0)) for r in takers))

    n_considered = int(len(rows))

    ratio_req_num = 2
    ratio_req_den = 5
    explore = bool(arena_evt.get("explore", False))

    vote_rule = "3of5"
    try:
        vr_raw = (ov.get("vote_rule") if isinstance(ov, dict) else None)
        if vr_raw is None:
            vr_raw = CONFIG.get("elastic_vote_rule", "")
        vr_cfg = str(vr_raw or "").lower().strip()
    except Exception:
        vr_cfg = ""
    if vr_cfg in ("1of5", "1/5", "2of5", "3of5"):
        vr_eff = ("1of5" if vr_cfg == "1/5" else vr_cfg)
        if vr_eff == "1of5" and (not bool(explore)):
            vote_rule = "2of5"
        else:
            vote_rule = vr_eff
    else:
        vote_rule = "3of5"

    elastic_enabled = bool(CONFIG.get("elastic_gating_enabled", False))
    if isinstance(ov, dict) and ov.get("elastic_gating_enabled") is not None:
        elastic_enabled = bool(ov.get("elastic_gating_enabled"))

    if bool(elastic_enabled):
        if vr_cfg in ("1of5", "1/5", "2of5", "3of5"):
            pass
        else:
            tier = None
            vr0 = ""
            try:
                em = arena_evt.get("elastic") if isinstance(arena_evt, dict) else None
                if isinstance(em, dict):
                    if em.get("tier") is not None:
                        tier = int(em.get("tier"))
                    vr0 = str(em.get("vote_rule") or "").lower().strip()
            except Exception:
                tier = None
                vr0 = ""

            if vr0 in ("1of5", "1/5", "2of5", "3of5"):
                vr_eff = ("1of5" if vr0 == "1/5" else vr0)
                if vr_eff == "1of5" and (not bool(explore)):
                    vote_rule = "2of5"
                else:
                    vote_rule = vr_eff
            else:
                if tier is None:
                    try:
                        g0 = str((arena_evt.get("group_id") if isinstance(arena_evt, dict) else None) or "global")
                        tier = int((((ELASTIC_STATE.get("by_group") or {}).get(g0) or {}).get("tier") or 2))
                    except Exception:
                        tier = None
                if tier is not None and int(tier) <= 0:
                    vote_rule = "1of5" if bool(explore) else "2of5"
                elif tier is not None and int(tier) <= 2:
                    vote_rule = "2of5"
                else:
                    vote_rule = "3of5"

    try:
        if bool(CONFIG.get("trade_whitelist_enabled", True)) and bool(CONFIG.get("whitelist_gate_enabled", True)):
            wl_coins = _trade_whitelist_coin_set()
            coin_evt = _coin_norm_from_any_symbol(str(arena_evt.get("pair") or ""))
            coin_evt = str(coin_evt or "").upper().strip()
            if coin_evt and wl_coins and coin_evt in wl_coins:
                vote_rule = _whitelist_gate_vote_rule(_now_ms())
    except Exception:
        pass

    if vote_rule == "1of5":
        ratio_req_num = 1
        ratio_req_den = 5
        min_votes = max(1, int(min_votes))
        floor_votes = max(1, int(floor_votes))
    elif vote_rule == "2of5":
        ratio_req_num = 2
        ratio_req_den = 5
        min_votes = max(2, int(min_votes))
        floor_votes = max(2, int(floor_votes))
    else:
        ratio_req_num = 3
        ratio_req_den = 5
        min_votes = max(3, int(min_votes))
        floor_votes = max(3, int(floor_votes))

    try:
        relax = bool(CONFIG.get("arena_entry_relax_quorum", False))
    except Exception:
        relax = False
    if bool(relax):
        ratio_req_num = 1
        ratio_req_den = 5
        min_votes = 1
        floor_votes = 1
    min_votes_ratio = int(((int(n_considered) * int(ratio_req_num)) + int(ratio_req_den) - 1) // int(ratio_req_den)) if n_considered > 0 else int(ratio_req_num)
    min_votes_ratio = max(1, int(min_votes_ratio))
    min_votes_eff = min(int(min_votes), int(n_considered)) if n_considered > 0 else int(min_votes)
    floor_votes_eff = min(int(floor_votes), int(n_considered)) if n_considered > 0 else int(floor_votes)
    min_votes_eff = max(1, int(min_votes_eff))
    floor_votes_eff = max(1, int(floor_votes_eff))

    min_votes_eff = max(int(min_votes_eff), int(min_votes_ratio))
    floor_votes_eff = max(int(floor_votes_eff), int(min_votes_ratio))

    pass_votes = bool(n_take >= int(min_votes_eff))
    pass_weight = bool((w_take >= float(min_w)) and (n_take >= int(floor_votes_eff)))
    passed = bool(pass_votes or pass_weight)
    reason = None
    if not passed:
        reason = "arena_quorum"

    return {
        "ok": True,
        "pass": passed,
        "reason": reason,
        "vote_rule": str(vote_rule),
        "min_votes": int(min_votes_eff),
        "min_weight_sum": float(min_w),
        "weight_sum_floor_votes": int(floor_votes_eff),
        "eligible_only": bool(eligible_only),
        "n_models_considered": int(len(rows)),
        "n_take": int(n_take),
        "w_take": float(w_take),
        "min_votes_ratio": int(min_votes_ratio),
        "take_ratio": (float(n_take) / float(n_considered)) if n_considered > 0 else 0.0,
        "pass_votes": bool(pass_votes),
        "pass_weight": bool(pass_weight),
    }


def _build_decision_info(evt: Any, dreq: Dict[str, Any], out: Dict[str, Any], code: int, now_ms: int) -> Dict[str, Any]:
    arena_evt = (evt.get("arena") if isinstance(evt, dict) else None)
    try:
        pc = float(out.get("pc")) if out.get("pc") is not None else None
    except Exception:
        pc = None
    try:
        thr = float(out.get("threshold")) if out.get("threshold") is not None else None
    except Exception:
        thr = None
    if thr is None and isinstance(arena_evt, dict):
        try:
            thr = float(arena_evt.get("threshold"))
        except Exception:
            thr = None

    decision = out.get("decision")
    reason = out.get("reason")
    if reason is None:
        reason = out.get("error")
    if str(decision) == "hold" and reason is None and pc is not None and thr is not None:
        if float(pc) < float(thr):
            reason = "below_threshold"

    gate = None
    try:
        if isinstance(arena_evt, dict) and bool(CONFIG.get("arena_enabled", False)):
            gate = _arena_entry_gate(arena_evt)
    except Exception:
        gate = None

    macro_shape = None
    try:
        pair0 = (evt.get("pair") if isinstance(evt, dict) else None)
        if pair0 is None:
            pair0 = dreq.get("pair")
        side0 = (evt.get("side") if isinstance(evt, dict) else None)
        if side0 is None:
            side0 = dreq.get("side")
        sid0 = (evt.get("strategy_id") if isinstance(evt, dict) else None)
        if pair0 and str(side0 or "").lower().strip() in ("long", "short") and _entry_macro_scope_ok(pair=str(pair0), strategy_id=str(sid0 or "")):
            ts0 = now_ms
            if isinstance(evt, dict):
                try:
                    ts0 = int(evt.get("bar_open_ms") or evt.get("bar_close_ms") or evt.get("ts") or evt.get("ts_emit_ms") or now_ms)
                except Exception:
                    ts0 = int(now_ms)
            macro_shape = _entry_macro_btceth_shape_at(int(ts0))
    except Exception:
        macro_shape = None

    return {
        "ts_ms": int(now_ms),
        "event_id": (evt.get("id") if isinstance(evt, dict) else None),
        "pair": (evt.get("pair") if isinstance(evt, dict) else dreq.get("pair")),
        "side": (evt.get("side") if isinstance(evt, dict) else dreq.get("side")),
        "tag": (evt.get("tag") if isinstance(evt, dict) else dreq.get("tag")),
        "decision": decision,
        "decision_code": int(code),
        "reason": reason,
        "p": out.get("p"),
        "pc": pc,
        "threshold": thr,
        "regime": (out.get("regime") if out.get("regime") is not None else (arena_evt.get("regime") if isinstance(arena_evt, dict) else None)),
        "arena": {"agg": _arena_aggregate(arena_evt), "gate": gate, "ref": (None if not isinstance(out.get("arena"), dict) else out.get("arena"))},
        "macro_btceth_shape": macro_shape,
        "committee": out.get("committee"),
        "out": out,
    }

@app.route("/signals", methods=["POST"])
def signals():
    data = request.get_json(force=True) or {}

    try:
        sv = int(data.get("signal_schema_version") or 0)
    except Exception:
        sv = 0

    has_v1_fields = (data.get("bar_open_ms") is not None) and (data.get("timeframe") is not None)
    if (sv >= 1) or has_v1_fields:
        trigger = None
        if "trigger_decision" in data:
            trigger = bool(data.get("trigger_decision"))
        elif "auto_decision" in data:
            trigger = bool(data.get("auto_decision"))
        else:
            trigger = bool(CONFIG.get("signals_auto_decision", False))

        try:
            if not bool(data.get("bar_closed", True)):
                trigger = False
        except Exception:
            trigger = False

        data2 = dict(data)
        if sv < 1:
            data2["signal_schema_version"] = 1
        resp = _emit_signal_v1(data2, bool(trigger), dict(data2))
        return jsonify(resp)

    pair = data.get("pair")
    side = str(data.get("side", "")).lower()
    tag = data.get("tag")
    features = data.get("features") or {}
    ts_raw = data.get("ts")
    try:
        ts = int(ts_raw) if ts_raw is not None else int(_now_ms())
    except Exception:
        ts = int(_now_ms())
    
    if side not in ("long", "short"):
        return jsonify({"ok": False, "error": "invalid_side"}), 400
    if not pair:
        return jsonify({"ok": False, "error": "missing_pair"}), 400

    strategy_id = data.get("strategy_id")
    if strategy_id is None:
        strategy_id = data.get("strategy")
    strategy_id = ("" if strategy_id is None else str(strategy_id)).strip() or None

    now_ms = _now_ms()
    _signals_prune_dedup(now_ms)
    skey = _signals_dedup_key(str(pair), str(side), strategy_id, ts)
    with SIGNAL_DEDUP_LOCK:
        cached = SIGNAL_DEDUP.get(skey)
    if isinstance(cached, dict):
        return jsonify(cached.get("resp") or {"ok": True, "id": cached.get("evt_id"), "dedup": True})
    strategy_version = None
    group_id = None
    feature_set_id = None
    if strategy_id is not None:
        sm = _get_strategy_meta(strategy_id)
        strategy_version = sm.get("strategy_version")
        group_id = sm.get("group_id")
        feature_set_id = sm.get("feature_set_id")
    if data.get("strategy_version") is not None:
        strategy_version = str(data.get("strategy_version"))
    if data.get("group_id") is not None:
        group_id = str(data.get("group_id"))
    if data.get("feature_set_id") is not None:
        feature_set_id = str(data.get("feature_set_id"))

    if not isinstance(features, dict):
        features = {}
    if feature_set_id:
        try:
            features = _align_features(str(feature_set_id), dict(features or {}))
        except Exception:
            features = dict(features or {})
    else:
        features = dict(features or {})

    strategy_features = dict(features or {})
    market_features: Dict[str, Any] = {}
    try:
        if pair and int(ts or 0) > 0:
            market_features = _ml3_features_at_timestamp(str(pair), int(ts)) or {}
    except Exception:
        market_features = {}

    merged_features: Dict[str, Any] = {}
    try:
        if isinstance(market_features, dict):
            merged_features.update(market_features)
        if isinstance(strategy_features, dict):
            merged_features.update(strategy_features)
    except Exception:
        merged_features = dict(strategy_features or {})

    evt_id = _gen_id("sig")
    EVENTS[evt_id] = {
        "id": evt_id,
        "pair": pair,
        "side": side,
        "tag": tag,
        "features": merged_features,
        "strategy_features": strategy_features,
        "market_features": market_features,
        "ts": ts,
        "ingested_ms": int(now_ms),
        "bar_closed": bool(data.get("bar_closed", True)),
        "strategy_id": strategy_id,
        "strategy_version": (None if strategy_version is None else str(strategy_version)),
        "group_id": (None if group_id is None else str(group_id)),
        "feature_set_id": (None if feature_set_id is None else str(feature_set_id)),
    }
    LOG.info("signal id=%s pair=%s side=%s tag=%s", evt_id, pair, side, str(tag))
    try:
        _archive_event(EVENTS.get(evt_id) or {})
    except Exception:
        pass

    if _arena_enabled():
        try:
            regime = _get_regime(features, pair=str(pair), ts=int(ts or 0), timeframe=(str(data.get("timeframe")) if data.get("timeframe") is not None else None))
            thr = _get_threshold(regime)
            if "threshold" in data:
                thr_override = _to_float(data.get("threshold"))
                if math.isfinite(float(thr_override)) and 0.10 < float(thr_override) < 1.0:
                    thr = float(thr_override)
            EVENTS[evt_id]["arena"] = _arena_snapshot_for_event(pair=str(pair), side=str(side), tag=tag, ts=int(ts or 0), features=merged_features, regime=regime, thr=float(thr), feature_set_id=feature_set_id)
            try:
                if isinstance(EVENTS[evt_id].get("arena"), dict) and isinstance((EVENTS[evt_id].get("arena") or {}).get("models"), dict):
                    EVENTS[evt_id]["arena"]["gate"] = _arena_entry_gate(EVENTS[evt_id]["arena"])
            except Exception:
                pass
        except Exception:
            pass

    trigger = None
    if "trigger_decision" in data:
        trigger = bool(data.get("trigger_decision"))
    elif "auto_decision" in data:
        trigger = bool(data.get("auto_decision"))
    else:
        trigger = bool(CONFIG.get("signals_auto_decision", False))

    if not bool(data.get("bar_closed", True)):
        trigger = False

    try:
        EVENTS[evt_id]["trigger_decision"] = bool(trigger)
    except Exception:
        pass

    resp: Dict[str, Any] = {"ok": True, "id": evt_id}
    if trigger:
        dreq: Dict[str, Any] = {
            "pair": pair,
            "side": side,
            "tag": tag,
            "features": merged_features,
            "size": data.get("size", 0.0),
            "event_id": evt_id,
        }
        if "threshold" in data:
            dreq["threshold"] = data.get("threshold")
        out, code = _decision_entry_impl(dreq)
        resp["auto_decision"] = True
        resp["decision"] = out
        resp["decision_code"] = int(code)
        try:
            evt = EVENTS.get(str(evt_id))
            if isinstance(evt, dict):
                evt["decision_info"] = _build_decision_info(evt, dreq=dreq, out=out, code=int(code), now_ms=now_ms)
                try:
                    _archive_event(evt)
                except Exception:
                    pass
        except Exception:
            pass

    with SIGNAL_DEDUP_LOCK:
        SIGNAL_DEDUP[skey] = {"seen_ms": now_ms, "evt_id": evt_id, "resp": resp}
    return jsonify(resp)

@app.route("/predict", methods=["POST"])
def predict():
    data = request.get_json(force=True) or {}
    side = str(data.get("side", "")).lower()
    features = data.get("features") or {}
    
    if side not in ("long", "short"):
        return jsonify({"ok": False, "error": "invalid_side"}), 400
        
    m = ACTIVE_MODEL.get("obj")
    if ACTIVE_MODEL.get("name") == "__committee__":
        p = _predict_committee(features, side=side)
    elif m is not None:
        p = _predict_with_model(m, features)
    else:
        p = _score(features, side)
        
    pc = _calibrate(p, features)
    return jsonify({"ok": True, "p": p, "pc": pc})

