@app.route("/models/reload", methods=["POST"])
@app.route("/api/models/reload", methods=["POST"])
def models_reload():
    try:
        _load_models()
        name = ACTIVE_MODEL.get("name")
        if name and name != "__committee__" and name not in MODELS:
            ACTIVE_MODEL["name"] = None
            ACTIVE_MODEL["obj"] = None
        if not ACTIVE_MODEL.get("name"):
            ACTIVE_MODEL["name"] = "__committee__"
            ACTIVE_MODEL["obj"] = None
        return jsonify({"ok": True, "models_loaded": list(MODELS.keys())})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500

@app.route("/models/select", methods=["POST"])
@app.route("/api/models/select", methods=["POST"])
def models_select():
    data = request.get_json(force=True) or {}
    name = data.get("name")
    if not name:
        return jsonify({"ok": False, "error": "not_found"}), 404

    if str(name) in ("__score__", "__rule__", "__baseline__", "__none__"):
        ACTIVE_MODEL["name"] = None
        ACTIVE_MODEL["obj"] = None
        return jsonify({"ok": True, "active": ACTIVE_MODEL.get("name")})
        
    if name == "__committee__":
        ACTIVE_MODEL["name"] = "__committee__"
        ACTIVE_MODEL["obj"] = None
        return jsonify({"ok": True, "active": ACTIVE_MODEL.get("name")})
        
    if name not in MODELS:
        return jsonify({"ok": False, "error": "not_found"}), 404
        
    ACTIVE_MODEL["name"] = name
    ACTIVE_MODEL["obj"] = MODELS[name]
    return jsonify({"ok": True, "active": ACTIVE_MODEL.get("name")})


def _arena_enabled() -> bool:
    if str(os.environ.get("PYTEST_CURRENT_TEST", "") or "").strip():
        return False
    return bool(CONFIG.get("arena_enabled", False))


def _arena_find_model_key(tokens: List[str]) -> Any:
    toks = [str(t).lower() for t in (tokens or []) if str(t)]
    if not toks:
        return None
    cands: List[str] = []
    for k in MODELS.keys():
        kl = str(k).lower()
        if all(t in kl for t in toks):
            cands.append(str(k))
    if not cands:
        return None

    def _rank(s: str) -> Tuple[int, int, int, str]:
        sl = s.lower()
        ext = 2
        if sl.endswith(".pkl"):
            ext = 0
        elif sl.endswith(".pth"):
            ext = 1
        online = 1
        if sl.startswith("online_"):
            online = 0
        return (ext, online, len(sl), sl)

    cands.sort(key=_rank)
    return cands[0]


def _arena_default_model_ids(n: int) -> List[str]:
    base6 = ["__xgb__", "__lstm__", "__rf__", "__nn__", "__rule__", "__lr__"]
    base5 = ["__xgb__", "__lstm__", "__rf__", "__nn__", "__lr__"]
    if int(n) <= 0:
        return []
    if int(n) <= 5:
        return base5[: int(n)]
    if int(n) <= 6:
        return base6[: int(n)]
    out = base6[:]
    for k in sorted([str(x) for x in MODELS.keys()]):
        if len(out) >= int(n):
            break
        if k in out:
            continue
        out.append(k)
    return out[: int(n)]


def _arena_display_name(model_id: Any) -> str:
    s = str(model_id or "")
    if s in ("__xgb__",):
        return "XGBoost"
    if s in ("__lstm__",):
        return "LSTM"
    if s in ("__rf__",):
        return "RandomForest"
    if s in ("__transformer__",):
        return "Transformer"
    if s in ("__nn__",):
        return "NN"
    if s in ("__lr__",):
        return "LinearRegression"
    if s in ("__rule__", "__score__"):
        return "规则基线"

    sl = s.lower()
    if "xgb" in sl:
        return "XGBoost"
    if "lstm" in sl:
        return "LSTM"
    if "transformer" in sl:
        return "Transformer"
    if "randomforest" in sl or sl.startswith("rf") or "_rf" in sl:
        return "RandomForest"
    if sl.startswith("nn") or "_nn" in sl:
        return "NN"
    if sl.startswith("lr") or "_lr" in sl or "linear" in sl:
        return "LinearRegression"
    if s.startswith("__") and s.endswith("__") and len(s) >= 4:
        return s.strip("_")
    for ext in (".pkl", ".pth", ".joblib"):
        if s.endswith(ext):
            return s[: -len(ext)]
    return s


def _arena_model_names() -> List[str]:
    cfg = CONFIG.get("arena_model_names")
    if isinstance(cfg, list) and cfg:
        names = [str(x) for x in cfg if str(x)]
    else:
        try:
            n = int(CONFIG.get("arena_n_models", 5) or 5)
        except Exception:
            n = 5
        names = _arena_default_model_ids(int(n))
    return names


def _arena_regime_key(regime: Any) -> str:
    s = ("" if regime is None else str(regime)).strip()
    return s if s else "__all__"


def _arena_take_rate_target() -> float:
    try:
        tgt = float(CONFIG.get("arena_take_rate_target", 0.12) or 0.12)
    except Exception:
        tgt = 0.12
    try:
        lo = float(CONFIG.get("arena_take_rate_min", 0.05) or 0.05)
    except Exception:
        lo = 0.05
    try:
        hi = float(CONFIG.get("arena_take_rate_max", 0.20) or 0.20)
    except Exception:
        hi = 0.20
    lo = max(0.0, min(1.0, float(lo)))
    hi = max(0.0, min(1.0, float(hi)))
    if float(hi) < float(lo):
        hi = lo
    return float(_clip(float(tgt), float(lo), float(hi)))


def _arena_quantile(xs: List[float], q: float) -> float:
    if not xs:
        return 0.0
    qq = float(_clip(float(q), 0.0, 1.0))
    ys = sorted(float(x) for x in xs)
    n = len(ys)
    if n == 1:
        return float(ys[0])
    pos = qq * float(n - 1)
    i = int(math.floor(pos))
    j = int(math.ceil(pos))
    if i == j:
        return float(ys[i])
    w = float(pos - float(i))
    return float((1.0 - w) * float(ys[i]) + w * float(ys[j]))


def _arena_init_if_needed(now_ms: int = None) -> None:
    if not _arena_enabled():
        return
    if not isinstance(ARENA_STATE, dict):
        return
    names = _arena_model_names()
    if not names:
        return
    ts0 = int(now_ms or _now_ms())
    try:
        init_cap = float(CONFIG.get("arena_init_capital_u", 100.0) or 100.0)
    except Exception:
        init_cap = 100.0
    try:
        init_pool = float(CONFIG.get("arena_init_pool_u", 100.0) or 100.0)
    except Exception:
        init_pool = 100.0
    w0 = 1.0 / float(len(names)) if len(names) > 0 else 0.0

    eq_max = 2000
    try:
        eq_max = int(CONFIG.get("arena_equity_max_points", 2000) or 2000)
    except Exception:
        eq_max = 2000
    eq_max = max(10, int(eq_max))

    try:
        min_settled = int(CONFIG.get("arena_eligible_min_settled", 0) or 0)
    except Exception:
        min_settled = 0
    try:
        min_takes = int(CONFIG.get("arena_eligible_min_takes", 0) or 0)
    except Exception:
        min_takes = 0

    if "attrib" not in ARENA_STATE or not isinstance(ARENA_STATE.get("attrib"), list):
        ARENA_STATE["attrib"] = []
    if "model_calib" not in ARENA_STATE or not isinstance(ARENA_STATE.get("model_calib"), dict):
        ARENA_STATE["model_calib"] = {}
    if "layer2" not in ARENA_STATE or not isinstance(ARENA_STATE.get("layer2"), dict):
        ARENA_STATE["layer2"] = {"last_train_ms": 0, "attrib_count": 0, "updated": {}}
    if "diversity" not in ARENA_STATE or not isinstance(ARENA_STATE.get("diversity"), dict):
        ARENA_STATE["diversity"] = {}
    if "attrib_count" not in (ARENA_STATE.get("layer2") or {}):
        try:
            ARENA_STATE["layer2"]["attrib_count"] = int(len(ARENA_STATE.get("attrib") or []))
        except Exception:
            ARENA_STATE["layer2"]["attrib_count"] = 0

    if bool(ARENA_STATE.get("inited")) and isinstance(ARENA_STATE.get("models"), dict):
        cur_models = ARENA_STATE.get("models")
        cur_keys = set([str(k) for k in cur_models.keys()])
        want_keys = set([str(k) for k in names])
        if cur_keys != want_keys:
            models: Dict[str, Dict[str, Any]] = {}
            for n in names:
                k = str(n)
                prev = cur_models.get(k)
                if isinstance(prev, dict):
                    rec = dict(prev)
                    rec["name"] = k
                    if "capital_u" not in rec:
                        rec["capital_u"] = float(init_cap)
                    if "weight" not in rec:
                        rec["weight"] = float(w0)
                    for kk in ("takes", "skips", "wins", "losses", "settled", "revives", "last_settle_ms"):
                        if kk not in rec:
                            rec[kk] = 0
                    if "equity" not in rec or not isinstance(rec.get("equity"), list):
                        rec["equity"] = [{"ts": int(ts0), "equity_u": float(rec.get("capital_u") or init_cap)}]
                    if "equity_peak_u" not in rec:
                        rec["equity_peak_u"] = float(rec.get("capital_u") or init_cap)
                    if "max_dd" not in rec:
                        rec["max_dd"] = 0.0
                    if "ll_sum" not in rec:
                        rec["ll_sum"] = 0.0
                    if "ll_n" not in rec:
                        rec["ll_n"] = 0
                    if "pnl_sum_u" not in rec:
                        rec["pnl_sum_u"] = 0.0
                    if "fees_sum_u" not in rec:
                        rec["fees_sum_u"] = 0.0
                    if "funding_sum_u" not in rec:
                        rec["funding_sum_u"] = 0.0
                    if "eligible" not in rec:
                        rec["eligible"] = True
                    if "eligible_after_settled" not in rec:
                        rec["eligible_after_settled"] = 0
                    if "eligible_min_takes" not in rec:
                        rec["eligible_min_takes"] = 0
                    if "log_w_base" not in rec:
                        try:
                            rec["log_w_base"] = float(math.log(max(1e-12, float(rec.get("weight") or w0))))
                        except Exception:
                            rec["log_w_base"] = float(math.log(max(1e-12, float(w0))))
                    if "log_w_regime" not in rec or not isinstance(rec.get("log_w_regime"), dict):
                        rec["log_w_regime"] = {}
                    if "bandit" not in rec or not isinstance(rec.get("bandit"), dict):
                        rec["bandit"] = {}
                    if "pc_hist" not in rec or not isinstance(rec.get("pc_hist"), dict):
                        rec["pc_hist"] = {}
                    if "ll_ema" not in rec:
                        rec["ll_ema"] = 0.693147
                    try:
                        eq = rec.get("equity")
                        if isinstance(eq, list) and len(eq) > eq_max:
                            rec["equity"] = eq[-eq_max:]
                    except Exception:
                        pass
                    models[k] = rec
                else:
                    models[k] = {
                        "name": k,
                        "capital_u": float(init_cap),
                        "weight": float(w0),
                        "log_w_base": float(math.log(max(1e-12, float(w0)))),
                        "log_w_regime": {},
                        "bandit": {},
                        "pc_hist": {},
                        "ll_ema": 0.693147,
                        "eligible": False,
                        "eligible_after_settled": int(min_settled),
                        "eligible_min_takes": int(min_takes),
                        "takes": 0,
                        "skips": 0,
                        "wins": 0,
                        "losses": 0,
                        "settled": 0,
                        "revives": 0,
                        "last_settle_ms": 0,
                        "equity": [{"ts": int(ts0), "equity_u": float(init_cap)}],
                        "equity_peak_u": float(init_cap),
                        "max_dd": 0.0,
                        "ll_sum": 0.0,
                        "ll_n": 0,
                        "pnl_sum_u": 0.0,
                        "fees_sum_u": 0.0,
                        "funding_sum_u": 0.0,
                    }
            s = sum(float(v.get("weight") or 0.0) for v in models.values())
            if s <= 1e-12:
                for v in models.values():
                    v["weight"] = float(w0)
            else:
                for v in models.values():
                    v["weight"] = float(v.get("weight") or 0.0) / float(s)

            ARENA_STATE["models"] = models
            ARENA_STATE["ts"] = int(ts0)
        else:
            updated = False
            for n in names:
                k = str(n)
                st = cur_models.get(k)
                if not isinstance(st, dict):
                    continue
                if "equity" not in st or not isinstance(st.get("equity"), list):
                    st["equity"] = [{"ts": int(ts0), "equity_u": float(st.get("capital_u") or init_cap)}]
                    updated = True
                if "equity_peak_u" not in st:
                    st["equity_peak_u"] = float(st.get("capital_u") or init_cap)
                    updated = True
                for kk, dv in (
                    ("max_dd", 0.0),
                    ("ll_sum", 0.0),
                    ("ll_n", 0),
                    ("pnl_sum_u", 0.0),
                    ("fees_sum_u", 0.0),
                    ("funding_sum_u", 0.0),
                ):
                    if kk not in st:
                        st[kk] = dv
                        updated = True
                if "log_w_base" not in st:
                    try:
                        st["log_w_base"] = float(math.log(max(1e-12, float(st.get("weight") or w0))))
                    except Exception:
                        st["log_w_base"] = float(math.log(max(1e-12, float(w0))))
                    updated = True
                if "log_w_regime" not in st or not isinstance(st.get("log_w_regime"), dict):
                    st["log_w_regime"] = {}
                    updated = True
                if "bandit" not in st or not isinstance(st.get("bandit"), dict):
                    st["bandit"] = {}
                    updated = True
                if "pc_hist" not in st or not isinstance(st.get("pc_hist"), dict):
                    st["pc_hist"] = {}
                    updated = True
                if "ll_ema" not in st:
                    st["ll_ema"] = 0.693147
                    updated = True
                try:
                    eq = st.get("equity")
                    if isinstance(eq, list) and len(eq) > eq_max:
                        st["equity"] = eq[-eq_max:]
                        updated = True
                except Exception:
                    pass
            if updated:
                ARENA_STATE["ts"] = int(ts0)
        return

    models: Dict[str, Dict[str, Any]] = {}
    for n in names:
        models[str(n)] = {
            "name": str(n),
            "capital_u": float(init_cap),
            "weight": float(w0),
            "log_w_base": float(math.log(max(1e-12, float(w0)))),
            "log_w_regime": {},
            "bandit": {},
            "pc_hist": {},
            "ll_ema": 0.693147,
            "eligible": True,
            "eligible_after_settled": 0,
            "eligible_min_takes": 0,
            "takes": 0,
            "skips": 0,
            "wins": 0,
            "losses": 0,
            "settled": 0,
            "revives": 0,
            "last_settle_ms": 0,
            "equity": [{"ts": int(ts0), "equity_u": float(init_cap)}],
            "equity_peak_u": float(init_cap),
            "max_dd": 0.0,
            "ll_sum": 0.0,
            "ll_n": 0,
            "pnl_sum_u": 0.0,
            "fees_sum_u": 0.0,
            "funding_sum_u": 0.0,
        }
    ARENA_STATE.clear()
    ARENA_STATE.update({
        "inited": True,
        "pool_u": float(init_pool),
        "models": models,
        "history": [],
        "attrib": [],
        "model_calib": {},
        "layer2": {"last_train_ms": 0, "attrib_count": 0, "updated": {}},
        "ts": int(ts0),
    })


def _arena_calibrate_model(model_id: str, p: float, features: Dict[str, Any] = None, regime: str = None) -> float:
    mid = str(model_id or "")
    if mid and isinstance(ARENA_STATE, dict):
        try:
            cm = (ARENA_STATE.get("model_calib") or {}).get(mid)
        except Exception:
            cm = None
        if isinstance(cm, dict) and cm.get("method") == "platt1d":
            m = cm.get("params")
            if isinstance(m, dict):
                try:
                    a = float(m.get("a", 1.0))
                    b = float(m.get("b", 0.0))
                    return float(_sigmoid(a * float(p) + b))
                except Exception:
                    pass
    return float(_calibrate(float(p), features=features, regime=regime))


def _arena_layer2_dataset_for_model(items: List[Dict[str, Any]], model_id: str) -> Tuple[List[float], List[float], List[float]]:
    mid = str(model_id or "")
    xs: List[float] = []
    ys: List[float] = []
    ws: List[float] = []
    try:
        fail_w = float(CONFIG.get("arena_layer2_fail_weight", 3.0) or 3.0)
    except Exception:
        fail_w = 3.0
    try:
        wcap = float(CONFIG.get("arena_layer2_weight_cap", 10.0) or 10.0)
    except Exception:
        wcap = 10.0

    for it in items:
        if not isinstance(it, dict):
            continue
        p_star = it.get("p_star")
        if p_star is None:
            continue
        try:
            p_star_f = float(p_star)
        except Exception:
            continue
        if not math.isfinite(p_star_f):
            continue
        p_star_f = float(_clip(p_star_f, 0.0, 1.0))

        models = it.get("models")
        if not isinstance(models, dict):
            continue
        mv = models.get(mid)
        if not isinstance(mv, dict):
            continue
        p = mv.get("p")
        if p is None:
            continue
        try:
            p_f = float(p)
        except Exception:
            continue
        if not math.isfinite(p_f):
            continue
        p_f = float(_clip(p_f, 1e-6, 1.0 - 1e-6))

        w = 1.0
        try:
            y = int(it.get("y") or 0)
        except Exception:
            y = 0
        correct_take = True if int(y) == 1 else False
        try:
            winner_id = it.get("winner_id")
        except Exception:
            winner_id = None

        try:
            model_take = bool(mv.get("take", False))
        except Exception:
            model_take = False
        winner_take = None
        if winner_id is not None and str(winner_id) in models:
            wv = models.get(str(winner_id))
            if isinstance(wv, dict):
                try:
                    winner_take = bool(wv.get("take", False))
                except Exception:
                    winner_take = None
        if winner_take is not None:
            winner_correct = bool(winner_take) == bool(correct_take)
            model_fail = bool(model_take) != bool(correct_take)
            if winner_correct and model_fail:
                w *= float(fail_w)
        if float(wcap) > 0:
            w = float(_clip(float(w), 0.0, float(wcap)))

        xs.append(float(p_f))
        ys.append(float(p_star_f))
        ws.append(float(w))
    return xs, ys, ws


def _arena_layer2_mse_platt1d(xs: List[float], ys: List[float], ws: List[float], a: float = None, b: float = None, baseline_model_id: str = None, baseline_regime: str = None) -> float:
    if not xs or not ys:
        return float("inf")
    wsum = 0.0
    sse = 0.0
    for i, (x, y) in enumerate(zip(xs, ys)):
        try:
            w = float(ws[i]) if ws and i < len(ws) else 1.0
        except Exception:
            w = 1.0
        w = max(0.0, float(w))
        if w <= 0.0:
            continue
        if a is None or b is None:
            try:
                pred = float(_arena_calibrate_model(str(baseline_model_id or ""), float(x), features=None, regime=baseline_regime))
            except Exception:
                pred = float(_clip(float(x), 0.0, 1.0))
        else:
            try:
                pred = float(_sigmoid(float(a) * float(x) + float(b)))
            except Exception:
                pred = float(_clip(float(x), 0.0, 1.0))
        d = float(pred) - float(y)
        sse += float(w) * float(d) * float(d)
        wsum += float(w)
    if wsum <= 1e-12:
        return float("inf")
    return float(sse) / float(wsum)


def _arena_layer2_mse_mode(xs: List[float], ys: List[float], ws: List[float], mode: str, model_id: str = None, regime: str = None) -> float:
    if not xs or not ys:
        return float("inf")
    mm = str(mode or "").lower()
    wsum = 0.0
    sse = 0.0
    for i, (x, y) in enumerate(zip(xs, ys)):
        try:
            w = float(ws[i]) if ws and i < len(ws) else 1.0
        except Exception:
            w = 1.0
        w = max(0.0, float(w))
        if w <= 0.0:
            continue
        if mm == "raw":
            pred = float(_clip(float(x), 0.0, 1.0))
        elif mm == "global":
            try:
                pred = float(_calibrate(float(x), features=None, regime=regime))
            except Exception:
                pred = float(_clip(float(x), 0.0, 1.0))
        else:
            try:
                pred = float(_arena_calibrate_model(str(model_id or ""), float(x), features=None, regime=regime))
            except Exception:
                pred = float(_clip(float(x), 0.0, 1.0))
        d = float(pred) - float(y)
        sse += float(w) * float(d) * float(d)
        wsum += float(w)
    if wsum <= 1e-12:
        return float("inf")
    return float(sse) / float(wsum)


def _arena_layer2_train_if_needed(now_ms: int, force: bool = False) -> Dict[str, Any]:
    if not _arena_enabled():
        return {"ok": True, "trained": False, "enabled": False}
    if not bool(CONFIG.get("arena_layer2_enabled", True)):
        return {"ok": True, "trained": False, "enabled": True, "skipped": "disabled"}
    _arena_init_if_needed(now_ms=now_ms)

    items = ARENA_STATE.get("attrib") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(items, list) or not items:
        return {"ok": True, "trained": False, "enabled": True, "reason": "no_attrib"}

    st = ARENA_STATE.get("layer2") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(st, dict):
        st = {"last_train_ms": 0, "attrib_count": 0, "updated": {}}
        ARENA_STATE["layer2"] = st
    prev = int(st.get("attrib_count") or 0)
    cur = int(len(items))
    new = int(cur) - int(prev)
    try:
        min_new = int(CONFIG.get("arena_layer2_min_new_attrib", 200) or 200)
    except Exception:
        min_new = 200
    if not force and int(new) < int(min_new):
        return {"ok": True, "trained": False, "enabled": True, "new_attrib": int(new), "min_new_attrib": int(min_new), "total_attrib": int(cur)}

    try:
        win = int(CONFIG.get("arena_layer2_train_window", 2000) or 2000)
    except Exception:
        win = 2000
    win = max(0, int(win))
    ss = list(items)[-win:] if win > 0 else list(items)
    try:
        oos_size = int(CONFIG.get("arena_layer2_oos_size", 200) or 200)
    except Exception:
        oos_size = 200
    oos_size = max(0, int(oos_size))
    try:
        oos_rolls = int(CONFIG.get("arena_layer2_oos_rolls", 3) or 3)
    except Exception:
        oos_rolls = 3
    oos_rolls = max(1, int(oos_rolls))
    try:
        min_train = int(CONFIG.get("arena_layer2_min_train", 200) or 200)
    except Exception:
        min_train = 200
    try:
        min_oos = int(CONFIG.get("arena_layer2_min_oos", 50) or 50)
    except Exception:
        min_oos = 50
    oos_total = int(oos_size) * int(oos_rolls)
    if oos_size <= 0 or int(oos_size) < int(min_oos) or len(ss) < (int(min_train) + int(min_oos)) or len(ss) < (int(min_train) + int(oos_total)):
        return {"ok": True, "trained": False, "enabled": True, "reason": "insufficient_samples", "total": int(len(ss)), "need": int(int(min_train) + int(oos_total)), "oos_size": int(oos_size), "min_oos": int(min_oos)}

    roll_windows: List[Dict[str, Any]] = []
    for r in range(int(oos_rolls)):
        end = int(len(ss)) - int(r) * int(oos_size)
        start_oos = int(end) - int(oos_size)
        if end <= 0:
            break
        if start_oos < 0:
            start_oos = 0
        if end <= start_oos:
            break
        oos_items = ss[start_oos:end]
        train_end = int(start_oos)
        train_start = max(0, int(train_end) - int(max(0, int(win) - int(oos_size))))
        train_items = ss[train_start:train_end]
        if len(train_items) < int(min_train) or len(oos_items) < int(min_oos):
            continue
        roll_windows.append({
            "roll": int(r),
            "train": train_items,
            "oos": oos_items,
            "train_n": int(len(train_items)),
            "oos_n": int(len(oos_items)),
            "oos_start_ts": int((oos_items[0] or {}).get("ts") or 0),
            "oos_end_ts": int((oos_items[-1] or {}).get("ts") or 0),
        })

    if not roll_windows:
        return {"ok": True, "trained": False, "enabled": True, "reason": "no_oos_windows", "total": int(len(ss)), "oos_size": int(oos_size), "rolls": int(oos_rolls)}

    try:
        min_improve = float(CONFIG.get("arena_layer2_min_improve", 1e-4) or 1e-4)
    except Exception:
        min_improve = 1e-4

    models_state = ARENA_STATE.get("models") if isinstance(ARENA_STATE, dict) else None
    state_ids = [str(k) for k in (models_state or {}).keys()] if isinstance(models_state, dict) else []

    attrib_ids: List[str] = []
    for it in ss:
        if not isinstance(it, dict):
            continue
        mm = it.get("models")
        if not isinstance(mm, dict):
            continue
        for k in mm.keys():
            attrib_ids.append(str(k))
    attrib_ids = sorted(list(set([x for x in attrib_ids if x])))

    model_ids = state_ids
    if attrib_ids:
        if model_ids:
            inter = [x for x in model_ids if x in set(attrib_ids)]
            model_ids = inter if inter else attrib_ids
        else:
            model_ids = attrib_ids

    if not model_ids:
        return {"ok": True, "trained": False, "enabled": True, "reason": "no_models"}

    updated: Dict[str, Any] = {}
    for mid in model_ids:
        win_metrics = []
        n_pos = 0
        base_sum = 0.0
        cand_sum = 0.0
        n_used = 0
        n_oos_total = 0

        for rw in roll_windows:
            tr_items = rw.get("train")
            oos_items = rw.get("oos")
            if not isinstance(tr_items, list) or not isinstance(oos_items, list):
                continue
            xtr, ytr, wtr = _arena_layer2_dataset_for_model(tr_items, mid)
            xo, yo, wo = _arena_layer2_dataset_for_model(oos_items, mid)
            if len(xtr) < int(min_train) or len(xo) < int(min_oos):
                continue
            params = _platt_fit_soft_1d(xtr, ytr, weights=wtr, steps=int(CONFIG.get("arena_layer2_platt_steps", 500) or 500))
            a = float(params.get("a", 1.0))
            b = float(params.get("b", 0.0))

            base = _arena_layer2_mse_platt1d(xo, yo, wo, a=None, b=None, baseline_model_id=mid)
            cand = _arena_layer2_mse_platt1d(xo, yo, wo, a=a, b=b)
            if not (math.isfinite(base) and math.isfinite(cand)):
                continue
            improve = float(base) - float(cand)
            if float(improve) > 0.0:
                n_pos += 1
            n_oos = int(len(xo))
            base_sum += float(base) * float(n_oos)
            cand_sum += float(cand) * float(n_oos)
            n_used += 1
            n_oos_total += int(n_oos)
            win_metrics.append({
                "roll": int(rw.get("roll") or 0),
                "n_train": int(len(xtr)),
                "n_oos": int(n_oos),
                "oos_start_ts": int(rw.get("oos_start_ts") or 0),
                "oos_end_ts": int(rw.get("oos_end_ts") or 0),
                "oos_mse_base": float(base),
                "oos_mse": float(cand),
                "improve": float(improve),
            })

        if n_used <= 0:
            continue
        denom = float(n_oos_total) if int(n_oos_total) > 0 else float(n_used)
        base_avg = float(base_sum) / float(denom)
        cand_avg = float(cand_sum) / float(denom)
        improve_avg = float(base_avg) - float(cand_avg)
        min_pos = max(1, int(math.ceil(float(n_used) * 0.6)))
        if int(n_pos) < int(min_pos) or float(improve_avg) < float(min_improve):
            continue

        xfit, yfit, wfit = _arena_layer2_dataset_for_model(ss, mid)
        if len(xfit) < int(min_train):
            continue
        params_fit = _platt_fit_soft_1d(xfit, yfit, weights=wfit, steps=int(CONFIG.get("arena_layer2_platt_steps", 500) or 500))
        a_fit = float(params_fit.get("a", 1.0))
        b_fit = float(params_fit.get("b", 0.0))
        mc = ARENA_STATE.get("model_calib") if isinstance(ARENA_STATE, dict) else None
        if not isinstance(mc, dict):
            mc = {}
            ARENA_STATE["model_calib"] = mc
        mc[str(mid)] = {
            "method": "platt1d",
            "params": {"a": float(a_fit), "b": float(b_fit)},
            "ts": int(now_ms),
            "metrics": {"oos_mse_base": float(base_avg), "oos_mse": float(cand_avg), "improve": float(improve_avg), "n_fit": int(len(xfit)), "oos_rolls": int(oos_rolls), "oos_used": int(n_used), "n_oos": int(n_oos_total), "oos_windows": win_metrics},
        }
        updated[str(mid)] = {"oos_mse_base": float(base_avg), "oos_mse": float(cand_avg), "improve": float(improve_avg), "oos_used": int(n_used)}

    try:
        st["last_train_ms"] = int(now_ms)
        st["attrib_count"] = int(cur)
        st["updated"] = updated
        ARENA_STATE["layer2"] = st
    except Exception:
        pass

    return {"ok": True, "trained": True, "enabled": True, "updated": updated, "oos_rolls": int(oos_rolls), "oos_size": int(oos_size), "oos_windows": int(len(roll_windows)), "total": int(len(ss)), "model_ids": model_ids}


_ARTIFACT_META_CACHE: Dict[str, Dict[str, Any]] = {}


def _artifact_meta_for_name(name: str) -> Dict[str, Any]:
    n = str(name or "")
    if not n:
        return {}
    cached = _ARTIFACT_META_CACHE.get(n)
    if isinstance(cached, dict):
        return cached
    meta: Dict[str, Any] = {}
    try:
        for d in _models_dirs_all():
            p = Path(d) / n
            if p.exists():
                meta = _read_artifact_meta_for_file(p)
                break
    except Exception:
        meta = {}
    if not isinstance(meta, dict):
        meta = {}

    if not meta:
        try:
            obj = MODELS.get(n)
            fam = _infer_family_from_filename(n)
            keys: List[str] = []
            train_samples = None
            fsid_in = None
            if isinstance(obj, dict):
                kk = obj.get("keys")
                if isinstance(kk, list) and kk:
                    keys = [str(x) for x in kk if str(x)]
                mk = obj.get("feature_keys")
                if (not keys) and isinstance(mk, list) and mk:
                    keys = [str(x) for x in mk if str(x)]
                for k in ("train_samples", "n_train", "n_samples", "samples"):
                    if obj.get(k) is not None:
                        try:
                            train_samples = int(obj.get(k) or 0)
                        except Exception:
                            train_samples = None
                        break
                if obj.get("feature_set_id") is not None:
                    fsid_in = str(obj.get("feature_set_id") or "").strip() or None
            else:
                try:
                    fn = getattr(obj, "feature_names_in_", None)
                    if fn is not None:
                        keys = [str(x) for x in list(fn) if str(x)]
                except Exception:
                    keys = []
                if not keys:
                    try:
                        nfi = getattr(obj, "n_features_in_", None)
                        if nfi is not None:
                            nfi_i = int(nfi)
                            if nfi_i == len(_ml3_feature_keys()):
                                keys = list(_ml3_feature_keys())
                            else:
                                keys = list(_eval_feature_keys(fam, None) if fam else _eval_feature_keys(None, None))
                                if len(keys) > nfi_i:
                                    keys = keys[:nfi_i]
                                elif len(keys) < nfi_i:
                                    keys = keys + [f"__pad_{i}__" for i in range(nfi_i - len(keys))]
                    except Exception:
                        keys = []
            fsid_guess = _resolve_feature_set_id_for_meta(None, {"feature_set_id": fsid_in, "feature_keys": list(keys)})
            sig = _feature_set_id([str(x) for x in (keys or []) if str(x)]) if keys else None
            meta = {
                "trained_at_ms": None,
                "train_samples": train_samples,
                "new_samples": None,
                "family": (str(fam) if fam else None),
                "filename": str(n),
                "online_version": None,
                "feature_set_version": _feature_set_version(),
                "feature_set_id": fsid_guess or (str(sig) if sig else None),
                "feature_set_sig": (str(sig) if sig else None),
                "signal_feature_set_id": None,
                "feature_keys": list(keys),
                "metrics": None,
                "backfilled": True,
            }
        except Exception:
            meta = {}
    _ARTIFACT_META_CACHE[n] = meta
    return meta


def _arena_model_family(model_id: str) -> Optional[str]:
    s = str(model_id or "")
    if not s:
        return None
    if s in ("__xgb__",):
        return "xgb"
    if s in ("__lstm__",):
        return "lstm"
    if s in ("__rf__",):
        return "rf"
    if s in ("__nn__",):
        return "nn"
    if s in ("__transformer__",):
        return "transformer"
    if s in ("__lr__",):
        return "lr"
    sl = s.lower()
    if "xgb" in sl:
        return "xgb"
    if "lstm" in sl:
        return "lstm"
    if "transformer" in sl:
        return "transformer"
    if "rf" in sl and "surf" not in sl:
        return "rf"
    if "_nn" in sl or sl.startswith("nn"):
        return "nn"
    if "_lr" in sl or sl.startswith("lr") or "linear" in sl:
        return "lr"
    return None


def _resolve_feature_set_id_for_meta(feature_set_id: Optional[str], meta: Optional[Dict[str, Any]] = None) -> Optional[str]:
    fsid = str(feature_set_id or "").strip() or None
    if fsid and _feature_set_keys_get(fsid):
        return fsid
    if isinstance(meta, dict):
        mfsid = str(meta.get("feature_set_id") or "").strip() or None
        if mfsid and _feature_set_keys_get(mfsid):
            return mfsid
        sfsid = str(meta.get("signal_feature_set_id") or "").strip() or None
        if sfsid and _feature_set_keys_get(sfsid):
            return sfsid
        mk = meta.get("feature_keys")
        if isinstance(mk, list) and mk:
            keys = [str(x) for x in mk if str(x)]
            keyset = set(keys)
            cfg = CONFIG.get("feature_set_keys")
            best = None
            best_score = 0.0
            best_jaccard = 0.0
            if isinstance(cfg, dict):
                for name, vv in cfg.items():
                    if not isinstance(vv, list) or not vv:
                        continue
                    vkeys = [str(x) for x in vv if str(x)]
                    vset = set(vkeys)
                    inter = len(keyset & vset)
                    if inter <= 0:
                        continue
                    union = len(keyset | vset)
                    jaccard = float(inter) / float(union) if union > 0 else 0.0
                    denom_keys = float(len(keyset)) if len(keyset) > 0 else 1.0
                    coverage = float(inter) / float(denom_keys)
                    score = float(coverage)
                    if score > best_score or (abs(score - best_score) <= 1e-12 and jaccard > best_jaccard):
                        best_score = score
                        best_jaccard = jaccard
                        best = str(name)
            if best is not None and best_score >= 0.70 and _feature_set_keys_get(best):
                return best
    return fsid


def _predict_obj_with_keys(m: Any, features: Dict[str, Any], side: str, keys: List[str]) -> float:
    keys0 = [str(k) for k in (keys or []) if str(k)]
    try:
        if hasattr(m, "feature_names_in_") and getattr(m, "feature_names_in_", None) is not None:
            keys0 = [str(x) for x in list(getattr(m, "feature_names_in_")) if str(x)]
    except Exception:
        pass
    try:
        nfi = getattr(m, "n_features_in_", None)
        if nfi is not None:
            nfi = int(nfi)
            if nfi == len(_ml3_feature_keys()) and len(keys0) != nfi:
                keys0 = _ml3_feature_keys()
            elif nfi > 0 and len(keys0) != nfi:
                if len(keys0) > nfi:
                    keys0 = keys0[:nfi]
                else:
                    keys0 = keys0 + [f"__pad_{i}__" for i in range(nfi - len(keys0))]
    except Exception:
        pass
    x = [[_scale_value(k, _to_float(features.get(k, 0.0))) for k in keys0]]
    try:
        if hasattr(m, "predict_proba"):
            proba = m.predict_proba(x)
            if getattr(proba, "shape", None) is not None and proba.shape[1] > 1:
                try:
                    cls = getattr(m, "classes_", None)
                    if cls is not None:
                        for i, c in enumerate(list(cls)):
                            try:
                                if int(c) == 1:
                                    return float(proba[0][i])
                            except Exception:
                                if str(c) == "1":
                                    return float(proba[0][i])
                except Exception:
                    pass
                if proba.shape[1] == 2:
                    return float(proba[0][1])
                return float(proba[0][-1])
            return float(proba[0][0])
        if hasattr(m, "predict"):
            y = m.predict(x)
            return float(y[0])
    except Exception:
        pass
    return float(_score(features, side))


def _arena_predict_one(model_name: str, features: Dict[str, Any], side: str, regime: str, feature_set_id: Optional[str] = None) -> Tuple[float, float]:
    name = str(model_name)
    if name in ("__rule__", "__score__"):
        p = _score(features, side)
    elif name.startswith("__score_t") and name.endswith("__"):
        p0 = float(_score(features, side))
        t_raw = name[len("__score_t") : -len("__")]
        try:
            t = float(t_raw)
        except Exception:
            t = 1.0
        t = max(1e-6, float(t))
        p0 = float(_clip(float(p0), 1e-6, 1.0 - 1e-6))
        logit = math.log(p0 / (1.0 - p0))
        p = 1.0 / (1.0 + math.exp(-logit / float(t)))
    elif name in ("__xgb__", "__lstm__", "__rf__", "__nn__", "__transformer__", "__lr__"):
        resolved = None
        if name == "__xgb__":
            resolved = _arena_find_model_key(["xgb"])
        elif name == "__lstm__":
            resolved = _arena_find_model_key(["lstm"])
        elif name == "__rf__":
            resolved = _arena_find_model_key(["rf"])
        elif name == "__nn__":
            resolved = _arena_find_model_key(["nn"])
        elif name == "__transformer__":
            resolved = _arena_find_model_key(["transformer"])
        elif name == "__lr__":
            resolved = _arena_find_model_key(["lr"])
        if resolved is not None and str(resolved) in MODELS:
            mk = str(resolved)
            obj = MODELS.get(mk)
            fam = _arena_model_family(name)
            meta = _artifact_meta_for_name(mk)
            fsid2 = _resolve_feature_set_id_for_meta(feature_set_id, meta)
            keys_pref = _eval_feature_keys(fam, fsid2) if fam else _eval_feature_keys(None, fsid2)
            keys_obj = None
            if isinstance(obj, dict):
                kk = obj.get("keys")
                if isinstance(kk, list) and kk:
                    keys_obj = [str(x) for x in kk if str(x)]
            if keys_obj is None:
                mk2 = meta.get("feature_keys")
                if isinstance(mk2, list) and mk2:
                    keys_obj = [str(x) for x in mk2 if str(x)]
            if keys_obj is None:
                keys_obj = list(keys_pref)
            if isinstance(keys_pref, list) and keys_pref:
                pref_set = set(str(x) for x in keys_pref if str(x))
                keys_obj = [k for k in keys_obj if k in pref_set] or list(keys_obj)
            if isinstance(obj, dict) and obj.get("type"):
                obj2 = dict(obj)
                obj2["keys"] = list(keys_obj)
                p = _predict_with_model(obj2, features)
            else:
                p = _predict_obj_with_keys(obj, features, side, list(keys_obj))
        else:
            p = _score(features, side)
    elif name in MODELS:
        obj = MODELS.get(name)
        fam = _arena_model_family(name)
        meta = _artifact_meta_for_name(name)
        fsid2 = _resolve_feature_set_id_for_meta(feature_set_id, meta)
        keys_pref = _eval_feature_keys(fam, fsid2) if fam else _eval_feature_keys(None, fsid2)
        keys_obj = None
        if isinstance(obj, dict):
            kk = obj.get("keys")
            if isinstance(kk, list) and kk:
                keys_obj = [str(x) for x in kk if str(x)]
        if keys_obj is None:
            mk2 = meta.get("feature_keys")
            if isinstance(mk2, list) and mk2:
                keys_obj = [str(x) for x in mk2 if str(x)]
        if keys_obj is None:
            keys_obj = list(keys_pref)
        if isinstance(keys_pref, list) and keys_pref:
            pref_set = set(str(x) for x in keys_pref if str(x))
            keys_obj = [k for k in keys_obj if k in pref_set] or list(keys_obj)
        if isinstance(obj, dict) and obj.get("type"):
            obj2 = dict(obj)
            obj2["keys"] = list(keys_obj)
            p = _predict_with_model(obj2, features)
        else:
            p = _predict_obj_with_keys(obj, features, side, list(keys_obj))
    else:
        p = _score(features, side)
    pc = _arena_calibrate_model(str(model_name), float(p), features=features, regime=regime)
    return float(p), float(pc)

def _dynamic_threshold_auto_update_from_arena(regime: str, models: Dict[str, Any], now_ms: int) -> Optional[Dict[str, Any]]:
    try:
        if not bool(CONFIG.get("dynamic_threshold_auto_enabled", True)):
            return None
        if not bool(CONFIG.get("arena_dynamic_threshold_enabled", False)):
            return None
        if not isinstance(models, dict) or not models:
            return None
        rk = str(regime or "trend")

        thrs: List[float] = []
        for _, m in models.items():
            if not isinstance(m, dict):
                continue
            if not bool(m.get("eligible", True)):
                continue
            try:
                t = float(m.get("thr"))
            except Exception:
                continue
            if (not math.isfinite(float(t))) or (float(t) <= 0.0) or (float(t) >= 1.0):
                continue
            thrs.append(float(t))
        if len(thrs) < 2:
            return None
        thrs.sort()
        mid = len(thrs) // 2
        thr_med = float(thrs[mid]) if (len(thrs) % 2 == 1) else 0.5 * float(thrs[mid - 1] + thrs[mid])

        try:
            window_sec = int(CONFIG.get("dynamic_threshold_auto_window_sec", 900) or 900)
        except Exception:
            window_sec = 900
        window_sec = int(max(60, min(6 * 3600, int(window_sec))))
        stats = _signals_recent_stats(int(now_ms), int(window_sec))
        spm = float(stats.get("spm") or 0.0)
        try:
            target_spm = float(CONFIG.get("dynamic_threshold_target_spm", CONFIG.get("elastic_target_spm", 4.0)) or 4.0)
        except Exception:
            target_spm = 4.0
        if (not math.isfinite(float(target_spm))) or float(target_spm) <= 0.0:
            target_spm = 4.0
        u = 0.0 if float(target_spm) <= 0.0 else min(1.0, float(spm) / float(target_spm))

        try:
            n_coins = int(stats.get("n_coins") or 0)
        except Exception:
            n_coins = 0
        target_cov = CONFIG.get("dynamic_threshold_target_coverage_coins")
        if target_cov is None:
            target_cov = CONFIG.get("universe_core_size", 30)
        try:
            target_cov = int(target_cov)
        except Exception:
            target_cov = 30
        target_cov = int(max(1, min(500, int(target_cov))))
        cov_ratio = float(n_coins) / float(target_cov) if target_cov > 0 else 0.0
        cov_def = float(_clip(1.0 - float(cov_ratio), 0.0, 1.0))
        s = float(_clip(float(cov_def) * float(1.0 - float(u)), 0.0, 1.0))

        try:
            drop_max = float(CONFIG.get("dynamic_threshold_drop_max", 0.06) or 0.06)
        except Exception:
            drop_max = 0.06
        drop_max = float(_clip(float(drop_max), 0.0, 0.50))
        try:
            floor = float(CONFIG.get("dynamic_threshold_floor", 0.45) or 0.45)
        except Exception:
            floor = 0.45
        floor = float(_clip(float(floor), 0.10, 0.95))

        thr_eff = float(thr_med) - float(drop_max) * float(s)
        thr_eff = max(float(floor), float(thr_eff))

        try:
            lo = float(CONFIG.get("threshold_grid_lo", 0.40) or 0.40)
        except Exception:
            lo = 0.40
        try:
            hi = float(CONFIG.get("threshold_grid_hi", 0.90) or 0.90)
        except Exception:
            hi = 0.90
        if (not math.isfinite(float(lo))) or (not math.isfinite(float(hi))) or float(hi) <= float(lo):
            lo, hi = 0.40, 0.90
        thr_eff = float(_clip(float(thr_eff), float(lo), float(hi)))

        DYNAMIC_THRESHOLDS.setdefault("by_regime", {})
        if isinstance(DYNAMIC_THRESHOLDS.get("by_regime"), dict):
            DYNAMIC_THRESHOLDS["by_regime"][str(rk)] = {
                "threshold": float(thr_eff),
                "stats": {
                    "source": "arena_auto",
                    "thr_median": float(thr_med),
                    "thr_eff": float(thr_eff),
                    "scarcity": float(s),
                    "spm": float(spm),
                    "target_spm": float(target_spm),
                    "n_coins": int(n_coins),
                    "target_coverage_coins": int(target_cov),
                    "window_sec": int(window_sec),
                    "ts": int(now_ms),
                },
                "ts": int(now_ms),
            }
            DYNAMIC_THRESHOLDS["ts"] = int(now_ms)
        return {"regime": str(rk), "thr_median": float(thr_med), "thr_eff": float(thr_eff), "scarcity": float(s), "ts": int(now_ms)}
    except Exception:
        return None


def _arena_snapshot_for_event(pair: str, side: str, tag: Any, ts: int, features: Dict[str, Any], regime: str, thr: float, feature_set_id: Optional[str] = None) -> Dict[str, Any]:
    _arena_init_if_needed()
    names = _arena_model_names()
    models_state = ARENA_STATE.get("models") if isinstance(ARENA_STATE, dict) else None
    use_dyn_thr = bool(CONFIG.get("arena_dynamic_threshold_enabled", False))
    by_regime = bool(CONFIG.get("arena_take_rate_by_regime", True))
    reg_key = _arena_regime_key(regime) if by_regime else "__all__"
    take_rate = float(_arena_take_rate_target())
    try:
        win_n = int(CONFIG.get("arena_take_rate_window", 2000) or 2000)
    except Exception:
        win_n = 2000
    win_n = max(50, int(win_n))
    try:
        min_samples = int(CONFIG.get("arena_take_rate_min_samples", 200) or 200)
    except Exception:
        min_samples = 200
    min_samples = max(10, int(min_samples))
    weights_by_name: Dict[str, float] = {}
    try:
        two_layer = bool(CONFIG.get("arena_weight_two_layer_enabled", False))
    except Exception:
        two_layer = False
    if two_layer and isinstance(models_state, dict) and names:
        try:
            temp = float(CONFIG.get("arena_weight_temperature", 1.0) or 1.0)
        except Exception:
            temp = 1.0
        temp = max(1e-6, float(temp))
        try:
            mix_gamma = float(CONFIG.get("arena_weight_mix_gamma", 0.0) or 0.0)
        except Exception:
            mix_gamma = 0.0
        mix_gamma = float(_clip(float(mix_gamma), 0.0, 1.0))

        logits: Dict[str, float] = {}
        for n in names:
            st0 = models_state.get(str(n))
            if not isinstance(st0, dict):
                continue
            try:
                logb = float(st0.get("log_w_base") or 0.0)
            except Exception:
                logb = 0.0
            if not math.isfinite(logb):
                logb = 0.0
            lgr = st0.get("log_w_regime")
            if not isinstance(lgr, dict):
                lgr = {}
            try:
                logr = float(lgr.get(str(reg_key)) or 0.0)
            except Exception:
                logr = 0.0
            if not math.isfinite(logr):
                logr = 0.0
            logits[str(n)] = float(logb) + float(logr)

        if logits:
            zmax = max(float(v) for v in logits.values())
            denom = 0.0
            exps: Dict[str, float] = {}
            for k, z in logits.items():
                try:
                    e = math.exp((float(z) - float(zmax)) / float(temp))
                except Exception:
                    e = 0.0
                if not math.isfinite(e) or e < 0.0:
                    e = 0.0
                exps[str(k)] = float(e)
                denom += float(e)
            if denom > 1e-12:
                uni = 1.0 / float(len(exps))
                for k, e in exps.items():
                    ww = float(e) / float(denom)
                    if mix_gamma > 0.0:
                        ww = (1.0 - float(mix_gamma)) * float(ww) + float(mix_gamma) * float(uni)
                    if not math.isfinite(ww) or ww < 0.0:
                        ww = 0.0
                    weights_by_name[str(k)] = float(ww)
    out_models: Dict[str, Dict[str, Any]] = {}
    for n in names:
        try:
            p, pc = _arena_predict_one(str(n), features, side, regime, feature_set_id=feature_set_id)
        except Exception:
            p, pc = 0.0, 0.0
        st = (models_state or {}).get(str(n)) if isinstance(models_state, dict) else None
        thr_i = float(thr)
        if use_dyn_thr and isinstance(st, dict):
            ph = st.get("pc_hist")
            if not isinstance(ph, dict):
                ph = {}
                st["pc_hist"] = ph
            xs = ph.get(str(reg_key))
            if not isinstance(xs, list):
                xs = []
            if len(xs) >= int(min_samples):
                thr_i = float(_clip(float(_arena_quantile(xs, 1.0 - float(take_rate))), 0.0, 1.0))
            xs.append(float(_clip(float(pc), 0.0, 1.0)))
            if len(xs) > int(win_n):
                xs = xs[-int(win_n):]
            ph[str(reg_key)] = xs
        take = bool(float(pc) >= float(thr_i))
        settled = int((st or {}).get("settled") or 0)
        takes = int((st or {}).get("takes") or 0)
        eligible = bool((st or {}).get("eligible", True))
        out_models[str(n)] = {
            "p": float(p),
            "pc": float(pc),
            "take": bool(take),
            "thr": float(thr_i),
            "weight": float(weights_by_name.get(str(n), float((st or {}).get("weight") or 0.0))),
            "capital_u": float((st or {}).get("capital_u") or 0.0),
            "settled": int(settled),
            "takes": int(takes),
            "eligible": bool(eligible),
        }
    try:
        _dynamic_threshold_auto_update_from_arena(str(regime), out_models, int(_now_ms()))
    except Exception:
        pass
    return {
        "pair": str(pair),
        "side": str(side),
        "tag": tag,
        "ts": int(ts),
        "regime": str(regime),
        "threshold": float(thr),
        "feature_set_id": (None if feature_set_id is None else str(feature_set_id)),
        "models": out_models,
        "chosen": None,
        "explore": False,
        "settled": False,
        "settle_ts": None,
    }


_ARENA_FEATURE_KEYS_CACHE: Dict[Tuple[str, str], List[str]] = {}


def _arena_effective_feature_keys(model_id: str, feature_set_id: Optional[str]) -> List[str]:
    mid = str(model_id or "")
    fsid_in = ("" if feature_set_id is None else str(feature_set_id)).strip()
    ck = (mid, fsid_in)
    cached = _ARENA_FEATURE_KEYS_CACHE.get(ck)
    if isinstance(cached, list):
        return list(cached)

    name = str(mid)
    fam = _arena_model_family(name)
    resolved_key = None
    if name in ("__xgb__", "__lstm__", "__rf__", "__nn__", "__transformer__", "__lr__"):
        if name == "__xgb__":
            resolved_key = _arena_find_model_key(["xgb"])
        elif name == "__lstm__":
            resolved_key = _arena_find_model_key(["lstm"])
        elif name == "__rf__":
            resolved_key = _arena_find_model_key(["rf"])
        elif name == "__nn__":
            resolved_key = _arena_find_model_key(["nn"])
        elif name == "__transformer__":
            resolved_key = _arena_find_model_key(["transformer"])
        elif name == "__lr__":
            resolved_key = _arena_find_model_key(["lr"])
        if resolved_key is not None and str(resolved_key) in MODELS:
            meta = _artifact_meta_for_name(str(resolved_key))
            fsid2 = _resolve_feature_set_id_for_meta(feature_set_id, meta)
            keys_pref = _eval_feature_keys(fam, fsid2) if fam else _eval_feature_keys(None, fsid2)
            obj = MODELS.get(str(resolved_key))
            keys_obj = None
            if isinstance(obj, dict):
                kk = obj.get("keys")
                if isinstance(kk, list) and kk:
                    keys_obj = [str(x) for x in kk if str(x)]
            if keys_obj is None:
                mk2 = meta.get("feature_keys")
                if isinstance(mk2, list) and mk2:
                    keys_obj = [str(x) for x in mk2 if str(x)]
            if keys_obj is None:
                keys_obj = list(keys_pref)
            if isinstance(keys_pref, list) and keys_pref:
                pref_set = set(str(x) for x in keys_pref if str(x))
                keys_obj = [k for k in keys_obj if k in pref_set] or list(keys_obj)
            _ARENA_FEATURE_KEYS_CACHE[ck] = list(keys_obj)
            return list(keys_obj)

    if name in MODELS:
        obj = MODELS.get(name)
        meta = _artifact_meta_for_name(name)
        fsid2 = _resolve_feature_set_id_for_meta(feature_set_id, meta)
        keys_pref = _eval_feature_keys(fam, fsid2) if fam else _eval_feature_keys(None, fsid2)
        keys_obj = None
        if isinstance(obj, dict):
            kk = obj.get("keys")
            if isinstance(kk, list) and kk:
                keys_obj = [str(x) for x in kk if str(x)]
        if keys_obj is None:
            mk2 = meta.get("feature_keys")
            if isinstance(mk2, list) and mk2:
                keys_obj = [str(x) for x in mk2 if str(x)]
        if keys_obj is None:
            keys_obj = list(keys_pref)
        if isinstance(keys_pref, list) and keys_pref:
            pref_set = set(str(x) for x in keys_pref if str(x))
            keys_obj = [k for k in keys_obj if k in pref_set] or list(keys_obj)
        _ARENA_FEATURE_KEYS_CACHE[ck] = list(keys_obj)
        return list(keys_obj)

    _ARENA_FEATURE_KEYS_CACHE[ck] = []
    return []


def _arena_feature_jaccard(a: str, b: str, feature_set_id: Optional[str]) -> float:
    ka = _arena_effective_feature_keys(str(a), feature_set_id)
    kb = _arena_effective_feature_keys(str(b), feature_set_id)
    sa = set(str(x) for x in (ka or []) if str(x))
    sb = set(str(x) for x in (kb or []) if str(x))
    if not sa or not sb:
        return 0.0
    inter = len(sa & sb)
    if inter <= 0:
        return 0.0
    uni = len(sa | sb)
    if uni <= 0:
        return 0.0
    j = float(inter) / float(uni)
    if not math.isfinite(j):
        return 0.0
    return float(_clip(float(j), 0.0, 1.0))


def _pearson_corr(xs: List[float], ys: List[float]) -> float:
    n = min(len(xs), len(ys))
    if n <= 1:
        return 0.0
    mx = float(sum(float(x) for x in xs[:n])) / float(n)
    my = float(sum(float(y) for y in ys[:n])) / float(n)
    sx = 0.0
    sy = 0.0
    sxy = 0.0
    for x, y in zip(xs[:n], ys[:n]):
        dx = float(x) - float(mx)
        dy = float(y) - float(my)
        sx += float(dx) * float(dx)
        sy += float(dy) * float(dy)
        sxy += float(dx) * float(dy)
    denom = math.sqrt(max(0.0, float(sx) * float(sy)))
    if denom <= 0.0:
        return 0.0
    c = float(sxy) / float(denom)
    if not math.isfinite(c):
        return 0.0
    return float(_clip(float(c), -1.0, 1.0))


def _arena_hist_metric_value(rec: Dict[str, Any], metric: str, model_id: str) -> float:
    mm = str(metric or "edge").strip().lower()
    if mm in ("logloss", "ll"):
        d = rec.get("logloss")
    else:
        d = rec.get("edges")
    if not isinstance(d, dict):
        return 0.0
    try:
        v = float(d.get(str(model_id)) or 0.0)
    except Exception:
        v = 0.0
    if not math.isfinite(float(v)):
        return 0.0
    return float(v)


def _arena_corr_from_hist(hist: List[Any], a: str, b: str, metric: str, window: int, min_overlap: int) -> Tuple[float, int]:
    if not isinstance(hist, list) or not hist:
        return 0.0, 0
    ww = max(0, int(window))
    xs: List[float] = []
    ys: List[float] = []
    for it in (list(hist)[-ww:] if ww > 0 else list(hist)):
        if not isinstance(it, dict):
            continue
        xs.append(float(_arena_hist_metric_value(it, metric, str(a))))
        ys.append(float(_arena_hist_metric_value(it, metric, str(b))))
    n = min(len(xs), len(ys))
    if n < int(max(2, int(min_overlap))):
        return 0.0, int(n)
    return float(_pearson_corr(xs[:n], ys[:n])), int(n)


def _arena_recent_counts(hist: List[Any], recent_k: int) -> Dict[str, int]:
    out: Dict[str, int] = {}
    rk = max(0, int(recent_k))
    if rk <= 0 or not isinstance(hist, list) or not hist:
        return out
    for it in list(hist)[-rk:]:
        if not isinstance(it, dict):
            continue
        c = it.get("chosen")
        if c is None:
            continue
        out[str(c)] = int(out.get(str(c), 0)) + 1
    return out


def _arena_diversity_ref_id(takers: List[str], recent_counts: Dict[str, int], hist: List[Any], best_mean_model: Optional[str]) -> Optional[str]:
    mode = str(CONFIG.get("arena_diversity_ref", "recent_top") or "recent_top").strip().lower()
    if mode in ("last", "last_chosen", "chosen"):
        if isinstance(hist, list) and hist:
            for it in list(hist)[::-1]:
                if not isinstance(it, dict):
                    continue
                c = it.get("chosen")
                if c is None:
                    continue
                cs = str(c)
                return cs if (not takers or cs in takers) else cs
        return best_mean_model

    if takers:
        best = None
        best_n = -1
        for n in takers:
            k = int(recent_counts.get(str(n), 0))
            if int(k) > int(best_n):
                best_n = int(k)
                best = str(n)
        if best is not None and int(best_n) > 0:
            return str(best)
    return best_mean_model


def _arena_choose_executor(arena_evt: Dict[str, Any]) -> Tuple[Any, bool]:
    models = arena_evt.get("models") if isinstance(arena_evt, dict) else None
    if not isinstance(models, dict) or not models:
        return None, False
    try:
        floor_u = float(CONFIG.get("arena_capital_floor_u", 10.0) or 10.0)
    except Exception:
        floor_u = 10.0
    takers: List[str] = []
    for n, v in models.items():
        if not bool((v or {}).get("eligible", True)):
            continue
        try:
            cap_u = float(v.get("capital_u") or 0.0)
        except Exception:
            cap_u = 0.0
        if cap_u < float(floor_u):
            continue
        if bool(v.get("take", False)):
            takers.append(str(n))
    if not takers:
        return None, False

    div_enabled = bool(CONFIG.get("arena_diversity_enabled", True))
    use_recent_count = bool(CONFIG.get("arena_diversity_use_recent_count", True))
    use_corr = bool(CONFIG.get("arena_diversity_use_corr", True))
    try:
        recent_k = int(CONFIG.get("arena_diversity_recent_k", 100) or 100)
    except Exception:
        recent_k = 100
    recent_k = max(0, int(recent_k))
    try:
        count_lam = float(CONFIG.get("arena_diversity_lambda", 0.25) or 0.25)
    except Exception:
        count_lam = 0.25
    count_lam = max(0.0, float(count_lam))
    corr_metric = str(CONFIG.get("arena_diversity_corr_metric", "edge") or "edge").strip().lower()
    try:
        corr_win = int(CONFIG.get("arena_diversity_corr_window", 200) or 200)
    except Exception:
        corr_win = 200
    corr_win = max(0, int(corr_win))
    try:
        corr_min_overlap = int(CONFIG.get("arena_diversity_corr_min_overlap", 30) or 30)
    except Exception:
        corr_min_overlap = 30
    corr_min_overlap = max(2, int(corr_min_overlap))
    try:
        corr_start = float(CONFIG.get("arena_diversity_corr_start", 0.70) or 0.70)
    except Exception:
        corr_start = 0.70
    corr_start = float(_clip(float(corr_start), 0.0, 1.0))
    corr_use_abs = bool(CONFIG.get("arena_diversity_corr_use_abs", False))
    try:
        corr_lam = float(CONFIG.get("arena_diversity_corr_lambda", count_lam) or count_lam)
    except Exception:
        corr_lam = float(count_lam)
    corr_lam = max(0.0, float(corr_lam))

    try:
        corr_anti_start = float(CONFIG.get("arena_diversity_corr_anti_start", 0.30) or 0.30)
    except Exception:
        corr_anti_start = 0.30
    corr_anti_start = float(_clip(float(corr_anti_start), 0.0, 1.0))
    try:
        corr_anti_lam = float(CONFIG.get("arena_diversity_corr_anti_lambda", 0.0) or 0.0)
    except Exception:
        corr_anti_lam = 0.0
    corr_anti_lam = max(0.0, float(corr_anti_lam))
    try:
        corr_anti_cap = float(CONFIG.get("arena_diversity_corr_anti_cap", 2.0) or 2.0)
    except Exception:
        corr_anti_cap = 2.0
    corr_anti_cap = max(1.0, float(corr_anti_cap))

    use_feat = bool(CONFIG.get("arena_diversity_use_feature", True))
    try:
        feat_start = float(CONFIG.get("arena_diversity_feature_start", 0.80) or 0.80)
    except Exception:
        feat_start = 0.80
    feat_start = float(_clip(float(feat_start), 0.0, 1.0))
    try:
        feat_lam = float(CONFIG.get("arena_diversity_feature_lambda", 0.0) or 0.0)
    except Exception:
        feat_lam = 0.0
    feat_lam = max(0.0, float(feat_lam))

    evt_fsid = None
    try:
        evt_fsid = arena_evt.get("feature_set_id") if isinstance(arena_evt, dict) else None
    except Exception:
        evt_fsid = None

    method = str(CONFIG.get("arena_select_method", "weight") or "weight").strip().lower()
    if method in ("bandit_thompson", "bandit", "thompson", "bandit_ucb", "ucb"):
        ms = ARENA_STATE.get("models") if isinstance(ARENA_STATE, dict) else None
        if not isinstance(ms, dict):
            method = "weight"
        else:
            reg = _arena_regime_key((arena_evt or {}).get("regime"))
            by_regime = bool(CONFIG.get("arena_bandit_by_regime", True))
            key = str(reg) if by_regime else "__all__"
            try:
                prior_a = float(CONFIG.get("arena_bandit_prior_a", 1.0) or 1.0)
            except Exception:
                prior_a = 1.0
            try:
                prior_b = float(CONFIG.get("arena_bandit_prior_b", 1.0) or 1.0)
            except Exception:
                prior_b = 1.0
            prior_a = max(1e-6, float(prior_a))
            prior_b = max(1e-6, float(prior_b))

            hist = ARENA_STATE.get("history") if isinstance(ARENA_STATE, dict) else None
            if not isinstance(hist, list):
                hist = []
            recent_counts = _arena_recent_counts(hist, int(recent_k))

            base_scores: Dict[str, float] = {}
            means: Dict[str, float] = {}

            ucb_total = 0.0
            if method in ("bandit_ucb", "ucb"):
                for n in takers:
                    st = ms.get(str(n))
                    if not isinstance(st, dict):
                        continue
                    bd = st.get("bandit")
                    if not isinstance(bd, dict):
                        continue
                    bucket = bd.get(str(key))
                    if not isinstance(bucket, dict):
                        continue
                    try:
                        a = float(bucket.get("a") or prior_a)
                        b = float(bucket.get("b") or prior_b)
                    except Exception:
                        a, b = prior_a, prior_b
                    ucb_total += float(max(0.0, a) + max(0.0, b))
                ucb_total = max(1.0, float(ucb_total))

            try:
                ucb_c = float(CONFIG.get("arena_bandit_ucb_c", 1.0) or 1.0)
            except Exception:
                ucb_c = 1.0
            ucb_c = max(0.0, float(ucb_c))

            for n in takers:
                st = ms.get(str(n))
                bd = (st.get("bandit") if isinstance(st, dict) else None)
                if not isinstance(bd, dict):
                    bd = {}
                    if isinstance(st, dict):
                        st["bandit"] = bd
                bucket = bd.get(str(key))
                if not isinstance(bucket, dict):
                    bucket = {"a": float(prior_a), "b": float(prior_b)}
                    bd[str(key)] = bucket
                try:
                    a = float(bucket.get("a") or prior_a)
                    b = float(bucket.get("b") or prior_b)
                except Exception:
                    a, b = prior_a, prior_b
                a = max(1e-6, float(a))
                b = max(1e-6, float(b))

                mean = float(a) / float(a + b)
                means[str(n)] = float(mean)

                if method in ("bandit_ucb", "ucb"):
                    nobs = float(a + b)
                    bonus = float(ucb_c) * math.sqrt(max(0.0, math.log(float(ucb_total) + 1.0)) / float(max(1.0, nobs)))
                    base_scores[str(n)] = float(mean + bonus)
                else:
                    base_scores[str(n)] = float(random.betavariate(float(a), float(b)))

            best_mean_model = None
            best_mean = None
            for n, mean in means.items():
                if best_mean is None or float(mean) > float(best_mean):
                    best_mean = float(mean)
                    best_mean_model = str(n)

            ref = None
            if div_enabled and ((use_corr and corr_lam > 0.0) or (use_feat and feat_lam > 0.0)):
                ref = _arena_diversity_ref_id(takers, recent_counts, hist, best_mean_model)

            corr_debug: Dict[str, float] = {}
            corr_anti_debug: Dict[str, float] = {}
            feat_debug: Dict[str, float] = {}
            best = None
            best_score = -1e18
            for n in takers:
                s = float(base_scores.get(str(n), 0.0))
                if div_enabled and use_recent_count and recent_k > 0 and count_lam > 0.0:
                    frac = float(recent_counts.get(str(n), 0)) / float(max(1, int(recent_k)))
                    s *= float(math.exp(-float(count_lam) * float(frac)))

                if div_enabled and use_corr and ref is not None and str(ref) != str(n) and corr_lam > 0.0:
                    c, nn = _arena_corr_from_hist(hist, str(n), str(ref), str(corr_metric), int(corr_win), int(corr_min_overlap))
                    if nn >= int(corr_min_overlap):
                        corr_debug[str(n)] = float(c)
                        c0 = abs(float(c)) if bool(corr_use_abs) else float(c)
                        excess = max(0.0, float(c0) - float(corr_start))
                        if excess > 0.0:
                            s *= float(math.exp(-float(corr_lam) * float(excess)))

                if div_enabled and use_corr and (not bool(corr_use_abs)) and ref is not None and str(ref) != str(n) and corr_anti_lam > 0.0:
                    c, nn = _arena_corr_from_hist(hist, str(n), str(ref), str(corr_metric), int(corr_win), int(corr_min_overlap))
                    if nn >= int(corr_min_overlap):
                        strength = max(0.0, (-float(c)) - float(corr_anti_start))
                        if strength > 0.0:
                            m = float(math.exp(float(corr_anti_lam) * float(strength)))
                            if float(corr_anti_cap) > 1.0:
                                m = float(min(float(m), float(corr_anti_cap)))
                            corr_anti_debug[str(n)] = float(m)
                            s *= float(m)

                if div_enabled and use_feat and ref is not None and str(ref) != str(n) and feat_lam > 0.0:
                    j = float(_arena_feature_jaccard(str(n), str(ref), evt_fsid))
                    feat_debug[str(n)] = float(j)
                    excess = max(0.0, float(j) - float(feat_start))
                    if excess > 0.0:
                        s *= float(math.exp(-float(feat_lam) * float(excess)))

                if float(s) > float(best_score):
                    best_score = float(s)
                    best = str(n)

            if isinstance(ARENA_STATE, dict):
                ARENA_STATE["diversity"] = {
                    "ts": int(_now_ms()),
                    "method": str(method),
                    "ref": (None if ref is None else str(ref)),
                    "metric": str(corr_metric),
                    "corr_window": int(corr_win),
                    "corr_min_overlap": int(corr_min_overlap),
                    "corr_start": float(corr_start),
                    "corr_use_abs": bool(corr_use_abs),
                    "corr_lambda": float(corr_lam),
                    "corr_anti_start": float(corr_anti_start),
                    "corr_anti_lambda": float(corr_anti_lam),
                    "corr_anti_cap": float(corr_anti_cap),
                    "feature_set_id": (None if evt_fsid is None else str(evt_fsid)),
                    "feature_start": float(feat_start),
                    "feature_lambda": float(feat_lam),
                    "recent_k": int(recent_k),
                    "count_lambda": float(count_lam),
                    "corr": dict(corr_debug),
                    "corr_anti": dict(corr_anti_debug),
                    "feat": dict(feat_debug),
                }

            if best is None:
                best = takers[0]
            explore = bool(best_mean_model is not None and str(best) != str(best_mean_model))
            return best, explore

    use_cap = bool(CONFIG.get("arena_use_capital_in_selection", False))
    best = None
    best_score = -1e18
    hist = ARENA_STATE.get("history") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(hist, list):
        hist = []
    recent_counts = _arena_recent_counts(hist, int(recent_k))
    ref = None
    if div_enabled and ((use_corr and corr_lam > 0.0) or (use_feat and feat_lam > 0.0)):
        ref = _arena_diversity_ref_id(takers, recent_counts, hist, None)
    corr_debug: Dict[str, float] = {}
    corr_anti_debug: Dict[str, float] = {}
    feat_debug: Dict[str, float] = {}
    scores: Dict[str, float] = {}
    for n in takers:
        v = models.get(str(n)) or {}
        try:
            w = float(v.get("weight") or 0.0)
        except Exception:
            w = 0.0
        try:
            cap_u = float(v.get("capital_u") or 0.0)
        except Exception:
            cap_u = 0.0
        s = float(w)
        if use_cap:
            s *= max(0.0, float(cap_u))
        if div_enabled and use_recent_count and recent_k > 0 and count_lam > 0.0:
            frac = float(recent_counts.get(str(n), 0)) / float(max(1, int(recent_k)))
            s *= float(math.exp(-float(count_lam) * float(frac)))
        if div_enabled and use_corr and ref is not None and str(ref) != str(n) and corr_lam > 0.0:
            c, nn = _arena_corr_from_hist(hist, str(n), str(ref), str(corr_metric), int(corr_win), int(corr_min_overlap))
            if nn >= int(corr_min_overlap):
                corr_debug[str(n)] = float(c)
                c0 = abs(float(c)) if bool(corr_use_abs) else float(c)
                excess = max(0.0, float(c0) - float(corr_start))
                if excess > 0.0:
                    s *= float(math.exp(-float(corr_lam) * float(excess)))

        if div_enabled and use_corr and (not bool(corr_use_abs)) and ref is not None and str(ref) != str(n) and corr_anti_lam > 0.0:
            c, nn = _arena_corr_from_hist(hist, str(n), str(ref), str(corr_metric), int(corr_win), int(corr_min_overlap))
            if nn >= int(corr_min_overlap):
                strength = max(0.0, (-float(c)) - float(corr_anti_start))
                if strength > 0.0:
                    m = float(math.exp(float(corr_anti_lam) * float(strength)))
                    if float(corr_anti_cap) > 1.0:
                        m = float(min(float(m), float(corr_anti_cap)))
                    corr_anti_debug[str(n)] = float(m)
                    s *= float(m)

        if div_enabled and use_feat and ref is not None and str(ref) != str(n) and feat_lam > 0.0:
            j = float(_arena_feature_jaccard(str(n), str(ref), evt_fsid))
            feat_debug[str(n)] = float(j)
            excess = max(0.0, float(j) - float(feat_start))
            if excess > 0.0:
                s *= float(math.exp(-float(feat_lam) * float(excess)))
        scores[str(n)] = float(s)
        if float(s) > float(best_score):
            best_score = float(s)
            best = str(n)
    if best is None:
        best = takers[0]

    if isinstance(ARENA_STATE, dict):
        ARENA_STATE["diversity"] = {
            "ts": int(_now_ms()),
            "method": str(method),
            "ref": (None if ref is None else str(ref)),
            "metric": str(corr_metric),
            "corr_window": int(corr_win),
            "corr_min_overlap": int(corr_min_overlap),
            "corr_start": float(corr_start),
            "corr_use_abs": bool(corr_use_abs),
            "corr_lambda": float(corr_lam),
            "corr_anti_start": float(corr_anti_start),
            "corr_anti_lambda": float(corr_anti_lam),
            "corr_anti_cap": float(corr_anti_cap),
            "feature_set_id": (None if evt_fsid is None else str(evt_fsid)),
            "feature_start": float(feat_start),
            "feature_lambda": float(feat_lam),
            "recent_k": int(recent_k),
            "count_lambda": float(count_lam),
            "corr": dict(corr_debug),
            "corr_anti": dict(corr_anti_debug),
            "feat": dict(feat_debug),
        }

    try:
        eps = float(CONFIG.get("arena_explore_epsilon", 0.0) or 0.0)
    except Exception:
        eps = 0.0
    if float(eps) > 0.0 and random.random() < float(eps):
        pool = [x for x in takers if str(x) != str(best)] if len(takers) > 1 else takers[:]
        wts = [max(0.0, float(scores.get(str(x), 0.0))) for x in pool]
        if sum(wts) <= 1e-12:
            return random.choice(pool), True
        r = random.random() * float(sum(wts))
        acc = 0.0
        for x, w in zip(pool, wts):
            acc += float(w)
            if acc >= r:
                return str(x), True
        return str(pool[-1]), True

    return best, False


def _arena_edge(ret: float, atr_pct: float) -> float:
    try:
        atr_floor = float(CONFIG.get("arena_atr_pct_floor", 0.002) or 0.002)
    except Exception:
        atr_floor = 0.002
    denom = max(float(atr_pct) if math.isfinite(float(atr_pct)) else 0.0, float(atr_floor))
    if denom <= 0.0:
        return 0.0
    raw = float(ret) / float(denom)
    try:
        c = float(CONFIG.get("arena_edge_clip", 3.0) or 3.0)
    except Exception:
        c = 3.0
    return float(_clip(float(raw), -float(c), float(c)))


def _arena_risk_unit_ratio(atr_pct: float, notional_usdc: float) -> float:
    try:
        atr_floor = float(CONFIG.get("arena_atr_pct_floor", 0.002) or 0.002)
    except Exception:
        atr_floor = 0.002
    try:
        min_risk_usdc = float(CONFIG.get("arena_min_risk_usdc", 5.0) or 5.0)
    except Exception:
        min_risk_usdc = 5.0
    n = float(notional_usdc) if math.isfinite(float(notional_usdc)) else 0.0
    n = max(1e-6, float(n))
    rmin = float(min_risk_usdc) / float(n)
    a = float(atr_pct) if math.isfinite(float(atr_pct)) else 0.0
    return float(max(float(a), float(atr_floor), float(rmin)))


def _arena_edge_trade(ret_ratio: float, atr_pct: float, notional_usdc: float) -> float:
    denom = _arena_risk_unit_ratio(float(atr_pct), float(notional_usdc))
    if denom <= 0.0:
        return 0.0
    raw = float(ret_ratio) / float(denom)
    try:
        c = float(CONFIG.get("arena_edge_clip", 3.0) or 3.0)
    except Exception:
        c = 3.0
    return float(_clip(float(raw), -float(c), float(c)))


def _arena_edge_trade_pnl(pnl_u: float, atr_pct: float, notional_usdc: float) -> float:
    ru = float(_arena_risk_unit_ratio(float(atr_pct), float(notional_usdc)))
    risk_usdc = abs(float(notional_usdc)) * float(ru)
    if risk_usdc <= 0.0:
        return 0.0
    raw = float(pnl_u) / float(risk_usdc)
    try:
        c = float(CONFIG.get("arena_edge_clip", 3.0) or 3.0)
    except Exception:
        c = 3.0
    return float(_clip(float(raw), -float(c), float(c)))


def _arena_logloss(p: float, y: int, eps: float) -> float:
    pp = float(_clip(float(p), float(eps), 1.0 - float(eps)))
    yy = 1 if int(y) == 1 else 0
    return float(-(float(yy) * math.log(pp) + float(1 - yy) * math.log(1.0 - pp)))


def _arena_settle_one(arena_evt: Dict[str, Any], ret_ratio: float, atr_pct: float, notional_usdc: float, now_ms: int, meta: Dict[str, Any]) -> Dict[str, Any]:
    if not _arena_enabled():
        return {"ok": True, "enabled": False}
    _arena_init_if_needed(now_ms=now_ms)
    if not bool(ARENA_STATE.get("inited")):
        return {"ok": False, "error": "arena_not_inited"}
    models_state = ARENA_STATE.get("models")
    if not isinstance(models_state, dict):
        return {"ok": False, "error": "arena_bad_state"}

    try:
        reward_u = float(CONFIG.get("arena_reward_u", 1.0) or 1.0)
    except Exception:
        reward_u = 1.0
    try:
        penalty_u = float(CONFIG.get("arena_penalty_u", 1.0) or 1.0)
    except Exception:
        penalty_u = 1.0
    eta = float(CONFIG.get("arena_hedge_eta", 0.5) or 0.5)
    alpha = float(CONFIG.get("arena_hedge_alpha", 1.0) or 1.0)
    beta = float(CONFIG.get("arena_hedge_beta", 0.10) or 0.10)
    loss_eps = float(CONFIG.get("arena_loss_eps", 1e-6) or 1e-6)
    penalize_no_take = bool(CONFIG.get("arena_penalize_no_take", False))
    try:
        floor_u = float(CONFIG.get("arena_capital_floor_u", 10.0) or 10.0)
    except Exception:
        floor_u = 10.0
    try:
        revive_threshold_u = float(CONFIG.get("arena_revive_threshold_u", 20.0) or 20.0)
    except Exception:
        revive_threshold_u = 20.0
    try:
        revive_grant = float(CONFIG.get("arena_revive_grant_u", 5.0) or 5.0)
    except Exception:
        revive_grant = 5.0
    try:
        revive_min_trades = int(CONFIG.get("arena_revive_min_shadow_trades", 50) or 50)
    except Exception:
        revive_min_trades = 50
    try:
        stats_win = int(CONFIG.get("arena_stats_window", 200) or 200)
    except Exception:
        stats_win = 200

    m_evt = arena_evt.get("models") if isinstance(arena_evt, dict) else None
    if not isinstance(m_evt, dict) or not m_evt:
        return {"ok": False, "error": "arena_missing_models"}

    try:
        fee_rate = float(CONFIG.get("arena_fee_rate", 0.0) or 0.0)
    except Exception:
        fee_rate = 0.0
    try:
        funding_rate_per_day = float(CONFIG.get("arena_funding_rate_per_day", 0.0) or 0.0)
    except Exception:
        funding_rate_per_day = 0.0
    try:
        win_min = float(CONFIG.get("arena_edge_win_min", 0.0) or 0.0)
    except Exception:
        win_min = 0.0
    win_min = max(0.0, float(win_min))

    hold_ms = 0
    try:
        hold_ms = int((meta or {}).get("hold_ms") or 0)
    except Exception:
        hold_ms = 0
    hold_days = float(max(0, int(hold_ms))) / 86400000.0 if int(hold_ms) > 0 else 0.0

    pnl_gross_u = float(ret_ratio) * float(notional_usdc)
    fees_u = abs(float(notional_usdc)) * float(max(0.0, fee_rate)) * 2.0
    funding_u = abs(float(notional_usdc)) * float(funding_rate_per_day) * float(hold_days) if float(funding_rate_per_day) != 0.0 else 0.0
    pnl_net_u = float(pnl_gross_u) - float(fees_u) - float(funding_u)

    y = 1 if float(pnl_net_u) > 0.0 else 0
    try:
        dz = float(CONFIG.get("arena_edge_dead_zone", 0.0) or 0.0)
    except Exception:
        dz = 0.0
    dz = max(0.0, float(dz))
    ru = float(_arena_risk_unit_ratio(float(atr_pct), float(notional_usdc)))
    risk_usdc = abs(float(notional_usdc)) * float(ru)
    edge_trade_global = float(_arena_edge_trade_pnl(float(pnl_net_u), float(atr_pct), float(notional_usdc)))
    informative = bool(abs(float(edge_trade_global)) >= float(dz) and float(pnl_net_u) != 0.0)

    ll_w = 1.0
    if not informative:
        ll_w = 0.0
    else:
        mode_ll = str(CONFIG.get("arena_logloss_importance_mode", "none") or "none").strip().lower()
        try:
            w_min = float(CONFIG.get("arena_logloss_w_min", 0.5) or 0.5)
        except Exception:
            w_min = 0.5
        try:
            w_max = float(CONFIG.get("arena_logloss_w_max", 2.0) or 2.0)
        except Exception:
            w_max = 2.0
        if float(w_min) > float(w_max):
            w_min, w_max = float(w_max), float(w_min)
        if mode_ll in ("risk_usdc", "risk"):
            try:
                target_risk = float(CONFIG.get("arena_logloss_target_risk_usdc", 10.0) or 10.0)
            except Exception:
                target_risk = 10.0
            target_risk = max(1e-6, float(target_risk))
            ll_w = float(_clip(float(risk_usdc) / float(target_risk), float(w_min), float(w_max)))
        else:
            ll_w = 1.0
    edges: Dict[str, float] = {}
    losses: Dict[str, float] = {}
    takers: List[str] = []
    for n, v in m_evt.items():
        if not isinstance(v, dict):
            continue
        take = bool(v.get("take", False))
        if take:
            takers.append(str(n))
            edges[str(n)] = float(edge_trade_global)
        else:
            if penalize_no_take and float(ret_ratio) > 0.0:
                edges[str(n)] = -1.0
            else:
                edges[str(n)] = 0.0
        try:
            p_i = v.get("pc")
            if p_i is None:
                p_i = v.get("p")
            losses[str(n)] = float(ll_w) * float(_arena_logloss(float(p_i or 0.0), int(y), float(loss_eps)))
        except Exception:
            losses[str(n)] = float(ll_w) * float(_arena_logloss(0.5, int(y), float(loss_eps)))

    winner = None
    best_r = -1e18
    for n in list(m_evt.keys()):
        try:
            edge_v = float(edges.get(str(n), 0.0))
        except Exception:
            edge_v = 0.0
        try:
            ll = float(losses.get(str(n), 0.0))
        except Exception:
            ll = 0.0
        r = float(alpha) * float(edge_v) - float(beta) * float(ll)
        if float(r) > float(best_r):
            best_r = float(r)
            winner = str(n)

    pnl_u = float(pnl_net_u)
    accounting_mode = str(CONFIG.get("arena_accounting_mode", "legacy") or "legacy").strip().lower()
    chosen_id = arena_evt.get("chosen")
    chosen_s = (str(chosen_id) if chosen_id is not None else None)
    conservative = accounting_mode not in ("legacy", "naive", "all")
    shares: Dict[str, float] = {}
    if accounting_mode in ("legacy", "naive", "all"):
        for n in takers:
            shares[str(n)] = 1.0
    elif accounting_mode in ("executor", "chosen", "executor_only"):
        if chosen_s is not None and chosen_s in takers:
            shares[str(chosen_s)] = 1.0
    else:
        if takers:
            w0 = 1.0 / float(len(takers))
            for n in takers:
                shares[str(n)] = float(w0)

    pnl_alloc: Dict[str, float] = {}
    fees_alloc: Dict[str, float] = {}
    funding_alloc: Dict[str, float] = {}
    for n, sh in shares.items():
        st = models_state.get(str(n))
        if not isinstance(st, dict):
            continue
        sh0 = float(sh) if math.isfinite(float(sh)) else 0.0
        sh0 = max(0.0, float(sh0))
        if sh0 <= 0.0:
            continue
        pnl_i = float(pnl_u) * float(sh0)
        fees_i = float(fees_u) * float(sh0)
        funding_i = float(funding_u) * float(sh0)
        pnl_alloc[str(n)] = float(pnl_i)
        fees_alloc[str(n)] = float(fees_i)
        funding_alloc[str(n)] = float(funding_i)
        st["capital_u"] = float(st.get("capital_u") or 0.0) + float(pnl_i)
        st["pnl_sum_u"] = float(st.get("pnl_sum_u") or 0.0) + float(pnl_i)
        st["fees_sum_u"] = float(st.get("fees_sum_u") or 0.0) + float(fees_i)
        st["funding_sum_u"] = float(st.get("funding_sum_u") or 0.0) + float(funding_i)
        if conservative:
            if float(st.get("capital_u") or 0.0) < 0.0:
                st["capital_u"] = 0.0
        else:
            if float(st.get("capital_u") or 0.0) < float(floor_u):
                st["capital_u"] = float(floor_u)

    pnl_sign = 0
    if float(pnl_u) > 0.0:
        pnl_sign = 1
    elif float(pnl_u) < 0.0:
        pnl_sign = -1

    try:
        thr_evt = float(arena_evt.get("threshold") or 0.0)
    except Exception:
        thr_evt = 0.0
    pool_score_mode = str(CONFIG.get("arena_pool_score_mode", "edge") or "edge").strip().lower()
    reward_score: Dict[str, float] = {}
    penalty_score: Dict[str, float] = {}
    if pnl_sign != 0 and takers:
        if pool_score_mode in ("pc_margin", "margin", "pc"):
            for n in takers:
                v = m_evt.get(str(n)) if isinstance(m_evt, dict) else None
                if not isinstance(v, dict):
                    continue
                try:
                    pc_i = float(v.get("pc") or v.get("p") or 0.0)
                except Exception:
                    pc_i = 0.0
                try:
                    thr_i = float(v.get("thr") or thr_evt)
                except Exception:
                    thr_i = float(thr_evt)
                s = float(max(0.0, float(pc_i) - float(thr_i)))
                if pnl_sign > 0:
                    reward_score[str(n)] = float(s)
                else:
                    penalty_score[str(n)] = float(s)
        elif pool_score_mode in ("ll_peer", "logloss_peer", "ll_takers"):
            lls = [float(losses.get(str(n), 0.0)) for n in takers]
            ll_mean = float(sum(lls)) / float(len(lls)) if lls else 0.0
            for n in takers:
                ll = float(losses.get(str(n), 0.0))
                if pnl_sign > 0:
                    reward_score[str(n)] = float(max(0.0, float(ll_mean) - float(ll)))
                else:
                    penalty_score[str(n)] = float(max(0.0, float(ll) - float(ll_mean)))
        elif pool_score_mode in ("ll_baseline", "ll_vs_0.5", "logloss_baseline"):
            ll0 = float(_arena_logloss(0.5, int(y), float(loss_eps)))
            for n in takers:
                ll = float(losses.get(str(n), 0.0))
                if pnl_sign > 0:
                    reward_score[str(n)] = float(max(0.0, float(ll0) - float(ll)))
                else:
                    penalty_score[str(n)] = float(max(0.0, float(ll) - float(ll0)))
        else:
            for n in takers:
                try:
                    edge_v = float(edges.get(str(n), 0.0))
                except Exception:
                    edge_v = 0.0
                reward_score[str(n)] = float(max(0.0, float(edge_v) - float(win_min)))
                penalty_score[str(n)] = float(max(0.0, -float(edge_v) - float(win_min)))

    pool_u = float(ARENA_STATE.get("pool_u") or 0.0)
    for n in takers:
        ps = float(penalty_score.get(str(n), 0.0))
        if ps <= 0.0:
            continue
        st = models_state.get(str(n))
        if not isinstance(st, dict):
            continue
        amt = float(penalty_u) * float(ps)
        cap0 = float(st.get("capital_u") or 0.0)
        pay = float(min(float(amt), float(max(0.0, cap0)))) if conservative else float(amt)
        st["capital_u"] = float(cap0) - float(pay)
        if conservative:
            if float(st.get("capital_u") or 0.0) < 0.0:
                st["capital_u"] = 0.0
        else:
            st["capital_u"] = max(float(floor_u), float(st.get("capital_u") or 0.0))
        st["losses"] = int(st.get("losses") or 0) + 1
        pool_u += float(pay)

    sum_rs = float(sum(float(v) for v in reward_score.values()))
    if sum_rs > 0.0 and float(pool_u) > 0.0:
        desired = float(reward_u) * float(sum_rs)
        pay_total = float(min(float(pool_u), float(desired)))
        scale = float(pay_total) / float(desired) if float(desired) > 0.0 else 0.0
        for n in takers:
            rs = float(reward_score.get(str(n), 0.0))
            if rs <= 0.0:
                continue
            st = models_state.get(str(n))
            if not isinstance(st, dict):
                continue
            amt = float(reward_u) * float(rs) * float(scale)
            st["capital_u"] = float(st.get("capital_u") or 0.0) + float(amt)
            st["wins"] = int(st.get("wins") or 0) + 1
            pool_u -= float(amt)

    pool_u = max(0.0, float(pool_u))
    ARENA_STATE["pool_u"] = float(pool_u)

    try:
        sel_method = str(CONFIG.get("arena_select_method", "weight") or "weight").strip().lower()
    except Exception:
        sel_method = "weight"
    if sel_method in ("bandit_thompson", "bandit", "thompson", "bandit_ucb", "ucb") and chosen_s is not None and bool(informative):
        stc = models_state.get(str(chosen_s))
        if isinstance(stc, dict):
            try:
                prior_a = float(CONFIG.get("arena_bandit_prior_a", 1.0) or 1.0)
            except Exception:
                prior_a = 1.0
            try:
                prior_b = float(CONFIG.get("arena_bandit_prior_b", 1.0) or 1.0)
            except Exception:
                prior_b = 1.0
            prior_a = max(1e-6, float(prior_a))
            prior_b = max(1e-6, float(prior_b))
            try:
                decay = float(CONFIG.get("arena_bandit_decay", 0.0) or 0.0)
            except Exception:
                decay = 0.0
            decay = float(_clip(float(decay), 0.0, 1.0))
            by_regime = bool(CONFIG.get("arena_bandit_by_regime", True))
            reg = _arena_regime_key((arena_evt or {}).get("regime"))
            key = str(reg) if by_regime else "__all__"
            bd = stc.get("bandit")
            if not isinstance(bd, dict):
                bd = {}
                stc["bandit"] = bd
            bucket = bd.get(str(key))
            if not isinstance(bucket, dict):
                bucket = {"a": float(prior_a), "b": float(prior_b)}
                bd[str(key)] = bucket
            try:
                a0 = float(bucket.get("a") or prior_a)
                b0 = float(bucket.get("b") or prior_b)
            except Exception:
                a0, b0 = prior_a, prior_b
            a0 = max(1e-6, float(a0))
            b0 = max(1e-6, float(b0))
            if decay > 0.0:
                a0 = float(prior_a) + (float(a0) - float(prior_a)) * (1.0 - float(decay))
                b0 = float(prior_b) + (float(b0) - float(prior_b)) * (1.0 - float(decay))
                a0 = max(1e-6, float(a0))
                b0 = max(1e-6, float(b0))
            if int(y) == 1:
                a0 += 1.0
            else:
                b0 += 1.0
            bucket["a"] = float(a0)
            bucket["b"] = float(b0)
            bucket["n"] = int(bucket.get("n") or 0) + 1
            bucket["last_y"] = int(y)
            bucket["last_ms"] = int(now_ms)

    for n, v in m_evt.items():
        st = models_state.get(str(n))
        if not isinstance(st, dict):
            continue
        ll = float(losses.get(str(n), 0.0))
        st["ll_sum"] = float(st.get("ll_sum") or 0.0) + float(ll)
        st["ll_n"] = int(st.get("ll_n") or 0) + 1
        if bool(v.get("take", False)):
            st["takes"] = int(st.get("takes") or 0) + 1
        else:
            st["skips"] = int(st.get("skips") or 0) + 1
        st["settled"] = int(st.get("settled") or 0) + 1
        st["last_settle_ms"] = int(now_ms)
        if not bool(st.get("eligible", True)):
            try:
                need_settled = int(st.get("eligible_after_settled") or CONFIG.get("arena_eligible_min_settled", 0) or 0)
            except Exception:
                need_settled = 0
            try:
                need_takes = int(st.get("eligible_min_takes") or CONFIG.get("arena_eligible_min_takes", 0) or 0)
            except Exception:
                need_takes = 0
            if int(st.get("settled") or 0) >= int(need_settled) and int(st.get("takes") or 0) >= int(need_takes):
                st["eligible"] = True

    try:
        two_layer = bool(CONFIG.get("arena_weight_two_layer_enabled", False))
    except Exception:
        two_layer = False
    try:
        eta_base = float(CONFIG.get("arena_weight_eta_base", 0.05) or 0.05)
    except Exception:
        eta_base = 0.05
    try:
        eta_regime = float(CONFIG.get("arena_weight_eta_regime", float(eta)) or float(eta))
    except Exception:
        eta_regime = float(eta)
    try:
        decay_base = float(CONFIG.get("arena_weight_decay_base", 0.0) or 0.0)
    except Exception:
        decay_base = 0.0
    try:
        decay_regime = float(CONFIG.get("arena_weight_decay_regime", 0.0) or 0.0)
    except Exception:
        decay_regime = 0.0
    decay_base = float(_clip(float(decay_base), 0.0, 1.0))
    decay_regime = float(_clip(float(decay_regime), 0.0, 1.0))
    try:
        mix_gamma = float(CONFIG.get("arena_weight_mix_gamma", 0.0) or 0.0)
    except Exception:
        mix_gamma = 0.0
    mix_gamma = float(_clip(float(mix_gamma), 0.0, 1.0))
    try:
        temp = float(CONFIG.get("arena_weight_temperature", 1.0) or 1.0)
    except Exception:
        temp = 1.0
    temp = max(1e-6, float(temp))
    reg_key = str(_arena_regime_key((arena_evt or {}).get("regime")))

    logits: Dict[str, float] = {}
    for n, st in models_state.items():
        if not isinstance(st, dict):
            continue
        edge_v = float(edges.get(str(n), 0.0))
        ll = float(losses.get(str(n), 0.0))
        r = float(alpha) * float(edge_v) - float(beta) * float(ll)

        if two_layer:
            try:
                logb = float(st.get("log_w_base") or 0.0)
            except Exception:
                logb = 0.0
            if not math.isfinite(logb):
                logb = 0.0
            logb = float(logb) * (1.0 - float(decay_base)) + float(eta_base) * float(r)
            st["log_w_base"] = float(logb)

            lgr = st.get("log_w_regime")
            if not isinstance(lgr, dict):
                lgr = {}
                st["log_w_regime"] = lgr
            try:
                logr = float(lgr.get(str(reg_key)) or 0.0)
            except Exception:
                logr = 0.0
            if not math.isfinite(logr):
                logr = 0.0
            logr = float(logr) * (1.0 - float(decay_regime)) + float(eta_regime) * float(r)
            lgr[str(reg_key)] = float(logr)
            logits[str(n)] = float(logb) + float(logr)
        else:
            try:
                w0 = float(st.get("weight") or 0.0)
            except Exception:
                w0 = 0.0
            w0 = max(1e-12, float(w0))
            logit = math.log(float(w0))
            if not math.isfinite(logit):
                logit = 0.0
            logit = float(logit) * (1.0 - float(decay_base)) + float(eta) * float(r)
            logits[str(n)] = float(logit)

    if not logits:
        n_all = len(models_state)
        w0 = 1.0 / float(n_all) if n_all > 0 else 0.0
        for _, st in models_state.items():
            if isinstance(st, dict):
                st["weight"] = float(w0)
    else:
        zmax = max(float(v) for v in logits.values())
        denom = 0.0
        exps: Dict[str, float] = {}
        for k, z in logits.items():
            try:
                e = math.exp((float(z) - float(zmax)) / float(temp))
            except Exception:
                e = 0.0
            if not math.isfinite(e) or e < 0.0:
                e = 0.0
            exps[str(k)] = float(e)
            denom += float(e)
        n_all = len(exps)
        if denom <= float(loss_eps) or n_all <= 0:
            w0 = 1.0 / float(len(models_state)) if len(models_state) > 0 else 0.0
            for _, st in models_state.items():
                if isinstance(st, dict):
                    st["weight"] = float(w0)
        else:
            uni = 1.0 / float(n_all)
            for mid, st in models_state.items():
                if not isinstance(st, dict):
                    continue
                ww = float(exps.get(str(mid), 0.0)) / float(denom)
                if mix_gamma > 0.0:
                    ww = (1.0 - float(mix_gamma)) * float(ww) + float(mix_gamma) * float(uni)
                if not math.isfinite(ww) or ww < 0.0:
                    ww = 0.0
                st["weight"] = float(ww)

    hist = ARENA_STATE.get("history")
    if not isinstance(hist, list):
        hist = []
        ARENA_STATE["history"] = hist

    trailing_edges: Dict[str, List[float]] = {}
    if stats_win > 0:
        for it in list(hist)[-int(stats_win):]:
            if not isinstance(it, dict):
                continue
            ed0 = it.get("edges")
            if not isinstance(ed0, dict):
                continue
            for k, vv in ed0.items():
                trailing_edges.setdefault(str(k), []).append(float(vv))

    try:
        revive_min_z = float(CONFIG.get("arena_revive_min_z", 0.0) or 0.0)
    except Exception:
        revive_min_z = 0.0
    revive_min_z = max(0.0, float(revive_min_z))
    try:
        revive_pool_frac = float(CONFIG.get("arena_revive_grant_pool_frac", 0.0) or 0.0)
    except Exception:
        revive_pool_frac = 0.0
    revive_pool_frac = float(_clip(float(revive_pool_frac), 0.0, 1.0))

    if float(revive_grant) > 0.0 and float(pool_u) > 0.0:
        for mid, st in models_state.items():
            if not isinstance(st, dict):
                continue
            if int(st.get("settled") or 0) < int(revive_min_trades):
                continue
            if float(st.get("capital_u") or 0.0) >= float(revive_threshold_u):
                continue
            te = trailing_edges.get(str(st.get("name") or "")) or trailing_edges.get(str(mid)) or []
            if not te:
                continue
            nte = len(te)
            if nte < 2:
                continue
            mu = float(sum(float(x) for x in te)) / float(nte)
            if mu <= 0.0:
                continue
            var = float(sum((float(x) - float(mu)) ** 2 for x in te)) / float(max(1, nte - 1))
            sd = math.sqrt(max(0.0, float(var)))
            se = float(sd) / math.sqrt(float(nte)) if float(nte) > 0.0 else 0.0
            z = float(mu) / float(se) if float(se) > 0.0 else 1e9
            if float(z) < float(revive_min_z):
                continue

            grant_i = float(revive_grant)
            if float(revive_pool_frac) > 0.0:
                grant_i = float(min(float(grant_i), float(pool_u) * float(revive_pool_frac)))
            if float(grant_i) <= 0.0 or float(pool_u) < float(grant_i):
                continue
            st["capital_u"] = float(st.get("capital_u") or 0.0) + float(grant_i)
            st["revives"] = int(st.get("revives") or 0) + 1
            pool_u = max(0.0, float(pool_u) - float(grant_i))
    ARENA_STATE["pool_u"] = float(pool_u)

    eq_max = 2000
    try:
        eq_max = int(CONFIG.get("arena_equity_max_points", 2000) or 2000)
    except Exception:
        eq_max = 2000
    eq_max = max(10, int(eq_max))
    for mid, st in models_state.items():
        if not isinstance(st, dict):
            continue
        cap_u = float(st.get("capital_u") or 0.0)
        peak_u = float(st.get("equity_peak_u") or cap_u)
        peak_u = max(float(peak_u), float(cap_u))
        st["equity_peak_u"] = float(peak_u)
        dd = (float(peak_u) - float(cap_u)) / float(peak_u) if float(peak_u) > 0.0 else 0.0
        st["max_dd"] = max(float(st.get("max_dd") or 0.0), float(dd))
        eq = st.get("equity")
        if not isinstance(eq, list):
            eq = []
        eq.append({"ts": int(now_ms), "equity_u": float(cap_u)})
        if len(eq) > eq_max:
            eq = eq[-eq_max:]
        st["equity"] = eq

    record = {
        "id": _gen_id("asett"),
        "ts": int(now_ms),
        "evt_ts": int(meta.get("evt_ts") or 0),
        "event_id": (str(meta.get("event_id")) if meta.get("event_id") is not None else None),
        "pair": str(meta.get("pair") or ""),
        "side": str(meta.get("side") or ""),
        "tag": meta.get("tag"),
        "ret": float(ret_ratio),
        "pnl_gross_u": float(pnl_gross_u),
        "pnl_net_u": float(pnl_net_u),
        "fees_u": float(fees_u),
        "funding_u": float(funding_u),
        "notional_usdc": float(notional_usdc),
        "risk_unit": float(_arena_risk_unit_ratio(float(atr_pct), float(notional_usdc))),
        "risk_usdc": abs(float(notional_usdc)) * float(_arena_risk_unit_ratio(float(atr_pct), float(notional_usdc))),
        "atr_pct": float(atr_pct),
        "y": int(y),
        "informative": bool(informative),
        "edge_dead_zone": float(dz),
        "logloss_w": float(ll_w),
        "edge_trade": float(edge_trade_global),
        "winner": winner,
        "chosen": arena_evt.get("chosen"),
        "explore": bool(arena_evt.get("explore", False)),
        "edges": {k: float(v) for k, v in edges.items()},
        "logloss": {k: float(v) for k, v in losses.items()},
        "accounting_mode": str(accounting_mode),
        "pnl_alloc_u": {k: float(v) for k, v in pnl_alloc.items()},
        "fees_alloc_u": {k: float(v) for k, v in fees_alloc.items()},
        "funding_alloc_u": {k: float(v) for k, v in funding_alloc.items()},
        "pool_u": float(pool_u),
    }
    hist.append(record)
    try:
        hist_max = int(CONFIG.get("arena_history_max", 2000) or 2000)
    except Exception:
        hist_max = 2000
    hist_max = max(0, int(hist_max))
    if hist_max > 0 and len(hist) > hist_max:
        ARENA_STATE["history"] = hist[-hist_max:]

    attrib = ARENA_STATE.get("attrib")
    if not isinstance(attrib, list):
        attrib = []
        ARENA_STATE["attrib"] = attrib
    try:
        attrib_max = int(CONFIG.get("arena_attrib_max", 5000) or 5000)
    except Exception:
        attrib_max = 5000
    attrib_max = max(100, int(attrib_max))

    try:
        models_out: Dict[str, Any] = {}
        for mid, mv in (m_evt or {}).items():
            if not isinstance(mv, dict):
                continue
            models_out[str(mid)] = {
                "p": float(mv.get("p") or 0.0),
                "pc": float(mv.get("pc") or 0.0),
                "take": bool(mv.get("take", False)),
                "eligible": bool(mv.get("eligible", True)),
                "weight": float(mv.get("weight") or 0.0),
                "capital_u": float(mv.get("capital_u") or 0.0),
                "edge": float(edges.get(str(mid), 0.0)),
                "logloss": float(losses.get(str(mid), 0.0)),
            }
        chosen_id = arena_evt.get("chosen")
        winner_id = winner
        p_star = None
        try:
            if winner_id is not None and str(winner_id) in models_out:
                p_star = float(models_out[str(winner_id)].get("pc") or models_out[str(winner_id)].get("p") or 0.0)
        except Exception:
            p_star = None

        strategy_id = ("" if meta.get("strategy_id") is None else str(meta.get("strategy_id"))).strip() or None
        group_id = ("" if meta.get("group_id") is None else str(meta.get("group_id"))).strip() or None
        feature_set_id = ("" if meta.get("feature_set_id") is None else str(meta.get("feature_set_id"))).strip() or None
        strategy_version = ("" if meta.get("strategy_version") is None else str(meta.get("strategy_version"))).strip() or None

        strategy_features = (meta.get("strategy_features") if isinstance(meta.get("strategy_features"), dict) else (meta.get("features") if isinstance(meta.get("features"), dict) else {}))
        market_features = (meta.get("market_features") if isinstance(meta.get("market_features"), dict) else {})
        if not market_features:
            try:
                evt_ts = int(meta.get("evt_ts") or 0)
            except Exception:
                evt_ts = 0
            pair_s = str(meta.get("pair") or "")
            if pair_s and evt_ts > 0:
                try:
                    market_features = _ml3_features_at_timestamp(pair_s, int(evt_ts))
                except Exception:
                    market_features = {}

        exec_ctx = (meta.get("exec") if isinstance(meta.get("exec"), dict) else {})
        execution_outcome_features = {
            "ret_ratio": float(ret_ratio),
            "pnl_gross_u": float(pnl_gross_u),
            "pnl_net_u": float(pnl_net_u),
            "fees_u": float(fees_u),
            "funding_u": float(funding_u),
            "notional_usdc": float(notional_usdc),
            "leverage": (None if exec_ctx.get("leverage") is None else int(exec_ctx.get("leverage") or 0)),
            "slippage": (None if exec_ctx.get("slippage") is None else float(exec_ctx.get("slippage") or 0.0)),
            "venue": (None if exec_ctx.get("venue") is None else str(exec_ctx.get("venue") or "")),
            "exit_reason": (None if meta.get("exit_reason") is None else str(meta.get("exit_reason") or "")),
            "atr_pct": float(atr_pct),
            "risk_unit": float(_arena_risk_unit_ratio(float(atr_pct), float(notional_usdc))),
            "risk_usdc": abs(float(notional_usdc)) * float(_arena_risk_unit_ratio(float(atr_pct), float(notional_usdc))),
            "hold_ms": int(hold_ms),
            "y": int(y),
        }

        attrib_item = {
            "id": _gen_id("aattrib"),
            "ts": int(now_ms),
            "evt_ts": int(meta.get("evt_ts") or 0),
            "event_id": (str(meta.get("event_id")) if meta.get("event_id") is not None else None),
            "pair": str(meta.get("pair") or ""),
            "side": str(meta.get("side") or ""),
            "tag": meta.get("tag"),
            "regime": str(arena_evt.get("regime") or ""),
            "strategy_id": strategy_id,
            "group_id": group_id,
            "feature_set_id": feature_set_id,
            "strategy_version": strategy_version,
            "features": strategy_features,
            "strategy_features": strategy_features,
            "market_features": market_features,
            "execution_outcome_features": execution_outcome_features,
            "y": int(y),
            "ret": float(ret_ratio),
            "pnl_net_u": float(pnl_net_u),
            "atr_pct": float(atr_pct),
            "notional_usdc": float(notional_usdc),
            "winner_id": (str(winner_id) if winner_id is not None else None),
            "chosen_id": (str(chosen_id) if chosen_id is not None else None),
            "explore": bool(arena_evt.get("explore", False)),
            "disagree": (str(winner_id) != str(chosen_id)) if (winner_id is not None and chosen_id is not None) else False,
            "p_star": p_star,
            "models": models_out,
        }
        attrib.append(attrib_item)
        if len(attrib) > attrib_max:
            ARENA_STATE["attrib"] = attrib[-attrib_max:]
    except Exception:
        pass

    try:
        if bool(CONFIG.get("arena_layer2_autotrain_on_settle", True)):
            _arena_layer2_train_if_needed(now_ms=int(now_ms), force=False)
    except Exception:
        pass

    arena_evt["settled"] = True
    arena_evt["settle_ts"] = int(now_ms)
    ARENA_STATE["ts"] = int(now_ms)
    return {"ok": True, "enabled": True, "winner": winner, "pool_u": float(pool_u)}


def _arena_settle_from_events(now_ms: int, max_n: int = 200) -> Dict[str, Any]:
    if not _arena_enabled():
        return {"ok": True, "settled": 0, "enabled": False}
    _arena_init_if_needed(now_ms=now_ms)
    if not bool(ARENA_STATE.get("inited")):
        return {"ok": False, "error": "arena_not_inited"}
    try:
        shadow_notional_u = float(CONFIG.get("arena_shadow_notional_u", 10.0) or 10.0)
    except Exception:
        shadow_notional_u = 10.0

    settled = 0
    for _, e in list(EVENTS.items()):
        if max_n and int(settled) >= int(max_n):
            break
        if not isinstance(e, dict):
            continue
        if not bool(e.get("labeled", False)):
            continue
        arena_evt = e.get("arena")
        if not isinstance(arena_evt, dict) or bool(arena_evt.get("settled", False)):
            continue
        targets = e.get("targets")
        if not isinstance(targets, dict):
            continue
        mode = str(targets.get("label_mode") or CONFIG.get("label_mode") or "tk").lower()
        if mode == "12h":
            ret_ratio = float(targets.get("return_12h") or 0.0)
        elif mode == "24h":
            ret_ratio = float(targets.get("return_24h") or 0.0)
        else:
            ret_ratio = float(targets.get("return_tk") or 0.0)
        atr_pct = float(targets.get("atr_pct") or 0.0)
        try:
            hold_ms = int(float(CONFIG.get("label_horizon_hours", 12) or 12) * 3600000.0)
        except Exception:
            hold_ms = int(12 * 3600000)
        meta = {
            "evt_ts": int(e.get("ts") or 0),
            "event_id": (str(e.get("id")) if e.get("id") is not None else None),
            "pair": str(e.get("pair") or ""),
            "side": str(e.get("side") or ""),
            "tag": e.get("tag"),
            "hold_ms": int(hold_ms),
            "features": (e.get("features") if isinstance(e.get("features"), dict) else {}),
            "strategy_features": (e.get("strategy_features") if isinstance(e.get("strategy_features"), dict) else (e.get("features") if isinstance(e.get("features"), dict) else {})),
            "market_features": (e.get("market_features") if isinstance(e.get("market_features"), dict) else {}),
            "strategy_id": e.get("strategy_id"),
            "group_id": e.get("group_id"),
            "feature_set_id": e.get("feature_set_id"),
            "strategy_version": e.get("strategy_version"),
        }
        _arena_settle_one(arena_evt=arena_evt, ret_ratio=float(ret_ratio), atr_pct=float(atr_pct), notional_usdc=float(shadow_notional_u), now_ms=int(now_ms), meta=meta)
        e["arena"] = arena_evt
        settled += 1

    return {"ok": True, "settled": int(settled), "pool_u": float(ARENA_STATE.get("pool_u") or 0.0)}


def _arena_settle_from_trade_close(
    pair: str,
    event_id: Any,
    ret_ratio: float,
    notional_usdc: float,
    now_ms: int,
    opened_ms: Any = None,
    extra_meta: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    if not _arena_enabled():
        return {"ok": True, "enabled": False}
    _arena_init_if_needed(now_ms=now_ms)
    if not bool(ARENA_STATE.get("inited")):
        return {"ok": False, "error": "arena_not_inited"}

    evt = EVENTS.get(str(event_id)) if event_id is not None else None
    if not isinstance(evt, dict):
        return {"ok": False, "error": "event_not_found"}
    arena_evt = evt.get("arena")
    if not isinstance(arena_evt, dict):
        return {"ok": False, "error": "arena_event_missing"}
    if bool(arena_evt.get("settled", False)):
        return {"ok": True, "enabled": True, "already_settled": True}

    features = evt.get("features") if isinstance(evt.get("features"), dict) else {}
    strategy_features = evt.get("strategy_features") if isinstance(evt.get("strategy_features"), dict) else {}
    market_features = evt.get("market_features") if isinstance(evt.get("market_features"), dict) else {}
    atr_pct = 0.0
    try:
        atr_pct = float((features or {}).get("atr_pct") or 0.0)
    except Exception:
        atr_pct = 0.0
    if atr_pct <= 0.0:
        try:
            atr_pct = float(_atr_pct_at_timestamp(str(pair), int(evt.get("ts") or 0)))
        except Exception:
            atr_pct = 0.0

    hold_ms = 0
    try:
        opened_ms_i = int(opened_ms or 0)
    except Exception:
        opened_ms_i = 0
    if opened_ms_i > 0:
        hold_ms = max(0, int(now_ms) - int(opened_ms_i))

    meta = {
        "evt_ts": int(evt.get("ts") or 0),
        "event_id": (str(event_id) if event_id is not None else None),
        "pair": str(pair or evt.get("pair") or ""),
        "side": str(evt.get("side") or ""),
        "tag": evt.get("tag"),
        "hold_ms": int(hold_ms),
        "features": (features if isinstance(features, dict) else {}),
        "strategy_features": (strategy_features if isinstance(strategy_features, dict) and strategy_features else (features if isinstance(features, dict) else {})),
        "market_features": (market_features if isinstance(market_features, dict) else {}),
        "strategy_id": evt.get("strategy_id"),
        "group_id": evt.get("group_id"),
        "feature_set_id": evt.get("feature_set_id"),
        "strategy_version": evt.get("strategy_version"),
    }
    if isinstance(extra_meta, dict) and extra_meta:
        try:
            for k, v in extra_meta.items():
                meta[str(k)] = v
        except Exception:
            pass
    out = _arena_settle_one(
        arena_evt=arena_evt,
        ret_ratio=float(ret_ratio),
        atr_pct=float(atr_pct),
        notional_usdc=float(notional_usdc),
        now_ms=int(now_ms),
        meta=meta,
    )
    evt["arena"] = arena_evt
    return out


def _entry_leverage_state() -> Dict[str, Any]:
    st = TRACKER_STATE.get("leverage_state")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["leverage_state"] = st
    return st


def _entry_hard_leverage_bounds() -> Tuple[int, int]:
    return 3, 10


def _entry_hard_clip_leverage(leverage: Any) -> int:
    lo, hi = _entry_hard_leverage_bounds()
    try:
        lev = int(leverage)
    except Exception:
        lev = int(lo)
    return int(_clip(int(lev), int(lo), int(hi)))


def _entry_base_leverage_for_venue(venue: str) -> int:
    v = str(venue or "stub").lower().strip() or "stub"
    if v == "hyperliquid":
        try:
            lev = int(CONFIG.get("hl_default_leverage", 1) or 1)
        except Exception:
            lev = 1
    elif v == "aster":
        try:
            lev = int(CONFIG.get("aster_default_leverage", 10) or 10)
        except Exception:
            lev = 10
    else:
        lev = 1
    if v in ("hyperliquid", "aster"):
        return _entry_hard_clip_leverage(int(lev))
    return max(1, min(20, int(lev)))


def _entry_dynamic_leverage(pair: str, side: str, market_features: Optional[Dict[str, Any]], features: Optional[Dict[str, Any]], now_ms: int) -> Tuple[int, Dict[str, Any]]:
    try:
        enabled = bool(CONFIG.get("leverage_dynamic_enabled", False))
    except Exception:
        enabled = False
    if not enabled:
        return _entry_base_leverage_for_venue(str(CONFIG.get("execution_venue", "stub") or "stub")), {"enabled": False}

    s = str(side or "").lower().strip()
    if s not in ("long", "short"):
        return _entry_base_leverage_for_venue(str(CONFIG.get("execution_venue", "stub") or "stub")), {"enabled": False}

    try:
        lev_min = int(CONFIG.get("leverage_dynamic_min", 3) or 3)
    except Exception:
        lev_min = 3
    try:
        lev_max = int(CONFIG.get("leverage_dynamic_max", 10) or 10)
    except Exception:
        lev_max = 10
    lo, hi = _entry_hard_leverage_bounds()
    lev_min = int(_clip(int(lev_min), int(lo), int(hi)))
    lev_max = int(_clip(int(lev_max), int(lo), int(hi)))
    if lev_max < lev_min:
        lev_max = int(lev_min)

    try:
        hyst = int(CONFIG.get("leverage_dynamic_hysteresis", 1) or 1)
    except Exception:
        hyst = 1
    hyst = max(0, int(hyst))

    try:
        cd_sec = float(CONFIG.get("leverage_dynamic_cooldown_sec", 900) or 900)
    except Exception:
        cd_sec = 900
    cooldown_ms = int(max(0.0, float(cd_sec)) * 1000.0)

    mf = market_features if isinstance(market_features, dict) else {}
    f = features if isinstance(features, dict) else {}

    try:
        rb = float(mf.get("risk_baseline") or 0.0)
    except Exception:
        rb = 0.0
    rb = float(_clip(float(rb), 0.0, 1.0))

    atr_pct = None
    try:
        atr_pct = float(mf.get("atr_pct")) if mf.get("atr_pct") is not None else None
    except Exception:
        atr_pct = None
    if atr_pct is None:
        try:
            atr_pct = float(f.get("atr_pct")) if f.get("atr_pct") is not None else None
        except Exception:
            atr_pct = None
    if atr_pct is None:
        atr_pct = 0.0
    atr_pct = float(_clip(float(atr_pct), 0.0, 0.50))

    try:
        atr_ref = float(CONFIG.get("leverage_dynamic_atr_ref", 0.03) or 0.03)
    except Exception:
        atr_ref = 0.03
    atr_ref = max(1e-9, float(atr_ref))
    atr_n = float(_clip(float(atr_pct) / float(atr_ref), 0.0, 1.0))

    risk = float(_clip(0.65 * float(rb) + 0.35 * float(atr_n), 0.0, 1.0))
    lev_raw = float(lev_max) - (float(lev_max - lev_min) * float(risk))
    lev_target = int(round(float(lev_raw)))
    lev_target = int(_clip(int(lev_target), int(lev_min), int(lev_max)))
    tri_tier = "neutral"
    tri_allow_open = True
    tri_crash_switch = False
    try:
        tri_link_enabled = bool(CONFIG.get("entry_tri_layer_leverage_link_enabled", True))
    except Exception:
        tri_link_enabled = True
    if bool(tri_link_enabled):
        try:
            tri_snap = _macro_btc_dir_snapshot(timeframe="1h", horizon_h=12, short_n=3)
        except Exception:
            tri_snap = None
        try:
            if isinstance(tri_snap, dict) and bool(tri_snap.get("ok", False)):
                tri_tier = str(tri_snap.get("risk_budget_tier") or "neutral")
                tri_allow_open = bool(tri_snap.get("allow_open", True))
                tri_crash_switch = bool(tri_snap.get("crash_switch", False))
        except Exception:
            tri_tier = "neutral"
            tri_allow_open = True
            tri_crash_switch = False
        tri_mul = 1.0
        try:
            if str(tri_tier) == "risk_on":
                tri_mul *= float(CONFIG.get("entry_tri_layer_leverage_mult_risk_on", 1.0) or 1.0)
            elif str(tri_tier) == "neutral":
                tri_mul *= float(CONFIG.get("entry_tri_layer_leverage_mult_neutral", 0.9) or 0.9)
            elif str(tri_tier) == "risk_off_pre":
                tri_mul *= float(CONFIG.get("entry_tri_layer_leverage_mult_risk_off_pre", 0.7) or 0.7)
            else:
                tri_mul *= float(CONFIG.get("entry_tri_layer_leverage_mult_risk_off", 0.5) or 0.5)
            if not bool(tri_allow_open):
                tri_mul *= float(CONFIG.get("entry_tri_layer_leverage_mult_allow_open_false", 0.7) or 0.7)
            if bool(tri_crash_switch):
                tri_mul *= float(CONFIG.get("entry_tri_layer_leverage_mult_crash_switch", 0.5) or 0.5)
        except Exception:
            tri_mul = 1.0
        if math.isfinite(float(tri_mul)) and float(tri_mul) > 0.0:
            lev_target = int(round(float(lev_target) * float(tri_mul)))
            lev_target = int(_clip(int(lev_target), int(lev_min), int(lev_max)))

    st = _entry_leverage_state()
    pkey = str(pair or "").strip()
    prev = st.get(pkey) if isinstance(st.get(pkey), dict) else {}
    try:
        prev_lev = int(prev.get("leverage") or 0)
    except Exception:
        prev_lev = 0
    try:
        prev_ts = int(prev.get("ts") or 0)
    except Exception:
        prev_ts = 0

    lev_eff = int(lev_target)
    changed = True
    if prev_lev > 0:
        if cooldown_ms > 0 and prev_ts > 0 and (int(now_ms) - int(prev_ts)) < int(cooldown_ms):
            lev_eff = int(prev_lev)
            changed = False
        elif hyst > 0 and abs(int(lev_target) - int(prev_lev)) < int(hyst):
            lev_eff = int(prev_lev)
            changed = False

    st[pkey] = {
        "ts": int(now_ms),
        "leverage": int(lev_eff),
        "target": int(lev_target),
        "risk": float(risk),
        "rb": float(rb),
        "atr_pct": float(atr_pct),
        "atr_n": float(atr_n),
        "cooldown_ms": int(cooldown_ms),
        "hysteresis": int(hyst),
        "changed": bool(changed),
        "tri_risk_budget_tier": str(tri_tier),
        "tri_allow_open": bool(tri_allow_open),
        "tri_crash_switch": bool(tri_crash_switch),
    }
    return int(lev_eff), dict(st[pkey])


def _decision_entry_impl(data: Dict[str, Any]) -> Tuple[Dict[str, Any], int]:
    side = str(data.get("side", "")).lower()
    pair = data.get("pair")
    tag = data.get("tag")
    features = data.get("features") or {}
    size = _to_float(data.get("size", 0.0))
    size_specified = False
    try:
        size_specified = ("size" in data) and math.isfinite(float(size)) and float(size) > 0.0
    except Exception:
        size_specified = False
    now_ms = _now_ms()

    canary_active = False
    canary_frac_used = None
    size_pre_canary = None
    size_after_canary = None
    soft_size_before = None
    soft_size_after = None
    soft_size_mult_total = 1.0

    event_id = data.get("event_id")
    if event_id is not None:
        event_id = str(event_id).strip() or None

    evt = EVENTS.get(str(event_id)) if event_id is not None else None

    try:
        if event_id is not None and isinstance(evt, dict):
            ts_sig = int(evt.get("ingested_ms") or evt.get("ts_emit_ms") or evt.get("ts") or 0)
            lat = int(now_ms) - int(ts_sig)
            if ts_sig > 0 and 0 <= int(lat) <= 10 * 60 * 1000:
                _sli_online_observe("signal_to_decision_ms", float(lat), now_ms=int(now_ms))
    except Exception:
        pass

    if not isinstance(features, dict):
        features = {}

    if event_id is not None and not isinstance(evt, dict):
        try:
            ts0 = int(data.get("ts") or now_ms)
        except Exception:
            ts0 = int(now_ms)
        stub = {
            "id": str(event_id),
            "event_id": str(event_id),
            "pair": (None if pair is None else str(pair)),
            "side": str(side),
            "tag": tag,
            "features": dict(features or {}),
            "strategy_features": dict(features or {}),
            "market_features": {},
            "ts": int(ts0),
            "ingested_ms": int(now_ms),
            "bar_closed": True,
            "action": "open",
            "strategy_id": None,
            "strategy_version": None,
            "group_id": None,
            "feature_set_id": None,
            "source": "decision_entry",
        }
        EVENTS[str(event_id)] = stub
        evt = stub
        try:
            _archive_event(stub)
        except Exception:
            pass
    strategy_features = data.get("strategy_features")
    if not isinstance(strategy_features, dict):
        if isinstance(evt, dict) and isinstance(evt.get("strategy_features"), dict):
            strategy_features = evt.get("strategy_features")
        else:
            strategy_features = features
    strategy_features = dict(strategy_features or {})
    features = dict(features or {})
    try:
        evt_ts = 0
        if isinstance(evt, dict):
            evt_ts = int(evt.get("bar_open_ms") or evt.get("bar_close_ms") or evt.get("ts") or evt.get("ts_emit_ms") or 0)
        ts_for_feat = int(data.get("ts") or evt_ts or now_ms)
    except Exception:
        ts_for_feat = int(now_ms)

    market_features: Dict[str, Any] = {}
    try:
        if pair and int(ts_for_feat) > 0:
            market_features = _ml3_features_at_timestamp(str(pair), int(ts_for_feat)) or {}
    except Exception:
        market_features = {}

    try:
        need_ml3 = False
        for mv in (MODELS or {}).values():
            if hasattr(mv, "n_features_in_") and int(getattr(mv, "n_features_in_")) == len(_ml3_feature_keys()):
                need_ml3 = True
                break
        if need_ml3 and market_features and isinstance(features, dict):
            for k, v in market_features.items():
                if k not in features or (not math.isfinite(float(features.get(k) or 0.0))):
                    features[k] = float(v)
    except Exception:
        pass

    if isinstance(evt, dict):
        evt["strategy_features"] = dict(strategy_features or {})
        evt["market_features"] = dict(market_features or {})

    tf_evt = None
    try:
        if isinstance(evt, dict):
            tf_evt = evt.get("timeframe")
    except Exception:
        tf_evt = None
    regime = _get_regime(features, pair=str(pair), ts=int(ts_for_feat or 0), timeframe=(None if tf_evt is None else str(tf_evt)))
    thr_base = _get_threshold(regime)
    threshold_specified = ("threshold" in data)
    if threshold_specified:
        thr_base = _to_float(data["threshold"])

    threshold_final = False
    try:
        threshold_final = bool(data.get("threshold_final") or data.get("threshold_locked") or data.get("threshold_absolute"))
    except Exception:
        threshold_final = False

    strategy_id = None
    group_id = None
    feature_set_id = None
    strategy_version = None
    if isinstance(evt, dict):
        strategy_id = evt.get("strategy_id")
        group_id = evt.get("group_id")
        feature_set_id = evt.get("feature_set_id")
        strategy_version = evt.get("strategy_version")
    strategy_id = ("" if strategy_id is None else str(strategy_id)).strip() or None
    if strategy_id:
        sid_l = strategy_id.lower().replace("-", "").replace("_", "").strip()
        if sid_l == "threescreen":
            strategy_id = "ThreeScreen"
    group_id = ("" if group_id is None else str(group_id)).strip() or None
    feature_set_id = ("" if feature_set_id is None else str(feature_set_id)).strip() or None
    strategy_version = ("" if strategy_version is None else str(strategy_version)).strip() or None

    three_screen_phase0 = False
    three_screen_force_shadow = False
    three_screen_force_strategy_book = False
    three_screen_use_ml_vote = True
    three_screen_live_exec = False
    if str(strategy_id or "") == "ThreeScreen":
        try:
            p0 = int(CONFIG.get("three_screen_phase", 0) or 0)
        except Exception:
            p0 = 0
        three_screen_phase0 = int(p0) == 0
        try:
            three_screen_live_exec = bool(_live_trading_enabled_for_owner("three_screen")) and (not bool(CONFIG.get("dry_run", True)))
        except Exception:
            three_screen_live_exec = False
        try:
            three_screen_use_ml_vote = bool(CONFIG.get("three_screen_use_ml_vote", True))
        except Exception:
            three_screen_use_ml_vote = True
        if bool(three_screen_phase0):
            try:
                three_screen_force_shadow = bool(CONFIG.get("three_screen_phase0_force_shadow", True))
            except Exception:
                three_screen_force_shadow = True
            if bool(three_screen_live_exec):
                keep_shadow = False
                try:
                    keep_shadow = bool(CONFIG.get("three_screen_force_shadow_when_live", False))
                except Exception:
                    keep_shadow = False
                if not bool(keep_shadow):
                    three_screen_force_shadow = False
            try:
                three_screen_force_strategy_book = bool(CONFIG.get("three_screen_phase0_force_ab_owner_strategy", True))
            except Exception:
                three_screen_force_strategy_book = True
        if group_id in (None, "", "default"):
            try:
                group_id = str(CONFIG.get("three_screen_group_id_default", "ThreeScreen.v0") or "ThreeScreen.v0").strip() or "ThreeScreen.v0"
            except Exception:
                group_id = "ThreeScreen.v0"
        if not bool(threshold_specified):
            try:
                et = features.get("entry_threshold")
                if et is None and isinstance(strategy_features, dict):
                    et = strategy_features.get("entry_threshold")
                if et is not None:
                    et_f = float(et)
                    if math.isfinite(float(et_f)):
                        thr_base = float(_clip(float(et_f), 0.0, 1.0))
            except Exception:
                pass

    owner_kind = _owner_from_strategy_id(strategy_id)
    if bool(three_screen_force_strategy_book):
        owner_kind = "strategy"

    strategy_tier = None
    tier_reason = None
    tier_trading_enabled = True
    try:
        tier_trading_enabled = bool(CONFIG.get("strategy_tier_trading_enabled", True))
    except Exception:
        tier_trading_enabled = True
    if tier_trading_enabled and owner_kind == "strategy" and strategy_id is not None:
        try:
            tdef = str(CONFIG.get("strategy_tier_default", "A") or "A").strip().upper()
        except Exception:
            tdef = "C"
        if tdef not in ("A", "B", "C"):
            tdef = "C"
        strategy_tier = tdef
        if strategy_id:
            try:
                ent = _strategy_registry_get_entry(str(strategy_id), "*")
            except Exception:
                ent = {}
            if isinstance(ent, dict) and ent:
                try:
                    t0 = _strategy_tier_normalize(ent.get("tier"))
                except Exception:
                    t0 = None
                if t0 in ("A", "B", "C"):
                    strategy_tier = t0
                if ent.get("tier_reason") is not None:
                    tier_reason = str(ent.get("tier_reason") or "").strip() or None

    ab_owner = None
    owner_contrib_raw = None
    try:
        if isinstance(evt, dict):
            ab_owner = evt.get("ab_owner")
            owner_contrib_raw = evt.get("owner_contrib")
    except Exception:
        ab_owner = None
        owner_contrib_raw = None
    if ab_owner is None:
        ab_owner = owner_kind
    if bool(three_screen_force_strategy_book) and str(strategy_id or "") == "ThreeScreen":
        ab_owner = "strategy"
    ab_owner = _ab_norm_owner(ab_owner)

    system_id_req = data.get("system_id")
    system_id = None
    if system_id_req is not None:
        try:
            system_id = _system_from_strategy_id(system_id_req)
        except Exception:
            system_id = None
    if system_id is None:
        try:
            system_id = _system_from_strategy_id(strategy_id)
        except Exception:
            system_id = "strategy"
    if bool(three_screen_force_strategy_book) and str(strategy_id or "") == "ThreeScreen":
        system_id = "strategy"
    try:
        if str(ab_owner) == "quant":
            system_id = "quant"
    except Exception:
        pass
    try:
        system_id = _system_from_strategy_id(system_id)
    except Exception:
        system_id = "strategy"

    try:
        if system_id_req is not None:
            sys_req = _system_from_strategy_id(system_id_req)
            if sys_req in ("quant", "carry"):
                owner_kind = str(sys_req)
                if str(ab_owner) == "strategy":
                    ab_owner = str(sys_req)
                ab_owner = _ab_norm_owner(ab_owner)
    except Exception:
        pass

    owner_contrib: Dict[str, float] = {"strategy": 0.0, "quant": 0.0, "carry": 0.0, "three_screen": 0.0}
    if isinstance(owner_contrib_raw, dict) and owner_contrib_raw:
        for k in ("strategy", "quant", "carry", "three_screen"):
            try:
                v = owner_contrib_raw.get(k)
                if v is not None and math.isfinite(float(v)):
                    owner_contrib[k] = float(v)
            except Exception:
                continue
    if float(owner_contrib.get("strategy", 0.0) + owner_contrib.get("quant", 0.0) + owner_contrib.get("carry", 0.0) + owner_contrib.get("three_screen", 0.0)) <= 0.0:
        owner_contrib = {"strategy": 0.0, "quant": 0.0, "carry": 0.0, "three_screen": 0.0}
        owner_contrib[str(ab_owner)] = 1.0

    base_dry_run = True
    try:
        base_dry_run = bool(CONFIG.get("dry_run", True))
    except Exception:
        base_dry_run = True

    dry_run_effective = bool(base_dry_run)
    strategy_live_allowed = True
    if not bool(base_dry_run):
        strategy_live_allowed = bool(_strategy_live_trading_allowed(strategy_id, group_id, str(pair) if pair is not None else None))
        if not bool(strategy_live_allowed):
            dry_run_effective = True

    if not bool(dry_run_effective):
        try:
            if not bool(_live_trading_enabled_for_owner(str(owner_kind))):
                dry_run_effective = True
        except Exception:
            dry_run_effective = True

    tier_shadow_for_strategy = False
    tier_force_canary = False
    if tier_trading_enabled and owner_kind == "strategy" and strategy_tier in ("A", "B", "C"):
        tier_shadow_for_strategy = (strategy_tier == "C")
        tier_force_canary = (strategy_tier == "B")
        if str(strategy_id or "") == "ThreeScreen" and bool(three_screen_live_exec):
            keep_tier_shadow = False
            try:
                keep_tier_shadow = bool(CONFIG.get("three_screen_keep_tier_shadow_when_live", False))
            except Exception:
                keep_tier_shadow = False
            if not bool(keep_tier_shadow):
                tier_shadow_for_strategy = False
        if tier_shadow_for_strategy:
            dry_run_effective = True

    macro_regime = None
    macro_regime_info = None
    tri_layer_snap = None
    tri_layer_ok = False
    tri_allow_open = True
    tri_allow_addon = False
    tri_addon_pacing = "normal"
    tri_risk_budget_tier = "neutral"
    tri_target_net_bias = 0.0
    tri_max_net_exposure = None
    tri_rule_id = "R-A0"
    do_apply_tri_layer = False
    try:
        do_apply_tri_layer = bool(CONFIG.get("entry_tri_layer_strategy_enabled", True)) and str(system_id) == "strategy" and bool(pair and side in ("long", "short") and _entry_macro_scope_ok(pair=str(pair), strategy_id=str(strategy_id or "")))
    except Exception:
        do_apply_tri_layer = False
    if bool(do_apply_tri_layer):
        try:
            tri_layer_snap = _macro_btc_dir_snapshot(timeframe="1h", horizon_h=12, short_n=3)
        except Exception:
            tri_layer_snap = None
        try:
            tri_layer_ok = bool(isinstance(tri_layer_snap, dict) and bool(tri_layer_snap.get("ok", False)))
            if bool(tri_layer_ok):
                tri_allow_open = bool(tri_layer_snap.get("allow_open", True))
                tri_allow_addon = bool(tri_layer_snap.get("allow_addon", False))
                tri_addon_pacing = str(tri_layer_snap.get("addon_pacing") or "normal")
                tri_risk_budget_tier = str(tri_layer_snap.get("risk_budget_tier") or "neutral")
                tri_rule_id = str(tri_layer_snap.get("rule_id") or "R-A0")
                if tri_layer_snap.get("target_net_bias") is not None:
                    tri_target_net_bias = float(tri_layer_snap.get("target_net_bias"))
                if tri_layer_snap.get("max_net_exposure") is not None:
                    tri_max_net_exposure = float(tri_layer_snap.get("max_net_exposure"))
        except Exception:
            tri_layer_ok = False
            tri_allow_open = True
            tri_allow_addon = False
            tri_addon_pacing = "normal"
            tri_risk_budget_tier = "neutral"
            tri_target_net_bias = 0.0
            tri_max_net_exposure = None
            tri_rule_id = "R-A0"
    if not bool(threshold_final):
        try:
            if pair and side in ("long", "short") and _entry_macro_scope_ok(pair=str(pair), strategy_id=str(strategy_id or "")):
                thr_base, macro_regime, macro_regime_info = _entry_macro_threshold_overlay(
                    float(thr_base),
                    side=str(side),
                    pair=str(pair),
                    strategy_id=str(strategy_id or ""),
                    ts_ms=int(ts_for_feat or now_ms),
                )
        except Exception:
            macro_regime = None
            macro_regime_info = None
    if (not bool(threshold_final)) and bool(do_apply_tri_layer) and bool(tri_layer_ok):
        try:
            tri_thr_link = bool(CONFIG.get("entry_tri_layer_threshold_link_enabled", True))
        except Exception:
            tri_thr_link = True
        if bool(tri_thr_link):
            tri_shift = 0.0
            try:
                if str(tri_risk_budget_tier) == "risk_on":
                    tri_shift += float(CONFIG.get("entry_tri_layer_threshold_shift_risk_on", -0.005) or -0.005)
                elif str(tri_risk_budget_tier) == "neutral":
                    tri_shift += float(CONFIG.get("entry_tri_layer_threshold_shift_neutral", 0.0) or 0.0)
                elif str(tri_risk_budget_tier) == "risk_off_pre":
                    tri_shift += float(CONFIG.get("entry_tri_layer_threshold_shift_risk_off_pre", 0.03) or 0.03)
                else:
                    tri_shift += float(CONFIG.get("entry_tri_layer_threshold_shift_risk_off", 0.08) or 0.08)
            except Exception:
                tri_shift += 0.0
            try:
                bias_abs_min = float(CONFIG.get("entry_tri_layer_target_bias_min_abs", 0.10) or 0.10)
            except Exception:
                bias_abs_min = 0.10
            if math.isfinite(float(tri_target_net_bias)) and abs(float(tri_target_net_bias)) >= float(max(0.0, bias_abs_min)):
                is_counter_side = (str(side) == "long" and float(tri_target_net_bias) < 0.0) or (str(side) == "short" and float(tri_target_net_bias) > 0.0)
                if bool(is_counter_side):
                    try:
                        tri_shift += float(CONFIG.get("entry_tri_layer_threshold_shift_counter", 0.02) or 0.02)
                    except Exception:
                        pass
                else:
                    try:
                        tri_shift -= float(CONFIG.get("entry_tri_layer_threshold_shift_aligned", 0.005) or 0.005)
                    except Exception:
                        pass
            if math.isfinite(float(tri_shift)) and float(tri_shift) != 0.0:
                thr_base = float(_clip(float(thr_base) + float(tri_shift), 0.0, 1.0))

    if not bool(threshold_final):
        if strategy_id is not None:
            st_ov = _get_strategy_threshold_override(strategy_id)
            if st_ov is not None:
                thr_base = max(float(thr_base), float(st_ov))
        if group_id is not None:
            gmeta = _get_group_meta(group_id)
            if "pc_threshold_min" in (gmeta or {}):
                try:
                    thr_base = max(float(thr_base), float(gmeta.get("pc_threshold_min")))
                except Exception:
                    pass

    thr_pre_elastic = float(thr_base)
    if not bool(threshold_final):
        try:
            do_ratio = bool(CONFIG.get("entry_shape12h_target_ratio_enabled", False))
        except Exception:
            do_ratio = False

        if bool(do_ratio) and pair and side in ("long", "short") and _entry_macro_scope_ok(pair=str(pair), strategy_id=str(strategy_id or "")):
            sh = None
            try:
                sh = _entry_macro_btceth_shape_at(int(ts_for_feat or now_ms))
            except Exception:
                sh = None
            if isinstance(sh, dict) and bool(sh.get("ok", False)) and bool(sh.get("valid", False)):
                shape0 = sh.get("shape")
                dir12 = None
                try:
                    if sh.get("dir_12h") is not None:
                        dir12 = int(sh.get("dir_12h") or 0)
                except Exception:
                    dir12 = None
                if shape0 is not None and str(shape0).strip() and dir12 in (1, -1, 0):
                    shape_tier = int(_shape_tier_get(shape0))
                    _, target_long_share, _ = _shape12h_target_net_bias_and_shares(shape=shape0, shape_tier=shape_tier, shape_dir_12h=dir12)

                    try:
                        op0 = _tracker_open_positions_get(system_id)
                    except Exception:
                        op0 = {}
                    stats0 = _open_positions_portfolio_stats(op0)
                    try:
                        gross_used0 = float(stats0.get("gross_usdc") or 0.0)
                    except Exception:
                        gross_used0 = 0.0
                    try:
                        long_used0 = float(stats0.get("long_usdc") or 0.0)
                    except Exception:
                        long_used0 = 0.0

                    cur_long_share = None
                    if math.isfinite(float(gross_used0)) and float(gross_used0) > 1e-12:
                        cur_long_share = float(_clip(float(long_used0) / float(gross_used0), 0.0, 1.0))

                    if cur_long_share is not None:
                        dev = float(cur_long_share) - float(target_long_share)
                        dev_abs = abs(float(dev))
                        is_over = (str(side).lower().strip() == "long" and dev > 0) or (str(side).lower().strip() == "short" and dev < 0)
                        is_under = (str(side).lower().strip() == "long" and dev < 0) or (str(side).lower().strip() == "short" and dev > 0)

                        try:
                            b1 = float(CONFIG.get("entry_shape12h_target_ratio_band1", 0.03) or 0.03)
                        except Exception:
                            b1 = 0.03
                        try:
                            b2 = float(CONFIG.get("entry_shape12h_target_ratio_band2", 0.08) or 0.08)
                        except Exception:
                            b2 = 0.08
                        try:
                            b3 = float(CONFIG.get("entry_shape12h_target_ratio_band3", 0.15) or 0.15)
                        except Exception:
                            b3 = 0.15
                        if (not math.isfinite(float(b1))) or float(b1) < 0.0:
                            b1 = 0.03
                        if (not math.isfinite(float(b2))) or float(b2) < float(b1):
                            b2 = max(float(b1), 0.08)
                        if (not math.isfinite(float(b3))) or float(b3) < float(b2):
                            b3 = max(float(b2), 0.15)

                        band = 0
                        if dev_abs >= float(b3) - 1e-12:
                            band = 3
                        elif dev_abs >= float(b2) - 1e-12:
                            band = 2
                        elif dev_abs >= float(b1) - 1e-12:
                            band = 1

                        if band > 0 and (bool(is_over) or bool(is_under)):
                            try:
                                ov1 = float(CONFIG.get("entry_shape12h_target_ratio_thr_shift_over_b1", 0.005) or 0.005)
                            except Exception:
                                ov1 = 0.005
                            try:
                                ov2 = float(CONFIG.get("entry_shape12h_target_ratio_thr_shift_over_b2", 0.010) or 0.010)
                            except Exception:
                                ov2 = 0.010
                            try:
                                ov3 = float(CONFIG.get("entry_shape12h_target_ratio_thr_shift_over_b3", 0.020) or 0.020)
                            except Exception:
                                ov3 = 0.020

                            shift_over = ov1 if band == 1 else (ov2 if band == 2 else ov3)
                            if (not math.isfinite(float(shift_over))) or float(shift_over) < 0.0:
                                shift_over = 0.0
                            shift_over = float(_clip(float(shift_over), 0.0, 0.10))

                            try:
                                under_mult = float(CONFIG.get("entry_shape12h_target_ratio_thr_shift_under_mult", 0.5) or 0.5)
                            except Exception:
                                under_mult = 0.5
                            if (not math.isfinite(float(under_mult))) or float(under_mult) < 0.0:
                                under_mult = 0.0
                            under_mult = float(_clip(float(under_mult), 0.0, 2.0))

                            shift = 0.0
                            if bool(is_over):
                                shift = float(shift_over)
                            elif bool(is_under):
                                shift = -float(shift_over) * float(under_mult)

                            if math.isfinite(float(shift)) and float(shift) != 0.0:
                                thr_base = float(_clip(float(thr_base) + float(shift), 0.0, 1.0))
        
        try:
            thr_base = float(_elastic_overlay_threshold(float(thr_base), group_id, int(now_ms)))
        except Exception:
            thr_base = float(thr_base)

        try:
            delta = float(CONFIG.get("pc_hysteresis_delta", 0.0) or 0.0)
        except Exception:
            delta = 0.0
        delta = float(_clip(float(delta), 0.0, 0.5))
        thr = float(thr_base) + float(delta) if delta > 0.0 else float(thr_base)
    else:
        delta = 0.0
        thr = float(thr_base)

    three_screen_size_mult = 1.0
    three_screen_degrade_info: Optional[Dict[str, Any]] = None
    try:
        if str(strategy_id or "") == "ThreeScreen":
            sf = dict(strategy_features or {}) if isinstance(strategy_features, dict) else {}
            issues: List[str] = []

            try:
                mfam = str(sf.get("entry_model_family") or "").strip().lower()
            except Exception:
                mfam = ""
            try:
                mver = str(sf.get("model_version") or "").strip()
            except Exception:
                mver = ""
            if mfam == "lstm" and not mver:
                issues.append("model_missing")

            try:
                rr = str(sf.get("reject_reason") or "").strip()
            except Exception:
                rr = ""
            rr_l = rr.lower()
            if rr_l in ("model_missing", "model_expired", "model_drift"):
                issues.append(rr_l)

            try:
                cts = int(sf.get("candidates_ts") or 0)
            except Exception:
                cts = 0
            try:
                ttl_sec = int(sf.get("candidates_ttl_sec") or 0)
            except Exception:
                ttl_sec = 0
            if cts > 0 and ttl_sec > 0:
                age_ms = int(now_ms) - int(cts)
                if age_ms > int(ttl_sec) * 1000:
                    issues.append("candidates_stale")

            try:
                align = sf.get("align_with_weekly")
                if align is False:
                    issues.append("align_with_weekly_false")
            except Exception:
                pass

            bar_close_ms_evt = 0
            try:
                if isinstance(evt, dict):
                    bar_close_ms_evt = int(evt.get("bar_close_ms") or 0)
            except Exception:
                bar_close_ms_evt = 0
            try:
                vu = int(sf.get("daily_valid_until_ms") or 0)
            except Exception:
                vu = 0
            if vu > 0 and bar_close_ms_evt > 0 and bar_close_ms_evt > vu:
                issues.append("daily_expired")

            if issues:
                st = TRACKER_STATE.get("three_screen_degradation")
                if not isinstance(st, dict):
                    st = {"stage": 0, "last_adv_ms": 0}
                try:
                    stage0 = int(st.get("stage") or 0)
                except Exception:
                    stage0 = 0
                try:
                    last_adv = int(st.get("last_adv_ms") or 0)
                except Exception:
                    last_adv = 0

                advance_ok = (int(now_ms) - int(last_adv)) >= 60_000
                stage = int(max(0, stage0))
                next_stage = stage
                mode = ""

                if stage <= 0:
                    try:
                        m1 = float(CONFIG.get("three_screen_degrade_size_mult_1", 0.50) or 0.50)
                    except Exception:
                        m1 = 0.50
                    if math.isfinite(float(m1)) and float(m1) > 0.0:
                        three_screen_size_mult *= float(m1)
                    next_stage = 1
                    mode = "size"
                elif stage == 1:
                    if not bool(threshold_final):
                        try:
                            add2 = float(CONFIG.get("three_screen_degrade_thr_add_2", 0.05) or 0.05)
                        except Exception:
                            add2 = 0.05
                        if math.isfinite(float(add2)) and float(add2) > 0.0:
                            thr_base = float(_clip(float(thr_base) + float(add2), 0.0, 1.0))
                            thr = float(_clip(float(thr) + float(add2), 0.0, 1.0))
                    next_stage = 2
                    mode = "thr"
                elif stage == 2:
                    if not bool(threshold_final):
                        try:
                            s3 = float(CONFIG.get("three_screen_degrade_strong_thr_3", 0.75) or 0.75)
                        except Exception:
                            s3 = 0.75
                        if math.isfinite(float(s3)):
                            thr_base = float(max(float(thr_base), float(s3)))
                            thr = float(max(float(thr), float(s3)))
                    next_stage = 3
                    mode = "strong"
                else:
                    out = {"ok": True, "decision": "hold", "threshold": float(thr), "regime": regime, "reason": f"three_screen_stop_{issues[0]}"}
                    if macro_regime is not None:
                        out["macro_regime"] = str(macro_regime)
                    out["degradation"] = {"stage": int(stage), "issues": issues}
                    out["strategy_features"] = dict(strategy_features or {})
                    out["market_features"] = dict(market_features or {})
                    return out, 200

                three_screen_degrade_info = {"stage": int(stage), "next_stage": int(next_stage), "mode": mode, "issues": issues}
                if bool(advance_ok) and int(next_stage) != int(stage):
                    TRACKER_STATE["three_screen_degradation"] = {"stage": int(next_stage), "last_adv_ms": int(now_ms), "issues": issues}
    except Exception:
        three_screen_size_mult = 1.0
        three_screen_degrade_info = None

    monitor_size_mult = 1.0
    monitor_thr_add = 0.0
    monitor_stop = False
    monitor_degrade_info: Optional[Dict[str, Any]] = None
    try:
        if str(strategy_id or "") == "ThreeScreen":
            st = TRACKER_STATE.get("entry_degradation")
            if not isinstance(st, dict):
                st = {}
            try:
                en = bool(st.get("enabled", True))
            except Exception:
                en = True
            try:
                auto_en = bool(CONFIG.get("monitor_center_auto_degrade_enabled", True))
            except Exception:
                auto_en = True
            if bool(en) and bool(auto_en):
                try:
                    stg = int(st.get("stage") or 0)
                except Exception:
                    stg = 0
                if stg > 0:
                    iss = st.get("issues") if isinstance(st.get("issues"), list) else []
                    monitor_degrade_info = {"stage": int(stg), "issues": [str(x) for x in iss if str(x or "").strip()][:20]}
                    if int(stg) >= 1:
                        try:
                            m1 = float(CONFIG.get("monitor_center_entry_degrade_size_mult_stage1", 0.50) or 0.50)
                        except Exception:
                            m1 = 0.50
                        if math.isfinite(float(m1)) and float(m1) > 0.0:
                            monitor_size_mult = float(_clip(float(m1), 0.0, 1.0))
                    if int(stg) >= 2 and (not bool(threshold_final)):
                        try:
                            add2 = float(CONFIG.get("monitor_center_entry_degrade_thr_add_stage2", 0.05) or 0.05)
                        except Exception:
                            add2 = 0.05
                        if math.isfinite(float(add2)) and float(add2) > 0.0:
                            monitor_thr_add = float(_clip(float(add2), 0.0, 0.20))
                    if int(stg) >= 3:
                        try:
                            monitor_stop = bool(CONFIG.get("monitor_center_entry_stop_stage3", True))
                        except Exception:
                            monitor_stop = True
    except Exception:
        monitor_size_mult = 1.0
        monitor_thr_add = 0.0
        monitor_stop = False
        monitor_degrade_info = None

    if math.isfinite(float(monitor_thr_add)) and float(monitor_thr_add) > 0.0 and (not bool(threshold_final)):
        thr_base = float(_clip(float(thr_base) + float(monitor_thr_add), 0.0, 1.0))
        thr = float(_clip(float(thr) + float(monitor_thr_add), 0.0, 1.0))

    degradation_out: Optional[Dict[str, Any]] = None
    try:
        dd: Dict[str, Any] = {}
        stage2 = 0
        issues2: List[str] = []
        if isinstance(three_screen_degrade_info, dict):
            dd["three_screen"] = dict(three_screen_degrade_info)
            try:
                stage2 = max(stage2, int(three_screen_degrade_info.get("stage") or 0))
            except Exception:
                pass
            try:
                ti = three_screen_degrade_info.get("issues") if isinstance(three_screen_degrade_info.get("issues"), list) else []
                issues2.extend([str(x) for x in ti if str(x or "").strip()])
            except Exception:
                pass
        if isinstance(monitor_degrade_info, dict):
            dd["monitor_center"] = dict(monitor_degrade_info)
            try:
                stage2 = max(stage2, int(monitor_degrade_info.get("stage") or 0))
            except Exception:
                pass
            try:
                mi = monitor_degrade_info.get("issues") if isinstance(monitor_degrade_info.get("issues"), list) else []
                issues2.extend([str(x) for x in mi if str(x or "").strip()])
            except Exception:
                pass
        if dd:
            dd["stage"] = int(stage2)
            dd["issues"] = [str(x) for x in issues2 if str(x or "").strip()][:20]
            degradation_out = dd
    except Exception:
        degradation_out = None

    if side not in ("long", "short"):
        return {"ok": False, "error": "invalid_side"}, 400
    if not pair:
        return {"ok": False, "error": "missing_pair"}, 400

    is_addon = False
    base_order_id = None
    base_event_id = None
    prev_notional_usdc = 0.0
    prev_entry_count = 0

    arena_choice = None
    arena_explore = False
    arena_evt: Dict[str, Any] = None
    committee_details = None
    use_rule_vote = bool(str(strategy_id or "") == "ThreeScreen") and (not bool(three_screen_use_ml_vote))
    if bool(use_rule_vote):
        arena_choice = "__rule__"
        arena_explore = False
        p = 0.0
        try:
            if str(side).lower().strip() == "long":
                p = float(features.get("p_enter_long") or strategy_features.get("p_enter_long") or 0.0)
            elif str(side).lower().strip() == "short":
                p = float(features.get("p_enter_short") or strategy_features.get("p_enter_short") or 0.0)
        except Exception:
            p = 0.0
        if not math.isfinite(float(p)):
            p = 0.0
        p = float(_clip(float(p), 0.0, 1.0))
        pc = float(p)
        committee_details = {"RULE": {"p": float(p), "pc": float(pc), "vote": ("agree" if float(pc) >= float(thr) else "veto")}}
    elif _arena_enabled():
        _arena_init_if_needed(now_ms=now_ms)
        if isinstance(evt, dict) and isinstance(evt.get("arena"), dict):
            arena_evt = evt.get("arena")
            try:
                if isinstance(arena_evt, dict):
                    arena_evt["group_id"] = group_id
                    arena_evt["strategy_id"] = strategy_id
                    if bool(CONFIG.get("elastic_gating_enabled", False)):
                        g0 = str(group_id or "global")
                        em = ((ELASTIC_STATE.get("by_group") or {}).get(g0) or {})
                        if isinstance(em, dict) and em:
                            arena_evt["elastic"] = dict(em)
            except Exception:
                pass
        else:
            try:
                tss = int(ts_for_feat)
            except Exception:
                tss = int(now_ms)
            arena_evt = _arena_snapshot_for_event(pair=str(pair), side=str(side), tag=tag, ts=int(tss), features=features, regime=regime, thr=float(thr), feature_set_id=feature_set_id)
