    def _settle_owner_hint(oid_s: str) -> Optional[str]:
        if not oid_s:
            return None
        rec = ab_settle_by_oid.get(oid_s)
        if not isinstance(rec, dict):
            return None
        nb = rec.get("notional_by_owner")
        if not isinstance(nb, dict):
            nb = {}
        scores: List[Tuple[float, str]] = []
        for k in ("strategy", "quant", "carry", "three_screen"):
            try:
                v = float(nb.get(k, 0.0) or 0.0)
            except Exception:
                v = 0.0
            scores.append((abs(float(v)), str(k)))
        scores.sort(reverse=True, key=lambda x: float(x[0]))
        if not scores:
            return None
        best_v, best_k = scores[0]
        second_v = (scores[1][0] if len(scores) > 1 else 0.0)
        if best_v <= 0.0:
            return None
        if float(second_v) > 0.0:
            return None
        return (best_k if best_k in ("strategy", "quant", "carry", "three_screen") else None)

