@app.route("/exit/open_positions", methods=["GET"])
def exit_open_positions():
    now_ms = _now_ms()
    out = []
    ops = [
        ("strategy", TRACKER_STATE.get("open_positions") or {}),
        ("carry", TRACKER_STATE.get("carry_open_positions") or {}),
        ("quant", TRACKER_STATE.get("quant_open_positions") or {}),
        ("three_screen", TRACKER_STATE.get("three_screen_open_positions") or {}),
    ]
    for sys_name, op in ops:
        for pair, v in (op.items() if isinstance(op, dict) else []):
            try:
                side = str((v or {}).get("side") or "").lower() or None
            except Exception:
                side = None
            try:
                notional = _to_float((v or {}).get("notional_usdc", 0.0))
            except Exception:
                notional = 0.0
            try:
                ts = int((v or {}).get("ts") or 0)
            except Exception:
                ts = 0
            oid0 = (None if (v or {}).get("order_id") is None else str((v or {}).get("order_id")))
            linked = any([(v or {}).get("strategy_id") is not None, (v or {}).get("event_id") is not None, oid0 is not None])
            order_present = (oid0 is not None) and isinstance(ORDERS.get(str(oid0)), dict)
            try:
                sys_id = _system_from_strategy_id((v or {}).get("system_id") or sys_name)
            except Exception:
                sys_id = str(sys_name)
            out.append({
                "pair": str(pair),
                "side": side,
                "notional_usdc": float(notional),
                "ts": int(ts),
                "age_ms": int(now_ms - ts) if ts > 0 else 0,
                "exit_owner": (None if (v or {}).get("exit_owner") is None else str((v or {}).get("exit_owner"))),
                "last_observe_event_id": (None if (v or {}).get("last_observe_event_id") is None else str((v or {}).get("last_observe_event_id"))),
                "last_observe_ts": (None if (v or {}).get("last_observe_ts") is None else int((v or {}).get("last_observe_ts") or 0)),
                "origin": (None if (v or {}).get("origin") is None else str((v or {}).get("origin"))),
                "strategy_id": (None if (v or {}).get("strategy_id") is None else str((v or {}).get("strategy_id"))),
                "event_id": (None if (v or {}).get("event_id") is None else str((v or {}).get("event_id"))),
                "order_id": oid0,
                "linked": bool(linked),
                "order_present": bool(order_present),
                "system_id": str(sys_id),
            })
    return jsonify({"ok": True, "ts": int(now_ms), "positions": out})


@app.route("/exit/features/latest", methods=["GET"])
def exit_features_latest():
    now_ms = _now_ms()
    pairs_q = request.args.get("pairs")
    include_macro_q = request.args.get("include_macro")

    include_macro = False
    if include_macro_q is not None:
        v = str(include_macro_q).strip().lower()
        include_macro = v in ("1", "true", "yes", "on")

    pairs: List[str] = []
    if pairs_q is not None and str(pairs_q).strip():
        raw = [x.strip() for x in str(pairs_q).split(",")]
        pairs = [x for x in raw if x]
    else:
        seen = set()
        for k in _tracker_open_positions_all_keys():
            ks = str(k or "").strip()
            if not ks or ks in seen:
                continue
            seen.add(ks)
            pairs.append(ks)

    items: List[Dict[str, Any]] = []

    macro_flow_snap: Optional[Dict[str, Any]] = None
    macro_btc_trend_snap: Optional[Dict[str, Any]] = None
    macro_eth_trend_snap: Optional[Dict[str, Any]] = None
    macro_btc_energy_snap: Optional[Dict[str, Any]] = None
    macro_eth_energy_snap: Optional[Dict[str, Any]] = None

    if include_macro:
        try:
            macro_flow_snap = _macro_flow_at(int(now_ms))
        except Exception:
            macro_flow_snap = {
                "rs_btc_vs_mkt": 0.0,
                "rs_eth_vs_mkt": 0.0,
                "rs_btc_vs_eth": 0.0,
                "macro_flow_dir": 0,
                "macro_flow_chg_dir": 0,
                "macro_flow_chg_speed": 0.0,
            }
        try:
            macro_btc_trend_snap = _macro_trend_at(int(now_ms), coin="BTC")
        except Exception:
            macro_btc_trend_snap = None
        try:
            macro_eth_trend_snap = _macro_trend_at(int(now_ms), coin="ETH")
        except Exception:
            macro_eth_trend_snap = None
        try:
            macro_btc_energy_snap = _macro_energy_at(int(now_ms), coin="BTC")
        except Exception:
            macro_btc_energy_snap = None
        try:
            macro_eth_energy_snap = _macro_energy_at(int(now_ms), coin="ETH")
        except Exception:
            macro_eth_energy_snap = None

    ops = [
        ("strategy", TRACKER_STATE.get("open_positions") or {}),
        ("carry", TRACKER_STATE.get("carry_open_positions") or {}),
        ("quant", TRACKER_STATE.get("quant_open_positions") or {}),
    ]
    for pair in pairs:
        pos = None
        sys_id = None
        for sys_name, op in ops:
            if not isinstance(op, dict) or (pair not in op):
                continue
            pos0 = op.get(pair)
            if isinstance(pos0, dict):
                pos = pos0
                sys_id = sys_name
                break
        if not isinstance(pos, dict):
            pos = {}
        else:
            pos = dict(pos)
        if pos.get("system_id") is None and sys_id is not None:
            pos["system_id"] = str(sys_id)
        feats = _exit_features_for_position(pair=str(pair), pos=pos)
        if not isinstance(feats, dict):
            feats = {}

        try:
            side = str((pos or {}).get("side") or "long")
        except Exception:
            side = "long"

        coin = _hl_coin_from_pair(str(pair))
        extra = _exit_pair_exit_features(coin=str(coin), now_ms=int(now_ms))
        if isinstance(extra, dict) and extra:
            for k, v in extra.items():
                if k not in feats:
                    feats[k] = v

        if include_macro:
            if isinstance(macro_flow_snap, dict):
                for k in ("rs_btc_vs_mkt", "rs_eth_vs_mkt", "rs_btc_vs_eth"):
                    kk = "macro_" + k
                    if kk not in feats:
                        try:
                            feats[kk] = float(macro_flow_snap.get(k) or 0.0)
                        except Exception:
                            feats[kk] = 0.0
                for k in ("macro_flow_dir", "macro_flow_chg_dir"):
                    if k not in feats:
                        try:
                            feats[k] = int(macro_flow_snap.get(k) or 0)
                        except Exception:
                            feats[k] = 0
                if "macro_flow_chg_speed" not in feats:
                    try:
                        feats["macro_flow_chg_speed"] = float(macro_flow_snap.get("macro_flow_chg_speed") or 0.0)
                    except Exception:
                        feats["macro_flow_chg_speed"] = 0.0

            if isinstance(macro_btc_trend_snap, dict):
                for k in (
                    "trend_w_dir",
                    "trend_d_dir",
                    "trend_shape_5",
                    "trend_w_slope",
                    "trend_d_slope",
                    "trend_rate_change_dw",
                    "time_regime",
                ):
                    feats["macro_btc_" + k] = macro_btc_trend_snap.get(k)

                if "macro_trend_w_dir" not in feats:
                    feats["macro_trend_w_dir"] = macro_btc_trend_snap.get("trend_w_dir")
                if "macro_trend_d_dir" not in feats:
                    feats["macro_trend_d_dir"] = macro_btc_trend_snap.get("trend_d_dir")
                if "macro_trend_shape_5" not in feats:
                    feats["macro_trend_shape_5"] = macro_btc_trend_snap.get("trend_shape_5")
                if "macro_trend_rate_change_dw" not in feats:
                    feats["macro_trend_rate_change_dw"] = macro_btc_trend_snap.get("trend_rate_change_dw")

            if isinstance(macro_eth_trend_snap, dict):
                for k in (
                    "trend_w_dir",
                    "trend_d_dir",
                    "trend_shape_5",
                    "trend_w_slope",
                    "trend_d_slope",
                    "trend_rate_change_dw",
                    "time_regime",
                ):
                    feats["macro_eth_" + k] = macro_eth_trend_snap.get(k)

            if isinstance(macro_btc_energy_snap, dict):
                for k in (
                    "atr_pct",
                    "risk_baseline",
                    "mom_dir",
                    "mom_chg_dir",
                    "mom_chg_speed",
                    "vol_dir",
                    "vol_chg_dir",
                    "vol_chg_speed",
                    "pot_dir",
                    "pot_chg_dir",
                    "pot_chg_speed",
                ):
                    feats["macro_btc_" + k] = macro_btc_energy_snap.get(k)

                if "macro_atr_pct" not in feats:
                    feats["macro_atr_pct"] = macro_btc_energy_snap.get("atr_pct")
                if "macro_mom_dir" not in feats:
                    feats["macro_mom_dir"] = macro_btc_energy_snap.get("mom_dir")
                if "macro_mom_chg_dir" not in feats:
                    feats["macro_mom_chg_dir"] = macro_btc_energy_snap.get("mom_chg_dir")

            if isinstance(macro_eth_energy_snap, dict):
                for k in (
                    "atr_pct",
                    "risk_baseline",
                    "mom_dir",
                    "mom_chg_dir",
                    "mom_chg_speed",
                    "vol_dir",
                    "vol_chg_dir",
                    "vol_chg_speed",
                    "pot_dir",
                    "pot_chg_dir",
                    "pot_chg_speed",
                ):
                    feats["macro_eth_" + k] = macro_eth_energy_snap.get(k)

            score_long, p_long = _exit_mrd_score_from_macro(feats, side="long")
            score_side, p_side = _exit_mrd_score_from_macro(feats, side=side)
            dir0 = "long" if float(score_long) >= 0.0 else "short"
            p_dir = float(p_long) if dir0 == "long" else float(1.0 - float(p_long))
            feats["macro_mrd_score"] = float(score_side)
            feats["macro_p_mrd"] = float(p_side)
            feats["macro_mrd_score_long"] = float(score_long)
            feats["macro_p_mrd_long"] = float(p_long)
            feats["macro_mrd_dir"] = str(dir0)
            feats["macro_p_mrd_dir"] = float(_clip(float(p_dir), 0.0, 1.0))

        evt_id = (None if pos.get("last_observe_event_id") is None else str(pos.get("last_observe_event_id") or ""))
        if evt_id is not None:
            evt_id = evt_id.strip() or None

        try:
            d1_all = _exit_l1_l2_decision(pair=str(pair), pos=pos, now_ms=int(now_ms), allow_disabled=True, return_hold=True)
        except Exception:
            d1_all = None

        dec = d1_all if isinstance(d1_all, dict) else (pos.get("exit_l1_last_decision") if isinstance(pos.get("exit_l1_last_decision"), dict) else None)
        if isinstance(dec, dict):
            try:
                pos["exit_l1_last_decision"] = dict(dec)
                pos["exit_l1_last_decision_ts"] = int(now_ms)
            except Exception:
                pass

        hr = None
        hv = None
        if isinstance(d1_all, dict):
            try:
                hr = float(d1_all.get("hold_risk")) if d1_all.get("hold_risk") is not None else None
            except Exception:
                hr = None
            try:
                hv = float(d1_all.get("hold_value")) if d1_all.get("hold_value") is not None else None
            except Exception:
                hv = None
        if hr is None:
            try:
                hr = float(pos.get("hold_risk")) if pos.get("hold_risk") is not None else None
            except Exception:
                hr = None
        if hv is None:
            try:
                hv = float(pos.get("hold_value")) if pos.get("hold_value") is not None else None
            except Exception:
                hv = None

        items.append({
            "pair": str(pair),
            "side": str(side or "long"),
            "exit_owner": (None if (pos or {}).get("exit_owner") is None else str((pos or {}).get("exit_owner"))),
            "ts": int(now_ms),
            "event_id": evt_id,
            "hold_risk": hr,
            "hold_value": hv,
            "l1_decision": dec,
            "features": feats,
        })

    out: Dict[str, Any] = {"ok": True, "ts": int(now_ms), "items": items}
    if include_macro:
        out["macro_flow"] = macro_flow_snap
        out["macro_btc_trend"] = macro_btc_trend_snap
        out["macro_eth_trend"] = macro_eth_trend_snap
        out["macro_btc_energy"] = macro_btc_energy_snap
        out["macro_eth_energy"] = macro_eth_energy_snap
    return jsonify(_json_sanitize(out))


@app.route("/exit/dataset/export", methods=["GET"])
def exit_dataset_export():
    now_ms = _now_ms()
    pair_q = request.args.get("pair")
    start_q = request.args.get("start_ms")
    end_q = request.args.get("end_ms")
    limit_q = request.args.get("limit")
    interval_q = request.args.get("interval")
    horizon_q = request.args.get("horizon")
    dd_k_q = request.args.get("dd_k")
    include_features_q = request.args.get("include_features")

    pair = None
    if pair_q is not None and str(pair_q).strip():
        pair = str(pair_q).strip()

    start_ms = None
    if start_q is not None and str(start_q).strip():
        try:
            start_ms = int(float(str(start_q).strip()))
        except Exception:
            start_ms = None
    end_ms = None
    if end_q is not None and str(end_q).strip():
        try:
            end_ms = int(float(str(end_q).strip()))
        except Exception:
            end_ms = None

    try:
        limit = int(limit_q or 2000)
    except Exception:
        limit = 2000
    limit = max(1, min(20000, int(limit)))

    interval = str(interval_q or "5m").strip().lower() or "5m"
    try:
        interval_ms = _hl_interval_to_ms(interval)
    except Exception:
        interval = "5m"
        interval_ms = _hl_interval_to_ms(interval)

    try:
        horizon = int(horizon_q or 12)
    except Exception:
        horizon = 12
    horizon = max(1, min(500, int(horizon)))

    try:
        dd_k = float(dd_k_q if dd_k_q is not None else (CONFIG.get("exit_label_dd_k", 0.03) if isinstance(CONFIG, dict) else 0.03))
    except Exception:
        dd_k = 0.03
    dd_k = float(_clip(float(dd_k), 0.0, 0.50))

    include_features = True
    if include_features_q is not None:
        v = str(include_features_q).strip().lower()
        include_features = v in ("1", "true", "yes", "on")

    events = _exit_dataset_collect_observe_events(pair=pair, start_ms=start_ms, end_ms=end_ms, limit=int(limit))
    if not events:
        return jsonify({"ok": True, "ts": int(now_ms), "interval": str(interval), "horizon": int(horizon), "dd_k": float(dd_k), "items": []})

    by_coin: Dict[str, Dict[str, Any]] = {}
    for e in events:
        p0 = str(e.get("pair") or "").strip()
        if not p0:
            continue
        coin = _hl_coin_from_pair(p0)
        try:
            ts = int(e.get("ts") or 0)
        except Exception:
            ts = 0
        if ts <= 0:
            continue
        r = by_coin.get(str(coin))
        if not isinstance(r, dict):
            r = {"min": ts, "max": ts}
            by_coin[str(coin)] = r
        r["min"] = int(min(int(r.get("min") or ts), int(ts)))
        r["max"] = int(max(int(r.get("max") or ts), int(ts)))

    candle_idx_by_coin: Dict[str, Dict[str, Any]] = {}
    pad = int(interval_ms)
    extra = int(interval_ms) * int(horizon + 2)
    for coin, r in by_coin.items():
        try:
            t0 = int(r.get("min") or 0)
            t1 = int(r.get("max") or 0)
        except Exception:
            continue
        if t0 <= 0 or t1 <= 0:
            continue
        start_fetch = int(max(0, int(t0) - int(pad)))
        end_fetch = int(t1 + int(extra))
        try:
            rows = _exit_fetch_ohlcv_rows(pair_or_coin=str(coin), interval=str(interval), start_ms=int(start_fetch), end_ms=int(end_fetch))
        except Exception:
            rows = []
        idx = _exit_dataset_build_candle_index(rows)
        if isinstance(idx, dict):
            candle_idx_by_coin[str(coin)] = idx

    items: List[Dict[str, Any]] = []
    for e in events:
        pair0 = str(e.get("pair") or "").strip()
        if not pair0:
            continue
        coin = _hl_coin_from_pair(pair0)
        idx = candle_idx_by_coin.get(str(coin))
        if not isinstance(idx, dict):
            continue
        lab = _exit_dataset_label_event(evt=e, candles=idx, horizon_bars=int(horizon), dd_k=float(dd_k))
        if not isinstance(lab, dict):
            continue
        out = {
            "event_id": str(e.get("id") or ""),
            "ts": int(e.get("ts") or 0),
            "pair": str(pair0),
            "side": (None if e.get("side") is None else str(e.get("side"))),
            "labels": lab,
        }
        if include_features:
            out["features"] = (dict(e.get("features") or {}) if isinstance(e.get("features"), dict) else {})
        items.append(out)

    return jsonify(_json_sanitize({"ok": True, "ts": int(now_ms), "interval": str(interval), "horizon": int(horizon), "dd_k": float(dd_k), "items": items}))


@app.route("/exit/dataset/generate", methods=["POST"])
def exit_dataset_generate():
    now_ms = _now_ms()
    data = request.get_json(force=True) or {}

    pair = str(data.get("pair") or "").strip()
    if not pair:
        return jsonify({"ok": False, "error": "missing_pair", "ts": int(now_ms)}), 400

    interval = str(data.get("interval") or "5m").strip().lower() or "5m"

    try:
        start_ms = int(float(data.get("start_ms") or 0))
    except Exception:
        start_ms = 0
    try:
        end_ms = int(float(data.get("end_ms") or 0))
    except Exception:
        end_ms = 0

    try:
        stride_bars = int(data.get("stride_bars") or 3)
    except Exception:
        stride_bars = 3
    try:
        max_events = int(data.get("max_events") or 5000)
    except Exception:
        max_events = 5000

    archive = bool(data.get("archive", True))

    strategy_id = (None if data.get("strategy_id") is None else str(data.get("strategy_id") or "").strip())
    if strategy_id == "":
        strategy_id = None

    res = _exit_dataset_generate_observe_events_from_ohlcv(
        pair=str(pair),
        interval=str(interval),
        start_ms=int(start_ms),
        end_ms=int(end_ms),
        stride_bars=int(stride_bars),
        max_events=int(max_events),
        archive=bool(archive),
        strategy_id=strategy_id,
    )
    code = 200 if bool(res.get("ok")) else 400
    return jsonify(_json_sanitize(res)), code


@app.route("/exit/ml/train", methods=["POST"])
def exit_ml_train_route():
    data = request.get_json(force=True) or {}
    task = str(data.get("task") or "tail").strip().lower() or "tail"
    family = str(data.get("family") or "lr").strip().lower() or "lr"
    pair = (None if data.get("pair") is None else str(data.get("pair") or "").strip())
    if pair == "":
        pair = None

    start_ms = None
    if data.get("start_ms") is not None:
        try:
            start_ms = int(float(data.get("start_ms")))
        except Exception:
            start_ms = None
    end_ms = None
    if data.get("end_ms") is not None:
        try:
            end_ms = int(float(data.get("end_ms")))
        except Exception:
            end_ms = None

    try:
        limit = int(data.get("limit") or 2000)
    except Exception:
        limit = 2000
    limit = max(1, min(20000, int(limit)))

    interval = str(data.get("interval") or "5m").strip().lower() or "5m"
    try:
        horizon = int(data.get("horizon") or 12)
    except Exception:
        horizon = 12
    horizon = max(1, min(500, int(horizon)))

    try:
        dd_k = float(data.get("dd_k") if data.get("dd_k") is not None else (CONFIG.get("exit_label_dd_k", 0.03) if isinstance(CONFIG, dict) else 0.03))
    except Exception:
        dd_k = 0.03
    dd_k = float(_clip(float(dd_k), 0.0, 0.50))

    params = data.get("params") if isinstance(data.get("params"), dict) else None
    save = bool(data.get("save", True))

    output_charts = bool(data.get("output_charts", False))

    if str(task) == "gate":
        res = _exit_gate_train(
            pair=pair,
            start_ms=start_ms,
            end_ms=end_ms,
            limit=int(limit),
            interval=str(interval),
            horizon=int(horizon),
            dd_k=float(dd_k),
            params=params,
            save=bool(save),
            output_charts=bool(output_charts),
        )
        _exit_monitor_record("gate", res)
        code = 200 if bool(res.get("ok")) else 409
        return jsonify(_json_sanitize(res)), code

    if str(task) == "feedback":
        res = _exit_feedback_train(
            pair=pair,
            start_ms=start_ms,
            end_ms=end_ms,
            limit=int(limit),
            interval=str(interval),
            horizon=int(horizon),
            dd_k=float(dd_k),
            params=params,
            save=bool(save),
            output_charts=bool(output_charts),
        )
        _exit_monitor_record("feedback", res)
        code = 200 if bool(res.get("ok")) else 409
        return jsonify(_json_sanitize(res)), code

    res = _exit_ml_train(
        task=str(task),
        family=str(family),
        pair=pair,
        start_ms=start_ms,
        end_ms=end_ms,
        limit=int(limit),
        interval=str(interval),
        horizon=int(horizon),
        dd_k=float(dd_k),
        params=params,
        save=bool(save),
        output_charts=bool(output_charts),
    )
    _exit_monitor_record(str(task), res)
    code = 200 if bool(res.get("ok")) else 409
    return jsonify(_json_sanitize(res)), code


@app.route("/exit/ml/predict", methods=["POST"])
def exit_ml_predict_route():
    data = request.get_json(force=True) or {}
    task = str(data.get("task") or "tail").strip().lower() or "tail"
    feats0 = data.get("features")
    feats = feats0 if isinstance(feats0, dict) else {}
    hist0 = data.get("history")
    hist: List[Dict[str, Any]] = []
    if isinstance(hist0, list):
        for it in hist0:
            if not isinstance(it, dict):
                continue
            fs = it.get("features") if isinstance(it.get("features"), dict) else it
            if isinstance(fs, dict) and fs:
                hist.append(dict(fs))
    if str(task) == "gate":
        m = _exit_gate_get_model()
        if m is None:
            return jsonify({"ok": False, "error": "model_not_loaded", "task": "gate"}), 404
        try:
            p_tail = (None if feats.get("p_tail") is None else float(feats.get("p_tail")))
        except Exception:
            p_tail = None
        try:
            p_move = (None if feats.get("p_move") is None else float(feats.get("p_move")))
        except Exception:
            p_move = None
        try:
            model_conf = float(feats.get("model_conf") or 0.0)
        except Exception:
            model_conf = 0.0
        try:
            pnl_pct = float(feats.get("pnl_pct") or 0.0)
        except Exception:
            pnl_pct = 0.0
        try:
            mfe = float(feats.get("mfe") or 0.0)
        except Exception:
            mfe = 0.0
        try:
            dd = float(feats.get("dd") or 0.0)
        except Exception:
            dd = 0.0
        try:
            pos_age_s = float(feats.get("pos_age_s") or 0.0)
        except Exception:
            pos_age_s = 0.0
        time_regime = str(feats.get("time_regime") or "")
        trend_shape_5 = str(feats.get("trend_shape_5") or "")
        action_context = str(feats.get("action_context") or feats.get("action") or "")
        hold_risk = None
        if feats.get("hold_risk") is not None:
            try:
                hold_risk = float(feats.get("hold_risk"))
            except Exception:
                hold_risk = None
        reduce_frac = None
        if feats.get("reduce_frac") is not None:
            try:
                reduce_frac = float(feats.get("reduce_frac"))
            except Exception:
                reduce_frac = None
        feats_gate = _exit_gate_build_features(
            p_tail=p_tail,
            p_move=p_move,
            model_conf=float(model_conf),
            pnl_pct=float(pnl_pct),
            mfe=float(mfe),
            dd=float(dd),
            pos_age_s=float(pos_age_s),
            time_regime=str(time_regime),
            trend_shape_5=str(trend_shape_5),
            action_context=str(action_context),
            hold_risk=hold_risk,
            reduce_frac=reduce_frac,
        )
        if not feats_gate:
            return jsonify({"ok": False, "error": "empty_features"}), 400
        p = _exit_gate_predict_proba(m, feats_gate)
        conf = float(_clip(abs(float(p) - 0.5) * 2.0, 0.0, 1.0))
        return jsonify({"ok": True, "task": "gate", "p": float(p), "conf": float(conf)})

    if str(task) == "feedback":
        m = _exit_feedback_get_model()
        if m is None:
            return jsonify({"ok": False, "error": "model_not_loaded", "task": "feedback"}), 404
        p_raw = None
        if feats.get("p_raw") is not None:
            try:
                p_raw = float(feats.get("p_raw"))
            except Exception:
                p_raw = None
        if p_raw is None and feats.get("hold_risk") is not None:
            try:
                p_raw = float(feats.get("hold_risk"))
            except Exception:
                p_raw = None
        if p_raw is None and feats.get("p_tail") is not None:
            try:
                p_raw = float(feats.get("p_tail"))
            except Exception:
                p_raw = None
        if p_raw is None:
            p_raw = 0.5
        try:
            model_conf = float(feats.get("model_conf") or 0.0)
        except Exception:
            model_conf = 0.0
        try:
            pnl_pct = float(feats.get("pnl_pct") or 0.0)
        except Exception:
            pnl_pct = 0.0
        try:
            dd = float(feats.get("dd") or 0.0)
        except Exception:
            dd = 0.0
        time_regime = str(feats.get("time_regime") or "")
        trend_shape_5 = str(feats.get("trend_shape_5") or "")
        feats_fb = _exit_feedback_build_features(
            p_raw=float(p_raw),
            model_conf=float(model_conf),
            dd=float(dd),
            pnl_pct=float(pnl_pct),
            time_regime=str(time_regime),
            trend_shape_5=str(trend_shape_5),
        )
        if not feats_fb:
            return jsonify({"ok": False, "error": "empty_features"}), 400
        p = float(_clip(float(_predict_with_model(m, feats_fb)), 0.0, 1.0))
        conf = float(_clip(abs(float(p) - 0.5) * 2.0, 0.0, 1.0))
        return jsonify({"ok": True, "task": "feedback", "p": float(p), "conf": float(conf)})

    feats_ml = _exit_seq_transform_from_history(hist) if hist else _exit_ml_transform_features(feats)
    m = _exit_ml_get_model(str(task))
    if m is None:
        return jsonify({"ok": False, "error": "model_not_loaded", "task": str(task)}), 404
    if not feats_ml:
        return jsonify({"ok": False, "error": "empty_features"}), 400
    try:
        p = float(_clip(float(_predict_with_model(m, feats_ml)), 0.0, 1.0))
    except Exception:
        p = 0.5
    conf = float(_clip(abs(float(p) - 0.5) * 2.0, 0.0, 1.0))
    return jsonify({"ok": True, "task": str(task), "p": float(p), "conf": float(conf)})


@app.route("/exit/ml/monitor", methods=["GET"])
def exit_ml_monitor_route():
    now_ms = _now_ms()
    include_charts = False
    try:
        include_charts = bool(int(request.args.get("include_charts") or 0))
    except Exception:
        include_charts = False

    auto_eval = False
    try:
        auto_eval = bool(int(request.args.get("auto_eval") or 0))
    except Exception:
        auto_eval = False

    try:
        limit = int(request.args.get("limit") or 200)
    except Exception:
        limit = 200
    limit = max(50, min(2000, int(limit)))

    interval = str(request.args.get("interval") or "5m").strip().lower() or "5m"
    try:
        horizon = int(request.args.get("horizon") or 12)
    except Exception:
        horizon = 12
    horizon = max(1, min(500, int(horizon)))

    try:
        dd_k = float(request.args.get("dd_k") or (CONFIG.get("exit_label_dd_k", 0.03) if isinstance(CONFIG, dict) else 0.03))
    except Exception:
        dd_k = 0.03
    dd_k = float(_clip(float(dd_k), 0.0, 0.50))

    def _eval_and_cache(t: str) -> None:
        mobj = None
        name = None
        family = ""
        if t in ("tail", "move"):
            mobj = _exit_ml_get_model(t)
            try:
                name = str(CONFIG.get(f"exit_ml_{t}_model_name") or "").strip()
            except Exception:
                name = None
        elif t == "gate":
            mobj = _exit_gate_get_model()
            try:
                name = str(CONFIG.get("exit_gate_model_name") or "").strip()
            except Exception:
                name = None
        else:
            mobj = _exit_feedback_get_model()
            try:
                name = str(CONFIG.get("exit_feedback_model_name") or "").strip()
            except Exception:
                name = None

        if isinstance(mobj, dict):
            family = str(mobj.get("family") or "")

        if mobj is None:
            return

        built = None
        if t in ("tail", "move"):
            built = _exit_ml_build_samples(pair=None, start_ms=None, end_ms=None, limit=int(limit), interval=str(interval), horizon=int(horizon), dd_k=float(dd_k), task=str(t))
        elif t == "gate":
            built = _exit_gate_build_samples(pair=None, start_ms=None, end_ms=None, limit=int(limit), interval=str(interval), horizon=int(horizon), dd_k=float(dd_k))
        else:
            built = _exit_feedback_build_samples(pair=None, start_ms=None, end_ms=None, limit=int(limit), interval=str(interval), horizon=int(horizon), dd_k=float(dd_k))

        if not isinstance(built, dict) or not bool(built.get("ok")):
            try:
                built_err = str((built or {}).get("error") or "build_failed") if isinstance(built, dict) else "build_failed"
            except Exception:
                built_err = "build_failed"
            _exit_monitor_record(
                str(t),
                {
                    "ok": True,
                    "ts": int(_now_ms()),
                    "task": str(t),
                    "family": str(family),
                    "saved": None,
                    "filename": (None if not name else str(name)),
                    "error": str(built_err),
                    "built": {
                        "interval": (None if not isinstance(built, dict) else built.get("interval")),
                        "horizon": (None if not isinstance(built, dict) else built.get("horizon")),
                        "dd_k": (None if not isinstance(built, dict) else built.get("dd_k")),
                        "n": 0,
                        "skipped": int((built or {}).get("skipped") or 0) if isinstance(built, dict) else 0,
                    },
                    "metrics": {},
                },
            )
            return
        samples0 = built.get("samples")
        samples = samples0 if isinstance(samples0, list) else []
        if not samples:
            _exit_monitor_record(
                str(t),
                {
                    "ok": True,
                    "ts": int(_now_ms()),
                    "task": str(t),
                    "family": str(family),
                    "saved": None,
                    "filename": (None if not name else str(name)),
                    "error": "no_samples",
                    "built": {
                        "interval": built.get("interval"),
                        "horizon": built.get("horizon"),
                        "dd_k": built.get("dd_k"),
                        "n": 0,
                        "skipped": int(built.get("skipped") or 0),
                    },
                    "metrics": {},
                },
            )
            return

        preds: List[float] = []
        labels: List[int] = []
        rets: List[float] = []
        for s in samples:
            if not isinstance(s, dict):
                continue
            fs = s.get("features") if isinstance(s.get("features"), dict) else {}
            try:
                preds.append(float(_predict_with_model(mobj, fs)))
            except Exception:
                preds.append(0.5)
            labels.append(int(s.get("label") or 0))
            meta = s.get("meta") if isinstance(s.get("meta"), dict) else None
            if isinstance(meta, dict):
                if meta.get("ret_h") is not None:
                    try:
                        rets.append(float(meta.get("ret_h") or 0.0))
                    except Exception:
                        rets.append(0.0)
                elif meta.get("gain") is not None:
                    try:
                        rets.append(float(meta.get("gain") or 0.0))
                    except Exception:
                        rets.append(0.0)
                else:
                    rets.append(1.0 if int(s.get("label") or 0) == 1 else -1.0)
            else:
                rets.append(1.0 if int(s.get("label") or 0) == 1 else -1.0)

        metrics = _compute_metrics(preds=preds, labels=labels, returns=rets)
        charts = _training_charts_binary(preds=preds, labels=labels, metrics=metrics, render_png=bool(include_charts))
        keys = []
        if isinstance(mobj, dict) and isinstance(mobj.get("keys"), list):
            keys = list(mobj.get("keys"))

        wf = None
        if str(t) in ("tail", "move") and keys:
            try:
                wf_enabled = bool(CONFIG.get("exit_ml_walkforward_enabled", True))
            except Exception:
                wf_enabled = True
            if bool(wf_enabled):
                try:
                    wf_folds = int(CONFIG.get("exit_ml_walkforward_folds", 5) or 5)
                except Exception:
                    wf_folds = 5
                wf_folds = max(3, min(20, int(wf_folds)))

                interval0 = str(built.get("interval") or interval)
                try:
                    interval_ms = _hl_interval_to_ms(interval0)
                except Exception:
                    interval_ms = _hl_interval_to_ms("5m")

                min_emb_ms = int(max(0, int(horizon)) * int(interval_ms))
                try:
                    emb_ms_cfg = CONFIG.get("exit_ml_walkforward_embargo_ms")
                    emb_ms = int(emb_ms_cfg) if emb_ms_cfg is not None else int(min_emb_ms)
                except Exception:
                    emb_ms = int(min_emb_ms)
                emb_ms = max(int(min_emb_ms), max(0, int(emb_ms)))

                try:
                    wf_cal_method0 = CONFIG.get("exit_ml_walkforward_calibrate_method")
                    wf_cal_method = None if wf_cal_method0 is None else str(wf_cal_method0).strip().lower()
                except Exception:
                    wf_cal_method = None
                if wf_cal_method == "":
                    wf_cal_method = None

                try:
                    stype0 = str(CONFIG.get("exit_ml_scaler_type") or "robust").strip().lower() or "robust"
                except Exception:
                    stype0 = "robust"
                train_params = {"keys": list(keys), "scale": 0.1, "bias": 0.0}
                wf = _exit_ml_walkforward_eval(samples=samples, keys=list(keys), stype=str(stype0), train_params=dict(train_params), folds=int(wf_folds), embargo_ms=int(emb_ms), calibrate_method=wf_cal_method)
                if isinstance(wf, dict) and bool(wf.get("ok")):
                    avg = wf.get("avg") if isinstance(wf.get("avg"), dict) else {}
                    picked = str(avg.get("picked") or "raw")
                    picked_metrics = avg.get(picked) if isinstance(avg.get(picked), dict) else (avg.get("raw") if isinstance(avg.get("raw"), dict) else {})
                    if isinstance(picked_metrics, dict):
                        for k in ("auc", "pr_auc", "ece", "brier", "coverage", "mean_return", "sharpe"):
                            if picked_metrics.get(k) is None:
                                continue
                            try:
                                metrics[f"wf_{k}"] = float(picked_metrics.get(k))
                            except Exception:
                                continue
        res = {
            "ok": True,
            "ts": int(_now_ms()),
            "task": str(t),
            "family": (str(mobj.get("family") or "") if isinstance(mobj, dict) else ""),
            "saved": None,
            "filename": (None if not name else str(name)),
            "keys": keys,
            "built": {
                "interval": built.get("interval"),
                "horizon": built.get("horizon"),
                "dd_k": built.get("dd_k"),
                "n": int(len(samples)),
                "skipped": int(built.get("skipped") or 0),
            },
            "metrics": metrics,
        }
        if isinstance(wf, dict) and wf:
            res["walkforward"] = wf
        if charts:
            res["charts"] = charts
        _exit_monitor_record(str(t), res)

    tasks_raw = str(request.args.get("tasks") or "").strip().lower()
    if tasks_raw:
        req = [x.strip() for x in tasks_raw.split(",") if x.strip()]
        tasks = [x for x in req if x in ("tail", "move", "gate", "feedback")]
        if not tasks:
            tasks = ["tail", "move", "gate", "feedback"]
    else:
        tasks = ["tail", "move", "gate", "feedback"]

    eval_started = False
    if bool(auto_eval):
        try:
            eval_cooldown_ms = int(request.args.get("eval_cooldown_ms") or 5000)
        except Exception:
            eval_cooldown_ms = 5000
        eval_cooldown_ms = max(0, min(120_000, int(eval_cooldown_ms)))

        try:
            with EXIT_MONITOR_EVAL_LOCK:
                running = bool(EXIT_MONITOR_EVAL_STATE.get("running"))
                last_start_ts = int(EXIT_MONITOR_EVAL_STATE.get("last_start_ts") or 0)
                if (not running) and (int(now_ms) - int(last_start_ts) >= int(eval_cooldown_ms)):
                    EXIT_MONITOR_EVAL_STATE["running"] = True
                    EXIT_MONITOR_EVAL_STATE["last_start_ts"] = int(now_ms)
                    EXIT_MONITOR_EVAL_STATE["ts"] = int(now_ms)
                    eval_started = True
        except Exception:
            eval_started = False

        if bool(eval_started):
            def _worker():
                try:
                    for t in tasks:
                        try:
                            _eval_and_cache(str(t))
                        except Exception:
                            pass
                finally:
                    try:
                        with EXIT_MONITOR_EVAL_LOCK:
                            EXIT_MONITOR_EVAL_STATE["running"] = False
                            EXIT_MONITOR_EVAL_STATE["ts"] = int(_now_ms())
                    except Exception:
                        pass

            try:
                threading.Thread(target=_worker, daemon=True).start()
            except Exception:
                try:
                    with EXIT_MONITOR_EVAL_LOCK:
                        EXIT_MONITOR_EVAL_STATE["running"] = False
                        EXIT_MONITOR_EVAL_STATE["ts"] = int(_now_ms())
                except Exception:
                    pass

    out: Dict[str, Any] = {}
    for t in tasks:
        snap = _exit_monitor_snapshot(t, bool(include_charts))
        if isinstance(snap, dict):
            out[str(t)] = snap

    try:
        with EXIT_MONITOR_EVAL_LOCK:
            eval_state = {
                "running": bool(EXIT_MONITOR_EVAL_STATE.get("running")),
                "last_start_ts": int(EXIT_MONITOR_EVAL_STATE.get("last_start_ts") or 0),
                "ts": int(EXIT_MONITOR_EVAL_STATE.get("ts") or 0),
                "started": bool(eval_started),
            }
    except Exception:
        eval_state = {"running": False, "last_start_ts": 0, "ts": 0, "started": bool(eval_started)}

    return jsonify(_json_sanitize({
        "ok": True,
        "ts": int(now_ms),
        "state_ts": int(EXIT_MONITOR_STATE.get("ts") or 0),
        "eval": eval_state,
        "models": out,
    }))

