@app.route("/arena/state", methods=["GET"])
def arena_state():
    now_ms = _now_ms()
    mode = str(request.args.get("mode") or "entry").strip().lower()
    if mode in ("exit", "out"):
        if not _arena_enabled():
            return jsonify({"ok": True, "enabled": False})
        try:
            limit = int(request.args.get("limit") or 0)
        except Exception:
            limit = 0
        if limit <= 0:
            try:
                limit = int(CONFIG.get("gate_history_max", 5000) or 5000)
            except Exception:
                limit = 5000
        limit = max(1, min(5000, int(limit)))

        gh = TRACKER_STATE.get("gate_history")
        if not isinstance(gh, list):
            gh = []
        items = list(gh)[-int(limit):]

        by_model: Dict[str, Dict[str, Any]] = {}
        total_takes = 0
        for it in items:
            if not isinstance(it, dict):
                continue
            mid = str(it.get("mode") or it.get("exit_owner") or "exit").strip() or "exit"
            m = by_model.get(mid)
            if not isinstance(m, dict):
                m = {
                    "id": mid,
                    "name": _arena_display_name(mid),
                    "capital_u": 0.0,
                    "weight": 0.0,
                    "takes": 0,
                    "skips": 0,
                    "wins": 0,
                    "losses": 0,
                    "settled": 0,
                    "revives": 0,
                    "last_settle_ms": 0,
                    "max_dd": 0.0,
                    "win_rate": 0.0,
                    "avg_logloss": 0.0,
                    "turnover": 0.0,
                    "equity": None,
                }
                by_model[mid] = m

            try:
                ts = int(it.get("ts") or 0)
            except Exception:
                ts = 0
            m["last_settle_ms"] = int(max(int(m.get("last_settle_ms") or 0), int(ts)))

            action = str(it.get("action") or "").strip().lower()
            is_take = action in ("close", "reduce")
            if is_take:
                m["takes"] = int(m.get("takes") or 0) + 1
                total_takes += 1
                m["settled"] = int(m.get("settled") or 0) + 1
                try:
                    pu = float(it.get("pnl_u") or 0.0)
                except Exception:
                    pu = 0.0
                m["capital_u"] = float(m.get("capital_u") or 0.0) + float(pu)
                if float(pu) > 0.0:
                    m["wins"] = int(m.get("wins") or 0) + 1
                else:
                    m["losses"] = int(m.get("losses") or 0) + 1
            else:
                m["skips"] = int(m.get("skips") or 0) + 1

        out_models = []
        for mid, m in by_model.items():
            wins = int(m.get("wins") or 0)
            losses = int(m.get("losses") or 0)
            takes = int(m.get("takes") or 0)
            skips = int(m.get("skips") or 0)
            denom_wl = float(wins + losses)
            denom_ts = float(takes + skips)
            m["win_rate"] = float(wins) / denom_wl if denom_wl > 0 else 0.0
            m["turnover"] = float(takes) / denom_ts if denom_ts > 0 else 0.0
            m["weight"] = (float(takes) / float(total_takes)) if total_takes > 0 else 0.0
            out_models.append(m)

        out_models.sort(key=lambda x: float(x.get("weight") or 0.0), reverse=True)
        return jsonify({
            "ok": True,
            "enabled": True,
            "ts": int(now_ms),
            "pool_u": 0.0,
            "diversity": {},
            "models": out_models,
        })

    _arena_init_if_needed(now_ms=now_ms)
    if not _arena_enabled():
        return jsonify({"ok": True, "enabled": False})
    try:
        equity_limit = int(request.args.get("equity_limit") or 0)
    except Exception:
        equity_limit = 0
    if equity_limit <= 0:
        try:
            equity_limit = int(CONFIG.get("arena_state_equity_limit", 200) or 200)
        except Exception:
            equity_limit = 200
    equity_limit = max(0, min(2000, int(equity_limit)))
    st = ARENA_STATE if isinstance(ARENA_STATE, dict) else {}
    models = st.get("models") if isinstance(st.get("models"), dict) else {}
    out_models = []
    for n, v in models.items():
        if not isinstance(v, dict):
            continue
        mid = str(n)
        wins = int(v.get("wins") or 0)
        losses = int(v.get("losses") or 0)
        takes = int(v.get("takes") or 0)
        skips = int(v.get("skips") or 0)
        ll_n = int(v.get("ll_n") or 0)
        ll_sum = float(v.get("ll_sum") or 0.0)
        denom_wl = float(wins + losses)
        denom_ts = float(takes + skips)
        win_rate = float(wins) / denom_wl if denom_wl > 0 else 0.0
        take_rate = float(takes) / denom_ts if denom_ts > 0 else 0.0
        avg_logloss = float(ll_sum) / float(ll_n) if ll_n > 0 else 0.0
        eq_out = None
        if equity_limit > 0:
            eq = v.get("equity")
            if isinstance(eq, list):
                eq_out = list(eq)[-equity_limit:]
        out_models.append({
            "id": mid,
            "name": _arena_display_name(mid),
            "capital_u": float(v.get("capital_u") or 0.0),
            "weight": float(v.get("weight") or 0.0),
            "takes": takes,
            "skips": skips,
            "wins": wins,
            "losses": losses,
            "settled": int(v.get("settled") or 0),
            "revives": int(v.get("revives") or 0),
            "last_settle_ms": int(v.get("last_settle_ms") or 0),
            "max_dd": float(v.get("max_dd") or 0.0),
            "win_rate": float(win_rate),
            "avg_logloss": float(avg_logloss),
            "turnover": float(take_rate),
            "equity": eq_out,
        })
    out_models.sort(key=lambda x: float(x.get("weight") or 0.0), reverse=True)
    return jsonify({
        "ok": True,
        "enabled": True,
        "ts": int(now_ms),
        "pool_u": float(st.get("pool_u") or 0.0),
        "diversity": (st.get("diversity") if isinstance(st.get("diversity"), dict) else {}),
        "models": out_models,
    })


@app.route("/arena/history", methods=["GET"])
def arena_history():
    now_ms = _now_ms()
    mode = str(request.args.get("mode") or "entry").strip().lower()
    if mode in ("exit", "out"):
        if not _arena_enabled():
            return jsonify({"ok": True, "enabled": False, "history": []})
        try:
            limit = int(request.args.get("limit", "50") or 50)
        except Exception:
            limit = 50
        limit = max(1, min(200, int(limit)))
        gh = TRACKER_STATE.get("gate_history")
        if not isinstance(gh, list):
            gh = []
        out = []
        for it in list(gh)[-limit:][::-1]:
            if not isinstance(it, dict):
                continue
            try:
                ts = int(it.get("ts") or 0)
            except Exception:
                ts = 0
            pair = str(it.get("pair") or "")
            side = str(it.get("side") or "")
            action = str(it.get("action") or "")
            winner_id = str(it.get("mode") or it.get("exit_owner") or "exit").strip() or "exit"
            try:
                ret = float(it.get("pnl_pct") or 0.0)
            except Exception:
                ret = 0.0
            out.append({
                "id": f"exit|{ts}|{pair}|{winner_id}|{action}",
                "ts": int(ts),
                "evt_ts": int(ts),
                "pair": pair,
                "side": side,
                "tag": it.get("reason"),
                "ret": float(ret),
                "risk_unit": 1.0,
                "winner_id": winner_id,
                "winner": _arena_display_name(winner_id),
                "chosen_id": None,
                "chosen": None,
                "explore": False,
                "pool_u": 0.0,
            })
        return jsonify({"ok": True, "enabled": True, "ts": int(now_ms), "history": out})

    _arena_init_if_needed(now_ms=now_ms)
    if not _arena_enabled():
        return jsonify({"ok": True, "enabled": False, "history": []})
    try:
        limit = int(request.args.get("limit", "50") or 50)
    except Exception:
        limit = 50
    limit = max(1, min(200, int(limit)))
    hist = ARENA_STATE.get("history") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(hist, list):
        hist = []
    out = []
    for it in list(hist)[-limit:][::-1]:
        if not isinstance(it, dict):
            continue
        rec = dict(it)
        if "winner" in rec and "winner_id" not in rec:
            rec["winner_id"] = rec.get("winner")
            rec["winner"] = _arena_display_name(rec.get("winner"))
        if "chosen" in rec and "chosen_id" not in rec:
            rec["chosen_id"] = rec.get("chosen")
            rec["chosen"] = _arena_display_name(rec.get("chosen"))
        out.append(rec)
    return jsonify({"ok": True, "enabled": True, "ts": int(now_ms), "history": out})


@app.route("/arena/reset", methods=["POST"])
def arena_reset():
    now_ms = _now_ms()
    mode = str(request.args.get("mode") or "entry").strip().lower()
    if mode in ("exit", "out"):
        if not _arena_enabled():
            return jsonify({"ok": False, "error": "arena_disabled"}), 400
        gh = TRACKER_STATE.get("gate_history")
        if isinstance(gh, list):
            gh.clear()
        else:
            TRACKER_STATE["gate_history"] = []
        return jsonify({"ok": True, "enabled": True, "ts": int(now_ms)})
    if not _arena_enabled():
        return jsonify({"ok": False, "error": "arena_disabled"}), 400
    ARENA_STATE.clear()
    ARENA_STATE.update({
        "inited": False,
        "pool_u": 0.0,
        "models": {},
        "history": [],
        "attrib": [],
        "model_calib": {},
        "layer2": {"last_train_ms": 0, "attrib_count": 0, "updated": {}},
        "diversity": {},
        "ts": int(now_ms),
    })
    _arena_init_if_needed(now_ms=now_ms)
    return jsonify({"ok": True, "enabled": True, "ts": int(now_ms)})


@app.route("/arena/models/eligible", methods=["POST"])
def arena_models_eligible():
    now_ms = _now_ms()
    mode = str(request.args.get("mode") or "entry").strip().lower()
    if mode in ("exit", "out"):
        return jsonify({"ok": False, "error": "unsupported_mode"}), 400
    _arena_init_if_needed(now_ms=now_ms)
    if not _arena_enabled():
        return jsonify({"ok": False, "error": "arena_disabled"}), 400

    data = request.get_json(force=True) or {}
    model_id_in = data.get("model_id")
    eligible_in = data.get("eligible")
    if model_id_in is None:
        return jsonify({"ok": False, "error": "missing_model_id"}), 400
    if eligible_in is None:
        return jsonify({"ok": False, "error": "missing_eligible"}), 400

    want = str(model_id_in).strip()
    want_l = want.lower()

    ms = ARENA_STATE.get("models") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(ms, dict):
        return jsonify({"ok": False, "error": "arena_models_unavailable"}), 500

    candidates = [want]
    if want_l in ("nn", "__nn__"):
        candidates = ["__nn__", "nn", want]
    elif want_l in ("rule", "__rule__"):
        candidates = ["__rule__", "rule", want]

    chosen_key = None
    for k in candidates:
        if str(k) in ms:
            chosen_key = str(k)
            break
    if chosen_key is None:
        for k in ms.keys():
            kn = str(k)
            knl = kn.lower().strip()
            if knl == want_l:
                chosen_key = kn
                break
            if knl.strip("_") == want_l.strip("_"):
                chosen_key = kn
                break

    if chosen_key is None:
        return jsonify({"ok": False, "error": "model_not_found", "model_id": want, "known": list(ms.keys())[:50]}), 404

    st = ms.get(str(chosen_key))
    if not isinstance(st, dict):
        return jsonify({"ok": False, "error": "model_state_invalid", "model_id": str(chosen_key)}), 500

    st["eligible"] = bool(eligible_in)
    if bool(eligible_in):
        st["eligible_after_settled"] = 0
        st["eligible_min_takes"] = 0

    try:
        _persist_arena_state_write(now_ms)
    except Exception:
        pass

    return jsonify({
        "ok": True,
        "enabled": True,
        "ts": int(now_ms),
        "model_id": str(chosen_key),
        "eligible": bool(st.get("eligible", True)),
        "eligible_after_settled": int(st.get("eligible_after_settled") or 0),
        "eligible_min_takes": int(st.get("eligible_min_takes") or 0),
    })


@app.route("/arena/attrib", methods=["GET"])
def arena_attrib():
    now_ms = _now_ms()
    _arena_init_if_needed(now_ms=now_ms)
    if not _arena_enabled():
        return jsonify({"ok": True, "enabled": False, "attrib": []})
    try:
        limit = int(request.args.get("limit", "50") or 50)
    except Exception:
        limit = 50
    limit = max(1, min(500, int(limit)))
    only_disagree = str(request.args.get("only_disagree", "0") or "0") in ("1", "true", "True")
    model_id = request.args.get("model")
    pair = request.args.get("pair")
    event_id = request.args.get("event_id")
    try:
        since_ts = int(request.args.get("since_ts") or 0)
    except Exception:
        since_ts = 0
    try:
        until_ts = int(request.args.get("until_ts") or 0)
    except Exception:
        until_ts = 0
    try:
        before_ts = int(request.args.get("before_ts") or 0)
    except Exception:
        before_ts = 0
    include_features = str(request.args.get("include_features", "1") or "1") in ("1", "true", "True")

    items = ARENA_STATE.get("attrib") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(items, list):
        items = []
    out = []
    next_before_ts = None
    for it in reversed(list(items)):
        if not isinstance(it, dict):
            continue
        ts = int(it.get("ts") or 0)
        if before_ts and ts >= int(before_ts):
            continue
        if since_ts and ts < int(since_ts):
            continue
        if until_ts and ts > int(until_ts):
            continue
        if only_disagree and not bool(it.get("disagree", False)):
            continue
        if pair is not None and str(it.get("pair") or "") != str(pair):
            continue
        if event_id is not None and str(it.get("event_id") or "") != str(event_id):
            continue
        if model_id is not None:
            try:
                mm = it.get("models") or {}
            except Exception:
                mm = {}
            if str(model_id) not in (mm if isinstance(mm, dict) else {}):
                continue
        rec = dict(it)
        if not include_features:
            rec.pop("features", None)
        if rec.get("winner_id") is not None:
            rec["winner"] = _arena_display_name(rec.get("winner_id"))
        if rec.get("chosen_id") is not None:
            rec["chosen"] = _arena_display_name(rec.get("chosen_id"))
        out.append(rec)
        if next_before_ts is None:
            next_before_ts = ts
        else:
            next_before_ts = min(int(next_before_ts), ts)
        if len(out) >= int(limit):
            break

    return jsonify({"ok": True, "enabled": True, "ts": int(now_ms), "attrib": out, "next_before_ts": next_before_ts})


@app.route("/arena/attrib_stats", methods=["GET"])
def arena_attrib_stats():
    now_ms = _now_ms()
    _arena_init_if_needed(now_ms=now_ms)
    if not _arena_enabled():
        return jsonify({"ok": True, "enabled": False})

    bucket_by = str(request.args.get("bucket_by") or "strategy_id").lower()
    pair = request.args.get("pair")
    regime = request.args.get("regime")
    strategy_id = request.args.get("strategy_id")
    tag = request.args.get("tag")
    only_disagree = str(request.args.get("only_disagree", "0") or "0") in ("1", "true", "True")
    try:
        since_ts = int(request.args.get("since_ts") or 0)
    except Exception:
        since_ts = 0
    try:
        until_ts = int(request.args.get("until_ts") or 0)
    except Exception:
        until_ts = 0

    items = ARENA_STATE.get("attrib") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(items, list) or not items:
        return jsonify({
            "ok": True,
            "enabled": True,
            "ts": int(now_ms),
            "n": 0,
            "bucket_by": bucket_by,
            "filters": {
                "pair": pair,
                "regime": regime,
                "strategy_id": strategy_id,
                "tag": tag,
                "since_ts": int(since_ts),
                "until_ts": int(until_ts),
                "only_disagree": bool(only_disagree),
            },
            "buckets": {},
        })

    def _pct(xs: List[float], q: float) -> float:
        if not xs:
            return 0.0
        ys = sorted(xs)
        pos = int(round(float(q) * float(len(ys) - 1)))
        pos = max(0, min(len(ys) - 1, pos))
        return float(ys[pos])

    def _bucket_key(it: Dict[str, Any]) -> str:
        if bucket_by == "tag":
            k = it.get("tag")
            return ("" if k is None else str(k))
        if bucket_by == "regime":
            return str(it.get("regime") or "")
        if bucket_by == "pair":
            return str(it.get("pair") or "")
        if bucket_by == "group_id":
            return str(it.get("group_id") or "")
        if bucket_by == "feature_set_id":
            return str(it.get("feature_set_id") or "")
        return str(it.get("strategy_id") or "")

    acc: Dict[str, Dict[str, Any]] = {}
    for it in list(items):
        if not isinstance(it, dict):
            continue
        ts = int(it.get("ts") or 0)
        if since_ts and ts < int(since_ts):
            continue
        if until_ts and ts > int(until_ts):
            continue
        if only_disagree and not bool(it.get("disagree", False)):
            continue
        if pair is not None and str(it.get("pair") or "") != str(pair):
            continue
        if regime is not None and str(it.get("regime") or "") != str(regime):
            continue
        if strategy_id is not None and str(it.get("strategy_id") or "") != str(strategy_id):
            continue
        if tag is not None and str(it.get("tag") or "") != str(tag):
            continue

        try:
            pnl = float(it.get("pnl_net_u") or 0.0)
        except Exception:
            pnl = 0.0
        try:
            ret = float(it.get("ret") or 0.0)
        except Exception:
            ret = 0.0

        ex = it.get("execution_outcome_features") if isinstance(it.get("execution_outcome_features"), dict) else {}
        try:
            hold_ms = int(ex.get("hold_ms") or 0)
        except Exception:
            hold_ms = 0

        bk = _bucket_key(it).strip() or "unknown"
        b = acc.get(bk)
        if not isinstance(b, dict):
            b = {"pnl": [], "ret": [], "ts_pnl": [], "hold_ms": []}
            acc[bk] = b
        b["pnl"].append(float(pnl))
        b["ret"].append(float(ret))
        b["ts_pnl"].append((int(ts), float(pnl)))
        if hold_ms > 0:
            b["hold_ms"].append(int(hold_ms))

    out: Dict[str, Any] = {}
    n_used = 0
    for bk, b in acc.items():
        pnl_xs = b.get("pnl") if isinstance(b.get("pnl"), list) else []
        ret_xs = b.get("ret") if isinstance(b.get("ret"), list) else []
        ts_pnl = b.get("ts_pnl") if isinstance(b.get("ts_pnl"), list) else []
        hold_xs = b.get("hold_ms") if isinstance(b.get("hold_ms"), list) else []
        n = int(len(pnl_xs))
        if n <= 0:
            continue

        n_used += n
        pnl_sum = float(sum(float(x) for x in pnl_xs))
        pnl_mean = pnl_sum / float(n)
        pnl_var = 0.0
        if n >= 2:
            pnl_var = sum((float(x) - float(pnl_mean)) ** 2 for x in pnl_xs) / float(n - 1)
        pnl_std = math.sqrt(max(0.0, float(pnl_var)))

        pos_sum = sum(float(x) for x in pnl_xs if float(x) > 0.0)
        neg_sum = sum(abs(float(x)) for x in pnl_xs if float(x) < 0.0)
        pf = (float(pos_sum) / float(neg_sum)) if float(neg_sum) > 1e-12 else (float("inf") if float(pos_sum) > 1e-12 else 0.0)
        win_n = sum(1 for x in pnl_xs if float(x) > 0.0)
        win_rate = float(win_n) / float(n) if n > 0 else 0.0

        ts_pnl_sorted = sorted([(int(t), float(p)) for t, p in ts_pnl if int(t) > 0], key=lambda x: x[0])
        cum = 0.0
        peak = 0.0
        max_dd_u = 0.0
        for _, p in ts_pnl_sorted:
            cum += float(p)
            if cum > peak:
                peak = float(cum)
            dd_u = float(peak) - float(cum)
            if dd_u > max_dd_u:
                max_dd_u = float(dd_u)
        max_dd_ratio = float(max_dd_u) / float(peak) if float(peak) > 1e-12 else 0.0

        hold_avg_ms = (float(sum(int(x) for x in hold_xs)) / float(len(hold_xs))) if hold_xs else 0.0

        out[str(bk)] = {
            "n": int(n),
            "pnl_sum_u": float(pnl_sum),
            "pnl_mean_u": float(pnl_mean),
            "pnl_std_u": float(pnl_std),
            "pnl_min_u": float(min(float(x) for x in pnl_xs)),
            "pnl_max_u": float(max(float(x) for x in pnl_xs)),
            "pnl_p10_u": float(_pct(pnl_xs, 0.10)),
            "pnl_p25_u": float(_pct(pnl_xs, 0.25)),
            "pnl_p50_u": float(_pct(pnl_xs, 0.50)),
            "pnl_p75_u": float(_pct(pnl_xs, 0.75)),
            "pnl_p90_u": float(_pct(pnl_xs, 0.90)),
            "win_n": int(win_n),
            "win_rate": float(win_rate),
            "profit_factor": (None if pf == float("inf") else float(pf)),
            "profit_factor_inf": True if pf == float("inf") else False,
            "ret_mean": (float(sum(float(x) for x in ret_xs)) / float(len(ret_xs))) if ret_xs else 0.0,
            "max_drawdown_u": float(max_dd_u),
            "max_drawdown_ratio": float(max_dd_ratio),
            "avg_hold_ms": float(hold_avg_ms),
        }

    out_sorted = dict(sorted(out.items(), key=lambda kv: float((kv[1] or {}).get("pnl_sum_u") or 0.0), reverse=True))
    return jsonify({
        "ok": True,
        "enabled": True,
        "ts": int(now_ms),
        "n": int(n_used),
        "bucket_by": bucket_by,
        "filters": {
            "pair": pair,
            "regime": regime,
            "strategy_id": strategy_id,
            "tag": tag,
            "since_ts": int(since_ts),
            "until_ts": int(until_ts),
            "only_disagree": bool(only_disagree),
        },
        "buckets": out_sorted,
    })


@app.route("/arena/fail_stats", methods=["GET"])
def arena_fail_stats():
    now_ms = _now_ms()
    _arena_init_if_needed(now_ms=now_ms)
    if not _arena_enabled():
        return jsonify({"ok": True, "enabled": False})

    model_id = request.args.get("model")
    pair = request.args.get("pair")
    regime = request.args.get("regime")
    bucket_by = str(request.args.get("bucket_by") or "edge").lower()
    only_failed = str(request.args.get("only_failed", "0") or "0") in ("1", "true", "True")
    only_disagree = str(request.args.get("only_disagree", "0") or "0") in ("1", "true", "True")
    try:
        since_ts = int(request.args.get("since_ts") or 0)
    except Exception:
        since_ts = 0
    try:
        until_ts = int(request.args.get("until_ts") or 0)
    except Exception:
        until_ts = 0

    try:
        edge_clip = float(CONFIG.get("arena_edge_clip", 3.0) or 3.0)
    except Exception:
        edge_clip = 3.0
    try:
        edge_step = float(request.args.get("edge_step") or 0.5)
    except Exception:
        edge_step = 0.5
    edge_step = float(max(1e-6, edge_step))
    try:
        pc_step = float(request.args.get("pc_step") or 0.05)
    except Exception:
        pc_step = 0.05
    pc_step = float(max(1e-6, pc_step))

    items = ARENA_STATE.get("attrib") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(items, list) or not items:
        return jsonify({"ok": True, "enabled": True, "ts": int(now_ms), "n": 0, "stats": {}, "buckets": {}})

    model_ids: List[str] = []
    if model_id is not None and str(model_id):
        model_ids = [str(model_id)]
    else:
        try:
            st = ARENA_STATE.get("models") if isinstance(ARENA_STATE, dict) else None
        except Exception:
            st = None
        if isinstance(st, dict):
            model_ids = [str(k) for k in st.keys()]
        else:
            model_ids = []

    def _bucket_key(it: Dict[str, Any], mv: Dict[str, Any]) -> str:
        if bucket_by == "regime":
            return str(it.get("regime") or "")
        if bucket_by == "pair":
            return str(it.get("pair") or "")
        if bucket_by == "pc":
            try:
                pc = float(mv.get("pc") or 0.0)
            except Exception:
                pc = 0.0
            pc = float(_clip(float(pc), 0.0, 1.0))
            lo = math.floor(pc / float(pc_step)) * float(pc_step)
            hi = min(1.0, float(lo) + float(pc_step))
            return f"{lo:.2f}..{hi:.2f}"
        try:
            ed = float(mv.get("edge") or 0.0)
        except Exception:
            ed = 0.0
        ed = float(_clip(float(ed), -float(edge_clip), float(edge_clip)))
        lo = math.floor((ed + float(edge_clip)) / float(edge_step)) * float(edge_step) - float(edge_clip)
        hi = min(float(edge_clip), float(lo) + float(edge_step))
        return f"{lo:.2f}..{hi:.2f}"

    out_stats: Dict[str, Any] = {}
    out_buckets: Dict[str, Any] = {}
    n_used = 0

    for mid in model_ids:
        agg = {
            "n": 0,
            "fail_n": 0,
            "disagree_n": 0,
            "winner_correct_n": 0,
            "avg_edge": 0.0,
            "avg_logloss": 0.0,
        }
        buckets: Dict[str, Dict[str, Any]] = {}

        for it in list(items):
            if not isinstance(it, dict):
                continue
            ts = int(it.get("ts") or 0)
            if since_ts and ts < int(since_ts):
                continue
            if until_ts and ts > int(until_ts):
                continue
            if pair is not None and str(it.get("pair") or "") != str(pair):
                continue
            if regime is not None and str(it.get("regime") or "") != str(regime):
                continue
            if only_disagree and not bool(it.get("disagree", False)):
                continue

            mm = it.get("models")
            if not isinstance(mm, dict):
                continue
            mv = mm.get(str(mid))
            if not isinstance(mv, dict):
                continue

            try:
                y = int(it.get("y") or 0)
            except Exception:
                y = 0
            correct_take = True if int(y) == 1 else False
            try:
                model_take = bool(mv.get("take", False))
            except Exception:
                model_take = False
            model_fail = bool(model_take) != bool(correct_take)
            if only_failed and not bool(model_fail):
                continue

            winner_correct = False
            wid = it.get("winner_id")
            if wid is not None and str(wid) in mm:
                wv = mm.get(str(wid))
                if isinstance(wv, dict):
                    try:
                        winner_take = bool(wv.get("take", False))
                        winner_correct = bool(winner_take) == bool(correct_take)
                    except Exception:
                        winner_correct = False

            try:
                ed = float(mv.get("edge") or 0.0)
            except Exception:
                ed = 0.0
            try:
                ll = float(mv.get("logloss") or 0.0)
            except Exception:
                ll = 0.0

            bk = _bucket_key(it, mv)
            b = buckets.get(bk)
            if not isinstance(b, dict):
                b = {"n": 0, "fail_n": 0, "disagree_n": 0, "winner_correct_n": 0, "avg_edge": 0.0, "avg_logloss": 0.0}
                buckets[bk] = b

            for tgt in (agg, b):
                tgt["n"] = int(tgt.get("n") or 0) + 1
                if model_fail:
                    tgt["fail_n"] = int(tgt.get("fail_n") or 0) + 1
                if bool(it.get("disagree", False)):
                    tgt["disagree_n"] = int(tgt.get("disagree_n") or 0) + 1
                if winner_correct:
                    tgt["winner_correct_n"] = int(tgt.get("winner_correct_n") or 0) + 1
                tgt["avg_edge"] = float(tgt.get("avg_edge") or 0.0) + float(ed)
                tgt["avg_logloss"] = float(tgt.get("avg_logloss") or 0.0) + float(ll)

        if int(agg.get("n") or 0) <= 0:
            continue

        n = float(agg["n"])
        agg["fail_rate"] = float(agg["fail_n"]) / n if n > 0 else 0.0
        agg["disagree_rate"] = float(agg["disagree_n"]) / n if n > 0 else 0.0
        agg["winner_correct_rate"] = float(agg["winner_correct_n"]) / n if n > 0 else 0.0
        agg["avg_edge"] = float(agg["avg_edge"]) / n if n > 0 else 0.0
        agg["avg_logloss"] = float(agg["avg_logloss"]) / n if n > 0 else 0.0

        for bk, b in list(buckets.items()):
            nn = float(b.get("n") or 0)
            if nn <= 0:
                continue
            b["fail_rate"] = float(b.get("fail_n") or 0) / nn
            b["disagree_rate"] = float(b.get("disagree_n") or 0) / nn
            b["winner_correct_rate"] = float(b.get("winner_correct_n") or 0) / nn
            b["avg_edge"] = float(b.get("avg_edge") or 0.0) / nn
            b["avg_logloss"] = float(b.get("avg_logloss") or 0.0) / nn
        out_stats[str(mid)] = agg
        out_buckets[str(mid)] = buckets
        n_used += int(agg.get("n") or 0)

    return jsonify({
        "ok": True,
        "enabled": True,
        "ts": int(now_ms),
        "n": int(n_used),
        "bucket_by": bucket_by,
        "filters": {
            "model": model_id,
            "pair": pair,
            "regime": regime,
            "since_ts": int(since_ts),
            "until_ts": int(until_ts),
            "only_failed": bool(only_failed),
            "only_disagree": bool(only_disagree),
        },
        "stats": out_stats,
        "buckets": out_buckets,
    })


@app.route("/arena/oos", methods=["GET"])
def arena_oos():
    now_ms = _now_ms()
    _arena_init_if_needed(now_ms=now_ms)
    if not _arena_enabled():
        return jsonify({"ok": True, "enabled": False})

    items = ARENA_STATE.get("attrib") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(items, list) or not items:
        return jsonify({"ok": True, "enabled": True, "ts": int(now_ms), "n": 0, "windows": []})

    try:
        window = int(request.args.get("window") or 0)
    except Exception:
        window = 0
    if window <= 0:
        try:
            window = int(CONFIG.get("arena_oos_window", 500) or 500)
        except Exception:
            window = 500
    window = max(10, int(window))

    try:
        rolls = int(request.args.get("rolls") or 0)
    except Exception:
        rolls = 0
    if rolls <= 0:
        try:
            rolls = int(CONFIG.get("arena_oos_rolls", 5) or 5)
        except Exception:
            rolls = 5
    rolls = max(1, min(50, int(rolls)))

    try:
        win_min = float(CONFIG.get("arena_edge_win_min", 0.0) or 0.0)
    except Exception:
        win_min = 0.0
    win_min = max(0.0, float(win_min))

    xs = list(items)
    windows = []
    for r in range(int(rolls)):
        end = len(xs) - int(r) * int(window)
        start = max(0, int(end) - int(window))
        if end <= start:
            break
        w = xs[start:end]

        model_ids: List[str] = []
        for it in w:
            if not isinstance(it, dict):
                continue
            mm = it.get("models")
            if not isinstance(mm, dict):
                continue
            for k in mm.keys():
                model_ids.append(str(k))
        model_ids = sorted(list(set(model_ids)))

        per_model: Dict[str, Any] = {}
        for mid in model_ids:
            agg = {
                "n": 0,
                "eligible_n": 0,
                "take_n": 0,
                "fail_n": 0,
                "disagree_n": 0,
                "chosen_n": 0,
                "winner_n": 0,
                "explore_n": 0,
                "avg_edge": 0.0,
                "avg_logloss": 0.0,
                "reward_score_sum": 0.0,
                "penalty_score_sum": 0.0,
            }
            for it in w:
                if not isinstance(it, dict):
                    continue
                mm = it.get("models")
                if not isinstance(mm, dict):
                    continue
                mv = mm.get(str(mid))
                if not isinstance(mv, dict):
                    continue

                try:
                    y = int(it.get("y") or 0)
                except Exception:
                    y = 0
                correct_take = True if int(y) == 1 else False
                take = bool(mv.get("take", False))
                fail = bool(take) != bool(correct_take)
                eligible = bool(mv.get("eligible", True))
                disagree = bool(it.get("disagree", False))
                explore = bool(it.get("explore", False))
                chosen_id = it.get("chosen_id")
                winner_id = it.get("winner_id")
                try:
                    edge_v = float(mv.get("edge") or 0.0)
                except Exception:
                    edge_v = 0.0
                try:
                    ll = float(mv.get("logloss") or 0.0)
                except Exception:
                    ll = 0.0

                agg["n"] += 1
                if eligible:
                    agg["eligible_n"] += 1
                if take:
                    agg["take_n"] += 1
                if fail:
                    agg["fail_n"] += 1
                if disagree:
                    agg["disagree_n"] += 1
                if explore:
                    agg["explore_n"] += 1
                if chosen_id is not None and str(chosen_id) == str(mid):
                    agg["chosen_n"] += 1
                if winner_id is not None and str(winner_id) == str(mid):
                    agg["winner_n"] += 1

                agg["avg_edge"] += float(edge_v)
                agg["avg_logloss"] += float(ll)
                if take:
                    agg["reward_score_sum"] += float(max(0.0, float(edge_v) - float(win_min)))
                    agg["penalty_score_sum"] += float(max(0.0, -float(edge_v) - float(win_min)))

            n = float(agg["n"])
            if n <= 0:
                continue
            agg["take_rate"] = float(agg["take_n"]) / n
            agg["fail_rate"] = float(agg["fail_n"]) / n
            agg["eligible_rate"] = float(agg["eligible_n"]) / n
            agg["disagree_rate"] = float(agg["disagree_n"]) / n
            agg["chosen_rate"] = float(agg["chosen_n"]) / n
            agg["winner_rate"] = float(agg["winner_n"]) / n
            agg["explore_rate"] = float(agg["explore_n"]) / n
            agg["avg_edge"] = float(agg["avg_edge"]) / n
            agg["avg_logloss"] = float(agg["avg_logloss"]) / n
            per_model[str(mid)] = agg

        windows.append({
            "start_ts": int((w[0] or {}).get("ts") or 0),
            "end_ts": int((w[-1] or {}).get("ts") or 0),
            "n": int(len(w)),
            "per_model": per_model,
        })

    return jsonify({"ok": True, "enabled": True, "ts": int(now_ms), "n": int(len(xs)), "window": int(window), "rolls": int(rolls), "win_min": float(win_min), "windows": windows})


@app.route("/arena/layer2/status", methods=["GET"])
def arena_layer2_status():
    now_ms = _now_ms()
    mode = str(request.args.get("mode") or "entry").strip().lower()
    if mode in ("exit", "out"):
        if not _arena_enabled():
            return jsonify({"ok": True, "enabled": False})
        return jsonify({
            "ok": True,
            "enabled": True,
            "ts": int(now_ms),
            "layer2_enabled": False,
            "state": {"last_train_ms": 0, "attrib_count": 0, "updated": {}},
            "model_calib": {},
        })
    _arena_init_if_needed(now_ms=now_ms)
    if not _arena_enabled():
        return jsonify({"ok": True, "enabled": False})
    st = ARENA_STATE.get("layer2") if isinstance(ARENA_STATE, dict) else {}
    mc = ARENA_STATE.get("model_calib") if isinstance(ARENA_STATE, dict) else {}
    out_mc = {}
    if isinstance(mc, dict):
        for k, v in mc.items():
            if not isinstance(v, dict):
                continue
            out_mc[str(k)] = {"method": v.get("method"), "ts": int(v.get("ts") or 0), "metrics": v.get("metrics")}
    return jsonify({
        "ok": True,
        "enabled": True,
        "ts": int(now_ms),
        "layer2_enabled": bool(CONFIG.get("arena_layer2_enabled", True)),
        "state": st,
        "model_calib": out_mc,
    })


@app.route("/arena/layer2/run", methods=["POST"])
def arena_layer2_run():
    now_ms = _now_ms()
    mode = str(request.args.get("mode") or "entry").strip().lower()
    if mode in ("exit", "out"):
        if not _arena_enabled():
            return jsonify({"ok": False, "trained": False, "error": "arena_disabled"}), 400
        return jsonify({"ok": True, "trained": False, "updated": {}})
    _arena_init_if_needed(now_ms=now_ms)
    data = request.get_json(force=True) or {}
    force = bool(data.get("force", True))
    res = _arena_layer2_train_if_needed(now_ms=int(now_ms), force=force)
    return jsonify(res)


@app.route("/arena/layer2/oos", methods=["GET"])
def arena_layer2_oos():
    now_ms = _now_ms()
    _arena_init_if_needed(now_ms=now_ms)
    if not _arena_enabled():
        return jsonify({"ok": True, "enabled": False})

    items = ARENA_STATE.get("attrib") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(items, list) or not items:
        return jsonify({"ok": True, "enabled": True, "ts": int(now_ms), "n": 0, "windows": []})

    model_id = request.args.get("model")
    pair = request.args.get("pair")
    regime = request.args.get("regime")
    try:
        since_ts = int(request.args.get("since_ts") or 0)
    except Exception:
        since_ts = 0
    try:
        until_ts = int(request.args.get("until_ts") or 0)
    except Exception:
        until_ts = 0

    try:
        window = int(request.args.get("window") or 0)
    except Exception:
        window = 0
    if window <= 0:
        try:
            window = int(CONFIG.get("arena_layer2_oos_size", 200) or 200)
        except Exception:
            window = 200
    window = max(10, int(window))

    try:
        rolls = int(request.args.get("rolls") or 0)
    except Exception:
        rolls = 0
    if rolls <= 0:
        try:
            rolls = int(CONFIG.get("arena_layer2_oos_rolls", 3) or 3)
        except Exception:
            rolls = 3
    rolls = max(1, min(50, int(rolls)))

    try:
        min_oos = int(CONFIG.get("arena_layer2_min_oos", 50) or 50)
    except Exception:
        min_oos = 50
    min_oos = max(10, int(min_oos))

    xs = []
    for it in list(items):
        if not isinstance(it, dict):
            continue
        ts = it.get("ts")
        try:
            ts_i = int(ts) if ts is not None else 0
        except Exception:
            ts_i = 0
        if since_ts > 0 and ts_i < int(since_ts):
            continue
        if until_ts > 0 and ts_i > int(until_ts):
            continue
        if pair is not None and str(it.get("pair") or "") != str(pair):
            continue
        if regime is not None and str(it.get("regime") or "") != str(regime):
            continue
        xs.append(it)

    if not xs:
        return jsonify({
            "ok": True,
            "enabled": True,
            "ts": int(now_ms),
            "n": 0,
            "window": int(window),
            "rolls": int(rolls),
            "filters": {"model": model_id, "pair": pair, "regime": regime, "since_ts": int(since_ts), "until_ts": int(until_ts)},
            "windows": [],
        })

    windows = []
    for r in range(int(rolls)):
        end = len(xs) - int(r) * int(window)
        start = max(0, int(end) - int(window))
        if end <= start:
            break
        w = xs[start:end]

        if model_id is not None:
            model_ids = [str(model_id)]
        else:
            model_ids: List[str] = []
            for it in w:
                mm = it.get("models")
                if not isinstance(mm, dict):
                    continue
                for k in mm.keys():
                    model_ids.append(str(k))
            model_ids = sorted(list(set(model_ids)))

        per_model: Dict[str, Any] = {}
        for mid in model_ids:
            xo, yo, wo = _arena_layer2_dataset_for_model(w, mid)
            if len(xo) < int(min_oos):
                continue
            mse_raw = _arena_layer2_mse_mode(xo, yo, wo, mode="raw", model_id=mid, regime=regime)
            mse_global = _arena_layer2_mse_mode(xo, yo, wo, mode="global", model_id=mid, regime=regime)
            mse_model = _arena_layer2_mse_mode(xo, yo, wo, mode="model", model_id=mid, regime=regime)
            if not (math.isfinite(mse_raw) and math.isfinite(mse_global) and math.isfinite(mse_model)):
                continue
            per_model[str(mid)] = {
                "n_oos": int(len(xo)),
                "mse_raw": float(mse_raw),
                "mse_global": float(mse_global),
                "mse_model": float(mse_model),
                "improve_vs_raw": float(mse_raw) - float(mse_model),
                "improve_vs_global": float(mse_global) - float(mse_model),
            }

        windows.append({
            "start_ts": int((w[0] or {}).get("ts") or 0),
            "end_ts": int((w[-1] or {}).get("ts") or 0),
            "n": int(len(w)),
            "per_model": per_model,
        })

    return jsonify({
        "ok": True,
        "enabled": True,
        "ts": int(now_ms),
        "n": int(len(xs)),
        "window": int(window),
        "rolls": int(rolls),
        "min_oos": int(min_oos),
        "filters": {"model": model_id, "pair": pair, "regime": regime, "since_ts": int(since_ts), "until_ts": int(until_ts)},
        "windows": windows,
    })

