        def _compact_sync_err(err0: Any) -> Optional[str]:
            if err0 is None:
                return None
            try:
                s = str(err0)
            except Exception:
                return None
            s2 = s.strip()
            if not s2:
                return None
            code = None
            if s2.startswith("(") and "," in s2:
                try:
                    head = s2[1:].split(",", 1)[0].strip()
                    if head.isdigit():
                        code = int(head)
                except Exception:
                    code = None
            if code is not None:
                msg = f"HTTP {code}"
                if "cloudfront" in s2.lower():
                    msg = f"{msg} · CloudFront"
                return msg
            if len(s2) > 280:
                return s2[:280] + "…"
