        def _json_fix_nonfinite(x: Any) -> Any:
            if x is None:
                return None
            if isinstance(x, (bool, int, str)):
                return x
            if isinstance(x, float):
                return x if math.isfinite(x) else None
            if isinstance(x, dict):
                out_d: Dict[str, Any] = {}
                for kk, vv in x.items():
                    out_d[str(kk)] = _json_fix_nonfinite(vv)
                return out_d
            if isinstance(x, list):
                return [_json_fix_nonfinite(vv) for vv in x]
            if isinstance(x, tuple):
                return [_json_fix_nonfinite(vv) for vv in x]
            try:
                if "np" in globals() and isinstance(x, np.floating):
                    xf = float(x)
                    return xf if math.isfinite(xf) else None
            except Exception:
                pass
            return x

        try:
            out = _json_fix_nonfinite(out)
        except Exception:
            pass

