@app.route("/macro/btceth/overview", methods=["GET"])
def macro_btceth_overview():
    def _trend_cache_ok(x: Any) -> bool:
        if not isinstance(x, dict):
            return False
        rows = x.get("rows")
        if not isinstance(rows, list) or not rows:
            return False
        last = rows[-1]
        if not isinstance(last, dict):
            return False
        need = (
            "trend_w_dir",
            "trend_d_dir",
            "trend_shape_5",
            "trend_w_slope",
            "trend_d_slope",
            "trend_rate_change_dw",
        )
        return all((k in last) for k in need)

    def _energy_cache_ok(x: Any) -> bool:
        if not isinstance(x, dict):
            return False
        rows = x.get("rows")
        if not isinstance(rows, list) or not rows:
            return False
        last = rows[-1]
        if not isinstance(last, dict):
            return False
        need = (
            "kin_ma",
            "vol_ma",
            "pot_ma",
            "risk_baseline",
            "vol_dir",
            "vol_chg_dir",
            "vol_chg_speed",
            "mom_dir",
            "mom_chg_dir",
            "mom_chg_speed",
            "pot_dir",
            "pot_chg_dir",
            "pot_chg_speed",
        )
        return all((k in last) for k in need)

    def _flow_cache_ok(x: Any) -> bool:
        if not isinstance(x, dict):
            return False
        rows = x.get("rows")
        if not isinstance(rows, list) or not rows:
            return False
        last = rows[-1]
        if not isinstance(last, dict):
            return False
        need = (
            "rs_btc_vs_mkt",
            "rs_eth_vs_mkt",
            "rs_btc_vs_eth",
            "macro_flow_dir",
            "macro_flow_chg_dir",
            "macro_flow_chg_speed",
        )
        return all((k in last) for k in need)

    try:
        lookback_days = int(request.args.get("lookback_days") or 400)
    except Exception:
        lookback_days = 400
    try:
        flow_lookback_days = int(request.args.get("flow_lookback_days") or 240)
    except Exception:
        flow_lookback_days = 240
    lookback_days = max(60, min(2000, int(lookback_days)))
    flow_lookback_days = max(30, min(2000, int(flow_lookback_days)))

    btc_trend = _macro_cache_get(f"trend|BTC|{lookback_days}", ttl_sec=600)
    if not _trend_cache_ok(btc_trend):
        btc_trend = _macro_trend_series("BTC", lookback_days)
        _macro_cache_set(f"trend|BTC|{lookback_days}", btc_trend)
    eth_trend = _macro_cache_get(f"trend|ETH|{lookback_days}", ttl_sec=600)
    if not _trend_cache_ok(eth_trend):
        eth_trend = _macro_trend_series("ETH", lookback_days)
        _macro_cache_set(f"trend|ETH|{lookback_days}", eth_trend)

    btc_energy = _macro_cache_get(f"energy|BTC|{lookback_days}", ttl_sec=600)
    if not _energy_cache_ok(btc_energy):
        btc_energy = _macro_energy_series("BTC", lookback_days)
        _macro_cache_set(f"energy|BTC|{lookback_days}", btc_energy)
    eth_energy = _macro_cache_get(f"energy|ETH|{lookback_days}", ttl_sec=600)
    if not _energy_cache_ok(eth_energy):
        eth_energy = _macro_energy_series("ETH", lookback_days)
        _macro_cache_set(f"energy|ETH|{lookback_days}", eth_energy)

    flow = _macro_cache_get(f"flow_series|{flow_lookback_days}|", ttl_sec=900)
    if not _flow_cache_ok(flow):
        flow = _macro_flow_series(flow_lookback_days, core_size=None)
        _macro_cache_set(f"flow_series|{flow_lookback_days}|", flow)

    std_1h = None
    std_12h = None
    std_1d = None
    std_shape = None
    std_shape_update_h = 1
    macro_shape = None
    macro_tri_layer = None
    try:
        now_ms = _now_ms()
        h = 3_600_000
        last_closed_1h = int((int(now_ms) // int(h)) * int(h) - 1)
        std_1h = _entry_macro_btceth_hourly_std_at(int(last_closed_1h if last_closed_1h > 0 else now_ms))

        try:
            tf12_ms = int(_hl_interval_to_ms("12h"))
        except Exception:
            tf12_ms = int(12 * h)
        last_closed_12h = int((int(now_ms) // int(tf12_ms)) * int(tf12_ms) - 1)
        std_12h = _entry_macro_btceth_tf_std_at(int(last_closed_12h if last_closed_12h > 0 else now_ms), timeframe="12h")
        try:
            tf1d_ms = int(_hl_interval_to_ms("1d"))
        except Exception:
            tf1d_ms = int(24 * h)
        last_closed_1d = int((int(now_ms) // int(tf1d_ms)) * int(tf1d_ms) - 1)
        std_1d = _entry_macro_btceth_tf_std_at(int(last_closed_1d if last_closed_1d > 0 else now_ms), timeframe="1d")

        try:
            std_shape_update_h = int(CONFIG.get("entry_macro_btceth_shape_update_hours", 12) or 12)
        except Exception:
            std_shape_update_h = 12
        std_shape_update_h = int(max(1, min(24 * 30, int(std_shape_update_h))))

        if int(std_shape_update_h) <= 1:
            std_shape = std_1h
        else:
            t_shape = 0
            try:
                t_shape = int(_macro_align_nhour_close_ts(int(last_closed_1h if last_closed_1h > 0 else now_ms), int(std_shape_update_h)))
            except Exception:
                t_shape = 0
            if t_shape > 0:
                try:
                    std_shape = _entry_macro_btceth_hourly_std_at(int(t_shape))
                except Exception:
                    std_shape = None
            if std_shape is None:
                std_shape = std_1h

        try:
            macro_shape = _entry_macro_btceth_shape_at(int(last_closed_1h if last_closed_1h > 0 else now_ms), allow_disabled=True)
        except Exception:
            macro_shape = None
        try:
            macro_tri_layer = _macro_btc_dir_snapshot(timeframe="1h", horizon_h=12, short_n=3)
        except Exception:
            macro_tri_layer = None
    except Exception:
        std_1h = None
        std_12h = None
        std_1d = None
        std_shape = None
        macro_shape = None
        macro_tri_layer = None

    gate_std1h = None
    try:
        thr = float(CONFIG.get("entry_macro_btceth_hard_gate_risk_pct_max", 0.40) or 0.40)
    except Exception:
        thr = 0.40
    thr = float(_clip(float(thr), 0.0, 1.0))
    try:
        only_align = bool(CONFIG.get("entry_macro_btceth_hard_gate_only_with_macro_alignment", True))
    except Exception:
        only_align = True
    try:
        block_counter = bool(CONFIG.get("entry_macro_btceth_hard_gate_block_counter_when_high_risk", True))
    except Exception:
        block_counter = True
    try:
        fail_open = bool(CONFIG.get("entry_macro_btceth_hard_gate_fail_open", True))
    except Exception:
        fail_open = True

    gate_cfg = None
    try:
        gate_cfg = {
            "enabled": bool(CONFIG.get("entry_macro_btceth_hard_gate_enabled", True)),
            "fail_open": bool(fail_open),
            "apply_to_addon": bool(CONFIG.get("entry_macro_btceth_hard_gate_apply_to_addon", True)),
            "only_with_alignment": bool(only_align),
            "risk_thr": float(thr),
            "block_counter_when_high_risk": bool(block_counter),
        }
    except Exception:
        gate_cfg = None
    gate_enabled = bool(gate_cfg.get("enabled")) if isinstance(gate_cfg, dict) else False

    try:
        std_for_gate = std_1h

        if isinstance(std_for_gate, dict) and bool(std_for_gate.get("ok", False)) and isinstance(std_for_gate.get("btc"), dict) and isinstance(std_for_gate.get("eth"), dict):
            btc0 = std_for_gate.get("btc") if isinstance(std_for_gate.get("btc"), dict) else {}
            eth0 = std_for_gate.get("eth") if isinstance(std_for_gate.get("eth"), dict) else {}

            try:
                rb = float(btc0.get("risk_pct"))
            except Exception:
                rb = float("nan")
            try:
                re = float(eth0.get("risk_pct"))
            except Exception:
                re = float("nan")
            try:
                db = int(btc0.get("dir") or 0)
            except Exception:
                db = 0
            try:
                de = int(eth0.get("dir") or 0)
            except Exception:
                de = 0

            min_risk = None
            try:
                vals = [v for v in [rb, re] if math.isfinite(v)]
                min_risk = (float(min(vals)) if vals else None)
            except Exception:
                min_risk = None

            macro_long_any = (db == 1) or (de == 1)
            macro_short_any = (db == -1) or (de == -1)

            def _blocked_for_side(s0: str) -> Tuple[bool, str, bool]:
                aligned_any = True
                if bool(only_align):
                    if s0 == "long":
                        aligned_any = bool(macro_long_any)
                    else:
                        aligned_any = bool(macro_short_any)

                if min_risk is None or (not math.isfinite(float(min_risk))):
                    if bool(fail_open):
                        return False, "pass:data_unavailable", bool(aligned_any)
                    return True, "block:data_unavailable", bool(aligned_any)

                if bool(block_counter) and float(min_risk) >= float(thr):
                    if bool(macro_long_any) and (not bool(macro_short_any)) and s0 == "short":
                        return True, "block:counter_when_high_risk", False
                    if bool(macro_short_any) and (not bool(macro_long_any)) and s0 == "long":
                        return True, "block:counter_when_high_risk", False

                if bool(only_align) and (not bool(aligned_any)):
                    return False, "pass:no_alignment", False
                if float(min_risk) < float(thr):
                    return False, "pass:risk_ok", bool(aligned_any)
                if bool(macro_long_any) and (not bool(macro_short_any)) and s0 == "long":
                    return False, "pass:risk_high_clear_dir", True
                if bool(macro_short_any) and (not bool(macro_long_any)) and s0 == "short":
                    return False, "pass:risk_high_clear_dir", True
                return True, "block:risk_hard", bool(aligned_any)

            long_blocked, long_reason, long_aligned = _blocked_for_side("long")
            short_blocked, short_reason, short_aligned = _blocked_for_side("short")

            long_ok = (not bool(long_blocked))
            short_ok = (not bool(short_blocked))
            rec = "blocked"
            if bool(long_ok) and bool(short_ok):
                rec = "both"
            elif bool(long_ok):
                rec = "long"
            elif bool(short_ok):
                rec = "short"

            def _reason_code(s: str) -> str:
                ss = str(s or "")
                if "data_unavailable" in ss:
                    return "macro_btceth_data_unavailable"
                if "risk_hard" in ss:
                    return "macro_btceth_risk_hard_block"
                if "counter_when_high_risk" in ss:
                    return "macro_btceth_counter_when_high_risk"
                if "risk_high_clear_dir" in ss:
                    return "macro_btceth_risk_high_clear_dir"
                if "no_alignment" in ss:
                    return "macro_btceth_no_alignment"
                if "risk_ok" in ss:
                    return "macro_btceth_risk_ok"
                return ss

            gate_std1h = {
                "ts": int(std_for_gate.get("ts") or 0),
                "risk_thr": float(thr),
                "only_with_alignment": bool(only_align),
                "block_counter_when_high_risk": bool(block_counter),
                "min_risk": (None if min_risk is None else float(min_risk)),
                "long_ok": bool(long_ok),
                "short_ok": bool(short_ok),
                "recommend": str(rec),
                "effective_enabled": bool(gate_enabled),
                "effective_long_ok": (bool(long_ok) if bool(gate_enabled) else True),
                "effective_short_ok": (bool(short_ok) if bool(gate_enabled) else True),
                "effective_recommend": (str(rec) if bool(gate_enabled) else "disabled"),
                "data_valid": bool(std_for_gate.get("valid", False)),
                "long": {"blocked": bool(long_blocked), "reason": str(long_reason), "reason_code": _reason_code(str(long_reason)), "aligned": bool(long_aligned)},
                "short": {"blocked": bool(short_blocked), "reason": str(short_reason), "reason_code": _reason_code(str(short_reason)), "aligned": bool(short_aligned)},
            }
    except Exception:
        gate_std1h = None

    if gate_std1h is None:
        data_ts = 0
        try:
            if isinstance(std_1h, dict):
                data_ts = int(std_1h.get("ts") or 0)
        except Exception:
            data_ts = 0
        pass_ok = bool(fail_open)
        gate_std1h = {
            "ts": int(data_ts),
            "risk_thr": float(thr),
            "only_with_alignment": bool(only_align),
            "block_counter_when_high_risk": bool(block_counter),
            "min_risk": None,
            "long_ok": bool(pass_ok),
            "short_ok": bool(pass_ok),
            "recommend": ("both" if bool(pass_ok) else "blocked"),
            "effective_enabled": bool(gate_enabled),
            "effective_long_ok": (bool(pass_ok) if bool(gate_enabled) else True),
            "effective_short_ok": (bool(pass_ok) if bool(gate_enabled) else True),
            "effective_recommend": (("both" if bool(pass_ok) else "blocked") if bool(gate_enabled) else "disabled"),
            "data_valid": False,
            "long": {"blocked": (not bool(pass_ok)), "reason": ("pass:data_unavailable" if bool(pass_ok) else "block:data_unavailable"), "reason_code": "macro_btceth_data_unavailable", "aligned": False},
            "short": {"blocked": (not bool(pass_ok)), "reason": ("pass:data_unavailable" if bool(pass_ok) else "block:data_unavailable"), "reason_code": "macro_btceth_data_unavailable", "aligned": False},
        }

    return jsonify({
        "ok": True,
        "ts": _now_ms(),
        "lookback_days": int(lookback_days),
        "flow_lookback_days": int(flow_lookback_days),
        "btc": {"trend": btc_trend, "energy": btc_energy},
        "eth": {"trend": eth_trend, "energy": eth_energy},
        "flow": flow,
        "std_1h": std_1h,
        "std_12h": std_12h,
        "std_1d": std_1d,
        "std_shape": std_shape,
        "std_shape_update_hours": int(std_shape_update_h),
        "macro_btceth_shape": macro_shape,
        "macro_shape": macro_shape,
        "macro_tri_layer": macro_tri_layer,
        "gate_std1h": gate_std1h,
        "gate_config": gate_cfg,
    })


def _quant_pairs_btceth_params() -> Dict[str, Any]:
    tf = str(CONFIG.get("quant_pairs_btceth_timeframe", "1h") or "1h").strip().lower() or "1h"
    if tf == "60m":
        tf = "1h"

    def _duration_to_bars(dur: Any, default_bars: int) -> int:
        if dur is None:
            return int(default_bars)
        if isinstance(dur, (int, float)):
            v = int(dur)
            return int(v) if v > 0 else int(default_bars)
        s = str(dur).strip().lower()
        if not s:
            return int(default_bars)
        try:
            v = int(float(s))
            if v > 0:
                return int(v)
        except Exception:
            pass
        num = None
        unit = ""
        i = 0
        while i < len(s) and (s[i].isdigit() or s[i] in (".",)):
            i += 1
        try:
            num = float(s[:i]) if i > 0 else None
        except Exception:
            num = None
        unit = s[i:].strip() if i < len(s) else ""
        if num is None or (not math.isfinite(float(num))) or float(num) <= 0.0:
            return int(default_bars)
        ms_per_bar = int(_hl_interval_to_ms(tf))
        if ms_per_bar <= 0:
            return int(default_bars)
        mul_ms = None
        if unit in ("ms", "msec"):
            mul_ms = 1.0
        elif unit in ("s", "sec", "secs"):
            mul_ms = 1000.0
        elif unit in ("m", "min", "mins"):
            mul_ms = 60_000.0
        elif unit in ("h", "hr", "hrs"):
            mul_ms = 3_600_000.0
        elif unit in ("d", "day", "days"):
            mul_ms = 86_400_000.0
        elif unit in ("w", "wk", "wks", "week", "weeks"):
            mul_ms = 7.0 * 86_400_000.0
        elif unit in ("mo", "mon", "month", "months"):
            mul_ms = 30.0 * 86_400_000.0
        elif unit in ("y", "yr", "yrs", "year", "years"):
            mul_ms = 365.0 * 86_400_000.0
        if mul_ms is None:
            return int(default_bars)
        bars = int(round((float(num) * float(mul_ms)) / float(ms_per_bar)))
        return int(bars) if bars > 0 else int(default_bars)

    try:
        window_ols = int(CONFIG.get("quant_pairs_btceth_window_ols", 240) or 240)
    except Exception:
        window_ols = 240
    try:
        window_z = int(CONFIG.get("quant_pairs_btceth_window_z", 240) or 240)
    except Exception:
        window_z = 240
    try:
        entry_z = float(CONFIG.get("quant_pairs_btceth_entry_z", 2.0) or 2.0)
    except Exception:
        entry_z = 2.0
    try:
        entry_z_long = float(CONFIG.get("quant_pairs_btceth_entry_z_long")) if CONFIG.get("quant_pairs_btceth_entry_z_long") is not None else None
    except Exception:
        entry_z_long = None
    try:
        entry_z_short = float(CONFIG.get("quant_pairs_btceth_entry_z_short")) if CONFIG.get("quant_pairs_btceth_entry_z_short") is not None else None
    except Exception:
        entry_z_short = None
    try:
        exit_z = float(CONFIG.get("quant_pairs_btceth_exit_z", 0.5) or 0.5)
    except Exception:
        exit_z = 0.5

    try:
        z_exit_confirm_bars = int(CONFIG.get("quant_pairs_btceth_z_exit_confirm_bars", 1) or 1)
    except Exception:
        z_exit_confirm_bars = 1
    z_exit_confirm_bars = int(max(1, min(10, int(z_exit_confirm_bars))))
    try:
        stop_z = float(CONFIG.get("quant_pairs_btceth_stop_z", 4.0) or 4.0)
    except Exception:
        stop_z = 4.0
    try:
        corr_min = float(CONFIG.get("quant_pairs_btceth_corr_min", 0.8) or 0.8)
    except Exception:
        corr_min = 0.8
    try:
        max_hold_bars = int(CONFIG.get("quant_pairs_btceth_max_hold_bars", 240) or 240)
    except Exception:
        max_hold_bars = 240

    try:
        state_check_interval_sec = int(CONFIG.get("quant_pairs_btceth_state_check_interval_sec", CONFIG.get("quant_auto_state_check_interval_sec", 60)) or 60)
    except Exception:
        state_check_interval_sec = 60
    state_check_interval_sec = int(max(10, min(3600, int(state_check_interval_sec))))

    beta_std_max = None
    try:
        beta_std_max = float(CONFIG.get("quant_pairs_btceth_beta_std_max")) if CONFIG.get("quant_pairs_btceth_beta_std_max") is not None else None
    except Exception:
        beta_std_max = None
    if beta_std_max is None:
        try:
            beta_std_max = float(CONFIG.get("quant_pairs_btceth_gate_beta_std_max", 0.15) or 0.15)
        except Exception:
            beta_std_max = 0.15

    try:
        beta_abs_max = float(CONFIG.get("quant_pairs_btceth_beta_abs_max", 3.0) or 3.0)
    except Exception:
        beta_abs_max = 3.0

    try:
        notional_usdc_per_leg = float(CONFIG.get("quant_pairs_btceth_notional_usdc", CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0) or 200.0)
    except Exception:
        notional_usdc_per_leg = float(CONFIG.get("entry_fixed_notional_usdc", 200.0) or 200.0)

    try:
        pair_notional_usdc_max = float(CONFIG.get("quant_pairs_btceth_pair_notional_usdc_max")) if CONFIG.get("quant_pairs_btceth_pair_notional_usdc_max") is not None else None
    except Exception:
        pair_notional_usdc_max = None

    try:
        cooldown_bars_after_exit = int(CONFIG.get("quant_pairs_btceth_cooldown_bars_after_exit", 4) or 4)
    except Exception:
        cooldown_bars_after_exit = 4

    try:
        emergency_close_on_gate_violation = bool(CONFIG.get("quant_pairs_btceth_emergency_close_on_gate_violation", True))
    except Exception:
        emergency_close_on_gate_violation = True

    try:
        z_cost_buffer_mult = float(CONFIG.get("quant_pairs_btceth_z_cost_buffer_mult", 1.0) or 1.0)
    except Exception:
        z_cost_buffer_mult = 1.0

    exit_pnl_enabled = True
    try:
        v = CONFIG.get("quant_pairs_btceth_exit_pnl_enabled", True)
        if isinstance(v, str):
            s = str(v).strip().lower()
            if s in ("0", "false", "no", "n", "off", "disable", "disabled"):
                exit_pnl_enabled = False
            elif s in ("1", "true", "yes", "y", "on", "enable", "enabled"):
                exit_pnl_enabled = True
        else:
            exit_pnl_enabled = bool(v)
    except Exception:
        exit_pnl_enabled = True

    try:
        pnl_stop_loss_r = float(CONFIG.get("quant_pairs_btceth_pnl_stop_loss_r", -0.010) or -0.010)
    except Exception:
        pnl_stop_loss_r = -0.010
    try:
        pnl_take_profit_r = float(CONFIG.get("quant_pairs_btceth_pnl_take_profit_r", 0.008) or 0.008)
    except Exception:
        pnl_take_profit_r = 0.008
    try:
        pnl_trail_start_r = float(CONFIG.get("quant_pairs_btceth_pnl_trail_start_r", 0.006) or 0.006)
    except Exception:
        pnl_trail_start_r = 0.006
    try:
        pnl_trail_dd_r = float(CONFIG.get("quant_pairs_btceth_pnl_trail_dd_r", 0.003) or 0.003)
    except Exception:
        pnl_trail_dd_r = 0.003
    try:
        pnl_min_on_z_exit_r = float(CONFIG.get("quant_pairs_btceth_pnl_min_on_z_exit_r", 0.000) or 0.000)
    except Exception:
        pnl_min_on_z_exit_r = 0.0
    try:
        pnl_min_hold_bars = int(CONFIG.get("quant_pairs_btceth_pnl_min_hold_bars", 0) or 0)
    except Exception:
        pnl_min_hold_bars = 0

    window_ols = _duration_to_bars(CONFIG.get("quant_pairs_btceth_window_ols_duration"), int(window_ols))
    window_z = _duration_to_bars(CONFIG.get("quant_pairs_btceth_window_z_duration"), int(window_z))
    max_hold_bars = _duration_to_bars(CONFIG.get("quant_pairs_btceth_max_hold_duration"), int(max_hold_bars))
    window_ols = max(10, min(5000, int(window_ols)))
    window_z = max(10, min(5000, int(window_z)))
    entry_z = float(_clip(float(entry_z), 0.1, 10.0))
    if entry_z_long is None or (not math.isfinite(float(entry_z_long))):
        entry_z_long = float(entry_z)
    if entry_z_short is None or (not math.isfinite(float(entry_z_short))):
        entry_z_short = float(entry_z)
    entry_z_long = float(_clip(float(entry_z_long), 0.1, 10.0))
    entry_z_short = float(_clip(float(entry_z_short), 0.1, 10.0))
    entry_z_min = float(min(float(entry_z_long), float(entry_z_short)))
    entry_z_max = float(max(float(entry_z_long), float(entry_z_short)))
    exit_z = float(_clip(float(exit_z), 0.0, float(entry_z_min)))
    stop_z = float(_clip(float(stop_z), float(entry_z_max), 20.0))
    corr_min = float(_clip(float(corr_min), 0.0, 0.999))
    max_hold_bars = max(1, min(20000, int(max_hold_bars)))
    beta_std_max = float(_clip(float(beta_std_max), 0.0, 5.0))
    beta_abs_max = float(_clip(float(beta_abs_max), 0.0, 20.0))
    notional_usdc_per_leg = float(_clip(float(notional_usdc_per_leg), 0.0, 1_000_000_000.0))
    if pair_notional_usdc_max is not None:
        try:
            pair_notional_usdc_max = float(pair_notional_usdc_max)
        except Exception:
            pair_notional_usdc_max = None
        if pair_notional_usdc_max is not None and (not math.isfinite(float(pair_notional_usdc_max))):
            pair_notional_usdc_max = None
        if pair_notional_usdc_max is not None:
            pair_notional_usdc_max = float(_clip(float(pair_notional_usdc_max), 0.0, 1_000_000_000.0))
    cooldown_bars_after_exit = int(max(0, min(2000, int(cooldown_bars_after_exit))))
    z_cost_buffer_mult = float(_clip(float(z_cost_buffer_mult), 0.0, 10.0))
    pnl_stop_loss_r = float(_clip(float(pnl_stop_loss_r), -1.0, 1.0))
    pnl_take_profit_r = float(_clip(float(pnl_take_profit_r), -1.0, 1.0))
    pnl_trail_start_r = float(_clip(float(pnl_trail_start_r), -1.0, 1.0))
    pnl_trail_dd_r = float(_clip(float(pnl_trail_dd_r), 0.0, 1.0))
    pnl_min_on_z_exit_r = float(_clip(float(pnl_min_on_z_exit_r), -1.0, 1.0))
    pnl_min_hold_bars = int(max(0, min(20000, int(pnl_min_hold_bars))))
    return {
        "timeframe": tf,
        "window_ols": int(window_ols),
        "window_z": int(window_z),
        "beta_std_max": float(beta_std_max),
        "beta_abs_max": float(beta_abs_max),
        "entry_z": float(entry_z),
        "entry_z_long": float(entry_z_long),
        "entry_z_short": float(entry_z_short),
        "exit_z": float(exit_z),
        "z_exit_confirm_bars": int(z_exit_confirm_bars),
        "stop_z": float(stop_z),
        "corr_min": float(corr_min),
        "max_hold_bars": int(max_hold_bars),
        "z_cost_buffer_mult": float(z_cost_buffer_mult),
        "notional_usdc_per_leg": float(notional_usdc_per_leg),
        "pair_notional_usdc_max": (None if pair_notional_usdc_max is None else float(pair_notional_usdc_max)),
        "cooldown_bars_after_exit": int(cooldown_bars_after_exit),
        "emergency_close_on_gate_violation": bool(emergency_close_on_gate_violation),
        "state_check_interval_sec": int(state_check_interval_sec),
        "exit_pnl_enabled": bool(exit_pnl_enabled),
        "pnl_stop_loss_r": float(pnl_stop_loss_r),
        "pnl_take_profit_r": float(pnl_take_profit_r),
        "pnl_trail_start_r": float(pnl_trail_start_r),
        "pnl_trail_dd_r": float(pnl_trail_dd_r),
        "pnl_min_on_z_exit_r": float(pnl_min_on_z_exit_r),
        "pnl_min_hold_bars": int(pnl_min_hold_bars),
    }


def _quant_pairs_btcalt_exit_pnl_defaults() -> Dict[str, Any]:
    return {
        "exit_pnl_enabled": True,
        "pnl_stop_loss_r": -0.010,
        "pnl_take_profit_r": 0.008,
        "pnl_trail_start_r": 0.006,
        "pnl_trail_dd_r": 0.003,
        "pnl_min_on_z_exit_r": 0.000,
        "pnl_min_hold_bars": 0,
    }


def _quant_pairs_pnl_track_key(tag: str, alt: Optional[str] = None) -> str:
    t = str(tag or "").strip().lower() or "pairs"
    if alt is None:
        return f"quant_pairs_pnl_track:{t}"
    a = str(alt).strip().upper()
    return f"quant_pairs_pnl_track:{t}:{a}"


def _quant_pairs_pnl_track_get(key: str) -> Dict[str, Any]:
    k = str(key or "").strip()
    st = TRACKER_STATE.get(k)
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE[k] = st
    return st


def _quant_pairs_pnl_track_reset(key: str):
    k = str(key or "").strip()
    if not k:
        return
    try:
        if k in TRACKER_STATE:
            del TRACKER_STATE[k]
    except Exception:
        pass


def _quant_pairs_side_norm(s: Any) -> str:
    try:
        s0 = str(s or "").strip().lower()
    except Exception:
        s0 = ""
    if s0 in ("buy", "long"):
        return "long"
    if s0 in ("sell", "short"):
        return "short"
    return ""


def _quant_pairs_two_leg_pair_ok(a: Any, b: Any) -> bool:
    if not isinstance(a, dict) or not isinstance(b, dict):
        return False
    sa = _quant_pairs_side_norm(a.get("side"))
    sb = _quant_pairs_side_norm(b.get("side"))
    if sa and sb:
        return sa != sb
    return True


def _quant_pairs_exit_decision_z_shared(
    pos_any: bool,
    pos_pair_ok: bool,
    zf: Optional[float],
    stop_z: float,
    hold_exceeded: bool,
    exit_z_eff: float,
) -> Tuple[str, Optional[str]]:
    if not bool(pos_any):
        return "hold", None
    if zf is None or (not math.isfinite(float(zf))):
        return "hold", "z_unavailable"
    if not bool(pos_pair_ok):
        return "stop", "one_leg_open"
    if abs(float(zf)) >= float(stop_z):
        return "stop", "z_stop"
    if bool(hold_exceeded):
        return "exit", "max_hold_exceeded"
    if abs(float(zf)) <= float(exit_z_eff):
        return "exit", "z_exit"
    return "hold", "in_position"


def _quant_pairs_pnl_ratio_from_pack(pnl_pack: Dict[str, Any], position_pack: Optional[Dict[str, Any]]) -> Optional[float]:
    if not isinstance(pnl_pack, dict) or (not bool(pnl_pack.get("ok"))):
        return None
    denom = None
    if isinstance(position_pack, dict):
        try:
            legs = position_pack.get("legs") if isinstance(position_pack.get("legs"), dict) else {}
            dv = 0.0
            for k in ("btc", "eth", "alt"):
                if isinstance(legs.get(k), dict):
                    dv += abs(float(legs[k].get("notional_usdc") or 0.0))
            denom = float(dv) if math.isfinite(float(dv)) and float(dv) > 0.0 else None
        except Exception:
            denom = None
    if denom is None:
        try:
            legs = pnl_pack.get("legs") if isinstance(pnl_pack.get("legs"), dict) else {}
            dv = 0.0
            for k in ("btc", "eth", "alt"):
                if isinstance(legs.get(k), dict):
                    dv += abs(float(legs[k].get("notional_usdc") or 0.0))
            denom = float(dv) if math.isfinite(float(dv)) and float(dv) > 0.0 else None
        except Exception:
            denom = None
    if denom is None or float(denom) <= 0.0:
        return None

    u = None
    try:
        u = pnl_pack.get("net_est_usdc") if pnl_pack.get("net_est_usdc") is not None else None
        if u is not None:
            u = float(u)
    except Exception:
        u = None
    if u is None:
        try:
            ug = float(pnl_pack.get("unrealized_gross_usdc") or 0.0)
        except Exception:
            ug = 0.0
        try:
            fu = float(pnl_pack.get("funding_accrual_usdc") or 0.0)
        except Exception:
            fu = 0.0
        cu = None
        try:
            cu = pnl_pack.get("cost_est_usdc") if pnl_pack.get("cost_est_usdc") is not None else None
            if cu is not None:
                cu = float(cu)
        except Exception:
            cu = None
        if cu is None:
            u = float(ug + fu)
        else:
            u = float(ug + fu - float(cu))

    if not math.isfinite(float(u)):
        return None
    return float(u) / float(denom)


def _quant_pairs_pnl_track_update(key: str, entry_ts: Optional[int], pnl_r: Optional[float], now_ms: int) -> Dict[str, Any]:
    st = _quant_pairs_pnl_track_get(str(key))
    try:
        cur_entry = int(st.get("entry_ts") or 0)
    except Exception:
        cur_entry = 0
    ent = None
    try:
        ent = int(entry_ts) if entry_ts is not None else None
    except Exception:
        ent = None

    if ent is None or ent <= 0:
        st.clear()
        return st

    if cur_entry != int(ent):
        st.clear()
        st["entry_ts"] = int(ent)

    pr = None
    try:
        pr = float(pnl_r) if pnl_r is not None else None
    except Exception:
        pr = None
    if pr is not None and math.isfinite(float(pr)):
        try:
            peak = float(st.get("peak_r") or pr)
        except Exception:
            peak = float(pr)
        if not math.isfinite(float(peak)):
            peak = float(pr)
        peak = float(max(float(peak), float(pr)))
        st["peak_r"] = float(peak)
        st["last_r"] = float(pr)
        st["ts"] = int(now_ms)
    return st


def _quant_pairs_apply_pnl_exit(
    action: str,
    reason: Optional[str],
    params: Dict[str, Any],
    position_pack: Optional[Dict[str, Any]],
    pnl_pack: Optional[Dict[str, Any]],
    zf: Optional[float],
    exit_z_eff: Optional[float],
    track_key: str,
    now_ms: int,
) -> Dict[str, Any]:
    out = {"action": str(action), "reason": reason, "pnl_exit": None}
    if not isinstance(params, dict):
        return out
    if not bool(params.get("exit_pnl_enabled", True)):
        return out
    if not isinstance(position_pack, dict) or (not bool(position_pack.get("any"))):
        _quant_pairs_pnl_track_reset(str(track_key))
        return out
    if not bool(position_pack.get("pair_ok")):
        _quant_pairs_pnl_track_reset(str(track_key))
        return out
    if not isinstance(pnl_pack, dict) or (not bool(pnl_pack.get("ok"))):
        return out

    hold_bars = None
    try:
        hold_bars = int(position_pack.get("hold_bars")) if position_pack.get("hold_bars") is not None else None
    except Exception:
        hold_bars = None

    entry_ts = None
    try:
        entry_ts = int(position_pack.get("entry_ts")) if position_pack.get("entry_ts") is not None else None
    except Exception:
        entry_ts = None

    pnl_r = _quant_pairs_pnl_ratio_from_pack(pnl_pack=dict(pnl_pack), position_pack=position_pack)
    st = _quant_pairs_pnl_track_update(key=str(track_key), entry_ts=entry_ts, pnl_r=pnl_r, now_ms=int(now_ms))
    peak_r = None
    try:
        peak_r = float(st.get("peak_r")) if st.get("peak_r") is not None else None
    except Exception:
        peak_r = None

    dd_r = None
    if pnl_r is not None and peak_r is not None and math.isfinite(float(pnl_r)) and math.isfinite(float(peak_r)):
        dd_r = float(max(0.0, float(peak_r) - float(pnl_r)))

    try:
        pnl_min_hold_bars = int(params.get("pnl_min_hold_bars") or 0)
    except Exception:
        pnl_min_hold_bars = 0
    pnl_min_hold_bars = int(max(0, int(pnl_min_hold_bars)))

    try:
        pnl_stop_loss_r = float(params.get("pnl_stop_loss_r")) if params.get("pnl_stop_loss_r") is not None else None
    except Exception:
        pnl_stop_loss_r = None
    try:
        pnl_take_profit_r = float(params.get("pnl_take_profit_r")) if params.get("pnl_take_profit_r") is not None else None
    except Exception:
        pnl_take_profit_r = None
    try:
        pnl_trail_start_r = float(params.get("pnl_trail_start_r")) if params.get("pnl_trail_start_r") is not None else None
    except Exception:
        pnl_trail_start_r = None
    try:
        pnl_trail_dd_r = float(params.get("pnl_trail_dd_r")) if params.get("pnl_trail_dd_r") is not None else None
    except Exception:
        pnl_trail_dd_r = None
    try:
        pnl_min_on_z_exit_r = float(params.get("pnl_min_on_z_exit_r")) if params.get("pnl_min_on_z_exit_r") is not None else None
    except Exception:
        pnl_min_on_z_exit_r = None

    out["pnl_exit"] = {
        "ok": True,
        "enabled": True,
        "pnl_r": (None if pnl_r is None else float(pnl_r)),
        "peak_r": (None if peak_r is None else float(peak_r)),
        "dd_from_peak_r": (None if dd_r is None else float(dd_r)),
        "hold_bars": (None if hold_bars is None else int(hold_bars)),
        "min_hold_bars": int(pnl_min_hold_bars),
        "stop_loss_r": (None if pnl_stop_loss_r is None else float(pnl_stop_loss_r)),
        "take_profit_r": (None if pnl_take_profit_r is None else float(pnl_take_profit_r)),
        "trail_start_r": (None if pnl_trail_start_r is None else float(pnl_trail_start_r)),
        "trail_dd_r": (None if pnl_trail_dd_r is None else float(pnl_trail_dd_r)),
        "min_on_z_exit_r": (None if pnl_min_on_z_exit_r is None else float(pnl_min_on_z_exit_r)),
        "z": (None if zf is None else float(zf)),
        "exit_z_eff": (None if exit_z_eff is None else float(exit_z_eff)),
    }

    z_exit_hits = 0
    try:
        z_exit_hits = int(st.get("z_exit_hits") or 0)
    except Exception:
        z_exit_hits = 0
    z_exit_hits = int(max(0, min(1_000_000, int(z_exit_hits))))
    try:
        z_exit_confirm_bars = int(params.get("z_exit_confirm_bars") or 1)
    except Exception:
        z_exit_confirm_bars = 1
    z_exit_confirm_bars = int(max(1, min(10, int(z_exit_confirm_bars))))

    in_z_exit_zone = False
    if zf is not None and exit_z_eff is not None and math.isfinite(float(zf)) and math.isfinite(float(exit_z_eff)):
        in_z_exit_zone = bool(abs(float(zf)) <= float(exit_z_eff))
    if bool(in_z_exit_zone):
        z_exit_hits = int(z_exit_hits + 1)
    else:
        z_exit_hits = 0
    st["z_exit_hits"] = int(z_exit_hits)
    out["pnl_exit"]["z_exit_hits"] = int(z_exit_hits)
    out["pnl_exit"]["z_exit_confirm_bars"] = int(z_exit_confirm_bars)

    if str(out.get("action")) == "stop":
        return out

    if pnl_r is not None and math.isfinite(float(pnl_r)) and pnl_stop_loss_r is not None and math.isfinite(float(pnl_stop_loss_r)):
        if float(pnl_r) <= float(pnl_stop_loss_r):
            out["action"] = "stop"
            out["reason"] = "pnl_stop"
            return out

    if str(out.get("action")) == "exit":
        r0 = str(out.get("reason") or "").strip()
        if r0 and r0 != "z_exit":
            return out

    allow_soft = True
    if hold_bars is None:
        allow_soft = True
    elif int(hold_bars) < int(pnl_min_hold_bars):
        allow_soft = False

    if allow_soft and pnl_r is not None and math.isfinite(float(pnl_r)) and pnl_take_profit_r is not None and math.isfinite(float(pnl_take_profit_r)):
        if float(pnl_r) >= float(pnl_take_profit_r):
            out["action"] = "exit"
            out["reason"] = "pnl_take_profit"
            return out

    if allow_soft and pnl_r is not None and peak_r is not None and dd_r is not None:
        if pnl_trail_start_r is not None and pnl_trail_dd_r is not None and math.isfinite(float(pnl_trail_start_r)) and math.isfinite(float(pnl_trail_dd_r)):
            if float(peak_r) >= float(pnl_trail_start_r) and float(dd_r) >= float(max(0.0, float(pnl_trail_dd_r))):
                out["action"] = "exit"
                out["reason"] = "pnl_trailing"
                return out

    if str(out.get("action")) == "exit" and str(out.get("reason") or "") == "z_exit":
        if int(z_exit_confirm_bars) > 1 and int(z_exit_hits) < int(z_exit_confirm_bars):
            out["action"] = "hold"
            out["reason"] = "z_exit_confirm_wait"
            return out
        if hold_bars is not None and int(hold_bars) < int(pnl_min_hold_bars):
            out["action"] = "hold"
            out["reason"] = "z_exit_before_min_hold"
            return out
        if pnl_min_on_z_exit_r is not None and pnl_r is not None and math.isfinite(float(pnl_min_on_z_exit_r)) and math.isfinite(float(pnl_r)):
            if float(pnl_r) < float(pnl_min_on_z_exit_r):
                out["action"] = "hold"
                out["reason"] = "z_exit_pnl_below_min"
                return out

    return out


def _quant_pairs_btceth_gate_params() -> Dict[str, Any]:
    enabled = bool(CONFIG.get("quant_pairs_btceth_gate_enabled", True))
    try:
        k_fail = int(CONFIG.get("quant_pairs_btceth_gate_k_fail", 5) or 5)
    except Exception:
        k_fail = 5
    try:
        window = int(CONFIG.get("quant_pairs_btceth_gate_window", 240) or 240)
    except Exception:
        window = 240
    try:
        freq = int(CONFIG.get("quant_pairs_btceth_gate_freq_bars", 10) or 10)
    except Exception:
        freq = 10
    try:
        freq_hv = int(CONFIG.get("quant_pairs_btceth_gate_freq_bars_highvol", 5) or 5)
    except Exception:
        freq_hv = 5
    try:
        hv_mult = float(CONFIG.get("quant_pairs_btceth_gate_highvol_mult", 1.5) or 1.5)
    except Exception:
        hv_mult = 1.5
    try:
        alpha = float(CONFIG.get("quant_pairs_btceth_gate_alpha", 0.05) or 0.05)
    except Exception:
        alpha = 0.05
    try:
        test_count = int(CONFIG.get("quant_pairs_btceth_gate_test_count", 1) or 1)
    except Exception:
        test_count = 1
    try:
        half_life_max_bars = int(CONFIG.get("quant_pairs_btceth_gate_half_life_max_bars", 480) or 480)
    except Exception:
        half_life_max_bars = 480
    try:
        beta_std_max = float(CONFIG.get("quant_pairs_btceth_beta_std_max")) if CONFIG.get("quant_pairs_btceth_beta_std_max") is not None else None
    except Exception:
        beta_std_max = None
    if beta_std_max is None:
        try:
            beta_std_max = float(CONFIG.get("quant_pairs_btceth_gate_beta_std_max", 0.15) or 0.15)
        except Exception:
            beta_std_max = 0.15
    k_fail = max(1, min(20, int(k_fail)))
    window = max(30, min(5000, int(window)))
    freq = max(1, min(1000, int(freq)))
    freq_hv = max(1, min(1000, int(freq_hv)))
    hv_mult = float(_clip(float(hv_mult), 1.0, 10.0))
    alpha = float(_clip(float(alpha), 0.001, 0.20))
    test_count = max(1, min(50, int(test_count)))
    alpha_eff = float(alpha) / float(test_count)
    return {
        "enabled": bool(enabled),
        "k_fail": int(k_fail),
        "window": int(window),
        "freq_bars": int(freq),
        "freq_bars_highvol": int(freq_hv),
        "highvol_mult": float(hv_mult),
        "alpha": float(alpha),
        "test_count": int(test_count),
        "alpha_eff": float(alpha_eff),
        "half_life_max_bars": int(max(1, min(10000, int(half_life_max_bars)))),
        "beta_std_max": float(_clip(float(beta_std_max), 0.0, 5.0)),
    }


def _quant_pairs_btceth_cost_params() -> Dict[str, Any]:
    try:
        execution = str(CONFIG.get("quant_pairs_btceth_cost_execution", "auto") or "auto").strip().lower()
    except Exception:
        execution = "auto"
    if execution not in ("taker", "maker", "auto"):
        execution = "auto"
    try:
        mu = float(CONFIG.get("quant_pairs_btceth_slip_mu", 0.0005) or 0.0005)
    except Exception:
        mu = 0.0005
    try:
        beta = float(CONFIG.get("quant_pairs_btceth_slip_beta", 0.0003) or 0.0003)
    except Exception:
        beta = 0.0003
    try:
        alpha = float(CONFIG.get("quant_pairs_btceth_slip_alpha", 0.5) or 0.5)
    except Exception:
        alpha = 0.5
    try:
        depth_th_btc = float(CONFIG.get("quant_pairs_btceth_depth_threshold_btc", 10.0) or 10.0)
    except Exception:
        depth_th_btc = 10.0
    try:
        avg_depth_btc = float(CONFIG.get("quant_pairs_btceth_avg_depth_btc", depth_th_btc) or depth_th_btc)
    except Exception:
        avg_depth_btc = float(depth_th_btc)
    try:
        maker_fee = float(CONFIG.get("quant_pairs_btceth_maker_fee", 0.0002) or 0.0002)
    except Exception:
        maker_fee = 0.0002
    try:
        taker_fee = float(CONFIG.get("quant_pairs_btceth_taker_fee", 0.0004) or 0.0004)
    except Exception:
        taker_fee = 0.0004
    try:
        maker_timeout_sec = float(CONFIG.get("quant_pairs_btceth_maker_timeout_sec", 10.0) or 10.0)
    except Exception:
        maker_timeout_sec = 10.0
    try:
        q = float(CONFIG.get("quant_pairs_btceth_slip_quantile", 0.95) or 0.95)
    except Exception:
        q = 0.95
    mu = float(_clip(float(mu), 0.0, 0.02))
    beta = float(_clip(float(beta), 1e-9, 0.02))
    alpha = float(_clip(float(alpha), 0.0, 2.0))
    depth_th_btc = float(_clip(float(depth_th_btc), 0.01, 10_000.0))
    avg_depth_btc = float(_clip(float(avg_depth_btc), 0.01, 10_000.0))
    maker_fee = float(_clip(float(maker_fee), 0.0, 0.01))
    taker_fee = float(_clip(float(taker_fee), 0.0, 0.01))
    maker_timeout_sec = float(_clip(float(maker_timeout_sec), 0.0, 120.0))
    q = float(_clip(float(q), 0.50, 0.999))
    return {
        "execution": str(execution),
        "slip_mu": float(mu),
        "slip_beta": float(beta),
        "slip_alpha": float(alpha),
        "depth_threshold_btc": float(depth_th_btc),
        "avg_depth_btc": float(avg_depth_btc),
        "maker_fee": float(maker_fee),
        "taker_fee": float(taker_fee),
        "maker_timeout_sec": float(maker_timeout_sec),
        "slip_quantile": float(q),
    }


def _quant_pairs_btceth_margin_params() -> Dict[str, Any]:
    lev_raw = None
    try:
        lev_raw = CONFIG.get("quant_pairs_btceth_leverage")
    except Exception:
        lev_raw = None
    if lev_raw is None:
        try:
            lev_raw = CONFIG.get("quant_pairs_aster_leverage", 10)
        except Exception:
            lev_raw = 10
    try:
        leverage = int(lev_raw or 10)
    except Exception:
        leverage = 10
    try:
        imr = float(CONFIG.get("quant_pairs_btceth_imr", 1.0 / float(leverage)) or (1.0 / float(leverage)))
    except Exception:
        imr = 1.0 / float(max(1, int(leverage)))
    try:
        mmr = float(CONFIG.get("quant_pairs_btceth_mmr", float(imr) * 0.5) or (float(imr) * 0.5))
    except Exception:
        mmr = float(imr) * 0.5
    try:
        buffer_pct = float(CONFIG.get("quant_pairs_btceth_mmr_buffer", 0.05) or 0.05)
    except Exception:
        buffer_pct = 0.05
    try:
        reduce_trigger_frac = float(CONFIG.get("quant_pairs_btceth_reduce_trigger_frac", 0.8) or 0.8)
    except Exception:
        reduce_trigger_frac = 0.8
    try:
        reduce_frac = float(CONFIG.get("quant_pairs_btceth_reduce_frac", 0.5) or 0.5)
    except Exception:
        reduce_frac = 0.5
    leverage = _entry_hard_clip_leverage(leverage)
    imr = float(_clip(float(imr), 0.001, 1.0))
    mmr = float(_clip(float(mmr), 0.001, float(imr)))
    buffer_pct = float(_clip(float(buffer_pct), 0.0, 0.5))
    reduce_trigger_frac = float(_clip(float(reduce_trigger_frac), 0.0, 1.0))
    reduce_frac = float(_clip(float(reduce_frac), 0.0, 1.0))
    return {
        "leverage": int(leverage),
        "imr": float(imr),
        "mmr": float(mmr),
        "mmr_buffer": float(buffer_pct),
        "reduce_trigger_frac": float(reduce_trigger_frac),
        "reduce_frac": float(reduce_frac),
    }


def _quant_pairs_btceth_latest_spread_sigma(spread: List[Optional[float]], window_z: int) -> Optional[float]:
    w = int(max(2, int(window_z)))
    if not isinstance(spread, list) or len(spread) < w:
        return None
    i = len(spread) - 1
    beg = int(max(0, i - w + 1))
    sw = spread[beg : i + 1]
    if any((v is None) for v in sw):
        return None
    vals = [float(v) for v in sw if v is not None and math.isfinite(float(v))]
    if len(vals) < w:
        return None
    m = sum(vals) / float(w)
    vs = 0.0
    for v in vals:
        d = float(v) - float(m)
        vs += d * d
    ss = math.sqrt(max(vs / float(max(1, w - 1)), 0.0))
    if not math.isfinite(float(ss)) or float(ss) <= 0.0:
        return None
    return float(ss)


def _quant_pairs_btceth_cost_z_buffer(cost_est: Dict[str, Any], spread_sigma: Optional[float], z_cost_buffer_mult: Optional[float] = None) -> Dict[str, Any]:
    if not isinstance(cost_est, dict) or (not bool(cost_est.get("ok"))):
        return {"ok": False, "error": "cost_est_unavailable", "z": 0.0, "cost_total_rate": None}
    try:
        fee = float(cost_est.get("fee_rate") or 0.0)
    except Exception:
        fee = 0.0
    try:
        slip = float(cost_est.get("slippage_rate") or 0.0)
    except Exception:
        slip = 0.0
    fee = 0.0 if (not math.isfinite(float(fee))) else float(max(0.0, fee))
    slip = 0.0 if (not math.isfinite(float(slip))) else float(max(0.0, slip))
    cost_total = float(2.0 * (float(fee) + float(slip)))
    ss = (None if spread_sigma is None else float(spread_sigma))
    if ss is None or (not math.isfinite(float(ss))) or float(ss) <= 0.0:
        return {"ok": True, "z": 0.0, "cost_total_rate": float(cost_total), "spread_sigma": None}
    mult = None
    try:
        mult = float(z_cost_buffer_mult) if z_cost_buffer_mult is not None else float(CONFIG.get("quant_pairs_btceth_z_cost_buffer_mult", 1.0) or 1.0)
    except Exception:
        mult = 1.0
    mult = 1.0 if mult is None or (not math.isfinite(float(mult))) else float(_clip(float(mult), 0.0, 10.0))
    z = (float(cost_total) / float(ss)) * float(mult)
    if not math.isfinite(float(z)) or float(z) < 0.0:
        z = 0.0
    return {"ok": True, "z": float(z), "cost_total_rate": float(cost_total), "spread_sigma": float(ss)}


def _quant_pairs_rolling_pairstats_alt_btc(
    ts: List[int],
    btc_close: List[float],
    alt_close: List[float],
    window_ols: int,
    window_z: int,
) -> Dict[str, Any]:
    n = min(len(ts), len(btc_close), len(alt_close))
    if n <= 0:
        return {"ts": [], "spread": [], "z": [], "beta": [], "corr": []}

    x = [0.0] * n
    y = [0.0] * n
    for i in range(n):
        ap = float(alt_close[i])
        bp = float(btc_close[i])
        if ap > 0.0 and bp > 0.0:
            x[i] = float(math.log(bp))
            y[i] = float(math.log(ap))
        else:
            x[i] = float("nan")
            y[i] = float("nan")

    eps = 1e-12
    w_ols = int(max(2, window_ols))
    w_z = int(max(2, window_z))

    beta_smooth_enabled = True
    try:
        beta_smooth_enabled = bool(CONFIG.get("quant_pairs_beta_smooth_enabled", True))
    except Exception:
        beta_smooth_enabled = True
    try:
        beta_ewma_alpha = float(CONFIG.get("quant_pairs_beta_ewma_alpha", 0.2) or 0.2)
    except Exception:
        beta_ewma_alpha = 0.2
    beta_ewma_alpha = float(_clip(float(beta_ewma_alpha), 0.0, 1.0))
    try:
        beta_shrink = float(CONFIG.get("quant_pairs_beta_shrinkage", 0.1) or 0.1)
    except Exception:
        beta_shrink = 0.1
    beta_shrink = float(_clip(float(beta_shrink), 0.0, 1.0))
    try:
        beta_target = float(CONFIG.get("quant_pairs_beta_shrinkage_target", 1.0) or 1.0)
    except Exception:
        beta_target = 1.0
    beta_target = (float(beta_target) if math.isfinite(float(beta_target)) else 1.0)
    prev_beta_sm: Optional[float] = None

    spread: List[Optional[float]] = [None] * n
    beta: List[Optional[float]] = [None] * n
    corr: List[Optional[float]] = [None] * n
    for i in range(n):
        if i + 1 < w_ols:
            continue
        xw = x[i - w_ols + 1 : i + 1]
        yw = y[i - w_ols + 1 : i + 1]
        if any((not math.isfinite(v)) for v in xw) or any((not math.isfinite(v)) for v in yw):
            continue
        mx = sum(xw) / float(w_ols)
        my = sum(yw) / float(w_ols)
        vx = 0.0
        vy = 0.0
        cxy = 0.0
        for a, b in zip(xw, yw):
            dx = float(a) - float(mx)
            dy = float(b) - float(my)
            vx += dx * dx
            vy += dy * dy
            cxy += dx * dy
        if vx <= eps:
            continue
        bta_raw = float(cxy / max(vx, eps))
        bta = float(bta_raw)
        if bool(beta_smooth_enabled):
            if prev_beta_sm is None or (not math.isfinite(float(prev_beta_sm))):
                bta_sm = float(bta_raw)
            else:
                bta_sm = float(beta_ewma_alpha) * float(bta_raw) + (1.0 - float(beta_ewma_alpha)) * float(prev_beta_sm)
            if float(beta_shrink) > 0.0:
                bta_sm = (1.0 - float(beta_shrink)) * float(bta_sm) + float(beta_shrink) * float(beta_target)
            if math.isfinite(float(bta_sm)):
                prev_beta_sm = float(bta_sm)
                bta = float(bta_sm)
        alp = float(my - float(bta) * mx)
        s = float(y[i] - (alp + float(bta) * x[i]))
        beta[i] = float(bta)
        spread[i] = float(s)
        denom = math.sqrt(max(vx, eps) * max(vy, eps))
        corr[i] = float(cxy / denom) if denom > eps else 0.0

    z: List[Optional[float]] = [None] * n
    for i in range(n):
        if i + 1 < max(w_ols, w_z):
            continue
        sw = spread[i - w_z + 1 : i + 1]
        if any((v is None) for v in sw):
            continue
        vals = [float(v) for v in sw if v is not None]
        if len(vals) < w_z:
            continue
        ms = sum(vals) / float(w_z)
        vs = 0.0
        for v in vals:
            d = float(v) - float(ms)
            vs += d * d
        ss = math.sqrt(max(vs / float(max(1, w_z - 1)), 0.0))
        ss_eff = max(float(ss), eps)
        z[i] = float((float(spread[i]) - float(ms)) / ss_eff) if spread[i] is not None else None

    return {
        "ts": [int(t) for t in ts[:n]],
        "spread": [None if v is None else float(v) for v in spread],
        "z": [None if v is None else float(v) for v in z],
        "beta": [None if v is None else float(v) for v in beta],
        "corr": [None if v is None else float(v) for v in corr],
    }


def _quant_pairs_btceth_cojump_params() -> Dict[str, Any]:
    enabled = bool(CONFIG.get("quant_pairs_btceth_cojump_enabled", True))
    tf = str(CONFIG.get("quant_pairs_btceth_cojump_timeframe", "5m") or "5m").strip().lower() or "5m"
    try:
        window = int(CONFIG.get("quant_pairs_btceth_cojump_window", 288) or 288)
    except Exception:
        window = 288
    try:
        sigma = float(CONFIG.get("quant_pairs_btceth_cojump_sigma", 3.0) or 3.0)
    except Exception:
        sigma = 3.0
    try:
        cooldown_bars = int(CONFIG.get("quant_pairs_btceth_cojump_cooldown_bars", 12) or 12)
    except Exception:
        cooldown_bars = 12
    same_sign = bool(CONFIG.get("quant_pairs_btceth_cojump_same_sign", True))
    window = max(30, min(5000, int(window)))
    sigma = float(_clip(float(sigma), 0.5, 10.0))
    cooldown_bars = max(0, min(10_000, int(cooldown_bars)))
    return {
        "enabled": bool(enabled),
        "timeframe": str(tf),
        "window": int(window),
        "sigma": float(sigma),
        "cooldown_bars": int(cooldown_bars),
        "same_sign": bool(same_sign),
    }


def _quant_pairs_btceth_cojump_eval_series(
    tf: str,
    ts: List[int],
    btc_close: List[float],
    eth_close: List[float],
    cfg: Dict[str, Any],
    state: Dict[str, Any],
    now_ms: int,
) -> Dict[str, Any]:
    if not isinstance(cfg, dict) or (not bool(cfg.get("enabled"))):
        return {"ok": True, "enabled": False, "blocked": False, "triggered": False, "ts": int(now_ms)}
    n = min(len(ts), len(btc_close), len(eth_close))
    if n < 50:
        return {"ok": False, "enabled": True, "error": "not_enough_points", "n": int(n), "ts": int(now_ms)}

    bucket_ms = int(_hl_interval_to_ms(str(tf)))
    window = int(cfg.get("window") or 288)
    sigma_mult = float(cfg.get("sigma") or 3.0)
    same_sign = bool(cfg.get("same_sign"))
    cooldown_bars = int(cfg.get("cooldown_bars") or 0)

    btc_r: List[float] = [0.0] * n
    eth_r: List[float] = [0.0] * n
    for i in range(1, n):
        b0 = float(btc_close[i - 1])
        b1 = float(btc_close[i])
        e0 = float(eth_close[i - 1])
        e1 = float(eth_close[i])
        if b0 > 0.0 and b1 > 0.0:
            try:
                btc_r[i] = float(math.log(float(b1) / float(b0)))
            except Exception:
                btc_r[i] = 0.0
        if e0 > 0.0 and e1 > 0.0:
            try:
                eth_r[i] = float(math.log(float(e1) / float(e0)))
            except Exception:
                eth_r[i] = 0.0

    w = int(max(30, min(int(window), n - 1)))
    btc_tail = btc_r[-w:]
    eth_tail = eth_r[-w:]

    def _std(xs: List[float]) -> float:
        vs = [float(x) for x in xs if x is not None and math.isfinite(float(x))]
        if len(vs) < 2:
            return 0.0
        m = sum(vs) / float(len(vs))
        s2 = 0.0
        for x in vs:
            d = float(x) - float(m)
            s2 += d * d
        return math.sqrt(max(s2 / float(max(1, len(vs) - 1)), 0.0))

    btc_sig = float(_std(btc_tail))
    eth_sig = float(_std(eth_tail))
    thr_btc = float(sigma_mult) * float(btc_sig)
    thr_eth = float(sigma_mult) * float(eth_sig)

    rb = float(btc_r[-1])
    re = float(eth_r[-1])
    ok_thr = (abs(rb) >= float(thr_btc) if float(thr_btc) > 0.0 else False) and (abs(re) >= float(thr_eth) if float(thr_eth) > 0.0 else False)
    if ok_thr and bool(same_sign):
        ok_thr = bool(float(rb) * float(re) > 0.0)

    last_open = int(ts[-1])
    last_close = int(last_open) + int(bucket_ms)

    st = (state if isinstance(state, dict) else {})
    prev_until = 0
    try:
        prev_until = int(st.get("blocked_until_ms") or 0)
    except Exception:
        prev_until = 0

    triggered = bool(ok_thr)
    blocked_until = int(prev_until)
    if triggered and int(cooldown_bars) > 0:
        blocked_until = max(int(blocked_until), int(last_close) + int(cooldown_bars) * int(bucket_ms))
        try:
            st["blocked_until_ms"] = int(blocked_until)
            st["last_trigger_open_ms"] = int(last_open)
            st["last_trigger_close_ms"] = int(last_close)
            st["last_btc_r"] = float(rb)
            st["last_eth_r"] = float(re)
        except Exception:
            pass

    blocked = bool(int(now_ms) < int(blocked_until)) if int(blocked_until) > 0 else False
    return {
        "ok": True,
        "enabled": True,
        "timeframe": str(tf),
        "bucket_ms": int(bucket_ms),
        "window": int(w),
        "sigma": float(sigma_mult),
        "same_sign": bool(same_sign),
        "cooldown_bars": int(cooldown_bars),
        "triggered": bool(triggered),
        "blocked": bool(blocked),
        "blocked_until_ms": (int(blocked_until) if int(blocked_until) > 0 else None),
        "last": {
            "open_ms": int(last_open),
            "close_ms": int(last_close),
            "btc_logret": float(rb),
            "eth_logret": float(re),
            "btc_sigma": float(btc_sig),
            "eth_sigma": float(eth_sig),
            "thr_btc": float(thr_btc),
            "thr_eth": float(thr_eth),
        },
        "ts": int(now_ms),
    }


def _quant_pairs_btceth_cojump_eval(now_ms: int = None) -> Dict[str, Any]:
    t_now = int(_now_ms() if now_ms is None else now_ms)
    cfg = _quant_pairs_btceth_cojump_params()
    tf = str(cfg.get("timeframe") or "5m").strip().lower() or "5m"
    key = f"quant_pairs_btceth_cojump|{tf}"
    st = TRACKER_STATE.get(key)
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE[key] = st

    limit = int(cfg.get("window") or 288) + 5
    btc_ts, btc_close = _quant_pairs_close_series("BTC", tf, limit=int(limit))
    eth_ts, eth_close = _quant_pairs_close_series("ETH", tf, limit=int(limit))
    if not btc_ts or not eth_ts:
        return {"ok": False, "enabled": bool(cfg.get("enabled")), "error": "no_data", "ts": int(t_now)}

    i = 0
    j = 0
    ts: List[int] = []
    bc: List[float] = []
    ec: List[float] = []
    while i < len(btc_ts) and j < len(eth_ts):
        a = int(btc_ts[i])
        b = int(eth_ts[j])
        if a == b:
            ts.append(a)
            bc.append(float(btc_close[i]))
            ec.append(float(eth_close[j]))
            i += 1
            j += 1
            continue
        if a < b:
            i += 1
            continue
        j += 1

    return _quant_pairs_btceth_cojump_eval_series(tf=tf, ts=ts, btc_close=bc, eth_close=ec, cfg=cfg, state=st, now_ms=int(t_now))


def _quant_pairs_btceth_funding_snapshot(ts_ms: int, notional_btc: float, notional_eth: float) -> Dict[str, Any]:
    try:
        t = int(ts_ms)
    except Exception:
        t = 0
    try:
        nb = float(notional_btc)
    except Exception:
        nb = 0.0
    try:
        ne = float(notional_eth)
    except Exception:
        ne = 0.0
    if t <= 0 or (not math.isfinite(float(nb))) or (not math.isfinite(float(ne))):
        return {"ok": False, "error": "invalid_inputs"}
    if float(nb) < 0.0:
        nb = abs(float(nb))
    if float(ne) < 0.0:
        ne = abs(float(ne))

    try:
        fr_btc, _ = _hl_funding_at_ts("BTC", int(t))
        fr_eth, _ = _hl_funding_at_ts("ETH", int(t))
    except Exception as e:
        return {"ok": False, "error": str(e), "ts": int(t)}

    fr_btc = 0.0 if (not math.isfinite(float(fr_btc))) else float(fr_btc)
    fr_eth = 0.0 if (not math.isfinite(float(fr_eth))) else float(fr_eth)

    per_day_btc = float(fr_btc) * 24.0
    per_day_eth = float(fr_eth) * 24.0

    pnl_long_btc_short_eth = (-float(nb) * float(per_day_btc)) + (+float(ne) * float(per_day_eth))
    pnl_short_btc_long_eth = (+float(nb) * float(per_day_btc)) + (-float(ne) * float(per_day_eth))

    return {
        "ok": True,
        "ts": int(t),
        "rate": {
            "btc": float(fr_btc),
            "eth": float(fr_eth),
            "btc_per_day": float(per_day_btc),
            "eth_per_day": float(per_day_eth),
        },
        "notional_usdc": {"btc": float(nb), "eth": float(ne)},
        "pnl_per_day_usdc": {
            "long_btc_short_eth": float(pnl_long_btc_short_eth),
            "short_btc_long_eth": float(pnl_short_btc_long_eth),
        },
    }


def _quant_pairs_btceth_gumbel_quantile(mu: float, beta: float, q: float) -> float:
    qq = float(_clip(float(q), 1e-9, 1.0 - 1e-12))
    return float(mu) - float(beta) * math.log(-math.log(float(qq)))


def _quant_pairs_btceth_cost_estimate(notional_usdc: float, btc_px: float, cost: Dict[str, Any]) -> Dict[str, Any]:
    n = float(notional_usdc)
    px = float(btc_px)
    if (not math.isfinite(n)) or n <= 0.0 or (not math.isfinite(px)) or px <= 0.0:
        return {"ok": False, "error": "invalid_inputs"}

    try:
        size_btc = float(n) / float(px)
    except Exception:
        size_btc = float("nan")
    if not math.isfinite(size_btc) or size_btc <= 0:
        return {"ok": False, "error": "size_calc_failed"}

    th = float(cost.get("depth_threshold_btc") or 10.0)
    avg_depth = float(cost.get("avg_depth_btc") or th)
    alpha = float(cost.get("slip_alpha") or 0.5)
    mu = float(cost.get("slip_mu") or 0.0)
    beta = float(cost.get("slip_beta") or 1e-9)
    q = float(cost.get("slip_quantile") or 0.95)

    try:
        exec_mode = str(cost.get("execution") or "taker").strip().lower()
    except Exception:
        exec_mode = "taker"
    if exec_mode not in ("taker", "maker", "auto"):
        exec_mode = "taker"

    if exec_mode == "taker":
        use_maker = False
    elif exec_mode == "maker":
        use_maker = True
    else:
        use_maker = bool(size_btc < th)
    fee = float(cost.get("maker_fee") if use_maker else cost.get("taker_fee"))

    base_slip = float(_quant_pairs_btceth_gumbel_quantile(mu, beta, q))
    try:
        scale = (float(size_btc) / max(float(avg_depth), 1e-12)) ** float(alpha)
    except Exception:
        scale = 1.0
    scale = float(max(0.0, scale))
    slip = float(max(0.0, base_slip * scale))

    return {
        "ok": True,
        "notional_usdc": float(n),
        "btc_px": float(px),
        "size_btc": float(size_btc),
        "mode": ("maker" if use_maker else "taker"),
        "fee_rate": float(fee),
        "slippage_rate": float(slip),
        "slippage_rate_base": float(base_slip),
        "slippage_scale": float(scale),
        "maker_timeout_sec": float(cost.get("maker_timeout_sec") or 0.0),
    }


def _quant_pairs_btceth_adf_kpss_fallback(y: List[float], alpha_eff: float) -> Dict[str, Any]:
    vals = [float(v) for v in y if v is not None and math.isfinite(float(v))]
    n = len(vals)
    if n < 30:
        return {"ok": False, "error": "not_enough_points"}

    y0 = vals[:-1]
    y1 = vals[1:]
    dy = [float(b) - float(a) for a, b in zip(y0, y1)]

    x = y0
    T = len(dy)
    if T < 20:
        return {"ok": False, "error": "not_enough_points"}

    mx = sum(x) / float(T)
    my = sum(dy) / float(T)
    sxx = 0.0
    sxy = 0.0
    for a, b in zip(x, dy):
        dx0 = float(a) - float(mx)
        dy0 = float(b) - float(my)
        sxx += dx0 * dx0
        sxy += dx0 * dy0
    if sxx <= 1e-18:
        return {"ok": False, "error": "degenerate"}
    b1 = float(sxy / sxx)
    a1 = float(my - b1 * mx)

    sse = 0.0
    for a, b in zip(x, dy):
        e = float(b) - (float(a1) + float(b1) * float(a))
        sse += float(e) * float(e)
    dof = max(1, int(T - 2))
    se2 = float(sse) / float(dof)
    seb1 = math.sqrt(float(se2) / float(sxx)) if se2 > 0 else float("inf")
    t_stat = float(b1 / seb1) if seb1 > 0 and math.isfinite(seb1) else float("nan")

    if float(alpha_eff) <= 0.01:
        adf_crit = -3.43
        crit_key = "1%"
    elif float(alpha_eff) <= 0.025:
        adf_crit = -3.12
        crit_key = "2.5%"
    elif float(alpha_eff) <= 0.05:
        adf_crit = -2.86
        crit_key = "5%"
    else:
        adf_crit = -2.57
        crit_key = "10%"

    adf_pass = bool(math.isfinite(t_stat) and (float(t_stat) < float(adf_crit)))
    if not math.isfinite(t_stat):
        p_bucket = None
    elif float(t_stat) < -3.43:
        p_bucket = 0.01
    elif float(t_stat) < -2.86:
        p_bucket = 0.05
    elif float(t_stat) < -2.57:
        p_bucket = 0.10
    else:
        p_bucket = 0.20

    v = vals
    m = sum(v) / float(n)
    e = [float(x) - float(m) for x in v]
    s = 0.0
    S = []
    for r in e:
        s += float(r)
        S.append(float(s))
    eta = sum(float(z) * float(z) for z in S) / float(n * n)
    l = int(12.0 * ((float(n) / 100.0) ** 0.25))
    l = max(1, min(int(n // 2), l))
    gamma0 = sum(float(r) * float(r) for r in e) / float(n)
    s2 = float(gamma0)
    for j in range(1, int(l) + 1):
        gj = 0.0
        for t in range(j, n):
            gj += float(e[t]) * float(e[t - j])
        gj = float(gj) / float(n)
        w = 1.0 - float(j) / float(l + 1)
        s2 += 2.0 * float(w) * float(gj)
    kpss_stat = float(eta / max(float(s2), 1e-18))
    kpss_crit_table = {"10%": 0.347, "5%": 0.463, "2.5%": 0.574, "1%": 0.739}
    if float(alpha_eff) <= 0.01:
        kpss_crit = float(kpss_crit_table["1%"])
        kpss_key = "1%"
    elif float(alpha_eff) <= 0.025:
        kpss_crit = float(kpss_crit_table["2.5%"])
        kpss_key = "2.5%"
    elif float(alpha_eff) <= 0.05:
        kpss_crit = float(kpss_crit_table["5%"])
        kpss_key = "5%"
    else:
        kpss_crit = float(kpss_crit_table["10%"])
        kpss_key = "10%"
    kpss_pass = bool(math.isfinite(kpss_stat) and (float(kpss_stat) <= float(kpss_crit)))

    return {
        "ok": True,
        "adf": {
            "stat": (None if not math.isfinite(t_stat) else float(t_stat)),
            "p": (None if p_bucket is None else float(p_bucket)),
            "crit": {"1%": -3.43, "5%": -2.86, "10%": -2.57, "2.5%": -3.12},
            "crit_key": str(crit_key),
            "pass": bool(adf_pass),
        },
        "kpss": {
            "stat": (None if not math.isfinite(kpss_stat) else float(kpss_stat)),
            "p": None,
            "crit": dict(kpss_crit_table),
            "crit_key": str(kpss_key),
            "pass": bool(kpss_pass),
        },
    }


def _quant_pairs_btceth_stationarity_gate_eval(tf: str, ts: List[int], spread: List[Optional[float]], beta: List[Optional[float]] = None) -> Dict[str, Any]:
    now_ms = _now_ms()
    gate_cfg = _quant_pairs_btceth_gate_params()
    key = f"quant_pairs_btceth_gate|{str(tf).strip().lower()}"
    st = TRACKER_STATE.get(key)
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE[key] = st

    if not bool(gate_cfg.get("enabled")):
        out = {
            "ok": True,
            "enabled": False,
            "pass": True,
            "fail_count": 0,
            "k_fail": int(gate_cfg.get("k_fail") or 5),
            "alpha": float(gate_cfg.get("alpha") or 0.05),
            "test_count": int(gate_cfg.get("test_count") or 1),
            "alpha_eff": float(gate_cfg.get("alpha_eff") or 0.05),
            "ts": int(now_ms),
        }
        st["last"] = out
        return out

    if not ts or not spread:
        out = {
            "ok": False,
            "enabled": True,
            "pass": True,
            "valid": False,
            "error": "no_data",
            "fail_open": True,
            "fail_count": int(st.get("fail_count") or 0),
            "k_fail": int(gate_cfg.get("k_fail") or 5),
            "alpha": float(gate_cfg.get("alpha") or 0.05),
            "test_count": int(gate_cfg.get("test_count") or 1),
            "alpha_eff": float(gate_cfg.get("alpha_eff") or 0.05),
            "ts": int(now_ms),
        }
        st["last"] = out
        return out

    w = int(gate_cfg.get("window") or 240)
    if len(ts) < w or len(spread) < w:
        out = {
            "ok": False,
            "enabled": True,
            "pass": True,
            "valid": False,
            "error": "not_enough_bars",
            "fail_open": True,
            "fail_count": int(st.get("fail_count") or 0),
            "k_fail": int(gate_cfg.get("k_fail") or 5),
            "alpha": float(gate_cfg.get("alpha") or 0.05),
            "test_count": int(gate_cfg.get("test_count") or 1),
            "alpha_eff": float(gate_cfg.get("alpha_eff") or 0.05),
            "ts": int(now_ms),
        }
        st["last"] = out
        return out

    t_last = int(ts[-1] or 0)
    last_eval_ts = int(st.get("last_eval_ts") or 0)

    spread_w = spread[-w:]
    vals = [float(v) for v in spread_w if v is not None and math.isfinite(float(v))]
    if len(vals) < w:
        out = {
            "ok": False,
            "enabled": True,
            "pass": True,
            "valid": False,
            "error": "spread_unavailable",
            "fail_open": True,
            "fail_count": int(st.get("fail_count") or 0),
            "k_fail": int(gate_cfg.get("k_fail") or 5),
            "alpha": float(gate_cfg.get("alpha") or 0.05),
            "test_count": int(gate_cfg.get("test_count") or 1),
            "alpha_eff": float(gate_cfg.get("alpha_eff") or 0.05),
            "ts": int(now_ms),
            "bar_ts": int(t_last),
        }
        st["last"] = out
        return out

    beta_std = None
    half_life_bars = None
    phi = None
    structural_reasons: List[str] = []
    try:
        beta_std_max = None
        half_life_max_bars = None
        try:
            beta_std_max = float(gate_cfg.get("beta_std_max")) if gate_cfg.get("beta_std_max") is not None else None
        except Exception:
            beta_std_max = None
        try:
            half_life_max_bars = int(gate_cfg.get("half_life_max_bars")) if gate_cfg.get("half_life_max_bars") is not None else None
        except Exception:
            half_life_max_bars = None

        if isinstance(beta, list) and len(beta) >= w:
            bw = beta[-w:]
            bvals = []
            for v in bw:
                if v is None:
                    continue
                try:
                    u = float(v)
                except Exception:
                    continue
                if not math.isfinite(u):
                    continue
                u = float(_clip(float(u), -5.0, 5.0))
                bvals.append(float(u))
            min_n = max(30, int(w // 2))
            if len(bvals) >= min_n:
                mb = sum(bvals) / float(len(bvals))
                vb = 0.0
                for u in bvals:
                    d = float(u) - float(mb)
                    vb += d * d
                beta_std = float(math.sqrt(max(vb / float(max(1, len(bvals) - 1)), 0.0)))
                if beta_std_max is not None and math.isfinite(float(beta_std)) and float(beta_std) > float(beta_std_max):
                    structural_reasons.append("beta_std")

        if len(vals) >= 3:
            x0 = vals[:-1]
            x1 = vals[1:]
            m0 = sum(x0) / float(len(x0))
            m1 = sum(x1) / float(len(x1))
            v0 = 0.0
            c01 = 0.0
            for a, b in zip(x0, x1):
                da = float(a) - float(m0)
                db = float(b) - float(m1)
                v0 += da * da
                c01 += da * db
            if v0 > 1e-18:
                phi = float(c01 / float(v0))
                if math.isfinite(float(phi)):
                    if float(phi) >= 1.0:
                        half_life_bars = float("inf")
                    elif float(phi) <= 0.0:
                        half_life_bars = 1.0
                    else:
                        den = float(math.log(float(phi)))
                        if abs(float(den)) < 1e-18:
                            half_life_bars = float("inf")
                        else:
                            half_life_bars = float(-math.log(2.0) / float(den))

        if half_life_max_bars is not None and half_life_bars is not None and math.isfinite(float(half_life_bars)):
            if float(half_life_bars) > float(half_life_max_bars):
                structural_reasons.append("half_life")
        elif half_life_max_bars is not None and half_life_bars is not None and (not math.isfinite(float(half_life_bars))):
            structural_reasons.append("half_life")
    except Exception:
        beta_std = None
        half_life_bars = None
        phi = None
        structural_reasons = []

    def _vol_est(x: List[float]) -> float:
        if len(x) < 3:
            return 0.0
        d = [float(x[i]) - float(x[i - 1]) for i in range(1, len(x))]
        m = sum(d) / float(len(d))
        v = 0.0
        for r in d:
            u = float(r) - float(m)
            v += u * u
        return float(math.sqrt(max(v / float(max(1, len(d) - 1)), 0.0)))

    vol_cur = _vol_est(vals)
    vol_base = vol_cur
    if len(spread) >= w * 3:
        prev = spread[-w * 3 : -w]
        prev_vals = [float(v) for v in prev if v is not None and math.isfinite(float(v))]
        if len(prev_vals) >= max(30, w // 2):
            vol_base = _vol_est(prev_vals)

    hv_mult = float(gate_cfg.get("highvol_mult") or 1.5)
    is_highvol = bool(vol_base > 0 and (float(vol_cur) > float(vol_base) * float(hv_mult)))
    freq = int(gate_cfg.get("freq_bars_highvol") if is_highvol else gate_cfg.get("freq_bars"))
    freq = max(1, int(freq))

    if last_eval_ts > 0 and t_last > 0 and (int(t_last) - int(last_eval_ts)) < int(freq) * int(_hl_interval_to_ms(tf)):
        last = st.get("last")
        if isinstance(last, dict):
            out = dict(last)
            out["ts"] = int(now_ms)
            out["bar_ts"] = int(t_last)
            out["high_vol"] = bool(is_highvol)
            out["freq_bars"] = int(freq)
            return out

    alpha = float(gate_cfg.get("alpha") or 0.05)
    alpha_eff = float(gate_cfg.get("alpha_eff") or 0.05)
    test_count = int(gate_cfg.get("test_count") or 1)
    adf_out = None
    kpss_out = None

    if adfuller is not None and kpss is not None:
        try:
            adf_res = adfuller(vals, regression="c", autolag="AIC")
            adf_stat = float(adf_res[0])
            adf_p = float(adf_res[1])
            adf_crit = dict(adf_res[4] or {})
            adf_p_adj = float(min(1.0, float(adf_p) * float(test_count)))
            adf_pass = bool(math.isfinite(adf_p_adj) and (float(adf_p_adj) <= float(alpha)))
            adf_out = {
                "stat": float(adf_stat),
                "p": float(adf_p),
                "p_adj": float(adf_p_adj),
                "alpha": float(alpha),
                "alpha_eff": float(alpha_eff),
                "pass": bool(adf_pass),
                "crit": {str(k): float(v) for k, v in (adf_crit or {}).items()},
            }
        except Exception as e:
            adf_out = {"error": str(e)}

        try:
            kpss_res = kpss(vals, regression="c", nlags="auto")
            kpss_stat = float(kpss_res[0])
            kpss_p = float(kpss_res[1])
            kpss_crit = dict(kpss_res[3] or {})
            if float(alpha_eff) <= 0.01:
                key2 = "1%"
            elif float(alpha_eff) <= 0.025:
                key2 = "2.5%"
            elif float(alpha_eff) <= 0.05:
                key2 = "5%"
            else:
                key2 = "10%"
            kpss_cv = None
            try:
                kpss_cv = float(kpss_crit.get(key2))
            except Exception:
                kpss_cv = None
            kpss_pass = bool((kpss_cv is None) or (math.isfinite(kpss_cv) and math.isfinite(kpss_stat) and float(kpss_stat) <= float(kpss_cv)))
            kpss_out = {
                "stat": float(kpss_stat),
                "p": float(kpss_p),
                "alpha_eff": float(alpha_eff),
                "crit": {str(k): float(v) for k, v in (kpss_crit or {}).items()},
                "crit_key": str(key2),
                "crit_value": (None if kpss_cv is None else float(kpss_cv)),
                "pass": bool(kpss_pass),
            }
        except Exception as e:
            kpss_out = {"error": str(e)}
    else:
        fb = _quant_pairs_btceth_adf_kpss_fallback(vals, alpha_eff=float(alpha_eff))
        if bool(fb.get("ok")):
            adf_out = fb.get("adf")
            kpss_out = fb.get("kpss")
            if isinstance(adf_out, dict):
                p0 = adf_out.get("p")
                adf_p_adj = None
                if p0 is not None:
                    try:
                        adf_p_adj = float(min(1.0, float(p0) * float(test_count)))
                    except Exception:
                        adf_p_adj = None
                adf_out = dict(adf_out)
                adf_out["p_adj"] = adf_p_adj
                adf_out["alpha"] = float(alpha)
                adf_out["alpha_eff"] = float(alpha_eff)
                if adf_p_adj is not None:
                    try:
                        adf_out["pass"] = bool(float(adf_p_adj) <= float(alpha))
                    except Exception:
                        pass
        else:
            adf_out = {"error": str(fb.get("error") or "fallback_failed")}
            kpss_out = {"error": str(fb.get("error") or "fallback_failed")}

    adf_pass = bool(isinstance(adf_out, dict) and bool(adf_out.get("pass")))
    kpss_pass = bool(isinstance(kpss_out, dict) and bool(kpss_out.get("pass")))
    passed = bool(adf_pass and kpss_pass)

    fail_count = int(st.get("fail_count") or 0)
    if passed:
        fail_count = 0
    else:
        fail_count += 1
    st["fail_count"] = int(fail_count)
    st["last_eval_ts"] = int(t_last)

    log_key = f"{key}|log"
    log = TRACKER_STATE.get(log_key)
    if not isinstance(log, list):
        log = []
        TRACKER_STATE[log_key] = log

    structural_blocked = bool(structural_reasons)
    entry = {
        "ts": int(t_last),
        "adf_p": (None if not isinstance(adf_out, dict) else adf_out.get("p")),
        "adf_p_adj": (None if not isinstance(adf_out, dict) else adf_out.get("p_adj")),
        "adf_stat": (None if not isinstance(adf_out, dict) else adf_out.get("stat")),
        "kpss_stat": (None if not isinstance(kpss_out, dict) else kpss_out.get("stat")),
        "beta_std": (None if beta_std is None else float(beta_std)),
        "half_life_bars": (None if half_life_bars is None else (float(half_life_bars) if math.isfinite(float(half_life_bars)) else None)),
        "half_life_infinite": bool(half_life_bars is not None and (not math.isfinite(float(half_life_bars)))),
        "phi": (None if phi is None else float(phi)),
        "alpha": float(alpha),
        "alpha_eff": float(alpha_eff),
        "pass": bool(passed),
        "structural_blocked": bool(structural_blocked),
    }
    log.append(entry)
    if len(log) > 500:
        del log[:-500]

    fail_rate = None
    try:
        nlog = len(log)
        if nlog > 0:
            nf = sum(1 for x in log if isinstance(x, dict) and (not bool(x.get("pass"))))
            fail_rate = float(nf) / float(nlog)
    except Exception:
        fail_rate = None

    blocked_stationarity = bool((not passed) and (int(fail_count) >= int(gate_cfg.get("k_fail") or 5)))
    blocked_structural = bool(structural_blocked)
    blocked = bool(blocked_stationarity or blocked_structural)
    blocked_reason = None
    if blocked_structural:
        blocked_reason = "+".join(structural_reasons) if structural_reasons else "structural"
    elif blocked_stationarity:
        blocked_reason = "adf_kpss"
    out = {
        "ok": True,
        "enabled": True,
        "valid": True,
        "pass": bool(passed),
        "blocked": bool(blocked),
        "blocked_reason": blocked_reason,
        "fail_count": int(fail_count),
        "k_fail": int(gate_cfg.get("k_fail") or 5),
        "alpha": float(alpha),
        "test_count": int(test_count),
        "alpha_eff": float(alpha_eff),
        "adf": adf_out,
        "kpss": kpss_out,
        "struct": {
            "beta_std": (None if beta_std is None else float(beta_std)),
            "beta_std_max": (None if gate_cfg.get("beta_std_max") is None else float(gate_cfg.get("beta_std_max"))),
            "half_life_bars": (None if half_life_bars is None else (float(half_life_bars) if math.isfinite(float(half_life_bars)) else None)),
            "half_life_infinite": bool(half_life_bars is not None and (not math.isfinite(float(half_life_bars)))),
            "half_life_max_bars": (None if gate_cfg.get("half_life_max_bars") is None else int(gate_cfg.get("half_life_max_bars"))),
            "phi": (None if phi is None else float(phi)),
            "blocked": bool(blocked_structural),
            "reasons": list(structural_reasons),
        },
        "fail_rate": fail_rate,
        "ts": int(now_ms),
        "bar_ts": int(t_last),
        "high_vol": bool(is_highvol),
        "freq_bars": int(freq),
        "log_tail": list(log[-50:]),
    }
    st["last"] = out
    return out


def _quant_pairs_btceth_margin_status(open_positions: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    cfg = _quant_pairs_btceth_margin_params()
    mmr = float(cfg.get("mmr") or 0.10)
    trig = float(cfg.get("reduce_trigger_frac") or 0.8)
    reduce_frac = float(cfg.get("reduce_frac") or 0.5)
    out = {
        "ok": True,
        "cfg": dict(cfg),
        "recommend": "none",
        "reduce_frac": float(reduce_frac),
        "legs": {},
    }
    op = open_positions if isinstance(open_positions, dict) else None
    if op is None:
        op = TRACKER_STATE.get("open_positions")
    if not isinstance(op, dict):
        return out

    legs = {}
    for coin in ("BTC", "ETH"):
        k = f"{coin}-PERP"
        pos = op.get(k)
        if not isinstance(pos, dict):
            continue
        try:
            pnl_pct = float(pos.get("unrealized_pnl_pct") or 0.0)
        except Exception:
            pnl_pct = 0.0
        leg = {
            "pnl_pct": float(pnl_pct),
            "trigger": float(-float(mmr) * float(trig)),
            "pressure": bool(float(pnl_pct) <= -float(mmr) * float(trig)),
        }
        legs[coin] = leg
    out["legs"] = legs
    if any(bool(v.get("pressure")) for v in legs.values() if isinstance(v, dict)):
        out["recommend"] = "reduce"
    return out


def _quant_pairs_select_pair_file(pair: str, ts_ms: int = None) -> Optional[Path]:
    candidates = _find_pair_files(pair)
    if not candidates:
        return None

    want_futures = (":" in str(pair)) or (str(CONFIG.get("trading_mode") or "").lower() == "futures")
    ex_name = str(((CONFIG.get("exchange") or {}).get("name") if isinstance(CONFIG.get("exchange"), dict) else "") or "").lower()

    def _score_path(p: Path) -> int:
        s = 0
        ps = str(p).lower()
        if want_futures and "futures" in ps:
            s += 100
        if ps.endswith("-5m-futures.json"):
            s += 40
        if ex_name and ex_name in ps:
            s += 25
        if "/gateio/" in ps or "\\gateio\\" in ps:
            s += 5
        if "/gate/" in ps or "\\gate\\" in ps:
            s += 2
        if "/binance/" in ps or "\\binance\\" in ps:
            s += 1
        return int(s)

    candidates = sorted(candidates, key=lambda p: (-_score_path(p), str(p)))
    if ts_ms is None:
        return candidates[0]
    t = int(ts_ms)
    for p in candidates:
        key = str(p)
        cached = PAIR_CACHE.get(key)
        if cached and isinstance(cached.get("raw_ts"), list) and cached.get("raw_ts"):
            try:
                lo = int(cached["raw_ts"][0])
                hi = int(cached["raw_ts"][-1])
                if lo <= t <= hi:
                    return p
            except Exception:
                pass
        raw = _read_5m_rows(p)
        if not raw:
            continue
        try:
            lo = int(raw[0][0])
            hi = int(raw[-1][0])
            if lo <= t <= hi:
                return p
        except Exception:
            continue
    return candidates[0]


def _quant_pairs_close_series(
    pair: str,
    timeframe: str,
    limit: int = 800,
    force_aster: bool = False,
    allow_fallback: bool = True,
    disable_aster: bool = False,
) -> Tuple[List[int], List[float]]:
    tf = str(timeframe or "").strip().lower()
    if tf == "60m":
        tf = "1h"
    bucket_ms = int(_hl_interval_to_ms(tf))
    raw = None
    use_aster = bool(force_aster) and (not bool(disable_aster))
    if (not bool(use_aster)) and (not bool(disable_aster)):
        try:
            use_aster = bool(CONFIG.get("quant_pairs_aster_klines_enabled", True))
        except Exception:
            use_aster = True
    if use_aster:
        try:
            raw = _aster_klines_ohlcv_rows(pair, tf, limit=int(limit) + 10)
        except Exception:
            raw = None
    if (not raw) and (not bool(allow_fallback)):
        return [], []
    if not raw:
        p = _quant_pairs_select_pair_file(pair, ts_ms=_now_ms())
        if p is None:
            return [], []
        raw = _read_5m_rows(p)
        if not raw:
            return [], []
    rows = _resample_closed(raw, int(bucket_ms))
    if not rows:
        return [], []
    ts = [int(r[0]) for r in rows]
    cl = [float(r[4]) for r in rows]
    if int(limit) > 0 and len(ts) > int(limit):
        ts = ts[-int(limit):]
        cl = cl[-int(limit):]
    return ts, cl


def _quant_pairs_close_series_range(
    pair: str,
    timeframe: str,
    start_ts_ms: int = None,
    end_ts_ms: int = None,
    limit: int = 0,
    force_aster: bool = False,
    allow_fallback: bool = True,
    disable_aster: bool = False,
) -> Tuple[List[int], List[float]]:
    tf = str(timeframe or "").strip().lower()
    if tf == "60m":
        tf = "1h"
    bucket_ms = int(_hl_interval_to_ms(tf))
    raw = None
    use_aster = bool(force_aster) and (not bool(disable_aster))
    if (not bool(use_aster)) and (not bool(disable_aster)):
        try:
            use_aster = bool(CONFIG.get("quant_pairs_aster_klines_enabled", True))
        except Exception:
            use_aster = True
    if use_aster:
        try:
            raw = _aster_klines_ohlcv_rows(
                pair,
                tf,
                limit=(0 if int(limit) <= 0 else int(limit) + 10),
                start_ms=start_ts_ms,
                end_ms=end_ts_ms,
            )
        except Exception:
            raw = None
    if (not raw) and (not bool(allow_fallback)):
        return [], []
    if not raw:
        ts_pick = end_ts_ms if end_ts_ms is not None else start_ts_ms
        p = _quant_pairs_select_pair_file(pair, ts_ms=ts_pick)
        if p is None:
            return [], []
        raw = _read_5m_rows(p)
        if not raw:
            return [], []
    now_ms = None
    if end_ts_ms is not None:
        try:
            now_ms = int(end_ts_ms) + int(bucket_ms) + 1
        except Exception:
            now_ms = None
    rows = _resample_closed(raw, int(bucket_ms), now_ms=now_ms)
    if not rows:
        return [], []
    out = []
    st = None if start_ts_ms is None else int(start_ts_ms)
    et = None if end_ts_ms is None else int(end_ts_ms)
    for r in rows:
        try:
            t = int(r[0])
        except Exception:
            continue
        if st is not None and t < int(st):
            continue
        if et is not None and t > int(et):
            continue
        out.append(r)
    if int(limit) > 0 and len(out) > int(limit):
        out = out[-int(limit):]
    ts = [int(r[0]) for r in out]
    cl = [float(r[4]) for r in out]
    return ts, cl


def _quant_pairs_rolling_pairstats(
    ts: List[int],
    btc_close: List[float],
    eth_close: List[float],
    window_ols: int,
    window_z: int,
) -> Dict[str, Any]:
    n = min(len(ts), len(btc_close), len(eth_close))
    if n <= 0:
        return {"ts": [], "spread": [], "z": [], "beta": [], "corr": []}

    x = [0.0] * n
    y = [0.0] * n
    for i in range(n):
        bx = float(btc_close[i])
        ey = float(eth_close[i])
        if bx > 0.0 and ey > 0.0:
            x[i] = float(math.log(bx))
            y[i] = float(math.log(ey))
        else:
            x[i] = float("nan")
            y[i] = float("nan")

    eps = 1e-12
    w_ols = int(max(2, window_ols))
    w_z = int(max(2, window_z))

    beta_smooth_enabled = True
    try:
        beta_smooth_enabled = bool(CONFIG.get("quant_pairs_beta_smooth_enabled", True))
    except Exception:
        beta_smooth_enabled = True
    try:
        beta_ewma_alpha = float(CONFIG.get("quant_pairs_beta_ewma_alpha", 0.2) or 0.2)
    except Exception:
        beta_ewma_alpha = 0.2
    beta_ewma_alpha = float(_clip(float(beta_ewma_alpha), 0.0, 1.0))
    try:
        beta_shrink = float(CONFIG.get("quant_pairs_beta_shrinkage", 0.1) or 0.1)
    except Exception:
        beta_shrink = 0.1
    beta_shrink = float(_clip(float(beta_shrink), 0.0, 1.0))
    try:
        beta_target = float(CONFIG.get("quant_pairs_beta_shrinkage_target", 1.0) or 1.0)
    except Exception:
        beta_target = 1.0
    beta_target = (float(beta_target) if math.isfinite(float(beta_target)) else 1.0)
    prev_beta_sm: Optional[float] = None

    spread: List[Optional[float]] = [None] * n
    beta: List[Optional[float]] = [None] * n
    corr: List[Optional[float]] = [None] * n
    for i in range(n):
        if i + 1 < w_ols:
            continue
        xw = x[i - w_ols + 1 : i + 1]
        yw = y[i - w_ols + 1 : i + 1]
        if any((not math.isfinite(v)) for v in xw) or any((not math.isfinite(v)) for v in yw):
            continue
        mx = sum(xw) / float(w_ols)
        my = sum(yw) / float(w_ols)
        vx = 0.0
        vy = 0.0
        cxy = 0.0
        for a, b in zip(xw, yw):
            dx = float(a) - float(mx)
            dy = float(b) - float(my)
            vx += dx * dx
            vy += dy * dy
            cxy += dx * dy
        if vx <= eps:
            continue
        bta_raw = float(cxy / max(vx, eps))
        bta = float(bta_raw)
        if bool(beta_smooth_enabled):
            if prev_beta_sm is None or (not math.isfinite(float(prev_beta_sm))):
                bta_sm = float(bta_raw)
            else:
                bta_sm = float(beta_ewma_alpha) * float(bta_raw) + (1.0 - float(beta_ewma_alpha)) * float(prev_beta_sm)
            if float(beta_shrink) > 0.0:
                bta_sm = (1.0 - float(beta_shrink)) * float(bta_sm) + float(beta_shrink) * float(beta_target)
            if math.isfinite(float(bta_sm)):
                prev_beta_sm = float(bta_sm)
                bta = float(bta_sm)
        alp = float(my - float(bta) * mx)
        s = float(y[i] - (alp + float(bta) * x[i]))
        beta[i] = float(bta)
        spread[i] = float(s)
        denom = math.sqrt(max(vx, eps) * max(vy, eps))
        corr[i] = float(cxy / denom) if denom > eps else 0.0

    z: List[Optional[float]] = [None] * n
    for i in range(n):
        if i + 1 < max(w_ols, w_z):
            continue
        sw = spread[i - w_z + 1 : i + 1]
        if any((v is None) for v in sw):
            continue
        vals = [float(v) for v in sw if v is not None]
        if len(vals) < w_z:
            continue
        ms = sum(vals) / float(w_z)
        vs = 0.0
        for v in vals:
            d = float(v) - float(ms)
            vs += d * d
        ss = math.sqrt(max(vs / float(max(1, w_z - 1)), 0.0))
        ss_eff = max(float(ss), eps)
        z[i] = float((float(spread[i]) - float(ms)) / ss_eff) if spread[i] is not None else None

    return {
        "ts": [int(t) for t in ts[:n]],
        "spread": [None if v is None else float(v) for v in spread],
        "z": [None if v is None else float(v) for v in z],
        "beta": [None if v is None else float(v) for v in beta],
        "corr": [None if v is None else float(v) for v in corr],
    }


def _quant_pairs_btceth_simulate(
    ts: List[int],
    btc_close: List[float],
    eth_close: List[float],
    params: Dict[str, Any],
    notional_btc_usdc: float = 100.0,
    funding_mean_8h_btc: float = 0.0,
    funding_mean_8h_eth: float = 0.0,
    apply_cost: bool = True,
) -> Dict[str, Any]:
    n = min(len(ts), len(btc_close), len(eth_close))
    if n <= 0:
        return {"ok": False, "error": "no_data"}

    p = dict(params or {})
    try:
        window_ols = int(p.get("window_ols") or 240)
    except Exception:
        window_ols = 240
    try:
        window_z = int(p.get("window_z") or 240)
    except Exception:
        window_z = 240
    try:
        entry_z = float(p.get("entry_z") or 2.0)
    except Exception:
        entry_z = 2.0
    try:
        entry_z_long = float(p.get("entry_z_long")) if p.get("entry_z_long") is not None else None
    except Exception:
        entry_z_long = None
    try:
        entry_z_short = float(p.get("entry_z_short")) if p.get("entry_z_short") is not None else None
    except Exception:
        entry_z_short = None
    try:
        exit_z = float(p.get("exit_z") or 0.5)
    except Exception:
        exit_z = 0.5
    try:
        stop_z = float(p.get("stop_z") or 4.0)
    except Exception:
        stop_z = 4.0
    try:
        corr_min = float(p.get("corr_min") or 0.8)
    except Exception:
        corr_min = 0.8
    try:
        max_hold_bars = int(p.get("max_hold_bars") or 240)
    except Exception:
        max_hold_bars = 240

    try:
        z_exit_confirm_bars = int(p.get("z_exit_confirm_bars") or 1)
    except Exception:
        z_exit_confirm_bars = 1
    z_exit_confirm_bars = int(max(1, min(10, int(z_exit_confirm_bars))))

    window_ols = max(10, min(5000, int(window_ols)))
    window_z = max(10, min(5000, int(window_z)))
    entry_z = float(_clip(float(entry_z), 0.1, 10.0))
    if entry_z_long is None or (not math.isfinite(float(entry_z_long))):
        entry_z_long = float(entry_z)
    if entry_z_short is None or (not math.isfinite(float(entry_z_short))):
        entry_z_short = float(entry_z)
    entry_z_long = float(_clip(float(entry_z_long), 0.1, 10.0))
    entry_z_short = float(_clip(float(entry_z_short), 0.1, 10.0))
    entry_z_min = float(min(float(entry_z_long), float(entry_z_short)))
    entry_z_max = float(max(float(entry_z_long), float(entry_z_short)))
    exit_z = float(_clip(float(exit_z), 0.0, float(entry_z_min)))
    stop_z = float(_clip(float(stop_z), float(entry_z_max), 20.0))
    corr_min = float(_clip(float(corr_min), 0.0, 0.999))
    max_hold_bars = max(1, min(20000, int(max_hold_bars)))

    stats = _quant_pairs_rolling_pairstats(ts=ts[:n], btc_close=btc_close[:n], eth_close=eth_close[:n], window_ols=int(window_ols), window_z=int(window_z))
    z = list(stats.get("z") or [])
    beta = list(stats.get("beta") or [])
    corr = list(stats.get("corr") or [])
    spread = list(stats.get("spread") or [])
    ts2 = list(stats.get("ts") or [])

    if not ts2:
        return {"ok": False, "error": "stats_empty"}

    try:
        bar_ms = int(ts2[1]) - int(ts2[0]) if len(ts2) > 1 else int(_hl_interval_to_ms(str(p.get("timeframe") or "1h")))
    except Exception:
        bar_ms = int(_hl_interval_to_ms(str(p.get("timeframe") or "1h")))
    bar_h = float(bar_ms) / 3_600_000.0 if bar_ms > 0 else 0.0
    fr_btc_per_h = float(funding_mean_8h_btc) / 8.0
    fr_eth_per_h = float(funding_mean_8h_eth) / 8.0

    cost_params = None
    try:
        cost_params = _quant_pairs_btceth_cost_params()
    except Exception:
        cost_params = None

    def _sigma_at(i: int) -> Optional[float]:
        if i + 1 < int(window_z):
            return None
        sw = spread[i - int(window_z) + 1 : i + 1]
        if any(v is None for v in sw):
            return None
        vals = [float(v) for v in sw if v is not None]
        if len(vals) < int(window_z):
            return None
        m = sum(vals) / float(len(vals))
        vv = 0.0
        for v in vals:
            d = float(v) - float(m)
            vv += d * d
        ss = math.sqrt(max(vv / float(max(1, len(vals) - 1)), 0.0))
        return float(ss) if math.isfinite(float(ss)) and float(ss) > 0.0 else None

    pos = None
    trades = []
    cum = 0.0
    curve = []

    for i in range(max(int(window_ols), int(window_z)), len(ts2)):
        zi = z[i] if i < len(z) else None
        if zi is None or (not math.isfinite(float(zi))):
            continue
        ci = corr[i] if i < len(corr) else None
        if ci is None or (not math.isfinite(float(ci))):
            ci = 0.0
        if pos is None and float(ci) < float(corr_min):
            continue

        sigma = _sigma_at(i)
        z_cost = 0.0
        if bool(apply_cost) and sigma is not None and isinstance(cost_params, dict):
            try:
                btc_px = float(btc_close[i])
                btmp = beta[i] if i < len(beta) else None
                beta_abs_tmp = 1.0
                try:
                    beta_abs_tmp = abs(float(btmp)) if btmp is not None else 1.0
                except Exception:
                    beta_abs_tmp = 1.0
                beta_abs_tmp = float(_clip(float(beta_abs_tmp), 0.2, 5.0))
                btc_leg_notional = float(notional_btc_usdc) * float(beta_abs_tmp)
                est = _quant_pairs_btceth_cost_estimate(notional_usdc=float(btc_leg_notional), btc_px=float(btc_px), cost=dict(cost_params))
                buf = _quant_pairs_btceth_cost_z_buffer(cost_est=(est if isinstance(est, dict) else {}), spread_sigma=sigma, z_cost_buffer_mult=float(p.get("z_cost_buffer_mult") or 1.0))
                if isinstance(buf, dict) and bool(buf.get("ok")):
                    z_cost = float(buf.get("z") or 0.0)
            except Exception:
                z_cost = 0.0
        z_cost = 0.0 if (not math.isfinite(float(z_cost))) else float(max(0.0, z_cost))
        entry_z_eff_long = float(_clip(float(entry_z_long) + float(z_cost), 0.05, 50.0))
        entry_z_eff_short = float(_clip(float(entry_z_short) + float(z_cost), 0.05, 50.0))
        entry_z_eff = float(min(float(entry_z_eff_long), float(entry_z_eff_short)))
        exit_z_eff = float(_clip(float(exit_z) - float(z_cost), 0.0, 50.0))

        if pos is None:
            direction = None
            if float(zi) >= float(entry_z_eff_long):
                direction = "long_btc_short_eth"
            elif float(zi) <= -float(entry_z_eff_short):
                direction = "short_btc_long_eth"
            if direction is None:
                continue
            b = beta[i] if i < len(beta) else None
            beta_abs = 1.0
            try:
                beta_abs = abs(float(b)) if b is not None else 1.0
            except Exception:
                beta_abs = 1.0
            beta_abs = float(_clip(float(beta_abs), 0.2, 5.0))
            pos = {
                "dir": direction,
                "i0": int(i),
                "t0": int(ts2[i]),
                "btc0": float(btc_close[i]),
                "eth0": float(eth_close[i]),
                "beta_abs": float(beta_abs),
                "entry_z_eff": float(entry_z_eff),
                "entry_z_eff_long": float(entry_z_eff_long),
                "entry_z_eff_short": float(entry_z_eff_short),
                "exit_z_eff": float(exit_z_eff),
                "z_cost": float(z_cost),
                "entry_z": float(zi),
                "corr": float(ci),
            }
            continue

        hold_bars = int(i) - int(pos.get("i0") or 0)
        do_exit = False
        reason = ""
        if abs(float(zi)) >= float(stop_z):
            do_exit = True
            reason = "z_stop"
        elif hold_bars >= int(max_hold_bars):
            do_exit = True
            reason = "max_hold_exceeded"
        elif abs(float(zi)) <= float(exit_z_eff):
            do_exit = True
            reason = "z_exit"
        if not bool(do_exit):
            continue

        base_notional = float(notional_btc_usdc)
        nb = float(base_notional) * float(pos.get("beta_abs") or 1.0)
        ne = float(base_notional)
        px_btc0 = float(pos.get("btc0") or 0.0)
        px_eth0 = float(pos.get("eth0") or 0.0)
        px_btc1 = float(btc_close[i])
        px_eth1 = float(eth_close[i])
        if px_btc0 <= 0.0 or px_eth0 <= 0.0 or px_btc1 <= 0.0 or px_eth1 <= 0.0:
            pos = None
            continue

        r_btc = float(px_btc1 / px_btc0 - 1.0)
        r_eth = float(px_eth1 / px_eth0 - 1.0)
        if str(pos.get("dir")) == "short_btc_long_eth":
            pnl_gross = (-float(nb) * float(r_btc)) + (+float(ne) * float(r_eth))
            fund = (+float(nb) * float(fr_btc_per_h) - float(ne) * float(fr_eth_per_h)) * float(max(0.0, bar_h * float(hold_bars)))
        else:
            pnl_gross = (+float(nb) * float(r_btc)) + (-float(ne) * float(r_eth))
            fund = (-float(nb) * float(fr_btc_per_h) + float(ne) * float(fr_eth_per_h)) * float(max(0.0, bar_h * float(hold_bars)))

        cost_abs = 0.0
        if bool(apply_cost) and isinstance(cost_params, dict):
            try:
                btc_px = float(px_btc0)
                est = _quant_pairs_btceth_cost_estimate(notional_usdc=float(notional_btc_usdc), btc_px=float(btc_px), cost=dict(cost_params))
                if isinstance(est, dict) and bool(est.get("ok")):
                    rt = 2.0 * (float(est.get("fee_rate") or 0.0) + float(est.get("slippage_rate") or 0.0))
                    cost_abs = float((float(nb) + float(ne)) * float(max(0.0, rt)))
            except Exception:
                cost_abs = 0.0

        pnl_net = float(pnl_gross) - float(cost_abs) + float(fund)
        cum += float(pnl_net)
        curve.append({"t": int(ts2[i]), "cum": float(cum)})
        trades.append({
            "dir": str(pos.get("dir")),
            "t0": int(pos.get("t0")),
            "t1": int(ts2[i]),
            "i0": int(pos.get("i0")),
            "i1": int(i),
            "hold_bars": int(hold_bars),
            "entry_z": float(pos.get("entry_z") or 0.0),
            "exit_z": float(zi),
            "entry_z_eff": float(pos.get("entry_z_eff") or 0.0),
            "exit_z_eff": float(pos.get("exit_z_eff") or 0.0),
            "z_cost": float(pos.get("z_cost") or 0.0),
            "pnl_gross": float(pnl_gross),
            "pnl_cost": float(cost_abs),
            "pnl_funding": float(fund),
            "pnl_net": float(pnl_net),
            "reason": str(reason),
        })
        pos = None

    rets = [float(t.get("pnl_net") or 0.0) for t in trades]
    ntr = len(rets)
    mean = float(sum(rets) / float(ntr)) if ntr > 0 else 0.0
    var = 0.0
    if ntr > 1:
        for r in rets:
            d = float(r) - float(mean)
            var += d * d
        var = float(var / float(ntr - 1))
    sd = math.sqrt(float(var)) if var > 0 else 0.0
    sharpe = float(mean / sd * math.sqrt(float(ntr))) if sd > 1e-12 and ntr > 1 else 0.0
    wins = sum(1 for r in rets if float(r) > 0.0)
    win_rate = float(wins) / float(ntr) if ntr > 0 else 0.0

    peak = 0.0
    dd = 0.0
    cur = 0.0
    for r in rets:
        cur += float(r)
        if cur > peak:
            peak = float(cur)
        dd = min(float(dd), float(cur - peak))
    max_dd = float(-dd)

    return {
        "ok": True,
        "trades": trades,
        "metrics": {
            "trades": int(ntr),
            "net_pnl": float(sum(rets)),
            "net_sharpe": float(sharpe),
            "win_rate": float(win_rate),
            "max_drawdown": float(max_dd),
            "mean_trade_pnl": float(mean),
        },
        "equity_curve": curve,
    }


def _quant_pairs_btceth_wfo_run(
    ts: List[int],
    btc_close: List[float],
    eth_close: List[float],
    base_params: Dict[str, Any],
    grid: Dict[str, Any],
    is_bars: int,
    oos_bars: int,
    step_bars: int,
    embargo_bars: int,
    plateau_min_frac: float = 0.6,
    plateau_tol: float = 0.1,
) -> Dict[str, Any]:
    n = min(len(ts), len(btc_close), len(eth_close))
    if n <= 0:
        return {"ok": False, "error": "no_data"}
    is_bars = max(50, min(200000, int(is_bars)))
    oos_bars = max(10, min(200000, int(oos_bars)))
    step_bars = max(1, min(200000, int(step_bars)))
    embargo_bars = max(0, min(200000, int(embargo_bars)))
    plateau_min_frac = float(_clip(float(plateau_min_frac), 0.0, 1.0))
    plateau_tol = float(_clip(float(plateau_tol), 0.0, 5.0))

    def _grid_values(spec: Any) -> List[Any]:
        if spec is None:
            return []
        if isinstance(spec, dict):
            if "values" in spec:
                return list(spec.get("values") or [])
            if all(k in spec for k in ("start", "stop", "step")):
                try:
                    a = float(spec.get("start"))
                    b = float(spec.get("stop"))
                    s = float(spec.get("step"))
                except Exception:
                    return []
                if (not math.isfinite(a)) or (not math.isfinite(b)) or (not math.isfinite(s)) or s <= 0:
                    return []
                vals = []
                v = float(a)
                while v <= float(b) + 1e-12 and len(vals) < 5000:
                    vals.append(float(v))
                    v += float(s)
                return vals
        if isinstance(spec, (list, tuple)):
            return list(spec)
        return [spec]

    keys = [str(k) for k in (grid or {}).keys()]
    vals_by_key = {k: _grid_values((grid or {}).get(k)) for k in keys}
    keys = [k for k in keys if vals_by_key.get(k)]

    def _enumerate(ix: int, cur: Dict[str, Any], out: List[Dict[str, Any]]):
        if ix >= len(keys):
            out.append(dict(cur))
            return
        k = keys[ix]
        for v in vals_by_key.get(k, []):
            cur[k] = v
            _enumerate(ix + 1, cur, out)

    def _score_map_for_slice(a: int, b: int) -> Dict[str, Any]:
        combos = []
        _enumerate(0, {}, combos)
        score_map: Dict[str, Any] = {}
        best_key = None
        best_score = None
        for c in combos:
            pp = dict(base_params or {})
            pp.update(c)
            if ("entry_z" in c) and ("entry_z_long" not in c) and ("entry_z_short" not in c):
                try:
                    ez = float(pp.get("entry_z") or 0.0)
                    if math.isfinite(float(ez)):
                        pp["entry_z_long"] = float(ez)
                        pp["entry_z_short"] = float(ez)
                except Exception:
                    pass
            try:
                if float(pp.get("exit_z") or 0.0) > float(pp.get("entry_z") or 0.0):
                    continue
            except Exception:
                pass
            sim = _quant_pairs_btceth_simulate(ts[a:b], btc_close[a:b], eth_close[a:b], pp)
            if not isinstance(sim, dict) or (not bool(sim.get("ok"))):
                continue
            met = sim.get("metrics") if isinstance(sim.get("metrics"), dict) else {}
            sc = float(met.get("net_sharpe") or 0.0)
            key = "|".join([f"{k}={pp.get(k)}" for k in keys])
            score_map[key] = {"params": dict(pp), "score": float(sc), "metrics": dict(met)}
            if best_score is None or float(sc) > float(best_score):
                best_score = float(sc)
                best_key = str(key)
        return {"scores": score_map, "best_key": best_key, "best_score": best_score}

    def _pick_plateau(score_pack: Dict[str, Any]) -> Dict[str, Any]:
        scores = score_pack.get("scores") if isinstance(score_pack.get("scores"), dict) else {}
        best_key = score_pack.get("best_key")
        best_score = score_pack.get("best_score")
        if best_key is None or best_key not in scores:
            return {"best": None, "plateau": None}
        try:
            best_score_f = float(best_score) if best_score is not None else float((scores.get(best_key) or {}).get("score") or 0.0)
        except Exception:
            best_score_f = float((scores.get(best_key) or {}).get("score") or 0.0)
        tol = float(abs(best_score_f) * float(plateau_tol))
        good_thr = float(best_score_f) - float(tol)
        plateau_keys = []
        for k0, row in scores.items():
            try:
                if float((row or {}).get("score") or 0.0) >= float(good_thr):
                    plateau_keys.append(str(k0))
            except Exception:
                continue
        if not plateau_keys:
            return {"best": dict(scores.get(best_key) or {}), "plateau": None}
        chosen = None
        chosen_score = None
        for k0 in plateau_keys:
            row = scores.get(k0) or {}
            p0 = row.get("params") if isinstance(row.get("params"), dict) else {}
            neigh = 0
            good = 0
            for k1, row1 in scores.items():
                p1 = row1.get("params") if isinstance(row1.get("params"), dict) else {}
                diff = 0
                for kk in keys:
                    if kk not in p0 or kk not in p1:
                        continue
                    if str(p0.get(kk)) != str(p1.get(kk)):
                        diff += 1
                if diff == 1:
                    neigh += 1
                    try:
                        if float((row1 or {}).get("score") or 0.0) >= float(good_thr):
                            good += 1
                    except Exception:
                        pass
            frac = float(good) / float(neigh) if neigh > 0 else 0.0
            if neigh > 0 and frac + 1e-12 < float(plateau_min_frac):
                continue
            sc = float(row.get("score") or 0.0)
            if chosen_score is None or float(sc) > float(chosen_score):
                chosen_score = float(sc)
                chosen = dict(row)
        if chosen is None:
            chosen = dict(scores.get(best_key) or {})
        return {"best": dict(scores.get(best_key) or {}), "plateau": chosen}

    folds = []
    start = 0
    while int(start) + int(is_bars) + int(embargo_bars) + int(oos_bars) <= int(n):
        tr_a = int(start)
        tr_b = int(start) + int(is_bars)
        te_a = int(tr_b) + int(embargo_bars)
        te_b = int(te_a) + int(oos_bars)
        pack = _score_map_for_slice(tr_a, tr_b)
        pick = _pick_plateau(pack)
        chosen = pick.get("plateau") if isinstance(pick.get("plateau"), dict) else pick.get("best")
        chosen_params = (chosen.get("params") if isinstance(chosen, dict) else None)
        if not isinstance(chosen_params, dict):
            start += int(step_bars)
            continue
        oos_sim = _quant_pairs_btceth_simulate(ts[te_a:te_b], btc_close[te_a:te_b], eth_close[te_a:te_b], chosen_params)
        folds.append({
            "train": {"a": int(tr_a), "b": int(tr_b), "ts0": int(ts[tr_a]), "ts1": int(ts[tr_b - 1])},
            "oos": {"a": int(te_a), "b": int(te_b), "ts0": int(ts[te_a]), "ts1": int(ts[te_b - 1])},
            "selected": {
                "mode": ("plateau" if isinstance(pick.get("plateau"), dict) else "best"),
                "params": dict(chosen_params),
                "train": {"score": float((chosen or {}).get("score") or 0.0), "metrics": dict((chosen or {}).get("metrics") or {})},
            },
            "oos_result": (oos_sim if isinstance(oos_sim, dict) else {"ok": False, "error": "oos_failed"}),
        })
        start += int(step_bars)

    oos_scores = []
    oos_pnl = []
    oos_win = []
    for f in folds:
        met = (((f.get("oos_result") or {}).get("metrics") or {}) if isinstance(f.get("oos_result"), dict) else {})
        try:
            oos_scores.append(float(met.get("net_sharpe") or 0.0))
        except Exception:
            pass
        try:
            oos_pnl.append(float(met.get("net_pnl") or 0.0))
        except Exception:
            pass
        try:
            oos_win.append(float(met.get("win_rate") or 0.0))
        except Exception:
            pass
    oos_score_mean = float(sum(oos_scores) / float(len(oos_scores))) if oos_scores else 0.0
    oos_pnl_sum = float(sum(oos_pnl)) if oos_pnl else 0.0
    oos_win_mean = float(sum(oos_win) / float(len(oos_win))) if oos_win else 0.0

    return {
        "ok": True,
        "folds": folds,
        "summary": {
            "folds": int(len(folds)),
            "oos_net_sharpe_mean": float(oos_score_mean),
            "oos_net_pnl_sum": float(oos_pnl_sum),
            "oos_win_rate_mean": float(oos_win_mean),
        },
    }


def _quant_pairs_btceth_wfo_config(tf: str) -> Dict[str, Any]:
    timeframe = str(tf or "1h").strip().lower() or "1h"
    if timeframe == "60m":
        timeframe = "1h"

    def _duration_to_bars(dur: Any, default_bars: int) -> int:
        if dur is None:
            return int(default_bars)
        if isinstance(dur, (int, float)):
            v = int(dur)
            return int(v) if v > 0 else int(default_bars)
        s = str(dur).strip().lower()
        if not s:
            return int(default_bars)
        try:
            v = int(float(s))
            if v > 0:
                return int(v)
        except Exception:
            pass
        num = None
        unit = ""
        i = 0
        while i < len(s) and (s[i].isdigit() or s[i] in (".",)):
            i += 1
        try:
            num = float(s[:i]) if i > 0 else None
        except Exception:
            num = None
        unit = s[i:].strip() if i < len(s) else ""
        if num is None or (not math.isfinite(float(num))) or float(num) <= 0.0:
            return int(default_bars)
        ms_per_bar = int(_hl_interval_to_ms(timeframe))
        if ms_per_bar <= 0:
            return int(default_bars)
        mul_ms = None
        if unit in ("ms", "msec"):
            mul_ms = 1.0
        elif unit in ("s", "sec", "secs"):
            mul_ms = 1000.0
        elif unit in ("m", "min", "mins"):
            mul_ms = 60_000.0
        elif unit in ("h", "hr", "hrs"):
            mul_ms = 3_600_000.0
        elif unit in ("d", "day", "days"):
            mul_ms = 86_400_000.0
        elif unit in ("w", "wk", "wks", "week", "weeks"):
            mul_ms = 7.0 * 86_400_000.0
        elif unit in ("mo", "mon", "month", "months"):
            mul_ms = 30.0 * 86_400_000.0
        elif unit in ("y", "yr", "yrs", "year", "years"):
            mul_ms = 365.0 * 86_400_000.0
        if mul_ms is None:
            return int(default_bars)
        bars = int(round((float(num) * float(mul_ms)) / float(ms_per_bar)))
        return int(bars) if bars > 0 else int(default_bars)

    enabled = bool(CONFIG.get("quant_pairs_btceth_wfo_enabled", False))
    apply_selected = bool(CONFIG.get("quant_pairs_btceth_wfo_apply", False))

    try:
        refresh_sec = float(CONFIG.get("quant_pairs_btceth_wfo_refresh_sec", 3600.0) or 3600.0)
    except Exception:
        refresh_sec = 3600.0
    refresh_sec = float(_clip(float(refresh_sec), 0.0, 7.0 * 24.0 * 3600.0))

    try:
        plateau_min_frac = float(CONFIG.get("quant_pairs_btceth_wfo_plateau_min_frac", 0.6) or 0.6)
    except Exception:
        plateau_min_frac = 0.6
    try:
        plateau_tol = float(CONFIG.get("quant_pairs_btceth_wfo_plateau_tol", 0.1) or 0.1)
    except Exception:
        plateau_tol = 0.1
    plateau_min_frac = float(_clip(float(plateau_min_frac), 0.0, 1.0))
    plateau_tol = float(_clip(float(plateau_tol), 0.0, 5.0))

    try:
        is_bars = int(CONFIG.get("quant_pairs_btceth_wfo_is_bars", 480) or 480)
    except Exception:
        is_bars = 480
    try:
        oos_bars = int(CONFIG.get("quant_pairs_btceth_wfo_oos_bars", 240) or 240)
    except Exception:
        oos_bars = 240
    try:
        step_bars = int(CONFIG.get("quant_pairs_btceth_wfo_step_bars", 240) or 240)
    except Exception:
        step_bars = 240
    try:
        embargo_bars = int(CONFIG.get("quant_pairs_btceth_wfo_embargo_bars", 0) or 0)
    except Exception:
        embargo_bars = 0

    is_bars = _duration_to_bars(CONFIG.get("quant_pairs_btceth_wfo_is_duration"), int(is_bars))
    oos_bars = _duration_to_bars(CONFIG.get("quant_pairs_btceth_wfo_oos_duration"), int(oos_bars))
    step_bars = _duration_to_bars(CONFIG.get("quant_pairs_btceth_wfo_step_duration"), int(step_bars))
    embargo_bars = _duration_to_bars(CONFIG.get("quant_pairs_btceth_wfo_embargo_duration"), int(embargo_bars))

    is_bars = max(50, min(200000, int(is_bars)))
    oos_bars = max(10, min(200000, int(oos_bars)))
    step_bars = max(1, min(200000, int(step_bars)))
    embargo_bars = max(0, min(200000, int(embargo_bars)))

    grid = CONFIG.get("quant_pairs_btceth_wfo_grid")
    if isinstance(grid, str):
        try:
            grid = json.loads(grid)
        except Exception:
            grid = None
    if not isinstance(grid, dict):
        grid = {
            "entry_z": {"values": [1.2, 1.4, 1.6, 1.8, 2.0]},
            "exit_z": {"values": [0.3, 0.5, 0.7]},
            "window_ols": {"values": [120, 240]},
            "window_z": {"values": [120, 240]},
            "corr_min": {"values": [0.5, 0.75]},
            "max_hold_bars": {"values": [120, 240]},
        }

    return {
        "enabled": bool(enabled),
        "apply": bool(apply_selected),
        "refresh_sec": float(refresh_sec),
        "is_bars": int(is_bars),
        "oos_bars": int(oos_bars),
        "step_bars": int(step_bars),
        "embargo_bars": int(embargo_bars),
        "plateau_min_frac": float(plateau_min_frac),
        "plateau_tol": float(plateau_tol),
        "grid": dict(grid),
    }


def _quant_pairs_btceth_wfo_maybe_run(
    tf: str,
    ts: List[int],
    bc: List[float],
    ec: List[float],
    base_params: Dict[str, Any],
    force_run: bool = False,
) -> Dict[str, Any]:
    cfg = _quant_pairs_btceth_wfo_config(tf)
    if not bool(cfg.get("enabled")):
        return {"ok": True, "enabled": False, "applied": False, "cached": False}

    key = f"quant_pairs_btceth_wfo|{str(tf).strip().lower() or '1h'}"
    st = TRACKER_STATE.get(key)
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE[key] = st

    now_ms = int(_now_ms())
    refresh_ms = int(float(cfg.get("refresh_sec") or 0.0) * 1000.0)
    allow_cache = bool((not bool(force_run)) and int(refresh_ms) > 0)
    if allow_cache:
        try:
            last_run = int(st.get("run_ms") or 0)
        except Exception:
            last_run = 0
        if last_run > 0 and (int(now_ms) - int(last_run)) < int(refresh_ms):
            out0 = dict(st.get("result") or {}) if isinstance(st.get("result"), dict) else None
            if isinstance(out0, dict) and bool(out0.get("ok")):
                out0["enabled"] = True
                out0["cached"] = True
                out0["run_ms"] = int(last_run)
                return out0

    n = min(len(ts), len(bc), len(ec))
    need = int(cfg.get("is_bars") or 0) + int(cfg.get("embargo_bars") or 0) + int(cfg.get("oos_bars") or 0)
    if n < max(100, need):
        out1 = {
            "ok": False,
            "enabled": True,
            "cached": False,
            "error": "not_enough_bars",
            "n": int(n),
            "need": int(need),
            "config": dict(cfg),
        }
        st["result"] = dict(out1)
        st["run_ms"] = int(now_ms)
        return out1

    sim_base = None
    try:
        sim_base = _quant_pairs_btceth_simulate(ts[:n], bc[:n], ec[:n], dict(base_params or {}))
    except Exception:
        sim_base = None

    out = _quant_pairs_btceth_wfo_run(
        ts=ts[:n],
        btc_close=bc[:n],
        eth_close=ec[:n],
        base_params=dict(base_params or {}),
        grid=dict(cfg.get("grid") or {}),
        is_bars=int(cfg.get("is_bars") or 480),
        oos_bars=int(cfg.get("oos_bars") or 240),
        step_bars=int(cfg.get("step_bars") or 240),
        embargo_bars=int(cfg.get("embargo_bars") or 0),
        plateau_min_frac=float(cfg.get("plateau_min_frac") or 0.6),
        plateau_tol=float(cfg.get("plateau_tol") or 0.1),
    )

    final = {
        "ok": bool(out.get("ok")),
        "enabled": True,
        "cached": False,
        "run_ms": int(now_ms),
        "config": dict(cfg),
        "base": (sim_base if isinstance(sim_base, dict) else None),
        "wfo": (dict(out) if isinstance(out, dict) else None),
    }

    selected = None
    try:
        folds = list((out or {}).get("folds") or []) if isinstance(out, dict) else []
        if folds:
            last_fold = folds[-1]
            sel = ((last_fold.get("selected") or {}).get("params") if isinstance(last_fold, dict) else None)
            if isinstance(sel, dict):
                selected = dict(sel)
    except Exception:
        selected = None
    if isinstance(selected, dict):
        final["selected_params"] = dict(selected)

    st["result"] = dict(final)
    st["run_ms"] = int(now_ms)
    return final


def _quant_pairs_btcalt_wfo_run(
    ts: List[int],
    btc_close: List[float],
    alt_close: List[float],
    base_params: Dict[str, Any],
    grid: Dict[str, Any],
    is_bars: int,
    oos_bars: int,
    step_bars: int,
    embargo_bars: int,
    plateau_min_frac: float = 0.6,
    plateau_tol: float = 0.1,
    alt: Optional[str] = None,
) -> Dict[str, Any]:
    n = min(len(ts), len(btc_close), len(alt_close))
    if n <= 0:
        return {"ok": False, "error": "no_data"}
    is_bars = max(50, min(200000, int(is_bars)))
    oos_bars = max(10, min(200000, int(oos_bars)))
    step_bars = max(1, min(200000, int(step_bars)))
    embargo_bars = max(0, min(200000, int(embargo_bars)))
    plateau_min_frac = float(_clip(float(plateau_min_frac), 0.0, 1.0))
    plateau_tol = float(_clip(float(plateau_tol), 0.0, 5.0))

    def _grid_values(spec: Any) -> List[Any]:
        if spec is None:
            return []
        if isinstance(spec, dict):
            if "values" in spec:
                return list(spec.get("values") or [])
            if all(k in spec for k in ("start", "stop", "step")):
                try:
                    a = float(spec.get("start"))
                    b = float(spec.get("stop"))
                    s = float(spec.get("step"))
                except Exception:
                    return []
                if (not math.isfinite(a)) or (not math.isfinite(b)) or (not math.isfinite(s)) or s <= 0:
                    return []
                vals = []
                v = float(a)
                while v <= float(b) + 1e-12 and len(vals) < 5000:
                    vals.append(float(v))
                    v += float(s)
                return vals
        if isinstance(spec, (list, tuple)):
            return list(spec)
        return [spec]

    keys = [str(k) for k in (grid or {}).keys()]
    vals_by_key = {k: _grid_values((grid or {}).get(k)) for k in keys}
    keys = [k for k in keys if vals_by_key.get(k)]

    def _enumerate(ix: int, cur: Dict[str, Any], out: List[Dict[str, Any]]):
        if ix >= len(keys):
            out.append(dict(cur))
            return
        k = keys[ix]
        for v in vals_by_key.get(k, []):
            cur[k] = v
            _enumerate(ix + 1, cur, out)

    def _score_map_for_slice(a: int, b: int) -> Dict[str, Any]:
        combos = []
        _enumerate(0, {}, combos)
        score_map: Dict[str, Any] = {}
        best_key = None
        best_score = None
        for c in combos:
            pp = dict(base_params or {})
            pp.update(c)
            if ("entry_z" in c) and ("entry_z_long" not in c) and ("entry_z_short" not in c):
                try:
                    ez = float(pp.get("entry_z") or 0.0)
                    if math.isfinite(float(ez)):
                        pp["entry_z_long"] = float(ez)
                        pp["entry_z_short"] = float(ez)
                except Exception:
                    pass
            try:
                if float(pp.get("exit_z") or 0.0) > float(pp.get("entry_z") or 0.0):
                    continue
            except Exception:
                pass
            sim = _quant_pairs_btcalt_simulate(ts[a:b], btc_close[a:b], alt_close[a:b], pp, alt=str(alt) if alt else None)
            if not isinstance(sim, dict) or (not bool(sim.get("ok"))):
                continue
            met = sim.get("metrics") if isinstance(sim.get("metrics"), dict) else {}
            sc = float(met.get("net_sharpe") or 0.0)
            key = "|".join([f"{k}={pp.get(k)}" for k in keys])
            score_map[key] = {"params": dict(pp), "score": float(sc), "metrics": dict(met)}
            if best_score is None or float(sc) > float(best_score):
                best_score = float(sc)
                best_key = str(key)
        return {"scores": score_map, "best_key": best_key, "best_score": best_score}

    def _pick_plateau(score_pack: Dict[str, Any]) -> Dict[str, Any]:
        scores = score_pack.get("scores") if isinstance(score_pack.get("scores"), dict) else {}
        best_key = score_pack.get("best_key")
        best_score = score_pack.get("best_score")
        if best_key is None or best_key not in scores:
            return {"best": None, "plateau": None}
        try:
            best_score_f = float(best_score) if best_score is not None else float((scores.get(best_key) or {}).get("score") or 0.0)
        except Exception:
            best_score_f = float((scores.get(best_key) or {}).get("score") or 0.0)
        tol = float(abs(best_score_f) * float(plateau_tol))
        good_thr = float(best_score_f) - float(tol)
        plateau_keys = []
        for k0, row in scores.items():
            try:
                if float((row or {}).get("score") or 0.0) >= float(good_thr):
                    plateau_keys.append(str(k0))
            except Exception:
                continue
        if not plateau_keys:
            return {"best": dict(scores.get(best_key) or {}), "plateau": None}
        chosen = None
        chosen_score = None
        for k0 in plateau_keys:
            row = scores.get(k0) or {}
            p0 = row.get("params") if isinstance(row.get("params"), dict) else {}
            neigh = 0
            good = 0
            for k1, row1 in scores.items():
                p1 = row1.get("params") if isinstance(row1.get("params"), dict) else {}
                diff = 0
                for kk in keys:
                    if kk not in p0 or kk not in p1:
                        continue
                    if str(p0.get(kk)) != str(p1.get(kk)):
                        diff += 1
                if diff == 1:
                    neigh += 1
                    try:
                        if float((row1 or {}).get("score") or 0.0) >= float(good_thr):
                            good += 1
                    except Exception:
                        pass
            frac = float(good) / float(neigh) if neigh > 0 else 0.0
            if neigh > 0 and frac + 1e-12 < float(plateau_min_frac):
                continue
            sc = float(row.get("score") or 0.0)
            if chosen_score is None or float(sc) > float(chosen_score):
                chosen_score = float(sc)
                chosen = dict(row)
        if chosen is None:
            chosen = dict(scores.get(best_key) or {})
        return {"best": dict(scores.get(best_key) or {}), "plateau": chosen}

    folds = []
    start = 0
    while int(start) + int(is_bars) + int(embargo_bars) + int(oos_bars) <= int(n):
        tr_a = int(start)
        tr_b = int(start) + int(is_bars)
        te_a = int(tr_b) + int(embargo_bars)
        te_b = int(te_a) + int(oos_bars)
        pack = _score_map_for_slice(tr_a, tr_b)
        pick = _pick_plateau(pack)
        chosen = pick.get("plateau") if isinstance(pick.get("plateau"), dict) else pick.get("best")
        chosen_params = (chosen.get("params") if isinstance(chosen, dict) else None)
        if not isinstance(chosen_params, dict):
            start += int(step_bars)
            continue
        oos_sim = _quant_pairs_btcalt_simulate(ts[te_a:te_b], btc_close[te_a:te_b], alt_close[te_a:te_b], chosen_params, alt=str(alt) if alt else None)
        folds.append({
            "train": {"a": int(tr_a), "b": int(tr_b), "ts0": int(ts[tr_a]), "ts1": int(ts[tr_b - 1])},
            "oos": {"a": int(te_a), "b": int(te_b), "ts0": int(ts[te_a]), "ts1": int(ts[te_b - 1])},
            "selected": {
                "mode": ("plateau" if isinstance(pick.get("plateau"), dict) else "best"),
                "params": dict(chosen_params),
                "train": {"score": float((chosen or {}).get("score") or 0.0), "metrics": dict((chosen or {}).get("metrics") or {})},
            },
            "oos_result": (oos_sim if isinstance(oos_sim, dict) else {"ok": False, "error": "oos_failed"}),
        })
        start += int(step_bars)

    oos_scores = []
    oos_pnl = []
    oos_win = []
    for f in folds:
        met = (((f.get("oos_result") or {}).get("metrics") or {}) if isinstance(f.get("oos_result"), dict) else {})
        try:
            oos_scores.append(float(met.get("net_sharpe") or 0.0))
        except Exception:
            pass
        try:
            oos_pnl.append(float(met.get("net_pnl") or 0.0))
        except Exception:
            pass
        try:
            oos_win.append(float(met.get("win_rate") or 0.0))
        except Exception:
            pass
    oos_score_mean = float(sum(oos_scores) / float(len(oos_scores))) if oos_scores else 0.0
    oos_pnl_sum = float(sum(oos_pnl)) if oos_pnl else 0.0
    oos_win_mean = float(sum(oos_win) / float(len(oos_win))) if oos_win else 0.0

    return {
        "ok": True,
        "folds": folds,
        "summary": {
            "folds": int(len(folds)),
            "oos_net_sharpe_mean": float(oos_score_mean),
            "oos_net_pnl_sum": float(oos_pnl_sum),
            "oos_win_rate_mean": float(oos_win_mean),
        },
    }


def _quant_pairs_btcalt_wfo_config(tf: str) -> Dict[str, Any]:
    timeframe = str(tf or "1h").strip().lower() or "1h"
    if timeframe == "60m":
        timeframe = "1h"

    def _duration_to_bars(dur: Any, default_bars: int) -> int:
        if dur is None:
            return int(default_bars)
        if isinstance(dur, (int, float)):
            v = int(dur)
            return int(v) if v > 0 else int(default_bars)
        s = str(dur).strip().lower()
        if not s:
            return int(default_bars)
        try:
            v = int(float(s))
            if v > 0:
                return int(v)
        except Exception:
            pass
        num = None
        unit = ""
        i = 0
        while i < len(s) and (s[i].isdigit() or s[i] in (".",)):
            i += 1
        try:
            num = float(s[:i]) if i > 0 else None
        except Exception:
            num = None
        unit = s[i:].strip() if i < len(s) else ""
        if num is None or (not math.isfinite(float(num))) or float(num) <= 0.0:
            return int(default_bars)
        ms_per_bar = int(_hl_interval_to_ms(timeframe))
        if ms_per_bar <= 0:
            return int(default_bars)
        mul_ms = None
        if unit in ("ms", "msec"):
            mul_ms = 1.0
        elif unit in ("s", "sec", "secs"):
            mul_ms = 1000.0
        elif unit in ("m", "min", "mins"):
            mul_ms = 60_000.0
        elif unit in ("h", "hr", "hrs"):
            mul_ms = 3_600_000.0
        elif unit in ("d", "day", "days"):
            mul_ms = 86_400_000.0
        elif unit in ("w", "wk", "wks", "week", "weeks"):
            mul_ms = 7.0 * 86_400_000.0
        elif unit in ("mo", "mon", "month", "months"):
            mul_ms = 30.0 * 86_400_000.0
        elif unit in ("y", "yr", "yrs", "year", "years"):
            mul_ms = 365.0 * 86_400_000.0
        if mul_ms is None:
            return int(default_bars)
        bars = int(round((float(num) * float(mul_ms)) / float(ms_per_bar)))
        return int(bars) if bars > 0 else int(default_bars)

    enabled = bool(CONFIG.get("quant_pairs_btcalt_wfo_enabled", False))
    apply_selected = bool(CONFIG.get("quant_pairs_btcalt_wfo_apply", False))

    try:
        refresh_sec = float(CONFIG.get("quant_pairs_btcalt_wfo_refresh_sec", 3600.0) or 3600.0)
    except Exception:
        refresh_sec = 3600.0
    refresh_sec = float(_clip(float(refresh_sec), 0.0, 7.0 * 24.0 * 3600.0))

    try:
        plateau_min_frac = float(CONFIG.get("quant_pairs_btcalt_wfo_plateau_min_frac", 0.6) or 0.6)
    except Exception:
        plateau_min_frac = 0.6
    try:
        plateau_tol = float(CONFIG.get("quant_pairs_btcalt_wfo_plateau_tol", 0.1) or 0.1)
    except Exception:
        plateau_tol = 0.1
    plateau_min_frac = float(_clip(float(plateau_min_frac), 0.0, 1.0))
    plateau_tol = float(_clip(float(plateau_tol), 0.0, 5.0))

    try:
        is_bars = int(CONFIG.get("quant_pairs_btcalt_wfo_is_bars", 480) or 480)
    except Exception:
        is_bars = 480
    try:
        oos_bars = int(CONFIG.get("quant_pairs_btcalt_wfo_oos_bars", 240) or 240)
    except Exception:
        oos_bars = 240
    try:
        step_bars = int(CONFIG.get("quant_pairs_btcalt_wfo_step_bars", 240) or 240)
    except Exception:
        step_bars = 240
    try:
        embargo_bars = int(CONFIG.get("quant_pairs_btcalt_wfo_embargo_bars", 0) or 0)
    except Exception:
        embargo_bars = 0

    is_bars = _duration_to_bars(CONFIG.get("quant_pairs_btcalt_wfo_is_duration"), int(is_bars))
    oos_bars = _duration_to_bars(CONFIG.get("quant_pairs_btcalt_wfo_oos_duration"), int(oos_bars))
    step_bars = _duration_to_bars(CONFIG.get("quant_pairs_btcalt_wfo_step_duration"), int(step_bars))
    embargo_bars = _duration_to_bars(CONFIG.get("quant_pairs_btcalt_wfo_embargo_duration"), int(embargo_bars))

    is_bars = max(50, min(200000, int(is_bars)))
    oos_bars = max(10, min(200000, int(oos_bars)))
    step_bars = max(1, min(200000, int(step_bars)))
    embargo_bars = max(0, min(200000, int(embargo_bars)))

    grid = CONFIG.get("quant_pairs_btcalt_wfo_grid")
    if isinstance(grid, str):
        try:
            grid = json.loads(grid)
        except Exception:
            grid = None
    if not isinstance(grid, dict):
        grid = {
            "entry_z": {"values": [1.2, 1.4, 1.6, 1.8, 2.0]},
            "exit_z": {"values": [0.3, 0.5, 0.7]},
            "window_ols": {"values": [120, 240]},
            "window_z": {"values": [120, 240]},
            "corr_min": {"values": [0.5, 0.75]},
            "max_hold_bars": {"values": [120, 240]},
        }

    return {
        "enabled": bool(enabled),
        "apply": bool(apply_selected),
        "refresh_sec": float(refresh_sec),
        "is_bars": int(is_bars),
        "oos_bars": int(oos_bars),
        "step_bars": int(step_bars),
        "embargo_bars": int(embargo_bars),
        "plateau_min_frac": float(plateau_min_frac),
        "plateau_tol": float(plateau_tol),
        "grid": dict(grid),
    }


def _quant_pairs_btcalt_wfo_maybe_run(
    tf: str,
    alt: str,
    ts: List[int],
    bc: List[float],
    ac: List[float],
    base_params: Dict[str, Any],
    force_run: bool = False,
) -> Dict[str, Any]:
    cfg = _quant_pairs_btcalt_wfo_config(tf)
    if not bool(cfg.get("enabled")):
        return {"ok": True, "enabled": False, "applied": False, "cached": False}

    key = f"quant_pairs_btcalt_wfo|{str(tf).strip().lower() or '1h'}|{str(alt or 'ALT').strip().upper() or 'ALT'}"
    st = TRACKER_STATE.get(key)
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE[key] = st

    now_ms = int(_now_ms())
    refresh_ms = int(float(cfg.get("refresh_sec") or 0.0) * 1000.0)
    allow_cache = bool((not bool(force_run)) and int(refresh_ms) > 0)
    if allow_cache:
        try:
            last_run = int(st.get("run_ms") or 0)
        except Exception:
            last_run = 0
        if last_run > 0 and (int(now_ms) - int(last_run)) < int(refresh_ms):
            out0 = dict(st.get("result") or {}) if isinstance(st.get("result"), dict) else None
            if isinstance(out0, dict) and bool(out0.get("ok")):
                out0["enabled"] = True
                out0["cached"] = True
                out0["run_ms"] = int(last_run)
                return out0

    n = min(len(ts), len(bc), len(ac))
    need = int(cfg.get("is_bars") or 0) + int(cfg.get("embargo_bars") or 0) + int(cfg.get("oos_bars") or 0)
    if n < max(100, need):
        out1 = {
            "ok": False,
            "enabled": True,
            "cached": False,
            "error": "not_enough_bars",
            "n": int(n),
            "need": int(need),
            "config": dict(cfg),
        }
        st["result"] = dict(out1)
        st["run_ms"] = int(now_ms)
        return out1

    sim_base = None
    try:
        sim_base = _quant_pairs_btcalt_simulate(ts[:n], bc[:n], ac[:n], dict(base_params or {}), alt=str(alt))
    except Exception:
        sim_base = None

    out = _quant_pairs_btcalt_wfo_run(
        ts=ts[:n],
        btc_close=bc[:n],
        alt_close=ac[:n],
        base_params=dict(base_params or {}),
        grid=dict(cfg.get("grid") or {}),
        is_bars=int(cfg.get("is_bars") or 480),
        oos_bars=int(cfg.get("oos_bars") or 240),
        step_bars=int(cfg.get("step_bars") or 240),
        embargo_bars=int(cfg.get("embargo_bars") or 0),
        plateau_min_frac=float(cfg.get("plateau_min_frac") or 0.6),
        plateau_tol=float(cfg.get("plateau_tol") or 0.1),
        alt=str(alt),
    )

    final = {
        "ok": bool(out.get("ok")),
        "enabled": True,
        "cached": False,
        "run_ms": int(now_ms),
        "config": dict(cfg),
        "base": (sim_base if isinstance(sim_base, dict) else None),
        "wfo": (dict(out) if isinstance(out, dict) else None),
        "alt": str(alt),
    }

    selected = None
    try:
        folds = list((out or {}).get("folds") or []) if isinstance(out, dict) else []
        if folds:
            last_fold = folds[-1]
            sel = ((last_fold.get("selected") or {}).get("params") if isinstance(last_fold, dict) else None)
            if isinstance(sel, dict):
                selected = dict(sel)
    except Exception:
        selected = None
    if isinstance(selected, dict):
        final["selected_params"] = dict(selected)

    st["result"] = dict(final)
    st["run_ms"] = int(now_ms)
    return final


def _quant_pairs_btcalt_params() -> Dict[str, Any]:
    tf = str(CONFIG.get("quant_pairs_btcalt_timeframe", "30m") or "30m").strip().lower() or "30m"
    if tf == "60m":
        tf = "1h"

    def _duration_to_bars(dur: Any, default_bars: int) -> int:
        if dur is None:
            return int(default_bars)
        if isinstance(dur, (int, float)):
            v = int(dur)
            return int(v) if v > 0 else int(default_bars)
        s = str(dur).strip().lower()
        if not s:
            return int(default_bars)
        try:
            v = int(float(s))
            if v > 0:
                return int(v)
        except Exception:
            pass
        num = None
        unit = ""
        i = 0
        while i < len(s) and (s[i].isdigit() or s[i] in (".",)):
            i += 1
        try:
            num = float(s[:i]) if i > 0 else None
        except Exception:
            num = None
        unit = s[i:].strip() if i < len(s) else ""
        if num is None or (not math.isfinite(float(num))) or float(num) <= 0.0:
            return int(default_bars)
        ms_per_bar = int(_hl_interval_to_ms(tf))
        if ms_per_bar <= 0:
            return int(default_bars)
        mul_ms = None
        if unit in ("ms", "msec"):
            mul_ms = 1.0
        elif unit in ("s", "sec", "secs"):
            mul_ms = 1000.0
        elif unit in ("m", "min", "mins"):
            mul_ms = 60_000.0
        elif unit in ("h", "hr", "hrs"):
            mul_ms = 3_600_000.0
        elif unit in ("d", "day", "days"):
            mul_ms = 86_400_000.0
        elif unit in ("w", "wk", "wks", "week", "weeks"):
            mul_ms = 7.0 * 86_400_000.0
        elif unit in ("mo", "mon", "month", "months"):
            mul_ms = 30.0 * 86_400_000.0
        elif unit in ("y", "yr", "yrs", "year", "years"):
            mul_ms = 365.0 * 86_400_000.0
        if mul_ms is None:
            return int(default_bars)
        bars = int(round((float(num) * float(mul_ms)) / float(ms_per_bar)))
        return int(bars) if bars > 0 else int(default_bars)

    try:
        window_ols = int(CONFIG.get("quant_pairs_btcalt_window_ols", 240) or 240)
    except Exception:
        window_ols = 240
    try:
        window_z = int(CONFIG.get("quant_pairs_btcalt_window_z", 240) or 240)
    except Exception:
        window_z = 240
    try:
        entry_z = float(CONFIG.get("quant_pairs_btcalt_entry_z", 2.0) or 2.0)
    except Exception:
        entry_z = 2.0

    entry_z_long = None
    try:
        v = CONFIG.get("quant_pairs_btcalt_entry_z_long")
        if v is not None and str(v).strip() != "":
            entry_z_long = float(v)
    except Exception:
        entry_z_long = None
    entry_z_short = None
    try:
        v = CONFIG.get("quant_pairs_btcalt_entry_z_short")
        if v is not None and str(v).strip() != "":
            entry_z_short = float(v)
    except Exception:
        entry_z_short = None
    try:
        exit_z = float(CONFIG.get("quant_pairs_btcalt_exit_z", 0.5) or 0.5)
    except Exception:
        exit_z = 0.5

    try:
        z_exit_confirm_bars = int(CONFIG.get("quant_pairs_btcalt_z_exit_confirm_bars", 1) or 1)
    except Exception:
        z_exit_confirm_bars = 1
    z_exit_confirm_bars = int(max(1, min(10, int(z_exit_confirm_bars))))
    try:
        stop_z = float(CONFIG.get("quant_pairs_btcalt_stop_z", 4.0) or 4.0)
    except Exception:
        stop_z = 4.0
    try:
        corr_min = float(CONFIG.get("quant_pairs_btcalt_corr_min", 0.6) or 0.6)
    except Exception:
        corr_min = 0.6
    try:
        max_hold_bars = int(CONFIG.get("quant_pairs_btcalt_max_hold_bars", 240) or 240)
    except Exception:
        max_hold_bars = 240
    try:
        z_cost_buffer_mult = float(CONFIG.get("quant_pairs_btcalt_z_cost_buffer_mult", 1.0) or 1.0)
    except Exception:
        z_cost_buffer_mult = 1.0

    d = _quant_pairs_btcalt_exit_pnl_defaults()
    exit_pnl_enabled = True
    try:
        v = CONFIG.get("quant_pairs_btcalt_exit_pnl_enabled", d.get("exit_pnl_enabled", True))
        if isinstance(v, str):
            s = str(v).strip().lower()
            if s in ("0", "false", "no", "n", "off", "disable", "disabled"):
                exit_pnl_enabled = False
            elif s in ("1", "true", "yes", "y", "on", "enable", "enabled"):
                exit_pnl_enabled = True
        else:
            exit_pnl_enabled = bool(v)
    except Exception:
        exit_pnl_enabled = bool(d.get("exit_pnl_enabled", True))

    try:
        pnl_stop_loss_r = float(CONFIG.get("quant_pairs_btcalt_pnl_stop_loss_r", d.get("pnl_stop_loss_r", -0.010)) or d.get("pnl_stop_loss_r", -0.010))
    except Exception:
        pnl_stop_loss_r = float(d.get("pnl_stop_loss_r", -0.010))
    try:
        pnl_take_profit_r = float(CONFIG.get("quant_pairs_btcalt_pnl_take_profit_r", d.get("pnl_take_profit_r", 0.008)) or d.get("pnl_take_profit_r", 0.008))
    except Exception:
        pnl_take_profit_r = float(d.get("pnl_take_profit_r", 0.008))
    try:
        pnl_trail_start_r = float(CONFIG.get("quant_pairs_btcalt_pnl_trail_start_r", d.get("pnl_trail_start_r", 0.006)) or d.get("pnl_trail_start_r", 0.006))
    except Exception:
        pnl_trail_start_r = float(d.get("pnl_trail_start_r", 0.006))
    try:
        pnl_trail_dd_r = float(CONFIG.get("quant_pairs_btcalt_pnl_trail_dd_r", d.get("pnl_trail_dd_r", 0.003)) or d.get("pnl_trail_dd_r", 0.003))
    except Exception:
        pnl_trail_dd_r = float(d.get("pnl_trail_dd_r", 0.003))
    try:
        pnl_min_on_z_exit_r = float(CONFIG.get("quant_pairs_btcalt_pnl_min_on_z_exit_r", d.get("pnl_min_on_z_exit_r", 0.000)) or d.get("pnl_min_on_z_exit_r", 0.000))
    except Exception:
        pnl_min_on_z_exit_r = float(d.get("pnl_min_on_z_exit_r", 0.000))
    try:
        pnl_min_hold_bars = int(CONFIG.get("quant_pairs_btcalt_pnl_min_hold_bars", d.get("pnl_min_hold_bars", 0)) or d.get("pnl_min_hold_bars", 0))
    except Exception:
        pnl_min_hold_bars = int(d.get("pnl_min_hold_bars", 0))

    window_ols = _duration_to_bars(CONFIG.get("quant_pairs_btcalt_window_ols_duration"), int(window_ols))
    window_z = _duration_to_bars(CONFIG.get("quant_pairs_btcalt_window_z_duration"), int(window_z))
    max_hold_bars = _duration_to_bars(CONFIG.get("quant_pairs_btcalt_max_hold_duration"), int(max_hold_bars))
    window_ols = max(10, min(5000, int(window_ols)))
    window_z = max(10, min(5000, int(window_z)))
    entry_z = float(_clip(float(entry_z), 0.1, 10.0))
    if entry_z_long is None or (not math.isfinite(float(entry_z_long))):
        entry_z_long = float(entry_z)
    if entry_z_short is None or (not math.isfinite(float(entry_z_short))):
        entry_z_short = float(entry_z)
    entry_z_long = float(_clip(float(entry_z_long), 0.1, 10.0))
    entry_z_short = float(_clip(float(entry_z_short), 0.1, 10.0))
    exit_z = float(_clip(float(exit_z), 0.0, float(entry_z)))
    stop_z = float(_clip(float(stop_z), float(entry_z), 20.0))
    corr_min = float(_clip(float(corr_min), 0.0, 0.999))
    max_hold_bars = max(1, min(20000, int(max_hold_bars)))
    z_cost_buffer_mult = float(_clip(float(z_cost_buffer_mult), 0.0, 10.0))
    pnl_stop_loss_r = float(_clip(float(pnl_stop_loss_r), -1.0, 1.0))
    pnl_take_profit_r = float(_clip(float(pnl_take_profit_r), -1.0, 1.0))
    pnl_trail_start_r = float(_clip(float(pnl_trail_start_r), -1.0, 1.0))
    pnl_trail_dd_r = float(_clip(float(pnl_trail_dd_r), 0.0, 1.0))
    pnl_min_on_z_exit_r = float(_clip(float(pnl_min_on_z_exit_r), -1.0, 1.0))
    pnl_min_hold_bars = int(max(0, min(20000, int(pnl_min_hold_bars))))
    return {
        "timeframe": tf,
        "window_ols": int(window_ols),
        "window_z": int(window_z),
        "entry_z": float(entry_z),
        "entry_z_long": float(entry_z_long),
        "entry_z_short": float(entry_z_short),
        "exit_z": float(exit_z),
        "z_exit_confirm_bars": int(z_exit_confirm_bars),
        "stop_z": float(stop_z),
        "corr_min": float(corr_min),
        "max_hold_bars": int(max_hold_bars),
        "z_cost_buffer_mult": float(z_cost_buffer_mult),
        "exit_pnl_enabled": bool(exit_pnl_enabled),
        "pnl_stop_loss_r": float(pnl_stop_loss_r),
        "pnl_take_profit_r": float(pnl_take_profit_r),
        "pnl_trail_start_r": float(pnl_trail_start_r),
        "pnl_trail_dd_r": float(pnl_trail_dd_r),
        "pnl_min_on_z_exit_r": float(pnl_min_on_z_exit_r),
        "pnl_min_hold_bars": int(pnl_min_hold_bars),
    }


def _quant_pairs_btcalt_regime_params() -> Dict[str, Any]:
    try:
        btc_tf = str(CONFIG.get("quant_pairs_btcalt_regime_btc_timeframe") or "").strip().lower()
    except Exception:
        btc_tf = ""
    if btc_tf == "60m":
        btc_tf = "1h"
    try:
        ema_fast = int(CONFIG.get("quant_pairs_btcalt_regime_ema_fast", 24) or 24)
    except Exception:
        ema_fast = 24
    try:
        ema_slow = int(CONFIG.get("quant_pairs_btcalt_regime_ema_slow", 96) or 96)
    except Exception:
        ema_slow = 96
    try:
        trend_strength_thr = float(CONFIG.get("quant_pairs_btcalt_regime_trend_strength_thr", 0.01) or 0.01)
    except Exception:
        trend_strength_thr = 0.01
    try:
        trend_strength_scale = float(CONFIG.get("quant_pairs_btcalt_regime_trend_strength_scale", 0.01) or 0.01)
    except Exception:
        trend_strength_scale = 0.01
    try:
        vol_window = int(CONFIG.get("quant_pairs_btcalt_regime_vol_window", 48) or 48)
    except Exception:
        vol_window = 48
    try:
        vol_hist_window = int(CONFIG.get("quant_pairs_btcalt_regime_vol_hist_window", 480) or 480)
    except Exception:
        vol_hist_window = 480
    try:
        vol_pct_thr = float(CONFIG.get("quant_pairs_btcalt_regime_vol_pct_thr", 0.6) or 0.6)
    except Exception:
        vol_pct_thr = 0.6
    try:
        vol_pct_scale = float(CONFIG.get("quant_pairs_btcalt_regime_vol_pct_scale", 0.1) or 0.1)
    except Exception:
        vol_pct_scale = 0.1
    try:
        prob_enter = float(CONFIG.get("quant_pairs_btcalt_regime_prob_enter", 0.65) or 0.65)
    except Exception:
        prob_enter = 0.65
    try:
        prob_exit = float(CONFIG.get("quant_pairs_btcalt_regime_prob_exit", 0.45) or 0.45)
    except Exception:
        prob_exit = 0.45
    try:
        min_hold_bars = int(CONFIG.get("quant_pairs_btcalt_regime_min_hold_bars", 24) or 24)
    except Exception:
        min_hold_bars = 24
    ema_fast = max(2, min(5000, int(ema_fast)))
    ema_slow = max(int(ema_fast) + 1, min(5000, int(ema_slow)))
    trend_strength_thr = float(_clip(float(trend_strength_thr), 0.0, 0.2))
    trend_strength_scale = float(_clip(float(trend_strength_scale), 1e-6, 0.2))
    vol_window = max(2, min(5000, int(vol_window)))
    vol_hist_window = max(int(vol_window) + 10, min(20000, int(vol_hist_window)))
    vol_pct_thr = float(_clip(float(vol_pct_thr), 0.0, 1.0))
    vol_pct_scale = float(_clip(float(vol_pct_scale), 1e-6, 1.0))
    prob_enter = float(_clip(float(prob_enter), 0.01, 0.99))
    prob_exit = float(_clip(float(prob_exit), 0.01, 0.99))
    if float(prob_exit) >= float(prob_enter):
        prob_exit = float(max(0.01, float(prob_enter) - 0.1))
    min_hold_bars = max(0, min(10_000, int(min_hold_bars)))
    return {
        "btc_timeframe": (None if not btc_tf else str(btc_tf)),
        "ema_fast": int(ema_fast),
        "ema_slow": int(ema_slow),
        "trend_strength_thr": float(trend_strength_thr),
        "trend_strength_scale": float(trend_strength_scale),
        "vol_window": int(vol_window),
        "vol_hist_window": int(vol_hist_window),
        "vol_pct_thr": float(vol_pct_thr),
        "vol_pct_scale": float(vol_pct_scale),
        "prob_enter": float(prob_enter),
        "prob_exit": float(prob_exit),
        "min_hold_bars": int(min_hold_bars),
    }


