def _quant_pairs_btcalt_exec_health_eval(tag: str = "btcalt", lookback_h: int = 24) -> Dict[str, Any]:
    enabled = bool(CONFIG.get("quant_pairs_btcalt_exec_gate_enabled", True))
    try:
        rollback_max_per_day = int(CONFIG.get("quant_pairs_btcalt_exec_rollback_max_per_day", 3) or 3)
    except Exception:
        rollback_max_per_day = 3
    try:
        fill_rate_min = float(CONFIG.get("quant_pairs_btcalt_exec_fill_rate_min", 0.95) or 0.95)
    except Exception:
        fill_rate_min = 0.95
    try:
        cooldown_sec = int(CONFIG.get("quant_pairs_btcalt_exec_gate_cooldown_sec", 3600) or 3600)
    except Exception:
        cooldown_sec = 3600
    lookback_h = max(1, min(168, int(lookback_h)))
    rollback_max_per_day = max(0, min(50, int(rollback_max_per_day)))
    fill_rate_min = float(_clip(float(fill_rate_min), 0.0, 1.0))
    cooldown_sec = max(0, min(7 * 86_400, int(cooldown_sec)))

    now_ms = int(_now_ms())
    since_ms = int(now_ms - int(lookback_h) * 3_600_000)
    filled = 0
    failed = 0
    rollbacks = 0
    considered = 0
    for o in list((ORDERS or {}).values()):
        if not isinstance(o, dict):
            continue
        try:
            ts = int(o.get("ts") or 0)
        except Exception:
            ts = 0
        if ts <= 0 or ts < int(since_ms):
            continue
        tg = str(o.get("tag") or "")
        if tag and (tag not in tg):
            continue
        if str(o.get("mode") or "").lower() != "real":
            continue
        st = str(o.get("status") or "").lower()
        if st not in ("filled", "failed", "rejected", "canceled", "cancelled", "expired"):
            continue
        considered += 1
        if st == "filled":
            filled += 1
        else:
            failed += 1
        ex = o.get("exec") if isinstance(o.get("exec"), dict) else {}
        if isinstance(ex, dict) and ex.get("maker_rollback") is not None:
            rollbacks += 1
        else:
            try:
                if str(ex.get("error") or "").lower().startswith("maker_timeout"):
                    rollbacks += 1
            except Exception:
                pass
    denom = int(filled + failed)
    fill_rate = float(filled) / float(denom) if denom > 0 else 1.0
    blocked = False
    blocked_reason = None
    if rollback_max_per_day > 0 and int(rollbacks) > int(rollback_max_per_day):
        blocked = True
        blocked_reason = "exec_rollback_excess"
    elif fill_rate_min > 0.0 and float(fill_rate) + 1e-12 < float(fill_rate_min) and int(denom) >= 5:
        blocked = True
        blocked_reason = "exec_fill_rate_low"
    until_ms = 0
    if bool(blocked) and int(cooldown_sec) > 0:
        until_ms = int(now_ms + int(cooldown_sec) * 1000)
    return {
        "ok": True,
        "enabled": bool(enabled),
        "blocked": bool(blocked) if bool(enabled) else False,
        "blocked_reason": (blocked_reason if bool(blocked) else None),
        "cooldown_until_ms": int(until_ms),
        "stats": {
            "lookback_h": int(lookback_h),
            "orders": int(considered),
            "filled": int(filled),
            "failed": int(failed),
            "fill_rate": float(fill_rate),
            "rollbacks": int(rollbacks),
        },
        "thresholds": {
            "rollback_max_per_day": int(rollback_max_per_day),
            "fill_rate_min": float(fill_rate_min),
            "cooldown_sec": int(cooldown_sec),
        },
    }


def _quant_pairs_btcalt_perf_gate_eval(strategy_id: str = "quant_pairs_btcalt") -> Dict[str, Any]:
    enabled = bool(CONFIG.get("quant_pairs_btcalt_perf_gate_enabled", True))
    try:
        min_trades = int(CONFIG.get("quant_pairs_btcalt_perf_gate_min_trades", 30) or 30)
    except Exception:
        min_trades = 30
    try:
        sharpe_min = float(CONFIG.get("quant_pairs_btcalt_perf_gate_sharpe_min", 0.5) or 0.5)
    except Exception:
        sharpe_min = 0.5
    try:
        maxdd_max = float(CONFIG.get("quant_pairs_btcalt_perf_gate_maxdd_max", 0.20) or 0.20)
    except Exception:
        maxdd_max = 0.20
    try:
        cooldown_sec = int(CONFIG.get("quant_pairs_btcalt_perf_gate_cooldown_sec", 86_400) or 86_400)
    except Exception:
        cooldown_sec = 86_400
    min_trades = max(0, min(10000, int(min_trades)))
    sharpe_min = float(_clip(float(sharpe_min), -10.0, 10.0))
    maxdd_max = float(_clip(float(maxdd_max), 0.0, 0.99))
    cooldown_sec = max(0, min(30 * 86_400, int(cooldown_sec)))

    sp = TRACKER_STATE.get("strategy_perf")
    rec = (sp.get(str(strategy_id)) if isinstance(sp, dict) else None)
    rets = (rec.get("rets") if isinstance(rec, dict) else None)
    if not isinstance(rets, list):
        rets = []
    n = len(rets)
    mean = float(sum(float(r) for r in rets) / float(n)) if n > 0 else 0.0
    var = 0.0
    if n > 1:
        for r in rets:
            d = float(r) - float(mean)
            var += d * d
        var = float(var / float(n - 1))
    sd = math.sqrt(float(var)) if var > 0 else 0.0
    sharpe = float(mean / sd * math.sqrt(float(n))) if sd > 1e-12 and n > 1 else 0.0
    maxdd = None
    try:
        maxdd = float(rec.get("maxdd")) if isinstance(rec, dict) and rec.get("maxdd") is not None else None
    except Exception:
        maxdd = None
    if maxdd is None:
        maxdd = 0.0
    blocked = False
    blocked_reason = None
    until_ms = 0
    if bool(enabled) and int(min_trades) > 0 and int(n) >= int(min_trades):
        if float(sharpe) + 1e-12 < float(sharpe_min):
            blocked = True
            blocked_reason = "rolling_sharpe_low"
        elif float(maxdd) - 1e-12 > float(maxdd_max):
            blocked = True
            blocked_reason = "rolling_maxdd_high"
    if bool(blocked) and int(cooldown_sec) > 0:
        until_ms = int(_now_ms()) + int(cooldown_sec) * 1000
    return {
        "ok": True,
        "enabled": bool(enabled),
        "blocked": bool(blocked) if bool(enabled) else False,
        "blocked_reason": (blocked_reason if bool(blocked) else None),
        "cooldown_until_ms": int(until_ms),
        "stats": {"n": int(n), "rolling_sharpe": float(sharpe), "rolling_maxdd": float(maxdd)},
        "thresholds": {"min_trades": int(min_trades), "sharpe_min": float(sharpe_min), "maxdd_max": float(maxdd_max), "cooldown_sec": int(cooldown_sec)},
    }


def _quant_pairs_btcalt_vol_gate_eval(alt: Optional[str] = None) -> Dict[str, Any]:
    enabled = bool(CONFIG.get("quant_pairs_btcalt_vol_gate_enabled", True))
    try:
        atr_mult = float(CONFIG.get("quant_pairs_btcalt_vol_atr_mult", 2.0) or 2.0)
    except Exception:
        atr_mult = 2.0
    try:
        lookback_h = int(CONFIG.get("quant_pairs_btcalt_vol_mean_lookback_h", 240) or 240)
    except Exception:
        lookback_h = 240
    try:
        cooldown_sec = int(CONFIG.get("quant_pairs_btcalt_vol_gate_cooldown_sec", 3600) or 3600)
    except Exception:
        cooldown_sec = 3600
    atr_mult = float(_clip(float(atr_mult), 1.0, 20.0))
    lookback_h = max(10, min(20000, int(lookback_h)))
    cooldown_sec = max(0, min(7 * 86_400, int(cooldown_sec)))

    btc = _atr_pct_stats("BTC", lookback_h=int(lookback_h))
    alt_s = (str(alt).upper().strip() if alt else "")
    alt_pack = None
    if alt_s and alt_s not in ("BTC", "USDT", "USDC"):
        alt_pack = _atr_pct_stats(str(alt_s), lookback_h=int(lookback_h))

    blocked = False
    reason = None
    try:
        if bool(btc.get("ok")) and float(btc.get("mean") or 0.0) > 0.0:
            if float(btc.get("latest") or 0.0) >= float(atr_mult) * float(btc.get("mean") or 0.0):
                blocked = True
                reason = "btc_atr_high"
    except Exception:
        pass
    try:
        if (not blocked) and isinstance(alt_pack, dict) and bool(alt_pack.get("ok")) and float(alt_pack.get("mean") or 0.0) > 0.0:
            if float(alt_pack.get("latest") or 0.0) >= float(atr_mult) * float(alt_pack.get("mean") or 0.0):
                blocked = True
                reason = ("alt_atr_high:" + str(alt_s))
    except Exception:
        pass
    until_ms = 0
    if bool(blocked) and int(cooldown_sec) > 0:
        until_ms = int(_now_ms()) + int(cooldown_sec) * 1000
    return {
        "ok": True,
        "enabled": bool(enabled),
        "blocked": bool(blocked) if bool(enabled) else False,
        "blocked_reason": (reason if bool(blocked) else None),
        "cooldown_until_ms": int(until_ms),
        "stats": {"btc": btc, "alt": alt_pack, "alt_coin": (None if not alt_s else str(alt_s))},
        "thresholds": {"atr_mult": float(atr_mult), "lookback_h": int(lookback_h), "cooldown_sec": int(cooldown_sec)},
    }


def _quant_pairs_btcalt_external_event_gate_eval(alt: Optional[str] = None) -> Dict[str, Any]:
    enabled = bool(CONFIG.get("quant_pairs_btcalt_event_gate_enabled", True))
    try:
        vol_pct = float(CONFIG.get("quant_pairs_btcalt_event_vol_pct", 0.99) or 0.99)
    except Exception:
        vol_pct = 0.99
    try:
        lookback_h = int(CONFIG.get("quant_pairs_btcalt_event_lookback_h", 4000) or 4000)
    except Exception:
        lookback_h = 4000
    try:
        cooldown_sec = int(CONFIG.get("quant_pairs_btcalt_event_gate_cooldown_sec", 3600) or 3600)
    except Exception:
        cooldown_sec = 3600
    vol_pct = float(_clip(float(vol_pct), 0.50, 0.9999))
    lookback_h = max(100, min(50000, int(lookback_h)))
    cooldown_sec = max(0, min(7 * 86_400, int(cooldown_sec)))

    out = {"ok": True, "enabled": bool(enabled), "blocked": False, "blocked_reason": None, "cooldown_until_ms": 0, "stats": {}, "thresholds": {"vol_pct": float(vol_pct), "lookback_h": int(lookback_h), "cooldown_sec": int(cooldown_sec)}}
    if not bool(enabled):
        return out
    if np is None:
        out["ok"] = False
        out["error"] = "numpy_unavailable"
        return out

    btc = _get_pair_cache("BTC")
    b = btc.get("atr_pct_h") if isinstance(btc, dict) else None
    if not isinstance(b, list) or (not b):
        out["ok"] = False
        out["error"] = "no_atr_pct"
        return out
    bb = [float(v) for v in b if v is not None and math.isfinite(float(v))]
    if not bb:
        out["ok"] = False
        out["error"] = "no_atr_pct"
        return out
    if len(bb) > int(lookback_h):
        bb = bb[-int(lookback_h):]
    bthr = float(np.quantile(np.asarray(bb, dtype=float), float(vol_pct)))
    blat = float(bb[-1])

    alt_s = (str(alt).upper().strip() if alt else "")
    alt_stats = None
    alt_trigger = False
    if alt_s and alt_s not in ("BTC", "USDT", "USDC"):
        alt_cache = _get_pair_cache(str(alt_s))
        a = alt_cache.get("atr_pct_h") if isinstance(alt_cache, dict) else None
        if isinstance(a, list) and a:
            aa = [float(v) for v in a if v is not None and math.isfinite(float(v))]
            if aa:
                if len(aa) > int(lookback_h):
                    aa = aa[-int(lookback_h):]
                athr = float(np.quantile(np.asarray(aa, dtype=float), float(vol_pct)))
                alat = float(aa[-1])
                alt_stats = {"latest": float(alat), "thr": float(athr)}
                if float(alat) >= float(athr):
                    alt_trigger = True

    out["stats"] = {"btc": {"latest": float(blat), "thr": float(bthr)}, "alt": alt_stats, "alt_coin": (None if not alt_s else str(alt_s))}
    if float(blat) >= float(bthr):
        out["blocked"] = True
        out["blocked_reason"] = "external_event_vol_btc"
    elif bool(alt_trigger):
        out["blocked"] = True
        out["blocked_reason"] = ("external_event_vol_alt:" + str(alt_s))
    if bool(out.get("blocked")) and int(cooldown_sec) > 0:
        out["cooldown_until_ms"] = int(_now_ms()) + int(cooldown_sec) * 1000
    return out


def _quant_pairs_btcalt_operational_gate_eval(tf: str, tag: str, strategy_id: str, alt: Optional[str] = None) -> Dict[str, Any]:
    enabled = bool(CONFIG.get("quant_pairs_btcalt_op_gate_enabled", True))
    now_ms = int(_now_ms())
    cds = TRACKER_STATE.get("quant_pairs_btcalt_cooldowns")
    if not isinstance(cds, dict):
        cds = {}
        TRACKER_STATE["quant_pairs_btcalt_cooldowns"] = cds

    def _cooldown_get() -> Tuple[int, Optional[str]]:
        until = 0
        why = None
        for k, v in cds.items():
            try:
                u = int(v or 0)
            except Exception:
                u = 0
            if u > until:
                until = u
                why = str(k)
        if until > int(now_ms):
            return int(until), why
        return 0, None

    until0, why0 = _cooldown_get()
    if until0 > int(now_ms):
        return {"ok": True, "enabled": bool(enabled), "blocked": True if bool(enabled) else False, "blocked_reason": ("cooldown:" + str(why0) if why0 else "cooldown"), "cooldown_until_ms": int(until0), "components": {}}

    exec_h = _quant_pairs_btcalt_exec_health_eval(tag=str(tag), lookback_h=24)
    perf = _quant_pairs_btcalt_perf_gate_eval(strategy_id=str(strategy_id))
    vol = _quant_pairs_btcalt_vol_gate_eval(alt=str(alt) if alt else None)
    evt = _quant_pairs_btcalt_external_event_gate_eval(alt=str(alt) if alt else None)
    comps = {"execution": exec_h, "perf": perf, "vol": vol, "event": evt}

    blocked = False
    blocked_reason = None
    until_ms = 0
    for k in ("execution", "perf", "vol", "event"):
        c = comps.get(k)
        if not isinstance(c, dict):
            continue
        if not bool(c.get("enabled", True)):
            continue
        if bool(c.get("blocked")):
            blocked = True
            br = None
            try:
                br = str(c.get("blocked_reason") or "").strip() or None
            except Exception:
                br = None
            blocked_reason = (k + ":" + br) if br else str(k)
            try:
                until_ms = int(c.get("cooldown_until_ms") or 0)
            except Exception:
                until_ms = 0
            break

    if bool(blocked) and int(until_ms) > int(now_ms):
        cds[str(blocked_reason or "blocked")] = int(until_ms)
        try:
            _quant_pairs_btcalt_gate_log({"ts": int(now_ms), "type": "btcalt_op_gate", "blocked": True, "reason": str(blocked_reason or "blocked"), "until_ms": int(until_ms)})
        except Exception:
            pass

    return {
        "ok": True,
        "enabled": bool(enabled),
        "blocked": bool(blocked) if bool(enabled) else False,
        "blocked_reason": (blocked_reason if bool(blocked) else None),
        "cooldown_until_ms": int(until_ms) if bool(blocked) else 0,
        "components": comps,
    }


