    min_coverage = float(data.get("min_coverage", 0.1) or 0.1)
    families = data.get("families")
    if not isinstance(families, list) or not families:
        families = ["committee", "xgb", "rf", "lr", "nn", "lstm", "score"]
    res = _evaluation_pick_best_family(
        families=[str(x) for x in families],
        window=window,
        calibrated=calibrated,
        objective=objective,
        min_samples=min_samples,
        min_coverage=min_coverage,
    )
    if not bool(res.get("ok")):
        return jsonify(res), 409
    chosen = str(res.get("chosen"))
    EVAL_MODELS["active_family"] = chosen
    res["active"] = chosen
    try:
        _audit_emit_action(
            "evaluation.active.auto",
            _audit_base_payload(
                scope="governance",
                action="evaluation.active.auto",
                trace_id=trace_id,
                extra={
                    "chosen": chosen,
                    "objective": objective,
                    "window": int(window),
                    "calibrated": bool(calibrated),
                    "min_samples": int(min_samples),
                    "min_coverage": float(min_coverage),
                    "families": families,
                    "approval_id": approval_id,
                },
            ),
        )
    except Exception:
        pass
    res["trace_id"] = trace_id
    res["approval_id"] = approval_id
    return jsonify(res)

