@app.route("/evaluation/train", methods=["POST"])
def evaluation_train():
    if not (_governance_write_auth_ok() or _agent_sandbox_task_auth_ok()):
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    family = str(data.get("family","lr")).lower()
    params = data.get("params") or {}
    samples = data.get("samples") or []
    feature_set_id = ("" if data.get("feature_set_id") is None else str(data.get("feature_set_id"))).strip() or None
    # If external samples provided, merge into EVAL_SAMPLES
    for s in samples:
        if "features" in s and "label" in s:
            item = {
                "features": s.get("features") or {},
                "label": int(s.get("label", 0)),
            }
            if "weight" in s:
                item["weight"] = float(s.get("weight") or 1.0)
            if "ts" in s:
                item["ts"] = int(s.get("ts") or 0)
            if "targets" in s:
                item["targets"] = s.get("targets") or {}
            if "pair" in s:
                item["pair"] = str(s.get("pair") or "")
            EVAL_SAMPLES.append(item)
    # Choose training set
    train_set = EVAL_SAMPLES[:] if EVAL_SAMPLES else []
    if len(train_set) == 0:
        # Bootstrap a tiny synthetic sample based on EVENTS (no labels -> assume tag contains label)
        for _,e in list(EVENTS.items())[:50]:
            lbl = 1 if str(e.get("side","")) == "long" else 0
            train_set.append({"features": e.get("features", {}), "label": lbl})

    if feature_set_id is None:
        feature_set_id = _infer_feature_set_id(train_set)

    keys = _eval_feature_keys(family, feature_set_id)
    # Train per family
    model = {}
    stype = str(CONFIG.get("scaler_type", "robust"))
    SCALER.clear()
    SCALER.update(_fit_scaler(train_set, keys, stype))
    _save_scaler()
    if family == "lr":
        model = _lr_train(train_set, {**(params or {}), "keys": keys, "feature_set_id": feature_set_id})
    elif family == "rf":
        model = _rf_train(train_set, {**(params or {}), "keys": keys, "feature_set_id": feature_set_id})
    elif family == "xgb":
        prior = None
        warm = bool(params.get("warm_start", False))
        resume = bool(params.get("resume", False))
        if warm and ("xgb" in EVAL_MODELS):
            prior = EVAL_MODELS["xgb"].get("booster")
        if resume and not prior:
            prior = _xgb_load().get("booster")
        import xgboost as xgb
        X = [[_scale_value(k, _to_float(s.get("features", {}).get(k, 0.0))) for k in keys] for s in train_set]
        y = [int(s.get("label", 0)) for s in train_set]
        weights = [float(s.get("weight", 1.0)) for s in train_set]
        dtrain = xgb.DMatrix(X, label=y, feature_names=keys, weight=weights)
        booster_params = {
            "objective": "binary:logistic",
            "eval_metric": "logloss",
            "eta": float(params.get("learning_rate", 0.1)),
            "max_depth": int(params.get("max_depth", 4))
        }
        num_round = int(params.get("n_estimators", 100))
        booster = xgb.train(booster_params, dtrain, num_boost_round=num_round, xgb_model=prior)
        model = {"type":"xgb","booster": booster, "keys": keys, "ts": _now_ms(), "feature_set_id": feature_set_id}
    elif family == "nn":
        model = _nn_train(train_set, {**(params or {}), "keys": keys, "feature_set_id": feature_set_id})
    elif family == "lstm":
        model = _lstm_train(train_set, {**(params or {}), "keys": keys, "feature_set_id": feature_set_id})
    else:
        model = _lr_train(train_set, {**(params or {}), "keys": keys, "feature_set_id": feature_set_id})
    EVAL_MODELS[family] = model
    EVAL_MODELS["active_family"] = family
    # Compute metrics on train_set
    preds = []
    labels = []
    for s in train_set:
        labels.append(int(s.get("label",0)))
        if family == "lr":
            preds.append(_lr_predict(model["weights"], model["bias"], s.get("features", {})))
        elif family == "rf":
            preds.append(_rf_predict(model, s.get("features", {})))
        elif family == "xgb":
            preds.append(_xgb_predict(model, s.get("features", {})))
        elif family == "nn":
            preds.append(_nn_predict(model, s.get("features", {})))
        elif family == "lstm":
            preds.append(_lstm_predict(model, s.get("features", {})))
        else:
            preds.append(_score(s.get("features", {}), "long"))
    metrics = _compute_metrics(preds, labels)
    run = {"id": _gen_id("run"), "family": family, "params": params, "metrics": metrics, "ts": _now_ms()}
    _evaluation_history_append(run)
    try:
        _audit_emit_action(
            "evaluation.train",
            _audit_base_payload(
                scope=("governance" if _governance_write_auth_ok() else "sandbox"),
                action="evaluation.train",
                trace_id=trace_id,
                extra={
                    "family": family,
                    "feature_set_id": feature_set_id,
                    "train_n": int(len(train_set)),
                    "metrics": metrics,
                },
            ),
        )
    except Exception:
        pass
    return jsonify({"ok": True, "model": {"family": family, "ts": model.get("ts")}, "metrics": metrics, "run": run})

