@app.route("/evaluation/predict", methods=["POST"])
def evaluation_predict():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    family = str(data.get("family","lr")).lower()
    features = data.get("features") or {}
    if family in EVAL_MODELS:
        m = EVAL_MODELS[family]
        if family == "committee" and isinstance(m, dict) and m.get("type") == "committee":
            p = _committee_predict(m, features)
        elif family == "lr":
            p = _lr_predict(m.get("weights", {}), float(m.get("bias", 0.0)), features)
        elif family == "rf":
            p = _rf_predict(m, features)
        elif family == "xgb":
            p = _xgb_predict(m, features)
        elif family == "nn":
            p = _nn_predict(m, features)
        elif family == "lstm":
            p = _lstm_predict(m, features)
        else:
            p = _score(features, "long")
    else:
        p = _score(features, "long")
    reg = _get_regime(features)
    pc = _calibrate(p, features, reg)
    thr = _get_threshold(reg)
    decision = "enter" if pc >= thr else "hold"
    return jsonify({"ok": True, "family": family, "p": p, "pc": pc, "threshold": thr, "decision": decision})

@app.route("/evaluation/feature-importance", methods=["GET"])
def evaluation_feature_importance():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    family = request.args.get("family","lr").lower()
    if family in EVAL_MODELS:
        m = EVAL_MODELS[family]
        if family == "lr":
            items = [{"feature": k, "weight": float(v)} for k,v in m.get("weights", {}).items()]
            items.sort(key=lambda x: abs(x["weight"]), reverse=True)
            return jsonify({"ok": True, "family": family, "coefficients": items})
        if family == "rf":
            mdl = m.get("model")
            keys = m.get("keys", _eval_feature_keys("rf", m.get("feature_set_id")))
            imp = getattr(mdl, "feature_importances_", None)
            if imp is not None:
                items = [{"feature": k, "gain": float(v)} for k, v in zip(keys, imp)]
                items.sort(key=lambda x: abs(x["gain"]), reverse=True)
                return jsonify({"ok": True, "family": family, "importance": items})
        if family == "xgb":
            booster = m.get("booster")
            score = booster.get_score(importance_type="gain")
            keys = m.get("keys", _eval_feature_keys("xgb", m.get("feature_set_id")))
            items = [{"feature": k, "gain": float(score.get(k, 0.0))} for k in keys]
            items.sort(key=lambda x: abs(x["gain"]), reverse=True)
            return jsonify({"ok": True, "family": family, "importance": items})
        if family in ("nn","lstm"):
            mdl = m.get("model")
            try:
                first = list(mdl.parameters())[0].detach().numpy()
                weights = first.mean(axis=0).tolist() if len(first.shape)>1 else first.tolist()
                keys = m.get("keys", _eval_feature_keys(family, m.get("feature_set_id")))
                items = [{"feature": k, "weight": float(weights[i] if i < len(weights) else 0.0)} for i, k in enumerate(keys)]
                items.sort(key=lambda x: abs(x["weight"]), reverse=True)
                return jsonify({"ok": True, "family": family, "coefficients": items})
            except Exception:
                pass
    items = [{"feature": k, "gain": 0.0} for k in _eval_feature_keys()]
    return jsonify({"ok": True, "family": family, "importance": items})

