def _metrics_to_api_payload(m: Any) -> Dict[str, Any]:
    if not isinstance(m, dict):
        return {}
    out: Dict[str, Any] = dict(m)

    bins = out.get("calibration") if isinstance(out.get("calibration"), list) else []
    try:
        ece = float(out.get("ece") or 0.0)
    except Exception:
        ece = 0.0
    out["calibration"] = {"bins": bins, "ece": ece}

    pnl_curve = out.get("pnl") if isinstance(out.get("pnl"), list) else []
    try:
        mean_return = float(out.get("mean_return") or 0.0)
    except Exception:
        mean_return = 0.0
    try:
        win_rate = float(out.get("win_rate") or 0.0)
    except Exception:
        win_rate = 0.0
    out["pnl_curve"] = pnl_curve
    out["pnl"] = {
        "curve": pnl_curve,
        "mean_return": mean_return,
        "win_rate": win_rate,
        "tail_loss_p95": _loss_tail_p(pnl_curve, 0.95),
        "maxdd": _max_drawdown_from_pnl(pnl_curve),
    }
    return out
@app.route("/evaluation/metrics", methods=["GET"])
def evaluation_metrics():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    # Evaluate on current EVAL_SAMPLES using active family
    family = EVAL_MODELS.get("active_family","lr")
    preds = []
    labels = []
    rets = []

    try:
        window = int(request.args.get("window", "0") or 0)
    except Exception:
        window = 0
    try:
        since_ts = int(request.args.get("since_ts", "0") or 0)
    except Exception:
        since_ts = 0
    try:
        until_ts = int(request.args.get("until_ts", "0") or 0)
    except Exception:
        until_ts = 0
    sort_mode = str(request.args.get("sort") or "ts").strip().lower()

    samples = EVAL_SAMPLES[:] if EVAL_SAMPLES else []
    if samples:
        if since_ts > 0 or until_ts > 0:
            xs = []
            for s in samples:
                try:
                    ts = int(s.get("ts") or 0)
                except Exception:
                    ts = 0
                if since_ts > 0 and ts < since_ts:
                    continue
                if until_ts > 0 and ts >= until_ts:
                    continue
                xs.append(s)
            samples = xs
        if sort_mode == "ts":
            samples = sorted(samples, key=lambda x: int(x.get("ts") or 0))
        if window and window > 0:
            window = max(1, min(200000, int(window)))
            if len(samples) > window:
                samples = samples[-window:]
    else:
        if since_ts <= 0 and until_ts <= 0 and window <= 0:
            for _, e in list(EVENTS.items())[:50]:
                lbl = 1 if str(e.get("side", "")) == "long" else 0
                samples.append({"features": e.get("features", {}), "label": lbl})
    for s in samples:
        labels.append(int(s.get("label",0)))
        tr = None
        try:
            tr = (s.get("targets") or {}).get("return_tk")
        except Exception:
            tr = None
        if tr is None:
            rets.append(1.0 if int(s.get("label", 0)) == 1 else -1.0)
        else:
            rets.append(float(tr))
        if family in EVAL_MODELS:
            m = EVAL_MODELS[family]
            if family == "committee" and isinstance(m, dict) and m.get("type") == "committee":
                preds.append(_committee_predict(m, s.get("features", {})))
            elif family == "lr":
                preds.append(_lr_predict(m.get("weights", {}), float(m.get("bias", 0.0)), s.get("features", {})))
            elif family == "rf":
                preds.append(_rf_predict(m, s.get("features", {})))
            elif family == "xgb":
                preds.append(_xgb_predict(m, s.get("features", {})))
            elif family == "nn":
                preds.append(_nn_predict(m, s.get("features", {})))
            elif family == "lstm":
                preds.append(_lstm_predict(m, s.get("features", {})))
            else:
                preds.append(_score(s.get("features", {}), "long"))
        else:
            preds.append(_score(s.get("features", {}), "long"))
    metrics = _compute_metrics(preds, labels, returns=rets)
    preds_cal = [_calibrate(float(p), features=s.get("features") or {}) for p, s in zip(preds, samples)]
    metrics_cal = _compute_metrics(preds_cal, labels, returns=rets)
    return jsonify({
        "ok": True,
        "family": family,
        "count": int(len(samples)),
        "filters": {"since_ts": int(since_ts), "until_ts": int(until_ts), "window": int(window), "sort": str(sort_mode)},
        "metrics": _metrics_to_api_payload(metrics),
        "metrics_calibrated": _metrics_to_api_payload(metrics_cal),
        "calibrator": {"method": CALIBRATOR.get("method")},
    })

