def _rolling_window_verify(
    family: str = "xgb",
    folds: int = 5,
    calibrate_method: str = None,
    embargo_ms: int = None,
    use_thresholds: bool = None,
    stress_cost_pct: float = None,
    bucketed: bool = True,
) -> Dict[str, Any]:
    samples = sorted(EVAL_SAMPLES, key=lambda x: x.get("ts", 0))
    n = len(samples)
    if n < folds * 20:
        return {"ok": False, "error": "not_enough_samples", "n": int(n), "folds": int(folds), "min_required": int(folds * 20)}
    
    chunk_size = n // folds
    metrics_list = []

    try:
        label_h = float(CONFIG.get("label_horizon_hours", 12) or 12)
    except Exception:
        label_h = 12.0
    try:
        emb_h_cfg = CONFIG.get("eval_walkforward_embargo_hours")
        emb_h = float(emb_h_cfg) if emb_h_cfg is not None else float(label_h)
    except Exception:
        emb_h = float(label_h)
    emb_ms_default = int(max(0.0, float(emb_h)) * 3600.0 * 1000.0)
    try:
        emb_ms = int(embargo_ms) if embargo_ms is not None else int(emb_ms_default)
    except Exception:
        emb_ms = int(emb_ms_default)
    emb_ms = max(0, int(emb_ms))

    if use_thresholds is None:
        use_thresholds = bool(CONFIG.get("eval_walkforward_use_thresholds", True))
    use_thr = bool(use_thresholds)

    try:
        stress_cost = float(stress_cost_pct) if stress_cost_pct is not None else float(CONFIG.get("eval_stress_cost_pct", 0.003) or 0.003)
    except Exception:
        stress_cost = 0.003
    stress_cost = float(_clip(float(stress_cost), 0.0, 0.05))

    def _q(vals: List[float], q: float) -> float:
        xs = sorted([float(x) for x in vals if math.isfinite(float(x))])
        if not xs:
            return 0.0
        qq = float(_clip(float(q), 0.0, 1.0))
        i = int(round(qq * float(len(xs) - 1)))
        i = max(0, min(len(xs) - 1, int(i)))
        return float(xs[i])

    def _vol_val(s: Dict[str, Any]) -> float:
        f = s.get("features") or {}
        for k in ("macro_atr_pct", "atr_pct", "atr_ratio"):
            try:
                v = float(f.get(k) or 0.0)
                if math.isfinite(v):
                    return float(abs(v))
            except Exception:
                continue
        return 0.0

    def _liq_val(s: Dict[str, Any]) -> float:
        f = s.get("features") or {}
        for k in ("volume", "quote_volume", "volume_ratio", "notional_1h"):
            try:
                v = float(f.get(k) or 0.0)
                if math.isfinite(v):
                    return float(max(0.0, v))
            except Exception:
                continue
        return 0.0

    def _spread_val(s: Dict[str, Any]) -> float:
        f = s.get("features") or {}
        for k in ("spread_bps", "book_spread_bps", "bid_ask_spread_bps", "slippage_bps_est"):
            try:
                v = float(f.get(k) or 0.0)
                if math.isfinite(v):
                    return float(max(0.0, v))
            except Exception:
                continue
        return 0.0

    vol_all = [float(_vol_val(s)) for s in samples]
    q20 = _q(vol_all, 0.20)
    q40 = _q(vol_all, 0.40)
    q60 = _q(vol_all, 0.60)
    q80 = _q(vol_all, 0.80)
    vol_edges = [float(q20), float(q40), float(q60), float(q80)]

    liq_all = [float(_liq_val(s)) for s in samples]
    liq_edges = [float(_q(liq_all, 0.20)), float(_q(liq_all, 0.40)), float(_q(liq_all, 0.60)), float(_q(liq_all, 0.80))]

    spread_all = [float(_spread_val(s)) for s in samples]
    spread_edges = [float(_q(spread_all, 0.20)), float(_q(spread_all, 0.40)), float(_q(spread_all, 0.60)), float(_q(spread_all, 0.80))]

    def _vol_bucket(v: float) -> str:
        idx = 0
        for e in vol_edges:
            if float(v) > float(e):
                idx += 1
        return f"q{int(_clip(idx, 0, 4))}"

    def _edge_bucket(v: float, edges: List[float]) -> str:
        idx = 0
        for e in edges:
            if float(v) > float(e):
                idx += 1
        return f"q{int(_clip(idx, 0, 4))}"

    def _bucket_key(s: Dict[str, Any]) -> Tuple[str, str, str, str, str, str]:
        f = s.get("features") or {}
        shape = ""
        for k in ("macro_trend_shape_5", "macro_btc_trend_shape_5", "macro_eth_trend_shape_5"):
            try:
                v = str(f.get(k) or "").strip()
                if v:
                    shape = v
                    break
            except Exception:
                continue
        if not shape:
            shape = "unknown"

        reg = ""
        for k in ("macro_btc_time_regime", "macro_eth_time_regime", "time_regime"):
            try:
                v = str(f.get(k) or "").strip()
                if v:
                    reg = v
                    break
            except Exception:
                continue
        if not reg:
            reg = "unknown"

        try:
            side = str(s.get("side") or "long").strip().lower() or "long"
        except Exception:
            side = "long"
        if side not in ("long", "short"):
            side = "long"

        vb = _vol_bucket(float(_vol_val(s)))
        lb = _edge_bucket(float(_liq_val(s)), liq_edges)
        sb = _edge_bucket(float(_spread_val(s)), spread_edges)
        return (shape, reg, side, vb, lb, sb)

    def _metrics_from_take(rets: List[float], takes: List[int]) -> Dict[str, Any]:
        pnl = []
        cum = 0.0
        taken = 0
        for i, (r, t) in enumerate(zip(rets, takes)):
            tr = 1 if int(t) == 1 else 0
            x = float(r) if tr else 0.0
            if tr:
                taken += 1
            cum += float(x)
            pnl.append({"date": f"t{i+1}", "pnl": float(x), "cum_pnl": float(cum)})
        rr = [float(it.get("pnl") or 0.0) for it in pnl if float(it.get("pnl") or 0.0) != 0.0]
        sharpe = 0.0
        sortino = 0.0
        try:
            if len(rr) >= 2:
                mu = sum(rr) / float(len(rr))
                var = sum((x - mu) ** 2 for x in rr) / float(max(1, len(rr) - 1))
                sd = math.sqrt(var) if var > 1e-12 else 0.0
                sharpe = float((mu / (sd + 1e-12)) * math.sqrt(252.0)) if sd > 0 else 0.0
                down = [float(min(0.0, float(x))) for x in rr]
                dd_var = sum((x ** 2) for x in down) / float(max(1, len(down)))
                dd = math.sqrt(dd_var) if dd_var > 1e-12 else 0.0
                sortino = float((mu / (dd + 1e-12)) * math.sqrt(252.0)) if dd > 0 else 0.0
        except Exception:
            sharpe = 0.0
            sortino = 0.0
        return {
            "count": int(len(rets)),
            "taken": int(taken),
            "coverage": float(taken) / float(max(1, len(rets))),
            "total_pnl": float(cum),
            "mean_return": float(cum) / float(max(1, taken)) if taken > 0 else 0.0,
            "sharpe": float(sharpe),
            "sortino": float(sortino),
            "maxdd": float(_max_drawdown_from_pnl(pnl)),
            "tail_loss_p95": float(_loss_tail_p(pnl, 0.95)),
        }

    def _trades_per_day(takes: List[int], ss: List[Dict[str, Any]]) -> Optional[float]:
        try:
            taken = sum(1 for t in takes if int(t) == 1)
        except Exception:
            taken = 0
        ts0 = None
        ts1 = None
        for s in ss:
            try:
                ts = int(s.get("ts") or 0)
            except Exception:
                ts = 0
            if ts <= 0:
                continue
            ts0 = ts if ts0 is None else min(int(ts0), int(ts))
            ts1 = ts if ts1 is None else max(int(ts1), int(ts))
        if ts0 is None or ts1 is None or int(ts1) <= int(ts0):
            return None
        days = float(int(ts1) - int(ts0)) / (24.0 * 3600.0 * 1000.0)
        if (not math.isfinite(float(days))) or float(days) <= 0.0:
            return None
        return float(taken) / float(days)

    def _take_decisions(ps: List[float], ss: List[Dict[str, Any]]) -> List[int]:
        if not use_thr:
            return [1 if float(p) >= 0.5 else 0 for p in ps]
        out: List[int] = []
        for p, s in zip(ps, ss):
            f = s.get("features") or {}
            ts0 = int(s.get("ts") or 0)
            pair0 = str(s.get("pair") or "")
            try:
                reg0 = _get_regime(f, pair=pair0, ts=ts0)
            except Exception:
                try:
                    reg0 = _get_regime(f)
                except Exception:
                    reg0 = "trend"
            try:
                thr = float(_get_threshold(str(reg0)))
            except Exception:
                thr = 0.5
            out.append(1 if float(p) >= float(thr) else 0)
        return out
    
    def _fit_calibrator(method: str, train_preds: List[float], train_labels: List[int]):
        mth = (method or "").lower()
        if mth == "isotonic":
            try:
                from sklearn.isotonic import IsotonicRegression

                ir = IsotonicRegression(y_min=0.0, y_max=1.0, out_of_bounds="clip")
                ir.fit(train_preds, train_labels)
                return lambda p: float(ir.predict([float(p)])[0])
            except Exception:
                params = _platt_fit_1d(train_preds, train_labels)
                return lambda p: float(_sigmoid(float(params.get("a", 1.0)) * float(p) + float(params.get("b", 0.0))))

        try:
            from sklearn.linear_model import LogisticRegression

            lr = LogisticRegression()
            X = [[float(p)] for p in train_preds]
            y = train_labels
            lr.fit(X, y)
            return lambda p: float(lr.predict_proba([[float(p)]])[0][1])
        except Exception:
            params = _platt_fit_1d(train_preds, train_labels)
            return lambda p: float(_sigmoid(float(params.get("a", 1.0)) * float(p) + float(params.get("b", 0.0))))

    fam = str(family or "xgb").lower().strip()
    for i in range(1, folds):
        train_end = i * chunk_size
        test_end = (i + 1) * chunk_size
        test_set = samples[train_end:test_end]
        if not test_set:
            continue
        split_ts = int(test_set[0].get("ts") or 0)
        cutoff_ts = int(split_ts) - int(emb_ms)
        train_set = [s for s in samples[:train_end] if int(s.get("ts") or 0) <= int(cutoff_ts)]
        if len(train_set) < 20:
            continue

        model: Dict[str, Any] = {}
        if fam == "lr":
            model = _lr_train(train_set, {})
        elif fam == "rf":
            model = _rf_train(train_set, {})
        elif fam == "xgb":
            model = _xgb_train(train_set, {"n_estimators": 50})
        elif fam == "nn":
            model = _nn_train(train_set, {"epochs": 30})
        elif fam == "lstm":
            model = _lstm_train(train_set, {"epochs": 20, "seq_len": 1})
        else:
            model = _xgb_train(train_set, {"n_estimators": 50})

        train_preds, train_labels = [], []
        for s in train_set:
            train_labels.append(int(s.get("label", 0)))
            try:
                train_preds.append(float(_predict_with_model(model, s.get("features", {}) or {})))
            except Exception:
                train_preds.append(float(_score(s.get("features", {}) or {}, "long")))

        preds, labels, rets = [], [], []
        for s in test_set:
            labels.append(int(s.get("label", 0)))
            tr = None
            try:
                tr = (s.get("targets") or {}).get("return_tk")
            except Exception:
                tr = None
            if tr is None:
                rets.append(1.0 if int(s.get("label", 0)) == 1 else -1.0)
            else:
                rets.append(float(tr))
            try:
                preds.append(float(_predict_with_model(model, s.get("features", {}) or {})))
            except Exception:
                preds.append(float(_score(s.get("features", {}) or {}, "long")))

        takes = _take_decisions(preds, test_set)
        base_takes = [1 for _ in takes]

        m_raw = _metrics_from_take(rets, takes)
        m_base = _metrics_from_take(rets, base_takes)
        tpd_raw = _trades_per_day(takes, test_set)
        tpd_base = _trades_per_day(base_takes, test_set)
        if tpd_raw is not None:
            m_raw["trades_per_day"] = float(tpd_raw)
        if tpd_base is not None:
            m_base["trades_per_day"] = float(tpd_base)
        m_raw["uplift_mean_return"] = float(m_raw.get("mean_return", 0.0)) - float(m_base.get("mean_return", 0.0))
        m_raw["uplift_total_pnl"] = float(m_raw.get("total_pnl", 0.0)) - float(m_base.get("total_pnl", 0.0))

        rets_stress = [float(r) - float(stress_cost) if int(t) == 1 else float(r) for r, t in zip(rets, base_takes)]
        m_stress = _metrics_from_take([float(r) - float(stress_cost) if int(t) == 1 else float(r) for r, t in zip(rets, takes)], takes)
        m_base_stress = _metrics_from_take(rets_stress, base_takes)
        if tpd_raw is not None:
            m_stress["trades_per_day"] = float(tpd_raw)
        if tpd_base is not None:
            m_base_stress["trades_per_day"] = float(tpd_base)
        m_stress["uplift_mean_return"] = float(m_stress.get("mean_return", 0.0)) - float(m_base_stress.get("mean_return", 0.0))
        m_stress["uplift_total_pnl"] = float(m_stress.get("total_pnl", 0.0)) - float(m_base_stress.get("total_pnl", 0.0))

        metrics_item: Dict[str, Any] = {
            "split_ts": int(split_ts),
            "embargo_ms": int(emb_ms),
            "train_n": int(len(train_set)),
            "test_n": int(len(test_set)),
            "raw": m_raw,
            "baseline": m_base,
            "stressed": m_stress,
            "baseline_stressed": m_base_stress,
            "stress_cost_pct": float(stress_cost),
            "use_thresholds": bool(use_thr),
            "vol_edges": list(vol_edges),
            "liq_edges": list(liq_edges),
            "spread_edges": list(spread_edges),
        }
        g_return = (float(m_stress.get("mean_return", 0.0) or 0.0) >= float(m_base_stress.get("mean_return", 0.0) or 0.0)) or (float(m_stress.get("uplift_mean_return", 0.0) or 0.0) > 0.0)
        g_tail = float(m_stress.get("tail_loss_p95", 0.0) or 0.0) <= float(m_base_stress.get("tail_loss_p95", 0.0) or 0.0)
        g_dd = float(m_stress.get("maxdd", 0.0) or 0.0) <= float(m_base_stress.get("maxdd", 0.0) or 0.0)
        g_cost = float(m_stress.get("uplift_mean_return", 0.0) or 0.0) > 0.0
        metrics_item["triple_gate"] = {
            "pass": bool(g_return and g_tail and g_dd and g_cost),
            "return_not_worse": bool(g_return),
            "tail_not_worse": bool(g_tail),
            "maxdd_not_worse": bool(g_dd),
            "cost_stress_pass": bool(g_cost),
        }

        if calibrate_method:
            try:
                cal = _fit_calibrator(str(calibrate_method), train_preds, train_labels)
                preds_cal = [float(cal(p)) for p in preds]
                takes_cal = _take_decisions(preds_cal, test_set)
                m_cal = _metrics_from_take(rets, takes_cal)
                m_cal_base = _metrics_from_take(rets, base_takes)
                m_cal["uplift_mean_return"] = float(m_cal.get("mean_return", 0.0)) - float(m_cal_base.get("mean_return", 0.0))
                m_cal["uplift_total_pnl"] = float(m_cal.get("total_pnl", 0.0)) - float(m_cal_base.get("total_pnl", 0.0))
                m_cal_stress = _metrics_from_take([float(r) - float(stress_cost) if int(t) == 1 else float(r) for r, t in zip(rets, takes_cal)], takes_cal)
                m_cal_base_stress = m_base_stress
                m_cal_stress["uplift_mean_return"] = float(m_cal_stress.get("mean_return", 0.0)) - float(m_cal_base_stress.get("mean_return", 0.0))
                m_cal_stress["uplift_total_pnl"] = float(m_cal_stress.get("total_pnl", 0.0)) - float(m_cal_base_stress.get("total_pnl", 0.0))
                metrics_item["calibrated"] = m_cal
                metrics_item["calibrated_stressed"] = m_cal_stress
                metrics_item["calibrate_method"] = str(calibrate_method).lower()
            except Exception as e:
                metrics_item["calibrated_error"] = str(e)

        if bucketed:
            by_bucket: Dict[str, Any] = {}
            by_bucket_stress: Dict[str, Any] = {}
            idxs: Dict[Tuple[str, str, str, str, str, str], List[int]] = {}
            for j, s in enumerate(test_set):
                idxs.setdefault(_bucket_key(s), []).append(int(j))

            try:
                min_bn = int(CONFIG.get("eval_bucketed_min_n", 30) or 30)
            except Exception:
                min_bn = 30
            min_bn = max(5, int(min_bn))

            for k, js in idxs.items():
                if len(js) < int(min_bn):
                    continue
                ss_b = [test_set[j] for j in js]
                rs = [float(rets[j]) for j in js]
                tk = [int(takes[j]) for j in js]
                btk = [1 for _ in js]
                mm = _metrics_from_take(rs, tk)
                bb = _metrics_from_take(rs, btk)
                tpd_m = _trades_per_day(tk, ss_b)
                tpd_b = _trades_per_day(btk, ss_b)
                if tpd_m is not None:
                    mm["trades_per_day"] = float(tpd_m)
                if tpd_b is not None:
                    bb["trades_per_day"] = float(tpd_b)
                mm["uplift_mean_return"] = float(mm.get("mean_return", 0.0)) - float(bb.get("mean_return", 0.0))
                mm["uplift_total_pnl"] = float(mm.get("total_pnl", 0.0)) - float(bb.get("total_pnl", 0.0))
                key_s = f"shape={k[0]}|regime={k[1]}|side={k[2]}|vol={k[3]}|liq={k[4]}|spread={k[5]}"
                by_bucket[key_s] = {"model": mm, "baseline": bb, "n": int(len(js))}

                rs_stress = [float(rets[j]) - float(stress_cost) for j in js]
                mm_s = _metrics_from_take([float(rets[j]) - float(stress_cost) if int(takes[j]) == 1 else float(rets[j]) for j in js], tk)
                bb_s = _metrics_from_take(rs_stress, btk)
                if tpd_m is not None:
                    mm_s["trades_per_day"] = float(tpd_m)
                if tpd_b is not None:
                    bb_s["trades_per_day"] = float(tpd_b)
                mm_s["uplift_mean_return"] = float(mm_s.get("mean_return", 0.0)) - float(bb_s.get("mean_return", 0.0))
                mm_s["uplift_total_pnl"] = float(mm_s.get("total_pnl", 0.0)) - float(bb_s.get("total_pnl", 0.0))
                by_bucket_stress[key_s] = {"model": mm_s, "baseline": bb_s, "n": int(len(js))}

            metrics_item["buckets"] = by_bucket
            metrics_item["buckets_stressed"] = by_bucket_stress

        metrics_list.append(metrics_item)

    if not metrics_list:
        return {
            "ok": False,
            "error": "not_enough_effective_folds",
            "n": int(n),
            "folds": int(folds),
            "embargo_ms": int(emb_ms),
        }
        
    def _avg(key: str, sub: str = None) -> float:
        vals = []
        for it in metrics_list:
            mm = it.get(key) or {}
            if sub is None:
                continue
            if sub in mm:
                vals.append(float(mm.get(sub) or 0.0))
        if not vals:
            return 0.0
        return float(sum(vals) / float(len(vals)))

    def _avg_opt(key: str, sub: str) -> Optional[float]:
        vals: List[float] = []
        for it in metrics_list:
            mm = it.get(key)
            if not isinstance(mm, dict):
                continue
            if sub not in mm:
                continue
            v = mm.get(sub)
            if v is None:
                continue
            try:
                f = float(v)
            except Exception:
                continue
            if not math.isfinite(float(f)):
                continue
            vals.append(float(f))
        if not vals:
            return None
        return float(sum(vals) / float(len(vals)))

    out = {
        "ok": True,
        "folds": folds,
        "folds_used": int(len(metrics_list)),
        "embargo_ms": int(emb_ms),
        "use_thresholds": bool(use_thr),
        "stress_cost_pct": float(stress_cost),
        "vol_edges": list(vol_edges),
        "liq_edges": list(liq_edges),
        "spread_edges": list(spread_edges),
        "avg": {
            "raw": {
                "coverage": _avg("raw", "coverage"),
                "mean_return": _avg("raw", "mean_return"),
                "sharpe": _avg("raw", "sharpe"),
                "sortino": _avg("raw", "sortino"),
                "maxdd": _avg("raw", "maxdd"),
                "tail_loss_p95": _avg("raw", "tail_loss_p95"),
                "uplift_mean_return": _avg("raw", "uplift_mean_return"),
                "trades_per_day": _avg_opt("raw", "trades_per_day"),
            }
        },
        "details": metrics_list,
    }
    if calibrate_method:
        out["avg"]["calibrated"] = {
            "coverage": _avg("calibrated", "coverage"),
            "mean_return": _avg("calibrated", "mean_return"),
            "sharpe": _avg("calibrated", "sharpe"),
            "sortino": _avg("calibrated", "sortino"),
            "maxdd": _avg("calibrated", "maxdd"),
            "tail_loss_p95": _avg("calibrated", "tail_loss_p95"),
            "uplift_mean_return": _avg("calibrated", "uplift_mean_return"),
            "trades_per_day": _avg_opt("calibrated", "trades_per_day"),
        }

    out["avg"]["stressed"] = {
        "coverage": _avg("stressed", "coverage"),
        "mean_return": _avg("stressed", "mean_return"),
        "sharpe": _avg("stressed", "sharpe"),
        "sortino": _avg("stressed", "sortino"),
        "maxdd": _avg("stressed", "maxdd"),
        "tail_loss_p95": _avg("stressed", "tail_loss_p95"),
        "uplift_mean_return": _avg("stressed", "uplift_mean_return"),
        "trades_per_day": _avg_opt("stressed", "trades_per_day"),
    }
    out["avg"]["baseline_stressed"] = {
        "coverage": _avg("baseline_stressed", "coverage"),
        "mean_return": _avg("baseline_stressed", "mean_return"),
        "sharpe": _avg("baseline_stressed", "sharpe"),
        "sortino": _avg("baseline_stressed", "sortino"),
        "maxdd": _avg("baseline_stressed", "maxdd"),
        "tail_loss_p95": _avg("baseline_stressed", "tail_loss_p95"),
        "trades_per_day": _avg_opt("baseline_stressed", "trades_per_day"),
    }
    if calibrate_method:
        out["avg"]["calibrated_stressed"] = {
            "coverage": _avg("calibrated_stressed", "coverage"),
            "mean_return": _avg("calibrated_stressed", "mean_return"),
            "sharpe": _avg("calibrated_stressed", "sharpe"),
            "sortino": _avg("calibrated_stressed", "sortino"),
            "maxdd": _avg("calibrated_stressed", "maxdd"),
            "tail_loss_p95": _avg("calibrated_stressed", "tail_loss_p95"),
            "uplift_mean_return": _avg("calibrated_stressed", "uplift_mean_return"),
            "trades_per_day": _avg_opt("calibrated_stressed", "trades_per_day"),
        }

    test_n_total = 0
    for it in metrics_list:
        try:
            test_n_total += int(it.get("test_n") or 0)
        except Exception:
            continue
    oos_ratio = (float(test_n_total) / float(max(1, n)))
    out["oos"] = {
        "test_n": int(test_n_total),
        "total_n": int(n),
        "ratio": float(oos_ratio),
        "min_ratio_required": float(CONFIG.get("acceptance_min_oos_ratio", 0.30) or 0.30),
        "min_folds_required": int(CONFIG.get("acceptance_min_wfo_folds", 3) or 3),
    }

    fold_pass_n = 0
    fold_return_pass_n = 0
    fold_tail_pass_n = 0
    fold_dd_pass_n = 0
    fold_cost_pass_n = 0
    fold_uplifts: List[float] = []
    fold_mean_model: List[float] = []
    fold_mean_base: List[float] = []
    for it in metrics_list:
        tg = it.get("triple_gate") if isinstance(it.get("triple_gate"), dict) else {}
        if bool(tg.get("pass")):
            fold_pass_n += 1
        if bool(tg.get("return_not_worse")):
            fold_return_pass_n += 1
        if bool(tg.get("tail_not_worse")):
            fold_tail_pass_n += 1
        if bool(tg.get("maxdd_not_worse")):
            fold_dd_pass_n += 1
        if bool(tg.get("cost_stress_pass")):
            fold_cost_pass_n += 1
        try:
            fold_uplifts.append(float((it.get("stressed") or {}).get("uplift_mean_return") or 0.0))
        except Exception:
            fold_uplifts.append(0.0)
        try:
            fold_mean_model.append(float((it.get("stressed") or {}).get("mean_return") or 0.0))
        except Exception:
            fold_mean_model.append(0.0)
        try:
            fold_mean_base.append(float((it.get("baseline_stressed") or {}).get("mean_return") or 0.0))
        except Exception:
            fold_mean_base.append(0.0)

    fold_n = int(len(metrics_list))
    fold_pass_ratio = (float(fold_pass_n) / float(max(1, fold_n)))
    out["triple_gate"] = {
        "folds": int(fold_n),
        "pass_count": int(fold_pass_n),
        "pass_ratio": float(fold_pass_ratio),
        "return_pass_count": int(fold_return_pass_n),
        "tail_pass_count": int(fold_tail_pass_n),
        "maxdd_pass_count": int(fold_dd_pass_n),
        "cost_pass_count": int(fold_cost_pass_n),
        "min_pass_ratio_required": float(CONFIG.get("acceptance_min_fold_pass_ratio", 0.67) or 0.67),
    }

    try:
        ci_runs = int(CONFIG.get("acceptance_bootstrap_runs", 400) or 400)
    except Exception:
        ci_runs = 400
    ci_runs = max(50, min(10000, int(ci_runs)))
    try:
        ci_alpha = float(CONFIG.get("acceptance_bootstrap_ci_alpha", 0.05) or 0.05)
    except Exception:
        ci_alpha = 0.05
    ci_alpha = float(_clip(float(ci_alpha), 0.001, 0.20))

    ci_low = 0.0
    ci_high = 0.0
    if fold_uplifts:
        rng = random.Random(1337)
        boot_vals: List[float] = []
        m = int(len(fold_uplifts))
        for _ in range(ci_runs):
            acc = 0.0
            for _j in range(m):
                acc += float(fold_uplifts[rng.randrange(m)])
            boot_vals.append(float(acc) / float(max(1, m)))
        boot_vals.sort()
        lo_q = float(ci_alpha / 2.0)
        hi_q = float(1.0 - ci_alpha / 2.0)
        i_lo = int(max(0, min(len(boot_vals) - 1, round(lo_q * (len(boot_vals) - 1)))))
        i_hi = int(max(0, min(len(boot_vals) - 1, round(hi_q * (len(boot_vals) - 1)))))
        ci_low = float(boot_vals[i_lo])
        ci_high = float(boot_vals[i_hi])
    out["significance"] = {
        "uplift_mean_return_ci": {"alpha": float(ci_alpha), "low": float(ci_low), "high": float(ci_high)},
        "uplift_mean_return_avg": float(sum(fold_uplifts) / float(max(1, len(fold_uplifts)))) if fold_uplifts else 0.0,
    }

    p05_model = float(_q(fold_mean_model, 0.05)) if fold_mean_model else 0.0
    p05_base = float(_q(fold_mean_base, 0.05)) if fold_mean_base else 0.0
    out["p05_guard"] = {
        "model_mean_return_p05": float(p05_model),
        "baseline_mean_return_p05": float(p05_base),
    }

    capacity_limits: Dict[str, Any] = {}
    try:
        base_notional = float(CONFIG.get("capacity_base_notional_usdc", 10000.0) or 10000.0)
    except Exception:
        base_notional = 10000.0
    try:
        base_open_trades = int(CONFIG.get("capacity_max_open_trades_base", 5) or 5)
    except Exception:
        base_open_trades = 5
    try:
        base_slip_bps = float(CONFIG.get("capacity_slippage_cap_bps_base", 20.0) or 20.0)
    except Exception:
        base_slip_bps = 20.0

    for it in metrics_list:
        bmap = it.get("buckets_stressed")
        if not isinstance(bmap, dict):
            continue
        for k, v in bmap.items():
            if not isinstance(v, dict):
                continue
            mm = v.get("model") if isinstance(v.get("model"), dict) else {}
            bb = v.get("baseline") if isinstance(v.get("baseline"), dict) else {}
            n0 = int(v.get("n") or 0)
            m_u = float(mm.get("uplift_mean_return") or 0.0)
            m_t = float(mm.get("tail_loss_p95") or 0.0)
            b_t = float(bb.get("tail_loss_p95") or 0.0)
            m_d = float(mm.get("maxdd") or 0.0)
            b_d = float(bb.get("maxdd") or 0.0)
            quality = 1.0
            if float(m_u) <= 0.0:
                quality *= 0.50
            if float(m_t) > float(b_t):
                quality *= 0.70
            if float(m_d) > float(b_d):
                quality *= 0.70
            quality *= float(_clip(float(n0) / 100.0, 0.20, 1.0))
            quality = float(_clip(float(quality), 0.10, 1.00))
            capacity_limits[str(k)] = {
                "n": int(n0),
                "quality_score": float(quality),
                "max_notional_usdc": float(base_notional) * float(quality),
                "max_open_trades": max(1, int(round(float(base_open_trades) * float(quality)))),
                "slippage_cap_bps": float(base_slip_bps) * (1.0 + (1.0 - float(quality))),
            }
    out["capacity"] = {"limits_by_bucket": capacity_limits}

    gate_pass = True
    gate_reasons: List[str] = []
    try:
        u0 = float(out.get("avg", {}).get("stressed", {}).get("uplift_mean_return", 0.0) or 0.0)
    except Exception:
        u0 = 0.0
    if float(u0) <= 0.0:
        gate_pass = False
        gate_reasons.append("stress_uplift_non_positive")
    try:
        mr0 = float(out.get("avg", {}).get("stressed", {}).get("mean_return", 0.0) or 0.0)
    except Exception:
        mr0 = 0.0
    if float(mr0) <= 0.0:
        gate_pass = False
        gate_reasons.append("stress_mean_return_non_positive")
    tpd0 = (out.get("avg", {}).get("stressed", {}) or {}).get("trades_per_day")
    try:
        tpd0 = (None if tpd0 is None else float(tpd0))
    except Exception:
        tpd0 = None
    try:
        tpd_cap = CONFIG.get("paramopt_max_trades_per_day")
        tpd_cap = (None if tpd_cap is None else float(tpd_cap))
    except Exception:
        tpd_cap = None
    if tpd_cap is not None and tpd0 is not None:
        if math.isfinite(float(tpd_cap)) and float(tpd_cap) > 0.0 and math.isfinite(float(tpd0)) and float(tpd0) > float(tpd_cap):
            gate_pass = False
            gate_reasons.append("trades_per_day_cap")
    try:
        dd_cap = CONFIG.get("paramopt_gate_maxdd")
        dd_cap = (None if dd_cap is None else float(dd_cap))
    except Exception:
        dd_cap = None
    if dd_cap is not None:
        try:
            dd0 = float(out.get("avg", {}).get("stressed", {}).get("maxdd", 0.0) or 0.0)
        except Exception:
            dd0 = 0.0
        if math.isfinite(float(dd_cap)) and float(dd_cap) > 0.0 and math.isfinite(float(dd0)) and float(dd0) > float(dd_cap):
            gate_pass = False
            gate_reasons.append("maxdd_cap")
    try:
        tail_cap = CONFIG.get("paramopt_gate_tail_loss_p95")
        tail_cap = (None if tail_cap is None else float(tail_cap))
    except Exception:
        tail_cap = None
    if tail_cap is not None:
        try:
            tl0 = float(out.get("avg", {}).get("stressed", {}).get("tail_loss_p95", 0.0) or 0.0)
        except Exception:
            tl0 = 0.0
        if math.isfinite(float(tail_cap)) and float(tail_cap) > 0.0 and math.isfinite(float(tl0)) and float(tl0) > float(tail_cap):
            gate_pass = False
            gate_reasons.append("tail_loss_p95_cap")
    try:
        min_fold_ratio = float(CONFIG.get("acceptance_min_fold_pass_ratio", 0.67) or 0.67)
    except Exception:
        min_fold_ratio = 0.67
    min_fold_ratio = float(_clip(float(min_fold_ratio), 0.0, 1.0))
    if float(fold_pass_ratio) + 1e-12 < float(min_fold_ratio):
        gate_pass = False
        gate_reasons.append("fold_pass_ratio_too_low")
    if float(ci_low) < 0.0:
        gate_pass = False
        gate_reasons.append("bootstrap_ci_low_negative")
    if bool(CONFIG.get("acceptance_p05_not_worse", True)):
        if float(p05_model) + 1e-12 < float(p05_base):
            gate_pass = False
            gate_reasons.append("p05_worse_than_baseline")
    if bool(CONFIG.get("acceptance_tail_not_worse", True)):
        try:
            tl_model_avg = float(out.get("avg", {}).get("stressed", {}).get("tail_loss_p95", 0.0) or 0.0)
            tl_base_avg = float(out.get("avg", {}).get("baseline_stressed", {}).get("tail_loss_p95", 0.0) or 0.0)
        except Exception:
            tl_model_avg = 0.0
            tl_base_avg = 0.0
        if float(tl_model_avg) > float(tl_base_avg):
            gate_pass = False
            gate_reasons.append("tail_loss_worse_than_baseline")
    try:
        dd0 = float(out.get("avg", {}).get("stressed", {}).get("maxdd", 0.0) or 0.0)
    except Exception:
        dd0 = 0.0
    try:
        tl0 = float(out.get("avg", {}).get("stressed", {}).get("tail_loss_p95", 0.0) or 0.0)
    except Exception:
        tl0 = 0.0
    out["gate"] = {
        "pass": bool(gate_pass),
        "reasons": gate_reasons,
        "metrics": {
            "stress_uplift_mean_return": float(u0),
            "stress_mean_return": float(mr0),
            "trades_per_day": (None if tpd0 is None else float(tpd0)),
            "maxdd": float(dd0),
            "tail_loss_p95": float(tl0),
        },
        "thresholds": {
            "tpd_cap": (None if tpd_cap is None else float(tpd_cap)),
            "maxdd_cap": (None if dd_cap is None else float(dd_cap)),
            "tail_loss_p95_cap": (None if tail_cap is None else float(tail_cap)),
            "min_fold_pass_ratio": float(min_fold_ratio),
            "bootstrap_ci_low_min": 0.0,
            "p05_not_worse_required": bool(CONFIG.get("acceptance_p05_not_worse", True)),
            "tail_not_worse_required": bool(CONFIG.get("acceptance_tail_not_worse", True)),
        },
    }
    return out

def _monte_carlo_verify(
    family: str = "xgb",
    runs: int = 200,
    window: int = 5000,
    calibrated: bool = True,
    p_noise_std: float = 0.02,
    ret_noise_std: float = 0.0,
    cost_pct: float = 0.0,
    bootstrap: bool = True,
    drop_frac: float = 0.0,
    seed: int = None,
) -> Dict[str, Any]:
    samples = sorted(EVAL_SAMPLES, key=lambda x: x.get("ts", 0))
    if not samples:
        return {"ok": False, "error": "no_samples"}
    if window and window > 0:
        samples = samples[-int(window):]
    if len(samples) < 50:
        return {"ok": False, "error": "not_enough_samples", "n": len(samples)}

    fam = str(family or EVAL_MODELS.get("active_family") or "lr").lower()
    m = EVAL_MODELS.get(fam)

    base_preds: List[float] = []
    labels: List[int] = []
    rets: List[float] = []
    for s in samples:
        f = s.get("features") or {}
        y = int(s.get("label", 0))
        labels.append(y)
        tr = None
        try:
            tr = (s.get("targets") or {}).get("return_tk")
        except Exception:
            tr = None
        if tr is None:
            rets.append(1.0 if y == 1 else -1.0)
        else:
            rets.append(float(tr))
        if fam == "committee" and isinstance(m, dict) and m.get("type") == "committee":
            p = float(_committee_predict(m, f))
        elif fam == "lr" and m:
            p = float(_lr_predict(m.get("weights", {}), float(m.get("bias", 0.0)), f))
        elif fam == "rf" and m:
            p = float(_rf_predict(m, f))
        elif fam == "xgb" and m:
            p = float(_xgb_predict(m, f))
        elif fam == "nn" and m:
            p = float(_nn_predict(m, f))
        elif fam == "lstm" and m:
            p = float(_lstm_predict(m, f))
        else:
            p = float(_score(f, "long"))
        if calibrated:
            p = float(_calibrate(p, f))
        base_preds.append(float(_clip(p, 0.0, 1.0)))

    n = len(labels)
    rng = random.Random()
    if seed is not None:
        rng.seed(int(seed))

    runs = max(1, min(5000, int(runs)))
    p_noise_std = float(max(0.0, min(0.5, p_noise_std)))
    ret_noise_std = float(max(0.0, min(1.0, ret_noise_std)))
    cost_pct = float(max(0.0, min(0.2, cost_pct)))
    drop_frac = float(max(0.0, min(0.9, drop_frac)))

    vals: Dict[str, List[float]] = {"auc": [], "brier": [], "win_rate": [], "coverage": [], "mean_return": [], "sharpe": []}
    for _ in range(runs):
        if bootstrap:
            idx = [rng.randrange(n) for _ in range(n)]
        else:
            idx = list(range(n))
            if drop_frac > 0:
                keep_n = max(10, int((1.0 - drop_frac) * n))
                rng.shuffle(idx)
                idx = idx[:keep_n]

        preds_run: List[float] = []
        labels_run: List[int] = []
        rets_run: List[float] = []
        for i in idx:
            pp = float(base_preds[i])
            if p_noise_std > 0:
                pp = float(_clip(pp + rng.gauss(0.0, p_noise_std), 0.0, 1.0))
            rr = float(rets[i])
            if cost_pct > 0:
                rr -= cost_pct
            if ret_noise_std > 0:
                rr += rng.gauss(0.0, ret_noise_std)
            preds_run.append(pp)
            labels_run.append(int(labels[i]))
            rets_run.append(rr)

        met = _compute_metrics(preds_run, labels_run, returns=rets_run)
        for k in vals.keys():
            vals[k].append(float(met.get(k, 0.0) or 0.0))

    def _pct(xs: List[float], q: float) -> float:
        if not xs:
            return 0.0
        ys = sorted(xs)
        pos = int(round(q * float(len(ys) - 1)))
        pos = max(0, min(len(ys) - 1, pos))
        return float(ys[pos])

    out = {
        "ok": True,
        "family": fam,
        "n": n,
        "runs": runs,
        "params": {
            "window": int(window),
            "calibrated": bool(calibrated),
            "p_noise_std": float(p_noise_std),
            "ret_noise_std": float(ret_noise_std),
            "cost_pct": float(cost_pct),
            "bootstrap": bool(bootstrap),
            "drop_frac": float(drop_frac),
            "seed": int(seed) if seed is not None else None,
        },
        "metrics": {
            "mean": {k: float(sum(v) / float(len(v))) if v else 0.0 for k, v in vals.items()},
            "p05": {k: _pct(v, 0.05) for k, v in vals.items()},
            "p50": {k: _pct(v, 0.50) for k, v in vals.items()},
            "p95": {k: _pct(v, 0.95) for k, v in vals.items()},
        },
    }
    return out

@app.route("/evaluation/heatmap", methods=["GET"])
def evaluation_heatmap():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    family = str(request.args.get("family", EVAL_MODELS.get("active_family", "lr"))).lower()
    window = int(request.args.get("window", "2000"))
    use_calibrated = str(request.args.get("calibrated", "true")).lower() in ("1", "true", "yes", "on")

    samples = sorted(EVAL_SAMPLES, key=lambda x: x.get("ts", 0))
    if not samples:
        return jsonify({"ok": False, "error": "no_samples"})
    if window > 0:
        samples = samples[-window:]

    m = EVAL_MODELS.get(family)
    counts = [[0 for _ in range(24)] for _ in range(7)]
    wins = [[0 for _ in range(24)] for _ in range(7)]
    sums = [[0.0 for _ in range(24)] for _ in range(7)]

    for s in samples:
        ts = int(s.get("ts") or 0)
        if ts <= 0:
            continue
        dt = datetime.fromtimestamp(ts / 1000.0, tz=timezone.utc)
        wd = int(dt.weekday())
        hh = int(dt.hour)
        f = s.get("features") or {}
        y = int(s.get("label", 0))
        tr = None
        try:
            tr = (s.get("targets") or {}).get("return_tk")
        except Exception:
            tr = None
        r = float(tr) if tr is not None else (1.0 if y == 1 else -1.0)

        if family == "committee" and isinstance(m, dict) and m.get("type") == "committee":
            p = float(_committee_predict(m, f))
        elif family == "lr" and m:
            p = float(_lr_predict(m.get("weights", {}), float(m.get("bias", 0.0)), f))
        elif family == "rf" and m:
            p = float(_rf_predict(m, f))
        elif family == "xgb" and m:
            p = float(_xgb_predict(m, f))
        elif family == "nn" and m:
            p = float(_nn_predict(m, f))
        elif family == "lstm" and m:
            p = float(_lstm_predict(m, f))
        else:
            p = float(_score(f, "long"))

        if use_calibrated:
            p = float(_calibrate(p, f))

        reg = _get_regime(f)
        thr = float(_get_threshold(reg))
        if p < thr:
            continue

        counts[wd][hh] += 1
        wins[wd][hh] += 1 if r > 0 else 0
        sums[wd][hh] += float(r)

    mean_return = [[0.0 for _ in range(24)] for _ in range(7)]
    win_rate = [[0.0 for _ in range(24)] for _ in range(7)]
    for d in range(7):
        for h in range(24):
            c = counts[d][h]
            if c > 0:
                mean_return[d][h] = float(sums[d][h]) / float(c)
                win_rate[d][h] = float(wins[d][h]) / float(c)

    return jsonify({
        "ok": True,
        "family": family,
        "window": window,
        "calibrated": use_calibrated,
        "counts": counts,
        "mean_return": mean_return,
        "win_rate": win_rate,
    })

@app.route("/evaluation/equity_curve", methods=["GET"])
def evaluation_equity_curve():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    family = str(request.args.get("family", EVAL_MODELS.get("active_family", "lr"))).lower()
    window = int(request.args.get("window", "5000"))
    use_calibrated = str(request.args.get("calibrated", "true")).lower() in ("1", "true", "yes", "on")

    samples = sorted(EVAL_SAMPLES, key=lambda x: x.get("ts", 0))
    if not samples:
        return jsonify({"ok": False, "error": "no_samples"})
    if window > 0:
        samples = samples[-window:]

    m = EVAL_MODELS.get(family)
    cum = 0.0
    curve = []
    for s in samples:
        ts = int(s.get("ts") or 0)
        if ts <= 0:
            continue
        f = s.get("features") or {}
        y = int(s.get("label", 0))
        tr = None
        try:
            tr = (s.get("targets") or {}).get("return_tk")
        except Exception:
            tr = None
        r = float(tr) if tr is not None else (1.0 if y == 1 else -1.0)

        if family == "committee" and isinstance(m, dict) and m.get("type") == "committee":
            p = float(_committee_predict(m, f))
        elif family == "lr" and m:
            p = float(_lr_predict(m.get("weights", {}), float(m.get("bias", 0.0)), f))
        elif family == "rf" and m:
            p = float(_rf_predict(m, f))
        elif family == "xgb" and m:
            p = float(_xgb_predict(m, f))
        elif family == "nn" and m:
            p = float(_nn_predict(m, f))
        elif family == "lstm" and m:
            p = float(_lstm_predict(m, f))
        else:
            p = float(_score(f, "long"))

        if use_calibrated:
            p = float(_calibrate(p, f))
        thr = float(_get_threshold(_get_regime(f)))
        take = 1 if p >= thr else 0
        cum += float(r) if take else 0.0
        curve.append({"ts": ts, "cum_pnl": float(cum), "p": float(p), "threshold": float(thr), "take": int(take)})

    return jsonify({"ok": True, "family": family, "window": window, "calibrated": use_calibrated, "curve": curve})

