@app.route("/automation/backtest/run", methods=["POST"])
def automation_backtest_run():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    config_path = str(data.get("config", "user_data/config_local_backtest.json"))
    if (".." in config_path) or config_path.startswith("/") or config_path.startswith("\\") or (not config_path.startswith("user_data/")) or (not config_path.lower().endswith(".json")):
        return jsonify({"ok": False, "error": "bad_config"}), 400
    timerange = data.get("timerange")
    strategy = data.get("strategy")
    sandbox_path = data.get("sandbox_path")
    strategy_name = data.get("strategy_name")
    inject_res = None
    strategy_path = None
    if sandbox_path:
        st_name = str(strategy_name or strategy or "").strip()
        if not st_name:
            return jsonify({"ok": False, "error": "missing_strategy_name"}), 400
        root = Path(str(sandbox_path)).expanduser()
        try:
            root = root.resolve()
        except Exception:
            return jsonify({"ok": False, "error": "bad_sandbox_path"}), 400
        try:
            bases = [
                _strategy_sandbox_dir().resolve(),
                (_user_data_dir() / "strategies" / "github").resolve(),
            ]
            if not any(str(root).startswith(str(b)) for b in bases):
                return jsonify({"ok": False, "error": "sandbox_outside_base"}), 400
        except Exception:
            return jsonify({"ok": False, "error": "sandbox_outside_base"}), 400
        files = _strategy_pick_files(root, strategy_name=st_name)
        if not files:
            return jsonify({"ok": False, "error": "strategy_file_not_found"}), 404
        hits = _strategy_scan_forbidden(files)
        if hits:
            return jsonify({"ok": False, "error": "strategy_forbidden_tokens", "hits": hits}), 400
        strategy = st_name
        strategy_path = str(root)
    env_overrides = data.get("env") or None
    timeout_sec = float(data.get("timeout_sec", 1800) or 1800)
    res = _run_backtest(config_path, timerange, strategy=strategy, strategy_path=strategy_path, env_overrides=env_overrides, timeout_sec=timeout_sec)
    if inject_res:
        res["inject"] = inject_res
    try:
        if isinstance(res, dict) and isinstance(res.get("metrics_summary"), dict):
            res["summary"] = {"metrics": res.get("metrics_summary")}
    except Exception:
        pass
    try:
        if isinstance(res, dict) and bool(res.get("ok")):
            z = res.get("result_zip")
            zname = (None if z is None else str(z).strip())
            if zname and zname.lower().endswith(".zip") and ("/" not in zname) and ("\\" not in zname) and (".." not in zname):
                rep = _backtest_report_from_zip(_backtests_dir() / zname, strategy=(None if strategy is None else str(strategy)))
                if isinstance(rep, dict):
                    res["report"] = rep
    except Exception:
        pass
    try:
        _audit_emit_action(
            "automation.backtest.run",
            _audit_base_payload(
                scope="sandbox",
                action="automation.backtest.run",
                trace_id=trace_id,
                extra={
                    "config": config_path,
                    "timerange": timerange,
                    "strategy": strategy,
                    "sandbox_path": sandbox_path,
                },
            ),
        )
    except Exception:
        pass
    return jsonify(res)


def _bt_tf_minutes(v):
    s = "" if v is None else str(v).strip().lower()
    if not s:
        return None
    try:
        if s.endswith("m"):
            return int(s[:-1])
        if s.endswith("h"):
            return int(s[:-1]) * 60
        if s.endswith("d"):
            return int(s[:-1]) * 1440
        if s.endswith("w"):
            return int(s[:-1]) * 10080
    except Exception:
        return None
    return None


def _bt_pair_key(pair):
    return ("" if pair is None else str(pair)).replace("/", "_").replace(":", "_")


def _bt_ohlcv_path(exchange, trading_mode, pair, timeframe):
    ex = "" if exchange is None else str(exchange).strip()
    tm = "" if trading_mode is None else str(trading_mode).strip()
    tf = "" if timeframe is None else str(timeframe).strip()
    if not ex or not tm or not tf:
        return None
    k = _bt_pair_key(pair)
    if not k:
        return None
    return _user_data_dir() / "data" / ex / tm / f"{k}-{tf}-{tm}.json"


def _bt_funding_path(exchange, trading_mode, pair):
    ex = "" if exchange is None else str(exchange).strip()
    tm = "" if trading_mode is None else str(trading_mode).strip()
    if not ex or not tm:
        return None
    k = _bt_pair_key(pair)
    if not k:
        return None
    return _user_data_dir() / "data" / ex / tm / f"{k}-8h-funding_rate.json"


def _bt_coverage_report(config, exchange=None, trading_mode=None, timeframe=None, check_funding_coverage=True):
    cfg = {} if not isinstance(config, dict) else config
    ex = exchange
    tm = trading_mode
    tf = timeframe
    try:
        if ex is None:
            ex = ((cfg.get("exchange") or {}) if isinstance(cfg.get("exchange"), dict) else {}).get("name")
        if tm is None:
            tm = cfg.get("trading_mode")
        if tf is None:
            tf = cfg.get("timeframe")
    except Exception:
        pass
    ex = "" if ex is None else str(ex).strip()
    tm = "" if tm is None else str(tm).strip()
    tf = "" if tf is None else str(tf).strip()

    pairs = []
    try:
        wl = ((cfg.get("exchange") or {}) if isinstance(cfg.get("exchange"), dict) else {}).get("pair_whitelist")
        if isinstance(wl, list):
            pairs = [str(x) for x in wl if x is not None and str(x).strip() != ""]
    except Exception:
        pairs = []

    missing = {}
    scored = []
    funding_missing = []
    for p in pairs:
        o = _bt_ohlcv_path(ex, tm, p, tf)
        ok_ohlcv = bool(o and o.exists() and o.is_file())
        if not ok_ohlcv:
            missing[p] = {"ohlcv": False}
        else:
            scored.append(p)
        if check_funding_coverage:
            f = _bt_funding_path(ex, tm, p)
            ok_funding = bool(f and f.exists() and f.is_file())
            if not ok_funding:
                funding_missing.append(p)
                mm = missing.get(p) or {}
                mm["funding_rate"] = False
                missing[p] = mm

    core_n = int(len(pairs))
    scored_n = int(len(scored))
    coverage_ratio = (0.0 if core_n <= 0 else float(scored_n) / float(core_n))

    return {
        "ok": True,
        "exchange": ex,
        "trading_mode": tm,
        "timeframe": tf,
        "core_pairs": pairs,
        "scored_pairs": scored,
        "missing": missing,
        "coverage_ratio": float(coverage_ratio),
        "funding_coverage": (False if (check_funding_coverage and len(funding_missing) > 0) else True),
        "funding_missing_pairs": funding_missing,
    }


def _bt_per_pair_metrics_from_zip(zip_path, strategy=None):
    p = Path(zip_path)
    main = _backtest_zip_load_main_json(p) or {}
    sb = _backtest_zip_strategy_block(main, strategy)
    v = (sb or {}).get("results_per_pair")
    if isinstance(v, list):
        out = []
        for x in v:
            if isinstance(x, dict):
                out.append(dict(x))
        return out
    return []


def _bt_daily_pnl_by_pair_from_zip(zip_path, strategy=None):
    p = Path(zip_path)
    trades = _backtest_zip_strategy_trades(p, strategy=strategy) or []
    out = {}
    for t in trades:
        if not isinstance(t, dict):
            continue
        pair = t.get("pair")
        if pair is None or str(pair).strip() == "":
            continue
        dt = t.get("close_date") or t.get("close_date_utc") or t.get("close_date_local") or t.get("close_timestamp")
        day = None
        try:
            if isinstance(dt, (int, float)):
                day = datetime.utcfromtimestamp(float(dt) / 1000.0).strftime("%Y-%m-%d")
            else:
                s = str(dt)
                day = s[:10] if len(s) >= 10 else None
        except Exception:
            day = None
        if not day:
            continue
        pnl = None
        for k in ("profit_abs", "profit_amount", "profit_u", "profit"):
            if k in t and t.get(k) is not None:
                try:
                    pnl = float(t.get(k))
                    break
                except Exception:
                    pnl = None
        if pnl is None:
            continue
        d = out.get(pair)
        if not isinstance(d, dict):
            d = {}
            out[pair] = d
        d[day] = float(d.get(day, 0.0) or 0.0) + float(pnl)
    return out


def _bt_pearson(xs, ys):
    if not xs or not ys or len(xs) != len(ys):
        return None
    n = len(xs)
    if n < 2:
        return None
    try:
        mx = sum(xs) / float(n)
        my = sum(ys) / float(n)
        vx = 0.0
        vy = 0.0
        c = 0.0
        for i in range(n):
            dx = float(xs[i]) - float(mx)
            dy = float(ys[i]) - float(my)
            vx += dx * dx
            vy += dy * dy
            c += dx * dy
        if vx <= 0.0 or vy <= 0.0:
            return None
        return float(c) / math.sqrt(float(vx) * float(vy))
    except Exception:
        return None


def _bt_corr_to_btc(daily_by_pair):
    if not isinstance(daily_by_pair, dict):
        return {"ok": False, "error": "bad_daily"}
    btc = None
    for k in daily_by_pair.keys():
        if isinstance(k, str) and k.startswith("BTC/"):
            btc = k
            break
    if not btc:
        return {"ok": False, "error": "btc_pair_not_found"}
    btc_map = daily_by_pair.get(btc) if isinstance(daily_by_pair.get(btc), dict) else {}
    if not btc_map:
        return {"ok": False, "error": "btc_daily_empty"}
    per_pair = {}
    vals = []
    for pair, m in daily_by_pair.items():
        if pair == btc:
            continue
        if not isinstance(m, dict) or not m:
            continue
        days = sorted(set(btc_map.keys()) & set(m.keys()))
        if len(days) < 10:
            continue
        xs = [float(btc_map.get(d, 0.0) or 0.0) for d in days]
        ys = [float(m.get(d, 0.0) or 0.0) for d in days]
        r = _bt_pearson(xs, ys)
        if r is None or (not math.isfinite(float(r))):
            continue
        per_pair[pair] = float(r)
        vals.append(float(r))
    return {"ok": True, "btc_pair": btc, "mean": (None if not vals else float(sum(vals)) / float(len(vals))), "per_pair": per_pair, "n": int(len(vals))}


def _bt_cross_coin_metrics(per_pair_metrics, daily_by_pair=None):
    ppm = [] if not isinstance(per_pair_metrics, list) else per_pair_metrics
    profits_pct = []
    profits_abs = []
    dds = []
    for r in ppm:
        if not isinstance(r, dict):
            continue
        if r.get("key") is None:
            continue
        try:
            profits_pct.append(float(r.get("profit_total_pct")))
        except Exception:
            pass
        try:
            profits_abs.append(float(r.get("profit_total_abs")))
        except Exception:
            profits_abs.append(0.0)
        try:
            dds.append(float(r.get("max_drawdown_account")))
        except Exception:
            pass
    n = int(len(ppm))
    pos = 0
    for x in profits_pct:
        if x > 0.0:
            pos += 1
    pos_ratio = (None if n <= 0 else float(pos) / float(n))
    worst_dd = (None if not dds else float(max(dds)))
    disp = None
    if profits_pct:
        mu = float(sum(profits_pct)) / float(len(profits_pct))
        var = float(sum((x - mu) * (x - mu) for x in profits_pct)) / float(max(1, len(profits_pct) - 1))
        disp = math.sqrt(var) if var > 0.0 else 0.0
    conc = None
    try:
        sabs = float(sum(abs(x) for x in profits_abs))
        if sabs > 0.0:
            conc = float(max(abs(x) for x in profits_abs)) / float(sabs)
    except Exception:
        conc = None
    corr = None
    if isinstance(daily_by_pair, dict):
        corr = _bt_corr_to_btc(daily_by_pair)
    return {
        "ok": True,
        "pos_coin_ratio": pos_ratio,
        "worst_coin_drawdown": worst_dd,
        "dispersion": disp,
        "concentration_top1": conc,
        "corr_to_btc": corr,
        "coins": n,
    }


def _bt_trade_thresholds(timeframe, days_effective, n_coins_scored, family=None):
    tfm = _bt_tf_minutes(timeframe)
    days_v = float(days_effective or 0.0)
    n = int(n_coins_scored or 0)
    fam = "" if family is None else str(family).strip().lower()
    per_coin = None
    if days_v > 0.0:
        if fam in ("trend", "trend_following", "trendfollowing"):
            per_coin = max(5, int(days_v / 40.0))
        elif fam in ("mean", "mean_reversion", "mr"):
            per_coin = max(10, int(days_v / 20.0))
        else:
            per_coin = max(8, int(days_v / 30.0))
    if per_coin is None:
        per_coin = 8
    scaled = int(per_coin) * int(max(1, n))
    global_min = 80
    if tfm is not None and tfm <= 15:
        global_min = 120
    return {
        "ok": True,
        "family": fam if fam else None,
        "timeframe": (None if timeframe is None else str(timeframe)),
        "days_effective": float(days_v),
        "n_coins_scored": int(n),
        "per_coin_min_trades": int(per_coin),
        "min_trades_scaled": int(scaled),
        "min_trades_global": int(global_min),
        "min_trades_required": int(max(int(global_min), int(scaled))),
    }


@app.route("/automation/backtest/ingest", methods=["POST"])
def automation_backtest_ingest():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    config_path = str(data.get("config", "user_data/config_backtest.json"))
    if (".." in config_path) or config_path.startswith("/") or config_path.startswith("\\") or (not config_path.startswith("user_data/")) or (not config_path.lower().endswith(".json")):
        return jsonify({"ok": False, "error": "bad_config"}), 400
    strategy = data.get("strategy")
    sandbox_path = data.get("sandbox_path")
    strategy_name = data.get("strategy_name")
    family = data.get("family")
    stage = data.get("stage")
    sync_registry = True
    try:
        if data.get("sync_registry") is not None:
            sync_registry = bool(data.get("sync_registry"))
    except Exception:
        sync_registry = True
    timerange_main = data.get("timerange_main") or data.get("timerange")
    timerange_recent = data.get("timerange_recent")
    try:
        n_slices = int(data.get("n_slices") or 6)
    except Exception:
        n_slices = 6
    n_slices = max(1, min(24, int(n_slices)))
    check_funding_coverage = bool(data.get("check_funding_coverage", True))
    timeout_sec = float(data.get("timeout_sec", 3600) or 3600)

    cfg_file = Path(config_path)
    if (not cfg_file.exists()) or (not cfg_file.is_file()):
        return jsonify({"ok": False, "error": "config_not_found"}), 404
    try:
        cfg = json.loads(cfg_file.read_text(encoding="utf-8"))
    except Exception:
        return jsonify({"ok": False, "error": "config_json_invalid"}), 400

    cov = _bt_coverage_report(cfg, check_funding_coverage=check_funding_coverage)
    scored_pairs = cov.get("scored_pairs") if isinstance(cov, dict) else None
    if not isinstance(scored_pairs, list) or not scored_pairs:
        return jsonify({"ok": False, "error": "no_scored_pairs", "coverage_report": cov}), 400

    cfg2 = dict(cfg) if isinstance(cfg, dict) else {}
    ex2 = dict(cfg2.get("exchange") or {}) if isinstance(cfg2.get("exchange"), dict) else {}
    ex2["pair_whitelist"] = scored_pairs
    cfg2["exchange"] = ex2
    if not cfg2.get("datadir"):
        cfg2["datadir"] = "user_data/data"
    if not cfg2.get("dataformat_ohlcv"):
        cfg2["dataformat_ohlcv"] = "json"
    if not cfg2.get("dataformat_trades"):
        cfg2["dataformat_trades"] = "jsongz"
    deny_network = False
    try:
        if data.get("deny_network") is not None:
            deny_network = bool(data.get("deny_network"))
    except Exception:
        deny_network = False
    allow_hosts = []
    try:
        ah = data.get("allow_hosts")
        if isinstance(ah, list):
            for it in ah[:50]:
                s = str(it or "").strip().lower()
                if not s:
                    continue
                if len(s) > 253:
                    continue
                bad = False
                for ch in s:
                    if not (ch.isalnum() or ch in ".-:"):
                        bad = True
                        break
                if bad:
                    continue
                if s.startswith(".") or s.endswith("."):
                    continue
                allow_hosts.append(s)
    except Exception:
        allow_hosts = []
    if (not allow_hosts) and bool(deny_network):
        try:
            ex_name = str(ex2.get("name") or "").strip().lower()
        except Exception:
            ex_name = ""
        if ex_name in {"gate", "gateio", "gateiofutures"} or ex_name.startswith("gate"):
            allow_hosts = ["api.gateio.ws", "fx-api.gateio.ws", "ws.gateio.ws"]
    pol2 = dict(cfg2.get("sandbox_policy") or {}) if isinstance(cfg2.get("sandbox_policy"), dict) else {}
    pol2["deny_network"] = bool(deny_network)
    auto_download_data = True
    try:
        if data.get("auto_download_data") is not None:
            auto_download_data = bool(data.get("auto_download_data"))
    except Exception:
        auto_download_data = True
    pol2["auto_download_data"] = bool(auto_download_data)
    if allow_hosts and bool(deny_network):
        seen = set()
        uniq = []
        for h in allow_hosts:
            if h in seen:
                continue
            seen.add(h)
            uniq.append(h)
        pol2["allow_hosts"] = uniq
    cfg2["sandbox_policy"] = pol2
    tmp_dir = _user_data_dir() / "tmp" / "ingest_configs"
    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    tmp_cfg = tmp_dir / f"ingest_{trace_id}.json"
    try:
        tmp_cfg.write_text(json.dumps(cfg2, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        return jsonify({"ok": False, "error": "tmp_config_write_failed"}), 500
    tmp_cfg_rel = f"user_data/tmp/ingest_configs/{tmp_cfg.name}"

    inject_res = None
    strategy_path = None
    if sandbox_path:
        st_name = str(strategy_name or strategy or "").strip()
        if not st_name:
            return jsonify({"ok": False, "error": "missing_strategy_name"}), 400
        root = Path(str(sandbox_path)).expanduser()
        try:
            root = root.resolve()
        except Exception:
            return jsonify({"ok": False, "error": "bad_sandbox_path"}), 400
        try:
            bases = [
                _strategy_sandbox_dir().resolve(),
                (_user_data_dir() / "strategies" / "github").resolve(),
            ]
            if not any(str(root).startswith(str(b)) for b in bases):
                return jsonify({"ok": False, "error": "sandbox_outside_base"}), 400
        except Exception:
            return jsonify({"ok": False, "error": "sandbox_outside_base"}), 400
        files = _strategy_pick_files(root, strategy_name=st_name)
        if not files:
            return jsonify({"ok": False, "error": "strategy_file_not_found"}), 404
        hits = _strategy_scan_forbidden(files)
        if hits:
            return jsonify({"ok": False, "error": "strategy_forbidden_tokens", "hits": hits}), 400
        strategy = st_name
        strategy_path = str(root)

    res_main = _run_backtest(tmp_cfg_rel, timerange_main, strategy=strategy, strategy_path=strategy_path, env_overrides=None, timeout_sec=timeout_sec)
    if not (isinstance(res_main, dict) and bool(res_main.get("ok"))):
        return jsonify({"ok": False, "error": "backtest_main_failed", "coverage_report": cov, "main": res_main}), 400
    zip_main = res_main.get("result_zip")
    if zip_main is None:
        return jsonify({"ok": False, "error": "backtest_main_no_zip", "main": res_main}), 400
    zip_main_name = str(zip_main).strip()
    zip_main_path = _backtests_dir() / zip_main_name
    rep_main = _backtest_report_from_zip(zip_main_path, strategy=(None if strategy is None else str(strategy)))
    per_pair_main = _bt_per_pair_metrics_from_zip(zip_main_path, strategy=(None if strategy is None else str(strategy)))
    daily_main = _bt_daily_pnl_by_pair_from_zip(zip_main_path, strategy=(None if strategy is None else str(strategy)))
    cross_main = _bt_cross_coin_metrics(per_pair_main, daily_by_pair=daily_main)
    rolling_main = _bt_robustness_from_zip(zip_main_path, strategy=(None if strategy is None else str(strategy)), n_slices=n_slices, n_bootstrap=0, n_shuffle=0)

    recent = None
    if timerange_recent is not None and str(timerange_recent).strip() != "":
        res_recent = _run_backtest(tmp_cfg_rel, timerange_recent, strategy=strategy, strategy_path=strategy_path, env_overrides=None, timeout_sec=timeout_sec)
        if isinstance(res_recent, dict) and bool(res_recent.get("ok")) and res_recent.get("result_zip") is not None:
            zip_recent_name = str(res_recent.get("result_zip")).strip()
            zip_recent_path = _backtests_dir() / zip_recent_name
            rep_recent = _backtest_report_from_zip(zip_recent_path, strategy=(None if strategy is None else str(strategy)))
            per_pair_recent = _bt_per_pair_metrics_from_zip(zip_recent_path, strategy=(None if strategy is None else str(strategy)))
            daily_recent = _bt_daily_pnl_by_pair_from_zip(zip_recent_path, strategy=(None if strategy is None else str(strategy)))
            cross_recent = _bt_cross_coin_metrics(per_pair_recent, daily_by_pair=daily_recent)
            rolling_recent = _bt_robustness_from_zip(zip_recent_path, strategy=(None if strategy is None else str(strategy)), n_slices=n_slices, n_bootstrap=0, n_shuffle=0)
            recent = {
                "ok": True,
                "timerange": timerange_recent,
                "result_zip": zip_recent_name,
                "report": rep_recent,
                "per_pair_metrics": per_pair_recent,
                "aligned_metrics": cross_recent,
                "oos_summary": rolling_recent,
            }
        else:
            recent = {"ok": False, "timerange": timerange_recent, "error": "backtest_recent_failed", "raw": res_recent}

    days_effective = None
    try:
        days_effective = float(((rep_main.get("metrics_summary") or {}) if isinstance(rep_main, dict) else {}).get("backtest_days"))
    except Exception:
        days_effective = None
    timeframe = None
    try:
        timeframe = str(((cov or {}).get("timeframe") if isinstance(cov, dict) else None) or cfg.get("timeframe") or "")
    except Exception:
        timeframe = None
    family_eff = None
    try:
        family_eff = str(family or "").strip() or None
    except Exception:
        family_eff = None
    if family_eff is None:
        try:
            family_eff = _infer_strategy_family_from_id("" if strategy is None else str(strategy))
        except Exception:
            family_eff = None
    thr = _bt_trade_thresholds(timeframe, days_effective, len(scored_pairs), family=family_eff)
    trades_n = None
    try:
        trades_n = int(((rep_main.get("aligned_metrics") or {}) if isinstance(rep_main, dict) else {}).get("trades"))
    except Exception:
        trades_n = None
    trade_gate_ok = None
    try:
        req = int(thr.get("min_trades_required"))
        trade_gate_ok = (None if trades_n is None else bool(int(trades_n) >= int(req)))
    except Exception:
        trade_gate_ok = None

    hard_fails = []
    warnings = []
    try:
        if isinstance(cov, dict) and float(cov.get("coverage_ratio") or 0.0) < 0.6:
            hard_fails.append("coverage_ratio_low")
        if check_funding_coverage and isinstance(cov, dict) and (not bool(cov.get("funding_coverage", True))):
            warnings.append("funding_coverage_incomplete")
        if trade_gate_ok is False:
            hard_fails.append("min_trades_not_met")
    except Exception:
        pass
    base_eval = None
    try:
        base_eval = (rep_main.get("eval") if isinstance(rep_main, dict) else None)
    except Exception:
        base_eval = None
    decision = "pass"
    if hard_fails:
        decision = "fail"
    gate = {
        "ok": True,
        "decision": decision,
        "hard_fails": hard_fails,
        "warnings": warnings,
        "eval_policy_ref": "core_universe_1y_main_3m_recent_v1",
        "base_eval": base_eval,
        "trade_thresholds": thr,
        "trades": trades_n,
        "trade_gate_ok": trade_gate_ok,
    }

    out = {
        "ok": True,
        "ts": _now_ms(),
        "trace_id": trace_id,
        "kind": "strategy_backtest_ingest",
        "strategy": (None if strategy is None else str(strategy)),
        "config": config_path,
        "timerange_main": timerange_main,
        "timerange_recent": timerange_recent,
        "coverage_report": cov,
        "main": {
            "ok": True,
            "timerange": timerange_main,
            "result_zip": zip_main_name,
            "report": rep_main,
            "per_pair_metrics": per_pair_main,
            "aligned_metrics": cross_main,
            "oos_summary": rolling_main,
        },
        "recent": recent,
        "gate_result": gate,
    }

    registry_sync = None
    try:
        sid = "" if strategy is None else str(strategy).strip()
        if bool(sync_registry) and sid:
            fam0 = None
            try:
                fam0 = str(family or "").strip() or None
            except Exception:
                fam0 = None
            if fam0 is None:
                try:
                    fam0 = _infer_strategy_family_from_id(sid) or "trend"
                except Exception:
                    fam0 = "trend"
            st0 = "research"
            try:
                st0 = str(stage or "").strip() or "research"
            except Exception:
                st0 = "research"
            src_obj = {"type": "sandbox_ingest", "config": str(config_path), "timerange_main": (None if timerange_main is None else str(timerange_main))}
            if sandbox_path:
                src_obj["sandbox_path"] = str(root)
            sync_payload = {
                "strategy_id": sid,
                "family": fam0,
                "stage": st0,
                "tags": ["sandbox_ingest"],
                "source": src_obj,
            }
            sync_payload["econ_driver"] = fam0
            sync_out, sync_code = _strategy_registry_sync_from_zip_impl(data=sync_payload, zip_path=Path(zip_main_path))
            registry_sync = {"ok": bool(isinstance(sync_out, dict) and sync_out.get("ok")), "http": int(sync_code), "sync": sync_out}
            if isinstance(sync_out, dict) and bool(sync_out.get("ok")) and isinstance(sync_out.get("entry"), dict):
                try:
                    reg = _strategy_registry_load()
                    entries = reg.get("entries") if isinstance(reg.get("entries"), dict) else {}
                    key = _strategy_registry_key(sid, str(zip_main_name))
                    ex = entries.get(key) if isinstance(entries.get(key), dict) else {}
                    if ex:
                        upd = dict(ex)
                        upd["ingest_meta"] = {
                            "ts": int(_now_ms()),
                            "trace_id": str(trace_id),
                            "coverage_report": cov,
                            "gate_result": gate,
                            "timerange_main": timerange_main,
                            "timerange_recent": timerange_recent,
                            "recent": (recent if isinstance(recent, dict) else None),
                        }
                        entries[key] = upd
                        reg["entries"] = entries
                        _strategy_registry_save(reg)
                except Exception:
                    pass
    except Exception as e:
        registry_sync = {"ok": False, "error": "registry_sync_exception", "details": str(e)}
    if registry_sync is not None:
        out["registry_sync"] = registry_sync
    if inject_res:
        out["inject"] = inject_res
    try:
        _audit_emit_action(
            "automation.backtest.ingest",
            _audit_base_payload(
                scope="sandbox",
                action="automation.backtest.ingest",
                trace_id=trace_id,
                extra={
                    "config": config_path,
                    "timerange_main": timerange_main,
                    "timerange_recent": timerange_recent,
                    "strategy": strategy,
                    "sandbox_path": sandbox_path,
                    "ok": bool(out.get("ok", True)),
                },
            ),
        )
    except Exception:
        pass
    return jsonify(out)


@app.route("/automation/github/backtest/ingest_one", methods=["POST"])
def automation_github_backtest_ingest_one():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
