    branch = (None if data.get("branch") is None else str(data.get("branch")).strip() or None)
    commit = (None if data.get("commit") is None else str(data.get("commit")).strip() or None)
    subpath = (None if data.get("path") is None else str(data.get("path")).strip() or None)
    strategy_name = str(data.get("strategy_name") or "").strip()
    if not repo_url:
        return jsonify({"ok": False, "error": "missing_repo_url", "trace_id": trace_id}), 400
    if not strategy_name:
        return jsonify({"ok": False, "error": "missing_strategy_name", "trace_id": trace_id}), 400
    if subpath is None:
        subpath = "user_data/strategies"

    step1 = _skill_github_fetch({
        "trace_id": trace_id,
        "mode": "list_files",
        "repo_url": repo_url,
        "branch": branch,
        "commit": commit,
        "path": subpath,
        "strategy_name": strategy_name,
    })
    if not bool(step1.get("ok")):
        return jsonify({"ok": False, "error": "github_fetch_list_failed", "trace_id": trace_id, "step1": step1}), 400
    commit_eff = str(step1.get("commit") or "").strip() or (commit or "")
    if not commit_eff:
        return jsonify({"ok": False, "error": "commit_not_found", "trace_id": trace_id, "step1": step1}), 400

    step2 = _skill_github_fetch({
        "trace_id": trace_id,
        "mode": "signature_check",
        "repo_url": repo_url,
        "branch": branch,
        "commit": commit_eff,
        "path": subpath,
        "strategy_name": strategy_name,
    })
    if not bool(step2.get("ok")):
        return jsonify({"ok": False, "error": "github_fetch_signature_failed", "trace_id": trace_id, "step2": step2}), 400
    compat_ok = None
    try:
        items = step2.get("items") if isinstance(step2.get("items"), list) else []
        if items:
            sc = items[0].get("schema_compat") if isinstance(items[0], dict) else {}
            st = str((sc or {}).get("status") or "").strip().lower()
            if "ok" in (sc or {}):
                compat_ok = bool((sc or {}).get("ok"))
            elif st:
                compat_ok = (st in {"pass", "ok", "true", "compatible"})
            else:
                compat_ok = None
    except Exception:
        compat_ok = None
    if compat_ok is False:
        return jsonify({"ok": False, "error": "schema_incompatible", "trace_id": trace_id, "step2": step2}), 400

    fetch = _skill_github_fetch({
        "trace_id": trace_id,
        "mode": "download_and_scan",
        "repo_url": repo_url,
        "branch": branch,
        "commit": commit_eff,
        "path": subpath,
        "strategy_name": strategy_name,
    })
    if not bool(fetch.get("ok")):
        return jsonify({"ok": False, "error": "github_fetch_failed", "trace_id": trace_id, "fetch": fetch, "step1": step1, "step2": step2}), 400
    if not bool(fetch.get("scan_ok")):
        return jsonify({"ok": False, "error": "scan_failed", "trace_id": trace_id, "analysis_report": fetch.get("analysis_report") if isinstance(fetch.get("analysis_report"), dict) else {}, "fetch": fetch, "step1": step1, "step2": step2}), 400
    sandbox_path = str(fetch.get("sandbox_path") or "").strip()
    eff = str(fetch.get("strategy_name_effective") or "").strip() or strategy_name
    if not sandbox_path:
        return jsonify({"ok": False, "error": "missing_sandbox_path", "trace_id": trace_id, "fetch": fetch, "step1": step1, "step2": step2}), 500

    config_path = str(data.get("config", "user_data/config_backtest.json"))
    if (".." in config_path) or config_path.startswith("/") or config_path.startswith("\\") or (not config_path.startswith("user_data/")) or (not config_path.lower().endswith(".json")):
        return jsonify({"ok": False, "error": "bad_config", "trace_id": trace_id}), 400
    sync_registry = True
    try:
        if data.get("sync_registry") is not None:
            sync_registry = bool(data.get("sync_registry"))
    except Exception:
        sync_registry = True
    timerange_main = data.get("timerange_main") or data.get("timerange")
    timerange_recent = data.get("timerange_recent")
    try:
        n_slices = int(data.get("n_slices") or 6)
    except Exception:
        n_slices = 6
    n_slices = max(1, min(24, int(n_slices)))
    check_funding_coverage = bool(data.get("check_funding_coverage", True))
    try:
        timeout_sec = float(data.get("timeout_sec", 3600) or 3600)
    except Exception:
        timeout_sec = 3600.0
    family = data.get("family")
    stage = data.get("stage")
    deny_network = False
    try:
        if data.get("deny_network") is not None:
            deny_network = bool(data.get("deny_network"))
    except Exception:
        deny_network = False
    allow_hosts = []
    try:
        ah = data.get("allow_hosts")
        if isinstance(ah, list):
            for it in ah[:50]:
                s = str(it or "").strip().lower()
                if not s:
                    continue
                if len(s) > 253:
                    continue
                bad = False
                for ch in s:
                    if not (ch.isalnum() or ch in ".-:"):
                        bad = True
                        break
                if bad:
                    continue
                if s.startswith(".") or s.endswith("."):
                    continue
                allow_hosts.append(s)
    except Exception:
        allow_hosts = []
    auto_download_data = True
    try:
        if data.get("auto_download_data") is not None:
            auto_download_data = bool(data.get("auto_download_data"))
    except Exception:
        auto_download_data = True

    cfg_file = Path(config_path)
    if (not cfg_file.exists()) or (not cfg_file.is_file()):
        return jsonify({"ok": False, "error": "config_not_found", "trace_id": trace_id}), 404
    try:
        cfg = json.loads(cfg_file.read_text(encoding="utf-8"))
    except Exception:
        return jsonify({"ok": False, "error": "config_json_invalid", "trace_id": trace_id}), 400

    cov = _bt_coverage_report(cfg, check_funding_coverage=check_funding_coverage)
    scored_pairs = cov.get("scored_pairs") if isinstance(cov, dict) else None
    if not isinstance(scored_pairs, list) or not scored_pairs:
        return jsonify({"ok": False, "error": "no_scored_pairs", "coverage_report": cov, "trace_id": trace_id}), 400

    cfg2 = dict(cfg) if isinstance(cfg, dict) else {}
    ex2 = dict(cfg2.get("exchange") or {}) if isinstance(cfg2.get("exchange"), dict) else {}
    ex2["pair_whitelist"] = scored_pairs
    cfg2["exchange"] = ex2
    if (not allow_hosts) and bool(deny_network):
        try:
            ex_name = str(ex2.get("name") or "").strip().lower()
        except Exception:
            ex_name = ""
        if ex_name in {"gate", "gateio", "gateiofutures"} or ex_name.startswith("gate"):
            allow_hosts = ["api.gateio.ws", "fx-api.gateio.ws", "ws.gateio.ws"]
    if not cfg2.get("datadir"):
        cfg2["datadir"] = "user_data/data"
    if not cfg2.get("dataformat_ohlcv"):
        cfg2["dataformat_ohlcv"] = "json"
    if not cfg2.get("dataformat_trades"):
        cfg2["dataformat_trades"] = "jsongz"
    pol2 = dict(cfg2.get("sandbox_policy") or {}) if isinstance(cfg2.get("sandbox_policy"), dict) else {}
    pol2["deny_network"] = bool(deny_network)
    pol2["auto_download_data"] = bool(auto_download_data)
    if allow_hosts and bool(deny_network):
        seen = set()
        uniq = []
        for h in allow_hosts:
            if h in seen:
                continue
            seen.add(h)
            uniq.append(h)
        pol2["allow_hosts"] = uniq
    cfg2["sandbox_policy"] = pol2
    tmp_dir = _user_data_dir() / "tmp" / "ingest_configs"
    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    tmp_cfg = tmp_dir / f"ingest_{trace_id}.json"
    try:
        tmp_cfg.write_text(json.dumps(cfg2, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        return jsonify({"ok": False, "error": "tmp_config_write_failed", "trace_id": trace_id}), 500
    tmp_cfg_rel = f"user_data/tmp/ingest_configs/{tmp_cfg.name}"

    root = Path(str(sandbox_path)).expanduser()
    try:
        root = root.resolve()
    except Exception:
        return jsonify({"ok": False, "error": "bad_sandbox_path", "trace_id": trace_id}), 400
    try:
        bases = [
            _strategy_sandbox_dir().resolve(),
            (_user_data_dir() / "strategies" / "github").resolve(),
        ]
        if not any(str(root).startswith(str(b)) for b in bases):
            return jsonify({"ok": False, "error": "sandbox_outside_base", "trace_id": trace_id}), 400
    except Exception:
        return jsonify({"ok": False, "error": "sandbox_outside_base", "trace_id": trace_id}), 400
    files = _strategy_pick_files(root, strategy_name=eff)
    if not files:
        return jsonify({"ok": False, "error": "strategy_file_not_found", "trace_id": trace_id, "strategy": eff, "sandbox_path": str(root)}), 404
    hits = _strategy_scan_forbidden(files)
    if hits:
        return jsonify({"ok": False, "error": "strategy_forbidden_tokens", "trace_id": trace_id, "hits": hits}), 400

    res_main = _run_backtest(tmp_cfg_rel, timerange_main, strategy=eff, strategy_path=str(root), env_overrides=None, timeout_sec=timeout_sec)
    if not (isinstance(res_main, dict) and bool(res_main.get("ok"))):
        return jsonify({"ok": False, "error": "backtest_main_failed", "trace_id": trace_id, "coverage_report": cov, "main": res_main, "fetch": fetch}), 400
    zip_main = res_main.get("result_zip")
    if zip_main is None:
        return jsonify({"ok": False, "error": "backtest_main_no_zip", "trace_id": trace_id, "main": res_main, "fetch": fetch}), 400
    zip_main_name = str(zip_main).strip()
    zip_main_path = _backtests_dir() / zip_main_name
    rep_main = _backtest_report_from_zip(zip_main_path, strategy=str(eff))
    per_pair_main = _bt_per_pair_metrics_from_zip(zip_main_path, strategy=str(eff))
    daily_main = _bt_daily_pnl_by_pair_from_zip(zip_main_path, strategy=str(eff))
    cross_main = _bt_cross_coin_metrics(per_pair_main, daily_by_pair=daily_main)
    rolling_main = _bt_robustness_from_zip(zip_main_path, strategy=str(eff), n_slices=n_slices, n_bootstrap=0, n_shuffle=0)

    recent = None
    if timerange_recent is not None and str(timerange_recent).strip() != "":
        res_recent = _run_backtest(tmp_cfg_rel, timerange_recent, strategy=eff, strategy_path=str(root), env_overrides=None, timeout_sec=timeout_sec)
        if isinstance(res_recent, dict) and bool(res_recent.get("ok")) and res_recent.get("result_zip") is not None:
            zip_recent_name = str(res_recent.get("result_zip")).strip()
            zip_recent_path = _backtests_dir() / zip_recent_name
            rep_recent = _backtest_report_from_zip(zip_recent_path, strategy=str(eff))
            per_pair_recent = _bt_per_pair_metrics_from_zip(zip_recent_path, strategy=str(eff))
            daily_recent = _bt_daily_pnl_by_pair_from_zip(zip_recent_path, strategy=str(eff))
            cross_recent = _bt_cross_coin_metrics(per_pair_recent, daily_by_pair=daily_recent)
            rolling_recent = _bt_robustness_from_zip(zip_recent_path, strategy=str(eff), n_slices=n_slices, n_bootstrap=0, n_shuffle=0)
            recent = {
                "ok": True,
                "timerange": timerange_recent,
                "result_zip": zip_recent_name,
                "report": rep_recent,
                "per_pair_metrics": per_pair_recent,
                "aligned_metrics": cross_recent,
                "oos_summary": rolling_recent,
            }
        else:
            recent = {"ok": False, "timerange": timerange_recent, "error": "backtest_recent_failed", "raw": res_recent}

    days_effective = None
    try:
        days_effective = float(((rep_main.get("metrics_summary") or {}) if isinstance(rep_main, dict) else {}).get("backtest_days"))
    except Exception:
        days_effective = None
    timeframe = None
    try:
        timeframe = str(((cov or {}).get("timeframe") if isinstance(cov, dict) else None) or cfg.get("timeframe") or "")
    except Exception:
        timeframe = None
    family_eff = None
    try:
        family_eff = str(family or "").strip() or None
    except Exception:
        family_eff = None
    if family_eff is None:
        try:
            family_eff = _infer_strategy_family_from_id(str(eff))
        except Exception:
            family_eff = None
    thr = _bt_trade_thresholds(timeframe, days_effective, len(scored_pairs), family=family_eff)
    trades_n = None
    try:
        trades_n = int(((rep_main.get("aligned_metrics") or {}) if isinstance(rep_main, dict) else {}).get("trades"))
    except Exception:
        trades_n = None
    trade_gate_ok = None
    try:
        req0 = int(thr.get("min_trades_required"))
        trade_gate_ok = (None if trades_n is None else bool(int(trades_n) >= int(req0)))
    except Exception:
        trade_gate_ok = None

    hard_fails = []
    warnings = []
    try:
        if isinstance(cov, dict) and float(cov.get("coverage_ratio") or 0.0) < 0.6:
            hard_fails.append("coverage_ratio_low")
        if check_funding_coverage and isinstance(cov, dict) and (not bool(cov.get("funding_coverage", True))):
            warnings.append("funding_coverage_incomplete")
        if trade_gate_ok is False:
            hard_fails.append("min_trades_not_met")
    except Exception:
        pass
    base_eval = None
    try:
        base_eval = (rep_main.get("eval") if isinstance(rep_main, dict) else None)
    except Exception:
        base_eval = None
    decision = "pass"
    if hard_fails:
        decision = "fail"
    gate = {
        "ok": True,
        "decision": decision,
        "hard_fails": hard_fails,
        "warnings": warnings,
        "eval_policy_ref": "core_universe_1y_main_3m_recent_v1",
        "base_eval": base_eval,
        "trade_thresholds": thr,
        "trades": trades_n,
        "trade_gate_ok": trade_gate_ok,
    }

    out = {
        "ok": True,
        "ts": _now_ms(),
        "trace_id": trace_id,
        "kind": "github_strategy_backtest_ingest",
        "repo": {"repo_url": str(repo_url), "branch": branch, "commit": (commit if commit else fetch.get("commit")), "path": subpath},
        "strategy": str(eff),
        "config": config_path,
        "timerange_main": timerange_main,
        "timerange_recent": timerange_recent,
        "coverage_report": cov,
        "main": {
            "ok": True,
            "timerange": timerange_main,
            "result_zip": zip_main_name,
            "report": rep_main,
            "per_pair_metrics": per_pair_main,
            "aligned_metrics": cross_main,
            "oos_summary": rolling_main,
        },
        "recent": recent,
        "gate_result": gate,
        "fetch": fetch,
        "fetch_steps": {"list_files": step1, "signature_check": step2},
    }

    registry_sync = None
    try:
        if bool(sync_registry) and str(eff).strip():
            fam0 = None
            try:
                fam0 = str(family or "").strip() or None
            except Exception:
                fam0 = None
            if fam0 is not None:
                try:
                    if _strategy_family_normalize(fam0) is None:
                        fam0 = None
                except Exception:
                    fam0 = None
            if fam0 is None:
                try:
                    fam0 = _infer_strategy_family_from_id(str(eff)) or "trend"
                except Exception:
                    fam0 = "trend"
            st0 = "research"
            try:
                st0 = str(stage or "").strip() or "research"
            except Exception:
                st0 = "research"
            try:
                if _strategy_stage_normalize(st0) is None:
                    st0 = "research"
            except Exception:
                st0 = "research"
            src_obj = {"type": "github_ingest", "repo_url": str(repo_url), "branch": branch, "commit": (commit if commit else fetch.get("commit")), "path": subpath, "timerange_main": (None if timerange_main is None else str(timerange_main))}
            sync_payload = {
                "strategy_id": str(eff).strip(),
                "family": fam0,
                "stage": st0,
                "tags": ["github_ingest", "sandbox_ingest"],
                "source": src_obj,
            }
            sync_payload["econ_driver"] = fam0
            sync_out, sync_code = _strategy_registry_sync_from_zip_impl(data=sync_payload, zip_path=Path(zip_main_path))
            registry_sync = {"ok": bool(isinstance(sync_out, dict) and sync_out.get("ok")), "http": int(sync_code), "sync": sync_out}
    except Exception as e:
        registry_sync = {"ok": False, "error": "registry_sync_exception", "details": str(e)}
    if registry_sync is not None:
        out["registry_sync"] = registry_sync

    try:
        _audit_emit_action(
            "automation.github.backtest.ingest_one",
            _audit_base_payload(
                scope="sandbox",
                action="automation.github.backtest.ingest_one",
                trace_id=trace_id,
                extra={
                    "config": config_path,
                    "timerange_main": timerange_main,
                    "timerange_recent": timerange_recent,
                    "strategy": str(eff),
                    "repo_url": str(repo_url),
                    "commit": (commit if commit else fetch.get("commit")),
                    "ok": True,
                },
            ),
        )
    except Exception:
        pass
    return jsonify(out)


