@app.route("/backtest/results/download", methods=["GET"])
def backtest_results_download():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    trace_id = str(request.args.get("trace_id") or "").strip() or uuid.uuid4().hex
    name = request.args.get("zip")
    s = "" if name is None else str(name).strip()
    if (not s) or (not s.lower().endswith(".zip")) or (".." in s) or ("/" in s) or ("\\" in s):
        return jsonify({"ok": False, "error": "bad_zip"}), 400
    p = _backtests_dir() / s
    if (not p.exists()) or (not p.is_file()):
        return jsonify({"ok": False, "error": "zip_not_found", "zip": s}), 404
    try:
        _audit_emit_action(
            "backtest.results.download",
            _audit_base_payload(
                scope="sandbox",
                action="backtest.results.download",
                trace_id=trace_id,
                extra={"zip": str(p.name)},
            ),
        )
    except Exception:
        pass
    return send_file(p, mimetype="application/zip", as_attachment=True, download_name=str(p.name))


