@app.route("/backtest/robustness", methods=["POST"])
def backtest_robustness():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    name = data.get("zip")
    s = "" if name is None else str(name).strip()
    if s:
        if (not s.lower().endswith(".zip")) or (".." in s) or ("/" in s) or ("\\" in s):
            return jsonify({"ok": False, "error": "bad_zip"}), 400
        p = _backtests_dir() / s
    else:
        p = _backtest_pick_latest_zip_path()

    if p is None or (not Path(p).exists()) or (not Path(p).is_file()):
        return jsonify({"ok": False, "error": "backtest_zip_not_found", "zip": s}), 404

    strategy = data.get("strategy")
    st = None if strategy is None else str(strategy)
    assumptions = data.get("assumptions")
    sensitivity = data.get("sensitivity")
    seed = data.get("seed")
    try:
        n_slices = int(data.get("n_slices") or 6)
    except Exception:
        n_slices = 6
    try:
        n_bootstrap = int(data.get("n_bootstrap") or 200)
    except Exception:
        n_bootstrap = 200
    try:
        n_shuffle = int(data.get("n_shuffle") or 200)
    except Exception:
        n_shuffle = 200
    try:
        vol_ratio_thr = float(data.get("vol_ratio_thr") or 1.5)
    except Exception:
        vol_ratio_thr = 1.5
    try:
        trend_dist_thr = float(data.get("trend_dist_thr") or 0.01)
    except Exception:
        trend_dist_thr = 0.01

    rep = _bt_robustness_from_zip(
        Path(p),
        strategy=st,
        assumptions=(assumptions if isinstance(assumptions, dict) else None),
        sensitivity=(sensitivity if isinstance(sensitivity, dict) else None),
        seed=(None if seed is None else int(seed)),
        n_slices=n_slices,
        n_bootstrap=n_bootstrap,
        n_shuffle=n_shuffle,
        vol_ratio_thr=vol_ratio_thr,
        trend_dist_thr=trend_dist_thr,
    )
    try:
        _audit_emit_action(
            "backtest.robustness",
            _audit_base_payload(
                scope="sandbox",
                action="backtest.robustness",
                trace_id=trace_id,
                extra={
                    "zip": (None if (not s) else s),
                    "strategy": st,
                    "n_slices": int(n_slices),
                    "n_bootstrap": int(n_bootstrap),
                    "n_shuffle": int(n_shuffle),
                    "vol_ratio_thr": float(vol_ratio_thr),
                    "trend_dist_thr": float(trend_dist_thr),
                    "ok": (None if not isinstance(rep, dict) else bool(rep.get("ok", True))),
                },
            ),
        )
    except Exception:
        pass
    code = 200 if bool(rep.get("ok")) else 400
    return jsonify(rep), code


