@app.route("/audit/data-quality", methods=["GET"])
def audit_data_quality():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    pair = request.args.get("pair")
    pair_s = "" if pair is None else str(pair).strip()
    if not pair_s:
        return jsonify({"ok": False, "error": "missing_pair"}), 400

    start_ts = request.args.get("start_ts")
    end_ts = request.args.get("end_ts")

    try:
        lookback_days = float(request.args.get("lookback_days") or 30)
    except Exception:
        lookback_days = 30.0
    lookback_days = max(0.1, min(3650.0, float(lookback_days)))

    try:
        max_points = int(request.args.get("max_points") or 5000)
    except Exception:
        max_points = 5000
    max_points = max(200, min(200000, int(max_points)))

    try:
        ret_abs_thr = float(request.args.get("ret_abs_thr") or 0.10)
    except Exception:
        ret_abs_thr = 0.10

    start_ms = None
    end_ms = None
    if start_ts is not None and str(start_ts).strip() != "":
        try:
            start_ms = int(float(start_ts))
        except Exception:
            start_ms = None
    if end_ts is not None and str(end_ts).strip() != "":
        try:
            end_ms = int(float(end_ts))
        except Exception:
            end_ms = None

    if end_ms is None or start_ms is None:
        p = _find_pair_file(pair_s)
        raw = _read_5m_rows(p) if p is not None else []
        last_ts = None
        try:
            if raw:
                last_ts = int(raw[-1][0])
        except Exception:
            last_ts = None
        if end_ms is None:
            end_ms = int(last_ts if last_ts is not None else _now_ms())
        if start_ms is None:
            start_ms = int(end_ms) - int(float(lookback_days) * 86400 * 1000)

    rep = _audit_data_quality(pair=pair_s, start_ts_ms=int(start_ms), end_ts_ms=int(end_ms), max_points=int(max_points), ret_abs_thr=float(ret_abs_thr))
    if bool(rep.get("ok")):
        try:
            limit = int(request.args.get("events_limit") or 2000)
        except Exception:
            limit = 2000
        include_events_q = request.args.get("include_events")
        include_events = True
        if include_events_q is not None:
            include_events = str(include_events_q).strip().lower() in ("1", "true", "yes", "on")
        if include_events:
            try:
                rep["bar_closed"] = _audit_bar_closed_stats(limit=limit, pair=pair_s)
            except Exception:
                rep["bar_closed"] = {"n": 0, "closed_true": 0, "closed_false": 0, "missing": 0, "rate_true": 0.0, "by_strategy": {}}

    rep["ts"] = int(_now_ms())
    code = 200 if bool(rep.get("ok")) else 400
    return jsonify(rep), code


