@app.route("/audit/alerts/evaluate", methods=["GET"])
def audit_alerts_evaluate():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    pair = request.args.get("pair")
    pair_s = None if pair is None else str(pair).strip()
    if pair_s is not None and not pair_s:
        pair_s = None

    try:
        lookback_days = float(request.args.get("lookback_days") or 7)
    except Exception:
        lookback_days = 7.0
    lookback_days = max(0.1, min(3650.0, float(lookback_days)))

    rep = _audit_alerts_evaluate_internal(pair=pair_s, lookback_days=float(lookback_days), now_ms=int(_now_ms()))
    return jsonify(rep), 200


def _audit_alerts_evaluate_internal(*, pair: Optional[str], lookback_days: float, now_ms: int) -> Dict[str, Any]:
    pair_s = None if pair is None else str(pair).strip()
    if pair_s is not None and not pair_s:
        pair_s = None
    try:
        lookback_days_f = float(lookback_days)
    except Exception:
        lookback_days_f = 7.0
    lookback_days_f = max(0.1, min(3650.0, float(lookback_days_f)))
    now_ms_i = int(now_ms)
    start_ms = int(now_ms_i) - int(float(lookback_days_f) * 86400.0 * 1000.0)

    dq_end_ms = int(now_ms_i)
    dq_start_ms = int(start_ms)
    if pair_s is not None:
        p = _find_pair_file(pair_s)
        raw = _read_5m_rows(p) if p is not None else []
        last_ts = None
        try:
            if raw:
                last_ts = int(raw[-1][0])
        except Exception:
            last_ts = None
        if last_ts is not None and int(last_ts) > 0:
            dq_end_ms = min(int(dq_end_ms), int(last_ts))
            dq_start_ms = int(dq_end_ms) - int(float(lookback_days_f) * 86400.0 * 1000.0)

    dq = None
    if pair_s is not None:
        try:
            dq = _audit_data_quality(pair=pair_s, start_ts_ms=int(dq_start_ms), end_ts_ms=int(dq_end_ms), max_points=5000, ret_abs_thr=0.10)
            if isinstance(dq, dict) and bool(dq.get("ok")):
                dq["bar_closed"] = _audit_bar_closed_stats(limit=2000, pair=pair_s)
        except Exception as e:
            dq = {"ok": False, "error": str(e)}

    eq = None
    try:
        eq = _audit_execution_quality(start_ts_ms=int(start_ms), end_ts_ms=int(now_ms_i), pair=pair_s, max_points=5000, include_shadow=False)
    except Exception as e:
        eq = {"ok": False, "error": str(e)}

    rep = _monitor_alerts_eval(dq=dq, eq=eq)
    if not isinstance(rep, dict):
        rep = {"ok": False, "error": "bad_alerts_eval"}
    rep["pair"] = pair_s
    rep["lookback_days"] = float(lookback_days_f)
    rep["ts"] = int(_now_ms())
    rep["dq"] = dq
    rep["eq"] = eq
    return rep


