def _agent_jsonl_tail(path: Path, tail_bytes: int = 2_000_000, max_lines: int = 20_000) -> List[Dict[str, Any]]:
    p = Path(path)
    if not p.exists() or not p.is_file():
        return []
    try:
        tail_bytes = int(tail_bytes)
    except Exception:
        tail_bytes = 2_000_000
    try:
        max_lines = int(max_lines)
    except Exception:
        max_lines = 20_000
    tail_bytes = max(1024, min(32_000_000, int(tail_bytes)))
    max_lines = max(1, min(20_000, int(max_lines)))

    lines = _tail_lines(p, max_lines=max_lines, max_bytes=tail_bytes)
    out: List[Dict[str, Any]] = []
    for s in lines:
        try:
            obj = json.loads(s)
        except Exception:
            continue
        if isinstance(obj, dict):
            out.append(obj)
    return out


def _agent_twitter_metrics(window_sec: int = 3600, tail_bytes: int = 2_000_000) -> Dict[str, Any]:
    now_ms = int(_now_ms())
    try:
        w = max(60, int(window_sec or 3600))
    except Exception:
        w = 3600
    since_ms = now_ms - int(w) * 1000

    outbox_dir = _agent_outbox_dir()
    twitter_path = outbox_dir / "twitter.jsonl"
    receipts_path = outbox_dir / "delivery_receipts.jsonl"

    twitter_rows = _agent_jsonl_tail(twitter_path, tail_bytes=tail_bytes, max_lines=20_000)
    receipt_rows_all = _agent_jsonl_tail(receipts_path, tail_bytes=tail_bytes, max_lines=40_000)
    receipt_rows = [r for r in receipt_rows_all if str(r.get("channel") or "").strip().lower() == "twitter"]

    req_by_key: Dict[str, int] = {}
    for r in twitter_rows:
        ts = int(r.get("ts") or 0)
        if ts <= 0 or ts < since_ms:
            continue
        k = str(r.get("idempotency_key") or r.get("id") or "").strip()
        if not k:
            continue
        prev = req_by_key.get(k)
        if prev is None or ts > prev:
            req_by_key[k] = ts

    receipt_by_key: Dict[str, Dict[str, Any]] = {}
    last_receipt: Optional[Dict[str, Any]] = None
    last_receipt_ts = -1
    for r in receipt_rows:
        ts = int(r.get("ts") or 0)
        if ts > last_receipt_ts:
            last_receipt_ts = ts
            last_receipt = r
        if ts <= 0 or ts < since_ms:
            continue
        k = str(r.get("idempotency_key") or r.get("id") or "").strip()
        if not k:
            continue
        prev = receipt_by_key.get(k)
        prev_ts = int(prev.get("ts") or 0) if isinstance(prev, dict) else 0
        if prev is None or ts >= prev_ts:
            receipt_by_key[k] = r

    ok_cnt = 0
    fail_cnt = 0
    for rr in receipt_by_key.values():
        if bool(rr.get("ok")):
            ok_cnt += 1
        else:
            fail_cnt += 1

    pending_keys = [k for k in req_by_key.keys() if k not in receipt_by_key]
    oldest_pending_ts = None
    for k in pending_keys:
        ts = int(req_by_key.get(k) or 0)
        if ts <= 0:
            continue
        if oldest_pending_ts is None or ts < oldest_pending_ts:
            oldest_pending_ts = ts

    oldest_pending_age_sec = None
    if oldest_pending_ts is not None:
        oldest_pending_age_sec = max(0.0, (now_ms - int(oldest_pending_ts)) / 1000.0)

    files = {}
    for name, p in (("twitter", twitter_path), ("receipts", receipts_path)):
        try:
            st = p.stat()
            files[name] = {"name": str(p.name), "size": int(st.st_size), "mtime_ms": int(st.st_mtime * 1000)}
        except Exception:
            files[name] = {"name": str(p.name)}

    lr = None
    if isinstance(last_receipt, dict):
        lr = {
            "ok": bool(last_receipt.get("ok")),
            "ts": int(last_receipt.get("ts") or 0),
            "status_code": last_receipt.get("status_code"),
            "error": last_receipt.get("error"),
            "provider_msg_id": last_receipt.get("provider_msg_id"),
            "id": last_receipt.get("id"),
            "idempotency_key": last_receipt.get("idempotency_key"),
        }

    tw_th = globals().get("_TWITTER_OUTBOX_THREAD")
    try:
        tw_started = bool(globals().get("_TWITTER_OUTBOX_STARTED", False))
    except Exception:
        tw_started = False
    try:
        tw_alive = bool(tw_th is not None and hasattr(tw_th, "is_alive") and tw_th.is_alive())
    except Exception:
        tw_alive = False
    tw_hb = None
    try:
        tw_hb = int(globals().get("_TWITTER_OUTBOX_HEARTBEAT_MS") or 0) or None
    except Exception:
        tw_hb = None
    tw_hb_age_sec = None
    try:
        if tw_hb is not None:
            tw_hb_age_sec = max(0.0, (float(now_ms) - float(tw_hb)) / 1000.0)
    except Exception:
        tw_hb_age_sec = None

    return {
        "ok": True,
        "window_sec": int(w),
        "since_ms": int(since_ms),
        "ts": int(now_ms),
        "requests": int(len(req_by_key)),
        "receipts_ok": int(ok_cnt),
        "receipts_fail": int(fail_cnt),
        "pending": int(len(pending_keys)),
        "oldest_pending_age_sec": oldest_pending_age_sec,
        "last_receipt": lr,
        "files": files,
        "worker_started": bool(tw_started),
        "worker_alive": bool(tw_alive),
        "worker_heartbeat_ms": tw_hb,
        "worker_heartbeat_age_sec": tw_hb_age_sec,
    }


