_TM_TODAY_SUMMARY_CACHE: Dict[str, Any] = {"ts_ms": 0, "day": "", "data": None}


def _trade_monitor_today_summary(now_ms: int) -> Dict[str, Any]:
    day = datetime.fromtimestamp(int(now_ms) / 1000.0, tz=timezone.utc).strftime("%Y-%m-%d")
    try:
        cached = _TM_TODAY_SUMMARY_CACHE
        if str(cached.get("day") or "") == str(day) and int(now_ms) - int(cached.get("ts_ms") or 0) < 20_000 and isinstance(cached.get("data"), dict):
            return dict(cached.get("data") or {})
    except Exception:
        pass

    start_ms = 0
    try:
        dt0 = datetime.fromtimestamp(int(now_ms) / 1000.0, tz=timezone.utc)
        dt0 = dt0.replace(hour=0, minute=0, second=0, microsecond=0)
        start_ms = int(dt0.timestamp() * 1000.0)
    except Exception:
        start_ms = int(max(0, int(now_ms) - int(86400 * 1000)))

    close_orders, used_files = [], []
    try:
        close_orders, used_files = _trade_monitor_close_orders_window(int(start_ms), int(now_ms), include_memory=True, max_days=3)
    except Exception:
        close_orders, used_files = [], []

    rep = None
    try:
        report_trace_id = "tm_day_" + uuid.uuid4().hex
        rep = _trade_monitor_build_report(
            int(now_ms),
            trace_id=str(report_trace_id),
            kind="day",
            window_start_ms=int(start_ms),
            window_end_ms=int(now_ms),
            close_orders=(close_orders if isinstance(close_orders, list) else []),
            reject_stats={},
            context={"monitor_cost": {"api_calls_total": 0, "latency_p95_ms": {}, "token_cost_estimate": 0}},
        )
        if isinstance(rep, dict):
            ev = []
            for p in (used_files or [])[:24]:
                ev.append({"method": "FILE", "endpoint": str(p)})
            if not ev:
                ev = [{"method": "FILE", "endpoint": "user_data/datasets/*_orders.jsonl"}]
            rep["input_evidence"] = ev
            rep["doc_refs"] = [
                {"doc_path": "交易AI Agent 技术文档2.0.md", "section": "5.4.1.3"},
                {"doc_path": "技术文档.md", "section": "11.z.2"},
            ]
            try:
                rep["analysis"] = _trade_monitor_analysis_build(rep)
            except Exception:
                pass
    except Exception:
        rep = None

    out = {
        "ok": True,
        "day": str(day),
        "window": {"start_ms": int(start_ms), "end_ms": int(now_ms)},
        "updated_ms": int(now_ms),
        "summary": (rep.get("summary") if isinstance(rep, dict) else None),
        "analysis": (rep.get("analysis") if isinstance(rep, dict) else None),
        "input_evidence": (rep.get("input_evidence") if isinstance(rep, dict) else None),
    }
    try:
        _TM_TODAY_SUMMARY_CACHE["ts_ms"] = int(now_ms)
        _TM_TODAY_SUMMARY_CACHE["day"] = str(day)
        _TM_TODAY_SUMMARY_CACHE["data"] = dict(out)
    except Exception:
        pass
    return out


