def _agent_outbox_dir() -> Path:
    try:
        env = _governance_env_name()
    except Exception:
        try:
            env = str(CONFIG.get("governance_env") or "prod").strip().lower()
        except Exception:
            env = "prod"
        env = env if env in ("prod", "explore", "pilot") else "prod"
    p0 = ""
    try:
        p0 = str(os.environ.get("AGENT_OUTBOX_DIR", "") or "").strip()
    except Exception:
        p0 = ""
    if env == "explore":
        p1 = ""
        try:
            p1 = str(os.environ.get("AGENT_OUTBOX_DIR_EXPLORE", "") or "").strip()
        except Exception:
            p1 = ""
        if not p1:
            try:
                p1 = str(CONFIG.get("agent_outbox_dir_explore") or "").strip()
            except Exception:
                p1 = ""
        if p1:
            p0 = p1
    if env == "pilot":
        p1 = ""
        try:
            p1 = str(os.environ.get("AGENT_OUTBOX_DIR_PILOT", "") or "").strip()
        except Exception:
            p1 = ""
        if not p1:
            try:
                p1 = str(CONFIG.get("agent_outbox_dir_pilot") or "").strip()
            except Exception:
                p1 = ""
        if p1:
            p0 = p1
    if not p0:
        try:
            p0 = str(CONFIG.get("agent_outbox_dir") or "").strip()
        except Exception:
            p0 = ""
    if p0:
        try:
            p = Path(p0).expanduser().resolve()
        except Exception:
            p = _user_data_dir() / "agent_outbox"
    else:
        if env == "explore":
            p = _user_data_dir() / "agent_outbox_explore"
        elif env == "pilot":
            p = _user_data_dir() / "agent_outbox_pilot"
        else:
            p = _user_data_dir() / "agent_outbox"
    if env == "explore":
        try:
            if str(p.name).lower() not in ("agent_outbox_explore", "explore", "explore_outbox") and ("explore" not in str(p.name).lower()):
                p = p / "explore"
        except Exception:
            pass
    if env == "pilot":
        try:
            if str(p.name).lower() not in ("agent_outbox_pilot", "pilot", "pilot_outbox") and ("pilot" not in str(p.name).lower()):
                p = p / "pilot"
        except Exception:
            pass
    try:
        p.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    return p


def _date_yyyymmdd_from_ms(ts_ms: int) -> str:
    try:
        ts_i = int(ts_ms or 0)
    except Exception:
        ts_i = int(_now_ms())
    return datetime.fromtimestamp(ts_i / 1000.0, tz=timezone.utc).strftime("%Y%m%d")


def _agent_outbox_rollover_one(path: Path, now_ms: int) -> None:
    p = Path(path)
    nm = str(p.name)
    low = nm.lower()
    if not low.endswith(".jsonl"):
        return
    if re.search(r"_\d{8}\.jsonl$", nm):
        return
    try:
        st = p.stat()
    except Exception:
        return
    if int(getattr(st, "st_size", 0) or 0) <= 0:
        return
    try:
        max_bytes = int(CONFIG.get("outbox_rollover_max_bytes", 32_000_000) or 32_000_000)
    except Exception:
        max_bytes = 32_000_000
    max_bytes = max(1_000_000, min(256_000_000, int(max_bytes)))
    try:
        chat_max = int(CONFIG.get("outbox_rollover_chat_max_bytes", 8_000_000) or 8_000_000)
    except Exception:
        chat_max = 8_000_000
    chat_max = max(1_000_000, min(128_000_000, int(chat_max)))
    effective_max = chat_max if low == "chat.jsonl" else max_bytes
    try:
        size0 = int(getattr(st, "st_size", 0) or 0)
    except Exception:
        size0 = 0
    today = _date_yyyymmdd_from_ms(int(now_ms))
    try:
        file_day = datetime.fromtimestamp(float(st.st_mtime), tz=timezone.utc).strftime("%Y%m%d")
    except Exception:
        file_day = today
    if (file_day == today) and (size0 < int(effective_max)):
        return

    stem = nm[:-5]
    tag = file_day
    if file_day == today and size0 >= int(effective_max):
        try:
            tag = f"{today}_{int(float(st.st_mtime) * 1000.0)}"
        except Exception:
            tag = f"{today}_{uuid.uuid4().hex[:8]}"
    target = p.parent / f"{stem}_{tag}.jsonl"
    if target.exists():
        try:
            target = p.parent / f"{stem}_{tag}_{int(float(st.st_mtime) * 1000.0)}.jsonl"
        except Exception:
            target = p.parent / f"{stem}_{tag}_{uuid.uuid4().hex[:8]}.jsonl"
    try:
        os.replace(str(p), str(target))
    except Exception:
        return


def _agent_outbox_rollover_all(now_ms: int) -> None:
    p = _agent_outbox_dir()
    try:
        for q in p.glob("*.jsonl"):
            _agent_outbox_rollover_one(q, now_ms=int(now_ms))
    except Exception:
        return


def _day_yyyy_mm_dd_from_ms(ts_ms: int) -> str:
    try:
        ts_i = int(ts_ms or 0)
    except Exception:
        ts_i = int(_now_ms())
    if ts_i > 0 and ts_i < 1_000_000_000_000:
        ts_i = ts_i * 1000
    return datetime.fromtimestamp(ts_i / 1000.0, tz=timezone.utc).strftime("%Y-%m-%d")


def _agent_outbox_recent_paths(base_name: str, *, days: int, now_ms: int) -> List[Path]:
    nm = str(base_name or "").strip()
    if not nm:
        return []
    d = max(1, min(3650, int(days)))
    out_dir = _agent_outbox_dir()
    paths: List[Path] = []
    seen: set = set()

    def _add(p: Path) -> None:
        try:
            if not p.exists() or (not p.is_file()):
                return
        except Exception:
            return
        key = str(p)
        if key in seen:
            return
        seen.add(key)
        paths.append(p)

    _add(out_dir / f"{nm}.jsonl")
    _add(out_dir / f"{nm}.jsonl.gz")

    base_dt = datetime.fromtimestamp(int(now_ms) / 1000.0, tz=timezone.utc)
    for i in range(0, d):
        dt = base_dt - timedelta(days=int(i))
        ymd = dt.strftime("%Y%m%d")
        for stem in (f"{nm}_{ymd}", f"{nm}._{ymd}"):
            _add(out_dir / f"{stem}.jsonl")
            _add(out_dir / f"{stem}.jsonl.gz")
    try:
        paths.sort(key=lambda p: float(p.stat().st_mtime), reverse=True)
    except Exception:
        pass
    return paths


def _iter_jsonl_objects(paths: List[Path], *, max_total_lines: int = 400_000) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    n_lines = 0
    for p in paths:
        if n_lines >= int(max_total_lines):
            break
        try:
            if str(p.name).lower().endswith(".gz"):
                fctx = gzip.open(p, "rt", encoding="utf-8", errors="ignore")
            else:
                fctx = open(p, "r", encoding="utf-8", errors="ignore")
        except Exception:
            continue
        try:
            with fctx as f:
                for line in f:
                    n_lines += 1
                    if n_lines > int(max_total_lines):
                        break
                    s = str(line or "").strip("\n")
                    if not s.strip():
                        continue
                    try:
                        obj = json.loads(s)
                    except Exception:
                        continue
                    if isinstance(obj, dict):
                        out.append(obj)
        except Exception:
            continue
    return out


def _agent_event_emit(name: str, *, trace_id: str, ok: bool = True, payload: Optional[Dict[str, Any]] = None, evidence: Optional[List[Dict[str, Any]]] = None, outputs: Optional[Dict[str, Any]] = None, reason: Optional[str] = None) -> Dict[str, Any]:
    nm = str(name or "").strip()
    tid = str(trace_id or "").strip()
    evt_id = uuid.uuid4().hex
    ts_ms = int(_now_ms())
    item: Dict[str, Any] = {
        "id": evt_id,
        "trace_id": tid,
        "ts": ts_ms,
        "event": nm,
        "ok": bool(ok),
        "payload": (payload if isinstance(payload, dict) else {}),
    }
    if reason is not None:
        item["reason"] = str(reason)
    if isinstance(evidence, list) and evidence:
        item["evidence"] = evidence
    if isinstance(outputs, dict) and outputs:
        item["outputs"] = outputs
    try:
        _agent_outbox_append_jsonl("events.jsonl", item)
    except Exception:
        pass
    return item


