def _trade_monitor_cursor_path() -> Path:
    return _agent_outbox_dir() / "trade_monitor_cursor.json"


def _trade_monitor_state_load() -> Dict[str, Any]:
    p = _trade_monitor_cursor_path()
    if not p.exists():
        return {
            "schema_version": 3,
            "last_close_ts_ms": 0,
            "seen_close_ids": [],
            "last_full_day": None,
            "last_report_ts_ms": 0,
            "last_light_ts_ms": 0,
            "last_full_ts_ms": 0,
            "last_light_key": None,
            "last_full_key": None,
            "baseline_full_metrics": None,
            "last_alert_idem": None,
            "last_alert_ts_ms": 0,
            "budget_day": None,
            "budget_used": 0,
            "latency_hist": {},
        }
    try:
        with open(p, "r", encoding="utf-8") as f:
            obj = json.load(f)
        if not isinstance(obj, dict):
            return {
                "schema_version": 3,
                "last_close_ts_ms": 0,
                "seen_close_ids": [],
                "last_full_day": None,
                "last_report_ts_ms": 0,
                "last_light_ts_ms": 0,
                "last_full_ts_ms": 0,
                "last_light_key": None,
                "last_full_key": None,
                "baseline_full_metrics": None,
                "last_alert_idem": None,
                "last_alert_ts_ms": 0,
                "budget_day": None,
                "budget_used": 0,
                "latency_hist": {},
            }
        seen = obj.get("seen_close_ids")
        if not isinstance(seen, list):
            seen = []
        seen_norm: List[str] = []
        for x in seen:
            try:
                s = str(x).strip()
            except Exception:
                s = ""
            if s:
                seen_norm.append(s)
        if len(seen_norm) > 800:
            seen_norm = seen_norm[-800:]
        base_m = obj.get("baseline_full_metrics")
        if not isinstance(base_m, dict):
            base_m = None
        latency_hist = obj.get("latency_hist")
        if not isinstance(latency_hist, dict):
            latency_hist = {}
        latency_norm: Dict[str, List[int]] = {}
        try:
            for k, v in latency_hist.items():
                if k is None:
                    continue
                ks = str(k).strip()
                if not ks:
                    continue
                if not isinstance(v, list):
                    continue
                xs: List[int] = []
                for it in v[-120:]:
                    try:
                        n = int(it)
                    except Exception:
                        n = 0
                    if n > 0:
                        xs.append(int(n))
                if xs:
                    latency_norm[ks] = xs[-120:]
        except Exception:
            latency_norm = {}
        return {
            "schema_version": int(obj.get("schema_version") or 3),
            "last_close_ts_ms": int(obj.get("last_close_ts_ms") or 0),
            "seen_close_ids": seen_norm,
            "last_full_day": (None if obj.get("last_full_day") is None else str(obj.get("last_full_day"))),
            "last_report_ts_ms": int(obj.get("last_report_ts_ms") or 0),
            "last_light_ts_ms": int(obj.get("last_light_ts_ms") or 0),
            "last_full_ts_ms": int(obj.get("last_full_ts_ms") or 0),
            "last_light_key": (None if obj.get("last_light_key") is None else str(obj.get("last_light_key"))),
            "last_full_key": (None if obj.get("last_full_key") is None else str(obj.get("last_full_key"))),
            "baseline_full_metrics": (None if base_m is None else dict(base_m)),
            "last_alert_idem": (None if obj.get("last_alert_idem") is None else str(obj.get("last_alert_idem"))),
            "last_alert_ts_ms": int(obj.get("last_alert_ts_ms") or 0),
            "budget_day": (None if obj.get("budget_day") is None else str(obj.get("budget_day"))),
            "budget_used": int(obj.get("budget_used") or 0),
            "latency_hist": latency_norm,
        }
    except Exception:
        return {
            "schema_version": 3,
            "last_close_ts_ms": 0,
            "seen_close_ids": [],
            "last_full_day": None,
            "last_report_ts_ms": 0,
            "last_light_ts_ms": 0,
            "last_full_ts_ms": 0,
            "last_light_key": None,
            "last_full_key": None,
            "baseline_full_metrics": None,
            "last_alert_idem": None,
            "last_alert_ts_ms": 0,
            "budget_day": None,
            "budget_used": 0,
            "latency_hist": {},
        }


def _trade_monitor_state_save(state: Dict[str, Any]) -> None:
    if not isinstance(state, dict):
        return
    p = _trade_monitor_cursor_path()
    tmp = p.parent / (p.name + ".tmp")
    latency_hist = state.get("latency_hist")
    if not isinstance(latency_hist, dict):
        latency_hist = {}
    latency_norm: Dict[str, List[int]] = {}
    try:
        for k, v in latency_hist.items():
            ks = str(k).strip() if k is not None else ""
            if not ks or not isinstance(v, list):
                continue
            xs: List[int] = []
            for it in v[-120:]:
                try:
                    n = int(it)
                except Exception:
                    n = 0
                if n > 0:
                    xs.append(int(n))
            if xs:
                latency_norm[ks] = xs[-120:]
    except Exception:
        latency_norm = {}
    obj = {
        "schema_version": 3,
        "last_close_ts_ms": int(state.get("last_close_ts_ms") or 0),
        "seen_close_ids": [str(x) for x in (state.get("seen_close_ids") if isinstance(state.get("seen_close_ids"), list) else []) if str(x).strip()][-800:],
        "last_full_day": (None if state.get("last_full_day") is None else str(state.get("last_full_day"))),
        "last_report_ts_ms": int(state.get("last_report_ts_ms") or 0),
        "last_light_ts_ms": int(state.get("last_light_ts_ms") or 0),
        "last_full_ts_ms": int(state.get("last_full_ts_ms") or 0),
        "last_light_key": (None if state.get("last_light_key") is None else str(state.get("last_light_key"))),
        "last_full_key": (None if state.get("last_full_key") is None else str(state.get("last_full_key"))),
        "baseline_full_metrics": (state.get("baseline_full_metrics") if isinstance(state.get("baseline_full_metrics"), dict) else None),
        "last_alert_idem": (None if state.get("last_alert_idem") is None else str(state.get("last_alert_idem"))),
        "last_alert_ts_ms": int(state.get("last_alert_ts_ms") or 0),
        "budget_day": (None if state.get("budget_day") is None else str(state.get("budget_day"))),
        "budget_used": int(state.get("budget_used") or 0),
        "latency_hist": latency_norm,
        "ts": int(_now_ms()),
    }
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False)
        os.replace(str(tmp), str(p))
    except Exception:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass


def _trade_monitor_order_ts_ms(o: Dict[str, Any]) -> int:
    try:
        return int(o.get("ingested_ms") or o.get("received_ms") or o.get("ts") or 0)
    except Exception:
        return 0


def _trade_monitor_order_id(o: Dict[str, Any]) -> Optional[str]:
    if not isinstance(o, dict):
        return None
    for k in ("order_id", "id", "client_order_id", "exchange_order_id"):
        if o.get(k) is not None:
            try:
                s = str(o.get(k)).strip()
            except Exception:
                s = ""
            if s:
                return s
    try:
        seed = json.dumps(
            {
                "pair": o.get("pair"),
                "ts": _trade_monitor_order_ts_ms(o),
                "side": o.get("side"),
                "action": o.get("action"),
                "tag": o.get("tag"),
                "p": (o.get("exec") if isinstance(o.get("exec"), dict) else {}).get("pnl_net_u"),
            },
            sort_keys=True,
            ensure_ascii=False,
        )
        return hashlib.sha256(seed.encode("utf-8")).hexdigest()[:24]
    except Exception:
        return None


