def _trade_monitor_is_close_completed(o: Dict[str, Any]) -> bool:
    if not isinstance(o, dict):
        return False
    try:
        side = str(o.get("side") or "").strip().lower()
    except Exception:
        side = ""
    try:
        action = str(o.get("action") or "").strip().lower()
    except Exception:
        action = ""
    if side == "close" and action != "close":
        action = "close"
        try:
            o["action"] = "close"
        except Exception:
            pass
    if action != "close":
        return False

    try:
        status = str(o.get("status") or "").strip().lower()
    except Exception:
        status = ""
    if status in ("canceled", "cancelled", "rejected", "failed", "error", "open", "new", "pending", "observed"):
        return False
    if status in ("filled", "closed", "done", "ok", "completed", "settled", "success", "executed"):
        return True
    exec0 = o.get("exec") if isinstance(o.get("exec"), dict) else {}
    if exec0.get("pnl_net_u") is not None or exec0.get("pnl_gross_u") is not None or exec0.get("pnl") is not None:
        return True
    return bool(status)


def _trade_monitor_reject_stats_snapshot(limit: int = 2000, include_shadow: bool = False) -> Dict[str, Any]:
    try:
        lim = int(limit or 2000)
    except Exception:
        lim = 2000
    lim = max(50, min(20000, int(lim)))
    def _evt_ts_ms(evt: Any) -> int:
        if not isinstance(evt, dict):
            return 0
        try:
            return int(evt.get("ingested_ms") or evt.get("received_ms") or evt.get("ts_emit_ms") or evt.get("ts") or 0)
        except Exception:
            return 0
    evts0 = sorted(EVENTS.values(), key=_evt_ts_ms, reverse=True)
    if not include_shadow:
        try:
            def _is_shadow_mode(evt: Any) -> bool:
                if not isinstance(evt, dict):
                    return False
                di = evt.get("decision_info")
                if not isinstance(di, dict):
                    return False
                return str(di.get("reason") or "").strip().lower() == "shadow_mode"
            evts0 = [e for e in evts0 if not _is_shadow_mode(e)]
        except Exception:
            pass
    evts = evts0[:lim]
    by_decision: Dict[str, int] = {}
    by_reason: Dict[str, int] = {}
    with_decision = 0
    for e in evts:
        if not isinstance(e, dict):
            continue
        di = e.get("decision_info")
        if not isinstance(di, dict):
            continue
        d = str(di.get("decision") or "unknown")
        with_decision += 1
        by_decision[d] = int(by_decision.get(d, 0)) + 1
        if d != "enter":
            r = di.get("reason")
            key = (str(r).strip() if r is not None else "")
            if not key:
                key = "none"
            by_reason[key] = int(by_reason.get(key, 0)) + 1
    reasons_sorted = sorted(by_reason.items(), key=lambda kv: kv[1], reverse=True)
    enter_n = int(by_decision.get("enter") or 0)
    reject_n = int(max(0, with_decision - enter_n))
    reject_rate = (float(reject_n) / float(with_decision)) if with_decision > 0 else 0.0
    return {
        "ok": True,
        "limit": int(lim),
        "total_events": int(len(evts)),
        "with_decision": int(with_decision),
        "by_decision": by_decision,
        "by_reason": {k: int(v) for k, v in reasons_sorted[:50]},
        "reject_rate": float(reject_rate),
        "reject_n": int(reject_n),
    }


def _trade_monitor_signals_window_snapshot(window_start_ms: int, window_end_ms: int, *, limit: int = 20000, include_shadow: bool = False) -> Dict[str, Any]:
    try:
        ws = int(window_start_ms or 0)
        we = int(window_end_ms or 0)
    except Exception:
        ws = 0
        we = 0
    if ws <= 0 or we <= 0 or we < ws:
        return {"ok": False, "error": "bad_window"}
    try:
        lim = int(limit or 20000)
    except Exception:
        lim = 20000
    lim = max(100, min(20000, int(lim)))

    evts0 = sorted(EVENTS.values(), key=lambda x: int(x.get("ingested_ms") or x.get("received_ms") or x.get("ts") or 0), reverse=True)
    if not include_shadow:
        try:
            def _is_shadow_mode(evt: Any) -> bool:
                if not isinstance(evt, dict):
                    return False
                di = evt.get("decision_info")
                if not isinstance(di, dict):
                    return False
                return str(di.get("reason") or "").strip().lower() == "shadow_mode"
            evts0 = [e for e in evts0 if not _is_shadow_mode(e)]
        except Exception:
            pass

    seen = 0
    by_decision: Dict[str, int] = {}
    by_reason: Dict[str, int] = {}
    by_pair: Dict[str, int] = {}
    for e in evts0[:lim]:
        if not isinstance(e, dict):
            continue
        ts = int(e.get("ingested_ms") or e.get("received_ms") or e.get("ts") or 0)
        if ts <= 0:
            continue
        if ts < ws or ts > we:
            continue
        seen += 1
        di = e.get("decision_info") if isinstance(e.get("decision_info"), dict) else None
        if di is not None:
            d = str(di.get("decision") or "unknown")
            by_decision[d] = int(by_decision.get(d, 0)) + 1
            if d != "enter":
                r = di.get("reason")
                rk = (str(r).strip() if r is not None else "")
                if not rk:
                    rk = "none"
                by_reason[rk] = int(by_reason.get(rk, 0)) + 1
        try:
            p = str(e.get("pair") or "").strip().upper()
        except Exception:
            p = ""
        if p:
            by_pair[p] = int(by_pair.get(p, 0)) + 1

    reasons_sorted = sorted(by_reason.items(), key=lambda kv: kv[1], reverse=True)
    pairs_sorted = sorted(by_pair.items(), key=lambda kv: kv[1], reverse=True)
    hrs = max(1e-9, float(int(we) - int(ws)) / 3600_000.0)
    enter_n = int(by_decision.get("enter") or 0)
    reject_n = int(max(0, seen - enter_n))
    reject_rate = (float(reject_n) / float(seen)) if seen > 0 else 0.0
    return {
        "ok": True,
        "window": {"start_ms": int(ws), "end_ms": int(we), "hours": float(hrs)},
        "total_signals": int(seen),
        "signal_density_per_hour": float(float(seen) / float(hrs)),
        "by_decision": by_decision,
        "reject_rate": float(reject_rate),
        "reject_n": int(reject_n),
        "top_reject_reasons": [{"reason": k, "count": int(v)} for k, v in reasons_sorted[:12]],
        "top_pairs": [{"pair": k, "count": int(v)} for k, v in pairs_sorted[:12]],
        "limit": int(lim),
    }


