def _trade_monitor_suggestion_attach_faq_fields(
    sug: Dict[str, Any],
    *,
    trace_id: str,
    window_start_ms: int,
    window_end_ms: int,
    tighten_only: bool,
) -> Dict[str, Any]:
    if not isinstance(sug, dict):
        return {}
    out = dict(sug)

    phen = str(out.get("phenomenon_id") or "").strip() or "unknown"
    if out.get("symptom_code") is None:
        out["symptom_code"] = phen

    if out.get("reason_code") is None:
        rid = ""
        try:
            ev = out.get("evidence") if isinstance(out.get("evidence"), dict) else {}
            rid = str(ev.get("rule_id") or "").strip()
        except Exception:
            rid = ""
        out["reason_code"] = (rid if rid else f"heuristic:{phen.lower()}")

    if out.get("trigger") is None:
        trig: Dict[str, Any] = {"window": {"start_ms": int(window_start_ms), "end_ms": int(window_end_ms)}}
        try:
            ev = out.get("evidence") if isinstance(out.get("evidence"), dict) else {}
            if ev.get("details") is not None:
                trig["rule_details"] = ev.get("details")
        except Exception:
            pass
        out["trigger"] = trig

    ie = out.get("interface_evidence") if isinstance(out.get("interface_evidence"), list) else []
    merged: List[Dict[str, Any]] = [x for x in ie if isinstance(x, dict)]
    existing_eps = {str(x.get("endpoint") or "") for x in merged}
    for x in _trade_monitor_interface_evidence_default(window_start_ms=int(window_start_ms), window_end_ms=int(window_end_ms)):
        ep = str(x.get("endpoint") or "")
        if ep and ep not in existing_eps:
            merged.append(x)
            existing_eps.add(ep)
    out["interface_evidence"] = merged

    sb = out.get("sandbox_plan") if isinstance(out.get("sandbox_plan"), list) else []
    sandbox: List[Dict[str, Any]] = [x for x in sb if isinstance(x, dict)]
    kinds = {str(x.get("kind") or "").strip().lower() for x in sandbox}
    has_core = any(k in ("backtest", "rolling_verify", "monte_carlo", "backtest_compare", "rolling") for k in kinds)
    has_replay_or_stress = any(k in ("replay", "stress", "replay_stress") for k in kinds)
    if not has_core or not has_replay_or_stress:
        for x in _trade_monitor_sandbox_plan_default(trace_id=str(trace_id)):
            k = str(x.get("kind") or "").strip().lower()
            if not k:
                continue
            if k in kinds:
                continue
            sandbox.append(x)
            kinds.add(k)
    out["sandbox_plan"] = sandbox

    if out.get("rollback_plan") is None:
        out["rollback_plan"] = {
            "snapshot": {"endpoint": "POST /evaluation/rollback/snapshot", "auth": "governance_write"},
            "restore": {"endpoint": "POST /evaluation/rollback/restore", "auth": "governance_write"},
            "policy": "snapshot_before_apply",
        }

    if out.get("release_plan") is None:
        out["release_plan"] = [
            {"step": "snapshot", "endpoint": "POST /evaluation/rollback/snapshot"},
            {"step": "sandbox_validate", "endpoints": ["POST /evaluation/rolling_verify", "POST /evaluation/monte_carlo", "GET /agent/trace/replay"]},
            {"step": "draft_change", "endpoint": "POST /agent/changeset/draft"},
            {"step": "approval_apply", "endpoint": "POST /governance/changeset/apply"},
            {"step": "monitor", "endpoint": "GET /agent/outbox/read?name=trade_monitor_reports.jsonl&offset=0&limit=50"},
        ]

    if out.get("preauth") is None:
        if bool(tighten_only):
            out["preauth"] = {"preauthorized": True, "scope": "tighten_only"}
        else:
            out["preauth"] = {"preauthorized": False, "scope": None}

    if out.get("minimal_fix_actions") is None:
        out["minimal_fix_actions"] = [
            "create_rollback_snapshot",
            "run_sandbox_validation",
            "produce_auditable_changeset",
            "apply_with_approval",
        ]

    return out


def _tm_iso_utc(ts_ms: Any) -> str:
    try:
        x = int(ts_ms)
    except Exception:
        return "N/A"
    if x <= 0:
        return "N/A"
    try:
        dt = datetime.fromtimestamp(float(x) / 1000.0, tz=timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    except Exception:
        return "N/A"


def _tm_f4(v: Any) -> str:
    if v is None:
        return "N/A"
    try:
        x = float(v)
    except Exception:
        return "N/A"
    if not math.isfinite(float(x)):
        return "N/A"
    return f"{float(x):.4f}"


def _tm_severity_display(sev: Any) -> str:
    s = str(sev or "").strip()
    if not s:
        return "info"
    u = s.upper()
    if u in ("P0", "P1", "P2", "P3"):
        return f"TM-{u}"
    return s


def _tm_compact_join(items: List[str], *, max_items: int, sep: str, empty_value: str) -> str:
    xs = [str(x) for x in (items or []) if str(x).strip()]
    if not xs:
        return str(empty_value)
    if int(max_items) <= 0:
        return sep.join(xs)
    if len(xs) <= int(max_items):
        return sep.join(xs)
    keep = xs[: int(max_items)]
    return sep.join(keep) + f"{sep}...(+{int(len(xs) - int(max_items))})"


def _trade_monitor_compact_upgrade_hits(report: Dict[str, Any]) -> str:
    hits = []
    try:
        hits = ((report.get("rules") or {}) if isinstance(report.get("rules"), dict) else {}).get("upgrade_hits")
    except Exception:
        hits = None
    if not isinstance(hits, list):
        hits = report.get("upgrade_rules_hit") if isinstance(report.get("upgrade_rules_hit"), list) else []
    rows: List[Tuple[int, str, str]] = []
    sev_pri = {"P0": 0, "P1": 1, "P2": 2, "WARN": 3, "INFO": 4}
    for h in hits:
        if not isinstance(h, dict):
            continue
        rid = str(h.get("rule_id") or "").strip()
        if not rid:
            continue
        sev = str(h.get("severity") or "").strip() or "info"
        sev0 = sev.upper()
        pri = int(sev_pri.get(sev0, 99))
        rows.append((pri, rid, sev))
    rows.sort(key=lambda x: (x[0], x[1]))
    items = [f"{_tm_severity_display(sev)}:{rid}" for _, rid, sev in rows]
    return _tm_compact_join(items, max_items=8, sep=", ", empty_value="[]")


def _trade_monitor_compact_trigger_rules_matched(report: Dict[str, Any]) -> str:
    rules = []
    try:
        rules = ((report.get("rules") or {}) if isinstance(report.get("rules"), dict) else {}).get("trigger_rules")
    except Exception:
        rules = None
    if not isinstance(rules, list):
        rules = report.get("trigger_rules") if isinstance(report.get("trigger_rules"), list) else []
    lvl_pri = {"upgrade_full": 0, "full": 1, "light": 2, "skip_full": 3, "rate_limit": 4}
    rows: List[Tuple[int, str, str, str]] = []
    for r in rules:
        if not isinstance(r, dict):
            continue
        if not bool(r.get("matched")):
            continue
        rid = str(r.get("rule_id") or "").strip()
        if not rid:
            continue
        lvl = str(r.get("level") or "").strip() or "unknown"
        grp = str(r.get("group") or "").strip() or "N/A"
        pri = int(lvl_pri.get(lvl, 99))
        rows.append((pri, rid, lvl, grp))
    rows.sort(key=lambda x: (x[0], x[1]))
    items = [f"{lvl}:{rid}({grp})" for _, rid, lvl, grp in rows]
    return _tm_compact_join(items, max_items=12, sep=", ", empty_value="[]")


def _trade_monitor_compact_latency_p95_ms(report: Dict[str, Any]) -> str:
    mc = report.get("monitor_cost") if isinstance(report.get("monitor_cost"), dict) else None
    lat = (mc.get("latency_p95_ms") if isinstance(mc, dict) else None) if isinstance(mc, dict) else None
    if not isinstance(lat, dict) or not lat:
        return "N/A"
    rows: List[Tuple[int, str]] = []
    for k, v in lat.items():
        try:
            p95 = int(v)
        except Exception:
            continue
        kk = str(k)
        if not kk:
            continue
        rows.append((p95, kk))
    if not rows:
        return "N/A"
    rows.sort(key=lambda x: (-x[0], x[1]))
    items = [f"{k}={int(v)}" for v, k in rows]
    return _tm_compact_join(items, max_items=6, sep=", ", empty_value="N/A")


def _trade_monitor_compact_doc_refs(report: Dict[str, Any]) -> str:
    refs = report.get("doc_refs") if isinstance(report.get("doc_refs"), list) else []
    seen: set = set()
    items: List[str] = []
    for r in refs:
        if not isinstance(r, dict):
            continue
        doc_path = str(r.get("doc_path") or "").strip()
        section = str(r.get("section") or "").strip()
        rule = (None if r.get("rule") is None else str(r.get("rule") or "").strip())
        if not doc_path or not section:
            continue
        k = (doc_path, section, rule or "")
        if k in seen:
            continue
        seen.add(k)
        s = f"{doc_path}:{section}"
        if rule:
            s += f"@{rule}"
        items.append(s)
    return _tm_compact_join(items, max_items=8, sep=", ", empty_value="[]")


def _trade_monitor_compact_evidence_endpoints(report: Dict[str, Any]) -> str:
    ev = None
    if isinstance(report.get("input_evidence"), list):
        ev = report.get("input_evidence")
    elif isinstance(report.get("interface_evidence"), list):
        ev = report.get("interface_evidence")
    if not isinstance(ev, list) or not ev:
        return "[]"
    seen: set = set()
    items: List[str] = []
    for x in ev:
        if not isinstance(x, dict):
            continue
        ep = str(x.get("endpoint") or "").strip()
        if not ep:
            continue
        method = str(x.get("method") or "").strip().upper()
        label = f"{method} {ep}".strip() if method else ep
        if label in seen:
            continue
        seen.add(label)
        items.append(label)
        if len(items) >= 12:
            break
    return "[" + ", ".join(items) + "]"


def _trade_monitor_compact_delta_metrics(delta_metrics: Any, *, max_items: int, keys: List[str]) -> str:
    if not isinstance(delta_metrics, dict):
        return "N/A"
    if any(k in delta_metrics for k in ("baseline_ref", "baseline", "current", "delta")):
        return "N/A"
    items: List[str] = []
    for k in keys:
        v = delta_metrics.get(k)
        if not isinstance(v, dict):
            continue
        if v.get("base") is None or v.get("cur") is None or v.get("abs") is None:
            continue
        base_s = _tm_f4(v.get("base"))
        cur_s = _tm_f4(v.get("cur"))
        abs_s = _tm_f4(v.get("abs"))
        rel_s = _tm_f4(v.get("rel")) if v.get("rel") is not None else "N/A"
        items.append(f"{k}:base={base_s},cur={cur_s},abs={abs_s},rel={rel_s}")
    return _tm_compact_join(items, max_items=int(max_items), sep=" | ", empty_value="N/A")


def _trade_monitor_analysis_build(report: Dict[str, Any]) -> Dict[str, Any]:
    r = report if isinstance(report, dict) else {}
    kind = str(r.get("kind") or "N/A")
    trace_id = str(r.get("trace_id") or "N/A")
    window = r.get("window") if isinstance(r.get("window"), dict) else {}
    start_ms = (window.get("start_ms") if isinstance(window, dict) else None)
    end_ms = (window.get("end_ms") if isinstance(window, dict) else None)
    start_iso = _tm_iso_utc(start_ms)
    end_iso = _tm_iso_utc(end_ms)
    try:
        start_ms_i = int(start_ms) if start_ms is not None else None
    except Exception:
        start_ms_i = None
    try:
        end_ms_i = int(end_ms) if end_ms is not None else None
    except Exception:
        end_ms_i = None

    summary = r.get("summary") if isinstance(r.get("summary"), dict) else {}
    trades = int(summary.get("trades") or 0) if isinstance(summary, dict) else 0
    wins = int(summary.get("wins") or 0) if isinstance(summary, dict) else 0
    losses = int(summary.get("losses") or 0) if isinstance(summary, dict) else 0
    winrate = summary.get("winrate") if isinstance(summary, dict) else None
    pnl_net_u = summary.get("pnl_net_u") if isinstance(summary, dict) else None
    fees_u = summary.get("fees_u") if isinstance(summary, dict) else None
    funding_u = summary.get("funding_u") if isinstance(summary, dict) else None
    max_drawdown_u = summary.get("max_drawdown_u") if isinstance(summary, dict) else None

    baseline_ref = None
    try:
        baseline_ref = str(r.get("baseline_ref") or "").strip() or None
    except Exception:
        baseline_ref = None
    if baseline_ref is None:
        b0 = r.get("baseline") if isinstance(r.get("baseline"), dict) else None
        if isinstance(b0, dict):
            try:
                baseline_ref = str(b0.get("ref") or "").strip() or None
            except Exception:
                baseline_ref = None
    baseline_missing = bool(r.get("baseline_missing")) if r.get("baseline_missing") is not None else bool(not baseline_ref)
    stable_24h = bool(r.get("stable_24h")) if r.get("stable_24h") is not None else False

    delta_metrics = r.get("delta_metrics") if isinstance(r.get("delta_metrics"), dict) else None
    if (not isinstance(delta_metrics, dict)) and isinstance(r.get("rules"), dict):
        try:
            delta_metrics = (r.get("rules") or {}).get("delta_metrics")
        except Exception:
            delta_metrics = None

    delta_core_compact = "N/A"
    if (not baseline_missing) and isinstance(delta_metrics, dict):
        delta_core_compact = _trade_monitor_compact_delta_metrics(
            delta_metrics,
            max_items=3,
            keys=["net_sharpe_oos", "sharpe", "profit_factor", "max_drawdown_pct", "daily_dd_pct", "reject_rate", "order_fail_rate"],
        )

    upgrade_hit_list_compact = _trade_monitor_compact_upgrade_hits(r)
    trigger_rules_matched_compact = _trade_monitor_compact_trigger_rules_matched(r)

    trigger_reason = str(r.get("trigger_reason") or "N/A").strip() or "N/A"
    budget = r.get("budget") if isinstance(r.get("budget"), dict) else {}
    used = budget.get("used") if isinstance(budget, dict) else None
    limit = budget.get("limit") if isinstance(budget, dict) else None
    budget_used = "N/A"
    budget_limit = "N/A"
    try:
        if used is not None:
            budget_used = str(int(used))
    except Exception:
        budget_used = "N/A"
    try:
        if limit is not None:
            budget_limit = str(int(limit))
    except Exception:
        budget_limit = "N/A"

    reject_stats = None
    try:
        reject_stats = ((r.get("signals") or {}) if isinstance(r.get("signals"), dict) else {}).get("reject_stats")
    except Exception:
        reject_stats = None
    reject_rate = (reject_stats.get("reject_rate") if isinstance(reject_stats, dict) else None)
    top_reject = []
    if isinstance(reject_stats, dict) and isinstance(reject_stats.get("by_reason"), dict):
        try:
            top_reject = sorted(list((reject_stats.get("by_reason") or {}).items()), key=lambda kv: kv[1], reverse=True)[:3]
        except Exception:
            top_reject = []

    mc = r.get("monitor_cost") if isinstance(r.get("monitor_cost"), dict) else None
    api_calls_total = mc.get("api_calls_total") if isinstance(mc, dict) else None
    token_cost_estimate = mc.get("token_cost_estimate") if isinstance(mc, dict) else None
    latency_p95_ms_compact = _trade_monitor_compact_latency_p95_ms(r)

    exec_snapshot = None
    try:
        exec_snapshot = ((r.get("execution") or {}) if isinstance(r.get("execution"), dict) else {}).get("snapshot")
    except Exception:
        exec_snapshot = None
    order_fail_rate = exec_snapshot.get("order_fail_rate") if isinstance(exec_snapshot, dict) else None

    macro_snapshot = None
    try:
        macro_snapshot = ((r.get("macro") or {}) if isinstance(r.get("macro"), dict) else {}).get("snapshot")
    except Exception:
        macro_snapshot = None
    macro_summary = "N/A"
    if isinstance(macro_snapshot, dict):
        try:
            bits = []
            for k in ("risk_state", "confidence", "btc_time_regime", "eth_time_regime"):
                if macro_snapshot.get(k) is None:
                    continue
                bits.append(f"{k}={str(macro_snapshot.get(k))}")
            if bits:
                macro_summary = " ".join(bits)[:240]
        except Exception:
            macro_summary = "N/A"

    evidence_endpoints_compact = _trade_monitor_compact_evidence_endpoints(r)
    doc_refs_compact = _trade_monitor_compact_doc_refs(r)

    anomalies = r.get("anomalies") if isinstance(r.get("anomalies"), list) else []
    n_anom = int(len([x for x in anomalies if isinstance(x, dict)]))

    by_system = r.get("by_system") if isinstance(r.get("by_system"), dict) else {}
    top_pairs = r.get("top_pairs") if isinstance(r.get("top_pairs"), list) else []
    top_loss_pairs = r.get("top_loss_pairs") if isinstance(r.get("top_loss_pairs"), list) else []

    sections: List[Dict[str, Any]] = []

    window_line = f"[Trade Monitor] kind={kind} window={start_iso}~{end_iso} ({'N/A' if start_ms_i is None else start_ms_i}~{'N/A' if end_ms_i is None else end_ms_i}) trace_id={trace_id}"
    sections.append({"id": "window", "title": "Window", "lines": [window_line], "data": {"window": {"start_ms": start_ms_i, "end_ms": end_ms_i}}})

    sec_overview = [
        "1) 总览",
        f"- trades={int(trades)} wins={int(wins)} losses={int(losses)} winrate={_tm_f4(winrate)}",
        f"- pnl_net_u={_tm_f4(pnl_net_u)} fees_u={_tm_f4(fees_u)} funding_u={_tm_f4(funding_u)}",
        f"- max_drawdown_u={_tm_f4(max_drawdown_u)}",
        f"- baseline_ref={baseline_ref or 'N/A'} baseline_missing={str(bool(baseline_missing)).lower()} stable_24h={str(bool(stable_24h)).lower()}",
        f"- delta_core={delta_core_compact}",
    ]
    sections.append({"id": "summary", "title": "总览", "lines": sec_overview, "data": {"summary": summary, "baseline_ref": baseline_ref, "baseline_missing": bool(baseline_missing), "stable_24h": bool(stable_24h)}})

    sys_lines = ["2) 分系统（Strategy/Quant/Carry/ThreeScreen）"]
    for sk in ("strategy", "quant", "carry", "three_screen"):
        sv = by_system.get(sk) if isinstance(by_system, dict) else None
        if not isinstance(sv, dict):
            continue
        sys_lines.append(f"- {sk}: trades={int(sv.get('trades') or 0)} pnl_net_u={_tm_f4(sv.get('pnl_net_u'))} winrate={_tm_f4(sv.get('winrate'))}")
    if len(sys_lines) == 1:
        sys_lines.append("- N/A")
    sections.append({"id": "systems", "title": "分系统", "lines": sys_lines, "data": {"by_system": by_system}})

    pair_lines = ["3) Top Pairs"]
    tp0 = [x for x in top_pairs if isinstance(x, dict)]
    for x in tp0[:6]:
        pair_lines.append(f"- {str(x.get('pair') or 'N/A')}: trades={int(x.get('trades') or 0)} pnl_net_u={_tm_f4(x.get('pnl_net_u'))}")
    lp0 = [x for x in top_loss_pairs if isinstance(x, dict)]
    if lp0:
        for x in lp0[:5]:
            pair_lines.append(f"- loss_pair={str(x.get('pair') or 'N/A')}: trades={int(x.get('trades') or 0)} pnl_net_u={_tm_f4(x.get('pnl_net_u'))}")
    if len(pair_lines) == 1:
        pair_lines.append("- N/A")
    sections.append({"id": "pairs", "title": "Top Pairs", "lines": pair_lines, "data": {"top_pairs": top_pairs[:10] if isinstance(top_pairs, list) else [], "top_loss_pairs": top_loss_pairs[:10] if isinstance(top_loss_pairs, list) else []}})

    sig_lines = ["4) 信号与拒绝"]
    try:
        sig_win = ((r.get("signals") or {}) if isinstance(r.get("signals"), dict) else {}).get("window")
    except Exception:
        sig_win = None
    signals_in_window = None
    if isinstance(sig_win, dict):
        signals_in_window = sig_win.get("total_signals")
    sig_lines.append(f"- signals_in_window={('N/A' if signals_in_window is None else int(signals_in_window))} reject_rate={_tm_f4(reject_rate)}")
    if top_reject:
        for k, v in top_reject[:3]:
            sig_lines.append(f"- top_reject={str(k)}:{int(v)}")
    else:
        sig_lines.append("- top_reject=N/A")
    sections.append({"id": "signals", "title": "信号与拒绝", "lines": sig_lines, "data": {"reject_stats": reject_stats}})

    rules_lines = [
        "5) 异常与规则命中（可审计）",
        f"- anomalies={int(n_anom)} (来自 upgrade_hits/upgrade_rules_hit)",
        f"- upgrade_hits={upgrade_hit_list_compact}",
        f"- trigger_rules_matched={trigger_rules_matched_compact}",
        f"- trigger_reason={trigger_reason} budget={budget_used}/{budget_limit}",
    ]
    sections.append({"id": "rules", "title": "异常与规则命中", "lines": rules_lines, "data": {"upgrade_hits": (r.get('upgrade_rules_hit') if isinstance(r.get('upgrade_rules_hit'), list) else ((r.get('rules') or {}) if isinstance(r.get('rules'), dict) else {}).get('upgrade_hits')), "trigger_rules": (r.get('trigger_rules') if isinstance(r.get('trigger_rules'), list) else ((r.get('rules') or {}) if isinstance(r.get('rules'), dict) else {}).get('trigger_rules'))}})

    mx_lines = [
        "6) 宏观与执行（如可得）",
        f"- macro: {macro_summary}",
        f"- execution: order_fail_rate={_tm_f4(order_fail_rate)} latency_p95_ms={latency_p95_ms_compact}",
    ]
    sections.append({"id": "macro", "title": "宏观与执行", "lines": mx_lines, "data": {"macro": (r.get("macro") if isinstance(r.get("macro"), dict) else None), "execution": (r.get("execution") if isinstance(r.get("execution"), dict) else None)}})

    cost_lines = [
        "7) 监控成本（必须可回放）",
        f"- cost: api_calls_total={('N/A' if api_calls_total is None else int(api_calls_total))} token_cost_estimate={('N/A' if token_cost_estimate is None else int(token_cost_estimate))}",
        f"- latency_p95_ms={latency_p95_ms_compact}",
    ]
    sections.append({"id": "cost", "title": "监控成本", "lines": cost_lines, "data": {"monitor_cost": mc}})

    sug_lines = ["8) 建议（Optimization List）"]
    sugs = r.get("suggestions") if isinstance(r.get("suggestions"), list) else []
    sug_items = [x for x in sugs if isinstance(x, dict)]
    if sug_items:
        for s in sug_items[:6]:
            sev = str(s.get("severity") or "N/A")
            phen = str(s.get("phenomenon_id") or "N/A")
            scope = str(s.get("scope") or "N/A")
            direction = str(s.get("direction") or "N/A")
            objective = str(s.get("objective_profile") or "N/A")
            sug_lines.append(f"- [{sev}] {phen} scope={scope} direction={direction} objective={objective}")
            dm = s.get("delta_metrics")
            dm_compact = _trade_monitor_compact_delta_metrics(dm, max_items=3, keys=["sharpe", "profit_factor", "max_drawdown_pct"]) if isinstance(dm, dict) else "N/A"
            if dm_compact == "N/A" and isinstance(delta_metrics, dict):
                dm_compact = _trade_monitor_compact_delta_metrics(delta_metrics, max_items=3, keys=["sharpe", "profit_factor", "max_drawdown_pct"])
            sug_lines.append(f"  delta_metrics: {dm_compact} baseline_ref={baseline_ref or 'N/A'}")
            hyp = str(s.get("hypothesis") or "").strip()
            if hyp:
                hyp = re.sub(r"\\s+", " ", hyp).strip()
                sug_lines.append(f"  hypothesis: {hyp[:240]}")
            ch = str(s.get("change") or "").strip()
            if ch:
                ch = re.sub(r"\\s+", " ", ch).strip()
                sug_lines.append(f"  change: {ch[:240]}")
    else:
        sug_lines.append("- N/A")
    sections.append({"id": "suggestions", "title": "建议", "lines": sug_lines, "data": {"suggestions": sug_items[:12]}})

    ev_lines = [
        "9) 证据与引用（必须可回放）",
        f"- evidence_endpoints={evidence_endpoints_compact}",
        f"- doc_refs={doc_refs_compact}",
    ]
    if evidence_endpoints_compact == "[]":
        ev_lines.append("- evidence_missing=true")
    sections.append({"id": "evidence", "title": "证据与引用", "lines": ev_lines, "data": {"input_evidence": (r.get("input_evidence") if isinstance(r.get("input_evidence"), list) else None), "doc_refs": (r.get("doc_refs") if isinstance(r.get("doc_refs"), list) else None)}})

    lines: List[str] = []
    for sec in sections:
        for ln in (sec.get("lines") or []):
            if isinstance(ln, str) and ln.strip():
                lines.append(ln.rstrip())
        lines.append("")
    text = "\n".join(lines).strip()
    if len(text) > 8000:
        text = text[:7990] + "…"

    return {
        "template_version": 1,
        "text": text,
        "sections": sections,
        "compacts": {
            "delta_core_compact": delta_core_compact,
            "upgrade_hit_list_compact": upgrade_hit_list_compact,
            "trigger_rules_matched_compact": trigger_rules_matched_compact,
            "latency_p95_ms_compact": latency_p95_ms_compact,
            "evidence_endpoints_compact": evidence_endpoints_compact,
            "doc_refs_compact": doc_refs_compact,
        },
    }


def _trade_monitor_outbox_find_latest_report(*, max_lines: int = 5000) -> Optional[Dict[str, Any]]:
    p = _agent_outbox_dir() / "trade_monitor_reports.jsonl"
    if not p.exists():
        return None
    buf: deque[Dict[str, Any]] = deque(maxlen=max(50, min(20000, int(max_lines))))
    try:
        with open(p, "r", encoding="utf-8") as f:
            for line in f:
                s = line.strip("\n")
                if not s.strip():
                    continue
                try:
                    obj = json.loads(s)
                except Exception:
                    continue
                if not isinstance(obj, dict):
                    continue
                if obj.get("window") is None or obj.get("summary") is None:
                    continue
                buf.append(obj)
    except Exception:
        return None
    if not buf:
        return None
    return buf[-1]


def _trade_monitor_build_report(
    now_ms: int,
    *,
    trace_id: str,
    kind: str,
    window_start_ms: int,
    window_end_ms: int,
    close_orders: List[Dict[str, Any]],
    reject_stats: Dict[str, Any],
    context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    rows = []
    by_system: Dict[str, Any] = {}
    by_pair: Dict[str, Any] = {}
    settle_by_oid = None
    settle_by_eid = None
    try:
        settle_by_oid = _ab_settlement_index()
    except Exception:
        settle_by_oid = None
    try:
        settle_by_eid = _ab_settlement_index_by_event_id()
    except Exception:
        settle_by_eid = None
    for o in close_orders:
        if not isinstance(o, dict):
            continue
        ts = _trade_monitor_order_ts_ms(o)
        if ts <= 0 or ts < int(window_start_ms) or ts > int(window_end_ms):
            continue
        exec0 = o.get("exec") if isinstance(o.get("exec"), dict) else {}
        pnl_net = exec0.get("pnl_net_u")
        pnl_gross = exec0.get("pnl_gross_u")
        pnl_raw = (pnl_net if pnl_net is not None else pnl_gross)
        pnl_has_direct = (pnl_raw is not None)
        try:
            pnl = float(_to_float(pnl_raw)) if pnl_raw is not None else 0.0
        except Exception:
            pnl = 0.0
        if not math.isfinite(float(pnl)):
            pnl = 0.0
        try:
            fees_u = float(_to_float(exec0.get("fees_u", 0.0)))
        except Exception:
            fees_u = 0.0
        if not math.isfinite(float(fees_u)):
            fees_u = 0.0
        try:
            funding_u = float(_to_float(exec0.get("funding_u", 0.0)))
        except Exception:
            funding_u = 0.0
        if not math.isfinite(float(funding_u)):
            funding_u = 0.0

        pair_raw = str(o.get("pair") or "").strip().upper() or "UNKNOWN"
        try:
            pair_key = str(_pair_to_base(pair_raw) or "").strip().upper() or pair_raw
        except Exception:
            pair_key = pair_raw
        try:
            ao_raw = str(o.get("ab_owner") or "").strip().lower()
        except Exception:
            ao_raw = ""
        try:
            sys_raw = str(o.get("system_id") or "").strip().lower()
        except Exception:
            sys_raw = ""
        try:
            sid_raw = str(o.get("strategy_id") or "").strip()
        except Exception:
            sid_raw = ""
        try:
            tag_raw = str(o.get("tag") or "").strip().lower()
        except Exception:
            tag_raw = ""
        try:
            sys_eff = _ab_infer_owner(ao_raw, system_id=sys_raw, strategy_id=sid_raw, tag=tag_raw)
        except Exception:
            sys_eff = "strategy"
        if sys_eff not in ("strategy", "quant", "carry", "three_screen"):
            sys_eff = "strategy"

        oid_s = None
        try:
            oid_s = str((o.get("id") if o.get("id") is not None else o.get("order_id")) or "").strip() or None
        except Exception:
            oid_s = None
        eid_s = None
        try:
            eid_s = str((o.get("event_id") if o.get("event_id") is not None else o.get("eid")) or "").strip() or None
        except Exception:
            eid_s = None

        rec = None
        if oid_s and isinstance(settle_by_oid, dict):
            rec = settle_by_oid.get(oid_s)
        if rec is None and eid_s and isinstance(settle_by_eid, dict):
            rec = settle_by_eid.get(eid_s)
        if isinstance(rec, dict):
            pnl_by_owner = rec.get("pnl_by_owner") if isinstance(rec.get("pnl_by_owner"), dict) else {}
            fees_by_owner = rec.get("fees_by_owner") if isinstance(rec.get("fees_by_owner"), dict) else {}
            funding_by_owner = rec.get("funding_by_owner") if isinstance(rec.get("funding_by_owner"), dict) else {}
            try:
                if sys_eff in pnl_by_owner:
                    pnl = float(pnl_by_owner.get(sys_eff) or 0.0)
                else:
                    pnl = float(sum(float(v or 0.0) for v in pnl_by_owner.values()))
            except Exception:
                pass
            try:
                if fees_by_owner:
                    if sys_eff in fees_by_owner:
                        fees_u = float(fees_by_owner.get(sys_eff) or 0.0)
                    else:
                        fees_u = float(sum(float(v or 0.0) for v in fees_by_owner.values()))
            except Exception:
                pass
            try:
                if funding_by_owner:
                    if sys_eff in funding_by_owner:
                        funding_u = float(funding_by_owner.get(sys_eff) or 0.0)
                    else:
                        funding_u = float(sum(float(v or 0.0) for v in funding_by_owner.values()))
            except Exception:
                pass
        elif not pnl_has_direct:
            ps = o.get("pos_snapshot") if isinstance(o.get("pos_snapshot"), dict) else {}
            entry_px = None
            for k in ("aster_entry_px", "entry_px", "entry_price", "avg_entry_px", "avg_entry_price"):
                if ps.get(k) is not None:
                    entry_px = ps.get(k)
                    break
            exit_px = None
            for k in ("avg_fill_px", "fill_px", "avg_fill_price", "fill_price", "price", "average"):
                if exec0.get(k) is not None:
                    exit_px = exec0.get(k)
                    break
            if exit_px is None:
                for k in ("aster_mid_px", "mid_px", "exit_px", "exit_price", "avg_exit_px", "avg_exit_price"):
                    if ps.get(k) is not None:
                        exit_px = ps.get(k)
                        break
            qty = None
            for k in ("qty", "quantity", "amount"):
                if exec0.get(k) is not None:
                    qty = exec0.get(k)
                    break
            if qty is None:
                for k in ("size", "qty", "amount"):
                    if o.get(k) is not None:
                        qty = o.get(k)
                        break
            if qty is None:
                for k in ("base_qty", "qty", "amount"):
                    if ps.get(k) is not None:
                        qty = ps.get(k)
                        break
            if qty is None and ps.get("aster_position_amt") is not None:
                qty = abs(ps.get("aster_position_amt") or 0.0)
            try:
                entry_px_f = float(_to_float(entry_px)) if entry_px is not None else None
            except Exception:
                entry_px_f = None
            try:
                exit_px_f = float(_to_float(exit_px)) if exit_px is not None else None
            except Exception:
                exit_px_f = None
            try:
                qty_f = float(_to_float(qty)) if qty is not None else None
            except Exception:
                qty_f = None
            if entry_px_f is not None and exit_px_f is not None and qty_f is not None:
                if math.isfinite(float(entry_px_f)) and math.isfinite(float(exit_px_f)) and math.isfinite(float(qty_f)) and float(qty_f) > 0.0:
                    side_eff = None
                    try:
                        side_eff = str(o.get("side") or "").strip().lower()
                    except Exception:
                        side_eff = ""
                    if not side_eff and isinstance(ps, dict):
                        try:
                            side_eff = str(ps.get("pos_side") or "").strip().lower()
                        except Exception:
                            side_eff = side_eff or ""
                    if side_eff not in ("long", "short"):
                        try:
                            pa = float(ps.get("aster_position_amt") or 0.0) if isinstance(ps, dict) else 0.0
                        except Exception:
                            pa = 0.0
                        side_eff = ("short" if float(pa) < 0.0 else "long")
                    if side_eff == "short":
                        pnl = float((float(entry_px_f) - float(exit_px_f)) * float(qty_f))
                    else:
                        pnl = float((float(exit_px_f) - float(entry_px_f)) * float(qty_f))
                    if not math.isfinite(float(pnl)):
                        pnl = 0.0

        rows.append({
            "ts": int(ts),
            "pnl_net_u": float(pnl),
            "fees_u": float(fees_u),
            "funding_u": float(funding_u),
            "pair": pair_key,
            "pair_raw": pair_raw,
            "system": sys_eff,
        })

        bp = by_pair.get(pair_key)
        if not isinstance(bp, dict):
            bp = {"trades": 0, "pnl_net_u": 0.0, "pair_raw": pair_raw}
            by_pair[pair_key] = bp
        bp["trades"] = int(bp.get("trades") or 0) + 1
        bp["pnl_net_u"] = float(bp.get("pnl_net_u") or 0.0) + float(pnl)
        if bp.get("pair_raw") is None and pair_raw:
            bp["pair_raw"] = pair_raw

        bs = by_system.get(sys_eff)
        if not isinstance(bs, dict):
            bs = {"trades": 0, "wins": 0, "losses": 0, "pnl_net_u": 0.0, "fees_u": 0.0, "funding_u": 0.0}
            by_system[sys_eff] = bs
        bs["trades"] = int(bs.get("trades") or 0) + 1
        bs["pnl_net_u"] = float(bs.get("pnl_net_u") or 0.0) + float(pnl)
        bs["fees_u"] = float(bs.get("fees_u") or 0.0) + float(fees_u)
        bs["funding_u"] = float(bs.get("funding_u") or 0.0) + float(funding_u)
        if pnl > 0:
            bs["wins"] = int(bs.get("wins") or 0) + 1
        elif pnl < 0:
            bs["losses"] = int(bs.get("losses") or 0) + 1

    total_trades = int(len(rows))
    total_pnl = 0.0
    total_fees = 0.0
    total_funding = 0.0
    total_wins = 0
    total_losses = 0
    for bs in (by_system or {}).values():
        if not isinstance(bs, dict):
            continue
        total_pnl += float(bs.get("pnl_net_u") or 0.0)
        total_fees += float(bs.get("fees_u") or 0.0)
        total_funding += float(bs.get("funding_u") or 0.0)
        total_wins += int(bs.get("wins") or 0)
        total_losses += int(bs.get("losses") or 0)
    winrate = (float(total_wins) / float(total_trades)) if total_trades > 0 else None
    for sk, bs in (by_system or {}).items():
        if not isinstance(bs, dict):
            continue
        try:
            t = int(bs.get("trades") or 0)
        except Exception:
            t = 0
        try:
            w = int(bs.get("wins") or 0)
        except Exception:
            w = 0
        bs["winrate"] = (float(w) / float(t)) if t > 0 else None

    sum_rows_pnl = 0.0
    sum_rows_fees = 0.0
    sum_rows_funding = 0.0
    for r0 in rows:
        if not isinstance(r0, dict):
            continue
        try:
            sum_rows_pnl += float(r0.get("pnl_net_u") or 0.0)
        except Exception:
            pass
        try:
            sum_rows_fees += float(r0.get("fees_u") or 0.0)
        except Exception:
            pass
        try:
            sum_rows_funding += float(r0.get("funding_u") or 0.0)
        except Exception:
            pass
    sum_pairs_pnl = 0.0
    for bp in (by_pair or {}).values():
        if not isinstance(bp, dict):
            continue
        try:
            sum_pairs_pnl += float(bp.get("pnl_net_u") or 0.0)
        except Exception:
            pass

    tol_pnl = max(1e-6, abs(float(total_pnl)) * 1e-6)
    tol_fees = max(1e-6, abs(float(total_fees)) * 1e-6)
    tol_funding = max(1e-6, abs(float(total_funding)) * 1e-6)
    pnl_consistency_ok = True
    if abs(float(sum_rows_pnl) - float(total_pnl)) > float(tol_pnl):
        pnl_consistency_ok = False
    if abs(float(sum_pairs_pnl) - float(total_pnl)) > float(tol_pnl):
        pnl_consistency_ok = False
    if abs(float(sum_rows_fees) - float(total_fees)) > float(tol_fees):
        pnl_consistency_ok = False
    if abs(float(sum_rows_funding) - float(total_funding)) > float(tol_funding):
        pnl_consistency_ok = False
    pnl_consistency = {
        "ok": bool(pnl_consistency_ok),
        "tol": {"pnl": float(tol_pnl), "fees": float(tol_fees), "funding": float(tol_funding)},
        "total": {"pnl_net_u": float(total_pnl), "fees_u": float(total_fees), "funding_u": float(total_funding)},
        "sum_rows": {"pnl_net_u": float(sum_rows_pnl), "fees_u": float(sum_rows_fees), "funding_u": float(sum_rows_funding)},
        "sum_pairs": {"pnl_net_u": float(sum_pairs_pnl)},
    }

    max_drawdown_u = None
    try:
        eq = 0.0
        peak = 0.0
        max_dd = 0.0
        for r0 in sorted([x for x in rows if isinstance(x, dict)], key=lambda x: int(x.get("ts") or 0)):
            try:
                dp = float(r0.get("pnl_net_u") or 0.0)
            except Exception:
                dp = 0.0
            if not math.isfinite(float(dp)):
                dp = 0.0
            eq = float(eq) + float(dp)
            if float(eq) > float(peak):
                peak = float(eq)
            dd = float(peak) - float(eq)
            if float(dd) > float(max_dd):
                max_dd = float(dd)
        max_drawdown_u = float(max_dd)
    except Exception:
        max_drawdown_u = None

    pairs_sorted = sorted(by_pair.items(), key=lambda kv: (kv[1].get("trades") or 0, kv[1].get("pnl_net_u") or 0.0), reverse=True)
    top_pairs = [{
        "pair": ((None if not isinstance(v, dict) else v.get("pair_raw")) or k),
        "pair_raw": (None if not isinstance(v, dict) else v.get("pair_raw")),
        "trades": int((v or {}).get("trades") or 0),
        "pnl_net_u": float((v or {}).get("pnl_net_u") or 0.0),
    } for k, v in pairs_sorted[:10]]
    loss_pairs_sorted = sorted(by_pair.items(), key=lambda kv: (kv[1].get("pnl_net_u") or 0.0, -(kv[1].get("trades") or 0)))
    top_loss_pairs = [{
        "pair": ((None if not isinstance(v, dict) else v.get("pair_raw")) or k),
        "pair_raw": (None if not isinstance(v, dict) else v.get("pair_raw")),
        "trades": int((v or {}).get("trades") or 0),
        "pnl_net_u": float((v or {}).get("pnl_net_u") or 0.0),
    } for k, v in loss_pairs_sorted[:10]]

    suggestions: List[Dict[str, Any]] = []
    doc_refs = _agent_doc_refs_trade_monitor_default()
    ctx = context if isinstance(context, dict) else {}
    baseline_ref = (None if ctx.get("baseline_ref") is None else str(ctx.get("baseline_ref")))
    baseline_metrics = (ctx.get("baseline_metrics") if isinstance(ctx.get("baseline_metrics"), dict) else None)
    current_metrics = (ctx.get("current_metrics") if isinstance(ctx.get("current_metrics"), dict) else None)
    delta_metrics = (ctx.get("delta_metrics") if isinstance(ctx.get("delta_metrics"), dict) else None)
    has_p1 = bool(ctx.get("has_p1"))
    exec_snapshot = (ctx.get("exec_snapshot") if isinstance(ctx.get("exec_snapshot"), dict) else None)
    macro_snapshot = (ctx.get("macro_snapshot") if isinstance(ctx.get("macro_snapshot"), dict) else None)
    exposure_snapshot = (ctx.get("exposure_snapshot") if isinstance(ctx.get("exposure_snapshot"), dict) else None)
    monitor_cost = (ctx.get("monitor_cost") if isinstance(ctx.get("monitor_cost"), dict) else None)
    trigger_rules = (ctx.get("trigger_rules") if isinstance(ctx.get("trigger_rules"), list) else [])
    upgrade_hits = (ctx.get("upgrade_hits") if isinstance(ctx.get("upgrade_hits"), list) else [])
    signals_window = _trade_monitor_signals_window_snapshot(int(window_start_ms), int(window_end_ms), limit=20000, include_shadow=False)
    input_evidence = _trade_monitor_interface_evidence_default(window_start_ms=int(window_start_ms), window_end_ms=int(window_end_ms))
    base_validation_plan = [
        "读取 user_data/datasets/*_orders.jsonl(.gz) 与 /orders/recent，确认窗口内样本量与时间戳连续性",
        "对比 /tracker/stats 的近端汇总，确认 pnl/fees/funding 口径一致",
        "若涉及门禁/阈值调整，先在沙箱回测验证并准备回滚点",
    ]
    if not bool(pnl_consistency_ok):
        suggestions = [{
            "phenomenon_id": "DATA_PNL_INCONSISTENT",
            "hypothesis": "PnL 明细与汇总不一致，拒绝输出可执行优化结论",
            "evidence": {"pnl_consistency": pnl_consistency},
            "change": "先修复 PnL 口径一致性（明细→分pair/分系统→总汇总）再继续优化链路",
            "delta_metrics": {"baseline_ref": baseline_ref, "baseline": baseline_metrics, "current": current_metrics, "delta": delta_metrics},
            "validation_plan": list(base_validation_plan)
            + [
                "对同一窗口内 close_orders 明细做逐笔求和，并与 by_pair/by_system/summary 对齐",
                "若存在降采样/聚合，确保汇总前后累计一致（允许误差阈值），否则拒绝执行",
            ],
            "sandbox_plan": [{"kind": "data_check", "endpoint": "GET /orders/recent"}],
            "doc_refs": doc_refs,
            "interface_evidence": input_evidence,
            "risk": "若在口径不一致情况下继续寻优，会导致错误的方向与过拟合",
            "rollback": "不产生任何自动化变更，仅输出排查建议",
        }]
    try:
        oaf = ctx.get("orders_archive_files")
        if isinstance(oaf, list):
            for p in [str(x) for x in oaf if str(x).strip()][:20]:
                input_evidence.append({"type": "file", "path": p, "note": "orders_archive"})
    except Exception:
        pass
    try:
        rr = float((reject_stats or {}).get("reject_rate") or 0.0)
    except Exception:
        rr = 0.0
    if rr >= 0.30:
        suggestions.append({
            "phenomenon_id": "B2_REJECT_HIGH",
            "hypothesis": "信号拒绝率偏高导致有效交易不足或错过机会",
            "evidence": {"reject_rate": float(rr), "by_reason": (reject_stats or {}).get("by_reason")},
            "change": "优先检查门禁/阈值与宏观硬门配置，按FAQ口径逐项排除",
            "delta_metrics": {"baseline_ref": baseline_ref, "baseline": baseline_metrics, "current": current_metrics, "delta": delta_metrics},
            "validation_plan": list(base_validation_plan),
            "sandbox_plan": [{"kind": "gatecheck", "endpoint": "GET /evaluation/gate/check"}],
            "doc_refs": doc_refs,
            "interface_evidence": input_evidence,
            "risk": "放宽门禁可能提高回撤与尾部风险",
            "rollback": "保留现有阈值快照，变更需可一键回退",
        })
    if total_trades >= 10 and float(total_pnl) < 0.0:
        suggestions.append({
            "phenomenon_id": "A2_RECENT_PNL_NEGATIVE",
            "hypothesis": "近期交易整体亏损，可能存在出场或波动环境不匹配",
            "evidence": {"trades": int(total_trades), "pnl_net_u": float(total_pnl), "by_system": by_system},
            "change": "按系统拆分复盘（Strategy/Quant/Carry），先定位亏损贡献最大的pair与system",
            "delta_metrics": {"baseline_ref": baseline_ref, "baseline": baseline_metrics, "current": current_metrics, "delta": delta_metrics},
            "validation_plan": list(base_validation_plan),
            "sandbox_plan": [{"kind": "backtest", "endpoint": "POST /automation/backtest/run"}, {"kind": "rolling_verify", "endpoint": "POST /evaluation/rolling_verify"}],
            "doc_refs": doc_refs,
            "interface_evidence": input_evidence,
            "risk": "过度收缩可能降低长期收益",
            "rollback": "仅输出建议，不自动改生产",
        })
    if total_trades >= 20 and winrate is not None and float(winrate) < 0.40:
        suggestions.append({
            "phenomenon_id": "A1_WINRATE_LOW",
            "hypothesis": "胜率偏低，可能是入场过滤不足或市场 regime 切换",
            "evidence": {"winrate": float(winrate), "trades": int(total_trades)},
            "change": "结合近期信号分布与拒绝原因，优先优化入场过滤与时间窗口",
            "delta_metrics": {"baseline_ref": baseline_ref, "baseline": baseline_metrics, "current": current_metrics, "delta": delta_metrics},
            "validation_plan": list(base_validation_plan),
            "sandbox_plan": [{"kind": "backtest", "endpoint": "POST /automation/backtest/run"}],
            "doc_refs": doc_refs,
            "interface_evidence": input_evidence,
            "risk": "提升胜率可能牺牲赔率",
            "rollback": "仅输出建议，不自动改生产",
        })

    quant_bs = by_system.get("quant")
    if isinstance(quant_bs, dict) and (not bool(has_p1)):
        try:
            quant_trades = int(quant_bs.get("trades") or 0)
        except Exception:
            quant_trades = 0
        try:
            quant_pnl = float(quant_bs.get("pnl_net_u") or 0.0)
        except Exception:
            quant_pnl = 0.0
        if (quant_trades >= 5) and (math.isfinite(float(quant_pnl))) and (float(quant_pnl) < 0.0):
            cur_mode = _quant_btcalts_strategy_mode_default()
            rec_mode = ("C" if cur_mode in ("A", "B") else "B")
            mode_patch = {"quant_auto_btcalts_strategy_mode": str(rec_mode)}

            strategy_ref = None
            try:
                strategy_ref = _system_monitor_pick_strategy_ref()
            except Exception:
                strategy_ref = None

            draft_req = None
            if isinstance(strategy_ref, dict) and str(strategy_ref.get("strategy_id") or "").strip() and str(strategy_ref.get("source_zip") or "").strip():
                draft_req = {
                    "trace_id": str(trace_id),
                    "strategy_id": str(strategy_ref.get("strategy_id")),
                    "source_zip": str(strategy_ref.get("source_zip")),
                    "policy_ref": "gov_default",
                    "action": "config.apply",
                    "reason": f"trade_monitor:quant_mode_switch:{cur_mode}->{rec_mode}",
                    "doc_refs": doc_refs,
                    "config_patch": dict(mode_patch),
                }

            alts_probe = ["ETH", "SOL", "BNB"]
            urls = []
            for alt in alts_probe:
                for m in ("A", "B", "C"):
                    urls.append(f"/quant/pairs/btcalt/status?alt={alt}&strategy_mode={m}")

            actions: List[Dict[str, Any]] = [
                {"type": "http.batch", "endpoint": "GET /quant/pairs/btcalt/status", "requests": [{"url": u} for u in urls[:18]]},
            ]
            if isinstance(draft_req, dict):
                actions.insert(0, {"type": "agent.changeset.draft", "endpoint": "POST /agent/changeset/draft", "payload": draft_req})

            suggestions.append({
                "phenomenon_id": "F2_QUANT_PNL_NEGATIVE",
                "hypothesis": f"Quant(BTC-Alts) 在当前模式 {cur_mode} 下近期表现偏弱，可能需要切换模式并联动参数自适应",
                "evidence": {
                    "quant": {"trades": int(quant_trades), "pnl_net_u": float(quant_pnl), "fees_u": float(quant_bs.get("fees_u") or 0.0), "funding_u": float(quant_bs.get("funding_u") or 0.0)},
                    "recommended": {"mode": str(rec_mode), "config_patch": mode_patch},
                    "strategy_ref": (strategy_ref if isinstance(strategy_ref, dict) else None),
                    "gating": {"has_p1": bool(has_p1), "baseline_ref": baseline_ref, "delta_metrics": delta_metrics},
                },
                "change": f"建议将 quant_auto_btcalts_strategy_mode 从 {cur_mode} 调整为 {rec_mode}，并用 A/B/C 三档做对比验证后再落地（不与参数寻优并行推进）",
                "delta_metrics": {"baseline_ref": baseline_ref, "baseline": baseline_metrics, "current": current_metrics, "delta": delta_metrics},
                "validation_plan": list(base_validation_plan)
                + [
                    "对 ETH/SOL/BNB 分别调用 /quant/pairs/btcalt/status?strategy_mode=A|B|C，优先选择 gate/structural/stationarity 更稳的模式",
                    "若需要落地，先在本地提交 /agent/changeset/draft 形成可审计变更包，再走治理链路 apply",
                ],
                "sandbox_plan": [
                    {"kind": "backtest_compare", "modes": ["A", "B", "C"], "endpoint": "POST /automation/backtest/run"},
                    {"kind": "rolling_verify", "endpoint": "POST /evaluation/rolling_verify"},
                    {"kind": "monte_carlo", "endpoint": "POST /evaluation/monte_carlo"},
                    {"kind": "gatecheck", "endpoint": "GET /evaluation/gate/check"},
                ],
                "doc_refs": doc_refs,
                "interface_evidence": input_evidence,
                "risk": "模式切换会改变对冲与开仓结构，可能引入短期回撤与执行成本上升",
                "rollback": "通过变更包与回滚点保障一键恢复",
                "actions": actions,
            })

    if (not close_orders) and (not suggestions):
        suggestions.append({
            "phenomenon_id": "DATA_NO_CLOSE_ORDERS",
            "hypothesis": "缺少可复盘的成交/平仓数据，无法生成有效监控结论",
            "evidence": {"close_orders": 0, "window": {"start_ms": int(window_start_ms), "end_ms": int(window_end_ms)}},
            "change": "先补齐订单落库/回传链路，确保 /orders/recent 在窗口内可返回数据",
            "delta_metrics": None,
            "validation_plan": [
                "检查订单采集是否开启，确认 ingested_ms/received_ms 字段写入",
                "调用 /orders/recent 验证窗口内是否有 close 成交记录",
            ],
            "doc_refs": doc_refs,
            "interface_evidence": input_evidence,
            "risk": "无",
            "rollback": "无",
        })

    try:
        suggestions = _trade_monitor_suggestions_route(
            suggestions,
            trace_id=str(trace_id),
            kind=str(kind),
            window_start_ms=int(window_start_ms),
            window_end_ms=int(window_end_ms),
            reject_stats=(reject_stats if isinstance(reject_stats, dict) else {}),
            by_system=(by_system if isinstance(by_system, dict) else {}),
            top_pairs=(top_pairs if isinstance(top_pairs, list) else []),
            metrics_summary=(current_metrics if isinstance(current_metrics, dict) else None),
            baseline=(baseline_metrics if isinstance(baseline_metrics, dict) else None),
            delta_metrics=(delta_metrics if isinstance(delta_metrics, dict) else None),
            exec_snapshot=(exec_snapshot if isinstance(exec_snapshot, dict) else None),
            upgrade_hits=(upgrade_hits if isinstance(upgrade_hits, list) else []),
        )
    except Exception:
        pass

    rep = {
        "schema_version": 1,
        "id": uuid.uuid4().hex,
        "trace_id": str(trace_id),
        "ts": int(now_ms),
        "type": "trade.monitor.report",
        "kind": str(kind),
        "window": {"start_ms": int(window_start_ms), "end_ms": int(window_end_ms)},
        "monitor_cost": monitor_cost,
        "input_evidence": input_evidence,
        "doc_refs": doc_refs,
        "summary": {
            "trades": int(total_trades),
            "wins": int(total_wins),
            "losses": int(total_losses),
            "winrate": (None if winrate is None else float(winrate)),
            "pnl_net_u": float(total_pnl),
            "fees_u": float(total_fees),
            "funding_u": float(total_funding),
            "max_drawdown_u": (None if max_drawdown_u is None else float(max_drawdown_u)),
        },
        "by_system": by_system,
        "top_pairs": top_pairs,
        "top_loss_pairs": top_loss_pairs,
        "signals": {"window": signals_window, "reject_stats": reject_stats},
        "anomalies": [{"severity": (x.get("severity") if isinstance(x, dict) else None), "severity_ns": "tm", "rule_id": (x.get("rule_id") if isinstance(x, dict) else None), "evidence": x} for x in (upgrade_hits or []) if isinstance(x, dict)],
        "macro": {"snapshot": macro_snapshot, "exposure": exposure_snapshot},
        "execution": {"snapshot": exec_snapshot},
        "rules": {"trigger_rules": trigger_rules, "upgrade_hits": upgrade_hits},
        "suggestions": suggestions,
        "consistency": pnl_consistency,
    }
    try:
        rep["analysis"] = _trade_monitor_analysis_build(rep)
    except Exception:
        pass
    return rep


def _trade_monitor_trades_per_day(*, window_start_ms: int, window_end_ms: int, trades: int) -> float:
    try:
        dt_ms = int(window_end_ms) - int(window_start_ms)
    except Exception:
        dt_ms = 0
    dt_ms = max(1, int(dt_ms))
    days = float(dt_ms) / float(86400 * 1000)
    return float(trades) / float(max(1e-9, days))


def _trade_monitor_suggestion_scope_pick_from_systems(by_system: Dict[str, Any]) -> str:
    if not isinstance(by_system, dict) or not by_system:
        return "O1"
    try:
        strat_t = int(((by_system.get("strategy") or {}) if isinstance(by_system.get("strategy"), dict) else {}).get("trades") or 0)
    except Exception:
        strat_t = 0
    try:
        quant_t = int(((by_system.get("quant") or {}) if isinstance(by_system.get("quant"), dict) else {}).get("trades") or 0)
    except Exception:
        quant_t = 0
    if int(quant_t) > int(strat_t):
        return "O2"
    return "O1"


def _trade_monitor_actions_default(
    *,
    trace_id: str,
    scope: str,
    direction: str,
    objective_profile: str,
    window_start_ms: int,
    window_end_ms: int,
    severity: str,
    tighten_only: bool,
) -> List[Dict[str, Any]]:
    s = str(scope or "").strip().upper()
    preset = None
    if s in ("O1", "O2", "O3", "O4", "O5", "O6", "O7"):
        preset = s.lower()
    ctx = {
        "severity": str(severity or "p2"),
        "source": "trade_monitor",
        "scope": s,
        "direction": str(direction),
        "objective_profile": str(objective_profile),
        "window": {"start_ms": int(window_start_ms), "end_ms": int(window_end_ms)},
    }
    include_modes = ["auto", "auto-tighten-only", "suggest-only"]
    if bool(tighten_only):
        include_modes = ["auto-tighten-only", "suggest-only"]
    actions: List[Dict[str, Any]] = []
    if preset:
        actions.append({
            "type": "agent.paramopt",
            "endpoint": "POST /agent/paramopt/run",
            "payload": {
                "trace_id": str(trace_id),
                "mode": "suggest",
                "preset": str(preset),
                "eval_mode": "rolling",
                "folds": 3,
                "n_init": 2,
                "n_iter": 3,
                "include_modes": include_modes,
                "include_suggest_only": True,
                "skip_robustness": True,
                "context": ctx,
            },
        })
    actions.append({
        "type": "http.batch",
        "endpoint": "GET /orders/recent",
        "requests": [{"url": f"/orders/recent?start_ts={int(window_start_ms)}&end_ts={int(window_end_ms)}&limit=2000"}],
    })
    actions.append({
        "type": "http.batch",
        "endpoint": "GET /signals/reject_stats",
        "requests": [{"url": f"/signals/reject_stats?lookback=2000"}],
    })
    return actions


def _trade_monitor_suggestions_from_rules(
    *,
    trace_id: str,
    kind: str,
    window_start_ms: int,
    window_end_ms: int,
    trigger_rules: List[Dict[str, Any]],
    upgrade_rules_hit: List[Dict[str, Any]],
    metrics_summary: Optional[Dict[str, Any]],
    baseline: Optional[Dict[str, Any]],
    delta_metrics: Optional[Dict[str, Any]],
    reject_stats: Dict[str, Any],
    exec_snapshot: Optional[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    rules = [r for r in (trigger_rules or []) if isinstance(r, dict) and bool(r.get("matched"))]
    if not rules:
        return []
    doc_refs = _agent_doc_refs_trade_monitor_default()
    input_evidence = _trade_monitor_interface_evidence_default(window_start_ms=int(window_start_ms), window_end_ms=int(window_end_ms))
    base_validation_plan = [
        "核对 metrics_summary/baseline/delta_metrics 字段口径一致性",
        "用 /agent/trace/replay 复盘该 trace_id 的证据链与去重键",
        "按 actions 在沙箱跑一次 paramopt(suggest)，再决定是否生成变更包草案",
    ]
    out: List[Dict[str, Any]] = []
    hit_ids = {str(h.get("rule_id") or "") for h in (upgrade_rules_hit or []) if isinstance(h, dict)}
    for r in rules:
        rid = str(r.get("rule_id") or "").strip()
        if not rid:
            continue
        if rid == "TM-541-PERF_DEGRADE":
            out.append({
                "phenomenon_id": "A1_PERF_DEGRADE",
                "hypothesis": "与基线相比绩效显著劣化，可能需要重配入场质量或门控权重",
                "evidence": {"rule_id": rid, "details": r.get("details"), "baseline": baseline, "metrics_summary": metrics_summary, "delta_metrics": delta_metrics},
                "change": "优先走 O1/O2 的入场与门控优化，必要时叠加 O3（宏观软调控）",
                "delta_metrics": delta_metrics,
                "validation_plan": list(base_validation_plan),
                "doc_refs": doc_refs,
                "interface_evidence": input_evidence,
                "risk": "若方向为 loosen 可能放大回撤与尾部风险",
                "rollback": "仅生成可审计建议与沙箱产物；落地需变更包+审批+可回滚点",
            })
        elif rid == "TM-541-RISK_DEGRADE":
            out.append({
                "phenomenon_id": "A2_DD_RISE",
                "hypothesis": "回撤/风险指标相对基线恶化，需要优先收敛尾部风险",
                "evidence": {"rule_id": rid, "details": r.get("details"), "baseline": baseline, "metrics_summary": metrics_summary, "delta_metrics": delta_metrics},
                "change": "优先走 O4/O5 的出场收敛，叠加 O3/O6 做风险折扣与护栏收紧",
                "delta_metrics": delta_metrics,
                "validation_plan": list(base_validation_plan),
                "doc_refs": doc_refs,
                "interface_evidence": input_evidence,
                "risk": "过度收紧可能降低收益与参与度",
                "rollback": "仅生成可审计建议与沙箱产物；落地需变更包+审批+可回滚点",
            })
        elif rid == "TM-541-REJECT_ANOMALY":
            out.append({
                "phenomenon_id": "B2_REJECT_ANOMALY",
                "hypothesis": "拒绝异常导致参与度下降，需要定位门禁与拒绝原因结构",
                "evidence": {"rule_id": rid, "details": r.get("details"), "reject_stats": reject_stats},
                "change": "先 O3（宏观/门控）定位常关原因，再决定是否触发 O1/O2 的入场阈值重设",
                "delta_metrics": delta_metrics,
                "validation_plan": list(base_validation_plan),
                "doc_refs": doc_refs,
                "interface_evidence": input_evidence,
                "risk": "直接放宽门禁可能提升回撤与尾部风险",
                "rollback": "保留阈值快照，变更需可一键回退",
            })
        elif rid == "TM-541-EXEC_ANOMALY":
            out.append({
                "phenomenon_id": "E3_EXEC_ANOMALY",
                "hypothesis": "执行异常（订单失败率/重试率上升）优先于信号优化处理",
                "evidence": {"rule_id": rid, "details": r.get("details"), "exec_snapshot": exec_snapshot},
                "change": "按 G1 执行安全门优先走 O6：限速/并发/最大持仓/下单节奏收紧",
                "delta_metrics": delta_metrics,
                "validation_plan": list(base_validation_plan),
                "doc_refs": doc_refs,
                "interface_evidence": input_evidence,
                "risk": "收紧会降低参与度与短期收益",
                "rollback": "tighten-only 在白名单内可受控发布；仍必须具备回滚点",
            })
        elif rid == "TM-541-MACRO_MISMATCH":
            out.append({
                "phenomenon_id": "D1_MACRO_MISMATCH",
                "hypothesis": "宏观置信度偏低但暴露上升，可能需要更敏感的风险状态折扣",
                "evidence": {"rule_id": rid, "details": r.get("details")},
                "change": "走 O3（Macro Overlay）做状态识别与阈值重配，必要时叠加 O6 降暴露",
                "delta_metrics": delta_metrics,
                "validation_plan": list(base_validation_plan),
                "doc_refs": doc_refs,
                "interface_evidence": input_evidence,
                "risk": "过度风控会导致长期不开仓",
                "rollback": "保留阈值快照，变更需可一键回退",
            })
        elif rid == "TM-541-REPORT_BUDGET" and (rid in hit_ids):
            out.append({
                "phenomenon_id": "SYS_REPORT_BUDGET",
                "hypothesis": "报告风暴防护命中，需减少重复触发并保持可回放",
                "evidence": {"rule_id": rid, "details": r.get("details")},
                "change": "检查去重键与扫描周期配置，避免短周期重复触发造成预算耗尽",
                "delta_metrics": None,
                "validation_plan": list(base_validation_plan),
                "doc_refs": doc_refs,
                "interface_evidence": input_evidence,
                "risk": "过度限速可能降低监控灵敏度",
                "rollback": "限速参数可回退到上一个门禁通过版本",
            })
    return out


def _trade_monitor_significant_rule_ids(upgrade_hits: Optional[List[Dict[str, Any]]]) -> List[str]:
    allow = {
        "TM-541-PERF_DEGRADE",
        "TM-541-RISK_DEGRADE",
        "TM-541-REJECT_ANOMALY",
        "TM-541-EXEC_ANOMALY",
        "TM-541-MACRO_MISMATCH",
    }
    out: List[str] = []
    seen: set = set()
    for h in (upgrade_hits or []):
        if not isinstance(h, dict):
            continue
        rid = str(h.get("rule_id") or "").strip()
        if not rid:
            continue
        if rid not in allow:
            continue
        if rid in seen:
            continue
        seen.add(rid)
        out.append(rid)
    return out


def _trade_monitor_suggestions_route(
    suggestions: List[Dict[str, Any]],
    *,
    trace_id: str,
    kind: str,
    window_start_ms: int,
    window_end_ms: int,
    reject_stats: Dict[str, Any],
    by_system: Dict[str, Any],
    top_pairs: List[Dict[str, Any]],
    metrics_summary: Optional[Dict[str, Any]],
    baseline: Optional[Dict[str, Any]],
    delta_metrics: Optional[Dict[str, Any]],
    exec_snapshot: Optional[Dict[str, Any]],
    upgrade_hits: Optional[List[Dict[str, Any]]] = None,
) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    used: set = set()

    try:
        sample_count = int((metrics_summary or {}).get("count") or 0) if isinstance(metrics_summary, dict) else 0
    except Exception:
        sample_count = 0
    try:
        order_fail_rate = (None if metrics_summary is None else (metrics_summary or {}).get("order_fail_rate"))
    except Exception:
        order_fail_rate = None
    try:
        reject_rate = float((metrics_summary or {}).get("reject_rate") or 0.0) if isinstance(metrics_summary, dict) and (metrics_summary or {}).get("reject_rate") is not None else float((reject_stats or {}).get("reject_rate") or 0.0)
    except Exception:
        reject_rate = float((reject_stats or {}).get("reject_rate") or 0.0)

    exec_safety = False
    try:
        if order_fail_rate is not None and float(order_fail_rate) >= float(CONFIG.get("trade_monitor_upgrade_order_fail_abs", 0.05) or 0.05):
            exec_safety = True
    except Exception:
        pass
    try:
        if isinstance(exec_snapshot, dict) and exec_snapshot.get("order_fail_rate") is not None:
            if float(exec_snapshot.get("order_fail_rate")) >= float(CONFIG.get("trade_monitor_upgrade_order_fail_abs", 0.05) or 0.05):
                exec_safety = True
    except Exception:
        pass
    tighten_only = bool(exec_safety)
    if not tighten_only:
        tighten_only = bool(sample_count > 0 and int(sample_count) < 30)

    baseline_missing = not (isinstance(baseline, dict) and bool(baseline))
    if baseline_missing:
        tighten_only = True
    g3_rule_ids = _trade_monitor_significant_rule_ids(upgrade_hits)
    g3_significant = bool(g3_rule_ids)

    cur_mode = None
    try:
        cur_mode = str(_quant_btcalts_strategy_mode_default() or "").strip() or None
    except Exception:
        cur_mode = None
    optimization_lock_key = f"tm:{str(kind or '').strip() or 'unknown'}:{int(window_start_ms)}-{int(window_end_ms)}:qm:{cur_mode or 'na'}"

    g3_required_phenomenon_ids = {
        "A1_PERF_DEGRADE",
        "A1_WINRATE_LOW",
        "A2_DD_RISE",
        "A2_RECENT_PNL_NEGATIVE",
        "B2_REJECT_HIGH",
        "B2_REJECT_ANOMALY",
        "D1_MACRO_MISMATCH",
        "F2_QUANT_PNL_NEGATIVE",
    }
    always_allow_phenomenon_ids = {
        "DATA_NO_CLOSE_ORDERS",
        "E3_EXEC_ANOMALY",
        "SYS_REPORT_BUDGET",
    }

    for s in (suggestions or []):
        if not isinstance(s, dict):
            continue
        phen = str(s.get("phenomenon_id") or "").strip() or "unknown"
        if phen in used:
            continue
        used.add(phen)
        if (not tighten_only) and (not g3_significant) and (phen in g3_required_phenomenon_ids) and (phen not in always_allow_phenomenon_ids):
            continue
        sug = dict(s)
        if sug.get("hypothesis") is None:
            sug["hypothesis"] = ""
        if sug.get("change") is None:
            sug["change"] = ""
        if sug.get("delta_metrics") is None:
            sug["delta_metrics"] = delta_metrics
        if sug.get("validation_plan") is None:
            sug["validation_plan"] = []
        if sug.get("risk") is None:
            sug["risk"] = ""
        if sug.get("rollback") is None:
            sug["rollback"] = ""
        if sug.get("optimization_lock_key") is None:
            sug["optimization_lock_key"] = optimization_lock_key
        try:
            ev = sug.get("evidence") if isinstance(sug.get("evidence"), dict) else {}
            if isinstance(ev, dict):
                if ev.get("optimization_lock_key") is None:
                    ev["optimization_lock_key"] = optimization_lock_key
                if ev.get("gates") is None:
                    ev["gates"] = {
                        "G1_exec_safety": bool(exec_safety),
                        "G2_small_sample": bool(sample_count > 0 and int(sample_count) < 30),
                        "G3_significant_deviation": bool(g3_significant),
                        "G3_rules": g3_rule_ids[:10],
                        "baseline_missing": bool(baseline_missing),
                        "tighten_only": bool(tighten_only),
                        "sample_count": int(sample_count),
                        "order_fail_rate": (None if order_fail_rate is None else float(order_fail_rate)),
                        "reject_rate": (None if reject_rate is None else float(reject_rate)),
                    }
                sug["evidence"] = ev
        except Exception:
            pass

        scope = None
        direction = None
        objective_profile = None
        severity = "p2"

        if phen in ("A1_PERF_DEGRADE", "A1_WINRATE_LOW"):
            scope = _trade_monitor_suggestion_scope_pick_from_systems(by_system)
            direction = "rebalance"
            objective_profile = "return_repair"
            severity = "p2"
            if tighten_only:
                scope = "O6"
                direction = "tighten"
                objective_profile = "tail_defense"
                severity = "p1"
        elif phen in ("A2_DD_RISE", "A2_RECENT_PNL_NEGATIVE"):
            scope = "O4"
            direction = "tighten"
            objective_profile = "tail_defense"
            severity = "p1"
        elif phen in ("B2_REJECT_HIGH", "B2_REJECT_ANOMALY"):
            scope = "O3"
            direction = "rebalance"
            objective_profile = "return_repair"
            severity = ("p1" if float(reject_rate) >= 0.30 else "p2")
            if tighten_only:
                scope = "O6"
                direction = "tighten"
                objective_profile = "tail_defense"
        elif phen == "E3_EXEC_ANOMALY":
            scope = "O6"
            direction = "tighten"
            objective_profile = "cost_sensitive"
            severity = "p1"
            tighten_only = True
        elif phen == "D1_MACRO_MISMATCH":
            scope = "O3"
            direction = "segment"
            objective_profile = "tail_defense"
            severity = "p1"
            if tighten_only:
                scope = "O6"
                direction = "tighten"
                objective_profile = "tail_defense"
        elif phen == "F2_QUANT_PNL_NEGATIVE":
            scope = "O2"
            direction = "rebalance"
            objective_profile = "generalization_stable"
            severity = "p2"
            if tighten_only:
                scope = "O6"
                direction = "tighten"
                objective_profile = "tail_defense"
        elif phen == "SYS_REPORT_BUDGET":
            scope = "O6"
            direction = "tighten"
            objective_profile = "cost_sensitive"
            severity = "p2"
        elif phen == "DATA_NO_CLOSE_ORDERS":
            scope = "O6"
            direction = "tighten"
            objective_profile = "tail_defense"
            severity = "p2"
        else:
            scope = "O6"
            direction = "tighten"
            objective_profile = "tail_defense"

        sug["scope"] = str(scope)
        sug["direction"] = str(direction)
        sug["objective_profile"] = str(objective_profile)

        actions = sug.get("actions") if isinstance(sug.get("actions"), list) else None
        if not actions:
            sug["actions"] = _trade_monitor_actions_default(
                trace_id=str(trace_id),
                scope=str(scope),
                direction=str(direction),
                objective_profile=str(objective_profile),
                window_start_ms=int(window_start_ms),
                window_end_ms=int(window_end_ms),
                severity=str(severity),
                tighten_only=bool(tighten_only),
            )
        else:
            try:
                acts0 = [a for a in actions if isinstance(a, dict)]
                has_paramopt = any(str(a.get("type") or "").strip() == "agent.paramopt" for a in acts0)
                if not has_paramopt and str(scope or "").strip().upper() in ("O1", "O2", "O3", "O4", "O5", "O6", "O7"):
                    base_acts = _trade_monitor_actions_default(
                        trace_id=str(trace_id),
                        scope=str(scope),
                        direction=str(direction),
                        objective_profile=str(objective_profile),
                        window_start_ms=int(window_start_ms),
                        window_end_ms=int(window_end_ms),
                        severity=str(severity),
                        tighten_only=bool(tighten_only),
                    )
                    paramopt_act = None
                    for a in base_acts:
                        if isinstance(a, dict) and str(a.get("type") or "").strip() == "agent.paramopt":
                            paramopt_act = a
                            break
                    if isinstance(paramopt_act, dict):
                        sug["actions"] = [paramopt_act] + acts0
                else:
                    first_idx = None
                    for i, a in enumerate(acts0):
                        if str(a.get("type") or "").strip() == "agent.paramopt":
                            first_idx = int(i)
                            break
                    if first_idx is not None and first_idx > 0:
                        p = acts0.pop(first_idx)
                        sug["actions"] = [p] + acts0
            except Exception:
                pass
        try:
            acts = sug.get("actions") if isinstance(sug.get("actions"), list) else []
            for a in acts:
                if not isinstance(a, dict):
                    continue
                if str(a.get("type") or "").strip() != "agent.paramopt":
                    continue
                payload = a.get("payload") if isinstance(a.get("payload"), dict) else None
                if not isinstance(payload, dict):
                    continue
                ctx = payload.get("context") if isinstance(payload.get("context"), dict) else None
                if not isinstance(ctx, dict):
                    continue
                if ctx.get("optimization_lock_key") is None:
                    ctx["optimization_lock_key"] = optimization_lock_key
                if ctx.get("phenomenon_id") is None:
                    ctx["phenomenon_id"] = phen
                payload["context"] = ctx
                a["payload"] = payload
        except Exception:
            pass
        try:
            sug = _trade_monitor_suggestion_attach_faq_fields(
                sug,
                trace_id=str(trace_id),
                window_start_ms=int(window_start_ms),
                window_end_ms=int(window_end_ms),
                tighten_only=bool(tighten_only),
            )
        except Exception:
            pass
        out.append(sug)
    return out


def _trade_monitor_metrics_from_trades(trades: List[Dict[str, Any]]) -> Dict[str, Any]:
    xs = [t for t in (trades or []) if isinstance(t, dict)]
    rets: List[float] = []
    pnl: List[Dict[str, Any]] = []
    cum = 0.0
    wins = 0
    sum_pos = 0.0
    sum_neg = 0.0
    for t in xs:
        r = 0.0
        try:
            r = float(t.get("ret_ratio") if t.get("ret_ratio") is not None else 0.0)
        except Exception:
            r = 0.0
        if not math.isfinite(float(r)):
            r = 0.0
        if float(r) != 0.0:
            rets.append(float(r))
        cum += float(r)
        pnl.append({"date": (t.get("ts") or None), "pnl": float(r), "cum_pnl": float(cum)})
        if float(r) > 0.0:
            wins += 1
            sum_pos += float(r)
        elif float(r) < 0.0:
            sum_neg += float(r)

    n = int(len(xs))
    winrate = float(wins) / float(n) if n > 0 else None
    sharpe = 0.0
    if len(rets) >= 2:
        try:
            mu = float(sum(rets) / float(len(rets)))
            var = float(sum((x - mu) ** 2 for x in rets) / float(max(1, len(rets) - 1)))
            sd = float(math.sqrt(var)) if var > 1e-12 else 0.0
            sharpe = float((mu / (sd + 1e-12)) * math.sqrt(252.0)) if sd > 0 else 0.0
        except Exception:
            sharpe = 0.0

    profit_factor = None
    if n > 0:
        if float(sum_neg) < 0.0:
            profit_factor = float(sum_pos) / abs(float(sum_neg))
        elif float(sum_pos) > 0.0:
            profit_factor = float("inf")
        else:
            profit_factor = 0.0

    try:
        maxdd = float(_max_drawdown_from_pnl(pnl))
    except Exception:
        maxdd = 0.0

    return {
        "count": int(n),
        "winrate": (None if winrate is None else float(winrate)),
        "mean_return": (float(cum) / float(n) if n > 0 else 0.0),
        "cum_return": float(cum),
        "sharpe": float(sharpe),
        "profit_factor": (None if profit_factor is None else float(profit_factor)),
        "max_drawdown_pct": float(maxdd),
        "pnl": pnl,
    }


def _trade_monitor_delta_metrics(cur: Dict[str, Any], base: Dict[str, Any]) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    for k in ("net_sharpe_oos", "sharpe", "profit_factor", "max_drawdown_pct", "daily_dd_pct", "reject_rate", "order_fail_rate"):
        if base.get(k) is None or cur.get(k) is None:
            continue
        try:
            b = float(base.get(k))
            c = float(cur.get(k))
        except Exception:
            continue
        if not math.isfinite(float(b)) or not math.isfinite(float(c)):
            continue
        out[k] = {"base": float(b), "cur": float(c), "abs": float(c - b)}
        if k in ("net_sharpe_oos", "sharpe", "profit_factor"):
            denom = max(1e-12, abs(float(b)))
            out[k]["rel"] = float((float(c) - float(b)) / float(denom))
        elif k in ("max_drawdown_pct", "daily_dd_pct", "reject_rate", "order_fail_rate"):
            denom = max(1e-12, float(b))
            out[k]["rel"] = float((float(c) - float(b)) / float(denom))
    return out


def _trade_monitor_rules_eval(
    *,
    now_ms: int,
    today: str,
    last_full_ts_ms: int,
    new_close_trades: int,
    light_threshold: int,
    full_threshold: int,
    full_age_ok: bool,
    full_due: bool,
    baseline_ref: Optional[str],
    baseline_metrics: Optional[Dict[str, Any]],
    current_metrics: Optional[Dict[str, Any]],
    reject_stats: Dict[str, Any],
    exec_snapshot: Optional[Dict[str, Any]],
    high_alerts: List[Dict[str, Any]],
    budget_used: int,
    budget_limit: int,
) -> Dict[str, Any]:
    rules: List[Dict[str, Any]] = []
    upgrade_hits: List[Dict[str, Any]] = []
    skip_reasons: List[str] = []
    has_p1 = False

    try:
        throttle_enabled = bool(CONFIG.get("trade_monitor_throttle_skip_full_if_stable_24h", CONFIG.get("throttle.skip_full_if_stable_24h", True)))
    except Exception:
        throttle_enabled = True

    stable_24h = False
    delta_metrics = None
    if isinstance(current_metrics, dict) and isinstance(baseline_metrics, dict):
        delta_metrics = _trade_monitor_delta_metrics(current_metrics, baseline_metrics)

    try:
        stable_dd_thr = float(CONFIG.get("trade_monitor_stable_daily_dd_pct", 0.01) or 0.01)
    except Exception:
        stable_dd_thr = 0.01
    try:
        stable_reject_rel_thr = float(CONFIG.get("trade_monitor_stable_reject_rel", 0.15) or 0.15)
    except Exception:
        stable_reject_rel_thr = 0.15
    try:
        stable_fail_abs_thr = float(CONFIG.get("trade_monitor_stable_order_fail_abs", 0.02) or 0.02)
    except Exception:
        stable_fail_abs_thr = 0.02

    rej_rel = None
    if isinstance(delta_metrics, dict) and isinstance(delta_metrics.get("reject_rate"), dict):
        try:
            rej_rel = float(delta_metrics.get("reject_rate").get("rel"))
        except Exception:
            rej_rel = None
    fail_abs = None
    if isinstance(delta_metrics, dict) and isinstance(delta_metrics.get("order_fail_rate"), dict):
        try:
            fail_abs = float(delta_metrics.get("order_fail_rate").get("abs"))
        except Exception:
            fail_abs = None
    dd_c = None
    if isinstance(current_metrics, dict):
        try:
            dd_c = float(current_metrics.get("daily_dd_pct") if current_metrics.get("daily_dd_pct") is not None else current_metrics.get("max_drawdown_pct"))
        except Exception:
            dd_c = None

    stable_24h = bool(
        throttle_enabled
        and str(baseline_ref or "") == "prev_full"
        and (not bool(high_alerts))
        and dd_c is not None
        and float(dd_c) < float(stable_dd_thr)
        and rej_rel is not None
        and float(rej_rel) <= float(stable_reject_rel_thr)
        and fail_abs is not None
        and abs(float(fail_abs)) <= float(stable_fail_abs_thr)
    )
    rules.append({
        "rule_id": "TM-541-HEALTH_BASELINE",
        "group": "健康基线",
        "level": "skip_full",
        "matched": bool(stable_24h),
        "config_keys": ["throttle.skip_full_if_stable_24h", "trade_monitor_throttle_skip_full_if_stable_24h"],
        "audit_fields": {"stable_24h": bool(stable_24h), "skip_reason": None},
        "details": {
            "baseline_ref": baseline_ref,
            "daily_dd_thr": float(stable_dd_thr),
            "reject_rel_thr": float(stable_reject_rel_thr),
            "order_fail_abs_thr": float(stable_fail_abs_thr),
            "delta_metrics": delta_metrics,
        },
    })

    rules.append({
        "rule_id": "TM-541-TRADE_COUNT_LIGHT",
        "group": "交易计数",
        "level": "light",
        "matched": bool(int(new_close_trades) >= int(light_threshold)),
        "config_keys": ["trigger.light.trades", "trade_monitor_light_trades"],
        "audit_fields": {"cursor.completed_trades_delta": int(new_close_trades)},
        "details": {"threshold": int(light_threshold)},
    })

    rules.append({
        "rule_id": "TM-541-TRADE_COUNT_FULL",
        "group": "交易计数",
        "level": "full",
        "matched": bool(int(new_close_trades) >= int(full_threshold) and bool(full_age_ok) and (not bool(full_due))),
        "config_keys": ["trigger.full.trades", "trigger.full.min_age_h", "trade_monitor_full_trades", "trade_monitor_full_min_age_hours"],
        "audit_fields": {"cursor.completed_trades_delta": int(new_close_trades), "last_full_ts": int(last_full_ts_ms)},
        "details": {"threshold": int(full_threshold), "min_age_ok": bool(full_age_ok), "full_due": bool(full_due)},
    })

    try:
        sharpe_decay_thr = float(CONFIG.get("trade_monitor_upgrade_sharpe_decay", CONFIG.get("upgrade.sharpe_decay", 0.20)) or 0.20)
    except Exception:
        sharpe_decay_thr = 0.20
    try:
        pf_drop_thr = float(CONFIG.get("trade_monitor_upgrade_pf_drop", CONFIG.get("upgrade.pf_drop", 0.15)) or 0.15)
    except Exception:
        pf_drop_thr = 0.15
    perf_hit = False
    perf_details: Dict[str, Any] = {"baseline_ref": baseline_ref, "delta_metrics": delta_metrics}
    if isinstance(delta_metrics, dict):
        s_key = "net_sharpe_oos" if "net_sharpe_oos" in delta_metrics else "sharpe"
        try:
            s_rel = float(((delta_metrics.get(s_key) or {}) or {}).get("rel"))
        except Exception:
            s_rel = None
        if s_rel is not None and float(s_rel) <= -abs(float(sharpe_decay_thr)):
            perf_hit = True
            perf_details["net_sharpe_oos_rel"] = float(s_rel)
            perf_details["threshold"] = float(sharpe_decay_thr)
        try:
            pf_rel = float(((delta_metrics.get("profit_factor") or {}) or {}).get("rel"))
        except Exception:
            pf_rel = None
        if pf_rel is not None and float(pf_rel) <= -abs(float(pf_drop_thr)):
            perf_hit = True
            perf_details["profit_factor_rel"] = float(pf_rel)
            perf_details["threshold_pf"] = float(pf_drop_thr)
    rules.append({
        "rule_id": "TM-541-PERF_DEGRADE",
        "group": "绩效劣化",
        "level": "upgrade_full",
        "matched": bool(perf_hit),
        "config_keys": ["upgrade.sharpe_decay", "upgrade.pf_drop", "trade_monitor_upgrade_sharpe_decay", "trade_monitor_upgrade_pf_drop"],
        "audit_fields": {"baseline_ref": baseline_ref, "delta_metrics": delta_metrics},
        "details": perf_details,
    })
    if perf_hit:
        upgrade_hits.append({"rule_id": "TM-541-PERF_DEGRADE", "severity": "warn", "baseline_ref": baseline_ref, "delta_metrics": delta_metrics, "details": perf_details})

    try:
        dd_rel_thr = float(CONFIG.get("trade_monitor_upgrade_dd_rel", CONFIG.get("upgrade.dd_rel", 0.10)) or 0.10)
    except Exception:
        dd_rel_thr = 0.10
    try:
        p1_dd_abs = float(CONFIG.get("trade_monitor_upgrade_daily_dd_abs", CONFIG.get("p1.daily_dd", 0.02)) or 0.02)
    except Exception:
        p1_dd_abs = 0.02
    risk_hit = False
    risk_details: Dict[str, Any] = {"baseline_ref": baseline_ref, "delta_metrics": delta_metrics}
    if isinstance(current_metrics, dict):
        try:
            dd_abs0 = float(current_metrics.get("daily_dd_pct") if current_metrics.get("daily_dd_pct") is not None else current_metrics.get("max_drawdown_pct") or 0.0)
        except Exception:
            dd_abs0 = 0.0
        if float(dd_abs0) >= float(p1_dd_abs):
            risk_hit = True
            risk_details["daily_dd_pct"] = float(dd_abs0)
            risk_details["threshold_abs"] = float(p1_dd_abs)
    if isinstance(delta_metrics, dict) and isinstance(delta_metrics.get("max_drawdown_pct"), dict):
        try:
            dd_rel0 = float(delta_metrics.get("max_drawdown_pct").get("rel"))
        except Exception:
            dd_rel0 = None
        if dd_rel0 is not None and float(dd_rel0) >= float(dd_rel_thr):
            risk_hit = True
            risk_details["max_drawdown_rel"] = float(dd_rel0)
            risk_details["threshold_rel"] = float(dd_rel_thr)
    rules.append({
        "rule_id": "TM-541-RISK_DEGRADE",
        "group": "风险劣化",
        "level": "upgrade_full",
        "matched": bool(risk_hit),
        "config_keys": ["upgrade.dd_rel", "p1.daily_dd", "trade_monitor_upgrade_dd_rel", "trade_monitor_upgrade_daily_dd_abs"],
        "audit_fields": {"severity": ("P1" if risk_hit else None), "risk_snapshot": {"daily_dd_pct": (None if current_metrics is None else current_metrics.get("daily_dd_pct")), "max_drawdown_pct": (None if current_metrics is None else current_metrics.get("max_drawdown_pct"))}},
        "details": risk_details,
    })
    if risk_hit:
        has_p1 = True
        upgrade_hits.append({"rule_id": "TM-541-RISK_DEGRADE", "severity": "P1", "baseline_ref": baseline_ref, "delta_metrics": delta_metrics, "risk_snapshot": {"daily_dd_pct": (None if current_metrics is None else current_metrics.get("daily_dd_pct")), "max_drawdown_pct": (None if current_metrics is None else current_metrics.get("max_drawdown_pct"))}, "details": risk_details})

    try:
        reject_abs_thr = float(CONFIG.get("trade_monitor_upgrade_reject_abs", CONFIG.get("upgrade.reject_abs", 0.30)) or 0.30)
    except Exception:
        reject_abs_thr = 0.30
    try:
        reject_rel_thr = float(CONFIG.get("trade_monitor_upgrade_reject_rel", CONFIG.get("upgrade.reject_rel", 0.15)) or 0.15)
    except Exception:
        reject_rel_thr = 0.15
    reject_hit = False
    rr_abs = None
    rr_rel = None
    if isinstance(current_metrics, dict):
        try:
            rr_abs = float(current_metrics.get("reject_rate") or 0.0)
        except Exception:
            rr_abs = None
    if rr_abs is None and isinstance(reject_stats, dict) and reject_stats.get("reject_rate") is not None:
        try:
            rr_abs = float(reject_stats.get("reject_rate") or 0.0)
        except Exception:
            rr_abs = None
    if isinstance(delta_metrics, dict) and isinstance(delta_metrics.get("reject_rate"), dict):
        try:
            rr_rel = float(delta_metrics.get("reject_rate").get("rel"))
        except Exception:
            rr_rel = None
    if rr_abs is not None and float(rr_abs) >= float(reject_abs_thr):
        reject_hit = True
    if rr_rel is not None and float(rr_rel) >= float(reject_rel_thr):
        reject_hit = True
    faq_refs = ["技术文档.md:0.3"] if reject_hit else []
    reject_breakdown = (reject_stats or {}).get("by_reason") if isinstance((reject_stats or {}).get("by_reason"), dict) else None
    rules.append({
        "rule_id": "TM-541-REJECT_ANOMALY",
        "group": "拒绝异常",
        "level": "upgrade_full",
        "matched": bool(reject_hit),
        "config_keys": ["upgrade.reject_abs", "upgrade.reject_rel", "trade_monitor_upgrade_reject_abs", "trade_monitor_upgrade_reject_rel"],
        "audit_fields": {"reject_breakdown": reject_breakdown, "faq_refs": faq_refs},
        "details": {"reject_rate": rr_abs, "reject_rate_rel": rr_rel, "threshold_abs": float(reject_abs_thr), "threshold_rel": float(reject_rel_thr), "baseline_ref": baseline_ref, "delta_metrics": delta_metrics},
    })
    if reject_hit:
        has_p1 = True
        upgrade_hits.append({"rule_id": "TM-541-REJECT_ANOMALY", "severity": "P1", "reject_breakdown": reject_breakdown, "faq_refs": faq_refs, "baseline_ref": baseline_ref, "delta_metrics": delta_metrics})

    try:
        fail_abs_thr = float(CONFIG.get("trade_monitor_upgrade_order_fail_abs", CONFIG.get("upgrade.order_fail_abs", 0.05)) or 0.05)
    except Exception:
        fail_abs_thr = 0.05
    try:
        fail_rel_thr = float(CONFIG.get("trade_monitor_upgrade_order_fail_rel", CONFIG.get("upgrade.order_fail_rel", 0.02)) or 0.02)
    except Exception:
        fail_rel_thr = 0.02
    exec_hit = False
    of_abs = None
    of_rel = None
    if isinstance(current_metrics, dict) and current_metrics.get("order_fail_rate") is not None:
        try:
            of_abs = float(current_metrics.get("order_fail_rate"))
        except Exception:
            of_abs = None
    if isinstance(delta_metrics, dict) and isinstance(delta_metrics.get("order_fail_rate"), dict):
        try:
            of_rel = float(delta_metrics.get("order_fail_rate").get("rel"))
        except Exception:
            of_rel = None
    if of_abs is not None and float(of_abs) >= float(fail_abs_thr):
        exec_hit = True
    if of_rel is not None and float(of_rel) >= float(fail_rel_thr):
        exec_hit = True
    audit_refs = (["/audit/execution-quality", "/audit/alerts/evaluate"] if exec_hit else [])
    rules.append({
        "rule_id": "TM-541-EXEC_ANOMALY",
        "group": "执行异常",
        "level": "upgrade_full",
        "matched": bool(exec_hit),
        "config_keys": ["upgrade.order_fail_abs", "upgrade.order_fail_rel", "trade_monitor_upgrade_order_fail_abs", "trade_monitor_upgrade_order_fail_rel"],
        "audit_fields": {"exec_snapshot": exec_snapshot, "audit_refs": audit_refs},
        "details": {"order_fail_rate": of_abs, "order_fail_rate_rel": of_rel, "threshold_abs": float(fail_abs_thr), "threshold_rel": float(fail_rel_thr), "baseline_ref": baseline_ref, "delta_metrics": delta_metrics},
    })
    if exec_hit:
        has_p1 = True
        upgrade_hits.append({"rule_id": "TM-541-EXEC_ANOMALY", "severity": "P1", "exec_snapshot": exec_snapshot, "audit_refs": audit_refs, "baseline_ref": baseline_ref, "delta_metrics": delta_metrics})

    try:
        macro_enabled = bool(CONFIG.get("trade_monitor_upgrade_macro_conf_low_enabled", CONFIG.get("upgrade.macro_conf_low", False)))
    except Exception:
        macro_enabled = False
    macro_hit = False
    macro_snapshot = None
    exposure_snapshot = None
    if macro_enabled:
        try:
            macro_snapshot = _macro_snapshot_btceth(int(now_ms))
        except Exception:
            macro_snapshot = None
        try:
            conf_long = _macro_confidence_for_signal("long", macro_snapshot or {})
        except Exception:
            conf_long = {}
        try:
            conf_short = _macro_confidence_for_signal("short", macro_snapshot or {})
        except Exception:
            conf_short = {}
        lvl0 = str((conf_long or {}).get("confidence_level") or "low").strip().lower() or "low"
        lvl1 = str((conf_short or {}).get("confidence_level") or "low").strip().lower() or "low"
        worst_low = ("low" in (lvl0, lvl1))
        try:
            op = TRACKER_STATE.get("open_positions") if isinstance(TRACKER_STATE.get("open_positions"), dict) else {}
            qp = TRACKER_STATE.get("quant_open_positions") if isinstance(TRACKER_STATE.get("quant_open_positions"), dict) else {}
            cp = TRACKER_STATE.get("carry_open_positions") if isinstance(TRACKER_STATE.get("carry_open_positions"), dict) else {}
            exposure_snapshot = {"open_positions": int(len(op)), "quant_open_positions": int(len(qp)), "carry_open_positions": int(len(cp)), "open_positions_total": int(len(op) + len(qp) + len(cp))}
        except Exception:
            exposure_snapshot = None
        base_open = None
        if isinstance(baseline_metrics, dict) and baseline_metrics.get("open_positions_total") is not None:
            try:
                base_open = int(baseline_metrics.get("open_positions_total"))
            except Exception:
                base_open = None
        cur_open = None
        if isinstance(exposure_snapshot, dict):
            try:
                cur_open = int(exposure_snapshot.get("open_positions_total"))
            except Exception:
                cur_open = None
        if worst_low and base_open is not None and cur_open is not None and int(cur_open) > int(base_open) + 1:
            macro_hit = True
    rules.append({
        "rule_id": "TM-541-MACRO_MISMATCH",
        "group": "宏观不一致",
        "level": "upgrade_full",
        "matched": bool(macro_hit),
        "config_keys": ["upgrade.macro_conf_low", "trade_monitor_upgrade_macro_conf_low_enabled"],
        "audit_fields": {"macro_snapshot": macro_snapshot, "exposure_snapshot": exposure_snapshot},
        "details": {"macro_conf_low": bool(macro_enabled), "baseline_ref": baseline_ref},
    })
    if macro_hit:
        has_p1 = True
        upgrade_hits.append({"rule_id": "TM-541-MACRO_MISMATCH", "severity": "P1", "macro_snapshot": macro_snapshot, "exposure_snapshot": exposure_snapshot, "baseline_ref": baseline_ref})

    if upgrade_hits:
        stable_24h = False
        try:
            rules[0]["matched"] = False
            rules[0]["audit_fields"]["stable_24h"] = False
            rules[0]["details"]["suppressed_by_upgrade_rules"] = [str(x.get("rule_id")) for x in upgrade_hits if isinstance(x, dict) and x.get("rule_id") is not None][:12]
        except Exception:
            pass

    budget_hit = bool(int(budget_limit) > 0 and int(budget_used) >= int(budget_limit))
    rules.append({
        "rule_id": "TM-541-REPORT_BUDGET",
        "group": "报告风暴防护",
        "level": "rate_limit",
        "matched": bool(budget_hit),
        "config_keys": ["budget.max_reports_per_day", "trade_monitor_budget_max_reports_per_day"],
        "audit_fields": {"budget.used": int(budget_used), "budget.limit": int(budget_limit)},
        "details": {"day": str(today)},
    })
    if budget_hit:
        skip_reasons.append("budget_rate_limited")

    return {
        "rules": rules,
        "upgrade_hits": upgrade_hits,
        "stable_24h": bool(stable_24h),
        "delta_metrics": delta_metrics,
        "has_p1": bool(has_p1),
        "skip_reasons": skip_reasons,
    }


def _trade_monitor_alerts_summary(rep: Any) -> Dict[str, Any]:
    if not isinstance(rep, dict):
        return {"ok": False, "alerts": [], "high": []}
    alerts = rep.get("alerts") if isinstance(rep.get("alerts"), list) else []
    high = [a for a in alerts if isinstance(a, dict) and str(a.get("severity") or "").strip().lower() in ("p0", "critical", "fatal", "high")]
    return {
        "ok": bool(rep.get("ok", True)),
        "alerts": alerts,
        "high": high,
        "summary": rep.get("summary") if isinstance(rep.get("summary"), dict) else None,
    }


def _trade_monitor_scan(now_ms: int, *, force_full: bool = False, lookback_days: Optional[int] = None) -> Dict[str, Any]:
    ts_ms = int(now_ms or _now_ms())
    try:
        enabled = bool(CONFIG.get("trade_monitor_enabled", True))
    except Exception:
        enabled = True
    if not enabled:
        return {"ok": False, "error": "disabled", "ts": int(ts_ms)}

    with _TRADE_MONITOR_LOCK:
        st = _trade_monitor_state_load()
        last_close_ts = int(st.get("last_close_ts_ms") or 0)
        seen_close_ids = st.get("seen_close_ids") if isinstance(st.get("seen_close_ids"), list) else []
        seen_close_set = {str(x).strip() for x in seen_close_ids if str(x).strip()}
        last_light_ts = int(st.get("last_light_ts_ms") or 0)
        last_full_ts = int(st.get("last_full_ts_ms") or 0)
        try:
            last_full_day = (None if st.get("last_full_day") is None else str(st.get("last_full_day")))
        except Exception:
            last_full_day = None

        today = datetime.fromtimestamp(int(ts_ms) / 1000.0, tz=timezone.utc).strftime("%Y-%m-%d")
        try:
            daily_full_enabled = bool(CONFIG.get("trade_monitor_daily_full_enabled", True))
        except Exception:
            daily_full_enabled = True
        try:
            daily_full_min_age_h = float(CONFIG.get("trade_monitor_daily_full_min_age_hours", CONFIG.get("trade_monitor_full_min_age_hours", 24)) or 24)
        except Exception:
            daily_full_min_age_h = 24.0
        daily_full_min_age_ms = int(max(0.0, min(7.0 * 24.0, float(daily_full_min_age_h))) * 3600.0 * 1000.0)
        daily_full_age_ok = (last_full_ts <= 0) or (daily_full_min_age_ms <= 0) or ((int(ts_ms) - int(last_full_ts)) >= int(daily_full_min_age_ms))
        full_due = bool(force_full) or (daily_full_enabled and (not last_full_day or str(last_full_day) != str(today)) and bool(daily_full_age_ok))

        try:
            light_trades_raw = CONFIG.get("trade_monitor_light_trades")
            if light_trades_raw is None:
                light_trades_raw = CONFIG.get("trigger.light.trades", 10)
            light_trades = int(light_trades_raw or 10)
        except Exception:
            light_trades = 10
        try:
            light_per_raw = CONFIG.get("trade_monitor_light_period_seconds")
            if light_per_raw is None:
                light_per_raw = CONFIG.get("trigger.light.period_seconds", 14400)
            light_per = int(light_per_raw or 14400)
        except Exception:
            light_per = 14400
        try:
            full_trades_raw = CONFIG.get("trade_monitor_full_trades")
            if full_trades_raw is None:
                full_trades_raw = CONFIG.get("trigger.full.trades", 30)
            full_trades = int(full_trades_raw or 30)
        except Exception:
            full_trades = 30
        try:
            full_min_age_h_raw = CONFIG.get("trade_monitor_full_min_age_hours")
            if full_min_age_h_raw is None:
                full_min_age_h_raw = CONFIG.get("trigger.full.min_age_h", 24)
            full_min_age_h = float(full_min_age_h_raw or 24)
        except Exception:
            full_min_age_h = 24.0
        light_trades = max(1, min(1000, int(light_trades)))
        light_per = max(60, min(7 * 86400, int(light_per)))
        full_trades = max(light_trades, min(5000, int(full_trades)))
        full_min_age_ms = int(max(0.0, min(7.0 * 24.0, float(full_min_age_h))) * 3600.0 * 1000.0)

        close_orders_all: List[Dict[str, Any]] = []
        orders_archive_files: List[str] = []
        try:
            try:
                max_days = int(CONFIG.get("trade_monitor_orders_archive_max_days", 180) or 180)
            except Exception:
                max_days = 180
            max_days = max(1, min(3650, int(max_days)))
            try:
                min_lb = int(lookback_days) if lookback_days is not None else int(CONFIG.get("trade_monitor_scan_min_lookback_days", 1) or 1)
            except Exception:
                min_lb = 1
            min_lb = max(1, min(int(max_days), int(min_lb)))
            try:
                grace_ms = int(CONFIG.get("trade_monitor_scan_backfill_grace_ms", 6 * 3600 * 1000) or (6 * 3600 * 1000))
            except Exception:
                grace_ms = 6 * 3600 * 1000
            grace_ms = max(0, min(14 * 24 * 3600 * 1000, int(grace_ms)))
            try:
                default_lookback_h = float(CONFIG.get("trade_monitor_scan_default_lookback_hours", 48) or 48)
            except Exception:
                default_lookback_h = 48.0
            default_lookback_ms = int(max(1.0, min(14.0 * 24.0, float(default_lookback_h))) * 3600.0 * 1000.0)
            if int(last_close_ts) > 0:
                scan_ws = int(max(0, int(last_close_ts) - int(grace_ms)))
            else:
                scan_ws = int(max(0, int(ts_ms) - int(default_lookback_ms)))
            scan_ws = int(min(int(scan_ws), int(max(0, int(ts_ms) - int(min_lb) * 24 * 3600 * 1000))))
            close_orders_all, orders_archive_files = _trade_monitor_close_orders_window(int(scan_ws), int(ts_ms), include_memory=True, max_days=int(max_days))
        except Exception:
            close_orders_all = []
            orders_archive_files = []
        new_close = []
        for o in close_orders_all:
            ts_o = _trade_monitor_order_ts_ms(o)
            if ts_o > int(last_close_ts):
                new_close.append(o)
                continue
            if ts_o == int(last_close_ts):
                oid = _trade_monitor_order_id(o)
                if oid and oid not in seen_close_set:
                    new_close.append(o)

        light_due_by_time = (last_light_ts <= 0) or ((int(ts_ms) - int(last_light_ts)) >= int(light_per) * 1000)
        do_light = (int(len(new_close)) >= int(light_trades)) or bool(light_due_by_time)

        full_age_ok = (last_full_ts <= 0) or (full_min_age_ms <= 0) or ((int(ts_ms) - int(last_full_ts)) >= int(full_min_age_ms))
        do_full_base = bool(full_due) or (int(len(new_close)) >= int(full_trades) and bool(full_age_ok))
        do_full = bool(do_full_base)

        triggered = []
        reports = []

        lat_hist = st.get("latency_hist") if isinstance(st.get("latency_hist"), dict) else {}
        st["latency_hist"] = lat_hist
        monitor_cost = {"api_calls_total": 0, "latency_p95_ms": {}, "token_cost_estimate": 0}
        def _tm_time_call(key: str, fn):
            t0 = time.time()
            out = fn()
            dt = int(max(0.0, (time.time() - t0) * 1000.0))
            try:
                xs = lat_hist.get(key)
                if not isinstance(xs, list):
                    xs = []
                xs.append(int(dt))
                if len(xs) > 120:
                    xs = xs[-120:]
                lat_hist[key] = xs
            except Exception:
                pass
            monitor_cost["api_calls_total"] = int(monitor_cost.get("api_calls_total") or 0) + 1
            return out
        def _tm_p95(xs: List[int]) -> Optional[int]:
            ys = [int(x) for x in xs if isinstance(x, int) and x > 0]
            if not ys:
                return None
            ys.sort()
            i = int(max(0, min(len(ys) - 1, math.ceil(0.95 * len(ys)) - 1)))
            return int(ys[i])
        reject_stats = _tm_time_call("signals.reject_stats", lambda: _trade_monitor_reject_stats_snapshot(limit=2000, include_shadow=False))

        try:
            alerts_enabled = bool(CONFIG.get("trade_monitor_alert_upgrade_enabled", True))
        except Exception:
            alerts_enabled = True
        try:
            baseline_days = float(CONFIG.get("trade_monitor_baseline_rolling_days", 30) or 30)
        except Exception:
            baseline_days = 30.0
        baseline_days = max(1.0, min(90.0, float(baseline_days)))

        alerts_rep = None
        alerts_sum = {"ok": False, "alerts": [], "high": [], "summary": None}
        if alerts_enabled:
            try:
                alerts_rep = _tm_time_call("audit.alerts_evaluate", lambda: _audit_alerts_evaluate_internal(pair=None, lookback_days=1.0, now_ms=int(ts_ms)))
            except Exception:
                alerts_rep = None
            alerts_sum = _trade_monitor_alerts_summary(alerts_rep)
        high_alerts = alerts_sum.get("high") if isinstance(alerts_sum.get("high"), list) else []
        high_alert_ids = []
        for a in high_alerts:
            if not isinstance(a, dict):
                continue
            try:
                aid = str(a.get("id") or "").strip()
            except Exception:
                aid = ""
            if aid:
                high_alert_ids.append(aid)
        try:
            alert_bucket = int(int(ts_ms) // (10 * 60 * 1000))
        except Exception:
            alert_bucket = int(int(ts_ms) // 600000)
        try:
            seed = json.dumps({"bucket": int(alert_bucket), "high": sorted(high_alert_ids)}, sort_keys=True, ensure_ascii=False)
            alert_idem = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:16]
        except Exception:
            alert_idem = None
        try:
            alert_ttl_sec = int(CONFIG.get("trade_monitor_alert_upgrade_ttl_seconds", 1800) or 1800)
        except Exception:
            alert_ttl_sec = 1800
        alert_ttl_sec = max(60, min(12 * 3600, int(alert_ttl_sec)))
        last_alert_idem = (None if st.get("last_alert_idem") is None else str(st.get("last_alert_idem")))
        last_alert_ts = int(st.get("last_alert_ts_ms") or 0)
        alert_deduped = bool(alert_idem and last_alert_idem and str(alert_idem) == str(last_alert_idem) and last_alert_ts > 0 and (int(ts_ms) - int(last_alert_ts)) <= int(alert_ttl_sec) * 1000)
        alert_trigger = bool(high_alerts) and (not bool(alert_deduped))
        try:
            auto_rb_enabled = bool(CONFIG.get("paramopt_fast_apply_auto_rollback_enabled", True))
        except Exception:
            auto_rb_enabled = True
        if auto_rb_enabled:
            try:
                xs0 = CONFIG.get("paramopt_fast_apply_triggers")
                xs = xs0 if isinstance(xs0, list) else []
                xs2 = [x for x in xs if isinstance(x, dict)]
            except Exception:
                xs2 = []
            if xs2:
                xs2_sorted = sorted(xs2, key=lambda x: int(x.get("ts_ms") or 0), reverse=True)
                updated: List[Dict[str, Any]] = []
                seen_ids: set = set()
                rolled = False
                for t in xs2_sorted:
                    tid = str(t.get("id") or "").strip()
                    if tid and tid in seen_ids:
                        continue
                    if tid:
                        seen_ids.add(tid)
                    t2 = dict(t)
                    st0 = str(t2.get("status") or "").strip().lower()
                    try:
                        exp = int(t2.get("expires_ts_ms") or 0)
                    except Exception:
                        exp = 0
                    if exp > 0 and int(ts_ms) > int(exp) and st0 in ("", "armed"):
                        t2["status"] = "expired"
                        t2["expired_at_ms"] = int(ts_ms)
                        updated.append(t2)
                        continue
                    if (not rolled) and bool(high_alerts) and st0 in ("", "armed") and (exp <= 0 or int(ts_ms) <= int(exp)):
                        rbid = str(t2.get("rollback_point_id") or "").strip()
                        if rbid:
                            pt = _rollback_point_get_by_id(rbid)
                        else:
                            pt = None
                        if isinstance(pt, dict):
                            rb_res = _rollback_point_apply(pt, restore_thresholds=True, restore_arena=True, restore_active_model=False, restore_tracker_state=True, restore_config=True)
                            rolled = bool(isinstance(rb_res, dict) and rb_res.get("ok"))
                            t2["status"] = "rolled_back" if rolled else "rollback_failed"
                            t2["rolled_at_ms"] = int(ts_ms)
                            t2["high_alert_ids"] = [str(a.get("id") or "") for a in high_alerts if isinstance(a, dict) and str(a.get("id") or "").strip()][:50]
                            t2["rollback_result"] = (rb_res if isinstance(rb_res, dict) else {"ok": False})
                            try:
                                _rollback_point_append_event(
                                    str(rbid),
                                    {
                                        "ts": int(ts_ms),
                                        "kind": "auto_rollback",
                                        "reason": "paramopt.fast_apply.p0",
                                        "trace_id": str(t2.get("trace_id") or ""),
                                        "approval_id": str(t2.get("approval_id") or ""),
                                        "high_alert_ids": t2.get("high_alert_ids"),
                                        "rollback_ok": bool(rolled),
                                    },
                                )
                            except Exception:
                                pass
                            try:
                                _agent_outbox_append_jsonl(
                                    "audit_actions.jsonl",
                                    {
                                        "name": "paramopt.fast_apply.auto_rollback",
                                        "ts": int(ts_ms),
                                        "payload": {
                                            "trace_id": str(t2.get("trace_id") or ""),
                                            "approval_id": str(t2.get("approval_id") or ""),
                                            "rollback_point_id": str(rbid),
                                            "ok": bool(rolled),
                                            "high_alert_ids": t2.get("high_alert_ids"),
                                            "rollback": t2.get("rollback_result"),
                                        },
                                    },
                                )
                            except Exception:
                                pass
                    updated.append(t2)
                CONFIG["paramopt_fast_apply_triggers"] = updated[:50]
                try:
                    _save_config()
                except Exception:
                    pass

        need_baseline_eval = bool(do_full_base) or bool(alert_trigger)
        baseline_ref = None
        baseline_metrics = None
        if isinstance(st.get("baseline_full_metrics"), dict) and st.get("baseline_full_metrics"):
            baseline_metrics = dict(st.get("baseline_full_metrics") or {})
            baseline_ref = "prev_full"

        try:
            budget_limit = int(CONFIG.get("trade_monitor_budget_max_reports_per_day", CONFIG.get("budget.max_reports_per_day", 6)) or 6)
        except Exception:
            budget_limit = 6
        budget_limit = max(0, min(1000, int(budget_limit)))
        try:
            budget_day = str(st.get("budget_day") or "")
        except Exception:
            budget_day = ""
        if str(budget_day) != str(today):
            st["budget_day"] = str(today)
            st["budget_used"] = 0
        try:
            budget_used = int(st.get("budget_used") or 0)
        except Exception:
            budget_used = 0

        current_metrics = None
        exec_snapshot = None
        macro_snapshot = None
        exposure_snapshot = None
        if need_baseline_eval:
            w24_start = int(max(0, int(ts_ms) - 24 * 3600 * 1000))
            try:
                trade_lim = int(CONFIG.get("trade_monitor_metrics_trade_limit", 2000) or 2000)
            except Exception:
                trade_lim = 2000
            trade_lim = max(200, min(20000, int(trade_lim)))
            trades_24h = _tm_time_call("tracker.stats", lambda: _agent_recent_trades_from_settlements(since_ms=int(w24_start), limit=int(trade_lim)))
            m0 = _tm_time_call("trade_monitor.metrics", lambda: _trade_monitor_metrics_from_trades(trades_24h))
            try:
                rr = float((reject_stats or {}).get("reject_rate") or 0.0)
            except Exception:
                rr = 0.0
            eq0 = None
            try:
                eq0 = (alerts_rep.get("eq") if isinstance(alerts_rep, dict) else None)
            except Exception:
                eq0 = None
            if eq0 is None:
                try:
                    eq0 = _tm_time_call("audit.execution_quality", lambda: _audit_execution_quality(start_ts_ms=int(w24_start), end_ts_ms=int(ts_ms), pair=None, max_points=5000, include_shadow=False))
                except Exception:
                    eq0 = None
            exec_snapshot = (eq0 if isinstance(eq0, dict) else None)
            try:
                ofr = (None if exec_snapshot is None else exec_snapshot.get("order_fail_rate"))
            except Exception:
                ofr = None
            if ofr is not None:
                try:
                    ofr_f = float(ofr)
                except Exception:
                    ofr_f = None
            else:
                ofr_f = None
            dd0 = float(m0.get("max_drawdown_pct") or 0.0)
            try:
                op = TRACKER_STATE.get("open_positions") if isinstance(TRACKER_STATE.get("open_positions"), dict) else {}
                qp = TRACKER_STATE.get("quant_open_positions") if isinstance(TRACKER_STATE.get("quant_open_positions"), dict) else {}
                cp = TRACKER_STATE.get("carry_open_positions") if isinstance(TRACKER_STATE.get("carry_open_positions"), dict) else {}
                open_total = int(len(op) + len(qp) + len(cp))
            except Exception:
                open_total = None
            current_metrics = {
                "ts": int(ts_ms),
                "count": int(m0.get("count") or 0),
                "net_sharpe_oos": float(m0.get("sharpe") or 0.0),
                "sharpe": float(m0.get("sharpe") or 0.0),
                "profit_factor": m0.get("profit_factor"),
                "max_drawdown_pct": float(dd0),
                "daily_dd_pct": float(dd0),
                "reject_rate": float(rr),
                "order_fail_rate": (None if ofr_f is None else float(ofr_f)),
                "open_positions_total": (None if open_total is None else int(open_total)),
            }

            if baseline_metrics is None:
                try:
                    baseline_enabled = bool(CONFIG.get("trade_monitor_baseline_rolling_enabled", True))
                except Exception:
                    baseline_enabled = True
                if baseline_enabled:
                    b_start = int(max(0, int(ts_ms) - int(float(baseline_days) * 86400.0 * 1000.0)))
                    trades_b = _tm_time_call("tracker.stats_baseline", lambda: _agent_recent_trades_from_settlements(since_ms=int(b_start), limit=int(max(trade_lim, 5000))))
                    bm0 = _tm_time_call("trade_monitor.metrics_baseline", lambda: _trade_monitor_metrics_from_trades(trades_b))
                    bdd0 = float(bm0.get("max_drawdown_pct") or 0.0)
                    baseline_metrics = {
                        "ts": int(ts_ms),
                        "count": int(bm0.get("count") or 0),
                        "net_sharpe_oos": float(bm0.get("sharpe") or 0.0),
                        "sharpe": float(bm0.get("sharpe") or 0.0),
                        "profit_factor": bm0.get("profit_factor"),
                        "max_drawdown_pct": float(bdd0),
                        "daily_dd_pct": None,
                        "reject_rate": None,
                        "order_fail_rate": None,
                        "open_positions_total": None,
                    }
                    baseline_ref = f"rolling_{int(baseline_days)}d"

        if bool(CONFIG.get("trade_monitor_upgrade_macro_conf_low_enabled", CONFIG.get("upgrade.macro_conf_low", False))):
            try:
                macro_snapshot = _tm_time_call("macro.btceth.overview", lambda: _macro_snapshot_btceth(int(ts_ms)))
            except Exception:
                macro_snapshot = None
            try:
                op = TRACKER_STATE.get("open_positions") if isinstance(TRACKER_STATE.get("open_positions"), dict) else {}
                qp = TRACKER_STATE.get("quant_open_positions") if isinstance(TRACKER_STATE.get("quant_open_positions"), dict) else {}
                cp = TRACKER_STATE.get("carry_open_positions") if isinstance(TRACKER_STATE.get("carry_open_positions"), dict) else {}
                exposure_snapshot = {"open_positions": int(len(op)), "quant_open_positions": int(len(qp)), "carry_open_positions": int(len(cp)), "open_positions_total": int(len(op) + len(qp) + len(cp))}
            except Exception:
                exposure_snapshot = None

        rules_eval = _trade_monitor_rules_eval(
            now_ms=int(ts_ms),
            today=str(today),
            last_full_ts_ms=int(last_full_ts),
            new_close_trades=int(len(new_close)),
            light_threshold=int(light_trades),
            full_threshold=int(full_trades),
            full_age_ok=bool(full_age_ok),
            full_due=bool(full_due),
            baseline_ref=(None if baseline_ref is None else str(baseline_ref)),
            baseline_metrics=(baseline_metrics if isinstance(baseline_metrics, dict) else None),
            current_metrics=(current_metrics if isinstance(current_metrics, dict) else None),
            reject_stats=(reject_stats if isinstance(reject_stats, dict) else {}),
            exec_snapshot=(exec_snapshot if isinstance(exec_snapshot, dict) else None),
            high_alerts=(high_alerts if isinstance(high_alerts, list) else []),
            budget_used=int(budget_used),
            budget_limit=int(budget_limit),
        )
        stable_24h = bool(rules_eval.get("stable_24h"))
        delta_metrics = (rules_eval.get("delta_metrics") if isinstance(rules_eval.get("delta_metrics"), dict) else None)
        upgrade_hits = (rules_eval.get("upgrade_hits") if isinstance(rules_eval.get("upgrade_hits"), list) else [])
        trigger_rules = (rules_eval.get("rules") if isinstance(rules_eval.get("rules"), list) else [])
        has_p1 = bool(rules_eval.get("has_p1"))

        baseline_missing = bool(need_baseline_eval and (baseline_metrics is None))
        skip_full_reasons: List[str] = []
        if baseline_missing:
            skip_full_reasons.append("baseline_missing")

        if (not bool(full_due)) and bool(do_full) and bool(baseline_missing) and (not bool(alert_trigger)) and (not bool(upgrade_hits)):
            do_full = False

        if bool(do_full_base) and (not bool(full_due)) and (not bool(alert_trigger)) and (not bool(upgrade_hits)) and bool(stable_24h):
            do_full = False
            skip_full_reasons.append("stable_24h")

        budget_limited = bool(int(budget_limit) > 0 and int(budget_used) >= int(budget_limit))
        if bool(do_full) and bool(budget_limited) and (not bool(full_due)) and (not bool(alert_trigger)) and (not bool(has_p1)) and (not bool(force_full)):
            do_full = False
            skip_full_reasons.append("budget_rate_limited")

        if (not bool(do_full)) and bool(alert_trigger):
            if (not bool(budget_limited)) or bool(has_p1) or bool(force_full):
                do_full = True

        if bool(do_full_base) and (not bool(do_full)):
            trace_id = "tm_" + uuid.uuid4().hex
            trig_reason = ("daily" if bool(full_due) else ("alert" if bool(alert_trigger) else ("upgrade" if bool(upgrade_hits) else "trades")))
            payload = {
                "kind": "full",
                "daily": bool(full_due),
                "skipped": True,
                "skip_reasons": skip_full_reasons,
                "new_close_trades": int(len(new_close)),
                "threshold": int(full_trades),
                "since_close_ts_ms": int(last_close_ts),
                "until_ms": int(ts_ms),
                "trigger_reason": str(trig_reason),
                "stable_24h": bool(stable_24h),
                "baseline_ref": baseline_ref,
                "baseline_missing": bool(baseline_missing),
                "alerts_high": int(len(high_alerts)) if isinstance(high_alerts, list) else 0,
                "alerts_high_ids": (high_alert_ids[:16] if isinstance(high_alert_ids, list) else []),
                "upgrade_rules_hit": (upgrade_hits[:12] if isinstance(upgrade_hits, list) else []),
                "trigger_rules": (trigger_rules[:24] if isinstance(trigger_rules, list) else []),
                "metrics": (current_metrics if isinstance(current_metrics, dict) else None),
                "delta_metrics": delta_metrics,
                "budget": {"day": str(today), "used": int(budget_used), "limit": int(budget_limit)},
            }
            triggered.append(_agent_event_emit("trade.monitor.trigger", trace_id=str(trace_id), ok=True, payload=payload, reason="skipped"))
            try:
                _agent_emit_envelope_event(
                    event="trade.monitor.trigger",
                    trace_id=str(trace_id),
                    severity="info",
                    intent_level="L0",
                    ts_ms=int(ts_ms),
                    inputs=payload,
                    evidence=[{"endpoint": "/orders/recent", "window": {"start_ms": int(max(0, int(ts_ms) - 24 * 3600 * 1000)), "end_ms": int(ts_ms)}, "count_hint": int(len(new_close))}],
                    outputs={"skipped": True, "skip_reasons": skip_full_reasons},
                    doc_refs=_agent_doc_refs_trade_monitor_default(),
                )
            except Exception:
                pass

        if do_light:
            trace_id = "tm_" + uuid.uuid4().hex
            trig_reason = ("trades" if int(len(new_close)) >= int(light_trades) else "time")
            light_bucket = int(int(ts_ms) // max(1, int(light_per) * 1000))
            light_key = hashlib.sha256(f"light|{light_bucket}|{int(last_close_ts)}".encode("utf-8")).hexdigest()[:16]
            deduped = bool(st.get("last_light_key") == light_key)
            payload = {
                "kind": "light",
                "new_close_trades": int(len(new_close)),
                "threshold": int(light_trades),
                "since_close_ts_ms": int(last_close_ts),
                "until_ms": int(ts_ms),
                "trigger_reason": str(trig_reason),
            }
            if deduped:
                payload["deduped"] = True
                payload["dedupe_key"] = light_key
            triggered.append(_agent_event_emit("trade.monitor.trigger", trace_id=str(trace_id), ok=True, payload=payload, reason=("deduped" if deduped else str(trig_reason))))
            try:
                _agent_emit_envelope_event(
                    event="trade.monitor.trigger",
                    trace_id=str(trace_id),
                    severity="info",
                    intent_level="L0",
                    ts_ms=int(ts_ms),
                    inputs=payload,
                    evidence=[{"endpoint": "/orders/recent", "window": {"start_ms": int(last_close_ts), "end_ms": int(ts_ms)}, "count_hint": int(len(new_close))}],
                    outputs={"deduped": bool(deduped), "dedupe_key": (light_key if deduped else None)},
                    doc_refs=_agent_doc_refs_trade_monitor_default(),
                )
            except Exception:
                pass

            if not deduped:
                if new_close:
                    w0 = int(_trade_monitor_order_ts_ms(new_close[0]))
                else:
                    w0 = int(max(0, int(ts_ms) - 6 * 3600 * 1000))
                rep = _trade_monitor_build_report(
                    int(ts_ms),
                    trace_id=str(trace_id),
                    kind="light",
                    window_start_ms=int(w0),
                    window_end_ms=int(ts_ms),
                    close_orders=close_orders_all,
                    reject_stats=reject_stats,
                    context={
                        "baseline_ref": baseline_ref,
                        "baseline_metrics": baseline_metrics,
                        "current_metrics": current_metrics,
                        "delta_metrics": delta_metrics,
                        "has_p1": has_p1,
                        "exec_snapshot": exec_snapshot,
                        "macro_snapshot": macro_snapshot,
                        "exposure_snapshot": exposure_snapshot,
                        "monitor_cost": monitor_cost,
                        "orders_archive_files": (orders_archive_files if isinstance(orders_archive_files, list) else []),
                        "trigger_rules": trigger_rules,
                        "upgrade_hits": upgrade_hits,
                    },
                )
                if isinstance(rep, dict):
                    rep["metrics_summary"] = (current_metrics if isinstance(current_metrics, dict) else None)
                    rep["baseline"] = ({"ref": baseline_ref, "metrics": baseline_metrics} if isinstance(baseline_metrics, dict) or baseline_ref else None)
                    rep["delta_metrics"] = delta_metrics
                    rep["stable_24h"] = bool(stable_24h)
                    rep["baseline_missing"] = bool(baseline_missing)
                    rep["trigger_reason"] = str(trig_reason)
                    rep["trigger_rules"] = (trigger_rules if isinstance(trigger_rules, list) else [])
                    rep["upgrade_rules_hit"] = (upgrade_hits if isinstance(upgrade_hits, list) else [])
                    rep["budget"] = {"day": str(today), "used": int(budget_used), "limit": int(budget_limit)}
                    try:
                        rep["analysis"] = _trade_monitor_analysis_build(rep)
                    except Exception:
                        pass
                _agent_outbox_append_jsonl("trade_monitor_reports.jsonl", rep)
                reports.append(rep)
                _agent_event_emit(
                    "trade.monitor.report",
                    trace_id=str(trace_id),
                    ok=True,
                    payload={"report_id": str(rep.get("id")), "outbox_file": "trade_monitor_reports.jsonl", "kind": "light"},
                    evidence=[{"type": "outbox", "source": "agent_outbox/trade_monitor_reports.jsonl", "report_id": str(rep.get("id"))}],
                )
                try:
                    _agent_emit_envelope_event(
                        event="trade.monitor.report",
                        trace_id=str(trace_id),
                        severity="info",
                        intent_level="L0",
                        ts_ms=int(ts_ms),
                        inputs={"kind": "light", "window": rep.get("window"), "outbox_file": "trade_monitor_reports.jsonl"},
                        evidence=(rep.get("input_evidence") if isinstance(rep.get("input_evidence"), list) else []),
                        outputs={"report_id": str(rep.get("id")), "summary": rep.get("summary"), "suggestions": rep.get("suggestions")},
                        doc_refs=(rep.get("doc_refs") if isinstance(rep.get("doc_refs"), list) else _agent_doc_refs_trade_monitor_default()),
                    )
                except Exception:
                    pass

            st["last_light_ts_ms"] = int(ts_ms)
            st["last_light_key"] = light_key

        if do_full:
            trace_id = "tm_" + uuid.uuid4().hex
            if bool(full_due):
                trig_reason = "daily"
            elif bool(alert_trigger):
                trig_reason = "alert"
            elif bool(upgrade_hits):
                trig_reason = "upgrade"
            else:
                trig_reason = "trades"
            full_window_days = 1
            try:
                if lookback_days is not None:
                    full_window_days = int(lookback_days)
            except Exception:
                full_window_days = 1
            full_window_days = max(1, min(60, int(full_window_days)))
            w0 = int(max(0, int(ts_ms) - int(full_window_days) * 24 * 3600 * 1000))
            full_bucket = str(today) if bool(full_due) else str(int(int(ts_ms) // max(1, int(full_min_age_ms) if int(full_min_age_ms) > 0 else 86400000)))
            full_key = hashlib.sha256(f"full|{full_bucket}|{int(last_close_ts)}|{str(trig_reason)}|{str(alert_idem or '')}".encode("utf-8")).hexdigest()[:16]
            deduped = bool(st.get("last_full_key") == full_key)
            if bool(force_full):
                deduped = False
            payload = {
                "kind": "full",
                "daily": bool(full_due),
                "new_close_trades": int(len(new_close)),
                "threshold": int(full_trades),
                "since_close_ts_ms": int(last_close_ts),
                "until_ms": int(ts_ms),
                "trigger_reason": str(trig_reason),
                "stable_24h": bool(stable_24h),
                "baseline_ref": baseline_ref,
                "baseline_missing": bool(baseline_missing),
                "alerts_high": int(len(high_alerts)) if isinstance(high_alerts, list) else 0,
                "alerts_high_ids": (high_alert_ids[:16] if isinstance(high_alert_ids, list) else []),
                "upgrade_rules_hit": (upgrade_hits[:12] if isinstance(upgrade_hits, list) else []),
                "trigger_rules": (trigger_rules[:24] if isinstance(trigger_rules, list) else []),
                "metrics": (current_metrics if isinstance(current_metrics, dict) else None),
                "delta_metrics": delta_metrics,
                "budget": {"day": str(today), "used": int(budget_used), "limit": int(budget_limit)},
            }
            if deduped:
                payload["deduped"] = True
                payload["dedupe_key"] = full_key
            triggered.append(_agent_event_emit("trade.monitor.trigger", trace_id=str(trace_id), ok=True, payload=payload, reason=("deduped" if deduped else str(trig_reason))))
            try:
                _agent_emit_envelope_event(
                    event="trade.monitor.trigger",
                    trace_id=str(trace_id),
                    severity=("warn" if str(trig_reason) in ("alert", "upgrade") else "info"),
                    intent_level=("L1" if str(trig_reason) in ("alert", "upgrade") else "L0"),
                    ts_ms=int(ts_ms),
                    inputs=payload,
                    evidence=[{"endpoint": "/orders/recent", "window": {"start_ms": int(w0), "end_ms": int(ts_ms)}, "count_hint": int(len(new_close))}],
                    outputs={"deduped": bool(deduped), "dedupe_key": (full_key if deduped else None)},
                    doc_refs=_agent_doc_refs_trade_monitor_default(),
                )
            except Exception:
                pass

            if not deduped:
                rep = _trade_monitor_build_report(
                    int(ts_ms),
                    trace_id=str(trace_id),
                    kind="full",
                    window_start_ms=int(w0),
                    window_end_ms=int(ts_ms),
                    close_orders=close_orders_all,
                    reject_stats=reject_stats,
                    context={
                        "baseline_ref": baseline_ref,
                        "baseline_metrics": baseline_metrics,
                        "current_metrics": current_metrics,
                        "delta_metrics": delta_metrics,
                        "has_p1": has_p1,
                        "exec_snapshot": exec_snapshot,
                        "macro_snapshot": macro_snapshot,
                        "exposure_snapshot": exposure_snapshot,
                        "monitor_cost": monitor_cost,
                        "orders_archive_files": (orders_archive_files if isinstance(orders_archive_files, list) else []),
                        "trigger_rules": trigger_rules,
                        "upgrade_hits": upgrade_hits,
                    },
                )
                if isinstance(rep, dict):
                    rep["metrics_summary"] = (current_metrics if isinstance(current_metrics, dict) else None)
                    rep["baseline"] = ({"ref": baseline_ref, "metrics": baseline_metrics} if isinstance(baseline_metrics, dict) or baseline_ref else None)
                    rep["delta_metrics"] = delta_metrics
                    rep["stable_24h"] = bool(stable_24h)
                    rep["baseline_missing"] = bool(baseline_missing)
                    rep["trigger_reason"] = str(trig_reason)
                    rep["trigger_rules"] = (trigger_rules if isinstance(trigger_rules, list) else [])
                    rep["upgrade_rules_hit"] = (upgrade_hits if isinstance(upgrade_hits, list) else [])
                    rep["budget"] = {"day": str(today), "used": int(budget_used), "limit": int(budget_limit)}
                    rep["macro"] = {"snapshot": macro_snapshot, "exposure": exposure_snapshot}
                    rep["execution"] = {"snapshot": exec_snapshot}
                    rep["monitor_cost"] = monitor_cost
                    rep["alerts"] = {
                        "high": (high_alerts[:12] if isinstance(high_alerts, list) else []),
                        "summary": (alerts_sum.get("summary") if isinstance(alerts_sum, dict) else None),
                    }
                    try:
                        add_sugs = _trade_monitor_suggestions_from_rules(
                            trace_id=str(trace_id),
                            kind="full",
                            window_start_ms=int(w0),
                            window_end_ms=int(ts_ms),
                            trigger_rules=(trigger_rules if isinstance(trigger_rules, list) else []),
                            upgrade_rules_hit=(upgrade_hits if isinstance(upgrade_hits, list) else []),
                            metrics_summary=(current_metrics if isinstance(current_metrics, dict) else None),
                            baseline=(baseline_metrics if isinstance(baseline_metrics, dict) else None),
                            delta_metrics=(delta_metrics if isinstance(delta_metrics, dict) else None),
                            reject_stats=(reject_stats if isinstance(reject_stats, dict) else {}),
                            exec_snapshot=(exec_snapshot if isinstance(exec_snapshot, dict) else None),
                        )
                    except Exception:
                        add_sugs = []
                    try:
                        existing = rep.get("suggestions") if isinstance(rep.get("suggestions"), list) else []
                        seen = set()
                        for s0 in existing:
                            if isinstance(s0, dict) and str(s0.get("phenomenon_id") or "").strip():
                                seen.add(str(s0.get("phenomenon_id")).strip())
                        for s1 in (add_sugs or []):
                            if not isinstance(s1, dict):
                                continue
                            pid = str(s1.get("phenomenon_id") or "").strip()
                            if pid and pid in seen:
                                continue
                            existing.append(s1)
                        rep["suggestions"] = _trade_monitor_suggestions_route(
                            existing,
                            trace_id=str(trace_id),
                            kind="full",
                            window_start_ms=int(w0),
                            window_end_ms=int(ts_ms),
                            reject_stats=(reject_stats if isinstance(reject_stats, dict) else {}),
                            by_system=(rep.get("by_system") if isinstance(rep.get("by_system"), dict) else {}),
                            top_pairs=(rep.get("top_pairs") if isinstance(rep.get("top_pairs"), list) else []),
                            metrics_summary=(current_metrics if isinstance(current_metrics, dict) else None),
                            baseline=(baseline_metrics if isinstance(baseline_metrics, dict) else None),
                            delta_metrics=(delta_metrics if isinstance(delta_metrics, dict) else None),
                            exec_snapshot=(exec_snapshot if isinstance(exec_snapshot, dict) else None),
                            upgrade_hits=(upgrade_hits if isinstance(upgrade_hits, list) else []),
                        )
                    except Exception:
                        pass
                _agent_outbox_append_jsonl("trade_monitor_reports.jsonl", rep)
                reports.append(rep)
                _agent_event_emit(
                    "trade.monitor.report",
                    trace_id=str(trace_id),
                    ok=True,
                    payload={"report_id": str(rep.get("id")), "outbox_file": "trade_monitor_reports.jsonl", "kind": "full"},
                    evidence=[{"type": "outbox", "source": "agent_outbox/trade_monitor_reports.jsonl", "report_id": str(rep.get("id"))}],
                )
                try:
                    _agent_emit_envelope_event(
                        event="trade.monitor.report",
                        trace_id=str(trace_id),
                        severity=("warn" if str(trig_reason) in ("alert", "upgrade") else "info"),
                        intent_level=("L1" if str(trig_reason) in ("alert", "upgrade") else "L0"),
                        ts_ms=int(ts_ms),
                        inputs={"kind": "full", "window": rep.get("window"), "outbox_file": "trade_monitor_reports.jsonl"},
                        evidence=(rep.get("input_evidence") if isinstance(rep.get("input_evidence"), list) else []),
                        outputs={"report_id": str(rep.get("id")), "summary": rep.get("summary"), "suggestions": rep.get("suggestions"), "metrics_summary": rep.get("metrics_summary"), "stable_24h": rep.get("stable_24h"), "trigger_rules": rep.get("trigger_rules"), "upgrade_rules_hit": rep.get("upgrade_rules_hit"), "budget": rep.get("budget")},
                        doc_refs=(rep.get("doc_refs") if isinstance(rep.get("doc_refs"), list) else _agent_doc_refs_trade_monitor_default()),
                    )
                except Exception:
                    pass

                if isinstance(current_metrics, dict) and current_metrics:
                    st["baseline_full_metrics"] = dict(current_metrics)
                try:
                    st["budget_used"] = int(budget_used) + 1
                except Exception:
                    st["budget_used"] = 0
                if bool(alert_trigger) and alert_idem:
                    st["last_alert_idem"] = str(alert_idem)
                    st["last_alert_ts_ms"] = int(ts_ms)

            st["last_full_day"] = str(today)
            st["last_full_ts_ms"] = int(ts_ms)
            st["last_full_key"] = full_key

        if new_close:
            try:
                new_last = int(max(_trade_monitor_order_ts_ms(o) for o in new_close))
                st["last_close_ts_ms"] = int(new_last)
            except Exception:
                st["last_close_ts_ms"] = int(ts_ms)
        last_close_ts2 = int(st.get("last_close_ts_ms") or 0)
        if last_close_ts2 > 0:
            ids_at_ts: List[str] = []
            for o in close_orders_all:
                if _trade_monitor_order_ts_ms(o) != last_close_ts2:
                    continue
                oid = _trade_monitor_order_id(o)
                if oid:
                    ids_at_ts.append(oid)
            if len(ids_at_ts) > 800:
                ids_at_ts = ids_at_ts[-800:]
            st["seen_close_ids"] = ids_at_ts
        st["last_report_ts_ms"] = int(ts_ms)
        try:
            for k, v in (st.get("latency_hist") if isinstance(st.get("latency_hist"), dict) else {}).items():
                if not isinstance(v, list):
                    continue
                p95 = _tm_p95(v)
                if p95 is not None:
                    monitor_cost["latency_p95_ms"][str(k)] = int(p95)
        except Exception:
            pass
        _trade_monitor_state_save(st)

        return {
            "ok": True,
            "ts": int(ts_ms),
            "state": st,
            "close_trades_total": int(len(close_orders_all)),
            "new_close_trades": int(len(new_close)),
            "light_threshold": int(light_trades),
            "full_threshold": int(full_trades),
            "did_light": bool(do_light),
            "did_full": bool(do_full),
            "triggered": triggered,
            "reports": [{"id": str(r.get("id")), "trace_id": str(r.get("trace_id")), "kind": str(r.get("kind"))} for r in (reports or [])],
            "monitor_cost": monitor_cost,
        }


@app.route("/agent/trade_monitor/scan", methods=["POST"])
def agent_trade_monitor_scan():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    force_full = bool(data.get("force_full", False))
    try:
        lookback_days_raw = data.get("lookback_days")
        if lookback_days_raw is None:
            lookback_days_raw = data.get("min_lookback_days")
        lookback_days = (None if lookback_days_raw is None else int(lookback_days_raw))
    except Exception:
        lookback_days = None
    try:
        now_ms = int(data.get("now_ms") or 0)
    except Exception:
        now_ms = 0
    if now_ms <= 0:
        now_ms = int(_now_ms())
    res = _trade_monitor_scan(int(now_ms), force_full=bool(force_full), lookback_days=lookback_days)
    return jsonify(res)


def _macro_snapshot_btceth(ts_ms: int, *, freshness_warn_sec: int = 3600) -> Dict[str, Any]:
    try:
        ts_i = int(ts_ms or 0)
    except Exception:
        ts_i = int(_now_ms())
    now_ms = int(_now_ms())
    snap = None
    try:
        snap = _entry_macro_btceth_shape_at(int(ts_i), allow_disabled=True)
    except Exception:
        snap = None
    data = snap if isinstance(snap, dict) else {}
    fields = []
    try:
        fields = list(data.keys())
    except Exception:
        fields = []
    missing = 0
    total = 0
    for k in fields:
        total += 1
        if data.get(k) is None:
            missing += 1
    missing_rate = (float(missing) / float(total)) if total > 0 else 1.0
    freshness_ms = None
    try:
        freshness_ms = int(now_ms - int(ts_i))
    except Exception:
        freshness_ms = None
    staleness = None
    if freshness_ms is not None:
        staleness = {
            "freshness_ms": int(freshness_ms),
            "warn": bool(int(freshness_ms) > int(freshness_warn_sec) * 1000),
            "asof_ts_ms": int(ts_i),
            "now_ms": int(now_ms),
        }
    try:
        seed = json.dumps({"asof_ts_ms": int(ts_i), "data": data}, sort_keys=True, ensure_ascii=False)
        sid = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:16]
    except Exception:
        sid = hashlib.sha256(str(ts_i).encode("utf-8")).hexdigest()[:16]
    out: Dict[str, Any] = {
        "macro_snapshot_id": sid,
        "asof_ts_ms": int(ts_i),
        "missing_rate": float(missing_rate),
        "data": data,
    }
    if staleness is not None:
        out["freshness"] = staleness
    return out


def _macro_confidence_for_signal(side: str, macro_snapshot: Dict[str, Any]) -> Dict[str, Any]:
    s = str(side or "").strip().lower()
    data = macro_snapshot.get("data") if isinstance(macro_snapshot.get("data"), dict) else {}
    missing_rate = 1.0
    try:
        missing_rate = float(macro_snapshot.get("missing_rate"))
    except Exception:
        missing_rate = 1.0
    freshness_ms = None
    try:
        freshness_ms = int(((macro_snapshot.get("freshness") if isinstance(macro_snapshot.get("freshness"), dict) else {}) or {}).get("freshness_ms") or 0)
    except Exception:
        freshness_ms = None

    support = []
    conflict = []

    trend_ok = None
    trend_key = None
    for k in ("trend", "dir", "dir_12h", "direction", "shape", "value_bucket", "state", "weekly_state"):
        if k in data:
            trend_key = k
            break
    if trend_key is not None:
        raw = data.get(trend_key)
        dir_i = None
        try:
            if isinstance(raw, (int, float)):
                dir_i = int(float(raw))
            elif isinstance(raw, str):
                xs = raw.strip()
                if xs and xs.replace("+", "", 1).replace("-", "", 1).isdigit():
                    dir_i = int(float(xs))
        except Exception:
            dir_i = None
        if dir_i is not None:
            if dir_i > 0:
                dir_i = 1
            elif dir_i < 0:
                dir_i = -1
            else:
                dir_i = 0
            if s in ("long", "buy"):
                if dir_i == 1:
                    trend_ok = True
                elif dir_i == -1:
                    trend_ok = False
            if s in ("short", "sell"):
                if dir_i == -1:
                    trend_ok = True
                elif dir_i == 1:
                    trend_ok = False

        if trend_ok is None:
            v = str(raw or "").strip().lower()
            is_up = (v in ("up", "bull", "long", "riskon")) or v.startswith("up")
            is_down = (v in ("down", "bear", "short", "riskoff")) or v.startswith("down")
            if s in ("long", "buy"):
                if is_up:
                    trend_ok = True
                elif is_down:
                    trend_ok = False
            if s in ("short", "sell"):
                if is_down:
                    trend_ok = True
                elif is_up:
                    trend_ok = False

    has_directional_evidence = bool(trend_key is not None and trend_ok is not None)

    if trend_ok is True:
        support.append({"feature": trend_key, "note": "trend_aligned"})
    elif trend_ok is False:
        conflict.append({"feature": trend_key, "note": "trend_conflict"})

    score = 0.50
    if trend_ok is True:
        score += 0.22
    elif trend_ok is False:
        score -= 0.22

    if freshness_ms is not None and int(freshness_ms) > 3600 * 1000:
        score -= 0.20
        conflict.append({"feature": "freshness", "note": "stale_macro"})
    if float(missing_rate) >= 0.35:
        score -= 0.20
        conflict.append({"feature": "missing_rate", "note": "macro_missing"})

    score = float(max(0.0, min(1.0, float(score))))
    level = "low"
    if score >= 0.75:
        level = "high"
    elif score >= 0.55:
        level = "medium"
    elif (not has_directional_evidence) and (not conflict) and (freshness_ms is not None) and int(freshness_ms) <= 3600 * 1000 and float(missing_rate) < 0.35:
        level = "neutral"
    if freshness_ms is None or float(missing_rate) >= 0.70:
        level = "low"

    return {
        "confidence_score": float(score),
        "confidence_level": str(level),
        "support": support,
        "conflict": conflict,
        "macro_snapshot_id": macro_snapshot.get("macro_snapshot_id"),
        "freshness": macro_snapshot.get("freshness"),
        "missing_rate": float(missing_rate),
    }


def _signal_explain_from_event(evt: Dict[str, Any]) -> Dict[str, Any]:
    pair = evt.get("pair")
    side = evt.get("side")
    tf = evt.get("timeframe")
    action = evt.get("action")
    sk = None
    try:
        sid = str(evt.get("strategy_id") or "").strip()
        ver = str(evt.get("strategy_version") or "").strip()
        sk = (sid + ("@" + ver if ver else "")) if sid else (ver or None)
    except Exception:
        sk = None

    triggers: List[Dict[str, Any]] = []
    for k in ("triggered_indicators", "trigger_indicators", "indicators", "triggers", "conditions"):
        v = evt.get(k)
        if isinstance(v, list):
            for it in v[:24]:
                if isinstance(it, dict):
                    name = it.get("name") if it.get("name") is not None else it.get("indicator")
                    triggers.append({
                        "name": (None if name is None else str(name)),
                        "value": it.get("value"),
                        "threshold": it.get("threshold"),
                        "op": it.get("op") if it.get("op") is not None else it.get("cmp"),
                        "hit": (it.get("hit") if it.get("hit") is not None else True),
                    })
                else:
                    triggers.append({"name": str(it), "hit": True})
            break
        if isinstance(v, dict):
            for kk, vv in list(v.items())[:24]:
                triggers.append({"name": str(kk), "value": vv, "hit": True})
            break

    if not triggers:
        di = evt.get("decision_info") if isinstance(evt.get("decision_info"), dict) else {}
        if di:
            for k in ("reason", "p", "pc", "threshold", "regime"):
                if di.get(k) is not None:
                    triggers.append({"name": str(k), "value": di.get(k), "hit": True})

    if not triggers:
        feats = evt.get("features") if isinstance(evt.get("features"), dict) else {}
        if feats:
            keys0 = [
                "rsi",
                "rsi_d",
                "adx",
                "atr_pct",
                "bb_percent",
                "z_score",
                "vol_z_20",
                "trend_score",
                "mr_score",
                "recent_pump",
                "buy_votes",
                "bottom_confirmation_score",
                "bottom_confirmed",
            ]

            def _ok(v: Any) -> bool:
                if v is None:
                    return False
                if isinstance(v, bool):
                    return True
                try:
                    x = float(v)
                except Exception:
                    return bool(str(v).strip())
                if not math.isfinite(float(x)):
                    return False
                return abs(float(x)) > 1e-9

            for k in keys0:
                if k in feats and _ok(feats.get(k)):
                    triggers.append({"name": str(k), "value": feats.get(k), "hit": True})
                if len(triggers) >= 12:
                    break

    return {
        "strategy_key": sk,
        "pair": pair,
        "timeframe": tf,
        "side": side,
        "action": action,
        "triggers": triggers,
    }


def _twitter_rate_limit_reasons() -> List[str]:
    cfg = CONFIG.get("agent_push") or {}
    if not isinstance(cfg, dict):
        cfg = {}
    try:
        max_per = int(cfg.get("twitter_max_per_hour", 2) or 2)
    except Exception:
        max_per = 2
    try:
        v = str(os.environ.get("TWITTER_MAX_PER_HOUR", "") or "").strip()
        if v:
            max_per = int(v)
    except Exception:
        pass
    try:
        win_sec = int(cfg.get("twitter_rate_window_sec", 3600) or 3600)
    except Exception:
        win_sec = 3600
    try:
        v = str(os.environ.get("TWITTER_RATE_WINDOW_SEC", "") or "").strip()
        if v:
            win_sec = int(v)
    except Exception:
        pass
    try:
        min_gap = int(cfg.get("twitter_min_interval_sec", 600) or 600)
    except Exception:
        min_gap = 600
    try:
        v = str(os.environ.get("TWITTER_MIN_INTERVAL_SEC", "") or "").strip()
        if v:
            min_gap = int(v)
    except Exception:
        pass
    max_per = max(0, min(200, int(max_per)))
    win_sec = max(60, min(24 * 3600, int(win_sec)))
    min_gap = max(0, min(24 * 3600, int(min_gap)))
    if max_per <= 0 and min_gap <= 0:
        return []

    q = _agent_outbox_dir() / "delivery_receipts.jsonl"
    if not q.exists():
        return []

    buf: deque[Dict[str, Any]] = deque(maxlen=6000)
    try:
        with open(q, "r", encoding="utf-8") as f:
            for line in f:
                s = line.strip("\n")
                if not s.strip():
                    continue
                try:
                    obj = json.loads(s)
                except Exception:
                    continue
                if not isinstance(obj, dict):
                    continue
                if str(obj.get("channel") or "").strip().lower() != "twitter":
                    continue
                if not bool(obj.get("ok", False)):
                    continue
                ts0 = obj.get("ts")
                if ts0 is None:
                    continue
                buf.append(obj)
    except Exception:
        return []

    now_ms = int(_now_ms())
    window_ms = int(win_sec) * 1000
    count_in_window = 0
    last_ok_ts = None
    for obj in reversed(list(buf)):
        try:
            ts_i = int(obj.get("ts") or 0)
        except Exception:
            ts_i = 0
        if ts_i <= 0:
            continue
        if last_ok_ts is None:
            last_ok_ts = ts_i
        if window_ms > 0 and (now_ms - ts_i) > window_ms:
            break
        count_in_window += 1

    out: List[str] = []
    if min_gap > 0 and last_ok_ts is not None and (now_ms - int(last_ok_ts)) < int(min_gap) * 1000:
        out.append("twitter_min_interval")
    if max_per > 0 and count_in_window >= int(max_per):
        out.append("twitter_rate_limited")
    return out


def _twitter_gate_decide(*, trace_id: str, evt: Optional[Dict[str, Any]], order: Optional[Dict[str, Any]], macro_assessment: Dict[str, Any], intent_level: str) -> Dict[str, Any]:
    reasons: List[str] = []
    decision = "pass"

    if not isinstance(evt, dict):
        decision = "fail"
        reasons.append("missing_signal")
    else:
        try:
            act0 = str(evt.get("action") or "").strip().lower()
        except Exception:
            act0 = ""
        if act0 in ("reduce", "close"):
            decision = "fail"
            reasons.append("exit_order_no_tweet")

    has_order = bool(isinstance(order, dict))

    lvl = str(macro_assessment.get("confidence_level") or "low").strip().lower() or "low"
    if lvl == "low" and (not has_order) and str(intent_level) != "L2":
        conflicts = macro_assessment.get("conflict")
        if not isinstance(conflicts, list):
            conflicts = []
        conflict_notes = []
        for it in conflicts:
            if not isinstance(it, dict):
                continue
            note = it.get("note")
            if note is None:
                continue
            ns = str(note).strip().lower()
            if ns:
                conflict_notes.append(ns)
        hard_conflict = any(x in conflict_notes for x in ("trend_conflict",))
        soft_only = all(x in ("stale_macro", "macro_missing") for x in conflict_notes) if conflict_notes else False
        if hard_conflict or (not soft_only):
            decision = "fail"
            reasons.append("macro_confidence_low")

    if (not has_order) and str(intent_level) != "L2":
        decision = "fail"
        reasons.append("no_order_result")

    if isinstance(order, dict):
        st = str(order.get("status") or "").strip().lower()
        if st and st not in ("filled", "submitted", "accepted"):
            decision = "fail"
            reasons.append("order_not_executed")

    ttl_ok = True
    try:
        ts_evt = None
        if isinstance(evt, dict):
            ts_evt = evt.get("ts_emit_ms") if evt.get("ts_emit_ms") is not None else evt.get("ingested_ms")
            if ts_evt is None:
                ts_evt = evt.get("ts")
        ts_i = int(ts_evt or 0)
        if ts_i > 0 and ts_i < 10_000_000_000:
            ts_i = ts_i * 1000
        now_ms = int(_now_ms())
        if ts_i > 0 and (now_ms - ts_i) > 30 * 60 * 1000:
            ttl_ok = False
    except Exception:
        ttl_ok = False
    if not ttl_ok:
        decision = "fail"
        reasons.append("signal_too_old")

    if decision == "pass":
        try:
            rr = _twitter_rate_limit_reasons()
            if rr and str(intent_level) == "L2" and isinstance(order, dict):
                rr = [x for x in rr if str(x) != "twitter_rate_limited"]
            if rr:
                decision = "fail"
                reasons.extend(rr)
        except Exception:
            pass

    if decision != "pass" and not reasons:
        reasons.append("blocked")

    return {
        "trace_id": str(trace_id),
        "decision": decision,
        "block_reasons": reasons,
        "intent_level": str(intent_level),
        "ts": int(_now_ms()),
    }


def _twitter_publish_request_enqueue(*, trace_id: str, text: str, idempotency_key: str, ttl_sec: int, refs: Dict[str, Any], intent_level: str) -> Dict[str, Any]:
    ts_ms = int(_now_ms())
    ttl_i = int(max(0, min(86400, int(ttl_sec))))
    try:
        outbox_id = hashlib.sha256(("twitter.publish.request|" + str(idempotency_key)).encode("utf-8")).hexdigest()[:32]
    except Exception:
        outbox_id = hashlib.sha256((str(trace_id) + "|" + str(idempotency_key)).encode("utf-8")).hexdigest()[:32]
    env: Dict[str, Any] = {
        "id": str(outbox_id),
        "trace_id": str(trace_id),
        "ts": ts_ms,
        "event": "twitter.publish.request",
        "type": "push.send",
        "channel": "twitter",
        "severity": "info",
        "idempotency_key": str(idempotency_key),
        "ttl_sec": int(ttl_i),
        "intent_level": str(intent_level),
        "message": str(text or "").strip(),
        "extras": {
            "twitter_publish_request": {"text": str(text or "").strip(), "ttl_sec": int(ttl_i)},
            "refs": (refs if isinstance(refs, dict) else {}),
        },
    }
    if ttl_i > 0:
        try:
            env["expires_at"] = int(ts_ms + ttl_i * 1000)
        except Exception:
            pass
    _agent_outbox_append_jsonl("twitter.jsonl", env)
    return env


def _maybe_trigger_twitter_from_order(*, order: Dict[str, Any], trace_id: str) -> None:
    tid = str(trace_id or "").strip()
    if not tid:
        return
    if not isinstance(order, dict):
        return
    try:
        ab0 = order.get("ab_owner") if order.get("ab_owner") is not None else order.get("system_id")
    except Exception:
        ab0 = None
    try:
        owner0 = str(_ab_norm_owner(ab0) or "strategy")
    except Exception:
        owner0 = "strategy"
    if owner0 in ("quant", "carry"):
        return
    try:
        sid = order.get("strategy_id")
        sid0 = (None if sid is None else str(sid).strip() or None)
    except Exception:
        sid0 = None
    try:
        _ensure_trace_event_for_order(tid, order=order, strategy_id=sid0)
    except Exception:
        pass
    try:
        _on_signal_ingest(tid)
    except Exception:
        pass


def _twitter_llm_note_generate(*, trace_id: str, evt: Dict[str, Any], order: Optional[Dict[str, Any]], signal_explain: Dict[str, Any], macro_assessment: Dict[str, Any]) -> Dict[str, Any]:
    cfg = CONFIG.get("agent_push") or {}
    if not isinstance(cfg, dict):
        cfg = {}

    provider = ""
    try:
        provider = str(cfg.get("twitter_llm_provider") or "").strip().lower()
    except Exception:
        provider = ""
    try:
        v = str(os.environ.get("TWITTER_LLM_PROVIDER", "") or "").strip().lower()
        if v:
            provider = v
    except Exception:
        pass
    if provider not in ("ollama", "dashscope", "qwen"):
        provider = "ollama"

    model = ""
    try:
        model = str(cfg.get("twitter_llm_model") or "").strip()
    except Exception:
        model = ""
    try:
        v = str(os.environ.get("TWITTER_LLM_MODEL", "") or "").strip()
        if v:
            model = v
    except Exception:
        pass
    if not model:
        if provider in ("dashscope", "qwen"):
            try:
                model = str(os.environ.get("AGENT_DASHSCOPE_MODEL", "") or "").strip()
            except Exception:
                model = ""
            if not model:
                try:
                    model = str(CONFIG.get("agent_dashscope_model") or "").strip()
                except Exception:
                    model = ""
            if not model:
                model = "qwen-plus"
        else:
            try:
                model = str(os.environ.get("AGENT_OLLAMA_MODEL", "") or "").strip()
            except Exception:
                model = ""
            if not model:
                try:
                    model = str(CONFIG.get("agent_ollama_model") or "").strip()
                except Exception:
                    model = ""
            if not model:
                model = "qwen2.5:7b-instruct"

    sys = "\n".join([
        "You generate a short explanation note for a crypto trading tweet. Output STRICT JSON only, no Markdown.",
        "Output: {\"note\": \"...\"}.",
        "note must be English only, <= 80 chars, single sentence, explain the trigger highlights.",
        "Do not include any keys/URLs/internal paths. If you cannot, output {\"note\":\"\"}.",
    ])

    di = evt.get("decision_info") if isinstance(evt.get("decision_info"), dict) else {}
    user_obj = {
        "trace_id": str(trace_id),
        "pair": evt.get("pair") if evt.get("pair") is not None else (order.get("pair") if isinstance(order, dict) else None),
        "side": evt.get("side") if evt.get("side") is not None else (order.get("side") if isinstance(order, dict) else None),
        "action": evt.get("action") if evt.get("action") is not None else (order.get("action") if isinstance(order, dict) else None),
        "tag": evt.get("tag") if evt.get("tag") is not None else (order.get("tag") if isinstance(order, dict) else None),
        "decision": {"reason": di.get("reason"), "p": di.get("p"), "pc": di.get("pc"), "threshold": di.get("threshold"), "regime": di.get("regime")},
        "macro": {"confidence_level": macro_assessment.get("confidence_level"), "confidence_score": macro_assessment.get("confidence_score")},
        "triggers": (signal_explain.get("triggers") or [])[:10],
    }

    resp: Dict[str, Any] = {"ok": False, "error": "llm_not_called"}

    timeout_sec = 12.0
    try:
        timeout_sec = float(cfg.get("twitter_llm_note_timeout_sec", 12.0) or 12.0)
    except Exception:
        timeout_sec = 12.0
    try:
        v = str(os.environ.get("TWITTER_LLM_NOTE_TIMEOUT_SEC", "") or "").strip()
        if v:
            timeout_sec = float(v)
    except Exception:
        pass
    timeout_sec = float(max(4.0, min(60.0, float(timeout_sec))))

    def _llm_call() -> None:
        nonlocal resp
        resp = _agent_llm_chat(
            provider=provider,
            model=model,
            messages=[
                {"role": "system", "content": sys},
                {"role": "user", "content": json.dumps(user_obj, ensure_ascii=False)},
            ],
            timeout_sec=float(timeout_sec),
        )

    t = threading.Thread(target=_llm_call, daemon=True)
    t.start()
    t.join(timeout=float(timeout_sec) + 0.6)
    if t.is_alive():
        return {"ok": False, "error": "llm_timeout", "provider": provider, "model": model}

    if not bool(resp.get("ok")):
        return {"ok": False, "error": str(resp.get("error") or "llm_failed"), "provider": provider, "model": model}

    data = resp.get("data") if isinstance(resp.get("data"), dict) else {}
    raw = ""
    try:
        raw = str(((data.get("message") or {}) if isinstance(data.get("message"), dict) else {}).get("content") or "")
    except Exception:
        raw = ""
    try:
        parsed = _json_parse_loose(raw)
    except Exception as e:
        return {"ok": False, "error": "parse_error", "raw": raw[:800], "exception": str(e), "provider": provider, "model": model}

    note = ""
    if isinstance(parsed, dict) and isinstance(parsed.get("note"), str):
        note = parsed.get("note")
    note = _clip_str(note, 120)
    if not note:
        return {"ok": False, "error": "empty_note", "raw": raw[:800], "provider": provider, "model": model}
    return {"ok": True, "note": note, "raw": raw[:800], "provider": provider, "model": model}


