def _push_text_attach_trace_id(text: str, trace_id: str) -> str:
    msg = str(text or "").strip()
    tid = str(trace_id or "").strip()
    if not msg:
        return msg
    if not tid:
        return msg
    if tid in msg:
        return msg
    return (f"trace_id={tid}\n" + msg)[:4000]


def _push_redact_value(v: Any) -> Any:
    if v is None:
        return None
    if isinstance(v, (int, float, bool)):
        return v
    if isinstance(v, str):
        s = v
        s = re.sub(r"(?i)\b(bearer)\s+[a-z0-9\-\._=]{16,}", r"\\1 [REDACTED]", s)
        s = re.sub(r"(?i)\b(token|secret|password|passwd|api_key|apikey|access_key|private_key)\b\s*[:=]\s*[^\s,;]{8,}", r"\\1=[REDACTED]", s)
        s = re.sub(r"(?i)\b(aws_access_key_id)\b\s*[:=]\s*[A-Z0-9]{16,}", r"\\1=[REDACTED]", s)
        s = re.sub(r"(?i)\b(aws_secret_access_key)\b\s*[:=]\s*[A-Za-z0-9/+=]{20,}", r"\\1=[REDACTED]", s)
        s = re.sub(r"\bghp_[A-Za-z0-9]{20,}\b", "ghp_[REDACTED]", s)
        s = re.sub(r"\b(xox[baprs]-[A-Za-z0-9-]{10,})\b", "xox-[REDACTED]", s)
        s = re.sub(r"\bsk-[A-Za-z0-9]{16,}\b", "sk-[REDACTED]", s)
        return s
    if isinstance(v, dict):
        out: Dict[str, Any] = {}
        for k, vv in list(v.items())[:200]:
            kk = str(k)
            if re.search(r"(?i)(token|secret|password|passwd|api[_-]?key|private[_-]?key)", kk):
                out[kk] = "[REDACTED]"
            else:
                out[kk] = _push_redact_value(vv)
        return out
    if isinstance(v, list):
        return [_push_redact_value(x) for x in list(v)[:200]]
    return str(v)


def _push_sanitize_message_and_extras(
    *,
    message: str,
    extras: Dict[str, Any],
    trace_id: str,
    attach_trace_id: bool = True,
) -> Tuple[str, Dict[str, Any], Dict[str, Any]]:
    msg0 = str(message or "").strip()
    ex0 = (extras if isinstance(extras, dict) else {})
    msg_red = _push_redact_value(msg0)
    msg1 = (str(msg_red) if isinstance(msg_red, str) else msg0)
    if bool(attach_trace_id):
        msg1 = _push_text_attach_trace_id(msg1, trace_id)
    ex1 = _push_redact_value(ex0)
    meta = {"redacted": (msg1 != msg0) or (ex1 != ex0)}
    if not isinstance(ex1, dict):
        ex1 = {}
    return msg1, ex1, meta


def _push_retry_delay_ms(*, attempt: int, base_sec: float, max_sec: float, seed: Optional[str]) -> int:
    a = max(1, int(attempt))
    delay = float(base_sec) * (2.0 ** float(max(0, a - 1)))
    delay = min(float(max_sec), delay)
    j = 0.0
    try:
        h = hashlib.sha256((str(seed or "") + "|" + str(a)).encode("utf-8")).hexdigest()[:8]
        j = (int(h, 16) % 1000) / 1000.0
    except Exception:
        j = 0.0
    return int((delay + j) * 1000)


def _push_should_retry(*, ok: bool, status_code: Optional[int], error: Optional[str]) -> bool:
    if ok:
        return False
    sc = 0 if status_code is None else int(status_code or 0)
    if sc in (408, 425, 429):
        return True
    if 500 <= sc <= 599:
        return True
    err = str(error or "").strip().lower()
    if not err:
        return True
    for k in ("timeout", "timed out", "connection", "connect", "network", "temporarily", "try again"):
        if k in err:
            return True
    return False


def _push_requeue_envelope(channel: str, env: Dict[str, Any], *, attempt: int, next_try_ms: int) -> None:
    ch = str(channel or "").strip().lower()
    if not ch:
        return
    src = (env if isinstance(env, dict) else {})
    ts_ms = int(_now_ms())
    idem = None
    try:
        idem = str(src.get("idempotency_key") or "").strip() or None
    except Exception:
        idem = None
    eid = hashlib.sha256(f"{ts_ms}|{idem or uuid.uuid4().hex}".encode("utf-8")).hexdigest()[:32]
    out = dict(src)
    out["id"] = eid
    out["ts"] = ts_ms
    out["channel"] = ch
    out["attempt"] = int(attempt)
    out["next_try_ms"] = int(next_try_ms)
    _agent_outbox_append_jsonl(f"{ch}.jsonl", out)


def _push_p0_outbox_emit(*, trace_id: str, channel: str, severity: str, reason: str, env: Dict[str, Any], receipt: Optional[Dict[str, Any]] = None) -> None:
    ts_ms = int(_now_ms())
    item = {
        "id": uuid.uuid4().hex,
        "trace_id": str(trace_id or "").strip() or uuid.uuid4().hex,
        "ts": ts_ms,
        "type": "push.p0",
        "channel": str(channel or "").strip().lower(),
        "severity": str(severity or "").strip().lower(),
        "reason": str(reason or "").strip()[:400],
        "env": (env if isinstance(env, dict) else {}),
    }
    if isinstance(receipt, dict):
        item["receipt"] = receipt
    _agent_outbox_append_jsonl("p0_alerts.jsonl", item)


def _im_webhook_url() -> Optional[str]:
    v = _agent_push_cfg_str("im_webhook", None)
    return (v if v and v.lower().startswith("http") else None)


def _im_webhook_push_enabled() -> bool:
    if not _agent_push_cfg_bool("im_enabled", False):
        return False
    if requests is None:
        return False
    if _im_webhook_url() is None:
        return False
    try:
        if _governance_is_test_mode():
            return False
    except Exception:
        pass
    return True


def _im_webhook_send_text(*, text: str, trace_id: str, severity: str, extras: Dict[str, Any], timeout_sec: float = 12.0) -> Tuple[bool, Dict[str, Any]]:
    if requests is None:
        return False, {"error": "requests_not_available"}
    url = _im_webhook_url()
    if url is None:
        return False, {"error": "missing_im_webhook"}
    payload = {
        "trace_id": str(trace_id or "").strip(),
        "severity": str(severity or "info").strip().lower(),
        "message": str(text or ""),
        "extras": (extras if isinstance(extras, dict) else {}),
        "ts": int(_now_ms()),
    }
    try:
        resp = requests.post(url, json=payload, timeout=float(max(2.0, min(30.0, float(timeout_sec)))))
        status_code = int(getattr(resp, "status_code", 0) or 0)
        ok = 200 <= status_code < 300
        body: Any = None
        try:
            body = resp.json()
        except Exception:
            try:
                body = {"raw": str(getattr(resp, "text", "") or "")[:2000]}
            except Exception:
                body = {"raw": ""}
        return bool(ok), {"status_code": status_code, "body": body}
    except Exception as e:
        return False, {"error": str(e)}


def _alert_outbox_worker_enabled() -> bool:
    try:
        v = str(os.environ.get("ALERT_OUTBOX_WORKER_ENABLED", "1") or "1").strip().lower()
        return v in ("1", "true", "yes", "on")
    except Exception:
        return True


def _load_processed_alert_ids() -> set:
    done: set = set()
    q = _agent_outbox_dir() / "delivery_receipts.jsonl"
    if not q.exists():
        return done
    try:
        with open(q, "r", encoding="utf-8") as f:
            for line in f:
                s = line.strip("\n")
                if not s.strip():
                    continue
                try:
                    obj = json.loads(s)
                except Exception:
                    continue
                if not isinstance(obj, dict):
                    continue
                if str(obj.get("origin") or "").strip().lower() != "alert":
                    continue
                tid = obj.get("id")
                if tid is None:
                    continue
                done.add(str(tid))
    except Exception:
        return done
    return done


def _alert_outbox_worker_loop() -> None:
    processed = _load_processed_alert_ids()
    last_offset = 0
    outbox_dir = _agent_outbox_dir()
    outbox = outbox_dir / "alert.jsonl"
    receipts = outbox_dir / "delivery_receipts.jsonl"
    receipts_mtime_ms: Optional[int] = None
    while True:
        try:
            if not _alert_outbox_worker_enabled():
                time.sleep(2.0)
                continue

            try:
                if receipts.exists():
                    st = receipts.stat()
                    mt = int(st.st_mtime * 1000)
                    if receipts_mtime_ms is None or mt != receipts_mtime_ms:
                        processed = _load_processed_alert_ids()
                        receipts_mtime_ms = mt
            except Exception:
                pass

            if not outbox.exists():
                time.sleep(1.0)
                continue

            lines: List[str] = []
            try:
                with open(outbox, "r", encoding="utf-8") as f:
                    lines = f.readlines()
            except Exception:
                time.sleep(1.0)
                continue

            if last_offset > len(lines):
                last_offset = 0

            for i in range(last_offset, len(lines)):
                raw = lines[i].strip("\n")
                if not raw.strip():
                    last_offset = i + 1
                    continue
                try:
                    env = json.loads(raw)
                except Exception:
                    last_offset = i + 1
                    continue
                if not isinstance(env, dict):
                    last_offset = i + 1
                    continue
                if str(env.get("channel") or "").strip().lower() != "alert":
                    last_offset = i + 1
                    continue
                if str(env.get("type") or "").strip().lower() != "push.send":
                    last_offset = i + 1
                    continue
                eid = str(env.get("id") or "").strip()
                if not eid:
                    last_offset = i + 1
                    continue
                if eid in processed:
                    last_offset = i + 1
                    continue

                now_ms = int(_now_ms())
                next_try_ms = 0
                try:
                    next_try_ms = int(env.get("next_try_ms") or 0)
                except Exception:
                    next_try_ms = 0
                if next_try_ms > 0 and now_ms < next_try_ms:
                    _push_requeue_envelope("twitter", env, attempt=int(env.get("attempt") or 1), next_try_ms=int(next_try_ms))
                    processed.add(eid)
                    last_offset = i + 1
                    continue

                now_ms = int(_now_ms())
                next_try_ms = 0
                try:
                    next_try_ms = int(env.get("next_try_ms") or 0)
                except Exception:
                    next_try_ms = 0
                if next_try_ms > 0 and now_ms < next_try_ms:
                    _push_requeue_envelope("telegram", env, attempt=int(env.get("attempt") or 1), next_try_ms=int(next_try_ms))
                    processed.add(eid)
                    last_offset = i + 1
                    continue

                now_ms = int(_now_ms())
                next_try_ms = 0
                try:
                    next_try_ms = int(env.get("next_try_ms") or 0)
                except Exception:
                    next_try_ms = 0
                if next_try_ms > 0 and now_ms < next_try_ms:
                    _push_requeue_envelope("alert", env, attempt=int(env.get("attempt") or 1), next_try_ms=int(next_try_ms))
                    processed.add(eid)
                    last_offset = i + 1
                    continue

                trace_id = str(env.get("trace_id") or eid).strip() or eid
                sev = str(env.get("severity") or "info").strip().lower()
                idem = None
                try:
                    idem = str(env.get("idempotency_key") or "").strip() or None
                except Exception:
                    idem = None
                attempt = 1
                try:
                    attempt = int(env.get("attempt") or 1)
                except Exception:
                    attempt = 1

                expired = False
                try:
                    exp = env.get("expires_at")
                    if exp is not None and int(exp) > 0 and int(_now_ms()) > int(exp):
                        expired = True
                except Exception:
                    expired = False
                if expired:
                    receipt = {
                        "id": eid,
                        "trace_id": trace_id,
                        "origin": "alert",
                        "channel": "alert",
                        "ok": False,
                        "attempt": int(attempt),
                        "status_code": None,
                        "error": "expired",
                        "severity": sev,
                        "ts": int(_now_ms()),
                        "idempotency_key": idem,
                    }
                    _append_delivery_receipt(receipt)
                    _agent_push_audit("agent.push.expired", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "severity": sev, "idempotency_key": idem})
                    processed.add(eid)
                    last_offset = i + 1
                    continue

                msg0 = str(env.get("message") or "").strip()
                ex0 = env.get("extras") if isinstance(env.get("extras"), dict) else {}
                msg, ex, s_meta = _push_sanitize_message_and_extras(message=msg0, extras=ex0, trace_id=trace_id, attach_trace_id=False)
                msg_with_trace = _push_text_attach_trace_id(msg, trace_id)

                chain0 = env.get("fallback_chain") if isinstance(env.get("fallback_chain"), list) else None
                if chain0 is None:
                    chain0 = _agent_push_cfg().get("alert_fallback_chain") if isinstance(_agent_push_cfg().get("alert_fallback_chain"), list) else None
                if chain0 is None:
                    chain0 = ["telegram", "im_webhook", "twitter", "email", "sms"]
                chain = [str(x).strip().lower() for x in chain0 if str(x or "").strip()]
                if not chain:
                    chain = ["telegram"]

                max_attempts = _agent_push_cfg_int("alert_max_attempts", 5, lo=1, hi=20)
                base_sec = _agent_push_cfg_float("alert_retry_base_sec", 3.0, lo=0.2, hi=120.0)
                max_sec = _agent_push_cfg_float("alert_retry_max_sec", 120.0, lo=1.0, hi=3600.0)

                delivered = False
                last_fail: Optional[Dict[str, Any]] = None
                for ch in chain:
                    ok_th, th_meta = _agent_push_channel_throttle_ok(channel=ch, idempotency_key=idem, now_ms=int(_now_ms()))
                    if not ok_th:
                        if str(th_meta.get("reason") or "") == "duplicate_idempotency_key":
                            receipt = {
                                "id": eid,
                                "trace_id": trace_id,
                                "origin": "alert",
                                "channel": ch,
                                "ok": True,
                                "attempt": int(attempt),
                                "status_code": None,
                                "error": None,
                                "severity": sev,
                                "ts": int(_now_ms()),
                                "idempotency_key": idem,
                                "skipped": True,
                                "skip_reason": "duplicate_idempotency_key",
                            }
                            _append_delivery_receipt(receipt)
                            delivered = True
                            last_fail = None
                            break
                        last_fail = {"channel": ch, "error": f"throttled:{str(th_meta.get('reason') or '')}"}
                        continue

                    ok = False
                    out: Dict[str, Any] = {}
                    if ch == "telegram":
                        if not _telegram_push_enabled():
                            ok, out = False, {"error": "telegram_disabled"}
                        else:
                            ok, out = _telegram_send_text(text=msg_with_trace)
                    elif ch == "twitter":
                        if not _twitter_push_enabled():
                            ok, out = False, {"error": "twitter_disabled"}
                        else:
                            ok, out = _twitter_send_text(msg)
                    elif ch in ("im", "im_webhook"):
                        if not _im_webhook_push_enabled():
                            ok, out = False, {"error": "im_webhook_disabled"}
                        else:
                            ok, out = _im_webhook_send_text(text=msg_with_trace, trace_id=trace_id, severity=sev, extras=ex)
                    elif ch == "email":
                        ok, out = False, {"error": "email_not_configured"}
                    elif ch == "sms":
                        ok, out = False, {"error": "sms_not_configured"}
                    else:
                        ok, out = False, {"error": "unknown_channel"}

                    status_code = None
                    try:
                        status_code = (None if out.get("status_code") is None else int(out.get("status_code") or 0))
                    except Exception:
                        status_code = None
                    err_s = None if ok else str(out.get("error") or out.get("body") or "send_failed")

                    provider_msg_id = None
                    if ch == "telegram":
                        provider_msg_id = (None if out.get("message_id") is None else str(out.get("message_id")))
                    elif ch == "twitter":
                        provider_msg_id = (None if out.get("tweet_id") is None else str(out.get("tweet_id")))

                    receipt = {
                        "id": eid,
                        "trace_id": trace_id,
                        "origin": "alert",
                        "channel": ch,
                        "ok": bool(ok),
                        "attempt": int(attempt),
                        "status_code": status_code,
                        "error": (None if ok else _clip_str(err_s, 1200)),
                        "severity": sev,
                        "ts": int(_now_ms()),
                        "idempotency_key": idem,
                        "provider_msg_id": provider_msg_id,
                        "sanitized": bool(s_meta.get("redacted")),
                    }
                    _append_delivery_receipt(receipt)
                    _agent_push_audit("agent.push.attempt", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "origin": "alert", "channel": ch, "ok": bool(ok), "attempt": int(attempt), "idempotency_key": idem, "status_code": status_code})

                    if ok:
                        delivered = True
                        last_fail = None
                        break
                    last_fail = {"channel": ch, "status_code": status_code, "error": err_s}

                if delivered:
                    _agent_push_audit("agent.push.delivered", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "origin": "alert", "severity": sev, "idempotency_key": idem})
                    processed.add(eid)
                    last_offset = i + 1
                    time.sleep(0.3)
                    continue

                sc = None
                err = None
                if isinstance(last_fail, dict):
                    sc = last_fail.get("status_code")
                    err = last_fail.get("error")
                do_retry = _push_should_retry(ok=False, status_code=(None if sc is None else int(sc or 0)), error=(None if err is None else str(err)))
                if do_retry and int(attempt) < int(max_attempts):
                    delay_ms = _push_retry_delay_ms(attempt=int(attempt), base_sec=float(base_sec), max_sec=float(max_sec), seed=str(idem or trace_id))
                    _push_requeue_envelope("alert", env, attempt=int(attempt) + 1, next_try_ms=int(_now_ms()) + int(delay_ms))
                    _agent_push_audit("agent.push.retry_scheduled", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "origin": "alert", "attempt": int(attempt), "next_try_ms": int(_now_ms()) + int(delay_ms), "idempotency_key": idem, "last_fail": last_fail})
                else:
                    _push_p0_outbox_emit(trace_id=trace_id, channel="alert", severity=sev, reason="delivery_failed", env=env, receipt=(last_fail if isinstance(last_fail, dict) else None))
                    _agent_push_audit("agent.push.failed", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "origin": "alert", "attempt": int(attempt), "idempotency_key": idem, "last_fail": last_fail})

                processed.add(eid)
                last_offset = i + 1
                time.sleep(0.5)

            time.sleep(0.8)
        except Exception:
            time.sleep(2.0)


def _ensure_alert_outbox_worker_started() -> None:
    try:
        flag = bool(globals().get("_ALERT_OUTBOX_STARTED", False))
    except Exception:
        flag = False
    if flag:
        return
    try:
        t = threading.Thread(target=_alert_outbox_worker_loop, daemon=True)
        t.start()
        globals()["_ALERT_OUTBOX_STARTED"] = True
    except Exception:
        pass


def _agent_push_cfg() -> Dict[str, Any]:
    cfg = CONFIG.get("agent_push") or {}
    return (cfg if isinstance(cfg, dict) else {})


def _agent_push_cfg_bool(key: str, default: bool) -> bool:
    cfg = _agent_push_cfg()
    try:
        v = cfg.get(key)
        if v is None:
            return bool(default)
        return bool(v)
    except Exception:
        return bool(default)


def _agent_push_cfg_int(key: str, default: int, *, lo: int, hi: int) -> int:
    cfg = _agent_push_cfg()
    try:
        v = cfg.get(key)
        if v is None:
            return int(default)
        x = int(v)
        return int(max(lo, min(hi, x)))
    except Exception:
        return int(max(lo, min(hi, int(default))))


def _agent_push_cfg_float(key: str, default: float, *, lo: float, hi: float) -> float:
    cfg = _agent_push_cfg()
    try:
        v = cfg.get(key)
        if v is None:
            return float(default)
        x = float(v)
        if not math.isfinite(x):
            return float(default)
        return float(max(lo, min(hi, x)))
    except Exception:
        return float(max(lo, min(hi, float(default))))


def _agent_push_cfg_str(key: str, default: Optional[str] = None) -> Optional[str]:
    cfg = _agent_push_cfg()
    try:
        v = cfg.get(key)
        if v is None:
            return default
        s = str(v).strip()
        return (s if s else default)
    except Exception:
        return default


def _agent_delivery_receipts_tail(tail_bytes: int = 2_000_000, max_lines: int = 40_000) -> List[Dict[str, Any]]:
    try:
        return _agent_jsonl_tail(_agent_outbox_dir() / "delivery_receipts.jsonl", tail_bytes=tail_bytes, max_lines=max_lines)
    except Exception:
        return []


def _agent_push_channel_throttle_ok(*, channel: str, idempotency_key: Optional[str], now_ms: int) -> Tuple[bool, Dict[str, Any]]:
    ch = str(channel or "").strip().lower()
    if not ch:
        return False, {"reason": "missing_channel"}

    base_sec = _agent_push_cfg_int("alert_throttle_base_sec", 15, lo=1, hi=3600)
    max_sec = _agent_push_cfg_int("alert_throttle_max_sec", 600, lo=1, hi=6 * 3600)
    burst = _agent_push_cfg_int("alert_throttle_burst", 3, lo=0, hi=50)

    min_interval_sec = _agent_push_cfg_int(f"{ch}_min_interval_sec", 3, lo=0, hi=3600)
    rate_window_sec = _agent_push_cfg_int(f"{ch}_rate_window_sec", 3600, lo=60, hi=24 * 3600)
    max_per_hour = _agent_push_cfg_int(f"{ch}_max_per_hour", 120, lo=1, hi=10_000)

    st = TRACKER_STATE.get("agent_push_throttle")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["agent_push_throttle"] = st

    state_key = f"channel:{ch}"
    rec = st.get(state_key)
    if not isinstance(rec, dict):
        rec = {"strike": 0, "next_allowed_ms": 0, "last_sent_ms": 0, "burst_left": int(burst)}
        st[state_key] = rec

    receipts = _agent_delivery_receipts_tail()
    if idempotency_key:
        for r in receipts:
            if not isinstance(r, dict):
                continue
            if str(r.get("channel") or "").strip().lower() != ch:
                continue
            if str(r.get("idempotency_key") or "").strip() != str(idempotency_key):
                continue
            if bool(r.get("ok")):
                return False, {"reason": "duplicate_idempotency_key"}

    since_ms = int(now_ms) - int(rate_window_sec * 1000)
    cnt = 0
    last_ok_ts = 0
    for r in receipts:
        if not isinstance(r, dict):
            continue
        if str(r.get("channel") or "").strip().lower() != ch:
            continue
        sc = r.get("status_code")
        if sc is None:
            continue
        ts = int(r.get("ts") or 0)
        if ts <= 0 or ts < since_ms:
            continue
        cnt += 1
        if bool(r.get("ok")) and ts > last_ok_ts:
            last_ok_ts = ts

    try:
        next_allowed0 = int(rec.get("next_allowed_ms") or 0)
    except Exception:
        next_allowed0 = 0
    if next_allowed0 > int(now_ms) and int(cnt) < int(max_per_hour) and int(last_ok_ts) <= 0:
        rec["strike"] = 0
        rec["next_allowed_ms"] = 0
        st[state_key] = rec
        next_allowed0 = 0
    if next_allowed0 > int(now_ms):
        return False, {"reason": "backoff", "next_allowed_ms": int(next_allowed0)}

    if int(min_interval_sec) > 0 and int(last_ok_ts) > 0 and (int(now_ms) - int(last_ok_ts)) < int(min_interval_sec * 1000):
        return False, {"reason": "min_interval", "last_ok_ts": int(last_ok_ts), "min_interval_sec": int(min_interval_sec), "next_allowed_ms": int(last_ok_ts) + int(min_interval_sec * 1000)}

    if cnt >= int(max_per_hour):
        try:
            strike = int(rec.get("strike") or 0) + 1
        except Exception:
            strike = 1
        delay = int(min(int(max_sec), int(base_sec) * (2 ** max(0, strike - 1))))
        rec["strike"] = int(strike)
        rec["next_allowed_ms"] = int(now_ms) + int(delay * 1000)
        st[state_key] = rec
        return False, {"reason": "rate_limit", "count": int(cnt), "window_sec": int(rate_window_sec), "next_allowed_ms": int(rec.get("next_allowed_ms") or 0)}

    if int(burst) > 0:
        try:
            bl = int(rec.get("burst_left") if rec.get("burst_left") is not None else int(burst))
        except Exception:
            bl = int(burst)
        if bl <= 0 and last_ok_ts > 0 and (int(now_ms) - int(last_ok_ts)) < int(base_sec * 1000):
            return False, {"reason": "burst_exhausted", "next_allowed_ms": int(last_ok_ts) + int(base_sec * 1000)}

    return True, {"reason": "ok"}


def _telegram_env_token() -> Optional[str]:
    try:
        v = str(os.environ.get("TELEGRAM_BOT_TOKEN", "") or "").strip()
        return (v if v else None)
    except Exception:
        return None


def _telegram_chat_id() -> Optional[str]:
    v = _agent_push_cfg_str("telegram_chat_id", None)
    if v:
        return v
    try:
        v2 = str(os.environ.get("TELEGRAM_CHAT_ID", "") or "").strip()
        return (v2 if v2 else None)
    except Exception:
        return None


def _telegram_push_enabled() -> bool:
    try:
        v = str(os.environ.get("TELEGRAM_ENABLED", "") or "").strip().lower()
        if v:
            if v not in ("1", "true", "yes", "on"):
                return False
    except Exception:
        v = ""
    if not v:
        if not _agent_push_cfg_bool("telegram_enabled", False):
            return False
    if _telegram_env_token() is None:
        return False
    if _telegram_chat_id() is None:
        return False
    try:
        if _governance_is_test_mode():
            return False
    except Exception:
        pass
    return True


def _telegram_outbox_worker_enabled() -> bool:
    try:
        v = str(os.environ.get("TELEGRAM_OUTBOX_WORKER_ENABLED", "1") or "1").strip().lower()
        return v in ("1", "true", "yes", "on")
    except Exception:
        return True


def _load_processed_telegram_ids() -> set:
    done: set = set()
    q = _agent_outbox_dir() / "delivery_receipts.jsonl"
    if not q.exists():
        return done
    try:
        with open(q, "r", encoding="utf-8") as f:
            for line in f:
                s = line.strip("\n")
                if not s.strip():
                    continue
                try:
                    obj = json.loads(s)
                except Exception:
                    continue
                if not isinstance(obj, dict):
                    continue
                if str(obj.get("channel") or "").strip().lower() != "telegram":
                    continue
                tid = obj.get("id")
                if tid is None:
                    continue
                try:
                    done.add(str(tid))
                except Exception:
                    pass
    except Exception:
        return done
    return done


def _telegram_send_text(*, text: str, timeout_sec: float = 20.0) -> Tuple[bool, Dict[str, Any]]:
    if requests is None:
        return False, {"error": "requests_not_available"}
    tok = _telegram_env_token()
    if tok is None:
        return False, {"error": "missing_telegram_token"}
    chat_id = _telegram_chat_id()
    if chat_id is None:
        return False, {"error": "missing_telegram_chat_id"}
    txt = str(text or "").strip()
    if not txt:
        return False, {"error": "empty_text"}
    url = f"https://api.telegram.org/bot{tok}/sendMessage"
    payload = {"chat_id": chat_id, "text": txt, "disable_web_page_preview": True}
    try:
        resp = requests.post(url, json=payload, timeout=float(max(3.0, min(60.0, float(timeout_sec)))))
        status_code = int(getattr(resp, "status_code", 0) or 0)
        body: Any = None
        try:
            body = resp.json()
        except Exception:
            try:
                body = {"raw": str(getattr(resp, "text", "") or "")[:2000]}
            except Exception:
                body = {"raw": ""}
        ok = 200 <= status_code < 300 and isinstance(body, dict) and bool(body.get("ok"))
        out = {"status_code": status_code, "body": body}
        if ok and isinstance(body, dict):
            res = body.get("result")
            if isinstance(res, dict) and res.get("message_id") is not None:
                out["message_id"] = int(res.get("message_id"))
        return ok, out
    except Exception as e:
        err = str(e)
        try:
            if tok:
                err = err.replace(f"bot{tok}", "bot***")
                err = err.replace(tok, "***")
        except Exception:
            pass
        return False, {"error": err}


def _telegram_outbox_worker_loop() -> None:
    processed = _load_processed_telegram_ids()
    last_offset = 0
    outbox_dir = _agent_outbox_dir()
    outbox = outbox_dir / "telegram.jsonl"
    receipts = outbox_dir / "delivery_receipts.jsonl"
    receipts_mtime_ms: Optional[int] = None
    while True:
        try:
            if not _telegram_outbox_worker_enabled() or not _telegram_push_enabled():
                time.sleep(2.0)
                continue

            try:
                if receipts.exists():
                    st = receipts.stat()
                    mt = int(st.st_mtime * 1000)
                    if receipts_mtime_ms is None or mt != receipts_mtime_ms:
                        processed = _load_processed_telegram_ids()
                        receipts_mtime_ms = mt
            except Exception:
                pass
            if not outbox.exists():
                time.sleep(1.0)
                continue

            lines: List[str] = []
            try:
                with open(outbox, "r", encoding="utf-8") as f:
                    lines = f.readlines()
            except Exception:
                time.sleep(1.0)
                continue

            if last_offset > len(lines):
                last_offset = 0

            for i in range(last_offset, len(lines)):
                raw = lines[i].strip("\n")
                if not raw.strip():
                    last_offset = i + 1
                    continue
                try:
                    env = json.loads(raw)
                except Exception:
                    last_offset = i + 1
                    continue
                if not isinstance(env, dict):
                    last_offset = i + 1
                    continue
                if str(env.get("channel") or "").strip().lower() != "telegram":
                    last_offset = i + 1
                    continue
                if str(env.get("type") or "").strip().lower() != "push.send":
                    last_offset = i + 1
                    continue

                eid = str(env.get("id") or "").strip()
                if not eid:
                    last_offset = i + 1
                    continue
                if eid in processed:
                    last_offset = i + 1
                    continue

                trace_id = str(env.get("trace_id") or eid).strip() or eid
                msg0 = str(env.get("message") or "").strip()
                sev = str(env.get("severity") or "info").strip().lower()
                idem = None
                try:
                    idem = str(env.get("idempotency_key") or "").strip() or None
                except Exception:
                    idem = None

                attempt = 1
                try:
                    attempt = int(env.get("attempt") or 1)
                except Exception:
                    attempt = 1

                expired = False
                try:
                    exp = env.get("expires_at")
                    if exp is not None and int(exp) > 0 and int(_now_ms()) > int(exp):
                        expired = True
                except Exception:
                    expired = False
                if expired:
                    receipt = {
                        "id": eid,
                        "trace_id": trace_id,
                        "channel": "telegram",
                        "ok": False,
                        "attempt": int(attempt),
                        "status_code": None,
                        "error": "expired",
                        "severity": sev,
                        "ts": int(_now_ms()),
                        "idempotency_key": idem,
                    }
                    _append_delivery_receipt(receipt)
                    _agent_push_audit("agent.push.expired", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "channel": "telegram", "attempt": int(attempt), "idempotency_key": idem, "severity": sev})
                    processed.add(eid)
                    last_offset = i + 1
                    continue

                ok_th, th_meta = _agent_push_channel_throttle_ok(channel="telegram", idempotency_key=idem, now_ms=int(_now_ms()))
                if not ok_th:
                    if str(th_meta.get("reason") or "") == "duplicate_idempotency_key":
                        receipt = {
                            "id": eid,
                            "trace_id": trace_id,
                            "channel": "telegram",
                            "ok": True,
                            "attempt": int(attempt),
                            "status_code": None,
                            "error": None,
                            "severity": sev,
                            "ts": int(_now_ms()),
                            "idempotency_key": idem,
                            "skipped": True,
                            "skip_reason": "duplicate_idempotency_key",
                        }
                        _append_delivery_receipt(receipt)
                        _agent_push_audit("agent.push.skipped", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "channel": "telegram", "attempt": int(attempt), "idempotency_key": idem, "reason": "duplicate_idempotency_key"})
                        processed.add(eid)
                        last_offset = i + 1
                        continue

                    next_allowed = None
                    try:
                        next_allowed = (None if th_meta.get("next_allowed_ms") is None else int(th_meta.get("next_allowed_ms") or 0))
                    except Exception:
                        next_allowed = None
                    if next_allowed is not None and int(next_allowed) > int(_now_ms()):
                        _push_requeue_envelope("telegram", env, attempt=int(attempt), next_try_ms=int(next_allowed))
                        _agent_push_audit("agent.push.throttled", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "channel": "telegram", "attempt": int(attempt), "idempotency_key": idem, "throttle": th_meta})
                        processed.add(eid)
                        last_offset = i + 1
                        continue

                    receipt = {
                        "id": eid,
                        "trace_id": trace_id,
                        "channel": "telegram",
                        "ok": False,
                        "attempt": int(attempt),
                        "status_code": None,
                        "error": f"throttled:{str(th_meta.get('reason') or '')}",
                        "severity": sev,
                        "ts": int(_now_ms()),
                        "idempotency_key": idem,
                    }
                    _append_delivery_receipt(receipt)
                    _agent_push_audit("agent.push.throttled", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "channel": "telegram", "attempt": int(attempt), "idempotency_key": idem, "throttle": th_meta})
                    processed.add(eid)
                    last_offset = i + 1
                    continue

                ex0 = env.get("extras") if isinstance(env.get("extras"), dict) else {}
                msg, _ex, s_meta = _push_sanitize_message_and_extras(message=msg0, extras=ex0, trace_id=trace_id)
                ok, out = _telegram_send_text(text=msg)
                receipt = {
                    "id": eid,
                    "trace_id": trace_id,
                    "channel": "telegram",
                    "ok": bool(ok),
                    "attempt": int(attempt),
                    "status_code": (None if out.get("status_code") is None else int(out.get("status_code") or 0)),
                    "error": (None if ok else str(out.get("error") or out.get("body") or "send_failed")[:1200]),
                    "severity": sev,
                    "ts": int(_now_ms()),
                    "idempotency_key": idem,
                    "provider_msg_id": (None if out.get("message_id") is None else str(out.get("message_id"))),
                    "sanitized": bool(s_meta.get("redacted")),
                }
                _append_delivery_receipt(receipt)
                _agent_push_audit("agent.push.attempt", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "channel": "telegram", "ok": bool(ok), "attempt": int(attempt), "idempotency_key": idem, "status_code": receipt.get("status_code")})
                if not bool(ok):
                    sc = receipt.get("status_code")
                    err = receipt.get("error")
                    max_attempts = _agent_push_cfg_int("telegram_max_attempts", 4, lo=1, hi=20)
                    if _push_should_retry(ok=False, status_code=(None if sc is None else int(sc or 0)), error=(None if err is None else str(err))) and int(attempt) < int(max_attempts):
                        delay_ms = _push_retry_delay_ms(attempt=int(attempt), base_sec=float(_agent_push_cfg_float("telegram_retry_base_sec", 2.0, lo=0.2, hi=120.0)), max_sec=float(_agent_push_cfg_float("telegram_retry_max_sec", 60.0, lo=1.0, hi=3600.0)), seed=str(idem or trace_id))
                        _push_requeue_envelope("telegram", env, attempt=int(attempt) + 1, next_try_ms=int(_now_ms()) + int(delay_ms))
                        _agent_push_audit("agent.push.retry_scheduled", ts_ms=int(_now_ms()), payload={"trace_id": trace_id, "id": eid, "channel": "telegram", "attempt": int(attempt), "next_try_ms": int(_now_ms()) + int(delay_ms), "idempotency_key": idem})
                    else:
                        _push_p0_outbox_emit(trace_id=trace_id, channel="telegram", severity=sev, reason="delivery_failed", env=env, receipt=receipt)
                processed.add(eid)
                last_offset = i + 1
                time.sleep(0.8)

            time.sleep(0.8)
        except Exception:
            time.sleep(2.0)


def _ensure_telegram_outbox_worker_started() -> None:
    try:
        flag = bool(globals().get("_TELEGRAM_OUTBOX_STARTED", False))
    except Exception:
        flag = False
    if flag:
        return
    try:
        t = threading.Thread(target=_telegram_outbox_worker_loop, daemon=True)
        t.start()
        globals()["_TELEGRAM_OUTBOX_STARTED"] = True
    except Exception:
        pass


