@app.route("/agent/twitter/auth/set", methods=["POST"])
def agent_twitter_auth_set():
    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="agent.twitter.auth.set")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    if (not _is_local_request()) and (not bool(data.get("confirm_live", False))):
        return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms())}), 400

    def _get_str(*keys: str) -> Optional[str]:
        for k in keys:
            try:
                v = data.get(k)
            except Exception:
                v = None
            if v is None:
                continue
            s = str(v).strip()
            if s:
                return s
        return None

    def _maybe_set(env_key: str, v: Optional[str], set_list: List[str]) -> None:
        if v is None:
            return
        try:
            os.environ[env_key] = v
            set_list.append(env_key)
        except Exception:
            pass

    def _maybe_clear(env_key: str, clear_list: List[str]) -> None:
        try:
            if env_key in os.environ:
                del os.environ[env_key]
                clear_list.append(env_key)
        except Exception:
            pass

    do_clear = False
    try:
        do_clear = bool(data.get("clear", False))
    except Exception:
        do_clear = False

    set_keys: List[str] = []
    cleared_keys: List[str] = []

    if do_clear:
        for k in [
            "TWITTER_BEARER_TOKEN",
            "TWITTER_TOKEN",
            "TWITTER_CONSUMER_KEY",
            "TWITTER_CONSUMER_SECRET",
            "TWITTER_ACCESS_TOKEN",
            "TWITTER_ACCESS_TOKEN_SECRET",
        ]:
            _maybe_clear(k, cleared_keys)

    _maybe_set("TWITTER_BEARER_TOKEN", _get_str("bearer_token", "TWITTER_BEARER_TOKEN", "TWITTER_TOKEN", "bearer"), set_keys)
    _maybe_set("TWITTER_CONSUMER_KEY", _get_str("consumer_key", "TWITTER_CONSUMER_KEY", "consumerKey", "api_key"), set_keys)
    _maybe_set("TWITTER_CONSUMER_SECRET", _get_str("consumer_secret", "TWITTER_CONSUMER_SECRET", "consumerSecret", "api_key_secret"), set_keys)
    _maybe_set("TWITTER_ACCESS_TOKEN", _get_str("access_token", "TWITTER_ACCESS_TOKEN", "accessToken"), set_keys)
    _maybe_set("TWITTER_ACCESS_TOKEN_SECRET", _get_str("access_token_secret", "TWITTER_ACCESS_TOKEN_SECRET", "accessTokenSecret"), set_keys)

    mode = _twitter_auth_mode()
    miss = _twitter_missing_credentials()
    return jsonify({
        "ok": True,
        "set": set_keys,
        "cleared": cleared_keys,
        "auth_mode": mode,
        "has_bearer": bool(miss.get("has_bearer")),
        "has_oauth1": bool(miss.get("has_oauth1")),
        "missing_env": miss.get("missing_env") if isinstance(miss.get("missing_env"), list) else [],
        "trace_id": trace_id,
        "approval_id": approval_id,
        "ts": int(_now_ms()),
    })


@app.route("/agent/audit/actions", methods=["POST"])
def agent_audit_actions():
    if not _agent_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    items = data.get("items")
    out: List[Dict[str, Any]] = []
    if isinstance(items, list):
        for it in items:
            if isinstance(it, dict):
                out.append({
                    "name": str(it.get("name") or ""),
                    "ts": int(it.get("ts") or _now_ms()),
                    "payload": it.get("payload") if isinstance(it.get("payload"), dict) else {},
                })
    else:
        name = data.get("name")
        payload = data.get("payload")
        out.append({
            "name": str(name or ""),
            "ts": int(data.get("ts") or _now_ms()),
            "payload": payload if isinstance(payload, dict) else {},
        })
    if not out:
        return jsonify({"ok": False, "error": "no_items"}), 400
    n = 0
    try:
        for it in out:
            _agent_outbox_append_jsonl("audit_actions.jsonl", it)
            n += 1
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500
    return jsonify({"ok": True, "saved": int(n), "ts": int(_now_ms())})


@app.route("/agent/push/send", methods=["POST"])
def agent_push_send():
    if not _agent_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    channel = str(data.get("channel") or "").strip().lower()
    message = str(data.get("message") or "").strip()
    severity = str(data.get("severity") or "info").strip().lower()
    extras = data.get("extras") if isinstance(data.get("extras"), dict) else {}
    if not channel or not message:
        return jsonify({"ok": False, "error": "missing_channel_or_message"}), 400

    trace_id = None
    try:
        trace_id = str(data.get("trace_id") or extras.get("trace_id") or "").strip() or None
    except Exception:
        trace_id = None
    idempotency_key = None
    try:
        idempotency_key = str(data.get("idempotency_key") or extras.get("idempotency_key") or "").strip() or None
    except Exception:
        idempotency_key = None

    ts_ms = int(_now_ms())
    env_id = None
    try:
        env_id = str(os.environ.get("AGENT_ENV", "") or "").strip() or None
    except Exception:
        env_id = None

    if not idempotency_key:
        try:
            stable = json.dumps({"channel": channel, "message": message, "severity": severity, "extras": extras}, sort_keys=True, ensure_ascii=False)
            idempotency_key = hashlib.sha256(stable.encode("utf-8")).hexdigest()
        except Exception:
            idempotency_key = hashlib.sha256(f"{channel}|{message}|{severity}".encode("utf-8")).hexdigest()

    event_id = hashlib.sha256(f"{ts_ms}|{idempotency_key}".encode("utf-8")).hexdigest()[:32]
    if not trace_id:
        trace_id = event_id

    envelope = {
        "id": event_id,
        "trace_id": trace_id,
        "ts": ts_ms,
        "type": "push.send",
        "channel": channel,
        "severity": severity,
        "message": message,
        "extras": extras,
        "idempotency_key": idempotency_key,
    }
    if env_id:
        envelope["env"] = env_id

    name = f"{channel}.jsonl" if channel else "unknown.jsonl"
    try:
        _agent_outbox_append_jsonl(name, envelope)
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "channel": channel, "ts": int(_now_ms())}), 500

    return jsonify({"ok": True, "queued": True, "id": event_id, "trace_id": trace_id, "channel": channel, "ts": int(_now_ms())})


@app.route("/agent/pressure/exec_failure", methods=["POST"])
def agent_pressure_exec_failure():
    if not _agent_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    try:
        n = int(data.get("n") or 50)
    except Exception:
        n = 50
    n = max(1, min(5000, int(n)))

    path = str(data.get("path") or "/execution/pairs/btceth/market_close").strip() or "/execution/pairs/btceth/market_close"
    try:
        hs = int(data.get("http_status") or 502)
    except Exception:
        hs = 502
    hs = max(500, min(599, int(hs)))
    pair = (None if data.get("pair") is None else str(data.get("pair") or "").strip().upper())
    if pair is not None and not pair:
        pair = None
    strategy_id = (None if data.get("strategy_id") is None else str(data.get("strategy_id") or "").strip())
    if strategy_id is not None and not strategy_id:
        strategy_id = None

    try:
        span_ms = int(data.get("span_ms") or 30_000)
    except Exception:
        span_ms = 30_000
    span_ms = max(0, min(10 * 60_000, int(span_ms)))
    step_ms = (0 if n <= 1 else int(span_ms // max(1, n - 1)))

    now_ms = int(_now_ms())
    items_all = TRACKER_STATE.get("system_monitor_exec_failures")
    st_list: List[Dict[str, Any]] = (items_all if isinstance(items_all, list) else [])
    if not isinstance(items_all, list):
        TRACKER_STATE["system_monitor_exec_failures"] = st_list

    base = json.dumps({"path": path, "pair": pair, "strategy_id": strategy_id, "hs": hs, "ts": now_ms}, sort_keys=True, ensure_ascii=False)
    base_key = hashlib.sha256(base.encode("utf-8")).hexdigest()[:16]

    inserted = 0
    for i in range(n):
        ts = int(now_ms) - int(step_ms) * int(max(0, (n - 1 - i)))
        tid = hashlib.sha256(f"pressure|exec_failure|{base_key}|{i}|{ts}".encode("utf-8")).hexdigest()[:32]
        item = {
            "ts": int(ts),
            "trace_id": tid,
            "idempotency_key": f"pressure|exec_failure|{base_key}",
            "http_status": int(hs),
            "path": path,
            "tag": "pressure_exec_failure",
            "pair": pair,
            "pairs": ([pair] if pair else None),
            "strategy_id": strategy_id,
            "system_id": "pressure",
            "resp": {"ok": False, "error": "pressure_injected"},
        }
        st_list.append(item)
        inserted += 1

    try:
        max_n = int(CONFIG.get("system_monitor_exec_failure_max_keep", 800) or 800)
    except Exception:
        max_n = 800
    max_n = max(50, min(5000, int(max_n)))
    if len(st_list) > max_n:
        try:
            TRACKER_STATE["system_monitor_exec_failures"] = list(st_list[-max_n:])
        except Exception:
            pass

    try:
        st = _system_monitor_exec_failure_state_get()
        st["last_scan_ms"] = 0
    except Exception:
        pass
    try:
        _system_monitor_exec_failure_process(int(_now_ms()))
    except Exception:
        pass

    return jsonify({"ok": True, "inserted": int(inserted), "path": path, "http_status": int(hs), "pair": pair, "strategy_id": strategy_id, "ts": int(_now_ms())})


@app.route("/agent/redteam/prompt_injection", methods=["POST"])
def agent_redteam_prompt_injection():
    data = request.get_json(force=True) or {}
    mode = str(data.get("mode") or "strip_only").strip().lower()
    if mode not in ("strip_only", "emit", "emit_and_push"):
        mode = "strip_only"
    if mode == "strip_only":
        if not _agent_read_auth_ok():
            return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    else:
        if not _agent_write_auth_ok():
            return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403

    text = data.get("text")
    r = _agent_external_text_strip_instructions(text, max_chars=4000)
    cleaned = str(r.get("cleaned_text") or "")
    preview = cleaned[:240]
    out = {
        "ok": True,
        "mode": mode,
        "sha256": r.get("sha256"),
        "dropped": int(r.get("dropped") or 0),
        "kept": int(r.get("kept") or 0),
        "truncated": bool(r.get("truncated")),
        "cleaned_preview": preview,
        "ts": int(_now_ms()),
    }

    if mode in ("emit", "emit_and_push"):
        now_ms = int(_now_ms())
        trace_id = hashlib.sha256(f"redteam|prompt_injection|{str(r.get('sha256') or '')}|{now_ms}".encode("utf-8")).hexdigest()[:32]
        _agent_emit_envelope_event(
            event="redteam.prompt_injection",
            trace_id=trace_id,
            severity="warn",
            intent_level="L0",
            ts_ms=now_ms,
            inputs={"mode": mode, "len": int(len(str(text or ""))), "sha256": r.get("sha256")},
            evidence=[{"type": "prompt", "source": "redteam", "cleaned_preview": preview}],
            outputs={"cleaned_sha256": hashlib.sha256(cleaned.encode("utf-8")).hexdigest(), "dropped": int(r.get("dropped") or 0), "kept": int(r.get("kept") or 0), "truncated": bool(r.get("truncated"))},
            doc_refs=_agent_doc_refs_48_default(),
        )
        out["trace_id"] = trace_id

    return jsonify(out), 200


def _agent_outbox_append(name: str, item: Dict[str, Any]) -> bool:
    if not name or "/" in name or "\\" in name or ".." in name:
        return False
    try:
        _agent_outbox_append_jsonl(name, item)
        return True
    except Exception:
        return False


def _agent_ollama_chat_url() -> str:
    try:
        u = str(os.environ.get("AGENT_OLLAMA_URL", "") or "").strip()
        if u:
            return u
    except Exception:
        pass
    try:
        u2 = str(CONFIG.get("agent_ollama_url") or "").strip()
        if u2:
            return u2
    except Exception:
        pass
    return "http://127.0.0.1:11434/api/chat"


def _agent_ollama_base_url() -> str:
    chat_url = _agent_ollama_chat_url()
    try:
        pr = urllib_parse.urlparse(str(chat_url or "").strip())
        if pr.scheme and pr.netloc:
            return f"{pr.scheme}://{pr.netloc}"
    except Exception:
        pass
    try:
        u = str(chat_url or "").strip()
        if u.startswith("http://") or u.startswith("https://"):
            parts = u.split("/")
            if len(parts) >= 3:
                return "/".join(parts[:3])
    except Exception:
        pass
    return "http://127.0.0.1:11434"


