def _agent_llm_router_policy() -> Dict[str, Any]:
    p = CONFIG.get("agent_llm_router") if isinstance(CONFIG.get("agent_llm_router"), dict) else {}
    try:
        if not isinstance(p, dict):
            return {}
    except Exception:
        return {}
    return dict(p)


def _agent_llm_router_defaults() -> Dict[str, Dict[str, str]]:
    pol = _agent_llm_router_policy()

    def _pick(keys: List[str], default: str = "") -> str:
        for k in keys:
            try:
                v = str(os.environ.get(k, "") or "").strip()
            except Exception:
                v = ""
            if v:
                return v
        return default

    small_provider = str((pol.get("small") or {}).get("provider") or "").strip().lower()
    small_model = str((pol.get("small") or {}).get("model") or "").strip()
    if not small_provider:
        small_provider = _pick(["AGENT_LLM_SMALL_PROVIDER"], default="openai_compat").strip().lower() or "openai_compat"
    if not small_model:
        small_model = _pick(["AGENT_LLM_SMALL_MODEL", "AGENT_OPENAI_COMPAT_MODEL"], default="qwen3.5-4b")

    code_provider = str((pol.get("code") or {}).get("provider") or "").strip().lower()
    code_model = str((pol.get("code") or {}).get("model") or "").strip()
    if not code_provider:
        code_provider = _pick(["AGENT_LLM_CODE_PROVIDER"], default="ollama").strip().lower() or "ollama"
    if not code_model:
        code_model = _pick(["AGENT_LLM_CODE_MODEL", "AGENT_OLLAMA_MODEL"], default="qwen2.5-coder:latest")

    explore_provider = str((pol.get("explore") or {}).get("provider") or "").strip().lower()
    explore_model = str((pol.get("explore") or {}).get("model") or "").strip()
    if not explore_provider:
        explore_provider = _pick(["AGENT_LLM_EXPLORE_PROVIDER"], default="dashscope").strip().lower() or "dashscope"
    if not explore_model:
        explore_model = _pick(["AGENT_LLM_EXPLORE_MODEL", "AGENT_DASHSCOPE_MODEL"], default="qwen3-coder-plus")

    return {
        "small": {"provider": small_provider, "model": small_model},
        "code": {"provider": code_provider, "model": code_model},
        "explore": {"provider": explore_provider, "model": explore_model},
    }


