def _agent_llm_router_rules() -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    try:
        env_raw = str(os.environ.get("AGENT_LLM_ROUTER_RULES_JSON", "") or "").strip()
    except Exception:
        env_raw = ""
    if env_raw:
        try:
            parsed = json.loads(env_raw)
        except Exception:
            parsed = None
        if isinstance(parsed, list):
            for r in parsed:
                if isinstance(r, dict):
                    out.append(dict(r))

    cfg_rules = CONFIG.get("agent_llm_router_rules")
    if isinstance(cfg_rules, list):
        for r in cfg_rules:
            if isinstance(r, dict):
                out.append(dict(r))

    if not out:
        out = _agent_llm_router_rules_default()

    out2: List[Dict[str, Any]] = []
    for r in out:
        if not isinstance(r, dict):
            continue
        rid = str(r.get("id") or "").strip()
        route = str(r.get("route") or "").strip().lower()
        try:
            w = float(r.get("weight") if r.get("weight") is not None else 0.0)
        except Exception:
            w = 0.0
        if (not rid) or (route not in ("small", "code", "explore")):
            continue
        r2 = dict(r)
        r2["id"] = rid
        r2["route"] = route
        r2["weight"] = w
        out2.append(r2)
    return out2


def _agent_llm_router_score(features: Dict[str, Any], rules: List[Dict[str, Any]]) -> Dict[str, Any]:
    kind = str(features.get("kind") or "").strip()
    t = str(features.get("text") or "").strip()
    t0 = str(features.get("text_lower") or t.lower()).strip()
    il = str(features.get("intent_level") or "L1").strip().upper() or "L1"
    purpose = str(features.get("purpose") or "").strip()
    plan_tools = set(features.get("plan_tools") or [])
    plan_len = int(features.get("plan_len") or 0)
    evidence_count = int(features.get("evidence_count") or 0)
    text_len = int(features.get("text_len") or len(t))

    scores = {"small": 0.0, "code": 0.0, "explore": 0.0}
    matched: List[Dict[str, Any]] = []

    def _list_str(v: Any) -> List[str]:
        if isinstance(v, list):
            return [str(x) for x in v if str(x).strip()]
        if isinstance(v, str) and v.strip():
            return [v.strip()]
        return []

    def _match_rule(r: Dict[str, Any]) -> bool:
        if r.get("purpose_any"):
            any_p = _list_str(r.get("purpose_any"))
            if any_p and (purpose not in any_p):
                return False
        if r.get("kind_any"):
            ks = _list_str(r.get("kind_any"))
            if ks and (kind not in ks):
                return False
        if r.get("kind_prefix_any"):
            ps = _list_str(r.get("kind_prefix_any"))
            if ps and not any(kind.startswith(pfx) for pfx in ps):
                return False
        if r.get("intent_level_in"):
            ils = [str(x).strip().upper() for x in _list_str(r.get("intent_level_in"))]
            if ils and (il not in ils):
                return False
        if r.get("min_text_len") is not None:
            try:
                nmin = int(r.get("min_text_len"))
            except Exception:
                nmin = 0
            if text_len < nmin:
                return False
        if r.get("plan_len_min") is not None:
            try:
                pmin = int(r.get("plan_len_min"))
            except Exception:
                pmin = 0
            if plan_len < pmin:
                return False
        if r.get("evidence_min") is not None:
            try:
                emin = int(r.get("evidence_min"))
            except Exception:
                emin = 0
            if evidence_count < emin:
                return False
        if r.get("tools_any"):
            ts = set(_list_str(r.get("tools_any")))
            if ts and plan_tools.isdisjoint(ts):
                return False
        if r.get("keywords_any"):
            kws = _list_str(r.get("keywords_any"))
            if kws:
                if not any((kw.lower() in t0) for kw in kws):
                    return False
        return True

    for r in rules:
        if not _match_rule(r):
            continue
        route = str(r.get("route") or "").strip().lower()
        w = float(r.get("weight") or 0.0)
        mode = str(r.get("weight_mode") or "once").strip().lower()
        cap = None
        try:
            if r.get("cap") is not None:
                cap = float(r.get("cap"))
        except Exception:
            cap = None
        delta = w
        if mode == "per_evidence":
            delta = w * float(max(0, evidence_count))
        elif mode == "per_plan_step":
            delta = w * float(max(0, plan_len))
        if cap is not None:
            if delta > cap:
                delta = cap
            if delta < -cap:
                delta = -cap
        scores[route] = float(scores.get(route, 0.0)) + float(delta)
        matched.append({"id": r.get("id"), "route": route, "delta": float(delta)})

    return {"scores": scores, "matched_rules": matched}


def _agent_llm_router_tcp_ok(base_url: str, *, timeout_sec: float = 0.15) -> bool:
    u = str(base_url or "").strip()
    if not u:
        return False
    try:
        if u.startswith("http://") or u.startswith("https://"):
            p = urllib_parse.urlparse(u)
            host = str(p.hostname or "").strip()
            port = int(p.port or (443 if p.scheme == "https" else 80))
        else:
            host = u
            port = 80
    except Exception:
        return False
    if not host:
        return False
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(float(timeout_sec))
        s.connect((host, int(port)))
        s.close()
        return True
    except Exception:
        try:
            s.close()
        except Exception:
            pass
        return False


def _agent_llm_route(
    *,
    purpose: str,
    req_provider: str,
    req_model: str,
    intent_norm: Optional[Dict[str, Any]] = None,
    intent_level: str = "L1",
    risk_level: str = "P2",
    tool_plan: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    p0 = str(req_provider or "").strip().lower()
    m0 = str(req_model or "").strip()
    allowed = {"ollama", "dashscope", "qwen", "openai_compat", "openai", "llama_cpp", "llama.cpp"}
    if p0 and (p0 not in allowed) and (p0 != "auto"):
        p0 = "auto"
    if not p0:
        p0 = "auto"

    kind = str((intent_norm or {}).get("kind") or "").strip()
    itext = str(((intent_norm or {}).get("query_text") if (intent_norm or {}).get("query_text") is not None else (intent_norm or {}).get("text")) or "").strip()
    il = str(intent_level or "L1").strip().upper() or "L1"

    plan = tool_plan if isinstance(tool_plan, list) else []
    plan_tools: List[str] = []
    try:
        for st in plan[:80]:
            if isinstance(st, dict):
                tool = str(st.get("tool") or "").strip()
                if tool:
                    plan_tools.append(tool)
    except Exception:
        plan_tools = []

    evidence_count = 0
    try:
        args = (intent_norm or {}).get("args")
        if isinstance(args, dict):
            urls = args.get("urls")
            if isinstance(urls, list):
                evidence_count += len([x for x in urls if str(x).strip()])
            refs = args.get("external_refs")
            if isinstance(refs, list):
                evidence_count += len([x for x in refs if str(x).strip()])
    except Exception:
        pass
    try:
        evidence_count += len(re.findall(r"https?://", itext))
    except Exception:
        pass
    evidence_count = int(max(0, evidence_count))

    if (p0 != "auto") or (not _agent_llm_router_enabled()):
        if not p0:
            p0 = "ollama"
        route0 = "explicit" if p0 != "auto" else "disabled"
        return {
            "provider": p0,
            "model": m0,
            "route": route0,
            "purpose": str(purpose or ""),
            "requested": {"provider": str(req_provider or "").strip(), "model": str(req_model or "").strip()},
        }

    rules = _agent_llm_router_rules()
    features = {
        "purpose": str(purpose or ""),
        "kind": kind,
        "text": itext,
        "text_lower": itext.lower(),
        "text_len": int(len(itext)),
        "intent_level": il,
        "risk_level": str(risk_level or "P2").strip().upper(),
        "plan_len": int(len(plan)),
        "plan_tools": plan_tools,
        "evidence_count": evidence_count,
    }
    scored = _agent_llm_router_score(features, rules)
    scores = scored.get("scores") if isinstance(scored.get("scores"), dict) else {"small": 0.0, "code": 0.0, "explore": 0.0}

    def _score(k: str) -> float:
        try:
            return float(scores.get(k) or 0.0)
        except Exception:
            return 0.0

    best_route = "small"
    best_score = _score("small")
    for r in ("code", "explore"):
        s = _score(r)
        if s > best_score:
            best_score = s
            best_route = r
        elif s == best_score:
            if r == "code" and best_route != "code":
                best_route = "code"
            elif r == "explore" and best_route == "small":
                best_route = "explore"

    defaults = _agent_llm_router_defaults()
    pick = defaults.get(best_route) if isinstance(defaults.get(best_route), dict) else defaults.get("small", {})
    desired_provider = str(pick.get("provider") or "openai_compat").strip().lower() or "openai_compat"
    desired_model = str(pick.get("model") or "").strip()

    fallbacks: List[Dict[str, str]] = []
    selected_by = ""
    provider = desired_provider
    model = desired_model

    if provider in ("openai_compat", "openai", "llama_cpp", "llama.cpp"):
        base = _agent_openai_compat_base_url()
        if base and _agent_llm_router_tcp_ok(base):
            provider = "openai_compat"
            selected_by = "tcp_ok"
        else:
            fallbacks.append({"from": "openai_compat", "to": "ollama", "reason": "openai_compat_unreachable"})
            provider = "ollama"

    if provider == "ollama":
        base2 = _agent_ollama_base_url()
        if base2 and _agent_llm_router_tcp_ok(base2):
            selected_by = selected_by or "tcp_ok"
            if best_route == "code":
                model2 = str(defaults.get("code", {}).get("model") or "").strip()
            else:
                model2 = str(defaults.get("small", {}).get("model") or "").strip()
                if model2.lower().startswith("qwen3.5") or model2.lower().endswith(".gguf"):
                    model2 = str(os.environ.get("AGENT_OLLAMA_MODEL", "") or "").strip() or str(CONFIG.get("agent_ollama_model") or "").strip() or "qwen2.5:7b-instruct"
            model = model2
        else:
            fallbacks.append({"from": "ollama", "to": "dashscope", "reason": "ollama_unreachable"})
            provider = "dashscope"

    if provider in ("dashscope", "qwen"):
        api_key = _agent_dashscope_api_key()
        if api_key:
            provider = "dashscope"
            model = str(defaults.get("explore", {}).get("model") or "").strip() or "qwen3-coder-plus"
            selected_by = selected_by or "api_key"
        else:
            fallbacks.append({"from": "dashscope", "to": "ollama", "reason": "missing_dashscope_api_key"})
            provider = "ollama"
            model = (str(CONFIG.get("agent_ollama_model") or "").strip() or "qwen2.5:7b-instruct")

    return {
        "provider": provider,
        "model": model,
        "route": best_route,
        "purpose": str(purpose or ""),
        "scores": scores,
        "matched_rules": scored.get("matched_rules") if isinstance(scored.get("matched_rules"), list) else [],
        "features": features,
        "fallbacks": fallbacks,
        "selected_by": selected_by or None,
        "requested": {"provider": str(req_provider or "").strip(), "model": str(req_model or "").strip()},
    }


def _agent_llm_chat(provider: str, model: str, messages: List[Dict[str, str]], timeout_sec: int = 60) -> Dict[str, Any]:
    p = str(provider or "").strip().lower()
    if not p:
        p = "ollama"

    if p == "ollama":
        url = _agent_ollama_chat_url()
        payload = {
            "model": model,
            "format": "json",
            "stream": False,
            "messages": messages,
            "options": {
                "temperature": 0.2,
                "num_predict": 512,
            },
        }
        try:
            body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        except Exception:
            body = json.dumps(payload).encode("utf-8")
        req = urllib_request.Request(url, data=body, headers={"Content-Type": "application/json"}, method="POST")
        try:
            with urllib_request.urlopen(req, timeout=max(1, int(timeout_sec))) as resp:
                raw = resp.read() or b""
            try:
                data = json.loads(raw.decode("utf-8"))
            except Exception:
                try:
                    data = json.loads(raw.decode("utf-8", errors="ignore"))
                except Exception:
                    return {"ok": False, "error": "bad_response"}
            if isinstance(data, dict) and data.get("error"):
                return {"ok": False, "error": str(data.get("error"))}
            return {"ok": True, "data": data}
        except urllib_error.HTTPError as e:
            try:
                raw = e.read() or b""
                msg = raw.decode("utf-8", errors="ignore")
            except Exception:
                msg = str(e)
            return {"ok": False, "error": msg or "http_error"}
        except Exception as e:
            return {"ok": False, "error": str(e) or "request_failed"}

    if p in ("openai_compat", "openai", "llama_cpp", "llama.cpp"):
        url = _agent_openai_compat_chat_url()
        api_key = _agent_openai_compat_api_key()
        payload3: Dict[str, Any] = {
            "model": model,
            "messages": messages,
            "stream": False,
            "temperature": 0.2,
            "max_tokens": 1024,
        }
        try:
            json_mode = str(os.environ.get("AGENT_OPENAI_COMPAT_JSON_MODE", "") or "").strip().lower()
            if json_mode in ("1", "true", "yes"):
                payload3["response_format"] = {"type": "json_object"}
        except Exception:
            pass
        try:
            body3 = json.dumps(payload3, ensure_ascii=False).encode("utf-8")
        except Exception:
            body3 = json.dumps(payload3).encode("utf-8")

        headers3 = {
            "Content-Type": "application/json",
            "Accept": "application/json",
        }
        if api_key:
            headers3["Authorization"] = f"Bearer {api_key}"

        req3 = urllib_request.Request(url, data=body3, headers=headers3, method="POST")
        try:
            with urllib_request.urlopen(req3, timeout=max(1, int(timeout_sec))) as resp:
                raw3 = resp.read() or b""
            try:
                data3 = json.loads(raw3.decode("utf-8"))
            except Exception:
                try:
                    data3 = json.loads(raw3.decode("utf-8", errors="ignore"))
                except Exception:
                    return {"ok": False, "error": "bad_response"}
            if isinstance(data3, dict) and data3.get("error"):
                err_obj = data3.get("error")
                if isinstance(err_obj, dict):
                    msg = str(err_obj.get("message") or err_obj.get("code") or "openai_compat_error")
                else:
                    msg = str(err_obj)
                return {"ok": False, "error": msg or "openai_compat_error"}
            content = ""
            try:
                ch0 = (data3.get("choices") or [None])[0] if isinstance(data3, dict) else None
                msg0 = ch0.get("message") if isinstance(ch0, dict) else None
                content = str((msg0 or {}).get("content") or "") if isinstance(msg0, dict) else ""
            except Exception:
                content = ""
            if not content.strip():
                return {"ok": False, "error": "empty_completion"}
            return {
                "ok": True,
                "data": {
                    "message": {"role": "assistant", "content": content},
                    "raw": data3,
                },
            }
        except urllib_error.HTTPError as e:
            try:
                raw4 = e.read() or b""
                msg4 = raw4.decode("utf-8", errors="ignore")
            except Exception:
                msg4 = str(e)
            return {"ok": False, "error": msg4 or "http_error"}
        except Exception as e:
            return {"ok": False, "error": str(e) or "request_failed"}

    if p in ("dashscope", "qwen"):
        api_key = _agent_dashscope_api_key()
        if not api_key:
            return {"ok": False, "error": "missing_dashscope_api_key"}
        url = _agent_dashscope_chat_url()
        payload2: Dict[str, Any] = {
            "model": model,
            "messages": messages,
            "stream": False,
            "temperature": 0.2,
            "max_tokens": 1024,
        }
        try:
            json_mode = str(os.environ.get("AGENT_DASHSCOPE_JSON_MODE", "") or "").strip().lower()
            if json_mode in ("1", "true", "yes"):
                payload2["response_format"] = {"type": "json_object"}
        except Exception:
            pass
        try:
            body2 = json.dumps(payload2, ensure_ascii=False).encode("utf-8")
        except Exception:
            body2 = json.dumps(payload2).encode("utf-8")
        headers2 = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "Authorization": f"Bearer {api_key}",
        }
        req2 = urllib_request.Request(url, data=body2, headers=headers2, method="POST")
        try:
            with urllib_request.urlopen(req2, timeout=max(1, int(timeout_sec))) as resp:
                raw2 = resp.read() or b""
            try:
                data2 = json.loads(raw2.decode("utf-8"))
            except Exception:
                try:
                    data2 = json.loads(raw2.decode("utf-8", errors="ignore"))
                except Exception:
                    return {"ok": False, "error": "bad_response"}
            if isinstance(data2, dict) and data2.get("error"):
                err_obj = data2.get("error")
                if isinstance(err_obj, dict):
                    msg = str(err_obj.get("message") or err_obj.get("code") or "dashscope_error")
                else:
                    msg = str(err_obj)
                return {"ok": False, "error": msg or "dashscope_error"}
            content = ""
            try:
                ch0 = (data2.get("choices") or [None])[0] if isinstance(data2, dict) else None
                msg0 = ch0.get("message") if isinstance(ch0, dict) else None
                content = str((msg0 or {}).get("content") or "") if isinstance(msg0, dict) else ""
            except Exception:
                content = ""
            if not content.strip():
                return {"ok": False, "error": "empty_completion"}
            return {
                "ok": True,
                "data": {
                    "message": {"role": "assistant", "content": content},
                    "raw": data2,
                },
            }
        except urllib_error.HTTPError as e:
            try:
                raw3 = e.read() or b""
                msg3 = raw3.decode("utf-8", errors="ignore")
            except Exception:
                msg3 = str(e)
            return {"ok": False, "error": msg3 or "http_error"}
        except Exception as e:
            return {"ok": False, "error": str(e) or "request_failed"}

    return {"ok": False, "error": "unsupported_provider"}


def _json_parse_loose(s: str) -> Any:
    t = str(s or "").strip()
    if not t:
        raise ValueError("empty")
    try:
        return json.loads(t)
    except Exception:
        b = t.find("{")
        e = t.rfind("}")
        if b >= 0 and e > b:
            mid = t[b : e + 1]
            return json.loads(mid)
        raise


def _risk_rank(v: str) -> int:
    s = str(v or "").strip().upper()
    if s == "P0":
        return 0
    if s == "P1":
        return 1
    if s == "P2":
        return 2
    if s == "P3":
        return 3
    return 2


def _risk_max(a: str, b: str) -> str:
    return a if _risk_rank(a) <= _risk_rank(b) else b


def _risk_valid(v: str) -> bool:
    s = str(v or "").strip().upper()
    return s in ("P0", "P1", "P2", "P3")


def _p2_health_gate_status(now_ms: int) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    enabled = bool(CONFIG.get("p2_health_gate_enabled", True))
    if not enabled:
        return {"ok": True, "blocked": False, "enabled": False, "ts": ts}

    fail_open = bool(CONFIG.get("p2_health_gate_fail_open", False))
    block_on_warn = bool(CONFIG.get("p2_health_gate_block_on_warn", True))

    try:
        serving = _serving_consistency_status()
    except Exception:
        serving = {"ok": True}
    if not bool(serving.get("ok", False)):
        if fail_open:
            return {"ok": True, "blocked": False, "enabled": True, "fail_open": True, "ts": ts, "reason": "serving_inconsistent", "serving": serving}
        return {"ok": False, "blocked": True, "enabled": True, "fail_open": False, "ts": ts, "reason": "serving_inconsistent", "serving": serving}

    try:
        window = int(CONFIG.get("p2_health_gate_window", 2000) or 2000)
    except Exception:
        window = 2000
    try:
        recent_window = int(CONFIG.get("p2_health_gate_recent_window", 500) or 500)
    except Exception:
        recent_window = 500
    try:
        max_features = int(CONFIG.get("p2_health_gate_max_features", 60) or 60)
    except Exception:
        max_features = 60
    try:
        drift_warn = float(CONFIG.get("p2_health_gate_drift_warn", CONFIG.get("health_drift_warn", 3.0) or 3.0) or 3.0)
    except Exception:
        drift_warn = 3.0

    window = max(0, min(200000, int(window)))
    recent_window = max(50, min(int(window) if int(window) > 0 else 5000, int(recent_window)))
    max_features = max(10, min(200, int(max_features)))

    samples_all = sorted(EVAL_SAMPLES, key=lambda x: x.get("ts", 0)) if isinstance(EVAL_SAMPLES, list) else []
    if not samples_all:
        if fail_open:
            return {"ok": True, "blocked": False, "enabled": True, "fail_open": True, "ts": ts, "reason": "no_samples"}
        return {"ok": False, "blocked": True, "enabled": True, "fail_open": False, "ts": ts, "reason": "no_samples"}
    samples = (samples_all[-window:] if (window > 0 and len(samples_all) > window) else samples_all)

    def _is_missing(v: Any) -> bool:
        try:
            if v is None:
                return True
            fv = float(v)
            return (not math.isfinite(fv))
        except Exception:
            return True

    try:
        keys = _eval_feature_keys()
        keys = [str(k) for k in keys if str(k)]
        if len(keys) > int(max_features):
            keys = keys[:int(max_features)]
    except Exception:
        keys = []

    drift_top = None
    max_abs_shift = None
    if keys and int(len(samples)) >= int(recent_window) + 50:
        recent = samples[-int(recent_window):]
        train = samples[:max(0, int(len(samples)) - int(recent_window))]
        drift_rows = []
        for k in keys:
            tv = []
            rv = []
            tm = 0
            rm = 0
            for s in train:
                v = (s.get("features") or {}).get(k)
                if _is_missing(v):
                    tm += 1
                else:
                    tv.append(float(v))
            for s in recent:
                v = (s.get("features") or {}).get(k)
                if _is_missing(v):
                    rm += 1
                else:
                    rv.append(float(v))
            if len(tv) < 20 or len(rv) < 20:
                continue
            ts0 = sorted(tv)
            rs0 = sorted(rv)
            tmed = float(_quantile(ts0, 0.50))
            rmed = float(_quantile(rs0, 0.50))
            tq1 = float(_quantile(ts0, 0.25))
            tq3 = float(_quantile(ts0, 0.75))
            iqr = float(tq3 - tq1)
            shift = float(rmed - tmed) / float(iqr + 1e-9)
            miss_delta = (float(rm) / float(max(1, len(recent)))) - (float(tm) / float(max(1, len(train))))
            drift_rows.append({"key": str(k), "shift_robust": float(shift), "missing_delta": float(miss_delta), "score": float(abs(shift) + 5.0 * abs(miss_delta))})
        if drift_rows:
            drift_rows.sort(key=lambda x: float(x.get("score", 0.0)), reverse=True)
            drift_top = drift_rows[0]
            try:
                max_abs_shift = float(abs(float(drift_top.get("shift_robust") or 0.0)))
            except Exception:
                max_abs_shift = None

    blocked = False
    reason = None
    if max_abs_shift is not None and math.isfinite(float(max_abs_shift)) and float(max_abs_shift) >= float(drift_warn):
        if block_on_warn:
            blocked = True
            reason = "feature_drift"

    if blocked and fail_open:
        blocked = False

    return {
        "ok": (not blocked),
        "blocked": bool(blocked),
        "enabled": True,
        "fail_open": bool(fail_open),
        "block_on_warn": bool(block_on_warn),
        "ts": ts,
        "reason": reason,
        "window": int(window),
        "recent_window": int(recent_window),
        "max_features": int(max_features),
        "drift_warn": float(drift_warn),
        "drift_top": drift_top,
        "max_abs_shift": max_abs_shift,
    }


def _psi_kl_from_binned_proportions(p: List[float], q: List[float], eps: float = 1e-6) -> Tuple[float, float]:
    if not p or not q or len(p) != len(q):
        return 0.0, 0.0
    psi = 0.0
    kl = 0.0
    for pi, qi in zip(p, q):
        p0 = float(pi)
        q0 = float(qi)
        if not math.isfinite(p0) or not math.isfinite(q0):
            continue
        p1 = max(float(eps), p0)
        q1 = max(float(eps), q0)
        psi += float(p1 - q1) * float(math.log(p1 / q1))
        kl += float(p1) * float(math.log(p1 / q1))
    return float(psi), float(kl)


def _quantile_edges(values_sorted: List[float], bins: int) -> List[float]:
    if not values_sorted:
        return []
    b = max(2, min(50, int(bins)))
    edges = []
    for i in range(b + 1):
        q = float(i) / float(b)
        try:
            edges.append(float(_quantile(values_sorted, q)))
        except Exception:
            edges.append(float(values_sorted[0]))
    for i in range(1, len(edges)):
        if edges[i] < edges[i - 1]:
            edges[i] = edges[i - 1]
    return edges


def _bin_proportions(values: List[float], edges: List[float]) -> List[float]:
    if not values or not edges or len(edges) < 2:
        return []
    k = int(len(edges) - 1)
    counts = [0] * k
    for x in values:
        try:
            v = float(x)
        except Exception:
            continue
        if not math.isfinite(float(v)):
            continue
        idx = k - 1
        for j in range(k - 1):
            if float(v) < float(edges[j + 1]):
                idx = j
                break
        if 0 <= idx < k:
            counts[idx] += 1
    tot = float(sum(counts))
    if tot <= 0.0:
        return [0.0] * k
    return [float(c) / float(tot) for c in counts]


def _p3_drift_psi_kl_status(
    *,
    now_ms: int,
    drift_days: float,
    max_features: int,
    bins: int,
    min_train: int,
    min_recent: int,
) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    try:
        drift_days = float(drift_days)
    except Exception:
        drift_days = 30.0
    drift_days = float(max(1.0, min(180.0, float(drift_days))))
    cutoff = int(ts) - int(drift_days * 86400.0 * 1000.0)

    samples_all = sorted(EVAL_SAMPLES, key=lambda x: x.get("ts", 0)) if isinstance(EVAL_SAMPLES, list) else []
    if not samples_all:
        return {"ok": False, "sufficient": False, "error": "no_samples", "ts": ts}

    recent = [s for s in samples_all if isinstance(s, dict) and int(s.get("ts") or 0) >= int(cutoff)]
    train = [s for s in samples_all if isinstance(s, dict) and int(s.get("ts") or 0) < int(cutoff)]
    if len(train) < int(min_train) or len(recent) < int(min_recent):
        return {
            "ok": True,
            "sufficient": False,
            "ts": ts,
            "cutoff_ts": int(cutoff),
            "n_train": int(len(train)),
            "n_recent": int(len(recent)),
        }

    try:
        keys = _eval_feature_keys()
        keys = [str(k) for k in keys if str(k)]
        if int(max_features) > 0 and len(keys) > int(max_features):
            keys = keys[: int(max_features)]
    except Exception:
        keys = []

    def _is_missing(v: Any) -> bool:
        try:
            if v is None:
                return True
            fv = float(v)
            return (not math.isfinite(fv))
        except Exception:
            return True

    rows: List[Dict[str, Any]] = []
    for k in keys:
        tv: List[float] = []
        rv: List[float] = []
        for s in train:
            v = (s.get("features") or {}).get(k)
            if _is_missing(v):
                continue
            tv.append(float(v))
        for s in recent:
            v = (s.get("features") or {}).get(k)
            if _is_missing(v):
                continue
            rv.append(float(v))
        if len(tv) < 50 or len(rv) < 50:
            continue
        ts0 = sorted(tv)
        edges = _quantile_edges(ts0, int(bins))
        if not edges or len(edges) < 3:
            continue
        p = _bin_proportions(tv, edges)
        q = _bin_proportions(rv, edges)
        psi, kl = _psi_kl_from_binned_proportions(p, q)
        rows.append({"key": str(k), "psi": float(psi), "kl": float(kl), "n_train": int(len(tv)), "n_recent": int(len(rv))})

    rows.sort(key=lambda x: float(max(float(x.get("psi") or 0.0), float(x.get("kl") or 0.0))), reverse=True)
    top = rows[: max(1, min(20, int(CONFIG.get("p3_drift_top_n", 10) or 10)))]

    psi_max = None
    kl_max = None
    if rows:
        try:
            psi_max = float(max(float(r.get("psi") or 0.0) for r in rows))
        except Exception:
            psi_max = None
        try:
            kl_max = float(max(float(r.get("kl") or 0.0) for r in rows))
        except Exception:
            kl_max = None

    return {
        "ok": True,
        "sufficient": True,
        "ts": ts,
        "cutoff_ts": int(cutoff),
        "n_train": int(len(train)),
        "n_recent": int(len(recent)),
        "psi_max": psi_max,
        "kl_max": kl_max,
        "top": top,
    }


def _is_local_request() -> bool:
    ip = ""
    try:
        xff = str(request.headers.get("X-Forwarded-For") or "").strip()
        if xff:
            ip = xff.split(",", 1)[0].strip()
    except Exception:
        ip = ""
    if not ip:
        try:
            ip = str(request.headers.get("X-Real-IP") or "").strip()
        except Exception:
            ip = ""
    if not ip:
        try:
            ip = str(request.remote_addr or "").strip()
        except Exception:
            ip = ""
    if ip.lower().startswith("::ffff:"):
        ip = ip.split("::ffff:", 1)[1].strip()
    return ip in ("127.0.0.1", "::1")


def _agent_read_auth_ok() -> bool:
    if _is_local_request():
        return True
    try:
        if bool(CONFIG.get("agent_read_allow_remote", False)):
            return True
    except Exception:
        pass
    return bool(_config_auth_ok())


def _agent_write_auth_ok() -> bool:
    if _is_local_request():
        return True
    return bool(_governance_write_auth_ok())


def _agent_sandbox_task_auth_ok() -> bool:
    if _is_local_request():
        return True
    try:
        if bool(CONFIG.get("agent_sandbox_allow_remote", False)):
            return True
    except Exception:
        pass
    return bool(_config_auth_ok())


