def _agent_external_text_strip_instructions(text: Any, *, max_chars: int = 4000) -> Dict[str, Any]:
    t0 = ""
    try:
        t0 = "" if text is None else str(text)
    except Exception:
        t0 = ""
    t0 = t0.replace("\r\n", "\n").replace("\r", "\n")
    if not t0.strip():
        return {"ok": True, "cleaned_text": "", "dropped": 0, "kept": 0, "truncated": False, "sha256": hashlib.sha256(b"").hexdigest()}

    suspicious = [
        "ignore previous",
        "override",
        "system prompt",
        "developer message",
        "you are chatgpt",
        "act as",
        "follow these instructions",
        "tool_plan",
        "tool call",
        "function call",
        "api key",
        "token",
        "password",
        "ssh",
        "rm -rf",
        "curl ",
        "wget ",
        "sudo ",
        "执行以下",
        "忽略之前",
        "系统提示",
        "开发者",
        "扮演",
        "你必须",
        "工具",
        "调用",
        "密钥",
        "令牌",
        "密码",
        "删除",
    ]
    suspicious_lc = [x.lower() for x in suspicious]

    lines0 = t0.split("\n")
    kept_lines: List[str] = []
    dropped = 0
    for line in lines0:
        s = line.strip()
        if not s:
            kept_lines.append("")
            continue
        sl = s.lower()
        if sl.startswith(("system:", "developer:", "assistant:", "工具:", "系统:", "开发者:", "助手:")):
            dropped += 1
            continue
        if any(p in sl for p in suspicious_lc):
            dropped += 1
            continue
        kept_lines.append(line)

    cleaned = "\n".join(kept_lines).strip()
    truncated = False
    if max_chars > 0 and len(cleaned) > int(max_chars):
        cleaned = cleaned[: int(max_chars)]
        truncated = True
    try:
        digest = hashlib.sha256(cleaned.encode("utf-8")).hexdigest()
    except Exception:
        digest = hashlib.sha256(cleaned.encode("utf-8", errors="ignore")).hexdigest()
    kept = int(max(0, int(len(lines0)) - int(dropped)))
    return {"ok": True, "cleaned_text": cleaned, "dropped": int(dropped), "kept": kept, "truncated": bool(truncated), "sha256": digest}


def _agent_chat_extract_external_blocks(raw_text: str) -> Tuple[str, List[Dict[str, Any]]]:
    t = str(raw_text or "")
    if not t.strip():
        return "", []
    lines = t.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    markers = ("外部材料:", "外部文本:", "引用材料:", "引用:", "NEWS:", "SOURCE:")
    idx = -1
    for i, ln in enumerate(lines):
        s = ln.strip()
        if not s:
            continue
        if any(s.upper().startswith(m) for m in markers) or any(s.startswith(m) for m in markers):
            idx = i
            break
    if idx < 0:
        return t.strip(), []

    query = "\n".join(lines[:idx]).strip()
    ext_raw = "\n".join(lines[idx + 1 :]).strip()
    if not ext_raw:
        return t.strip(), []
    return (query or t.strip()), [{"ref_id": "ext-1", "source": str(lines[idx]).strip(), "text": ext_raw}]


def _agent_chat_intent_normalize(intent: Any) -> Dict[str, Any]:
    raw_text = ""
    explicit_kind = None
    explicit_args = None
    if isinstance(intent, dict):
        try:
            raw_text = str(intent.get("text") or "").strip()
        except Exception:
            raw_text = ""
        try:
            explicit_kind = str(intent.get("kind") or "").strip() or None
        except Exception:
            explicit_kind = None
        explicit_args = intent.get("args") if isinstance(intent.get("args"), dict) else None
    else:
        raw_text = str(intent or "").strip()

    query_text, external_blocks = _agent_chat_extract_external_blocks(raw_text)

    urls = []
    try:
        urls = [str(m or "").strip() for m in re.findall(r"(https?://[^\s]+)", raw_text)]
        urls = [u for u in urls if u]
    except Exception:
        urls = []

    text_without_urls = query_text
    try:
        text_without_urls = re.sub(r"https?://[^\s]+", "", query_text).strip()
    except Exception:
        text_without_urls = query_text

    kind = "general.assist"
    args: Dict[str, Any] = {}
    t = query_text.lower()
    lookback_days = None
    try:
        m = re.search(r"(?:最近|近)\s*(\d+(?:\.\d+)?)\s*天", query_text)
        if not m:
            m = re.search(r"\b(\d+(?:\.\d+)?)\s*d\b", t)
        if m:
            try:
                lookback_days = float(m.group(1))
            except Exception:
                lookback_days = None
    except Exception:
        lookback_days = None
    if lookback_days is not None:
        lookback_days = max(0.1, min(90.0, float(lookback_days)))
        args["lookback_days"] = float(lookback_days)

    allowed_kinds = {
        "general.assist",
        "repo.fetch_strategy",
        "sandbox.backtest",
        "sandbox.robustness",
        "read.observe",
        "read.explain",
        "optimize.one_click",
        "bugfix.triage_and_draft",
        "bayes.optimize.strategy_scope",
        "bayes.optimize.system_scope",
        "trade_monitor.analyze",
    }
    if explicit_kind and explicit_kind in allowed_kinds:
        kind = explicit_kind
        if isinstance(explicit_args, dict):
            try:
                args.update(explicit_args)
            except Exception:
                pass
    elif any(k in t for k in ["bugfix.triage_and_draft", "system_monitor", "triage", "故障草案", "诊断草案"]):
        kind = "bugfix.triage_and_draft"
    elif any(k in t for k in ["strategy_scope", "strategy scope", "strategy/entry", "策略参数优化"]):
        kind = "bayes.optimize.strategy_scope"
    elif any(k in t for k in ["system_scope", "system scope", "quant/common", "系统参数优化"]):
        kind = "bayes.optimize.system_scope"
    elif any(k in t for k in ["一键优化", "bayes", "bayesian", "贝叶斯", "paramopt", "参数优化"]):
        kind = "optimize.one_click"
    elif urls and any("github.com" in u.lower() for u in urls):
        kind = "repo.fetch_strategy"
        args["repo_url"] = next((u for u in urls if "github.com" in u.lower()), urls[0])
    elif any(k in t for k in ["回测", "backtest"]):
        kind = "sandbox.backtest"
    elif any(k in t for k in ["稳健", "robust", "oos", "rolling", "蒙特卡洛", "monte"]):
        kind = "sandbox.robustness"
    elif (("亏损" in t) or ("loss" in t)) and any(k in t for k in ["分析", "归因", "复盘", "报告", "report", "模板", "模版", "固定分析"]):
        kind = "trade_monitor.analyze"
    elif (("交易" in t) or ("trade" in t)) and any(k in t for k in ["分析", "复盘", "报告", "report"]) and any(k in t for k in ["模板", "模版", "固定分析"]):
        kind = "trade_monitor.analyze"
    elif (lookback_days is not None) and (("交易" in t) or ("trade" in t)) and any(k in t for k in ["分析", "复盘", "报告", "report"]):
        kind = "trade_monitor.analyze"
    elif any(k in t for k in ["trade monitor", "trade_monitor", "trade.monitor", "交易监控", "监控报告", "复盘"]):
        kind = "trade_monitor.analyze"
    elif any(k in t for k in ["告警", "诊断", "状态", "观测", "指标", "metrics", "signal", "signals", "信号", "交易信号", "订单", "orders", "order", "下单", "拒单", "成交", "持仓", "开仓", "平仓"]):
        kind = "read.observe"
    elif any(k in t for k in ["解释", "说明", "是什么", "为什么", "原因", "why", "how"]):
        kind = "read.explain"

    if urls:
        args["urls"] = urls
    if text_without_urls and text_without_urls != query_text:
        args["text_without_urls"] = text_without_urls

    external_refs: List[Dict[str, Any]] = []
    try:
        blocks: List[Dict[str, Any]] = []
        if isinstance(intent, dict):
            if isinstance(intent.get("external_text"), str) and str(intent.get("external_text") or "").strip():
                blocks.append({"ref_id": "ext-1", "source": "external_text", "text": str(intent.get("external_text") or "")})
            if isinstance(intent.get("external_texts"), list):
                for i, it in enumerate(intent.get("external_texts") or []):
                    if isinstance(it, dict) and str(it.get("text") or "").strip():
                        blocks.append({"ref_id": str(it.get("ref_id") or f"ext-{i+1}"), "source": it.get("source"), "url": it.get("url"), "title": it.get("title"), "text": str(it.get("text") or "")})
            if isinstance(intent.get("evidence"), list):
                for i, ev in enumerate(intent.get("evidence") or []):
                    if isinstance(ev, dict) and isinstance(ev.get("text"), str) and str(ev.get("text") or "").strip():
                        blocks.append({"ref_id": str(ev.get("ref_id") or f"ev-{i+1}"), "source": ev.get("source"), "url": ev.get("url"), "title": ev.get("title"), "text": str(ev.get("text") or "")})
        if external_blocks:
            blocks.extend(external_blocks)

        seen: set = set()
        for b in blocks[:8]:
            if not isinstance(b, dict):
                continue
            ref_id = str(b.get("ref_id") or "").strip() or f"ext-{len(external_refs)+1}"
            if ref_id in seen:
                continue
            seen.add(ref_id)
            cleaned = _agent_external_text_strip_instructions(b.get("text"), max_chars=4000)
            excerpt = str((cleaned.get("cleaned_text") if isinstance(cleaned, dict) else "") or "")
            if len(excerpt) > 900:
                excerpt = excerpt[:900]
            external_refs.append({
                "ref_id": ref_id,
                "source": (None if b.get("source") is None else str(b.get("source"))),
                "url": (None if b.get("url") is None else str(b.get("url"))),
                "title": (None if b.get("title") is None else str(b.get("title"))),
                "excerpt": excerpt,
                "sha256": (cleaned.get("sha256") if isinstance(cleaned, dict) else None),
                "dropped": (cleaned.get("dropped") if isinstance(cleaned, dict) else None),
                "truncated": (cleaned.get("truncated") if isinstance(cleaned, dict) else None),
            })
    except Exception:
        external_refs = []
    if external_refs:
        args["external_refs"] = external_refs

    out: Dict[str, Any] = {
        "text": raw_text,
        "query_text": query_text,
        "kind": kind,
        "args": args,
    }
    if isinstance(intent, dict):
        for k in ("constraints", "evidence", "meta"):
            if k in intent and isinstance(intent.get(k), (dict, list, str, int, float, bool)):
                out[k] = intent.get(k)
    return out


def _agent_chat_context_snapshot(limit_chars: int = 9000) -> Dict[str, Any]:
    t0 = time.time()
    snapshot: Dict[str, Any] = {"ts": int(_now_ms())}
    try:
        snapshot["metrics"] = {
            "signals": int(len(EVENTS) if isinstance(EVENTS, dict) else 0),
            "orders_total": int(len(ORDERS) if isinstance(ORDERS, dict) else 0),
            "active_model": (None if ACTIVE_MODEL is None else ACTIVE_MODEL.get("name")),
        }
    except Exception:
        snapshot["metrics"] = {}

    try:
        cfg = CONFIG or {}
        snapshot["config"] = {
            "dry_run": bool(cfg.get("dry_run", True)),
            "live_trading_enabled": bool(cfg.get("live_trading_enabled", False)),
            "execution_venue": str(cfg.get("execution_venue") or ""),
            "max_open_trades": int(cfg.get("max_open_trades", 0) or 0),
            "threshold_trend": float(cfg.get("threshold_trend", 0.0) or 0.0),
            "threshold_chop": float(cfg.get("threshold_chop", 0.0) or 0.0),
        }
    except Exception:
        snapshot["config"] = {}

    try:
        last_zip = _backtest_last_result_zip_name()
        if last_zip:
            snapshot["sandbox"] = {"latest_backtest_zip": str(last_zip)}
            try:
                zip_path = _backtests_dir() / str(last_zip)
                allow_report = (time.time() - t0) < 0.25
                if allow_report:
                    try:
                        st = zip_path.stat()
                        if int(st.st_size) > 80 * 1024 * 1024:
                            allow_report = False
                    except Exception:
                        pass
                if allow_report:
                    rep = _backtest_report_from_zip(zip_path, strategy=None)
                    if isinstance(rep, dict) and bool(rep.get("ok")):
                        snapshot["sandbox"]["latest_backtest_report"] = {
                            "zip": str(rep.get("zip") or str(last_zip)),
                            "metrics_summary": rep.get("metrics_summary"),
                            "eval": (rep.get("eval") if isinstance(rep.get("eval"), dict) else None),
                        }
            except Exception:
                pass
    except Exception:
        pass

    try:
        reg = _strategy_registry_load()
        entries = reg.get("entries") if isinstance(reg, dict) else None
        items: List[Dict[str, Any]] = []
        if isinstance(entries, dict):
            for v in entries.values():
                if isinstance(v, dict):
                    items.append(v)
        elif isinstance(reg, dict) and isinstance(reg.get("entries"), list):
            for v in reg.get("entries"):
                if isinstance(v, dict):
                    items.append(v)
        items.sort(key=lambda x: str(x.get("updated_at") or ""), reverse=True)
        snapshot["strategy_registry"] = {
            "count": int(len(items)),
            "recent": [
                {
                    "strategy_id": str(x.get("strategy_id") or ""),
                    "family": str(x.get("family") or ""),
                    "stage": str(x.get("stage") or ""),
                    "tier": str(x.get("tier") or ""),
                    "updated_at": str(x.get("updated_at") or ""),
                    "source_zip": str(x.get("source_zip") or ""),
                }
                for x in items[:5]
            ],
        }
    except Exception:
        pass

    try:
        raw = json.dumps(snapshot, ensure_ascii=False)
        if len(raw) > int(limit_chars):
            snapshot = {"ts": snapshot.get("ts"), "truncated": True, "metrics": snapshot.get("metrics"), "config": snapshot.get("config")}
    except Exception:
        pass
    return snapshot


