def _agent_chat_hard_constraints_text() -> str:
    allowed = _doc_allowed_map()
    p = allowed.get("交易AI Agent 技术文档2.0.md")
    if isinstance(p, Path) and p.exists():
        try:
            s = _md_extract_section(p, section_key="1.3.1 两份文档分工（强约束）", max_chars=2600)
            if isinstance(s, dict) and s.get("ok") and isinstance(s.get("text"), str) and str(s.get("text") or "").strip():
                return str(s.get("text") or "").strip()
        except Exception:
            pass
    return "\n".join(
        [
            "#### 1.3.1 两份文档分工（强约束）",
            "1) 技术文档.md：交易系统长期记忆（SSoT / Runbook）。涉及系统怎么跑/链路怎么走/为什么没下单或被拒绝/排障等，必须优先检索并引用本文件。",
            "2) 交易AI Agent 技术文档 2.0：AI Agent 与沙箱体系（边界、门禁、审计、闭环、Skills/outbox）。涉及 agent/沙箱/技能/审计回放/审批回滚等，以本文档为准。",
            "若与 技术文档.md 冲突，以 技术文档.md 为准。",
        ]
    )


def _agent_chat_doc_policy(intent_text: str) -> Dict[str, str]:
    t = str(intent_text or "").strip().lower()
    t_raw = str(intent_text or "").strip()

    trading_kw = [
        "交易系统",
        "交易信号",
        "信号",
        "signals",
        "signal",
        "orders",
        "order",
        "订单",
        "下单",
        "成交",
        "持仓",
        "开仓",
        "平仓",
        "仓位",
        "pairs",
        "交易对",
        "风控",
        "风险",
        "亏损",
        "日亏损",
        "周亏损",
        "限制交易",
        "限制交易时间",
        "冷却",
        "cooldown",
        "熔断",
        "最大回撤",
        "max_daily_loss",
        "max_weekly_loss",
        "max_drawdown",
        "链路",
        "路由",
        "怎么跑",
        "没下单",
        "未下单",
        "被拒绝",
        "拒单",
        "异常信号",
        "异常订单",
        "排障",
        "生产",
        "runbook",
        "ssot",
        "faq",
    ]
    agent_kw = [
        "agent",
        "沙箱",
        "sandbox",
        "技能",
        "skills",
        "outbox",
        "审计",
        "回放",
        "门禁",
        "审批",
        "回滚",
        "/agent/chat",
    ]

    hit_trading = any((k in t_raw) for k in trading_kw) or any((k in t) for k in ("runbook", "ssot", "faq"))
    hit_trading = hit_trading or any((k in t_raw) for k in ("没下单", "未下单", "被拒绝", "拒单", "排障", "链路"))
    hit_agent = any((k in t_raw) for k in agent_kw) or any((k in t) for k in ("agent", "sandbox", "skills", "outbox"))

    if hit_trading and (not hit_agent):
        return {"primary": "技术文档.md", "secondary": "交易AI Agent 技术文档2.0.md", "conflict_winner": "技术文档.md"}
    if hit_agent and (not hit_trading):
        return {"primary": "交易AI Agent 技术文档2.0.md", "secondary": "技术文档.md", "conflict_winner": "技术文档.md"}
    return {"primary": "交易AI Agent 技术文档2.0.md", "secondary": "技术文档.md", "conflict_winner": "技术文档.md"}


def _agent_chat_enforce_doc_refs(doc_refs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    base = _agent_chat_default_doc_refs()
    out: List[Dict[str, Any]] = []

    def _key(x: Dict[str, Any]) -> Tuple[str, str]:
        return (str(x.get("doc_path") or "").strip(), str(x.get("section") or "").strip())

    seen = set()
    for x in doc_refs:
        if not isinstance(x, dict):
            continue
        k = _key(x)
        if not k[0] or k in seen:
            continue
        out.append(x)
        seen.add(k)
    for x in base:
        k = _key(x)
        if not k[0] or k in seen:
            continue
        out.append(x)
        seen.add(k)
    return out


def _agent_chat_ensure_hard_constraints_snippet(doc_snippets: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    cur = [x for x in (doc_snippets or []) if isinstance(x, dict)]
    for x in cur:
        dp = str(x.get("doc_path") or "").strip()
        sec = str(x.get("section") or "").strip()
        if dp == "交易AI Agent 技术文档2.0.md" and "两份文档分工" in sec:
            return cur
    hard_text = _agent_chat_hard_constraints_text()
    if not hard_text.strip():
        return cur
    hard = {
        "doc_path": "交易AI Agent 技术文档2.0.md",
        "section": "1.3.1 两份文档分工（强约束）",
        "title": "两份文档分工（强约束）",
        "text": hard_text.strip(),
    }
    return [hard] + cur


def _agent_chat_build_suggestion(trace_id: str, intent_norm: Dict[str, Any], intent_level: str, risk_level: str, ctx: Dict[str, Any], tool_plan: List[Dict[str, Any]], doc_refs: List[Dict[str, str]]) -> Dict[str, Any]:
    now_iso = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    risk_s = "medium"
    if _risk_rank(risk_level) <= _risk_rank("P1"):
        risk_s = "high"
    elif _risk_rank(risk_level) >= _risk_rank("P3"):
        risk_s = "low"

    pairs: List[str] = []
    try:
        a = intent_norm.get("args") if isinstance(intent_norm.get("args"), dict) else {}
        pairs_raw = a.get("pairs")
        if isinstance(pairs_raw, list):
            pairs = [str(x).strip() for x in pairs_raw if str(x).strip()]
    except Exception:
        pairs = []
    if not pairs:
        pairs = ["BTC/USDT"]

    proposed_actions: List[Dict[str, Any]] = []
    for step in tool_plan:
        if not isinstance(step, dict):
            continue
        if str(step.get("tool") or "") in ("config.set", "config_change"):
            inp = step.get("input") if isinstance(step.get("input"), dict) else {}
            changes = inp.get("changes")
            if isinstance(changes, list):
                for c in changes:
                    if not isinstance(c, dict):
                        continue
                    path = str(c.get("path") or "").strip()
                    if not path:
                        continue
                    proposed_actions.append({"type": "config_change", "path": path, "from": c.get("from"), "to": c.get("to")})
    if not proposed_actions:
        proposed_actions.append({"type": "config_change", "path": "(none)", "from": 0, "to": 0})

    evidence: List[Dict[str, Any]] = []
    try:
        m = ctx.get("metrics") if isinstance(ctx.get("metrics"), dict) else {}
        evidence.append({"type": "metric", "source": "live_metrics", "name": "signals", "value": m.get("signals"), "ts": str(ctx.get("ts") or "")})
        evidence.append({"type": "metric", "source": "live_metrics", "name": "orders_total", "value": m.get("orders_total"), "ts": str(ctx.get("ts") or "")})
    except Exception:
        pass

    return {
        "suggestion_id": f"sg-{int(_now_ms())}",
        "created_at": now_iso,
        "status": "pending_review",
        "title": str(intent_norm.get("kind") or "task").strip() or "task",
        "summary": str(intent_norm.get("text") or "").strip()[:240] or "(empty)",
        "doc_refs": doc_refs[:],
        "evidence": evidence if evidence else [{"type": "metric", "source": "live_metrics", "name": "ts", "value": ctx.get("ts") }],
        "impact_scope": {"pairs": pairs, "market_regime": "unknown", "expected_effect": "生成可审计的建议与任务计划"},
        "risk": {"level": risk_s, "notes": f"intent_level={intent_level}, risk_level={risk_level}"},
        "proposed_actions": proposed_actions,
        "review": {"required": bool(intent_level == "L2" or risk_s == "high"), "approvers": ["risk_owner", "strategy_owner"]},
        "sandbox_plan": {"dataset_snapshot": str(((ctx.get("sandbox") or {}) if isinstance(ctx.get("sandbox"), dict) else {}).get("latest_backtest_zip") or "latest"), "run_id": f"sb-{int(_now_ms())}", "gates": ["backtest", "robustness"]},
        "rollback_plan": {"fallback_version": "latest_rollback_point", "trigger": "P0/P1 or hard gate fail"},
        "audit": {"created_by": "local_llm_driver", "trace_id": trace_id},
    }


def _agent_chat_build_assistant_text(
    *,
    intent_norm: Dict[str, Any],
    intent_level: str,
    risk_level: str,
    driver_mode: str,
    degrade_reason: Optional[str],
    doc_snippets: Optional[List[Dict[str, Any]]],
    tool_plan: List[Dict[str, Any]],
    suggestion: Optional[Dict[str, Any]],
    parse_ok: bool,
    parse_error: Optional[str],
) -> str:
    text = str((intent_norm.get("query_text") if intent_norm.get("query_text") is not None else intent_norm.get("text")) or "").strip()
    kind = str(intent_norm.get("kind") or "").strip()

    lines: List[str] = []

    mode_s = str(driver_mode or "").strip() or "template"
    if mode_s == "llm" and (not parse_ok):
        mode_s = "llm_failed_degraded"

    answer_lines: List[str] = []
    q = text
    if (not q) and kind:
        q = kind

    is_template_like = mode_s != "llm"

    if is_template_like:
        q0 = q.lower()
        if ("亏损" in q) or ("loss" in q0) or ("pnl" in q0) or ("回撤" in q) or ("drawdown" in q0):
            t_loss = _agent_loss_rca_text_from_settlements(q)
            if t_loss:
                answer_lines.extend([x for x in t_loss.splitlines() if str(x).strip()])
        elif ("订单" in q) or ("成交" in q) or ("orders" in q0) or ("order" in q0) or ("/orders/recent" in q0) or ("recent orders" in q0) or ("recent order" in q0):
            t_orders = _agent_orders_visibility_diag_text(q)
            if t_orders:
                answer_lines.extend([x for x in t_orders.splitlines() if str(x).strip()])
        elif ("信号" in q) or ("交易信号" in q) or ("signals" in q0) or ("signal" in q0) or ("拒单" in q) or ("reject" in q0):
            answer_lines.extend([
                "你问的是‘为什么会有大量交易信号’，这类问题需要先把‘信号生成’与‘下单/成交’区分开，否则很容易误判。",
                "建议先按证据链排查（只读）：",
                "1) 看信号样本：按 pair/strategy_id 分布、同一币是否重复触发。",
                "2) 看拒单原因：是被风控/门禁拦截，还是策略本身太激进。",
                "3) 看配置与阈值：threshold、冷却、max_open_trades、是否启用宏观门控/影子模式等。",
                "4) 再看代码证据：信号去重/冷却/阈值叠加逻辑是否被改动或被绕过。",
                "\n建议工具链：signals.recent → signals.reject_stats → metrics.recent → config.get → code.search",
                "\n常见根因（从高到低）：",
                "- 阈值过低/回归到‘几乎一直满足’的条件（特别是 chop 阈值/趋势阈值叠加失效）。",
                "- 冷却/去重失效：同一根 K 线或相邻 K 线反复产生 enter 信号。",
                "- 交易对范围扩大或 informative pair/timeframe 对齐异常，导致更多 pair 同时触发。",
                "- shadow_mode/只记录不交易：你看到大量信号，但并不会下单（需看 reject_stats 的 reason）。",
            ])
        elif ("前端" in q) or ("frontend" in q0) or ("页面" in q) or ("控制台" in q) or ("console" in q0) or ("报错" in q) or ("error" in q0):
            answer_lines.extend([
                "你描述的是‘对话框能力/页面报错/不按预期工作’类问题，优先走“前端 → 接口 → outbox → 后端”证据链。",
                "建议先做三步（只读）：",
                "1) 浏览器控制台：看是否有 JS 报错、请求 4xx/5xx、CORS、代理失败。",
                "2) Network：确认 /agent/chat、/agent/outbox/read 是否有返回，以及返回体里是否有 chat.result.assistant_text。",
                "3) Trace 回放：用 trace_id 在 outbox 里回放 chat.command/chat.result/tool.plan 事件，定位在哪一步降级。",
                "\n建议工具链：engineering.index → code_index.query → code.search → doc.retrieve → agent.trace.replay",
            ])
        elif ("加仓" in q) or ("addon" in q0):
            if ("最短" in q) or ("一句" in q) or ("简短" in q):
                answer_lines.append("加仓（addon）是：在已有同向持仓基础上按规则追加仓位，以调整均价/敞口。")
            else:
                answer_lines.extend([
                    "加仓（addon）一般指：在已有持仓且方向一致时，按规则追加仓位。",
                    "加仓没触发/被拦，常见原因：方向冲突、达到最大加仓次数、冷却期未过、名义/仓位上限、风险门禁。",
                    "可用 /tracker/addon/diagnose?pair=XXX 直接看门禁原因与自然语言解释。",
                ])
        elif ("rsi" in q0) or ("相对强弱" in q):
            if ("最短" in q) or ("一句" in q) or ("简短" in q):
                answer_lines.append("RSI 是衡量一段时间内上涨/下跌强度的动量指标，用于识别超买超卖与趋势强弱。")
            else:
                answer_lines.extend([
                    "RSI（Relative Strength Index）衡量一段时间内上涨与下跌强度的相对比例，是常用的动量指标。",
                    "常见用法：超买/超卖阈值（如 70/30）、背离、以及在趋势中配合均线/结构过滤。",
                ])
        elif ("最短" in q) or ("一句" in q) or ("简单回复" in q) or ("简短" in q):
            answer_lines.append("好的，已收到。")
        elif ("回测" in q) or ("backtest" in q0) or ("稳健" in q) or ("robust" in q0):
            answer_lines.extend([
                "回测/稳健性建议：先沙箱回测（明确 timerange/手续费/滑点假设），再 rolling/蒙特卡洛，最后再走灰度门禁。",
                "给我 strategy + timerange，我可以把需要跑的接口/步骤列成清单。",
            ])
        else:
            snippets = [x for x in (doc_snippets or []) if isinstance(x, dict)]
            if snippets:
                pick = None
                for it in snippets:
                    dp = str(it.get("doc_path") or "").strip()
                    sec = str(it.get("section") or "").strip()
                    if dp == "交易AI Agent 技术文档2.0.md" and ("两份文档分工" in sec):
                        continue
                    pick = it
                    break
                if pick is None:
                    pick = snippets[0]
                t = str((pick or {}).get("text") or "").strip()
                if t:
                    if len(t) > 420:
                        t = t[:420] + "…"
                    answer_lines.append(t)
            if not answer_lines:
                q_show = _clip_str(q, 200)
                answer_lines.append(f"收到：{q_show}")
                answer_lines.append("提示：当前未启用本地 LLM，仅提供模板级回复。")

    if answer_lines and is_template_like:
        out0 = "\n".join([ln for ln in answer_lines if str(ln).strip()]).strip()
        if degrade_reason:
            out0 = (out0 + f"\n\n（已降级：{_clip_str(degrade_reason, 64)}）").strip()
        return out0[:2000]

    if answer_lines:
        lines.extend(answer_lines)

    if degrade_reason:
        lines.append(f"模式：{mode_s}（{_clip_str(degrade_reason, 64)}）")
    else:
        lines.append(f"模式：{mode_s}")

    if driver_mode == "llm" and (not parse_ok) and parse_error:
        lines.append(f"LLM 输出未通过 JSON 校验，已自动降级（{_clip_str(parse_error, 120)}）")

    if kind:
        lines.append(f"识别意图：{kind}（intent={intent_level}, risk={risk_level}）")
    else:
        lines.append(f"级别：intent={intent_level} risk={risk_level}")

    if text:
        lines.append(f"你的输入：{_clip_str(text, 220)}")

    if intent_level == "L2":
        lines.append("提示：该请求涉及可能改变生产行为的动作（L2），系统只会给出计划与证据，执行需人工审批。")

    if kind in ("read.explain", "general.assist") and ("/agent/chat" in text.lower() or "agent/chat" in text.lower() or "对话" in text or "工作流" in text):
        lines.append("\n工作流（最短闭环）：")
        lines.append("1) 前端把你的自然语言作为 intent.text POST 到 /agent/chat")
        lines.append("2) 后端写入 user_data/agent_outbox/chat.jsonl（chat.command 事件，生成 trace_id）")
        lines.append("3) Driver 线程/子进程读取上下文快照，生成 chat.result（模板或本地 LLM JSON）")
        lines.append("4) 前端轮询 /agent/outbox/read?name=chat.jsonl 聚合 trace_id 对应的事件")
        lines.append("5) 若 chat.result 给出 tool_plan_suggested，可点“执行 tool_plan”触发 /agent/skills/execute")
        lines.append("\n你现在能看到的“对话”主要由 chat.result.assistant_text（自然语言摘要）驱动；完整结构化信息在“原始事件”里。")
    elif kind == "repo.fetch_strategy":
        lines.append("\n下一步建议：")
        lines.append("- 确认 repo whitelist 已启用且包含该仓库")
        lines.append("- 触发导入/回测（策略库入库 → 沙箱回测 → 稳健性）")
    elif kind == "sandbox.backtest":
        lines.append("\n下一步建议：")
        lines.append("- 指定策略名与 timerange（例如 20240101-20250101）")
        lines.append("- 回测后再跑稳健性（rolling/蒙特卡洛）并生成变更包")
    elif kind == "sandbox.robustness":
        lines.append("\n下一步建议：")
        lines.append("- 选择 backtest zip（默认 latest）")
        lines.append("- 根据 rolling/MC 结果决定是否进入 P3 门禁与灰度")

    steps = []
    for st in tool_plan or []:
        if not isinstance(st, dict):
            continue
        nm = str(st.get("tool") or "").strip()
        if nm:
            steps.append(nm)
    if steps:
        uniq: List[str] = []
        for x in steps:
            if x not in uniq:
                uniq.append(x)
        lines.append("\n建议工具链：" + " → ".join(uniq[:8]))

    if isinstance(suggestion, dict):
        title = str(suggestion.get("title") or "").strip()
        summary = str(suggestion.get("summary") or "").strip()
        if title and title != kind:
            lines.append(f"\n建议主题：{_clip_str(title, 120)}")
        if summary and summary != text:
            lines.append(f"摘要：{_clip_str(summary, 360)}")

    out = "\n".join([ln for ln in lines if str(ln).strip()]).strip()
    return out[:2000]


def _agent_orders_visibility_diag_text(q: str) -> str:
    def _to_int(v: Any, default: int = 0) -> int:
        try:
            return int(v)
        except Exception:
            return default

    def _to_float(v: Any, default: float = 0.0) -> float:
        try:
            return float(v)
        except Exception:
            return default

    def _fmt_ts_ms(ts_ms: int) -> str:
        try:
            if int(ts_ms) <= 0:
                return "-"
            dt = datetime.fromtimestamp(float(ts_ms) / 1000.0)
            return dt.strftime("%m-%d %H:%M")
        except Exception:
            return "-"

    def _parse_window_sec(text: str) -> Optional[int]:
        s = str(text or "").lower()
        m = re.search(r"(\d{1,3})\s*(分钟|分|min|m)\b", s)
        if m:
            return int(m.group(1)) * 60
        m = re.search(r"(\d{1,3})\s*(小时|h)\b", s)
        if m:
            return int(m.group(1)) * 3600
        m = re.search(r"(\d{1,3})\s*(天|d)\b", s)
        if m:
            return int(m.group(1)) * 86400
        m = re.search(r"(\d{1,3})\s*(周|w)\b", s)
        if m:
            return int(m.group(1)) * 7 * 86400
        if "最近" in s:
            return None
        return None

    def _inc(d: Dict[str, int], k: str, n: int = 1) -> None:
        if not k:
            k = "-"
        d[k] = int(d.get(k) or 0) + int(n)

    now_ms = int(_now_ms())
    window_sec_cfg = _to_int((CONFIG or {}).get("agent_orders_diag_window_sec"), 7 * 86400)
    window_sec_cfg = max(60, min(60 * 86400, int(window_sec_cfg)))
    window_sec = _parse_window_sec(q) or window_sec_cfg
    since_ms = int(now_ms) - int(window_sec * 1000)

    max_files = _to_int((CONFIG or {}).get("agent_orders_diag_max_files"), 8)
    max_files = max(1, min(30, int(max_files)))
    max_lines = _to_int((CONFIG or {}).get("agent_orders_diag_max_lines_per_file"), 6000)
    max_lines = max(200, min(20000, int(max_lines)))

    ds_dir = _user_data_dir() / "datasets"
    ds_files: List[Path] = []
    try:
        if ds_dir.exists() and ds_dir.is_dir():
            ds_files = [p for p in ds_dir.glob("*_orders.jsonl") if p.is_file()]
            ds_files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    except Exception:
        ds_files = []

    cands = [o for o in _orders_recent_candidates(max_files=max_files, max_lines_per_file=max_lines) if isinstance(o, dict)]
    if not cands:
        files_s = ", ".join([p.name for p in ds_files[:5]]) if ds_files else "-"
        return "\n".join([
            "订单可见性诊断（读侧）",
            f"- 窗口：{int(window_sec // 3600)}h",
            "- 结论：内存 ORDERS 与 datasets 归档里都未读到订单候选。",
            f"- datasets 目录：{str(ds_dir)}（匹配 *_orders.jsonl={len(ds_files)}，示例：{files_s}）",
            "下一步（只读）：",
            "- GET /orders/recent?no_default_filter=1&include_shadow=1&sort=ingest&limit=200",
            "- 若仍为空，确认是否确实有落盘：user_data/datasets/*_orders.jsonl 是否在写入/回灌链路中更新",
        ]).strip()

    rows = []
    for o in cands:
        ts = _to_int(o.get("ts"), 0)
        if ts > 0 and ts < int(since_ms):
            continue
        rows.append(o)

    rows.sort(key=lambda x: _to_int(x.get("ts"), 0))
    n_total = len(rows)
    if n_total <= 0:
        return "\n".join([
            "订单可见性诊断（读侧）",
            f"- 窗口：{int(window_sec // 3600)}h",
            f"- 结论：候选订单存在（总数={len(cands)}），但窗口内 ts 过滤后为空。",
            "下一步（只读）：",
            "- 放大窗口：例如“最近 30 天成交订单为什么不显示”",
        ]).strip()

    n_mem = 0
    missing_book = 0
    missing_owner = 0
    missing_pair = 0
    by_book: Dict[str, int] = {}
    by_owner: Dict[str, int] = {}
    by_status: Dict[str, int] = {}
    by_pair: Dict[str, int] = {}
    filled_n = 0

    for o in rows:
        oid = str(o.get("id") or "").strip()
        if oid and isinstance(ORDERS, dict) and oid in ORDERS:
            n_mem += 1
        book_id = str(o.get("book_id") or "").strip().lower()
        if not book_id:
            missing_book += 1
            book_id = "-"
        owner = str(o.get("ab_owner") or o.get("owner") or "").strip().lower()
        if not owner:
            missing_owner += 1
            owner = "-"
        st = str(o.get("status") or "").strip().lower()
        if not st:
            st = "-"
        pair = str(o.get("pair") or "").strip()
        if not pair:
            missing_pair += 1
            pair = "-"

        _inc(by_book, book_id)
        _inc(by_owner, owner)
        _inc(by_status, st)
        _inc(by_pair, pair)

        if st in ("filled", "closed", "done"):
            filled_n += 1

    ts_first = _to_int(rows[0].get("ts"), 0)
    ts_last = _to_int(rows[-1].get("ts"), 0)

    default_book = None
    try:
        default_book = str(_book_isolation_default_book_id() or "").strip().lower() or None
    except Exception:
        default_book = None

    read_infer = False
    try:
        read_infer = bool(_book_isolation_read_infer_enabled())
    except Exception:
        read_infer = False

    def _top3(d: Dict[str, int]) -> str:
        items = sorted([(k, int(v or 0)) for k, v in (d or {}).items()], key=lambda kv: kv[1], reverse=True)
        out = []
        for k, v in items[:3]:
            out.append(f"{k}({v})")
        return "；".join(out) if out else "-"

    files_s = ", ".join([p.name for p in ds_files[:4]]) if ds_files else "-"
    lines: List[str] = []
    lines.append("订单可见性诊断（按工程索引：/orders/recent 合并内存 ORDERS + datasets 归档）")
    lines.append(f"- 窗口：{int(window_sec // 3600)}h；样本：{n_total} 笔（filled≈{filled_n}）")
    lines.append(f"- 时间范围：{_fmt_ts_ms(ts_first)} → {_fmt_ts_ms(ts_last)}")
    lines.append(f"- 来源：内存命中={n_mem}；datasets 文件数={len(ds_files)}（示例：{files_s}）")
    lines.append(f"- 字段缺失：book_id 缺失={missing_book}；ab_owner 缺失={missing_owner}；pair 缺失={missing_pair}")
    lines.append(f"- book_id 分布：{_top3(by_book)}")
    lines.append(f"- ab_owner 分布：{_top3(by_owner)}")
    lines.append(f"- status 分布：{_top3(by_status)}")
    lines.append(f"- pair Top：{_top3(by_pair)}")
    lines.append(f"- 读侧推断：read_infer={'on' if read_infer else 'off'}；默认 book_id={default_book or '-'}")

    lines.append("可能根因（你描述的“前端定时清理后看不到”在本工程里通常是‘读侧过滤口径’而非‘数据丢失’）：")
    lines.append("- /orders/recent 默认会套上 book_id 过滤（通常是 strategy）。若你的订单属于 quant/carry，或历史订单缺 book_id，会被过滤成空。")
    lines.append("- UI 表格如果没带 no_default_filter=1 / allow_book_id_missing=1，会更容易出现“明明成交了但 recent 为空”。")

    lines.append("建议证据链（只读，先验证再改 UI/逻辑）：")
    lines.append("- 1) GET /orders/recent?no_default_filter=1&include_shadow=1&sort=ingest&limit=200（看是否能看到订单）")
    lines.append("- 2) 若 1) 有，但 UI 为空：对比 UI 调用是否缺少 no_default_filter / book_id / ab_owner 参数")
    lines.append("- 3) 若 1) 有，但带 book_id=strategy 为空：说明订单归属不在 strategy book（或 book_id 缺失），用 book_id=quant/carry 或加 allow_book_id_missing=1 复核")
    lines.append("- 4) 若 1) 也空：检查 user_data/datasets/*_orders.jsonl 是否有写入/回灌（按 mtime 排查）")

    return "\n".join([x for x in lines if str(x).strip()]).strip()[:1800]


def _agent_loss_rca_text_from_settlements(q: str) -> str:
    def _to_int(v: Any, default: int = 0) -> int:
        try:
            return int(v)
        except Exception:
            return default

    def _to_float(v: Any, default: float = 0.0) -> float:
        try:
            return float(v)
        except Exception:
            return default

    def _fmt_money(v: float) -> str:
        try:
            vv = float(v)
        except Exception:
            vv = 0.0
        if not math.isfinite(vv):
            vv = 0.0
        return f"{vv:+.2f}"

    def _fmt_ts_ms(ts_ms: int) -> str:
        try:
            if ts_ms <= 0:
                return "-"
            dt = datetime.fromtimestamp(float(ts_ms) / 1000.0)
            return dt.strftime("%m-%d %H:%M")
        except Exception:
            return "-"

    def _parse_window_sec(text: str) -> Optional[int]:
        s = str(text or "").lower()
        m = re.search(r"(\d{1,3})\s*(分钟|分|min|m)\b", s)
        if m:
            return int(m.group(1)) * 60
        m = re.search(r"(\d{1,3})\s*(小时|h)\b", s)
        if m:
            return int(m.group(1)) * 3600
        m = re.search(r"(\d{1,3})\s*(天|d)\b", s)
        if m:
            return int(m.group(1)) * 86400
        m = re.search(r"(\d{1,3})\s*(周|w)\b", s)
        if m:
            return int(m.group(1)) * 7 * 86400
        if "最近" in s:
            return None
        return None

    now_ms = int(_now_ms())
    window_sec_cfg = _to_int((CONFIG or {}).get("agent_pnl_drawdown_window_sec"), 86400)
    window_sec_cfg = max(60, min(30 * 86400, int(window_sec_cfg)))
    window_sec = _parse_window_sec(q) or window_sec_cfg
    since_ms = int(now_ms) - int(window_sec * 1000)

    limit_n = _to_int((CONFIG or {}).get("agent_pnl_recent_trade_n"), 20)
    limit_n = max(5, min(80, int(limit_n)))

    rows = []
    try:
        rows = [r for r in (_ab_settlements_get() or []) if isinstance(r, dict) and _to_int(r.get("ts"), 0) >= int(since_ms)]
    except Exception:
        rows = []
    rows.sort(key=lambda r: _to_int(r.get("ts"), 0))

    if not rows:
        return "\n".join([
            "未找到可用于归因的结算记录（ab_settlements 为空或窗口内无数据）。",
            "建议先确认：最近是否有 close 成交（/orders/recent），以及结算落库链路是否正常（tracker.stats / ingest）。",
        ]).strip()

    agg: Dict[str, Dict[str, Any]] = {}
    for r in rows:
        oid = str(r.get("order_id") or "").strip()
        eid = str(r.get("event_id") or "").strip()
        ts = _to_int(r.get("ts"), 0)
        pair = str(r.get("pair") or "").strip()
        reason = str(r.get("reason") or "").strip()
        owner = str(r.get("owner") or "").strip().lower()

        key = ""
        if oid:
            key = f"oid:{oid}"
        elif eid:
            key = f"eid:{eid}"
        else:
            key = f"ts:{ts}|pair:{pair}"

        rec = agg.get(key)
        if not isinstance(rec, dict):
            rec = {
                "ts": ts,
                "pair": pair,
                "order_id": (oid or None),
                "event_id": (eid or None),
                "pnl_usdc": 0.0,
                "notional_usdc": 0.0,
                "fee_abs": 0.0,
                "funding_abs": 0.0,
                "slippage_abs": 0.0,
                "duration_ms": None,
                "reason_counts": {},
                "owner_pnl": {},
            }
            agg[key] = rec

        if ts > _to_int(rec.get("ts"), 0):
            rec["ts"] = ts
        if pair and (not str(rec.get("pair") or "").strip()):
            rec["pair"] = pair
        if pair and (ts >= _to_int(rec.get("ts"), 0)):
            rec["pair"] = pair

        rec["pnl_usdc"] = _to_float(rec.get("pnl_usdc"), 0.0) + _to_float(r.get("pnl_usdc"), 0.0)
        rec["notional_usdc"] = _to_float(rec.get("notional_usdc"), 0.0) + max(0.0, _to_float(r.get("notional_usdc"), 0.0))

        fa = r.get("fee_abs")
        if fa is not None:
            rec["fee_abs"] = _to_float(rec.get("fee_abs"), 0.0) + _to_float(fa, 0.0)
        fu = r.get("funding_abs")
        if fu is not None:
            rec["funding_abs"] = _to_float(rec.get("funding_abs"), 0.0) + _to_float(fu, 0.0)
        sa = r.get("slippage_abs")
        if sa is not None:
            rec["slippage_abs"] = _to_float(rec.get("slippage_abs"), 0.0) + _to_float(sa, 0.0)

        dm = r.get("duration_ms")
        if dm is not None:
            cur_dm = rec.get("duration_ms")
            try:
                dm_i = int(dm)
            except Exception:
                dm_i = None
            if dm_i is not None and dm_i >= 0:
                if cur_dm is None or int(cur_dm or 0) < dm_i:
                    rec["duration_ms"] = int(dm_i)

        if reason:
            rc = rec.get("reason_counts")
            if not isinstance(rc, dict):
                rc = {}
            rc[reason] = _to_int(rc.get(reason), 0) + 1
            rec["reason_counts"] = rc

        if owner:
            op = rec.get("owner_pnl")
            if not isinstance(op, dict):
                op = {}
            op[owner] = _to_float(op.get(owner), 0.0) + _to_float(r.get("pnl_usdc"), 0.0)
            rec["owner_pnl"] = op

    trades = [x for x in agg.values() if isinstance(x, dict) and _to_int(x.get("ts"), 0) > 0]
    trades.sort(key=lambda x: _to_int(x.get("ts"), 0))
    if len(trades) > limit_n:
        trades = trades[-limit_n:]

    n = len(trades)
    total_pnl = sum(_to_float(t.get("pnl_usdc"), 0.0) for t in trades)
    gross_profit = sum(max(0.0, _to_float(t.get("pnl_usdc"), 0.0)) for t in trades)
    gross_loss = sum(max(0.0, -_to_float(t.get("pnl_usdc"), 0.0)) for t in trades)
    wins = sum(1 for t in trades if _to_float(t.get("pnl_usdc"), 0.0) > 0.0)
    win_rate = (float(wins) / float(n)) if n > 0 else 0.0
    pf = (gross_profit / gross_loss) if gross_loss > 0.0 else None

    cur = 0.0
    peak = 0.0
    max_dd = 0.0
    for t in trades:
        cur += _to_float(t.get("pnl_usdc"), 0.0)
        if cur >= peak:
            peak = float(cur)
        else:
            max_dd = max(float(max_dd), float(peak - cur))

    streak = 0
    for t in reversed(trades):
        if _to_float(t.get("pnl_usdc"), 0.0) < 0.0:
            streak += 1
        else:
            break

    fee_total = sum(_to_float(t.get("fee_abs"), 0.0) for t in trades)
    funding_total = sum(_to_float(t.get("funding_abs"), 0.0) for t in trades)
    slip_total = sum(_to_float(t.get("slippage_abs"), 0.0) for t in trades)

    by_pair: Dict[str, Dict[str, Any]] = {}
    for t in trades:
        p = str(t.get("pair") or "").strip() or "-"
        rec = by_pair.get(p)
        if rec is None:
            rec = {"pair": p, "pnl": 0.0, "n": 0}
            by_pair[p] = rec
        rec["pnl"] = _to_float(rec.get("pnl"), 0.0) + _to_float(t.get("pnl_usdc"), 0.0)
        rec["n"] = _to_int(rec.get("n"), 0) + 1
    losing_pairs = sorted(by_pair.values(), key=lambda x: _to_float(x.get("pnl"), 0.0))[:3]

    by_reason: Dict[str, Dict[str, Any]] = {}
    for t in trades:
        rc = t.get("reason_counts")
        if not isinstance(rc, dict) or not rc:
            continue
        top_reason = sorted(rc.items(), key=lambda kv: int(kv[1] or 0), reverse=True)[0][0]
        if not top_reason:
            continue
        rec = by_reason.get(top_reason)
        if rec is None:
            rec = {"reason": top_reason, "pnl": 0.0, "n": 0}
            by_reason[top_reason] = rec
        rec["pnl"] = _to_float(rec.get("pnl"), 0.0) + _to_float(t.get("pnl_usdc"), 0.0)
        rec["n"] = _to_int(rec.get("n"), 0) + 1
    losing_reasons = sorted(by_reason.values(), key=lambda x: _to_float(x.get("pnl"), 0.0))[:3]

    by_owner: Dict[str, float] = {}
    for t in trades:
        op = t.get("owner_pnl")
        if not isinstance(op, dict):
            continue
        for k, v in op.items():
            kk = str(k or "").strip().lower()
            if not kk:
                continue
            by_owner[kk] = _to_float(by_owner.get(kk), 0.0) + _to_float(v, 0.0)

    worst = sorted(trades, key=lambda x: _to_float(x.get("pnl_usdc"), 0.0))[:3]
    lines: List[str] = []
    lines.append("最近亏损归因（结算口径）")
    lines.append(f"- 窗口：{int(window_sec // 3600)}h 内，样本：{n} 笔 close")
    lines.append(f"- 总PnL：{_fmt_money(total_pnl)} USDC；胜率：{win_rate:.0%}；PF：{('-' if pf is None else f'{pf:.2f}')}；MaxDD：{max_dd:.2f} USDC；连亏：{streak}")
    if abs(fee_total) > 0.0 or abs(funding_total) > 0.0 or abs(slip_total) > 0.0:
        lines.append(f"- 费用/资金费/滑点：{_fmt_money(fee_total)}/{_fmt_money(funding_total)}/{_fmt_money(slip_total)} USDC")
    if losing_pairs:
        p_line = "；".join([f"{x.get('pair')}({_fmt_money(_to_float(x.get('pnl'), 0.0))},n={_to_int(x.get('n'), 0)})" for x in losing_pairs if isinstance(x, dict)])
        if p_line.strip():
            lines.append(f"- 亏损币对：{p_line}")
    if losing_reasons:
        r_line = "；".join([f"{x.get('reason')}({_fmt_money(_to_float(x.get('pnl'), 0.0))},n={_to_int(x.get('n'), 0)})" for x in losing_reasons if isinstance(x, dict)])
        if r_line.strip():
            lines.append(f"- 退出原因：{r_line}")
    if by_owner:
        owners = sorted(by_owner.items(), key=lambda kv: float(kv[1] or 0.0))
        o_line = "；".join([f"{k}({_fmt_money(float(v))})" for k, v in owners[:3]])
        if o_line.strip():
            lines.append(f"- 归属（owner）：{o_line}")
    if worst:
        w_lines = []
        for t in worst:
            ts = _fmt_ts_ms(_to_int(t.get("ts"), 0))
            pair = str(t.get("pair") or "").strip() or "-"
            pnl = _fmt_money(_to_float(t.get("pnl_usdc"), 0.0))
            notional = _to_float(t.get("notional_usdc"), 0.0)
            rr = (_to_float(t.get("pnl_usdc"), 0.0) / notional) if notional > 0.0 else 0.0
            dm = t.get("duration_ms")
            dmin = (int(dm) // 60000) if dm is not None and int(dm or 0) > 0 else None
            seg = f"{ts} {pair} {pnl} (ret={rr:.2%}"
            if dmin is not None:
                seg += f",dur={dmin}m"
            seg += ")"
            w_lines.append(seg)
        if w_lines:
            lines.append("- 最差交易：")
            lines.extend([f"  {x}" for x in w_lines[:3]])

    out = "\n".join([x for x in lines if str(x).strip()]).strip()
    return out[:1800]


