_AGENT_SKILLS_REGISTRY: Dict[str, Dict[str, Any]] = {}


def _agent_skill_register(name: str, handler: Any, *, title: str, category: str, input_schema: Dict[str, Any], description: str = "") -> None:
    nm = str(name or "").strip()
    if not nm:
        return
    _AGENT_SKILLS_REGISTRY[nm] = {
        "name": nm,
        "title": str(title or nm),
        "category": str(category or ""),
        "description": str(description or ""),
        "input_schema": (input_schema if isinstance(input_schema, dict) else {}),
        "handler": handler,
    }


def _agent_skills_list() -> List[Dict[str, Any]]:
    items = []
    for nm, meta in sorted(_AGENT_SKILLS_REGISTRY.items(), key=lambda x: str(x[0])):
        if not isinstance(meta, dict):
            continue
        items.append({
            "name": nm,
            "title": meta.get("title"),
            "category": meta.get("category"),
            "description": meta.get("description"),
            "input_schema": meta.get("input_schema") if isinstance(meta.get("input_schema"), dict) else {},
            "enabled": True,
        })
    try:
        if not _repo_fetch_enabled():
            for it in items:
                if str(it.get("name") or "") == "github.fetch":
                    it["enabled"] = False
    except Exception:
        pass
    return items


def _agent_skill_emit(trace_id: str, *, phase: str, tool: str, step_id: str, payload: Dict[str, Any]) -> None:
    item = {
        "id": uuid.uuid4().hex,
        "trace_id": str(trace_id or "").strip(),
        "ts": int(_now_ms()),
        "type": f"tool.{str(phase or '').strip().lower() or 'result'}",
        "channel": "skills",
        "tool": str(tool or "").strip(),
        "step_id": str(step_id or "").strip(),
        "payload": payload if isinstance(payload, dict) else {},
    }
    _agent_outbox_append_jsonl("chat.jsonl", item)


def _agent_skill_execute_step(trace_id: str, step: Dict[str, Any]) -> Dict[str, Any]:
    tool = str(step.get("tool") or "").strip()
    inp = step.get("input") if isinstance(step.get("input"), dict) else {}
    step_id = str(step.get("id") or "").strip() or uuid.uuid4().hex

    try:
        is_test = bool(str(os.environ.get("PYTEST_CURRENT_TEST", "") or "").strip()) or bool(str(os.environ.get("UNITTEST", "") or "").strip())
    except Exception:
        is_test = False
    if is_test and tool in ("sandbox.backtest", "sandbox.robustness", "github.fetch"):
        out = {"ok": True, "skipped": True, "tool": tool, "step_id": step_id}
        _agent_skill_emit(trace_id, phase="start", tool=tool, step_id=step_id, payload={"input": _json_sanitize(inp)})
        _agent_skill_emit(trace_id, phase="result", tool=tool, step_id=step_id, payload=out)
        return out

    _agent_skill_emit(trace_id, phase="start", tool=tool, step_id=step_id, payload={"input": _json_sanitize(inp)})

    meta = _AGENT_SKILLS_REGISTRY.get(tool)
    if not isinstance(meta, dict) or not meta.get("handler"):
        out = {"ok": False, "error": "unknown_tool", "tool": tool, "step_id": step_id}
        _agent_skill_emit(trace_id, phase="result", tool=tool, step_id=step_id, payload=out)
        return out

    timeout_map = {
        "sandbox.backtest": 240,
        "sandbox.robustness": 240,
        "github.fetch": 180,
        "binance_web3.crypto_market_rank": 60,
        "binance_web3.query_token_info": 25,
        "binance_web3.query_address_info": 25,
        "binance_spot.market_data": 25,
        "binance_spot.account": 25,
        "binance_spot.trade": 45,
        "changeset.draft": 60,
        "pipeline.r2_param": 60,
        "pipeline.r3_bugfix": 60,
        "approval.request": 60,
    }
    try:
        step_timeout = step.get("timeout_sec")
        if step_timeout is None:
            step_timeout = step.get("timeout")
        if step_timeout is None:
            step_timeout = inp.get("_timeout_sec")
        if step_timeout is None:
            step_timeout = timeout_map.get(tool)
        if step_timeout is None:
            step_timeout = CONFIG.get("agent_tool_step_timeout_sec", 8)
        timeout_sec = int(step_timeout or 0)
    except Exception:
        timeout_sec = 8
    timeout_sec = int(max(1, min(600, timeout_sec)))

    out: Dict[str, Any] = {"ok": False, "error": "tool_not_called"}
    handler_exc: Optional[BaseException] = None
    handler = meta.get("handler")

    def _call_handler() -> None:
        nonlocal out, handler_exc
        try:
            res = handler(inp)
            out = res if isinstance(res, dict) else {"ok": True, "result": res}
        except BaseException as e:
            handler_exc = e

    t = threading.Thread(target=_call_handler, daemon=True)
    t.start()
    t.join(timeout=float(timeout_sec) + 0.2)
    if t.is_alive():
        out = {"ok": False, "error": "tool_timeout", "tool": tool, "timeout_sec": int(timeout_sec), "step_id": step_id}
    elif handler_exc is not None:
        out = {"ok": False, "error": str(handler_exc) or "tool_failed"}

    try:
        raw = json.dumps(out, ensure_ascii=False)
        if len(raw) > 12000:
            out = {"ok": bool(out.get("ok")), "truncated": True, "keys": sorted(list(out.keys()))[:80]}
    except Exception:
        pass

    _agent_skill_emit(trace_id, phase="result", tool=tool, step_id=step_id, payload=out)
    return out


def _agent_skill_execute_plan(trace_id: str, tool_plan: List[Dict[str, Any]], *, limit_steps: int = 8) -> List[Dict[str, Any]]:
    tid = str(trace_id or "").strip() or uuid.uuid4().hex
    out: List[Dict[str, Any]] = []
    for step in (tool_plan if isinstance(tool_plan, list) else [])[: int(limit_steps)]:
        if not isinstance(step, dict):
            continue
        if str(step.get("tool") or "").strip() not in _AGENT_CHAT_ALLOWED_TOOLS:
            continue
        out.append({
            "tool": str(step.get("tool") or "").strip(),
            "step_id": str(step.get("id") or "").strip() or uuid.uuid4().hex,
            "result": _agent_skill_execute_step(tid, {"tool": step.get("tool"), "input": step.get("input"), "id": step.get("id")}),
        })
    return out


def _skill_metrics_recent(inp: Dict[str, Any]) -> Dict[str, Any]:
    ctx = _agent_chat_context_snapshot(limit_chars=9000)
    m = ctx.get("metrics") if isinstance(ctx, dict) else {}
    return {"ok": True, "ts": int(_now_ms()), "metrics": (m if isinstance(m, dict) else {}), "config": (ctx.get("config") if isinstance(ctx.get("config"), dict) else {})}


def _skill_health_get(inp: Dict[str, Any]) -> Dict[str, Any]:
    try:
        sch = TRACKER_STATE.get("scheduler")
    except Exception:
        sch = None
    try:
        started = bool(globals().get("_SCHEDULER_STARTED", False))
    except Exception:
        started = False
    th = globals().get("_SCHEDULER_THREAD")
    try:
        alive = bool(th is not None and hasattr(th, "is_alive") and th.is_alive())
    except Exception:
        alive = False
    try:
        c_started = bool(globals().get("_CARRY_WORKER_STARTED", False))
    except Exception:
        c_started = False
    c_th = globals().get("_CARRY_WORKER_THREAD")
    try:
        c_alive = bool(c_th is not None and hasattr(c_th, "is_alive") and c_th.is_alive())
    except Exception:
        c_alive = False
    return {
        "ok": True,
        "ts": int(_now_ms()),
        "scheduler": (sch if isinstance(sch, dict) else {}),
        "scheduler_thread": {"started": bool(started), "alive": bool(alive)},
        "carry_worker_thread": {"started": bool(c_started), "alive": bool(c_alive)},
    }


def _skill_signals_recent(inp: Dict[str, Any]) -> Dict[str, Any]:
    try:
        limit = int(inp.get("limit") or 40)
    except Exception:
        limit = 40
    limit = max(1, min(200, int(limit)))

    diverse = bool(inp.get("diverse", True))
    try:
        per_pair = int(inp.get("per_pair") or 8)
    except Exception:
        per_pair = 8
    per_pair = max(0, min(50, int(per_pair)))

    pair = (None if inp.get("pair") is None else str(inp.get("pair") or "").strip())
    strategy_id = (None if inp.get("strategy_id") is None else str(inp.get("strategy_id") or "").strip())
    group_id = (None if inp.get("group_id") is None else str(inp.get("group_id") or "").strip())
    side = (None if inp.get("side") is None else str(inp.get("side") or "").strip().lower())
    action = (None if inp.get("action") is None else str(inp.get("action") or "").strip().lower())
    if pair is not None and not pair:
        pair = None
    if strategy_id is not None and not strategy_id:
        strategy_id = None
    if group_id is not None and not group_id:
        group_id = None
    if side is not None and not side:
        side = None
    if action is not None and not action:
        action = None

    try:
        base0 = [e for e in EVENTS.values() if isinstance(e, dict)]
    except Exception:
        base0 = []

    def _ok(e: Dict[str, Any]) -> bool:
        if pair is not None and str(e.get("pair") or "").strip() != pair:
            return False
        if strategy_id is not None and str(e.get("strategy_id") or "").strip() != strategy_id:
            return False
        if group_id is not None and str(e.get("group_id") or "").strip() != group_id:
            return False
        if side is not None and str(e.get("side") or "").strip().lower() != side:
            return False
        if action is not None and str(e.get("action") or "").strip().lower() != action:
            return False
        return True

    base = [e for e in base0 if _ok(e)]

    def _sort_key(e: Dict[str, Any]) -> int:
        try:
            return int(e.get("ingested_ms") or e.get("received_ms") or e.get("ts") or 0)
        except Exception:
            return 0

    base.sort(key=_sort_key, reverse=True)

    selected: List[Dict[str, Any]] = []
    if diverse and per_pair > 0:
        by_pair: Dict[str, int] = {}
        for e in base:
            p = str(e.get("pair") or "").strip() or "UNKNOWN"
            c = int(by_pair.get(p, 0))
            if c >= per_pair:
                continue
            by_pair[p] = c + 1
            selected.append(e)
            if len(selected) >= int(limit):
                break
    else:
        selected = base[: int(limit)]

    def _compact_evt(e: Dict[str, Any]) -> Dict[str, Any]:
        di = e.get("decision_info") if isinstance(e.get("decision_info"), dict) else {}
        out = {
            "id": e.get("id") or e.get("eid"),
            "ts": e.get("ts"),
            "pair": e.get("pair"),
            "side": e.get("side"),
            "action": e.get("action"),
            "strategy_id": e.get("strategy_id"),
            "group_id": e.get("group_id"),
            "tag": e.get("tag"),
            "prob": e.get("prob"),
            "decision": di.get("decision"),
            "reason": di.get("reason"),
            "ingested_ms": e.get("ingested_ms") or e.get("received_ms"),
        }
        return {k: v for k, v in out.items() if v is not None}

    by_pair_cnt: Dict[str, int] = {}
    by_strategy_cnt: Dict[str, int] = {}
    for e in base[: min(len(base), 5000)]:
        try:
            p = str(e.get("pair") or "").strip() or "UNKNOWN"
        except Exception:
            p = "UNKNOWN"
        by_pair_cnt[p] = int(by_pair_cnt.get(p, 0)) + 1
        try:
            sid = str(e.get("strategy_id") or "").strip() or "UNKNOWN"
        except Exception:
            sid = "UNKNOWN"
        by_strategy_cnt[sid] = int(by_strategy_cnt.get(sid, 0)) + 1
    by_pair_sorted = sorted(by_pair_cnt.items(), key=lambda kv: kv[1], reverse=True)
    by_strategy_sorted = sorted(by_strategy_cnt.items(), key=lambda kv: kv[1], reverse=True)

    return {
        "ok": True,
        "ts": int(_now_ms()),
        "filters": {"pair": pair, "strategy_id": strategy_id, "group_id": group_id, "side": side, "action": action, "diverse": bool(diverse), "per_pair": int(per_pair)},
        "count_scanned": int(len(base)),
        "events": [_compact_evt(e) for e in selected if isinstance(e, dict)],
        "by_pair": {k: int(v) for k, v in by_pair_sorted[:50]},
        "by_strategy_id": {k: int(v) for k, v in by_strategy_sorted[:50]},
    }


def _skill_signals_reject_stats(inp: Dict[str, Any]) -> Dict[str, Any]:
    try:
        limit = int(inp.get("limit") or 2000)
    except Exception:
        limit = 2000
    limit = max(1, min(20000, int(limit)))

    include_shadow = bool(inp.get("include_shadow", False))

    evts0 = sorted([e for e in EVENTS.values() if isinstance(e, dict)], key=lambda x: x.get("ts", 0), reverse=True)
    if not include_shadow:
        def _is_shadow_mode(evt: Any) -> bool:
            if not isinstance(evt, dict):
                return False
            di = evt.get("decision_info")
            if not isinstance(di, dict):
                return False
            return str(di.get("reason") or "").strip().lower() == "shadow_mode"

        try:
            evts0 = [e for e in evts0 if not _is_shadow_mode(e)]
        except Exception:
            pass
    evts = evts0[:limit]
    by_decision: Dict[str, int] = {}
    by_reason: Dict[str, int] = {}
    with_decision = 0
    for e in evts:
        di = e.get("decision_info")
        if not isinstance(di, dict):
            continue
        d = str(di.get("decision") or "unknown")
        with_decision += 1
        by_decision[d] = int(by_decision.get(d, 0)) + 1
        if d != "enter":
            r = di.get("reason")
            key = (str(r).strip() if r is not None else "")
            if not key:
                key = "none"
            by_reason[key] = int(by_reason.get(key, 0)) + 1

    reasons_sorted = sorted(by_reason.items(), key=lambda kv: kv[1], reverse=True)
    return {
        "ok": True,
        "ts": int(_now_ms()),
        "limit": int(limit),
        "total_events": int(len(evts)),
        "with_decision": int(with_decision),
        "by_decision": by_decision,
        "by_reason": {k: int(v) for k, v in reasons_sorted},
    }


def _skill_audit_alerts_evaluate(inp: Dict[str, Any]) -> Dict[str, Any]:
    pair = (None if inp.get("pair") is None else str(inp.get("pair") or "").strip())
    if pair is not None and not pair:
        pair = None
    try:
        lookback_days = float(inp.get("lookback_days") or 7)
    except Exception:
        lookback_days = 7.0
    lookback_days = max(0.1, min(3650.0, float(lookback_days)))
    return _audit_alerts_evaluate_internal(pair=pair, lookback_days=float(lookback_days), now_ms=int(_now_ms()))


def _tracker_compact_sync_err(err0: Any) -> Optional[str]:
    if err0 is None:
        return None
    try:
        s = str(err0)
    except Exception:
        return None
    s2 = s.strip()
    if not s2:
        return None
    code = None
    if s2.startswith("(") and "," in s2:
        try:
            head = s2[1:].split(",", 1)[0].strip()
            if head.isdigit():
                code = int(head)
        except Exception:
            code = None
    if code is not None:
        msg = f"HTTP {code}"
        if "cloudfront" in s2.lower():
            msg = f"{msg} · CloudFront"
        return msg
    if len(s2) > 280:
        return s2[:280] + "…"
    return s2


def _tracker_compact_sync_state(src0: Any) -> Dict[str, Any]:
    if not isinstance(src0, dict):
        src0 = {}
    out0: Dict[str, Any] = {}
    for k in (
        "sync_ok",
        "ts",
        "last_sync_ts",
        "open_position_count",
        "pruned_open_positions",
        "rate_limit_until_ts",
        "rate_limit_backoff_ms",
    ):
        if k in src0:
            out0[k] = src0.get(k)
    out0["last_sync_error"] = _tracker_compact_sync_err(src0.get("last_sync_error"))
    return out0


def _skill_tracker_stats(inp: Dict[str, Any]) -> Dict[str, Any]:
    view = str(inp.get("view") or "ui").strip().lower() or "ui"
    now_ms = int(_now_ms())
    if view not in ("ui", "summary", "dashboard"):
        view = "ui"
    return {
        "ok": True,
        "ts": now_ms,
        "hl": _tracker_compact_sync_state(TRACKER_STATE.get("hl")),
        "aster": _tracker_compact_sync_state(TRACKER_STATE.get("aster")),
    }


def _skill_tracker_sync_recent(inp: Dict[str, Any]) -> Dict[str, Any]:
    venue = str(inp.get("venue") or "all").strip().lower() or "all"
    try:
        limit = int(inp.get("limit") or 30)
    except Exception:
        limit = 30
    limit = max(1, min(200, int(limit)))

    def _pick(vn: str) -> List[Dict[str, Any]]:
        st = TRACKER_STATE.get(vn)
        if not isinstance(st, dict):
            return []
        hist = st.get("sync_history")
        if not isinstance(hist, list) or not hist:
            it = {
                "ts": int(st.get("last_sync_ts") or st.get("ts") or 0) or None,
                "ok": st.get("sync_ok"),
                "error": _tracker_compact_sync_err(st.get("last_sync_error")),
            }
            return [it] if it.get("ts") else []
        out: List[Dict[str, Any]] = []
        for x in hist[-limit:]:
            if not isinstance(x, dict):
                continue
            out.append({
                "ts": x.get("ts"),
                "ok": x.get("ok"),
                "error": _tracker_compact_sync_err(x.get("error")),
                "skipped": bool(x.get("skipped", False)) if x.get("skipped") is not None else None,
                "until": x.get("until"),
            })
        return out

    res: Dict[str, Any] = {"ok": True, "ts": int(_now_ms())}
    if venue in ("hl", "hyperliquid"):
        res["hl"] = _pick("hl")
    elif venue in ("aster",):
        res["aster"] = _pick("aster")
    else:
        res["hl"] = _pick("hl")
        res["aster"] = _pick("aster")
    return res


