def _skill_doc_retrieve(inp: Dict[str, Any]) -> Dict[str, Any]:
    query = str(inp.get("query") or inp.get("q") or inp.get("text") or "").strip()
    doc = (None if inp.get("doc") is None else str(inp.get("doc") or "").strip())
    try:
        max_sections = int(inp.get("max_sections") or 4)
    except Exception:
        max_sections = 4
    try:
        max_chars_total = int(inp.get("max_chars_total") or 6500)
    except Exception:
        max_chars_total = 6500
    max_sections = max(1, min(8, int(max_sections)))
    max_chars_total = max(1200, min(20000, int(max_chars_total)))

    if not query:
        return {"ok": False, "error": "missing_query", "ts": int(_now_ms())}

    allowed = _doc_allowed_map()
    targets: List[str] = []
    if doc:
        if doc in allowed:
            targets = [doc]
        else:
            return {"ok": False, "error": "doc_not_allowed", "doc": doc, "ts": int(_now_ms())}
    else:
        targets = list(allowed.keys())

    snippets: List[Dict[str, Any]] = []
    for d in targets:
        p = allowed.get(d)
        if (not p) or (not p.exists()):
            continue
        try:
            snippets.extend(_doc_retrieve_snippets(p, query, max_sections=max_sections, max_chars_total=max_chars_total))
        except Exception:
            continue
    return {"ok": True, "ts": int(_now_ms()), "query": query, "doc": doc, "snippets": snippets, "count": int(len(snippets))}


