def _skill_code_search(inp: Dict[str, Any]) -> Dict[str, Any]:
    query = str(inp.get("query") or inp.get("q") or inp.get("text") or "").strip()
    if not query:
        return {"ok": False, "error": "missing_query", "ts": int(_now_ms())}
    try:
        max_hits = int(inp.get("max_hits") or 40)
    except Exception:
        max_hits = 40
    max_hits = max(5, min(200, int(max_hits)))

    root = _project_root_dir()
    q = query.lower()
    glob_pat = inp.get("glob")
    include_vendor = bool(inp.get("include_vendor", False))
    try:
        max_files = int(inp.get("max_files") or 2000)
    except Exception:
        max_files = 2000
    max_files = max(50, min(20000, int(max_files)))

    files_inp = inp.get("files")
    file_list: List[Path] = []
    if isinstance(files_inp, str):
        p = _agent_code_allowed_resolve(files_inp)
        if p:
            file_list = [p]
    elif isinstance(files_inp, list) and files_inp:
        for x in files_inp[:400]:
            p = _agent_code_allowed_resolve(str(x))
            if p:
                file_list.append(p)
    else:
        try:
            if isinstance(glob_pat, str) and glob_pat.strip():
                pats = [glob_pat.strip()]
            else:
                pats = ["**/*"]
        except Exception:
            pats = ["**/*"]
        seen: set = set()
        for pat in pats[:6]:
            for p in root.glob(pat):
                if len(file_list) >= max_files:
                    break
                try:
                    if not p.is_file():
                        continue
                except Exception:
                    continue
                rel = str(p.relative_to(root)).replace("\\", "/")
                if not include_vendor:
                    if rel.startswith(".git/") or rel.startswith("node_modules/") or rel.startswith(".venv/") or rel.startswith("venv/"):
                        continue
                if rel.startswith("__pycache__/") or "/__pycache__/" in f"/{rel}/":
                    continue
                if rel.startswith("user_data/datasets/"):
                    continue
                if rel in seen:
                    continue
                seen.add(rel)
                p2 = _agent_code_allowed_resolve(rel)
                if p2:
                    file_list.append(p2)
            if len(file_list) >= max_files:
                break

    hits: List[Dict[str, Any]] = []
    files_scanned = 0
    for p in file_list[:max_files]:
        files_scanned += 1
        try:
            lines = _code_file_lines_cached(p)
        except Exception:
            continue
        if not lines:
            extra, _scanned = _text_search_streaming(p, q, max_hits=int(max_hits) - int(len(hits)))
            if extra:
                hits.extend(extra)
        else:
            for i, ln in enumerate(lines):
                if q in str(ln or "").lower():
                    t = _redact_sensitive_text(_clip_str(str(ln or "").strip(), 280))
                    hits.append({"file": str(p.name), "line": int(i + 1), "text": t})
                    if len(hits) >= max_hits:
                        break
        if len(hits) >= max_hits:
            break
    return {"ok": True, "ts": int(_now_ms()), "query": query, "hits": hits, "count": int(len(hits)), "files_scanned": int(files_scanned)}


def _skill_fs_glob(inp: Dict[str, Any]) -> Dict[str, Any]:
    pattern = str(inp.get("pattern") or inp.get("glob") or "**/*").strip() or "**/*"
    include_vendor = bool(inp.get("include_vendor", False))
    try:
        max_items = int(inp.get("max_items") or 500)
    except Exception:
        max_items = 500
    max_items = max(10, min(5000, int(max_items)))

    root = _project_root_dir()
    items: List[Dict[str, Any]] = []
    seen: set = set()
    try:
        it = root.glob(pattern)
    except Exception:
        it = root.glob("**/*")

    for p in it:
        if len(items) >= max_items:
            break
        try:
            if not p.is_file():
                continue
        except Exception:
            continue
        try:
            rel = str(p.relative_to(root)).replace("\\", "/")
        except Exception:
            rel = str(p)
        if rel in seen:
            continue
        seen.add(rel)
        if not include_vendor:
            if rel.startswith(".git/") or rel.startswith("node_modules/") or rel.startswith(".venv/") or rel.startswith("venv/"):
                continue
        if rel.startswith("__pycache__/") or "/__pycache__/" in f"/{rel}/":
            continue
        try:
            st = p.stat()
            size = int(st.st_size)
        except Exception:
            size = None
        items.append({"path": rel, "size": size})
    return {"ok": True, "ts": int(_now_ms()), "pattern": pattern, "items": items, "count": int(len(items))}


