def _skill_automation_control_plane_orchestrator(inp: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(inp, dict):
        inp = {}
    trace_id = str(inp.get("trace_id") or "").strip() or uuid.uuid4().hex
    intent = str(inp.get("intent") or "observe").strip().lower() or "observe"
    target = str(inp.get("target") or "").strip().lower() or "paramopt"
    mode = str(inp.get("mode") or "plan_only").strip().lower() or "plan_only"
    if mode != "plan_only":
        mode = "plan_only"
    risk_level = str(inp.get("risk_level") or "R0").strip().upper() or "R0"
    params = inp.get("params") if isinstance(inp.get("params"), dict) else {}
    env = str(inp.get("env") or "").strip().lower() or None

    def _templates_default() -> Dict[str, Any]:
        return {
            "strategy_explore_8h_with_baseline": {
                "title": "策略级 8h Explore（baseline 回测前置）",
                "intent": "trigger",
                "target": "paramopt_explore",
                "risk_level": "R2",
                "baseline_backtest": {"enabled": True, "config": "user_data/config_local_backtest.json", "days": 120, "strategy": None},
                "audits": [{"tool": "audit.data_quality", "input": {"pair": "BTC/USDT", "lookback_days": 7}}],
                "trigger_params": {},
            },
            "system_kpi_conservative_paramopt": {
                "title": "系统级 KPI 触发（保守 ParamOpt）",
                "intent": "trigger",
                "target": "paramopt",
                "risk_level": "R2",
                "baseline_backtest": {"enabled": True, "config": "user_data/config_local_backtest.json", "days": 120, "strategy": None},
                "audits": [
                    {"tool": "audit.execution_quality", "input": {"lookback_days": 14, "include_shadow": True}},
                    {"tool": "audit.alerts_evaluate", "input": {"lookback_days": 14}},
                ],
                "trigger_params": {"presets": ["o6"]},
            },
            "auto_system_kpi_decision": {
                "title": "系统级 KPI 自动决策（保守 ParamOpt / Explore）",
                "engine": "auto",
                "decision": {
                    "type": "pnl_trigger_eval",
                    "pick": "any",
                    "if_true": "system_kpi_conservative_paramopt",
                    "if_false": "strategy_explore_8h_with_baseline",
                },
            },
        }

    def _templates_load() -> Dict[str, Any]:
        base = _templates_default()
        raw = AUTOMATION.get("control_plane_orchestrator_templates_json", None)
        if raw is None:
            return base
        try:
            s = str(raw).strip()
        except Exception:
            s = ""
        if not s:
            return base
        try:
            d = json.loads(s)
        except Exception:
            return base
        if not isinstance(d, dict):
            return base
        for k, v in d.items():
            kk = str(k).strip()
            if not kk or not isinstance(v, dict):
                continue
            base[kk] = v
        return base

    def _template_apply(tpl: Dict[str, Any], overrides: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        out0 = dict(tpl)
        if isinstance(overrides, dict) and overrides:
            for k, v in overrides.items():
                if k in ("baseline_backtest", "trigger_params", "decision") and isinstance(v, dict) and isinstance(out0.get(k), dict):
                    vv = dict(out0.get(k))
                    vv.update(v)
                    out0[k] = vv
                else:
                    out0[k] = v
        return out0

    def _pnl_trigger_eval_override(now_ms: int, decision: Dict[str, Any]) -> List[Dict[str, Any]]:
        if not isinstance(decision, dict):
            decision = {}
        try:
            window_sec = decision.get("window_sec")
            if window_sec is None:
                window_sec = CONFIG.get("agent_pnl_drawdown_window_sec", 86400)
            window_sec = int(window_sec or 86400)
        except Exception:
            window_sec = 86400
        window_sec = max(60, min(30 * 86400, int(window_sec)))
        since_ms = int(now_ms) - int(window_sec * 1000)

        try:
            limit_n = decision.get("recent_trade_n")
            if limit_n is None:
                limit_n = CONFIG.get("agent_pnl_recent_trade_n", 20)
            limit_n = int(limit_n or 20)
        except Exception:
            limit_n = 20
        limit_n = max(5, min(200, int(limit_n)))

        trades = _agent_recent_trades_from_settlements(since_ms=since_ms, limit=limit_n)
        if not trades:
            return []

        recent_ids: List[str] = []
        for t in trades:
            try:
                eid = str(t.get("event_id") or "").strip()
            except Exception:
                eid = ""
            if eid:
                recent_ids.append(eid)
        recent_ids = recent_ids[-limit_n:]

        base_trace_id = recent_ids[-1] if recent_ids else None
        if base_trace_id is None:
            return []

        streak = 0
        for t in reversed(trades):
            try:
                pnl = float(t.get("pnl_usdc") or 0.0)
            except Exception:
                pnl = 0.0
            if pnl < 0.0:
                streak += 1
            else:
                break

        dd = 0.0
        peak = 0.0
        cur = 0.0
        for t in trades:
            try:
                cur += float(t.get("ret_ratio") or 0.0)
            except Exception:
                cur += 0.0
            if cur >= peak:
                peak = float(cur)
            else:
                dd = max(float(dd), float(peak) - float(cur))

        try:
            k = decision.get("loss_streak_k")
            if k is None:
                k = int(AUTOMATION.get("paramopt_loss_trigger_streak_k", CONFIG.get("agent_pnl_loss_streak_k", 5)) or CONFIG.get("agent_pnl_loss_streak_k", 5) or 5)
            k = int(k or 5)
        except Exception:
            k = 5
        k = max(1, min(50, int(k)))

        try:
            dd_thr = decision.get("drawdown_thr")
            if dd_thr is None:
                dd_thr = CONFIG.get("agent_pnl_drawdown_thr", 0.05)
            dd_thr = float(dd_thr or 0.05)
        except Exception:
            dd_thr = 0.05
        dd_thr = float(max(0.0, min(0.50, float(dd_thr))))

        out: List[Dict[str, Any]] = []
        if int(streak) >= int(k):
            out.append({"trigger": "loss.streak.trigger", "base_trace_id": base_trace_id, "recent_trade_event_ids": recent_ids, "window_sec": int(window_sec), "threshold": int(k), "observed": int(streak), "drawdown_ret": float(dd)})
        if float(dd) >= float(dd_thr):
            out.append({"trigger": "pnl.drawdown.trigger", "base_trace_id": base_trace_id, "recent_trade_event_ids": recent_ids, "window_sec": int(window_sec), "threshold": float(dd_thr), "observed": float(dd), "loss_streak": int(streak)})
        return out

    allowed_tools = {
        "metrics.recent",
        "tracker.stats",
        "agent.trace.replay",
        "audit.alerts_evaluate",
        "audit.data_quality",
        "audit.execution_quality",
        "sandbox.backtest",
        "sandbox.robustness",
        "qwen.control.gtw_run",
        "qwen.control.shadow_loop_run",
        "qwen.control.paramopt_trigger",
        "qwen.control.paramopt_explore_trigger",
        "qwen.control.system_monitor_run",
    }

    def _step(tool: str, input0: Optional[Dict[str, Any]] = None, *, requires_approval: bool = False) -> Dict[str, Any]:
        return {"tool": tool, "input": (_json_sanitize(input0) if isinstance(input0, dict) else {}), "requires_approval": bool(requires_approval)}

    tool_plan: List[Dict[str, Any]] = []
    tool_plan.append(_step("metrics.recent", {}))
    tool_plan.append(_step("tracker.stats", {"view": "summary"}))

    base_trace_id = str(inp.get("base_trace_id") or inp.get("focus_trace_id") or "").strip() or None
    if base_trace_id:
        tool_plan.append(_step("agent.trace.replay", {"trace_id": str(base_trace_id)}))

    templates = _templates_load()
    template_id = str(inp.get("template") or inp.get("template_id") or "").strip() or None
    template_overrides = inp.get("template_overrides") if isinstance(inp.get("template_overrides"), dict) else None
    template_applied = None
    auto_decision = None
    if template_id and template_id in templates and isinstance(templates.get(template_id), dict):
        tpl_raw = _template_apply(templates.get(template_id), template_overrides)
        engine = str(tpl_raw.get("engine") or "rule").strip().lower() or "rule"
        if engine == "auto":
            decision = tpl_raw.get("decision") if isinstance(tpl_raw.get("decision"), dict) else {}
            if str(decision.get("type") or "").strip().lower() == "pnl_trigger_eval":
                now_ms = int(_now_ms())
                use_override = any(
                    decision.get(k) is not None
                    for k in (
                        "window_sec",
                        "loss_streak_k",
                        "drawdown_thr",
                        "recent_trade_n",
                    )
                )
                if use_override:
                    try:
                        evs = _pnl_trigger_eval_override(int(now_ms), decision)
                    except Exception:
                        evs = []
                else:
                    try:
                        evs = _agent_pnl_trigger_eval(int(now_ms))
                    except Exception:
                        evs = []
                evs = [e for e in evs if isinstance(e, dict)]
                trig_names = [str(e.get("trigger") or "").strip() for e in evs if str(e.get("trigger") or "").strip()]
                bad_triggers = decision.get("bad_triggers") if isinstance(decision.get("bad_triggers"), list) else None
                if bad_triggers:
                    bt = set([str(x).strip() for x in bad_triggers if str(x).strip()])
                    is_bad = bool([t for t in trig_names if t in bt])
                else:
                    is_bad = bool(trig_names)
                if_true = str(decision.get("if_true") or "system_kpi_conservative_paramopt").strip()
                if_false = str(decision.get("if_false") or "strategy_explore_8h_with_baseline").strip()
                chosen = if_true if is_bad else if_false
                auto_decision = {
                    "engine": "pnl_trigger_eval",
                    "now_ms": int(now_ms),
                    "override_enabled": bool(use_override),
                    "window_sec": (None if decision.get("window_sec") is None else int(decision.get("window_sec") or 0)),
                    "loss_streak_k": (None if decision.get("loss_streak_k") is None else int(decision.get("loss_streak_k") or 0)),
                    "drawdown_thr": (None if decision.get("drawdown_thr") is None else float(decision.get("drawdown_thr") or 0.0)),
                    "recent_trade_n": (None if decision.get("recent_trade_n") is None else int(decision.get("recent_trade_n") or 0)),
                    "bad_triggers": (None if not bad_triggers else [str(x).strip() for x in bad_triggers if str(x).strip()][:20]),
                    "is_bad": bool(is_bad),
                    "triggers": trig_names[:20],
                    "chosen_template": chosen,
                }
                tpl0 = templates.get(chosen) if isinstance(templates.get(chosen), dict) else None
                if tpl0 is None:
                    tpl0 = templates.get(if_false) if isinstance(templates.get(if_false), dict) else None
                if tpl0 is None:
                    tpl0 = templates.get("strategy_explore_8h_with_baseline")
                tpl0 = _template_apply(tpl0 if isinstance(tpl0, dict) else {}, template_overrides)
                template_applied = str(template_id)
            else:
                tpl0 = tpl_raw
                template_applied = str(template_id)
        else:
            tpl0 = tpl_raw
            template_applied = str(template_id)
        intent = str(tpl0.get("intent") or intent).strip().lower() or intent
        target = str(tpl0.get("target") or target).strip().lower() or target
        risk_level = str(tpl0.get("risk_level") or risk_level).strip().upper() or risk_level
        try:
            tp = tpl0.get("trigger_params") if isinstance(tpl0.get("trigger_params"), dict) else {}
            if isinstance(params, dict) and params:
                tp2 = dict(tp)
                tp2.update(params)
                params = tp2
            else:
                params = dict(tp)
        except Exception:
            pass
        audits = tpl0.get("audits") if isinstance(tpl0.get("audits"), list) else []
        for a0 in audits:
            if not isinstance(a0, dict):
                continue
            tool0 = str(a0.get("tool") or "").strip()
            if tool0 not in ("audit.alerts_evaluate", "audit.data_quality", "audit.execution_quality"):
                continue
            in0 = a0.get("input") if isinstance(a0.get("input"), dict) else {}
            tool_plan.append(_step(tool0, in0))
        bb = tpl0.get("baseline_backtest") if isinstance(tpl0.get("baseline_backtest"), dict) else {}
        if bool(bb.get("enabled", False)):
            cfg = str(bb.get("config") or "user_data/config_local_backtest.json")
            days = bb.get("days", 120)
            try:
                days_i = int(days)
            except Exception:
                days_i = 120
            days_i = max(30, min(3650, int(days_i)))
            timerange = _agent_pick_timerange_for_config(config_path=str(cfg), days=int(days_i))
            strategy0 = bb.get("strategy")
            st_name = None if strategy0 is None else str(strategy0).strip()
            inp_bt = {"config": str(cfg), "timerange": (None if timerange is None else str(timerange))}
            if st_name:
                inp_bt["strategy"] = st_name
            tool_plan.append(_step("sandbox.backtest", inp_bt))

    if intent not in ("observe", "trigger", "explain"):
        intent = "observe"

    if intent == "trigger":
        trig_evt = str(inp.get("trigger_event") or "automation.control_plane.orchestrator").strip() or "automation.control_plane.orchestrator"

        if target == "gtw":
            tool_plan.append(_step("qwen.control.gtw_run", {"trace_id": trace_id, "force": bool(params.get("force", False)), "trigger_event": trig_evt}, requires_approval=True))
        elif target == "shadow_loop":
            payload = {"trace_id": trace_id, "mode": str(params.get("mode") or "new"), "trigger_event": trig_evt}
            for k in ("decision_id", "gtw_path_id", "idempotency_key", "candidate_limit", "baseline_enabled", "skip_paramopt", "gates"):
                if k in params:
                    payload[k] = params.get(k)
            tool_plan.append(_step("qwen.control.shadow_loop_run", payload, requires_approval=True))
        elif target == "system_monitor":
            payload = {"trace_id": trace_id, "trigger_event": trig_evt}
            for k in ("pair", "strategy", "lookback_days", "timerange_days", "run_link_check", "run_backtest", "run_triage", "generate_changeset", "request_approval", "allow_auto_exec"):
                if k in params:
                    payload[k] = params.get(k)
            if "run_link_check" not in payload:
                payload["run_link_check"] = True
            if "request_approval" not in payload:
                payload["request_approval"] = True
            if "allow_auto_exec" not in payload:
                payload["allow_auto_exec"] = False
            tool_plan.append(_step("qwen.control.system_monitor_run", payload, requires_approval=True))
        elif target == "paramopt_explore":
            tool_plan.append(_step("qwen.control.paramopt_explore_trigger", {"trace_id": trace_id, "trigger_event": trig_evt}, requires_approval=True))
        else:
            payload = {"trace_id": trace_id, "trigger_event": trig_evt}
            preset = str(params.get("preset") or "").strip().lower()
            presets = params.get("presets") if isinstance(params.get("presets"), list) else None
            if presets is not None:
                payload["presets"] = [str(x).strip().lower() for x in presets if str(x).strip()][:7]
            elif preset:
                payload["preset"] = preset
            budget = params.get("budget") if isinstance(params.get("budget"), dict) else None
            if isinstance(budget, dict) and budget:
                payload["budget"] = _json_sanitize(budget)
            tool_plan.append(_step("qwen.control.paramopt_trigger", payload, requires_approval=True))

    tool_plan = [st for st in tool_plan if isinstance(st, dict) and str(st.get("tool") or "").strip() in allowed_tools]
    try:
        tool_plan = _agent_chat_tool_plan_sanitize(tool_plan, intent_level="L0", risk_uncertain=(risk_level != "R0"))
    except Exception:
        tool_plan = [{"tool": str(st.get("tool")), "input": _json_sanitize(st.get("input")), "requires_approval": bool(st.get("requires_approval"))} for st in tool_plan]

    out = {
        "ok": True,
        "trace_id": trace_id,
        "tool": "automation.control_plane.orchestrator",
        "mode": "plan_only",
        "intent": str(intent),
        "target": str(target),
        "template": template_applied,
        "auto_decision": _json_sanitize(auto_decision) if isinstance(auto_decision, dict) else None,
        "env": env,
        "risk_level": str(risk_level),
        "tool_plan": tool_plan,
        "templates_available": sorted([str(k) for k in templates.keys() if str(k).strip()])[:200],
        "next": {"execute_endpoint": "POST /agent/skills/execute", "async_default": True, "payload": {"trace_id": trace_id, "tool_plan": tool_plan}},
        "ts": int(_now_ms()),
    }
    try:
        _agent_outbox_append_jsonl(
            "chat.jsonl",
            {
                "id": uuid.uuid4().hex,
                "trace_id": str(trace_id),
                "ts": int(_now_ms()),
                "type": "tool.plan.generated",
                "channel": "skills",
                "tool": "automation.control_plane.orchestrator",
                "input": _json_sanitize(inp),
                "result": _json_sanitize(out),
            },
        )
    except Exception:
        pass
    return out


def _skill_approval_request(inp: Dict[str, Any]) -> Dict[str, Any]:
    reason = str(inp.get("reason") or "").strip() or "approval_requested"
    rid = hashlib.sha256(f"approval.request|{_now_ms()}|{uuid.uuid4().hex}".encode("utf-8")).hexdigest()[:16]
    trace_id = str(inp.get("trace_id") or "").strip() or rid
    _agent_outbox_append_jsonl("chat.jsonl", {"id": rid, "trace_id": trace_id, "ts": int(_now_ms()), "type": "approval.requested", "channel": "skills", "reason": reason, "input": _json_sanitize(inp)})
    try:
        _approval_append({"id": rid, "trace_id": trace_id, "decision": "pending", "reason": reason, "action": "approval.request", "scope": "skills", "ts": int(_now_ms())})
    except Exception:
        pass
    return {"ok": True, "request_id": rid, "status": "pending", "reason": reason}


def _skill_telegram_send(inp: Dict[str, Any]) -> Dict[str, Any]:
    msg = str(inp.get("message") or "").strip()
    if not msg:
        return {"ok": False, "error": "empty_message"}
    if not _agent_push_cfg_bool("telegram_enabled", False):
        return {"ok": False, "error": "telegram_disabled"}
    if _telegram_env_token() is None:
        return {"ok": False, "error": "missing_telegram_token"}
    if _telegram_chat_id() is None:
        return {"ok": False, "error": "missing_telegram_chat_id"}

    trace_id = str(inp.get("trace_id") or "").strip() or uuid.uuid4().hex
    severity = str(inp.get("severity") or "info").strip().lower() or "info"
    idempotency_key = None
    try:
        idempotency_key = str(inp.get("idempotency_key") or "").strip() or None
    except Exception:
        idempotency_key = None
    if not idempotency_key:
        idempotency_key = hashlib.sha256(f"telegram.send|{trace_id}|{msg}".encode("utf-8")).hexdigest()
    event_id = hashlib.sha256(f"{idempotency_key}".encode("utf-8")).hexdigest()[:32]
    ts_ms = int(_now_ms())
    env = {
        "id": event_id,
        "trace_id": trace_id,
        "ts": ts_ms,
        "type": "push.send",
        "channel": "telegram",
        "severity": severity,
        "message": msg,
        "extras": {"source": "skill.telegram.send"},
        "idempotency_key": idempotency_key,
    }
    try:
        ttl_sec = inp.get("ttl_sec")
        if ttl_sec is None:
            ttl_sec = inp.get("ttl")
        if ttl_sec is not None:
            ttl_i = int(max(0, min(86400, int(ttl_sec))))
            if ttl_i > 0:
                env["expires_at"] = int(ts_ms + ttl_i * 1000)
    except Exception:
        pass
    _agent_outbox_append_jsonl("telegram.jsonl", env)
    return {"ok": True, "queued": True, "id": event_id, "trace_id": trace_id, "ts": ts_ms}


def _agent_skill_binance_spot_cfg() -> Dict[str, Any]:
    cfg = CONFIG.get("agent_skills")
    if not isinstance(cfg, dict):
        cfg = {}
    sp = cfg.get("binance_spot")
    if not isinstance(sp, dict):
        sp = {}
    return sp


def _agent_skill_binance_spot_set_cfg(next_cfg: Dict[str, Any]) -> None:
    cfg = CONFIG.get("agent_skills")
    if not isinstance(cfg, dict):
        cfg = {}
    cfg["binance_spot"] = dict(next_cfg or {})
    CONFIG["agent_skills"] = cfg


def _mask_secret_like(v: Any) -> str:
    s = str(v or "").strip()
    if not s:
        return ""
    if len(s) <= 8:
        return "*" * len(s)
    return s[:4] + ("*" * (len(s) - 8)) + s[-4:]


def _binance_spot_skill_api_key() -> str:
    cfg = _agent_skill_binance_spot_cfg()
    v = str(cfg.get("api_key") or "").strip()
    if v:
        return v
    return str(os.environ.get("BINANCE_SPOT_API_KEY", "") or "").strip()


def _binance_spot_skill_secret() -> str:
    cfg = _agent_skill_binance_spot_cfg()
    v = str(cfg.get("api_secret") or "").strip()
    if v:
        return v
    return str(os.environ.get("BINANCE_SPOT_API_SECRET", "") or "").strip()


def _binance_spot_skill_testnet() -> bool:
    cfg = _agent_skill_binance_spot_cfg()
    v = cfg.get("testnet")
    if v is not None:
        return bool(v)
    env_v = str(os.environ.get("BINANCE_SPOT_TESTNET", "") or "").strip().lower()
    return env_v in ("1", "true", "yes", "on", "y")


def _binance_spot_skill_base_url() -> str:
    cfg = _agent_skill_binance_spot_cfg()
    b = str(cfg.get("base_url") or "").strip().rstrip("/")
    if b:
        return b
    if _binance_spot_skill_testnet():
        return "https://testnet.binance.vision"
    return "https://api.binance.com"


def _binance_spot_skill_timeout_sec(default_v: float = 10.0) -> float:
    cfg = _agent_skill_binance_spot_cfg()
    try:
        v = float(cfg.get("timeout_sec") or default_v)
    except Exception:
        v = float(default_v)
    if not math.isfinite(float(v)):
        v = float(default_v)
    return float(max(1.0, min(60.0, float(v))))


def _binance_spot_skill_recv_window_ms(default_v: int = 15000) -> int:
    cfg = _agent_skill_binance_spot_cfg()
    try:
        v = int(cfg.get("recv_window_ms") or default_v)
    except Exception:
        v = int(default_v)
    return int(max(1000, min(60000, int(v))))


def _binance_spot_skill_http(method: str, path: str, *, params: Optional[Dict[str, Any]] = None, signed: bool = False, timeout_sec: Optional[float] = None) -> Any:
    m = str(method or "GET").strip().upper() or "GET"
    p = {k: v for k, v in dict(params or {}).items() if v is not None}
    base = _binance_spot_skill_base_url().rstrip("/")
    url = base + str(path)
    headers: Dict[str, str] = {"Accept": "application/json"}
    if signed:
        api_key = _binance_spot_skill_api_key()
        secret = _binance_spot_skill_secret()
        if not api_key:
            raise RuntimeError("missing_binance_spot_api_key")
        if not secret:
            raise RuntimeError("missing_binance_spot_api_secret")
        headers["X-MBX-APIKEY"] = api_key
        if "timestamp" not in p:
            p["timestamp"] = int(_now_ms())
        if "recvWindow" not in p:
            p["recvWindow"] = int(_binance_spot_skill_recv_window_ms())
        tuples = [(k, p[k]) for k in sorted(p.keys())]
        qs_sig = _aster_hmac_signed_query(tuples, secret)
        url = url + ("?" + qs_sig if qs_sig else "")
        query = None
    else:
        query = p
    to_sec = float(_binance_spot_skill_timeout_sec(timeout_sec if timeout_sec is not None else 10.0))
    if requests is not None:
        try:
            s = requests.Session()
            s.trust_env = False
            r = s.request(m, url, headers=headers, params=query, timeout=to_sec)
            if not bool(getattr(r, "ok", False)):
                txt = str(getattr(r, "text", "") or "")
                raise RuntimeError(f"binance_spot_http_error:{int(getattr(r, 'status_code', 0) or 0)}:{txt[:300]}")
            try:
                return r.json()
            except Exception:
                return str(getattr(r, "text", "") or "")
        except Exception:
            pass
    if query:
        qs = urllib_parse.urlencode([(k, "" if v is None else v) for k, v in sorted(query.items())], doseq=True)
        url = url + (("?" + qs) if qs else "")
    req = urllib_request.Request(url, headers=headers, method=m)
    with urllib_request.urlopen(req, timeout=to_sec) as resp:
        raw = resp.read().decode("utf-8")
        try:
            return json.loads(raw) if raw else {}
        except Exception:
            return raw


def _skill_binance_spot_market_data(inp: Dict[str, Any]) -> Dict[str, Any]:
    action = str(inp.get("action") or "exchangeInfo").strip().lower()
    symbol = str(inp.get("symbol") or "").strip().upper()
    try:
        limit = int(inp.get("limit") or 100)
    except Exception:
        limit = 100
    limit = int(max(1, min(1000, int(limit))))
    interval = str(inp.get("interval") or "1m").strip() or "1m"
    endpoint_map = {
        "exchangeinfo": ("/api/v3/exchangeInfo", {}),
        "ticker_price": ("/api/v3/ticker/price", {"symbol": symbol or None}),
        "ticker_24hr": ("/api/v3/ticker/24hr", {"symbol": symbol or None}),
        "book_ticker": ("/api/v3/ticker/bookTicker", {"symbol": symbol or None}),
        "depth": ("/api/v3/depth", {"symbol": symbol or None, "limit": int(max(5, min(5000, limit)))}),
        "klines": ("/api/v3/klines", {"symbol": symbol or None, "interval": interval, "limit": int(max(1, min(1000, limit)))}),
    }
    if action not in endpoint_map:
        return {"ok": False, "error": "unsupported_action", "supported": sorted(list(endpoint_map.keys()))}
    path, q = endpoint_map[action]
    if action != "exchangeinfo" and not symbol:
        return {"ok": False, "error": "missing_symbol"}
    out = _binance_spot_skill_http("GET", path, params={k: v for k, v in q.items() if v is not None}, signed=False, timeout_sec=float(inp.get("timeout_sec") or 10.0))
    return {"ok": True, "ts": int(_now_ms()), "action": action, "result": out}


def _skill_binance_spot_account(inp: Dict[str, Any]) -> Dict[str, Any]:
    action = str(inp.get("action") or "account").strip().lower()
    symbol = str(inp.get("symbol") or "").strip().upper()
    order_id = inp.get("orderId")
    endpoint_map = {
        "account": ("/api/v3/account", {}),
        "open_orders": ("/api/v3/openOrders", {"symbol": (symbol or None)}),
        "order": ("/api/v3/order", {"symbol": (symbol or None), "orderId": order_id}),
        "my_trades": ("/api/v3/myTrades", {"symbol": (symbol or None), "limit": int(max(1, min(1000, int(inp.get("limit") or 100))))}),
    }
    if action not in endpoint_map:
        return {"ok": False, "error": "unsupported_action", "supported": sorted(list(endpoint_map.keys()))}
    path, q = endpoint_map[action]
    if action in ("order", "my_trades") and not symbol:
        return {"ok": False, "error": "missing_symbol"}
    out = _binance_spot_skill_http("GET", path, params={k: v for k, v in q.items() if v is not None}, signed=True, timeout_sec=float(inp.get("timeout_sec") or 10.0))
    return {"ok": True, "ts": int(_now_ms()), "action": action, "result": out}


def _skill_binance_spot_trade(inp: Dict[str, Any]) -> Dict[str, Any]:
    action = str(inp.get("action") or "new_order").strip().lower()
    endpoint_map = {
        "new_order": ("POST", "/api/v3/order"),
        "test_order": ("POST", "/api/v3/order/test"),
        "cancel_order": ("DELETE", "/api/v3/order"),
        "new_oco": ("POST", "/api/v3/orderList/oco"),
        "cancel_oco": ("DELETE", "/api/v3/orderList"),
        "new_oto": ("POST", "/api/v3/orderList/oto"),
        "new_otoco": ("POST", "/api/v3/orderList/otoco"),
    }
    if action not in endpoint_map:
        return {"ok": False, "error": "unsupported_action", "supported": sorted(list(endpoint_map.keys()))}
    m, path = endpoint_map[action]
    params = inp.get("params") if isinstance(inp.get("params"), dict) else {}
    merged = dict(params)
    for k in (
        "symbol",
        "side",
        "type",
        "timeInForce",
        "quantity",
        "quoteOrderQty",
        "price",
        "stopPrice",
        "trailingDelta",
        "newClientOrderId",
        "listClientOrderId",
        "limitClientOrderId",
        "stopClientOrderId",
        "aboveType",
        "abovePrice",
        "aboveStopPrice",
        "belowType",
        "belowPrice",
        "belowStopPrice",
        "strategyId",
        "strategyType",
        "selfTradePreventionMode",
        "recvWindow",
        "timestamp",
        "orderId",
        "origClientOrderId",
    ):
        if inp.get(k) is not None and merged.get(k) is None:
            merged[k] = inp.get(k)
    sym = str(merged.get("symbol") or "").strip().upper()
    if not sym:
        return {"ok": False, "error": "missing_symbol"}
    merged["symbol"] = sym
    if action in ("new_order", "test_order"):
        side = str(merged.get("side") or "BUY").strip().upper()
        typ = str(merged.get("type") or "MARKET").strip().upper()
        merged["side"] = side
        merged["type"] = typ
    out = _binance_spot_skill_http(m, path, params={k: v for k, v in merged.items() if v is not None}, signed=True, timeout_sec=float(inp.get("timeout_sec") or 15.0))
    return {"ok": True, "ts": int(_now_ms()), "action": action, "result": out}


