                    secondary_doc = str(policy.get("secondary") or "").strip() or ("技术文档.md" if primary_doc != "技术文档.md" else "交易AI Agent 技术文档2.0.md")

                    doc_snippets: List[Dict[str, Any]] = []

                    def _pick_doc(doc_name: str, *, max_sections: int, max_chars_total: int) -> None:
                        p = allowed.get(doc_name)
                        if p and p.exists():
                            hits = _doc_retrieve_snippets(p, intent_text0, max_sections=max_sections, max_chars_total=max_chars_total)
                            if hits:
                                doc_snippets.extend(hits)

                    _pick_doc(primary_doc, max_sections=4, max_chars_total=5200)
                    if secondary_doc and secondary_doc != primary_doc:
                        _pick_doc(secondary_doc, max_sections=3, max_chars_total=2600)

                    if not any((str(x.get("doc_path") or "").strip() == primary_doc) for x in doc_snippets if isinstance(x, dict)):
                        p = allowed.get(primary_doc)
                        if p and p.exists() and primary_doc == "交易AI Agent 技术文档2.0.md":
                            s1 = _md_extract_section(p, section_key="4.7 本地大模型驱动模块（Local LLM Driver）", max_chars=4500)
