def agent_outbox_files():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    p = _agent_outbox_dir()
    items = []
    try:
        pats = list(p.glob("*.jsonl")) + list(p.glob("*.jsonl.gz"))
        for q in sorted(pats):
            try:
                st = q.stat()
                items.append({"name": q.name, "size": int(st.st_size), "mtime_ms": int(st.st_mtime * 1000)})
            except Exception:
                items.append({"name": q.name})
    except Exception:
        items = []
    return jsonify({"ok": True, "dir": str(p), "items": items, "count": int(len(items)), "ts": int(_now_ms())})


def _agent_outbox_compact_item(obj: Any) -> Any:
    if not isinstance(obj, dict):
        return obj

    def _clip_str(v: Any, n: int) -> Any:
        if v is None:
            return None
        try:
            s = str(v)
        except Exception:
            return v
        if len(s) <= n:
            return s
        return s[: max(0, n - 1)] + "…"

    def _summarize_value(v: Any) -> Any:
        if v is None:
            return None
        if isinstance(v, (bool, int, float)):
            return v
        if isinstance(v, str):
            return _clip_str(v, 2000)
        if isinstance(v, list):
            n = len(v)
            sample = v[:5]
            return {"_omitted": True, "type": "list", "len": int(n), "sample": sample}
        if isinstance(v, dict):
            keys = list(v.keys())
            return {"_omitted": True, "type": "dict", "len": int(len(keys)), "keys": [str(k) for k in keys[:40]]}
        return _clip_str(v, 2000)

    keep = ("id", "trace_id", "ts", "type", "channel", "status", "ok", "message", "tool", "step_id", "reason")
    out: Dict[str, Any] = {}
    for k in keep:
        if k in obj:
            out[k] = obj.get(k)

    if "driver" in obj and isinstance(obj.get("driver"), dict):
        out["driver"] = obj.get("driver")

    if "intent" in obj and isinstance(obj.get("intent"), dict):
        it = obj.get("intent") or {}
        out["intent"] = {"kind": it.get("kind"), "text": _clip_str(it.get("text"), 240), "query_text": _clip_str(it.get("query_text"), 240)}

    if "assistant_text" in obj:
        out["assistant_text"] = _clip_str(obj.get("assistant_text"), 9000)

    if "error" in obj:
        out["error"] = _clip_str(obj.get("error"), 1000)

    if "summary" in obj:
        out["summary"] = _summarize_value(obj.get("summary"))

    for k in ("params", "requested", "mode", "severity", "eval_mode", "family"):
        if k in obj:
            out[k] = _summarize_value(obj.get(k))

    if "payload" in obj and isinstance(obj.get("payload"), dict):
        payload = obj.get("payload") or {}
        p_out: Dict[str, Any] = {}
        for k in ("ok", "error", "ts"):
            if k in payload:
                p_out[k] = payload.get(k)
        for k in ("stdout", "stderr"):
            if k in payload:
                p_out[k] = _clip_str(payload.get(k), 2400)
        if "items" in payload and isinstance(payload.get("items"), list):
            p_out["items"] = {"_omitted": True, "type": "list", "len": int(len(payload.get("items") or []))}
        out["payload"] = p_out

    if "result" in obj:
        out["result"] = _summarize_value(obj.get("result"))

    return out


@app.route("/agent/outbox/read", methods=["GET"])
def agent_outbox_read():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    name = str(request.args.get("name") or "").strip()
    if not name or "/" in name or "\\" in name or ".." in name:
        return jsonify({"ok": False, "error": "bad_name"}), 400
    try:
        offset = int(request.args.get("offset") or 0)
    except Exception:
        offset = 0
    try:
        limit = int(request.args.get("limit") or 200)
    except Exception:
        limit = 200
    offset = max(0, offset)
    limit = max(1, min(2000, limit))
    compact = False
    try:
        compact = str(request.args.get("compact") or "").strip().lower() in ("1", "true", "yes", "y", "on")
    except Exception:
        compact = False
    tail_mode = False
    try:
        tail_mode = str(request.args.get("tail") or "").strip().lower() in ("1", "true", "yes", "y", "on")
    except Exception:
        tail_mode = False

    p = _agent_outbox_dir() / name
    if not p.exists():
        return jsonify({"ok": False, "error": "not_found"}), 404

    lines = []
    next_offset = offset
    reset = False
    try:
        if tail_mode:
            tail_bytes = 2_000_000
            try:
                tail_bytes = int(request.args.get("tail_bytes") or 2_000_000)
            except Exception:
                tail_bytes = 2_000_000
            tail_bytes = max(1024, min(20_000_000, int(tail_bytes)))
            raw_lines = _tail_lines_gzip(p, max_lines=int(limit)) if str(p.name).lower().endswith(".gz") else _tail_lines(p, max_lines=int(limit), max_bytes=int(tail_bytes))
            for i, s in enumerate(raw_lines):
                try:
                    obj = json.loads(s)
                except Exception:
                    obj = {"raw": s}
                if compact:
                    obj = _agent_outbox_compact_item(obj)
                lines.append({"offset": i, "item": obj})
            return jsonify({"ok": True, "name": name, "offset": 0, "next_offset": 0, "items": lines, "count": int(len(lines)), "reset": False, "tail": True, "ts": int(_now_ms())})

        last_i = -1
        if str(p.name).lower().endswith(".gz"):
            fctx = gzip.open(p, "rt", encoding="utf-8", errors="ignore")
        else:
            fctx = open(p, "r", encoding="utf-8")
        with fctx as f:
            for i, line in enumerate(f):
                last_i = i
                if i < offset:
                    continue
                if len(lines) >= limit:
                    break
                s = line.strip("\n")
                if not s.strip():
                    next_offset = i + 1
                    continue
                try:
                    obj = json.loads(s)
                except Exception:
                    obj = {"raw": s}
                if compact:
                    obj = _agent_outbox_compact_item(obj)
                lines.append({"offset": i, "item": obj})
                next_offset = i + 1
        if offset > 0 and last_i >= 0 and offset > (last_i + 1):
            reset = True
            lines = []
            next_offset = 0
            if str(p.name).lower().endswith(".gz"):
                fctx2 = gzip.open(p, "rt", encoding="utf-8", errors="ignore")
            else:
                fctx2 = open(p, "r", encoding="utf-8")
            with fctx2 as f2:
                for i, line in enumerate(f2):
                    if len(lines) >= limit:
                        break
                    s = line.strip("\n")
                    if not s.strip():
                        next_offset = i + 1
                        continue
                    try:
                        obj = json.loads(s)
                    except Exception:
                        obj = {"raw": s}
                    if compact:
                        obj = _agent_outbox_compact_item(obj)
                    lines.append({"offset": i, "item": obj})
                    next_offset = i + 1
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500

    return jsonify({"ok": True, "name": name, "offset": int(offset), "next_offset": int(next_offset), "items": lines, "count": int(len(lines)), "reset": bool(reset), "ts": int(_now_ms())})


