def _fundamental_project_root_dir() -> Path:
    here = Path(__file__).resolve()
    candidates = [
        here.parent.parent.parent,
        here.parent.parent,
        here.parent,
    ]
    for c in candidates:
        try:
            p = (c / "ops" / "nanoclaw" / "core_task1").resolve()
        except Exception:
            continue
        if p.exists():
            return c
    return here.parent


