def _fundamental_safe_name(name: str = "") -> str:
    n = str(name or "").strip()
    if (not n) or ("/" in n) or ("\\" in n) or (".." in n):
        return ""
    return n


def _fundamental_news_pick_file(name: str = "") -> Optional[Path]:
    p = _fundamental_news_outputs_dir()
    try:
        n = _fundamental_safe_name(name)
        if n:
            q = p / n
            if q.exists() and q.is_file():
                return q
            return None
        def _sorted_cands(pattern: str) -> List[Path]:
            try:
                return sorted([x for x in p.glob(pattern) if x.is_file()], key=lambda x: x.stat().st_mtime, reverse=True)
            except Exception:
                return []

        strict_patterns = ("brief_v3_*_optimized.md", "brief_v3_*.md", "brief_on_demand_*.md")
        for pat in strict_patterns:
            for q in _sorted_cands(pat):
                try:
                    with open(q, "r", encoding="utf-8", errors="replace") as f:
                        txt = f.read(400000)
                except Exception:
                    continue
                guard = _fundamental_brief_template_guard(
                    module_name="news",
                    content=txt,
                    required_title=BRIEF_V3_TITLE,
                    required_headings=BRIEF_V3_REQUIRED_HEADINGS,
                )
                if bool(guard.get("ok")):
                    return q

        relaxed_patterns = ("brief_v2_*.md", "brief_[0-9]*.md")
        relaxed: List[Path] = []
        for pat in relaxed_patterns:
            relaxed.extend(_sorted_cands(pat))
        if relaxed:
            relaxed = sorted(relaxed, key=lambda x: x.stat().st_mtime, reverse=True)
            return relaxed[0]
    except Exception:
        return None
    return None


def _fundamental_flows_pick_file(name: str = "") -> Optional[Path]:
    p = _fundamental_flows_outputs_dir()
    try:
        n = _fundamental_safe_name(name)
        if n:
            q = p / n
            if q.exists() and q.is_file():
                return q
            return None
        all_cands: List[Path] = []
        for pat in ("flow_brief_v*.md", "flow_brief_*.md"):
            try:
                all_cands.extend([x for x in p.glob(pat) if x.is_file()])
            except Exception:
                pass
        if all_cands:
            all_cands = sorted(all_cands, key=lambda x: x.stat().st_mtime, reverse=True)
            return all_cands[0]
    except Exception:
        return None
    return None


