def _fundamental_narrative_parse_hours(v: Any) -> Optional[int]:
    s = str(v or "").strip().lower()
    if not s:
        return None
    m = re.search(r"(\d+)\s*(h|小时)", s)
    if not m:
        m = re.search(r"(\d+)", s)
    if not m:
        return None
    try:
        h = int(m.group(1))
        if h <= 0:
            return None
        return h
    except Exception:
        return None


def _fundamental_narrative_registry_row(q: Path) -> Optional[Dict[str, Any]]:
    try:
        obj = json.loads(q.read_text(encoding="utf-8", errors="replace"))
    except Exception:
        return None
    if not isinstance(obj, dict):
        return None
    rec = _json_sanitize(obj)
    contract = rec.get("contract") if isinstance(rec.get("contract"), dict) else {}
    scores = contract.get("scores") if isinstance(contract.get("scores"), dict) else {}
    quality = contract.get("quality") if isinstance(contract.get("quality"), dict) else (
        rec.get("quality") if isinstance(rec.get("quality"), dict) else {}
    )
    top_narratives = contract.get("top_narratives") if isinstance(contract.get("top_narratives"), list) else []
    evidence_refs = contract.get("evidence_refs") if isinstance(contract.get("evidence_refs"), list) else []
    generated_at = (
        str(rec.get("generated_at") or "").strip()
        or str(rec.get("timestamp") or "").strip()
        or str(contract.get("generated_at") or "").strip()
    )
    analysis_window = str(rec.get("analysis_window") or "").strip()
    time_window = str(contract.get("time_window") or analysis_window).strip()
    h1 = _fundamental_narrative_parse_hours(time_window)
    h2 = _fundamental_narrative_parse_hours(analysis_window)
    source_urls: List[str] = []
    for it in top_narratives:
        if not isinstance(it, dict):
            continue
        srcs = it.get("sources")
        if not isinstance(srcs, list):
            continue
        for s in srcs:
            if not isinstance(s, dict):
                continue
            u = str(s.get("url") or "").strip()
            if u:
                source_urls.append(u)
    row = {
        "name": q.name,
        "path": str(q),
        "mtime_ms": int(q.stat().st_mtime * 1000),
        "generated_at": generated_at,
        "analysis_window": analysis_window,
        "time_window": time_window,
        "time_window_hours": (h1 if h1 is not None else h2),
        "top_narrative": str(rec.get("top_narrative") or "").strip(),
        "narrative_count": int(rec.get("narrative_count") or len(rec.get("narratives") or []) or 0),
        "overall_sentiment": rec.get("overall_sentiment"),
        "overall_heat": rec.get("overall_heat"),
        "community_effective_score": scores.get("community_effective_score"),
        "community_impulse": scores.get("community_impulse"),
        "stress_level": ((scores.get("narrative_stress") or {}).get("stress_level") if isinstance(scores.get("narrative_stress"), dict) else None),
        "recommended_action": ((scores.get("narrative_stress") or {}).get("recommended_action") if isinstance(scores.get("narrative_stress"), dict) else None),
        "quality_overall": quality.get("overall_quality"),
        "quality_coverage": quality.get("coverage"),
        "quality_flags": (quality.get("quality_flags") if isinstance(quality.get("quality_flags"), list) else []),
        "missing_disclosure": (quality.get("missing_disclosure") if isinstance(quality.get("missing_disclosure"), list) else []),
        "backfilled_disclosure": (quality.get("backfilled_disclosure") if isinstance(quality.get("backfilled_disclosure"), list) else []),
        "evidence_count": int(len(evidence_refs)),
        "source_count": int(len(set(source_urls))),
        "top_narratives": top_narratives[:10],
        "evidence_refs": evidence_refs[:50],
    }
    return _json_sanitize(row)


def _fundamental_narrative_history_rows(limit: int = 120, window_hours: Optional[int] = None) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    cands = _fundamental_narrative_pick_registry_files(limit=max(200, int(limit) * 3))
    for q in cands:
        row = _fundamental_narrative_registry_row(q)
        if not isinstance(row, dict):
            continue
        if window_hours is not None:
            try:
                h = int(row.get("time_window_hours") or 0)
            except Exception:
                h = 0
            if h != int(window_hours):
                continue
        rows.append(row)
        if len(rows) >= int(limit):
            break
    return rows


def _fundamental_news_pick_event_ledger_file(name: str = "") -> Optional[Path]:
    p = _fundamental_news_raw_dir()
    try:
        n = _fundamental_safe_name(name)
        if n:
            q = p / n
            if q.exists() and q.is_file() and q.suffix.lower() == ".jsonl":
                return q
            return None
        cands = [x for x in p.glob("event_ledger_*.jsonl") if ("overlay" not in x.name.lower() and "backtest" not in x.name.lower())]
        cands = sorted(cands, key=lambda x: x.stat().st_mtime, reverse=True)
        if cands:
            return cands[0]
        cands2 = sorted(p.glob("event_ledger_*.jsonl"), key=lambda x: x.stat().st_mtime, reverse=True)
        if cands2:
            return cands2[0]
    except Exception:
        return None
    return None


