def _fundamental_news_extract_file_stamp(name: str) -> str:
    s = str(name or "").strip()
    if not s:
        return ""
    m = re.search(r"_(\d{8}_\d{4,6})\.", s)
    if m:
        return str(m.group(1) or "").strip()
    m2 = re.search(r"_(\d{8})\.", s)
    if m2:
        return str(m2.group(1) or "").strip()
    return ""


def _fundamental_news_stamp_to_ms(stamp: str) -> Optional[int]:
    s = str(stamp or "").strip()
    if not s:
        return None
    fmts = ("%Y%m%d_%H%M%S", "%Y%m%d_%H%M", "%Y%m%d")
    for fmt in fmts:
        try:
            dt = datetime.strptime(s, fmt).replace(tzinfo=timezone.utc)
            return int(dt.timestamp() * 1000)
        except Exception:
            continue
    return None


def _fundamental_news_load_risk_rows(path: Path) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    try:
        obj = json.loads(path.read_text(encoding="utf-8", errors="replace"))
    except Exception:
        return rows
    if isinstance(obj, list):
        for it in obj:
            if isinstance(it, dict):
                rows.append(dict(it))
    elif isinstance(obj, dict):
        xs = obj.get("items")
        if isinstance(xs, list):
            for it in xs:
                if isinstance(it, dict):
                    rows.append(dict(it))
    return rows


def _fundamental_news_action_counts(risk_rows: List[Dict[str, Any]]) -> Dict[str, int]:
    out: Dict[str, int] = {}
    for it in (risk_rows or []):
        if not isinstance(it, dict):
            continue
        a = str(it.get("risk_action_proposal") or "").strip().lower()
        if not a:
            continue
        out[a] = int(out.get(a) or 0) + 1
    return out


def _fundamental_news_evaluation_rows(limit: int = 120) -> List[Dict[str, Any]]:
    cov_files = _fundamental_news_pick_coverage_report_files(limit=max(240, int(limit) * 3))
    risk_files = _fundamental_news_pick_risk_events_files(limit=max(240, int(limit) * 3))
    risk_by_stamp: Dict[str, Path] = {}
    for rq in risk_files:
        st = _fundamental_news_extract_file_stamp(rq.name)
        if st and (st not in risk_by_stamp):
            risk_by_stamp[st] = rq
    rows: List[Dict[str, Any]] = []
    used_stamps: set[str] = set()
    for cq in cov_files:
        cov_obj: Dict[str, Any] = {}
        try:
            xo = json.loads(cq.read_text(encoding="utf-8", errors="replace"))
            if isinstance(xo, dict):
                cov_obj = xo
        except Exception:
            cov_obj = {}
        st = _fundamental_news_extract_file_stamp(cq.name)
        rq = risk_by_stamp.get(st) if st else None
        risk_rows = _fundamental_news_load_risk_rows(rq) if isinstance(rq, Path) else []
        compact = _fundamental_news_compact_fields(
            brief_generated_at=str(cov_obj.get("generated_at") or ""),
            coverage_report=cov_obj,
            risk_events=risk_rows,
        )
        action_counts = _fundamental_news_action_counts(risk_rows)
        total = int(sum(action_counts.values()))
        dominant_action = ""
        if action_counts:
            dominant_action = sorted(action_counts.items(), key=lambda x: (-int(x[1]), str(x[0])))[0][0]
        ts_ms = _fundamental_news_stamp_to_ms(st)
        if not isinstance(ts_ms, int):
            mts: List[int] = [int(cq.stat().st_mtime * 1000)]
            if isinstance(rq, Path):
                mts.append(int(rq.stat().st_mtime * 1000))
            ts_ms = max(mts)
        try:
            asof = datetime.fromtimestamp(float(ts_ms) / 1000.0, tz=timezone.utc).isoformat().replace("+00:00", "Z")
        except Exception:
            asof = ""
        rows.append({
            "stamp": st,
            "ts_ms": int(ts_ms),
            "asof": asof,
            "coverage_report_name": cq.name,
            "risk_action_events_name": (rq.name if isinstance(rq, Path) else ""),
            "generated_at": str(compact.get("generated_at") or ""),
            "quality": str(compact.get("quality") or "unknown"),
            "coverage": compact.get("coverage"),
            "missing_data": list(compact.get("missing_data") or []),
            "turning_point_state": str(compact.get("turning_point_state") or "unknown"),
            "dominant_action": (dominant_action or "hold"),
            "action_total": int(total),
            "action_counts": _json_sanitize(action_counts),
        })
        if st:
            used_stamps.add(st)
        if len(rows) >= int(limit):
            break
    if len(rows) < int(limit):
        for rq in risk_files:
            st = _fundamental_news_extract_file_stamp(rq.name)
            if st and st in used_stamps:
                continue
            risk_rows = _fundamental_news_load_risk_rows(rq)
            compact = _fundamental_news_compact_fields(
                brief_generated_at="",
                coverage_report={},
                risk_events=risk_rows,
            )
            action_counts = _fundamental_news_action_counts(risk_rows)
            total = int(sum(action_counts.values()))
            dominant_action = ""
            if action_counts:
                dominant_action = sorted(action_counts.items(), key=lambda x: (-int(x[1]), str(x[0])))[0][0]
            ts_ms = _fundamental_news_stamp_to_ms(st)
            if not isinstance(ts_ms, int):
                ts_ms = int(rq.stat().st_mtime * 1000)
            try:
                asof = datetime.fromtimestamp(float(ts_ms) / 1000.0, tz=timezone.utc).isoformat().replace("+00:00", "Z")
            except Exception:
                asof = ""
            rows.append({
                "stamp": st,
                "ts_ms": int(ts_ms),
                "asof": asof,
                "coverage_report_name": "",
                "risk_action_events_name": rq.name,
                "generated_at": str(compact.get("generated_at") or ""),
                "quality": str(compact.get("quality") or "unknown"),
                "coverage": compact.get("coverage"),
                "missing_data": list(compact.get("missing_data") or []),
                "turning_point_state": str(compact.get("turning_point_state") or "unknown"),
                "dominant_action": (dominant_action or "hold"),
                "action_total": int(total),
                "action_counts": _json_sanitize(action_counts),
            })
            if st:
                used_stamps.add(st)
            if len(rows) >= int(limit):
                break
    rows.sort(key=lambda x: int(x.get("ts_ms") or 0), reverse=True)
    return rows[: int(limit)]


def _fundamental_news_pick_anchor_latest_delta(rows: List[Dict[str, Any]], anchor_hour: int = 8) -> Dict[str, Any]:
    xs = [dict(x) for x in (rows or []) if isinstance(x, dict)]
    if not xs:
        return {"anchor_run": None, "latest_run": None, "delta": {}}
    latest = xs[0]
    try:
        target_day = datetime.now().strftime("%Y%m%d")
    except Exception:
        target_day = ""
    target_min = int(max(0, min(23, int(anchor_hour))) * 60)
    day_rows: List[Tuple[Dict[str, Any], int]] = []
    for r in xs:
        ts_ms = int(r.get("ts_ms") or 0)
        if ts_ms <= 0:
            continue
        try:
            dt_local = datetime.fromtimestamp(float(ts_ms) / 1000.0)
            day_key = dt_local.strftime("%Y%m%d")
            if target_day and day_key != target_day:
                continue
            cur_min = int(dt_local.hour * 60 + dt_local.minute)
            day_rows.append((r, cur_min))
        except Exception:
            continue
    anchor: Optional[Dict[str, Any]] = None
    if day_rows:
        day_rows.sort(key=lambda it: (0 if int(it[1]) >= target_min else 1, abs(int(it[1]) - target_min), -int(it[0].get("ts_ms") or 0)))
        anchor = day_rows[0][0]
    else:
        anchor = xs[-1]
    def _q_rank(q: str) -> int:
        m = {"ok": 0, "stale": 1, "backfilled": 2, "suspect": 3, "missing": 4, "unknown": 5}
        return int(m.get(str(q or "").strip().lower(), 5))
    a_cov = _fundamental_flows_num((anchor or {}).get("coverage"))
    l_cov = _fundamental_flows_num(latest.get("coverage"))
    cov_delta = (float(l_cov - a_cov) if isinstance(a_cov, float) and isinstance(l_cov, float) else None)
    a_q = str((anchor or {}).get("quality") or "unknown").strip().lower()
    l_q = str(latest.get("quality") or "unknown").strip().lower()
    a_action = str((anchor or {}).get("dominant_action") or "hold").strip().lower() or "hold"
    l_action = str(latest.get("dominant_action") or "hold").strip().lower() or "hold"
    a_total = int((anchor or {}).get("action_total") or 0)
    l_total = int(latest.get("action_total") or 0)
    dt_minutes: Optional[int] = None
    try:
        dt_minutes = int(max(0, (int(latest.get("ts_ms") or 0) - int((anchor or {}).get("ts_ms") or 0)) // 60000))
    except Exception:
        dt_minutes = None
    return {
        "anchor_run": anchor,
        "latest_run": latest,
        "delta": {
            "coverage_delta": cov_delta,
            "quality_delta_rank": int(_q_rank(l_q) - _q_rank(a_q)),
            "quality_from": a_q,
            "quality_to": l_q,
            "dominant_action_from": a_action,
            "dominant_action_to": l_action,
            "action_total_delta": int(l_total - a_total),
            "minutes_since_anchor": dt_minutes,
        },
    }


def _fundamental_parse_limit(v: Any, default: int, min_v: int, max_v: int) -> int:
    try:
        n = int(v)
    except Exception:
        n = int(default)
    return max(int(min_v), min(int(max_v), int(n)))


def _fundamental_parse_max_chars(v: Any, default: int = 200000, min_v: int = 4000, max_v: int = 1200000) -> int:
    try:
        n = int(v)
    except Exception:
        n = int(default)
    return max(int(min_v), min(int(max_v), int(n)))


def _fundamental_news_extract_generated_at(md: str) -> str:
    try:
        m = re.search(r"^\*\*生成时间\*\*:\s*(.+)$", str(md or ""), flags=re.MULTILINE)
        if m:
            return str(m.group(1) or "").strip()
    except Exception:
        pass
    return ""


