def _fundamental_monitoring_clocks(module_name: str) -> Dict[str, Any]:
    m = str(module_name or "").strip().lower()
    if m == "news":
        update_sec = int(_fundamental_news_period_hours() * 3600)
        max_delay_sec = int(update_sec * 2)
        backfill_freeze_sec = int(6 * 3600)
    elif m == "narrative":
        update_sec = int(_fundamental_narrative_period_hours() * 3600)
        max_delay_sec = int(update_sec * 2)
        backfill_freeze_sec = int(4 * 3600)
    elif m == "trading":
        update_sec = int(_fundamental_trading_period_sec())
        max_delay_sec = int(max(update_sec * 2, 20 * 60))
        backfill_freeze_sec = int(4 * 3600)
    elif m == "flows":
        update_sec = int(4 * 3600)
        max_delay_sec = int(8 * 3600)
        backfill_freeze_sec = int(8 * 3600)
    else:
        update_sec = int(4 * 3600)
        max_delay_sec = int(8 * 3600)
        backfill_freeze_sec = int(4 * 3600)
    return {
        "update_frequency_sec": int(update_sec),
        "max_tolerated_delay_sec": int(max_delay_sec),
        "backfill_freeze_window_sec": int(backfill_freeze_sec),
    }


def _fundamental_brief_template_guard(*, module_name: str, content: str, required_title: str, required_headings: List[str]) -> Dict[str, Any]:
    txt = str(content or "")
    first_non_empty = ""
    for line in txt.splitlines():
        s = str(line or "").strip()
        if s:
            first_non_empty = s
            break
    title_ok = (first_non_empty == str(required_title or "").strip()) if required_title else bool(first_non_empty)
    missing = []
    for h in (required_headings or []):
        hs = str(h or "").strip()
        if not hs:
            continue
        if hs not in txt:
            missing.append(hs)
    ok = bool(title_ok and not missing)
    reasons: List[str] = []
    if not title_ok:
        reasons.append("title_mismatch")
    if missing:
        reasons.append("missing_required_headings")
    return {
        "module": str(module_name or "").strip(),
        "ok": bool(ok),
        "title_ok": bool(title_ok),
        "missing_headings": missing,
        "required_title": str(required_title or "").strip(),
        "required_headings": [str(x) for x in (required_headings or []) if str(x or "").strip()],
        "reasons": reasons,
    }


def _fundamental_trading_template_guard(rep: Dict[str, Any]) -> Dict[str, Any]:
    obj = rep if isinstance(rep, dict) else {}
    missing = [k for k in FUNDAMENTAL_TRADING_REQUIRED_FIELDS if k not in obj]
    bias = obj.get("bias") if isinstance(obj.get("bias"), dict) else {}
    flt = obj.get("filter") if isinstance(obj.get("filter"), dict) else {}
    risk = obj.get("risk_off") if isinstance(obj.get("risk_off"), dict) else {}
    nested_missing: List[str] = []
    if "bias_dir" not in bias:
        nested_missing.append("bias.bias_dir")
    if "execution_filter" not in flt:
        nested_missing.append("filter.execution_filter")
    if "risk_action_proposal" not in risk:
        nested_missing.append("risk_off.risk_action_proposal")
    ok = (not missing) and (not nested_missing)
    reasons: List[str] = []
    if missing:
        reasons.append("missing_required_fields")
    if nested_missing:
        reasons.append("missing_required_nested_fields")
    return {
        "module": "trading",
        "ok": bool(ok),
        "missing_fields": missing,
        "missing_nested_fields": nested_missing,
        "required_fields": list(FUNDAMENTAL_TRADING_REQUIRED_FIELDS),
        "reasons": reasons,
    }


def _fundamental_parse_iso_ts_ms(v: Any) -> Optional[int]:
    s = str(v or "").strip()
    if not s:
        return None
    try:
        dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
        return int(dt.timestamp() * 1000)
    except Exception:
        return None


def _fundamental_quality_overall(*, coverage: Any, counts: Any, critical_missing_sources: Any) -> str:
    c = _fundamental_flows_num(coverage)
    cnt = counts if isinstance(counts, dict) else {}
    miss_n = int(cnt.get("missing") or 0)
    stale_n = int(cnt.get("stale") or 0)
    backfilled_n = int(cnt.get("backfilled") or 0)
    suspect_n = int(cnt.get("suspect") or 0)
    critical = [str(x) for x in (critical_missing_sources or []) if str(x or "").strip()]
    if suspect_n > 0:
        return "suspect"
    if miss_n > 0:
        return "missing"
    if backfilled_n > 0:
        return "backfilled"
    if stale_n > 0:
        return "stale"
    if isinstance(c, float):
        if c < 0.5:
            return "missing"
        if c < 0.8 or critical:
            return "stale"
    if critical:
        return "stale"
    return "ok"


def _fundamental_turning_point_state(
    *,
    level: Any,
    slope: Any,
    stress: str,
    coverage: Any,
    missing_data: List[str],
    confirm_bars: int = 2,
    level_hi: float = 0.20,
    level_lo: float = -0.20,
) -> Dict[str, Any]:
    lv = _fundamental_flows_num(level)
    sl = _fundamental_flows_num(slope)
    cov = _fundamental_flows_num(coverage)
    st = str(stress or "unknown").strip().lower() or "unknown"
    reasons: List[str] = []
    if isinstance(cov, float):
        reasons.append(f"coverage={cov:.4f}")
    if isinstance(lv, float):
        reasons.append(f"level={lv:.4f}")
    if isinstance(sl, float):
        reasons.append(f"slope={sl:.4f}")
    reasons.append(f"stress={st}")
    for x in (missing_data or []):
        sx = str(x or "").strip()
        if sx:
            reasons.append(f"missing={sx}")
    if (not isinstance(cov, float)) or cov < 0.5:
        return {"turning_point_state": "unknown", "trigger_reasons": reasons + ["coverage_below_threshold"], "confirm_bars": int(confirm_bars)}
    if missing_data:
        return {"turning_point_state": "unknown", "trigger_reasons": reasons + ["critical_missing_data"], "confirm_bars": int(confirm_bars)}
    if not isinstance(lv, float):
        return {"turning_point_state": "unknown", "trigger_reasons": reasons + ["level_missing"], "confirm_bars": int(confirm_bars)}
    if not isinstance(sl, float):
        return {"turning_point_state": "unknown", "trigger_reasons": reasons + ["slope_missing"], "confirm_bars": int(confirm_bars)}
    if lv >= float(level_hi):
        if sl < 0 and st == "high":
            state = "distribution"
        elif sl < 0 or st in ("med", "high"):
            state = "overheat"
        else:
            state = "expansion"
    elif lv <= float(level_lo):
        if sl > 0 and st in ("low", "med"):
            state = "repair"
        else:
            state = "contraction"
    else:
        if sl > 0 and st == "low":
            state = "repair"
        elif sl < 0 and st in ("med", "high"):
            state = "distribution"
        elif st == "high":
            state = "overheat"
        else:
            state = "contraction"
    return {"turning_point_state": state, "trigger_reasons": reasons, "confirm_bars": int(confirm_bars)}


def _fundamental_news_allowed_hours(v: Any, default_h: int = 24) -> int:
    allowed = {4, 8, 12, 24}
    try:
        h = int(v)
    except Exception:
        h = int(default_h)
    if h not in allowed:
        h = int(default_h if default_h in allowed else 24)
    return int(h)


