def _fundamental_iso_to_ms(v: Any) -> Optional[int]:
    s = str(v or "").strip()
    if not s:
        return None
    try:
        dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
    except Exception:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    try:
        return int(dt.timestamp() * 1000)
    except Exception:
        return None


def _fundamental_news_cmd(hours: int) -> Tuple[List[str], Path]:
    root = Path(__file__).resolve().parent / "ops" / "nanoclaw" / "core_task1"
    ondemand = root / "scripts" / "run_news_digest_on_demand.py"
    if ondemand.exists():
        return (["python3", str(ondemand), "--hours", str(int(hours)), "--report-mode", "full", "--json", "--quiet"], root)
    sh = root / "smart_run.sh"
    if sh.exists():
        return (["bash", str(sh), "hours", str(int(hours)), "-j"], root)
    py = root / "scripts" / "news_digest_v2.py"
    if py.exists():
        return (["python3", str(py), "--hours", str(int(hours)), "--json", "--use-ollama"], root)
    return (["bash", "-lc", "true"], root)


def _fundamental_news_run_shell_cmd(cmd: List[str], cwd: Optional[Path], timeout_sec: float) -> Dict[str, Any]:
    try:
        env = dict(os.environ)
    except Exception:
        env = {}
    try:
        old_path = str(env.get("PATH") or "")
    except Exception:
        old_path = ""
    parts: List[str] = []
    for p in ("/opt/anaconda3/bin", "/usr/local/bin"):
        if os.path.isdir(p):
            parts.append(p)
    if old_path:
        parts.extend([x for x in str(old_path).split(":") if x])
    seen = set()
    merged_parts: List[str] = []
    for p in parts:
        if p in seen:
            continue
        seen.add(p)
        merged_parts.append(p)
    if merged_parts:
        env["PATH"] = ":".join(merged_parts)
    try:
        r = subprocess.run(
            cmd,
            cwd=(str(cwd) if cwd is not None else None),
            capture_output=True,
            text=True,
            timeout=float(timeout_sec),
            env=env,
        )
        return {
            "ok": r.returncode == 0,
            "code": int(r.returncode),
            "stdout": str(r.stdout or "").strip()[:2000],
            "stderr": str(r.stderr or "").strip()[:2000],
        }
    except Exception as e:
        return {
            "ok": False,
            "code": -1,
            "stdout": "",
            "stderr": str(e)[:2000],
        }


def _fundamental_news_latest_meta() -> Dict[str, Any]:
    now_ms = int(_now_ms())
    cached = _FUNDAMENTAL_NEWS_LATEST_META_CACHE.get("value")
    cached_ts = int(_FUNDAMENTAL_NEWS_LATEST_META_CACHE.get("ts_ms") or 0)
    if isinstance(cached, dict) and (now_ms - cached_ts) <= 60000:
        return dict(cached)
    b = _fundamental_news_pick_file("")
    e = _fundamental_news_pick_event_ledger_file("")
    r = _fundamental_news_pick_risk_events_file("")
    v = _fundamental_news_pick_anchor_delta_view_file("")
    c = _fundamental_news_pick_coverage_report_file("")
    out: Dict[str, Any] = {}
    if isinstance(b, Path):
        out["brief"] = {"name": b.name, "path": str(b), "mtime_ms": int(b.stat().st_mtime * 1000)}
    if isinstance(e, Path):
        out["event_ledger"] = {"name": e.name, "path": str(e), "mtime_ms": int(e.stat().st_mtime * 1000)}
    if isinstance(r, Path):
        out["risk_action_events"] = {"name": r.name, "path": str(r), "mtime_ms": int(r.stat().st_mtime * 1000)}
    if isinstance(v, Path):
        out["anchor_delta_view"] = {"name": v.name, "path": str(v), "mtime_ms": int(v.stat().st_mtime * 1000)}
    if isinstance(c, Path):
        out["coverage_report"] = {"name": c.name, "path": str(c), "mtime_ms": int(c.stat().st_mtime * 1000)}
    _FUNDAMENTAL_NEWS_LATEST_META_CACHE["ts_ms"] = int(now_ms)
    _FUNDAMENTAL_NEWS_LATEST_META_CACHE["value"] = dict(out)
    return out


