def _fundamental_narrative_digest_execute(hours: int, *, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    ts0 = int(_now_ms())
    got = _FUNDAMENTAL_NARRATIVE_LOCK.acquire(blocking=False)
    if not got:
        st = _fundamental_narrative_state_get()
        return {"ok": False, "error": "already_running", "ts": int(_now_ms()), "state": _json_sanitize(st)}
    _fundamental_narrative_state_set(running=True, running_since_ms=int(ts0), last_trigger_source=str(source), last_trigger_event=(trigger_event or "manual"), last_hours=int(hours), last_error=None)
    try:
        cmd, cwd = _fundamental_narrative_cmd(hours)
        run_out = _fundamental_news_run_shell_cmd(cmd=cmd, cwd=cwd, timeout_sec=1800.0)
        ok = bool(run_out.get("ok"))
        code = int(run_out.get("code") or 0)
        ts1 = int(_now_ms())
        duration_ms = int(max(0, ts1 - ts0))
        latest = _fundamental_narrative_latest_meta()
        _fundamental_narrative_state_set(
            running=False,
            running_since_ms=None,
            last_run_ms=int(ts1),
            last_duration_ms=int(duration_ms),
            last_ok=bool(ok),
            last_error=(None if ok else str(run_out.get("stderr") or run_out.get("stdout") or "run_failed")[:2000]),
            last_exit_code=int(code),
            last_stdout=str(run_out.get("stdout") or "")[:2000],
            last_stderr=str(run_out.get("stderr") or "")[:2000],
            last_source=str(source),
            last_trigger_event=(trigger_event or "manual"),
            last_hours=int(hours),
            latest=latest,
        )
        return {
            "ok": bool(ok),
            "code": int(code),
            "duration_ms": int(duration_ms),
            "hours": int(hours),
            "source": str(source),
            "trigger_event": (trigger_event or "manual"),
            "latest": latest,
            "stdout": str(run_out.get("stdout") or "")[:1000],
            "stderr": str(run_out.get("stderr") or "")[:1000],
            "ts": int(ts1),
        }
    finally:
        try:
            _FUNDAMENTAL_NARRATIVE_LOCK.release()
        except Exception:
            pass


def _fundamental_narrative_digest_run_async(*, hours: int, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    h = _fundamental_news_allowed_hours(hours, default_h=_fundamental_narrative_window_hours())
    st = _fundamental_narrative_state_get()
    if bool(st.get("running")):
        return {"ok": False, "error": "already_running", "state": _json_sanitize(st), "ts": int(_now_ms())}

    def _bg() -> None:
        with app.app_context():
            try:
                _fundamental_narrative_digest_execute(int(h), source=str(source), trigger_event=trigger_event)
            except Exception as e:
                _fundamental_narrative_state_set(running=False, running_since_ms=None, last_ok=False, last_error=str(e), last_run_ms=int(_now_ms()))

    try:
        _fundamental_narrative_state_set(running=True, running_since_ms=int(_now_ms()), last_trigger_source=str(source), last_trigger_event=(trigger_event or "manual"), last_hours=int(h))
        threading.Thread(target=_bg, daemon=True).start()
    except Exception as e:
        _fundamental_narrative_state_set(running=False, running_since_ms=None, last_ok=False, last_error=str(e))
        return {"ok": False, "error": str(e), "ts": int(_now_ms())}
    return {"ok": True, "queued": True, "hours": int(h), "source": str(source), "trigger_event": (trigger_event or "manual"), "state": _json_sanitize(_fundamental_narrative_state_get()), "ts": int(_now_ms())}


def _fundamental_news_digest_execute(hours: int, *, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    ts0 = int(_now_ms())
    got = _FUNDAMENTAL_NEWS_LOCK.acquire(blocking=False)
    if not got:
        st = _fundamental_news_state_get()
        return {"ok": False, "error": "already_running", "ts": int(_now_ms()), "state": _json_sanitize(st)}
    _fundamental_news_state_set(running=True, running_since_ms=int(ts0), last_trigger_source=str(source), last_trigger_event=(trigger_event or "manual"), last_hours=int(hours), last_error=None)
    try:
        def _brief_read_latest(max_chars: int = 260000) -> Tuple[str, str, Optional[Path]]:
            bq = _fundamental_news_pick_file(name="")
            if not isinstance(bq, Path) or (not bq.exists()) or (not bq.is_file()):
                return "", "", None
            try:
                md = bq.read_text(encoding="utf-8", errors="replace")[:max_chars]
            except Exception:
                md = ""
            gen = str(_fundamental_news_extract_generated_at(md) or "").strip()
            return gen, md, bq

        def _brief_top_points(md: str) -> Dict[str, Dict[str, str]]:
            out: Dict[str, Dict[str, str]] = {}
            if not md:
                return out
            m = re.search(r"^##\s+.*今日要点.*$", md, flags=re.MULTILINE)
            if not m:
                return out
            rest = md[m.end():]
            end_m = re.search(r"^##\s+", rest, flags=re.MULTILINE)
            block = rest[: end_m.start()] if end_m else rest
            for line in block.splitlines():
                s = str(line or "").strip()
                if not s:
                    continue
                m2 = re.match(r"^\d+\.\s+\*\*\[(.+?)\]\*\*\s*-\s*(.+)$", s)
                if not m2:
                    continue
                title = str(m2.group(1) or "").strip()
                if (not title) or title.lower() == "no data":
                    continue
                tail = str(m2.group(2) or "").strip()
                url_m = re.search(r"来源=([^）\)\s]+)", tail)
                url = str(url_m.group(1) or "").strip() if url_m else ""
                cred_m = re.search(r"可信度=([A-Za-z_]+)", tail)
                cred = str(cred_m.group(1) or "").strip().lower() if cred_m else ""
                out[title] = {"source_url": url, "credibility": cred}
            return out

        def _brief_event_table(md: str, gen: str, limit: int = 60) -> List[Dict[str, Any]]:
            if not md:
                return []
            m = re.search(r"^###\s+今日事件账本\s*$", md, flags=re.MULTILINE)
            if not m:
                return []
            rest = md[m.end():]
            end_m = re.search(r"^###\s+|^##\s+", rest, flags=re.MULTILINE)
            block = rest[: end_m.start()] if end_m else rest
            lines = [x.strip() for x in block.splitlines() if str(x or "").strip()]
            table_lines = [x for x in lines if x.startswith("|") and x.endswith("|")]
            if len(table_lines) < 3:
                return []
            top_map = _brief_top_points(md)
            out: List[Dict[str, Any]] = []
            for i, ln in enumerate(table_lines[2:]):
                cols = [c.strip() for c in ln.strip("|").split("|")]
                if len(cols) < 6:
                    continue
                title = str(cols[0] or "").strip()
                if (not title) or title.lower() == "no data":
                    continue
                type_weight = str(cols[1] or "").strip()
                ev_type = type_weight.split("(", 1)[0].strip() if type_weight else ""
                contrib_raw = str(cols[5] or "").strip()
                try:
                    contrib = float(contrib_raw)
                except Exception:
                    contrib = 0.0
                act = "hold"
                if contrib <= -0.15:
                    act = "reduce"
                elif contrib >= 0.15:
                    act = "add"
                link = top_map.get(title) or {}
                out.append({
                    "event_id": f"brief_{int(i)}",
                    "timestamp": (gen or datetime.utcnow().isoformat()),
                    "published_at": (gen or datetime.utcnow().isoformat()),
                    "event_type": (ev_type or "brief_event"),
                    "expectation_bucket": "unknown",
                    "risk_action_proposal": act,
                    "risk_flags": [],
                    "title": title,
                    "source_url": str(link.get("source_url") or "").strip() or None,
                    "credibility": (str(link.get("credibility") or "").strip() or "medium"),
                    "evidence_grade": (str(link.get("credibility") or "").strip() or "medium"),
                    "signal_contribution": contrib,
                    "source": "brief_synth",
                })
                if len(out) >= int(limit):
                    break
            return out

        def _brief_position_event(md: str, gen: str, ts_ms: int) -> Dict[str, Any]:
            action = ""
            pos = ""
            m1 = re.search(r"^-\s*建议动作：\*\*(.+?)\*\*\s*$", md, flags=re.MULTILINE)
            if m1:
                action = str(m1.group(1) or "").strip()
            m2 = re.search(r"^-\s*建议仓位：\*\*(.+?)\*\*\s*$", md, flags=re.MULTILINE)
            if m2:
                pos = str(m2.group(1) or "").strip()
            act_norm = (action or "HOLD").strip().lower()
            return {
                "ts_ms": int(ts_ms),
                "published_at": (gen or datetime.utcnow().isoformat()),
                "ts": (gen or datetime.utcnow().isoformat()),
                "event_type": "position",
                "title": "brief_position_advice",
                "risk_action_proposal": act_norm,
                "risk_action": act_norm,
                "reason": (f"position={pos}" if pos else "from_brief"),
                "source": "brief_synth",
                "evidence_grade": "brief",
            }

        def _fundamental_news_refresh_raw_from_brief(now_ms: int) -> Dict[str, Any]:
            gen, md, bq = _brief_read_latest()
            if not md or (not isinstance(bq, Path)):
                return {"ok": False, "error": "brief_not_found"}
            raw_dir = _fundamental_news_raw_dir()
            try:
                raw_dir.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            stamp = datetime.utcfromtimestamp(float(now_ms) / 1000.0).strftime("%Y%m%d_%H%M")
            ledger_items = _brief_event_table(md, gen, limit=200)
            pos_item = _brief_position_event(md, gen, now_ms)
            wrote = {"event_ledger": False, "risk_action_events": False}
            ledger_path = raw_dir / f"event_ledger_{stamp}.jsonl"
            if ledger_items:
                try:
                    with open(ledger_path, "w", encoding="utf-8") as f:
                        for it in ledger_items:
                            f.write(json.dumps(it, ensure_ascii=False) + "\n")
                    wrote["event_ledger"] = True
                except Exception:
                    wrote["event_ledger"] = False
            risk_path = raw_dir / f"risk_action_events_{stamp}.json"
            try:
                risk_path.write_text(json.dumps([pos_item], ensure_ascii=False, indent=2), encoding="utf-8")
                wrote["risk_action_events"] = True
            except Exception:
                wrote["risk_action_events"] = False
            return {
                "ok": bool(wrote.get("event_ledger") or wrote.get("risk_action_events")),
                "brief_path": str(bq),
                "brief_generated_at": gen,
                "stamp": stamp,
                "wrote": wrote,
                "event_ledger_path": (str(ledger_path) if wrote.get("event_ledger") else None),
                "risk_action_events_path": (str(risk_path) if wrote.get("risk_action_events") else None),
            }

        cmd, cwd = _fundamental_news_cmd(hours)
        run_out = _fundamental_news_run_shell_cmd(cmd=cmd, cwd=cwd, timeout_sec=1800.0)
        ok = bool(run_out.get("ok"))
        code = int(run_out.get("code") or 0)
        ts1 = int(_now_ms())
        duration_ms = int(max(0, ts1 - ts0))
        raw_refresh: Dict[str, Any] = {}
        try:
            latest_before = _fundamental_news_latest_meta()
            b = latest_before.get("brief") if isinstance(latest_before, dict) else {}
            e = latest_before.get("event_ledger") if isinstance(latest_before, dict) else {}
            r = latest_before.get("risk_action_events") if isinstance(latest_before, dict) else {}
            b_m = int((b.get("mtime_ms") or 0) if isinstance(b, dict) else 0)
            e_m = int((e.get("mtime_ms") or 0) if isinstance(e, dict) else 0)
            r_m = int((r.get("mtime_ms") or 0) if isinstance(r, dict) else 0)
            raw_stale = (b_m > 0) and ((e_m == 0 or b_m > e_m) or (r_m == 0 or b_m > r_m))
            raw_too_old = (e_m > 0 and (ts1 - e_m > 24 * 3600 * 1000)) or (r_m > 0 and (ts1 - r_m > 24 * 3600 * 1000))
            if raw_stale or raw_too_old:
                raw_refresh = _fundamental_news_refresh_raw_from_brief(int(ts1))
                _FUNDAMENTAL_NEWS_LATEST_META_CACHE["ts_ms"] = 0
                _FUNDAMENTAL_NEWS_LATEST_META_CACHE["value"] = {}
        except Exception as e:
            raw_refresh = {"ok": False, "error": str(e)[:2000]}
        latest = _fundamental_news_latest_meta()
        _fundamental_news_state_set(
            running=False,
            running_since_ms=None,
            last_run_ms=int(ts1),
            last_duration_ms=int(duration_ms),
            last_ok=bool(ok),
            last_error=(None if ok else str(run_out.get("stderr") or run_out.get("stdout") or "run_failed")[:2000]),
            last_exit_code=int(code),
            last_stdout=str(run_out.get("stdout") or "")[:2000],
            last_stderr=str(run_out.get("stderr") or "")[:2000],
            last_source=str(source),
            last_trigger_event=(trigger_event or "manual"),
            last_hours=int(hours),
            latest=latest,
            raw_refresh=raw_refresh,
        )
        return {
            "ok": bool(ok),
            "code": int(code),
            "duration_ms": int(duration_ms),
            "hours": int(hours),
            "source": str(source),
            "trigger_event": (trigger_event or "manual"),
            "latest": latest,
            "raw_refresh": raw_refresh,
            "stdout": str(run_out.get("stdout") or "")[:1000],
            "stderr": str(run_out.get("stderr") or "")[:1000],
            "ts": int(ts1),
        }
    finally:
        try:
            _FUNDAMENTAL_NEWS_LOCK.release()
        except Exception:
            pass


def _fundamental_news_digest_run_async(*, hours: int, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    h = _fundamental_news_allowed_hours(hours, default_h=_fundamental_news_window_hours())
    st = _fundamental_news_state_get()
    if bool(st.get("running")):
        return {"ok": False, "error": "already_running", "state": _json_sanitize(st), "ts": int(_now_ms())}

    def _bg() -> None:
        with app.app_context():
            try:
                _fundamental_news_digest_execute(int(h), source=str(source), trigger_event=trigger_event)
            except Exception as e:
                _fundamental_news_state_set(running=False, running_since_ms=None, last_ok=False, last_error=str(e), last_run_ms=int(_now_ms()))

    try:
        _fundamental_news_state_set(running=True, running_since_ms=int(_now_ms()), last_trigger_source=str(source), last_trigger_event=(trigger_event or "manual"), last_hours=int(h))
        threading.Thread(target=_bg, daemon=True).start()
    except Exception as e:
        _fundamental_news_state_set(running=False, running_since_ms=None, last_ok=False, last_error=str(e))
        return {"ok": False, "error": str(e), "ts": int(_now_ms())}
    return {"ok": True, "queued": True, "hours": int(h), "source": str(source), "trigger_event": (trigger_event or "manual"), "state": _json_sanitize(_fundamental_news_state_get()), "ts": int(_now_ms())}


def _fundamental_flows_pick_regime_files(limit: int = 3) -> List[Path]:
    p = _fundamental_flows_outputs_dir()
    try:
        files = sorted([x for x in p.glob("flow_regime_*.json") if x.is_file()], key=lambda x: x.stat().st_mtime, reverse=True)
    except Exception:
        files = []
    return files[: max(1, int(limit))]


def _fundamental_flows_prev_regime_record(current_name: str) -> Dict[str, Any]:
    files = _fundamental_flows_pick_regime_files(limit=5)
    if len(files) < 2:
        return {}
    cur = str(current_name or "").strip()
    prev_path: Optional[Path] = None
    if cur:
        for i, fp in enumerate(files):
            if fp.name == cur:
                if i + 1 < len(files):
                    prev_path = files[i + 1]
                break
    if prev_path is None:
        prev_path = files[1]
    if not isinstance(prev_path, Path):
        return {}
    try:
        obj = json.loads(prev_path.read_text(encoding="utf-8", errors="replace"))
    except Exception:
        return {}
    return obj if isinstance(obj, dict) else {}


def _fundamental_flows_stress_state(record: Dict[str, Any]) -> str:
    rec = record if isinstance(record, dict) else {}
    ro = (rec.get("regime_output") or {}) if isinstance(rec.get("regime_output"), dict) else {}
    quality = (rec.get("quality") or {}) if isinstance(rec.get("quality"), dict) else {}
    risk_off = bool(ro.get("risk_off") or False)
    flt = str(ro.get("filter") or rec.get("filter") or "").strip().lower()
    critical = list(quality.get("critical_missing_sources") or [])
    coverage = _fundamental_flows_num(quality.get("coverage"))
    if risk_off:
        return "high"
    if flt in ("block",):
        return "high"
    if flt in ("slowdown", "disable"):
        return "med"
    if isinstance(coverage, float) and coverage < 0.5:
        return "high"
    if critical:
        return "med"
    return "low"


def _fundamental_flows_compact_fields(record: Dict[str, Any], name: str) -> Dict[str, Any]:
    rec = record if isinstance(record, dict) else {}
    quality = (rec.get("quality") or {}) if isinstance(rec.get("quality"), dict) else {}
    coverage = _fundamental_flows_num(quality.get("coverage"))
    counts = quality.get("counts") if isinstance(quality.get("counts"), dict) else {}
    missing_data = [str(x) for x in (quality.get("critical_missing_sources") or []) if str(x or "").strip()]
    missing_data = list(dict.fromkeys(missing_data))
    rec_tag = _fundamental_flows_extract_tag_from_name(name)
    exo_src = _fundamental_flows_try_read_json(_fundamental_flows_pick_layer_raw_file("exogenous", rec_tag))
    lev_src = _fundamental_flows_try_read_json(_fundamental_flows_pick_layer_raw_file("leverage", rec_tag))
    onc_src = _fundamental_flows_try_read_json(_fundamental_flows_pick_layer_raw_file("onchain", rec_tag))
    etf_obj = (exo_src.get("etf_flow") or {}) if isinstance(exo_src.get("etf_flow"), dict) else {}
    stable_obj = (exo_src.get("stablecoin") or {}) if isinstance(exo_src.get("stablecoin"), dict) else {}
    cg_obj = (lev_src.get("coinglass") or {}) if isinstance(lev_src.get("coinglass"), dict) else {}
    bin_obj = (lev_src.get("binance") or {}) if isinstance(lev_src.get("binance"), dict) else {}
    bridge_obj = (lev_src.get("bridge") or {}) if isinstance(lev_src.get("bridge"), dict) else {}
    gn_obj = (onc_src.get("glassnode") or {}) if isinstance(onc_src.get("glassnode"), dict) else {}
    eth_obj = (onc_src.get("etherscan") or {}) if isinstance(onc_src.get("etherscan"), dict) else {}
    whale_obj = (onc_src.get("whale_alert") or {}) if isinstance(onc_src.get("whale_alert"), dict) else {}
    etf_ready = (
        (_fundamental_flows_num(etf_obj.get("btc_etf_net_inflow")) is not None)
        or (_fundamental_flows_num(etf_obj.get("eth_etf_net_inflow")) is not None)
        or (_fundamental_flows_num(stable_obj.get("total_supply_usd")) is not None)
    )
    bin_funding = _fundamental_flows_num((((bin_obj.get("funding_rate") or {}) if isinstance(bin_obj.get("funding_rate"), dict) else {}).get("last_funding_rate")))
    bin_basis = _fundamental_flows_num(bin_obj.get("basis_bps"))
    bridge_net = _fundamental_flows_num(bridge_obj.get("netflow_usd"))
    cg_ready = (
        (_fundamental_flows_num((cg_obj.get("open_interest") or {}).get("value") if isinstance(cg_obj.get("open_interest"), dict) else cg_obj.get("open_interest")) is not None)
        or (_fundamental_flows_num((cg_obj.get("liquidation_24h") or {}).get("value") if isinstance(cg_obj.get("liquidation_24h"), dict) else cg_obj.get("liquidation_24h")) is not None)
        or (bin_funding is not None)
        or (bin_basis is not None)
        or (bridge_net is not None)
    )
    eth_addr_n = len(eth_obj.get("exchange_addresses") or []) if isinstance(eth_obj.get("exchange_addresses"), list) else 0
    whale_cnt = _fundamental_flows_num(whale_obj.get("btc_large_transfers"))
    gn_ready = (
        (_fundamental_flows_num(gn_obj.get("exchange_inflow_btc")) is not None and _fundamental_flows_num(gn_obj.get("exchange_outflow_btc")) is not None)
        or (_fundamental_flows_num(gn_obj.get("exchange_balance_btc")) is not None)
        or (eth_addr_n > 0)
        or (whale_cnt is not None)
    )
    miss_set = set(missing_data)
    recovered_sources: List[str] = []
    for src, ok in (("etf", etf_ready), ("coinglass", cg_ready), ("glassnode", gn_ready)):
        if ok and src in miss_set:
            miss_set.discard(src)
            recovered_sources.append(src)
    snapshot_items = _fundamental_flows_skill_snapshot_items()
    snapshot_ready = _fundamental_flows_skill_snapshot_ready_bases(snapshot_items)
    if snapshot_ready:
        recovery_map = _fundamental_flows_snapshot_recovery_map()
        for src in list(miss_set):
            bases = recovery_map.get(str(src))
            if not isinstance(bases, list) or not bases:
                continue
            if any(str(b or "").strip() in snapshot_ready for b in bases):
                miss_set.discard(src)
                recovered_sources.append(src)
    missing_data = [x for x in missing_data if x in miss_set]
    if recovered_sources:
        miss_n0 = int(counts.get("missing") or 0)
        backfilled_n0 = int(counts.get("backfilled") or 0)
        recovered_n = max(0, min(len(recovered_sources), miss_n0))
        counts = {
            **counts,
            "missing": int(max(0, miss_n0 - recovered_n)),
            "backfilled": int(backfilled_n0 + recovered_n),
        }
        total_n = int(sum(int(counts.get(k) or 0) for k in ("ok", "stale", "missing", "backfilled", "suspect")))
        if total_n > 0:
            ok_n = int(counts.get("ok") or 0)
            stale_n = int(counts.get("stale") or 0)
            backfilled_n = int(counts.get("backfilled") or 0)
            coverage = round(float(max(0, min(total_n, ok_n + stale_n + backfilled_n))) / float(total_n), 4)
    total_n2 = int(sum(int((counts or {}).get(k) or 0) for k in ("ok", "stale", "missing", "backfilled", "suspect")))
    if total_n2 > 0:
        inferred_cov = round(float(max(0, total_n2 - len(missing_data))) / float(total_n2), 4)
        if coverage is None:
            coverage = inferred_cov
        else:
            coverage = max(float(coverage), float(inferred_cov))
    prev = _fundamental_flows_prev_regime_record(name)
    level = _fundamental_flows_num(rec.get("composite"))
    prev_level = _fundamental_flows_num(prev.get("composite"))
    slope = (None if not isinstance(level, float) or not isinstance(prev_level, float) else float(level - prev_level))
    stress = _fundamental_flows_stress_state(rec)
    tp = _fundamental_turning_point_state(
        level=level,
        slope=slope,
        stress=stress,
        coverage=coverage,
        missing_data=missing_data,
        confirm_bars=2,
    )
    return {
        "generated_at": str(rec.get("timestamp") or rec.get("generated_at") or "").strip(),
        "quality": _fundamental_quality_overall(coverage=coverage, counts=counts, critical_missing_sources=missing_data),
        "coverage": coverage,
        "missing_data": missing_data,
        "turning_point_state": str(tp.get("turning_point_state") or "unknown"),
        "trigger_reasons": list(tp.get("trigger_reasons") or []) + [f"backfilled_source:{x}" for x in recovered_sources],
        "confirm_bars": int(tp.get("confirm_bars") or 2),
        "turning_point_detail": {
            "level": level,
            "slope": slope,
            "stress": stress,
        },
        "evidence_refs": [],
        "execution_gate": "readonly_advisory",
        "stress_state": stress,
        "monitoring_clocks": _fundamental_monitoring_clocks("flows"),
    }


def _fundamental_narrative_compact_fields(record: Dict[str, Any], history_row: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    rec = record if isinstance(record, dict) else {}
    contract = (rec.get("contract") or {}) if isinstance(rec.get("contract"), dict) else {}
    scores_obj = contract.get("scores")
    scores = (scores_obj or {}) if isinstance(scores_obj, dict) else {}
    stress_obj = (scores.get("narrative_stress") or {}) if isinstance(scores.get("narrative_stress"), dict) else {}
    q_obj = contract.get("quality") if isinstance(contract.get("quality"), dict) else (rec.get("quality") if isinstance(rec.get("quality"), dict) else {})
    quality = q_obj if isinstance(q_obj, dict) else {}
    coverage = _fundamental_flows_num(quality.get("coverage"))
    if coverage is None and isinstance(history_row, dict):
        coverage = _fundamental_flows_num(history_row.get("quality_coverage"))
    missing_data = [str(x) for x in (quality.get("missing_disclosure") or []) if str(x or "").strip()]
    level = _fundamental_flows_num(scores.get("community_effective_score"))
    slope = _fundamental_flows_num(scores.get("community_impulse"))
    if slope is None and isinstance(history_row, dict):
        slope = _fundamental_flows_num(history_row.get("community_impulse"))
    stress = str(stress_obj.get("stress_level") or "unknown").strip().lower()
    if stress not in ("low", "med", "high"):
        stress = "unknown"
    tp = _fundamental_turning_point_state(
        level=level,
        slope=slope,
        stress=stress,
        coverage=coverage,
        missing_data=missing_data,
        confirm_bars=2,
    )
    evidence_refs = contract.get("evidence_refs") if isinstance(contract.get("evidence_refs"), list) else []
    quality_overall = str(quality.get("overall_quality") or "").strip()
    if not quality_overall and isinstance(history_row, dict):
        quality_overall = str(history_row.get("quality_overall") or "").strip()
    if not quality_overall:
        quality_overall = str(_fundamental_quality_overall(coverage=coverage, counts={}, critical_missing_sources=missing_data)).strip()
    return {
        "generated_at": str(rec.get("generated_at") or contract.get("generated_at") or rec.get("timestamp") or "").strip(),
        "quality": quality_overall,
        "coverage": coverage,
        "missing_data": missing_data,
        "turning_point_state": str(tp.get("turning_point_state") or "unknown"),
        "trigger_reasons": list(tp.get("trigger_reasons") or []) + [str(x) for x in (stress_obj.get("trigger_reasons") or []) if str(x or "").strip()],
        "confirm_bars": int(tp.get("confirm_bars") or 2),
        "turning_point_detail": {
            "level": level,
            "slope": slope,
            "stress": stress,
        },
        "evidence_refs": evidence_refs,
        "execution_gate": str(contract.get("execution_gate") or rec.get("execution_gate") or "readonly_advisory").strip() or "readonly_advisory",
        "stress_state": stress,
        "monitoring_clocks": _fundamental_monitoring_clocks("narrative"),
    }


def _fundamental_news_compact_fields(*, brief_generated_at: str, coverage_report: Dict[str, Any], risk_events: List[Dict[str, Any]]) -> Dict[str, Any]:
    cov_rep = coverage_report if isinstance(coverage_report, dict) else {}
    score_parts: List[float] = []
    for k in ("analysis_text_non_empty_rate", "macro_expectation_known_rate", "cross_market_map_non_empty_rate"):
        v = _fundamental_flows_num(cov_rep.get(k))
        if isinstance(v, float):
            score_parts.append(max(0.0, min(1.0, v)))
    coverage = (sum(score_parts) / len(score_parts)) if score_parts else None
    unknown_rate = _fundamental_flows_num(cov_rep.get("unknown_expectation_rate_macro"))
    missing_data: List[str] = []
    if isinstance(unknown_rate, float) and unknown_rate > 0.20:
        missing_data.append("macro_expectation")
    if not score_parts:
        missing_data.append("coverage_report")
    action_count: Dict[str, int] = {}
    for it in (risk_events or []):
        if not isinstance(it, dict):
            continue
        act = str(it.get("risk_action_proposal") or "").strip().lower()
        if not act:
            continue
        action_count[act] = int(action_count.get(act) or 0) + 1
    total = sum(action_count.values())
    high_score = float(action_count.get("stop_loss", 0) + action_count.get("reduce", 0))
    med_score = float(action_count.get("hedge", 0) + action_count.get("slowdown", 0))
    stress = "low"
    if total > 0:
        ratio = (high_score + 0.5 * med_score) / float(total)
        if ratio >= 0.45:
            stress = "high"
        elif ratio >= 0.20:
            stress = "med"
    level = (None if total <= 0 else float(-1.0 * (high_score + 0.5 * med_score) / float(total)))
    slope = level
    tp = _fundamental_turning_point_state(
        level=level,
        slope=slope,
        stress=stress,
        coverage=coverage,
        missing_data=missing_data,
        confirm_bars=2,
    )
    quality = _fundamental_quality_overall(
        coverage=coverage,
        counts={"missing": (1 if missing_data else 0), "stale": 0, "backfilled": 0, "suspect": 0},
        critical_missing_sources=missing_data,
    )
    evidence_refs: List[Dict[str, Any]] = []
    for it in (risk_events or [])[:20]:
        if not isinstance(it, dict):
            continue
        u = str(it.get("source_url") or "").strip()
        t = str(it.get("published_at") or it.get("ts") or "").strip()
        if not u:
            continue
        evidence_refs.append({"source": u, "timestamp": t})
    return {
        "generated_at": str(brief_generated_at or ""),
        "quality": quality,
        "coverage": coverage,
        "missing_data": missing_data,
        "turning_point_state": str(tp.get("turning_point_state") or "unknown"),
        "trigger_reasons": list(tp.get("trigger_reasons") or []),
        "confirm_bars": int(tp.get("confirm_bars") or 2),
        "turning_point_detail": {
            "level": level,
            "slope": slope,
            "stress": stress,
        },
        "evidence_refs": evidence_refs,
        "execution_gate": "readonly_advisory",
        "stress_state": stress,
        "monitoring_clocks": _fundamental_monitoring_clocks("news"),
    }


@app.route("/fundamental/flows/brief/latest", methods=["GET"])
def fundamental_flows_brief_latest():
    name = str(request.args.get("name") or "").strip()
    q = _fundamental_flows_pick_file(name=name)
    if q is None:
        return jsonify({"ok": False, "error": "not_found", "ts": int(_now_ms())}), 404
    try:
        text = q.read_text(encoding="utf-8", errors="replace")
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "ts": int(_now_ms())}), 500
    regime_q = _fundamental_flows_pick_regime_file("")
    regime_obj: Dict[str, Any] = {}
    if isinstance(regime_q, Path):
        try:
            rec = json.loads(regime_q.read_text(encoding="utf-8", errors="replace"))
            if isinstance(rec, dict):
                regime_obj = rec
        except Exception:
            regime_obj = {}
    compact = _fundamental_flows_compact_fields(regime_obj, (regime_q.name if isinstance(regime_q, Path) else ""))
    generated_at = _fundamental_flows_extract_generated_at(text) or str(compact.get("generated_at") or "").strip()
    tpl_guard = _fundamental_brief_template_guard(
        module_name="flows",
        content=text,
        required_title=FUNDAMENTAL_FLOWS_BRIEF_TITLE,
        required_headings=FUNDAMENTAL_FLOWS_REQUIRED_HEADINGS,
    )
    if not bool(tpl_guard.get("ok")):
        compact["quality"] = "suspect"
        compact["missing_data"] = sorted(list({*list(compact.get("missing_data") or []), "brief_template_guard"}))
        compact["trigger_reasons"] = list(compact.get("trigger_reasons") or []) + list(tpl_guard.get("reasons") or [])
    return jsonify({
        "ok": True,
        "path": str(q),
        "name": q.name,
        "generated_at": generated_at,
        "content": str(text),
        "quality": compact.get("quality"),
        "coverage": compact.get("coverage"),
        "missing_data": compact.get("missing_data"),
        "turning_point_state": compact.get("turning_point_state"),
        "trigger_reasons": compact.get("trigger_reasons"),
        "confirm_bars": compact.get("confirm_bars"),
        "turning_point_detail": compact.get("turning_point_detail"),
        "evidence_refs": compact.get("evidence_refs"),
        "execution_gate": compact.get("execution_gate"),
        "monitoring_clocks": compact.get("monitoring_clocks"),
        "template_guard": tpl_guard,
        "ts": int(_now_ms()),
    })


@app.route("/fundamental/flows/regime/latest", methods=["GET"])
def fundamental_flows_regime_latest():
    name = str(request.args.get("name") or "").strip()
    q = _fundamental_flows_pick_regime_file(name=name)
