def _fundamental_flows_quality_map(regime_record: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    out: Dict[str, Dict[str, Any]] = {}
    try:
        checks = ((((regime_record.get("diagnostics") or {}).get("data_quality") or {}).get("checks")) or [])
        if not isinstance(checks, list):
            return out
        for c in checks:
            if not isinstance(c, dict):
                continue
            nm = str(c.get("name") or "").strip()
            if not nm:
                continue
            out[nm] = c
    except Exception:
        return out
    return out


def _fundamental_flows_quality_payload(checks: Dict[str, Dict[str, Any]], key: str) -> Dict[str, Any]:
    c = checks.get(str(key or "").strip()) or {}
    status = str(c.get("status") or "").strip() or "unknown"
    reasons = c.get("status_reasons")
    if not isinstance(reasons, list):
        reasons = []
    err = str(c.get("error") or "").strip()
    return {
        "status": status,
        "reasons": [str(x) for x in reasons if str(x or "").strip()],
        "error": err,
    }


def _fundamental_flows_manual_quality(*, status: str, reasons: Optional[List[str]] = None, error: str = "") -> Dict[str, Any]:
    return {
        "status": (str(status or "").strip() or "unknown"),
        "reasons": [str(x) for x in (reasons or []) if str(x or "").strip()],
        "error": str(error or "").strip(),
    }


def _fundamental_flows_quality_from_source(source: Any, has_value: bool) -> Dict[str, Any]:
    s = source if isinstance(source, dict) else {}
    err = str(s.get("error") or "").strip()
    if bool(has_value):
        if err:
            return _fundamental_flows_manual_quality(status="suspect", reasons=["source_error_with_fallback_value"], error=err)
        rev = s.get("revision_meta")
        backfilled = bool((rev.get("is_backfilled") if isinstance(rev, dict) else False))
        if backfilled:
            return _fundamental_flows_manual_quality(status="backfilled", reasons=["revision_backfilled"], error="")
        return _fundamental_flows_manual_quality(status="ok", reasons=[], error="")
    if err:
        return _fundamental_flows_manual_quality(status="missing", reasons=["source_error"], error=err)
    return _fundamental_flows_manual_quality(status="missing", reasons=["value_missing"], error="")


def _fundamental_flows_extract_value(obj: Any, path: List[str]) -> Any:
    cur = obj
    for k in path:
        if isinstance(cur, dict) and (k in cur):
            cur = cur.get(k)
        else:
            return None
    return cur


def _fundamental_flows_recent_series(layer: str, path: List[str], limit: int = 40) -> List[float]:
    p = _fundamental_flows_raw_dir()
    if str(layer or "").strip() == "exogenous":
        d = p / "exogenous"
        pat = "exogenous_flow_*.json"
    elif str(layer or "").strip() == "leverage":
        d = p / "leverage"
        pat = "leverage_flow_*.json"
    elif str(layer or "").strip() == "onchain":
        d = p / "onchain"
        pat = "onchain_flow_*.json"
    else:
        return []
    try:
        files = sorted([x for x in d.glob(pat) if x.is_file()], key=lambda x: x.stat().st_mtime, reverse=True)[: max(2, int(limit))]
    except Exception:
        files = []
    out: List[float] = []
    for fp in reversed(files):
        try:
            obj = json.loads(fp.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue
        val = _fundamental_flows_extract_value(obj, path)
        num = _fundamental_flows_num(val)
        if isinstance(num, float):
            out.append(float(num))
    return out


def _fundamental_flows_stats(layer: str, path: List[str], current: Any) -> Dict[str, Any]:
    cur = _fundamental_flows_num(current)
    if cur is None:
        return {"raw": None, "z": None, "ema": None, "delta": None}
    xs = _fundamental_flows_recent_series(layer, path, limit=50)
    if not xs:
        return {"raw": cur, "z": None, "ema": cur, "delta": None}
    mean = sum(xs) / max(1, len(xs))
    var = sum((v - mean) * (v - mean) for v in xs) / max(1, len(xs))
    std = math.sqrt(max(0.0, var))
    z = ((cur - mean) / std) if std > 1e-12 else None
    k = min(10, max(2, len(xs)))
    alpha = 2.0 / (k + 1.0)
    ema = xs[0]
    for v in xs[1:]:
        ema = alpha * v + (1.0 - alpha) * ema
    delta = (xs[-1] - xs[-2]) if len(xs) >= 2 else None
    return {"raw": cur, "z": z, "ema": ema, "delta": delta}


def _fundamental_flows_latency_sec(source: Any) -> Optional[int]:
    s = source if isinstance(source, dict) else {}
    rev = s.get("revision_meta")
    if isinstance(rev, dict):
        try:
            late = int(rev.get("late_seconds"))
            return late
        except Exception:
            pass
    ts = s.get("timestamp")
    if ts:
        try:
            dt = datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
            now = datetime.now(timezone.utc)
            return int((now - dt).total_seconds())
        except Exception:
            return None
    return None


def _fundamental_flows_degrade_hint(quality_status: str) -> str:
    q = str(quality_status or "").strip().lower()
    if q == "ok":
        return "none"
    if q == "backfilled":
        return "drop_direction_use_risk_only"
    if q == "suspect":
        return "down_weight_and_confirm_with_other_layers"
    if q == "stale":
        return "hold_last_value_and_reduce_confidence"
    return "fallback_to_neutral_and_fail_closed"


def _fundamental_flows_num(v: Any) -> Optional[float]:
    try:
        x = float(v)
    except Exception:
        return None
    if not math.isfinite(x):
        return None
    return float(x)


def _fundamental_flows_direction(signal: Any) -> str:
    v = _fundamental_flows_num(signal)
    if v is None:
        return "neutral"
    if v > 0.12:
        return "bullish"
    if v < -0.12:
        return "bearish"
    return "neutral"


def _fundamental_flows_inference_payload(*, signal: Any, confidence: Any, contribution_weight: float, horizon: str) -> Dict[str, Any]:
    s = _fundamental_flows_num(signal)
    c = _fundamental_flows_num(confidence)
    contrib = (s * float(contribution_weight)) if isinstance(s, float) else None
    return {
        "signal": s,
        "direction": _fundamental_flows_direction(s),
        "confidence": c,
        "horizon": str(horizon or ""),
        "contribution": contrib,
    }


