@app.route("/fundamental/flows/explain/latest", methods=["GET"])
def fundamental_flows_explain_latest():
    name = str(request.args.get("name") or "").strip()
    q = _fundamental_flows_pick_regime_file(name=name)
    if q is None:
        return jsonify({"ok": False, "error": "not_found", "ts": int(_now_ms())}), 404
    try:
        obj = json.loads(q.read_text(encoding="utf-8", errors="replace"))
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "ts": int(_now_ms())}), 500
    rec = obj if isinstance(obj, dict) else {}
    compact = _fundamental_flows_compact_fields(rec, q.name)
    categories = _fundamental_flows_explain_categories(rec, q.name)
    quality = (rec.get("quality") or {}) if isinstance(rec.get("quality"), dict) else {}
    summary = {
        "composite": _fundamental_flows_num(rec.get("composite")),
        "confidence": _fundamental_flows_num(rec.get("confidence")),
        "bias": str((((rec.get("regime_output") or {}) if isinstance(rec.get("regime_output"), dict) else {}).get("bias") or rec.get("bias") or "")).strip(),
        "filter": str((((rec.get("regime_output") or {}) if isinstance(rec.get("regime_output"), dict) else {}).get("filter") or rec.get("filter") or "")).strip(),
        "risk_off": bool((((rec.get("regime_output") or {}) if isinstance(rec.get("regime_output"), dict) else {}).get("risk_off") or False)),
        "coverage": compact.get("coverage"),
        "critical_missing_sources": list(compact.get("missing_data") or []),
        "counts": quality.get("counts") if isinstance(quality.get("counts"), dict) else {},
        "data_quality_checks": ((((rec.get("diagnostics") or {}).get("data_quality") or {}).get("checks")) or []),
        "turning_point_state": compact.get("turning_point_state"),
        "trigger_reasons": compact.get("trigger_reasons"),
        "confirm_bars": compact.get("confirm_bars"),
    }
    return jsonify({
        "ok": True,
        "path": str(q),
        "name": q.name,
        "regime": _json_sanitize(rec),
        "categories": _json_sanitize(categories),
        "summary": _json_sanitize(summary),
        "generated_at": compact.get("generated_at"),
        "quality": compact.get("quality"),
        "coverage": compact.get("coverage"),
        "missing_data": compact.get("missing_data"),
        "turning_point_state": compact.get("turning_point_state"),
        "trigger_reasons": compact.get("trigger_reasons"),
        "confirm_bars": compact.get("confirm_bars"),
        "turning_point_detail": compact.get("turning_point_detail"),
        "evidence_refs": compact.get("evidence_refs"),
        "execution_gate": compact.get("execution_gate"),
        "monitoring_clocks": compact.get("monitoring_clocks"),
        "ts": int(_now_ms()),
    })


def _fundamental_http_get_json(url: str, timeout_sec: float = 4.0) -> Any:
    try:
        req = urllib_request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib_request.urlopen(req, timeout=float(timeout_sec)) as resp:
            raw = resp.read()
        return json.loads(raw.decode("utf-8", errors="replace"))
    except Exception:
        return None


def _fundamental_local_pair_last_close(pair: str) -> Optional[Dict[str, Any]]:
    try:
        p = _find_pair_file(str(pair or ""))
    except Exception:
        p = None
    try:
        c = _get_pair_cache(str(pair or ""))
    except Exception:
        c = {}
    if not isinstance(c, dict):
        return None
    raw_close = c.get("raw_close")
    raw_ts = c.get("raw_ts")
    if not isinstance(raw_close, list) or not isinstance(raw_ts, list) or not raw_close or not raw_ts:
        return None
    n = min(len(raw_close), len(raw_ts))
    if n <= 0:
        return None
    for i in range(n - 1, -1, -1):
        try:
            px = float(raw_close[i])
            ts_ms = int(raw_ts[i])
        except Exception:
            continue
        if not math.isfinite(px) or px <= 0:
            continue
        return {
            "price": float(px),
            "bar_ts_ms": int(ts_ms),
            "path": (None if p is None else str(p)),
        }
    return None


@app.route("/fundamental/flows/btc_price/latest", methods=["GET"])
def fundamental_flows_btc_price_latest():
    src = str(request.args.get("source") or "binance").strip().lower()
    price = None
    used = src or "binance"
    err = None
    if used == "binance_spot":
        used = "binance_spot"
    elif used == "binance_fapi":
        used = "binance_fapi"
    else:
        used = "binance"

    if used in ("binance", "binance_spot"):
        obj = _fundamental_http_get_json("https://api.binance.com/api/v3/ticker/price?symbol=BTCUSDT", timeout_sec=4.0)
        if isinstance(obj, dict):
            v = obj.get("price")
            try:
                price = float(v)
            except Exception:
                price = None
        if price is None:
            err = "binance_spot_unavailable"

    if price is None and used in ("binance", "binance_fapi"):
        obj = _fundamental_http_get_json("https://fapi.binance.com/fapi/v1/premiumIndex?symbol=BTCUSDT", timeout_sec=4.0)
        if isinstance(obj, dict):
            v = obj.get("markPrice") or obj.get("lastPrice")
            try:
                price = float(v)
            except Exception:
                price = None
        if price is None and err is None:
            err = "binance_fapi_unavailable"

    if price is None:
        obj = _fundamental_http_get_json("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd", timeout_sec=5.0)
        if isinstance(obj, dict):
            v = (obj.get("bitcoin") or {}).get("usd") if isinstance(obj.get("bitcoin"), dict) else None
            try:
                price = float(v)
                used = "coingecko"
                err = None
            except Exception:
                price = None

    local_meta = None
    if price is None:
        local_meta = _fundamental_local_pair_last_close("BTC")
        if isinstance(local_meta, dict):
            try:
                price = float(local_meta.get("price"))
                used = "local_ohlcv"
                err = None
            except Exception:
                price = None

    if price is None:
        return jsonify({"ok": False, "error": err or "unavailable", "ts": int(_now_ms())}), 502

    return jsonify({
        "ok": True,
        "symbol": "BTCUSDT",
        "price": float(price),
        "source": used,
        "bar_ts_ms": (None if not isinstance(local_meta, dict) else local_meta.get("bar_ts_ms")),
        "path": (None if not isinstance(local_meta, dict) else local_meta.get("path")),
        "ts": int(_now_ms()),
    })


def _fundamental_flows_latest_meta() -> Dict[str, Any]:
    b = _fundamental_flows_pick_file("")
    r = _fundamental_flows_pick_regime_file("")
    out: Dict[str, Any] = {}
    if isinstance(b, Path):
        out["brief"] = {"name": b.name, "path": str(b), "mtime_ms": int(b.stat().st_mtime * 1000)}
    if isinstance(r, Path):
        out["regime"] = {"name": r.name, "path": str(r), "mtime_ms": int(r.stat().st_mtime * 1000)}
    return out


def _fundamental_multi_agent_pick_file(kind: str, name: str = "") -> Optional[Path]:
    p = _fundamental_multi_agent_outputs_dir()
    k = str(kind or "").strip().lower()
    prefix_map = {
        "overview": "multi_agent_fundamental_overview_",
        "meeting": "multi_agent_meeting_",
        "signals": "multi_agent_signals_",
        "meta": "multi_agent_meta_",
        "summary": "multi_agent_summary_",
    }
    suffix_map = {
        "overview": ".json",
        "meeting": ".json",
        "signals": ".json",
        "meta": ".json",
        "summary": ".md",
    }
    pref = prefix_map.get(k)
    suf = suffix_map.get(k)
    if (not pref) or (not suf):
        return None
    try:
        n = _fundamental_safe_name(name)
        if n:
            q = p / n
            if q.exists() and q.is_file():
                return q
            return None
        cands = sorted([x for x in p.glob(f"{pref}*{suf}") if x.is_file()], key=lambda x: x.stat().st_mtime, reverse=True)
        if cands:
            return cands[0]
    except Exception:
        return None
    return None


def _fundamental_multi_agent_latest_meta() -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    for k in ["overview", "meeting", "signals", "meta", "summary"]:
        q = _fundamental_multi_agent_pick_file(k, "")
        if isinstance(q, Path):
            out[k] = {"name": q.name, "path": str(q), "mtime_ms": int(q.stat().st_mtime * 1000)}
    return out


def _fundamental_multi_agent_bridge_cmd(asset: str, *, debate: bool = False) -> Tuple[List[str], Path]:
    script_path = _fundamental_multi_agent_script_path()
    if (not script_path.exists()) or (not script_path.is_file()):
        raise FileNotFoundError(str(script_path))
    cmd = ["node", str(script_path), "--asset", str(asset)]
    if bool(debate):
        cmd.append("--debate")
    repo_cfg = str(CONFIG.get("multi_agent_repo") or "").strip()
    if repo_cfg:
        cmd.extend(["--multi-agent-repo", repo_cfg])
    cwd = script_path.parent.parent
    return cmd, cwd


def _fundamental_multi_agent_bridge_execute(*, asset: str, debate: bool, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    ts0 = int(_now_ms())
    got = _FUNDAMENTAL_MULTI_AGENT_LOCK.acquire(blocking=False)
    if not got:
        st = _fundamental_multi_agent_state_get()
        return {"ok": False, "error": "already_running", "ts": int(_now_ms()), "state": _json_sanitize(st)}
    _fundamental_multi_agent_state_set(
        running=True,
        running_since_ms=int(ts0),
        last_trigger_source=str(source),
        last_trigger_event=(trigger_event or "manual"),
        last_asset=str(asset or "BTC"),
        last_debate=bool(debate),
        last_error=None,
    )
    try:
        cmd, cwd = _fundamental_multi_agent_bridge_cmd(asset=str(asset or "BTC"), debate=bool(debate))
        run_out = _fundamental_news_run_shell_cmd(cmd=cmd, cwd=cwd, timeout_sec=1800.0)
        ok = bool(run_out.get("ok"))
        code = int(run_out.get("code") or 0)
        stdout_txt = str(run_out.get("stdout") or "")
        summary: Dict[str, Any] = {}
        if stdout_txt:
            try:
                summary = json.loads(stdout_txt.strip())
            except Exception:
                summary = {}
        ts1 = int(_now_ms())
        duration_ms = int(max(0, ts1 - ts0))
        latest = _fundamental_multi_agent_latest_meta()
        _fundamental_multi_agent_state_set(
            running=False,
            running_since_ms=None,
            last_run_ms=int(ts1),
            last_duration_ms=int(duration_ms),
            last_ok=bool(ok),
            last_error=(None if ok else str(run_out.get("stderr") or run_out.get("stdout") or "run_failed")[:2000]),
            last_exit_code=int(code),
            last_stdout=str(run_out.get("stdout") or "")[:2000],
            last_stderr=str(run_out.get("stderr") or "")[:2000],
            last_source=str(source),
            last_trigger_event=(trigger_event or "manual"),
            last_asset=str(asset or "BTC"),
            last_debate=bool(debate),
            latest=latest,
            summary=_json_sanitize(summary),
        )
        return {
            "ok": bool(ok),
            "code": int(code),
            "duration_ms": int(duration_ms),
            "source": str(source),
            "trigger_event": (trigger_event or "manual"),
            "asset": str(asset or "BTC"),
            "debate": bool(debate),
            "latest": latest,
            "summary": _json_sanitize(summary),
            "stdout": str(run_out.get("stdout") or "")[:1000],
            "stderr": str(run_out.get("stderr") or "")[:1000],
            "ts": int(ts1),
        }
    finally:
        try:
            _FUNDAMENTAL_MULTI_AGENT_LOCK.release()
        except Exception:
            pass


def _fundamental_multi_agent_bridge_run_async(*, asset: str, debate: bool, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    st = _fundamental_multi_agent_state_get()
    if bool(st.get("running")):
        return {"ok": False, "error": "already_running", "state": _json_sanitize(st), "ts": int(_now_ms())}

    def _bg() -> None:
        with app.app_context():
            try:
                _fundamental_multi_agent_bridge_execute(asset=str(asset), debate=bool(debate), source=str(source), trigger_event=trigger_event)
            except Exception as e:
                _fundamental_multi_agent_state_set(running=False, running_since_ms=None, last_ok=False, last_error=str(e), last_run_ms=int(_now_ms()))

    try:
        _fundamental_multi_agent_state_set(
            running=True,
            running_since_ms=int(_now_ms()),
            last_trigger_source=str(source),
            last_trigger_event=(trigger_event or "manual"),
            last_asset=str(asset or "BTC"),
            last_debate=bool(debate),
        )
        threading.Thread(target=_bg, daemon=True).start()
    except Exception as e:
        _fundamental_multi_agent_state_set(running=False, running_since_ms=None, last_ok=False, last_error=str(e))
        return {"ok": False, "error": str(e), "ts": int(_now_ms())}
    return {
        "ok": True,
        "queued": True,
        "source": str(source),
        "trigger_event": (trigger_event or "manual"),
        "asset": str(asset or "BTC"),
        "debate": bool(debate),
        "state": _json_sanitize(_fundamental_multi_agent_state_get()),
        "ts": int(_now_ms()),
    }


def _fundamental_flows_refresh_cmds() -> Tuple[List[Tuple[List[str], Path]], Path]:
    flow_root = Path(__file__).resolve().parent / "ops" / "nanoclaw" / "core_task1" / "flow"
    scripts_dir = flow_root / "scripts"
    cmd1 = ["python3", str(scripts_dir / "run_flow_analysis.py")]
    cmd2 = ["python3", str(scripts_dir / "flow_brief_generator.py")]
    return ([(cmd1, flow_root), (cmd2, flow_root)], flow_root)


def _fundamental_flows_refresh_execute(*, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    ts0 = int(_now_ms())
    got = _FUNDAMENTAL_FLOWS_LOCK.acquire(blocking=False)
    if not got:
        st = _fundamental_flows_state_get()
        return {"ok": False, "error": "already_running", "ts": int(_now_ms()), "state": _json_sanitize(st)}
    _fundamental_flows_state_set(running=True, running_since_ms=int(ts0), last_trigger_source=str(source), last_trigger_event=(trigger_event or "manual"), last_error=None)
    try:
        cmds, cwd = _fundamental_flows_refresh_cmds()
        last_out: Dict[str, Any] = {"ok": True, "code": 0, "stdout": "", "stderr": ""}
        for cmd, ccwd in cmds:
            run_out = _fundamental_news_run_shell_cmd(cmd=cmd, cwd=ccwd, timeout_sec=1800.0)
            last_out = run_out
            if not bool(run_out.get("ok")):
                break
        ok = bool(last_out.get("ok"))
        code = int(last_out.get("code") or 0)
        ts1 = int(_now_ms())
        duration_ms = int(max(0, ts1 - ts0))
        latest = _fundamental_flows_latest_meta()
        _fundamental_flows_state_set(
            running=False,
            running_since_ms=None,
            last_run_ms=int(ts1),
            last_duration_ms=int(duration_ms),
            last_ok=bool(ok),
            last_error=(None if ok else str(last_out.get("stderr") or last_out.get("stdout") or "run_failed")[:2000]),
            last_exit_code=int(code),
            last_stdout=str(last_out.get("stdout") or "")[:2000],
            last_stderr=str(last_out.get("stderr") or "")[:2000],
            last_source=str(source),
            last_trigger_event=(trigger_event or "manual"),
            latest=latest,
        )
        return {
            "ok": bool(ok),
            "code": int(code),
            "duration_ms": int(duration_ms),
            "source": str(source),
            "trigger_event": (trigger_event or "manual"),
            "latest": latest,
            "stdout": str(last_out.get("stdout") or "")[:1000],
            "stderr": str(last_out.get("stderr") or "")[:1000],
            "ts": int(ts1),
        }
    finally:
        try:
            _FUNDAMENTAL_FLOWS_LOCK.release()
        except Exception:
            pass


def _fundamental_flows_refresh_run_async(*, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    st = _fundamental_flows_state_get()
    if bool(st.get("running")):
        return {"ok": False, "error": "already_running", "state": _json_sanitize(st), "ts": int(_now_ms())}

    def _bg() -> None:
        with app.app_context():
            try:
                _fundamental_flows_refresh_execute(source=str(source), trigger_event=trigger_event)
            except Exception as e:
                _fundamental_flows_state_set(running=False, running_since_ms=None, last_ok=False, last_error=str(e), last_run_ms=int(_now_ms()))

    try:
        _fundamental_flows_state_set(running=True, running_since_ms=int(_now_ms()), last_trigger_source=str(source), last_trigger_event=(trigger_event or "manual"))
        threading.Thread(target=_bg, daemon=True).start()
    except Exception as e:
        _fundamental_flows_state_set(running=False, running_since_ms=None, last_ok=False, last_error=str(e))
        return {"ok": False, "error": str(e), "ts": int(_now_ms())}
    return {"ok": True, "queued": True, "source": str(source), "trigger_event": (trigger_event or "manual"), "state": _json_sanitize(_fundamental_flows_state_get()), "ts": int(_now_ms())}


