@app.route("/fundamental/flows/skills/snapshot/latest", methods=["GET"])
def fundamental_flows_skills_snapshot_latest():
    refresh = str(request.args.get("refresh") or "0").strip().lower() in ("1", "true", "yes", "on")
    asset = str(request.args.get("asset") or "BTC").strip() or "BTC"
    q = _fundamental_flows_skills_snapshot_file()
    if (not refresh) and q.exists() and q.is_file():
        try:
            obj = json.loads(q.read_text(encoding="utf-8", errors="replace"))
            rec = obj if isinstance(obj, dict) else {}
            rows = rec.get("items") if isinstance(rec.get("items"), list) else []
            null_count = 0
            for it in rows:
                if isinstance(it, dict) and (it.get("value") is None):
                    null_count += 1
            row_n = int(len(rows))
            trace = rec.get("source_trace") if isinstance(rec.get("source_trace"), dict) else {}
            coin_ok = bool(trace.get("coinanalysis_ok"))
            qv = str(rec.get("quality") or "").strip().lower()
            stale_missing = (qv == "missing") or ((row_n > 0) and (null_count >= row_n)) or ((not coin_ok) and (null_count > 0))
            if stale_missing:
                raise RuntimeError("stale_missing_snapshot_refresh_required")
            rec["ok"] = True
            rec["path"] = str(q)
            rec["count"] = int(len(rec.get("items") or [])) if isinstance(rec.get("items"), list) else 0
            rec["ts"] = int(_now_ms())
            return jsonify(_json_sanitize(rec))
        except RuntimeError:
            pass
        except Exception as e:
            return jsonify({"ok": False, "error": str(e), "path": str(q), "ts": int(_now_ms())}), 500
    payload = _fundamental_flows_skills_snapshot_build(asset=asset)
    try:
        q.parent.mkdir(parents=True, exist_ok=True)
        q.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass
    payload["path"] = str(q)
    return jsonify(_json_sanitize(payload))


