@app.route("/fundamental/news/brief/latest", methods=["GET"])
def fundamental_news_brief_latest():
    name = str(request.args.get("name") or "").strip()
    max_chars = _fundamental_parse_max_chars(request.args.get("max_chars"), default=200000, min_v=4000, max_v=1200000)
    q = _fundamental_news_pick_file(name=name)
    if q is None:
        return jsonify({"ok": False, "error": "not_found", "ts": int(_now_ms())}), 404
    try:
        with open(q, "r", encoding="utf-8", errors="replace") as f:
            text = f.read(int(max_chars) + 1)
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "ts": int(_now_ms())}), 500
    is_truncated = len(text) > int(max_chars)
    content = text[: int(max_chars)] if is_truncated else text
    coverage_obj: Dict[str, Any] = {}
    cq = _fundamental_news_pick_coverage_report_file("")
    if isinstance(cq, Path):
        try:
            o = json.loads(cq.read_text(encoding="utf-8", errors="replace"))
            if isinstance(o, dict):
                coverage_obj = o
        except Exception:
            coverage_obj = {}
    risk_rows: List[Dict[str, Any]] = []
    rq = _fundamental_news_pick_risk_events_file("")
    if isinstance(rq, Path):
        try:
            o2 = json.loads(rq.read_text(encoding="utf-8", errors="replace"))
            if isinstance(o2, list):
                risk_rows = [x for x in o2 if isinstance(x, dict)]
            elif isinstance(o2, dict) and isinstance(o2.get("items"), list):
                risk_rows = [x for x in (o2.get("items") or []) if isinstance(x, dict)]
        except Exception:
            risk_rows = []
    generated_at = _fundamental_news_extract_generated_at(content)
    compact = _fundamental_news_compact_fields(
        brief_generated_at=generated_at,
        coverage_report=coverage_obj,
        risk_events=risk_rows,
    )
    tpl_guard = _fundamental_brief_template_guard(
        module_name="news",
        content=content,
        required_title=BRIEF_V3_TITLE,
        required_headings=BRIEF_V3_REQUIRED_HEADINGS,
    )
    if not bool(tpl_guard.get("ok")):
        compact["quality"] = "suspect"
        compact["missing_data"] = sorted(list({*list(compact.get("missing_data") or []), "brief_template_guard"}))
        compact["trigger_reasons"] = list(compact.get("trigger_reasons") or []) + list(tpl_guard.get("reasons") or [])
    return jsonify({
        "ok": True,
        "path": str(q),
        "name": q.name,
        "generated_at": generated_at,
        "content": str(content),
        "content_chars": int(len(content)),
        "content_truncated": bool(is_truncated),
        "max_chars": int(max_chars),
        "quality": compact.get("quality"),
        "coverage": compact.get("coverage"),
        "missing_data": compact.get("missing_data"),
        "turning_point_state": compact.get("turning_point_state"),
        "trigger_reasons": compact.get("trigger_reasons"),
        "confirm_bars": compact.get("confirm_bars"),
        "turning_point_detail": compact.get("turning_point_detail"),
        "evidence_refs": compact.get("evidence_refs"),
        "execution_gate": compact.get("execution_gate"),
        "monitoring_clocks": compact.get("monitoring_clocks"),
        "template_guard": tpl_guard,
        "ts": int(_now_ms()),
    })


@app.route("/fundamental/news/event_ledger/latest", methods=["GET"])
def fundamental_news_event_ledger_latest():
    name = str(request.args.get("name") or "").strip()
    limit = _fundamental_parse_limit(request.args.get("limit"), default=80, min_v=1, max_v=500)
    q = _fundamental_news_pick_event_ledger_file(name=name)
    if q is None:
        return jsonify({"ok": False, "error": "not_found", "ts": int(_now_ms())}), 404
    rows: List[Dict[str, Any]] = []
    try:
        with open(q, "r", encoding="utf-8", errors="replace") as f:
            for i, line in enumerate(f):
                if len(rows) >= limit:
                    break
                s = str(line or "").strip()
                if not s:
                    continue
                try:
                    obj = json.loads(s)
                except Exception:
                    obj = {"raw": s}
                if isinstance(obj, dict):
                    obj["_idx"] = int(i)
                rows.append(obj if isinstance(obj, dict) else {"raw": obj, "_idx": int(i)})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "ts": int(_now_ms())}), 500

    def _brief_generated_at_and_text(max_chars: int = 260000) -> Tuple[str, str, Optional[Path]]:
        bq = _fundamental_news_pick_file(name="")
        if not isinstance(bq, Path) or (not bq.exists()) or (not bq.is_file()):
            return "", "", None
        try:
            md = bq.read_text(encoding="utf-8", errors="replace")[:max_chars]
        except Exception:
            md = ""
        gen = str(_fundamental_news_extract_generated_at(md) or "").strip()
        return gen, md, bq

    def _brief_top_points(md: str) -> Dict[str, Dict[str, str]]:
        out: Dict[str, Dict[str, str]] = {}
        if not md:
            return out
        m = re.search(r"^##\s+.*今日要点.*$", md, flags=re.MULTILINE)
        if not m:
            return out
        rest = md[m.end():]
        end_m = re.search(r"^##\s+", rest, flags=re.MULTILINE)
        block = rest[: end_m.start()] if end_m else rest
        for line in block.splitlines():
            s = str(line or "").strip()
            if not s:
                continue
            m2 = re.match(r"^\d+\.\s+\*\*\[(.+?)\]\*\*\s*-\s*(.+)$", s)
            if not m2:
                continue
            title = str(m2.group(1) or "").strip()
            if (not title) or title.lower() == "no data":
                continue
            tail = str(m2.group(2) or "").strip()
            url_m = re.search(r"来源=([^）\)\s]+)", tail)
            url = str(url_m.group(1) or "").strip() if url_m else ""
            cred_m = re.search(r"可信度=([A-Za-z_]+)", tail)
            cred = str(cred_m.group(1) or "").strip().lower() if cred_m else ""
            out[title] = {"source_url": url, "credibility": cred}
        return out

    def _brief_event_table(md: str, gen: str) -> List[Dict[str, Any]]:
        if not md:
            return []
        m = re.search(r"^###\s+今日事件账本\s*$", md, flags=re.MULTILINE)
        if not m:
            return []
        rest = md[m.end():]
        end_m = re.search(r"^###\s+|^##\s+", rest, flags=re.MULTILINE)
        block = rest[: end_m.start()] if end_m else rest
        lines = [x.strip() for x in block.splitlines() if str(x or "").strip()]
        table_lines = [x for x in lines if x.startswith("|") and x.endswith("|")]
        if len(table_lines) < 3:
            return []
        top_map = _brief_top_points(md)
        out: List[Dict[str, Any]] = []
        for i, ln in enumerate(table_lines[2:]):
            cols = [c.strip() for c in ln.strip("|").split("|")]
            if len(cols) < 6:
                continue
            title = str(cols[0] or "").strip()
            type_weight = str(cols[1] or "").strip()
            ev_type = type_weight.split("(", 1)[0].strip() if type_weight else ""
            contrib_raw = str(cols[5] or "").strip()
            try:
                contrib = float(contrib_raw)
            except Exception:
                contrib = 0.0
            act = "hold"
            if contrib <= -0.15:
                act = "reduce"
            elif contrib >= 0.15:
                act = "add"
            link = top_map.get(title) or {}
            out.append({
                "_idx": int(i),
                "event_id": f"brief_{int(i)}",
                "timestamp": (gen or datetime.utcnow().isoformat()),
                "published_at": (gen or datetime.utcnow().isoformat()),
                "event_type": (ev_type or "brief_event"),
                "expectation_bucket": "unknown",
                "risk_action_proposal": act,
                "risk_flags": [],
                "title": title,
                "source_url": str(link.get("source_url") or "").strip() or None,
                "credibility": (str(link.get("credibility") or "").strip() or "medium"),
                "evidence_grade": (str(link.get("credibility") or "").strip() or "medium"),
                "signal_contribution": contrib,
                "source": {"kind": "brief_synth", "brief_table": True},
            })
            if len(out) >= int(limit):
                break
        return out

    gen, md, bq = _brief_generated_at_and_text()
    try:
        ledger_mtime_ms = int(q.stat().st_mtime * 1000)
    except Exception:
        ledger_mtime_ms = 0
    try:
        brief_mtime_ms = int(bq.stat().st_mtime * 1000) if isinstance(bq, Path) else 0
    except Exception:
        brief_mtime_ms = 0
    now_ms = int(_now_ms())
    ledger_is_stale = (ledger_mtime_ms > 0) and (now_ms - ledger_mtime_ms > 72 * 3600 * 1000)
    brief_is_fresh = (brief_mtime_ms > 0) and (now_ms - brief_mtime_ms < 24 * 3600 * 1000)
    if ledger_is_stale and brief_is_fresh and md:
        synth = _brief_event_table(md, gen)
        if synth:
            return jsonify({
                "ok": True,
                "path": str(q),
                "name": q.name,
                "items": synth,
                "count": int(len(synth)),
                "limit": int(limit),
                "ts": int(_now_ms()),
                "fallback": {"used": True, "mode": "brief_synth_event_table", "brief_path": str(bq) if isinstance(bq, Path) else None, "brief_generated_at": gen},
            })
    return jsonify({
        "ok": True,
        "path": str(q),
        "name": q.name,
        "items": rows,
        "count": int(len(rows)),
        "limit": int(limit),
        "ts": int(_now_ms()),
    })


@app.route("/fundamental/news/risk_action_events/latest", methods=["GET"])
def fundamental_news_risk_action_events_latest():
    name = str(request.args.get("name") or "").strip()
    limit = _fundamental_parse_limit(request.args.get("limit"), default=80, min_v=1, max_v=500)
    q = _fundamental_news_pick_risk_events_file(name=name)
    if q is None:
        return jsonify({"ok": False, "error": "not_found", "ts": int(_now_ms())}), 404
    rows: List[Dict[str, Any]] = []
    try:
        obj = json.loads(q.read_text(encoding="utf-8", errors="replace"))
        if isinstance(obj, list):
            for i, it in enumerate(obj[:limit]):
                if isinstance(it, dict):
                    it2 = dict(it)
                    it2["_idx"] = int(i)
                    rows.append(it2)
                else:
                    rows.append({"_idx": int(i), "raw": it})
        elif isinstance(obj, dict):
            xs = obj.get("items")
            if isinstance(xs, list):
                for i, it in enumerate(xs[:limit]):
                    if isinstance(it, dict):
                        it2 = dict(it)
                        it2["_idx"] = int(i)
                        rows.append(it2)
                    else:
                        rows.append({"_idx": int(i), "raw": it})
            else:
                rows.append({"_idx": 0, "raw": obj})
        else:
            rows.append({"_idx": 0, "raw": obj})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "ts": int(_now_ms())}), 500

    gen = ""
    md = ""
    bq = _fundamental_news_pick_file(name="")
    if isinstance(bq, Path) and bq.exists() and bq.is_file():
        try:
            md = bq.read_text(encoding="utf-8", errors="replace")[:260000]
        except Exception:
            md = ""
        gen = str(_fundamental_news_extract_generated_at(md) or "").strip()
    try:
        risk_mtime_ms = int(q.stat().st_mtime * 1000)
    except Exception:
        risk_mtime_ms = 0
    try:
        brief_mtime_ms = int(bq.stat().st_mtime * 1000) if isinstance(bq, Path) else 0
    except Exception:
        brief_mtime_ms = 0
    now_ms = int(_now_ms())
    risk_is_stale = (risk_mtime_ms > 0) and (now_ms - risk_mtime_ms > 72 * 3600 * 1000)
    brief_is_fresh = (brief_mtime_ms > 0) and (now_ms - brief_mtime_ms < 24 * 3600 * 1000)
    if risk_is_stale and brief_is_fresh and md:
        action = ""
        pos = ""
        m1 = re.search(r"^-\s*建议动作：\*\*(.+?)\*\*\s*$", md, flags=re.MULTILINE)
        if m1:
            action = str(m1.group(1) or "").strip()
        m2 = re.search(r"^-\s*建议仓位：\*\*(.+?)\*\*\s*$", md, flags=re.MULTILINE)
        if m2:
            pos = str(m2.group(1) or "").strip()
        act_norm = (action or "HOLD").strip().lower()
        item = {
            "_idx": 0,
            "ts_ms": int(now_ms),
            "published_at": (gen or datetime.utcnow().isoformat()),
            "ts": (gen or datetime.utcnow().isoformat()),
            "event_type": "position",
            "title": "brief_position_advice",
            "risk_action_proposal": act_norm,
            "risk_action": act_norm,
            "reason": (f"position={pos}" if pos else "from_brief"),
            "source": "brief_synth",
            "evidence_grade": "brief",
        }
        return jsonify({
            "ok": True,
            "path": str(q),
            "name": q.name,
            "items": [item],
            "count": 1,
            "limit": int(limit),
            "ts": int(_now_ms()),
            "fallback": {"used": True, "mode": "brief_synth_position", "brief_path": str(bq) if isinstance(bq, Path) else None, "brief_generated_at": gen},
        })
    return jsonify({
        "ok": True,
        "path": str(q),
        "name": q.name,
        "items": rows,
        "count": int(len(rows)),
        "limit": int(limit),
        "ts": int(_now_ms()),
    })


