@app.route("/fundamental/multi-agent/latest", methods=["GET"])
def fundamental_multi_agent_latest():
    kind = str(request.args.get("kind") or "overview").strip().lower()
    if kind not in ("overview", "meeting", "signals", "meta", "summary"):
        return jsonify({"ok": False, "error": "bad_kind", "allowed": ["overview", "meeting", "signals", "meta", "summary"], "ts": int(_now_ms())}), 400
    name = str(request.args.get("name") or "").strip()
    q = _fundamental_multi_agent_pick_file(kind=kind, name=name)
    if q is None:
        return jsonify({"ok": False, "error": "not_found", "kind": kind, "ts": int(_now_ms())}), 404
    if kind == "summary":
        max_chars = _fundamental_parse_max_chars(request.args.get("max_chars"), default=200000, min_v=4000, max_v=1200000)
        try:
            with open(q, "r", encoding="utf-8", errors="replace") as f:
                text = f.read(int(max_chars) + 1)
        except Exception as e:
            return jsonify({"ok": False, "error": str(e), "ts": int(_now_ms())}), 500
        truncated = len(text) > int(max_chars)
        return jsonify({
            "ok": True,
            "kind": kind,
            "name": q.name,
            "path": str(q),
            "content": (text[: int(max_chars)] if truncated else text),
            "truncated": bool(truncated),
            "latest": _json_sanitize(_fundamental_multi_agent_latest_meta()),
            "ts": int(_now_ms()),
        })
    try:
        obj = json.loads(q.read_text(encoding="utf-8", errors="replace"))
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "ts": int(_now_ms())}), 500
    return jsonify({
        "ok": True,
        "kind": kind,
        "name": q.name,
        "path": str(q),
        "record": _json_sanitize(obj),
        "latest": _json_sanitize(_fundamental_multi_agent_latest_meta()),
        "ts": int(_now_ms()),
    })


def _fundamental_trading_advice_latest(*, force_rebuild: bool = False) -> Dict[str, Any]:
    if not bool(force_rebuild):
        st = _fundamental_trading_state_get()
        cached = st.get("last_output")
        if isinstance(cached, dict):
            return dict(cached)
    flow_q = _fundamental_flows_pick_regime_file("")
    nar_q = _fundamental_narrative_pick_registry_file("")
    risk_q = _fundamental_news_pick_risk_events_file("")
    coverage_q = _fundamental_news_pick_coverage_report_file("")
    flow_rec: Dict[str, Any] = {}
    nar_rec: Dict[str, Any] = {}
    risk_rows: List[Dict[str, Any]] = []
    coverage_obj: Dict[str, Any] = {}
    if isinstance(flow_q, Path):
        try:
            x = json.loads(flow_q.read_text(encoding="utf-8", errors="replace"))
            if isinstance(x, dict):
                flow_rec = x
        except Exception:
            flow_rec = {}
    if isinstance(nar_q, Path):
        try:
            x = json.loads(nar_q.read_text(encoding="utf-8", errors="replace"))
            if isinstance(x, dict):
                nar_rec = x
        except Exception:
            nar_rec = {}
    if isinstance(risk_q, Path):
        try:
            x = json.loads(risk_q.read_text(encoding="utf-8", errors="replace"))
            if isinstance(x, list):
                risk_rows = [it for it in x if isinstance(it, dict)]
            elif isinstance(x, dict) and isinstance(x.get("items"), list):
                risk_rows = [it for it in (x.get("items") or []) if isinstance(it, dict)]
        except Exception:
            risk_rows = []
    if isinstance(coverage_q, Path):
        try:
            x = json.loads(coverage_q.read_text(encoding="utf-8", errors="replace"))
            if isinstance(x, dict):
                coverage_obj = x
        except Exception:
            coverage_obj = {}
    flow_compact = _fundamental_flows_compact_fields(flow_rec, (flow_q.name if isinstance(flow_q, Path) else ""))
    nar_compact = _fundamental_narrative_compact_fields(nar_rec, None)
    news_compact = _fundamental_news_compact_fields(
        brief_generated_at=str(nar_rec.get("generated_at") or flow_compact.get("generated_at") or ""),
        coverage_report=coverage_obj,
        risk_events=risk_rows,
    )
    ro = (flow_rec.get("regime_output") or {}) if isinstance(flow_rec.get("regime_output"), dict) else {}
    flow_bias = str(ro.get("bias") or flow_rec.get("bias") or "").strip().lower()
    bias_dir = "neutral"
    if flow_bias in ("long_bias", "long", "bullish"):
        bias_dir = "long_only"
    elif flow_bias in ("short_bias", "short", "bearish"):
        bias_dir = "short_only"
    elif flow_bias in ("two_sided",):
        bias_dir = "two_sided"
    flow_filter = str(ro.get("filter") or flow_rec.get("filter") or "").strip().lower()
    nar_stress = str(nar_compact.get("stress_state") or "unknown").strip().lower()
    flow_stress = str(flow_compact.get("stress_state") or "unknown").strip().lower()
    missing_data = [str(x) for x in list(flow_compact.get("missing_data") or []) + list(nar_compact.get("missing_data") or []) + list(news_compact.get("missing_data") or []) if str(x or "").strip()]
    if flow_filter in ("block",) or flow_stress == "high" or nar_stress == "high":
        execution_filter = "block"
        risk_action = "reduce"
        position_scale = 0.30
    elif flow_filter in ("slowdown", "disable") or flow_stress == "med" or nar_stress == "med":
        execution_filter = "slowdown"
        risk_action = "hedge"
        position_scale = 0.60
    else:
        execution_filter = "allow"
        risk_action = "hold"
        position_scale = 1.00
    if missing_data:
        execution_filter = "block" if execution_filter == "allow" else execution_filter
        if risk_action == "hold":
            risk_action = "hedge"
        position_scale = min(position_scale, 0.60)
    generated_candidates = [
        str(flow_compact.get("generated_at") or "").strip(),
        str(nar_compact.get("generated_at") or "").strip(),
        str(news_compact.get("generated_at") or "").strip(),
    ]
    generated_at = next((x for x in generated_candidates if x), "")
    quality_levels = [str(flow_compact.get("quality") or "unknown"), str(nar_compact.get("quality") or "unknown"), str(news_compact.get("quality") or "unknown")]
    quality_rank = {"ok": 0, "stale": 1, "backfilled": 2, "suspect": 3, "missing": 4, "unknown": 5}
    overall_quality = sorted(quality_levels, key=lambda x: quality_rank.get(str(x).strip().lower(), 5), reverse=True)[0]
    coverage_vals = [_fundamental_flows_num(flow_compact.get("coverage")), _fundamental_flows_num(nar_compact.get("coverage")), _fundamental_flows_num(news_compact.get("coverage"))]
    cov_xs = [x for x in coverage_vals if isinstance(x, float)]
    coverage = (sum(cov_xs) / len(cov_xs)) if cov_xs else None
    evidence_refs: List[Dict[str, Any]] = []
    if isinstance(flow_q, Path):
        evidence_refs.append({"module": "flows", "path": str(flow_q), "timestamp": str(flow_compact.get("generated_at") or "")})
    if isinstance(nar_q, Path):
        evidence_refs.append({"module": "narrative", "path": str(nar_q), "timestamp": str(nar_compact.get("generated_at") or "")})
    for row in risk_rows[:8]:
        u = str(row.get("source_url") or "").strip()
        t = str(row.get("published_at") or row.get("ts") or "").strip()
        if u:
            evidence_refs.append({"module": "news", "source": u, "timestamp": t})
    tp_state = str(flow_compact.get("turning_point_state") or "unknown")
    tp_reasons = list(flow_compact.get("trigger_reasons") or [])
    if not tp_reasons:
        tp_reasons = [str(nar_compact.get("turning_point_state") or "unknown"), str(news_compact.get("turning_point_state") or "unknown")]
    flow_tp_detail = flow_compact.get("turning_point_detail") if isinstance(flow_compact.get("turning_point_detail"), dict) else {}
    trading_tp_detail = {
        "level": _fundamental_flows_num(flow_tp_detail.get("level")),
        "slope": _fundamental_flows_num(flow_tp_detail.get("slope")),
        "stress": str(flow_tp_detail.get("stress") or flow_stress or "unknown").strip().lower(),
    }
    return {
        "generated_at": generated_at,
        "quality": overall_quality,
        "coverage": coverage,
        "missing_data": missing_data,
        "turning_point_state": tp_state,
        "trigger_reasons": tp_reasons,
        "confirm_bars": 2,
        "turning_point_detail": trading_tp_detail,
        "execution_gate": "readonly_advisory",
        "monitoring_clocks": _fundamental_monitoring_clocks("trading"),
        "bias": {
            "bias_dir": bias_dir,
            "reasons": [f"flow_bias={flow_bias or 'neutral'}", f"flow_turning={flow_compact.get('turning_point_state')}", f"narrative_stress={nar_stress}"],
        },
        "filter": {
            "execution_filter": execution_filter,
            "blocked_reasons": missing_data,
        },
        "risk_off": {
            "risk_action_proposal": risk_action,
            "position_scale": float(max(0.0, min(1.0, position_scale))),
            "valid_until": int(_now_ms() + 4 * 3600 * 1000),
        },
        "quality_summary": {
            "flows": {"quality": flow_compact.get("quality"), "coverage": flow_compact.get("coverage")},
            "narrative": {"quality": nar_compact.get("quality"), "coverage": nar_compact.get("coverage")},
            "news": {"quality": news_compact.get("quality"), "coverage": news_compact.get("coverage")},
            "overall_quality": overall_quality,
            "overall_coverage": coverage,
        },
        "doc_refs": [
            {"doc": "基本面研究文档.md", "section": "14-15"},
            {"doc": "技术文档.md", "section": "0.0"},
        ],
        "evidence_refs": evidence_refs,
    }


def _fundamental_trading_advice_refresh_execute(*, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    now_ms = int(_now_ms())
    now_iso = datetime.now(timezone.utc).isoformat()
    _fundamental_trading_state_set(
        running=True,
        last_run_ms=int(now_ms),
        last_source=str(source),
        last_trigger_event=(None if trigger_event is None else str(trigger_event)),
        last_error=None,
    )
    try:
        rep = _fundamental_trading_advice_latest(force_rebuild=True)
        tpl_guard = _fundamental_trading_template_guard(rep)
        if not bool(tpl_guard.get("ok")):
            rep["quality"] = "suspect"
            rep["missing_data"] = sorted(list({*list(rep.get("missing_data") or []), "trading_template_guard"}))
            rep["trigger_reasons"] = list(rep.get("trigger_reasons") or []) + list(tpl_guard.get("reasons") or [])
        rep["template_guard"] = tpl_guard
        generated_ms = _fundamental_iso_to_ms(rep.get("generated_at"))
        signal_age_sec = (None if generated_ms is None else max(0, int((int(now_ms) - int(generated_ms)) / 1000)))
        fresh_sec = int(_fundamental_trading_freshness_sec())
        rep["production"] = {
            "produced_at": str(now_iso),
            "produced_ts": int(now_ms),
            "source": str(source),
            "trigger_event": (None if trigger_event is None else str(trigger_event)),
            "signal_age_sec": (None if signal_age_sec is None else int(signal_age_sec)),
            "freshness_target_sec": int(fresh_sec),
            "fresh": bool((signal_age_sec is not None) and (int(signal_age_sec) <= int(fresh_sec))),
        }
        rep["monitoring_clocks"] = _fundamental_monitoring_clocks("trading")
        st = _fundamental_trading_state_set(
            running=False,
            last_success_ms=int(now_ms),
            last_error=None,
            last_error_ms=None,
            last_output=_json_sanitize(rep),
            last_output_ts=int(now_ms),
            last_output_generated_at=str(rep.get("generated_at") or ""),
            last_output_signal_age_sec=(None if signal_age_sec is None else int(signal_age_sec)),
            updated_at=str(now_iso),
        )
        return {"ok": True, "ts": int(now_ms), "state": _json_sanitize(st), "output": _json_sanitize(rep)}
    except Exception as e:
        st = _fundamental_trading_state_set(
            running=False,
            last_error=str(e),
            last_error_ms=int(now_ms),
            updated_at=str(now_iso),
        )
        return {"ok": False, "error": str(e), "ts": int(now_ms), "state": _json_sanitize(st)}


def _fundamental_trading_advice_refresh_run_async(*, source: str, trigger_event: Optional[str]) -> Dict[str, Any]:
    st = _fundamental_trading_state_get()
    if bool(st.get("running")):
        return {"ok": True, "scheduled": False, "reason": "already_running", "ts": int(_now_ms()), "state": _json_sanitize(st)}
    try:
        def _bg():
            with app.app_context():
                _fundamental_trading_advice_refresh_execute(source=str(source), trigger_event=trigger_event)

        threading.Thread(target=_bg, daemon=True).start()
        st2 = _fundamental_trading_state_set(running=True, queued_at=int(_now_ms()), queued_source=str(source), queued_trigger_event=(None if trigger_event is None else str(trigger_event)))
        return {"ok": True, "scheduled": True, "ts": int(_now_ms()), "state": _json_sanitize(st2)}
    except Exception as e:
        return {"ok": False, "error": str(e), "ts": int(_now_ms()), "state": _json_sanitize(_fundamental_trading_state_get())}


@app.route("/fundamental/trading/latest", methods=["GET"])
def fundamental_trading_latest():
    st = _fundamental_trading_state_get()
    rep = st.get("last_output") if isinstance(st.get("last_output"), dict) else None
    if not isinstance(rep, dict):
        run = _fundamental_trading_advice_refresh_execute(source="on_read", trigger_event="on_read")
        rep = (run.get("output") if isinstance(run.get("output"), dict) else None)
    if not isinstance(rep, dict):
        rep = _fundamental_trading_advice_latest(force_rebuild=True)
        tpl_guard = _fundamental_trading_template_guard(rep)
        rep["template_guard"] = tpl_guard
    return jsonify({"ok": True, **_json_sanitize(rep), "ts": int(_now_ms())})


