def _fundamental_risk_top_items(risk_rows: List[Dict[str, Any]], limit: int = 8) -> List[str]:
    rows = [x for x in (risk_rows or []) if isinstance(x, dict)]
    out: List[str] = []
    for it in rows:
        title = str(it.get("title") or "").strip()
        act = str(it.get("risk_action_proposal") or "").strip().lower()
        et = str(it.get("event_type") or "").strip()
        if not title and not act and not et:
            continue
        parts = [x for x in [et, act, title] if x]
        out.append(" | ".join(parts))
        if len(out) >= int(max(1, limit)):
            break
    return out


def _fundamental_overview_latest() -> Dict[str, Any]:
    gray_v1_on = str(os.getenv("FUNDAMENTAL_GRAY_V1", "1")).strip() == "1"
    source_summary = {
        "primary_sources": [
            "okx:market-intel",
            "okx:cmc-okx",
            "okx:alpha-vantage",
            "okx:hyperliquid-analyzer",
        ],
        "cross_validation": [
            "gate-info-research",
            "gate-info-coinanalysis",
            "binance:crypto-market-rank",
        ],
        "fallback_enabled": True,
    }
    news_q = _fundamental_news_pick_file("")
    news_text = ""
    if isinstance(news_q, Path):
        try:
            news_text = news_q.read_text(encoding="utf-8", errors="replace")
        except Exception:
            news_text = ""
    cov_obj: Dict[str, Any] = {}
    cov_q = _fundamental_news_pick_coverage_report_file("")
    if isinstance(cov_q, Path):
        try:
            x = json.loads(cov_q.read_text(encoding="utf-8", errors="replace"))
            if isinstance(x, dict):
                cov_obj = x
        except Exception:
            cov_obj = {}
    risk_rows: List[Dict[str, Any]] = []
    risk_q = _fundamental_news_pick_risk_events_file("")
    if isinstance(risk_q, Path):
        try:
            x = json.loads(risk_q.read_text(encoding="utf-8", errors="replace"))
            if isinstance(x, list):
                risk_rows = [it for it in x if isinstance(it, dict)]
            elif isinstance(x, dict) and isinstance(x.get("items"), list):
                risk_rows = [it for it in (x.get("items") or []) if isinstance(it, dict)]
        except Exception:
            risk_rows = []
    news_compact = _fundamental_news_compact_fields(
        brief_generated_at=_fundamental_news_extract_generated_at(news_text),
        coverage_report=cov_obj,
        risk_events=risk_rows,
    )
    news_guard = _fundamental_brief_template_guard(
        module_name="news",
        content=news_text,
        required_title=BRIEF_V3_TITLE,
        required_headings=BRIEF_V3_REQUIRED_HEADINGS,
    )
    if not bool(news_guard.get("ok")):
        news_compact["quality"] = "suspect"
        news_compact["missing_data"] = sorted(list({*list(news_compact.get("missing_data") or []), "brief_template_guard"}))

    flow_regime_q = _fundamental_flows_pick_regime_file("")
    flow_rec: Dict[str, Any] = {}
    if isinstance(flow_regime_q, Path):
        try:
            x = json.loads(flow_regime_q.read_text(encoding="utf-8", errors="replace"))
            if isinstance(x, dict):
                flow_rec = x
        except Exception:
            flow_rec = {}
    flow_compact = _fundamental_flows_compact_fields(flow_rec, (flow_regime_q.name if isinstance(flow_regime_q, Path) else ""))
    flow_brief_q = _fundamental_flows_pick_file("")
    flow_text = ""
    if isinstance(flow_brief_q, Path):
        try:
            flow_text = flow_brief_q.read_text(encoding="utf-8", errors="replace")
        except Exception:
            flow_text = ""
    flow_guard = _fundamental_brief_template_guard(
        module_name="flows",
        content=flow_text,
        required_title=FUNDAMENTAL_FLOWS_BRIEF_TITLE,
        required_headings=FUNDAMENTAL_FLOWS_REQUIRED_HEADINGS,
    )
    if not bool(flow_guard.get("ok")):
        flow_compact["quality"] = "suspect"
        flow_compact["missing_data"] = sorted(list({*list(flow_compact.get("missing_data") or []), "brief_template_guard"}))

    nar_registry_q = _fundamental_narrative_pick_registry_file("")
    nar_rec: Dict[str, Any] = {}
    if isinstance(nar_registry_q, Path):
        try:
            x = json.loads(nar_registry_q.read_text(encoding="utf-8", errors="replace"))
            if isinstance(x, dict):
                nar_rec = x
        except Exception:
            nar_rec = {}
    nar_compact = _fundamental_narrative_compact_fields(nar_rec, None)
    nar_brief_q = _fundamental_narrative_pick_brief_file("")
    nar_text = ""
    if isinstance(nar_brief_q, Path):
        try:
            nar_text = nar_brief_q.read_text(encoding="utf-8", errors="replace")
        except Exception:
            nar_text = ""
    nar_guard = _fundamental_brief_template_guard(
        module_name="narrative",
        content=nar_text,
        required_title=FUNDAMENTAL_NARRATIVE_BRIEF_TITLE,
        required_headings=FUNDAMENTAL_NARRATIVE_REQUIRED_HEADINGS,
    )
    if not bool(nar_guard.get("ok")):
        nar_compact["quality"] = "suspect"
        nar_compact["missing_data"] = sorted(list({*list(nar_compact.get("missing_data") or []), "brief_template_guard"}))

    trading = _fundamental_trading_advice_latest()
    trading_guard = _fundamental_trading_template_guard(trading)
    if not bool(trading_guard.get("ok")):
        trading["quality"] = "suspect"
        trading["missing_data"] = sorted(list({*list(trading.get("missing_data") or []), "trading_template_guard"}))

    covs = {
        "news": _fundamental_flows_num(news_compact.get("coverage")),
        "flows": _fundamental_flows_num(flow_compact.get("coverage")),
        "narrative": _fundamental_flows_num(nar_compact.get("coverage")),
        "trading": _fundamental_flows_num(trading.get("coverage")),
    }
    module_quality = {
        "news": str(news_compact.get("quality") or "unknown"),
        "flows": str(flow_compact.get("quality") or "unknown"),
        "narrative": str(nar_compact.get("quality") or "unknown"),
        "trading": str(trading.get("quality") or "unknown"),
    }
    missing_data = {
        "news": list(news_compact.get("missing_data") or []),
        "flows": list(flow_compact.get("missing_data") or []),
        "narrative": list(nar_compact.get("missing_data") or []),
        "trading": list(trading.get("missing_data") or []),
    }
    top_risks = _fundamental_risk_top_items(risk_rows, limit=8)
    for x in list(trading.get("trigger_reasons") or [])[:4]:
        sx = str(x or "").strip()
        if sx:
            top_risks.append(f"trading | {sx}")
    top_risks = top_risks[:12]
    modules = {
        "news": {**news_compact, "template_guard": news_guard},
        "flows": {**flow_compact, "template_guard": flow_guard},
        "narrative": {**nar_compact, "template_guard": nar_guard},
        "trading": {**trading, "template_guard": trading_guard},
    }
    heatmap = []
    for k in ["news", "flows", "narrative", "trading"]:
        heatmap.append({
            "module": k,
            "quality": module_quality.get(k),
            "coverage": covs.get(k),
            "turning_point_state": str((modules.get(k) or {}).get("turning_point_state") or "unknown"),
        })
    regime_transition = [
        {"module": "flows", "state": str(flow_compact.get("turning_point_state") or "unknown"), "ts": str(flow_compact.get("generated_at") or "")},
        {"module": "narrative", "state": str(nar_compact.get("turning_point_state") or "unknown"), "ts": str(nar_compact.get("generated_at") or "")},
        {"module": "news", "state": str(news_compact.get("turning_point_state") or "unknown"), "ts": str(news_compact.get("generated_at") or "")},
        {"module": "trading", "state": str(trading.get("turning_point_state") or "unknown"), "ts": str(trading.get("generated_at") or "")},
    ]
    gate_timeline = [
        {"module": "news", "gate": str(news_compact.get("execution_gate") or "readonly_advisory"), "ts": str(news_compact.get("generated_at") or "")},
        {"module": "flows", "gate": str(flow_compact.get("execution_gate") or "readonly_advisory"), "ts": str(flow_compact.get("generated_at") or "")},
        {"module": "narrative", "gate": str(nar_compact.get("execution_gate") or "readonly_advisory"), "ts": str(nar_compact.get("generated_at") or "")},
        {"module": "trading", "gate": str(trading.get("execution_gate") or "readonly_advisory"), "ts": str(trading.get("generated_at") or "")},
    ]
    quadrant_templates = {
        "news": {
            "main_series": {"required": True, "placeholder": True},
            "quantile_band": {"required": True, "placeholder": True},
            "turning_markers": {"required": True, "placeholder": True},
            "quality_coverage_bar": {"required": True, "placeholder": True},
        },
        "flows": {
            "main_series": {"required": True, "placeholder": True},
            "quantile_band": {"required": True, "placeholder": True},
            "turning_markers": {"required": True, "placeholder": True},
            "quality_coverage_bar": {"required": True, "placeholder": True},
        },
        "narrative": {
            "main_series": {"required": True, "placeholder": True},
            "quantile_band": {"required": True, "placeholder": True},
            "turning_markers": {"required": True, "placeholder": True},
            "quality_coverage_bar": {"required": True, "placeholder": True},
        },
        "trading": {
            "main_series": {"required": True, "placeholder": True},
            "quantile_band": {"required": True, "placeholder": True},
            "turning_markers": {"required": True, "placeholder": True},
            "quality_coverage_bar": {"required": True, "placeholder": True},
        },
    }
    out = {
        "asof": datetime.now(timezone.utc).isoformat(),
        "time_window_hours": 24,
        "overall_quality": _fundamental_quality_overall(
            coverage=(sum([x for x in covs.values() if isinstance(x, float)]) / max(1, len([x for x in covs.values() if isinstance(x, float)]))),
            counts={},
            critical_missing_sources=[k for k, v in module_quality.items() if str(v).strip().lower() in ("missing", "suspect")],
        ),
        "coverage": covs,
        "missing_data": missing_data,
        "top_risks": top_risks,
        "modules": modules,
        "chart_pack": {
            "quadrant_templates": quadrant_templates,
            "top_level": {
                "cross_module_heatmap": heatmap,
                "regime_transition": regime_transition,
                "gate_action_timeline": gate_timeline,
            },
        },
    }
    if gray_v1_on:
        out["source_summary"] = source_summary
    return out


