@app.route("/agent/outbox/ack", methods=["POST"])
def agent_outbox_ack():
    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="agent.outbox.ack")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    items = data.get("items")
    if not isinstance(items, list) or not items:
        return jsonify({"ok": False, "error": "no_items"}), 400
    out_items = []
    for it in items:
        if not isinstance(it, dict):
            continue
        out_items.append({
            "id": str(it.get("id") or "").strip(),
            "trace_id": str(it.get("trace_id") or "").strip(),
            "channel": str(it.get("channel") or "").strip().lower(),
            "ok": bool(it.get("ok")),
            "attempt": int(it.get("attempt") or 0),
            "provider_msg_id": (None if it.get("provider_msg_id") is None else str(it.get("provider_msg_id"))),
            "status_code": (None if it.get("status_code") is None else int(it.get("status_code") or 0)),
            "error": (None if it.get("error") is None else str(it.get("error"))),
            "ts": int(it.get("ts") or _now_ms()),
            "idempotency_key": (None if it.get("idempotency_key") is None else str(it.get("idempotency_key"))),
        })
    if not out_items:
        return jsonify({"ok": False, "error": "no_valid_items"}), 400
    q = _agent_outbox_dir() / "delivery_receipts.jsonl"
    saved = 0
    try:
        with open(q, "a", encoding="utf-8") as f:
            for it in out_items:
                f.write(json.dumps(it, ensure_ascii=False) + "\n")
                saved += 1
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500
    try:
        _audit_emit_action(
            "agent.outbox.ack",
            _audit_base_payload(scope="governance", action="agent.outbox.ack", trace_id=trace_id, extra={"ok": True, "saved": int(saved), "approval_id": approval_id}),
        )
    except Exception:
        pass
    return jsonify({"ok": True, "saved": int(saved), "trace_id": trace_id, "approval_id": approval_id, "ts": int(_now_ms())})


