@app.route("/repo/whitelist/update", methods=["POST"])
def repo_whitelist_update():
    if _governance_hmac_secret():
        if not _governance_write_auth_ok():
            return jsonify({"ok": False, "error": "unauthorized"}), 403
    else:
        if not (_governance_write_auth_ok() or _agent_sandbox_task_auth_ok()):
            return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="repo.whitelist.update")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    rb_pt = _rollback_snapshot_append(label="repo.whitelist.update", reason="l2_preflight", config_keys=["repo_fetch_enabled", "repo_whitelist"])
    if rb_pt is None:
        return jsonify({"ok": False, "error": "rollback_snapshot_failed", "ts": int(_now_ms())}), 500
    enabled = data.get("enabled")
    if enabled is not None:
        CONFIG["repo_fetch_enabled"] = bool(enabled)
        try:
            _save_config()
        except Exception:
            pass
    items = None
    if isinstance(data.get("items"), list):
        items = [str(x).strip() for x in data.get("items") if str(x).strip()]
    add_items = [str(x).strip() for x in (data.get("add") if isinstance(data.get("add"), list) else []) if str(x).strip()]
    remove_items = [str(x).strip() for x in (data.get("remove") if isinstance(data.get("remove"), list) else []) if str(x).strip()]
    cur = _repo_whitelist_list()
    if items is not None:
        cur = items
    if add_items:
        for it in add_items:
            if it not in cur:
                cur.append(it)
    if remove_items:
        cur = [it for it in cur if it not in remove_items]
    cur = _repo_whitelist_set(cur)
    try:
        _audit_emit_action(
            "repo.whitelist.update",
            _audit_base_payload(scope="governance", action="repo.whitelist.update", trace_id=trace_id, extra={"ok": True, "enabled": bool(_repo_fetch_enabled()), "count": int(len(cur)), "approval_id": approval_id, "rollback_point": (rb_pt.get("id") if isinstance(rb_pt, dict) else None)}),
        )
    except Exception:
        pass
    return jsonify({"ok": True, "enabled": _repo_fetch_enabled(), "count": len(cur), "items": cur, "trace_id": trace_id, "approval_id": approval_id, "rollback_point": (rb_pt.get("id") if isinstance(rb_pt, dict) else None), "ts": int(_now_ms())})


@app.route("/repo/fetch_strategy_stub", methods=["POST"])
def repo_fetch_strategy_stub():
    if _governance_hmac_secret():
        if not _governance_write_auth_ok():
            return jsonify({"ok": False, "error": "unauthorized"}), 403
    else:
        if not (_governance_write_auth_ok() or _agent_sandbox_task_auth_ok()):
            return jsonify({"ok": False, "error": "unauthorized"}), 403
    if not _repo_fetch_enabled():
        return jsonify({"ok": False, "error": "repo_fetch_disabled"}), 400
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="repo.fetch_strategy_stub")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    repo_url_raw = data.get("repo_url")
    branch = data.get("branch")
    commit = data.get("commit")
    subpath = data.get("path")
    strategy_name = data.get("strategy_name")
    repo_from_tree, tree_branch, tree_subpath = _parse_github_tree_url(str(repo_url_raw or ""))
    if repo_from_tree:
        repo_url_raw = repo_from_tree
        if (not branch) and tree_branch:
            branch = tree_branch
        if (not subpath) and tree_subpath:
            subpath = tree_subpath
    repo_url = _normalize_repo_url(repo_url_raw)
    if not repo_url:
        return jsonify({"ok": False, "error": "missing_repo_url"}), 400
    if not _repo_url_allowed(repo_url):
        return jsonify({"ok": False, "error": "repo_not_whitelisted"}), 403
    ok, head, repo_path, err = _repo_ensure_cached(repo_url, branch=branch, commit=commit)
    if not ok or repo_path is None:
        return jsonify({"ok": False, "error": "repo_fetch_failed", "detail": err}), 500
    repo_id = _repo_id_from_url(repo_url)
    commit_id = str(head or "")
    if not commit_id:
        return jsonify({"ok": False, "error": "commit_not_found"}), 500
    if subpath and str(subpath).strip().lower().endswith(".py"):
        try:
            pp = Path(str(subpath).strip())
            if not strategy_name:
                strategy_name = pp.stem
            parent = str(pp.parent).strip()
            subpath = (None if (not parent) or parent == "." else parent)
        except Exception:
            pass
    stage_ok, sandbox_path, files, stage_err, diff_summary = _strategy_sandbox_stage(repo_path, subpath, repo_id, commit_id, strategy_name=strategy_name)
    if not stage_ok:
        return jsonify({"ok": False, "error": stage_err}), 400
    _repo_update_registry(repo_id, repo_url, repo_path, commit_id)
    try:
        _audit_emit_action(
            "repo.fetch_strategy_stub",
            _audit_base_payload(scope="governance", action="repo.fetch_strategy_stub", trace_id=trace_id, extra={"ok": True, "repo_id": repo_id, "commit": commit_id, "approval_id": approval_id, "repo_url": str(repo_url)}),
        )
    except Exception:
        pass
    return jsonify({"ok": True, "repo_id": repo_id, "commit": commit_id, "files": files, "diff_summary": diff_summary, "sandbox_path": sandbox_path, "trace_id": trace_id, "approval_id": approval_id})


