def _agent_skills_execute_process(trace_id: str, tool_plan: List[Dict[str, Any]]) -> None:
    tid = str(trace_id or "").strip() or uuid.uuid4().hex
    ts0 = int(_now_ms())
    _agent_outbox_append_jsonl(
        "chat.jsonl",
        {"id": uuid.uuid4().hex, "trace_id": tid, "ts": ts0, "type": "tool.plan", "channel": "skills", "tool_plan": _json_sanitize(tool_plan)},
    )
    results = _agent_skill_execute_plan(tid, tool_plan)
    _agent_outbox_append_jsonl(
        "chat.jsonl",
        {"id": uuid.uuid4().hex, "trace_id": tid, "ts": int(_now_ms()), "type": "tool.plan.done", "channel": "skills", "results": results, "duration_ms": int(_now_ms()) - ts0},
    )


@app.route("/agent/skills/execute", methods=["POST"])
def agent_skills_execute():
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    tool_plan = data.get("tool_plan") if isinstance(data.get("tool_plan"), list) else (data.get("steps") if isinstance(data.get("steps"), list) else [])
    tool_plan = [x for x in tool_plan if isinstance(x, dict)]

    def _tool_plan_is_readonly(tp: List[Dict[str, Any]]) -> bool:
        for st in (tp or []):
            tool = str(st.get("tool") or "").strip()
            if not tool:
                continue
            meta = _AGENT_SKILLS_REGISTRY.get(tool)
            cat = str((meta or {}).get("category") or "")
            if cat not in ("read", "audit"):
                return False
        return True

    if not _agent_sandbox_task_auth_ok():
        if not (_agent_read_auth_ok() and _tool_plan_is_readonly(tool_plan)):
            return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    try:
        async_run = bool(data.get("async", True))
    except Exception:
        async_run = True

    if async_run:
        t = threading.Thread(target=_agent_skills_execute_process, args=(trace_id, tool_plan), daemon=True)
        t.start()
        return jsonify({"ok": True, "queued": True, "trace_id": trace_id, "ts": int(_now_ms())})

    tid = str(trace_id or "").strip() or uuid.uuid4().hex
    ts0 = int(_now_ms())
    _agent_outbox_append_jsonl(
        "chat.jsonl",
        {"id": uuid.uuid4().hex, "trace_id": tid, "ts": ts0, "type": "tool.plan", "channel": "skills", "tool_plan": _json_sanitize(tool_plan)},
    )
    results = _agent_skill_execute_plan(tid, tool_plan)
    _agent_outbox_append_jsonl(
        "chat.jsonl",
        {"id": uuid.uuid4().hex, "trace_id": tid, "ts": int(_now_ms()), "type": "tool.plan.done", "channel": "skills", "results": results, "duration_ms": int(_now_ms()) - ts0},
    )
    return jsonify({"ok": True, "queued": False, "trace_id": tid, "ts": int(_now_ms()), "results": results, "duration_ms": int(_now_ms()) - ts0})


def _agent_workflow_sys_monitor_bugfix_process(trace_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    tid = str(trace_id or "").strip() or uuid.uuid4().hex
    ts0 = int(_now_ms())
    _agent_outbox_append_jsonl(
        "chat.jsonl",
        {"id": uuid.uuid4().hex, "trace_id": tid, "ts": ts0, "type": "workflow.sys_monitor_bugfix", "channel": "workflow", "status": "running", "input": _json_sanitize(payload)},
    )

    try:
        try:
            lookback_days = float(payload.get("lookback_days") or 7.0)
        except Exception:
            lookback_days = 7.0
        lookback_days = float(max(0.1, min(3650.0, lookback_days)))

        try:
            signals_limit = int(payload.get("signals_limit") or 80)
        except Exception:
            signals_limit = 80
        signals_limit = max(1, min(200, int(signals_limit)))

        try:
            signals_per_pair = int(payload.get("signals_per_pair") or 2)
        except Exception:
            signals_per_pair = 2
        signals_per_pair = max(0, min(50, int(signals_per_pair)))

        include_alerts = bool(payload.get("include_alerts", True))
        include_tracker = bool(payload.get("include_tracker", True))
        include_signals = bool(payload.get("include_signals", True))

        report: Dict[str, Any] = {"ok": True, "ts": int(_now_ms()), "trace_id": tid}
        try:
            report["health"] = _skill_health_get({})
        except Exception as e:
            report["health"] = {"ok": False, "error": str(e), "ts": int(_now_ms())}
        try:
            report["metrics"] = _skill_metrics_recent({})
        except Exception as e:
            report["metrics"] = {"ok": False, "error": str(e), "ts": int(_now_ms())}
        if include_tracker:
            try:
                report["tracker"] = _skill_tracker_stats({"view": "summary"})
            except Exception as e:
                report["tracker"] = {"ok": False, "error": str(e), "ts": int(_now_ms())}
        if include_signals:
            try:
                report["signals"] = _skill_signals_recent({"limit": int(signals_limit), "diverse": True, "per_pair": int(signals_per_pair)})
            except Exception as e:
                report["signals"] = {"ok": False, "error": str(e), "ts": int(_now_ms())}
        if include_alerts:
            try:
                report["alerts"] = _skill_audit_alerts_evaluate({"lookback_days": float(lookback_days)})
            except Exception as e:
                report["alerts"] = {"ok": False, "error": str(e), "ts": int(_now_ms())}

        out = {"ok": True, "ts": int(_now_ms()), "trace_id": tid, "report": report}
        _agent_outbox_append_jsonl(
            "chat.jsonl",
            {
                "id": uuid.uuid4().hex,
                "trace_id": tid,
                "ts": int(_now_ms()),
                "type": "workflow.sys_monitor_bugfix.done",
                "channel": "workflow",
                "status": "ok",
                "result": _json_sanitize(out),
                "duration_ms": int(_now_ms()) - ts0,
            },
        )
        return out
    except Exception as e:
        out = {"ok": False, "ts": int(_now_ms()), "trace_id": tid, "error": str(e)}
        try:
            _agent_outbox_append_jsonl(
                "chat.jsonl",
                {
                    "id": uuid.uuid4().hex,
                    "trace_id": tid,
                    "ts": int(_now_ms()),
                    "type": "workflow.sys_monitor_bugfix.done",
                    "channel": "workflow",
                    "status": "failed",
                    "result": _json_sanitize(out),
                    "duration_ms": int(_now_ms()) - ts0,
                },
            )
        except Exception:
            pass
        return out


@app.route("/agent/workflows/sys_monitor_bugfix", methods=["POST"])
def agent_workflow_sys_monitor_bugfix():
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    try:
        async_run = bool(data.get("async", True))
    except Exception:
        async_run = True
    if async_run:
        t = threading.Thread(target=_agent_workflow_sys_monitor_bugfix_process, args=(trace_id, (data if isinstance(data, dict) else {})), daemon=True)
        t.start()
        return jsonify({"ok": True, "queued": True, "trace_id": trace_id, "ts": int(_now_ms())})
    res = _agent_workflow_sys_monitor_bugfix_process(trace_id, (data if isinstance(data, dict) else {}))
    return jsonify(res)


def _agent_outbox_append_jsonl(name: str, item: Dict[str, Any]) -> None:
    nm = str(name or "").strip()
    if (not nm) or ("/" in nm) or ("\\" in nm) or (".." in nm):
        return
    try:
        if _governance_is_test_mode() and (not bool(CONFIG.get("outbox_allow_test_mode", False))):
            return
    except Exception:
        pass
    out = _agent_outbox_dir() / nm
    try:
        _agent_outbox_rollover_one(out, now_ms=int(_now_ms()))
        s = json.dumps(item, ensure_ascii=False)
        try:
            max_line_bytes = int(CONFIG.get("outbox_max_line_bytes", 250_000) or 250_000)
        except Exception:
            max_line_bytes = 250_000
        max_line_bytes = max(10_000, min(5_000_000, int(max_line_bytes)))
        is_payload_stream = nm.lower().endswith("_payload.jsonl") or nm.lower().endswith("_payloads.jsonl")
        if (not is_payload_stream) and nm.lower() in ("chat.jsonl", "events.jsonl"):
            try:
                nbytes = int(len(s.encode("utf-8")))
            except Exception:
                nbytes = int(len(s))
            if nbytes > int(max_line_bytes):
                ts_ms = int(_now_ms())
                trace_id = str(item.get("trace_id") or "").strip() or None
                base_id = str(item.get("id") or "").strip() or uuid.uuid4().hex
                sha = hashlib.sha256(s.encode("utf-8")).hexdigest()
                payload_id = hashlib.sha256(f"{nm}|{base_id}|{sha}|{ts_ms}".encode("utf-8")).hexdigest()[:32]
                payload_name = f"{nm[:-5]}_payload.jsonl"
                payload_item = {
                    "id": payload_id,
                    "trace_id": trace_id or payload_id,
                    "ts": ts_ms,
                    "type": "outbox.payload",
                    "source": nm,
                    "bytes": int(nbytes),
                    "sha256": sha,
                    "item": item,
                }
                try:
                    _agent_outbox_append_jsonl(payload_name, payload_item)
                except Exception:
                    pass
                compact_item = _agent_outbox_compact_item(item)
                if isinstance(compact_item, dict):
                    compact_item["payload_ref"] = {"file": payload_name, "id": payload_id, "sha256": sha, "bytes": int(nbytes)}
                    s = json.dumps(compact_item, ensure_ascii=False)
        with open(out, "a", encoding="utf-8") as f:
            f.write(s + "\n")
    except Exception:
        pass


def _audit_base_payload(scope: str, action: str, *, trace_id: Optional[str] = None, extra: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    now_ms = int(_now_ms())
    try:
        actor = str(request.headers.get("X-Actor") or "").strip() or None
    except Exception:
        actor = None
    try:
        source = str(request.headers.get("X-Source") or "").strip() or None
    except Exception:
        source = None
    try:
        ip = str(request.remote_addr or "").strip() or None
    except Exception:
        ip = None
    try:
        ua = str(request.headers.get("User-Agent") or "").strip() or None
    except Exception:
        ua = None
    try:
        path = str(request.path or "").strip() or None
    except Exception:
        path = None
    try:
        method = str(request.method or "").strip().upper() or None
    except Exception:
        method = None
    tid = (None if trace_id is None else str(trace_id).strip() or None)
    if tid is None:
        try:
            tid = str(request.headers.get("X-Trace-Id") or "").strip() or None
        except Exception:
            tid = None
    if tid is None:
        tid = uuid.uuid4().hex
    payload: Dict[str, Any] = {
        "trace_id": tid,
        "ts": now_ms,
        "actor": actor,
        "source": source,
        "scope": str(scope or "").strip() or "unknown",
        "action": str(action or "").strip() or "unknown",
        "ip": ip,
        "ua": ua,
        "path": path,
        "method": method,
    }
    if isinstance(extra, dict) and extra:
        payload["extra"] = extra
    return payload


def _audit_emit_action(name: str, payload: Dict[str, Any]) -> None:
    nm = str(name or "").strip() or "audit"
    now_ms = int(_now_ms())
    pl = payload if isinstance(payload, dict) else {"trace_id": uuid.uuid4().hex}
    _agent_outbox_append_jsonl("audit_actions.jsonl", {"name": nm, "ts": now_ms, "payload": pl})


def _agent_trace_outbox_timeline(trace_id: str, *, max_items: int = 400) -> List[Dict[str, Any]]:
    tid = str(trace_id or "").strip()
    if not tid:
        return []
    try:
        tail_bytes = int(CONFIG.get("outbox_trace_tail_bytes", 2000000) or 2000000)
    except Exception:
        tail_bytes = 2000000
    files = [
        "chat.jsonl",
        "events.jsonl",
        "rca.jsonl",
        "trade_monitor_reports.jsonl",
        "sandbox_queue.jsonl",
        "changeset_drafts.jsonl",
        "approvals.jsonl",
        "audit_actions.jsonl",
        "twitter.jsonl",
        "twitter_queue.jsonl",
        "delivery_receipts.jsonl",
    ]
    out: List[Dict[str, Any]] = []
    for nm in files:
        p = _agent_outbox_dir() / nm
        if not p.exists():
            continue
        try:
            rows = _agent_jsonl_tail(p, tail_bytes=tail_bytes, max_lines=20000)
        except Exception:
            rows = []
        for obj in rows:
            if not isinstance(obj, dict):
                continue
            if str(obj.get("trace_id") or "").strip() != tid:
                continue
            ts = obj.get("ts")
            try:
                ts_i = int(ts or 0)
            except Exception:
                ts_i = 0
            t0 = obj.get("type")
            if t0 is None:
                t0 = obj.get("event")
            if t0 is None:
                t0 = obj.get("name")
            kind = str(t0 or "record")
            out.append({"ts": ts_i, "file": nm, "kind": kind, "item": obj})
    out.sort(key=lambda x: int(x.get("ts") or 0))
    if len(out) > int(max_items):
        out = out[-int(max_items):]
    return out


def _agent_trace_chain(trace_id: str, *, max_orders: int = 50) -> Dict[str, Any]:
    tid = str(trace_id or "").strip()
    if not tid:
        return {"ok": False, "error": "missing_trace_id"}

    evt = EVENTS.get(tid) if isinstance(EVENTS, dict) else None
    if isinstance(evt, dict):
        evt = dict(evt)
    else:
        evt = None

    if evt is None:
        try:
            tail_bytes = int(CONFIG.get("events_archive_tail_bytes", 2000000) or 2000000)
        except Exception:
            tail_bytes = 2000000
        try:
            arch_events = _load_recent_jsonl_records("events", limit=20000, max_files=30, tail_bytes=tail_bytes)
        except Exception:
            arch_events = []
        for e in arch_events:
            if not isinstance(e, dict):
                continue
            try:
                eid = str(e.get("id") or e.get("event_id") or "").strip()
            except Exception:
                eid = ""
            if eid == tid:
                evt = dict(e)
                break

    orders: List[Dict[str, Any]] = []
    try:
        for o in (ORDERS or {}).values():
            if not isinstance(o, dict):
                continue
            eid0 = o.get("base_event_id") if o.get("base_event_id") is not None else o.get("event_id")
            if eid0 is None:
                continue
            if str(eid0).strip() != tid:
                continue
            orders.append(dict(o))
    except Exception:
        orders = []

    if not orders:
        try:
            tail_bytes = int(CONFIG.get("events_archive_tail_bytes", 2000000) or 2000000)
        except Exception:
            tail_bytes = 2000000
        try:
            arch_orders = _load_recent_jsonl_records("orders", limit=max(2000, int(max_orders) * 200), max_files=30, tail_bytes=tail_bytes)
        except Exception:
            arch_orders = []
        for o in arch_orders:
            if not isinstance(o, dict):
                continue
            eid0 = o.get("base_event_id") if o.get("base_event_id") is not None else o.get("event_id")
            if eid0 is None:
                continue
            if str(eid0).strip() != tid:
                continue
            orders.append(dict(o))
    orders.sort(key=lambda x: int(x.get("ts") or 0))
    if len(orders) > int(max_orders):
        orders = orders[-int(max_orders):]

    settlements: List[Dict[str, Any]] = []
    try:
        for r in (_ab_settlements_get() or []):
            if not isinstance(r, dict):
                continue
            if str(r.get("event_id") or "").strip() == tid:
                settlements.append(dict(r))
    except Exception:
        settlements = []
    settlements.sort(key=lambda x: int(x.get("ts") or 0))

    outbox_timeline = _agent_trace_outbox_timeline(tid, max_items=500)

    if (evt is None) and (not orders) and (not settlements) and (not outbox_timeline):
        return {"ok": False, "error": "trace_not_found", "trace_id": tid, "ts": int(_now_ms())}

    out = {
        "ok": True,
        "trace_id": tid,
        "ts": int(_now_ms()),
        "event": evt,
        "orders": orders,
        "settlements": settlements,
        "outbox": outbox_timeline,
    }
    try:
        if evt is not None and isinstance(evt, dict):
            out["pair"] = evt.get("pair")
            out["side"] = evt.get("side")
            out["tag"] = evt.get("tag")
    except Exception:
        pass
    return out


def _agent_audit_replay(trace_id: str, *, limit: int = 3000) -> Dict[str, Any]:
    tid = str(trace_id or "").strip()
    if not tid:
        return {"ok": False, "error": "missing_trace_id"}
    p = _agent_outbox_dir() / "audit_actions.jsonl"
    if not p.exists():
        return {"ok": True, "trace_id": tid, "items": [], "count": 0, "ts": int(_now_ms())}
    items = []
    try:
        with open(p, "r", encoding="utf-8") as f:
            for line in f:
                if len(items) >= int(limit):
                    break
                s = line.strip("\n")
                if not s.strip():
                    continue
                try:
                    obj = json.loads(s)
                except Exception:
                    continue
                if not isinstance(obj, dict):
                    continue
                payload = obj.get("payload") if isinstance(obj.get("payload"), dict) else {}
                t0 = str(payload.get("trace_id") or "").strip()
                if t0 != tid:
                    continue
                items.append(obj)
    except Exception as e:
        return {"ok": False, "error": str(e) or "read_failed", "trace_id": tid, "ts": int(_now_ms())}
    return {"ok": True, "trace_id": tid, "items": items, "count": int(len(items)), "ts": int(_now_ms())}


def _agent_loss_reason_scores_tradfi_v1(
    *,
    trigger_event: Optional[str],
    event: Optional[Dict[str, Any]],
    orders: List[Dict[str, Any]],
    settlements: List[Dict[str, Any]],
    error_norm: Dict[str, Any],
) -> Dict[str, Any]:
    trig = str(trigger_event or "").strip()
    pair = (event.get("pair") if isinstance(event, dict) else None)
    try:
        pair_s = (None if pair is None else str(pair).strip())
    except Exception:
        pair_s = None

    loss_items: List[Dict[str, Any]] = []
    notional_sum = 0.0
    fee_abs_sum = 0.0
    pnl_neg_sum = 0.0
    rets: List[float] = []
    durs: List[int] = []
    stop_hits = 0
    for r in settlements:
        if not isinstance(r, dict):
            continue
        try:
            pnl = float(r.get("pnl_usdc") or 0.0)
        except Exception:
            pnl = 0.0
        try:
            notional = float(r.get("notional_usdc") or 0.0)
        except Exception:
            notional = 0.0
        try:
            fee = float(r.get("fee_abs") or 0.0)
        except Exception:
            fee = 0.0
        try:
            funding = float(r.get("funding_abs") or 0.0)
        except Exception:
            funding = 0.0
        rr = r.get("ret_ratio")
        try:
            ret = float(rr) if rr is not None else None
        except Exception:
            ret = None
        dur0 = r.get("duration_ms")
        try:
            dur = int(dur0) if dur0 is not None else None
        except Exception:
            dur = None
        if notional > 0.0:
            notional_sum += float(notional)
        fee_abs_sum += abs(float(fee)) + abs(float(funding))
        if pnl < 0.0:
            pnl_neg_sum += abs(float(pnl))
            loss_items.append(r)
            if ret is not None and math.isfinite(float(ret)):
                rets.append(float(ret))
            if dur is not None and int(dur) > 0:
                durs.append(int(dur))
            try:
                rs = str(r.get("reason") or "").strip().lower()
            except Exception:
                rs = ""
            if rs and (("stop" in rs) or ("stoploss" in rs) or ("sl" in rs)):
                stop_hits += 1

    owner_loss: Dict[str, float] = {}
    for r in loss_items:
        if not isinstance(r, dict):
            continue
        try:
            pnl = float(r.get("pnl_usdc") or 0.0)
        except Exception:
            pnl = 0.0
        if pnl >= 0.0:
            continue
        owner = str(r.get("owner") or "").strip() or "unknown"
        owner_loss[owner] = float(owner_loss.get(owner, 0.0)) + abs(float(pnl))
    tot_loss = float(sum(owner_loss.values()) or 0.0)
    top_owner = None
    top_share = 0.0
    if owner_loss and tot_loss > 0.0:
        top_owner = max(owner_loss.items(), key=lambda kv: float(kv[1]))[0]
        top_share = float(owner_loss.get(top_owner, 0.0)) / float(tot_loss)

    def _owner_group(owner: Optional[str]) -> str:
        o = str(owner or "").strip().lower()
        if ("quant" in o) or ("carry" in o):
            return "quant"
        if ("macro" in o) or ("overlay" in o):
            return "macro"
        return "strategy"

    groups = set([_owner_group(k) for k in owner_loss.keys() if str(k).strip()])
    top_group = _owner_group(top_owner)

    max_loss_abs = 0.0
    for r in loss_items:
        if not isinstance(r, dict):
            continue
        try:
            pnl = float(r.get("pnl_usdc") or 0.0)
        except Exception:
            pnl = 0.0
        max_loss_abs = max(float(max_loss_abs), abs(min(0.0, float(pnl))))
    top_loss_share = (float(max_loss_abs) / float(tot_loss)) if tot_loss > 0.0 else 0.0

    mean_ret = None
    std_ret = None
    min_ret = None
    if rets:
        try:
            mean_ret = float(sum(rets)) / float(len(rets))
        except Exception:
            mean_ret = None
        try:
            m = float(mean_ret) if mean_ret is not None else 0.0
            v = sum((float(x) - m) ** 2 for x in rets) / float(max(1, len(rets) - 1))
            std_ret = float(math.sqrt(max(0.0, v)))
        except Exception:
            std_ret = None
        try:
            min_ret = float(min(rets))
        except Exception:
            min_ret = None

    short_loss_n = 0
    for r in loss_items:
        if not isinstance(r, dict):
            continue
        rr = r.get("ret_ratio")
        try:
            ret = float(rr) if rr is not None else None
        except Exception:
            ret = None
        if ret is None or (not math.isfinite(float(ret))) or float(ret) >= 0.0:
            continue
        dur0 = r.get("duration_ms")
        try:
            dur = int(dur0) if dur0 is not None else None
        except Exception:
            dur = None
        if dur is not None and int(dur) > 0 and int(dur) <= 30 * 60 * 1000:
            short_loss_n += 1
    loss_n = int(len(loss_items))
    stop_ratio = float(stop_hits) / float(max(1, loss_n))
    short_ratio = float(short_loss_n) / float(max(1, loss_n))

    cost_rate = float(fee_abs_sum) / float(notional_sum) if float(notional_sum) > 0.0 else 0.0
    err_type = str((error_norm.get("type") if isinstance(error_norm, dict) else None) or "").strip().lower()
    err_code = (error_norm.get("code") if isinstance(error_norm, dict) else None)
    is_429 = False
    try:
        if err_code is not None and int(err_code) == 429:
            is_429 = True
    except Exception:
        try:
            is_429 = str(err_code).strip() == "429"
        except Exception:
            is_429 = False

    any_exec_fail = False
    for o in orders:
        if not isinstance(o, dict):
            continue
        st = str(o.get("status") or "").strip().lower()
        if st in ("rejected", "failed", "error"):
            any_exec_fail = True
            break

    any_gate_veto = False
    for o in orders:
        if not isinstance(o, dict):
            continue
        gate = o.get("gate") if isinstance(o.get("gate"), dict) else {}
        if gate and gate.get("ok") is False:
            any_gate_veto = True
            break

    regime = None
    try:
        di = (event.get("decision_info") if isinstance(event, dict) and isinstance(event.get("decision_info"), dict) else {})
        regime = di.get("regime")
    except Exception:
        regime = None
    try:
        regime_s = (None if regime is None else str(regime).strip().lower())
    except Exception:
        regime_s = None

    beta_score = 0.0
    if trig == "pnl.drawdown.trigger":
        beta_score = 0.85
    elif pair_s in ("BTC/USDT", "ETH/USDT"):
        beta_score = 0.60 if tot_loss > 0.0 else 0.0
    if regime_s and any(x in regime_s for x in ("risk", "bear", "crash", "panic", "drawdown")):
        beta_score = min(1.0, float(beta_score) + 0.15)

    vol_score = 0.0
    if stop_ratio >= 0.60:
        vol_score = 0.85
    elif short_ratio >= 0.50:
        vol_score = 0.70
    else:
        if std_ret is not None and mean_ret is not None and float(mean_ret) < 0.0 and float(std_ret) >= 0.03:
            vol_score = 0.60
    vol_score = min(1.0, max(float(vol_score), 0.50 * float(stop_ratio) + 0.35 * float(short_ratio)))

    liq_score = 0.0
    if is_429:
        liq_score = 0.95
    elif err_type in ("http", "execution"):
        liq_score = 0.75
    if any_exec_fail:
        liq_score = min(1.0, float(liq_score) + 0.15)
    if float(cost_rate) >= 0.0025:
        liq_score = min(1.0, float(liq_score) + 0.20)
    elif float(cost_rate) >= 0.0015:
        liq_score = min(1.0, float(liq_score) + 0.10)

    tail_score = 0.0
    if float(top_loss_share) >= 0.65 and tot_loss > 0.0:
        tail_score = 0.85
    elif float(top_loss_share) >= 0.55 and tot_loss > 0.0:
        tail_score = 0.70
    if min_ret is not None and float(min_ret) <= -0.08:
        tail_score = min(1.0, float(tail_score) + 0.15)
    if any_gate_veto:
        tail_score = min(1.0, float(tail_score) + 0.05)

    corr_score = 0.0
    if trig == "pnl.drawdown.trigger" and len(groups) >= 2:
        corr_score = 0.85
    elif len(groups) >= 2 and float(top_share) <= 0.55:
        corr_score = 0.75
    elif len(groups) >= 2 and float(top_share) <= 0.70:
        corr_score = 0.60
    if loss_n >= 4 and len(owner_loss) >= 3:
        corr_score = min(1.0, float(corr_score) + 0.10)

    if any_gate_veto:
        beta_score = min(1.0, float(beta_score) + 0.05)
        corr_score = min(1.0, float(corr_score) + 0.05)

    def _score_obj(score: float, evidence: Dict[str, Any]) -> Dict[str, Any]:
        return {"score": float(max(0.0, min(1.0, float(score)))), "evidence": evidence}

    out = {
        "schema_version": "tradfi_v1",
        "ts": int(_now_ms()),
        "trigger_event": (None if not trig else trig),
        "meta": {
            "pair": pair_s,
            "loss_n": int(loss_n),
            "total_loss_abs": float(tot_loss),
            "top_loss_share": float(top_loss_share),
            "top_owner": top_owner,
            "top_owner_share": float(top_share),
            "groups": sorted(list(groups)),
            "top_group": str(top_group),
            "cost_rate": float(cost_rate),
            "mean_ret": mean_ret,
            "std_ret": std_ret,
            "min_ret": min_ret,
            "stop_ratio": float(stop_ratio),
            "short_loss_ratio": float(short_ratio),
            "error_type": (None if not err_type else err_type),
            "error_code": err_code,
            "gate_veto": bool(any_gate_veto),
            "exec_fail": bool(any_exec_fail),
            "regime": (None if not regime_s else regime_s),
        },
        "scores": {
            "beta_exposure": _score_obj(beta_score, {"trigger_event": trig, "pair": pair_s, "regime": regime_s, "gate_veto": bool(any_gate_veto)}),
            "vol_mismatch": _score_obj(vol_score, {"stop_ratio": float(stop_ratio), "short_loss_ratio": float(short_ratio), "mean_ret": mean_ret, "std_ret": std_ret}),
            "liquidity_shock": _score_obj(liq_score, {"error_type": err_type, "error_code": err_code, "exec_fail": bool(any_exec_fail), "cost_rate": float(cost_rate)}),
            "tail_risk": _score_obj(tail_score, {"top_loss_share": float(top_loss_share), "min_ret": min_ret, "gate_veto": bool(any_gate_veto)}),
            "correlation_rise": _score_obj(corr_score, {"groups": sorted(list(groups)), "top_owner_share": float(top_share), "loss_n": int(loss_n), "owner_n": int(len(owner_loss))}),
        },
    }
    return out


def _agent_rca_report_from_chain(chain: Dict[str, Any], *, include_dq: bool = False, include_eq: bool = False) -> Dict[str, Any]:
    tid = str(chain.get("trace_id") or "").strip()
    evt = chain.get("event") if isinstance(chain.get("event"), dict) else None
    orders = chain.get("orders") if isinstance(chain.get("orders"), list) else []
    settlements = chain.get("settlements") if isinstance(chain.get("settlements"), list) else []

    pair = None
    side = None
    tag = None
    ts_evt = None
    try:
        if isinstance(evt, dict):
            pair = evt.get("pair")
            side = evt.get("side")
            tag = evt.get("tag")
            ts_evt = evt.get("ts_emit_ms") if evt.get("ts_emit_ms") is not None else evt.get("ingested_ms")
            if ts_evt is None:
                ts_evt = evt.get("ts")
    except Exception:
        pass

    def _error_normalize() -> Dict[str, Any]:
        venue = None
        try:
            venue = str(CONFIG.get("execution_venue") or "").strip() or None
        except Exception:
            venue = None
        if isinstance(evt, dict):
            try:
                venue = str(evt.get("venue") or venue or "").strip() or venue
            except Exception:
                pass

        ts_ms = None
        try:
            if ts_evt is not None:
                ts_i = int(ts_evt)
                if ts_i > 0 and ts_i < 10_000_000_000:
                    ts_i = ts_i * 1000
                ts_ms = ts_i
        except Exception:
            ts_ms = None
        time_window = None
        if ts_ms is not None and int(ts_ms) > 0:
            time_window = {"start_ms": int(ts_ms) - 30 * 60 * 1000, "end_ms": int(ts_ms) + 30 * 60 * 1000}

        err_text = ""
        http_code = None
        component = None
        for o in orders:
            if not isinstance(o, dict):
                continue
            st = str(o.get("status") or "").strip().lower()
            if st not in ("rejected", "failed", "error"):
                continue
            try:
                err_text = str(o.get("error") or o.get("exec_error") or o.get("reason") or "").strip()
            except Exception:
                err_text = ""
            try:
                if o.get("http_status") is not None:
                    http_code = int(o.get("http_status"))
            except Exception:
                http_code = None
            if err_text:
                break

        if not component:
            for o in orders:
                if not isinstance(o, dict):
                    continue
                gate = o.get("gate") if isinstance(o.get("gate"), dict) else {}
                if gate and gate.get("ok") is False:
                    component = "risk"
                    if not err_text:
                        try:
                            err_text = str(gate.get("block_reasons") or gate.get("reason") or "").strip()
                        except Exception:
                            err_text = ""
                    break

        if not component:
            if http_code is not None:
                component = "http"
            elif err_text:
                component = "execution"

        error_type = "unknown"
        if component == "risk":
            error_type = "risk"
        elif component == "http":
            error_type = "http"
        elif component == "execution":
            error_type = "execution"
        elif component:
            error_type = component

        code = None
        if http_code is not None:
            code = http_code
        elif err_text:
            code = "text"

        return {
            "type": error_type,
            "venue": venue,
            "code": code,
            "component": component,
            "time_window": time_window,
            "message": (err_text[:360] if isinstance(err_text, str) else ""),
        }

    pnl_usdc = 0.0
    pnl_n = 0
    for r in settlements:
        if not isinstance(r, dict):
            continue
        try:
            p = float(r.get("pnl_usdc") or 0.0)
        except Exception:
            p = 0.0
        pnl_usdc += float(p)
        pnl_n += 1

    loss = pnl_usdc < 0.0

    causes: List[Dict[str, Any]] = []
    evidence: List[Dict[str, Any]] = []
    recs: List[str] = []

    def _ev(name: str, detail: Any) -> None:
        evidence.append({"name": str(name), "detail": detail, "trace_id": tid})

    error_norm = _error_normalize()
    _ev("error_norm", error_norm)

    def _is_rate_limit_429(en: Any) -> bool:
        if not isinstance(en, dict):
            return False
        try:
            code0 = en.get("code")
            if code0 is not None:
                if str(code0).strip() == "429":
                    return True
                try:
                    if int(code0) == 429:
                        return True
                except Exception:
                    pass
        except Exception:
            pass
        try:
            msg = str(en.get("message") or "")
        except Exception:
            msg = ""
        m = msg.lower()
        return ("429" in msg) or ("too many requests" in m) or ("cloudfront" in m)

    if evt is not None:
        _ev("event", {k: evt.get(k) for k in ["pair", "side", "tag", "ts", "ts_emit_ms", "ingested_ms", "timeframe", "action", "strategy_id", "strategy_version", "group_id", "feature_set_id"] if k in evt})
        try:
            di = evt.get("decision_info") if isinstance(evt.get("decision_info"), dict) else {}
            if di:
                _ev("decision_info", {k: di.get(k) for k in ["decision", "reason", "p", "pc", "threshold", "regime"] if k in di})
        except Exception:
            pass

    if orders:
        o0 = orders[0] if isinstance(orders[0], dict) else None
        ol = orders[-1] if isinstance(orders[-1], dict) else None
        if isinstance(o0, dict):
            _ev("first_order", {k: o0.get(k) for k in ["id", "ts", "pair", "side", "action", "mode", "status", "tag", "p", "pc", "regime", "model", "event_id", "base_event_id"] if k in o0})
        if isinstance(ol, dict) and ol is not o0:
            _ev("last_order", {k: ol.get(k) for k in ["id", "ts", "pair", "side", "action", "mode", "status", "tag", "p", "pc", "regime", "model", "event_id", "base_event_id"] if k in ol})

    if settlements:
        _ev("settlements", [
            {k: r.get(k) for k in ["ts", "owner", "pnl_usdc", "notional_usdc", "ret_ratio", "duration_ms", "fee_abs", "funding_abs", "order_id", "event_id", "reason"] if k in r}
            for r in settlements if isinstance(r, dict)
        ])

    if loss:
        exec_fail = False
        for o in orders:
            if not isinstance(o, dict):
                continue
            st = str(o.get("status") or "").strip().lower()
            if st in ("rejected", "failed", "error"):
                exec_fail = True
                break
        if exec_fail:
            causes.append({"code": "execution_failure", "weight": 0.7, "summary": "执行侧出现失败/拒绝状态"})
            recs.append("检查执行 API 与交易所连接，优先排查失败订单的 error/exec 字段")

        gate_veto = False
        for o in orders:
            if not isinstance(o, dict):
                continue
            gate = o.get("gate") if isinstance(o.get("gate"), dict) else {}
            if gate and gate.get("ok") is False:
                gate_veto = True
                break
        if gate_veto:
            causes.append({"code": "gate_veto", "weight": 0.6, "summary": "门禁/风控拒绝或异常"})
            recs.append("检查 gate_history 与 gate 配置，确认门禁是否应 fail-open/收紧")

        exit_reason = None
        for r in settlements:
            if not isinstance(r, dict):
                continue
            if r.get("reason") is not None:
                exit_reason = str(r.get("reason") or "").strip()
                if exit_reason:
                    break
        if exit_reason:
            causes.append({"code": "exit_trigger", "weight": 0.4, "summary": f"出场原因: {exit_reason}"})

        if isinstance(evt, dict) and isinstance(evt.get("arena"), dict):
            try:
                arena = evt.get("arena")
                chosen = arena.get("chosen")
                explore = arena.get("explore")
                if chosen is not None:
                    causes.append({"code": "arena_choice", "weight": 0.3, "summary": f"Arena 选择: {str(chosen)}{'(explore)' if bool(explore) else ''}"})
            except Exception:
                pass

        if not causes:
            causes.append({"code": "unknown", "weight": 0.2, "summary": "缺少足够链路信息，建议补齐 trace->订单->结算字段"})
            recs.append("确认事件/订单归档开启，并确保 event_id/base_event_id 与 trace_id 一致")
    else:
        causes.append({"code": "not_a_loss", "weight": 1.0, "summary": "未识别到亏损结算记录"})

    if _is_rate_limit_429(error_norm):
        causes.append({"code": "rate_limited_429", "weight": 0.9, "summary": "HTTP 429 触发限流/节流（可能来自 CloudFront）"})
        recs.append("优先检查同步触发频率、并发同步与重试风暴；确认退避窗口内不会继续触发同步")

    dq = None
    eq = None
    if include_dq and pair and ts_evt is not None:
        try:
            ts_i = int(ts_evt)
            if ts_i > 0 and ts_i < 10_000_000_000:
                ts_i = ts_i * 1000
            dq = _audit_data_quality(pair=str(pair), start_ts_ms=int(ts_i - 6 * 3600 * 1000), end_ts_ms=int(ts_i + 6 * 3600 * 1000), max_points=1500, ret_abs_thr=0.10)
        except Exception as e:
            dq = {"ok": False, "error": str(e)}
    if include_eq and pair and ts_evt is not None:
        try:
            ts_i = int(ts_evt)
            if ts_i > 0 and ts_i < 10_000_000_000:
                ts_i = ts_i * 1000
            eq = _audit_execution_quality(start_ts_ms=int(ts_i - 6 * 3600 * 1000), end_ts_ms=int(ts_i + 6 * 3600 * 1000), pair=str(pair), max_points=1500, include_shadow=True)
        except Exception as e:
            eq = {"ok": False, "error": str(e)}

    summary = {
        "pair": pair,
        "side": side,
        "tag": tag,
        "loss": bool(loss),
        "pnl_usdc": float(pnl_usdc),
        "settlements_n": int(pnl_n),
    }
    if dq is not None:
        summary["dq"] = dq
    if eq is not None:
        summary["eq"] = eq

    timeline: List[Dict[str, Any]] = []
    if isinstance(evt, dict):
        timeline.append({"ts": int(evt.get("ts_emit_ms") or evt.get("ingested_ms") or evt.get("ts") or 0), "type": "event", "id": tid, "pair": evt.get("pair"), "side": evt.get("side"), "tag": evt.get("tag"), "action": evt.get("action")})
    for o in orders:
        if not isinstance(o, dict):
            continue
        timeline.append({"ts": int(o.get("ts") or 0), "type": "order", "id": o.get("id"), "pair": o.get("pair"), "side": o.get("side"), "action": o.get("action"), "status": o.get("status"), "mode": o.get("mode")})
    for r in settlements:
        if not isinstance(r, dict):
            continue
        timeline.append({"ts": int(r.get("ts") or 0), "type": "settlement", "owner": r.get("owner"), "pnl_usdc": r.get("pnl_usdc"), "reason": r.get("reason"), "order_id": r.get("order_id")})
    timeline = [x for x in timeline if int(x.get("ts") or 0) > 0]
    timeline.sort(key=lambda x: int(x.get("ts") or 0))

    troubleshooting = None
    if _is_rate_limit_429(error_norm):
        now_ms = int(_now_ms())
        hl_state = TRACKER_STATE.get("hl") if isinstance(TRACKER_STATE.get("hl"), dict) else {}
        aster_state = TRACKER_STATE.get("aster") if isinstance(TRACKER_STATE.get("aster"), dict) else {}

        def _hist_stats(st: Dict[str, Any]) -> Dict[str, Any]:
            hist = st.get("sync_trigger_history")
            if not isinstance(hist, list) or not hist:
                return {"count_5m": 0, "count_30m": 0, "recent": []}
            recent: List[Dict[str, Any]] = []
            for x in hist[-20:]:
                if not isinstance(x, dict):
                    continue
                recent.append({
                    "ts": x.get("ts"),
                    "trigger": x.get("trigger"),
                    "trace_id": x.get("trace_id"),
                    "ok": x.get("ok"),
                    "skipped": x.get("skipped"),
                    "error": _tracker_compact_sync_err(x.get("error")),
                    "until": x.get("until"),
                })
            c5 = 0
            c30 = 0
            for x in hist:
                if not isinstance(x, dict):
                    continue
                try:
                    ts = int(x.get("ts") or 0)
                except Exception:
                    ts = 0
                if ts <= 0:
                    continue
                if (now_ms - ts) <= 5 * 60 * 1000:
                    c5 += 1
                if (now_ms - ts) <= 30 * 60 * 1000:
                    c30 += 1
            return {"count_5m": int(c5), "count_30m": int(c30), "recent": recent}

        hl_tr = _hist_stats(hl_state)
        try:
            until_ts = int(hl_state.get("rate_limit_until_ts") or 0)
        except Exception:
            until_ts = 0
        try:
            backoff_ms = int(hl_state.get("rate_limit_backoff_ms") or 0)
        except Exception:
            backoff_ms = 0

        cfg_ev = {
            "execution_venue": (CONFIG.get("execution_venue") if isinstance(CONFIG, dict) else None),
            "tracker_autosync_hl_enabled": (CONFIG.get("tracker_autosync_hl_enabled") if isinstance(CONFIG, dict) else None),
            "tracker_autosync_hl_min_interval_sec": (CONFIG.get("tracker_autosync_hl_min_interval_sec") if isinstance(CONFIG, dict) else None),
            "tracker_autoretry_hl_on_fail_min_interval_sec": (CONFIG.get("tracker_autoretry_hl_on_fail_min_interval_sec") if isinstance(CONFIG, dict) else None),
            "live_trading_enabled": (CONFIG.get("live_trading_enabled") if isinstance(CONFIG, dict) else None),
            "dry_run": (CONFIG.get("dry_run") if isinstance(CONFIG, dict) else None),
        }

        hypotheses: List[Dict[str, Any]] = [
            {
                "id": "H1",
                "title": "同步触发频率过高",
                "statement": "tracker/scheduler/策略层触发过密，导致 HL 侧限流返回 429。",
                "signals": ["5m 触发次数偏高", "min_interval 过小", "退避窗口内仍持续触发"],
            },
            {
                "id": "H2",
                "title": "并发同步/重复同步",
                "statement": "多个线程/实例同时发起同步，触发请求风暴。",
                "signals": ["相同时间戳附近多次触发", "不同 trigger 混杂", "同步耗时拉长"],
            },
            {
                "id": "H3",
                "title": "失败重试风暴",
                "statement": "失败后自动重试间隔过短，叠加指数退避前的多次尝试。",
                "signals": ["autotry 连续出现", "sync_ok=false 连续", "backoff 递增"],
            },
            {
                "id": "H4",
                "title": "上游/边缘节点异常",
                "statement": "CloudFront/上游节点短期异常导致 429 增多，与本地触发无强相关。",
                "signals": ["触发次数不高但仍 429", "跨策略/跨操作均 429", "持续时间短且自行恢复"],
            },
        ]

        validations: List[Dict[str, Any]] = [
            {
                "id": "R0",
                "title": "快速确认是否处于退避窗口",
                "steps": [
                    {"tool": "tracker.stats", "input": {"view": "summary"}},
                    {"tool": "tracker.sync.recent", "input": {"venue": "hl", "limit": 30}},
                ],
                "expected": ["rate_limit_until_ts>now 时应暂停同步", "backoff_ms 随 429 递增"],
            },
            {
                "id": "R1",
                "title": "检查触发频率与并发迹象",
                "steps": [
                    {"tool": "config.get", "input": {"keys": ["tracker_autosync_hl_min_interval_sec", "tracker_autoretry_hl_on_fail_min_interval_sec", "tracker_autosync_hl_enabled", "execution_venue"]}},
                    {"tool": "tracker.stats", "input": {"view": "summary"}},
                ],
                "expected": ["5m/30m 触发次数与阈值匹配", "同一秒内多触发提示并发/重复"],
            },
            {
                "id": "R2",
                "title": "回放链路确认 429 的来源与范围",
                "steps": [
                    {"tool": "agent.trace.replay", "input": {"trace_id": tid, "max_orders": 120}},
                ],
                "expected": ["订单/执行错误包含 429/CloudFront 线索", "确认是否仅 HL 同步受影响"],
            },
        ]

        actions_short: List[Dict[str, Any]] = [
            {
                "id": "S1",
                "title": "在退避窗口内禁止继续同步",
                "requires_approval": False,
                "how": {"tool": "tracker.stats", "input": {"sync": 0, "view": "summary"}},
            },
            {
                "id": "S2",
                "title": "临时降低同步触发频率",
                "requires_approval": True,
                "how": {"api": "/config/set", "payload": {"tracker_autosync_hl_min_interval_sec": 45}},
                "rollback": "config_set 自动创建 rollback_point（L2 变更）",
            },
            {
                "id": "S3",
                "title": "必要时临时关闭 HL autosync",
                "requires_approval": True,
                "how": {"api": "/config/set", "payload": {"tracker_autosync_hl_enabled": False}},
                "rollback": "config_set 自动创建 rollback_point（L2 变更）",
            },
        ]
        actions_long: List[Dict[str, Any]] = [
            {
                "id": "L1",
                "title": "对所有同步触发源增加抖动与单飞锁",
                "requires_approval": True,
                "how": {"note": "需要代码改动：全局 singleflight/lock + jitter"},
            },
            {
                "id": "L2",
                "title": "将 429 排障结论与证据落盘可回放",
                "requires_approval": False,
                "how": {"tool": "agent.audit.replay", "input": {"trace_id": tid, "limit": 3000}},
            },
        ]

        troubleshooting = {
            "error": {"normalized": error_norm, "trace_id": tid},
            "evidence": [
                {"name": "tracker_hl_state", "detail": _tracker_compact_sync_state(hl_state), "how_to_get": {"tool": "tracker.stats", "input": {"view": "summary"}}},
                {"name": "tracker_hl_rate_limit", "detail": {"rate_limit_until_ts": int(until_ts), "rate_limit_backoff_ms": int(backoff_ms)}, "how_to_get": {"tool": "tracker.stats", "input": {"view": "summary"}}},
                {"name": "tracker_hl_sync_triggers", "detail": hl_tr, "how_to_get": {"tool": "tracker.stats", "input": {"view": "summary"}}},
                {"name": "config_snapshot", "detail": _json_sanitize(_config_public_view(cfg_ev)), "how_to_get": {"tool": "config.get", "input": {"keys": list(cfg_ev.keys())}}},
                {"name": "trace_chain", "detail": {"trace_id": tid, "orders_n": len(orders), "settlements_n": len(settlements)}, "how_to_get": {"tool": "agent.trace.replay", "input": {"trace_id": tid, "max_orders": 120}}},
            ],
            "hypotheses": hypotheses,
            "validations": validations,
            "actions": {
                "short_term": actions_short,
                "long_term": actions_long,
                "release_safety": "任何生产变更需人工审批与受控写入口，并保留可回滚点与审计回放",
            },
            "context": {
                "venue": error_norm.get("venue"),
                "hl_state": {"rate_limited": (int(until_ts) > int(now_ms)), "until_ts": int(until_ts), "backoff_ms": int(backoff_ms)},
                "hl_triggers": {"count_5m": hl_tr.get("count_5m"), "count_30m": hl_tr.get("count_30m")},
                "aster_state": _tracker_compact_sync_state(aster_state),
            },
        }

    reason_scores = _agent_loss_reason_scores_tradfi_v1(
        trigger_event=(str(((chain.get("trigger") or {}) if isinstance(chain.get("trigger"), dict) else {}).get("trigger_event") or "").strip() or None),
        event=(evt if isinstance(evt, dict) else None),
        orders=[o for o in orders if isinstance(o, dict)],
        settlements=[r for r in settlements if isinstance(r, dict)],
        error_norm=(error_norm if isinstance(error_norm, dict) else {}),
    )
    _ev("reason_scores", reason_scores)

    return {
        "ok": True,
        "ts": int(_now_ms()),
        "trace_id": tid,
        "error_norm": error_norm,
        "reason_scores": reason_scores,
        "summary": summary,
        "timeline": timeline,
        "causes": causes,
        "evidence": evidence,
        "recommendations": recs,
        "troubleshooting": troubleshooting,
    }


def _agent_rca_emit(report: Dict[str, Any]) -> None:
    if not isinstance(report, dict):
        return
    tid = str(report.get("trace_id") or "").strip()
    rid = uuid.uuid4().hex
    item = {"id": rid, "trace_id": tid, "ts": int(report.get("ts") or _now_ms()), "type": "rca.report", "report": report}
    _agent_outbox_append_jsonl("rca.jsonl", item)
    try:
        _agent_outbox_append_jsonl("audit_actions.jsonl", {"name": "agent.rca.generated", "ts": int(_now_ms()), "payload": {"trace_id": tid, "rca_id": rid, "loss": ((report.get("summary") or {}).get("loss") if isinstance(report.get("summary"), dict) else None)}})
    except Exception:
        pass


def _agent_rca_emit_guard(trace_id: str, *, ttl_ms: int = 3600_000) -> bool:
    tid = str(trace_id or "").strip()
    if not tid:
        return False
    st = TRACKER_STATE.get("rca_emitted")
    if not isinstance(st, dict):
        st = {}
        TRACKER_STATE["rca_emitted"] = st
    now_ms = int(_now_ms())
    try:
        last = int(st.get(tid) or 0)
    except Exception:
        last = 0
    if last > 0 and (now_ms - last) < int(ttl_ms):
        return False
    st[tid] = now_ms
    return True


