def _agent_rca_analyze_process(trace_id: str, *, include_dq: bool, include_eq: bool, llm_cfg: Dict[str, Any]) -> None:
    tid = str(trace_id or "").strip() or uuid.uuid4().hex
    ts0 = int(_now_ms())
    _agent_outbox_append_jsonl("chat.jsonl", {"id": uuid.uuid4().hex, "trace_id": tid, "ts": ts0, "type": "rca.analyze.start", "channel": "rca"})

    chain = _agent_trace_chain(tid)
    if not bool(chain.get("ok")):
        _agent_outbox_append_jsonl("chat.jsonl", {"id": uuid.uuid4().hex, "trace_id": tid, "ts": int(_now_ms()), "type": "rca.analyze.error", "channel": "rca", "error": chain.get("error") or "trace_not_found"})
        return
    rep = _agent_rca_report_from_chain(chain, include_dq=bool(include_dq), include_eq=bool(include_eq))

    hypotheses: List[Dict[str, Any]] = []
    suggested_tool_plan: List[Dict[str, Any]] = []
    parse_ok = False
    parse_error = None
    response_raw = ""

    llm_enabled = bool(llm_cfg.get("enabled"))
    provider = str(llm_cfg.get("provider") or "auto").strip().lower() or "auto"
    model = str(llm_cfg.get("model") or "").strip()
    try:
        timeout_sec = int(llm_cfg.get("timeout_sec") or 60)
    except Exception:
        timeout_sec = 60
    timeout_sec = max(5, min(900, int(timeout_sec)))

    sel = _agent_llm_route(
        purpose="agent.rca",
        req_provider=provider,
        req_model=model,
        intent_norm={"kind": "explore.rca", "text": "rca_analyze"},
        intent_level="L1",
        risk_level="P2",
        tool_plan=[],
    )
    provider2 = str((sel or {}).get("provider") or provider).strip().lower() or "ollama"
    model2 = str((sel or {}).get("model") or model).strip()

    if llm_enabled and model2:
        sys = "\n".join([
            "你是交易系统的 RCA 假设生成与验证编排器，只输出严格 JSON。",
            "输出字段：hypotheses, tool_plan。",
            "hypotheses 是数组，每项包含：id,title,statement,expected_evidence,risk_level。",
            "tool_plan 是数组，每项包含：tool,input,requires_approval。",
            "tool 只能使用以下集合：" + ",".join(sorted(list(_AGENT_SKILLS_REGISTRY.keys()))),
            "不要假装已执行工具；工具结果由宿主侧回写。",
        ])
        user_obj = {
            "trace_id": tid,
            "rca": rep,
            "skills": _agent_skills_list(),
        }
        resp = _agent_llm_chat(provider=provider2, model=model2, messages=[{"role": "system", "content": sys}, {"role": "user", "content": json.dumps(user_obj, ensure_ascii=False)}], timeout_sec=timeout_sec)
        if resp.get("ok"):
            data = resp.get("data") if isinstance(resp.get("data"), dict) else {}
            try:
                response_raw = str(((data.get("message") or {}) if isinstance(data.get("message"), dict) else {}).get("content") or "")
            except Exception:
                response_raw = ""
            parsed = None
            try:
                parsed = _json_parse_loose(response_raw)
            except Exception as e:
                parse_error = str(e)
                parsed = None
            if isinstance(parsed, dict):
                parse_ok = True
                if isinstance(parsed.get("hypotheses"), list):
                    hypotheses = [x for x in parsed.get("hypotheses") if isinstance(x, dict)][:12]
                if isinstance(parsed.get("tool_plan"), list):
                    suggested_tool_plan = [x for x in parsed.get("tool_plan") if isinstance(x, dict)]
        else:
            parse_error = str(resp.get("error") or "llm_failed")
    else:
        parse_error = "llm_disabled"

    if not hypotheses:
        causes = rep.get("causes") if isinstance(rep.get("causes"), list) else []
        for i, c in enumerate([x for x in causes if isinstance(x, dict)][:6]):
            code = str(c.get("code") or f"h{i+1}").strip() or f"h{i+1}"
            hypotheses.append({
                "id": code,
                "title": str(c.get("summary") or code),
                "statement": str(c.get("summary") or ""),
                "expected_evidence": ["orders/settlements trace", "dq/eq window"],
                "risk_level": "P2",
            })

    if not suggested_tool_plan:
        suggested_tool_plan = [
            {"tool": "metrics.recent", "input": {}, "requires_approval": False},
        ]
        if bool(include_dq):
            suggested_tool_plan.append({"tool": "audit.data_quality", "input": {"pair": (rep.get("summary") or {}).get("pair")}, "requires_approval": False})
        if bool(include_eq):
            suggested_tool_plan.append({"tool": "audit.execution_quality", "input": {"pair": (rep.get("summary") or {}).get("pair")}, "requires_approval": False})

    suggested_tool_plan = _agent_chat_tool_plan_sanitize(suggested_tool_plan, intent_level="L1", risk_uncertain=False)

    validation_actions: List[Dict[str, Any]] = []
    sandbox_tasks: List[Dict[str, Any]] = []
    governance_actions: List[Dict[str, Any]] = []

    def _h_text(h: Dict[str, Any]) -> str:
        parts = []
        try:
            parts.append(str(h.get("title") or "").strip())
        except Exception:
            pass
        try:
            parts.append(str(h.get("statement") or "").strip())
        except Exception:
            pass
        return " ".join([x for x in parts if x])

    for h in (hypotheses if isinstance(hypotheses, list) else [])[:12]:
        if not isinstance(h, dict):
            continue
        hid = str(h.get("id") or "").strip() or uuid.uuid4().hex
        txt = _h_text(h)
        txt_low = txt.lower()
        hid_low = hid.lower()

        r0_plan: List[Dict[str, Any]] = [
            {"tool": "agent.trace.replay", "input": {"trace_id": tid, "max_orders": 80}, "requires_approval": False},
        ]
        if ("execution" in hid_low) or ("exec" in hid_low) or ("执行" in txt) or ("rejected" in txt_low) or ("failed" in txt_low):
            r0_plan.extend([
                {"tool": "tracker.sync.recent", "input": {"venue": "all", "limit": 30}, "requires_approval": False},
                {"tool": "tracker.stats", "input": {"view": "summary"}, "requires_approval": False},
            ])
        if ("gate" in hid_low) or ("veto" in hid_low) or ("风控" in txt) or ("gate" in txt_low) or ("limit" in txt_low):
            r0_plan.append({"tool": "metrics.recent", "input": {}, "requires_approval": False})
            r0_plan.append({"tool": "code.search", "input": {"query": "daily_loss_limit", "files": ["ml_trade_service.py"], "max_hits": 20}, "requires_approval": False})

        r0_plan = _agent_chat_tool_plan_sanitize(r0_plan, intent_level="L0", risk_uncertain=False)
        validation_actions.append({"hypothesis_id": hid, "level": "R0", "tool_plan": r0_plan})

        needs_sandbox = ("regime" in txt_low) or ("exit" in hid_low) or ("exit" in txt_low) or ("回测" in txt) or ("robust" in txt_low) or ("稳健" in txt)
        if needs_sandbox:
            r1_plan = [
                {"tool": "sandbox.backtest", "input": {"strategy": "(from_repo)", "timerange": ""}, "requires_approval": False},
                {"tool": "sandbox.robustness", "input": {"zip": "latest"}, "requires_approval": False},
            ]
            r1_plan = _agent_chat_tool_plan_sanitize(r1_plan, intent_level="L1", risk_uncertain=False)
            sandbox_tasks.append({"hypothesis_id": hid, "level": "R1", "tool_plan": r1_plan})

        wants_change = ("config" in txt_low) or ("参数" in txt) or ("调整" in txt) or ("patch" in txt_low) or ("修复" in txt)
        if wants_change:
            governance_actions.append({"hypothesis_id": hid, "level": "R2", "tool_plan": [{"tool": "approval.request", "input": {"reason": f"rca_change:{hid}"}, "requires_approval": True}]})

    _agent_outbox_append_jsonl(
        "chat.jsonl",
        {
            "id": uuid.uuid4().hex,
            "trace_id": tid,
            "ts": int(_now_ms()),
            "type": "rca.hypothesis",
            "channel": "rca",
            "rca": rep,
            "hypotheses": hypotheses,
            "tool_plan_suggested": suggested_tool_plan,
            "validation_actions": validation_actions,
            "sandbox_tasks": sandbox_tasks,
            "governance_actions": governance_actions,
            "parse_ok": bool(parse_ok),
            "parse_error": parse_error,
            "response_raw": (response_raw[:6500] if isinstance(response_raw, str) else ""),
        },
    )

    tool_results = _agent_skill_execute_plan(tid, suggested_tool_plan)

    final = None
    if llm_enabled and model2:
        sys2 = "\n".join([
            "你是交易系统的 RCA 验证总结器，只输出严格 JSON。",
            "输出字段：validated_hypotheses,next_actions,confidence,summary。",
            "validated_hypotheses 是数组，每项包含：id,status(e.g. supported/rejected/unknown),evidence,notes。",
            "next_actions 是数组，每项包含：title,tool_plan(optional),priority。",
            "不要输出多余字段。",
        ])
        user_obj2 = {
            "trace_id": tid,
            "rca": rep,
            "hypotheses": hypotheses,
            "tool_results": tool_results,
        }
        resp2 = _agent_llm_chat(provider=provider2, model=model2, messages=[{"role": "system", "content": sys2}, {"role": "user", "content": json.dumps(user_obj2, ensure_ascii=False)}], timeout_sec=timeout_sec)
        if resp2.get("ok"):
            data2 = resp2.get("data") if isinstance(resp2.get("data"), dict) else {}
            raw2 = ""
            try:
                raw2 = str(((data2.get("message") or {}) if isinstance(data2.get("message"), dict) else {}).get("content") or "")
            except Exception:
                raw2 = ""
            try:
                parsed2 = _json_parse_loose(raw2)
            except Exception:
                parsed2 = None
            if isinstance(parsed2, dict):
                final = parsed2

    item = {
        "ok": True,
        "ts": int(_now_ms()),
        "trace_id": tid,
        "rca": rep,
        "hypotheses": hypotheses,
        "tool_plan": suggested_tool_plan,
        "tool_results": tool_results,
        "validation_actions": validation_actions,
        "sandbox_tasks": sandbox_tasks,
        "governance_actions": governance_actions,
        "final": final,
        "duration_ms": int(_now_ms()) - ts0,
    }
    _agent_outbox_append_jsonl("rca.jsonl", {"id": uuid.uuid4().hex, "trace_id": tid, "ts": int(_now_ms()), "type": "rca.analysis", "report": item})
    _agent_outbox_append_jsonl("chat.jsonl", {"id": uuid.uuid4().hex, "trace_id": tid, "ts": int(_now_ms()), "type": "rca.analyze.result", "channel": "rca", "result": item})


@app.route("/agent/rca/analyze", methods=["POST"])
def agent_rca_analyze():
    if not _agent_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip()
    if not trace_id:
        return jsonify({"ok": False, "error": "missing_trace_id", "ts": int(_now_ms())}), 400
    include_dq = bool(data.get("include_dq", True))
    include_eq = bool(data.get("include_eq", True))

    llm = data.get("llm") if isinstance(data.get("llm"), dict) else {}
    llm_provider = str((data.get("llm_provider") if data.get("llm_provider") is not None else llm.get("provider")) or "").strip().lower()
    llm_model = str((data.get("llm_model") if data.get("llm_model") is not None else llm.get("model")) or "").strip()
    llm_enabled = None
    try:
        if data.get("llm_enabled") is not None:
            llm_enabled = bool(data.get("llm_enabled"))
        elif llm.get("enabled") is not None:
            llm_enabled = bool(llm.get("enabled"))
    except Exception:
        llm_enabled = None
    if llm_enabled is None:
        llm_enabled = bool(llm_provider or llm_model)
    try:
        llm_timeout_sec = int((data.get("llm_timeout_sec") if data.get("llm_timeout_sec") is not None else llm.get("timeout_sec")) or 60)
    except Exception:
        llm_timeout_sec = 60
    llm_timeout_sec = max(5, min(900, int(llm_timeout_sec)))
    if not llm_provider:
        llm_provider = "auto"
    if (not llm_model) and (llm_provider != "auto"):
        if llm_provider in ("dashscope", "qwen"):
            try:
                llm_model = str(os.environ.get("AGENT_DASHSCOPE_MODEL", "") or "").strip()
            except Exception:
                llm_model = ""
            if not llm_model:
                try:
                    llm_model = str(CONFIG.get("agent_dashscope_model") or "").strip()
                except Exception:
                    llm_model = ""
            if not llm_model:
                llm_model = "qwen3-coder-plus"
        else:
            try:
                llm_model = str(os.environ.get("AGENT_OLLAMA_MODEL", "") or "").strip()
            except Exception:
                llm_model = ""
            if not llm_model:
                try:
                    llm_model = str(CONFIG.get("agent_ollama_model") or "").strip()
                except Exception:
                    llm_model = ""
            if not llm_model:
                llm_model = "qwen2.5:7b-instruct"

    llm_cfg = {"enabled": bool(llm_enabled), "provider": llm_provider, "model": llm_model, "timeout_sec": llm_timeout_sec}

    try:
        async_run = bool(data.get("async", True))
    except Exception:
        async_run = True

    if async_run:
        t = threading.Thread(target=_agent_rca_analyze_process, args=(trace_id,), kwargs={"include_dq": include_dq, "include_eq": include_eq, "llm_cfg": llm_cfg}, daemon=True)
        t.start()
        return jsonify({"ok": True, "queued": True, "trace_id": trace_id, "ts": int(_now_ms())})

    _agent_rca_analyze_process(trace_id, include_dq=include_dq, include_eq=include_eq, llm_cfg=llm_cfg)
    return jsonify({"ok": True, "queued": False, "trace_id": trace_id, "ts": int(_now_ms())})


def _stable_json_dumps(obj: Any) -> str:
    try:
        return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    except Exception:
        try:
            return json.dumps(_json_sanitize(obj), ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        except Exception:
            return "{}"


def _agent_change_bundle_change_id(*, strategy_key: str, action: str, policy_ref: str, config_patch: Dict[str, Any], baseline_ref: Optional[str]) -> str:
    stable = _stable_json_dumps({"strategy_key": str(strategy_key), "action": str(action), "policy_ref": str(policy_ref), "baseline_ref": (baseline_ref or None), "config_patch": (config_patch if isinstance(config_patch, dict) else {})})
    return hashlib.sha256(stable.encode("utf-8")).hexdigest()[:32]


def _agent_config_diff_direction(*, key: str, from_v: Any, to_v: Any, rule: Optional[Dict[str, Any]]) -> str:
    tr = str((rule or {}).get("tighten_rule") or "").strip().lower()
    tp = str((rule or {}).get("type") or "").strip().lower()
    if from_v == to_v:
        return "neutral"
    if tr == "disable_only":
        return "tighten" if (tp == "bool" and bool(from_v) and (not bool(to_v))) else "loosen"
    if tr == "enable_only":
        return "tighten" if (tp == "bool" and (not bool(from_v)) and bool(to_v)) else "loosen"
    if tr == "restrict_only":
        if tp != "list_str":
            return "neutral"
        a = {str(x).strip().upper() for x in (from_v if isinstance(from_v, list) else []) if str(x or "").strip()}
        b = {str(x).strip().upper() for x in (to_v if isinstance(to_v, list) else []) if str(x or "").strip()}
        if b.issubset(a) and (a != b):
            return "tighten"
        if a.issubset(b) and (a != b):
            return "loosen"
        return "neutral"
    if tr in ("increase", "decrease", "toward_zero"):
        if tp not in ("int", "float"):
            return "neutral"
        try:
            af = float(from_v)
            bf = float(to_v)
        except Exception:
            return "neutral"
        if not (math.isfinite(float(af)) and math.isfinite(float(bf))):
            return "neutral"
        if tr == "increase":
            return "tighten" if bf > af else "loosen"
        if tr == "decrease":
            return "tighten" if bf < af else "loosen"
        if tr == "toward_zero":
            aa = abs(float(af))
            bb = abs(float(bf))
            if bb < aa:
                return "tighten"
            if bb > aa:
                return "loosen"
            return "neutral"
    return "neutral"


def _agent_config_diff_build(*, config_patch: Dict[str, Any], base_cfg: Optional[Dict[str, Any]], rules: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
    patch = config_patch if isinstance(config_patch, dict) else {}
    base = base_cfg if isinstance(base_cfg, dict) else {}
    changes: List[Dict[str, Any]] = []
    for k in sorted([str(x).strip() for x in patch.keys() if str(x).strip()]):
        rule = rules.get(k) if isinstance(rules, dict) else None
        try:
            frm = base.get(k)
        except Exception:
            frm = None
        to = patch.get(k)
        direction = _agent_config_diff_direction(key=k, from_v=frm, to_v=to, rule=rule if isinstance(rule, dict) else None)
        allowlist_ref = f"agent_auto_config_rules_v1:{k}"
        changes.append({"key": k, "from": frm, "to": to, "direction": direction, "reason": None, "allowlist_ref": allowlist_ref})
    return {"changes": changes}


def _agent_change_tags_from_config_diff(config_diff: Dict[str, Any]) -> List[str]:
    tags: List[str] = []
    changes = config_diff.get("changes") if isinstance(config_diff, dict) else None
    if not isinstance(changes, list) or not changes:
        return ["neutral"]
    if any(isinstance(c, dict) and str(c.get("direction") or "") == "tighten" for c in changes):
        tags.append("tighten")
    if any(isinstance(c, dict) and str(c.get("direction") or "") == "loosen" for c in changes):
        tags.append("loosen")
    risk_keys = {"max_open_trades", "max_orders_per_minute", "entry_max_notional_usdc", "entry_fixed_notional_usdc", "entry_min_notional_usdc", "hl_default_leverage", "aster_default_leverage"}
    exposure_increase_keys = {"entry_max_notional_usdc", "entry_fixed_notional_usdc", "entry_min_notional_usdc", "hl_default_leverage", "aster_default_leverage"}
    try:
        for c in changes:
            if not isinstance(c, dict):
                continue
            k = str(c.get("key") or "").strip()
            if k in exposure_increase_keys:
                try:
                    if float(c.get("to")) > float(c.get("from")):
                        tags.append("exposure_increase")
                        break
                except Exception:
                    continue
    except Exception:
        pass
    if any(isinstance(c, dict) and str(c.get("key") or "").strip() in risk_keys for c in changes):
        tags.append("risk_controls")
    uniq: List[str] = []
    seen = set()
    for t in tags:
        s = str(t).strip()
        if not s or s in seen:
            continue
        seen.add(s)
        uniq.append(s)
    return uniq if uniq else ["neutral"]


def _agent_expected_effect_from_delta_metrics(delta_metrics: Any) -> Dict[str, Any]:
    dm = delta_metrics if isinstance(delta_metrics, dict) else {}
    primary_metrics_up: List[str] = []
    tradeoffs: List[str] = []
    try:
        for k in ("profit_factor", "winrate", "trades"):
            d = dm.get(k) if isinstance(dm.get(k), dict) else None
            if not isinstance(d, dict):
                continue
            dv = d.get("delta")
            if dv is None:
                continue
            try:
                if float(dv) > 0:
                    primary_metrics_up.append(k)
            except Exception:
                continue
        ddd = dm.get("max_drawdown_pct") if isinstance(dm.get("max_drawdown_pct"), dict) else None
        if isinstance(ddd, dict):
            dv = ddd.get("delta")
            if dv is not None:
                try:
                    if float(dv) < 0:
                        primary_metrics_up.append("max_drawdown_pct")
                except Exception:
                    pass
    except Exception:
        pass
    if not primary_metrics_up and dm:
        tradeoffs.append("metrics_delta_unclear")
    return {"primary_metrics_up": primary_metrics_up, "possible_tradeoffs": tradeoffs, "regime_assumptions": []}


PIPELINE_ARTIFACT_SCHEMA_VERSION = "2026-02-24"


def _agent_pipeline_producer(kind: str) -> Dict[str, Any]:
    return {
        "kind": str(kind or "").strip() or "agent",
        "name": "ml_trade_service",
        "version": str(os.environ.get("ML_TRADE_SERVICE_VERSION") or "").strip() or "unknown",
    }


def _agent_pipeline_artifact_common_fields(*, trace_id: str, created_at_ms: int, producer_kind: str = "agent") -> Dict[str, Any]:
    return {
        "schema_version": str(PIPELINE_ARTIFACT_SCHEMA_VERSION),
        "trace_id": str(trace_id),
        "created_at_ms": int(created_at_ms),
        "producer": _agent_pipeline_producer(str(producer_kind or "agent")),
        "scope": {},
        "inputs": {},
        "references": {},
    }


def _agent_pipeline_artifact_apply_common_fields(*, trace_id: str, created_at_ms: int, artifact: Any, producer_kind: str = "agent") -> Dict[str, Any]:
    art = artifact if isinstance(artifact, dict) else {}
    out: Dict[str, Any] = dict(art)
    out["trace_id"] = str(trace_id)

    if not str(out.get("schema_version") or "").strip():
        out["schema_version"] = str(PIPELINE_ARTIFACT_SCHEMA_VERSION)

    ca = out.get("created_at_ms")
    if ca is None:
        out["created_at_ms"] = int(created_at_ms)
    else:
        try:
            out["created_at_ms"] = int(ca)
        except Exception:
            out["created_at_ms"] = int(created_at_ms)

    prod = out.get("producer")
    if not isinstance(prod, dict):
        out["producer"] = _agent_pipeline_producer(str(producer_kind or "agent"))
    else:
        pk = str(prod.get("kind") or "").strip()
        pn = str(prod.get("name") or "").strip()
        if not pk or not pn:
            out["producer"] = _agent_pipeline_producer(str(producer_kind or "agent"))

    if not isinstance(out.get("scope"), dict):
        out["scope"] = {}
    if not isinstance(out.get("inputs"), dict):
        out["inputs"] = {}
    if not isinstance(out.get("references"), dict):
        out["references"] = {}
    return out


def _agent_change_bundle_draft_validate(obj: Any) -> Dict[str, Any]:
    errors: List[Dict[str, Any]] = []
    if not isinstance(obj, dict):
        return {"ok": False, "errors": [{"path": "$", "error": "not_object"}]}
    ct = str(obj.get("change_type") or "").strip()
    if ct not in ("param", "code"):
        errors.append({"path": "$.change_type", "error": "bad_value"})
    cid = str(obj.get("change_id") or "").strip()
    if not cid:
        errors.append({"path": "$.change_id", "error": "missing"})
    tags = obj.get("change_tags")
    if not (isinstance(tags, list) and all(isinstance(x, str) and x.strip() for x in tags) and len(tags) <= 50):
        errors.append({"path": "$.change_tags", "error": "bad_type"})
    diff_ref = obj.get("diff_ref")
    if not isinstance(diff_ref, dict):
        errors.append({"path": "$.diff_ref", "error": "bad_type"})
    exp = obj.get("expected_effect")
    if not isinstance(exp, dict):
        errors.append({"path": "$.expected_effect", "error": "bad_type"})
    rb = obj.get("rollback_plan")
    if not isinstance(rb, dict) or (rb.get("rollback_to") is None and rb.get("rollback_point_id") is None):
        errors.append({"path": "$.rollback_plan", "error": "bad_type"})
    req = obj.get("required_gates")
    if not isinstance(req, dict):
        errors.append({"path": "$.required_gates", "error": "bad_type"})
    return {"ok": (not errors), "errors": errors}


