def _governance_scan_obj_for_explore_markers(obj: Any, *, max_hits: int) -> List[Dict[str, Any]]:
    hits: List[Dict[str, Any]] = []

    def _walk(x: Any, path: str) -> None:
        nonlocal hits
        if len(hits) >= int(max_hits):
            return
        if isinstance(x, dict):
            for k, v in list(x.items())[:2000]:
                kk = str(k)
                p2 = f"{path}.{kk}" if path else kk
                if "explore" in kk.lower():
                    hits.append({"path": p2, "kind": "key_contains_explore", "value": None})
                    if len(hits) >= int(max_hits):
                        return
                _walk(v, p2)
            return
        if isinstance(x, list):
            for i, v in enumerate(x[:2000]):
                _walk(v, f"{path}[{i}]")
                if len(hits) >= int(max_hits):
                    return
            return
        if isinstance(x, str):
            s = x
            if "explore" in s.lower():
                hits.append({"path": path, "kind": "value_contains_explore", "value": (s[:240] + ("..." if len(s) > 240 else ""))})
            return

    _walk(obj, "")
    return hits


@app.route("/agent/governance/scan_contamination", methods=["GET"])
def agent_governance_scan_contamination():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    env = _governance_env_name()
    try:
        limit = int(request.args.get("limit") or 200)
    except Exception:
        limit = 200
    limit = max(1, min(2000, int(limit)))
    if env not in ("prod", "pilot"):
        return jsonify({"ok": True, "ts": int(_now_ms()), "env": env, "skipped": True, "reason": "non_prod_env", "hits": [], "count": 0}), 200
    hits = _governance_scan_obj_for_explore_markers(CONFIG, max_hits=int(limit))
    out = {"ok": True, "ts": int(_now_ms()), "env": env, "skipped": False, "hits": hits, "count": int(len(hits))}
    try:
        _agent_outbox_append_jsonl("audit_actions.jsonl", {"name": "governance.scan_contamination", "ts": int(_now_ms()), "payload": {"env": env, "count": int(len(hits)), "hits": hits[:50]}})
    except Exception:
        pass
    return jsonify(out), 200


@app.route("/agent/mip/list", methods=["GET"])
def agent_mip_list():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
