def _paramopt_context_severity(ctx: Any) -> str:
    if not isinstance(ctx, dict):
        return "normal"
    sev = str(ctx.get("severity") or ctx.get("risk_level") or "").strip().lower()
    if sev in ("p0", "p1", "p2", "p3"):
        return sev
    alerts = ctx.get("alerts")
    items = []
    if isinstance(alerts, dict):
        items = alerts.get("alerts") if isinstance(alerts.get("alerts"), list) else []
    elif isinstance(alerts, list):
        items = alerts
    for a in items:
        if not isinstance(a, dict):
            continue
        s = str(a.get("severity") or a.get("level") or "").strip().lower()
        if s in ("p0", "critical", "fatal"):
            return "p0"
        if s in ("p1", "high"):
            return "p1"
        if s in ("p2", "medium"):
            return "p2"
        if s in ("p3", "low"):
            return "p3"
    return "normal"


def _paramopt_resolve_default(item: Dict[str, Any]) -> Any:
    k = str(item.get("key") or "").strip()
    if not k:
        return item.get("default")
    try:
        if k in CONFIG:
            return CONFIG.get(k)
    except Exception:
        pass
    return item.get("default")


def _paramopt_round_to_step(v: float, step: Optional[float]) -> float:
    if step is None:
        return float(v)
    try:
        s = float(step)
    except Exception:
        return float(v)
    if s <= 0:
        return float(v)
    try:
        return float(round(float(v) / s) * s)
    except Exception:
        return float(v)


def _paramopt_item_effective_domain(item: Dict[str, Any], *, ctx: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    out = dict(item)
    cur = _paramopt_resolve_default(item)
    out["current"] = cur
    sev = _paramopt_context_severity(ctx or {})
    tighten_only = sev in ("p0", "p1")

    tp = str(item.get("type") or "").strip().lower()
    tr = str(item.get("tighten_rule") or "").strip().lower()

    if tp == "bool":
        choices = out.get("choices")
        if not isinstance(choices, list) or not choices:
            choices = [False, True]
        if tighten_only and tr == "disable_only":
            cur_b = bool(cur) if cur is not None else False
            choices = [False] if cur_b else [False]
        if tighten_only and tr == "enable_only":
            choices = [True]
        out["choices"] = choices
        return out

    if tp in ("int", "float"):
        r0 = out.get("range")
        if not (isinstance(r0, list) and len(r0) == 2):
            return out
        try:
            lo = float(r0[0])
            hi = float(r0[1])
        except Exception:
            return out
        if hi < lo:
            lo, hi = hi, lo
        if tighten_only and tr and cur is not None:
            try:
                cur_f = float(cur)
            except Exception:
                cur_f = None
            if cur_f is not None and math.isfinite(float(cur_f)):
                if tr == "increase":
                    lo = max(lo, float(cur_f))
                elif tr == "decrease":
                    hi = min(hi, float(cur_f))
                elif tr == "toward_zero":
                    if float(cur_f) > 0:
                        hi = min(hi, float(cur_f))
                    elif float(cur_f) < 0:
                        lo = max(lo, float(cur_f))
                    else:
                        lo, hi = 0.0, 0.0

        step = out.get("step")
        if step is not None:
            try:
                step_f = float(step)
                if step_f > 0:
                    lo = _paramopt_round_to_step(lo, step_f)
                    hi = _paramopt_round_to_step(hi, step_f)
            except Exception:
                pass
        out["range"] = [lo, hi]
        return out

    return out


def _paramopt_parse_scopes(data: Dict[str, Any]) -> List[str]:
    raw: List[str] = []
    if isinstance(data.get("scopes"), list):
        raw = [str(x) for x in (data.get("scopes") or [])]
    else:
        sc = str(data.get("scope") or "").strip()
        if sc:
            raw = [sc]

    out: List[str] = []
    for s in raw:
        ss = str(s).strip().lower()
        if not ss:
            continue
        if ss in ("all", "*"):
            out.extend(["strategy", "quant", "entry", "exit", "overlay"])
            continue
        out.append(ss)

    allowed = {"strategy", "quant", "entry", "exit", "overlay"}
    out2: List[str] = []
    seen = set()
    for s in out:
        if s not in allowed:
            continue
        if s in seen:
            continue
        seen.add(s)
        out2.append(s)
    if not out2:
        return ["strategy", "quant", "entry", "exit", "overlay"]
    return out2


def _paramopt_strategy_group_id(strategy_id: str) -> str:
    sid = str(strategy_id or "").strip()
    if not sid:
        return ""
    try:
        sm = CONFIG.get("strategy_meta") if isinstance(CONFIG.get("strategy_meta"), dict) else {}
    except Exception:
        sm = {}
    try:
        gid = str((sm.get(sid) or {}).get("group_id") or "").strip()
    except Exception:
        gid = ""
    if gid:
        return gid
    try:
        sm2 = _strategy_id_map() if isinstance(_strategy_id_map(), dict) else {}
    except Exception:
        sm2 = {}
    try:
        gid2 = str((sm2.get(sid) or {}).get("group_id") or "").strip()
    except Exception:
        gid2 = ""
    if gid2:
        return gid2
    return sid


def _paramopt_strategy_prefixes(strategy_id: str, group_id: Optional[str] = None) -> List[str]:
    sid = str(strategy_id or "").strip()
    sid_l = sid.lower()
    gid = str(group_id or "").strip() or _paramopt_strategy_group_id(sid)
    prefixes: List[str] = []
    if gid:
        gid_slug = _cfg_key_slug(gid).lower()
        if gid_slug:
            prefixes.append((gid_slug if gid_slug.endswith("_") else f"{gid_slug}_"))
    if sid:
        sid_slug = _cfg_key_slug(sid).lower()
        if sid_slug:
            prefixes.append((sid_slug if sid_slug.endswith("_") else f"{sid_slug}_"))
    if sid_l == "regimehybridstrategy":
        prefixes.extend(["rh_", "regime_hybrid_"])
    m_sid_num = re.match(r"^strategy(\d+)$", sid_l)
    if m_sid_num is not None:
        try:
            sid_num = int(m_sid_num.group(1))
            prefixes.append(f"s{int(sid_num):03d}_")
        except Exception:
            pass
    if sid_l == "strategy005":
        prefixes.append("s005_")
    out: List[str] = []
    seen = set()
    for p0 in prefixes:
        p1 = str(p0 or "").strip().lower()
        if (not p1) or (p1 in seen):
            continue
        seen.add(p1)
        out.append(p1)
    return out


