def _paramopt_select_items(*, space: Dict[str, Any], scopes: List[str], include_modes: List[str], ctx: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    wanted_scopes = [str(s).strip().lower() for s in (scopes or []) if str(s).strip()]
    if not wanted_scopes:
        wanted_scopes = ["strategy", "quant"]
    mode_set = set([str(m).strip().lower() for m in (include_modes or []) if str(m).strip()])
    if not mode_set:
        mode_set = {"auto", "auto-tighten-only"}
    items: List[Dict[str, Any]] = []
    def _with_scope(it: Dict[str, Any], scope: str) -> Dict[str, Any]:
        out = dict(it)
        if not str(out.get("scope") or "").strip():
            out["scope"] = str(scope)
        return out
    if "strategy" in wanted_scopes:
        if "strategy_auto" in space and isinstance(space.get("strategy_auto"), list):
            items.extend([_with_scope(x, "strategy") for x in space.get("strategy_auto") if isinstance(x, dict)])
        if "strategy_suggest_only" in space and isinstance(space.get("strategy_suggest_only"), list):
            items.extend([_with_scope(x, "strategy") for x in space.get("strategy_suggest_only") if isinstance(x, dict)])
    if "quant" in wanted_scopes:
        if "quant_suggest_only" in space and isinstance(space.get("quant_suggest_only"), list):
            items.extend([_with_scope(x, "quant") for x in space.get("quant_suggest_only") if isinstance(x, dict)])
    if "entry" in wanted_scopes:
        if "entry_suggest_only" in space and isinstance(space.get("entry_suggest_only"), list):
            items.extend([_with_scope(x, "entry") for x in space.get("entry_suggest_only") if isinstance(x, dict)])
    if "overlay" in wanted_scopes:
        if "overlay_suggest_only" in space and isinstance(space.get("overlay_suggest_only"), list):
            items.extend([_with_scope(x, "overlay") for x in space.get("overlay_suggest_only") if isinstance(x, dict)])
    if "exit" in wanted_scopes:
        if "exit_suggest_only" in space and isinstance(space.get("exit_suggest_only"), list):
            items.extend([_with_scope(x, "exit") for x in space.get("exit_suggest_only") if isinstance(x, dict)])
    out: List[Dict[str, Any]] = []
    for it in items:
        am = str(it.get("apply_mode") or "").strip().lower()
        if am and am not in mode_set:
            continue
        eff = _paramopt_item_effective_domain(it, ctx=ctx)
        sc0 = str(eff.get("scope") or "").strip().lower()
        if not str(eff.get("opt_class") or "").strip():
            eff["opt_class"] = ("strategy" if sc0 == "strategy" else "system")
        if not str(eff.get("tag") or "").strip():
            eff["tag"] = sc0
        out.append(eff)
    return out


def _paramopt_macro_focus_default_allowlist(scenario_target: str) -> List[str]:
    st = str(scenario_target or "").strip().upper()
    common = [
        "signals_pair_side_cooldown_sec",
        "signals_coin_side_cooldown_sec",
        "entry_inflight_cooldown_sec",
        "pc_hysteresis_delta",
        "max_orders_per_minute",
        "order_rate_window_sec",
        "max_open_trades",
        "addon_entry_max_count",
        "addon_entry_min_interval_sec",
        "entry_risk_gate_long_max",
        "entry_risk_gate_short_max",
        "entry_dir1h_hard_gate_enabled",
        "entry_dir1h_hard_gate_fail_open",
        "entry_macro_btceth_hard_gate_enabled",
        "entry_macro_btceth_hard_gate_risk_pct_max",
    ]
    up_keys = common + [
        "s005_daily_ema_fast",
        "s005_daily_ema_slow",
        "s005_hourly_ema_short",
        "s005_hourly_ema_long",
        "s005_donchian_period",
        "s005_volume_multiplier",
        "s005_entry_adx_h_threshold",
        "s005_entry_vol_max_atr_pct",
    ]
    down_keys = common + [
        "entry_macro_addon_block_counter",
        "entry_macro_gate_hard_r5",
        "entry_shape12h_net_bias_abs",
        "entry_shape12h_net_bias_abs_tier0",
        "entry_shape12h_net_bias_abs_tier1",
        "entry_shape12h_net_bias_abs_tier2",
        "entry_shape12h_net_bias_abs_tier3",
        "entry_shape12h_net_bias_abs_tier4",
    ]
    range_keys = common + [
        "threshold_chop",
        "threshold_trend",
        "threshold_min_trades",
        "entry_shape12h_net_bias_abs",
        "entry_shape12h_net_bias_abs_tier2",
        "entry_shape12h_net_bias_abs_tier3",
        "entry_shape12h_net_bias_abs_tier4",
    ]
    if st.startswith("TS_UP_"):
        return up_keys
    if st.startswith("TS_DOWN_"):
        return down_keys
    if st.startswith("TS_RANGE_"):
        return range_keys
    if st.startswith("TS_CONFLICT_"):
        return common
    if st == "TS_MIXED_DATA_GAP":
        return common
    return common


def _paramopt_match_macro_focus_pattern(key: str, pattern: str) -> bool:
    kk = str(key or "").strip()
    pp = str(pattern or "").strip()
    if (not kk) or (not pp):
        return False
    if pp == "*":
        return True
    if pp.endswith("*"):
        return kk.startswith(str(pp[:-1]))
    if pp.startswith("*"):
        return kk.endswith(str(pp[1:]))
    return kk == pp


def _paramopt_macro_focus_allowlist_for_scenario(scenario_target: str) -> Tuple[List[str], str]:
    st = str(scenario_target or "").strip().upper()
    raw = AUTOMATION.get("paramopt_macro_cycle_focus_allowlist_by_scenario")
    if isinstance(raw, dict) and raw:
        merged: List[str] = []
        for rk, rv in raw.items():
            rr = str(rk or "").strip().upper()
            if not rr:
                continue
            matched = False
            if rr == st or rr == "*":
                matched = True
            elif rr.endswith("*") and st.startswith(rr[:-1]):
                matched = True
            if not matched:
                continue
            vals = rv if isinstance(rv, list) else []
            for x in vals:
                xs = str(x).strip()
                if xs:
                    merged.append(xs)
        if merged:
            seen = set()
            out = []
            for k in merged:
                if k in seen:
                    continue
                seen.add(k)
                out.append(k)
            return out, "automation_map"
    return _paramopt_macro_focus_default_allowlist(st), "default_map"


def _paramopt_macro_focus_filter_requested_keys(requested_keys: List[str], ctx: Dict[str, Any]) -> Dict[str, Any]:
    src = str(ctx.get("source") or "").strip().lower()
    kind = str(ctx.get("kind") or "").strip().lower()
    scenario = str(ctx.get("scenario_target") or "").strip().upper()
    if (src != "macro_cycle" and kind != "paramopt_macro_cycle") or (not scenario):
        return {"applied": False}
    if not bool(AUTOMATION.get("paramopt_macro_cycle_focus_filter_enabled", True)):
        return {"applied": False, "disabled": True, "scenario_target": scenario}
    allowlist, source = _paramopt_macro_focus_allowlist_for_scenario(str(scenario))
    allowlist2 = [str(x).strip() for x in allowlist if str(x).strip()]
    if not allowlist2:
        return {"applied": False, "scenario_target": scenario, "allowlist_source": source}
    selected: List[str] = []
    dropped: List[str] = []
    for k in (requested_keys or []):
        if any(_paramopt_match_macro_focus_pattern(str(k), pat) for pat in allowlist2):
            selected.append(str(k))
        else:
            dropped.append(str(k))
    return {
        "applied": True,
        "scenario_target": scenario,
        "allowlist_source": source,
        "allowlist": allowlist2,
        "before": [str(k) for k in (requested_keys or []) if str(k)],
        "after": selected,
        "dropped": dropped,
    }


def _paramopt_eval_extract_rolling(res: Dict[str, Any]) -> Dict[str, Any]:
    out = {"ok": bool(res.get("ok")), "error": res.get("error"), "gate": res.get("gate")}
    avg = res.get("avg") if isinstance(res.get("avg"), dict) else {}
    stressed = avg.get("stressed") if isinstance(avg.get("stressed"), dict) else {}
    raw = avg.get("raw") if isinstance(avg.get("raw"), dict) else {}
    tpd_s = stressed.get("trades_per_day")
    tpd_r = raw.get("trades_per_day")
    out["stressed"] = {
        "coverage": float(stressed.get("coverage") or 0.0),
        "mean_return": float(stressed.get("mean_return") or 0.0),
        "uplift_mean_return": float(stressed.get("uplift_mean_return") or 0.0),
        "sharpe": float(stressed.get("sharpe") or 0.0),
        "sortino": float(stressed.get("sortino") or 0.0),
        "maxdd": float(stressed.get("maxdd") or 0.0),
        "tail_loss_p95": float(stressed.get("tail_loss_p95") or 0.0),
        "trades_per_day": (None if tpd_s is None else float(tpd_s)),
    }
    out["raw"] = {
        "coverage": float(raw.get("coverage") or 0.0),
        "mean_return": float(raw.get("mean_return") or 0.0),
        "uplift_mean_return": float(raw.get("uplift_mean_return") or 0.0),
        "sharpe": float(raw.get("sharpe") or 0.0),
        "sortino": float(raw.get("sortino") or 0.0),
        "maxdd": float(raw.get("maxdd") or 0.0),
        "tail_loss_p95": float(raw.get("tail_loss_p95") or 0.0),
        "trades_per_day": (None if tpd_r is None else float(tpd_r)),
    }
    trades = []
    tpds = []
    try:
        details = res.get("details") if isinstance(res.get("details"), list) else []
        for d in details:
            s = d.get("stressed") if isinstance(d.get("stressed"), dict) else {}
            if "taken" in s:
                trades.append(float(s.get("taken") or 0.0))
            if s.get("trades_per_day") is not None:
                try:
                    tpds.append(float(s.get("trades_per_day")))
                except Exception:
                    pass
    except Exception:
        trades = []
    out["avg_trades"] = float(sum(trades) / float(len(trades))) if trades else 0.0
    out["avg_trades_per_day"] = (float(sum(tpds) / float(len(tpds))) if tpds else None)
    return out


def _paramopt_score_rolling(metrics: Dict[str, Any], *, baseline: Optional[Dict[str, Any]] = None, system: str = "mixed") -> Tuple[float, Dict[str, Any]]:
    if not bool(metrics.get("ok")):
        return -1e18, {"reason": "eval_not_ok", "error": metrics.get("error")}
    gate = metrics.get("gate") if isinstance(metrics.get("gate"), dict) else {}
    gate_relaxed = False
    if gate and (not bool(gate.get("pass", True))):
        b_ok = bool(isinstance(baseline, dict) and bool(baseline.get("ok")))
        b_gate = (baseline.get("gate") if b_ok and isinstance(baseline.get("gate"), dict) else {})
        if b_gate and (not bool(b_gate.get("pass", True))):
            gate_relaxed = True
        else:
            return -1e18, {"reason": "gate_fail", "gate": gate}

    st = metrics.get("stressed") if isinstance(metrics.get("stressed"), dict) else {}
    uplift = float(st.get("uplift_mean_return") or 0.0)
    mean_return = float(st.get("mean_return") or 0.0)
    sharpe = float(st.get("sharpe") or 0.0)
    sortino = float(st.get("sortino") or 0.0)
    maxdd = float(st.get("maxdd") or 0.0)
    tail = float(st.get("tail_loss_p95") or 0.0)
    cov = float(st.get("coverage") or 0.0)
    trades = float(metrics.get("avg_trades") or 0.0)
    tpd = metrics.get("avg_trades_per_day")
    try:
        tpd = (None if tpd is None else float(tpd))
    except Exception:
        tpd = None

    if baseline is not None and isinstance(baseline, dict) and bool(baseline.get("ok")):
        b_st = baseline.get("stressed") if isinstance(baseline.get("stressed"), dict) else {}
        b_maxdd = float(b_st.get("maxdd") or 0.0)
        b_trades = float(baseline.get("avg_trades") or 0.0)
        if b_maxdd > 0 and float(maxdd) > 1.10 * float(b_maxdd):
            return -1e18, {"reason": "hard_constraint_maxdd", "maxdd": maxdd, "baseline_maxdd": b_maxdd}
        if b_trades > 0 and float(trades) < 0.70 * float(b_trades):
            return -1e18, {"reason": "hard_constraint_trades", "trades": trades, "baseline_trades": b_trades}
        b_tail = float(b_st.get("tail_loss_p95") or 0.0)
        if b_tail > 0 and float(tail) > 1.10 * float(b_tail):
            return -1e18, {"reason": "hard_constraint_tail_loss_p95", "tail_loss_p95": tail, "baseline_tail_loss_p95": b_tail}
        b_tpd = baseline.get("avg_trades_per_day")
        try:
            b_tpd = (None if b_tpd is None else float(b_tpd))
        except Exception:
            b_tpd = None
        if b_tpd is not None and tpd is not None and float(b_tpd) > 0.0 and float(tpd) > float(b_tpd) * 1.50:
            return -1e18, {"reason": "hard_constraint_trades_per_day", "trades_per_day": float(tpd), "baseline_trades_per_day": float(b_tpd)}

    try:
        tpd_cap = CONFIG.get("paramopt_max_trades_per_day")
        tpd_cap = (None if tpd_cap is None else float(tpd_cap))
    except Exception:
        tpd_cap = None
    if tpd_cap is not None and tpd is not None:
        if math.isfinite(float(tpd_cap)) and float(tpd_cap) > 0.0 and math.isfinite(float(tpd)) and float(tpd) > float(tpd_cap):
            return -1e18, {"reason": "hard_constraint_trades_per_day_cap", "trades_per_day": float(tpd), "cap": float(tpd_cap)}

    sys = str(system or "mixed").strip().lower() or "mixed"
    if sys not in ("strategy", "quant", "mixed", "risk"):
        sys = "mixed"
    calmar_like = float(mean_return) / float(max(1e-12, float(maxdd))) if float(maxdd) > 0.0 else float(mean_return)

    def _score_for(sys0: str, m: Dict[str, Any]) -> float:
        st0 = m.get("stressed") if isinstance(m.get("stressed"), dict) else {}
        u = float(st0.get("uplift_mean_return") or 0.0)
        mr = float(st0.get("mean_return") or 0.0)
        sh = float(st0.get("sharpe") or 0.0)
        so = float(st0.get("sortino") or 0.0)
        dd0 = float(st0.get("maxdd") or 0.0)
        tl = float(st0.get("tail_loss_p95") or 0.0)
        cal = float(mr) / float(max(1e-12, float(dd0))) if float(dd0) > 0.0 else float(mr)
        if sys0 == "strategy":
            return float(u) + 0.10 * float(cal) + 0.02 * float(so) + 0.01 * float(sh) - 0.18 * float(dd0) - 0.35 * float(tl)
        if sys0 == "quant":
            return float(u) + 0.05 * float(cal) + 0.06 * float(sh) + 0.04 * float(so) - 0.08 * float(dd0) - 0.20 * float(tl)
        if sys0 == "risk":
            return 0.20 * float(u) + 0.02 * float(sh) + 0.02 * float(so) - 0.30 * float(dd0) - 0.60 * float(tl)
        return float(u) + 0.04 * float(sh) + 0.02 * float(so) - 0.10 * float(dd0) - 0.25 * float(tl)

    score_strategy = _score_for("strategy", metrics)
    score_quant = _score_for("quant", metrics)
    if sys == "strategy":
        score = float(score_strategy)
    elif sys == "quant":
        score = float(score_quant)
    elif sys == "risk":
        score = float(_score_for("risk", metrics))
    else:
        score = float(0.5 * float(score_strategy) + 0.5 * float(score_quant))
        if baseline is not None and isinstance(baseline, dict) and bool(baseline.get("ok")):
            b_score_strategy = _score_for("strategy", baseline)
            b_score_quant = _score_for("quant", baseline)
            if float(score_strategy) < float(b_score_strategy) or float(score_quant) < float(b_score_quant):
                return -1e18, {
                    "reason": "hard_constraint_cross_system_harm",
                    "candidate": {"strategy": float(score_strategy), "quant": float(score_quant)},
                    "baseline": {"strategy": float(b_score_strategy), "quant": float(b_score_quant)},
                }
    if cov < 0.02:
        score -= 1.0
    return score, {
        "system": sys,
        "gate_relaxed": bool(gate_relaxed),
        "score_strategy": float(score_strategy),
        "score_quant": float(score_quant),
        "uplift": uplift,
        "mean_return": float(mean_return),
        "calmar_like": float(calmar_like),
        "sharpe": sharpe,
        "sortino": sortino,
        "maxdd": maxdd,
        "tail_loss_p95": tail,
        "coverage": cov,
        "avg_trades": trades,
        "trades_per_day": tpd,
        "tpd_cap": tpd_cap,
    }


def _paramopt_eval_extract_backtest(res: Dict[str, Any]) -> Dict[str, Any]:
    ok = bool(res.get("ok"))
    ms = res.get("metrics_summary") if isinstance(res.get("metrics_summary"), dict) else {}
    out: Dict[str, Any] = {
        "ok": ok,
        "error": res.get("error"),
        "metrics_summary": ms,
        "result_zip": res.get("result_zip"),
    }
    if ok:
        zip_name = str(out.get("result_zip") or "").strip()
        if zip_name:
            try:
                zip_path = _backtests_dir() / zip_name
                trades = _backtest_zip_strategy_trades(zip_path, strategy=None) or []
            except Exception:
                trades = []

            pnls: List[float] = []
            hold_ms_list: List[int] = []
            retraces: List[float] = []
            for t in trades:
                if not isinstance(t, dict):
                    continue
                try:
                    pr = float(t.get("profit_ratio") or 0.0)
                except Exception:
                    pr = 0.0
                if math.isfinite(float(pr)):
                    pnls.append(float(pr))

                try:
                    ot = t.get("open_timestamp")
                    ct = t.get("close_timestamp")
                    if ot is not None and ct is not None:
                        d = int(ct) - int(ot)
                        if d >= 0:
                            hold_ms_list.append(int(d))
                    else:
                        td = t.get("trade_duration")
                        if td is not None:
                            d = int(td) * 60 * 1000
                            if d >= 0:
                                hold_ms_list.append(int(d))
                except Exception:
                    pass

                try:
                    if float(pr) <= 0.0:
                        continue
                    is_short = bool(t.get("is_short", False))
                    mfe = None
                    if t.get("max_profit_ratio") is not None:
                        try:
                            v = float(t.get("max_profit_ratio"))
                            mfe = (v if math.isfinite(float(v)) else None)
                        except Exception:
                            mfe = None
                    if mfe is None:
                        try:
                            open_rate = float(t.get("open_rate") or 0.0)
                        except Exception:
                            open_rate = 0.0
                        if open_rate > 0.0 and math.isfinite(float(open_rate)):
                            if is_short:
                                try:
                                    min_rate = float(t.get("min_rate") or 0.0)
                                except Exception:
                                    min_rate = 0.0
                                if min_rate > 0.0 and math.isfinite(float(min_rate)):
                                    mfe = float(open_rate) / float(min_rate) - 1.0
                            else:
                                try:
                                    max_rate = float(t.get("max_rate") or 0.0)
                                except Exception:
                                    max_rate = 0.0
                                if max_rate > 0.0 and math.isfinite(float(max_rate)):
                                    mfe = float(max_rate) / float(open_rate) - 1.0
                    if mfe is None or (not math.isfinite(float(mfe))) or float(mfe) <= 0.0:
                        continue
                    retr = (float(mfe) - float(pr)) / float(max(1e-12, abs(float(mfe))))
                    if math.isfinite(float(retr)):
                        retraces.append(float(max(0.0, min(1.0, float(retr)))))
                except Exception:
                    pass

            tail_loss_p95 = 0.0
            if pnls:
                pnls_sorted = sorted(pnls)
                i = int(round(0.05 * float(max(0, len(pnls_sorted) - 1))))
                i = max(0, min(len(pnls_sorted) - 1, int(i)))
                q05 = float(pnls_sorted[i])
                tail_loss_p95 = float(max(0.0, -float(q05)))

            days = None
            try:
                v = ms.get("backtest_days")
                if v is not None:
                    days = float(v)
            except Exception:
                days = None
            if days is None or (not math.isfinite(float(days))) or float(days) <= 0.0:
                try:
                    a = int(ms.get("backtest_start_ts") or 0)
                    b = int(ms.get("backtest_end_ts") or 0)
                    if a > 0 and b > a:
                        days = float(b - a) / (24.0 * 3600.0 * 1000.0)
                except Exception:
                    days = None
            trades_per_day = None
            if days is not None and math.isfinite(float(days)) and float(days) > 0.0:
                trades_per_day = float(len(trades)) / float(days)

            ms2 = dict(ms)
            ms2["tail_loss_p95"] = float(tail_loss_p95)
            if hold_ms_list:
                try:
                    avg_hold_ms = float(sum(hold_ms_list)) / float(len(hold_ms_list))
                    if math.isfinite(float(avg_hold_ms)):
                        ms2["avg_hold_ms"] = float(avg_hold_ms)
                        ms2["avg_hold_min"] = float(avg_hold_ms) / (60.0 * 1000.0)
                except Exception:
                    pass

            if retraces:
                try:
                    rs = sorted([float(x) for x in retraces if math.isfinite(float(x))])
                except Exception:
                    rs = []
                if rs:
                    def _q(frac: float) -> float:
                        j = int(round(float(frac) * float(max(0, len(rs) - 1))))
                        j = max(0, min(len(rs) - 1, int(j)))
                        return float(rs[j])
                    try:
                        ms2["mfe_to_final_retrace"] = {
                            "n": int(len(rs)),
                            "mean": float(sum(rs) / float(len(rs))),
                            "p50": _q(0.50),
                            "p75": _q(0.75),
                            "p90": _q(0.90),
                            "p95": _q(0.95),
                            "max": float(rs[-1]),
                        }
                    except Exception:
                        pass
            if trades_per_day is not None:
                ms2["trades_per_day"] = float(trades_per_day)
            out["metrics_summary"] = ms2
    return out


def _paramopt_sample_gate_7d(*, eval_mode: str, baseline: Dict[str, Any], min_trades_7d: int, min_effective_days_7d: int) -> Dict[str, Any]:
    em = str(eval_mode or "").strip().lower()
    try:
        mt = int(min_trades_7d)
    except Exception:
        mt = 0
    try:
        md = int(min_effective_days_7d)
    except Exception:
        md = 0
    mt = max(0, min(100000, int(mt)))
    md = max(0, min(7, int(md)))
    sample = {
        "eval_mode": em,
        "min_trades_7d": int(mt),
        "min_effective_days_7d": int(md),
        "trades_7d": 0.0,
        "effective_days_7d": 0.0,
    }
    if not isinstance(baseline, dict) or (not bool(baseline.get("ok"))):
        return {"ok": False, "pass": False, "reason": "baseline_not_ok", "sample": sample}
    if em == "backtest":
        ms = baseline.get("metrics_summary") if isinstance(baseline.get("metrics_summary"), dict) else {}
        try:
            tpd = float(ms.get("trades_per_day") or 0.0)
        except Exception:
            tpd = 0.0
        try:
            bdays = float(ms.get("backtest_days") or 0.0)
        except Exception:
            bdays = 0.0
        sample["trades_7d"] = float(max(0.0, float(tpd)) * 7.0)
        sample["effective_days_7d"] = float(max(0.0, min(7.0, float(bdays))))
    else:
        st = baseline.get("stressed") if isinstance(baseline.get("stressed"), dict) else {}
        try:
            tpd = float(st.get("trades_per_day") or 0.0)
        except Exception:
            tpd = 0.0
        try:
            cov = float(st.get("coverage") or 0.0)
        except Exception:
            cov = 0.0
        cov = max(0.0, min(1.0, float(cov)))
        sample["trades_7d"] = float(max(0.0, float(tpd)) * 7.0)
        sample["effective_days_7d"] = float(cov * 7.0)
    pass_trades = (float(sample["trades_7d"]) >= float(mt)) if int(mt) > 0 else True
    pass_days = (float(sample["effective_days_7d"]) >= float(md)) if int(md) > 0 else True
    reasons: List[str] = []
    if not pass_trades:
        reasons.append("min_trades_7d")
    if not pass_days:
        reasons.append("min_effective_days_7d")
    return {
        "ok": True,
        "pass": bool(pass_trades and pass_days),
        "reason": ("insufficient_sample" if reasons else None),
        "reason_codes": reasons,
        "sample": sample,
    }


def _paramopt_score_backtest(metrics: Dict[str, Any], *, baseline: Optional[Dict[str, Any]] = None, system: str = "mixed") -> Tuple[float, Dict[str, Any]]:
    if not bool(metrics.get("ok")):
        return -1e18, {"reason": "eval_not_ok", "error": metrics.get("error")}
    ms = metrics.get("metrics_summary") if isinstance(metrics.get("metrics_summary"), dict) else {}
    pf = _to_float(ms.get("profit_factor")) or 0.0
    calmar = _to_float(ms.get("calmar")) or 0.0
    sharpe = _to_float(ms.get("sharpe")) or 0.0
    sortino = _to_float(ms.get("sortino")) or 0.0
    dd = _norm_dd_pct(ms.get("max_drawdown_account")) or 0.0
    trades = _to_int(ms.get("trades")) or 0
    tail = _to_float(ms.get("tail_loss_p95")) or 0.0
    tpd = _to_float(ms.get("trades_per_day"))

    if baseline is not None and isinstance(baseline, dict) and bool(baseline.get("ok")):
        bms = baseline.get("metrics_summary") if isinstance(baseline.get("metrics_summary"), dict) else {}
        bdd = _norm_dd_pct(bms.get("max_drawdown_account"))
        btr = _to_int(bms.get("trades"))
        if bdd is not None and float(bdd) > 0 and float(dd) > 1.10 * float(bdd):
            return -1e18, {"reason": "hard_constraint_maxdd", "maxdd": dd, "baseline_maxdd": bdd}
        if btr is not None and int(btr) > 0 and int(trades) < int(float(btr) * 0.70):
            return -1e18, {"reason": "hard_constraint_trades", "trades": trades, "baseline_trades": btr}
        btail = _to_float(bms.get("tail_loss_p95"))
        if btail is not None and float(btail) > 0.0 and float(tail) > 1.10 * float(btail):
            return -1e18, {"reason": "hard_constraint_tail_loss_p95", "tail_loss_p95": tail, "baseline_tail_loss_p95": float(btail)}
        btpd = _to_float(bms.get("trades_per_day"))
        if btpd is not None and tpd is not None and float(btpd) > 0.0 and float(tpd) > float(btpd) * 1.50:
            return -1e18, {"reason": "hard_constraint_trades_per_day", "trades_per_day": float(tpd), "baseline_trades_per_day": float(btpd)}

    try:
        tpd_cap = CONFIG.get("paramopt_max_trades_per_day")
        tpd_cap = (None if tpd_cap is None else float(tpd_cap))
    except Exception:
        tpd_cap = None
    if tpd_cap is not None and tpd is not None:
        if math.isfinite(float(tpd_cap)) and float(tpd_cap) > 0.0 and math.isfinite(float(tpd)) and float(tpd) > float(tpd_cap):
            return -1e18, {"reason": "hard_constraint_trades_per_day_cap", "trades_per_day": float(tpd), "cap": float(tpd_cap)}

    min_trades = 30
    try:
        min_trades = int(CONFIG.get("paramopt_backtest_min_trades", 30) or 30)
    except Exception:
        min_trades = 30
    min_trades = max(0, min(5000, int(min_trades)))
    t_pen = 0.0
    if int(trades) < int(min_trades):
        t_pen = float(int(min_trades) - int(trades)) / float(max(1, int(min_trades)))

    sys = str(system or "mixed").strip().lower() or "mixed"
    if sys not in ("strategy", "quant", "mixed", "risk"):
        sys = "mixed"
    def _score_for(sys0: str, ms0: Dict[str, Any]) -> float:
        pf0 = _to_float(ms0.get("profit_factor")) or 0.0
        cal0 = _to_float(ms0.get("calmar")) or 0.0
        sh0 = _to_float(ms0.get("sharpe")) or 0.0
        so0 = _to_float(ms0.get("sortino")) or 0.0
        ddx = _norm_dd_pct(ms0.get("max_drawdown_account")) or 0.0
        tl0 = _to_float(ms0.get("tail_loss_p95")) or 0.0
        tr0 = _to_int(ms0.get("trades")) or 0
        t_pen0 = 0.0
        if int(tr0) < int(min_trades):
            t_pen0 = float(int(min_trades) - int(tr0)) / float(max(1, int(min_trades)))
        if sys0 == "strategy":
            return float(1.0 * pf0 + 1.2 * cal0 + 0.3 * so0 + 0.1 * sh0 - 2.2 * float(ddx) - 0.35 * t_pen0 - 0.55 * float(tl0))
        if sys0 == "quant":
            return float(0.8 * pf0 + 0.3 * cal0 + 1.0 * so0 + 0.7 * sh0 - 2.0 * float(ddx) - 0.35 * t_pen0 - 0.55 * float(tl0))
        if sys0 == "risk":
            return float(0.2 * pf0 + 0.2 * cal0 + 0.2 * so0 + 0.1 * sh0 - 3.0 * float(ddx) - 0.50 * t_pen0 - 1.00 * float(tl0))
        return float(1.6 * pf0 + 0.6 * cal0 + 0.2 * sh0 - 1.8 * float(ddx) - 0.35 * t_pen0 - 0.45 * float(tl0))

    score_strategy = _score_for("strategy", ms)
    score_quant = _score_for("quant", ms)
    if sys == "strategy":
        score = float(score_strategy)
    elif sys == "quant":
        score = float(score_quant)
    elif sys == "risk":
        score = float(_score_for("risk", ms))
    else:
        score = float(0.5 * float(score_strategy) + 0.5 * float(score_quant))
        if baseline is not None and isinstance(baseline, dict) and bool(baseline.get("ok")):
            bms = baseline.get("metrics_summary") if isinstance(baseline.get("metrics_summary"), dict) else {}
            b_score_strategy = _score_for("strategy", bms)
            b_score_quant = _score_for("quant", bms)
            if float(score_strategy) < float(b_score_strategy) or float(score_quant) < float(b_score_quant):
                return -1e18, {
                    "reason": "hard_constraint_cross_system_harm",
                    "candidate": {"strategy": float(score_strategy), "quant": float(score_quant)},
                    "baseline": {"strategy": float(b_score_strategy), "quant": float(b_score_quant)},
                }
    return score, {
        "system": sys,
        "score_strategy": float(score_strategy),
        "score_quant": float(score_quant),
        "profit_factor": pf,
        "calmar": calmar,
        "sortino": sortino,
        "sharpe": sharpe,
        "maxdd": dd,
        "tail_loss_p95": tail,
        "trades": trades,
        "trades_per_day": tpd,
        "min_trades": min_trades,
    }


def _paramopt_apply_cfg_patch_temporarily(patch: Dict[str, Any]) -> Dict[str, Any]:
    prev: Dict[str, Any] = {}
    for k, v in (patch or {}).items():
        kk = str(k)
        if not kk:
            continue
        try:
            prev[kk] = CONFIG.get(kk)
        except Exception:
            prev[kk] = None
        try:
            CONFIG[kk] = v
        except Exception:
            pass
    return prev


def _paramopt_restore_cfg(prev: Dict[str, Any]) -> None:
    for k, v in (prev or {}).items():
        try:
            if v is None and k not in CONFIG:
                continue
            CONFIG[k] = v
        except Exception:
            pass


def _paramopt_pick_default_keys(items: List[Dict[str, Any]], *, scopes: Optional[List[str]] = None, score_system: Optional[str] = None, preset: Optional[str] = None) -> List[str]:
    scope_set = set()
    try:
        scope_set = set([str(s).strip().lower() for s in (scopes or []) if str(s).strip()])
    except Exception:
        scope_set = set()

    sys0 = str(score_system or "").strip().lower()
    if sys0 not in ("strategy", "quant", "mixed", "risk"):
        sys0 = ""
    if not sys0:
        if ("overlay" in scope_set) and ("strategy" not in scope_set) and ("quant" not in scope_set):
            sys0 = "risk"
        elif ("quant" in scope_set) and ("strategy" not in scope_set):
            sys0 = "quant"
        elif "quant" not in scope_set:
            sys0 = "strategy"
        else:
            sys0 = "mixed"

    items_ok = [it for it in (items or []) if isinstance(it, dict)]
    items_ok = [it for it in items_ok if str(it.get("key") or "").strip()]
    items_ok = [it for it in items_ok if str(it.get("type") or "").strip().lower() in ("int", "float", "bool")]

    keys_all = [str(it.get("key") or "").strip() for it in items_ok]
    keys_set = set(keys_all)

    entry_gate_pref = [
        "signals_dedup_ttl_sec",
        "signals_dedup_bucket_sec",
        "signals_pair_side_cooldown_sec",
        "signals_coin_side_cooldown_sec",
        "entry_inflight_cooldown_sec",
        "pc_hysteresis_delta",
        "signals_v1_confirm_enabled",
        "signals_v1_confirm_n",
        "signals_v1_confirm_m",
    ]

    risk_exec_pref = [
        "serving_shadow_mode",
        "serving_canary_enabled",
        "serving_canary_size_frac",
        "max_orders_per_minute",
        "order_rate_window_sec",
        "max_open_trades",
        "addon_entry_max_count",
        "addon_entry_min_interval_sec",
        "max_daily_loss",
        "max_weekly_loss",
    ]

    def _strategy_pack_prefixes() -> List[str]:
        prefs = set()
        for kk in keys_all:
            if len(kk) >= 5 and kk[0].lower() == "s" and kk[1:4].isdigit() and kk[4] == "_":
                prefs.add(kk[:5])
        return sorted(prefs)

    def _strategy_signal_keys() -> List[str]:
        out0: List[str] = []
        seen0 = set()
        for pref0 in _strategy_pack_prefixes():
            for kk in keys_all:
                if kk.startswith(pref0) and kk not in seen0:
                    seen0.add(kk)
                    out0.append(kk)
        for kk in keys_all:
            if kk.startswith(("threshold_", "regime_", "rh_", "regime_hybrid_")) and kk not in seen0:
                seen0.add(kk)
                out0.append(kk)
        return out0

    def _is_quant_exitish_key(kk: str) -> bool:
        k0 = str(kk or "").strip().lower()
        if not k0:
            return False
        if "exit" in k0:
            return True
        if "stop" in k0:
            return True
        if "_pnl_" in k0:
            return True
        return False

    def _quant_core_keys() -> List[str]:
        def _is_quant_exec_or_risk_key(kk: str) -> bool:
            k0 = str(kk or "").strip().lower()
            if not k0:
                return True
            if "wfo_" in k0:
                return True
            if "notional" in k0:
                return True
            if "init_equity" in k0:
                return True
            if "max_open" in k0:
                return True
            if "max_daily_loss" in k0 or "max_weekly_loss" in k0:
                return True
            if "loss_limit" in k0:
                return True
            if "net_btc" in k0:
                return True
            if "state_check_interval" in k0:
                return True
            if "max_trade" in k0:
                return True
            if "maker_timeout" in k0:
                return True
            if "max_hold" in k0:
                return True
            if "emergency_close" in k0:
                return True
            if "capacity_" in k0:
                return True
            if "circuit_breaker" in k0:
                return True
            if "risk_budget" in k0:
                return True
            if "universe_consistency" in k0:
                return True
            if "cluster_" in k0:
                return True
            if "max_pairs" in k0:
                return True
            if "timeframe" in k0:
                return True
            if "risk_weight_mode" in k0:
                return True
            if k0.endswith("_enabled") or ("_enabled_" in k0) or (k0.endswith("_enabled")) or ("_enabled" in k0):
                return True
            if "live_trading" in k0:
                return True
            return False

        corr = [k for k in keys_all if k.startswith("correlation_") and not _is_quant_exec_or_risk_key(k)]
        pairs = [k for k in keys_all if k.startswith("quant_pairs_") and (not _is_quant_exitish_key(k)) and (not _is_quant_exec_or_risk_key(k))]
        auto = [k for k in keys_all if k.startswith("quant_auto_") and not _is_quant_exec_or_risk_key(k)]
        misc = [k for k in keys_all if k.startswith("quant_") and (not k.startswith("quant_pairs_")) and (not k.startswith("quant_auto_")) and (not _is_quant_exec_or_risk_key(k))]

        def _pair_sort_key(k: str) -> Any:
            k0 = k.lower()
            if "entry_inflight" in k0:
                return (-1, 0, k0)
            a = 0 if "btceth" in k0 else (1 if "btcalt" in k0 else 2)
            b = 0 if ("gate" in k0 or "entry" in k0) else 1
            return (a, b, k0)

        corr = sorted(corr, key=lambda x: x.lower())
        pairs = sorted(pairs, key=_pair_sort_key)
        auto = sorted(auto, key=lambda x: x.lower())
        misc = sorted(misc, key=lambda x: x.lower())

        out0: List[str] = []
        seen0 = set()
        for kk in (corr + pairs + auto + misc):
            if kk not in seen0:
                seen0.add(kk)
                out0.append(kk)
        return out0

    macro_pref = [
        "macro_gate_enabled",
        "macro_gate_priority_threshold",
        "macro_gate_pass_threshold",
        "macro_gate_min_confidence",
        "macro_gate_strategy_block_min_conf",
        "macro_gate_strategy_close_min_conf",
        "macro_gate_data_quality_min",
        "macro_gate_data_quality_disable_below",
        "entry_macro_btceth_hard_gate_enabled",
        "entry_macro_btceth_hard_gate_auto_period_seconds",
        "entry_macro_btceth_hard_gate_auto_unlock_cooldown_hours",
    ]

    prefer: List[str] = []
    max_keys = 12
    preset0 = str(preset or "").strip().lower()
    if preset0 in ("o1", "o2", "o3", "o4", "o5", "o6", "o7"):
        if preset0 == "o1":
            sys0 = "strategy"
            max_keys = 32
            prefer = _strategy_signal_keys() + entry_gate_pref
        elif preset0 == "o2":
            sys0 = "quant"
            max_keys = 28
            prefer = _quant_core_keys() + entry_gate_pref
        elif preset0 == "o3":
            sys0 = "risk"
            max_keys = 18
            prefer = macro_pref + [k for k in keys_all if k.lower().startswith(("macro_", "entry_macro_"))]
        elif preset0 == "o4":
            sys0 = "risk"
            max_keys = 24
            prefer = [k for k in keys_all if k.lower().startswith("exit_")]
        elif preset0 == "o5":
            sys0 = "risk"
            max_keys = 24
            prefer = [k for k in keys_all if k.startswith("quant_pairs_") and _is_quant_exitish_key(k)]
        elif preset0 == "o6":
            sys0 = "risk"
            max_keys = 24
            prefer = []
            for k in risk_exec_pref:
                prefer.append(k)
            for k in keys_all:
                k0 = k.lower()
                if k.startswith(("s", "threshold_", "regime_", "rh_", "regime_hybrid_")):
                    continue
                if k.startswith("quant_pairs_"):
                    continue
                if k.startswith("exit_"):
                    continue
                if k.startswith(("signals_", "serving_", "addon_entry_")):
                    prefer.append(k)
                    continue
                if "notional" in k0 or "leverage" in k0:
                    prefer.append(k)
                    continue
                if "max_open" in k0 or "max_orders" in k0:
                    prefer.append(k)
                    continue
                if "loss" in k0 or "circuit_breaker" in k0 or "capacity_" in k0 or "risk_budget" in k0:
                    prefer.append(k)
                    continue
                if "cooldown" in k0 or "dedup" in k0:
                    prefer.append(k)
                    continue
            if entry_gate_pref:
                prefer.extend(entry_gate_pref)
    if not prefer:
        preset0 = ""
    preset_active = bool(preset0) and bool(prefer)
    if not preset_active:
        if sys0 == "risk":
            max_keys = 16
            prefer = macro_pref + entry_gate_pref + risk_exec_pref
        elif sys0 == "quant":
            max_keys = 28
            prefer = _quant_core_keys() + entry_gate_pref
        elif sys0 == "strategy":
            max_keys = 32
            prefer = _strategy_signal_keys() + entry_gate_pref
        else:
            max_keys = 16
            prefer = _strategy_signal_keys() + _quant_core_keys() + entry_gate_pref + risk_exec_pref

    out: List[str] = []
    seen = set()
    for k in prefer:
        if k in keys_set and k not in seen:
            seen.add(k)
            out.append(k)
        if len(out) >= max_keys:
            break

    if len(out) < 6:
        def _is_strategy_pack_key(kk: str) -> bool:
            s = str(kk or "").strip()
            if not s:
                return False
            if s.startswith("strategy_"):
                return True
            if s.startswith(("rh_", "regime_hybrid_")):
                return True
            if len(s) >= 5 and s[0].lower() == "s" and s[1:4].isdigit() and s[4] == "_":
                return True
            return False
        for k in keys_all:
            if k in seen:
                continue
            if sys0 == "quant" and _is_strategy_pack_key(k):
                continue
            if sys0 == "risk" and (_is_strategy_pack_key(k) or k.startswith(("quant_", "quant_pairs_"))):
                continue
            seen.add(k)
            out.append(k)
            if len(out) >= max_keys:
                break

    return out[:max_keys] if out else keys_all[:8]


def _paramopt_partition_patch_by_apply_mode(patch: Dict[str, Any], *, items_by_key: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    apply_patch: Dict[str, Any] = {}
    suggest: Dict[str, Any] = {}
    for k, v in (patch or {}).items():
        kk = str(k or "").strip()
        if not kk:
            continue
        it = items_by_key.get(kk) if isinstance(items_by_key, dict) else None
        mode = str((it or {}).get("apply_mode") or "").strip().lower()
        if mode == "suggest-only":
            suggest[kk] = v
        else:
            apply_patch[kk] = v
    return {"config_patch": apply_patch, "config_suggest": suggest}


def _paramopt_topk_from_history(history: List[Dict[str, Any]], *, k: int) -> List[Dict[str, Any]]:
    if not isinstance(history, list) or not history:
        return []
    kk = max(1, min(50, int(k)))
    items = []
    for h in history:
        if not isinstance(h, dict):
            continue
        sc = h.get("score")
        mt = h.get("metrics") if isinstance(h.get("metrics"), dict) else {}
        if sc is None:
            continue
        try:
            scf = float(sc)
        except Exception:
            continue
        patch = h.get("patch") if isinstance(h.get("patch"), dict) else {}
        if not patch:
            continue
        items.append({"score": scf, "patch": patch, "metrics": mt, "meta": (h.get("meta") if isinstance(h.get("meta"), dict) else {}), "raw": h})
    items.sort(key=lambda x: float(x.get("score") or -1e18), reverse=True)
    out: List[Dict[str, Any]] = []
    seen = set()
    for it in items:
        try:
            sig = json.dumps(it.get("patch") or {}, sort_keys=True, ensure_ascii=False)
        except Exception:
            sig = str(it.get("patch"))
        if sig in seen:
            continue
        seen.add(sig)
        out.append(it)
        if len(out) >= kk:
            break
    return out


def _paramopt_timerange_split_v1(timerange: str, *, is_frac: float = 0.80, embargo_days: int = 0) -> Dict[str, Optional[str]]:
    tr = str(timerange or "").strip()
    if not tr or "-" not in tr:
        return {"is": None, "oos": None, "embargo_days": int(embargo_days)}
    parts = tr.split("-", 1)
    if len(parts) != 2:
        return {"is": None, "oos": None, "embargo_days": int(embargo_days)}
    s0 = parts[0].strip()
    s1 = parts[1].strip()
    if len(s0) != 8 or len(s1) != 8:
        return {"is": None, "oos": None, "embargo_days": int(embargo_days)}
    try:
        dt0 = datetime.datetime.strptime(s0, "%Y%m%d")
        dt1 = datetime.datetime.strptime(s1, "%Y%m%d")
    except Exception:
        return {"is": None, "oos": None, "embargo_days": int(embargo_days)}
    if dt1 <= dt0:
        return {"is": None, "oos": None, "embargo_days": int(embargo_days)}
    frac = float(max(0.50, min(0.95, float(is_frac))))
    total_days = max(1, int((dt1 - dt0).days))
    is_days = max(1, min(total_days - 1, int(round(total_days * frac))))
    is_end = dt0 + datetime.timedelta(days=int(is_days))
    emb = max(0, min(3650, int(embargo_days)))
    oos_start = is_end + datetime.timedelta(days=int(emb))
    is_tr = dt0.strftime("%Y%m%d") + "-" + is_end.strftime("%Y%m%d")
    if oos_start >= dt1:
        return {"is": is_tr, "oos": None, "embargo_days": int(emb)}
    oos_tr = oos_start.strftime("%Y%m%d") + "-" + dt1.strftime("%Y%m%d")
    return {"is": is_tr, "oos": oos_tr, "embargo_days": int(emb)}


def _paramopt_cost_sensitivity_gate_eval(robust: Any) -> Dict[str, Any]:
    try:
        enabled = bool(CONFIG.get("paramopt_cost_gate_enabled", True))
    except Exception:
        enabled = True
    try:
        require_sensitivity = bool(CONFIG.get("paramopt_cost_gate_require_sensitivity", True))
    except Exception:
        require_sensitivity = True
    if not enabled:
        return {"enabled": False, "pass": True, "sufficient": False}
    if not isinstance(robust, dict) or (not bool(robust.get("ok"))):
        return {"enabled": True, "pass": False, "sufficient": False, "reason": "robust_missing"}

    sens = robust.get("sensitivity") if isinstance(robust.get("sensitivity"), dict) else None
    if not isinstance(sens, dict):
        if require_sensitivity:
            return {"enabled": True, "pass": False, "sufficient": False, "reason": "no_sensitivity"}
        return {"enabled": True, "pass": True, "sufficient": False, "reason": "no_sensitivity"}
    grid = sens.get("grid") if isinstance(sens.get("grid"), list) else None
    x = sens.get("x") if isinstance(sens.get("x"), dict) else {}
    y = sens.get("y") if isinstance(sens.get("y"), dict) else {}
    x_vals = x.get("values") if isinstance(x.get("values"), list) else []
    y_vals = y.get("values") if isinstance(y.get("values"), list) else []
    if not grid or not x_vals or not y_vals:
        if require_sensitivity:
            return {"enabled": True, "pass": False, "sufficient": False, "reason": "no_grid"}
        return {"enabled": True, "pass": True, "sufficient": False, "reason": "no_grid"}

    try:
        fee0 = float(((robust.get("assumptions") or {}) if isinstance(robust.get("assumptions"), dict) else {}).get("fee_rate") or 0.0)
    except Exception:
        fee0 = 0.0

    def _closest_idx(vals: List[Any], target: float) -> int:
        best_i = 0
        best_d = None
        for i, v in enumerate(vals):
            try:
                f = float(v)
            except Exception:
                continue
            d = abs(float(f) - float(target))
            if best_d is None or d < float(best_d):
                best_d = float(d)
                best_i = int(i)
        return int(best_i)

    ix0 = _closest_idx(x_vals, 0.0)
    iy0 = _closest_idx(y_vals, float(fee0))
    ix_stress = _closest_idx(x_vals, float(max([float(v) for v in x_vals if isinstance(v, (int, float))] or [0.0])))
    iy_stress = _closest_idx(y_vals, float(max([float(v) for v in y_vals if isinstance(v, (int, float))] or [0.0])))

    def _cell(j: int, i: int) -> Optional[float]:
        try:
            row = grid[j]
            if not isinstance(row, list):
                return None
            v = row[i]
            if v is None:
                return None
            f = float(v)
            return f if math.isfinite(float(f)) else None
        except Exception:
            return None

    base_score = _cell(int(iy0), int(ix0))
    stress_score = _cell(int(iy_stress), int(ix_stress))
    all_vals: List[float] = []
    for row in grid:
        if not isinstance(row, list):
            continue
        for v in row:
            try:
                if v is None:
                    continue
                f = float(v)
                if math.isfinite(float(f)):
                    all_vals.append(float(f))
            except Exception:
                continue
    worst_all = min(all_vals) if all_vals else None

    try:
        max_drop_frac = float(CONFIG.get("paramopt_cost_gate_max_drop_frac", 0.80) or 0.80)
    except Exception:
        max_drop_frac = 0.80
    max_drop_frac = float(max(0.0, min(1.0, float(max_drop_frac))))

    sufficient = (base_score is not None and stress_score is not None)
    if not sufficient:
        if require_sensitivity:
            return {
                "enabled": True,
                "pass": False,
                "sufficient": False,
                "base": {"score": base_score, "x": x_vals[ix0] if ix0 < len(x_vals) else None, "y": y_vals[iy0] if iy0 < len(y_vals) else None},
                "stress": {"score": stress_score, "x": x_vals[ix_stress] if ix_stress < len(x_vals) else None, "y": y_vals[iy_stress] if iy_stress < len(y_vals) else None},
                "worst_all": worst_all,
            }
        return {
            "enabled": True,
            "pass": True,
            "sufficient": False,
            "base": {"score": base_score, "x": x_vals[ix0] if ix0 < len(x_vals) else None, "y": y_vals[iy0] if iy0 < len(y_vals) else None},
            "stress": {"score": stress_score, "x": x_vals[ix_stress] if ix_stress < len(x_vals) else None, "y": y_vals[iy_stress] if iy_stress < len(y_vals) else None},
            "worst_all": worst_all,
        }

    base = float(base_score)
    stress = float(stress_score)
    denom = max(1e-9, abs(float(base)))
    drop_frac = (float(base) - float(stress)) / float(denom)
    sign_flip = (float(base) > 0.0 and float(stress) < 0.0)
    passed = (not sign_flip) and (float(drop_frac) <= float(max_drop_frac))
    return {
        "enabled": True,
        "pass": bool(passed),
        "sufficient": True,
        "base": {"score": float(base), "x": x_vals[ix0] if ix0 < len(x_vals) else None, "y": y_vals[iy0] if iy0 < len(y_vals) else None},
        "stress": {"score": float(stress), "x": x_vals[ix_stress] if ix_stress < len(x_vals) else None, "y": y_vals[iy_stress] if iy_stress < len(y_vals) else None},
        "worst_all": worst_all,
        "drop_frac": float(drop_frac),
        "max_drop_frac": float(max_drop_frac),
        "sign_flip": bool(sign_flip),
    }


def _paramopt_exec_quality_gate_eval(*, baseline_ofr: Any, ofr_days: int, ofr_delta: float) -> Dict[str, Any]:
    try:
        base = (None if baseline_ofr is None else float(baseline_ofr))
    except Exception:
        base = None
    days = max(1, min(30, int(ofr_days)))
    try:
        delta = float(ofr_delta)
    except Exception:
        delta = 0.03
    delta = max(0.0, min(0.50, float(delta)))

    exec_quality = None
    cur = None
    try:
        start_ms = int(_now_ms()) - int(days) * 24 * 60 * 60 * 1000
        exec_quality = _audit_execution_quality(start_ts_ms=int(start_ms), end_ts_ms=int(_now_ms()), pair=None, strategy_id=None, max_points=200000, include_shadow=False)
        if isinstance(exec_quality, dict):
            v = exec_quality.get("order_fail_rate")
            cur = (None if v is None else float(v))
    except Exception:
        exec_quality = None
        cur = None

    sufficient = (base is not None) and (cur is not None)
    passed = True
    if sufficient:
        passed = bool(float(cur) <= float(base) + float(delta))
    return {
        "ok": True,
        "pass": bool(passed),
        "sufficient": bool(sufficient),
        "metrics": {"order_fail_rate": cur, "baseline_order_fail_rate": base, "days": int(days)},
        "thresholds": {"baseline_ofr_delta": float(delta)},
        "evidence": exec_quality,
    }


