@app.route("/automation/paramopt/explore/trigger", methods=["POST"])
def automation_paramopt_explore_trigger():
    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    confirm_live = bool(data.get("confirm_live", False))
    if (not _is_local_request()) and (not bool(confirm_live)):
        return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms())}), 400
    if not bool(AUTOMATION.get("enable_shadow_automation_loop", False)):
        return jsonify({"ok": False, "error": "shadow_required_for_paramopt", "ts": int(_now_ms())}), 400
    if not bool(AUTOMATION.get("enable_paramopt_daily", False)):
        return jsonify({"ok": False, "error": "paramopt_not_enabled", "ts": int(_now_ms())}), 400
    if not bool(AUTOMATION.get("paramopt_explore_cycle_enabled", True)):
        return jsonify({"ok": False, "error": "paramopt_explore_cycle_disabled", "ts": int(_now_ms())}), 400

    now_ms = int(_now_ms())
    run_sync = bool(app.testing or CONFIG.get("outbox_allow_test_mode", False))
    if run_sync:
        rep = _automation_paramopt_explore_cycle_run(int(now_ms))
        code = 200 if bool(rep.get("ok")) else 400
        return jsonify(_json_sanitize(rep)), int(code)

    def _bg() -> None:
        with app.app_context():
            try:
                _automation_paramopt_explore_cycle_run(int(_now_ms()))
            except Exception:
                pass

    try:
        t = threading.Thread(target=_bg, daemon=True)
        t.start()
    except Exception:
        return jsonify({"ok": False, "error": "thread_start_failed", "ts": int(_now_ms())}), 500
    return jsonify({"ok": True, "queued": True, "trigger": "strategy.explore.cycle.trigger", "ts": int(now_ms)}), 202


