@app.route("/automation/gtw/run", methods=["POST"])
def automation_gtw_run():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    try:
        force = bool(data.get("force", False))
    except Exception:
        force = False
    trigger_event = (None if data.get("trigger_event") is None else str(data.get("trigger_event") or "").strip()) or None
    force_path_ids = data.get("force_path_ids") if isinstance(data.get("force_path_ids"), list) else None
    rep = _gtw_run_once(now_ms=int(_now_ms()), polling_kind=("event" if trigger_event else "poll"), trigger_event=trigger_event, force=bool(force), force_path_ids=(force_path_ids if isinstance(force_path_ids, list) else None))
    return jsonify(rep), (200 if bool(rep.get("ok")) else 400)


