@app.route("/agent/automation/web3_market_digest", methods=["GET", "POST"])
def agent_automation_web3_market_digest():
    if str(request.method or "").upper() == "POST":
        if not _agent_sandbox_task_auth_ok():
            return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
        data = request.get_json(force=True) or {}
        try:
            force = bool(data.get("force", False))
        except Exception:
            force = False
        trigger_event = (None if data.get("trigger_event") is None else str(data.get("trigger_event") or "").strip()) or None
        rep = _automation_web3_market_digest_run(int(_now_ms()), force=bool(force), trigger_event=(trigger_event or "manual"), source="manual")
        return jsonify(rep), (200 if bool(rep.get("ok")) else 400)
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    now_ms = int(_now_ms())
    hold_sec = _web3_market_digest_hold_last_sec()
    scan = _web3_market_digest_latest_row_from_outbox(now_ms=int(now_ms), hold_sec=int(hold_sec))
    latest = scan.get("latest") if isinstance(scan, dict) else None
    latest_any = scan.get("latest_any") if isinstance(scan, dict) else None
    st = TRACKER_STATE.get("web3_market_digest") if isinstance(TRACKER_STATE.get("web3_market_digest"), dict) else {}
    age_sec = None
    try:
        ts_latest = _web3_market_digest_ts_to_ms((latest if isinstance(latest, dict) else {}).get("ts"))
        if ts_latest > 0:
            age_sec = float(max(0, int(now_ms) - int(ts_latest))) / 1000.0
    except Exception:
        age_sec = None
    return (
        jsonify(
            {
                "ok": True,
                "ts": int(now_ms),
                "hold_sec": int(hold_sec),
                "latest_age_sec": age_sec,
                "state": _json_sanitize(st),
                "latest": (_json_sanitize(latest) if isinstance(latest, dict) else None),
                "latest_any": (_json_sanitize(latest_any) if isinstance(latest_any, dict) else None),
            }
        ),
        200,
    )


