@app.route("/agent/automation/auto_trade/decisions", methods=["GET"])
def agent_automation_auto_trade_decisions():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    try:
        window_sec = int(request.args.get("window_sec") or 6 * 3600)
    except Exception:
        window_sec = 6 * 3600
    window_sec = max(300, min(7 * 86400, int(window_sec)))
    now_ms = int(_now_ms())
    outbox_name = _auto_trade_decision_outbox_name()
    p = _agent_outbox_dir() / outbox_name
    try:
        tail = _agent_jsonl_tail(p, tail_bytes=2_000_000, max_lines=10_000)
    except Exception:
        tail = []
    rows: List[Dict[str, Any]] = []
    for it in reversed(tail if isinstance(tail, list) else []):
        if not isinstance(it, dict):
            continue
        if str(it.get("type") or "").strip() != "trade.decision":
            continue
        ts_ms = _web3_market_digest_ts_to_ms(it.get("ts"))
        if ts_ms <= 0:
            continue
        if int(now_ms) - int(ts_ms) > int(window_sec) * 1000:
            continue
        rows.append(_json_sanitize(it))
        if len(rows) >= 200:
            break
    rows.reverse()
    return jsonify({"ok": True, "ts": int(now_ms), "window_sec": int(window_sec), "items": rows, "outbox": outbox_name})


@app.route("/agent/automation/auto_trade/kill_switch/trigger", methods=["POST"])
def agent_automation_auto_trade_kill_switch_trigger():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    ok_iso, reason_iso = _auto_trade_guard_isolation()
    isolation_warning = None if bool(ok_iso) else {"error": str(reason_iso), "isolation": _json_sanitize(_auto_trade_isolation_status())}
    st = _auto_trade_state_get()
    reason = str(data.get("reason") or "manual").strip() or "manual"
    st["kill_switch_triggered"] = True
    st["kill_switch_reason"] = reason
    st["kill_switch_ts_ms"] = int(_now_ms())
    st["enter_exit_review"] = True
    review_rep: Dict[str, Any] = {"ok": True, "skipped": True, "reason": "auto_exit_disabled"}
    if bool(_auto_trade_auto_exit_enabled()):
        try:
            def _bg_auto_trade_exit_review():
                with app.app_context():
                    try:
                        _auto_trade_exit_review_run(int(_now_ms()), reason="kill_switch")
                    except Exception:
                        pass
            threading.Thread(target=_bg_auto_trade_exit_review, daemon=True).start()
            review_rep = {"ok": True, "queued": True}
        except Exception as e:
            review_rep = {"ok": False, "error": str(e)}
    try:
        _agent_outbox_append_jsonl(
            "auto_trade_events.jsonl",
            {"id": uuid.uuid4().hex, "trace_id": str(data.get("trace_id") or uuid.uuid4().hex), "ts": int(_now_ms()), "type": "auto_trade.kill_switch", "reason": reason, "triggered": True},
        )
    except Exception:
        pass
    return jsonify({"ok": True, "ts": int(_now_ms()), "triggered": True, "reason": reason, "exit_review": _json_sanitize(review_rep), "isolation_warning": _json_sanitize(isolation_warning)})


@app.route("/agent/automation/auto_trade/precheck/run", methods=["POST"])
def agent_automation_auto_trade_precheck_run():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    chain_id = str(data.get("chain_id") or data.get("chainId") or "56").strip() or "56"
    contract_address = str(data.get("contract_address") or data.get("contractAddress") or "").strip()
    if not contract_address:
        return jsonify({"ok": False, "error": "missing_contract_address", "trace_id": trace_id, "ts": int(_now_ms())}), 400
    try:
        timeout_sec = float(data.get("timeout_sec") or 10.0)
    except Exception:
        timeout_sec = 10.0
    timeout_sec = float(max(1.0, min(30.0, float(timeout_sec))))

    audit = _skill_binance_web3_query_token_audit({"chainId": chain_id, "contractAddress": contract_address, "timeout_sec": float(timeout_sec), "requestId": uuid.uuid4().hex})
    tradeable = _skill_binance_web3_token_tradeable_check({"chainId": chain_id, "contractAddress": contract_address, "timeout_sec": float(timeout_sec)})

    gate_decision = "pass"
    gate_reason = ""
    if not bool(audit.get("ok")) or not bool(tradeable.get("ok")):
        gate_decision = "blocked"
        gate_reason = "precheck_failed"
    else:
        if not bool(audit.get("supported", True)) or not bool(audit.get("hasResult", True)):
            gate_decision = "inconclusive"
            gate_reason = "audit_inconclusive"
        elif bool(tradeable.get("block", False)):
            gate_decision = "fail"
            gate_reason = "tradeable_block"

    out = {
        "ok": True,
        "ts": int(_now_ms()),
        "trace_id": trace_id,
        "type": "trade.precheck",
        "chain_id": chain_id,
        "contract_address": contract_address,
        "audit": _json_sanitize(audit),
        "tradeable": _json_sanitize(tradeable),
        "gate": {"decision": gate_decision, "reason": gate_reason},
    }
    try:
        _agent_outbox_append_jsonl("trade_prechecks.jsonl", {"id": uuid.uuid4().hex, **out})
    except Exception:
        pass
    return jsonify(out), 200


