@app.route("/agent/automation/auto_trade/position/snapshot", methods=["POST"])
def agent_automation_auto_trade_position_snapshot():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    position_id = (None if data.get("position_id") is None else str(data.get("position_id") or "").strip()) or None
    chain_id = str(data.get("chain_id") or data.get("chainId") or "56").strip() or "56"
    contract_address = str(data.get("contract_address") or data.get("contractAddress") or "").strip()
    refresh_period = (None if data.get("refresh_period") is None else str(data.get("refresh_period") or "").strip()) or None
    now_ms = int(_now_ms())

    ps = TRACKER_STATE.get("auto_trade_positions")
    if not isinstance(ps, dict):
        ps = {}
        TRACKER_STATE["auto_trade_positions"] = ps
    pos = None
    if position_id and position_id in ps and isinstance(ps.get(position_id), dict):
        pos = dict(ps.get(position_id) or {})
        chain_id = str(pos.get("chain_id") or chain_id).strip() or chain_id
        contract_address = str(pos.get("contract_address") or contract_address).strip() or contract_address
    if not contract_address:
        return jsonify({"ok": False, "error": "missing_contract_address", "trace_id": trace_id, "ts": int(now_ms)}), 400

    token_info = _skill_binance_web3_query_token_info({"chainId": chain_id, "contractAddress": contract_address})
    market = token_info.get("market") if isinstance(token_info.get("market"), dict) else {}
    symbol = (str(pos.get("symbol") or "").strip() if isinstance(pos, dict) else "") or (str((token_info.get("token") or {}).get("symbol") or "").strip() if isinstance(token_info.get("token"), dict) else "")
    score_pack = _auto_trade_four_factor_scores(
        int(now_ms),
        chain_id=chain_id,
        contract_address=contract_address,
        symbol=(symbol or None),
        market=(market if isinstance(market, dict) else {}),
    )
    payload_factors = data.get("factors") if isinstance(data.get("factors"), dict) else {}
    merged_factors = dict(score_pack)
    if isinstance(payload_factors, dict):
        for k, v in payload_factors.items():
            merged_factors[str(k)] = v
    snapshot = {
        "ok": True,
        "ts": int(now_ms),
        "trace_id": trace_id,
        "type": "position.snapshot",
        "position_id": position_id,
        "chain_id": chain_id,
        "contract_address": contract_address,
        "symbol": (symbol or None),
        "refresh_period": refresh_period,
        "factors": {
            "liquidity_usd": market.get("liquidity"),
            "volume24h_usd": market.get("volume24h"),
            "price_usd": market.get("price"),
            "holders": market.get("holders"),
            **_json_sanitize(merged_factors),
        },
    }
    try:
        _agent_outbox_append_jsonl("positions.jsonl", {"id": uuid.uuid4().hex, **_json_sanitize(snapshot)})
    except Exception:
        pass
    if position_id and isinstance(pos, dict):
        pos2 = dict(pos)
        pos2["last_snapshot_ts_ms"] = int(now_ms)
        ps[position_id] = pos2
    return jsonify(snapshot), 200


@app.route("/agent/automation/auto_trade/exit/intent", methods=["POST"])
def agent_automation_auto_trade_exit_intent():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    if not _auto_trade_enabled():
        return jsonify({"ok": False, "error": "auto_trade_disabled", "trace_id": trace_id, "ts": int(_now_ms())}), 400
    ok_iso, reason_iso = _auto_trade_guard_isolation()
    if not ok_iso:
        return jsonify({"ok": False, "error": reason_iso, "trace_id": trace_id, "ts": int(_now_ms()), "isolation": _json_sanitize(_auto_trade_isolation_status())}), 400
    if _auto_trade_env() != "prod":
        return jsonify({"ok": False, "error": "env_not_prod", "trace_id": trace_id, "ts": int(_now_ms())}), 400
    now_ms = int(_now_ms())
    position_id = (None if data.get("position_id") is None else str(data.get("position_id") or "").strip()) or None
    reason = str(data.get("reason") or "manual").strip() or "manual"
    mode = str(data.get("mode") or "manual").strip().lower() or "manual"
    if mode not in ("manual", "auto"):
        mode = "manual"
    if mode == "auto" and _auto_trade_mode() != "auto":
        return jsonify({"ok": False, "error": "auto_trade_mode_manual", "trace_id": trace_id, "ts": int(_now_ms())}), 400
    selected_factors = data.get("selected_factors") if isinstance(data.get("selected_factors"), list) else []
    selected_factors = [str(x).strip() for x in selected_factors if str(x).strip()][:12]
    try:
        confirm_count = int(data.get("confirm_count") or 0)
    except Exception:
        confirm_count = 0
    confirm_count = max(0, min(20, int(confirm_count)))
    try:
        risk_score = float(data.get("risk_score")) if data.get("risk_score") is not None else None
    except Exception:
        risk_score = None
    try:
        value_score = float(data.get("value_score")) if data.get("value_score") is not None else None
    except Exception:
        value_score = None
    if isinstance(risk_score, float):
        risk_score = float(max(0.0, min(1.0, float(risk_score))))
    if isinstance(value_score, float):
        value_score = float(max(0.0, min(1.0, float(value_score))))
    action = str(data.get("action") or "close").strip().lower() or "close"
    if action not in ("hold", "reduce", "close"):
        action = "close"
    try:
        reduce_ratio = float(data.get("reduce_ratio") if data.get("reduce_ratio") is not None else (1.0 if action == "close" else 0.5))
    except Exception:
        reduce_ratio = (1.0 if action == "close" else 0.5)
    reduce_ratio = float(max(0.0, min(1.0, float(reduce_ratio))))
    intent_id = uuid.uuid4().hex

    payload = {
        "ok": True,
        "ts": int(now_ms),
        "trace_id": trace_id,
        "type": "exit.intent",
        "intent_id": intent_id,
        "position_id": position_id,
        "mode": mode,
        "reason": reason,
        "selected_factors": selected_factors,
        "confirm_count": int(confirm_count),
        "risk_score": risk_score,
        "value_score": value_score,
        "action": action,
        "reduce_ratio": float(reduce_ratio),
    }
    try:
        _agent_outbox_append_jsonl("exits.jsonl", {"id": uuid.uuid4().hex, **_json_sanitize(payload)})
    except Exception:
        pass
    st = _auto_trade_state_get()
    st["last_exit_intent_ms"] = int(now_ms)
    st["last_exit_intent_id"] = intent_id
    return jsonify(payload), 200


