@app.route("/agent/automation/auto_trade/receipts", methods=["GET"])
def agent_automation_auto_trade_receipts():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    now_ms = int(_now_ms())
    try:
        window_sec = int(request.args.get("window_sec") or 24 * 3600)
    except Exception:
        window_sec = 24 * 3600
    window_sec = max(300, min(7 * 86400, int(window_sec)))
    cutoff_ms = int(now_ms) - int(window_sec) * 1000

    def _collect(name: str, intent_type: str, receipt_type: str) -> Dict[str, Any]:
        p = _agent_outbox_dir() / name
        try:
            rows = _agent_jsonl_tail(p, tail_bytes=3_000_000, max_lines=15_000)
        except Exception:
            rows = []
        intents: Dict[str, Dict[str, Any]] = {}
        receipts: Dict[str, Dict[str, Any]] = {}
        for it in rows if isinstance(rows, list) else []:
            if not isinstance(it, dict):
                continue
            typ = str(it.get("type") or "").strip().lower()
            ts_ms = _web3_market_digest_ts_to_ms(it.get("ts"))
            if ts_ms <= 0 or ts_ms < int(cutoff_ms):
                continue
            iid = str(it.get("intent_id") or "").strip()
            if not iid:
                continue
            if typ == intent_type:
                prev = intents.get(iid)
                if (not isinstance(prev, dict)) or int(_web3_market_digest_ts_to_ms(prev.get("ts"))) <= int(ts_ms):
                    intents[iid] = it
            elif typ == receipt_type:
                prev = receipts.get(iid)
                if (not isinstance(prev, dict)) or int(_web3_market_digest_ts_to_ms(prev.get("ts"))) <= int(ts_ms):
                    receipts[iid] = it
        pending_ids = [iid for iid in intents.keys() if iid not in receipts]
        pending_ids.sort(key=lambda x: int(_web3_market_digest_ts_to_ms((intents.get(x) or {}).get("ts"))), reverse=True)
        return {
            "intents_total": int(len(intents)),
            "receipts_total": int(len(receipts)),
            "pending_total": int(len(pending_ids)),
            "pending_intent_ids": pending_ids[:50],
            "latest_receipt": _json_sanitize((max(receipts.values(), key=lambda x: int(_web3_market_digest_ts_to_ms(x.get("ts")))) if receipts else {})),
        }

    return jsonify(
        {
            "ok": True,
            "ts": int(now_ms),
            "window_sec": int(window_sec),
            "orders": _collect("orders.jsonl", "order.intent", "order.receipt"),
            "exits": _collect("exits.jsonl", "exit.intent", "exit.receipt"),
        }
    ), 200


