    return jsonify({"ok": True, "queued": True, "trace_id": trace_id, "ts": int(now_ms), "scenarios": scenarios, "max_batches": int(max_batches), "apply_live": bool(apply_live), "rollback_after_apply": bool(rollback_after_apply)}), 202


