@app.route("/automation/gtw/sandbox/smoke", methods=["POST"])
def automation_gtw_sandbox_smoke():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    if not bool(_is_local_request()):
        return jsonify({"ok": False, "error": "local_only", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    try:
        trigger_event = (None if data.get("trigger_event") is None else str(data.get("trigger_event") or "").strip()) or None
    except Exception:
        trigger_event = None
    trigger_event = trigger_event or "sandbox.smoke"
    try:
        lookback_days = int(data.get("lookback_days") or 60)
    except Exception:
        lookback_days = 60
    lookback_days = max(1, min(365, int(lookback_days)))
    try:
        wait_sec = float(data.get("wait_sec") or 45)
    except Exception:
        wait_sec = 45.0
    wait_sec = float(max(0.0, min(900.0, wait_sec)))
    try:
        poll_interval_ms = int(data.get("poll_interval_ms") or 750)
    except Exception:
        poll_interval_ms = 750
    poll_interval_ms = max(200, min(5000, int(poll_interval_ms)))

    default_paths = ["strategy_supply_chain", "strategy_shadow_loop", "paramopt_automation"]
    force_path_ids = data.get("force_path_ids") if isinstance(data.get("force_path_ids"), list) else default_paths
    try:
        force_path_ids = [str(x).strip() for x in (force_path_ids or []) if str(x).strip()]
    except Exception:
        force_path_ids = default_paths
    if not force_path_ids:
        force_path_ids = default_paths

    ts0 = int(_now_ms())
    decision_id = _gtw_decision_id(int(ts0), seed=str(trigger_event))

    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.trade_analysis", artifact={"ts": int(ts0), "trade": _json_sanitize(_gtw_trade_eval(now_ms=int(ts0)))})
    except Exception:
        pass
    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.macro_analysis", artifact={"ts": int(ts0), "macro": _json_sanitize(_gtw_macro_eval(now_ms=int(ts0), trace_id=str(decision_id)))})
    except Exception:
        pass

    pkg = _gtw_build_decision_package(now_ms=int(ts0), decision_id=str(decision_id), polling_kind="event", trigger_event=str(trigger_event), force_path_ids=list(force_path_ids))
    try:
        rc = pkg.get("run_context") if isinstance(pkg.get("run_context"), dict) else {}
        rc = dict(rc) if isinstance(rc, dict) else {}
        rc["lookback_days"] = int(lookback_days)
        pkg["run_context"] = rc
    except Exception:
        pass

    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.decision_package", artifact=pkg)
    except Exception:
        pass
    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.training.sample", artifact=_gtw_training_sample_build(pkg=pkg))
    except Exception:
        pass

    rep = _gtw_trigger_paths(now_ms=int(_now_ms()), decision_id=str(decision_id), pkg=pkg)
    try:
        triggered0 = rep.get("triggered") if isinstance(rep, dict) else None
        fb: List[Dict[str, Any]] = []
        if isinstance(triggered0, list):
            for t in triggered0:
                if not isinstance(t, dict):
                    continue
                pid0 = str(t.get("path_id") or "").strip()
                if not pid0:
                    continue
                st0 = str(t.get("status") or "").strip().upper() or "PENDING"
                if st0 in ("DONE", "FAIL", "BLOCKED", "RUNNING", "PENDING"):
                    st1 = st0
                elif st0 in ("OK", "SUCCESS"):
                    st1 = "DONE"
                else:
                    st1 = ("DONE" if bool(t.get("ok", False)) else "FAIL")
                fb.append(
                    {
                        "path_id": pid0,
                        "status": st1,
                        "updated_at_ms": int(_now_ms()),
                        "trace_id": (None if not str(t.get("trace_id") or "").strip() else str(t.get("trace_id") or "").strip()),
                        "summary": {"http": t.get("http"), "summary": t.get("summary"), "deduped": t.get("deduped")},
                    }
                )
        pkg2 = dict(pkg) if isinstance(pkg, dict) else {"schema_version": "v1", "decision_id": str(decision_id)}
        pkg2["feedback"] = fb if fb else None
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.decision_package", artifact=pkg2)
    except Exception:
        pkg2 = pkg
    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.triggered", artifact=rep)
    except Exception:
        pass
    try:
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.training.outcome", artifact=_gtw_training_outcome_build(decision_id=str(decision_id), pkg=pkg2 if isinstance(pkg2, dict) else pkg, rep=rep if isinstance(rep, dict) else {}))
    except Exception:
        pass
    try:
        st2 = _gtw_state_get()
        st2["last_run_ms"] = int(ts0)
        st2["last_trace_id"] = str(decision_id)
        st2["active_trace_id"] = str(decision_id)
        st2["last_decision_id"] = str(decision_id)
        st2["last_triggered"] = _json_sanitize(rep)
        TRACKER_STATE["gtw"] = st2
    except Exception:
        pass

    step_by_path: Dict[str, Dict[str, Any]] = {}
    try:
        for t in (rep.get("triggered") if isinstance(rep, dict) else []) or []:
            if not isinstance(t, dict):
                continue
            pid = str(t.get("path_id") or "").strip()
            tr = str(t.get("trace_id") or "").strip()
            if not pid:
                continue
            step_by_path[pid] = {"path_id": pid, "trace_id": (tr or None), "http": t.get("http"), "ok": bool(t.get("ok", False)), "status": str(t.get("status") or ""), "summary": (None if t.get("summary") is None else str(t.get("summary")))}
    except Exception:
        step_by_path = {}

    need: Dict[str, List[str]] = {
        str(decision_id): ["gtw.decision_package", "gtw.triggered"],
    }
    for pid in ("strategy_supply_chain", "strategy_shadow_loop", "paramopt_automation"):
        tr0 = (step_by_path.get(pid) or {}).get("trace_id")
        if not tr0:
            continue
        if pid == "strategy_supply_chain":
            need[str(tr0)] = ["repo_scan", "baseline_report"]
        elif pid == "paramopt_automation":
            need[str(tr0)] = ["paramopt_trigger"]
        else:
            need[str(tr0)] = []

    def _collect() -> Dict[str, Any]:
        rows = _pipeline_artifacts_tail(tail_bytes=2_000_000, max_lines=20_000)
        out: Dict[str, Any] = {}
        for tid, kinds in need.items():
            found: Dict[str, Any] = {"count": 0, "kinds": [], "has": {}, "missing": []}
            ks: Dict[str, int] = {}
            for r in rows:
                if not isinstance(r, dict):
                    continue
                if str(r.get("trace_id") or "") != str(tid):
                    continue
                found["count"] = int(found["count"]) + 1
                k = str(r.get("kind") or "").strip()
                if k:
                    ks[k] = int(ks.get(k, 0)) + 1
            found["kinds"] = sorted(list(ks.keys()))
            has_map: Dict[str, bool] = {}
            missing: List[str] = []
            for k in kinds:
                okk = k in ks
                has_map[k] = bool(okk)
                if not okk:
                    missing.append(k)
            found["has"] = has_map
            found["missing"] = missing
            out[str(tid)] = found
        return out

    deadline = time.time() + float(wait_sec)
    snap = _collect()
    while time.time() < deadline:
        all_ok = True
        for tid, want in need.items():
            if not want:
                continue
            if any([not bool(snap.get(str(tid), {}).get("has", {}).get(k, False)) for k in want]):
                all_ok = False
                break
        if all_ok:
            break
        time.sleep(float(poll_interval_ms) / 1000.0)
        snap = _collect()

    rows_out: List[Dict[str, Any]] = []
    rows_out.append(
        {
            "step": "gtw",
            "path_id": "gtw",
            "trace_id": str(decision_id),
            "required_kinds": need.get(str(decision_id)) or [],
            "missing_kinds": (snap.get(str(decision_id), {}).get("missing") if isinstance(snap.get(str(decision_id)), dict) else []),
            "artifact_count": (snap.get(str(decision_id), {}).get("count") if isinstance(snap.get(str(decision_id)), dict) else 0),
        }
    )
    for pid in ("strategy_supply_chain", "strategy_shadow_loop", "paramopt_automation"):
        s = step_by_path.get(pid) or {"path_id": pid}
        tid0 = s.get("trace_id")
        miss = (snap.get(str(tid0), {}).get("missing") if (tid0 and isinstance(snap.get(str(tid0)), dict)) else [])
        rows_out.append(
            {
                "step": pid,
                "path_id": pid,
                "trace_id": (None if not tid0 else str(tid0)),
                "http": s.get("http"),
                "ok": s.get("ok"),
                "status": s.get("status"),
                "summary": s.get("summary"),
                "required_kinds": need.get(str(tid0)) if tid0 else [],
                "missing_kinds": miss,
                "artifact_count": (snap.get(str(tid0), {}).get("count") if (tid0 and isinstance(snap.get(str(tid0)), dict)) else 0),
            }
        )

    md_lines = [
        "| step | trace_id | artifacts | missing |",
        "|---|---|---:|---|",
    ]
    for r in rows_out:
        tid = str(r.get("trace_id") or "")
        ac = int(r.get("artifact_count") or 0)
        missing = r.get("missing_kinds") if isinstance(r.get("missing_kinds"), list) else []
        md_lines.append(f"| {str(r.get('step') or '')} | {tid} | {ac} | {', '.join([str(x) for x in missing])} |")
    table_md = "\n".join(md_lines)

    report = {"ok": True, "ts": int(_now_ms()), "decision_id": str(decision_id), "force_path_ids": list(force_path_ids), "wait_sec": float(wait_sec), "artifact_snapshot": snap, "rows": rows_out, "table_md": table_md}
    try:
        art = _agent_pipeline_artifact_common_fields(trace_id=str(decision_id), created_at_ms=int(_now_ms()), producer_kind="agent")
        art.update({"ts": int(_now_ms()), "report": report})
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(decision_id), kind="gtw.sandbox.smoke_report", artifact=art)
    except Exception:
        pass
    return jsonify(report), 200


def _trace_is_paramopt_explore(trace_id: str, *, max_lines: int = 12000, max_bytes: int = 8_000_000) -> bool:
    tid = str(trace_id or "").strip()
    if not tid:
        return False
    outbox = _agent_outbox_dir()
    cand: List[Path] = []
    try:
        p0 = outbox / "chat.jsonl"
        if p0.exists() and p0.is_file():
            cand.append(p0)
    except Exception:
        pass
    try:
        others = [p for p in outbox.glob("chat._*.jsonl") if p.is_file()]
        others.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others[:16])
    except Exception:
        pass
    try:
        others = [p for p in outbox.glob("chat_*.jsonl") if p.is_file()]
        others.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        cand.extend(others[:16])
    except Exception:
        pass
    for fp in cand[:20]:
        try:
            lines = _tail_lines(fp, max_lines=int(max_lines), max_bytes=int(max_bytes))
        except Exception:
            lines = []
        for ln in reversed(lines):
            s = str(ln or "").strip("\n")
            if not s.strip():
                continue
            try:
                obj = json.loads(s)
            except Exception:
                continue
            if not isinstance(obj, dict):
                continue
            if str(obj.get("trace_id") or "").strip() != tid:
                continue
            tp = str(obj.get("type") or "").strip()
            if tp == "automation.paramopt.explore.trigger":
                return True
            if tp == "automation.paramopt.trigger":
                res = obj.get("result") if isinstance(obj.get("result"), dict) else {}
                if str(res.get("trigger_event") or obj.get("trigger_event") or "").strip() == "strategy.explore.cycle.trigger":
                    return True
    return False


def _approvals_auto_reject_expired_explore(*, now_ms: int, ttl_hours: int = 24, max_lines: int = 20000, max_bytes: int = 12_000_000) -> Dict[str, Any]:
    p = _approvals_log_path()
    if not p.exists() or (not p.is_file()):
        return {"ok": True, "scanned": 0, "rejected": 0}
    ttl_ms = int(max(1, min(168, int(ttl_hours)))) * 3600 * 1000
    lines = _tail_lines(p, max_lines=int(max_lines), max_bytes=int(max_bytes))
    scanned = 0
    rejected = 0
    visited: set = set()
    for ln in reversed(lines):
        s = str(ln or "").strip("\n")
        if not s.strip():
            continue
        try:
            obj = json.loads(s)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        rid = str(obj.get("id") or "").strip()
        if not rid or rid in visited:
            continue
        visited.add(rid)
        scanned += 1
        dec = str(obj.get("decision") or "").strip().lower()
        if not dec.startswith("pending"):
            continue
        try:
            ts = int(obj.get("ts") or 0)
        except Exception:
            ts = 0
        if ts <= 0 or int(now_ms) - int(ts) < int(ttl_ms):
            continue
        tid = str(obj.get("trace_id") or "").strip()
        if not _trace_is_paramopt_explore(tid):
            continue
        try:
            _approval_append(
                {
                    "id": str(rid),
                    "trace_id": (tid or rid),
                    "approver": "system",
                    "decision": "rejected",
                    "action": str(obj.get("action") or ""),
                    "reason": "expired_24h_auto_reject",
                    "doc_refs": _doc_refs_default(),
                    "evidence": {
                        "expired": True,
                        "ttl_hours": int(ttl_hours),
                        "pending_ts": int(ts),
                        "now_ms": int(now_ms),
                        "auto_gc": "paramopt_explore",
                    },
                    "ts": int(now_ms),
                }
            )
            rejected += 1
        except Exception:
            continue
    return {"ok": True, "scanned": int(scanned), "rejected": int(rejected), "ttl_hours": int(ttl_hours)}


def _approvals_pending_by_trace(*, max_lines: int = 2000, max_bytes: int = 2_000_000) -> Dict[str, Dict[str, Any]]:
    p = _approvals_log_path()
    if not p.exists() or (not p.is_file()):
        return {}
    lines = _tail_lines(p, max_lines=int(max_lines), max_bytes=int(max_bytes))
    out: Dict[str, Dict[str, Any]] = {}
    for ln in reversed(lines):
        s = str(ln or "").strip("\n")
        if not s.strip():
            continue
        try:
            obj = json.loads(s)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        dec = str(obj.get("decision") or "").strip().lower()
        if not dec.startswith("pending"):
            continue
        tid = str(obj.get("trace_id") or "").strip()
        if not tid:
            continue
        if tid in out:
            continue
        out[tid] = obj
        if len(out) >= 50:
            break
    return out


def _pipeline_artifacts_tail(*, tail_bytes: int = 2_000_000, max_lines: int = 20_000) -> List[Dict[str, Any]]:
    try:
        p = _agent_outbox_dir() / "pipeline_artifacts.jsonl"
    except Exception:
        return []
    return _agent_jsonl_tail(p, tail_bytes=int(tail_bytes), max_lines=int(max_lines))


def _pipeline_artifacts_for_trace(rows: List[Dict[str, Any]], trace_id: str) -> List[Dict[str, Any]]:
    tid = str(trace_id or "").strip()
    if not tid:
        return []
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if str(r.get("trace_id") or "").strip() != tid:
            continue
        out.append(r)
    return out


def _pipeline_latest_trace_for_kinds(rows: List[Dict[str, Any]], kinds: List[str]) -> Optional[str]:
    ks = set([str(k).strip() for k in (kinds or []) if str(k).strip()])
    if not ks:
        return None
    best_ts = 0
    best_tid = None
    for r in rows:
        if not isinstance(r, dict):
            continue
        k = str(r.get("kind") or "").strip()
        if k not in ks:
            continue
        try:
            ts = int(r.get("ts") or 0)
        except Exception:
            ts = 0
        if ts <= 0:
            continue
        if ts >= best_ts:
            tid = str(r.get("trace_id") or "").strip()
            if tid:
                best_ts = ts
                best_tid = tid
    return best_tid


def _automation_progress_build(*, trace_id: str, mode: str, rows: List[Dict[str, Any]], approvals_pending: Dict[str, Dict[str, Any]]) -> Tuple[Optional[Dict[str, Any]], Optional[Dict[str, Any]], int]:
    tid = str(trace_id or "").strip()
    if not tid:
        return None, None, 0
    items = _pipeline_artifacts_for_trace(rows, tid)
    by_kind: Dict[str, List[Dict[str, Any]]] = {}
    latest_ts = 0
    for r in items:
        k = str(r.get("kind") or "").strip()
        if not k:
            continue
        by_kind.setdefault(k, []).append(r)
        try:
            latest_ts = max(latest_ts, int(r.get("ts") or 0))
        except Exception:
            pass

    def _kind_ts(k: str) -> int:
        its = by_kind.get(k) or []
        out_ts = 0
        for r in its:
            try:
                out_ts = max(out_ts, int(r.get("ts") or 0))
            except Exception:
                pass
        return int(out_ts)

    def _has(k: str) -> bool:
        return bool(by_kind.get(k))

    def _latest_artifact(k: str) -> Dict[str, Any]:
        its = by_kind.get(k) or []
        best_ts = -1
        best = None
        for r in its:
            if not isinstance(r, dict):
                continue
            try:
                ts = int(r.get("ts") or 0)
            except Exception:
                ts = 0
            if ts >= best_ts:
                best_ts = ts
                best = r
        art = (best.get("artifact") if isinstance(best, dict) else None)
        return art if isinstance(art, dict) else {}

    def _gating_decision() -> Optional[str]:
        gr = _latest_artifact("gating_report")
        d = str(gr.get("decision") or "").strip().lower()
        return (d if d else None)

    def _shadow_apply_approval_id() -> Optional[str]:
        art = _latest_artifact("shadow_config_apply")
        try:
            if str(art.get("approval_id") or "").strip():
                return str(art.get("approval_id") or "").strip()
        except Exception:
            pass
        resp = art.get("response") if isinstance(art.get("response"), dict) else {}
        try:
            if str(resp.get("approval_id") or "").strip():
                return str(resp.get("approval_id") or "").strip()
        except Exception:
            pass
        return None

    pending = approvals_pending.get(tid)
    apply_approval_id = _shadow_apply_approval_id() if mode == "shadow_loop" else None
    has_approval = _has("approval_request") or (pending is not None) or (bool(apply_approval_id) if mode == "shadow_loop" else False)
    approval_ts = max(
        _kind_ts("approval_request"),
        int((pending or {}).get("ts") or 0) if isinstance(pending, dict) else 0,
        (_kind_ts("shadow_config_apply") if (mode == "shadow_loop" and bool(apply_approval_id)) else 0),
    )

    steps: List[Dict[str, Any]] = []
    if mode == "supply_chain":
        base_ok = True
        base_err = None
        if _has("baseline_report"):
            br = _latest_artifact("baseline_report")
            try:
                if br.get("ok") is not None:
                    base_ok = bool(br.get("ok"))
            except Exception:
                base_ok = True
            if not base_ok:
                try:
                    res0 = br.get("result") if isinstance(br.get("result"), dict) else {}
                    base_err = str(res0.get("error") or br.get("error") or "baseline_failed")
                except Exception:
                    base_err = "baseline_failed"

        gate_dec = _gating_decision()
        gate_status = "WAIT"
        if _has("gating_report"):
            if gate_dec == "pass":
                gate_status = "DONE"
            else:
                gate_status = "FAIL"

        steps = [
            {"key": "repo", "label": "拉取/扫描", "status": ("DONE" if (_has("repo_fetch") or _has("repo_scan")) else "WAIT"), "ts_ms": max(_kind_ts("repo_fetch"), _kind_ts("repo_scan")) or None},
            {"key": "registry", "label": "入库", "status": ("DONE" if (_has("candidate_strategies") or (_has("baseline_report") and base_ok)) else ("FAIL" if _has("baseline_report") and (not base_ok) else "WAIT")), "ts_ms": max(_kind_ts("candidate_strategies"), _kind_ts("baseline_report")) or None, "evidence": ({"error": base_err} if (base_err and (not base_ok)) else None)},
            {"key": "sandbox", "label": "沙箱评估/分档", "status": gate_status, "ts_ms": _kind_ts("gating_report") or None},
            {"key": "approval", "label": "审批", "status": ("RUN" if (pending is not None and not _has("config.set.result")) else ("DONE" if has_approval else "WAIT")), "ts_ms": (approval_ts or None)},
        ]
    elif mode == "shadow_loop":
        gate_dec = _gating_decision()
        gate_status = "WAIT"
        if _has("gating_report"):
            if gate_dec == "pass":
                gate_status = "DONE"
            else:
                gate_status = "FAIL"
        apply_art = _latest_artifact("shadow_config_apply") if _has("shadow_config_apply") else {}
        apply_ok = None
        try:
            if apply_art.get("ok") is not None:
                apply_ok = bool(apply_art.get("ok"))
        except Exception:
            apply_ok = None
        apply_status = "WAIT"
        if _has("shadow_config_apply"):
            apply_status = ("DONE" if (apply_ok is None or bool(apply_ok)) else "FAIL")
        elif _has("config.set.result"):
            apply_status = "DONE"
        elif _has("auto_rollback"):
            apply_status = "FAIL"
        steps = [
            {"key": "trigger", "label": "触发", "status": ("DONE" if _has("trigger_record") else "WAIT"), "ts_ms": (_kind_ts("trigger_record") or None)},
            {"key": "candidates", "label": "候选生成", "status": ("DONE" if (_has("candidate_strategies") or _has("change_bundle_draft")) else "WAIT"), "ts_ms": max(_kind_ts("candidate_strategies"), _kind_ts("change_bundle_draft")) or None},
            {"key": "gate", "label": "沙箱门禁", "status": gate_status, "ts_ms": _kind_ts("gating_report") or None},
            {"key": "approval", "label": "审批", "status": ("RUN" if (pending is not None and not _has("shadow_config_apply")) else ("DONE" if has_approval else "WAIT")), "ts_ms": (approval_ts or None)},
            {"key": "apply", "label": "执行/回滚", "status": apply_status, "ts_ms": max(_kind_ts("shadow_config_apply"), _kind_ts("config.set.result"), _kind_ts("auto_rollback")) or None},
        ]
    elif mode == "system_monitor":
        trig = _latest_artifact("system_monitor_trigger") if _has("system_monitor_trigger") else {}
        inputs = trig.get("inputs") if isinstance(trig, dict) and isinstance(trig.get("inputs"), dict) else {}
        run_backtest_req = bool(inputs.get("run_backtest", True))
        run_triage_req = bool(inputs.get("run_triage", True))
        gen_req = bool(inputs.get("generate_changeset", True))
        appr_req = bool(inputs.get("request_approval", True))

        triage_status = ("SKIP" if not run_triage_req else ("DONE" if _has("system_monitor_triage") else "WAIT"))

        bt_ok = None
        if _has("system_monitor_backtest"):
            art = _latest_artifact("system_monitor_backtest")
            try:
                bt_ok = (None if art.get("ok") is None else bool(art.get("ok")))
            except Exception:
                bt_ok = None
        sandbox_status = "SKIP" if not run_backtest_req else ("DONE" if (bt_ok is None or bool(bt_ok)) and _has("system_monitor_backtest") else ("FAIL" if (bt_ok is False and _has("system_monitor_backtest")) else ("RUN" if _has("system_monitor_backtest") else "WAIT")))

        tri = _latest_artifact("system_monitor_triage") if _has("system_monitor_triage") else {}
        tri_hits = tri.get("faq_hits") if isinstance(tri, dict) and isinstance(tri.get("faq_hits"), list) else []
        has_faq_hit = bool([x for x in tri_hits if str(x or "").strip()])

        draft_status = "SKIP"
        if gen_req and run_triage_req and has_faq_hit:
            draft_status = ("DONE" if _has("change_bundle_draft") else "WAIT")

        approval_status = "SKIP"
        if appr_req and gen_req and draft_status != "SKIP":
            approval_status = ("RUN" if pending is not None else ("DONE" if _has("approval_request") else "WAIT"))

        report_status = ("DONE" if _has("system_monitor_report") else "WAIT")

        steps = [
            {"key": "trigger", "label": "触发", "status": ("DONE" if _has("system_monitor_trigger") else "WAIT"), "ts_ms": (_kind_ts("system_monitor_trigger") or None)},
            {"key": "triage", "label": "FAQ 命中/分流", "status": triage_status, "ts_ms": (_kind_ts("system_monitor_triage") or None)},
            {"key": "sandbox", "label": "自动沙箱", "status": sandbox_status, "ts_ms": (_kind_ts("system_monitor_backtest") or None)},
            {"key": "draft", "label": "变更包草案", "status": draft_status, "ts_ms": (_kind_ts("change_bundle_draft") or None)},
            {"key": "approval", "label": "审批", "status": approval_status, "ts_ms": (approval_ts or None)},
            {"key": "report", "label": "报告落盘", "status": report_status, "ts_ms": (_kind_ts("system_monitor_report") or None)},
        ]
    elif mode == "gtw":
        trig_art = _latest_artifact("gtw.triggered") if _has("gtw.triggered") else {}
        trig_ok = None
        try:
            if trig_art.get("ok") is not None:
                trig_ok = bool(trig_art.get("ok"))
        except Exception:
            trig_ok = None
        trig_status = "WAIT"
        if _has("gtw.triggered"):
            trig_status = ("DONE" if (trig_ok is None or bool(trig_ok)) else "FAIL")
        steps = [
            {"key": "trade", "label": "交易数据分析", "status": ("DONE" if _has("gtw.trade_analysis") else "WAIT"), "ts_ms": (_kind_ts("gtw.trade_analysis") or None)},
            {"key": "macro", "label": "宏观趋势分析", "status": ("DONE" if _has("gtw.macro_analysis") else "WAIT"), "ts_ms": (_kind_ts("gtw.macro_analysis") or None)},
            {"key": "decide", "label": "决策编排", "status": ("DONE" if _has("gtw.decision_package") else "WAIT"), "ts_ms": (_kind_ts("gtw.decision_package") or None)},
            {"key": "trigger", "label": "触发执行", "status": trig_status, "ts_ms": (_kind_ts("gtw.triggered") or None)},
        ]
    else:
        steps = [
            {"key": "trigger", "label": "触发", "status": ("DONE" if (_has("paramopt_trigger") or _has("paramopt_daily_trigger")) else ("DONE" if bool(items) else "WAIT")), "ts_ms": max(_kind_ts("paramopt_trigger"), _kind_ts("paramopt_daily_trigger")) or None},
            {"key": "run", "label": "paramopt.run", "status": ("DONE" if _has("paramopt_run") else "WAIT"), "ts_ms": _kind_ts("paramopt_run") or None},
            {"key": "suggestion", "label": "建议产出", "status": ("DONE" if (_has("paramopt_suggestion") or _has("change_bundle_draft")) else "WAIT"), "ts_ms": max(_kind_ts("paramopt_suggestion"), _kind_ts("change_bundle_draft")) or None},
            {"key": "verify", "label": "验证", "status": ("DONE" if (_has("rolling_verify") or _has("robustness") or _has("stress")) else "WAIT"), "ts_ms": max(_kind_ts("rolling_verify"), _kind_ts("robustness"), _kind_ts("stress")) or None},
            {"key": "approval", "label": "审批", "status": ("RUN" if (pending is not None and not _has("config.set.result")) else ("DONE" if has_approval else "WAIT")), "ts_ms": (approval_ts or None)},
            {"key": "apply", "label": "应用/回滚", "status": ("DONE" if (_has("config.set.result") or _has("auto_rollback")) else "WAIT"), "ts_ms": max(_kind_ts("config.set.result"), _kind_ts("auto_rollback")) or None},
        ]

    done_n = len([s for s in steps if str(s.get("status") or "") in ("DONE", "FAIL", "SKIP")])
    pct = int(round(float(done_n) / float(max(1, len(steps))) * 100.0))
    prog = {"schema_version": "v1", "pct": int(max(0, min(100, pct))), "steps": steps}

    stuck = None
    if pending is not None:
        try:
            st_ms = int(pending.get("ts") or latest_ts or _now_ms())
        except Exception:
            st_ms = int(latest_ts or _now_ms())
        stuck = {"stuck_at": "approval", "stuck_since_ms": int(st_ms), "reason_code": "approval_pending", "reason": str(pending.get("reason") or "") or "approval_pending"}
    elif mode == "supply_chain":
        gate_dec = _gating_decision()
        if _has("baseline_report"):
            br = _latest_artifact("baseline_report")
            ok0 = True
            try:
                if br.get("ok") is not None:
                    ok0 = bool(br.get("ok"))
            except Exception:
                ok0 = True
            if not ok0:
                try:
                    st_ms = int(br.get("ts") or latest_ts or _now_ms())
                except Exception:
                    st_ms = int(latest_ts or _now_ms())
                res0 = br.get("result") if isinstance(br.get("result"), dict) else {}
                reason = str(res0.get("error") or br.get("error") or "baseline_failed")
                stuck = {"stuck_at": "registry", "stuck_since_ms": int(st_ms), "reason_code": "baseline_failed", "reason": reason}
        if stuck is None and _has("gating_report") and gate_dec and gate_dec != "pass":
            gr = _latest_artifact("gating_report")
            try:
                st_ms = int(gr.get("ts") or latest_ts or _now_ms())
            except Exception:
                st_ms = int(latest_ts or _now_ms())
            detail = None
            try:
                items0 = gr.get("items") if isinstance(gr.get("items"), list) else []
                it0 = items0[0] if items0 and isinstance(items0[0], dict) else None
                detail = (it0.get("detail") if isinstance(it0, dict) and isinstance(it0.get("detail"), dict) else None)
            except Exception:
                detail = None
            reasons = []
            try:
                reasons = (detail.get("reasons") if isinstance(detail, dict) and isinstance(detail.get("reasons"), list) else [])
            except Exception:
                reasons = []
            rc = f"gate_{gate_dec}"
            msg = ",".join([str(x) for x in reasons[:6] if str(x).strip()]) if reasons else f"gate_{gate_dec}"
            stuck = {"stuck_at": "sandbox", "stuck_since_ms": int(st_ms), "reason_code": rc, "reason": msg}
    elif mode == "shadow_loop":
        gate_dec = _gating_decision()
        if _has("gating_report") and gate_dec and gate_dec != "pass" and (not (_has("shadow_config_apply") or _has("auto_rollback"))):
            gr = _latest_artifact("gating_report")
            try:
                st_ms = int(gr.get("ts") or latest_ts or _now_ms())
            except Exception:
                st_ms = int(latest_ts or _now_ms())
            detail = None
            try:
                items0 = gr.get("items") if isinstance(gr.get("items"), list) else []
                it0 = items0[0] if items0 and isinstance(items0[0], dict) else None
                detail = (it0.get("detail") if isinstance(it0, dict) and isinstance(it0.get("detail"), dict) else None)
            except Exception:
                detail = None
            reasons = []
            try:
                reasons = (detail.get("reasons") if isinstance(detail, dict) and isinstance(detail.get("reasons"), list) else [])
            except Exception:
                reasons = []
            rc = f"gate_{gate_dec}"
            msg = ",".join([str(x) for x in reasons[:6] if str(x).strip()]) if reasons else f"gate_{gate_dec}"
            stuck = {"stuck_at": "gate", "stuck_since_ms": int(st_ms), "reason_code": rc, "reason": msg}
        elif _has("shadow_config_apply"):
            ap = _latest_artifact("shadow_config_apply")
            try:
                ok0 = ap.get("ok")
                if ok0 is not None and (not bool(ok0)):
                    st_ms = int(ap.get("ts") or latest_ts or _now_ms())
                    reason = str((ap.get("response") if isinstance(ap.get("response"), dict) else {}).get("error") or ap.get("error") or "apply_failed")
                    stuck = {"stuck_at": "apply", "stuck_since_ms": int(st_ms), "reason_code": "apply_failed", "reason": reason}
            except Exception:
                pass
    else:
        for s in steps:
            if str(s.get("status") or "") in ("WAIT", "RUN"):
                try:
                    last_ts = int(latest_ts or _now_ms())
                except Exception:
                    last_ts = int(_now_ms())
                stuck = {"stuck_at": str(s.get("key") or ""), "stuck_since_ms": int(last_ts), "reason_code": "waiting", "reason": "waiting_for_artifact"}
                break

    return prog, stuck, int(latest_ts or 0)


@app.route("/automation/cards/state", methods=["GET"])
def automation_cards_state():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    include_details = False
    try:
        include_details = str(request.args.get("details") or "").strip().lower() in ("1", "true", "yes", "on")
    except Exception:
        include_details = False
    now_ms = int(_now_ms())
    rows = _pipeline_artifacts_tail(tail_bytes=800_000, max_lines=6000)
    approvals_pending = _approvals_pending_by_trace(max_lines=1500, max_bytes=600_000)

    st_shadow = TRACKER_STATE.get("shadow_automation") if isinstance(TRACKER_STATE.get("shadow_automation"), dict) else {}
    shadow_trace = str((st_shadow or {}).get("active_trace_id") or (st_shadow or {}).get("last_trace_id") or "").strip() or None

    st_paramopt_auto = TRACKER_STATE.get("paramopt_automation") if isinstance(TRACKER_STATE.get("paramopt_automation"), dict) else {}
    st_paramopt_last = TRACKER_STATE.get("paramopt_daily_last") if isinstance(TRACKER_STATE.get("paramopt_daily_last"), dict) else {}
    st_paramopt_explore_auto = TRACKER_STATE.get("paramopt_explore_automation") if isinstance(TRACKER_STATE.get("paramopt_explore_automation"), dict) else {}
    st_paramopt_explore_last = TRACKER_STATE.get("paramopt_explore_last") if isinstance(TRACKER_STATE.get("paramopt_explore_last"), dict) else {}
    paramopt_trace = str((st_paramopt_auto or {}).get("active_trace_id") or (st_paramopt_auto or {}).get("last_trace_id") or "").strip() or None
    if not paramopt_trace:
        paramopt_trace = str((st_paramopt_last or {}).get("trace_id") or "").strip() or None
    paramopt_explore_trace = str((st_paramopt_explore_auto or {}).get("active_trace_id") or (st_paramopt_explore_auto or {}).get("last_trace_id") or "").strip() or None
    if not paramopt_explore_trace:
        paramopt_explore_trace = str((st_paramopt_explore_last or {}).get("trace_id") or "").strip() or None

    supply_trace = _pipeline_latest_trace_for_kinds(rows, ["repo_fetch", "repo_scan", "candidate_strategies", "baseline_report", "gating_report", "approval_request"])

    st_sysmon = TRACKER_STATE.get("system_monitor") if isinstance(TRACKER_STATE.get("system_monitor"), dict) else {}
    system_monitor_trace = str((st_sysmon or {}).get("active_trace_id") or (st_sysmon or {}).get("last_trace_id") or "").strip() or None

    st_gtw = TRACKER_STATE.get("gtw") if isinstance(TRACKER_STATE.get("gtw"), dict) else {}
    gtw_trace = str((st_gtw or {}).get("active_trace_id") or (st_gtw or {}).get("last_trace_id") or "").strip() or None
    if not gtw_trace:
        gtw_trace = _pipeline_latest_trace_for_kinds(rows, ["gtw.decision_package", "gtw.triggered", "gtw.macro_analysis", "gtw.trade_analysis"])

    shadow_enabled = bool(AUTOMATION.get("enable_shadow_automation_loop", False))
    shadow_autostart = bool(AUTOMATION.get("shadow_automation_autostart", False))
    paramopt_enabled = bool(AUTOMATION.get("enable_paramopt_daily", False))
    gtw_enabled = bool(AUTOMATION.get("enable_gtw", False))
    gtw_autostart = bool(AUTOMATION.get("gtw_autostart", False))
    twitter_enabled = _agent_push_cfg_bool("twitter_enabled", False)

    cards: List[Dict[str, Any]] = []

    prog_gtw, stuck_gtw, upd_gtw = _automation_progress_build(trace_id=str(gtw_trace or ""), mode="gtw", rows=rows, approvals_pending=approvals_pending)
    gtw_status = "ON" if gtw_enabled else "OFF"
    try:
        cd_until = int((st_gtw or {}).get("cooldown_until_ms") or 0)
    except Exception:
        cd_until = 0
    if cd_until > 0 and int(now_ms) < int(cd_until):
        gtw_status = "BLOCKED"
        stuck_gtw = {"stuck_at": "cooldown", "stuck_since_ms": int(now_ms), "reason_code": "cooldown_active", "reason": "cooldown_active"}
    elif gtw_enabled and prog_gtw and int(prog_gtw.get("pct") or 0) < 100:
        gtw_status = "RUNNING"
    cards.append(
        {
            "schema_version": "v1",
            "card_id": "gtw_global_workflow",
            "status": gtw_status,
            "updated_at_ms": int(upd_gtw or now_ms),
            "trace_id": gtw_trace,
            "progress": prog_gtw,
            "stuck": stuck_gtw,
            "actions": [
                {"id": "toggle_gtw", "label": ("关闭" if gtw_enabled else "开启"), "kind": "controlled", "request": {"type": "automation.config", "payload": {"enable_gtw": (not gtw_enabled)}}},
                {"id": "toggle_gtw_autostart", "label": ("关闭自动启动" if gtw_autostart else "开启自动启动"), "kind": "controlled", "request": {"type": "automation.config", "payload": {"gtw_autostart": (not gtw_autostart)}}},
                {"id": "gtw_run_now", "label": "运行一次", "kind": "controlled", "request": {"type": "automation.gtw.run", "payload": {"force": True}}},
            ]
            + (
                [
                    {"id": "view_pipeline", "label": "查看流水线", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(gtw_trace))}#pipeline"},
                    {"id": "trace_replay", "label": "查看 trace 回放", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(gtw_trace))}#trace_replay"},
                ]
                if gtw_trace
                else []
            ),
        }
    )

    prog_shadow, stuck_shadow, upd_shadow = _automation_progress_build(trace_id=str(shadow_trace or ""), mode="shadow_loop", rows=rows, approvals_pending=approvals_pending)
    shadow_status = "ON" if shadow_enabled else "OFF"
    if shadow_enabled and prog_shadow and int(prog_shadow.get("pct") or 0) < 100:
        shadow_status = "RUNNING"
    if isinstance(stuck_shadow, dict) and str(stuck_shadow.get("reason_code") or "") == "approval_pending":
        shadow_status = "BLOCKED"
    cards.append(
        {
            "schema_version": "v1",
            "card_id": "shadow_switch",
            "status": shadow_status,
            "updated_at_ms": int(upd_shadow or now_ms),
            "trace_id": shadow_trace,
            "progress": prog_shadow,
            "stuck": stuck_shadow,
            "actions": [
                {"id": "toggle_shadow", "label": ("关闭" if shadow_enabled else "开启"), "kind": "controlled", "request": {"type": "automation.config", "payload": {"enable_shadow_automation_loop": (not shadow_enabled)}}},
                {"id": "toggle_autostart", "label": ("关闭自动启动" if shadow_autostart else "开启自动启动"), "kind": "controlled", "request": {"type": "automation.config", "payload": {"shadow_automation_autostart": (not shadow_autostart)}}},
            ]
            + (
                [
                    {"id": "view_pipeline", "label": "查看流水线", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(shadow_trace))}#pipeline"},
                    {"id": "jump_approvals", "label": "跳到审批区", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(shadow_trace))}#approvals"},
                    {"id": "trace_replay", "label": "查看 trace 回放", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(shadow_trace))}#trace_replay"},
                ]
                if shadow_trace
                else []
            ),
        }
    )

    prog_supply, stuck_supply, upd_supply = _automation_progress_build(trace_id=str(supply_trace or ""), mode="supply_chain", rows=rows, approvals_pending=approvals_pending)
    supply_status = "ON" if supply_trace else "OFF"
    if supply_trace and prog_supply and int(prog_supply.get("pct") or 0) < 100:
        supply_status = "RUNNING"
    if isinstance(stuck_supply, dict) and str(stuck_supply.get("reason_code") or "") == "approval_pending":
        supply_status = "BLOCKED"
    cards.append(
        {
            "schema_version": "v1",
            "card_id": "strategy_supply_chain",
            "status": supply_status,
            "updated_at_ms": int(upd_supply or now_ms),
            "trace_id": supply_trace,
            "progress": prog_supply,
            "stuck": stuck_supply,
            "actions": [
                {"id": "trigger_supply_chain", "label": "触发（沙箱）", "kind": "controlled", "request": {"type": "automation.supply_chain.run", "payload": {"mode": "auto", "timerange_days": 60}}},
                {"id": "retry_supply_chain", "label": "重试", "kind": "controlled", "request": {"type": "automation.supply_chain.run", "payload": {"mode": "retry", "trace_id": supply_trace}}} if supply_trace else {"id": "retry_supply_chain", "label": "重试", "kind": "controlled", "request": {"type": "automation.supply_chain.run", "payload": {"mode": "retry"}}},
            ]
            + (
                [
                    {"id": "view_pipeline", "label": "查看流水线", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(supply_trace))}#pipeline"},
                    {"id": "jump_approvals", "label": "跳到审批区", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(supply_trace))}#approvals"},
                    {"id": "trace_replay", "label": "查看 trace 回放", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(supply_trace))}#trace_replay"},
                ]
                if supply_trace
                else []
            ),
        }
    )

    cards.append(
        {
            "schema_version": "v1",
            "card_id": "strategy_shadow_loop",
            "status": ("BLOCKED" if not shadow_enabled else (shadow_status if shadow_trace else "ON")),
            "updated_at_ms": int(upd_shadow or now_ms),
            "trace_id": shadow_trace,
            "progress": prog_shadow,
            "stuck": ({"stuck_at": "shadow_switch", "stuck_since_ms": int(now_ms), "reason_code": "shadow_disabled", "reason": "shadow_disabled"} if not shadow_enabled else stuck_shadow),
            "actions": [
                {"id": "trigger_shadow_loop", "label": "触发", "kind": "controlled", "request": {"type": "automation.shadow_loop.run", "payload": {"mode": "new"}}},
                {"id": "retry_shadow_loop", "label": "重试", "kind": "controlled", "request": {"type": "automation.shadow_loop.run", "payload": {"mode": "retry", "trace_id": shadow_trace}}} if shadow_trace else {"id": "retry_shadow_loop", "label": "重试", "kind": "controlled", "request": {"type": "automation.shadow_loop.run", "payload": {"mode": "retry"}}},
            ]
            + (
                [
                    {"id": "jump_approvals", "label": "跳到审批区", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(shadow_trace))}#approvals"},
                    {"id": "view_pipeline", "label": "查看流水线", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(shadow_trace))}#pipeline"},
                    {"id": "trace_replay", "label": "查看 trace 回放", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(shadow_trace))}#trace_replay"},
                ]
                if shadow_trace
                else []
            ),
        }
    )

    prog_paramopt, stuck_paramopt, upd_paramopt = _automation_progress_build(trace_id=str(paramopt_trace or ""), mode="paramopt", rows=rows, approvals_pending=approvals_pending)
    prog_paramopt_explore, stuck_paramopt_explore, upd_paramopt_explore = _automation_progress_build(trace_id=str(paramopt_explore_trace or ""), mode="paramopt", rows=rows, approvals_pending=approvals_pending)
    paramopt_status = "ON" if paramopt_enabled else "OFF"
    if not shadow_enabled:
        paramopt_status = "BLOCKED"
        stuck_paramopt = {"stuck_at": "shadow_switch", "stuck_since_ms": int(now_ms), "reason_code": "shadow_disabled", "reason": "shadow_disabled"}
    elif paramopt_enabled and prog_paramopt and int(prog_paramopt.get("pct") or 0) < 100:
        paramopt_status = "RUNNING"
    elif paramopt_enabled and prog_paramopt_explore and int(prog_paramopt_explore.get("pct") or 0) < 100:
        paramopt_status = "RUNNING"
        if not isinstance(stuck_paramopt, dict):
            stuck_paramopt = stuck_paramopt_explore if isinstance(stuck_paramopt_explore, dict) else None
    if isinstance(stuck_paramopt, dict) and str(stuck_paramopt.get("reason_code") or "") == "approval_pending":
        paramopt_status = "BLOCKED"

    last_wrap = st_paramopt_last if isinstance(st_paramopt_last, dict) else {}
    out0 = last_wrap.get("out") if isinstance(last_wrap.get("out"), dict) else {}
    ops_view = None
    if include_details:
        outbox_sig = _agent_outbox_chat_sig(outbox=_agent_outbox_dir(), max_files=8)
        try:
            ts_cached = int(_PARAMOPT_LAST_WRAP_CACHE.get("ts_ms") or 0)
        except Exception:
            ts_cached = 0
        if (not (isinstance(out0.get("summary"), dict) and isinstance(out0.get("stages"), list))):
            hit_last = (
                str(_PARAMOPT_LAST_WRAP_CACHE.get("sig") or "") == str(outbox_sig)
                and int(now_ms) - int(ts_cached) <= 60_000
                and isinstance(_PARAMOPT_LAST_WRAP_CACHE.get("value"), dict)
            )
            if hit_last:
                last_wrap = _PARAMOPT_LAST_WRAP_CACHE.get("value") if isinstance(_PARAMOPT_LAST_WRAP_CACHE.get("value"), dict) else last_wrap
            else:
                ow = _paramopt_last_chain_wrap_from_outbox(max_files=4, max_lines=2000, max_bytes=1_500_000)
                if isinstance(ow, dict) and isinstance(ow.get("out"), dict):
                    last_wrap = ow
                    _PARAMOPT_LAST_WRAP_CACHE["sig"] = str(outbox_sig)
                    _PARAMOPT_LAST_WRAP_CACHE["ts_ms"] = int(now_ms)
                    _PARAMOPT_LAST_WRAP_CACHE["value"] = _json_sanitize(ow)
        try:
            ts_cached_ops = int(_PARAMOPT_OPS_VIEW_CACHE.get("ts_ms") or 0)
        except Exception:
            ts_cached_ops = 0
        hit_ops = (
            str(_PARAMOPT_OPS_VIEW_CACHE.get("sig") or "") == str(outbox_sig)
            and int(now_ms) - int(ts_cached_ops) <= 30_000
            and isinstance(_PARAMOPT_OPS_VIEW_CACHE.get("value"), dict)
        )
        if hit_ops:
            ops_view = _PARAMOPT_OPS_VIEW_CACHE.get("value") if isinstance(_PARAMOPT_OPS_VIEW_CACHE.get("value"), dict) else None
        else:
            try:
                ops_view = _paramopt_ops_view_recent(max_runs=24, max_lines=1500, max_bytes=1_500_000)
                _PARAMOPT_OPS_VIEW_CACHE["sig"] = str(outbox_sig)
                _PARAMOPT_OPS_VIEW_CACHE["ts_ms"] = int(now_ms)
                _PARAMOPT_OPS_VIEW_CACHE["value"] = _json_sanitize(ops_view if isinstance(ops_view, dict) else {})
            except Exception:
                ops_view = None

    cards.append(
        {
            "schema_version": "v1",
            "card_id": "paramopt_automation",
            "status": paramopt_status,
            "updated_at_ms": int(upd_paramopt or now_ms),
            "trace_id": paramopt_trace,
            "progress": prog_paramopt,
            "stuck": stuck_paramopt,
            "details": {
                "automation": {
                    "loss_trigger_streak_k": int(AUTOMATION.get("paramopt_loss_trigger_streak_k", 2) or 2),
                    "loss_auto_no_manual_approval": bool(AUTOMATION.get("paramopt_loss_auto_no_manual_approval", True)),
                    "trade_cycle_enabled": bool(AUTOMATION.get("paramopt_trade_cycle_enabled", True)),
                    "trade_cycle_period_sec": int(AUTOMATION.get("paramopt_trade_cycle_period_sec", 14400) or 14400),
                    "explore_cycle_enabled": bool(AUTOMATION.get("paramopt_explore_cycle_enabled", True)),
                    "explore_cycle_period_sec": int(AUTOMATION.get("paramopt_explore_cycle_period_sec", 3600) or 3600),
                    "explore_approval_ttl_hours": int(AUTOMATION.get("paramopt_explore_approval_ttl_hours", 24) or 24),
                    "explore_llm_provider": str(AUTOMATION.get("paramopt_explore_llm_provider", "openai_compat") or "openai_compat"),
                    "explore_llm_model": str(AUTOMATION.get("paramopt_explore_llm_model", "claude-sonnet-4-5") or "claude-sonnet-4-5"),
                    "explore_llm_remote_fallback": bool(AUTOMATION.get("paramopt_explore_llm_remote_fallback", True)),
                },
                "last": _json_sanitize(last_wrap),
                "last_explore": _json_sanitize(st_paramopt_explore_last),
                "scenario_ensure_last": _json_sanitize(TRACKER_STATE.get("paramopt_scenarios_ensure_last") if isinstance(TRACKER_STATE.get("paramopt_scenarios_ensure_last"), dict) else {}),
                "ops_view": (_json_sanitize(ops_view) if include_details else {}),
                "ops_view_passive": (_json_sanitize(ops_view) if include_details else {}),
                "ops_view_explore": (_json_sanitize(ops_view) if include_details else {}),
                "trace_passive": paramopt_trace,
                "trace_explore": paramopt_explore_trace,
                "progress_explore": _json_sanitize(prog_paramopt_explore),
                "stuck_explore": _json_sanitize(stuck_paramopt_explore),
                "updated_at_explore_ms": int(upd_paramopt_explore or 0),
            },
            "actions": [
                {"id": "toggle_paramopt_daily", "label": ("关闭" if paramopt_enabled else "开启"), "kind": "controlled", "request": {"type": "automation.config", "payload": {"enable_paramopt_daily": (not paramopt_enabled)}}},
                {
                    "id": "trigger_paramopt_sandbox",
                    "label": "手动触发（沙箱）",
                    "kind": "controlled",
                    "request": {"type": "automation.paramopt.trigger", "payload": {"mode": "sandbox", "budget": {"n_init": 3, "n_iter": 10, "skip_robustness": True, "auto_draft": True, "no_manual_approval": False}}},
                },
                {
                    "id": "trigger_paramopt_explore_sandbox",
                    "label": "探索触发（策略库）",
                    "kind": "controlled",
                    "request": {"type": "automation.paramopt.explore.trigger", "payload": {"mode": "sandbox", "budget": {"n_init": 3, "n_iter": 10, "skip_robustness": True, "auto_draft": True, "no_manual_approval": False}}},
                },
            ]
            + (
                [
                    {"id": "view_pipeline", "label": "查看流水线", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(paramopt_trace))}#pipeline"},
                    {"id": "jump_approvals", "label": "跳到审批区", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(paramopt_trace))}#approvals"},
                    {"id": "trace_replay", "label": "查看 trace 回放", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(paramopt_trace))}#trace_replay"},
                ]
                if paramopt_trace
                else []
            ),
        }
    )

    twitter_status = "ON" if twitter_enabled else "OFF"
    try:
        tm = _agent_twitter_metrics(window_sec=3600, tail_bytes=2_000_000)
    except Exception:
        tm = {"ok": False}
    if twitter_enabled and isinstance(tm, dict):
        try:
            fail = int(tm.get("receipts_fail") or 0)
            ok_n = int(tm.get("receipts_ok") or 0)
            if fail > 0 and (fail >= ok_n):
                twitter_status = "ERROR"
        except Exception:
            pass
    last_receipt = (tm.get("last_receipt") if isinstance(tm, dict) and isinstance(tm.get("last_receipt"), dict) else {}) if isinstance(tm, dict) else {}
    try:
        last_receipt_ok = bool(last_receipt.get("ok"))
    except Exception:
        last_receipt_ok = False
    try:
        last_receipt_ts = int(last_receipt.get("ts") or 0)
    except Exception:
        last_receipt_ts = 0
    try:
        pending_n = int(tm.get("pending") or 0) if isinstance(tm, dict) else 0
    except Exception:
        pending_n = 0
    cards.append(
        {
            "schema_version": "v1",
            "card_id": "twitter_delivery",
            "status": twitter_status,
            "updated_at_ms": int((tm.get("ts") if isinstance(tm, dict) else 0) or now_ms),
            "trace_id": None,
            "progress": {
                "schema_version": "v1",
                "pct": (100 if (twitter_enabled and bool(last_receipt_ok)) else (0 if not twitter_enabled else 50)),
                "steps": [
                    {"key": "auth", "label": "auth ok", "status": ("DONE" if twitter_enabled else "WAIT"), "ts_ms": int((tm.get("ts") if isinstance(tm, dict) else 0) or 0) or None, "evidence": {"twitter_enabled": bool(twitter_enabled)}},
                    {"key": "outbox", "label": "outbox 非阻塞", "status": ("DONE" if int(pending_n) <= 0 else "RUN"), "ts_ms": int((tm.get("ts") if isinstance(tm, dict) else 0) or 0) or None, "evidence": {"pending": int(pending_n)}},
                    {"key": "last", "label": "最近一次投递成功", "status": ("DONE" if bool(last_receipt_ok) else "WAIT"), "ts_ms": (int(last_receipt_ts) if int(last_receipt_ts) > 0 else None)},
                ],
            },
            "stuck": (
                {"stuck_at": "outbox", "stuck_since_ms": int(now_ms), "reason_code": "queue_full", "reason": "twitter_outbox_pending"} if (twitter_enabled and int(pending_n) > 0) else None
            ),
            "actions": [
                {"id": "go_skills", "label": "查看 Skills", "kind": "navigate", "href": "/agent/skills"},
                {"id": "go_twitter_metrics", "label": "查看 metrics", "kind": "navigate", "href": "/agent/ops#twitter"},
            ],
        }
    )

    web3_enabled = bool(AUTOMATION.get("enable_web3_market_digest", False))
    st_web3 = TRACKER_STATE.get("web3_market_digest") if isinstance(TRACKER_STATE.get("web3_market_digest"), dict) else {}
    try:
        web3_last_ms = int((st_web3 or {}).get("last_run_ms") or 0)
    except Exception:
        web3_last_ms = 0
    web3_status = "ON" if web3_enabled else "OFF"
    try:
        per = _web3_market_digest_cfg_int("web3_market_digest_period_sec", 3600, lo=30, hi=24 * 3600)
    except Exception:
        per = 300
    if web3_enabled and int(web3_last_ms) <= 0:
        web3_status = "ERROR"
    try:
        lp = (st_web3 or {}).get("last_publish") if isinstance((st_web3 or {}).get("last_publish"), dict) else {}
    except Exception:
        lp = {}
    stuck_web3 = None
    if web3_enabled and isinstance(lp, dict) and bool(lp.get("skipped")):
        stuck_web3 = {"stuck_at": "publish", "stuck_since_ms": int(now_ms), "reason_code": str(lp.get("reason") or "publish_skipped"), "reason": str(lp.get("reason") or "publish_skipped")}
    cards.append(
        {
            "schema_version": "v1",
            "card_id": "web3_market_digest",
            "status": web3_status,
            "updated_at_ms": int(web3_last_ms or now_ms),
            "trace_id": (str((st_web3 or {}).get("last_trace_id") or "").strip() or None),
            "progress": {
                "schema_version": "v1",
                "pct": (100 if (web3_enabled and int(web3_last_ms) > 0) else (0 if not web3_enabled else 50)),
                "steps": [
                    {"key": "auto", "label": "自动轮询", "status": ("DONE" if web3_enabled else "WAIT"), "ts_ms": (int(web3_last_ms) if int(web3_last_ms) > 0 else None), "evidence": {"period_sec": int(per)}},
                    {"key": "digest", "label": "生成 digest", "status": ("DONE" if int(web3_last_ms) > 0 else ("WAIT" if not web3_enabled else "RUN")), "ts_ms": (int(web3_last_ms) if int(web3_last_ms) > 0 else None)},
                    {"key": "publish", "label": "入队 thread", "status": ("DONE" if (isinstance(lp, dict) and bool(lp.get("ok"))) else ("WAIT" if not web3_enabled else "RUN")), "ts_ms": (int(web3_last_ms) if int(web3_last_ms) > 0 else None), "evidence": {"last_publish": _json_sanitize(lp)}},
                ],
            },
            "stuck": stuck_web3,
            "actions": [
                {"id": "toggle_web3_market_digest", "label": ("关闭" if web3_enabled else "开启"), "kind": "controlled", "request": {"type": "automation.config", "payload": {"enable_web3_market_digest": (not web3_enabled)}}},
                {"id": "web3_market_digest_run_now", "label": "运行一次", "kind": "controlled", "request": {"type": "automation.web3.market_digest.run", "payload": {"force": True}}},
                {"id": "go_skills", "label": "查看 Skills", "kind": "navigate", "href": "/agent/skills"},
            ],
        }
    )

    prog_sys, stuck_sys, upd_sys = _automation_progress_build(trace_id=str(system_monitor_trace or ""), mode="system_monitor", rows=rows, approvals_pending=approvals_pending)
    sys_pair = _system_monitor_default_pair()
    sys_strategy = _system_monitor_default_strategy("user_data/config_local_backtest.json")
    sys_auto_enabled = bool(AUTOMATION.get("enable_sys_monitor_bugfix", True))
    sys_status = "ON" if sys_auto_enabled else "OFF"
    if system_monitor_trace and prog_sys and int(prog_sys.get("pct") or 0) < 100:
        sys_status = "RUNNING"
    if isinstance(stuck_sys, dict) and str(stuck_sys.get("reason_code") or "") == "approval_pending":
        sys_status = "BLOCKED"
    try:
        if prog_sys and any(str(s.get("status") or "") == "FAIL" for s in (prog_sys.get("steps") if isinstance(prog_sys.get("steps"), list) else [])):
            sys_status = "ERROR"
    except Exception:
        pass
    if not sys_auto_enabled:
        stuck_sys = {"stuck_at": "system_monitor", "stuck_since_ms": int(now_ms), "reason_code": "disabled", "reason": "sys_monitor_auto_disabled"}
    sys_auto_state = TRACKER_STATE.get("sys_monitor_auto") if isinstance(TRACKER_STATE.get("sys_monitor_auto"), dict) else {}
    try:
        last_light_ms = int((sys_auto_state or {}).get("last_light_ms") or 0)
    except Exception:
        last_light_ms = 0
    try:
        last_global_ms = int((sys_auto_state or {}).get("last_global_ms") or 0)
    except Exception:
        last_global_ms = 0
    if (not system_monitor_trace) and (not prog_sys):
        prog_sys = {
            "schema_version": "v1",
            "pct": (100 if sys_auto_enabled else 0),
            "steps": [
                {"key": "auto", "label": "自动轮询", "status": ("DONE" if sys_auto_enabled else "WAIT"), "ts_ms": (int(upd_sys or 0) or None), "evidence": {"enabled": bool(sys_auto_enabled)}},
                {"key": "feedback_5m", "label": "反馈信号(5m)", "status": ("DONE" if int((sys_auto_state or {}).get("last_feedback_ms") or 0) > 0 else "WAIT"), "ts_ms": (int((sys_auto_state or {}).get("last_feedback_ms") or 0) if int((sys_auto_state or {}).get("last_feedback_ms") or 0) > 0 else None)},
                {"key": "light", "label": "重点检查(1h)", "status": ("DONE" if int(last_light_ms) > 0 else "WAIT"), "ts_ms": (int(last_light_ms) if int(last_light_ms) > 0 else None)},
                {"key": "global", "label": "全局检查(每日)", "status": ("DONE" if int(last_global_ms) > 0 else "WAIT"), "ts_ms": (int(last_global_ms) if int(last_global_ms) > 0 else None)},
            ],
        }
    cards.append(
        {
            "schema_version": "v1",
            "card_id": "other",
            "status": sys_status,
            "updated_at_ms": int(upd_sys or now_ms),
            "trace_id": system_monitor_trace,
            "progress": prog_sys,
            "stuck": stuck_sys,
            "actions": [
                {"id": "toggle_sys_monitor_bugfix", "label": ("关闭自动轮询" if sys_auto_enabled else "开启自动轮询"), "kind": "controlled", "request": {"type": "automation.config", "payload": {"enable_sys_monitor_bugfix": (not sys_auto_enabled)}}},
                {"id": "trigger_system_monitor", "label": "运行检查（沙箱）", "kind": "controlled", "request": {"type": "automation.system_monitor.run", "payload": {"mode": "new", "pair": sys_pair, "strategy": sys_strategy, "timerange_days": 60, "lookback_days": 7, "run_link_check": True, "run_backtest": True, "run_triage": True, "generate_changeset": True, "request_approval": True}}},
                {"id": "retry_system_monitor", "label": "重试", "kind": "controlled", "request": {"type": "automation.system_monitor.run", "payload": {"mode": "retry", "trace_id": system_monitor_trace}}} if system_monitor_trace else {"id": "retry_system_monitor", "label": "重试", "kind": "controlled", "request": {"type": "automation.system_monitor.run", "payload": {"mode": "retry"}}},
            ]
            + (
                [
                    {"id": "view_pipeline", "label": "查看流水线", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(system_monitor_trace))}#pipeline"},
                    {"id": "trace_replay", "label": "查看 trace 回放", "kind": "navigate", "href": f"/agent/ops?trace_id={urllib_parse.quote(str(system_monitor_trace))}#trace_replay"},
                ]
                if system_monitor_trace
                else []
            ),
        }
    )

    return jsonify({"ok": True, "schema_version": "v1", "ts": int(now_ms), "cards": cards}), 200


@app.route("/automation/nanoclaw/upgrade/monitor", methods=["GET"])
def automation_nanoclaw_upgrade_monitor():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403

    try:
        lookback_hours = int(request.args.get("lookback_hours") or int(AUTOMATION.get("nanoclaw_monitor_window_hours", 168) or 168))
    except Exception:
        lookback_hours = 168
    lookback_hours = max(1, min(24 * 90, int(lookback_hours)))

    try:
        max_lines = int(request.args.get("max_lines") or 6000)
    except Exception:
        max_lines = 6000
    max_lines = max(200, min(20000, int(max_lines)))

    try:
        max_bytes = int(request.args.get("max_bytes") or 6_000_000)
    except Exception:
        max_bytes = 6_000_000
    max_bytes = max(200_000, min(40_000_000, int(max_bytes)))

    now_ms = int(_now_ms())
    start_ms = int(now_ms) - int(lookback_hours) * 3600 * 1000

    def _recent_jsonl_records(stem: str) -> List[Dict[str, Any]]:
        paths = _agent_outbox_recent_paths(str(stem), days=max(1, int(math.ceil(float(lookback_hours) / 24.0))), now_ms=int(now_ms))
        out: List[Dict[str, Any]] = []
        lines_used = 0
        bytes_used = 0
        for p in paths:
            if lines_used >= int(max_lines) or bytes_used >= int(max_bytes):
                break
            try:
                if str(p.name).lower().endswith(".gz"):
                    chunk = _tail_lines_gzip(p, max_lines=max(1, int(max_lines) - int(lines_used)))
                else:
                    chunk = _tail_lines(p, max_lines=max(1, int(max_lines) - int(lines_used)), max_bytes=max(1024, int(max_bytes) - int(bytes_used)))
            except Exception:
                chunk = []
            for ln in chunk:
                if lines_used >= int(max_lines) or bytes_used >= int(max_bytes):
                    break
                s = str(ln or "").strip()
                if not s:
                    continue
                try:
                    b = len(s.encode("utf-8", errors="ignore"))
                except Exception:
                    b = len(s)
                if bytes_used + int(b) > int(max_bytes):
                    break
                try:
                    obj = json.loads(s)
                except Exception:
                    continue
                if not isinstance(obj, dict):
                    continue
                try:
                    ts_i = int(obj.get("ts") or 0)
                except Exception:
                    ts_i = 0
                if ts_i > 0 and ts_i < 10_000_000_000:
                    ts_i = int(ts_i) * 1000
                if int(ts_i) > 0 and int(ts_i) < int(start_ms):
                    continue
                out.append(obj)
                lines_used += 1
                bytes_used += int(b)
        return out

    rca_rows = _recent_jsonl_records("rca")
    approvals_rows = _recent_jsonl_records("approvals")
    audit_rows = _recent_jsonl_records("audit_actions")

    report_total = 0
    report_hits = 0
    report_samples: List[Dict[str, Any]] = []
    for row in rca_rows:
        if str(row.get("event_type") or "").strip() != "system.monitor.report":
            continue
        report_total += 1
        result = row.get("result") if isinstance(row.get("result"), dict) else {}
        summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
        faq_hits = summary.get("faq_hits") if isinstance(summary.get("faq_hits"), list) else []
        draft_id = str(summary.get("changeset_draft_id") or "").strip()
        approval_id = str(summary.get("approval_id") or "").strip()
        actionable = bool(faq_hits) or bool(draft_id) or bool(approval_id)
        if actionable:
            report_hits += 1
        if len(report_samples) < 6:
            report_samples.append(
                {
                    "trace_id": str(row.get("trace_id") or ""),
                    "severity": str(row.get("severity") or ""),
                    "faq_hits_n": int(len(faq_hits)),
                    "changeset_draft_id": draft_id or None,
                    "approval_id": approval_id or None,
                    "actionable": bool(actionable),
                    "ts": row.get("ts"),
                }
            )

    approved_n = 0
    rejected_n = 0
    pending_n = 0
    approvals_total = 0
    for row in approvals_rows:
        approvals_total += 1
        dec = str(row.get("decision") or "").strip().lower()
        if dec.startswith("pending"):
            pending_n += 1
        elif dec in ("approve", "approved", "ok", "pass", "yes"):
            approved_n += 1
        elif dec in ("reject", "rejected", "deny", "denied", "no", "fail", "failed"):
            rejected_n += 1

    rollback_n = 0
    applied_n = 0
    for row in audit_rows:
        nm = str(row.get("name") or "").strip().lower()
        payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
        ok_v = payload.get("ok")
        ok_b = (bool(ok_v) if ok_v is not None else None)
        if ("rollback" in nm) or isinstance(payload.get("rollback"), dict):
            rollback_n += 1
        if (("apply" in nm) or ("config.set" in nm)) and (ok_b is not False):
            applied_n += 1

    try:
        first_report_hit_rate = (float(report_hits) / float(report_total)) if int(report_total) > 0 else None
    except Exception:
        first_report_hit_rate = None
    appr_denom = int(approved_n) + int(rejected_n)
    try:
        approval_pass_rate = (float(approved_n) / float(appr_denom)) if appr_denom > 0 else None
    except Exception:
        approval_pass_rate = None
    try:
        rollback_rate = (float(rollback_n) / float(applied_n)) if int(applied_n) > 0 else None
    except Exception:
        rollback_rate = None

    try:
        th_first_min = float(AUTOMATION.get("nanoclaw_threshold_first_report_hit_rate_min", 0.55) or 0.55)
    except Exception:
        th_first_min = 0.55
    try:
        th_approval_min = float(AUTOMATION.get("nanoclaw_threshold_approval_pass_rate_min", 0.60) or 0.60)
    except Exception:
        th_approval_min = 0.60
    try:
        th_rollback_max = float(AUTOMATION.get("nanoclaw_threshold_rollback_rate_max", 0.15) or 0.15)
    except Exception:
        th_rollback_max = 0.15
    try:
        min_reports = int(AUTOMATION.get("nanoclaw_threshold_min_reports", 20) or 20)
    except Exception:
        min_reports = 20
    try:
        min_approval_decisions = int(AUTOMATION.get("nanoclaw_threshold_min_approval_decisions", 20) or 20)
    except Exception:
        min_approval_decisions = 20
    try:
        min_applied_actions = int(AUTOMATION.get("nanoclaw_threshold_min_applied_actions", 10) or 10)
    except Exception:
        min_applied_actions = 10
    min_reports = max(1, min(200000, int(min_reports)))
    min_approval_decisions = max(1, min(200000, int(min_approval_decisions)))
    min_applied_actions = max(1, min(200000, int(min_applied_actions)))

    breaches: List[Dict[str, Any]] = []
    if (first_report_hit_rate is not None) and int(report_total) >= int(min_reports) and float(first_report_hit_rate) < float(th_first_min):
        breaches.append(
            {
                "metric": "first_report_hit_rate",
                "rule": "min",
                "value": round(float(first_report_hit_rate), 6),
                "threshold": float(th_first_min),
                "sample_size": int(report_total),
                "min_required": int(min_reports),
            }
        )
    if (approval_pass_rate is not None) and int(appr_denom) >= int(min_approval_decisions) and float(approval_pass_rate) < float(th_approval_min):
        breaches.append(
            {
                "metric": "approval_pass_rate",
                "rule": "min",
                "value": round(float(approval_pass_rate), 6),
                "threshold": float(th_approval_min),
                "sample_size": int(appr_denom),
                "min_required": int(min_approval_decisions),
            }
        )
    if (rollback_rate is not None) and int(applied_n) >= int(min_applied_actions) and float(rollback_rate) > float(th_rollback_max):
        breaches.append(
            {
                "metric": "rollback_rate",
                "rule": "max",
                "value": round(float(rollback_rate), 6),
                "threshold": float(th_rollback_max),
                "sample_size": int(applied_n),
                "min_required": int(min_applied_actions),
            }
        )

    stage_before = str(AUTOMATION.get("nanoclaw_upgrade_stage", "B") or "B").strip().upper() or "B"
    stage_after = str(stage_before)
    downgraded = False
    emitted_alarm = False
    cooldown_ok = True
    cooldown_left_sec = 0
    breach_event_id = ""
    if breaches:
        st_root = TRACKER_STATE.get("nanoclaw_upgrade_monitor")
        if not isinstance(st_root, dict):
            st_root = {}
            TRACKER_STATE["nanoclaw_upgrade_monitor"] = st_root
        try:
            cooldown_sec = int(AUTOMATION.get("nanoclaw_threshold_alert_cooldown_sec", 3600) or 3600)
        except Exception:
            cooldown_sec = 3600
        cooldown_sec = max(0, min(24 * 3600, int(cooldown_sec)))
        last_alert_ms = int(st_root.get("last_alert_ms") or 0)
        cooldown_ms = int(cooldown_sec) * 1000
        cooldown_ok = (int(now_ms) - int(last_alert_ms)) >= int(cooldown_ms)
        if not cooldown_ok:
            cooldown_left_sec = max(0, int((int(cooldown_ms) - (int(now_ms) - int(last_alert_ms))) / 1000))
        should_emit_alert = bool(AUTOMATION.get("nanoclaw_threshold_alert_enabled", True)) and bool(cooldown_ok)
        if should_emit_alert:
            alert_severity = "warn"
            if any(str((b or {}).get("metric") or "") == "rollback_rate" for b in breaches):
                alert_severity = "error"
            idem_raw = {
                "event": "nanoclaw.upgrade.threshold_breach",
                "window_h": int(lookback_hours),
                "breaches": [
                    {
                        "metric": str((b or {}).get("metric") or ""),
                        "rule": str((b or {}).get("rule") or ""),
                        "value": (b or {}).get("value"),
                        "threshold": (b or {}).get("threshold"),
                    }
                    for b in breaches
                ],
            }
            try:
                idem = hashlib.sha256(json.dumps(idem_raw, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
            except Exception:
                idem = uuid.uuid4().hex
            trace_id = hashlib.sha256(f"nanoclaw.upgrade.threshold|{int(now_ms)}|{idem}".encode("utf-8")).hexdigest()[:32]
            env = _agent_emit_envelope_event(
                event="nanoclaw.upgrade.threshold_breach",
                trace_id=str(trace_id),
                severity=str(alert_severity),
                intent_level="L2",
                ts_ms=int(now_ms),
                inputs={"lookback_hours": int(lookback_hours), "stage": str(stage_before), "window_kind": "rolling_7d"},
                evidence=[{"type": "metric.window", "source": "automation.nanoclaw.upgrade.monitor", "lookback_hours": int(lookback_hours)}],
                outputs={
                    "breaches": breaches,
                    "indicators": {
                        "first_report_hit_rate": (None if first_report_hit_rate is None else round(float(first_report_hit_rate), 6)),
                        "approval_pass_rate": (None if approval_pass_rate is None else round(float(approval_pass_rate), 6)),
                        "rollback_rate": (None if rollback_rate is None else round(float(rollback_rate), 6)),
                    },
                    "raw_counts": {"report_total": int(report_total), "approval_decisions": int(appr_denom), "applied_n": int(applied_n)},
                    "idempotency_key": str(idem),
                    "stage_before": str(stage_before),
                    "stage_after": str(stage_before),
                },
                doc_refs=[{"doc_path": "交易AI Agent 技术文档2.0.md", "section": "10.1.1.A", "rule": "B_to_C_threshold_monitoring"}],
            )
            emitted_alarm = True
            breach_event_id = str((env or {}).get("event_id") or "")
            st_root["last_alert_ms"] = int(now_ms)
            st_root["last_alert_event_id"] = str(breach_event_id or "")

        should_downgrade = bool(AUTOMATION.get("nanoclaw_threshold_auto_downgrade_enabled", True))
        tgt = str(AUTOMATION.get("nanoclaw_threshold_auto_downgrade_target_stage", "B") or "B").strip().upper() or "B"
        if should_downgrade and str(stage_before).upper() != str(tgt).upper():
            AUTOMATION["nanoclaw_upgrade_stage"] = str(tgt)
            stage_after = str(tgt)
            downgraded = True
            try:
                _save_config()
            except Exception:
                pass
            if emitted_alarm and isinstance(TRACKER_STATE.get("nanoclaw_upgrade_monitor"), dict):
                TRACKER_STATE["nanoclaw_upgrade_monitor"]["last_stage_after"] = str(stage_after)

    rules = {str(r.rule) for r in app.url_map.iter_rules()}
    required_rules = [
        "/automation/cards/state",
        "/automation/system_monitor/run",
        "/automation/paramopt/trigger",
        "/automation/paramopt/explore/trigger",
        "/agent/skills/execute",
        "/approvals/summary",
    ]
    chain_check = {
        "required_rules_ok": all(str(x) in rules for x in required_rules),
        "required_rules_missing": [str(x) for x in required_rules if str(x) not in rules],
        "records_window": {
            "system_monitor_reports": int(report_total),
            "approvals": int(approvals_total),
            "audit_actions": int(len(audit_rows)),
        },
        "trace_coverage": {
            "rca_with_trace_ratio": (
                float(len([x for x in rca_rows if str((x or {}).get("trace_id") or "").strip()])) / float(len(rca_rows))
                if rca_rows
                else None
            ),
            "approvals_with_trace_ratio": (
                float(len([x for x in approvals_rows if str((x or {}).get("trace_id") or "").strip()])) / float(len(approvals_rows))
                if approvals_rows
                else None
            ),
        },
    }

    out = {
        "ok": True,
        "ts": int(now_ms),
        "lookback_hours": int(lookback_hours),
        "architecture": {
            "upgrade_path": "B_to_C",
            "stage": str(AUTOMATION.get("nanoclaw_upgrade_stage", "B") or "B"),
            "stage_before_eval": str(stage_before),
            "stage_after_eval": str(stage_after),
            "ui_role": str(AUTOMATION.get("nanoclaw_page_mode", "fact_panel") or "fact_panel"),
            "nanoclaw_role": str(AUTOMATION.get("nanoclaw_orchestrator_mode", "intent_orchestrator") or "intent_orchestrator"),
            "control_plane_enabled": bool(AUTOMATION.get("nanoclaw_control_plane_enabled", True)),
            "governance_unchanged": True,
            "guardrail": {"approval_trace_confirm_live_required": True},
        },
        "indicators": {
            "first_report_hit_rate": (None if first_report_hit_rate is None else round(float(first_report_hit_rate), 4)),
            "approval_pass_rate": (None if approval_pass_rate is None else round(float(approval_pass_rate), 4)),
            "rollback_rate": (None if rollback_rate is None else round(float(rollback_rate), 4)),
            "raw_counts": {
                "report_total": int(report_total),
                "report_hits": int(report_hits),
                "approved": int(approved_n),
                "rejected": int(rejected_n),
                "pending": int(pending_n),
                "applied": int(applied_n),
                "rollback": int(rollback_n),
            },
            "samples": {"first_reports": report_samples},
        },
        "threshold_policy": {
            "window_kind": "rolling_7d",
            "enabled": True,
            "thresholds": {
                "first_report_hit_rate_min": float(th_first_min),
                "approval_pass_rate_min": float(th_approval_min),
                "rollback_rate_max": float(th_rollback_max),
            },
            "minimum_samples": {
                "first_report_total": int(min_reports),
                "approval_decisions": int(min_approval_decisions),
                "applied_actions": int(min_applied_actions),
            },
            "breaches": breaches,
            "auto_downgrade": {
                "enabled": bool(AUTOMATION.get("nanoclaw_threshold_auto_downgrade_enabled", True)),
                "target_stage": str(AUTOMATION.get("nanoclaw_threshold_auto_downgrade_target_stage", "B") or "B"),
                "downgraded": bool(downgraded),
            },
            "alerting": {
                "enabled": bool(AUTOMATION.get("nanoclaw_threshold_alert_enabled", True)),
                "cooldown_sec": int(AUTOMATION.get("nanoclaw_threshold_alert_cooldown_sec", 3600) or 3600),
                "cooldown_ok": bool(cooldown_ok),
                "cooldown_left_sec": int(cooldown_left_sec),
                "emitted": bool(emitted_alarm),
                "event_id": str(breach_event_id or ""),
                "channel": "alert",
            },
        },
        "chain_check": chain_check,
    }
    return jsonify(_json_sanitize(out)), 200


def _system_monitor_default_pair() -> str:
    try:
        ex = CONFIG.get("exchange") if isinstance(CONFIG.get("exchange"), dict) else {}
    except Exception:
        ex = {}
    wl = ex.get("pair_whitelist") if isinstance(ex, dict) and isinstance(ex.get("pair_whitelist"), list) else []
    for x in wl:
        p = str(x or "").strip().upper()
        if p:
            return p
    return "BTC/USDC"


def _system_monitor_default_strategy(config_path: str) -> str:
    cfg_p = str(config_path or "").strip() or "user_data/config_local_backtest.json"
    if (".." in cfg_p) or cfg_p.startswith("/") or cfg_p.startswith("\\") or (not cfg_p.startswith("user_data/")) or (not cfg_p.lower().endswith(".json")):
        cfg_p = "user_data/config_local_backtest.json"
    p = Path(cfg_p)
    if not p.exists():
        try:
            p = (Path(__file__).resolve().parent / cfg_p)
        except Exception:
            p = Path(cfg_p)
    try:
        if p.exists() and p.is_file():
            with open(p, "r", encoding="utf-8") as f:
                obj = json.load(f) or {}
            if isinstance(obj, dict):
                s = str(obj.get("strategy") or "").strip()
                if s:
                    return s
    except Exception:
        pass
    return "Strategy005"


def _system_monitor_pick_registry_entry(*, prefer_strategy_name: Optional[str] = None) -> Optional[Dict[str, Any]]:
    reg = _strategy_registry_load()
    entries = reg.get("entries") if isinstance(reg, dict) else None
    if not isinstance(entries, dict) or not entries:
        return None
    pref = str(prefer_strategy_name or "").strip().lower()
    best: Optional[Dict[str, Any]] = None
    best_score = -1.0
    for e in entries.values():
        if not isinstance(e, dict):
            continue
        sid = str(e.get("strategy_id") or "").strip()
        z = str(e.get("source_zip") or "").strip()
        if not sid or not z:
            continue
        score = 0.0
        if pref:
            nm = str(e.get("name") or sid).strip().lower()
            if pref in nm:
                score += 1000.0
        try:
            ts_s = str(e.get("updated_at") or e.get("ts") or "").strip()
            if ts_s:
                if ts_s.isdigit():
                    score += float(ts_s) / 1e6
                else:
                    score += float(int(float(ts_s))) / 1e6
        except Exception:
            pass
        if score > best_score:
            best_score = score
            best = e
    return best


def _system_monitor_faq_hits_from_link_report(link_rep: Optional[Dict[str, Any]]) -> List[str]:
    if not isinstance(link_rep, dict):
        return []
    anomalies = link_rep.get("anomalies") if isinstance(link_rep.get("anomalies"), list) else []
    hits: List[str] = []
    for a in anomalies[:50]:
        if not isinstance(a, dict):
            continue
        k = str(a.get("symptom_code") or a.get("reason_code") or "").strip()
        if not k:
            continue
        hits.append(k)
    out: List[str] = []
    seen = set()
    for k in hits:
        if k not in seen:
            out.append(k)
            seen.add(k)
    return out[:12]


def _system_monitor_stopgap_config_patch(*, faq_hits: List[str]) -> Dict[str, Any]:
    hits = [str(x or "").strip().lower() for x in (faq_hits or []) if str(x or "").strip()]
    if not hits:
        return {}
    patch: Dict[str, Any] = {}
    rules = _agent_auto_config_rules()

    def _cur_int(key: str, default: int) -> int:
        try:
            v = CONFIG.get(key) if isinstance(CONFIG, dict) else None
            if v is None:
                return int(default)
            return int(v)
        except Exception:
            return int(default)

    def _tighten_int(key: str, default: int, direction: str) -> None:
        r = rules.get(key) if isinstance(rules, dict) else None
        if not isinstance(r, dict):
            return
        try:
            mn = int(r.get("min")) if r.get("min") is not None else None
        except Exception:
            mn = None
        try:
            mx = int(r.get("max")) if r.get("max") is not None else None
        except Exception:
            mx = None
        cur = _cur_int(key, default)
        if direction == "decrease":
            cand = cur - 1
            if mn is not None:
                cand = max(int(mn), int(cand))
        else:
            cand = cur + 1
            if mx is not None:
                cand = min(int(mx), int(cand))
        patch[key] = int(cand)

    if any(x in hits for x in ("bar_not_closed",)):
        _tighten_int("signals_dedup_ttl_sec", 3600, "increase")
        _tighten_int("signals_pair_side_cooldown_sec", 600, "increase")
        _tighten_int("signals_coin_side_cooldown_sec", 300, "increase")
        patch["signals_v1_confirm_enabled"] = True
        _tighten_int("signals_v1_confirm_n", 2, "increase")
        _tighten_int("signals_v1_confirm_m", 3, "increase")

    if any(x in hits for x in ("order_id_missing", "route_inconsistent")):
        _tighten_int("max_orders_per_minute", 12, "decrease")
        _tighten_int("order_rate_window_sec", 60, "increase")
        _tighten_int("max_open_trades", 5, "decrease")

    if any(x in hits for x in ("arena_disabled",)):
        patch["arena_enabled"] = True
        patch["three_screen_use_ml_vote"] = True

    val = _agent_config_patch_validate(patch, base_cfg=CONFIG, allow_suggest_only=False)
    if not bool(val.get("ok")):
        return {}
    out = val.get("patch") if isinstance(val.get("patch"), dict) else {}
    return out


def _system_monitor_get_json_get(path: str, qs: Dict[str, Any]) -> Any:
    try:
        from urllib.parse import urlencode
    except Exception:
        urlencode = None
    q = ""
    try:
        q = ("?" + urlencode({k: v for k, v in (qs or {}).items() if v is not None})) if urlencode else ""
    except Exception:
        q = ""
    with app.test_request_context(
        f"{path}{q}",
        method="GET",
        content_type="application/json",
        environ_base={"REMOTE_ADDR": "127.0.0.1"},
    ):
        if path == "/signals/recent":
            resp = signals_recent()
        elif path == "/orders/recent":
            resp = orders_recent()
        elif path == "/tracker/stats":
            resp = tracker_stats()
        else:
            return None
    resp0 = resp[0] if isinstance(resp, tuple) and resp else resp
    try:
        if hasattr(resp0, "get_json"):
            return resp0.get_json(force=True)
    except Exception:
        pass
    return None


def _system_monitor_link_check(*, pair: str, lookback_days: float, trace_id: str) -> Dict[str, Any]:
    now_ms = int(_now_ms())
    start_ms = int(now_ms) - int(float(max(0.1, min(3650.0, float(lookback_days)))) * 86400.0 * 1000.0)
    sigs = _system_monitor_get_json_get(
        "/signals/recent",
        {
            "limit": 120,
            "sort": "ingest",
            "pair": str(pair),
            "include_shadow": 1,
            "include_backfill": 1,
            "include_stale": 1,
            "require_bar_closed": 0,
            "no_default_filter": 1,
            "start_ts": int(start_ms),
            "end_ts": int(now_ms),
        },
    )
    orders = _system_monitor_get_json_get(
        "/orders/recent",
        {
            "limit": 200,
            "sort": "ingest",
            "pair": str(pair),
            "include_shadow": 1,
            "allow_book_id_missing": 1,
            "no_default_filter": 1,
            "start_ts": int(start_ms),
            "end_ts": int(now_ms),
        },
    )

    sig_items = sigs if isinstance(sigs, list) else (sigs.get("items") if isinstance(sigs, dict) else [])
    ord_items = orders if isinstance(orders, list) else (orders.get("items") if isinstance(orders, dict) else [])

    anomalies: List[Dict[str, Any]] = []
    examples: Dict[str, List[str]] = {"signal_not_closed": [], "order_missing_ids": [], "order_book_mismatch": []}

    try:
        for s in (sig_items or [])[:200]:
            if not isinstance(s, dict):
                continue
            if bool(s.get("bar_closed")) is False:
                eid = str(s.get("event_id") or s.get("id") or "").strip()
                if eid and len(examples["signal_not_closed"]) < 8:
                    examples["signal_not_closed"].append(eid)
    except Exception:
        pass

    try:
        for o in (ord_items or [])[:400]:
            if not isinstance(o, dict):
                continue
            cid = str(o.get("client_order_id") or "").strip()
            oid = str(o.get("order_id") or o.get("exchange_order_id") or "").strip()
            if (not cid) and (not oid):
                x = str(o.get("id") or "").strip()
                if x and len(examples["order_missing_ids"]) < 8:
                    examples["order_missing_ids"].append(x)
            try:
                b0 = _ab_norm_owner(o.get("book_id"))
                a0 = _ab_norm_owner(o.get("ab_owner"))
                if b0 and a0 and b0 != a0:
                    x = str(o.get("id") or cid or oid or "").strip()
                    if x and len(examples["order_book_mismatch"]) < 8:
                        examples["order_book_mismatch"].append(x)
            except Exception:
                pass
    except Exception:
        pass

    try:
        ui_sigs = _system_monitor_get_json_get(
            "/signals/recent",
            {
                "limit": 60,
                "sort": "ingest",
                "action": "open",
                "require_bar_closed": 1,
                "no_default_filter": 1,
                "diverse": 0,
                "per_pair": 3,
                "scan_limit": 20000,
                "include_stale": 1,
                "include_shadow": 1,
            },
        )
        ui_sigs_strategy = _system_monitor_get_json_get(
            "/signals/recent",
            {
                "limit": 60,
                "sort": "ingest",
                "action": "open",
                "require_bar_closed": 1,
                "no_default_filter": 1,
                "diverse": 0,
                "per_pair": 3,
                "scan_limit": 20000,
                "include_stale": 1,
                "include_shadow": 1,
                "ab_owner": "strategy",
                "book_id": "strategy",
            },
        )
        ui_items = ui_sigs if isinstance(ui_sigs, list) else (ui_sigs.get("items") if isinstance(ui_sigs, dict) and isinstance(ui_sigs.get("items"), list) else None)
        st_items = ui_sigs_strategy if isinstance(ui_sigs_strategy, list) else (ui_sigs_strategy.get("items") if isinstance(ui_sigs_strategy, dict) and isinstance(ui_sigs_strategy.get("items"), list) else None)
        if isinstance(ui_items, list) and isinstance(st_items, list) and len(ui_items) >= 10 and len(st_items) >= 3:
            ui_n = 0
            ui_has = 0
            for s in ui_items[:60]:
                if not isinstance(s, dict):
                    continue
                if str(s.get("action") or "").strip().lower() != "open":
                    continue
                ui_n += 1
                ar = s.get("arena")
                if isinstance(ar, dict) and isinstance(ar.get("models"), dict) and bool(ar.get("models")):
                    ui_has += 1
            st_n = 0
            st_has = 0
            for s in st_items[:60]:
                if not isinstance(s, dict):
                    continue
                if str(s.get("action") or "").strip().lower() != "open":
                    continue
                st_n += 1
                ar = s.get("arena")
                if isinstance(ar, dict) and isinstance(ar.get("models"), dict) and bool(ar.get("models")):
                    st_has += 1
            if ui_n >= 10 and st_n >= 3:
                ui_rate = float(ui_has) / float(max(1, ui_n))
                st_rate = float(st_has) / float(max(1, st_n))
                if ui_rate <= 0.05 and st_rate >= 0.2:
                    anomalies.append({"symptom_code": "arena_ui_scope_mismatch", "severity": "P3", "count": int(ui_n)})
    except Exception:
        pass

    try:
        if not bool(CONFIG.get("arena_enabled", False)):
            anomalies.append({"symptom_code": "arena_disabled", "severity": "P2", "count": 1})
    except Exception:
        pass

    if examples["signal_not_closed"]:
        anomalies.append({"symptom_code": "bar_not_closed", "severity": "P2", "count": int(len(examples["signal_not_closed"]))})
    if examples["order_missing_ids"]:
        anomalies.append({"symptom_code": "order_id_missing", "severity": "P1", "count": int(len(examples["order_missing_ids"]))})
    if examples["order_book_mismatch"]:
        anomalies.append({"symptom_code": "route_inconsistent", "severity": "P1", "count": int(len(examples["order_book_mismatch"]))})

    ok = (len(anomalies) == 0)
    return {
        "ok": bool(ok),
        "ts": int(now_ms),
        "trace_id": str(trace_id),
        "pair": str(pair),
        "window": {"start_ms": int(start_ms), "end_ms": int(now_ms), "lookback_days": float(lookback_days)},
        "anomalies": anomalies,
        "examples": examples,
        "evidence": {
            "signals_n": (len(sig_items) if isinstance(sig_items, list) else None),
            "orders_n": (len(ord_items) if isinstance(ord_items, list) else None),
        },
    }


@app.route("/automation/system_monitor/run", methods=["POST"])
def automation_system_monitor_run():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    mode = str(data.get("mode") or "new").strip().lower() or "new"
    trace_id_in = str(data.get("trace_id") or "").strip() or None
    now_ms = int(_now_ms())
    trace_id = trace_id_in if (mode == "retry" and trace_id_in) else uuid.uuid4().hex

    try:
        st = TRACKER_STATE.get("system_monitor") if isinstance(TRACKER_STATE.get("system_monitor"), dict) else {}
        if not isinstance(st, dict):
            st = {}
        st["last_trace_id"] = str(trace_id)
        st["active_trace_id"] = str(trace_id)
        st["last_run_ms"] = int(now_ms)
        TRACKER_STATE["system_monitor"] = st
    except Exception:
        pass

    pair = str(data.get("pair") or "").strip().upper() or _system_monitor_default_pair()
    strategy = (None if data.get("strategy") is None else str(data.get("strategy") or "").strip()) or None
    try:
        lookback_days = float(data.get("lookback_days") or 7.0)
    except Exception:
        lookback_days = 7.0
    lookback_days = float(max(0.1, min(3650.0, float(lookback_days))))
    try:
        timerange_days = int(data.get("timerange_days") or 60)
    except Exception:
        timerange_days = 60
    timerange_days = int(max(1, min(3650, int(timerange_days))))
    config_path = str(data.get("config") or "user_data/config_local_backtest.json")
    if (".." in config_path) or config_path.startswith("/") or config_path.startswith("\\") or (not config_path.startswith("user_data/")) or (not config_path.lower().endswith(".json")):
        config_path = "user_data/config_local_backtest.json"
    timerange = (None if data.get("timerange") is None else str(data.get("timerange") or "").strip()) or None
    if timerange is None:
        timerange = _agent_pick_timerange_for_config(config_path=config_path, days=int(timerange_days))
    if strategy is None:
        strategy = _system_monitor_default_strategy(config_path)
    try:
        timeout_sec = float(data.get("timeout_sec") or 1800)
    except Exception:
        timeout_sec = 1800.0
    timeout_sec = float(max(30.0, min(6 * 3600.0, timeout_sec)))
    run_link_check = bool(data.get("run_link_check", True))
    run_backtest = bool(data.get("run_backtest", True))
    run_triage = bool(data.get("run_triage", True))
    generate_changeset = bool(data.get("generate_changeset", True))
    request_approval = bool(data.get("request_approval", True))
    allow_auto_exec = bool(data.get("allow_auto_exec", False))
    prefer_registry_strategy = (None if data.get("prefer_registry_strategy") is None else str(data.get("prefer_registry_strategy") or "").strip()) or None

    trigger_art = _agent_pipeline_artifact_common_fields(trace_id=str(trace_id), created_at_ms=int(now_ms), producer_kind="agent")
    trigger_art.update(
        {
            "ok": True,
            "ts": int(now_ms),
            "mode": str(mode),
            "inputs": _json_sanitize(
                {
                    "pair": str(pair),
                    "strategy": str(strategy),
                    "lookback_days": float(lookback_days),
                    "timerange": str(timerange),
                    "timerange_days": int(timerange_days),
                    "config": str(config_path),
                    "timeout_sec": float(timeout_sec),
                    "run_link_check": bool(run_link_check),
                    "run_backtest": bool(run_backtest),
                }
            ),
        }
    )
    trigger_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="system_monitor_trigger.json", obj=trigger_art)
    if trigger_path and isinstance(trigger_art, dict):
        trigger_art["artifact_files"] = {"system_monitor_trigger_json": trigger_path}
    _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="system_monitor_trigger", artifact=trigger_art)

    link_rep = None
    if run_link_check:
        try:
            link_rep = _system_monitor_link_check(pair=str(pair), lookback_days=float(lookback_days), trace_id=str(trace_id))
        except Exception as e:
            link_rep = {"ok": False, "ts": int(_now_ms()), "trace_id": str(trace_id), "error": str(e)}
        link_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="system_monitor_link_check.json", obj=link_rep)
        if link_path and isinstance(link_rep, dict):
            link_rep["artifact_files"] = {"system_monitor_link_check_json": link_path}
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="system_monitor_link_check", artifact=link_rep if isinstance(link_rep, dict) else {"ok": False, "ts": int(_now_ms()), "trace_id": str(trace_id), "error": "link_check_bad_type"})

    triage_rep = None
    faq_hits: List[str] = []
    preauth: Dict[str, Any] = {"ok": False, "allowed": False}
    cfg_patch = None
    draft = None
    draft_id = None
    approval_id = None
    if run_triage:
        try:
            faq_hits = _system_monitor_faq_hits_from_link_report(link_rep if isinstance(link_rep, dict) else None)
        except Exception:
            faq_hits = []
        try:
            cfg_patch = _system_monitor_stopgap_config_patch(faq_hits=faq_hits)
        except Exception:
            cfg_patch = None
        try:
            if isinstance(cfg_patch, dict) and cfg_patch:
                lvl = _config_patch_level_info(cfg_patch, base_cfg=CONFIG)
                preauth = {"ok": True, "allowed": (str(lvl.get("level") or "").strip().upper() == "A"), "level_info": _json_sanitize(lvl)}
        except Exception:
            preauth = {"ok": False, "allowed": False}

        triage_rep = {
            "ok": True,
            "ts": int(_now_ms()),
            "trace_id": str(trace_id),
            "state": "triaged",
            "faq_hits": [str(x) for x in faq_hits if str(x).strip()][:12],
            "preauthorized": _json_sanitize(preauth),
            "proposed_config_patch": (_json_sanitize(cfg_patch) if isinstance(cfg_patch, dict) else None),
            "missing_context": [],
            "doc_refs": _json_sanitize(
                _agent_chat_enforce_doc_refs(
                    [
                        {"doc_path": "交易AI Agent 技术文档2.0.md", "section": "5.4.2", "rule": "两层准入口径"},
                        {"doc_path": "交易AI Agent 技术文档2.0.md", "section": "5.5.1", "rule": "Event Protocol"},
                    ]
                )
            ),
        }
        triage_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="system_monitor_triage.json", obj=triage_rep)
        if triage_path and isinstance(triage_rep, dict):
            triage_rep["artifact_files"] = {"system_monitor_triage_json": triage_path}
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="system_monitor_triage", artifact=triage_rep)
        try:
            _agent_outbox_append_jsonl(
                "chat.jsonl",
                {"id": uuid.uuid4().hex, "trace_id": str(trace_id), "ts": int(_now_ms()), "type": "system.monitor.triaged", "channel": "workflow", "faq_hits": [str(x) for x in faq_hits if str(x).strip()][:12], "preauthorized": _json_sanitize(preauth)},
            )
        except Exception:
            pass

    bt_rep = None
    if run_backtest:
        try:
            bt_rep = _run_backtest(config_path, timerange, strategy=str(strategy), strategy_path=None, env_overrides=None, timeout_sec=float(timeout_sec))
        except Exception as e:
            bt_rep = {"ok": False, "error": str(e)}
        bt_art = {"ok": bool(bt_rep.get("ok")) if isinstance(bt_rep, dict) else False, "ts": int(_now_ms()), "trace_id": str(trace_id), "pair": str(pair), "strategy": str(strategy), "timerange": str(timerange), "result": _json_sanitize(bt_rep)}
        bt_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="system_monitor_backtest.json", obj=bt_art)
        if bt_path and isinstance(bt_art, dict):
            bt_art["artifact_files"] = {"system_monitor_backtest_json": bt_path}
        _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="system_monitor_backtest", artifact=bt_art)

    sandbox_ok = None
    try:
        if isinstance(bt_rep, dict) and bt_rep.get("ok") is not None:
            sandbox_ok = bool(bt_rep.get("ok"))
    except Exception:
        sandbox_ok = None

    if generate_changeset and run_triage and faq_hits:
        if sandbox_ok is None or sandbox_ok is True:
            ent = _system_monitor_pick_registry_entry(prefer_strategy_name=prefer_registry_strategy)
            sid = str((ent or {}).get("strategy_id") or "").strip()
            z = str((ent or {}).get("source_zip") or "").strip()
            if sid and z:
                safe_patch = cfg_patch if isinstance(cfg_patch, dict) else {}
                try:
                    if not safe_patch:
                        safe_patch = {}
                except Exception:
                    safe_patch = {}
                try:
                    draft_in = {
                        "trace_id": str(trace_id),
                        "strategy_id": sid,
                        "source_zip": z,
                        "config_patch": safe_patch,
                        "label": f"system_monitor_fix:{','.join([str(x) for x in faq_hits[:2]])}",
                        "reason": f"system_monitor:{','.join([str(x) for x in faq_hits[:6]])}",
                        "policy_ref": "gov_default",
                        "action": "config.apply",
                        "doc_refs": _agent_chat_enforce_doc_refs(
                            [
                                {"doc_path": "交易AI Agent 技术文档2.0.md", "section": "5.4.2", "rule": "两层准入口径"},
                                {"doc_path": "技术文档.md", "section": "0.3", "rule": "工程索引（SSoT 入口）"},
                            ]
                        ),
                        "evidence": _json_sanitize(
                            {
                                "system_monitor": {
                                    "faq_hits": [str(x) for x in faq_hits if str(x).strip()][:12],
                                    "link_check": (link_rep if isinstance(link_rep, dict) else None),
                                    "backtest": (bt_rep if isinstance(bt_rep, dict) else None),
                                }
                            }
                        ),
                    }
                    draft = _agent_changeset_draft_build(draft_in)
                except Exception as e:
                    draft = {"ok": False, "error": str(e), "trace_id": str(trace_id), "ts": int(_now_ms())}

                if isinstance(draft, dict) and bool(draft.get("ok")):
                    draft_id = uuid.uuid4().hex
                    try:
                        _agent_outbox_append_jsonl("changeset_drafts.jsonl", {"id": str(draft_id), "trace_id": str(trace_id), "ts": int(_now_ms()), "type": "changeset.draft", "draft": _json_sanitize(draft)})
                    except Exception:
                        pass
                    try:
                        cbd = draft.get("change_bundle_draft")
                        cbd_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="change_bundle_draft.json", obj=cbd)
                        if cbd_path and isinstance(cbd, dict):
                            cbd["artifact_files"] = {"change_bundle_draft_json": cbd_path}
                        _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="change_bundle_draft", artifact=cbd)
                    except Exception:
                        pass
                    try:
                        _agent_outbox_append_jsonl(
                            "chat.jsonl",
                            {"id": uuid.uuid4().hex, "trace_id": str(trace_id), "ts": int(_now_ms()), "type": "system.monitor.changeset_draft", "channel": "workflow", "draft_id": str(draft_id), "strategy_id": sid, "source_zip": z},
                        )
                    except Exception:
                        pass

                    if request_approval:
                        try:
                            approval_id = _approval_request_for_changeset_draft(trace_id=str(trace_id), draft_id=str(draft_id), draft=draft, action="governance.changeset.apply")
                        except Exception:
                            approval_id = None
                        if approval_id:
                            approval_pkg = _pipeline_approval_request_build(
                                trace_id=str(trace_id),
                                now_ms=int(_now_ms()),
                                action="governance.changeset.apply",
                                approval_id=str(approval_id),
                                draft_id=str(draft_id),
                                draft=draft,
                                chosen={"strategy_id": str(sid), "source_zip": str(z)},
                            )
                            approval_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="approval_request.json", obj=approval_pkg)
                            if approval_path and isinstance(approval_pkg, dict):
                                approval_pkg["artifact_files"] = {"approval_request_json": approval_path}
                            _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="approval_request", artifact=approval_pkg)

    auto_exec_rep = None
    if allow_auto_exec and bool(preauth.get("allowed")) and (sandbox_ok is True) and isinstance(draft, dict) and bool(draft.get("ok")):
        try:
            changeset = {
                "action": "config.apply",
                "strategy_id": str(sid),
                "source_zip": str(z),
                "config_patch": _json_sanitize(safe_patch),
                "label": str(label),
                "reason": str(reason),
                "doc_refs": _agent_chat_enforce_doc_refs(
                    [
                        {"doc_path": "交易AI Agent 技术文档2.0.md", "section": "5.4.2", "rule": "两层准入口径"},
                        {"doc_path": "技术文档.md", "section": "0.3", "rule": "工程索引（SSoT 入口）"},
                    ]
                ),
            }
            payload_apply = {"trace_id": str(trace_id), "confirm_live": True, "policy_ref": str(policy_ref), "changeset": changeset}
            if approval_id:
                payload_apply["approval_id"] = str(approval_id)
            with app.test_request_context(
                "/governance/changeset/apply",
                method="POST",
                json=payload_apply,
                content_type="application/json",
                environ_base={"REMOTE_ADDR": "127.0.0.1"},
            ):
                resp_apply = governance_changeset_apply()
            resp0 = resp_apply[0] if isinstance(resp_apply, tuple) and resp_apply else resp_apply
            if hasattr(resp0, "get_json"):
                out_apply = resp0.get_json(force=True)
            else:
                out_apply = resp0
            auto_exec_rep = {"ok": True, "ts": int(_now_ms()), "apply": _json_sanitize(out_apply)}
        except Exception as e:
            auto_exec_rep = {"ok": False, "error": str(e), "ts": int(_now_ms())}

    report = {
        "ok": True,
        "ts": int(_now_ms()),
        "trace_id": str(trace_id),
        "pair": str(pair),
        "strategy": str(strategy),
        "timerange": str(timerange),
        "summary": {
            "link_check_ok": (bool(link_rep.get("ok")) if isinstance(link_rep, dict) and link_rep.get("ok") is not None else None),
            "backtest_ok": (bool((bt_rep or {}).get("ok")) if isinstance(bt_rep, dict) and (bt_rep or {}).get("ok") is not None else None),
            "backtest_metrics_summary": ((bt_rep or {}).get("metrics_summary") if isinstance(bt_rep, dict) and isinstance((bt_rep or {}).get("metrics_summary"), dict) else {}),
            "faq_hits": [str(x) for x in (faq_hits or []) if str(x).strip()][:12],
            "preauthorized_allowed": (bool(preauth.get("allowed")) if isinstance(preauth, dict) else False),
            "changeset_draft_id": (str(draft_id) if draft_id else None),
            "approval_id": (str(approval_id) if approval_id else None),
        },
        "evidence": {
            "doc_refs": _json_sanitize(_doc_refs_default()),
            "endpoints": [
                {"endpoint": "/signals/recent", "pair": str(pair), "window_days": float(lookback_days)},
                {"endpoint": "/orders/recent", "pair": str(pair), "window_days": float(lookback_days)},
                {"endpoint": "/automation/backtest/run", "strategy": str(strategy), "timerange": str(timerange)},
            ],
        },
        "link_check": _json_sanitize(link_rep),
        "triage": _json_sanitize(triage_rep),
        "backtest": _json_sanitize(bt_rep),
        "changeset_draft": _json_sanitize(draft),
        "auto_exec": _json_sanitize(auto_exec_rep),
        "next_actions": [
            {"kind": "sandbox", "action": "review", "target": "report_files", "trace_id": str(trace_id)},
            {"kind": "human_review", "action": "triage", "target": "FAQ/技术文档口径", "trace_id": str(trace_id)},
        ],
    }
    severity = "P3"
    try:
        if isinstance(link_rep, dict) and link_rep.get("ok") is False:
            severity = "P1"
        if isinstance(bt_rep, dict) and bt_rep.get("ok") is False:
            severity = "P1"
    except Exception:
        severity = "P3"

    report_path = _agent_pipeline_package_write(trace_id=str(trace_id), filename="system_monitor_report.json", obj=report)
    if report_path and isinstance(report, dict):
        report["artifact_files"] = {"system_monitor_report_json": report_path}
    _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="system_monitor_report", artifact=report)

    try:
        _agent_outbox_append_jsonl(
            "rca.jsonl",
            {"id": uuid.uuid4().hex, "trace_id": str(trace_id), "ts": int(_now_ms()), "event_type": "system.monitor.report", "severity": str(severity), "evidence": report.get("evidence"), "result": report},
        )
    except Exception:
        pass

    return jsonify({"ok": True, "trace_id": str(trace_id), "ts": int(_now_ms()), "result": _json_sanitize(report)}), 200


@app.route("/automation/shadow_loop/run", methods=["POST"])
def automation_shadow_loop_run():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    if not bool(AUTOMATION.get("enable_shadow_automation_loop", False)):
        return jsonify({"ok": False, "error": "shadow_disabled", "ts": int(_now_ms())}), 400
    data = request.get_json(force=True) or {}
    mode = str(data.get("mode") or "new").strip().lower() or "new"
    trace_id_in = str(data.get("trace_id") or "").strip() or None
    decision_id = str(data.get("decision_id") or "").strip() or None
    gtw_path_id = str(data.get("gtw_path_id") or data.get("path_id") or "").strip() or None
    idempotency_key = str(data.get("idempotency_key") or "").strip() or None
    now_ms = int(_now_ms())
    trace_id = (trace_id_in or uuid.uuid4().hex) if mode in ("new", "retry", "auto") else (trace_id_in or uuid.uuid4().hex)
    if decision_id:
        try:
            dp = _agent_pipeline_artifact_find_latest(trace_id=str(decision_id), kind="gtw.decision_package")
        except Exception:
            dp = None
        if not isinstance(dp, dict):
            return jsonify({"ok": False, "error": "missing_decision_package", "decision_id": decision_id, "ts": int(now_ms)}), 400
    try:
        cand_limit = int(data.get("candidate_limit") or AUTOMATION.get("shadow_automation_candidate_limit", 3) or 3)
    except Exception:
        cand_limit = int(AUTOMATION.get("shadow_automation_candidate_limit", 3) or 3)
    cand_limit = max(1, min(10, int(cand_limit)))
    baseline_enabled = bool(data.get("baseline_enabled", AUTOMATION.get("shadow_automation_baseline_enabled", True)))
    skip_paramopt = bool(data.get("skip_paramopt", AUTOMATION.get("shadow_automation_skip_paramopt", True)))
    gates = data.get("gates") if isinstance(data.get("gates"), list) else ["backtest", "robustness", "stress", "rolling_verify", "monte_carlo"]
    trig_evt = "gtw.strategy_shadow_loop" if decision_id else "automation.shadow_loop.manual"
    payload = {
        "trace_id": str(trace_id),
        "force": True,
        "idempotent": True if (trace_id_in or idempotency_key) else False,
        "shadow_only": True,
        "gray_rollout_mode": "execute",
        "queue_sandbox": True,
        "candidate_limit": int(cand_limit),
        "baseline_enabled": bool(baseline_enabled),
        "skip_paramopt": bool(skip_paramopt),
        "gates": [str(x) for x in gates if str(x).strip()][:20],
        "trigger_event": trig_evt,
        "objective": {"kind": "shadow_automation", "source": trig_evt, "decision_id": decision_id, "gtw_path_id": gtw_path_id, "idempotency_key": idempotency_key},
        "risk_budget": {"never_live": True},
        "doc_refs": _agent_doc_refs_48_default(),
    }
    out, code = _automation_local_post_json("/agent/pipeline/run", agent_pipeline_run, payload)
    if out is None:
        out = {"ok": False, "error": "pipeline_no_response", "http": int(code), "trace_id": str(trace_id), "ts": int(now_ms)}
    try:
        _agent_outbox_append_jsonl(
            "chat.jsonl",
            {
                "id": uuid.uuid4().hex,
                "trace_id": str(trace_id),
                "ts": int(now_ms),
                "type": "automation.shadow_loop.manual",
                "channel": "workflow",
                "request": _json_sanitize(payload),
                "http": int(code),
                "result": _json_sanitize(out),
            },
        )
    except Exception:
        pass
    try:
        _ensure_sandbox_outbox_worker_started()
    except Exception:
        pass
    return jsonify({"ok": True, "trace_id": str(trace_id), "ts": int(now_ms), "http": int(code), "result": _json_sanitize(out)}), 200

@app.route("/automation/serving/pipeline/config", methods=["POST"])
def automation_serving_pipeline_config():
    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="automation.serving.pipeline.config")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    confirm_live = bool(data.get("confirm_live", False))
    data.pop("confirm_live", None)
    data.pop("trace_id", None)

    if not _is_local_request():
        if not bool(confirm_live):
            return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms())}), 400

    rb_pt = _rollback_snapshot_append(label="serving_pipeline.config", reason="l2_preflight")
    if rb_pt is None:
        return jsonify({"ok": False, "error": "rollback_snapshot_failed", "ts": int(_now_ms())}), 500

    sp = AUTOMATION.get("serving_pipeline") or {}
    if not isinstance(sp, dict):
        sp = {}
    for k in (
        "enabled",
        "phase",
        "canary_frac",
        "pairs",
        "eval_window",
        "min_eval_samples",
        "min_win_rate",
        "min_pr_auc",
        "max_ece",
        "max_tail_loss_p95",
        "profit_days",
        "min_profit_factor",
        "max_drawdown_ratio",
        "p0_since_ms",
        "p0_breach_lookback_hours",
        "require_exec_quality_sufficient",
        "require_drift_sufficient",
        "require_live_deviation_sufficient",
        "p3_order_fail_rate_days",
        "p3_order_fail_rate_delta",
        "p3_drift_days",
        "p3_drift_psi",
        "p3_drift_kl",
        "p3_drift_psi_severe",
        "p3_drift_kl_severe",
        "p3_drift_bins",
        "p3_drift_max_features",
        "p3_drift_min_train",
        "p3_drift_min_recent",
        "auto_guard_rollback",
    ):
        if k in data:
            sp[k] = data[k]
    AUTOMATION["serving_pipeline"] = sp
    try:
        enabled = bool(sp.get("enabled", False))
        phase = str(sp.get("phase", "shadow") or "shadow").lower().strip()
        if enabled:
            v = sp.get("canary_frac", None)
            pairs = sp.get("pairs") or []
            _apply_serving_phase(phase=phase, canary_frac=v, pairs=pairs)
    except Exception:
        pass
    try:
        _save_config()
    except Exception:
        pass
    out = {"ok": True, "serving_pipeline": AUTOMATION.get("serving_pipeline")}
    out["rollback_point"] = rb_pt
    out["approval_id"] = approval_id
    out["trace_id"] = trace_id
    try:
        sp_out = out.get("serving_pipeline") if isinstance(out, dict) else None
        _audit_emit_action(
            "automation.serving.pipeline.config",
            _audit_base_payload(
                scope="governance",
                action="automation.serving.pipeline.config",
                trace_id=trace_id,
                extra={
                    "enabled": (None if not isinstance(sp_out, dict) else bool(sp_out.get("enabled", False))),
                    "phase": (None if not isinstance(sp_out, dict) else str(sp_out.get("phase") or "").strip() or None),
                    "rollback_point": rb_pt,
                    "approval_id": approval_id,
                },
            ),
        )
    except Exception:
        pass
    return jsonify(out)

