@app.route("/automation/serving/pipeline/guard/rollback", methods=["POST"])
def automation_serving_pipeline_guard_rollback():
    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    latest = bool(data.get("latest", True))

    confirm_live = bool(data.get("confirm_live", False))
    data.pop("confirm_live", None)
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="automation.serving.pipeline.guard.rollback")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    if (not _is_local_request()) and (not bool(confirm_live)):
        return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms())}), 400
    eval_res = None
    try:
        r = automation_serving_pipeline_guard_eval()
        eval_res = r.get_json(force=True)
    except Exception:
        eval_res = None
    if not isinstance(eval_res, dict):
        return jsonify({"ok": False, "error": "guard_eval_failed"}), 500
    if (not bool(eval_res.get("pass", False))) and bool(eval_res.get("rollback_recommended", False)):
        try:
            checks = eval_res.get("checks") if isinstance(eval_res.get("checks"), dict) else {}
            fails = [k for k, v in checks.items() if isinstance(k, str) and (not bool(v))]
            reason = "manual_guard_rollback" + (":" + ",".join(sorted(fails)) if fails else "")
        except Exception:
            fails = []
            reason = "manual_guard_rollback"
        try:
            rb_ev = _rollback_snapshot_append(label="serving_guard.rollback", reason=reason, config_keys=["automation", "universe_core"])
        except Exception:
            rb_ev = None

        restore_data = {
            "latest": bool(latest),
            "restore_thresholds": True,
            "restore_arena": True,
            "restore_active_model": False,
            "restore_tracker_state": True,
            "restore_config": False,
            "reason": reason,
            "threshold_hits": {"fails": fails, "thresholds": eval_res.get("thresholds"), "metrics": eval_res.get("metrics")},
            "evidence": {"guard_eval": eval_res},
        }
        rr, rr_code = _evaluation_rollback_restore_internal(data=restore_data, trace_id=trace_id, approval_id=approval_id)
        if int(rr_code) >= 400:
            return jsonify({"ok": False, "error": "rollback_failed", "details": rr, "ts": int(_now_ms())}), 500
        _apply_serving_phase("shadow")
        try:
            _audit_emit_action(
                "automation.serving.pipeline.guard.rollback",
                _audit_base_payload(
                    scope="governance",
                    action="automation.serving.pipeline.guard.rollback",
                    trace_id=trace_id,
                    extra={
                        "rolled_back": True,
                        "latest": bool(latest),
                        "approval_id": approval_id,
                        "reason": (None if 'reason' not in locals() else reason),
                        "fails": fails,
                        "eval": eval_res,
                        "rollback_snapshot": (rb_ev.get("id") if isinstance(rb_ev, dict) else None),
                        "restore": rr,
                    },
                ),
            )
        except Exception:
            pass
        return jsonify({"ok": True, "rolled_back": True, "reason": (None if 'reason' not in locals() else reason), "fails": fails, "eval": eval_res, "rollback_snapshot": (rb_ev.get("id") if isinstance(rb_ev, dict) else None), "restore": rr, "ts": int(_now_ms())})
    try:
        _audit_emit_action(
            "automation.serving.pipeline.guard.rollback",
            _audit_base_payload(
                scope="governance",
                action="automation.serving.pipeline.guard.rollback",
                trace_id=trace_id,
                extra={"rolled_back": False, "latest": bool(latest), "approval_id": approval_id, "eval": eval_res},
            ),
        )
    except Exception:
        pass
    return jsonify({"ok": True, "rolled_back": False, "ts": int(_now_ms())})


def _apply_serving_phase(phase: str, canary_frac: Any = None, pairs: Any = None) -> None:
    ph = str(phase or "shadow").lower().strip()
    try:
        sp = AUTOMATION.get("serving_pipeline")
        if not isinstance(sp, dict):
            sp = {}
        sp2 = dict(sp)
        sp2["phase"] = ph
        if ph == "canary":
            if canary_frac is not None:
                try:
                    cf0 = float(canary_frac)
                    if math.isfinite(float(cf0)):
                        sp2["canary_frac"] = float(max(0.0, min(0.10, float(cf0))))
                except Exception:
                    pass
            if pairs is not None:
                wl0 = pairs if isinstance(pairs, list) else []
                wl: List[str] = []
                seen: set = set()
                for it in wl0:
                    s = str(it or "").strip()
                    if not s:
                        continue
                    if len(s) > 64:
                        s = s[:64]
                    if s in seen:
                        continue
                    seen.add(s)
                    wl.append(s)
                    if len(wl) >= 200:
                        break
                sp2["pairs"] = wl
        AUTOMATION["serving_pipeline"] = sp2
    except Exception:
        pass
    if ph == "shadow":
        CONFIG["serving_shadow_mode"] = True
        CONFIG["serving_canary_enabled"] = False
    elif ph == "canary":
        CONFIG["serving_shadow_mode"] = False
        CONFIG["serving_canary_enabled"] = True
        try:
            cf = 0.05 if canary_frac is None else float(canary_frac)
            if not math.isfinite(float(cf)):
                cf = 0.05
            CONFIG["serving_canary_size_frac"] = float(max(0.0, min(0.10, float(cf))))
        except Exception:
            CONFIG["serving_canary_size_frac"] = 0.05
        wl_src = pairs if isinstance(pairs, list) else []
        wl2: List[str] = []
        seen2: set = set()
        for it in wl_src:
            s = str(it or "").strip()
            if not s:
                continue
            if len(s) > 64:
                s = s[:64]
            if s in seen2:
                continue
            seen2.add(s)
            wl2.append(s)
            if len(wl2) >= 200:
                break
        CONFIG["serving_canary_pairs"] = wl2
    elif ph == "full":
        CONFIG["serving_shadow_mode"] = False
        CONFIG["serving_canary_enabled"] = False
    try:
        _save_config()
    except Exception:
        pass


def _serving_pipeline_profit_window(*, now_ms: int, profit_days: int) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    try:
        profit_days = int(profit_days)
    except Exception:
        profit_days = 30
    profit_days = max(1, min(365, int(profit_days)))
    since = int(ts) - int(profit_days) * 24 * 60 * 60 * 1000
    out: Dict[str, Any] = {
        "days": int(profit_days),
        "since_ts": int(since),
        "n": 0,
        "profit_factor": None,
        "profit_factor_inf": False,
        "max_drawdown_u": None,
        "max_drawdown_ratio": None,
    }
    attrib = ARENA_STATE.get("attrib") if isinstance(ARENA_STATE, dict) else None
    if not isinstance(attrib, list):
        attrib = []
    ts_pnls: List[Tuple[int, float]] = []
    for it in attrib:
        if not isinstance(it, dict):
            continue
        try:
            t0 = int(it.get("ts") or 0)
        except Exception:
            t0 = 0
        if t0 <= 0 or t0 < int(since):
            continue
        pnl = 0.0
        try:
            if it.get("pnl_net_u") is not None:
                pnl = float(it.get("pnl_net_u") or 0.0)
            else:
                pnl = float(it.get("pnl") or 0.0)
        except Exception:
            pnl = 0.0
        ts_pnls.append((int(t0), float(pnl)))
    ts_pnls.sort(key=lambda x: x[0])
    out["n"] = int(len(ts_pnls))
    if not ts_pnls:
        return out
    pos_sum = float(sum(p for _, p in ts_pnls if float(p) > 0.0))
    neg_sum = float(sum(abs(p) for _, p in ts_pnls if float(p) < 0.0))
    pf = (float(pos_sum) / float(neg_sum)) if float(neg_sum) > 1e-12 else (float("inf") if float(pos_sum) > 1e-12 else 0.0)
    out["profit_factor"] = (None if pf == float("inf") else float(pf))
    out["profit_factor_inf"] = True if pf == float("inf") else False

    cum = 0.0
    peak = 0.0
    max_dd_u = 0.0
    max_dd_ratio = 0.0
    for _, pnl in ts_pnls:
        cum += float(pnl)
        if cum >= peak:
            peak = float(cum)
        else:
            dd_u = float(peak) - float(cum)
            if dd_u > max_dd_u:
                max_dd_u = float(dd_u)
                max_dd_ratio = (float(max_dd_u) / float(peak)) if float(peak) > 1e-12 else 0.0
    out["max_drawdown_u"] = float(max_dd_u)
    out["max_drawdown_ratio"] = float(max_dd_ratio)
    return out


def _serving_pipeline_p0_loss_gate_status(*, sp: Dict[str, Any], now_ms: int) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    phase = str((sp or {}).get("phase", "shadow") or "shadow").lower().strip() or "shadow"
    try:
        since_ms_cfg = (sp or {}).get("p0_since_ms")
        since_ms = (None if since_ms_cfg is None else int(since_ms_cfg))
    except Exception:
        since_ms = None

    if since_ms is None and phase in ("canary", "full"):
        try:
            v = (sp or {}).get("canary_start_ms")
            since_ms = (None if v is None else int(v))
        except Exception:
            since_ms = None

    if since_ms is None:
        try:
            lookback_h = float((sp or {}).get("p0_breach_lookback_hours") or 24.0)
        except Exception:
            lookback_h = 24.0
        lookback_h = max(1.0, min(24.0 * 30.0, float(lookback_h)))
        since_ms = int(ts) - int(lookback_h * 3600.0 * 1000.0)

    gh = TRACKER_STATE.get("gate_history") if isinstance(TRACKER_STATE, dict) else None
    if not isinstance(gh, list):
        gh = []
    loss_reasons = {
        "daily_loss_limit",
        "weekly_loss_limit",
        "account_daily_loss_limit",
        "account_weekly_loss_limit",
        "strategy_daily_loss_limit",
        "strategy_weekly_loss_limit",
    }
    breaches: List[Dict[str, Any]] = []
    for it in gh:
        if not isinstance(it, dict):
            continue
        try:
            t0 = int(it.get("ts") or 0)
        except Exception:
            t0 = 0
        if t0 <= 0 or t0 < int(since_ms):
            continue
        if bool(it.get("ok", True)):
            continue
        r = str(it.get("reason") or "").strip()
        if not r or r not in loss_reasons:
            continue
        breaches.append({"ts": int(t0), "reason": r, "system_id": str(it.get("system_id") or "").strip() or None})
    breaches.sort(key=lambda x: int(x.get("ts") or 0))
    last = breaches[-1] if breaches else None
    return {
        "ok": True,
        "phase": phase,
        "since_ms": int(since_ms),
        "breached": bool(breaches),
        "breaches_n": int(len(breaches)),
        "last_breach": last,
    }


def _serving_pipeline_guard_status(*, sp: Dict[str, Any], now_ms: int) -> Dict[str, Any]:
    ts = int(now_ms or _now_ms())
    phase = str(sp.get("phase", "shadow") or "shadow").lower().strip() or "shadow"

    try:
        min_n = int(sp.get("min_eval_samples") or 200)
    except Exception:
        min_n = 200
    try:
        min_pf = float(sp.get("min_profit_factor") or 0.9)
    except Exception:
        min_pf = 0.9
    try:
        max_dd = float(sp.get("max_drawdown_ratio") or 1.2)
    except Exception:
        max_dd = 1.2
    try:
        profit_days = int(sp.get("profit_days") or 30)
    except Exception:
        profit_days = 30

    pw = _serving_pipeline_profit_window(now_ms=int(ts), profit_days=int(profit_days))
    n = int(pw.get("n") or 0)
    pf = pw.get("profit_factor")
    dd = pw.get("max_drawdown_ratio")

    ok_n = n >= int(min_n)
    ok_pf = (pf is not None) and (float(pf) >= float(min_pf))
    ok_dd = (dd is not None) and (float(dd) <= float(max_dd))

    hg = _p2_health_gate_status(now_ms=int(ts))
    ok_p2 = (not isinstance(hg, dict)) or (not bool(hg.get("blocked", False)))

    p1 = _p1_exec_gate_status(now_ms=int(ts))
    ok_p1 = (not isinstance(p1, dict)) or (not bool(p1.get("blocked", False)))

    try:
        ofr_days = int(sp.get("p3_order_fail_rate_days") or 7)
    except Exception:
        ofr_days = 7
    ofr_days = max(1, min(30, int(ofr_days)))
    try:
        ofr_delta = float(sp.get("p3_order_fail_rate_delta") or 0.03)
    except Exception:
        ofr_delta = 0.03
    try:
        drift_days = float(sp.get("p3_drift_days") or 30.0)
    except Exception:
        drift_days = 30.0
    try:
        psi_thr = float(sp.get("p3_drift_psi") or 0.20)
    except Exception:
        psi_thr = 0.20
    try:
        kl_thr = float(sp.get("p3_drift_kl") or 0.15)
    except Exception:
        kl_thr = 0.15
    try:
        psi_severe = float(sp.get("p3_drift_psi_severe") or (float(psi_thr) * 2.0))
    except Exception:
        psi_severe = float(psi_thr) * 2.0
    try:
        kl_severe = float(sp.get("p3_drift_kl_severe") or (float(kl_thr) * 2.0))
    except Exception:
        kl_severe = float(kl_thr) * 2.0

    exec_quality = None
    baseline_ofr = None
    cur_ofr = None
    ok_exec = True
    exec_sufficient = True
    if phase in ("canary", "full"):
        try:
            v = sp.get("baseline_order_fail_rate_7d")
            baseline_ofr = (None if v is None else float(v))
        except Exception:
            baseline_ofr = None
        try:
            start_ms = int(ts) - int(ofr_days) * 24 * 60 * 60 * 1000
            exec_quality = _audit_execution_quality(start_ts_ms=int(start_ms), end_ts_ms=int(ts), include_shadow=False, max_points=200000)
            if isinstance(exec_quality, dict):
                v = exec_quality.get("order_fail_rate")
                cur_ofr = (None if v is None else float(v))
        except Exception:
            exec_quality = None
            cur_ofr = None
        if baseline_ofr is None or cur_ofr is None:
            ok_exec = True
            exec_sufficient = False
        else:
            ok_exec = bool(float(cur_ofr) <= float(baseline_ofr) + float(ofr_delta))

    drift = None
    ok_drift = True
    severe_drift = False
    drift_sufficient = True
    if phase in ("canary", "full"):
        try:
            drift = _p3_drift_psi_kl_status(
                now_ms=int(ts),
                drift_days=float(drift_days),
                max_features=int(sp.get("p3_drift_max_features") or 60),
                bins=int(sp.get("p3_drift_bins") or 10),
                min_train=int(sp.get("p3_drift_min_train") or 200),
                min_recent=int(sp.get("p3_drift_min_recent") or 200),
            )
        except Exception:
            drift = None
        if isinstance(drift, dict) and bool(drift.get("sufficient", False)):
            try:
                psi_max = drift.get("psi_max")
                kl_max = drift.get("kl_max")
                ok_psi = (psi_max is None) or (float(psi_max) <= float(psi_thr))
                ok_kl = (kl_max is None) or (float(kl_max) <= float(kl_thr))
                ok_drift = bool(ok_psi and ok_kl)
                severe_drift = bool(((psi_max is not None) and (float(psi_max) > float(psi_severe))) or ((kl_max is not None) and (float(kl_max) > float(kl_severe))))
            except Exception:
                ok_drift = True
        else:
            ok_drift = True
            drift_sufficient = False

    live_dev_gate_enabled = False
    live_dev = None
    ok_live_dev = True
    live_dev_sufficient = False
    live_dev_stage = 0
    try:
        live_dev_gate_enabled = bool(sp.get("p3_live_deviation_gate_enabled", True))
    except Exception:
        live_dev_gate_enabled = True
    if live_dev_gate_enabled and phase in ("canary", "full"):
        try:
            if bool(CONFIG.get("monitor_center_enabled", True)):
                _monitor_center_update(int(ts))
        except Exception:
            pass
        try:
            mc = TRACKER_STATE.get("monitor_center") if isinstance(TRACKER_STATE, dict) else None
        except Exception:
            mc = None
        ts_block = (mc.get("three_screen") if isinstance(mc, dict) else None)
        if isinstance(ts_block, dict) and isinstance(ts_block.get("degradation"), dict):
            live_dev = ts_block.get("degradation")
            try:
                live_dev_stage = int((live_dev or {}).get("stage") or 0)
            except Exception:
                live_dev_stage = 0
            try:
                max_stage = int(sp.get("p3_live_deviation_max_stage") if sp.get("p3_live_deviation_max_stage") is not None else 1)
            except Exception:
                max_stage = 1
            try:
                rollback_stage = int(sp.get("p3_live_deviation_rollback_stage") or 3)
            except Exception:
                rollback_stage = 3
            ok_live_dev = bool(int(live_dev_stage) <= int(max_stage))
            try:
                ord_in = (live_dev.get("inputs") or {}).get("orders_recent") if isinstance((live_dev or {}).get("inputs"), dict) else None
                ord_ref_in = (live_dev.get("inputs") or {}).get("orders_ref") if isinstance((live_dev or {}).get("inputs"), dict) else None
                set_in = (live_dev.get("inputs") or {}).get("settle_recent") if isinstance((live_dev or {}).get("inputs"), dict) else None
                set_ref_in = (live_dev.get("inputs") or {}).get("settle_ref") if isinstance((live_dev or {}).get("inputs"), dict) else None
                ord_n = int((ord_in or {}).get("n") or 0) if isinstance(ord_in, dict) else 0
                ord_ref_n = int((ord_ref_in or {}).get("n") or 0) if isinstance(ord_ref_in, dict) else 0
                set_n = int((set_in or {}).get("n") or 0) if isinstance(set_in, dict) else 0
                set_ref_n = int((set_ref_in or {}).get("n") or 0) if isinstance(set_ref_in, dict) else 0
            except Exception:
                ord_n, ord_ref_n, set_n, set_ref_n = 0, 0, 0, 0
            try:
                min_orders_recent = int(CONFIG.get("monitor_center_orders_min_recent", 20) or 20)
            except Exception:
                min_orders_recent = 20
            try:
                min_orders_ref = int(CONFIG.get("monitor_center_orders_min_ref", 80) or 80)
            except Exception:
                min_orders_ref = 80
            try:
                min_settle_recent = int(CONFIG.get("monitor_center_settlements_min_recent", 30) or 30)
            except Exception:
                min_settle_recent = 30
            try:
                min_settle_ref = int(CONFIG.get("monitor_center_settlements_min_ref", 120) or 120)
            except Exception:
                min_settle_ref = 120
            try:
                pe = ts_block.get("p_enter") if isinstance(ts_block.get("p_enter"), dict) else {}
                pr = pe.get("recent") if isinstance(pe.get("recent"), dict) else {}
                pb = pe.get("ref") if isinstance(pe.get("ref"), dict) else {}
                cr = pr.get("counts") if isinstance(pr.get("counts"), dict) else {}
                cb = pb.get("counts") if isinstance(pb.get("counts"), dict) else {}
                p_recent = int(cr.get("total") or 0)
                p_ref = int(cb.get("total") or 0)
            except Exception:
                p_recent, p_ref = 0, 0
            try:
                min_p_recent = int(CONFIG.get("monitor_center_p_enter_min_recent", 100) or 100)
            except Exception:
                min_p_recent = 100
            try:
                min_p_ref = int(CONFIG.get("monitor_center_p_enter_min_ref", 300) or 300)
            except Exception:
                min_p_ref = 300
            live_dev_sufficient = bool(
                (ord_n >= int(min_orders_recent))
                and (ord_ref_n >= int(min_orders_ref))
                and (set_n >= int(min_settle_recent))
                and (set_ref_n >= int(min_settle_ref))
                and (p_recent >= int(min_p_recent))
                and (p_ref >= int(min_p_ref))
            )
            severe_live = bool(live_dev_sufficient and int(live_dev_stage) >= int(rollback_stage))
        else:
            try:
                max_stage = int(sp.get("p3_live_deviation_max_stage") if sp.get("p3_live_deviation_max_stage") is not None else 1)
            except Exception:
                max_stage = 1
            try:
                rollback_stage = int(sp.get("p3_live_deviation_rollback_stage") or 3)
            except Exception:
                rollback_stage = 3
            severe_live = False
    else:
        try:
            max_stage = int(sp.get("p3_live_deviation_max_stage") if sp.get("p3_live_deviation_max_stage") is not None else 1)
        except Exception:
            max_stage = 1
        try:
            rollback_stage = int(sp.get("p3_live_deviation_rollback_stage") or 3)
        except Exception:
            rollback_stage = 3
        severe_live = False

    p0 = _serving_pipeline_p0_loss_gate_status(sp=sp, now_ms=int(ts))
    p0_breached = bool(isinstance(p0, dict) and bool(p0.get("breached", False)))
    ok_p0 = True if phase not in ("canary", "full") else (not bool(p0_breached))

    try:
        require_exec_sufficient = bool(sp.get("require_exec_quality_sufficient", True))
    except Exception:
        require_exec_sufficient = True
    try:
        require_drift_sufficient = bool(sp.get("require_drift_sufficient", True))
    except Exception:
        require_drift_sufficient = True
    try:
        require_live_sufficient = bool(sp.get("require_live_deviation_sufficient", False))
    except Exception:
        require_live_sufficient = False

    exec_pass = bool(ok_exec and ((not bool(require_exec_sufficient)) or bool(exec_sufficient) or (phase not in ("canary", "full"))))
    drift_pass = bool(ok_drift and ((not bool(require_drift_sufficient)) or bool(drift_sufficient) or (phase not in ("canary", "full"))))
    try:
        monitor_enabled = bool(CONFIG.get("monitor_center_enabled", True))
    except Exception:
        monitor_enabled = True
    live_pass = bool(
        (not bool(live_dev_gate_enabled))
        or (phase not in ("canary", "full"))
        or (bool(ok_live_dev) and ((not bool(require_live_sufficient)) or (not bool(monitor_enabled)) or bool(live_dev_sufficient)))
    )

    success_n = bool(ok_n)
    success_p0 = bool(ok_p0)
    success_p1 = bool(ok_p1 and exec_pass)
    success_p2 = bool(ok_p2 and ok_pf and ok_dd and drift_pass and live_pass)
    success = bool(success_n and success_p0 and success_p1 and success_p2)

    passed = bool(success)
    pause_recommended = bool(
        ((phase in ("canary", "full")) and (not ok_drift) and bool(drift_sufficient) and (not bool(severe_drift)))
        or ((phase in ("canary", "full")) and bool(live_dev_gate_enabled) and bool(live_dev_sufficient) and (not bool(ok_live_dev)) and (not bool(severe_live)))
    )
    rollback_recommended = bool(
        (phase in ("canary", "full"))
        and (
            (not ok_p0)
            or (not ok_p2)
            or (not ok_p1)
            or ((not ok_pf) and (pf is not None))
            or ((not ok_dd) and (dd is not None))
            or ((not ok_exec) and exec_sufficient)
            or ((bool(severe_drift)) and (not ok_drift) and drift_sufficient)
            or (bool(severe_live) and bool(live_dev_gate_enabled))
        )
    )

    return {
        "ok": True,
        "phase": phase,
        "checks": {
            "n": ok_n,
            "pf": ok_pf,
            "dd": ok_dd,
            "p0_loss": bool(ok_p0),
            "p2_health": ok_p2,
            "p1_exec": ok_p1,
            "exec_quality": bool(exec_pass),
            "drift": bool(drift_pass),
            "live_deviation": bool(live_pass),
        },
        "sufficient": {
            "exec_quality": bool(exec_sufficient),
            "drift": bool(drift_sufficient),
            "live_deviation": (True if (not live_dev_gate_enabled) else bool(live_dev_sufficient)),
        },
        "success_criteria": {"n": bool(success_n), "p0": bool(success_p0), "p1": bool(success_p1), "p2": bool(success_p2), "success": bool(success)},
        "metrics": {
            "n": n,
            "pf": pf,
            "dd": dd,
            "p0_loss": p0,
            "p2_health": hg,
            "p1_exec": p1,
            "order_fail_rate_7d": cur_ofr,
            "baseline_order_fail_rate_7d": baseline_ofr,
            "drift": drift,
            "live_deviation": live_dev,
            "live_deviation_stage": int(live_dev_stage),
        },
        "thresholds": {
            "min_n": int(min_n),
            "min_pf": float(min_pf),
            "max_dd": float(max_dd),
            "p0_since_ms": (p0.get("since_ms") if isinstance(p0, dict) else None),
            "require_exec_quality_sufficient": bool(require_exec_sufficient),
            "require_drift_sufficient": bool(require_drift_sufficient),
            "require_live_deviation_sufficient": bool(require_live_sufficient),
            "p1_exec": (p1.get("thresholds") if isinstance(p1, dict) else None),
            "baseline_ofr_delta": float(ofr_delta),
            "psi": float(psi_thr),
            "kl": float(kl_thr),
            "psi_severe": float(psi_severe),
            "kl_severe": float(kl_severe),
            "drift_days": float(drift_days),
            "live_deviation_gate_enabled": bool(live_dev_gate_enabled),
            "live_deviation_max_stage": int(max_stage),
            "live_deviation_rollback_stage": int(rollback_stage),
            "live_deviation_min_orders_recent": int(min_orders_recent) if 'min_orders_recent' in locals() else int(CONFIG.get("monitor_center_orders_min_recent", 20) or 20),
            "live_deviation_min_orders_ref": int(min_orders_ref) if 'min_orders_ref' in locals() else int(CONFIG.get("monitor_center_orders_min_ref", 80) or 80),
            "live_deviation_min_settle_recent": int(min_settle_recent) if 'min_settle_recent' in locals() else int(CONFIG.get("monitor_center_settlements_min_recent", 30) or 30),
            "live_deviation_min_settle_ref": int(min_settle_ref) if 'min_settle_ref' in locals() else int(CONFIG.get("monitor_center_settlements_min_ref", 120) or 120),
            "live_deviation_min_p_enter_recent": int(min_p_recent) if 'min_p_recent' in locals() else int(CONFIG.get("monitor_center_p_enter_min_recent", 100) or 100),
            "live_deviation_min_p_enter_ref": int(min_p_ref) if 'min_p_ref' in locals() else int(CONFIG.get("monitor_center_p_enter_min_ref", 300) or 300),
        },
        "pass": bool(passed),
        "pause_recommended": bool(pause_recommended),
        "rollback_recommended": bool(rollback_recommended),
        "ts": int(ts),
    }


def _serving_pipeline_advance_impl(*, trace_id: Optional[str] = None, approval_id: Optional[str] = None) -> Dict[str, Any]:
    sp = AUTOMATION.get("serving_pipeline") or {}
    if not isinstance(sp, dict) or not bool(sp.get("enabled", False)):
        return {"ok": False, "error": "pipeline_disabled", "_http": 400}

    tid = str(trace_id or "").strip() or uuid.uuid4().hex

    phase = str(sp.get("phase", "shadow") or "shadow").lower().strip()
    try:
        v = sp.get("eval_window", None)
        win = (1000 if v is None else int(v))
    except Exception:
        win = 1000
    try:
        v = sp.get("min_eval_samples", None)
        min_n = (200 if v is None else int(v))
    except Exception:
        min_n = 200
    eval_set = EVAL_SAMPLES[-win:] if win > 0 else EVAL_SAMPLES[:]
    if len(eval_set) < int(min_n):
        return {"ok": False, "error": "not_enough_eval_samples", "n": int(len(eval_set)), "min_n": int(min_n), "_http": 400}

    base_obj = ACTIVE_MODEL.get("obj")
    base_m = _metrics_for_model(eval_set, base_obj)
    wr = float(base_m.get("win_rate", 0.0) or 0.0)
    pr = float(base_m.get("pr_auc", 0.0) or 0.0)
    ece = float(base_m.get("ece", 0.0) or 0.0)
    tail = _loss_tail_p(base_m.get("pnl"), 0.95)
    try:
        v = sp.get("min_win_rate", None)
        min_wr = (0.55 if v is None else float(v))
    except Exception:
        min_wr = 0.55
    try:
        v = sp.get("min_pr_auc", None)
        min_pr = (0.60 if v is None else float(v))
    except Exception:
        min_pr = 0.60
    try:
        v = sp.get("max_ece", None)
        max_e = (0.10 if v is None else float(v))
    except Exception:
        max_e = 0.10
    try:
        v = sp.get("max_tail_loss_p95", None)
        max_t = (2.0 if v is None else float(v))
    except Exception:
        max_t = 2.0
    ok = (wr >= min_wr) and (pr >= min_pr) and (ece <= max_e) and (tail <= max_t)
    if not ok:
        return {"ok": True, "advanced": False, "phase": phase, "metrics": {"win_rate": wr, "pr_auc": pr, "ece": ece, "tail_p95": tail}, "thresholds": {"min_wr": min_wr, "min_pr": min_pr, "max_ece": max_e, "max_tail_p95": max_t}}

    prev = phase
    if phase == "shadow":
        v = sp.get("canary_frac", None)
        v0 = sp.get("canary_frac_start", None)
        v_use = v if v0 is None else v0
        wl = sp.get("pairs") or []
        _apply_serving_phase(phase="canary", canary_frac=v_use, pairs=wl)
        sp["phase"] = "canary"
        if approval_id is not None:
            sp["canary_first_approval_id"] = str(approval_id)
            sp["canary_first_approved_ts"] = int(_now_ms())
        sp["canary_first_trace_id"] = str(tid)
        try:
            sp["canary_frac_current"] = float(CONFIG.get("serving_canary_size_frac") or v_use or 0.0)
        except Exception:
            sp["canary_frac_current"] = v_use
        try:
            sp["canary_start_ms"] = int(_now_ms())
        except Exception:
            sp["canary_start_ms"] = int(_now_ms())
        sp["guard_pass_consecutive"] = 0
        try:
            if sp.get("baseline_order_fail_rate_7d") is None:
                now_ms = int(_now_ms())
                start_ms = int(now_ms) - 7 * 24 * 60 * 60 * 1000
                eq = _audit_execution_quality(start_ts_ms=int(start_ms), end_ts_ms=int(now_ms), include_shadow=False, max_points=200000)
                if isinstance(eq, dict) and eq.get("order_fail_rate") is not None:
                    sp["baseline_order_fail_rate_7d"] = float(eq.get("order_fail_rate"))
                    sp["baseline_order_fail_rate_ts"] = int(now_ms)
        except Exception:
            pass
        AUTOMATION["serving_pipeline"] = sp
        try:
            _save_config()
        except Exception:
            pass
        gate = None
        try:
            gate = _serving_pipeline_guard_status(sp=sp, now_ms=int(_now_ms()))
        except Exception:
            gate = None
        if bool(sp.get("auto_guard_rollback", True)) and isinstance(gate, dict) and (not bool(gate.get("pass", True))) and bool(gate.get("rollback_recommended", False)):
            try:
                checks = gate.get("checks") if isinstance(gate.get("checks"), dict) else {}
                fails = [k for k, v in checks.items() if isinstance(k, str) and (not bool(v))]
                reason = "auto_guard_rollback" + (":" + ",".join(sorted(fails)) if fails else "")
                rb_ev = _rollback_snapshot_append(label="serving_guard.rollback", reason=reason, config_keys=["automation", "universe_core"])
                _ = rb_ev
            except Exception:
                rb_ev = None
            try:
                _audit_emit_action(
                    "serving_guard.rollback",
                    _audit_base_payload(
                        scope="governance",
                        action="serving_guard.rollback",
                        trace_id=uuid.uuid4().hex,
                        extra={
                            "phase": prev,
                            "to": "shadow",
                            "reason": (None if 'reason' not in locals() else reason),
                            "gate": gate,
                            "metrics": base_m,
                            "rollback_snapshot": (rb_ev.get("id") if isinstance(rb_ev, dict) else None),
                        },
                    ),
                )
            except Exception:
                pass
            restore_data = {
                "latest": True,
                "restore_thresholds": True,
                "restore_arena": True,
                "restore_active_model": False,
                "restore_tracker_state": True,
                "restore_config": False,
                "reason": (None if 'reason' not in locals() else reason),
                "threshold_hits": {"fails": (fails if 'fails' in locals() else []), "thresholds": (gate.get("thresholds") if isinstance(gate, dict) else None), "metrics": (gate.get("metrics") if isinstance(gate, dict) else None)},
                "evidence": {"gate": gate, "metrics": base_m},
            }
            rr, rr_code = _evaluation_rollback_restore_internal(data=restore_data, trace_id=tid, approval_id=approval_id)
            if int(rr_code) >= 400:
                rr = {"ok": False, "error": "rollback_failed", "details": rr}
            _apply_serving_phase("shadow")
            sp["phase"] = "shadow"
            AUTOMATION["serving_pipeline"] = sp
            try:
                _save_config()
            except Exception:
                pass
            return {"ok": True, "advanced": True, "from": prev, "to": "canary", "rolled_back": True, "rolled_back_to": "shadow", "gate": gate, "rollback": rr, "metrics": base_m}
        return {"ok": True, "advanced": True, "from": prev, "to": "canary", "gate": gate, "metrics": base_m}
    if phase == "canary":
        gate = None
        try:
            gate = _serving_pipeline_guard_status(sp=sp, now_ms=int(_now_ms()))
        except Exception:
            gate = None
        passed = bool(isinstance(gate, dict) and bool(gate.get("pass", False)))
        try:
            req = int(sp.get("promote_required_consecutive_pass") or 3)
        except Exception:
            req = 3
        try:
            cur_pass = int(sp.get("guard_pass_consecutive") or 0)
        except Exception:
            cur_pass = 0
        if passed:
            cur_pass += 1
        else:
            cur_pass = 0
        sp["guard_pass_consecutive"] = int(cur_pass)
        try:
            step = float(sp.get("promote_step_frac") or 0.01)
        except Exception:
            step = 0.01
        try:
            target_frac = float(sp.get("canary_frac") or 0.05)
        except Exception:
            target_frac = 0.05
        try:
            cur_frac = float(sp.get("canary_frac_current") or CONFIG.get("serving_canary_size_frac") or 0.0)
        except Exception:
            cur_frac = float(CONFIG.get("serving_canary_size_frac") or 0.0)
        if passed and (cur_pass >= int(req)) and (cur_frac < float(target_frac)):
            next_frac = min(float(target_frac), float(cur_frac) + float(step))
            _apply_serving_phase(phase="canary", canary_frac=next_frac, pairs=sp.get("pairs") or [])
            sp["canary_frac_current"] = float(CONFIG.get("serving_canary_size_frac") or next_frac)
            sp["phase"] = "canary"
            AUTOMATION["serving_pipeline"] = sp
            try:
                _save_config()
            except Exception:
                pass
            return {"ok": True, "advanced": True, "from": prev, "to": "promote", "phase": "canary", "gate": gate, "metrics": base_m, "promote": {"guard_pass_consecutive": int(cur_pass), "required": int(req), "canary_frac": float(sp.get("canary_frac_current") or 0.0), "target": float(target_frac)}}

        if (not passed) or (cur_pass < int(req)) or (cur_frac < float(target_frac)):
            sp["phase"] = "canary"
            AUTOMATION["serving_pipeline"] = sp
            try:
                _save_config()
            except Exception:
                pass
            return {"ok": True, "advanced": False, "phase": "canary", "gate": gate, "metrics": base_m, "promote": {"guard_pass_consecutive": int(cur_pass), "required": int(req), "canary_frac": float(cur_frac), "target": float(target_frac)}}

        require_second = True
        try:
            if sp.get("require_second_approval") is not None:
                require_second = bool(sp.get("require_second_approval"))
        except Exception:
            require_second = True
        first_id = str(sp.get("canary_first_approval_id") or "").strip()
        if require_second and first_id and approval_id is not None and str(approval_id) == first_id:
            return {"ok": False, "error": "second_approval_required", "phase": "canary", "first_approval_id": first_id, "_http": 412}

        _apply_serving_phase(phase="full")
        sp["phase"] = "full"
        if approval_id is not None:
            sp["canary_second_approval_id"] = str(approval_id)
            sp["canary_second_approved_ts"] = int(_now_ms())
        AUTOMATION["serving_pipeline"] = sp
        try:
            _save_config()
        except Exception:
            pass
        gate = None
        try:
            gate = _serving_pipeline_guard_status(sp=sp, now_ms=int(_now_ms()))
        except Exception:
            gate = None
        if bool(sp.get("auto_guard_rollback", True)) and isinstance(gate, dict) and (not bool(gate.get("pass", True))) and bool(gate.get("rollback_recommended", False)):
            try:
                checks = gate.get("checks") if isinstance(gate.get("checks"), dict) else {}
                fails = [k for k, v in checks.items() if isinstance(k, str) and (not bool(v))]
                reason = "auto_guard_rollback" + (":" + ",".join(sorted(fails)) if fails else "")
                rb_ev = _rollback_snapshot_append(label="serving_guard.rollback", reason=reason, config_keys=["automation", "universe_core"])
                _ = rb_ev
            except Exception:
                rb_ev = None
            try:
                _audit_emit_action(
                    "serving_guard.rollback",
                    _audit_base_payload(
                        scope="governance",
                        action="serving_guard.rollback",
                        trace_id=uuid.uuid4().hex,
                        extra={
                            "phase": prev,
                            "to": "shadow",
                            "reason": (None if 'reason' not in locals() else reason),
                            "gate": gate,
                            "metrics": base_m,
                            "rollback_snapshot": (rb_ev.get("id") if isinstance(rb_ev, dict) else None),
                        },
                    ),
                )
            except Exception:
                pass
            restore_data = {
                "latest": True,
                "restore_thresholds": True,
                "restore_arena": True,
                "restore_active_model": False,
                "restore_tracker_state": True,
                "restore_config": False,
                "reason": (None if 'reason' not in locals() else reason),
                "threshold_hits": {"fails": (fails if 'fails' in locals() else []), "thresholds": (gate.get("thresholds") if isinstance(gate, dict) else None), "metrics": (gate.get("metrics") if isinstance(gate, dict) else None)},
                "evidence": {"gate": gate, "metrics": base_m},
            }
            rr, rr_code = _evaluation_rollback_restore_internal(data=restore_data, trace_id=tid, approval_id=approval_id)
            if int(rr_code) >= 400:
                rr = {"ok": False, "error": "rollback_failed", "details": rr}
            _apply_serving_phase("shadow")
            sp["phase"] = "shadow"
            AUTOMATION["serving_pipeline"] = sp
            try:
                _save_config()
            except Exception:
                pass
            return {"ok": True, "advanced": True, "from": prev, "to": "full", "rolled_back": True, "rolled_back_to": "shadow", "gate": gate, "rollback": rr, "metrics": base_m}
        return {"ok": True, "advanced": True, "from": prev, "to": "full", "gate": gate, "metrics": base_m}

    return {"ok": True, "advanced": False, "phase": phase, "metrics": base_m}

@app.route("/automation/strategies/config", methods=["POST"])
def automation_strategies_config():
    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    confirm_live = bool(data.get("confirm_live", False))
    data.pop("confirm_live", None)
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="automation.strategies.config")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    if (not _is_local_request()) and (not bool(confirm_live)):
        return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms())}), 400
    rb_pt = _rollback_snapshot_append(label="automation.strategies.config", reason="l2_preflight", config_keys=["automation", "universe_core"])
    if rb_pt is None:
        return jsonify({"ok": False, "error": "rollback_snapshot_failed", "ts": int(_now_ms())}), 500
    feeders = data.get("strategy_feeders")
    if isinstance(feeders, list):
        supported = set(_strategy_feeder_supported_ids())
        seen = set()
        for it in list(feeders):
            if not isinstance(it, dict):
                return jsonify({"ok": False, "error": "invalid_strategy_feeders"}), 400
            sid = str(it.get("strategy_id") or "").strip()
            if not sid:
                return jsonify({"ok": False, "error": "invalid_strategy_id"}), 400
            if sid not in supported:
                return jsonify({"ok": False, "error": "invalid_strategy_id", "strategy_id": sid}), 400
            if sid in seen:
                return jsonify({"ok": False, "error": "duplicate_strategy_id", "strategy_id": sid}), 400
            seen.add(sid)
        AUTOMATION["strategy_feeders"] = feeders
    if "enable_strategy_feeders" in data:
        AUTOMATION["enable_strategy_feeders"] = bool(data.get("enable_strategy_feeders"))
    if "feeders_period_seconds" in data:
        try:
            AUTOMATION["feeders_period_seconds"] = int(data.get("feeders_period_seconds"))
        except Exception:
            pass
    if "use_universe_core" in data:
        AUTOMATION["use_universe_core"] = bool(data.get("use_universe_core"))
    if bool(AUTOMATION.get("enable_strategy_feeders")):
        AUTOMATION["use_universe_core"] = True
        core = UNIVERSE_STATE.get("core")
        core_coins = core if isinstance(core, list) else []
        if not core_coins:
            UNIVERSE_STATE["core"] = ["BTC", "ETH", "SOL"]
    if "use_exit_feeder" in data:
        AUTOMATION["use_exit_feeder"] = bool(data.get("use_exit_feeder"))
    if "exit_feeder_period_seconds" in data:
        try:
            AUTOMATION["exit_feeder_period_seconds"] = int(data.get("exit_feeder_period_seconds"))
        except Exception:
            pass
    if "use_exit_feeder_strategy" in data:
        AUTOMATION["use_exit_feeder_strategy"] = bool(data.get("use_exit_feeder_strategy"))
    try:
        _save_config()
    except Exception:
        pass
    out = {"ok": True, "automation": {"enable_strategy_feeders": AUTOMATION.get("enable_strategy_feeders"), "feeders_period_seconds": AUTOMATION.get("feeders_period_seconds"), "strategy_feeders": AUTOMATION.get("strategy_feeders"), "use_universe_core": AUTOMATION.get("use_universe_core"), "use_exit_feeder": AUTOMATION.get("use_exit_feeder"), "exit_feeder_period_seconds": AUTOMATION.get("exit_feeder_period_seconds"), "use_exit_feeder_strategy": AUTOMATION.get("use_exit_feeder_strategy")}, "trace_id": trace_id, "approval_id": approval_id, "rollback_point": (rb_pt.get("id") if isinstance(rb_pt, dict) else None)}
    try:
        _audit_emit_action(
            "automation.strategies.config",
            _audit_base_payload(scope="governance", action="automation.strategies.config", trace_id=trace_id, extra={"ok": True, "approval_id": approval_id, "rollback_point": (rb_pt.get("id") if isinstance(rb_pt, dict) else None)}),
        )
    except Exception:
        pass
    return jsonify(out)

