@app.route("/data/quality/score", methods=["GET"])
def data_quality_score():
    # Heuristic quality score (0-1)
    score = 0.5
    reasons = []
    try:
        m = _macro_cache_get("trend|BTC|400")
        if isinstance(m, dict) and isinstance(m.get("rows"), list) and m["rows"]:
            score += 0.2
        else:
            reasons.append("macro_trend_missing")
    except Exception:
        reasons.append("macro_trend_error")
    try:
        sig = len(EVENTS)
        ords = len(ORDERS)
        if sig > 0:
            score += 0.15
        else:
            reasons.append("no_signals")
        if ords > 0:
            score += 0.15
        else:
            reasons.append("no_orders")
    except Exception:
        reasons.append("metrics_error")
    score = max(0.0, min(1.0, float(score)))
    grade = "green" if score >= 0.75 else ("yellow" if score >= 0.5 else "red")
    return jsonify({"ok": True, "score": score, "grade": grade, "reasons": reasons, "ts": int(_now_ms())})

