@app.route("/risk/stack/eval", methods=["GET", "POST"])
def risk_stack_eval():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    params = request.get_json(force=True) if request.method == "POST" else {}
    thr = CONFIG.get("risk_stack_thresholds") or {"funding_pct_extreme": 0.05, "spread_bp_extreme": 30, "liquidity_drop_pct": 0.3}
    funding = float(params.get("funding_pct") or 0.0)
    spread_bp = float(params.get("spread_bp") or 0.0)
    liq_drop = float(params.get("liquidity_drop_pct") or 0.0)
    factors = {
        "funding_pct_extreme": abs(funding) >= float(thr["funding_pct_extreme"]),
        "spread_bp_extreme": abs(spread_bp) >= float(thr["spread_bp_extreme"]),
        "liquidity_drop_extreme": float(liq_drop) >= float(thr["liquidity_drop_pct"]),
    }
    pass_ = not any(factors.values())
    return jsonify({"ok": True, "pass": bool(pass_), "factors": factors, "thresholds": thr, "ts": int(_now_ms())})

@app.route("/audit/factors", methods=["POST"])
def audit_factors():
    if not (_agent_write_auth_ok() or _agent_sandbox_task_auth_ok()):
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    data = request.get_json(force=True) or {}
    items = data.get("items")
    out_items = []
    if isinstance(items, list):
        for it in items:
            if isinstance(it, dict):
                out_items.append({
                    "factor": str(it.get("factor") or ""),
                    "contribution": float(it.get("contribution") or 0.0),
                    "evidence": it.get("evidence") or {},
                    "ts": int(it.get("ts") or _now_ms()),
                })
    if not out_items:
        return jsonify({"ok": False, "error": "no_items"}), 400
    q = _agent_outbox_dir() / "factor_contrib.jsonl"
    saved = 0
    try:
        with open(q, "a", encoding="utf-8") as f:
            for it in out_items:
                f.write(json.dumps(it, ensure_ascii=False) + "\n")
                saved += 1
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500
    return jsonify({"ok": True, "saved": int(saved), "ts": int(_now_ms())})

