def _sandbox_queue_enqueue_impl(
    *,
    trace_id: str,
    inputs: Dict[str, Any],
    trigger: Optional[str] = None,
    req_type: Optional[str] = None,
    outputs: Optional[Dict[str, Any]] = None,
) -> Tuple[Dict[str, Any], int]:
    etype = str(req_type or "").strip().lower()
    if etype not in ("sandbox.job.request", "sandbox.job"):
        etype = "sandbox.job.request"
        if req_type:
            inputs = dict(inputs)
            inputs.setdefault("job_type", str(req_type))

    pol = CONFIG.get("sandbox_policy") or {}
    st = CONFIG.get("sandbox_state")
    if not isinstance(st, dict):
        st = {"running": 0, "queued": 0}
    try:
        qmax = int(pol.get("queue_max") or 8)
    except Exception:
        qmax = 8
    qmax = max(1, min(2000, int(qmax)))
    if int(st.get("queued") or 0) >= int(qmax):
        return {"ok": False, "error": "queue_full", "state": st, "ts": int(_now_ms())}, 429

    job_id = uuid.uuid4().hex
    tid = str(trace_id or job_id).strip() or job_id
    env: Dict[str, Any] = {
        "type": etype,
        "id": job_id,
        "trace_id": tid,
        "ts": int(_now_ms()),
        "inputs": (inputs if isinstance(inputs, dict) else {}),
    }
    if isinstance(outputs, dict) and outputs:
        env["outputs"] = dict(outputs)
    if trigger is not None:
        env["trigger"] = str(trigger)

    try:
        q = _agent_outbox_dir() / "sandbox_queue.jsonl"
        with open(q, "a", encoding="utf-8") as f:
            f.write(json.dumps(env, ensure_ascii=False) + "\n")
    except Exception:
        return {"ok": False, "error": "queue_write_failed", "ts": int(_now_ms())}, 500

    st["queued"] = int(st.get("queued") or 0) + 1
    CONFIG["sandbox_state"] = st
    try:
        _save_config()
    except Exception:
        pass

    return {"ok": True, "queued": True, "state": st, "job": {"id": job_id, "trace_id": tid, "type": etype}, "ts": int(_now_ms())}, 202


@app.route("/repo/fetch_strategy", methods=["POST"])
def repo_fetch_strategy():
    if _governance_hmac_secret():
        if not _governance_write_auth_ok():
            return jsonify({"ok": False, "error": "unauthorized"}), 403
    else:
        if not (_governance_write_auth_ok() or _agent_sandbox_task_auth_ok()):
            return jsonify({"ok": False, "error": "unauthorized"}), 403
    if not _repo_fetch_enabled():
        return jsonify({"ok": False, "error": "repo_fetch_disabled"}), 400
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="repo.fetch_strategy")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)

    repo_url_raw = data.get("repo_url")
    mode = str(data.get("mode") or "stage").strip().lower() or "stage"
    branch = data.get("branch")
    commit = data.get("commit")
    subpath = data.get("path")
    strategy_name = data.get("strategy_name")
    repo_from_tree, tree_branch, tree_subpath = _parse_github_tree_url(str(repo_url_raw or ""))
    if repo_from_tree:
        repo_url_raw = repo_from_tree
        if (not branch) and tree_branch:
            branch = tree_branch
        if (not subpath) and tree_subpath:
            subpath = tree_subpath
    repo_url = _normalize_repo_url(repo_url_raw)
    if not repo_url:
        return jsonify({"ok": False, "error": "missing_repo_url"}), 400
    if not _repo_url_allowed(repo_url):
        return jsonify({"ok": False, "error": "repo_not_whitelisted"}), 403

    if subpath and str(subpath).strip().lower().endswith(".py"):
        try:
            pp = Path(str(subpath).strip())
            if not strategy_name:
                strategy_name = pp.stem
            parent = str(pp.parent).strip()
            subpath = (None if (not parent) or parent == "." else parent)
        except Exception:
            pass

    if mode in {"scan", "stage_scan", "download_and_scan"}:
        rep = _skill_github_fetch({"mode": "download_and_scan", "repo_url": repo_url, "branch": branch, "commit": commit, "path": subpath, "strategy_name": strategy_name, "trace_id": trace_id})
        if not isinstance(rep, dict) or not bool(rep.get("ok")):
            return jsonify(rep if isinstance(rep, dict) else {"ok": False, "error": "repo_fetch_failed"}), 400
        repo_id = str(rep.get("repo_id") or _repo_id_from_url(repo_url))
        commit_id = str(rep.get("commit") or "")
        out = {
            "ok": True,
            "mode": "download_and_scan",
            "repo_id": repo_id,
            "repo_url": repo_url,
            "commit": commit_id,
            "files": rep.get("files") if isinstance(rep.get("files"), list) else [],
            "diff_summary": rep.get("diff_summary"),
            "sandbox_path": rep.get("sandbox_path"),
            "analysis_report": rep.get("analysis_report"),
            "scan_ok": bool(rep.get("scan_ok", True)),
            "strategy_name_effective": rep.get("strategy_name_effective"),
            "rename_map": rep.get("rename_map") if isinstance(rep.get("rename_map"), list) else [],
            "trace_id": trace_id,
            "approval_id": approval_id,
            "ts": int(_now_ms()),
        }
        try:
            q = _agent_outbox_dir() / "repo_fetch.jsonl"
            with open(q, "a", encoding="utf-8") as f:
                f.write(json.dumps(out, ensure_ascii=False) + "\n")
        except Exception:
            pass
        try:
            art = _agent_pipeline_artifact_common_fields(trace_id=str(trace_id), created_at_ms=int(_now_ms()), producer_kind="agent")
            art.update({"ts": int(_now_ms()), "kind": "repo_fetch.scan", "repo": {"repo_id": repo_id, "repo_url": repo_url, "commit": commit_id, "branch": branch, "path": subpath}, "result": {"scan_ok": bool(out.get("scan_ok")), "sandbox_path": out.get("sandbox_path")}})
            _agent_pipeline_artifact_emit(trace_id=str(trace_id), kind="repo_fetch", artifact=art)
        except Exception:
            pass
        try:
            _audit_emit_action(
                "repo.fetch_strategy",
                _audit_base_payload(scope="governance", action="repo.fetch_strategy", trace_id=trace_id, extra={"ok": True, "repo_id": repo_id, "commit": commit_id, "approval_id": approval_id, "repo_url": str(repo_url), "mode": "download_and_scan"}),
            )
        except Exception:
            pass
        return jsonify(out)

    if mode in {"pipeline", "auto", "import_and_eval"}:
        family = str(data.get("family") or "trend").strip() or "trend"
        stage = str(data.get("stage") or "research").strip() or "research"
        timerange = (None if data.get("timerange") is None else str(data.get("timerange")).strip()) or None
        config_path = str(data.get("config") or data.get("config_path") or "user_data/config_local_backtest.json").strip() or "user_data/config_local_backtest.json"
        if (".." in config_path) or config_path.startswith("/") or config_path.startswith("\\") or (not config_path.startswith("user_data/")) or (not config_path.lower().endswith(".json")):
            return jsonify({"ok": False, "error": "bad_config", "trace_id": trace_id, "ts": int(_now_ms())}), 400
        try:
            timeout_sec = float(data.get("timeout_sec", 1800) or 1800)
        except Exception:
            timeout_sec = 1800.0
        timeout_sec = float(max(30.0, min(6 * 3600.0, timeout_sec)))

        rep = _skill_github_fetch({"mode": "download_and_scan", "repo_url": repo_url, "branch": branch, "commit": commit, "path": subpath, "strategy_name": strategy_name, "trace_id": trace_id})
        if not isinstance(rep, dict) or not bool(rep.get("ok")):
            return jsonify(rep if isinstance(rep, dict) else {"ok": False, "error": "repo_fetch_failed", "trace_id": trace_id, "ts": int(_now_ms())}), 400

        repo_id = str(rep.get("repo_id") or _repo_id_from_url(repo_url))
        commit_id = str(rep.get("commit") or "")
        sandbox_path = str(rep.get("sandbox_path") or "")
        scan_ok = bool(rep.get("scan_ok", True))
        effective_name = rep.get("strategy_name_effective")
        if effective_name is None:
            effective_name = strategy_name
        st_name = str(effective_name or "").strip()
        if not st_name and sandbox_path:
            try:
                stems = sorted({p.stem for p in Path(sandbox_path).glob("*.py") if p.is_file()})
            except Exception:
                stems = []
            if len(stems) == 1:
                st_name = stems[0]
        if not st_name:
            return jsonify({"ok": False, "error": "missing_strategy_name", "trace_id": trace_id, "repo_id": repo_id, "commit": commit_id, "sandbox_path": sandbox_path, "ts": int(_now_ms())}), 400

        out0 = {
            "ok": True,
            "mode": "pipeline",
            "repo_id": repo_id,
            "repo_url": repo_url,
            "commit": commit_id,
            "sandbox_path": sandbox_path,
            "analysis_report": rep.get("analysis_report"),
            "scan_ok": bool(scan_ok),
            "strategy_id": st_name,
            "trace_id": trace_id,
            "approval_id": approval_id,
            "ts": int(_now_ms()),
        }
        try:
            q = _agent_outbox_dir() / "repo_fetch.jsonl"
            with open(q, "a", encoding="utf-8") as f:
                f.write(json.dumps(out0, ensure_ascii=False) + "\n")
        except Exception:
            pass
        try:
            art = _agent_pipeline_artifact_common_fields(trace_id=str(trace_id), created_at_ms=int(_now_ms()), producer_kind="agent")
            art.update({"ts": int(_now_ms()), "kind": "repo_fetch.pipeline", "repo": {"repo_id": repo_id, "repo_url": repo_url, "commit": commit_id, "branch": branch, "path": subpath}, "result": {"scan_ok": bool(scan_ok), "sandbox_path": sandbox_path, "strategy_id": st_name}})
            _agent_pipeline_artifact_emit(trace_id=str(trace_id), kind="repo_fetch", artifact=art)
        except Exception:
            pass

        if not scan_ok:
            return jsonify({"ok": False, "error": "code_scan_failed", "trace_id": trace_id, "repo": {"repo_id": repo_id, "repo_url": repo_url, "commit": commit_id}, "sandbox_path": sandbox_path, "analysis_report": rep.get("analysis_report"), "ts": int(_now_ms())}), 400

        bt = _run_backtest(config_path, timerange, strategy=str(st_name), strategy_path=str(sandbox_path), timeout_sec=timeout_sec)
        if not isinstance(bt, dict) or not bool(bt.get("ok")):
            return jsonify({"ok": False, "error": "backtest_failed", "trace_id": trace_id, "repo": {"repo_id": repo_id, "repo_url": repo_url, "commit": commit_id}, "sandbox_path": sandbox_path, "backtest": bt, "ts": int(_now_ms())}), 500
        zip_name = str(bt.get("result_zip") or "").strip()
        if (not zip_name) or (not zip_name.lower().endswith(".zip")) or (".." in zip_name) or ("/" in zip_name) or ("\\" in zip_name):
            return jsonify({"ok": False, "error": "bad_result_zip", "trace_id": trace_id, "backtest": bt, "ts": int(_now_ms())}), 500
        zip_path = _backtests_dir() / zip_name
        if (not zip_path.exists()) or (not zip_path.is_file()):
            return jsonify({"ok": False, "error": "backtest_zip_not_found", "trace_id": trace_id, "backtest": bt, "ts": int(_now_ms())}), 500

        sync_payload: Dict[str, Any] = {
            "trace_id": trace_id,
            "zip": zip_name,
            "strategy_id": st_name,
            "family": family,
            "stage": stage,
            "eval_policy_ref": (str(data.get("eval_policy_ref") or "").strip() or "p3_default"),
            "source": {
                "kind": "github",
                "repo_url": repo_url,
                "repo_id": repo_id,
                "commit": commit_id,
                "branch": (None if branch is None else str(branch)),
                "path": (None if subpath is None else str(subpath)),
                "sandbox_path": sandbox_path,
                "diff_summary": rep.get("diff_summary"),
                "ts": int(_now_ms()),
            },
        }
        if data.get("tags") is not None and isinstance(data.get("tags"), list):
            sync_payload["tags"] = [str(x) for x in (data.get("tags") or []) if str(x or "").strip()]
        if data.get("robustness") is not None:
            sync_payload["robustness"] = data.get("robustness")
        if data.get("econ_driver") is not None:
            sync_payload["econ_driver"] = data.get("econ_driver")
        if data.get("owner") is not None:
            sync_payload["owner"] = data.get("owner")

        sync_out, sync_code = _strategy_registry_sync_from_zip_impl(data=sync_payload, zip_path=Path(zip_path))
        if int(sync_code) != 200 or (not isinstance(sync_out, dict)) or (not bool(sync_out.get("ok"))):
            return jsonify({"ok": False, "error": (sync_out.get("error") if isinstance(sync_out, dict) else None) or "sync_failed", "trace_id": trace_id, "backtest": bt, "sync": sync_out, "ts": int(_now_ms())}), int(sync_code)

        queue_job = None
        if bool(data.get("enqueue_sandbox", True)):
            job_inputs: Dict[str, Any] = {"candidates": [{"strategy_id": str(st_name), "source_zip": str(zip_name)}], "base_trace_id": trace_id, "trigger_event": "repo.fetch_strategy"}
            job_resp, job_code = _sandbox_queue_enqueue_impl(trace_id=str(trace_id), inputs=job_inputs, trigger="repo.fetch_strategy")
            if int(job_code) >= 300:
                return jsonify({"ok": False, "error": "sandbox_enqueue_failed", "trace_id": trace_id, "job": job_resp, "ts": int(_now_ms())}), int(job_code)
            queue_job = job_resp.get("job") if isinstance(job_resp, dict) else None
            try:
                cand_art = _agent_pipeline_artifact_common_fields(trace_id=str(trace_id), created_at_ms=int(_now_ms()), producer_kind="agent")
                cand_art.update({"ts": int(_now_ms()), "items": [{"strategy_id": str(st_name), "source_zip": str(zip_name)}]})
                _agent_pipeline_artifact_validate_and_emit(trace_id=str(trace_id), kind="candidate_strategies", artifact=cand_art)
            except Exception:
                pass

        out = {"ok": True, "mode": "pipeline", "trace_id": trace_id, "approval_id": approval_id, "repo": {"repo_id": repo_id, "repo_url": repo_url, "commit": commit_id, "branch": branch, "path": subpath, "sandbox_path": sandbox_path}, "backtest": bt, "sync": sync_out, "candidate": {"strategy_id": str(st_name), "source_zip": str(zip_name)}, "sandbox_job": queue_job, "ts": int(_now_ms())}
        try:
            _audit_emit_action(
                "repo.fetch_strategy",
                _audit_base_payload(scope="governance", action="repo.fetch_strategy", trace_id=trace_id, extra={"ok": True, "repo_id": repo_id, "commit": commit_id, "approval_id": approval_id, "repo_url": str(repo_url), "mode": "pipeline", "zip": zip_name}),
            )
        except Exception:
            pass
        return jsonify(out)

    ok, head, repo_path, err = _repo_ensure_cached(repo_url, branch=branch, commit=commit)
    if not ok or repo_path is None:
        return jsonify({"ok": False, "error": "repo_fetch_failed", "detail": err}), 500
    repo_id = _repo_id_from_url(repo_url)
    commit_id = str(head or "")
    if not commit_id:
        return jsonify({"ok": False, "error": "commit_not_found"}), 500

    stage_ok, sandbox_path, files, stage_err, diff_summary = _strategy_sandbox_stage_from_git(repo_path, subpath, repo_id, commit_id, strategy_name=strategy_name)
    if not stage_ok:
        return jsonify({"ok": False, "error": stage_err}), 400
    align = _strategy_sandbox_align_and_dedupe(Path(str(sandbox_path)), repo_id=str(repo_id), preferred_name=(None if strategy_name is None else str(strategy_name)))
    if not bool(align.get("ok", True)):
        return jsonify({"ok": False, "error": align.get("error") or "sandbox_align_failed"}), 400
    _repo_update_registry(repo_id, repo_url, repo_path, commit_id)

    out = {
        "ok": True,
        "mode": "stage",
        "repo_id": repo_id,
        "repo_url": repo_url,
        "commit": commit_id,
        "files": files,
        "diff_summary": diff_summary,
        "sandbox_path": sandbox_path,
        "strategy_name_effective": align.get("effective_strategy_name"),
        "rename_map": (align.get("renamed") if isinstance(align.get("renamed"), list) else []),
        "trace_id": trace_id,
        "approval_id": approval_id,
        "ts": int(_now_ms()),
    }
    try:
        q = _agent_outbox_dir() / "repo_fetch.jsonl"
        with open(q, "a", encoding="utf-8") as f:
            f.write(json.dumps(out, ensure_ascii=False) + "\n")
    except Exception:
        pass
    try:
        art = _agent_pipeline_artifact_common_fields(trace_id=str(trace_id), created_at_ms=int(_now_ms()), producer_kind="agent")
        art.update({"ts": int(_now_ms()), "kind": "repo_fetch.stage", "repo": {"repo_id": repo_id, "repo_url": repo_url, "commit": commit_id, "branch": branch, "path": subpath}, "result": {"sandbox_path": sandbox_path}})
        _agent_pipeline_artifact_emit(trace_id=str(trace_id), kind="repo_fetch", artifact=art)
    except Exception:
        pass
    try:
        _audit_emit_action(
            "repo.fetch_strategy",
            _audit_base_payload(scope="governance", action="repo.fetch_strategy", trace_id=trace_id, extra={"ok": True, "repo_id": repo_id, "commit": commit_id, "approval_id": approval_id, "repo_url": str(repo_url), "mode": "stage"}),
        )
    except Exception:
        pass
    return jsonify(out)

@app.route("/repo/scan", methods=["POST"])
def repo_scan():
    if _governance_hmac_secret():
        if not _governance_write_auth_ok():
            return jsonify({"ok": False, "error": "unauthorized"}), 403
    else:
        if not (_governance_write_auth_ok() or _agent_sandbox_task_auth_ok()):
            return jsonify({"ok": False, "error": "unauthorized"}), 403
    if not _repo_fetch_enabled():
        return jsonify({"ok": False, "error": "repo_fetch_disabled"}), 400
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="repo.scan")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)

    repo_id = data.get("repo_id")
    repo_url = _normalize_repo_url(data.get("repo_url"))
    since_commit = data.get("since_commit")
    max_items = data.get("max_items")
    auto_pipeline = bool(data.get("auto_pipeline", False))
    pipeline_limit = data.get("pipeline_limit")
    try:
        pipeline_limit_n = int(pipeline_limit or 1)
    except Exception:
        pipeline_limit_n = 1
    pipeline_limit_n = max(1, min(5, int(pipeline_limit_n)))

    repo_path = None
    repo_id_final = None
    if repo_id:
        reg = _repo_registry_get()
        meta = reg.get(str(repo_id)) if isinstance(reg, dict) else None
        if isinstance(meta, dict) and meta.get("path"):
            repo_path = Path(str(meta.get("path")))
            repo_id_final = str(repo_id)
    if repo_path is None and repo_url:
        if not _repo_url_allowed(repo_url):
            return jsonify({"ok": False, "error": "repo_not_whitelisted"}), 403
        ok, head, path, err = _repo_ensure_cached(repo_url)
        if not ok or path is None:
            return jsonify({"ok": False, "error": "repo_fetch_failed", "detail": err}), 500
        repo_id_final = _repo_id_from_url(repo_url)
        if head:
            _repo_update_registry(repo_id_final, repo_url, path, str(head))
        repo_path = path
    if repo_path is None or not repo_path.exists():
        return jsonify({"ok": False, "error": "repo_not_found"}), 404

    repo_url_effective = repo_url
    if (not repo_url_effective) and repo_id_final:
        try:
            reg2 = _repo_registry_get()
            meta2 = reg2.get(str(repo_id_final)) if isinstance(reg2, dict) else None
            if isinstance(meta2, dict) and meta2.get("repo_url"):
                repo_url_effective = _normalize_repo_url(str(meta2.get("repo_url")))
        except Exception:
            repo_url_effective = repo_url

    commits = _repo_scan_commits(repo_path, since_commit=str(since_commit) if since_commit is not None else None, max_items=int(max_items or 20))
    auto_results = []
    if auto_pipeline and isinstance(commits, list) and commits:
        for it in commits[:pipeline_limit_n]:
            cmt = str((it or {}).get("commit") or "").strip()
            if not cmt:
                continue
            payload = {
                "trace_id": trace_id,
                "mode": "pipeline",
                "repo_url": repo_url_effective,
                "repo_id": repo_id_final,
                "commit": cmt,
                "path": data.get("path"),
                "strategy_name": data.get("strategy_name"),
                "family": data.get("family"),
                "stage": data.get("stage"),
                "timerange": data.get("timerange"),
                "config": data.get("config") or data.get("config_path"),
                "timeout_sec": data.get("timeout_sec"),
                "eval_policy_ref": data.get("eval_policy_ref"),
                "enqueue_sandbox": data.get("enqueue_sandbox"),
                "tags": data.get("tags"),
                "robustness": data.get("robustness"),
                "econ_driver": data.get("econ_driver"),
                "owner": data.get("owner"),
            }
            try:
                if repo_url and (not _repo_url_allowed(repo_url)):
                    auto_results.append({"ok": False, "commit": cmt, "error": "repo_not_whitelisted"})
                    continue
                rp_url = _normalize_repo_url(payload.get("repo_url"))
                if not rp_url:
                    auto_results.append({"ok": False, "commit": cmt, "error": "missing_repo_url"})
                    continue
                if not _repo_url_allowed(rp_url):
                    auto_results.append({"ok": False, "commit": cmt, "error": "repo_not_whitelisted"})
                    continue
                rep2 = _skill_github_fetch({"mode": "download_and_scan", "repo_url": rp_url, "commit": cmt, "path": payload.get("path"), "strategy_name": payload.get("strategy_name"), "trace_id": trace_id})
                if not isinstance(rep2, dict) or not bool(rep2.get("ok")):
                    auto_results.append({"ok": False, "commit": cmt, "error": (rep2.get("error") if isinstance(rep2, dict) else "repo_fetch_failed")})
                    continue
                auto_results.append({"ok": True, "commit": cmt, "sandbox_path": rep2.get("sandbox_path"), "scan_ok": bool(rep2.get("scan_ok", True)), "strategy_name_effective": rep2.get("strategy_name_effective")})
            except Exception as e:
                auto_results.append({"ok": False, "commit": cmt, "error": str(e)})
    try:
        _audit_emit_action(
            "repo.scan",
            _audit_base_payload(scope="governance", action="repo.scan", trace_id=trace_id, extra={"ok": True, "repo_id": repo_id_final, "count": (len(commits) if isinstance(commits, list) else None), "approval_id": approval_id}),
        )
    except Exception:
        pass
    try:
        art = _agent_pipeline_artifact_common_fields(trace_id=str(trace_id), created_at_ms=int(_now_ms()), producer_kind="agent")
        art.update({"ts": int(_now_ms()), "kind": "repo_scan", "repo": {"repo_id": repo_id_final, "repo_url": repo_url}, "commits": commits})
        _agent_pipeline_artifact_emit(trace_id=str(trace_id), kind="repo_scan", artifact=art)
    except Exception:
        pass
    out = {"ok": True, "repo_id": repo_id_final, "commits": commits, "trace_id": trace_id, "approval_id": approval_id, "ts": int(_now_ms())}
    if auto_results:
        out["auto"] = {"mode": "download_and_scan", "results": auto_results}
    return jsonify(out)

@app.route("/code/compliance/scan", methods=["POST"])
def code_compliance_scan():
    data = request.get_json(force=True) or {}
    files = data.get("files") if isinstance(data.get("files"), list) else []
    ruleset_version = 2

    def _scan_one(path: str, content: str) -> List[Dict[str, Any]]:
        issues: List[Dict[str, Any]] = []
        if not str(path).lower().endswith(".py"):
            low = str(content or "").lower()
            if "http://" in low or "https://" in low:
                issues.append({"path": path, "rule": "ban_url_literal", "severity": "high"})
            return issues

        try:
            tree = ast.parse(content or "", filename=path)
        except SyntaxError as e:
            issues.append({
                "path": path,
                "rule": "syntax_error",
                "severity": "high",
                "line": int(getattr(e, "lineno", 0) or 0),
                "col": int(getattr(e, "offset", 0) or 0),
            })
            return issues
        except Exception:
            issues.append({"path": path, "rule": "parse_failed", "severity": "high"})
            return issues

        alias_to_mod: Dict[str, str] = {}

        def _root(mod: str) -> str:
            s = str(mod or "").strip()
            return s.split(".", 1)[0] if s else ""

        banned_root = {"ccxt", "requests", "subprocess", "socket", "aiohttp", "websocket", "websockets", "paramiko", "urllib", "importlib"}

        class V(ast.NodeVisitor):
            def visit_Import(self, node: ast.Import):
                for a in node.names or []:
                    try:
                        root = _root(a.name)
                        asn = str(a.asname or root)
                        if asn:
                            alias_to_mod[asn] = root
                        if root in banned_root:
                            issues.append({"path": path, "rule": f"ban_import_{root}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                    except Exception:
                        continue
                self.generic_visit(node)

            def visit_ImportFrom(self, node: ast.ImportFrom):
                root = _root(node.module)
                try:
                    for a in node.names or []:
                        asn = str(a.asname or a.name or "")
                        if asn and root:
                            alias_to_mod[asn] = root
                except Exception:
                    pass
                if root in banned_root:
                    issues.append({"path": path, "rule": f"ban_import_{root}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                self.generic_visit(node)

            def visit_Call(self, node: ast.Call):
                fn = node.func

                def _name(n: ast.AST) -> Optional[str]:
                    return str(n.id) if isinstance(n, ast.Name) else None

                def _attr(n: ast.AST) -> Optional[Tuple[str, str]]:
                    if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name):
                        return str(n.value.id), str(n.attr)
                    return None

                nm = _name(fn)
                if nm in {"eval", "exec"}:
                    issues.append({"path": path, "rule": f"ban_{nm}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                if nm == "__import__":
                    try:
                        a0 = node.args[0] if node.args else None
                        if isinstance(a0, ast.Constant) and isinstance(a0.value, str):
                            root = _root(a0.value)
                            if root in banned_root:
                                issues.append({"path": path, "rule": f"ban_dynamic_import_{root}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                    except Exception:
                        pass

                at = _attr(fn)
                if at is not None:
                    base, attr = at
                    base_mod = alias_to_mod.get(base, base)
                    if base_mod == "os" and attr in {"system", "popen", "spawnl", "spawnlp", "spawnv", "spawnvp", "execl", "execle", "execlp", "execlpe", "execv", "execve", "execvp", "execvpe"}:
                        issues.append({"path": path, "rule": f"ban_os_{attr}", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                    if base_mod == "subprocess":
                        issues.append({"path": path, "rule": "ban_subprocess_call", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                    if base_mod == "importlib" and attr in {"import_module"}:
                        issues.append({"path": path, "rule": "ban_dynamic_import_importlib", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                self.generic_visit(node)

            def visit_Constant(self, node: ast.Constant):
                try:
                    if isinstance(node.value, str):
                        s = node.value.lower()
                        if "http://" in s or "https://" in s:
                            issues.append({"path": path, "rule": "ban_url_literal", "severity": "high", "line": int(getattr(node, "lineno", 0) or 0)})
                except Exception:
                    pass

        V().visit(tree)
        return issues

    issues: List[Dict[str, Any]] = []
    for f in files:
        p = str((f or {}).get("path") or "")
        c = (f or {}).get("content")
        content_s = "" if c is None else str(c)
        issues.extend(_scan_one(p, content_s))

    return jsonify({
        "ok": True,
        "pass": (len(issues) == 0),
        "issues": issues,
        "ruleset_version": int(ruleset_version),
        "ts": int(_now_ms()),
    })

@app.route("/sandbox/policy", methods=["GET", "POST"])
@app.route("/agent/sandbox/policy", methods=["GET", "POST"])
def sandbox_policy():
    if request.method == "GET":
        return jsonify({"ok": True, "policy": CONFIG.get("sandbox_policy") or {}, "ts": int(_now_ms())})

    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403

    data = request.get_json(force=True) or {}

    confirm_live = bool(data.get("confirm_live", False))
    approval_id = (None if data.get("approval_id") is None else str(data.get("approval_id") or "").strip())
    data.pop("confirm_live", None)
    data.pop("approval_id", None)

    if not _is_local_request():
        if not approval_id:
            return jsonify({"ok": False, "error": "approval_required", "ts": int(_now_ms())}), 400
        if not _approval_ok(approval_id, max_age_ms=86400_000):
            return jsonify({"ok": False, "error": "approval_invalid", "ts": int(_now_ms())}), 400
        if not bool(confirm_live):
            return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms())}), 400

    rb_pt = _rollback_snapshot_append(label="sandbox.policy", reason="l2_preflight", config_keys=["sandbox_policy"])
    if rb_pt is None:
        return jsonify({"ok": False, "error": "rollback_snapshot_failed", "ts": int(_now_ms())}), 500

    policy = {
        "cpu_cores": int(data.get("cpu_cores") or 2),
        "mem_gb": int(data.get("mem_gb") or 4),
        "timeout_sec": int(data.get("timeout_sec") or 1800),
        "concurrent_limit": int(data.get("concurrent_limit") or 2),
        "queue_max": int(data.get("queue_max") or 8),
        "deny_network": True,
    }
    CONFIG["sandbox_policy"] = policy
    try:
        _save_config()
    except Exception:
        pass

    try:
        _audit_emit_action(
            "sandbox.policy.set",
            _audit_base_payload(
                scope="governance",
                action="sandbox.policy.set",
                extra={"policy": policy, "approval_id": approval_id, "rollback_point_id": (rb_pt or {}).get("id")},
            ),
        )
    except Exception:
        pass

    out = {"ok": True, "policy": policy, "ts": int(_now_ms()), "rollback_point": rb_pt}
    if approval_id:
        out["approval_id"] = approval_id
    return jsonify(out)

@app.route("/sandbox/queue/submit", methods=["POST"])
@app.route("/agent/sandbox/queue/submit", methods=["POST"])
def sandbox_queue_submit():
    if not _agent_sandbox_task_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    req_type = str(data.get("type") or "").strip()
    inputs = data.get("inputs") if isinstance(data.get("inputs"), dict) else None
    outputs = data.get("outputs") if isinstance(data.get("outputs"), dict) else None
    payload = data.get("payload") if isinstance(data.get("payload"), dict) else {}
    if inputs is None:
        inputs = payload

    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    trigger = (None if data.get("trigger") is None else str(data.get("trigger")))
    rep, code = _sandbox_queue_enqueue_impl(trace_id=str(trace_id), inputs=(inputs if isinstance(inputs, dict) else {}), trigger=trigger, req_type=req_type, outputs=(outputs if isinstance(outputs, dict) else None))
    return jsonify(rep), int(code)

@app.route("/gate/thresholds", methods=["GET", "POST"])
def gate_thresholds():
    if request.method == "GET":
        return jsonify({"ok": True, "thresholds": CONFIG.get("gate_thresholds") or {}, "ts": int(_now_ms())})
    if not _governance_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    trace_id = str(data.get("trace_id") or "").strip() or uuid.uuid4().hex
    confirm_live = bool(data.get("confirm_live", False))
    ok_appr, approval_id, err_obj, err_code = _governance_require_approval_or_error(data, trace_id=trace_id, action="gate.thresholds.set")
    if not ok_appr:
        return jsonify(err_obj), int(err_code)
    data.pop("confirm_live", None)
    data.pop("approval_id", None)
    data.pop("trace_id", None)

    if (not _is_local_request()) and (not bool(confirm_live)):
        return jsonify({"ok": False, "error": "confirm_live_required", "ts": int(_now_ms())}), 400

    rb_pt = _rollback_snapshot_append(label="gate.thresholds", reason="l2_preflight")
    if rb_pt is None:
        return jsonify({"ok": False, "error": "rollback_snapshot_failed", "ts": int(_now_ms())}), 500
    thr = {
        "pf": float(data.get("pf") or 1.05),
        "dd": float(data.get("dd") or 0.95),
        "trades": float(data.get("trades") or 0.7),
        "winrate": float(data.get("winrate") or 0.95),
        "recovery_time": float(data.get("recovery_time") or 1.2),
        "oos_ok": bool(data.get("oos_ok", True)),
        "sensitivity_ok": bool(data.get("sensitivity_ok", True)),
    }
    CONFIG["gate_thresholds"] = thr
    try:
        _save_config()
    except Exception:
        pass

    try:
        _audit_emit_action(
            "gate.thresholds.set",
            _audit_base_payload(
                scope="governance",
                action="gate.thresholds.set",
                trace_id=trace_id,
                extra={"thresholds": thr, "approval_id": approval_id, "rollback_point_id": (rb_pt or {}).get("id")},
            ),
        )
    except Exception:
        pass

    out = {"ok": True, "thresholds": thr, "ts": int(_now_ms()), "rollback_point": rb_pt}
    out["trace_id"] = trace_id
    out["approval_id"] = approval_id
    return jsonify(out)

@app.route("/evaluation/gate/check", methods=["GET"])
def evaluation_gate_check():
    thr = CONFIG.get("gate_thresholds") or {}
    p = _backtest_pick_latest_zip_path()
    rep = _backtest_report_from_zip(p, strategy=None)
    if not isinstance(rep, dict) or not bool(rep.get("ok")):
        return jsonify({"ok": False, "error": "backtest_unavailable"}), 404
    ms = rep.get("metrics_summary") or {}
    baseline = {}  # could be extended to load baseline
    checks = {
        "pf": (ms.get("pf") is not None) and (float(ms.get("pf")) >= float(thr.get("pf", 1.05))),
        "dd": (ms.get("maxdd") is not None) and (float(ms.get("maxdd")) <= float(thr.get("dd", 0.95))),
        "trades": (ms.get("trades") is not None) and (float(ms.get("trades")) >= float(thr.get("trades", 0.7)) * float((baseline.get("trades") or ms.get("trades") or 1))),
        "winrate": (ms.get("winrate") is not None) and (float(ms.get("winrate")) >= float(thr.get("winrate", 0.95))),
    }
    passed = all(bool(v) for v in checks.values())
    return jsonify({"ok": True, "passed": bool(passed), "checks": checks, "thresholds": thr, "metrics": ms, "ts": int(_now_ms())})

