@app.route("/approvals/summary", methods=["GET"])
def approvals_summary():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    try:
        max_lines = int(request.args.get("max_lines") or 800)
    except Exception:
        max_lines = 800
    max_lines = max(50, min(20000, int(max_lines)))
    try:
        max_bytes = int(request.args.get("max_bytes") or 2_000_000)
    except Exception:
        max_bytes = 2_000_000
    max_bytes = max(100_000, min(20_000_000, int(max_bytes)))

    now_ms = int(_now_ms())
    try:
        days = int(request.args.get("days") or 0)
    except Exception:
        days = 0
    if days <= 0:
        try:
            by_stem = CONFIG.get("agent_outbox_retention_days_by_stem")
        except Exception:
            by_stem = None
        keep_days = None
        if isinstance(by_stem, dict):
            try:
                keep_days = int(by_stem.get("approvals") or 0) or None
            except Exception:
                keep_days = None
        if keep_days is None:
            try:
                keep_days = int(CONFIG.get("agent_outbox_retention_days_default", 180) or 180)
            except Exception:
                keep_days = 180
        days = int(keep_days)
    days = max(1, min(36500, int(days)))

    paths = _agent_outbox_recent_paths("approvals", days=int(days), now_ms=int(now_ms))
    if not paths:
        p0 = _approvals_log_path()
        return jsonify({"ok": True, "counts": {"total": 0, "pending": 0, "approved": 0, "rejected": 0, "other": 0}, "pending": [], "latest": None, "path": str(p0), "ts": int(now_ms)})

    lines: List[str] = []
    bytes_used = 0
    lines_used = 0
    for p in paths:
        if lines_used >= int(max_lines) or bytes_used >= int(max_bytes):
            break
        try:
            if str(p.name).lower().endswith(".gz"):
                chunk = _tail_lines_gzip(p, max_lines=max(1, int(max_lines) - int(lines_used)))
            else:
                chunk = _tail_lines(p, max_lines=max(1, int(max_lines) - int(lines_used)), max_bytes=max(1024, int(max_bytes) - int(bytes_used)))
        except Exception:
            chunk = []
        if not chunk:
            continue
        for ln in chunk:
            s = str(ln or "").strip("\n")
            if not s.strip():
                continue
            try:
                b = len(s.encode("utf-8", errors="ignore"))
            except Exception:
                b = len(s)
            if bytes_used + int(b) > int(max_bytes):
                break
            lines.append(s)
            lines_used += 1
            bytes_used += int(b)
            if lines_used >= int(max_lines) or bytes_used >= int(max_bytes):
                break
        if lines_used >= int(max_lines) or bytes_used >= int(max_bytes):
            break
    total = 0
    n_pending = 0
    n_approved = 0
    n_rejected = 0
    n_other = 0
    pending_items = []
    recent_auto_rejected = []
    latest = None
    parsed: List[Tuple[int, int, Dict[str, Any]]] = []
    for i, ln in enumerate(lines):
        s = str(ln or "").strip("\n")
        if not s.strip():
            continue
        try:
            obj = json.loads(s)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        try:
            ts_i = int(obj.get("ts") or 0)
        except Exception:
            ts_i = 0
        parsed.append((int(ts_i), int(i), obj))

    parsed.sort(key=lambda x: (int(x[0]), int(x[1])), reverse=True)
    seen_ids: set = set()
    for ts_i, _, obj in parsed:
        total += 1
        oid = str(obj.get("id") or "").strip()
        if oid:
            if oid in seen_ids:
                continue
            seen_ids.add(oid)
        dec = str(obj.get("decision") or "").strip().lower()
        if dec.startswith("pending"):
            n_pending += 1
            if len(pending_items) < 20:
                trace_id0 = str(obj.get("trace_id") or "").strip()
                is_explore = _trace_is_paramopt_explore(trace_id0)
                exp_raw = obj.get("expires_at")
                try:
                    exp_i = int(exp_raw) if exp_raw is not None and str(exp_raw).strip() != "" else 0
                except Exception:
                    exp_i = 0
                if exp_i <= 0 and bool(is_explore) and int(ts_i) > 0:
                    try:
                        ttl_h0 = int(AUTOMATION.get("paramopt_explore_approval_ttl_hours", 24) or 24)
                    except Exception:
                        ttl_h0 = 24
                    ttl_h0 = max(1, min(168, int(ttl_h0)))
                    exp_i = int(int(ts_i) + int(ttl_h0) * 3600 * 1000)
                ttl_ms = (int(exp_i) - int(now_ms)) if int(exp_i) > 0 else None
                pending_items.append(
                    {
                        "id": obj.get("id"),
                        "trace_id": trace_id0,
                        "action": obj.get("action"),
                        "reason": obj.get("reason"),
                        "approver": obj.get("approver"),
                        "ts": obj.get("ts"),
                        "decision": obj.get("decision"),
                        "expires_at": (int(exp_i) if int(exp_i) > 0 else None),
                        "ttl_ms": (int(ttl_ms) if ttl_ms is not None else None),
                        "is_explore": bool(is_explore),
                        "auto_reject_policy": ("expired_24h_auto_reject" if bool(is_explore) else None),
                    }
                )
        elif dec in ("approve", "approved", "ok", "pass", "yes"):
            n_approved += 1
        elif dec in ("reject", "rejected", "deny", "denied", "no", "fail", "failed"):
            n_rejected += 1
            rs = str(obj.get("reason") or "").strip().lower()
            if (rs == "expired_24h_auto_reject") and len(recent_auto_rejected) < 20:
                recent_auto_rejected.append(
                    {
                        "id": obj.get("id"),
                        "trace_id": obj.get("trace_id"),
                        "action": obj.get("action"),
                        "reason": obj.get("reason"),
                        "approver": obj.get("approver"),
                        "decision": obj.get("decision"),
                        "ts": obj.get("ts"),
                    }
                )
        else:
            n_other += 1
        if latest is None:
            latest = {
                "id": obj.get("id"),
                "trace_id": obj.get("trace_id"),
                "action": obj.get("action"),
                "decision": obj.get("decision"),
                "ts": obj.get("ts"),
            }

    out = {
        "ok": True,
        "counts": {"total": int(total), "pending": int(n_pending), "approved": int(n_approved), "rejected": int(n_rejected), "other": int(n_other)},
        "pending": list(pending_items),
        "recent_auto_rejected": list(recent_auto_rejected),
        "latest": latest,
        "path": str(_approvals_log_path()),
        "ts": int(now_ms),
    }
    return jsonify(out)


