@app.route("/agent/approvals/brief/generate", methods=["POST"])
def agent_approvals_brief_generate():
    if not _agent_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    approval_id = str(data.get("id") or data.get("approval_id") or "").strip()
    if not approval_id:
        return jsonify({"ok": False, "error": "missing_id", "ts": int(_now_ms())}), 400
    force = bool(data.get("force", False))
    ap = _approval_lookup(approval_id, max_lines=20000, max_bytes=20_000_000)
    if not isinstance(ap, dict) or not ap:
        return jsonify({"ok": False, "error": "not_found", "id": approval_id, "ts": int(_now_ms())}), 404
    draft_id = str(ap.get("draft_id") or "").strip()
    if not draft_id:
        return jsonify({"ok": False, "error": "missing_draft_id", "id": approval_id, "ts": int(_now_ms())}), 400
    ent = _agent_changeset_draft_lookup(draft_id, max_lines=20000, max_bytes=20_000_000)
    if not isinstance(ent, dict) or not ent:
        return jsonify({"ok": False, "error": "draft_not_found", "draft_id": draft_id, "ts": int(_now_ms())}), 404
    now_ms = int(_now_ms())
    schema_version = "v1"
    brief = _approval_brief_build(approval=ap, draft_entry=ent, now_ms=int(now_ms), schema_version=str(schema_version))
    prev = _approval_brief_lookup_latest(approval_id)
    if (not force) and isinstance(prev, dict) and prev and str(prev.get("idempotency_key") or "").strip() == str(brief.get("idempotency_key") or "").strip():
        return jsonify({"ok": True, "skipped": True, "id": approval_id, "brief": _json_sanitize(prev), "ts": int(_now_ms())}), 200
    try:
        _agent_outbox_append_jsonl("approval_briefs.jsonl", brief)
    except Exception as e:
        return jsonify({"ok": False, "error": "write_failed", "detail": str(e), "ts": int(_now_ms())}), 500
    return jsonify({"ok": True, "skipped": False, "id": approval_id, "brief": _json_sanitize(brief), "ts": int(_now_ms())}), 200


