@app.route("/approvals/history", methods=["GET"])
def approvals_history():
    if not _agent_read_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    try:
        max_lines = int(request.args.get("max_lines") or 4000)
    except Exception:
        max_lines = 4000
    max_lines = max(50, min(50000, int(max_lines)))
    try:
        max_bytes = int(request.args.get("max_bytes") or 4_000_000)
    except Exception:
        max_bytes = 4_000_000
    max_bytes = max(100_000, min(50_000_000, int(max_bytes)))
    try:
        limit = int(request.args.get("limit") or 100)
    except Exception:
        limit = 100
    limit = max(1, min(1000, int(limit)))
    try:
        offset = int(request.args.get("offset") or 0)
    except Exception:
        offset = 0
    offset = max(0, int(offset))
    try:
        days = int(request.args.get("days") or 0)
    except Exception:
        days = 0
    now_ms = int(_now_ms())
    if days <= 0:
        try:
            by_stem = CONFIG.get("agent_outbox_retention_days_by_stem")
        except Exception:
            by_stem = None
        keep_days = None
        if isinstance(by_stem, dict):
            try:
                keep_days = int(by_stem.get("approvals") or 0) or None
            except Exception:
                keep_days = None
        if keep_days is None:
            try:
                keep_days = int(CONFIG.get("agent_outbox_retention_days_default", 180) or 180)
            except Exception:
                keep_days = 180
        days = int(keep_days)
    days = max(1, min(36500, int(days)))
    decision_raw = str(request.args.get("decision") or "all").strip().lower()
    decision_alias = {
        "approve": "approved",
        "approved": "approved",
        "ok": "approved",
        "pass": "approved",
        "yes": "approved",
        "reject": "rejected",
        "rejected": "rejected",
        "deny": "rejected",
        "denied": "rejected",
        "no": "rejected",
        "fail": "rejected",
        "failed": "rejected",
        "pending": "pending",
        "all": "all",
        "": "all",
    }
    decision_norm = decision_alias.get(decision_raw, decision_raw)
    action_filter = str(request.args.get("action") or "").strip().lower()
    q = str(request.args.get("q") or "").strip().lower()

    paths = _agent_outbox_recent_paths("approvals", days=int(days), now_ms=int(now_ms))
    if not paths:
        p0 = _approvals_log_path()
        return jsonify({"ok": True, "items": [], "total_scanned": 0, "total_matched": 0, "returned": 0, "offset": int(offset), "limit": int(limit), "path": str(p0), "ts": int(now_ms)})

    lines: List[str] = []
    bytes_used = 0
    lines_used = 0
    for p in paths:
        if lines_used >= int(max_lines) or bytes_used >= int(max_bytes):
            break
        try:
            if str(p.name).lower().endswith(".gz"):
                chunk = _tail_lines_gzip(p, max_lines=max(1, int(max_lines) - int(lines_used)))
            else:
                chunk = _tail_lines(p, max_lines=max(1, int(max_lines) - int(lines_used)), max_bytes=max(1024, int(max_bytes) - int(bytes_used)))
        except Exception:
            chunk = []
        if not chunk:
            continue
        for ln in chunk:
            s = str(ln or "").strip("\n")
            if not s.strip():
                continue
            try:
                b = len(s.encode("utf-8", errors="ignore"))
            except Exception:
                b = len(s)
            if bytes_used + int(b) > int(max_bytes):
                break
            lines.append(s)
            lines_used += 1
            bytes_used += int(b)
            if lines_used >= int(max_lines) or bytes_used >= int(max_bytes):
                break
        if lines_used >= int(max_lines) or bytes_used >= int(max_bytes):
            break

    items = []
    scanned = 0
    matched = 0
    skipped = 0
    for ln in reversed(lines):
        s = str(ln or "").strip("\n")
        if not s.strip():
            continue
        try:
            obj = json.loads(s)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        scanned += 1
        dec = str(obj.get("decision") or "").strip().lower()
        dec_norm = decision_alias.get(dec, dec)
        if str(decision_norm) != "all" and dec_norm != str(decision_norm):
            continue
        action = str(obj.get("action") or "").strip()
        if action_filter and action_filter not in action.lower():
            continue
        if q:
            q_fields = [
                str(obj.get("id") or ""),
                str(obj.get("trace_id") or ""),
                str(obj.get("action") or ""),
                str(obj.get("reason") or ""),
                str(obj.get("approver") or ""),
            ]
            q_hit = any(q in str(v).lower() for v in q_fields)
            if not q_hit:
                continue
        matched += 1
        if skipped < int(offset):
            skipped += 1
            continue
        if len(items) >= int(limit):
            continue
        items.append(
            {
                "id": obj.get("id"),
                "trace_id": obj.get("trace_id"),
                "action": obj.get("action"),
                "decision": obj.get("decision"),
                "reason": obj.get("reason"),
                "approver": obj.get("approver"),
                "ts": obj.get("ts"),
            }
        )
    has_more = bool(int(offset) + len(items) < int(matched))
    out = {
        "ok": True,
        "items": items,
        "total_scanned": int(scanned),
        "total_matched": int(matched),
        "returned": int(len(items)),
        "offset": int(offset),
        "limit": int(limit),
        "has_more": bool(has_more),
        "path": str(_approvals_log_path()),
        "ts": int(now_ms),
    }
    return jsonify(out)


@app.route("/approvals/log", methods=["POST"])
def approvals_log():
    if not _approval_executor_write_auth_ok():
        return jsonify({"ok": False, "error": "unauthorized", "ts": int(_now_ms())}), 403
    data = request.get_json(force=True) or {}
    now_ms = int(_now_ms())
    rid = (None if data.get("id") is None else str(data.get("id") or "").strip())
    if not rid:
        rid = hashlib.sha256(f"approval|{now_ms}|{uuid.uuid4().hex}".encode("utf-8")).hexdigest()[:16]
    trace_id = str(data.get("trace_id") or "").strip() or rid
    entry = {
        "id": rid,
        "trace_id": trace_id,
        "draft_id": (None if data.get("draft_id") is None else str(data.get("draft_id") or "").strip()) or None,
        "approver": str(data.get("approver") or ""),
        "decision": str(data.get("decision") or "approve"),
        "action": (None if data.get("action") is None else str(data.get("action") or "").strip()) or None,
        "reason": (None if data.get("reason") is None else str(data.get("reason") or "").strip()) or None,
        "gate_results": data.get("gate_results") if isinstance(data.get("gate_results"), dict) else {},
        "doc_refs": _doc_refs_sanitize(data.get("doc_refs")),
        "evidence": _evidence_sanitize(data.get("evidence"), gate_results=(data.get("gate_results") if isinstance(data.get("gate_results"), dict) else {})),
        "baseline_version": str(data.get("baseline_version") or ""),
        "expires_at": (None if data.get("expires_at") is None else int(float(data.get("expires_at"))) if str(data.get("expires_at") or "").strip() != "" else None),
        "ttl_ms": (None if data.get("ttl_ms") is None else int(float(data.get("ttl_ms"))) if str(data.get("ttl_ms") or "").strip() != "" else None),
        "ts": int(data.get("ts") or now_ms),
    }
    try:
        q = _approvals_log_path()
        with open(q, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    except Exception:
        return jsonify({"ok": False, "error": "write_failed"}), 500
    return jsonify({"ok": True, "id": rid, "saved": 1, "ts": int(_now_ms())})
@app.route("/api/ml3_health", methods=["GET"])
def api_ml3_health():
    ok = True
    reasons = []
    try:
        mdir = _models_dir()
        if not mdir.exists():
            ok = False
            reasons.append("models_dir_missing")
        artifacts = len(list(mdir.glob("*.pkl"))) + len(list(mdir.glob("*.pth")))
        if artifacts <= 0 and (ACTIVE_MODEL.get("obj") is None and ACTIVE_MODEL.get("name") != "__committee__"):
            reasons.append("no_model_artifacts")
    except Exception:
        ok = False
        reasons.append("models_dir_error")
    try:
        r = evaluation_acceptance_status()
        acc = r.get_json(force=True)
        if isinstance(acc, dict):
            pw = acc.get("profit_window") if isinstance(acc.get("profit_window"), dict) else {}
            if int(pw.get("n") or 0) <= 0:
                reasons.append("no_profit_window")
    except Exception:
        reasons.append("acceptance_unavailable")
    status = "ok" if (ok and not reasons) else "degraded"
    return jsonify({"ok": True, "status": status, "reasons": reasons, "ts": int(_now_ms())})

