@app.route("/change/package/generate", methods=["POST"])
def change_package_generate():
    data = request.get_json(force=True) or {}
    base_version = str(data.get("base_version") or "")
    target_version = str(data.get("target_version") or "")
    doc_section = str(data.get("doc_section") or "")
    doc_summary = str(data.get("doc_change_summary") or "")
    pf = data.get("pf")
    dd = data.get("dd")
    trades = data.get("trades")
    win = data.get("win")
    rollout = data.get("rollout") if isinstance(data.get("rollout"), dict) else {}
    overrides = data.get("config_overrides") if isinstance(data.get("config_overrides"), dict) else {}
    doc_refs = data.get("doc_refs")
    if not isinstance(doc_refs, list):
        doc_refs = None
    rollback_trigger = str(data.get("rollback_trigger") or "").strip() or None
    strategy_hint = str(data.get("strategy") or "").strip() or None
    # config diff (shallow)
    cur = CONFIG.copy()
    diff = {}
    for k, v in (overrides or {}).items():
        if cur.get(k) != v:
            diff[k] = {"from": cur.get(k), "to": v}
    # latest backtest summary
    bt_summary = None
    bt_report = None
    bt_eval = None
    try:
        p = _backtest_pick_latest_zip_path()
        rep = _backtest_report_from_zip(p, strategy=None)
        if isinstance(rep, dict) and rep.get("ok"):
            bt_summary = rep.get("metrics_summary")
            bt_report = rep
            bt_eval = rep.get("eval")
    except Exception:
        bt_summary = None
        bt_report = None
        bt_eval = None
    # rollback points list (short)
    rb_list = []
    try:
        r = evaluation_rollback_list()
        rb = r.get_json(force=True)
        if isinstance(rb, dict) and isinstance(rb.get("items"), list):
            rb_list = rb["items"]
    except Exception:
        rb_list = []

    evidence_exec = None
    try:
        now_ms = int(_now_ms())
        lookback_days = float(data.get("exec_lookback_days") or 7)
        lookback_days = max(0.1, min(3650.0, float(lookback_days)))
        start_ms = int(now_ms) - int(lookback_days * 86400.0 * 1000.0)
        evidence_exec = _audit_execution_quality(start_ts_ms=int(start_ms), end_ts_ms=int(now_ms), pair=None, strategy_id=None, max_points=5000, include_shadow=False)
    except Exception:
        evidence_exec = None

    evidence_perf = None
    try:
        evidence_perf = _orders_exec_equity_metrics(limit=5000)
    except Exception:
        evidence_perf = None

    chosen_rb = None
    if isinstance(rb_list, list) and rb_list:
        it0 = rb_list[0]
        if isinstance(it0, dict):
            chosen_rb = it0

    doc_refs_out = doc_refs if isinstance(doc_refs, list) else []
    if not doc_refs_out:
        doc_refs_out = [
            {"doc_path": "交易AI Agent 技术文档2.0.md", "section": (doc_section or "4.7.6"), "rule": "变更包最小集合"},
            {"doc_path": "技术文档.md", "section": "0.3", "rule": "工程索引（SSoT 入口）"},
        ]
    else:
        has_agent_doc = False
        has_tech_doc = False
        for r in doc_refs_out:
            if not isinstance(r, dict):
                continue
            dp = str(r.get("doc_path") or "").strip()
            if dp == "交易AI Agent 技术文档2.0.md":
                has_agent_doc = True
            if dp == "技术文档.md":
                has_tech_doc = True
        if not has_agent_doc:
            doc_refs_out.append({"doc_path": "交易AI Agent 技术文档2.0.md", "section": (doc_section or "4.7.6"), "rule": "变更包最小集合"})
        if not has_tech_doc:
            doc_refs_out.append({"doc_path": "技术文档.md", "section": "0.3", "rule": "工程索引（SSoT 入口）"})

    pkg = {
        "base_version": base_version,
        "target_version": target_version,
        "doc": {"section": doc_section, "change_summary": doc_summary},
        "metrics": {"pf": pf, "max_dd": dd, "trades": trades, "win_rate": win},
        "rollout": {
            "mode": rollout.get("mode"),
            "scope": rollout.get("scope"),
            "duration": rollout.get("duration"),
        },
        "config_diff": diff,
        "backtest_summary": bt_summary,
        "candidate": {
            "strategy": strategy_hint,
            "backtest_zip": (None if not isinstance(bt_report, dict) else bt_report.get("zip")),
            "metrics_summary": bt_summary,
        },
        "gate_result": bt_eval,
        "evidence": {
            "backtest": {
                "zip": (None if not isinstance(bt_report, dict) else bt_report.get("zip")),
                "metrics_summary": bt_summary,
                "eval": bt_eval,
            },
            "execution": evidence_exec,
            "performance": evidence_perf,
        },
        "rollback_plan": {
            "point": chosen_rb,
            "trigger": rollback_trigger,
        },
        "doc_refs": doc_refs_out,
        "rollback_points": rb_list,
        "ts": int(_now_ms()),
    }
    return jsonify({"ok": True, "package": pkg})

