@app.route("/validation/conflict/resolve", methods=["POST"])
def validation_conflict_resolve():
    data = request.get_json(force=True) or {}
    mode = str(data.get("mode") or "observe").strip().lower()
    guard = None
    try:
        r = automation_serving_pipeline_guard_eval()
        guard = r.get_json(force=True)
    except Exception:
        guard = None
    plan = {"action": "observe", "details": "门控未通过，保持观望或降仓"}
    result = None
    if isinstance(guard, dict) and not bool(guard.get("pass", False)):
        if mode == "rollback":
            try:
                r2 = automation_serving_pipeline_guard_rollback()
                result = r2.get_json(force=True)
                plan = {"action": "rollback", "details": "触发自动回滚"}
            except Exception as e:
                result = {"ok": False, "error": str(e)}
        else:
            plan = {"action": "observe", "details": "门控未通过，保持观望或降仓"}
    else:
        plan = {"action": "proceed", "details": "门控通过，可按灰度推进策略执行"}
    return jsonify({"ok": True, "guard": guard, "plan": plan, "result": result, "ts": int(_now_ms())})


def _parse_listen_port(v: Any) -> Optional[int]:
    try:
        if v is None:
            return None
        if isinstance(v, str):
            v = v.strip()
            if not v:
                return None
        p = int(v)
    except Exception:
        return None
    if p < 1 or p > 65535:
        return None
    return p


def _tcp_port_available(host: str, port: int) -> bool:
    s = None
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        s.bind((host, int(port)))
        return True
    except Exception:
        return False
    finally:
        try:
            if s is not None:
                s.close()
        except Exception:
            pass


def _pick_listen_port(host: str, preferred_port: int, strict: bool) -> int:
    if strict:
        return int(preferred_port)
    if _tcp_port_available(host, int(preferred_port)):
        return int(preferred_port)
    for i in range(1, 50):
        p = int(preferred_port) + int(i)
        if p > 65535:
            break
        if _tcp_port_available(host, p):
            try:
                LOG.warning("PORT %s in use, fallback to %s", int(preferred_port), int(p))
            except Exception:
                pass
            return int(p)
    return int(preferred_port)

if __name__ == "__main__":
    if "--agent-driver-once" in sys.argv:
        try:
            _load_config()
        except Exception:
            pass
        try:
            raw = sys.stdin.buffer.read() if hasattr(sys, "stdin") and hasattr(sys.stdin, "buffer") else sys.stdin.read().encode("utf-8")
        except Exception:
            raw = b""
        payload = None
        try:
            payload = json.loads((raw or b"{}").decode("utf-8"))
        except Exception:
            try:
                payload = json.loads((raw or b"{}").decode("utf-8", errors="ignore"))
            except Exception:
                payload = None
        if isinstance(payload, dict):
            cmd = payload.get("cmd") if isinstance(payload.get("cmd"), dict) else {}
            llm = payload.get("llm") if isinstance(payload.get("llm"), dict) else {}
            try:
                _agent_chat_driver_process(cmd, llm)
            except Exception:
                pass
        raise SystemExit(0)

    _load_config()

    try:
        if bool(AUTOMATION.get("shadow_automation_autostart", False)):
            AUTOMATION["enable_shadow_automation_loop"] = True
    except Exception:
        pass

    try:
        if bool(AUTOMATION.get("gtw_autostart", False)):
            AUTOMATION["enable_gtw"] = True
    except Exception:
        pass

    try:
        if bool(CONFIG.get("orders_isolation_backfill_on_start", False)):
            _orders_archive_backfill_isolation(max_files=int(CONFIG.get("orders_isolation_backfill_max_files", 60) or 60))
    except Exception:
        pass

    try:
        CONFIG.setdefault("aster_maker_price_offset_bps", 1.0)
    except Exception:
        pass
    try:
        CONFIG.setdefault("aster_maker_fallback_to_market", False)
    except Exception:
        pass
    try:
        CONFIG.setdefault("aster_maker_complete_on_partial", True)
    except Exception:
        pass
    try:
        _load_models()
    except Exception:
        pass
    try:
        _ensure_scheduler_started()
    except Exception:
        pass
    try:
        _ensure_twitter_outbox_worker_started()
    except Exception:
        pass
    try:
        _ensure_telegram_outbox_worker_started()
    except Exception:
        pass
    try:
        _ensure_agent_chat_outbox_worker_started()
    except Exception:
        pass
    try:
        _ensure_sandbox_outbox_worker_started()
    except Exception:
        pass
    host = str(os.environ.get("LISTEN_HOST", "127.0.0.1")).strip() or "127.0.0.1"
    env_port_raw = os.environ.get("PORT")
    if not env_port_raw:
        env_port_raw = os.environ.get("ML_TRADE_SERVICE_PORT")
    env_port = _parse_listen_port(env_port_raw)
    cfg_port = _parse_listen_port(CONFIG.get("trade_service_port"))
    if cfg_port is None:
        cfg_port = _parse_listen_port(CONFIG.get("service_port"))
    if cfg_port is None:
        cfg_port = _parse_listen_port(CONFIG.get("server_port"))
    preferred_port = int(env_port or cfg_port or 8092)
    port = _pick_listen_port(host, preferred_port, strict=(env_port is not None or cfg_port is not None))
    CONFIG["_listen_host"] = host
    CONFIG["_listen_port"] = int(port)
    app.run(host=host, port=int(port), threaded=True)
